20: 
21: pub const MAX_WEAPON_RECIPE_BYTES: usize = adventuresim_weapon_model::MAX_ENCODED_RECIPE_BYTES;
22: 
23: fn checked_scaled_u32(value: f32, scale: f32, label: &str) -> Result<u32, String> {
24:     let scaled = value * scale;
25:     if !scaled.is_finite() || scaled < 0.0 || scaled > u32::MAX as f32 {
26:         return Err(format!("Weapon {label} is outside the persisted range"));
27:     }
28:     Ok(scaled.round() as u32)
29: }
30: 
31: #[derive(Clone, Debug, PartialEq)]
32: /// Immutable evaluated recipe and storage projections, owned by
33: /// `from_evaluation`. Consumption re-evaluates the recipe and compares every
34: /// projection; catalog defaults never rewrite an existing physical object.
35: #[table(accessor = weapon_instance)]
36: pub struct WeaponInstance {
37:     #[primary_key]
38:     pub physical_object_id: u64,
39:     pub generator_version: u16,
40:     pub design_hash: Vec<u8>,
41:     pub recipe: Vec<u8>,
42:     pub mass_grams: u32,
43:     pub length_mm: u32,
44:     pub grip_to_tip_mm: u32,
45: }
46: 
47: #[derive(Clone, Debug, PartialEq)]
48: /// Independently evaluated holder recipe with the same construction and
49: /// authentication contract as `WeaponInstance`; holder geometry is distinct.
50: #[table(accessor = weapon_holder_instance)]
51: pub struct WeaponHolderInstance {
52:     #[primary_key]
53:     pub physical_object_id: u64,
54:     pub generator_version: u16,
55:     pub design_hash: Vec<u8>,
56:     pub recipe: Vec<u8>,
57:     pub mass_grams: u32,
58:     pub length_mm: u32,
59:     pub grip_to_tip_mm: u32,
60: }
61: 
62: /// Trusted strategic-backend projection used to produce per-instance inventory
63: /// icons. Recipes remain absent for ordinary player subscriptions and HTML.
64: #[view(accessor = backend_weapon_instances, public)]
65: pub fn backend_weapon_instances(ctx: &ViewContext) -> Vec<WeaponInstance> {
66:     let gateway = ctx.db.strategic_gateway_authority().id().find(0);
67:     if gateway.is_none_or(|authority| authority.identity != ctx.sender()) {
68:         return Vec::new();
69:     }
70:     let mut instances = Vec::new();
71:     for object in ctx
72:         .db
73:         .inventory_object()
74:         .item_id()
75:         .filter(""..)
76:         .filter(|object| {
77:             matches!(
78:                 &object.location,
79:                 InventoryLocation::Personal(_) | InventoryLocation::Party(_)
80:             )
81:         })
82:     {
83:         if let Some(instance) = ctx
84:             .db
85:             .weapon_instance()
86:             .physical_object_id()
87:             .find(object.id)
88:         {
89:             instances.push(instance);
90:         }
91:     }
92:     instances
93: }
94: 
95: /// Trusted strategic-backend projection for independently persisted scabbard
96: /// and haft-loop recipes. Ordinary players still receive holder recipes only
97: /// through the sender-scoped tactical projection.
98: #[view(accessor = backend_weapon_holder_instances, public)]
99: pub fn backend_weapon_holder_instances(ctx: &ViewContext) -> Vec<WeaponHolderInstance> {
100:     let gateway = ctx.db.strategic_gateway_authority().id().find(0);
101:     if gateway.is_none_or(|authority| authority.identity != ctx.sender()) {
102:         return Vec::new();
103:     }
104:     let mut instances = Vec::new();
105:     for object in ctx
106:         .db
