368:                 row.context_kind != kind
369:                     || row.location_id != location_id
370:                     || row.role != CharacterContextRole::Counterparty
371:             })
372:         {
373:             return Err("Context roster conflicts with its immutable materialization".into());
374:         }
375:         if existing.len() == expected as usize {
376:             return Ok(existing.into_iter().map(|row| row.character_id).collect());
377:         }
378:     }
379:     let mut ids = Vec::with_capacity(expected as usize);
380:     ids.extend(existing.iter().map(|row| row.character_id));
381:     for ordinal in existing.len() as u16..expected as u16 {
382:         let id = field_character_id(context_id, ordinal);
383:         if ctx.db.character().id().find(id).is_some() {
384:             return Err("Deterministic field-character identity collision".into());
385:         }
386:         crate::character::insert_persistent_field_character(
387:             ctx,
388:             "Pending generated name".into(),
389:             id,
390:             fabelgeist_determinism::Seed::from_u64(id),
391:             None,
392:         )?;
393:         crate::character::assign_generated_historical_name_for_age(
394:             ctx,
395:             crate::character::CharacterId::new(id),
396:             adventuresim_world_schema::person_names::NameStableSeed::new(id),
397:             entered_at,
398:             None,
399:         )
400:         .map_err(|error| error.to_string())?;
401:         ctx.db
402:             .character_context_membership()
403:             .insert(CharacterContextMembership {
404:                 id: format!("context:{context_id}:{ordinal}"),
405:                 context_id: context_id.to_string(),
406:                 location_id: location_id.to_string(),
407:                 character_id: id,
408:                 context_kind: kind,
409:                 role: CharacterContextRole::Counterparty,
410:                 ordinal,
411:                 entered_at,
412:                 left_at: None,
413:                 revision: 1,
414:                 contact_decision: ContextualDecisionState::Allowed,
415:                 treatment_decision: ContextualDecisionState::Unavailable,
416:             });
417:         ids.push(id);
418:     }
419:     Ok(ids)
420: }
