422: /// Carry already-materialized mortal road counterparties into a combat
423: /// follow-up without replacing their Character identity or components.
424: pub(crate) fn rebind_road_cast_to_strategic_encounter(
425:     ctx: &ReducerContext,
426:     road_context_id: &str,
427:     encounter_id: &str,
428:     count: u32,
429: ) -> Result<Vec<u64>, String> {
430:     let entered_at = crate::time::refresh_clock(ctx)?;
431:     let mut eligible = context_members(ctx, road_context_id)
432:         .into_iter()
433:         .filter(|membership| {
434:             membership.context_kind == CharacterContextKind::RoadEncounter
435:                 && membership.role == CharacterContextRole::Counterparty
436:                 && ctx
437:                     .db
438:                     .character()
439:                     .id()
440:                     .find(membership.character_id)
441:                     .is_some_and(|character| character.alive)
442:         })
443:         .take(usize::try_from(count).unwrap_or(usize::MAX))
444:         .collect::<Vec<_>>();
445:     eligible.sort_by_key(|membership| membership.ordinal);
446:     for (ordinal, road_membership) in eligible.iter().enumerate() {
447:         let ordinal = u16::try_from(ordinal)
448:             .map_err(|_| "Strategic encounter roster exceeds the supported size")?;
449:         let id = format!("context:{encounter_id}:{ordinal}");
450:         let rebound = CharacterContextMembership {
451:             id: id.clone(),
452:             context_id: encounter_id.into(),
453:             location_id: encounter_id.into(),
454:             character_id: road_membership.character_id,
455:             context_kind: CharacterContextKind::StrategicEncounter,
456:             role: CharacterContextRole::Counterparty,
457:             ordinal,
458:             entered_at,
459:             left_at: None,
460:             revision: 1,
461:             contact_decision: ContextualDecisionState::Allowed,
462:             treatment_decision: ContextualDecisionState::Unavailable,
463:         };
464:         if let Some(existing) = ctx.db.character_context_membership().id().find(&id) {
465:             if existing.context_id != rebound.context_id
466:                 || existing.character_id != rebound.character_id
467:                 || existing.context_kind != rebound.context_kind
468:                 || existing.role != rebound.role
469:             {
470:                 return Err("Road-to-combat Character identity collision".into());
471:             }
472:         } else {
473:             ctx.db.character_context_membership().insert(rebound);
474:         }
475:     }
476:     materialize_context_roster(
477:         ctx,
478:         CharacterContextKind::StrategicEncounter,
479:         encounter_id,
480:         encounter_id,
481:         count,
482:     )
483: }
