494: /// Materialize every individualized mortal in a compiled road cast as an
495: /// ordinary, fully componentized Character. Cast order is the stable identity
496: /// coordinate; narrative collectives and explicitly blocked figures never
497: /// receive a surrogate Character row.
498: pub(crate) fn materialize_road_encounter_cast(
499:     ctx: &ReducerContext,
500:     context_id: &str,
501:     definition: &adventuresim_core::road_encounter_catalog::EncounterDefinition,
502:     absolute_minute: StrategicMinute,
503: ) -> Result<Vec<u64>, String> {
504:     use adventuresim_core::road_encounter_catalog::SpeakerBacking;
505: 
506:     let mut materialized = Vec::new();
507:     for (cast_ordinal, speaker) in definition.cast.iter().enumerate() {
508:         let SpeakerBacking::Character {
509:             role,
510:             contact_decision,
511:             treatment_decision,
512:         } = &speaker.backing
513:         else {
514:             continue;
515:         };
516:         let ordinal = u16::try_from(cast_ordinal)
517:             .map_err(|_| "Road encounter cast exceeds the supported roster size")?;
518:         let membership_id = format!("context:{context_id}:{ordinal}");
519:         let character_id = field_character_id(context_id, ordinal);
520:         let expected_role = *role;
521:         let existing_membership = ctx
522:             .db
523:             .character_context_membership()
524:             .id()
525:             .find(&membership_id);
526:         let existing_character = ctx.db.character().id().find(character_id);
527:         match (existing_membership, existing_character) {
528:             (Some(membership), Some(character)) => {
529:                 if membership.context_id != context_id
530:                     || membership.location_id != context_id
531:                     || membership.character_id != character_id
532:                     || membership.context_kind != CharacterContextKind::RoadEncounter
533:                     || membership.role != expected_role
534:                     || membership.ordinal != ordinal
535:                     || !context_membership_interval_is_well_formed(&membership)
536:                     || !membership.is_open()
537:                     || membership.contact_decision != *contact_decision
538:                     || membership.treatment_decision != *treatment_decision
539:                     || character.name != speaker.name
540:                 {
541:                     return Err(
542:                         "Road cast retry conflicts with immutable Character authority".into(),
543:                     );
544:                 }
545:                 materialized.push(character_id);
546:                 continue;
547:             }
548:             (Some(_), None) | (None, Some(_)) => {
549:                 return Err("Road cast retry found partial Character authority".into());
550:             }
551:             (None, None) => {}
552:         }
553:         crate::character::insert_persistent_field_character(
554:             ctx,
555:             speaker.name.clone(),
556:             character_id,
557:             fabelgeist_determinism::Seed::from_u64(character_id),
558:             Some(absolute_minute),
559:         )?;
560:         ctx.db
561:             .character_context_membership()
562:             .insert(CharacterContextMembership {
563:                 id: membership_id,
564:                 context_id: context_id.into(),
565:                 location_id: context_id.into(),
566:                 character_id,
567:                 context_kind: CharacterContextKind::RoadEncounter,
568:                 role: expected_role,
569:                 ordinal,
570:                 entered_at: absolute_minute,
571:                 left_at: None,
572:                 revision: 1,
573:                 contact_decision: *contact_decision,
574:                 treatment_decision: *treatment_decision,
575:             });
576:         if expected_role == CharacterContextRole::Patient {
577:             crate::surgery::seed_field_cut(
578:                 ctx,
579:                 character_id,
580:                 adventuresim_core::physiology::BodyRegion::LeftArm,
581:                 0.35,
582:                 absolute_minute,
583:             );
584:             if *treatment_decision == ContextualDecisionState::Unavailable {
585:                 crate::condition::apply_blood_loss(ctx, character_id, 0.30)?;
586:             }
587:         }
588:         materialized.push(character_id);
589:     }
590:     Ok(materialized)
591: }
