593: pub(crate) fn characters_are_contextually_present(
594:     ctx: &ReducerContext,
595:     actor_id: u64,
596:     target_id: u64,
597: ) -> bool {
598:     let Some(actor) = ctx.db.character().id().find(actor_id) else {
599:         return false;
600:     };
601:     let Some(target) = ctx.db.character().id().find(target_id) else {
602:         return false;
603:     };
604:     if actor.current_settlement_id.is_some()
605:         && actor.current_settlement_id == target.current_settlement_id
606:     {
607:         return true;
608:     }
609:     let actor_case_presence = actor_case_presence(ctx, actor_id);
610:     if let Some((actor_presence, minute)) = actor_case_presence.as_ref()
611:         && case_site_presence_for_observer(ctx, actor_id, target_id, *minute).is_some_and(
612:             |target_presence| {
613:                 adventuresim_core::strategic_presence::are_co_present(
614:                     actor_presence,
615:                     &target_presence,
616:                 )
617:             },
618:         )
619:     {
620:         return true;
621:     }
622:     ctx.db
623:         .character_context_membership()
624:         .character_id()
625:         .filter(target_id)
626:         .filter(|row| {
627:             context_membership_interval_is_well_formed(row)
628:                 && (row.is_open()
629:                     || matches!(
630:                         row.context_kind,
631:                         CharacterContextKind::CaseSite | CharacterContextKind::HostileGroup
632:                     ))
633:         })
634:         .any(|row| match row.context_kind {
635:             CharacterContextKind::CaseSite | CharacterContextKind::HostileGroup => {
636:                 actor_case_presence
637:                     .as_ref()
638:                     .is_some_and(|(actor_presence, minute)| {
639:                         let minute = *minute;
640:                         let Some((projected_id, projected_revision)) =
641:                             projected_case_context_claim(ctx, actor_id, &row, minute)
642:                         else {
643:                             return false;
644:                         };
645:                         case_context_presence_for_observer(
646:                             ctx,
647:                             actor_id,
648:                             &row,
649:                             &projected_id,
650:                             projected_revision,
651:                             minute,
652:                         )
653:                         .is_some_and(|target_presence| {
654:                             adventuresim_core::strategic_presence::are_co_present(
655:                                 actor_presence,
656:                                 &target_presence,
657:                             )
658:                         })
659:                     })
660:             }
661:             CharacterContextKind::StrategicEncounter => {
662:                 actor.party_id.as_ref().is_some_and(|party_id| {
663:                     ctx.db
664:                         .strategic_encounter()
665:                         .party_id()
666:                         .find(party_id)
667:                         .is_some_and(|encounter| {
668:                             encounter.encounter_id == row.context_id
669:                                 && encounter.status == StrategicEncounterStatus::AwaitingChoice
670:                         })
671:                 })
672:             }
673:             CharacterContextKind::RoadEncounter => {
674:                 actor.party_id.as_ref().is_some_and(|party_id| {
675:                     ctx.db
676:                         .party_authority()
677:                         .id()
678:                         .find(party_id)
679:                         .is_some_and(|party| {
680:                             ctx.db
681:                                 .road_challenge_authority()
682:                                 .id()
683:                                 .find(&row.context_id)
684:                                 .is_some_and(|challenge| {
685:                                     challenge.party_id == *party_id
686:                                         && challenge.is_open()
687:                                         && crate::strategic::party_at_bound_road_challenge(
688:                                             ctx, &party, &challenge,
689:                                         )
690:                                 })
691:                         })
692:                 })
693:             }
694:         })
695: }
