697: fn contextual_membership_is_visible(
698:     ctx: &ReducerContext,
699:     actor_id: u64,
700:     membership: &CharacterContextMembership,

701: ) -> bool {
702:     let Some(actor) = ctx.db.character().id().find(actor_id) else {
703:         return false;
704:     };
705:     let Some(party_id) = actor.party_id.as_deref() else {
706:         return false;
707:     };
708:     let Some(actor_minute) = ctx
709:         .db
710:         .character_time()
711:         .character_id()
712:         .find(actor_id)
713:         .map(|row| row.minutes)
714:     else {
715:         return false;
716:     };
717:     (if matches!(
718:         membership.context_kind,
719:         CharacterContextKind::CaseSite | CharacterContextKind::HostileGroup
720:     ) {
721:         context_membership_valid_at(membership, actor_minute)
722:     } else {
723:         context_membership_interval_is_well_formed(membership) && membership.is_open()
724:     }) && characters_are_contextually_present(ctx, actor_id, membership.character_id)
725:         && match membership.context_kind {
726:             CharacterContextKind::CaseSite => crate::outbreak::case_patient_visible_to_character(
727:                 ctx,
728:                 actor_id,
729:                 &membership.context_id,
730:                 actor_minute,
731:             ),
732:             CharacterContextKind::RoadEncounter => ctx
733:                 .db
734:                 .road_challenge_authority()
735:                 .id()
736:                 .find(&membership.context_id)
737:                 .is_some_and(|challenge| challenge.party_id == party_id),
738:             CharacterContextKind::StrategicEncounter => ctx
739:                 .db
740:                 .strategic_encounter()
741:                 .party_id()
742:                 .find(party_id.to_owned())
743:                 .is_some_and(|encounter| encounter.encounter_id == membership.context_id),
744:             CharacterContextKind::HostileGroup => true,
745:         }
746: }
