748: fn public_decision(
749:     state: ContextualDecisionState,
750: ) -> adventuresim_core::strategic_action::ContextualActionDecision {
751:     use adventuresim_core::strategic_action::{ContextualActionDecision, ContextualActionReason};
752:     match state {
753:         ContextualDecisionState::Allowed => {
754:             ContextualActionDecision::Allowed(ContextualActionReason::TargetPermission)
755:         }
756:         ContextualDecisionState::Refused => ContextualActionDecision::Refused,
757:         ContextualDecisionState::Unavailable => ContextualActionDecision::Unavailable,
758:     }
