762: pub(crate) struct ContextualTreatmentClaim {
763:     pub contact_ref: String,
764:     pub expected_membership_revision: u32,
765: }
766: 
767: fn contextual_treatment_claim_matches(
768:     membership: &CharacterContextMembership,
769:     claim: &ContextualTreatmentClaim,
770: ) -> bool {
771:     let reference_matches = match membership.context_kind {
772:         CharacterContextKind::CaseSite | CharacterContextKind::HostileGroup => {
773:             claim.contact_ref == EXACT_CASE_CONTEXT_CONTACT_REF
774:         }
775:         CharacterContextKind::StrategicEncounter | CharacterContextKind::RoadEncounter => {
776:             claim.contact_ref == membership.context_id
777:         }
778:     };
779:     reference_matches && claim.expected_membership_revision == membership.revision
780: }
