782: fn treatment_target_answer(
783:     contextual_answer: Option<ContextualDecisionState>,
784:     party_preference: Option<ContextualDecisionState>,
785: ) -> adventuresim_core::strategic_action::ContextualActionDecision {
786:     contextual_answer.or(party_preference).map_or(
787:         adventuresim_core::strategic_action::ContextualActionDecision::Unavailable,
788:         public_decision,
789:     )
790: }
