792: fn contextual_contact_decision(
793:     ctx: &ReducerContext,
794:     actor_id: u64,
795:     target_id: u64,
796:     membership: &CharacterContextMembership,
797: ) -> adventuresim_core::strategic_action::ContextualActionDecision {
798:     use adventuresim_core::strategic_action::{ContextualActionDecision, ContextualActionReason};
799:     if actor_id == target_id {
800:         return ContextualActionDecision::Allowed(ContextualActionReason::SelfAction);
801:     }
802:     if membership.character_id != target_id
803:         || !ctx
804:             .db
805:             .character()
806:             .id()
807:             .find(target_id)
808:             .is_some_and(|target| target.alive)
809:         || !contextual_membership_is_visible(ctx, actor_id, membership)
810:     {
811:         return ContextualActionDecision::Unavailable;
812:     }
813:     public_decision(membership.contact_decision)
814: }
