816: fn contextual_treatment_decision_with_emergency(
817:     ctx: &ReducerContext,
818:     actor_id: u64,
819:     patient_id: u64,
820:     emergency_medical_necessity: bool,
821:     claim: Option<&ContextualTreatmentClaim>,
822: ) -> adventuresim_core::strategic_action::ContextualActionDecision {
823:     use adventuresim_core::strategic_action::ContextualActionDecision;
824:     let Some(actor) = ctx
825:         .db
826:         .character()
827:         .id()
828:         .find(actor_id)
829:         .filter(|row| row.alive)
830:     else {
831:         return ContextualActionDecision::Unavailable;
832:     };
833:     let Some(patient) = ctx
834:         .db
835:         .character()
836:         .id()
837:         .find(patient_id)
838:         .filter(|row| row.alive)
839:     else {
840:         return ContextualActionDecision::Unavailable;
841:     };
842:     if actor_id == patient_id {
843:         if claim.is_some() {
844:             return ContextualActionDecision::Unavailable;
845:         }
846:         return adventuresim_core::strategic_action::decide_contextual_action(
847:             true,
848:             ContextualActionDecision::Unavailable,
849:             false,
850:         );
851:     }
852:     if !characters_are_contextually_present(ctx, actor_id, patient_id) {
853:         return ContextualActionDecision::Unavailable;
854:     }
855: 
856:     let actor_minute = ctx
857:         .db
858:         .character_time()
859:         .character_id()
860:         .find(actor_id)
861:         .map_or(StrategicMinute::ZERO, |t| t.minutes);
862:     let contextual = ctx
863:         .db
864:         .character_context_membership()
865:         .character_id()
866:         .filter(patient_id)
867:         .filter(|membership| {
868:             if matches!(
869:                 membership.context_kind,
870:                 CharacterContextKind::CaseSite | CharacterContextKind::HostileGroup
871:             ) {
872:                 context_membership_valid_at(membership, actor_minute)
873:             } else {
874:                 context_membership_interval_is_well_formed(membership) && membership.is_open()
875:             }
876:         })
877:         .collect::<Vec<_>>();
878:     let authored = if contextual.is_empty() {
879:         if claim.is_some() {
880:             return ContextualActionDecision::Unavailable;
881:         }
882:         None
883:     } else {
884:         let Some(claim) = claim else {
885:             return ContextualActionDecision::Unavailable;
886:         };
887:         let matching = contextual.iter().filter(|membership| {
888:             contextual_treatment_claim_matches(membership, claim)
889:                 && contextual_membership_is_visible(ctx, actor_id, membership)
890:         });
891:         let Some(membership) = exactly_one(matching) else {
892:             return ContextualActionDecision::Unavailable;
893:         };
894:         Some(membership.treatment_decision)
895:     };
896:     let same_party_preference = (actor.party_id.is_some() && actor.party_id == patient.party_id)
897:         .then_some(patient.party_treatment_decision);
898:     adventuresim_core::strategic_action::decide_contextual_action(
899:         false,
900:         treatment_target_answer(authored, same_party_preference),
901:         emergency_medical_necessity,
902:     )
903: }
