905: pub(crate) fn contextual_treatment_decision(
906:     ctx: &ReducerContext,
907:     actor_id: u64,
908:     patient_id: u64,
909:     limb: adventuresim_core::physiology::BodyRegion,
910:     procedure: adventuresim_core::surgery::SurgeryProcedure,
911:     claim: Option<&ContextualTreatmentClaim>,
