913:     let incapacitated = ctx
914:         .db
915:         .character_strategic_condition()
916:         .character_id()
917:         .find(patient_id)
918:         .is_some_and(|row| {
919:             row.status == adventuresim_core::morale::IncapacitationStatus::Incapacitated
920:         });
921:     let injury = crate::surgery::injury_for(ctx, patient_id, limb);
922:     let emergency_bandage = adventuresim_core::strategic_action::emergency_bandage_is_necessary(
923:         incapacitated,
924:         procedure,
925:         injury.cut_damage,
926:         injury.bandaged,
927:     );
928:     contextual_treatment_decision_with_emergency(
929:         ctx,
930:         actor_id,
931:         patient_id,
932:         emergency_bandage,
933:         claim,
934:     )
