961: /// Initiate ordinary social contact with any living co-present Character.
962: /// Contact is intentionally not a full authored-dialogue session: it lays the
963: /// durable relationship edge and changes encounter awareness atomically.
964: #[reducer]
965: pub fn contact_context_character(
966:     ctx: &ReducerContext,
967:     actor_id: u64,
968:     target_id: u64,
969:     contact_ref: String,
970:     expected_revision: u32,
971:     action_id: String,
972: ) -> Result<(), String> {
973:     crate::strategic::require_strategic_character_authority(ctx, actor_id)?;
974:     if action_id.is_empty() || action_id.len() > 160 {
975:         return Err("Contextual contact action ID is invalid".into());
976:     }
977:     let receipt_id = format!("context-contact:{actor_id}:{action_id}");
978:     if let Some(existing) = ctx.db.contextual_contact_receipt().id().find(&receipt_id) {
979:         return if existing.actor_id == actor_id
980:             && existing.target_id == target_id
981:             && existing.context_id == contact_ref
982:             && existing.expected_revision == expected_revision
983:         {
984:             Ok(())
985:         } else {
986:             Err("Conflicting contextual contact retry".into())
987:         };
988:     }
989:     crate::character::require_living_character(ctx, actor_id)?;
990:     crate::character::require_living_character(ctx, target_id)?;
991:     let actor = ctx
992:         .db
993:         .character()
994:         .id()
995:         .find(actor_id)
996:         .ok_or("Contact actor does not exist")?;
997:     let party_id = actor.party_id.ok_or("Contact requires an active party")?;
998:     let actor_minute = ctx
999:         .db
1000:         .character_time()
1001:         .character_id()
1002:         .find(actor_id)
1003:         .ok_or("Contact actor has no personal time")?
1004:         .minutes;
1005:     let case_presence = case_site_presence_for_observer(ctx, actor_id, actor_id, actor_minute);
1006:     let candidates = ctx
1007:         .db
1008:         .character_context_membership()
1009:         .character_id()
1010:         .filter(target_id)
1011:         .filter(|row| {
1012:             (if matches!(
1013:                 row.context_kind,
1014:                 CharacterContextKind::CaseSite | CharacterContextKind::HostileGroup
1015:             ) {
1016:                 context_membership_valid_at(row, actor_minute)
1017:             } else {
1018:                 context_membership_interval_is_well_formed(row) && row.is_open()
1019:             }) && match row.context_kind {
1020:                 CharacterContextKind::StrategicEncounter => row.context_id == contact_ref,
1021:                 CharacterContextKind::CaseSite | CharacterContextKind::HostileGroup => {
1022:                     exact_context_claim_matches(
1023:                         row.context_kind,
1024:                         &contact_ref,
1025:                         expected_revision,
1026:                         row.revision,
1027:                     ) && case_presence.as_ref().is_some_and(|actor_presence| {
1028:                         case_context_presence_for_observer(
1029:                             ctx,
1030:                             actor_id,
1031:                             row,
1032:                             &row.id,
1033:                             expected_revision,
1034:                             actor_minute,
1035:                         )
1036:                         .is_some_and(|target_presence| {
1037:                             adventuresim_core::strategic_presence::are_co_present(
1038:                                 actor_presence,
1039:                                 &target_presence,
1040:                             )
1041:                         })
1042:                     })
1043:                 }
1044:                 CharacterContextKind::RoadEncounter => row.location_id == contact_ref,
1045:             }
1046:         })
1047:         .collect::<Vec<_>>();
1048:     let membership = exactly_one(candidates.into_iter())
1049:         .ok_or("Target context claim is unavailable or ambiguous")?;
1050:     if membership.context_kind == CharacterContextKind::CaseSite

1051:         && membership.role == CharacterContextRole::Patient
1052:         && !crate::outbreak::case_patient_visible_to_character(
1053:             ctx,
1054:             actor_id,
1055:             &membership.context_id,
1056:             actor_minute,
1057:         )
1058:     {
1059:         return Err("Patient context is not visible at the actor frontier".into());
1060:     }
1061:     match contextual_contact_decision(ctx, actor_id, target_id, &membership) {
1062:         adventuresim_core::strategic_action::ContextualActionDecision::Allowed(_) => {}
1063:         adventuresim_core::strategic_action::ContextualActionDecision::Refused => {
1064:             return Err("Contact was refused".into());
1065:         }
1066:         adventuresim_core::strategic_action::ContextualActionDecision::Unavailable => {
1067:             return Err("Contact is unavailable".into());
1068:         }
1069:     }
1070:     let mut encounter = ctx
1071:         .db
1072:         .strategic_encounter()
1073:         .party_id()
1074:         .find(
1075:             &ctx.db
1076:                 .character()
1077:                 .id()
1078:                 .find(actor_id)
1079:                 .and_then(|character| character.party_id)
1080:                 .ok_or("Contact requires an active party")?,
1081:         )
1082:         .filter(|encounter| {
1083:             encounter.encounter_id == membership.context_id
1084:                 && encounter.status == StrategicEncounterStatus::AwaitingChoice
1085:         });
1086:     let contact_id = party_context_contact_id(&party_id, &membership.context_id);
1087:     let existing_contact = ctx
1088:         .db
1089:         .party_context_contact_authority()
1090:         .id()
1091:         .find(&contact_id);
1092:     let current_revision = if matches!(
1093:         membership.context_kind,
1094:         CharacterContextKind::CaseSite | CharacterContextKind::HostileGroup
1095:     ) {
1096:         membership.revision
1097:     } else {
1098:         existing_contact.as_ref().map_or_else(
1099:             || encounter.as_ref().map_or(1, |encounter| encounter.revision),
1100:             |contact| contact.revision,
1101:         )
1102:     };
1103:     if current_revision != expected_revision {
1104:         return Err("Context contact revision is stale".into());
1105:     }
1106:     let resulting_revision = expected_revision.saturating_add(1);
1107:     if let Some(encounter) = encounter.as_mut() {
1108:         encounter.party_aware = true;
1109:         encounter.enemy_aware = true;
1110:         encounter
1111:             .available_choices
1112:             .retain(|choice| choice != "sneak");
1113:         encounter.selection_explanation =
1114:             "Contact established; both sides are aware and surprise is no longer possible.".into();
1115:         encounter.revision = resulting_revision;
1116:         ctx.db
1117:             .strategic_encounter()
1118:             .party_id()
1119:             .update(encounter.clone());
1120:     } else {
1121:         if membership.context_kind == CharacterContextKind::StrategicEncounter {
1122:             return Err("Strategic encounter is no longer active".into());
1123:         }
1124:     }
1125:     let contact = PartyContextContactAuthority {
1126:         id: contact_id,
1127:         party_id,
1128:         context_id: membership.context_id.clone(),
1129:         location_id: membership.location_id.clone(),
1130:         revision: resulting_revision,
1131:     };
1132:     if existing_contact.is_some() {
1133:         ctx.db
1134:             .party_context_contact_authority()
1135:             .id()
1136:             .update(contact);
1137:     } else {
1138:         ctx.db.party_context_contact_authority().insert(contact);
1139:     }
1140:     crate::social::begin_physiology_presence_on_contact(ctx, actor_id, target_id);
1141:     crate::social::apply_async_socializing(ctx, actor_id, target_id, 10)?;
1142:     ctx.db
1143:         .contextual_contact_receipt()
1144:         .insert(ContextualContactReceipt {
1145:             id: receipt_id,
1146:             actor_id,
1147:             target_id,
1148:             context_id: contact_ref,
1149:             action_id,
1150:             expected_revision,
1151:             resulting_revision,
1152:         });
1153:     Ok(())
1154: }
