3: #[reducer]
4: pub fn authority_test_context_intervals(
5:     ctx: &ReducerContext,
6:     bootstrap_token: String,
7: ) -> Result<(), String> {
8:     crate::strategic::require_dev_bootstrap_token(&bootstrap_token)?;
9:     let context_id = "authority-test-context";
10:     let id = "authority-test-membership";
11:     let entered = StrategicMinute::new(10);
12:     let left = StrategicMinute::new(20);
13:     let row = CharacterContextMembership {
14:         id: id.into(),
15:         context_id: context_id.into(),
16:         location_id: context_id.into(),
17:         character_id: 732010,
18:         context_kind: CharacterContextKind::StrategicEncounter,
19:         role: CharacterContextRole::Bystander,
20:         ordinal: 0,
21:         entered_at: entered,
22:         left_at: None,
23:         revision: 0,
24:         contact_decision: ContextualDecisionState::Allowed,
25:         treatment_decision: ContextualDecisionState::Unavailable,
26:     };
27:     ctx.db.character_context_membership().insert(row.clone());
28:     if context_members(ctx, context_id).len() != 1
29:         || context_membership_valid_at(&row, StrategicMinute::new(9))
30:         || !context_membership_valid_at(&row, entered)
31:     {
32:         return Err("Open membership projection disagrees with its interval".into());
33:     }
34:     deactivate_context_roster_at(ctx, context_id, left);
35:     let closed = ctx.db.character_context_membership().id().find(id.to_owned()).ok_or("Membership missing")?;
36:     if closed.is_open()
37:         || !context_members(ctx, context_id).is_empty()
38:         || !context_membership_valid_at(&closed, entered)
39:         || context_membership_valid_at(&closed, left)
40:     {
41:         return Err("Closed membership lost historical interval semantics".into());
42:     }
43:     close_context_membership_at(ctx, closed.clone(), StrategicMinute::new(30));
44:     let after = ctx.db.character_context_membership().id().find(id.to_owned()).ok_or("Membership missing")?;
45:     if after.left_at != Some(left) || after.revision != closed.revision {
46:         return Err("Repeated closure rewrote membership history".into());
47:     }
48:     Ok(())
49: }

