268: enum WorldEventFingerprintDomain {
269:     Request,
270:     Envelope,
271:     ConsequenceSet,
272: }
273: 
274: impl WorldEventFingerprintDomain {
275:     const fn stable_id(self) -> &'static [u8] {
276:         match self {
277:             Self::Request => b"adventuresim.world-event.request.v1",
278:             Self::Envelope => b"adventuresim.world-event.envelope.v1",
279:             Self::ConsequenceSet => b"adventuresim.world-event.consequence-set.v1",
280:         }
281:     }
282: }
283: 
284: fn fingerprint<T: Serialize>(
285:     domain: WorldEventFingerprintDomain,
286:     value: &T,
287: ) -> Result<String, String> {
288:     let bytes = serde_json::to_vec(value).map_err(|_| "Could not fingerprint typed world event")?;
289:     let mut hasher = Sha256::new();
290:     for value in [domain.stable_id(), bytes.as_slice()] {
291:         hasher.update((value.len() as u64).to_le_bytes());
292:         hasher.update(value);
293:     }
294:     Ok(hasher
295:         .finalize()
296:         .iter()
297:         .map(|byte| format!("{byte:02x}"))
298:         .collect())
299: }
