301: fn commit_world_event(
302:     ctx: &ReducerContext,
303:     request: WorldEventRequest,
304:     build: impl FnOnce() -> (
305:         WorldEventEnvelope,
306:         ConsequenceOrder,
307:         Vec<WorldEventConsequence>,
308:     ),
309: ) -> Result<bool, String> {
310:     request
311:         .envelope()
312:         .validate()
313:         .map_err(|_| "Typed world event is invalid")?;
314:     let request_digest = fingerprint(WorldEventFingerprintDomain::Request, &request)?;
315:     if let Some(existing) = ctx
316:         .db
317:         .world_event_receipt()
318:         .id()
319:         .find(&request.envelope().id)
320:     {
321:         return if existing.request_digest == request_digest {
322:             Ok(false)
323:         } else {
324:             Err("World event ID conflicts with different canonical request".into())
325:         };
326:     }
327:     let (envelope, order, consequences) = build();
328:     envelope
329:         .validate()
330:         .map_err(|_| "Typed world event is invalid")?;
331:     validate_consequences(order, &consequences)?;
332:     validate_semantic_binding(&request, &envelope, &consequences)?;
333:     let digest = fingerprint(WorldEventFingerprintDomain::Envelope, &envelope)?;
334:     let consequence_digest =
335:         fingerprint(WorldEventFingerprintDomain::ConsequenceSet, &consequences)?;
336:     let consequence_count = u16::try_from(consequences.len())
337:         .map_err(|_| "World event consequence count is out of bounds")?;
338:     let persisted = persist(&envelope);
339:     preflight_consequences(ctx, &consequences)?;
340:     apply_consequences(ctx, consequences)?;
341:     ctx.db.world_event_receipt().insert(WorldEventReceipt {
342:         id: envelope.id,
343:         envelope: persisted,
344:         request_digest,
345:         envelope_digest: digest,
346:         consequence_digest,
347:         consequence_count,
348:     });
349:     Ok(true)
350: }
