463: fn validate_consequences(
464:     order: ConsequenceOrder,
465:     consequences: &[WorldEventConsequence],
466: ) -> Result<(), String> {
467:     if consequences.len() > MAX_WORLD_EVENT_CONSEQUENCES {
468:         return Err("World event consequence count is out of bounds".into());
469:     }
470:     let mut identities = BTreeSet::new();
471:     validate_consequence_order(order, consequences)?;
472:     for consequence in consequences {
473:         let identity = consequence_identity(consequence);
474:         if !identities.insert(identity) {
475:             return Err("World event repeats a consequence identity".into());
476:         }
477:     }
478:     Ok(())
479: }
