67:     fn new() -> Self {
68:         Self {
69:             private_projection_canary: PRIVATE_SCENARIO_CANARY,
70:             now: StrategicMinute::ZERO,
71:             renter_funds: 50,
72:             renter_next_due: StrategicMinute::new(HOUSING_BILLING_PERIOD_MINUTES),
73:             renter_paid: 0,
74:             owner_funds: 25,
75:             owner_next_due: StrategicMinute::new(HOUSING_BILLING_PERIOD_MINUTES),
76:             owner_paid: 0,
77:             residence_morale: RefreshableMorale::default(),
78:             spouse_morale: RefreshableMorale::default(),
79:             wedding_done: false,
80:             dowry_paid: false,
81:             ceremonies: 0,
82:             dowry_payments: 0,
