93: 
94:     fn advance_to(&mut self, end: StrategicMinute, seed: Seed) {
95:         while self.now < end {
96:             let boundary = end.min(self.now.day_start().saturating_add_days(1));
97:             self.process_interval(self.now, boundary, seed);
98:             self.now = boundary;
99:         }
100:     }
101: 
102:     fn process_interval(&mut self, start: StrategicMinute, end: StrategicMinute, seed: Seed) {
103:         self.process_billing(end);
104:         self.process_wedding(end);
105:         self.process_joint_leisure(start, end, seed);
106:         self.process_birth(end);
107:         self.process_morale(end);
108:         self.process_npc_batch();
109:     }
110: 
111:     fn process_billing(&mut self, through: StrategicMinute) {
112:         let renter = plan_due_period_settlement(
113:             self.renter_next_due,
114:             through,
115:             self.renter_funds,
116:             HousingTier::Moderate.economy().rent_per_30_days.into(),
117:         );
118:         self.renter_funds = renter.funds_remaining;
119:         self.renter_next_due = renter.next_due_minute;
120:         self.renter_paid = self.renter_paid.saturating_add(renter.periods_paid);
121: 
122:         let owner_charge = HousingTier::Moderate
123:             .economy()
124:             .owner_maintenance_per_30_days
125:             .saturating_add(HousingTier::Moderate.economy().property_tax_per_30_days);
126:         let owner = plan_due_period_settlement(
127:             self.owner_next_due,
128:             through,
129:             self.owner_funds,
130:             owner_charge.into(),
131:         );
132:         self.owner_funds = owner.funds_remaining;
133:         self.owner_next_due = owner.next_due_minute;
134:         self.owner_paid = self.owner_paid.saturating_add(owner.periods_paid);
135:     }
136: 
137:     fn process_wedding(&mut self, through: StrategicMinute) {
138:         if through < StrategicMinute::new(WEDDING_NOTICE_MINUTES) || self.wedding_done {
139:             return;
140:         }
141:         self.wedding_done = true;
142:         self.ceremonies += 1;
143:         if !self.dowry_paid {
144:             self.dowry_paid = true;
145:             self.dowry_payments += 1;
146:         }
147:     }
148: 
149:     fn process_joint_leisure(&mut self, start: StrategicMinute, end: StrategicMinute, seed: Seed) {
150:         if !self.wedding_done || self.conception_minute.is_some() {
151:             return;
152:         }
153:         let married_start = start.max(StrategicMinute::new(WEDDING_NOTICE_MINUTES));
154:         if married_start >= end {
155:             return;
156:         }
157:         let day_start = married_start.day_start();
158:         let left = LeisureInterval {
159:             start_minute: day_start.saturating_add_minutes(12 * 60),
160:             end_minute: day_start.saturating_add_days(1),
161:             location_id: "shared_home",
162:         };
163:         let right = LeisureInterval {
164:             start_minute: day_start.saturating_add_minutes(10 * 60),
165:             end_minute: day_start.saturating_add_minutes(22 * 60),
166:             location_id: "shared_home",
167:         };
168:         let joint = joint_leisure_minutes_in(left, right, married_start, end);
169:         self.joint_leisure_minutes = self.joint_leisure_minutes.saturating_add(joint);
170:         let plan = conception_quantum_plan(self.conception, joint);
171:         for trial in &plan.trials {
172:             self.conception_trials += 1;
173:             let entropy = lifecycle_entropy(seed, "conception", trial.ordinal);
174:             if succeeds_daily_trial(entropy, CONCEPTION_CHANCE_PER_TEN_THOUSAND) {
175:                 let conceived = left
176:                     .start_minute
177:                     .max(married_start)
178:                     .saturating_add_minutes(trial.crossing_offset_minutes);
179:                 self.conception_minute = Some(conceived);
180:                 self.birth_minute = Some(conceived.saturating_add_minutes(GESTATION_MINUTES));
181:                 break;
182:             }
183:         }
184:         self.conception = plan.state;
185:     }
186: 
187:     fn process_birth(&mut self, through: StrategicMinute) {
188:         if self.births == 0 && self.birth_minute.is_some_and(|birth| through >= birth) {
189:             self.births = 1;
190:         }
191:     }
192: 
193:     fn process_morale(&mut self, now: StrategicMinute) {
194:         let residence_gain = residence_leisure_bonus_milli(
195:             20_000,
196:             HousingTier::Fancy.economy().leisure_morale_basis_points,
197:         );
198:         self.residence_morale = refresh_bounded_leisure_morale(
199:             self.residence_morale,
200:             self.spouse_morale,
201:             now,
202:             residence_gain,
203:             RESIDENCE_MORALE_SPEC,
204:         );
205:         if self.wedding_done {
206:             self.spouse_morale = refresh_bounded_leisure_morale(
207:                 self.spouse_morale,
208:                 self.residence_morale,
209:                 now,
210:                 spouse_leisure_earned_milli(12 * 60),
211:                 SPOUSE_LEISURE_MORALE_SPEC,
212:             );
213:         }
214:     }
