216:     fn process_npc_batch(&mut self) {
217:         let remaining = NPC_QUEUE_LEN.saturating_sub(self.npc_processed);
218:         let processed = remaining.min(NPC_BATCH_LIMIT);
219:         if processed > 0 {
220:             self.npc_processed += processed;
221:             self.npc_batches += 1;
222:         }
223:     }
224: }
