226: fn select_socializing_role<'a>(tiers: &[(&'a str, &[&'a str])]) -> Option<(&'a str, &'a str)> {
227:     tiers.iter().find_map(|(role, candidates)| {
228:         select_daily_location_target("actor", "shared_place", 9, candidates.iter().copied())
229:             .map(|target| (*role, target))
