233: fn run_cadence(seed: Seed, cadence: LifecycleCadence) -> Result<LifecycleReport, String> {
234:     let mut state = ScenarioState::new();
235:     let horizon = StrategicMinute::day_start_for_index(HORIZON_DAYS);
236:     match cadence {
237:         LifecycleCadence::Whole => state.advance_to(horizon, seed),
238:         LifecycleCadence::Daily => {
239:             for day in 1..=HORIZON_DAYS {
240:                 state.advance_to(StrategicMinute::day_start_for_index(day), seed);
241:             }
242:         }
243:     }
244:     let metrics = project_metrics(&state);
245:     let passed = all_acceptance_assertions_pass(&metrics);
246:     let normalized_digest = digest_json(&metrics)?;
247:     Ok(LifecycleReport {
248:         format_version: LIFECYCLE_REPORT_VERSION,
249:         evidence_tier: "offline_authoritative_pure_rules".into(),
250:         cadence,
251:         seed,
252:         elapsed_days: HORIZON_DAYS,
253:         passed,
254:         normalized_digest,
255:         metrics,
256:         limitations: vec![
257:             "Does not invoke SpacetimeDB reducers, persistence, subscriptions, or the browser UI."
258:                 .into(),
259:             "Proves deterministic rule composition and cadence equivalence, not database concurrency."
260:                 .into(),
261:             "The guarded module integration suite remains the authority for reducer access and projection privacy."
262:                 .into(),
263:         ],
264:     })
265: }
