476: fn digest_json<T: Serialize>(value: &T) -> Result<String, String> {
477:     serde_json::to_vec(value)
478:         .map(|bytes| blake3::hash(&bytes).to_hex().to_string())
479:         .map_err(|error| error.to_string())
