482: pub fn run_lifecycle_acceptance(seed: Seed) -> Result<LifecycleBundle, String> {
483:     let whole = run_cadence(seed, LifecycleCadence::Whole)?;
484:     let daily = run_cadence(seed, LifecycleCadence::Daily)?;
485:     let mut differences = Vec::new();
486:     if whole.metrics != daily.metrics {
487:         differences.push("final lifecycle metrics differ by cadence".into());
488:     }
489:     if whole.normalized_digest != daily.normalized_digest {
490:         differences.push("normalized lifecycle digest differs by cadence".into());
491:     }
492:     let whole_report_digest = digest_json(&whole)?;
493:     let daily_report_digest = digest_json(&daily)?;
494:     let normalized_digest = whole.normalized_digest.clone();
495:     let mut comparison = LifecycleComparison {
496:         format_version: LIFECYCLE_REPORT_VERSION,
497:         passed: whole.passed && daily.passed && differences.is_empty(),
498:         normalized_digest,
499:         whole_report_digest,
500:         daily_report_digest,
501:         differences,
502:         privacy_canary_absent: true,
503:         privacy_findings: Vec::new(),
504:     };
505:     let mut findings = audit_json(&whole).map_err(|error| error.to_string())?;
506:     findings.extend(audit_json(&daily).map_err(|error| error.to_string())?);
507:     findings.extend(audit_json(&comparison).map_err(|error| error.to_string())?);
508:     let projected =
509:         serde_json::to_string(&(&whole, &daily, &comparison)).map_err(|error| error.to_string())?;
510:     comparison.privacy_canary_absent = !projected.contains(PRIVATE_SCENARIO_CANARY)
511:         && !projected.contains(ScenarioState::new().private_projection_canary);
512:     comparison.privacy_findings = findings;
513:     comparison.passed &= comparison.privacy_canary_absent && comparison.privacy_findings.is_empty();
514:     Ok(LifecycleBundle {
515:         whole,
516:         daily,
517:         comparison,
518:     })
519: }
