521: pub fn write_lifecycle_acceptance(
522:     output_dir: &Path,
523:     seed: Seed,
524: ) -> Result<LifecycleBundle, String> {
525:     if output_dir.exists() {
526:         return Err(format!(
527:             "lifecycle output directory already exists: {}",
528:             output_dir.display()
529:         ));
530:     }
531:     let bundle = run_lifecycle_acceptance(seed)?;
532:     let whole = pretty_json(&bundle.whole)?;
533:     let daily = pretty_json(&bundle.daily)?;
534:     let comparison = pretty_json(&bundle.comparison)?;
535:     fs::create_dir(output_dir).map_err(|error| error.to_string())?;
536:     write_new(&output_dir.join("whole.json"), &whole)?;
537:     write_new(&output_dir.join("daily.json"), &daily)?;
538:     write_new(&output_dir.join("comparison.json"), &comparison)?;
539:     Ok(bundle)
540: }
