542: fn pretty_json<T: Serialize>(value: &T) -> Result<Vec<u8>, String> {
543:     let mut bytes = serde_json::to_vec_pretty(value).map_err(|error| error.to_string())?;
544:     bytes.push(b'\n');
545:     Ok(bytes)
546: }
547: 
548: fn write_new(path: &Path, bytes: &[u8]) -> Result<(), String> {
549:     let mut options = OpenOptions::new();
550:     options.write(true).create_new(true);
551:     options
552:         .open(path)
553:         .and_then(|mut file| file.write_all(bytes))
554:         .map_err(|error| error.to_string())
555: }
