12: pub(super) fn equipment_utility(profile: &AgentProfile, item: &Item) -> Option<f32> {
13:     let preference = &profile.equipment;
14:     let armor = matches!(
15:         item.kind,
16:         CatalogItemKind::Armor | CatalogItemKind::Clothing
17:     );
18:     let compatible = match preference.style {
19:         EquipmentStyle::Unarmored => !armor && item.melee && item.weight <= 2.5,
20:         EquipmentStyle::Ranged => !armor && item.ranged,
21:         EquipmentStyle::Light => (armor && item.weight <= 8.0) || (!armor && item.melee),
22:         EquipmentStyle::Heavy => armor || item.melee,
23:     };
24:     if !compatible || item.base_value.is_none() || item.equipment_placements.is_empty() {
25:         return None;
26:     }
27:     let protection = item.coverage + item.resistance + item.padding;
28:     let mobility = item.flexibility + item.range_of_motion - item.weight * 0.1;
29:     let price = 1.0 / (1.0 + item.base_value.unwrap_or(1) as f32 / 100.0);
30:     Some(
31:         preference.protection_weight * protection
32:             + preference.mobility_weight * mobility
33:             + preference.price_weight * price
34:             + preference.reach_weight * item.reach,
35:     )
36: }
