38: pub(super) fn root_requirement_matches_slot(
39:     requirement: &OccupancyRequirement,
40:     slot: Slot,
41: ) -> bool {
42:     match slot {
43:         Slot::LeftHolding => {
44:             requirement.location == EquipmentLocation::LeftHand
45:                 && requirement.channel == EquipmentChannel::Held
46:         }
47:         Slot::RightHolding => {
48:             requirement.location == EquipmentLocation::RightHand
49:                 && requirement.channel == EquipmentChannel::Held
50:         }
51:         Slot::AnyHolding => requirement.channel == EquipmentChannel::Held,
52:         Slot::LeftArm => requirement.location == EquipmentLocation::LeftArm,
53:         Slot::RightArm => requirement.location == EquipmentLocation::RightArm,
54:         Slot::AnyArm => matches!(
55:             requirement.location,
56:             EquipmentLocation::LeftArm | EquipmentLocation::RightArm
57:         ),
58:         Slot::LeftLeg => requirement.location == EquipmentLocation::LeftLeg,
59:         Slot::RightLeg => requirement.location == EquipmentLocation::RightLeg,
60:         Slot::AnyLeg => matches!(
61:             requirement.location,
62:             EquipmentLocation::LeftLeg | EquipmentLocation::RightLeg
63:         ),
64:         Slot::Head => requirement.location == EquipmentLocation::Head,
65:         Slot::Chest => requirement.location == EquipmentLocation::Chest,
66:         Slot::Stomach => requirement.location == EquipmentLocation::Stomach,
67:         Slot::None => true,
68:     }
69: }
