78:         .next()
79:         .ok_or("required quest fixture completed without receipt-backed public provenance")?;
80:     if rows.next().is_some() {
81:         return Err("required quest fixture public provenance is ambiguous".into());
82:     }
83:     if fixture.id != 0 || fixture.run_id != expected_run_id {
84:         return Err("required quest fixture public provenance identifies the wrong run".into());
85:     }
86:     let direct = (fixture.direct_leader_id, fixture.direct_party_id.as_str());
87:     let generated = (
88:         fixture.generated_leader_id,
89:         fixture.generated_party_id.as_str(),
90:     );
91:     let first = (expected_parties[0].0, expected_parties[0].1.as_str());
92:     let second = (expected_parties[1].0, expected_parties[1].1.as_str());
93:     if !((direct == first && generated == second) || (direct == second && generated == first)) {
94:         return Err("required quest fixture public provenance identifies the wrong parties".into());
95:     }
96:     Ok(fixture)
97: }
