111: fn wait_for_new_public_direct_contract(
112:     runner: &LiveRunner,
113:     existing_contract_ids: &HashSet<String>,
114:     settlement_id: &str,
115:     direct_party_id: &str,
116: ) -> Result<String, String> {
117:     let deadline = std::time::Instant::now() + ACTION_TIMEOUT;
118:     loop {
119:         let mut candidates = runner
120:             .connection
121:             .db
122:             .backend_contracts()
123:             .iter()
124:             .filter(|contract| {
125:                 !existing_contract_ids.contains(&contract.id)
126:                     && contract.settlement_id == settlement_id
127:                     && contract.status == ContractStatus::Offered
128:                     && runner
129:                         .public_party_contract_assessment(direct_party_id, contract)
130:                         .eligible
131:             })
132:             .map(|contract| contract.id)
133:             .collect::<Vec<_>>();
134:         candidates.sort();
135:         candidates.dedup();
136:         match candidates.as_slice() {
137:             [contract_id] => return Ok(contract_id.clone()),
138:             [] if std::time::Instant::now() < deadline => {
139:                 std::thread::sleep(Duration::from_millis(5));
140:             }
141:             [] => return Err("required direct fixture contract was not publicly projected".into()),
142:             _ => return Err("required direct fixture contract projection is ambiguous".into()),
143:         }
144:     }
145: }
