147: pub fn run_core_loop(config: CoreLoopConfig) -> CoreLoopRunResult<CoreLoopReport> {
148:     let failure_recorder = FailureRecorder::new(
149:         config.failure_output.clone(),
150:         config.fixture_disease.clone(),
151:     );
152:     let error = match run_core_loop_inner(config, failure_recorder.clone()) {
153:         Ok(report) => return Ok(report),
154:         Err(error) => error,
155:     };
156:     if let Err(report) = failure_recorder.write(&error) {
157:         return Err(CoreLoopRunError::FailureReport { error, report });
158:     }
159:     Err(error.into())
160: }
