166:     config.validate()?;
167:     let bootstrap_token =
168:         bootstrap_token_from_environment(std::env::var(BOOTSTRAP_TOKEN_ENV).ok())?;
169:     let (connected_tx, connected_rx) = mpsc::sync_channel(1);
170:     let connect_error_tx = connected_tx.clone();
171:     let connection = DbConnection::builder()
172:         .with_uri(&config.host)
173:         .with_database_name(&config.database)
174:         .on_connect(move |_, _, _| {
175:             let _ = connected_tx.send(Ok(()));
176:         })
177:         .on_connect_error(move |_, error| {
178:             let _ = connect_error_tx.send(Err(error.to_string()));
179:         })
180:         .build()
181:         .map_err(|error| error.to_string())?;
182:     let (subscription_tx, subscription_rx) = mpsc::sync_channel(1);
183:     let subscription_error_tx = subscription_tx.clone();
184:     connection
185:         .subscription_builder()
186:         .on_applied(move |_| {
187:             let _ = subscription_tx.send(Ok(()));
188:         })
189:         .on_error(move |_, error| {
190:             let _ = subscription_error_tx.send(Err(error.to_string()));
191:         })
192:         // Deliberately enumerate the policy observation surface. In
