293:     if runner
294:         .connection
295:         .db
296:         .simulation_run()
297:         .iter()
298:         .next()
299:         .is_some()
300:     {
301:         return Err("refusing reused simulation database".into());
302:     }
303:     let world_import = runner.connection.db.world_data_import().iter().next();
304:     if config.use_imported_world {
305:         let imported = world_import
306:             .as_ref()
307:             .filter(|import| import.completed)
308:             .ok_or("full-world mode requires a completed world_data_import")?;
309:         if Some(imported.manifest_digest.as_str())
310:             != config.expected_world_manifest_digest.as_deref()
311:         {
312:             return Err(
313:                 "imported world manifest does not match the pinned expected manifest".into(),
314:             );
315:         }
316:         if imported.artifact_id.trim().is_empty()
317:             || imported.manifest_digest.len() != 64
318:             || runner.connection.db.settlement().iter().next().is_none()
319:         {
320:             return Err(
321:                 "completed world_data_import has invalid provenance or no settlements".into(),
322:             );
323:         }
324:     } else if world_import.is_some() || runner.connection.db.settlement().iter().next().is_some() {
325:         return Err("fixture mode refuses imported or pre-existing settlement state".into());
326:     }
327:     let result = reducer_call!(runner, ReducerOperation::ClaimSimulationRun, |cb| runner
328:         .connection
329:         .reducers
330:         .claim_simulation_run_then(

331:             bootstrap_token.clone(),
332:             config.run_nonce.clone(),
333:             config.seed.into(),
334:             cb,
335:         ));
336:     runner.call(result)?;
337:     let claimed_run_ids = runner
338:         .connection
339:         .db
340:         .simulation_run()
341:         .iter()
342:         .filter(|run| run.nonce == config.run_nonce)
343:         .map(|run| run.id)
344:         .take(2)
