556:             let result = reducer_call!(self, ReducerOperation::AbandonDefeatedQuest, |cb| self
557:                 .connection
558:                 .reducers
559:                 .abandon_contract_then(leader, quest.id.clone(), cb));
560:             self.call(result)?;
561:             self.metrics.direct_contracts_safely_abandoned += 1;
562:             self.direct_contract_event(
563:                 leader_agent,
564:                 CoreLoopEventKind::AbandonQuest,
565:                 party_id,
566:                 &quest.id,
567:                 format!(
568:                     "quest={};reason=unchanged_defeated_threat",
569:                     bounded_event_field(&quest.id)
570:                 ),
571:             );
572:             let result = reducer_call!(self, ReducerOperation::ReplenishQuestsAfterAbandon, |cb| self
573:                 .connection
574:                 .reducers
575:                 .ensure_settlement_activity_then(quest.settlement_id.clone(), cb));
576:             self.call(result)?;
577:             return Ok(());
578:         }
579:         let winning_battle_id = winning_battle_id.ok_or("victory had no battle authority")?;
580: 
581:         let loot: Vec<_> = self
582:             .connection
583:             .db
584:             .battle_loot_item()
585:             .iter()
586:             .filter(|row| row.loot_battle_id == winning_battle_id)
587:             .collect();
588:         let definitions: HashMap<_, _> = self
589:             .connection
590:             .db
591:             .item()
592:             .iter()
593:             .map(|item| (item.id.clone(), item))
594:             .collect();
595:         for entry in &loot {
596:             self.metrics.loot_items = self.metrics.loot_items.saturating_add(entry.quantity);
597:             self.metrics.loot_value = self.metrics.loot_value.saturating_add(
598:                 u64::from(entry.quantity)
599:                     * u64::from(
600:                         definitions
601:                             .get(&entry.item_id)
602:                             .and_then(|i| i.base_value)
603:                             .unwrap_or(0),
604:                     ),
605:             );
606:         }
607:         let result = reducer_call!(self, ReducerOperation::StoreBattleLoot, |cb| self
608:             .connection
609:             .reducers
610:             .store_battle_loot_then(leader, winning_battle_id, vec![], vec![], cb,));
611:         self.call(result)?;
612:         self.event(
613:             leader_agent,
614:             CoreLoopEventKind::StoreLoot,
615:             format!("stacks={}", loot.len()),
616:         );
617: 
618:         let result = reducer_call!(self, ReducerOperation::ReturnToSettlement, |cb| self
619:             .connection
620:             .reducers
621:             .travel_to_settlement_then(leader, quest.settlement_id.clone(), cb));
622:         self.call(result)?;
623:         self.direct_contract_event(
624:             leader_agent,
625:             CoreLoopEventKind::Travel,
626:             party_id,
627:             &quest.id,
628:             format!("return={}", quest.settlement_id),
629:         );
630:         if self.travel_camps(party_id)? != JourneyTravelOutcome::Completed {
631:             return Ok(());
632:         }
633:         self.observe_deaths();
634:         let Some((current, current_agent)) = self.current_leader(party_id) else {
635:             return Ok(());
636:         };
637:         leader = current;
638:         leader_agent = current_agent;
639:         self.turn_in_ready_direct_contract(party_id, leader, leader_agent, &quest)?;
640:

641:         let party = self.party_for(leader)?;
642:         let sale: Vec<_> = self
643:             .connection
644:             .db
645:             .party_inventory_item()
646:             .iter()
647:             .filter(|row| row.party_id == party.id && !is_currency_id(&row.item_id))
648:             .collect();
649:         if !sale.is_empty() {
650:             let before_coins: u64 = self
651:                 .connection
652:                 .db
653:                 .party_inventory_item()
654:                 .iter()
655:                 .filter(|row| row.party_id == party.id && is_currency_id(&row.item_id))
656:                 .map(|row| u64::from(row.quantity))
657:                 .sum();
658:             let ids = sale.iter().map(|row| row.id).collect();
659:             let quantities = sale.iter().map(|row| row.quantity).collect();
660:             let result = reducer_call!(self, ReducerOperation::LiquidatePartyInventory, |cb| self
661:                 .connection
662:                 .reducers
663:                 .liquidate_party_inventory_then(
664:                     leader,
665:                     quest.settlement_id.clone(),
666:                     ids,
667:                     quantities,
668:                     cb
669:                 ));
670:             self.call(result)?;
671:             let after_coins: u64 = self
672:                 .connection
673:                 .db
674:                 .party_inventory_item()
675:                 .iter()
676:                 .filter(|row| row.party_id == party.id && is_currency_id(&row.item_id))
677:                 .map(|row| u64::from(row.quantity))
678:                 .sum();
679:             self.metrics.sale_proceeds += after_coins.saturating_sub(before_coins);
680:             self.event(
681:                 leader_agent,
682:                 CoreLoopEventKind::Liquidate,
683:                 format!("stacks={}", sale.len()),
684:             );
685:         }
686:         // Spending priority is medical care, then repairs, then upgrades.
687:         for agent in self.party_agents(leader)? {
688:             if self.ensure_medically_safe(agent)? {
689:                 self.maintain_equipment(agent)?;
690:             }
691:         }
692:         if let Some((current_agent, _)) =
693:             self.refreshed_safe_party_for_owner(party_id, quest_owner)?
694:         {
695:             let current_leader = self.character_ids[current_agent as usize];
696:             for party_agent in self.party_agents(current_leader)? {
697:                 self.try_upgrade(party_agent, &quest.settlement_id)?;
698:             }
699:         }
700:         Ok(())
701:     }
702: 
703:     pub(super) fn try_upgrade(&mut self, agent: u32, settlement: &str) -> Result<(), String> {
704:         let character_id = self.character_ids[agent as usize];
705:         let profile = self.profiles[agent as usize].clone();
706:         let equipped_ids = self
707:             .connection
708:             .db
709:             .character_equipped_item()
710:             .iter()
711:             .filter(|row| row.character_id == character_id)
712:             .map(|row| row.inventory_item_id)
713:             .collect::<HashSet<_>>();
714:         let inventories: Vec<_> = self
715:             .connection
716:             .db
717:             .inventory_item()
718:             .iter()
719:             .filter(|row| row.character_id == character_id)
720:             .collect();
721:         let definitions: Vec<_> = self.connection.db.item().iter().collect();
722:         let equipped_definitions = inventories
723:             .iter()
724:             .filter(|row| equipped_ids.contains(&row.id))
725:             .filter_map(|row| {
726:                 let definition = definitions.iter().find(|item| item.id == row.item_id)?;
727:                 let condition = self
728:                     .connection
729:                     .db
730:                     .item_condition()
731:                     .iter()
732:                     .find(|value| value.inventory_item_id == row.id)
733:                     .map_or(1.0, |value| {
734:                         1.0 - (value.tier_1
735:                             + value.tier_2
736:                             + value.tier_3
737:                             + value.tier_4
738:                             + value.tier_5)
739:                             .clamp(0.0, 1.0)
740:                     });
741:                 Some((definition, condition))
742:             })
743:             .collect::<Vec<_>>();
744:         let character = self
745:             .connection
746:             .db
747:             .backend_characters()
748:             .iter()
749:             .find(|row| row.id == character_id)
750:             .ok_or("missing upgrade character")?;
751:         let party_id = character.party_id.ok_or("missing upgrade party")?;
752:         let stake = self
753:             .connection
754:             .db
755:             .party_stake()
756:             .iter()
757:             .find(|row| row.party_id == party_id && row.character_id == character_id)
758:             .map_or(0, |row| row.value);
759:         let (party_load_kg, party_capacity_kg, _) = self.public_party_load_and_capacity(&party_id);
760:         let mut candidates = definitions
761:             .iter()
762:             .filter_map(|candidate| {
763:                 let utility = equipment_utility(&profile, candidate)?;
764:                 let armor = matches!(
765:                     candidate.kind,
766:                     CatalogItemKind::Armor | CatalogItemKind::Clothing
767:                 );
768:                 let current = equipped_definitions
769:                     .iter()
770:                     .filter(|(item, _)| {
771:                         if candidate.melee || candidate.ranged {
772:                             item.melee || item.ranged
773:                         } else {
774:                             armor
775:                                 && matches!(
776:                                     item.kind,
777:                                     CatalogItemKind::Armor | CatalogItemKind::Clothing
778:                                 )
779:                                 && item.slot == candidate.slot
780:                         }
781:                     })
782:                     .filter_map(|(item, condition)| {
783:                         equipment_utility(&profile, item).map(|utility| utility * *condition)
784:                     })
785:                     .fold(0.0, f32::max);
786:                 let (service_id, provider_id, quoted_cost) =
787:                     self.public_equipment_storefront_offer(character_id, settlement, candidate)?;
788:                 let medical_reserve = self
789:                     .observable_medical_reserve(character_id, settlement)
790:                     .unwrap_or(0);
791:                 let personal_spendable = self
792:                     .personal_gold(character_id)
793:                     .saturating_sub(medical_reserve);
794:                 let earned_shortfall = quoted_cost.saturating_sub(personal_spendable);
795:                 let projected_remaining = public_encumbrance_remaining_bps(
796:                     party_load_kg + candidate.weight.max(0.0),
797:                     party_capacity_kg,
798:                 );
799:                 (utility > current
800:                     && earned_shortfall <= stake
801:                     && projected_remaining >= MIN_DEPARTURE_ENCUMBRANCE_REMAINING_BPS)
802:                     .then_some((
803:                         utility - current,
804:                         quoted_cost,
805:                         earned_shortfall,
806:                         medical_reserve,
807:                         service_id,
808:                         provider_id,
809:                         candidate.clone(),
810:                     ))
811:             })
812:             .collect::<Vec<_>>();
813:         candidates.sort_by(|left, right| {
814:             right
815:                 .0
816:                 .total_cmp(&left.0)
817:                 .then_with(|| left.6.id.cmp(&right.6.id))
818:         });
819:         let Some((
820:             improvement,
821:             quoted_cost,
822:             earned_shortfall,
823:             medical_reserve,
824:             service_id,
825:             provider_id,
826:             candidate,
827:         )) = candidates.into_iter().next()
828:         else {
829:             return Ok(());
830:         };
831:         let selected_offer = (service_id.clone(), provider_id, quoted_cost);
832:         if !storefront_offer_unchanged(
833:             &selected_offer,
834:             self.public_equipment_storefront_offer(character_id, settlement, &candidate),
835:         ) {
836:             return Ok(());
837:         }
838:         let purse_before_trade = self.personal_gold(character_id);
839:         let stake_before_trade = self
840:             .connection
841:             .db
842:             .party_stake()
843:             .iter()
844:             .find(|row| row.party_id == party_id && row.character_id == character_id)
845:             .map_or(0, |row| row.value);
846:         let maximum_personal_payment = quoted_cost.saturating_sub(earned_shortfall);
847:         let result = reducer_call!(self, ReducerOperation::PurchasePersonalStorefrontWithPartyStake,
848:             |cb| self
849:                 .connection
850:                 .reducers
851:                 .purchase_personal_storefront_with_party_stake_then(
852:                     character_id,
853:                     settlement.to_string(),
854:                     service_id.clone(),
855:                     provider_id,
856:                     candidate.id.clone(),
857:                     1,
858:                     quoted_cost,
859:                     maximum_personal_payment,
860:                     earned_shortfall,
861:                     cb,
862:                 )
863:         );
864:         if let Err(error) = result {
865:             if merchant_provider_unavailable_failure(&error) {
866:                 return Ok(());
867:             }
868:             return self.call(Err(error));
869:         }
870:         let purse_after_trade = self.personal_gold(character_id);
871:         let stake_after_trade = self
872:             .connection
873:             .db
874:             .party_stake()
875:             .iter()
876:             .find(|row| row.party_id == party_id && row.character_id == character_id)
877:             .map_or(0, |row| row.value);
878:         let personal_spent = purse_before_trade.saturating_sub(purse_after_trade);
879:         let stake_spent = stake_before_trade.saturating_sub(stake_after_trade);
880:         let actual_cost = personal_spent.saturating_add(stake_spent);
881:         self.metrics.earned_gold_withdrawn = self
882:             .metrics
883:             .earned_gold_withdrawn
884:             .saturating_add(stake_spent);
885:         self.metrics.equipment_purchases += 1;
886:         self.event(
887:             agent,
888:             CoreLoopEventKind::Purchase,
889:             format!(
890:                 "item={};storefront={service_id};provider={provider_id};upper_bound_quote={quoted_cost};actual_cost={actual_cost};personal_spent={personal_spent};stake_spent={stake_spent};authorized_stake_max={earned_shortfall};medical_reserve={medical_reserve};utility_gain={improvement:.3}",
891:                 candidate.id,
892:             ),
893:         );
894:         let inventory = self
895:             .connection
896:             .db
897:             .inventory_item()
898:             .iter()
899:             .filter(|row| row.character_id == character_id && row.item_id == candidate.id)
900:             .max_by_key(|row| row.id)
901:             .ok_or("purchase succeeded but inventory was not coherent")?;
902:         let destination = if candidate.melee || candidate.ranged {
903:             let held = self
904:                 .connection
905:                 .db
906:                 .equipment_occupancy()
907:                 .iter()
908:                 .filter(|row| {
909:                     row.character_id == character_id && row.channel == EquipmentChannel::Held
910:                 })
911:                 .collect::<Vec<_>>();
912:             if !held
913:                 .iter()
914:                 .any(|row| row.location == Some(EquipmentLocation::LeftHand))
915:             {
916:                 Slot::LeftHolding
917:             } else {
918:                 Slot::RightHolding
919:             }
920:         } else {
921:             candidate.slot
922:         };
923:         let placement_index = candidate
924:             .equipment_placements
925:             .iter()
926:             .position(|placement| {
927:                 placement.parents.is_empty()
928:                     && placement
929:                         .occupancy
930:                         .iter()
931:                         .any(|requirement| root_requirement_matches_slot(requirement, destination))
932:             })
933:             .and_then(|index| u16::try_from(index).ok())
934:             .ok_or("equipment upgrade lacks a compatible authored root placement")?;
935:         let result = reducer_call!(self, ReducerOperation::ReplaceItemAtPlacement, |cb| self
936:             .connection
937:             .reducers
938:             .replace_item_at_placement_then(
939:                 character_id,
940:                 inventory.id,
941:                 placement_index,
942:                 Vec::new(),
943:                 cb,
944:             ));
945:         self.call(result)?;
946:         let verified = self
947:             .connection
948:             .db
949:             .character_equipped_item()
950:             .iter()
951:             .any(|row| row.character_id == character_id && row.inventory_item_id == inventory.id);
952:         if !verified {
953:             return Err("equip reducer completed without the requested equipped state".into());
954:         }
955:         self.metrics.equipment_upgrades += 1;
956:         self.item_event(
957:             agent,
958:             CoreLoopEventKind::Equip,
959:             inventory.id,
960:             candidate.id,
961:         );
962:         Ok(())
963:     }
964: }

1: //! Departure readiness, safe-wait selection, and provisioning deferrals.
2: 
3: use super::*;
4: 
5: pub(super) const TRAVEL_PROVISION_RESERVE_DAYS: f32 = 1.0;
6: pub(super) const MAX_TRAVEL_PROVISION_UNITS_PER_ITEM: u32 = 512;
7: /// Public fail-safe bound for a disclosed one-way distance. The ordinary
8: /// daylight projection covers schedule downtime; four times that projection
9: /// covers fatigue-expanded outbound travel plus the return leg. The separate
10: /// reserve day remains available for delays and encounters.
11: pub(super) const JOURNEY_PROVISION_ELAPSED_BOUND_FACTOR: u64 = 4;
12: /// Keep a material movement margin rather than departing at the point where
13: /// the authoritative linear encumbrance rule reaches zero.
14: pub(super) const MIN_DEPARTURE_ENCUMBRANCE_REMAINING_BPS: u32 = 2_000;
15: pub(super) const MAX_DEPARTURE_WETNESS_BPS: u16 = 8_000;
16: pub(super) const MAX_DEPARTURE_ABS_THERMAL_STRAIN: u32 = 2_500;
17: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
18: pub(super) enum DepartureDeferralReason {
19:     AmmunitionProviderProjectionUnavailable,
20:     AmmunitionUnaffordable,
21:     AmmunitionWouldOverload,
22:     EquipmentNotReady,
23:     PartyLoadUnsafe,
24:     PartyTentQuoteUnavailable,
25:     PartyTentUnaffordable,
26:     PartyTentWouldOverload,
27:     RouteActionNotSurvivable,
28:     RouteActionSiteMismatch,
29:     RouteFatigueRecoveryRequired,
30:     RouteThermalRisk,
31:     RouteThermalUnsafeAllPublicWindows,
32:     RouteWeatherProjectionUnavailable,
33:     SafePublicRouteWindow,
34:     WaitTowardSafePublicRouteWindow,
35:     SurvivalProjectionUnavailable,
36:     SurvivalReadinessRequiresSettlement,
37:     ThermalRecoveryRequired,
38: }
39: 
40: impl DepartureDeferralReason {
41:     pub(super) const fn as_str(self) -> &'static str {
42:         match self {
43:             Self::AmmunitionProviderProjectionUnavailable => {
44:                 "ammunition_provider_projection_unavailable"
45:             }
46:             Self::AmmunitionUnaffordable => "ammunition_unaffordable",
47:             Self::AmmunitionWouldOverload => "ammunition_would_overload",
48:             Self::EquipmentNotReady => "equipment_not_ready",
49:             Self::PartyLoadUnsafe => "party_load_unsafe",
50:             Self::PartyTentQuoteUnavailable => "party_tent_quote_unavailable",
51:             Self::PartyTentUnaffordable => "party_tent_unaffordable",
52:             Self::PartyTentWouldOverload => "party_tent_would_overload",
53:             Self::RouteActionNotSurvivable => "route_action_not_survivable",
54:             Self::RouteActionSiteMismatch => "route_action_site_mismatch",
55:             Self::RouteFatigueRecoveryRequired => "route_fatigue_recovery_required",
56:             Self::RouteThermalRisk => "route_thermal_risk",
57:             Self::RouteThermalUnsafeAllPublicWindows => "route_thermal_unsafe_all_public_windows",
58:             Self::RouteWeatherProjectionUnavailable => "route_weather_projection_unavailable",
59:             Self::SafePublicRouteWindow => "safe_public_route_window",
60:             Self::WaitTowardSafePublicRouteWindow => "wait_toward_safe_public_route_window",
61:             Self::SurvivalProjectionUnavailable => "survival_projection_unavailable",
62:             Self::SurvivalReadinessRequiresSettlement => "survival_readiness_requires_settlement",
63:             Self::ThermalRecoveryRequired => "thermal_recovery_required",
64:         }
65:     }
