74: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
75: pub(super) enum DepartureReadiness {
76:     Ready,
77:     ReadyWithItinerary {
78:         walking_minutes_per_day: u16,
79:         travel_at_night: bool,
80:         case_site_recovery_minutes: u64,
81:     },
82:     WaitForSafeDeparture {
83:         reason: DepartureDeferralReason,
84:         wait_minutes: u64,
85:         walking_minutes_per_day: u16,
86:         travel_at_night: bool,
87:         case_site_recovery_minutes: u64,
88:     },
89:     Deferred(DepartureDeferralReason),
90: }
91: 
92: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
93: pub(super) struct SettlementDepartureWait<'a> {
94:     pub(super) character_id: u64,
95:     pub(super) agent: u32,
96:     pub(super) case_id: &'a str,
97:     pub(super) reason: DepartureDeferralReason,
98:     pub(super) wait_minutes: u64,
99:     pub(super) walking_minutes_per_day: u16,
100:     pub(super) travel_at_night: bool,
101: }
102: 
103: pub(super) fn safe_departure_wait_minutes(
104:     immediate_safe: bool,
105:     delayed_safe: bool,
106:     wait_minutes: Option<u64>,
107: ) -> Option<u64> {
108:     (!immediate_safe && delayed_safe)
109:         .then_some(wait_minutes?)
110:         .filter(|minutes| (60..=MINUTES_PER_DAY).contains(minutes))
111: }
112: 
113: pub(super) const MAX_CASE_SITE_SAFE_WINDOW_SEARCH_DAYS: u64 = 7;
114: pub(super) const MAX_CASE_SITE_SAFE_WINDOW_SEARCH_MINUTES: u64 =
115:     MAX_CASE_SITE_SAFE_WINDOW_SEARCH_DAYS * MINUTES_PER_DAY;
116: 
117: pub(super) fn generated_safe_departure_waits(
118:     starting_minute: StrategicMinute,
119:     walking_minutes: u16,
120:     travel_at_night: bool,
121: ) -> Vec<u64> {
122:     let mut waits = (60..=MAX_CASE_SITE_SAFE_WINDOW_SEARCH_MINUTES)
123:         .step_by(60)
124:         .filter(|wait| {
125:             adventuresim_core::strategic_time::is_walking_time(
126:                 starting_minute.saturating_add_minutes(*wait),
127:                 walking_minutes,
128:                 travel_at_night,
129:             )
130:         })
131:         .collect::<Vec<_>>();
132:     waits.extend(generated_daily_walking_start_waits(
133:         starting_minute,
134:         walking_minutes,
135:         travel_at_night,
136:     ));
137:     waits.sort_unstable();
138:     waits.dedup();
139:     waits
140: }
141: 
142: pub(super) fn generated_daily_walking_start_waits(
143:     starting_minute: StrategicMinute,
144:     walking_minutes: u16,
145:     travel_at_night: bool,
146: ) -> Vec<u64> {
147:     (0..=MAX_CASE_SITE_SAFE_WINDOW_SEARCH_DAYS)
148:         .filter_map(|day_offset| {
149:             let day_wait = day_offset * MINUTES_PER_DAY;
150:             adventuresim_core::strategic_time::minutes_until_next_walking_start(
151:                 starting_minute.saturating_add_days(day_offset),
152:                 walking_minutes,
153:                 travel_at_night,
154:             )
155:             .and_then(|wait| forecast_safe_departure_wait_minutes(day_wait.saturating_add(wait)))
156:         })
157:         .collect()
158: }
159: 
160: pub(super) fn forecast_safe_departure_wait_minutes(next_walking_start: u64) -> Option<u64> {
161:     (next_walking_start <= MAX_CASE_SITE_SAFE_WINDOW_SEARCH_MINUTES)
162:         .then_some(next_walking_start.max(60))
163: }
164: 
165: pub(super) fn representable_safe_departure_wait_minutes(next_walking_start: u64) -> Option<u64> {
166:     (next_walking_start <= MINUTES_PER_DAY).then_some(next_walking_start.max(60))
167: }
168: 
169: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
170: pub(super) enum TravelProvisionDeferralReason {
171:     ContributionRevalidationFailed,
172:     EssentialsUnaffordable,
