135: pub(super) fn public_discovery_referral_to_follow(
136:     owner_character_id: u64,
137:     before: &HashMap<String, PublicDiscoveryReferral>,
138:     open_cases: &HashSet<String>,
139:     after: impl IntoIterator<Item = PublicDiscoveryReferral>,
140: ) -> Option<PublicDiscoveryReferral> {
141:     let mut newest_changed: Option<PublicDiscoveryReferral> = None;
142:     let mut newest_unresolved: Option<PublicDiscoveryReferral> = None;
143:     for lead in after.into_iter().filter(|lead| {
144:         lead.owner_character_id == owner_character_id
145:             && !lead.case_id.is_empty()
146:             && !lead.witness_name.is_empty()
147:             && lead.corrected_by.is_empty()
148:     }) {
149:         let later_than_changed = newest_changed.as_ref().is_none_or(|current| {
150:             (lead.recorded_at, &lead.lead_id) > (current.recorded_at, &current.lead_id)
151:         });
152:         let later_than_unresolved = newest_unresolved.as_ref().is_none_or(|current| {
153:             (lead.recorded_at, &lead.lead_id) > (current.recorded_at, &current.lead_id)
154:         });
155:         if before.get(&lead.lead_id) != Some(&lead) && later_than_changed {
156:             newest_changed = Some(lead.clone());
157:         }
158:         if !open_cases.contains(&lead.case_id) && later_than_unresolved {
159:             newest_unresolved = Some(lead);
160:         }
161:     }
162:     newest_changed.or(newest_unresolved)
163: }
