1: //! Strategic and narrative encounter choice policy.
2: 
3: use super::*;
4: 
5: pub(super) const RANGED_AMMUNITION_ITEM_ID: &str = "arrow";
6: /// One ordinary autoresolve can consume several arrows. Twenty leaves a
7: /// conservative reserve for an encounter plus the disclosed quest fight.
8: pub(super) const RANGED_AMMUNITION_FLOOR: u32 = 20;
9: #[derive(Clone, Debug, PartialEq, Eq)]
10: pub(super) struct EncounterPolicyChoice {
