15: pub(super) fn select_expedition_encounter_choice(
16:     available_choices: &[String],
17:     evacuation: bool,
18: ) -> Option<EncounterPolicyChoice> {
19:     let has = |candidate: &str| available_choices.iter().any(|choice| choice == candidate);
20:     if has("detour") {
21:         return Some(EncounterPolicyChoice {
22:             choice: "detour".into(),
23:             reason: "guaranteed_party_aware_detour",
24:         });
25:     }
26:     if has("run") {
27:         return Some(EncounterPolicyChoice {
28:             choice: "run".into(),
29:             reason: "public_speed_check_allows_escape",
30:         });
31:     }
32:     if has("surrender") {
33:         return Some(EncounterPolicyChoice {
34:             choice: "surrender".into(),
35:             reason: "bandit_surrender_is_only_protective_choice",
36:         });
37:     }
38:     (!evacuation && has("attack")).then(|| EncounterPolicyChoice {
39:         choice: "attack".into(),
40:         reason: "no_protective_response_available",
41:     })
42: }
43: 
