45: pub(super) struct NarrativeEncounterPolicyChoice {
46:     pub(super) choice: String,
47:     pub(super) reason: &'static str,
48:     pub(super) visible_alternatives: Vec<String>,
49:     pub(super) eligible_meaningful_alternatives: Vec<String>,
50: }
51: 
52: pub(super) fn narrative_axis_fit(
53:     profile: &AgentProfile,
54:     development: &adventuresim_core::road_encounter_catalog::PersonalityDevelopment,
55: ) -> i32 {
56:     use adventuresim_core::road_encounter_catalog::PersonalityAxisId;
57:     let preferred_sign = match development.axis {
58:         PersonalityAxisId::Nerve => match profile.personality.nerve {
59:             Nerve::Brave => 1,
60:             Nerve::Fearful => -1,
61:             Nerve::Neutral => 0,
62:         },
63:         PersonalityAxisId::Drive => match profile.personality.drive {
64:             Drive::Ambitious => 1,
65:             Drive::Content => -1,
66:             Drive::Neutral => 0,
67:         },
68:         PersonalityAxisId::Sociability => match profile.personality.sociability {
69:             Sociability::Gregarious => 1,
70:             Sociability::Solitary => -1,
71:             Sociability::Neutral => 0,
72:         },
73:         PersonalityAxisId::Conscience => match profile.personality.conscience {
74:             Conscience::Compassionate => 1,
75:             Conscience::Callous | Conscience::Cruel => -1,
76:             Conscience::Neutral => 0,
77:         },
78:         PersonalityAxisId::SelfRegard => match profile.personality.self_regard {
79:             SelfRegard::Proud => 1,
80:             SelfRegard::Humble => -1,
81:             SelfRegard::Neutral => 0,
82:         },
83:         PersonalityAxisId::Conviction => match profile.personality.conviction {
84:             Conviction::Zealous => 1,
85:             Conviction::Irreverent => -1,
86:             Conviction::Neutral => 0,
87:         },
88:         PersonalityAxisId::Transparency => match profile.personality.transparency {
89:             Transparency::Open => 1,
90:             Transparency::Guarded => -1,
91:             Transparency::Neutral => 0,
92:         },
93:         PersonalityAxisId::Courtship => 0,
94:     };
95:     preferred_sign * i32::from(development.delta.signum())
96: }
97: 
98: pub(super) fn select_public_narrative_encounter_choice(
99:     presentation_json: &str,
100:     profile: &AgentProfile,
101: ) -> Result<Option<NarrativeEncounterPolicyChoice>, serde_json::Error> {
102:     let presentation: adventuresim_core::road_encounter_catalog::EncounterPresentation =
103:         serde_json::from_str(presentation_json)?;
104:     let mut visible_alternatives = presentation
105:         .choices
106:         .iter()
107:         .filter(|choice| choice.available)
108:         .map(|choice| choice.id.clone())
109:         .collect::<Vec<_>>();
110:     visible_alternatives.sort();
111:     let ignore = visible_alternatives.iter().any(|choice| choice == "ignore");
112:     let mut meaningful = presentation
113:         .choices
114:         .iter()
115:         .filter(|choice| choice.available && choice.id != "ignore")
116:         .filter_map(|presented| {
117:             let mut authored = adventuresim_core::road_encounter_catalog::definitions()
118:                 .iter()
119:                 .flat_map(|definition| definition.choices.iter())
120:                 .filter(|choice| choice.id == presented.id);
121:             let choice = authored.next()?;
122:             if authored.next().is_some()
123:                 || !choice.checks.is_empty()
124:                 || matches!(
125:                     choice.transition.as_ref(),
126:                     Some(adventuresim_core::road_encounter_catalog::EncounterTransition::StartCombat { .. })
127:                 )
128:             {
129:                 return None;
130:             }
131:             let personality_fit = choice
132:                 .personality
133:                 .iter()
134:                 .map(|development| narrative_axis_fit(profile, development))
135:                 .sum::<i32>();
136:             // Public availability and authored requirements prove only that
137:             // a choice is legal. They do not establish that spending its
138:             // resources is preferable to continuing safely.
139:             (personality_fit > 0).then_some((presented.id.clone(), personality_fit))
140:         })
141:         .collect::<Vec<_>>();
142:     meaningful.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
143:     let eligible_meaningful_alternatives = meaningful
144:         .iter()
145:         .map(|(choice, _)| choice.clone())
146:         .collect::<Vec<_>>();
147:     if let Some((choice, _)) = meaningful.into_iter().next() {
148:         return Ok(Some(NarrativeEncounterPolicyChoice {
149:             choice,
150:             reason: "personality_aligned_check_free_noncombat",
151:             visible_alternatives,
152:             eligible_meaningful_alternatives,
153:         }));
154:     }
155:     Ok(ignore.then_some(NarrativeEncounterPolicyChoice {
156:         choice: "ignore".into(),
157:         reason: "unconditional_check_free_noncombat_fallback",
158:         visible_alternatives,
159:         eligible_meaningful_alternatives,
160:     }))
161: }
