185: 
186: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
187: pub(super) struct PublicContractAssessment {
188:     pub(super) eligible: bool,
189:     pub(super) reason: &'static str,
190:     pub(super) enemy_count: Option<u32>,
191:     pub(super) ready_combatants: u32,
192:     pub(super) party_power_milli: u64,
193:     pub(super) enemy_power_milli: u64,
194: }
195: 
196: pub(super) fn public_contract_assessment(
197:     difficulty: i32,
198:     opposition_count: u32,
199:     opposition_combat_power: u64,
200:     members: &[PublicPartyCombatant],
201: ) -> PublicContractAssessment {
202:     let Some(enemy_count) = (opposition_count > 0).then_some(opposition_count) else {
203:         return PublicContractAssessment {
204:             eligible: false,
205:             reason: "unknown_public_opposition_count",
206:             enemy_count: None,
207:             ready_combatants: 0,
208:             party_power_milli: 0,
209:             enemy_power_milli: 0,
210:         };
211:     };
212:     if difficulty <= 0 {
213:         return PublicContractAssessment {
214:             eligible: false,
215:             reason: "invalid_public_difficulty",
216:             enemy_count: Some(enemy_count),
217:             ready_combatants: 0,
218:             party_power_milli: 0,
219:             enemy_power_milli: 0,
220:         };
221:     }
222:     if opposition_combat_power == 0 {
223:         return PublicContractAssessment {
224:             eligible: false,
225:             reason: "missing_authoritative_opposition_power",
226:             enemy_count: Some(enemy_count),
227:             ready_combatants: 0,
228:             party_power_milli: 0,
229:             enemy_power_milli: 0,
230:         };
231:     }
232:     let ready = members
233:         .iter()
234:         .filter(|member| member.ready && (member.capability.melee || member.capability.ranged))
235:         .collect::<Vec<_>>();
236:     let Some(party_power_milli) = ready.iter().try_fold(0u64, |total, member| {
237:         total.checked_add(member.capability.autoresolve_combat_power)
238:     }) else {
239:         return PublicContractAssessment {
240:             eligible: false,
241:             reason: "public_party_power_overflow",
242:             enemy_count: Some(enemy_count),
243:             ready_combatants: ready.len().min(u32::MAX as usize) as u32,
244:             party_power_milli: 0,
245:             enemy_power_milli: opposition_combat_power,
246:         };
247:     };
248:     let enemy_power_milli = opposition_combat_power;
249:     let margin = adventuresim_core::autoresolve::combat_power_meets_safety_margin(
250:         party_power_milli,
251:         enemy_power_milli,
252:     );
253:     let eligible = !ready.is_empty() && margin == Some(true);
254:     PublicContractAssessment {
255:         eligible,
256:         reason: if ready.is_empty() {
257:             "no_ready_public_combatants"
258:         } else if party_power_milli == 0 {
259:             "missing_authoritative_party_power"
260:         } else if margin.is_none() {
261:             "public_combat_margin_overflow"
262:         } else if eligible {
263:             "public_matchup_with_safety_margin"
264:         } else {
265:             "public_matchup_below_safety_margin"
266:         },
267:         enemy_count: Some(enemy_count),
268:         ready_combatants: ready.len() as u32,
269:         party_power_milli,
270:         enemy_power_milli,
271:     }
272: }
