274: pub(super) fn public_combat_fingerprint(
275:     mut capabilities: Vec<CharacterCapability>,
276: ) -> PublicCombatFingerprint {
277:     const SKILL_CENTIPOINTS_PER_POINT: f32 = 100.0;
278: 
279:     capabilities.sort_by_key(|row| row.character_id);
280:     PublicCombatFingerprint {
281:         members: capabilities
282:             .into_iter()
283:             .map(|row| PublicCombatMemberFingerprint {
284:                 character_id: row.character_id,
285:                 melee: row.melee,
286:                 ranged: row.ranged,
287:                 armored: row.heavy || row.half_armor,
288:                 endurance_centipoints: (row.endurance.max(0.0) * SKILL_CENTIPOINTS_PER_POINT)
289:                     .round() as u32,
290:                 athletics_centipoints: (row.athletics.max(0.0) * SKILL_CENTIPOINTS_PER_POINT)
291:                     .round() as u32,
292:                 weapon_precision_centipoints: (row.weapon_precision.max(0.0)
293:                     * SKILL_CENTIPOINTS_PER_POINT)
294:                     .round() as u32,
295:                 autoresolve_combat_power: row.autoresolve_combat_power,
296:             })
297:             .collect(),
298:     }
299: }
