301: pub(super) fn generated_method_skill_fit(profile: &AgentProfile, method: &str) -> u32 {
302:     let skills = &profile.initial_skills;
303:     let hours = match method {
304:         "inspect_site" | "search_area" | "locate_contact" | "watch" | "patrol"
305:         | "approach_lead" => skills.insight,
306:         // The public action projection does not expose target terrain.
307:         "follow_tracks" | "reacquire_tracks" => 0.0,
308:         "lay_ambush" => (skills.insight + skills.stealth) / 2.0,
309:         _ => 0.0,
310:     };
311:     hours.clamp(0.0, 100_000.0).round() as u32
312: }
