46: #[cfg_attr(
47:     not(target_family = "wasm"),
48:     expect(dead_code, reason = "called by the browser probe export")
49: )]
50: async fn run(bytes: &[u8]) -> anyhow::Result<String> {
51:     use adventuresim_character_creator::{design_input, runtime_equipment};
52:     use anyhow::Context;
53:     let (body, _) = armor_fixture::load(bytes)?;
54:     let bracer = design_input::load_bracer_design(None)?;
55:     let breastplate = design_input::load_breastplate_design(None)?;
56:     let gpu = adventuresim_character_creator::armor_gpu_async().await?;
57:     let errors = capture_errors(gpu);
58:     let mut results = Vec::new();
59:     for round in 0..2 {
60:         for probe in [
61:             Probe::Catalog("vambrace", "left"),
62:             Probe::Catalog("breastplate", "worn"),
63:             Probe::Catalog("gorget", "worn"),
64:             Probe::Catalog("sallet", "worn"),
65:             Probe::Catalog("mail_standard", "worn"),
66:             Probe::Catalog("linen_tunic", "worn"),
67:             Probe::Catalog("leather_boot", "left"),
68:             Probe::Catalog("puffed_sleeve", "left"),
69:             Probe::Catalog("puffed_hose", "left"),
70:             Probe::Catalog("pauldron", "left"),
71:             Probe::Anime,
72:             Probe::Wrapped,
73:         ] {
74:             let (item, placement) = match probe {
75:                 Probe::Catalog(item, placement) => (item, placement),
76:                 Probe::Anime => ("anime", "worn"),
77:                 Probe::Wrapped => ("wrapped_tassets", "worn"),
78:             };
79:             let started = web_time::Instant::now();
80:             let cached_kernels = gpu.cache().len();
81:             let mut breastplate = breastplate.clone();
82:             let armor = if matches!(probe, Probe::Wrapped) {
83:                 wrapped(&body).await
84:             } else {
85:                 let recipe = if matches!(probe, Probe::Anime) {
86:                     breastplate.construction =
87:                         fabelgeist_armor::BreastplateConstruction::Anime(Default::default());
88:                     "cuirass"
89:                 } else {
90:                     item
91:                 };
92:                 runtime_equipment::generate(
93:                     &body,
94:                     adventuresim_core::equipment_assets::CatalogPlacement::find(
95:                         adventuresim_core::item_catalog::catalog(),
96:                         recipe,
97:                         placement,
98:                     )
99:                     .ok_or_else(|| anyhow::anyhow!("unknown equipment placement"))?,
100:                     &bracer,
101:                     &breastplate,
102:                     &[],
103:                 )
104:                 .await
105:                 .with_context(|| format!("fitting {item}, round {round}"))
106:             };
107:             let failures = errors.lock().unwrap().clone();
108:             anyhow::ensure!(failures.is_empty(), "WebGPU validation: {failures:?}");
109:             let armor = armor?;
110:             anyhow::ensure!(
111:                 gpu.cache().len() == cached_kernels,
112:                 "post-readiness fit compiled new kernels: {item}"
113:             );
114:             anyhow::ensure!(
115:                 armor.morphs.is_empty(),
116:                 "runtime equipment generated morph targets"
117:             );
118:             anyhow::ensure!(
119:                 !armor.positions.is_empty() && !armor.indices.is_empty(),
120:                 "empty equipment"
121:             );
122:             anyhow::ensure!(
123:                 armor
124:                     .positions
125:                     .iter()
126:                     .chain(&armor.normals)
127:                     .flatten()
128:                     .all(|v| v.is_finite()),
129:                 "non-finite mesh"
130:             );
131:             anyhow::ensure!(
132:                 armor
133:                     .indices
134:                     .iter()
135:                     .all(|&index| (index as usize) < armor.positions.len()),
136:                 "invalid mesh index"
137:             );
138:             anyhow::ensure!(
139:                 armor.indices.as_chunks::<3>().0.iter().any(|face| {
140:                     let [a, b, c] =
141:                         face.map(|i| bevy::math::Vec3::from(armor.positions[i as usize]));
142:                     (b - a).cross(c - a).length_squared() > 1e-14
143:                 }),
144:                 "collapsed equipment geometry: {item}"
145:             );
146:             results.push(serde_json::json!({"item":item,"round":round,"ms":started.elapsed().as_secs_f64()*1000.0,
147:                 "vertices":armor.positions.len(),"triangles":armor.indices.len()/3,"morphs":armor.morphs.len(),
148:                 "new_kernels":gpu.cache().len()-cached_kernels}));
149:         }
150:     }
151:     Ok(serde_json::to_string_pretty(&results)?)
152: }
