158: fn capture_errors(
159:     gpu: &fabelgeist_armor::ArmorGpu,
160: ) -> std::sync::Arc<std::sync::Mutex<Vec<String>>> {
161:     let errors = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
162:     let captured = errors.clone();
