1: //! Independent triangle checks on generated walls, beyond edge closure.
2: use fabelgeist_armor::{GeneratedArmor, PlateFace};
3: use fabelgeist_bvh::{Aabb, TriangleBvh};
4: use fabelgeist_math::Vec3;
5: 
6: const CONTACT_DISTANCE_TOLERANCE_METERS: f64 = 1e-10;
7: const TRIANGLE_NORMAL_DIRECTION_TOLERANCE: f64 = 1e-4;
8: mod manifold;
9: mod shared_contact;
10: pub(super) use manifold::assert_closed_oriented_manifold;
