12: /// Small facets are usable when their f32 direction resolves the actual face.
13: /// An area floor alone cannot distinguish a small face from a collapsed one.
14: pub(super) fn assert_triangle_normal_resolved(points: [[f32; 3]; 3]) {
15:     let [a, b, c] = points.map(Vec3::from_array);
16:     let normal = (b - a).cross(c - a);
17:     let length = normal.length_squared().sqrt();
18:     assert!(length.is_finite() && length > 0.0);
19:     let [a, b, c] = points.map(|p| p.map(f64::from));
20:     let precise = cross(
21:         std::array::from_fn(|k| b[k] - a[k]),
22:         std::array::from_fn(|k| c[k] - a[k]),
23:     );
24:     let precise_length = dot(precise, precise).sqrt();
25:     let error = normal
26:         .to_array()
27:         .into_iter()
28:         .zip(precise)
29:         .map(|(found, expected)| {
30:             (f64::from(found) / f64::from(length) - expected / precise_length).powi(2)
31:         })
32:         .sum::<f64>();
33:     assert!(error < TRIANGLE_NORMAL_DIRECTION_TOLERANCE.powi(2));
34: }
