36: pub(super) fn assert_no_shell_crossings(armor: &GeneratedArmor) {
37:     let triangles = armor.indices.as_chunks::<3>().0.to_vec();
38:     let mesh = TriangleBvh::new(
39:         armor
40:             .positions
41:             .iter()
42:             .copied()
43:             .map(Vec3::from_array)
44:             .collect(),
45:         triangles.clone(),
46:     );
47:     for (id, face) in triangles.into_iter().enumerate() {
48:         let points = face.map(|i| Vec3::from_array(armor.positions[i as usize]));
49:         mesh.bvh
50:             .candidates_aabb(&Aabb::from_points(points), |other| {
51:                 if other as usize <= id {
52:                     return;
53:                 }
54:                 let (a, b, c) = mesh.triangle(other);
55:                 if shared_contact::beyond_shared_feature(points, [a, b, c]) {
56:                     assert!(
57:                         !intersect(points, [a, b, c]),
58:                         "shell triangles {id} and {other} intersect: {points:?} {:?}",
59:                         [a, b, c]
60:                     );
61:                 }
62:             });
63:     }
64: }
