66: pub(super) fn assert_walls_disjoint(armor: &GeneratedArmor) {
67:     let ranges = if armor.components.is_empty() {
68:         vec![0..armor.indices.len()]
69:     } else {
70:         armor
71:             .components
72:             .iter()
73:             .map(|part| part.indices.clone())
74:             .collect()
75:     };
76:     for (component, range) in ranges.into_iter().enumerate() {
77:         let wall = |kind| {
78:             armor.indices[range.clone()]
79:                 .chunks_exact(3)
80:                 .zip(&armor.faces[range.start / 3..range.end / 3])
81:                 .filter(|(_, face)| **face == kind)
82:                 .map(|(face, _)| [face[0], face[1], face[2]])
83:                 .collect::<Vec<_>>()
84:         };
85:         let inner = TriangleBvh::new(
86:             armor
87:                 .positions
88:                 .iter()
89:                 .copied()
90:                 .map(Vec3::from_array)
91:                 .collect(),
92:             wall(PlateFace::Inner),
93:         );
94:         for (outer_id, face) in wall(PlateFace::Outer).into_iter().enumerate() {
95:             let outer = face.map(|i| Vec3::from_array(armor.positions[i as usize]));
96:             inner.bvh.candidates_aabb(&Aabb::from_points(outer), |inner_id| {
97:                 let (a, b, c) = inner.triangle(inner_id);
98:                 assert!(
99:                     !intersect([a, b, c], outer),
100:                     "component {component} inner {inner_id} crosses outer {outer_id}: {:?} {outer:?}",
101:                     [a, b, c],
102:                 );
103:             });
104:         }
105:     }
