108: fn intersect(a: [Vec3; 3], b: [Vec3; 3]) -> bool {
109:     let a = a.map(|p| p.to_array().map(f64::from));
110:     let b = b.map(|p| p.to_array().map(f64::from));
111:     let edges = |p: [[f64; 3]; 3]| {
112:         std::array::from_fn::<_, 3, _>(|i| {
113:             std::array::from_fn::<_, 3, _>(|k| p[(i + 1) % 3][k] - p[i][k])
114:         })
115:     };
116:     let ae = edges(a);
117:     let be = edges(b);
118:     let normals = [cross(ae[0], ae[1]), cross(be[0], be[1])];
119:     let separated = |axis: [f64; 3]| {
120:         let length = dot(axis, axis).sqrt();
121:         if length == 0.0 {
122:             return false;
123:         }
124:         let axis = axis.map(|v| v / length);
125:         let interval = |p: [[f64; 3]; 3]| {
126:             p.map(|p| dot(p, axis))
127:                 .into_iter()
128:                 .fold((f64::INFINITY, f64::NEG_INFINITY), |(low, high), v| {
129:                     (low.min(v), high.max(v))
130:                 })
131:         };
132:         let (al, ah) = interval(a);
133:         let (bl, bh) = interval(b);
134:         // Ten orders below a metre separates rounding noise from contact.
135:         ah < bl - CONTACT_DISTANCE_TOLERANCE_METERS || bh < al - CONTACT_DISTANCE_TOLERANCE_METERS
136:     };
137:     !normals.into_iter().any(separated)
138:         && !ae
139:             .into_iter()
140:             .any(|a| be.into_iter().any(|b| separated(cross(a, b))))
141:         && !ae.into_iter().any(|e| separated(cross(normals[0], e)))
142:         && !be.into_iter().any(|e| separated(cross(normals[1], e)))
143: }
144: 
145: fn dot(a: [f64; 3], b: [f64; 3]) -> f64 {
146:     (0..3).map(|k| a[k] * b[k]).sum()
147: }
148: 
149: fn cross(a: [f64; 3], b: [f64; 3]) -> [f64; 3] {
150:     [
151:         a[1] * b[2] - a[2] * b[1],
152:         a[2] * b[0] - a[0] * b[2],
153:         a[0] * b[1] - a[1] * b[0],
154:     ]
155: }
