170: 
171: fn report(
172:     item: &str,
173:     round: usize,
174:     targets: usize,
175:     started: Instant,
176:     result: Result<fabelgeist_armor::GeneratedArmor>,
177: ) -> Result<()> {
178:     let ms = started.elapsed().as_secs_f64() * 1000.0;
179:     match result {
180:         Ok(armor) => {
181:             anyhow::ensure!(
182:                 armor.positions.iter().flatten().all(|v| v.is_finite()),
183:                 "non-finite mesh"
184:             );
185:             anyhow::ensure!(
186:                 armor
187:                     .indices
188:                     .iter()
189:                     .all(|&i| (i as usize) < armor.positions.len()),
190:                 "invalid triangle"
191:             );
192:             anyhow::ensure!(
193:                 armor.morphs.len() == targets,
194:                 "unexpected equipment targets"
195:             );
196:             println!(
197:                 "{}",
198:                 serde_json::json!({"item":item,"round":round,"targets":targets,"ms":ms,"vertices":armor.positions.len(),"triangles":armor.indices.len()/3})
199:             );
200:         }
201:         Err(error) => {
202:             println!(
203:                 "{}",
204:                 serde_json::json!({"item":item,"round":round,"targets":targets,"ms":ms,"error":format!("{error:#}")})
205:             );
206:             return Err(error);
207:         }
208:     }
209:     Ok(())
210: }
