333: fn puffed_garment_extremes_are_closed_finite_shells() -> Result<()> {
334:     use adventuresim_character_creator::{
335:         armor_recipes::ParametricDesign,
336:         device_fit::{self, FitBody, Realization},
337:     };
338:     use fabelgeist_armor::{Permille, PuffAndSlashDesign};
339:     let (body, _) = armor_fixture::load(&std::fs::read(concat!(
340:         env!("CARGO_MANIFEST_DIR"),
341:         "/../../assets/animations/biped/unarmed/base.glb"
342:     ))?)?;
343:     let fit_body = FitBody {
344:         faces: &body.faces,
345:         texcoords: &body.texcoords,
346:         joint_indices: &body.joint_indices,
347:         joint_weights: &body.joint_weights,
348:         joint_names: &body.joint_names,
349:     };
350:     let wearer = Realization {
351:         positions: &body.positions,
352:         normals: &body.normals,
353:         joints: &body.global_joint_states,
354:         device: &body.device,
355:     };
356:     for (puff_count, slash_count) in [(1, 0), (8, 16)] {
357:         let design = ParametricDesign::PuffAndSlash(PuffAndSlashDesign {
358:             puff_count,
359:             slash_count,
360:             length: Permille(1000),
361:             proximal_position: Permille(1000),
362:             ..Default::default()
363:         });
364:         let piece = device_fit::fit_recipe(
365:             adventuresim_character_creator::armor_gpu()?,
366:             &fit_body,
367:             &wearer,
368:             &[],
369:             &design,
370:             adventuresim_character_creator::armor_frames::FittingPlacement::Lateral(
371:                 adventuresim_character_creator::armor_frames::Side::Left,
372:             ),
373:             &[],
374:         )?;
375:         assert!(piece.endpoints.is_empty());
376:         let part = piece.base;
377:         assert!(
378:             part.positions
379:                 .iter()
380:                 .chain(&part.normals)
381:                 .flatten()
382:                 .all(|v| v.is_finite())
383:         );
384:         assert_eq!(part.components.len(), 2);
385:         // Every shell must have positive area, including the fully unslashed
386:         // middle. Closed shells have no unpaired geometric boundary edges.
387:         let mut edges = std::collections::BTreeMap::<_, i32>::new();
388:         let key = |i: u32| part.positions[i as usize].map(f32::to_bits);
389:         for face in part.indices.as_chunks::<3>().0 {
390:             let [a, b, c] = face.map(|i| bevy::math::Vec3::from(part.positions[i as usize]));
391:             assert!((b - a).cross(c - a).length_squared() > 1e-18);
392:             for i in 0..3 {
393:                 let (a, b) = (key(face[i]), key(face[(i + 1) % 3]));
394:                 *edges.entry((a.min(b), a.max(b))).or_default() += if a < b { 1 } else { -1 };
395:             }
396:         }
397:         assert!(
398:             edges.values().all(|&balance| balance == 0),
399:             "open or reversed shell at {puff_count} puffs, {slash_count} slashes"
400:         );
401:     }
402:     Ok(())
403: }
