92: fn wrapped(gpu: &ArmorGpu, body: &RuntimeBody, slope: u16) -> Result<GeneratedArmor> {
93:     let mut garment = GarmentArmorDesign::new(GarmentArmorKind::Tassets);
94:     garment.lame_count = 8;
95:     garment.wall_thickness = Millimeters(1);
96:     garment.plate_shape = GarmentPlateShape::WrappedTassets(WrappedTassetDesign {
97:         upper_edge_slope: Permille(slope),
98:         ..Default::default()
99:     });
100:     let design = ParametricDesign::Garment(garment);
101:     let topology = FitBody {
102:         faces: &body.faces,
103:         texcoords: &body.texcoords,
104:         joint_indices: &body.joint_indices,
105:         joint_weights: &body.joint_weights,
106:         joint_names: &body.joint_names,
107:     };
108:     let wearer = Realization {
109:         positions: &body.positions,
110:         normals: &body.normals,
111:         joints: &body.global_joint_states,
112:         device: &body.device,
113:     };
114:     let piece = device_fit::fit_recipe(
115:         gpu,
116:         &topology,
117:         &wearer,
118:         &[],
119:         &design,
120:         adventuresim_character_creator::armor_frames::FittingPlacement::Unpaired,
121:         &[],
122:     )?;
123:     device_fit::assemble_recipe(
124:         &design,
125:         piece,
126:         &Fitted {
127:             placement: adventuresim_character_creator::armor_frames::FittingPlacement::Unpaired,
128:             morphs: &[],
129:             domain: &body.domain,
130:             joint_names: &body.joint_names,
131:             joints: &body.global_joint_states,
132:         },
133:     )
134: }
