136: fn report(name: &str, round: usize, start: Instant, armor: &GeneratedArmor) -> Result<()> {
137:     let ms = start.elapsed().as_secs_f64() * 1000.0;
138:     anyhow::ensure!(
139:         armor.morphs.is_empty() && armor.positions.iter().flatten().all(|v| v.is_finite()),
140:         "invalid runtime mesh"
141:     );
142:     println!(
143:         "{}",
144:         serde_json::json!({"item":name,"round":round,"ms":ms,"vertices":armor.positions.len(),"targets":armor.morphs.len()})
145:     );
146:     Ok(())
147: }
