91:     pub(super) fn clear_motion(&mut self, motion: CalibrationMotion) {
92:         self.phase_curves.remove(&motion);
93:         self.measured_clips.remove(&motion);
94:         match motion {
95:             CalibrationMotion::Walk => self.walk = None,
96:             CalibrationMotion::Run => self.run = None,
97:             CalibrationMotion::Strafe => self.strafe = None,
