114:     pub(super) fn sample_phase(
115:         &self,
116:         pose: SemanticPose,
117:         physical_phase: CyclePhase,
118:     ) -> AnimationValueResult<CyclePhase> {
119:         if !self.has_current_configuration() {
120:             return Ok(physical_phase.wrapped());
121:         }
122:         let motion = match pose {
123:             SemanticPose::WalkContact => CalibrationMotion::Walk,
124:             SemanticPose::RunContact => CalibrationMotion::Run,
125:             _ => return Ok(physical_phase.wrapped()),
126:         };
127:         self.phase_curves.get(&motion).map_or_else(
128:             || Ok(physical_phase.wrapped()),
129:             |curve| curve.sample(physical_phase),
130:         )
131:     }
