133:     pub(super) fn ordinary(
134:         &self,
135:         speed: NonnegativeSpeed,
136:     ) -> AnimationValueResult<Option<AuthoredStrideMeasurement>> {
137:         if !self.has_current_configuration() {
138:             return Ok(None);
139:         }
140:         let Some(walk) = self.walk else {
141:             return Ok(None);
142:         };
143:         let blend = ((speed.metres_per_second()
144:             - walk_locomotion_profile()
145:                 .reference_speed
146:                 .metres_per_second())
147:             / (run_locomotion_profile().reference_speed.metres_per_second()
148:                 - walk_locomotion_profile()
149:                     .reference_speed
150:                     .metres_per_second()))
151:         .clamp(0.0, 1.0);
152:         if blend <= 0.0 {
153:             Ok(Some(walk))
154:         } else {
155:             let Some(run) = self.run else {
156:                 return Ok(None);
157:             };
158:             walk.lerp(run, UnitInterval::from_fraction(blend)?)
159:                 .map(Some)
160:         }
161:     }
162: 
163:     pub(super) fn combat(
164:         &self,
165:         direction: Vec2,
166:     ) -> AnimationValueResult<Option<AuthoredStrideMeasurement>> {
167:         if !self.has_current_configuration() {
168:             return Ok(None);
169:         }
170:         let strafe_weight = direction.x.abs();
171:         let skip_weight = direction.y.abs();
172:         let total = strafe_weight + skip_weight;
173:         if total <= 0.0 {
174:             return Ok(None);
175:         }
176:         // Native weighted mean of rig-local metre measurements, in original X/Y order.
177:         let mut step_distance = 0.0;
178:         let mut maximum_stance_slip = 0.0;
179:         if strafe_weight > 0.0 {
180:             let Some(strafe) = self.strafe else {
181:                 return Ok(None);
182:             };
183:             step_distance += strafe.step_distance.metres() * strafe_weight;
184:             maximum_stance_slip += strafe.maximum_stance_slip.metres() * strafe_weight;
185:         }
186:         if skip_weight > 0.0 {
187:             let Some(skip) = self.skip else {
188:                 return Ok(None);
189:             };
190:             step_distance += skip.step_distance.metres() * skip_weight;
191:             maximum_stance_slip += skip.maximum_stance_slip.metres() * skip_weight;
192:         }
193:         step_distance /= total;
194:         maximum_stance_slip /= total;
195:         Ok(Some(AuthoredStrideMeasurement {
196:             step_distance: NonnegativeLength::from_arithmetic(step_distance)?,
197:             maximum_stance_slip: NonnegativeLength::from_arithmetic(maximum_stance_slip)?,
198:         }))
199:     }
200: }
