241: /// for a chain end, continued from its chain parent.
242: fn bone_direction(
243:     index: usize,
244:     rig: &HumanoidRig,
245:     globals: &Query<&GlobalTransform>,
246: ) -> Option<Vec3> {
247:     let definition = reactive_bone(index);
248:     let position = |role: BoneRole| {
249:         rig.get(&role)
250:             .and_then(|entity| globals.get(*entity).ok())
251:             .map(GlobalTransform::translation)
252:     };
253:     let origin = position(definition.role)?;
254:     let direction = match definition.tip {
255:         Some(tip) => position(tip)? - origin,
256:         None => origin - position(reactive_bone(definition.parent?).role)?,
257:     };
258:     direction.try_normalize()
259: }
