292: /// World rotation of `entity` from the live `Transform` chain.
293: fn live_world_rotation(
294:     entity: Entity,
295:     parents: &Query<&ChildOf>,
296:     transforms: &Query<&mut Transform>,
297: ) -> Quat {
298:     let mut rotation = Quat::IDENTITY;
299:     let mut current = Some(entity);
300:     while let Some(entity) = current {
301:         if let Ok(transform) = transforms.get(entity) {
302:             rotation = transform.rotation * rotation;
303:         }
304:         current = parents.get(entity).ok().map(ChildOf::parent);
305:     }
306:     rotation
307: }
