311:     reason = "the Bevy query pairs each rig owner with its spring state and pose ownership"
312: )]
313: pub(super) fn apply_bouncy_bones(
314:     time: Res<Time>,
315:     mut telemetry: ResMut<BouncyBonesTelemetry>,
316:     mut rigs: Query<(
317:         Entity,
318:         &HumanoidRig,
319:         &mut BouncyBones,
320:         Option<&PoseBufferRig>,
321:         Has<Ragdolling>,
322:     )>,
323:     bones: Query<&HumanoidBone>,
324:     parents: Query<&ChildOf>,
325:     children: Query<&Children>,
326:     mut transforms: Query<&mut Transform>,
327: ) {
328:     *telemetry = BouncyBonesTelemetry::default();
329:     let delta_seconds = time.delta_secs();
330:     if delta_seconds <= 0.0 {
331:         return;
332:     }
333:     let tuning = bounce_tuning();
334:     for (owner, rig, mut springs, pose_rig, ragdolling) in &mut rigs {
335:         // Wave coupling: a deflected bone torques its chain parent, scaled by
336:         // the parent's own response, so the kick takes several frames to
337:         // walk the chain one link at a time instead of the whole arm
338:         // starting at once. One-way up; the return trip rides transform
339:         // inheritance.
340:         let deflections: [Vec3; BONE_COUNT] = std::array::from_fn(|i| springs.springs[i].offset);
341:         for (index, deflection) in deflections.iter().enumerate() {
342:             if let Some(parent) = reactive_bone(index).parent
343:                 && *deflection != Vec3::ZERO
344:             {
345:                 springs.springs[parent].velocity += *deflection
346:                     * (tuning.coupling_per_second_squared
347:                         * reactive_bone(parent).response
348:                         * delta_seconds);
349:             }
350:         }
351:         let mut active = false;
352:         for spring in &mut springs.springs {
353:             if spring.at_rest() {
354:                 continue;
355:             }
356:             spring_step(
357:                 spring,
358:                 tuning.halflife_seconds,
359:                 tuning.frequency_hz,
360:                 delta_seconds,
361:             );
362:             spring.offset = spring.offset.clamp_length_max(tuning.maximum_angle_radians);
363:             active = true;
364:         }
365:         telemetry.active_springs += springs.active_springs();
366:         telemetry.maximum_deflection_radians = telemetry
367:             .maximum_deflection_radians
368:             .max(springs.maximum_deflection_radians());
369:         // Springs keep decaying while ragdolled or culled so a rig that gets
370:         // back up does not replay a stale wobble; only the transform walk is
371:         // skipped, because those bones belong to physics or hold a frozen
372:         // pose.
373:         if !active || ragdolling || pose_rig.is_some_and(PoseBufferRig::is_frozen) {
374:             continue;
375:         }
376:         let Some(rig_scene) = rig.rig_scene() else {
377:             continue;
378:         };
379:         let base = parents
380:             .get(rig_scene)
381:             .map(|parent| live_world_rotation(parent.parent(), &parents, &transforms))
382:             .unwrap_or(Quat::IDENTITY);
383:         let mut stack: Vec<(Entity, Quat)> = vec![(rig_scene, base)];
384:         while let Some((entity, parent_rotation)) = stack.pop() {
385:             let local_rotation = transforms
386:                 .get(entity)
387:                 .map(|transform| transform.rotation)
388:                 .unwrap_or(Quat::IDENTITY);
389:             let mut world_rotation = parent_rotation * local_rotation;
390:             if let Ok(bone) = bones.get(entity)
391:                 && bone.owner == owner
392:                 && let Some(index) = bone_index(bone.role)
393:             {
394:                 let offset = springs.springs[index].offset;
395:                 if offset.length_squared() > 1e-8
396:                     && let Ok(mut transform) = transforms.get_mut(entity)
397:                 {
398:                     let local_delta = world_rotation.inverse() * offset;
399:                     transform.rotation *= Quat::from_scaled_axis(local_delta);
400:                     world_rotation = parent_rotation * transform.rotation;
401:                 }
402:             }
403:             if let Ok(kids) = children.get(entity) {
404:                 stack.extend(kids.iter().map(|kid| (kid, world_rotation)));
405:             }
406:         }
407:     }
408: }
