22:         .0
23:         .iter()
24:         .map(|f| f.map(|i| vertices[i as usize]))
25:         .collect::<Vec<_>>();
26:     let mut edges = BTreeMap::<_, Vec<_>>::new();
27:     let mut incident = vec![Vec::new(); points.len()];
28:     for (id, face) in faces.iter().enumerate() {
29:         assert!(face[0] != face[1] && face[1] != face[2] && face[2] != face[0]);
30:         for &vertex in face {
31:             incident[vertex].push(id);
32:         }
33:         for i in 0..3 {
34:             let (a, b) = (face[i], face[(i + 1) % 3]);
35:             edges
36:                 .entry([a.min(b), a.max(b)])
37:                 .or_default()
38:                 .push((a, b, id));
39:         }
40:     }
41:     let mut neighbors = vec![Vec::new(); faces.len()];
42:     for (edge, uses) in edges {
43:         let [(a, b, first), (c, d, second)] = *uses.as_slice() else {
44:             panic!("nonmanifold edge {edge:?}: {uses:?}");
45:         };
46:         assert!(a == d && b == c, "incoherent winding at {edge:?}");
47:         neighbors[first].push((second, edge));
48:         neighbors[second].push((first, edge));
49:     }
50:     for (vertex, faces) in incident.iter().enumerate() {
51:         let Some(&first) = faces.first() else {
52:             continue;
53:         };
54:         let mut fan = BTreeSet::new();
55:         let mut pending = vec![first];
56:         while let Some(face) = pending.pop() {
57:             if !fan.insert(face) {
58:                 continue;
59:             }
60:             pending.extend(
61:                 neighbors[face]
62:                     .iter()
63:                     .filter(|(_, edge)| edge.contains(&vertex))
64:                     .map(|&(id, _)| id),
65:             );
66:         }
67:         assert_eq!(
68:             fan.len(),
69:             faces.len(),
70:             "disconnected vertex fan at {:?}",
71:             points[vertex]
72:         );
73:     }
74:     let mut seen = vec![false; faces.len()];
75:     for first in 0..faces.len() {
76:         if seen[first] {
77:             continue;
78:         }
79:         let origin = points[faces[first][0]];
80:         let mut volume = 0.0;
81:         let mut pending = vec![first];
82:         while let Some(face) = pending.pop() {
83:             if seen[face] {
84:                 continue;
85:             }
86:             seen[face] = true;
87:             let [a, b, c] = faces[face].map(|i| std::array::from_fn(|k| points[i][k] - origin[k]));
88:             volume += super::dot(a, super::cross(b, c)) / 6.0;
89:             pending.extend(neighbors[face].iter().map(|&(id, _)| id));
90:         }
91:         assert!(
92:             volume.is_finite() && volume > 0.0,
93:             "shell material has nonpositive volume {volume} m^3"
94:         );
95:     }
96: }
