1: //! Distinguish intended welded adjacency from overlap beyond that feature.
2: use fabelgeist_math::Vec3;
3: 
4: use super::{CONTACT_DISTANCE_TOLERANCE_METERS as TOLERANCE, cross, dot};
5: 
6: type Point = [f64; 3];
7: 
8: pub(super) fn beyond_shared_feature(a: [Vec3; 3], b: [Vec3; 3]) -> bool {
9:     let shared = a.into_iter().filter(|p| b.contains(p)).collect::<Vec<_>>();
10:     if shared.is_empty() || shared.len() == 3 {
11:         return true;
12:     }
13:     let a = a.map(|p| p.to_array().map(f64::from));
14:     let b = b.map(|p| p.to_array().map(f64::from));
15:     let normals = [normal(a), normal(b)];
16:     if b.iter()
17:         .all(|&p| dot(sub(p, a[0]), normals[0]).abs() <= TOLERANCE)
18:     {
19:         return coplanar_contact_beyond(a, b, normals[0], &shared);
20:     }
21:     // Two noncoplanar triangles sharing an edge meet only along that edge.
22:     if shared.len() == 2 {
23:         return false;
24:     }
25:     let line = unit(cross(normals[0], normals[1]));
26:     let Some(ai) = section(a, b[0], normals[1], line) else {
27:         return false;
28:     };
29:     let Some(bi) = section(b, a[0], normals[0], line) else {
30:         return false;
31:     };
32:     let contact = (ai.0.max(bi.0), ai.1.min(bi.1));
33:     if contact.0 > contact.1 + TOLERANCE {
34:         return false;
35:     }
36:     let allowed = dot(shared[0].to_array().map(f64::from), line);
37:     contact.0 < allowed - TOLERANCE || contact.1 > allowed + TOLERANCE
38: }
39: 
40: fn sub(a: Point, b: Point) -> Point {
41:     std::array::from_fn(|k| a[k] - b[k])
42: }
43: 
44: fn unit(p: Point) -> Point {
45:     let length = dot(p, p).sqrt();
46:     p.map(|v| v / length)
47: }
48: 
49: fn normal(p: [Point; 3]) -> Point {
50:     unit(cross(sub(p[1], p[0]), sub(p[2], p[0])))
51: }
52: 
53: fn section(p: [Point; 3], origin: Point, normal: Point, line: Point) -> Option<(f64, f64)> {
54:     let distances = p.map(|p| dot(sub(p, origin), normal));
55:     let mut interval: Option<(f64, f64)> = None;
56:     let mut include = |point| {
57:         let value = dot(point, line);
58:         interval = Some(match interval {
59:             Some((low, high)) => (low.min(value), high.max(value)),
60:             None => (value, value),
61:         });
62:     };
63:     for i in 0..3 {
64:         if distances[i].abs() <= TOLERANCE {
65:             include(p[i]);
66:         }
67:         let next = (i + 1) % 3;
68:         if distances[i] * distances[next] < 0.0 {
69:             let t = distances[i] / (distances[i] - distances[next]);
70:             include(std::array::from_fn(|k| {
71:                 p[i][k] + t * (p[next][k] - p[i][k])
72:             }));
73:         }
74:     }
75:     interval
76: }
77: 
78: fn coplanar_contact_beyond(a: [Point; 3], b: [Point; 3], normal: Point, shared: &[Vec3]) -> bool {
79:     let allowed = |point: Point| {
80:         let first = shared[0].to_array().map(f64::from);
81:         let closest = if shared.len() == 1 {
82:             first
83:         } else {
84:             let edge = sub(shared[1].to_array().map(f64::from), first);
85:             let t = (dot(sub(point, first), edge) / dot(edge, edge)).clamp(0.0, 1.0);
86:             std::array::from_fn(|k| first[k] + t * edge[k])
87:         };
88:         let distance = sub(point, closest);
89:         dot(distance, distance) <= TOLERANCE * TOLERANCE
90:     };
91:     let inside = |point: Point, triangle: [Point; 3]| {
92:         let sides = std::array::from_fn::<_, 3, _>(|i| {
93:             let edge = sub(triangle[(i + 1) % 3], triangle[i]);
94:             dot(cross(edge, sub(point, triangle[i])), normal) / dot(edge, edge).sqrt()
95:         });
96:         sides.iter().all(|&d| d >= -TOLERANCE) || sides.iter().all(|&d| d <= TOLERANCE)
97:     };
98:     if a.into_iter().any(|p| inside(p, b) && !allowed(p))
99:         || b.into_iter().any(|p| inside(p, a) && !allowed(p))
100:     {
101:         return true;
102:     }
103:     // Vertices and edge crossings are the vertices of the convex intersection,
104:     // including zero-area segment contacts. Each must lie on the shared feature.
105:     for i in 0..3 {
106:         let ae = sub(a[(i + 1) % 3], a[i]);
107:         for j in 0..3 {
108:             let be = sub(b[(j + 1) % 3], b[j]);
109:             let denominator = dot(cross(ae, be), normal);
110:             if denominator == 0.0 {
111:                 continue;
112:             }
113:             let delta = sub(b[j], a[i]);
114:             let t = dot(cross(delta, be), normal) / denominator;
115:             let u = dot(cross(delta, ae), normal) / denominator;
116:             if (0.0..=1.0).contains(&t)
117:                 && (0.0..=1.0).contains(&u)
118:                 && !allowed(std::array::from_fn(|k| a[i][k] + t * ae[k]))
119:             {
120:                 return true;
121:             }
122:         }
123:     }
124:     false
125: }
