17: pub(super) fn refresh_animation_revisions(
18:     mut events: RevisionEvents,
19:     asset_server: Res<AssetServer>,
20:     gltfs: Res<Assets<Gltf>>,
21:     catalog: Res<AnimationPackCatalog>,
22:     mut runtime: ResMut<AnimationRuntime>,
23:     mut caches: RevisionCaches,
24: ) {
25:     let revisions = events.read(&runtime);
26:     let mut changed = revisions.clips;
27:     let sources = revisions.sources;
28:     if changed.is_empty() && sources.is_empty() {
29:         return;
30:     }
31:     let motions = {
32:         let AnimationRuntime {
33:             requested_motions,
34:             clips,
35:             ..
36:         } = &mut *runtime;
37:         requested_motions
38:             .iter_mut()
39:             .filter_map(|(key, load)| {
40:                 let source_changed = sources
41:                     .iter()
42:                     .any(|&id| load.observe_source_revision(&asset_server, id));
43:                 let affected = source_changed
44:                     || clips
45:                         .get(key)
46:                         .is_some_and(|clip| changed.contains(&clip.handle.id()))
47:                     || load
48:                         .source()
49:                         .and_then(|source| gltfs.get(source))
50:                         .is_some_and(|gltf| {
51:                             gltf.animations
52:                                 .iter()
53:                                 .any(|clip| changed.contains(&clip.id()))
54:                         });
55:                 affected.then(|| key.clone())
56:             })
57:             .collect::<Vec<_>>()
58:     };
59:     let grips = runtime
60:         .requested_grips
61:         .iter()
62:         .filter(|(grip, source)| {
63:             sources.contains(&source.id())
64:                 || runtime
65:                     .grips
66:                     .get(*grip)
67:                     .is_some_and(|clip| changed.contains(&clip.handle.id()))
68:                 || gltfs.get(*source).is_some_and(|gltf| {
69:                     gltf.animations
70:                         .iter()
71:                         .any(|clip| changed.contains(&clip.id()))
72:                 })
73:         })
74:         .map(|(&grip, _)| grip)
75:         .collect::<Vec<_>>();
76:     for key in &motions {
77:         if let Some(clip) = runtime.clips.remove(key) {
78:             changed.insert(clip.handle.id());
79:         }
80:         runtime.unavailable_motions.remove(key);
81:     }
82:     for grip in grips {
83:         if let Some(clip) = runtime.grips.remove(&grip) {
84:             changed.insert(clip.handle.id());
85:         }
86:         runtime.processed_grips.remove(&grip);
87:         runtime.unavailable_grips.remove(&grip);
88:     }
89:     caches.bank.invalidate_assets(&changed);
90:     caches.strides.invalidate_assets(&changed);
91:     for mut character in &mut caches.characters {
92:         character.measurements.invalidate_assets(&changed);
93:     }
94:     for mut rig in &mut caches.rigs {
95:         rig.invalidate_clip_revisions(&changed);
96:     }
97:     if !motions.is_empty() {
98:         runtime.rebuild_loaded_library(&catalog);
99:     }
