77:             Err(error) => {
78:                 error!(%error, "Failed to serialize animation diagnostics");
79:                 return;
80:             }
81:         };
82:         value["frame"] = self.frame.into();
83:         if let Err(error) = serde_json::to_writer(&mut self.writer, &value) {
84:             error!(%error, "Failed to write animation diagnostics");
85:             return;
86:         }
87:         if let Err(error) = self.writer.write_all(b"\n") {
88:             error!(%error, "Failed to finish animation diagnostic record");
89:             return;
90:         }
91:         if self.frame % 60 == 59
92:             && let Err(error) = self.writer.flush()
93:         {
94:             error!(%error, "Failed to flush animation diagnostics");
95:             return;
96:         }
97:         self.frame += 1;
98:     }
99: }
