257: // --- Temporary per-system frame-time probe (diagnostic; safe to remove) -----
258: // Records the maximum wall time a handful of movement/animation systems take
259: // per frame and logs the ranking once a second, so `just client` reveals which
260: // system carries a running/jumping FPS drop without needing a Tracy capture.
261: static PERF_MAX_MS: std::sync::LazyLock<
262:     std::sync::Mutex<std::collections::HashMap<&'static str, f32>>,
263: > = std::sync::LazyLock::new(|| std::sync::Mutex::new(std::collections::HashMap::new()));
264: 
265: /// Drop guard that stamps its label's per-frame max on scope exit, so it
266: /// captures the cost even when a system returns early.
267: pub(in crate::animation) struct SpikeGuard {
268:     label: &'static str,
269:     start: web_time::Instant,
270: }
271: 
272: impl SpikeGuard {
273:     pub(in crate::animation) fn new(label: &'static str) -> Self {
274:         Self {
275:             label,
276:             start: web_time::Instant::now(),
277:         }
278:     }
279: }
280: 
281: impl Drop for SpikeGuard {
282:     fn drop(&mut self) {
283:         let ms = self.start.elapsed().as_secs_f32() * 1000.0;
284:         if let Ok(mut map) = PERF_MAX_MS.lock() {
285:             let entry = map.entry(self.label).or_insert(0.0);
286:             *entry = entry.max(ms);
287:         }
288:     }
289: }
290: 
291: pub(in crate::animation) fn report_system_spikes(time: Res<Time>, mut elapsed: Local<f32>) {
292:     *elapsed += time.delta_secs();
293:     if *elapsed < 1.0 {
294:         return;
295:     }
296:     *elapsed = 0.0;
297:     let Ok(mut map) = PERF_MAX_MS.lock() else {
298:         return;
299:     };
300:     if map.is_empty() {
301:         return;
302:     }
303:     let mut rows = map.iter().map(|(k, v)| (*k, *v)).collect::<Vec<_>>();
304:     rows.sort_by(|a, b| b.1.total_cmp(&a.1));
305:     let summary = rows
306:         .iter()
307:         .map(|(label, ms)| format!("{label} {ms:.2}ms"))
308:         .collect::<Vec<_>>()
309:         .join("  |  ");
310:     info!("PERF/frame-max (last 1s): {summary}");
311:     map.clear();
312: }
