1: //! Bounded left/right IK influence from semantic samples through pose solving.
2: 
3: use super::catalog;
4: use adventuresim_tactical_core::animation::{
5:     AnimationEvaluation, AnimationQuantity, AnimationValueError, AnimationValueResult, BlendWeight,
6:     ClipMirror, CycleDelta, CyclePhase, LocomotionProfile, PoseSampling, SemanticPose,
7:     UnitInterval, gait_support_weights, run_locomotion_profile, walk_locomotion_profile,
8: };
9: use bevy::math::Vec2;
10: 
11: #[derive(Clone, Copy, Debug, PartialEq)]
12: pub(super) struct FootIkInfluence {
13:     left: UnitInterval,
14:     right: UnitInterval,
15: }
16: 
17: impl FootIkInfluence {
18:     pub(super) const NONE: Self = Self::new(UnitInterval::ZERO, UnitInterval::ZERO);
19:     pub(super) const BOTH: Self = Self::new(UnitInterval::ONE, UnitInterval::ONE);
20:     pub(super) const LEFT: Self = Self::new(UnitInterval::ONE, UnitInterval::ZERO);
21:     pub(super) const RIGHT: Self = Self::new(UnitInterval::ZERO, UnitInterval::ONE);
22: 
23:     pub(super) const fn new(left: UnitInterval, right: UnitInterval) -> Self {
24:         Self { left, right }
25:     }
26: 
27:     pub(super) fn left(self) -> UnitInterval {
28:         self.left
29:     }
30: 
31:     pub(super) fn right(self) -> UnitInterval {
32:         self.right
33:     }
34: 
35:     /// Preserve the authored weighted reduction before admitting its result.
36:     pub(super) fn from_evaluation(evaluation: &AnimationEvaluation) -> AnimationValueResult<Self> {
37:         let samples = if !evaluation.lower_body.is_empty() {
38:             &evaluation.lower_body
39:         } else if evaluation.action.is_empty() {
40:             &evaluation.base
41:         } else {
42:             return Ok(Self::NONE);
43:         };
44:         let mut result = Vec2::ZERO;
45:         let mut total = BlendWeight::ZERO;
46:         for sample in samples {
47:             let mut weights = match (sample.pose, sample.sampling) {
48:                 (SemanticPose::IdleRelaxed, _) | (SemanticPose::CombatStance, _) => Self::BOTH,
49:                 (
50:                     SemanticPose::StrafeCycle | SemanticPose::SkipCycle,
51:                     PoseSampling::Cycle { phase },
52:                 ) => Self::combat_cycle(phase),
53:                 (
54:                     SemanticPose::QuickstepForwardTakeoff
55:                     | SemanticPose::QuickstepRightTakeoff
56:                     | SemanticPose::QuickstepLeftTakeoff
57:                     | SemanticPose::QuickstepBackTakeoff,
58:                     PoseSampling::Timeline { .. },
59:                 ) => Self::NONE,
60:                 (SemanticPose::WalkContact, PoseSampling::Cycle { phase }) => {
61:                     let (left, right) = gait_support_weights(walk_locomotion_profile(), phase)?;
62:                     Self::new(left, right)
63:                 }
64:                 (SemanticPose::RunContact, PoseSampling::Cycle { phase }) => {
65:                     // IK becomes strong near authored contact, after descent;
66:                     // simulation support owns the complete stance interval.
67:                     let contact_profile = LocomotionProfile {
68:                         support_phase_radius: CycleDelta::from_cycles(0.11)?,
69:                         ..run_locomotion_profile()
70:                     };
71:                     let (left, right) = gait_support_weights(contact_profile, phase)?;
72:                     Self::new(left, right)
73:                 }
74:                 _ => Self::NONE,
75:             };
76:             if sample.mirror_lower_body == ClipMirror::Mirrored {
77:                 weights = weights.mirrored();
78:             }
79:             // Vec2 owns the original component-wise multiply/add/divide kernel;
80:             // no native pair is retained in playback or passed to another API.
81:             let weight = sample.weight;
82:             let next = result
83:                 + Vec2::new(weights.left.fraction(), weights.right.fraction()) * weight.factor();
84:             if !next.is_finite() {
85:                 return Err(AnimationValueError::Overflow {
86:                     quantity: AnimationQuantity::BlendWeight,
87:                 });
88:             }
89:             total = total.checked_add(weight)?;
90:             result = next;
91:         }
92:         let normalized = if total.is_absent() {
93:             Vec2::ZERO
94:         } else {
95:             result / total.factor()
96:         };
97:         if !normalized.is_finite() {
98:             return Err(AnimationValueError::Overflow {
99:                 quantity: AnimationQuantity::BlendWeight,
100:             });
101:         }
102:         let normalized = normalized.clamp(Vec2::ZERO, Vec2::ONE);
103:         Ok(Self::new(
104:             UnitInterval::from_fraction(normalized.x)?,
105:             UnitInterval::from_fraction(normalized.y)?,
106:         ))
107:     }
108: 
109:     /// Authored contacts select one foot; pose interpolation supplies continuity.
110:     pub(super) fn combat_cycle(phase: CyclePhase) -> Self {
111:         let phase = phase.wrapped().cycles();
112:         if (catalog::COMBAT_FIRST_CONTACT_PHASE..catalog::COMBAT_SECOND_CONTACT_PHASE)
113:             .contains(&phase)
114:         {
115:             Self::LEFT
116:         } else {
117:             Self::RIGHT
118:         }
119:     }
120: 
121:     fn mirrored(self) -> Self {
122:         Self::new(self.right, self.left)
123:     }
124: }
