120: pub(crate) fn validate<K: JitterBoneIdentity>(
121:     frames: &[JitterFrame<K>],
122:     thresholds: JitterThresholds,
123: ) -> JitterValidationSummary<K> {
124:     let mut incidents = Vec::new();
125:     let mut start = 0;
126:     while start < frames.len() {
127:         let end = frames[start..]
128:             .iter()
129:             .position(|frame| {
130:                 frame.scenario != frames[start].scenario
131:                     || frame.analysis_segment != frames[start].analysis_segment
132:             })
133:             .map_or(frames.len(), |offset| start + offset);
134:         let scenario_thresholds = thresholds_for_scenario(thresholds, &frames[start].scenario);
135:         let acquisition_warmup = acquisition_warmup_frames(&frames[start].scenario);
136:         let analysis_start = if frames[start].scenario_frame < acquisition_warmup {
137:             // Acquisition can itself change contact identity and therefore
138:             // split the opening samples into multiple analysis segments. Skip
139:             // by the scenario clock so every opening segment observes the same
140:             // fixture warmup boundary.
141:             frames[start..end]
142:                 .iter()
143:                 .position(|frame| frame.scenario_frame >= acquisition_warmup)
144:                 .map_or(end, |offset| start + offset)
145:         } else if frames[start].analysis_segment == 0 {
146:             start
147:         } else {
148:             // Acceleration/jerk need samples on both sides of a contact event.
149:             // Each contact starts a fresh analysis segment, so its first
150:             // derivative window is a boundary artifact rather than a complete
151:             // steady-state measurement. Adjacent-pose continuity still judges
152:             // every frame across the handoff.
153:             (start + contact_segment_warmup_frames(&frames[start].scenario)).min(end)
154:         };
155:         analyze_scenario(
156:             &frames[analysis_start..end],
157:             &scenario_thresholds,
158:             &mut incidents,
159:         );
160:         start = end;

