196: fn acquisition_warmup_frames(scenario: &ScenarioMetadata<'_>) -> usize {
197:     if scenario.is(ScenarioId::RaisedGuardStationaryTurn)
198:         || (scenario.has(ScenarioFeature::RaisedGuard) && scenario.has(ScenarioFeature::TapStop))
199:         || (scenario.has(ScenarioFeature::RaisedGuard)
200:             && !scenario.is(ScenarioId::RaisedGuardTransition))
201:     {
202:         // The viewer starts these fixtures directly in raised guard so the
203:         // first four samples include one-time pose/IK acquisition. Judge the
204:         // repeated authored cycle, stationary pole-limit turns, and procedural
205:         // steps after that deterministic handoff. The dedicated transition
206:         // fixture retains its complete entry sequence.
207:         5
208:     } else {
209:         0
210:     }
211: }
