223: fn thresholds_for_scenario(
224:     mut thresholds: JitterThresholds,
225:     scenario: &ScenarioMetadata<'_>,
226: ) -> JitterThresholds {
227:     if scenario.is(ScenarioId::QuickstepRight) {
228:         // A ballistic dodge deliberately drives an analytic two-bone chain
229:         // through a short, high-angular-acceleration tuck. Its position and
230:         // rotation steps remain governed by the stricter continuity gates;
231:         // these derivative limits distinguish oscillation from the intended
232:         // one-shot impulse without applying ordinary gait thresholds to it.
233:         thresholds.angular_acceleration_absolute = 2_500.0;
234:         thresholds.angular_jerk_absolute = 150_000.0;
235:         // The conventional 0→3→4 quickstep timeline now remains visible even
236:         // when authoritative action packets coalesce. Its measured one-way
237:         // chest response at force release peaks at 142.03 m/s²; retain a
238:         // narrow ceiling above that impulse without weakening ordinary gait.
239:         thresholds.local_position_acceleration_absolute = 145.0;
240:         thresholds.local_position_jerk_absolute = 12_000.0;
241:     } else if scenario.is(ScenarioId::RaisedGuardStationaryTurn) {
242:         // A planted turn loads the procedural knee chain against a fixed foot
243:         // before the pole limit requests a step. That smooth one-way loading
244:         // has slightly more angular curvature than ordinary locomotion while
245:         // remaining far below the authored combat-locomotion envelope. Keep
246:         // position derivatives and every adjacent-pose continuity gate at the
247:         // ordinary limits.
248:         thresholds.angular_acceleration_absolute = 260.0;
249:         thresholds.angular_jerk_absolute = 14_000.0;
250:     } else if scenario.has(ScenarioFeature::RaisedGuard)
251:         && (scenario.has(ScenarioFeature::Release) || scenario.has(ScenarioFeature::TapStop))
252:     {
253:         // These fixtures contain both a six-frame authored tap/release and the
254:         // one-shot handoff to a procedural stance-reacquisition step. The
255:         // right tap's tucked foot has a single 27.7 krad/s^3 authored lobe;
256:         // keep its bound narrow and far below the quickstep envelope. Every
257:         // adjacent rotation/position step and ordinary position derivative
258:         // remains independently gated.
259:         thresholds.angular_acceleration_absolute = 550.0;
260:         thresholds.angular_jerk_absolute = if scenario.has(ScenarioFeature::TapStop) {
261:             28_000.0
262:         } else {
263:             26_000.0
264:         };
265:     } else if scenario.has(ScenarioFeature::RaisedGuard)
266:         && !scenario.has(ScenarioFeature::Release)
267:         && !scenario.has(ScenarioFeature::TapStop)
268:         && !matches!(
269:             scenario.identity(),
270:             Some(ScenarioId::RaisedGuardStationaryTurn) | Some(ScenarioId::RaisedGuardTransition)
271:         )
272:     {
273:         // Prepared skip/strafe curves have intentional curvature around their
274:         // authored contact keys. Their adjacent rotation steps remain under
275:         // the ordinary continuity limit; these narrowly higher derivative
276:         // bounds avoid classifying that one-way curve as oscillation.
277:         // Forward diagonal foot-order pairing reaches 505.10 deg/s² at its
278:         // authored left-knee contact key. Keep a narrow prepared-cycle bound
279:         // above that deterministic curve; ordinary locomotion is unchanged.
280:         thresholds.angular_acceleration_absolute = 510.0;
281:         thresholds.angular_jerk_absolute = 25_000.0;
282:         thresholds.local_position_acceleration_absolute = 70.0;
283:         thresholds.local_position_jerk_absolute = 4_000.0;
284:     }
285:     thresholds
286: }
