288: fn analyze_scenario<K: JitterBoneIdentity>(
289:     frames: &[JitterFrame<K>],
290:     t: &JitterThresholds,
291:     out: &mut Vec<JitterIncident<K>>,
292: ) {
293:     if frames.len() < 4 {
294:         return;
295:     }
296:     let mut names: Vec<_> = frames
297:         .iter()
298:         .flat_map(|frame| frame.bones.keys())
299:         .collect::<std::collections::BTreeSet<_>>()
300:         .into_iter()
301:         .collect();
302:     names.sort_by(|left, right| left.report_label().cmp(&right.report_label()));
303:     for name in names {
304:         let Some(samples) = frames
305:             .iter()
306:             .map(|frame| frame.bones.get(name))
307:             .collect::<Option<Vec<_>>>()
308:         else {
309:             continue;
310:         };
311:         let mut positions = Vec::with_capacity(samples.len());
312:         let mut angles = Vec::with_capacity(samples.len());
313:         for sample in samples {
314:             positions.push(Vec3::from_array(sample.position));
315:             angles.push(Quat::from_array(sample.rotation_xyzw));
316:         }
317:         let position_velocity = vector_derivative(&positions, frames);
318:         let position_accel = vector_derivative(&position_velocity, &frames[1..])
319:             .into_iter()
320:             .map(Vec3::length)
321:             .collect::<Vec<_>>();
322:         let position_jerk = derivative(&position_accel, frames);
323:         let angular_velocity = angles
324:             .windows(2)
325:             .enumerate()
326:             .map(|(index, pair)| pair[0].angle_between(pair[1]) / dt(frames, index + 1).seconds())
327:             .collect::<Vec<_>>();
328:         let angular_accel = derivative(&angular_velocity, &frames[1..]);
329:         let angular_jerk = derivative(&angular_accel, &frames[2..]);
330:         report(
331:             name,
332:             JitterClass::LocalPositionAcceleration,
333:             &position_accel,
334:             frames,
335:             JitterLimit {
336:                 absolute: t.local_position_acceleration_absolute,
337:                 relative: t.local_position_acceleration_relative,
338:                 noise_floor: t.local_position_acceleration_noise_floor,
339:             },
340:             out,
341:         );
342:         report(
343:             name,
344:             JitterClass::LocalPositionJerk,
345:             &position_jerk,
346:             frames,
347:             JitterLimit {
348:                 absolute: t.local_position_jerk_absolute,
349:                 relative: t.local_position_jerk_relative,
350:                 noise_floor: t.local_position_jerk_noise_floor,
351:             },
352:             out,
353:         );
354:         report(
355:             name,
356:             JitterClass::AngularAcceleration,
357:             &angular_accel,
358:             &frames[2..],
359:             JitterLimit {
360:                 absolute: t.angular_acceleration_absolute,

