381: fn report<K: JitterBoneIdentity>(
382:     name: &K,
383:     class: JitterClass,
384:     values: &[f32],
385:     frames: &[JitterFrame<K>],
386:     limit: JitterLimit,
387:     out: &mut Vec<JitterIncident<K>>,
388: ) {
389:     let mut baseline_values = values
390:         .iter()
391:         .copied()
392:         .filter(|value| value.is_finite())
393:         .collect::<Vec<_>>();
394:     baseline_values.sort_by(f32::total_cmp);
395:     let baseline = baseline_values
396:         .get(baseline_values.len() / 2)
397:         .copied()
398:         .unwrap_or(0.0);
399:     let threshold = limit
400:         .absolute
401:         .max(limit.relative * baseline.min(limit.absolute));
402:     for (index, value) in values.iter().copied().enumerate() {
403:         if !value.is_finite() || value <= limit.noise_floor || value <= threshold {
404:             continue;
405:         }
406:         let frame = frames.get(index).or_else(|| frames.last()).unwrap();
407:         out.push(JitterIncident {
408:             scenario: frame.scenario.clone(),
409:             bone: name.clone(),
410:             class,
411:             frame: frame.scenario_frame,
412:             window_start: frame.scenario_frame.saturating_sub(2),
413:             window_end: frame.scenario_frame + 2,
414:             value,
415:             threshold,
416:             severity: value / threshold,
417:         });
418:     }
419: }
