421: fn dt<K: JitterBoneIdentity>(frames: &[JitterFrame<K>], index: usize) -> AnimationElapsed {
422:     frames
423:         .get(index)
424:         .zip(frames.get(index.saturating_sub(1)))
425:         .map_or(MISSING_FRAME_INTERVAL, |(a, b)| {
426:             a.time_seconds
427:                 .abs_diff(b.time_seconds)
428:                 .max(MINIMUM_DERIVATIVE_INTERVAL)
429:         })
430: }
431: 
432: fn derivative<K: JitterBoneIdentity>(values: &[f32], frames: &[JitterFrame<K>]) -> Vec<f32> {
433:     values
434:         .windows(2)
435:         .enumerate()
436:         .map(|(index, pair)| (pair[1] - pair[0]).abs() / dt(frames, index + 1).seconds())
437:         .collect()
438: }
439: 
440: fn vector_derivative<K: JitterBoneIdentity>(
441:     values: &[Vec3],
442:     frames: &[JitterFrame<K>],
443: ) -> Vec<Vec3> {
444:     values
445:         .windows(2)
446:         .enumerate()
447:         .map(|(index, pair)| (pair[1] - pair[0]) / dt(frames, index + 1).seconds())
448:         .collect()
449: }
