60:             .or_insert_with(|| asset_server.load(animation_asset_path(&grip.path())));
61:     }
62:     for (pack_id, pack) in &catalog.packs {
63:         for (motion_id, source) in &pack.motions {
64:             // Strategic portraits and street characters stand in relaxed idle.
65:             // Combat and locomotion clips join the persistent asset cache when
66:             // the player enters tactical play.
67:             #[cfg(target_family = "wasm")]
68:             if *mode == crate::browser_runtime::BrowserMode::Strategic
69:                 && !pack
70:                     .poses
71:                     .get(&SemanticPose::IdleRelaxed)
72:                     .is_some_and(|anchor| anchor.motion == *motion_id)
73:             {
74:                 continue;
75:             }
76:             runtime
77:                 .requested_motions
78:                 .entry(MotionKey::new(pack_id, motion_id))
79:                 .or_insert_with(|| MotionLoad::request(&asset_server, &source.path));
80:         }
81:     }
82:     if let Err(error) = runtime.library.validate_structure() {
83:         error!(
84:             ?error,
85:             "Rejected structurally invalid animation pack library"
86:         );
87:     }
88: }
