90: pub(super) fn collect_loaded_packs(
91:     catalog: Res<AnimationPackCatalog>,
92:     asset_server: Res<AssetServer>,
93:     gltfs: Res<Assets<Gltf>>,
94:     clips: Res<Assets<AnimationClip>>,
95:     mut runtime: ResMut<AnimationRuntime>,
96: ) {
97:     let mut changed = false;
98:     if let BaseRigLoad::Loading { source } = &runtime.base_rig {
99:         let source = source.clone();
100:         if matches!(asset_server.load_state(source.id()), LoadState::Failed(_)) {
101:             runtime.base_rig = BaseRigLoad::Failed { source };
102:             warn!(path = %BIPED_BASE_GLB, "Authored base rig is unavailable");
103:         } else if let Some(gltf) = gltfs.get(&source) {
104:             if let Some(scene) = gltf
105:                 .default_scene
106:                 .clone()
107:                 .or_else(|| gltf.scenes.first().cloned())
108:             {
109:                 runtime.base_rig = BaseRigLoad::Ready { source, scene };
110:             } else {
111:                 runtime.base_rig = BaseRigLoad::Failed { source };
112:                 warn!(path = %BIPED_BASE_GLB, "Authored base rig has no scene");
113:             }
114:         }
115:     }
116: 
117:     let requested = runtime
118:         .requested_motions
119:         .iter_mut()
120:         .filter_map(|(key, load)| load.poll(&asset_server).map(|handle| (key.clone(), handle)))
121:         .collect::<Vec<_>>();
122:     for (key, handle) in requested {
123:         if runtime.clips.contains_key(&key) || runtime.unavailable_motions.contains(&key) {
124:             continue;
125:         }
126:         let Some(handle) = handle else {
127:             runtime.unavailable_motions.insert(key.clone());
128:             changed = true;
129:             continue;
130:         };
131:         let Some(gltf) = gltfs.get(&handle) else {
132:             continue;
133:         };
134:         let source = catalog
135:             .packs
136:             .get(&key.pack)
137:             .and_then(|pack| pack.motions.get(&key.motion));
138:         match motion::MotionClipAdmission::admit(
139:             &key,
140:             source,
141:             gltf,
142:             &asset_server,
143:             &clips,
144:             &runtime.canonical_targets,
145:         ) {
146:             motion::MotionClipAdmission::Pending => continue,
147:             motion::MotionClipAdmission::Unavailable => {
148:                 runtime.unavailable_motions.insert(key);
149:             }
150:             motion::MotionClipAdmission::Ready(clip) => {
151:                 runtime.clips.insert(key, clip);
152:             }
153:         }
154:         changed = true;
155:     }
156: 
157:     if !changed {
158:         collect_loaded_grips(&asset_server, &gltfs, &clips, &mut runtime);
159:         return;
160:     }
161:     runtime.rebuild_loaded_library(&catalog);
162:     collect_loaded_grips(&asset_server, &gltfs, &clips, &mut runtime);
163: }
