227: /// Recreate the loader's stable name-path target IDs so independently exported
228: /// motion files can animate the canonical `Skeleton` hierarchy.
229: pub(super) fn establish_animation_targets(
230:     mut commands: Commands,
231:     mut runtime: ResMut<AnimationRuntime>,
232:     roots: Query<(Entity, &AnimationRigScene), Without<RigAnimationTargetsBound>>,
233:     children: Query<&Children>,
234:     names: Query<&Name>,
