277: pub(super) fn bind_animation_target_paths(
278:     commands: &mut Commands,
279:     entity: Entity,
280:     mut path: Vec<Name>,
281:     children: &Query<&Children>,
282:     names: &Query<&Name>,
283:     runtime: &mut AnimationRuntime,
284: ) {
285:     let Ok(name) = names.get(entity) else {
286:         return;
287:     };
288:     path.push(name.clone());
289:     let target = AnimationTargetId::from_names(path.iter());
290:     runtime.canonical_targets.insert(target);
291:     // `Name` is the native scene boundary; downstream rig consumers retain
292:     // this admitted identity and its cached animation classification.
293:     commands
294:         .entity(entity)
295:         .insert((target, AuthoredRigJoint::new(name.as_str().into())));
296:     if let Ok(entity_children) = children.get(entity) {
297:         for child in entity_children.iter() {
298:             bind_animation_target_paths(commands, child, path.clone(), children, names, runtime);
299:         }
300:     }
301: }
