303: fn collect_loaded_grips(
304:     asset_server: &AssetServer,
305:     gltfs: &Assets<Gltf>,
306:     clips: &Assets<AnimationClip>,
307:     runtime: &mut AnimationRuntime,
308: ) {
309:     let requested = runtime
310:         .requested_grips
311:         .iter()
312:         .map(|(&grip, handle)| (grip, handle.clone()))
313:         .collect::<Vec<_>>();
314:     for (grip, handle) in requested {
315:         if runtime.processed_grips.contains(&grip) || runtime.unavailable_grips.contains(&grip) {
316:             continue;
317:         }
318:         match asset_server.load_state(handle.id()) {
319:             LoadState::Failed(_) => {
320:                 runtime.unavailable_grips.insert(grip);
321:                 warn!(path = %grip.path(), "Authored weapon grip is unavailable");
322:                 continue;
323:             }
324:             LoadState::NotLoaded | LoadState::Loading => continue,
325:             LoadState::Loaded => {}
326:         }
327:         let Some(gltf) = gltfs.get(&handle) else {
328:             continue;
329:         };
330:         let Some(clip_handle) = sole_animation(&gltf.animations) else {
331:             warn!(
332:                 path = %grip.path(),
333:                 count = gltf.animations.len(),
334:                 "Weapon grip must contain exactly one animation"
335:             );
336:             runtime.unavailable_grips.insert(grip);
337:             continue;
338:         };
339:         match asset_server.load_state(clip_handle.id()) {
340:             LoadState::Failed(_) => {
341:                 runtime.unavailable_grips.insert(grip);
342:                 continue;
343:             }
344:             LoadState::NotLoaded | LoadState::Loading => continue,
345:             LoadState::Loaded => {}
346:         }
347:         let Some(clip) = clips.get(clip_handle) else {
348:             continue;
349:         };
350:         if runtime.canonical_targets.is_empty() {
351:             continue;
352:         }
353:         if !clip_targets_match_base(clip, &runtime.canonical_targets) {
354:             warn!(
355:                 path = %grip.path(),
356:                 "Weapon grip targets are incompatible with the base rig"
357:             );
358:             runtime.unavailable_grips.insert(grip);
359:             continue;
360:         }
361:         let duration_seconds = match ClipDuration::from_seconds(clip.duration()) {
362:             Ok(duration) => duration,
363:             Err(error) => {
364:                 warn!(%error, path = %grip.path(), "Rejected grip duration");
365:                 runtime.unavailable_grips.insert(grip);
366:                 continue;
367:             }
368:         };
369:         runtime.grips.insert(
370:             grip,
371:             LoadedClip {
372:                 handle: clip_handle.clone(),
373:                 duration_seconds,
374:                 layer: ClipLayer::MainHand,
375:             },
376:         );
377:         runtime.processed_grips.insert(grip);
378:     }
379: }
