13: /// Optional motions own their load diagnostics so expected gaps do not emit
14: /// Bevy's unconditional asset-load errors before pose fallback can run.
15: pub(crate) struct MotionLoad {
16:     path: AnimationAssetPath,
17:     state: MotionLoadState,
18: }
19: 
20: pub(super) enum MotionClipAdmission {
21:     Pending,
22:     Unavailable,
23:     Ready(LoadedClip),
24: }
25: 
26: enum MotionLoadState {
27:     Pending(Task<Option<Handle<Gltf>>>),
28:     Ready(Option<Handle<Gltf>>),
29: }
30: 
31: impl MotionLoad {
32:     pub(super) fn request(asset_server: &AssetServer, path: &AnimationAssetPath) -> Self {
33:         let requested = path.clone();
34:         let path = animation_asset_path(path);
35:         let asset_server = asset_server.clone();
36:         let task = IoTaskPool::get().spawn(async move {
37:             match asset_server.load_builder().load_untyped_async(&path).await {
38:                 Ok(handle) => match handle.try_typed::<Gltf>() {
39:                     Ok(handle) => Some(handle),
40:                     Err(error) => {
41:                         error!(path = %path, %error, "Animation motion has the wrong asset type");
42:                         None
43:                     }
44:                 },
45:                 Err(AssetLoadError::AssetReaderError(AssetReaderError::NotFound(_))) => {
46:                     info!(
47:                         path = %path,
48:                         "Animation motion is absent; using available pose fallbacks"
49:                     );
50:                     None
51:                 }
52:                 Err(error) => {
53:                     error!(path = %path, %error, "Animation motion failed to load");
54:                     None
55:                 }
56:             }
57:         });
58:         Self {
59:             path: requested,
60:             state: MotionLoadState::Pending(task),
61:         }
62:     }
63: 
64:     /// Retain the source handle even while its current load state is failed.
65:     pub(in crate::animation) fn source(&self) -> Option<&Handle<Gltf>> {
66:         match &self.state {
67:             MotionLoadState::Ready(handle) => handle.as_ref(),
68:             MotionLoadState::Pending(_) => None,
69:         }
70:     }
71: 
72:     /// The outer option is pending; the inner option is motion availability.
73:     pub(super) fn poll(&mut self, asset_server: &AssetServer) -> Option<Option<Handle<Gltf>>> {
74:         if let MotionLoadState::Pending(task) = &mut self.state {
75:             self.state = MotionLoadState::Ready(future::block_on(future::poll_once(task))?);
76:         }
77:         match &self.state {
78:             MotionLoadState::Ready(Some(handle)) => match asset_server.load_state(handle.id()) {
79:                 LoadState::Loaded => Some(Some(handle.clone())),
80:                 LoadState::Failed(_) => Some(None),
81:                 LoadState::NotLoaded | LoadState::Loading => None,
82:             },
83:             MotionLoadState::Ready(None) => Some(None),
84:             MotionLoadState::Pending(_) => None,
85:         }
86:     }
87: 
88:     /// Associate revisions by the actual source/path/label even when the first
89:     /// request failed before Bevy could return a typed handle. The AssetServer
90:     /// remains the handle authority; observing a revision does not issue a retry.
91:     pub(in crate::animation) fn observe_source_revision(
92:         &mut self,
93:         asset_server: &AssetServer,
94:         id: bevy::asset::AssetId<Gltf>,
95:     ) -> bool {
96:         let requested = animation_asset_path(&self.path);
97:         if !self.source().is_some_and(|source| source.id() == id)
98:             && !asset_server
99:                 .get_path(id)
100:                 .is_some_and(|path| path == requested)
101:         {
102:             return false;
103:         }
104:         if let Some(source) = asset_server.get_handle::<Gltf>(requested) {
105:             self.state = MotionLoadState::Ready(Some(source));
106:         }
107:         true
108:     }
109: }
