111: impl MotionClipAdmission {
112:     /// Admit the complete single-motion clip before publishing any availability.
113:     pub(super) fn admit(
114:         key: &MotionKey,
115:         source: Option<&MotionSource>,
116:         gltf: &Gltf,
117:         asset_server: &AssetServer,
118:         clips: &Assets<AnimationClip>,
119:         canonical_targets: &HashSet<AnimationTargetId>,
120:     ) -> MotionClipAdmission {
121:         let Some(clip_handle) = sole_animation(&gltf.animations) else {
122:             warn!(
123:                 pack = %key.pack,
124:                 motion = %key.motion,
125:                 count = gltf.animations.len(),
126:                 "Motion must contain exactly one animation"
127:             );
128:             return MotionClipAdmission::Unavailable;
129:         };
130:         match asset_server.load_state(clip_handle.id()) {
131:             LoadState::Failed(_) => return MotionClipAdmission::Unavailable,
132:             LoadState::NotLoaded | LoadState::Loading => return MotionClipAdmission::Pending,
133:             LoadState::Loaded => {}
134:         }
135:         let Some(clip) = clips.get(clip_handle) else {
136:             return MotionClipAdmission::Pending;
137:         };
138:         if canonical_targets.is_empty() {
139:             return MotionClipAdmission::Pending;
140:         }
141:         if !clip_targets_match_base(clip, canonical_targets) {
142:             warn!(
143:                 pack = %key.pack,
144:                 motion = %key.motion,
145:                 "Motion targets are incompatible with the base rig"
146:             );
147:             return MotionClipAdmission::Unavailable;
148:         }
149:         let Some(source) = source else {
150:             return MotionClipAdmission::Unavailable;
151:         };
152:         let duration_seconds = match ClipDuration::from_seconds(clip.duration()) {
153:             Ok(duration) => duration,
154:             Err(error) => {
155:                 warn!(%error, motion = %key.motion, "Rejected animation duration");
156:                 return MotionClipAdmission::Unavailable;
157:             }
158:         };
159:         if !frame_fits_clip(source.required_last_frame, duration_seconds) {
160:             warn!(
161:                 pack = %key.pack,
162:                 motion = %key.motion,
163:                 last_frame = u16::from(source.required_last_frame),
164:                 duration = clip.duration(),
165:                 "Motion is shorter than its catalog frames"
166:             );
167:             return MotionClipAdmission::Unavailable;
168:         }
169:         MotionClipAdmission::Ready(LoadedClip {
170:             handle: clip_handle.clone(),
171:             duration_seconds,
172:             layer: ClipLayer::Whole,
173:         })
174:     }
175: }
