5: #[derive(Debug, Default, Clone)]
6: pub(super) struct PlaybackContributions {
7:     clips: Vec<WeightedClip>,
8:     extrapolated: Vec<ExtrapolatedSpan>,
9:     continuations: Vec<ContinuationSpan>,
10: }
11: 
12: impl PlaybackContributions {
13:     pub(super) fn admit(
14:         clips: Vec<WeightedClip>,
15:         extrapolated: Vec<ExtrapolatedSpan>,
16:         continuations: Vec<ContinuationSpan>,
17:     ) -> AnimationValueResult<Self> {
18:         // Grip endpoints join before admission. Zero weights retain their declared topology.
19:         clips
20:             .iter()
21:             .map(|clip| clip.weight)
22:             .chain(extrapolated.iter().map(|span| span.weight))
23:             .chain(continuations.iter().map(|span| span.weight))
24:             .try_fold(BlendWeight::ZERO, |total, weight| total.checked_add(weight))?;
25:         Ok(Self {
26:             clips,
27:             extrapolated,
28:             continuations,
29:         })
30:     }
31:     pub(super) fn is_bind(&self) -> bool {
32:         self.clips.is_empty() && self.extrapolated.is_empty() && self.continuations.is_empty()
33:     }
34:     pub(super) fn clips(&self) -> &[WeightedClip] {
35:         &self.clips
36:     }
37:     pub(super) fn extrapolated(&self) -> &[ExtrapolatedSpan] {
38:         &self.extrapolated
39:     }
40:     pub(super) fn continuations(&self) -> &[ContinuationSpan] {
41:         &self.continuations
42:     }
43: }

