281: fn evaluate_skeletons(
282:     mut commands: Commands,
283:     catalog: Res<AnimationPackCatalog>,
284:     runtime: Res<AnimationRuntime>,
285:     locomotion_strides: pose_buffer::CalibrationLookup,
286:     players: Query<
287:         (
288:             Entity,
289:             &PresentedSkeleton,
290:             &semantic_route::SemanticRouteTrace,
291:             Option<&InventoryItems>,
292:             Option<&mut AnimationPlayback>,
293:         ),
294:         AnimatedActors,
295:     >,
296:     weapons: Query<(&WeaponItem, &ItemProperties)>,
297:     equip_slots: Query<&EquipSlot>,
298: ) {
299:     'actor: for (entity, skeleton, route_trace, inventory, playback) in players {
300:         // The preceding chained system directly routes authoritative
301:         // presentation state into deterministic semantic samples.
302:         let evaluation = route_trace.evaluation.clone();
303:         let samples = if evaluation.action.is_empty() {
304:             &evaluation.base
305:         } else {
306:             &evaluation.action
307:         };
308:         let sample_resolver = PoseSampleResolver {
309:             runtime: &runtime,
310:             catalog: &catalog,
311:             pack: &route_trace.inputs.pack,
312:             locomotion_strides: locomotion_strides.for_actor(entity),
313:         };
314:         let mut target = match sample_resolver.resolve_body(skeleton, &evaluation) {
315:             Ok(target) => target,
316:             Err(error) => {
317:                 error!(?entity, %error, "Rejected animation sample plan");
318:                 continue;
319:             }
320:         };
321:         if let Some((weapon, properties)) = equipped_main_weapon(inventory, &weapons, &equip_slots)
322:             && let Some(clip) = runtime.grips.get(&weapon_grip(&weapon.skill_weights))
323:         {
324:             let uses_offhand =
325:                 weapon_uses_offhand(&properties.id, offhand_is_empty(inventory, &equip_slots));
326:             let authored_pose_owns_hands = authored_pose_owns_hands(samples);
327:             for layer in weapon_grip_layers(authored_pose_owns_hands, uses_offhand)
328:                 .into_iter()
329:                 .flatten()
330:             {
331:                 if let Err(error) = append_weighted_clip(
332:                     &mut target.clips,
333:                     &clip.at_anchor_layer(AuthoredAnimationFrame::ZERO, layer),
334:                     ClipMirror::Original,
335:                     ClipTime::ZERO,
336:                     BlendWeight::ONE,
337:                     None,
338:                 ) {
339:                     error!(?entity, %error, "Rejected weapon grip contribution");
340:                     continue 'actor;
341:                 }
342:             }
343:         }
344:         let target = match target.into_playback(&evaluation) {
345:             Ok(target) => target,
346:             Err(error) => {
347:                 error!(?entity, %error, "Rejected animation IK contributions");
348:                 continue;
349:             }
350:         };
351:         if let Some(mut playback) = playback {
352:             playback.apply_presented_pose(skeleton, target, evaluation.movement_speed);
353:         } else {
354:             commands
355:                 .entity(entity)
356:                 .insert(AnimationPlayback::from_presented_pose(
357:                     skeleton,
358:                     target,
359:                     evaluation.movement_speed,
360:                 ));
361:         }
362:     }
363: }
