492: fn resolve_anchor<'a>(
493:     runtime: &'a AnimationRuntime,
494:     catalog: &'a AnimationPackCatalog,
495:     requested_pack: &AnimationPackId,
496:     pose: SemanticPose,
497: ) -> Option<ResolvedAnchor<'a>> {
498:     let ordinary = resolve_library_anchor(runtime, catalog, requested_pack, pose);
499:     if ordinary
500:         .as_ref()
501:         .is_some_and(|resolved| resolved.semantic == pose)
502:     {
503:         return ordinary;
504:     }
505: 
506:     // A directional quickstep may omit its opposite file. In that case its
507:     // takeoff resolves to the authored opposite contact and its contact to the
508:     // opposite takeoff, which samples that one clip backward. Exact authored
509:     // direction clips always win above.
510:     if let Some(reversed_pose) = reversed_quickstep_pose(pose)
511:         && let Some(reversed) =
512:             resolve_library_anchor(runtime, catalog, requested_pack, reversed_pose)
513:         && reversed.semantic == reversed_pose
514:     {
515:         return Some(ResolvedAnchor {
516:             timeline_direction: TimelineDirection::Reversed,
517:             ..reversed
518:         });
519:     }
520: 
521:     ordinary
522: }
