524: fn resolve_library_anchor<'a>(
525:     runtime: &'a AnimationRuntime,
526:     catalog: &'a AnimationPackCatalog,
527:     requested_pack: &AnimationPackId,
528:     pose: SemanticPose,
529: ) -> Option<ResolvedAnchor<'a>> {
530:     let ResolvedPose::Clip {
531:         pack_id,
532:         pose: resolved_pose,
533:         mirrored,
534:         ..
535:     } = runtime.library.resolve(requested_pack, pose)
536:     else {
537:         return None;
538:     };
539:     let pack = catalog.packs.get(pack_id)?;
540:     let anchor = pack.poses.get(&resolved_pose)?;
541:     pack.motions.get(&anchor.motion)?;
542:     let clip = runtime
543:         .clips
544:         .get(&MotionKey::new(pack_id, &anchor.motion))?;
545:     Some(ResolvedAnchor {
546:         clip,
547:         anchor,
548:         pack_id,
549:         semantic: resolved_pose,
550:         mirrored,
551:         timeline_direction: TimelineDirection::Forward,
552:     })
553: }
554: 
555: fn reversed_quickstep_pose(pose: SemanticPose) -> Option<SemanticPose> {
556:     use SemanticPose::*;
557:     Some(match pose {
558:         QuickstepForwardTakeoff => QuickstepBackTakeoff,
559:         QuickstepForwardContact => QuickstepBackContact,
560:         QuickstepBackTakeoff => QuickstepForwardTakeoff,
561:         QuickstepBackContact => QuickstepForwardContact,
562:         QuickstepRightTakeoff => QuickstepLeftTakeoff,
563:         QuickstepRightContact => QuickstepLeftContact,
564:         QuickstepLeftTakeoff => QuickstepRightTakeoff,
565:         QuickstepLeftContact => QuickstepRightContact,
566:         _ => return None,
567:     })
568: }
