570: fn select_gait_endpoint_parity<'a>(
571:     runtime: &'a AnimationRuntime,
572:     resolved: ResolvedAnchor<'a>,
573:     mirrored: ClipMirror,
574: ) -> Option<ResolvedAnchor<'a>> {
575:     if mirrored == ClipMirror::Original {
576:         return Some(resolved);
577:     }
578:     let motion = resolved.anchor.motion.mirrored();
579:     let clip = runtime
580:         .clips
581:         .get(&MotionKey::new(resolved.pack_id, &motion))?;
582:     Some(ResolvedAnchor { clip, ..resolved })
