209: impl LocalPose {
210:     fn from_transform(transform: Transform) -> Self {
211:         Self {
212:             translation: transform.translation,
213:             rotation: transform.rotation,
214:             scale: transform.scale,
215:         }
216:     }
217: 
218:     fn interpolate(self, next: Self, alpha: UnitInterval) -> Self {
219:         let alpha = alpha.fraction().clamp(0.0, 1.0);
220:         Self {
221:             translation: self.translation.lerp(next.translation, alpha),
222:             rotation: hemisphere_slerp(self.rotation, next.rotation, alpha),
223:             scale: self.scale.lerp(next.scale, alpha),
224:         }
225:     }
226: 
227:     fn extrapolate(self, next: Self, coordinate: AttackPoseCoordinate) -> Self {
228:         let coordinate = coordinate.clamped_to_curve().coordinate();
229:         self.extrapolate_unbounded(next, coordinate)
230:     }
231: 
232:     fn extrapolate_unbounded(self, next: Self, coordinate: f32) -> Self {
233:         let relative = shortest_rotation(next.rotation * self.rotation.inverse());
234:         Self {
235:             translation: self.translation + (next.translation - self.translation) * coordinate,
236:             rotation: (quaternion_exp(quaternion_log(relative) * coordinate) * self.rotation)
237:                 .normalize(),
238:             scale: self.scale + (next.scale - self.scale) * coordinate,
239:         }
240:     }

