242:     fn continuation_transition(
243:         self,
244:         transition: ContinuationTransition,
245:         progress: UnitInterval,
246:     ) -> Self {
247:         let start = self.extrapolate(transition.contact, transition.start_coordinate);
248:         // The complete native spline consumes phase knots, normalized progress
249:         // and an attack-coordinate derivative; checked roles end at this kernel.
250:         let progress = progress.fraction().clamp(0.0, 1.0);
251:         let ready_phase = transition.ready_phase.phase();
252:         let knots = [0.0, ready_phase, 0.5, 1.0];
253:         let incoming_scale = transition.incoming_tangent.coordinate_delta() / ready_phase;
254:         let rotation_values = [
255:             Vec3::ZERO,
256:             quaternion_log(shortest_rotation(
257:                 transition.ready.rotation * start.rotation.inverse(),
258:             )),
259:             quaternion_log(shortest_rotation(
260:                 transition.outgoing.rotation * start.rotation.inverse(),
261:             )),
262:             quaternion_log(shortest_rotation(
263:                 transition.finish.rotation * start.rotation.inverse(),
264:             )),
265:         ];
266:         Self {
267:             translation: clamped_cubic_spline_vec3(
268:                 knots,
269:                 [
270:                     start.translation,
271:                     transition.ready.translation,
272:                     transition.outgoing.translation,
273:                     transition.finish.translation,
274:                 ],
275:                 (transition.contact.translation - self.translation) * incoming_scale,
276:                 Vec3::ZERO,
277:                 progress,
278:             ),
279:             rotation: (quaternion_exp(clamped_cubic_spline_vec3(
280:                 knots,
281:                 rotation_values,
282:                 quaternion_log(shortest_rotation(
283:                     transition.contact.rotation * self.rotation.inverse(),
284:                 )) * incoming_scale,
285:                 Vec3::ZERO,
286:                 progress,
287:             )) * start.rotation)
288:                 .normalize(),
289:             scale: clamped_cubic_spline_vec3(
290:                 knots,
291:                 [
292:                     start.scale,
293:                     transition.ready.scale,
294:                     transition.outgoing.scale,
295:                     transition.finish.scale,
296:                 ],
297:                 (transition.contact.scale - self.scale) * incoming_scale,
298:                 Vec3::ZERO,
299:                 progress,
300:             ),
301:         }
302:     }
