312:             .collect::<Vec<_>>();
313:         clips.extend(playback.plan.extrapolated().iter().flat_map(|span| {
314:             [
315:                 (span.start.handle.id(), span.start.layer),
316:                 (span.end.handle.id(), span.end.layer),
