322:                 (span.contact.handle.id(), span.contact.layer),
323:                 (span.end.handle.id(), span.end.layer),
324:                 (span.outgoing.handle.id(), span.outgoing.layer),
325:                 (span.finish.handle.id(), span.finish.layer),
326:             ]
