594: pub(super) fn apply_pose_buffers(
595:     mut rigs: Query<&mut PoseBufferRig>,
596:     mut transforms: Query<&mut Transform, Without<PoseBufferRig>>,
597: ) {
598:     let _spike = crate::animation::diagnostics::SpikeGuard::new("apply_pose_buffers");
599:     for mut rig in &mut rigs {
600:         if !rig.has_presented_pose() || rig.visibility == PoseVisibility::Frozen {
601:             continue;
602:         }
603:         let alpha = rig.interpolation_alpha.amount();
604:         let delta_seconds = rig.decay_delta_seconds;
605:         let rig = &mut *rig;
606:         for joint in rig.entities.ordinals() {
607:             let Some(entity) = rig.entities[joint] else {
608:                 continue;
609:             };
610:             let input = rig.previous[joint].interpolate(rig.next[joint], alpha);
611:             let pose = if rig.inertial_state == InertialState::Settled {
612:                 input
613:             } else if !delta_seconds.is_zero() {
614:                 match rig.offsets[joint].update(input, delta_seconds) {
615:                     Ok(pose) => pose,
616:                     Err(error) => {
617:                         warn!(%error, "Rejected pose inertialization clock");
618:                         continue;
619:                     }
620:                 }
621:             } else {
622:                 rig.offsets[joint].peek(input)
623:             };
624:             if let Ok(mut transform) = transforms.get_mut(entity) {
625:                 transform.translation = pose.translation;
626:                 transform.rotation = pose.rotation;
627:                 transform.scale = pose.scale;
628:             }
629:         }
630:         // Once every quintic has run its full length the offsets are exactly
631:         // zero; clear them so at-rest rigs skip the decay entirely.
632:         if rig.inertial_state != InertialState::Settled
633:             && rig.offsets.iter().all(JointInertialOffset::done)
634:         {
635:             rig.inertial_state = InertialState::Settled;
636:             rig.offsets.fill(JointInertialOffset::default());
637:         }
638:     }
639: }
