1: //! Source-clip admission, fixed-rate bake grids and cached sampling.
2: 
3: use super::*;
4: use adventuresim_tactical_core::animation::{AnimationQuantity, PositiveAnimationDuration};
5: use std::num::NonZeroUsize;
6: 
7: #[derive(Clone)]
8: pub(super) struct BakedClip {
9:     pub(super) duration: ClipDuration,
10:     frame_dt: PositiveAnimationDuration,
11:     frames: BakedFrameCount,
12:     tracks: RigJointTable<BoneTrack>,
13: }
14: 
15: /// Stored samples, including the endpoint: 64 intervals require 65 samples.
16: /// A one-sample clip is valid and has no interpolation interval.
17: #[derive(Clone, Copy)]
18: pub(super) struct BakedFrameCount(NonZeroUsize);
19: 
20: #[derive(Clone)]
21: pub(super) struct BoneTrack {
22:     pub(super) translations: Vec<Vec3>,
23:     pub(super) rotations: Vec<Quat>,
24:     pub(super) scales: Vec<Vec3>,
25:     pub(super) source: BoneTrackSource,
26: }
27: 
28: /// Whether the source clip owns this joint or sampling retained its bind transform.
29: #[derive(Clone, Copy, PartialEq, Eq)]
30: pub(super) enum BoneTrackSource {
31:     Authored,
32:     BindPose,
33: }
34: 
35: impl TryFrom<usize> for BakedFrameCount {
36:     type Error = AnimationValueError;
37: 
38:     fn try_from(samples: usize) -> AnimationValueResult<Self> {
39:         NonZeroUsize::new(samples)
40:             .map(Self)
41:             .ok_or(AnimationValueError::NonPositive {
42:                 quantity: AnimationQuantity::BakedFrameCount,
43:             })
44:     }
45: }
46: 
47: impl BakedFrameCount {
48:     /// Native grid cardinality for allocation, indexing and calibration kernels.
49:     pub(super) fn samples(self) -> usize {
50:         self.0.get()
51:     }
52: 
53:     pub(super) fn intervals(self) -> usize {
54:         self.0.get() - 1
55:     }
56: }
57: 
58: impl BakedClip {
59:     /// Admit the complete grid before sampling can index any channel. Private
60:     /// storage and slice-only translation edits preserve these channel lengths.
61:     pub(super) fn new(
62:         duration: ClipDuration,
63:         frame_dt: PositiveAnimationDuration,
64:         frames: BakedFrameCount,
65:         tracks: RigJointTable<BoneTrack>,
66:     ) -> AnimationValueResult<Self> {
67:         for track in &tracks {
68:             for actual in [
69:                 track.translations.len(),
70:                 track.rotations.len(),
71:                 track.scales.len(),
72:             ] {
73:                 if actual != frames.samples() {
74:                     return Err(AnimationValueError::BakedChannelSampleCount {
75:                         expected: frames.samples(),
76:                         actual,
77:                     });
78:                 }
79:             }
80:         }
81:         Ok(Self {
82:             duration,
83:             frame_dt,
84:             frames,
85:             tracks,
86:         })
87:     }
88: 
89:     pub(super) fn frame_count(&self) -> BakedFrameCount {
90:         self.frames
91:     }
92: 
93:     pub(super) fn track_source(&self, joint: RigJointOrdinal) -> BoneTrackSource {
94:         self.tracks[joint].source
95:     }
96: 
97:     pub(super) fn translations_mut(&mut self, joint: RigJointOrdinal) -> &mut [Vec3] {
98:         &mut self.tracks[joint].translations
99:     }
100: 
101:     pub(super) fn offset_translations(&mut self, offsets: &[Vec3]) {
102:         for (joint, offset) in self.tracks.ordinals().zip(offsets) {
103:             for translation in self.translations_mut(joint) {
104:                 *translation += *offset;
105:             }
106:         }
107:     }
108: 
109:     /// One joint's local transform in the pose buffer.
110:     pub(super) fn sample(&self, joint: RigJointOrdinal, time_seconds: ClipTime) -> LocalPose {
111:         // Only this interpolation kernel projects seconds to a native grid index.
112:         let frame = if self.frames.samples() == 1 {
113:             0.0
114:         } else {
115:             (time_seconds.seconds().clamp(0.0, self.duration.seconds()) / self.frame_dt.seconds())
116:                 .min(self.frames.intervals() as f32)
117:         };
118:         // A large interval count can round upward when projected to f32;
119:         // indexing still ends at the last admitted channel sample.
120:         let first = (frame as usize).min(self.frames.intervals());
121:         let second = (first + 1).min(self.frames.intervals());
122:         let alpha = frame.fract();
123:         let track = &self.tracks[joint];
124:         LocalPose {
125:             translation: track.translations[first].lerp(track.translations[second], alpha),
126:             rotation: hemisphere_slerp(track.rotations[first], track.rotations[second], alpha),
127:             scale: track.scales[first].lerp(track.scales[second], alpha),
128:         }
129:     }
130: 
131:     pub(super) fn frame_time(&self, frame: usize) -> AnimationValueResult<ClipTime> {
132:         // A bake-grid ordinal becomes a source seconds coordinate here.
133:         ClipTime::from_seconds(frame as f32 * self.frame_dt.seconds())
134:     }
