136:     fn memory_bytes(&self) -> usize {
137:         self.tracks
138:             .iter()
139:             .map(|track| {
140:                 track.translations.len() * size_of::<Vec3>()
141:                     + track.rotations.len() * size_of::<Quat>()
142:                     + track.scales.len() * size_of::<Vec3>()
143:             })
144:             .sum()
145:     }
