148: pub(super) fn get_or_bake(
149:     id: AssetId<AnimationClip>,
150:     handle: &Handle<AnimationClip>,
151:     definition: &RigDefinition,
152:     clips: &Assets<AnimationClip>,
153:     bank: &mut BakedClipBank,
154:     metrics: &mut PoseBufferMetrics,
155: ) -> Option<Arc<BakedClip>> {
156:     let key = (definition.family.clone(), id);
157:     if let Some(clip) = bank.0.get(&key) {
158:         return Some(clip.clone());
159:     }
160:     let clip = clips.get(handle)?;
161:     let baked = match bake_clip(clip, definition) {
162:         Ok(baked) => Arc::new(baked),
163:         Err(error) => {
164:             warn!(%error, ?id, "Rejected animation bake grid");
165:             return None;
166:         }
167:     };
168:     metrics.baked_clip_bytes = metrics
169:         .baked_clip_bytes
170:         .saturating_add(baked.memory_bytes());
171:     metrics.baked_clip_count = metrics.baked_clip_count.saturating_add(1);
172:     bank.0.insert(key, baked.clone());
173:     Some(baked)
174: }
175: 
176: pub(super) fn bake_clip(
177:     clip: &AnimationClip,
178:     definition: &RigDefinition,
179: ) -> AnimationValueResult<BakedClip> {
180:     let source_duration = ClipDuration::from_seconds(clip.duration())?;
181:     // Preserve the existing minimum sampling-grid extent, after source admission.
182:     let duration = ClipDuration::from_seconds(
183:         source_duration
184:             .seconds()
185:             .max(pose_tuning().minimum_baked_grid_seconds.seconds()),
186:     )?;
187:     let frame_dt = pose_sample_interval();
188:     let grid_span = duration.seconds() / frame_dt.seconds();
189:     if !grid_span.is_finite() || grid_span.ceil() >= usize::MAX as f32 {
190:         return Err(AnimationValueError::Overflow {
191:             quantity: adventuresim_tactical_core::animation::AnimationQuantity::ClipTime,
192:         });
193:     }
194:     let frames = BakedFrameCount::try_from(grid_span.ceil() as usize + 1)?;
195:     if !(frames.intervals() as f32 * frame_dt.seconds()).is_finite() {
196:         return Err(AnimationValueError::Overflow {
197:             quantity: adventuresim_tactical_core::animation::AnimationQuantity::ClipTime,
198:         });
199:     }
200:     let translation_field = animated_field!(Transform::translation);
201:     let rotation_field = animated_field!(Transform::rotation);
202:     let scale_field = animated_field!(Transform::scale);
203:     let tracks: RigJointTable<BoneTrack> = definition
204:         .joints
205:         .iter()
206:         .map(|joint| {
207:             let sample_time =
208:                 |frame: usize| (frame as f32 * frame_dt.seconds()).min(duration.seconds());
209:             let translations = (0..frames.samples())
210:                 .map(|frame| {
211:                     clip.sample_clamped(translation_field.clone(), joint.target, sample_time(frame))
212:                         .unwrap_or(joint.bind.translation)
213:                 })
214:                 .collect::<Vec<_>>();
215:             let rotations = (0..frames.samples())
216:                 .map(|frame| {
217:                     clip.sample_clamped(rotation_field.clone(), joint.target, sample_time(frame))
218:                         .unwrap_or(joint.bind.rotation)
219:                 })
220:                 .collect::<Vec<_>>();
221:             let scales = (0..frames.samples())
222:                 .map(|frame| {
223:                     clip.sample_clamped(scale_field.clone(), joint.target, sample_time(frame))
224:                         .unwrap_or(joint.bind.scale)
225:                 })
226:                 .collect::<Vec<_>>();
227:             BoneTrack {
228:                 translations,
229:                 rotations,
230:                 scales,
231:                 source: if clip.curves().contains_key(&joint.target) {
232:                     BoneTrackSource::Authored
233:                 } else {
234:                     BoneTrackSource::BindPose
235:                 },
236:             }
237:         })
238:         .collect();
239:     BakedClip::new(duration, frame_dt, frames, tracks)
240: }
