1: //! Infer cadence from rig-local foot contacts and retain checked metre measurements.
2: 
3: use super::phase_calibration::{
4:     AuthoredContactSample, ContactOrientation, ContactPhaseFit, FootTrajectorySample,
5:     PhysicalContactSample, StanceDirection, low_height_contacts,
6: };
7: use super::*;
8: 
9: /// Infer travel from the low portion of each authored foot trajectory. This
10: /// discovers contact timing from clip geometry, then fits the single virtual
11: /// root velocity that best holds every stance segment still. The residual is
12: /// retained because some clips cannot represent a requested speed with a
13: /// constant playback rate alone.
14: #[derive(Debug, Clone)]
15: pub(super) struct AuthoredLocomotionCalibration {
16:     pub(super) stride: AuthoredStrideMeasurement,
17:     pub(super) phase_curve: Option<AuthoredPhaseCurve>,
18: }
19: 
20: pub(super) fn measure_authored_contact_step_distance(
21:     definition: &RigDefinition,
22:     clip: &BakedClip,
23:     travel_axis: CalibrationAxis,
24:     expected_stance_direction: StanceDirection,
25: ) -> AnimationValueResult<Option<AuthoredLocomotionCalibration>> {
26:     if clip.duration.seconds() <= 0.0 || clip.frame_count().samples() < 4 {
27:         return Ok(None);
28:     }
29:     let Some(segments) = contact_segments(definition, clip, travel_axis)? else {
30:         return Ok(None);
31:     };
32:     let Some(orientation) = ContactOrientation::fit(&segments, expected_stance_direction)? else {
33:         return Ok(None);
34:     };
35:     let Some(fitted) = ContactPhaseFit::fit(&segments, orientation, expected_stance_direction)?
36:     else {
37:         return Ok(None);
38:     };
39:     fit_stride(fitted.trajectories, fitted.curve, expected_stance_direction)
40: }
41: 
42: pub(super) fn measure_authored_foot_range(
43:     definition: &RigDefinition,
44:     clip: &BakedClip,
45:     travel_axis: CalibrationAxis,
46: ) -> AnimationValueResult<Option<NonnegativeLength>> {
47:     let feet =
48:         [RigJointName::L_FOOT, RigJointName::R_FOOT].map(|name| definition.joint_ordinal(&name));
49:     let [Some(left), Some(right)] = feet else {
50:         return Ok(None);
51:     };
52:     let mut ranges = Vec::with_capacity(2);
53:     for foot in [left, right] {
54:         // Neutral extrema belong only to this nonempty native sampled-position fold.
55:         let mut minimum = f32::INFINITY;
56:         let mut maximum = f32::NEG_INFINITY;
57:         for frame in 0..clip.frame_count().samples() {
58:             let mut globals = RigJointTable::from(vec![None; definition.joints.len()]);
59:             let position = travel_axis.component(
60:                 sampled_global_transform(
61:                     definition,
62:                     clip,
63:                     foot,
64:                     clip.frame_time(frame)?,
65:                     &mut globals,
66:                 )
67:                 .translation,
68:             )?;
69:             minimum = minimum.min(position.metres());
70:             maximum = maximum.max(position.metres());
71:         }
72:         ranges.push(NonnegativeLength::from_arithmetic(maximum - minimum)?);
73:     }
74:     let stride =
75:         NonnegativeLength::from_arithmetic((ranges[0].metres() + ranges[1].metres()) * 0.5)?;
76:     Ok((pose_tuning().minimum_authored_foot_range_metres.metres()
77:         ..=pose_tuning().maximum_authored_foot_range_metres.metres())
78:         .contains(&stride.metres())
79:         .then_some(stride))
80: }
81: 
82: fn contact_segments(
83:     definition: &RigDefinition,
84:     clip: &BakedClip,
85:     travel_axis: CalibrationAxis,
86: ) -> AnimationValueResult<Option<Vec<Vec<AuthoredContactSample>>>> {
87:     let sample_count = clip.frame_count().intervals();
88:     let mut segments = Vec::new();
89:     for name in [RigJointName::L_FOOT, RigJointName::R_FOOT] {
90:         let Some(foot) = definition.joint_ordinal(&name) else {
91:             return Ok(None);
92:         };
93:         let samples = (0..sample_count)
94:             .map(|frame| {
95:                 let time = clip.frame_time(frame)?;
96:                 let mut globals = RigJointTable::from(vec![None; definition.joints.len()]);
97:                 let position = sampled_global_transform(definition, clip, foot, time, &mut globals)
98:                     .translation;
99:                 if !position.is_finite() {
100:                     return Err(AnimationValueError::NonFinite {
101:                         quantity: AnimationQuantity::CalibrationPosition,
102:                     });
103:                 }
104:                 Ok(FootTrajectorySample {
105:                     authored: CyclePhase::from_arithmetic(
106:                         time.seconds() / clip.duration.seconds(),
107:                     )?,
108:                     position,
109:                 })
110:             })
111:             .collect::<AnimationValueResult<Vec<_>>>()?;
112:         let Some(supported) = low_height_contacts(&samples)? else {
113:             return Ok(None);
114:         };
115:         if supported.iter().all(|supported| *supported) {
116:             return Ok(None);
117:         }
118:         // Start after a non-contact sample: a seam-crossing stance is one unwrapped segment.
119:         let Some(start) = supported.iter().position(|supported| !*supported) else {
120:             return Ok(None);
121:         };
122:         let mut current = Vec::new();
123:         let mut foot_segments = Vec::new();
124:         for offset in 1..=sample_count {
125:             let index = (start + offset) % sample_count;
126:             if supported[index] {
127:                 let wraps = (start + offset) / sample_count;
128:                 current.push(AuthoredContactSample {
129:                     authored: CyclePhase::from_arithmetic(
130:                         samples[index].authored.cycles() + wraps as f32,
131:                     )?,
132:                     position: travel_axis.component(samples[index].position)?,
133:                 });
134:             } else if !current.is_empty() {
135:                 if current.len() >= 3 {
136:                     foot_segments.push(std::mem::take(&mut current));
137:                 } else {
138:                     current.clear();
139:                 }
140:             }
141:         }
142:         if current.len() >= 3 {
143:             foot_segments.push(current);
144:         }
145:         // A low swing-through can enter the height band; retain the longest circular interval.
146:         let Some(segment) = foot_segments.into_iter().max_by_key(Vec::len) else {
147:             return Ok(None);
148:         };
149:         segments.push(segment);
150:     }
151:     Ok(Some(segments))
152: }
153: 
154: fn fit_stride(
155:     warped_segments: Vec<Vec<PhysicalContactSample>>,
156:     curve: AuthoredPhaseCurve,
157:     expected_stance_direction: StanceDirection,
158: ) -> AnimationValueResult<Option<AuthoredLocomotionCalibration>> {
159:     // Each stance gets its own intercept; only the common virtual-root slope
160:     // is shared between feet and contact lobes. Measure the residual after the
161:     // phase warp, because that is the curve actually sampled at runtime.
162:     let mut covariance = 0.0;
163:     let mut phase_variance = 0.0;
164:     for samples in &warped_segments {
165:         let count = samples.len() as f32;
166:         let mean_phase = samples
167:             .iter()
168:             .map(|sample| sample.physical.cycles())
169:             .sum::<f32>()
170:             / count;
171:         let mean_position = samples
172:             .iter()
173:             .map(|sample| sample.position.metres())
174:             .sum::<f32>()
175:             / count;
176:         for sample in samples {
177:             let centered_phase = sample.physical.cycles() - mean_phase;
178:             covariance += centered_phase * (sample.position.metres() - mean_position);
179:             phase_variance += centered_phase * centered_phase;
180:         }
181:     }
182:     if phase_variance <= 0.0 {
183:         return Ok(None);
184:     }
185:     let fitted_slope = covariance / phase_variance;
186:     let cycle_distance = fitted_slope * expected_stance_direction.sign();
187:     let step_distance = cycle_distance * 0.5;
188:     let maximum_stance_slip = warped_segments
189:         .iter()
190:         .map(|samples| {
191:             let residuals = samples
192:                 .iter()
193:                 .map(|sample| sample.position.metres() - fitted_slope * sample.physical.cycles());
194:             let (minimum, maximum) = residuals.fold(
195:                 (f32::INFINITY, f32::NEG_INFINITY),
196:                 |(minimum, maximum), residual| (minimum.min(residual), maximum.max(residual)),
197:             );
198:             maximum - minimum
199:         })
200:         .fold(0.0_f32, f32::max);
201:     if !step_distance.is_finite() || !maximum_stance_slip.is_finite() {
202:         return Err(AnimationValueError::Overflow {
203:             quantity: AnimationQuantity::CalibrationPosition,
204:         });
205:     }
206:     if cycle_distance <= 0.0 {
207:         return Ok(None);
208:     }
209:     let step_distance = NonnegativeLength::from_arithmetic(step_distance)?;
210:     let maximum_stance_slip = NonnegativeLength::from_arithmetic(maximum_stance_slip)?;
211:     if !(pose_tuning().minimum_authored_foot_range_metres.metres()
212:         ..=pose_tuning().maximum_authored_foot_range_metres.metres())
213:         .contains(&step_distance.metres())
214:     {
215:         return Ok(None);
216:     }
217:     Ok(Some(AuthoredLocomotionCalibration {
218:         stride: AuthoredStrideMeasurement {
219:             step_distance,
220:             maximum_stance_slip,
221:         },
222:         phase_curve: Some(curve),
223:     }))
224: }
