1: //! Traverse the retained rig hierarchy in pose-buffer space.
2: //!
3: //! Joint ordinals remain typed across recursive sampling. Their
4: //! values select rig-order collections whose owner performs native indexing.
5: 
6: use super::*;
7: 
8: pub(super) fn hand_animation_joint(
9:     definition: &RigDefinition,
10:     mut joint: RigJointOrdinal,
11: ) -> Option<ClipLayer> {
12:     loop {
13:         match definition.joints[joint].role {
14:             Some(BoneRole::HandRight) => return Some(ClipLayer::MainHand),
15:             Some(BoneRole::HandLeft) => return Some(ClipLayer::Offhand),
16:             _ => {}
17:         }
18:         let parent = definition.joints[joint].parent?;
19:         joint = parent;
20:     }
21: }
22: 
23: pub(super) fn local_pose_global(
24:     definition: &RigDefinition,
25:     pose: &RigJointTable<LocalPose>,
26:     joint: RigJointOrdinal,
27:     cache: &mut RigJointTable<Option<Transform>>,
28: ) -> Transform {
29:     if let Some(global) = cache[joint] {
30:         return global;
31:     }
32:     let local = Transform {
33:         translation: pose[joint].translation,
34:         rotation: pose[joint].rotation,
35:         scale: pose[joint].scale,
36:     };
37:     let global = definition.joints[joint].parent.map_or(local, |parent| {
38:         local_pose_global(definition, pose, parent, cache).mul_transform(local)
39:     });
40:     cache[joint] = Some(global);
41:     global
42: }
43: 
44: pub(super) fn aim_pose_joint(
45:     definition: &RigDefinition,
46:     pose: &mut RigJointTable<LocalPose>,
47:     joint: RigJointOrdinal,
48:     from: Vec3,
49:     to: Vec3,
50: ) {
51:     let (Some(from), Some(to)) = (from.try_normalize(), to.try_normalize()) else {
52:         return;
53:     };
54:     let mut cache = RigJointTable::from(vec![None; pose.len()]);
55:     let current = local_pose_global(definition, pose, joint, &mut cache);
56:     let parent_rotation = definition.joints[joint]
57:         .parent
58:         .map(|parent| local_pose_global(definition, pose, parent, &mut cache).rotation)
59:         .unwrap_or(Quat::IDENTITY);
60:     let desired_world = Quat::from_rotation_arc(from, to) * current.rotation;
61:     let local = parent_rotation.inverse() * desired_world;
62:     if local.is_finite() {
63:         pose[joint].rotation = local.normalize();
64:     }
65: }
66: 
67: pub(super) fn sampled_global_transform(
68:     definition: &RigDefinition,
69:     clip: &BakedClip,
70:     joint: RigJointOrdinal,
71:     time_seconds: ClipTime,
72:     cache: &mut RigJointTable<Option<Transform>>,
73: ) -> Transform {
74:     if let Some(transform) = cache[joint] {
75:         return transform;
76:     }
77:     let pose = clip.sample(joint, time_seconds);
78:     let local = Transform {
79:         translation: pose.translation,
80:         rotation: pose.rotation,
81:         scale: pose.scale,
82:     };
83:     let global = definition.joints[joint].parent.map_or(local, |parent| {
84:         sampled_global_transform(definition, clip, parent, time_seconds, cache).mul_transform(local)
85:     });
86:     cache[joint] = Some(global);
87:     global
88: }
