1: //! Checked phase of the pose buffer's fixed sample interval.
2: 
3: use adventuresim_tactical_core::animation::{
4:     AnimationElapsed, AnimationQuantity, AnimationValueError, AnimationValueResult,
5:     PositiveAnimationDuration, UnitInterval,
6: };
7: 
8: #[derive(Clone, Copy)]
9: pub(super) struct PoseInterpolation(UnitInterval);
10: 
11: impl PoseInterpolation {
12:     pub(super) const ZERO: Self = Self(UnitInterval::ZERO);
13:     pub(super) const ONE: Self = Self(UnitInterval::ONE);
14:     pub(super) fn from_sample_clock(
15:         elapsed: AnimationElapsed,
16:         interval: PositiveAnimationDuration,
17:     ) -> AnimationValueResult<Self> {
18:         // Native seconds cancel only in this fixed-clock ratio kernel.
19:         let fraction = elapsed.seconds() / interval.seconds();
20:         if !fraction.is_finite() {
21:             return Err(AnimationValueError::Overflow {
22:                 quantity: AnimationQuantity::PoseInterpolation,
23:             });
24:         }
25:         Self::from_fraction(
26:             fraction.clamp(UnitInterval::ZERO.fraction(), UnitInterval::ONE.fraction()),
27:         )
28:     }
29:     pub(super) fn amount(self) -> UnitInterval {
30:         self.0
31:     }
32:     pub(super) fn fraction(self) -> f32 {
33:         self.0.fraction()
34:     }
35:     fn from_fraction(fraction: f32) -> AnimationValueResult<Self> {
36:         UnitInterval::from_fraction(fraction)
37:             .map(Self)
38:             .map_err(|error| {
39:                 AnimationValueError::from(error).for_quantity(AnimationQuantity::PoseInterpolation)
40:             })
41:     }
42: }

