1: //! Interruption-safe pose inertialization (Bollo, GDC 2018, "Inertialization:
2: //! High-Performance Animation Transitions in Gears of War").
3: //!
4: //! A plan change never crossfades clip against clip. The difference between
5: //! the displayed pose and the new target folds into a per-joint offset, and
6: //! that offset decays to zero over a fixed blend with a quintic that lands on
7: //! zero position, velocity, and acceleration. An interruption captures the
8: //! still-decaying offset together with its velocity, so back-to-back
9: //! transitions stay continuous.
10: //!
11: //! Each channel is a scalar magnitude along a direction frozen at capture; a
12: //! rotation offset is an angle about the axis of the offset quaternion. Two
13: //! overshoot guards from the talk apply: an initial velocity that carries the
14: //! offset away from zero is dropped, and the blend is shortened when the
15: //! offset is already closing fast enough to swing through zero.
16: 
17: use bevy::prelude::*;
18: 
19: use super::LocalPose;
20: use adventuresim_tactical_core::animation::{
21:     AnimationElapsed, AnimationValueResult, PositiveAnimationDuration,
22: };
23: 
24: /// Neighbourhood-checked slerp: `q` and `-q` are the same rotation, and
25: /// interpolating across the antipode is the classic one-frame bone teleport.
26: pub(super) fn hemisphere_slerp(first: Quat, mut second: Quat, alpha: f32) -> Quat {
27:     if first.dot(second) < 0.0 {
28:         second = -second;
29:     }
30:     first.slerp(second, alpha.clamp(0.0, 1.0)).normalize()
31: }
32: 
33: /// Keep `w >= 0` so logarithms and differences take the short way round.
34: pub(super) fn shortest_rotation(rotation: Quat) -> Quat {
35:     if rotation.w < 0.0 {
36:         -rotation
37:     } else {
38:         rotation
39:     }
40: }
41: 
42: pub(super) fn quaternion_exp(value: Vec3) -> Quat {
43:     let half_angle = value.length();
44:     if half_angle < 1e-8 {
45:         Quat::from_xyzw(value.x, value.y, value.z, 1.0).normalize()
46:     } else {
47:         let scale = half_angle.sin() / half_angle;
48:         Quat::from_xyzw(
49:             scale * value.x,
50:             scale * value.y,
51:             scale * value.z,
52:             half_angle.cos(),
53:         )
54:     }
55: }
56: 
57: pub(super) fn quaternion_log(rotation: Quat) -> Vec3 {
58:     let vector = Vec3::new(rotation.x, rotation.y, rotation.z);
59:     let length = vector.length();
60:     if length < 1e-8 {
61:         vector
62:     } else {
63:         rotation.w.clamp(-1.0, 1.0).acos() * vector / length
64:     }
65: }
66: 
67: pub(super) fn scaled_angle_axis(rotation: Quat) -> Vec3 {
68:     2.0 * quaternion_log(rotation)
69: }
70: 
71: pub(super) fn quaternion_from_scaled_angle_axis(value: Vec3) -> Quat {
72:     quaternion_exp(value / 2.0)
73: }
74: 
75: /// Angular velocity in scaled-angle-axis form (rad/s) between two rotations
76: /// `delta_seconds` apart. The hemisphere fix is mandatory: a near-antipodal
77: /// pair would otherwise read as a spin of ~2π per step.
78: pub(super) fn quaternion_angular_velocity(
79:     next: Quat,
80:     current: Quat,
81:     elapsed: AnimationElapsed,
82: ) -> Vec3 {
83:     scaled_angle_axis(shortest_rotation(next * current.inverse())) / elapsed.seconds().max(1e-5)
84: }
85: 
86: pub(super) fn local_pose_velocity(
87:     previous: LocalPose,
88:     current: LocalPose,
89:     elapsed: AnimationElapsed,
90: ) -> (Vec3, Vec3) {
91:     (
92:         (current.translation - previous.translation) / elapsed.seconds().max(1.0e-5),
93:         quaternion_angular_velocity(current.rotation, previous.rotation, elapsed),
94:     )
95: }
96: 
97: /// One inertialized channel: the magnitude of an offset along `direction`
98: /// as a quintic in time. The default is a finished (zero) offset.
99: #[derive(Clone, Copy, Debug, Default)]
100: struct QuinticChannel {
101:     direction: Vec3,
102:     x0: f32,
103:     v0: f32,
104:     a0: f32,
105:     a: f32,
106:     b: f32,
107:     c: f32,
108:     duration: AnimationElapsed,
109: }
110: 
111: impl QuinticChannel {
112:     /// `offset` is the offset vector at capture, `velocity` its rate of
113:     /// change, and `blend_seconds` the requested decay (shortened by the
114:     /// overshoot guard when the offset is already closing quickly).
115:     fn new(
116:         offset: Vec3,
117:         velocity: Vec3,
118:         blend: PositiveAnimationDuration,
119:     ) -> AnimationValueResult<Self> {
120:         let magnitude = offset.length();
121:         // A pure velocity discontinuity still needs a direction to decay
122:         // along.
123:         let direction = if magnitude > 1e-6 {
124:             offset / magnitude
125:         } else {
126:             velocity.normalize_or_zero()
127:         };
128:         if direction == Vec3::ZERO {
129:             // Nothing to decay: an already-finished channel must not hold
130:             // the other channel's `done` open for the full blend.
131:             return Ok(Self::default());
132:         }
133:         let x0 = magnitude;
134:         let mut v0 = velocity.dot(direction);
135:         let mut duration = blend.seconds();
136:         if x0 * v0 > 0.0 {
137:             v0 = 0.0;
138:         } else if v0 < 0.0 && x0 > 0.0 {
139:             duration = duration.min(-5.0 * x0 / v0);
140:         }
141:         let duration = duration.max(1e-3);
142:         let (t2, t3) = (duration * duration, duration * duration * duration);
143:         let (t4, t5) = (t3 * duration, t3 * t2);
144:         let a0 = (-8.0 * v0 * duration - 20.0 * x0) / t2;
145:         let a = -(a0 * t2 + 6.0 * v0 * duration + 12.0 * x0) / (2.0 * t5);
146:         let b = (3.0 * a0 * t2 + 16.0 * v0 * duration + 30.0 * x0) / (2.0 * t4);
147:         let c = -(3.0 * a0 * t2 + 12.0 * v0 * duration + 20.0 * x0) / (2.0 * t3);
148:         Ok(Self {
149:             direction,
150:             x0,
151:             v0,
152:             a0,
153:             a,
154:             b,
155:             c,
156:             duration: AnimationElapsed::from_seconds(duration)?,
157:         })
158:     }
159: 
160:     fn offset(&self, elapsed: AnimationElapsed) -> Vec3 {
161:         if elapsed >= self.duration {
162:             return Vec3::ZERO;
163:         }
164:         let t = elapsed.seconds();
165:         let x = ((((self.a * t + self.b) * t + self.c) * t + self.a0 / 2.0) * t + self.v0) * t
166:             + self.x0;
167:         self.direction * x
168:     }
169: 
170:     fn velocity(&self, elapsed: AnimationElapsed) -> Vec3 {
171:         if elapsed >= self.duration {
172:             return Vec3::ZERO;
173:         }
174:         let t = elapsed.seconds();
175:         let v =
176:             (((5.0 * self.a * t + 4.0 * self.b) * t + 3.0 * self.c) * t + self.a0) * t + self.v0;
177:         self.direction * v
178:     }
179: }
180: 
181: /// Per-joint inertialization state. The displayed pose is
182: /// `rotation_offset * input.rotation` and `input.translation + offset`; the
183: /// offset is what decays to identity and zero.
184: #[derive(Clone, Copy, Debug, Default)]
185: pub(super) struct JointInertialOffset {
186:     translation: QuinticChannel,
187:     rotation: QuinticChannel,
188:     elapsed: AnimationElapsed,
189: }
190: 
191: impl JointInertialOffset {
192:     /// Call at the moment of a plan change with the pose and velocity that
193:     /// were displayed this frame (offset included, which is what makes an
194:     /// interruption seamless) and the new target with its velocity.
195:     ///
196:     /// Each velocity is a `(linear, angular)` pair in the joint's local frame.
197:     pub(super) fn capture(
198:         &mut self,
199:         displayed: LocalPose,
200:         displayed_velocity: (Vec3, Vec3),
201:         target: LocalPose,
202:         target_velocity: (Vec3, Vec3),
203:         blend: PositiveAnimationDuration,
204:     ) -> AnimationValueResult<()> {
205:         let translation = QuinticChannel::new(
206:             displayed.translation - target.translation,
207:             displayed_velocity.0 - target_velocity.0,
208:             blend,
209:         )?;
210:         let rotation_offset = shortest_rotation(displayed.rotation * target.rotation.inverse());
211:         let rotation = QuinticChannel::new(
212:             scaled_angle_axis(rotation_offset),
213:             displayed_velocity.1 - target_velocity.1,
214:             blend,
215:         )?;
216:         self.translation = translation;
217:         self.rotation = rotation;
218:         self.elapsed = AnimationElapsed::ZERO;
219:         Ok(())
220:     }
221: 
222:     /// Both channels have reached zero; the joint sits on the raw target.
223:     pub(super) fn done(&self) -> bool {
224:         self.elapsed >= self.translation.duration.max(self.rotation.duration)
225:     }
226: 
227:     pub(super) fn translation_velocity(&self) -> Vec3 {
228:         self.translation.velocity(self.elapsed)
229:     }
230:

