231:     pub(super) fn angular_velocity(&self) -> Vec3 {
232:         self.rotation.velocity(self.elapsed)
233:     }
234: 
235:     fn rotation_offset(&self) -> Quat {
236:         quaternion_from_scaled_angle_axis(self.rotation.offset(self.elapsed))
237:     }
238: 
239:     /// Advance the decay and return the displayed pose.
240:     pub(super) fn update(
241:         &mut self,
242:         input: LocalPose,
243:         elapsed: AnimationElapsed,
244:     ) -> AnimationValueResult<LocalPose> {
245:         let next = self.elapsed.checked_add(elapsed)?;
246:         self.elapsed = next;
247:         Ok(self.peek(input))
248:     }
249: 
250:     /// Apply the current offset without advancing it.
251:     pub(super) fn peek(&self, input: LocalPose) -> LocalPose {
252:         if self.done() {
253:             return input;
254:         }
255:         LocalPose {
256:             translation: input.translation + self.translation.offset(self.elapsed),
257:             // Round trips through exp/log accumulate drift; keep it unit.
258:             rotation: (self.rotation_offset() * input.rotation).normalize(),
259:             scale: input.scale,
260:         }
261:     }
262: }
