1: //! Sparse locomotion anchors and their admitted authored timeline.
2: 
3: use super::*;
4: 
5: #[derive(Debug, PartialEq)]
6: struct SparseLocomotionSegment {
7:     start: u32,
8:     end: u32,
9:     amount: UnitInterval,
10: }
11: 
12: pub(super) fn sample_locomotion_at_time(
13:     clip: &AnimationClip,
14:     joint: &RigJoint,
15:     duration: ClipDuration,
16:     time_seconds: ClipTime,
17: ) -> AnimationValueResult<LocalPose> {
18:     let phase = if duration.seconds() > 0.0 {
19:         time_seconds.seconds() / duration.seconds()
20:     } else {
21:         0.0
22:     };
23:     sample_two_pose_locomotion_clip(clip, joint, duration, CyclePhase::from_cycles(phase)?)
24: }
25: 
26: fn sample_two_pose_locomotion_clip(
27:     clip: &AnimationClip,
28:     joint: &RigJoint,
29:     duration: ClipDuration,
30:     authored_phase: CyclePhase,
31: ) -> AnimationValueResult<LocalPose> {
32:     // The source owns two unique poses: contact and passing/flight. Their
33:     // mirrored counterparts occupy the other half-cycle. Sample only those
34:     // four semantic anchors, then own every in-between here instead of asking
35:     // the glTF sampler (or the 30 Hz baked cache) for intermediate frames.
36:     let segment = sparse_locomotion_segment(authored_phase)?;
37:     const ANCHOR_COUNT: f32 = 4.0;
38:     let sample_anchor = |index: u32| {
39:         // Preserve the source kernel's multiply-then-divide f32 order.
40:         ClipTime::from_seconds(duration.seconds() * index as f32 / ANCHOR_COUNT)
41:             .map(|time| sample_source_clip(clip, joint, time))
42:     };
43:     Ok(sample_anchor(segment.start)?.interpolate(sample_anchor(segment.end)?, segment.amount))
44: }
45: 
46: fn sparse_locomotion_segment(
47:     authored_phase: CyclePhase,
48: ) -> AnimationValueResult<SparseLocomotionSegment> {
49:     let coordinate = authored_phase.cycles().rem_euclid(1.0) * 4.0;
50:     let start = coordinate.floor() as u32;
51:     let t = coordinate - start as f32;
52:     Ok(SparseLocomotionSegment {
53:         start,
54:         end: (start + 1) % 4,
55:         amount: UnitInterval::from_fraction(t * t * (3.0 - 2.0 * t))?,
56:     })
57: }
58: 
59: #[cfg(test)]
60: mod tests {
61:     use super::*;
62:     #[test]
63:     fn sparse_locomotion_sampling_uses_only_semantic_quarter_cycle_anchors() {
64:         assert_eq!(
65:             sparse_locomotion_segment(CyclePhase::from_cycles(0.0).unwrap()).unwrap(),
66:             SparseLocomotionSegment {
67:                 start: 0,
68:                 end: 1,
69:                 amount: UnitInterval::from_fraction(0.0).unwrap()
70:             }
71:         );
72:         assert_eq!(
73:             sparse_locomotion_segment(CyclePhase::from_cycles(0.25).unwrap()).unwrap(),
74:             SparseLocomotionSegment {
75:                 start: 1,
76:                 end: 2,
77:                 amount: UnitInterval::from_fraction(0.0).unwrap()
78:             }
79:         );
80:         assert_eq!(
81:             sparse_locomotion_segment(CyclePhase::from_cycles(0.5).unwrap()).unwrap(),
82:             SparseLocomotionSegment {
83:                 start: 2,
84:                 end: 3,
85:                 amount: UnitInterval::from_fraction(0.0).unwrap()
86:             }
87:         );
88:         assert_eq!(
89:             sparse_locomotion_segment(CyclePhase::from_cycles(0.75).unwrap()).unwrap(),
90:             SparseLocomotionSegment {
91:                 start: 3,
92:                 end: 0,
93:                 amount: UnitInterval::from_fraction(0.0).unwrap()
94:             }
95:         );
96:         assert_eq!(
97:             sparse_locomotion_segment(CyclePhase::from_cycles(1.0).unwrap()).unwrap(),
98:             SparseLocomotionSegment {
99:                 start: 0,
100:                 end: 1,
101:                 amount: UnitInterval::from_fraction(0.0).unwrap()
102:             }
103:         );
104:         let midpoint = sparse_locomotion_segment(CyclePhase::from_cycles(0.125).unwrap())
105:             .unwrap()
106:             .amount
107:             .fraction();
108:         assert!((midpoint - 0.5).abs() < 0.0001);
109:     }
