1: //! Phase-aware sagittal run-foot roll over the canonical bilateral contact.
2: 
3: use super::*;
4: use adventuresim_core::linear_speed::NonnegativeSpeed;
5: use adventuresim_tactical_core::animation::STATIONARY_ANIMATION_SPEED_LIMIT;
6: 
7: /// Phase-aware sagittal foot roll for running. Negative phase is the approach
8: /// to this foot's contact and positive phase is its stance/release. The curve
9: /// arrives with a modest dorsiflexed heel presentation, flattens early in
10: /// stance, then plantar-flexes into toe-off before returning to neutral during
11: /// swing. Terrain-normal alignment remains the base orientation.
12: pub(super) fn run_foot_roll_degrees(
13:     skeleton: &SkeletonState,
14:     speed: NonnegativeSpeed,
15:     foot_side: LeadFoot,
16: ) -> AnimationValueResult<SignedAngleDegrees> {
17:     let profile = locomotion_profile(skeleton, speed)?;
18:     if profile.gait != LocomotionGait::Run
19:         || skeleton.action_kind() != SkeletonAction::None
20:         || skeleton.weapon_guard() != WeaponGuardState::Lowered
21:         || speed <= STATIONARY_ANIMATION_SPEED_LIMIT
22:     {
23:         return Ok(SignedAngleDegrees::ZERO);
24:     }
25:     let signed = skeleton
26:         .gait_phase
27:         .nearest_contact_offset(foot_side)
28:         .cycles();
29:     let radius = profile.support_phase_radius.cycles();
30:     SignedAngleDegrees::from_degrees(if signed < -radius {
31:         // Prepare the heel during the latter half of flight.
32:         8.0 * smoothstep(-0.25, -radius, signed)
33:     } else if signed < -0.05 {
34:         8.0 * (1.0 - smoothstep(-radius, -0.05, signed))
35:     } else if signed <= 0.06 {
36:         0.0
37:     } else if signed <= radius {
38:         -8.0 * smoothstep(0.06, radius, signed)
39:     } else {
40:         // Release the toe smoothly instead of carrying a pointed foot through
41:         // the whole airborne arc.
42:         -8.0 * (1.0 - smoothstep(radius, 0.25, signed))
43:     })
44:     .map_err(|_| AnimationValueError::Overflow {
45:         quantity: AnimationQuantity::BodyAngle,
46:     })
47: }
48: 
49: /// Apply the phase-owned sagittal roll to the already terrain-aligned foot.
50: pub(super) fn run_foot_roll_world_rotation(
51:     skeleton: &SkeletonState,
52:     speed: NonnegativeSpeed,
53:     foot_side: LeadFoot,
54:     rig_rotation: Quat,
55:     base_world: Quat,
56: ) -> AnimationValueResult<Quat> {
57:     let roll_degrees = run_foot_roll_degrees(skeleton, speed, foot_side)?;
58:     Ok(if roll_degrees.degrees().abs() > 0.0 {
59:         let lateral = (rig_rotation * Vec3::X).normalize_or_zero();
60:         Quat::from_axis_angle(lateral, roll_degrees.radians()) * base_world
61:     } else {
62:         base_world
63:     })
64: }
65: 
66: #[cfg(test)]
67: mod tests {
68:     use super::run_foot_roll_degrees;
69:     use adventuresim_tactical_core::animation::{CyclePhase, LeadFoot, SkeletonState};
70:     use bevy::prelude::Vec3;
71: 
72:     #[test]
73:     fn run_foot_roll_has_heel_flat_and_toe_off_beats() {
74:         let mut run = SkeletonState::default();
75:         run.local_velocity = Vec3::new(0.0, 0.0, -5.5);
76:         run.world_velocity = Vec3::new(0.0, 0.0, -5.5);
77:         run.gait_phase = CyclePhase::from_cycles(0.84).unwrap();
78:         assert!(
79:             run_foot_roll_degrees(&run, run.animation_speed().unwrap(), LeadFoot::Left)
80:                 .unwrap()
81:                 .degrees()
82:                 > 0.0,
83:             "heel prepares"
84:         );
85:         run.gait_phase = CyclePhase::from_cycles(0.0).unwrap();
86:         assert_eq!(
87:             run_foot_roll_degrees(&run, run.animation_speed().unwrap(), LeadFoot::Left)
88:                 .unwrap()
89:                 .degrees(),
90:             0.0,
91:             "flat stance"
92:         );
93:         run.gait_phase = CyclePhase::from_cycles(0.15).unwrap();
94:         assert!(
95:             run_foot_roll_degrees(&run, run.animation_speed().unwrap(), LeadFoot::Left)
96:                 .unwrap()
97:                 .degrees()
98:                 < 0.0,
99:             "toe off"
100:         );
101:         run.gait_phase = CyclePhase::from_cycles(0.25).unwrap();
102:         assert_eq!(
103:             run_foot_roll_degrees(&run, run.animation_speed().unwrap(), LeadFoot::Left)
104:                 .unwrap()
105:                 .degrees(),
106:             0.0,
107:             "neutral swing"
108:         );
109:         run.gait_phase = CyclePhase::from_cycles(0.5).unwrap();
110:         assert_eq!(
111:             run_foot_roll_degrees(&run, run.animation_speed().unwrap(), LeadFoot::Right)
112:                 .unwrap()
113:                 .degrees(),
114:             0.0,
115:             "mirrored contact"
116:         );
117:     }
118: }
