1: //! A real finite rig scene frame; absence never fabricates a world transform.
2: 
3: use super::*;
4: 
5: #[derive(Debug, Clone, Copy, PartialEq)]
6: pub(in crate::animation::procedural) struct ObservedRigFrame {
7:     origin: Vec3,
8:     rotation: Quat,
9: }
10: 
11: impl ObservedRigFrame {
12:     pub(in crate::animation::procedural) fn from_native(
13:         origin: Vec3,
14:         rotation: Quat,
15:     ) -> AnimationValueResult<Self> {
16:         if !origin.is_finite() {
17:             return Err(AnimationValueError::NonFinite {
18:                 quantity: AnimationQuantity::WorldPosition,
19:             });
20:         }
21:         if !rotation.is_finite() {
22:             return Err(AnimationValueError::NonFinite {
23:                 quantity: AnimationQuantity::BodyOrientation,
24:             });
25:         }
26:         Ok(Self { origin, rotation })
27:     }
28: 
29:     pub(super) fn from_global(global: &GlobalTransform) -> AnimationValueResult<Self> {
30:         Self::from_native(global.translation(), global.rotation())
31:     }
32: 
33:     pub(super) fn resolve(
34:         rig: &HumanoidRig,
35:         transforms: &TransformHelper,
36:     ) -> AnimationValueResult<Option<Self>> {
37:         let Some(scene) = rig.rig_scene() else {
38:             return Ok(None);
39:         };
40:         let Ok(global) = transforms.compute_global_transform(scene) else {
41:             return Ok(None);
42:         };
43:         Self::from_global(&global).map(Some)
44:     }
45: 
46:     /// Native origin consumed by world/owner vector arithmetic.
47:     pub(super) fn origin(self) -> Vec3 {
48:         self.origin
49:     }
50:     /// Finite non-unit orientations retain their original projection semantics.
51:     pub(super) fn rotation(self) -> Quat {
52:         self.rotation
53:     }
54: }

1: use super::*;
2: 
3: /// Client-only world-space target for a hand. It is presentation data and is
4: /// deliberately absent from replicated `SkeletonState`.
5: #[derive(Debug, Clone, Copy)]
6: pub(crate) struct HandIkTarget {
7:     pub translation: Vec3,
8:     pub rotation: Option<Quat>,
9:     pub weight: UnitInterval,
10: }
11: 
12: /// Optional client-only direct hand targets.
13: #[derive(Component, Debug, Clone, Copy, Default)]
14: pub(crate) struct HumanoidIkTargets {
15:     pub left: Option<HandIkTarget>,
16:     pub right: Option<HandIkTarget>,
17: }
18: 
19: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
20: pub(crate) enum HandSide {
21:     Left,
22:     Right,
23: }
24: 
25: /// Constrains a client-side held item to an authored weapon socket. The
26: /// optional point is in weapon-local space and becomes an off-hand IK target.
27: #[derive(Component, Debug, Clone, Copy)]
28: pub(crate) struct HeldWeaponConstraint {
29:     pub owner: Entity,
30:     pub primary_hand: HandSide,
31:     pub secondary_grip_local: Option<Vec3>,
32: }
33: 
34: #[derive(Debug, Clone, Copy)]
35: struct HandChain {
36:     upper_role: BoneRole,
37:     lower_role: BoneRole,
38:     hand_role: BoneRole,
39:     side: HandSide,
40: }
41: 
42: impl HandChain {
43:     const LEFT: Self = Self {
44:         upper_role: BoneRole::UpperArmLeft,
45:         lower_role: BoneRole::ForearmLeft,
46:         hand_role: BoneRole::HandLeft,
47:         side: HandSide::Left,
48:     };
49:     const RIGHT: Self = Self {
50:         upper_role: BoneRole::UpperArmRight,
51:         lower_role: BoneRole::ForearmRight,
52:         hand_role: BoneRole::HandRight,
53:         side: HandSide::Right,
54:     };
55: 
56:     fn for_side(side: HandSide) -> Self {
57:         match side {
58:             HandSide::Left => Self::LEFT,
59:             HandSide::Right => Self::RIGHT,
60:         }
61:     }
62: 
63:     fn target(self, targets: HumanoidIkTargets) -> Option<HandIkTarget> {
64:         match self.side {
65:             HandSide::Left => targets.left,
66:             HandSide::Right => targets.right,
67:         }
68:     }
69: 
70:     fn is_left(self) -> bool {
71:         self.side == HandSide::Left
72:     }
73: }
