75: /// Applies optional client-only hand targets and held-item constraints. Missing
76: /// targets, sockets, or arm bones are intentionally inert.
77: pub(in crate::animation) fn apply_arm_and_weapon_constraints(
78:     rigs: Query<(Entity, &HumanoidRig)>,
79:     parents: Query<&ChildOf>,
80:     targets: Query<&HumanoidIkTargets>,
81:     mut ik_states: Query<&mut ArmIkState>,
82:     weapon_constraints: Query<(Entity, &HeldWeaponConstraint)>,
83:     mut transforms: ParamSet<(TransformHelper, Query<&mut Transform>)>,
84:     mut commands: Commands,
85: ) {
86:     // Move an explicitly targeted primary hand first. The socket is a child of
87:     // that hand, so the weapon placement below observes the same-frame result.
88:     for (_, constraint) in &weapon_constraints {
89:         let Ok((_, rig)) = rigs.get(constraint.owner) else {
90:             continue;
91:         };
92:         let explicit = targets.get(constraint.owner).copied().unwrap_or_default();
93:         let chain = HandChain::for_side(constraint.primary_hand);
94:         let target = chain.target(explicit);
95:         let Some(target) = target else { continue };
96:         let mut memory = ik_states
97:             .get_mut(constraint.owner)
98:             .map(|state| state.0)
99:             .unwrap_or_default();
100:         apply_hand_target(
101:             constraint.owner,
102:             rig,
103:             chain,
104:             target,
105:             &mut memory,
106:             &parents,
107:             &mut transforms,
108:         );
109:         if let Ok(mut state) = ik_states.get_mut(constraint.owner) {
110:             state.0 = memory;
111:         }
112:     }
113: 
114:     let mut derived_targets = BTreeMap::<Entity, HumanoidIkTargets>::new();
115:     for (weapon, constraint) in &weapon_constraints {
116:         let Ok((_, rig)) = rigs.get(constraint.owner) else {
117:             continue;
118:         };
119:         let socket_role = match constraint.primary_hand {
120:             HandSide::Left => BoneRole::WeaponLeft,
121:             HandSide::Right => BoneRole::WeaponRight,
122:         };
123:         let Some(&socket) = rig.get(&socket_role) else {
124:             continue;
125:         };
126:         let Ok(socket_global) = transforms.p0().compute_global_transform(socket) else {
127:             continue;
128:         };
129:         set_world_transform(
130:             weapon,
131:             weapon_socket_world_transform(socket_global),
132:             &parents,
133:             &mut transforms,
134:         );
135:         if let Some(grip) = constraint.secondary_grip_local {
136:             let Ok(weapon_global) = transforms.p0().compute_global_transform(weapon) else {
137:                 continue;
138:             };
139:             let target = HandIkTarget {
140:                 translation: secondary_grip_world(weapon_global, grip),
141:                 rotation: None,
142:                 weight: UnitInterval::ONE,
143:             };
144:             let entry = derived_targets.entry(constraint.owner).or_default();
145:             match constraint.primary_hand {
146:                 HandSide::Left => entry.right = Some(target),
147:                 HandSide::Right => entry.left = Some(target),
148:             }
149:         }
150:     }
151: 
152:     for (owner, rig) in &rigs {
153:         let explicit = targets.get(owner).copied().unwrap_or_default();
154:         let derived = derived_targets.get(&owner).copied().unwrap_or_default();
155:         let combined = HumanoidIkTargets {
156:             left: derived.left.or(explicit.left),
157:             right: derived.right.or(explicit.right),
158:         };
159:         let mut memory = ik_states
160:             .get_mut(owner)
161:             .map(|state| state.0)
162:             .unwrap_or_default();
163:         for (chain, target) in [
164:             (HandChain::LEFT, combined.left),
165:             (HandChain::RIGHT, combined.right),
166:         ] {
167:             let Some(target) = target else { continue };
168:             apply_hand_target(
169:                 owner,
170:                 rig,
171:                 chain,
172:                 target,
173:                 &mut memory,
174:                 &parents,
175:                 &mut transforms,
176:             );
177:         }
178:         if let Ok(mut state) = ik_states.get_mut(owner) {
179:             state.0 = memory;
180:         } else {
181:             commands.entity(owner).insert(ArmIkState(memory));
182:         }
183:     }
184: }
185: 
186: fn weapon_socket_world_transform(socket: GlobalTransform) -> Transform {
187:     Transform {
188:         translation: socket.translation(),
189:         rotation: socket.rotation(),
190:         scale: Vec3::ONE,
191:     }
192: }
193: 
194: #[cfg(test)]
195: mod tests {
196:     use super::*;
197: 
198:     #[test]
199:     fn held_weapon_uses_the_authored_socket_orientation_without_inheriting_scale() {
200:         let socket = GlobalTransform::from(Transform {

201:             translation: Vec3::new(0.4, 1.2, -0.3),
202:             rotation: Quat::from_euler(EulerRot::XYZ, 0.7, -0.4, 1.1),
203:             scale: Vec3::splat(1.25),
204:         });
205: 
206:         let weapon = weapon_socket_world_transform(socket);
207: 
208:         assert!(weapon.translation.abs_diff_eq(socket.translation(), 1e-5));
209:         assert!(weapon.rotation.dot(socket.rotation()).abs() > 1.0 - 1e-5);
210:         assert_eq!(weapon.scale, Vec3::ONE);
211:     }
212: }
213: 
214: fn apply_hand_target(
215:     owner: Entity,
216:     rig: &HumanoidRig,
217:     chain: HandChain,
218:     target: HandIkTarget,
219:     memory: &mut ArmIkMemory,
220:     parents: &Query<&ChildOf>,
221:     transforms: &mut ParamSet<(TransformHelper, Query<&mut Transform>)>,
222: ) {
223:     let weight = target.weight.fraction();
224:     if weight <= 0.0 {
225:         return;
226:     }
227:     let (Some(&upper), Some(&lower), Some(&hand)) = (
228:         rig.get(&chain.upper_role),
229:         rig.get(&chain.lower_role),
230:         rig.get(&chain.hand_role),
231:     ) else {
232:         return;
233:     };
234:     let Some((upper_snapshot, lower_snapshot, hand_snapshot)) =
235:         snapshot_chain(upper, lower, hand, parents, &transforms.p0())
236:     else {
237:         return;
238:     };
239:     let blended_target = hand_snapshot
240:         .global
241:         .translation()
242:         .lerp(target.translation, weight);
243:     let remembered = if chain.is_left() {
244:         memory.left_arm
245:     } else {
246:         memory.right_arm
247:     };
248:     let Ok(owner_global) = transforms.p0().compute_global_transform(owner) else {
249:         return;
250:     };
251:     let owner_rotation = match ObservedRigFrame::from_global(&owner_global) {
252:         Ok(frame) => frame.rotation(),
253:         Err(error) => {
254:             warn!(%error, "arm owner frame rejected");
255:             return;
256:         }
257:     };
258:     let segments = match LimbSegments::measure(
259:         upper_snapshot.global.translation(),
260:         lower_snapshot.global.translation(),
261:         hand_snapshot.global.translation(),
262:     ) {
263:         Ok(segments) => segments,
264:         Err(error) => {
265:             warn!(%error, "arm segment measurement rejected");
266:             return;
267:         }
268:     };
269:     if let Some(solution) = solve_two_bone(
270:         TwoBoneChain::new(
271:             upper_snapshot.global.translation(),
272:             lower_snapshot.global.translation(),
273:             hand_snapshot.global.translation(),
274:             segments.upper,
275:             segments.lower,
276:             pole_to_world(owner_rotation, remembered.unwrap_or(Vec3::NEG_Y)),
277:         ),
278:         blended_target,
279:     ) {
280:         apply_two_bone_solution(upper, lower, hand, solution, parents, transforms);
281:         let bend = (solution.knee - upper_snapshot.global.translation())
282:             .reject_from_normalized(solution.end_direction);
283:         if let Some(valid) = bend.try_normalize() {
284:             if chain.is_left() {
285:                 memory.left_arm = Some(pole_to_owner(owner_rotation, valid));
286:             } else {
287:                 memory.right_arm = Some(pole_to_owner(owner_rotation, valid));
288:             }
289:         }
290:         if let Some(rotation) = target.rotation {
291:             set_bone_world_rotation(hand, rotation, parents, transforms);
292:         }
293:     }
294: }
