303: fn set_bone_world_rotation(
304:     entity: Entity,
305:     world_rotation: Quat,
306:     parents: &Query<&ChildOf>,
307:     transforms: &mut ParamSet<(TransformHelper, Query<&mut Transform>)>,
308: ) {
309:     let parent_rotation = parents
310:         .get(entity)
311:         .ok()
312:         .and_then(|parent| {
313:             transforms
314:                 .p0()
315:                 .compute_global_transform(parent.parent())
316:                 .ok()
317:         })
318:         .map(|global| global.rotation())
319:         .unwrap_or(Quat::IDENTITY);
320:     let local = parent_rotation.inverse() * world_rotation;
321:     if local.is_finite()
322:         && let Ok(mut transform) = transforms.p1().get_mut(entity)
323:     {
324:         transform.rotation = local.normalize();
325:     }
326: }
327: 
328: fn set_world_transform(
329:     entity: Entity,
330:     world: Transform,
331:     parents: &Query<&ChildOf>,
332:     transforms: &mut ParamSet<(TransformHelper, Query<&mut Transform>)>,
333: ) {
334:     let local = parents
335:         .get(entity)
336:         .ok()
337:         .and_then(|parent| {
338:             transforms
339:                 .p0()
340:                 .compute_global_transform(parent.parent())
341:                 .ok()
342:         })
343:         .map(|parent| GlobalTransform::from(world).reparented_to(&parent))
344:         .unwrap_or(world);
345:     if local.translation.is_finite()
346:         && local.rotation.is_finite()
347:         && let Ok(mut transform) = transforms.p1().get_mut(entity)
348:     {
349:         *transform = local;
350:     }
351: }
