17: #[derive(Debug, Clone, Copy, Default)]
18: enum PelvisShiftState {
19:     #[default]
20:     Pending,
21:     Tracking {
22:         /// Retained world-vertical correction, in signed metres.
23:         metres: SignedLength,
24:     },
25: }
