27: impl OrdinaryLocomotionIkState {
28:     /// Admit the native leg-geometry correction before updating the retained tracking state.
29:     fn observe_terrain_reach(
30:         &mut self,
31:         desired: SignedLength,
32:         elapsed: AnimationElapsed,
33:     ) -> Option<SignedLength> {
34:         match self.pelvis_shift.advance(desired, elapsed) {
35:             Ok(shift) => Some(shift),
36:             Err(error) => {
37:                 warn!(%error, "ordinary IK pelvis correction rejected");
38:                 None
39:             }
40:         }
41:     }
42: 
43:     /// Elapsed IK interval, deduplicated by its typed sample tick.
44:     fn sample_delta_seconds(
45:         &mut self,
46:         clock: &ProceduralAnimationClock,
47:         time: &Time,
48:     ) -> AnimationElapsed {
49:         match clock.fixed_step() {
50:             Some(super::super::clock::FixedAnimationStep { tick, .. })
51:                 if self.evaluation_tick == Some(tick) =>
52:             {
53:                 AnimationElapsed::ZERO
54:             }
55:             Some(super::super::clock::FixedAnimationStep {
56:                 tick,
57:                 delta_seconds: delta,
58:             }) => {
59:                 self.evaluation_tick = Some(tick);
60:                 delta
61:             }
62:             None => AnimationElapsed::from(time.delta()),
63:         }
64:     }
65: }
66: 
67: impl PelvisShiftState {
68:     fn advance(
69:         &mut self,
70:         desired_metres: SignedLength,
71:         elapsed: AnimationElapsed,
72:     ) -> AnimationValueResult<SignedLength> {
73:         let metres = match *self {
74:             Self::Pending => desired_metres,
75:             Self::Tracking { metres } if !elapsed.is_zero() => {
76:                 advance_pelvis_shift(metres, desired_metres, elapsed)?
77:             }
78:             Self::Tracking { metres } => metres,
79:         };
80:         *self = Self::Tracking { metres };
81:         Ok(metres)
82:     }
83: }
