85: /// World-space plant confidence used by diagnostics. Procedural guard movement
86: /// has exactly one support foot while the other follows its clearance arc.
87: pub(crate) fn locomotion_support_weights(
88:     skeleton: &SkeletonState,
89:     speed: NonnegativeSpeed,
90: ) -> AnimationValueResult<(UnitInterval, UnitInterval)> {
91:     if !skeleton.is_grounded() {
92:         return Ok((UnitInterval::ZERO, UnitInterval::ZERO));
93:     }
94:     if !matches!(
95:         skeleton.action_kind(),
96:         SkeletonAction::None | SkeletonAction::Attack
97:     ) {
98:         return Ok((UnitInterval::ZERO, UnitInterval::ZERO));
99:     }
100:     if speed <= STATIONARY_ANIMATION_SPEED_LIMIT {
101:         return Ok((UnitInterval::ONE, UnitInterval::ONE));
102:     }
103:     if skeleton.weapon_guard() == WeaponGuardState::Raised
104:         && skeleton.raised_locomotion().is_moving()
105:     {
106:         Ok(match skeleton.contact_foot {
107:             LeadFoot::Left => (UnitInterval::ONE, UnitInterval::ZERO),
108:             LeadFoot::Right => (UnitInterval::ZERO, UnitInterval::ONE),
109:         })
110:     } else {
111:         let profile = locomotion_profile(skeleton, speed)?;
112:         let (left, right) = gait_support_weights(profile, skeleton.gait_phase)?;
113:         Ok(if profile.gait == LocomotionGait::Run {
114:             (contact_support_weight(left), contact_support_weight(right))
115:         } else {
116:             exclusive_ground_support(left, right, skeleton.gait_phase)
117:         })
118:     }
119: }
