121: pub(in crate::animation::procedural) fn owns(skeleton: &SkeletonState) -> bool {
122:     skeleton.is_grounded()
123:         && !skeleton.is_posture_transitioning()
124:         && skeleton.posture() == Posture::Upright
125:         && !skeleton.is_quickstep()
126:         && ((skeleton.weapon_guard() == WeaponGuardState::Lowered
127:             && skeleton.action_kind() == SkeletonAction::None)
128:             || (skeleton.weapon_guard() == WeaponGuardState::Raised
129:                 && skeleton.raised_locomotion().is_moving()))
130: }
