132: /// Authored upright-locomotion IK: semantic evaluation supplies the complete
133: /// FK pose and frame-specific foot weights. This pass only conforms weighted
134: /// ankles to terrain, applies one shared hip correction, and solves each leg
135: /// once; it never plans a step or changes the authored horizontal trajectory.
136: #[expect(
137:     clippy::too_many_arguments,
138:     reason = "Bevy injects each independently borrowed locomotion IK resource and query as a system parameter"
139: )]
140: pub(in crate::animation) fn apply(
141:     enabled: Res<super::super::super::TerrainIkMode>,
142:     time: Res<Time>,
143:     clock: Res<ProceduralAnimationClock>,
144:     terrain: Query<&SceneTerrain>,
145:     owners: Query<(&PresentedSkeleton, &AnimationPlayback)>,
146:     rigs: Query<(Entity, &HumanoidRig)>,
147:     parents: Query<&ChildOf>,
148:     mut states: Query<&mut OrdinaryLocomotionIkState>,
149:     mut diagnostics: Query<&mut LegIkState>,
150:     mut transforms: ParamSet<(TransformHelper, Query<&mut Transform>)>,
151:     mut commands: Commands,
152: ) {
153:     let _spike = crate::animation::diagnostics::SpikeGuard::new("apply_ordinary_locomotion_ik");
154:     let terrain = terrain.single().ok();
155:     for (owner, rig) in &rigs {
156:         let Ok((skeleton, playback)) = owners.get(owner) else {
157:             continue;
158:         };
159:         if !owns(skeleton) {
160:             continue;
161:         }
162: 
163:         let frame = match ObservedRigFrame::resolve(rig, &transforms.p0()) {
164:             Ok(Some(frame)) => frame,
165:             Ok(None) => continue,
166:             Err(error) => {
167:                 warn!(%error, ?owner, "Rejected ordinary IK rig frame");
168:                 continue;
169:             }
170:         };
171:         let mut state = states
172:             .get_mut(owner)
173:             .map(|state| *state)
174:             .unwrap_or_default();
175:         let delta_seconds = state.sample_delta_seconds(&clock, &time);
176:         let authored_weights = playback.foot_ik_weights;
177: 
178:         let solve_weights = if enabled.is_enabled() && terrain.is_some() {
179:             authored_weights
180:         } else {
181:             FootIkInfluence::NONE
182:         };
183: 
184:         let legs = [
185:             OrdinaryLeg {
186:                 upper_role: BoneRole::ThighLeft,
187:                 lower_role: BoneRole::ShinLeft,
188:                 foot_role: BoneRole::FootLeft,
189:                 weight: solve_weights.left(),
190:                 foot_side: LeadFoot::Left,
191:             },
192:             OrdinaryLeg {
193:                 upper_role: BoneRole::ThighRight,
194:                 lower_role: BoneRole::ShinRight,
195:                 foot_role: BoneRole::FootRight,
196:                 weight: solve_weights.right(),
197:                 foot_side: LeadFoot::Right,
198:             },
199:         ];
200:         let mut targets = [None, None];

201:         let mut authored = [None, None];
202:         let mut support = if enabled.is_enabled() {
203:             [None, None]
204:         } else {
205:             [
206:                 Some(authored_weights.left()),
207:                 Some(authored_weights.right()),
208:             ]
209:         };
210:         let mut desired_pelvis_shift = 0.0_f32;
211: 
212:         for (
213:             index,
214:             OrdinaryLeg {
215:                 upper_role,
216:                 lower_role,
217:                 foot_role,
218:                 weight,
219:                 ..
220:             },
221:         ) in legs.iter().copied().enumerate()
222:         {
223:             let (Some(&upper), Some(&lower), Some(&foot), Some(terrain)) = (
224:                 rig.get(&upper_role),
225:                 rig.get(&lower_role),
226:                 rig.get(&foot_role),
227:                 terrain,
228:             ) else {
229:                 continue;
230:             };
231:             let Some((upper_snapshot, lower_snapshot, foot_snapshot)) =
232:                 snapshot_chain(upper, lower, foot, &parents, &transforms.p0())
233:             else {
234:                 continue;
235:             };
236:             let foot_position = foot_snapshot.global.translation();
237:             authored[index] = Some(foot_position);
238:             let Some(height) = ScenePlanPoint::from_metres(foot_position.xz())
239:                 .and_then(|point| terrain.height_at(point))
240:             else {
241:                 continue;
242:             };
243:             let target = match ordinary_terrain_target(foot_position, height, weight) {
244:                 Ok(target) => target,
245:                 Err(error) => {
246:                     warn!(%error, "authored terrain target rejected");
247:                     continue;
248:                 }
249:             };
250:             let LimbSegments {
251:                 upper: upper_length,
252:                 lower: lower_length,
253:             } = match LimbSegments::measure(
254:                 upper_snapshot.global.translation(),
255:                 lower_snapshot.global.translation(),
256:                 foot_position,
257:             ) {
258:                 Ok(segments) => segments,
259:                 Err(error) => {
260:                     warn!(%error, "IK segment measurement rejected");
261:                     continue;
262:                 }
263:             };
264:             let reach = maximum_reach(upper_length, lower_length);
265:             let shift = match reach.ordinary_pelvis_shift(
266:                 upper_snapshot.global.translation(),
267:                 target,
268:                 ik_tuning().maximum_hip_drop_metres,
269:                 weight,
270:             ) {
271:                 Ok(shift) => shift,
272:                 Err(error) => {
273:                     warn!(%error, "ordinary pelvis reach rejected");
274:                     continue;
275:                 }
276:             };
277:             targets[index] = Some(target);
278:             desired_pelvis_shift = desired_pelvis_shift.min(shift.metres());
279:         }
280: 
281:         let desired_pelvis_shift = match SignedLength::from_metres(desired_pelvis_shift) {
282:             Ok(shift) => shift,
283:             Err(_) => {
284:                 warn!("ordinary IK pelvis geometry overflowed");
285:                 continue;
286:             }
287:         };
288:         let Some(pelvis_shift) = state.observe_terrain_reach(desired_pelvis_shift, delta_seconds)
289:         else {
290:             continue;
291:         };
292:         apply_root_vertical_shift(rig, pelvis_shift, &parents, &mut transforms);
293: 
294:         for (index, leg) in legs.iter().copied().enumerate() {
295:             if let Some(target) = targets[index] {
296:                 let observed = leg.solve(rig, target, frame, terrain, &parents, &mut transforms);
297:                 if enabled.is_enabled() {
298:                     support[index] = observed;
299:                 }
300:             }
301:         }
302: 
303:         let mut memory = LegIkMemory {
304:             left_authored_world_target: authored[0],
305:             right_authored_world_target: authored[1],
306:             left_foot_world_target: targets[0],
307:             right_foot_world_target: targets[1],
308:             left_support_weight: support[0],
309:             right_support_weight: support[1],
310:             pelvis_shift,
311:             evaluation_tick: state.evaluation_tick,
312:             ..default()
313:         };
314:         memory.left_foot_target = targets[0];
315:         memory.right_foot_target = targets[1];
316:         if let Err(error) = memory.publish(owner, &mut diagnostics, &mut commands) {
317:             warn!(%error, "ordinary IK targets rejected");
318:             continue;
319:         }
320:         if let Ok(mut current) = states.get_mut(owner) {
321:             *current = state;
322:         } else {
323:             commands.entity(owner).insert(state);
324:         }
325:     }
326: }
327: 
328: fn apply_root_vertical_shift(
329:     rig: &HumanoidRig,
330:     shift: SignedLength,
331:     parents: &Query<&ChildOf>,
332:     transforms: &mut ParamSet<(TransformHelper, Query<&mut Transform>)>,
333: ) {
334:     let shift = shift.metres();
335:     if shift.abs() <= 0.0001 {
336:         return;
337:     }
338:     let Some(&root) = rig.get(&BoneRole::Root) else {
339:         return;
340:     };
341:     let local_delta = parents
342:         .get(root)
343:         .ok()
344:         .and_then(|parent| {
345:             transforms
346:                 .p0()
347:                 .compute_global_transform(parent.parent())
348:                 .ok()
349:         })
350:         .map(|parent| parent.affine().inverse().transform_vector3(Vec3::Y * shift))
351:         .unwrap_or(Vec3::Y * shift);
352:     if local_delta.is_finite()
353:         && let Ok(mut transform) = transforms.p1().get_mut(root)
354:     {
355:         transform.translation += local_delta;
356:     }
357: }
