359: fn align_foot_to_slope_weighted(
360:     foot: Entity,
361:     sole_up_local: Vec3,
362:     normal: Dir3,
363:     weight: UnitInterval,
364:     parents: &Query<&ChildOf>,
365:     transforms: &mut ParamSet<(TransformHelper, Query<&mut Transform>)>,
366: ) {
367:     let Some(snapshot) = snapshot(foot, parents, &transforms.p0()) else {
368:         return;
369:     };
370:     let Some(aligned_world) =
371:         slope_aligned_world_rotation(snapshot.global.rotation(), sole_up_local, normal)
372:     else {
373:         return;
374:     };
375:     let desired_world = snapshot
376:         .global
377:         .rotation()
378:         .slerp(aligned_world, weight.fraction().clamp(0.0, 1.0));
379:     let Some(local) = local_rotation_for_world(snapshot.parent_rotation, desired_world) else {
380:         return;
381:     };
382:     if let Ok(mut transform) = transforms.p1().get_mut(foot) {
383:         transform.rotation = local;
384:     }
385: }
