24:         let Self {
25:             upper_role,
26:             lower_role,
27:             foot_role,
28:             foot_side,
29:             ..
30:         } = self;
31:         let (Some(target), Some(&upper), Some(&lower), Some(&foot)) = (
32:             Some(target),
33:             rig.get(&upper_role),
34:             rig.get(&lower_role),
35:             rig.get(&foot_role),
36:         ) else {
37:             return None;
38:         };
39:         let (upper_snapshot, lower_snapshot, foot_snapshot) =
40:             snapshot_chain(upper, lower, foot, parents, &transforms.p0())?;
41:         if target.distance(foot_snapshot.global.translation()) <= 0.0001 {
42:             // Preserve an already-clear authored chain exactly. Solving an
43:             // identity ankle target can still rotate it through a newly
44:             // selected knee pole.
45:             return Some(self.weight);
46:         }
47:         let LimbSegments {
48:             upper: upper_length,
49:             lower: lower_length,
50:         } = match LimbSegments::measure(
51:             upper_snapshot.global.translation(),
52:             lower_snapshot.global.translation(),
53:             foot_snapshot.global.translation(),
54:         ) {
55:             Ok(segments) => segments,
56:             Err(error) => {
57:                 warn!(%error, "IK segment measurement rejected");
58:                 return None;
59:             }
60:         };
61:         let canonical = canonical_knee_pole_world(foot_side, frame.rotation());
62:         let pole = authored_knee_pole_world(
63:             upper_snapshot.global.translation(),
64:             lower_snapshot.global.translation(),
65:             target,
66:             canonical,
67:         )
68:         .unwrap_or(canonical);
69:         let pole = constrain_rendered_leg_pole(
70:             rig,
71:             foot_side,
72:             upper_snapshot.global.translation(),
73:             foot_snapshot.global.translation(),
74:             target,
75:             pole,
76:             parents,
77:             &transforms.p0(),
78:         );
79:         let solution = solve_two_bone_with_reach(
80:             TwoBoneChain::new(
81:                 upper_snapshot.global.translation(),
82:                 lower_snapshot.global.translation(),
