2769:                     memory.left_terrain_pole_world,
2770:                     memory.left_terrain_end_direction,
2771:                 )
2772:             } else {
2773:                 (
2774:                     memory.right_terrain_pole_world,
2775:                     memory.right_terrain_end_direction,
2776:                 )
2777:             };
2778:             let next_end_direction =
2779:                 (target - upper_snapshot.global.translation()).normalize_or_zero();
2780:             let remembered = transported_terrain_pole(
2781:                 remembered_pole,
2782:                 previous_end_direction,
2783:                 next_end_direction,
2784:                 canonical_world,
2785:             );
2786:             let pole = remembered
2787:                 .or_else(|| {
2788:                     authored_knee_pole_world(
2789:                         upper_snapshot.global.translation(),
2790:                         lower_snapshot.global.translation(),
2791:                         target,
2792:                         canonical_world,
2793:                     )
2794:                 })
2795:                 .unwrap_or(canonical_world);
2796:             let pole = constrain_rendered_leg_pole(
2797:                 rig,
2798:                 foot_side,
2799:                 upper_snapshot.global.translation(),
2800:                 foot_position,
2801:                 target,
2802:                 pole,
2803:                 &parents,
2804:                 &transforms.p0(),
2805:             );
2806:             let solve_reach = if speed <= STATIONARY_ANIMATION_SPEED_LIMIT {
2807:                 terrain_maximum_reach(upper_length, lower_length)
2808:             } else {
2809:                 maximum_reach(upper_length, lower_length)
2810:             };
2811:             // The transported pole already provides temporal continuity.
2812:             // Authored-bend preservation happens inside the generic solver
2813:             // after pole selection and can rotate the resulting knee outside
2814:             // the anatomical foot-facing cone, so leg IK must use the final
2815:             // constrained pole without another authored blend.
2816:             let solution = solve_two_bone_with_reach(
2817:                 TwoBoneChain::new(
2818:                     upper_snapshot.global.translation(),
2819:                     lower_snapshot.global.translation(),
2820:                     foot_position,
2821:                     upper_length,
2822:                     lower_length,
2823:                     pole,
2824:                 ),
2825:                 target,
2826:                 solve_reach,
2827:             );
2828:             let mut reported_support_weight = UnitInterval::ZERO;
2829:             if let Some(solution) = solution {
2830:                 let sole_at_contact = ScenePlanPoint::from_metres(solution.end.xz())
2831:                     .and_then(|point| terrain.height_at(point))
2832:                     .is_some_and(|height| {
2833:                         sole_is_at_contact(solution.end.y, height)
2834:                             && plant
2835:                                 .is_some_and(|plant| solution.end.xz().distance(plant.xz()) <= 0.02)
2836:                     });
2837:                 if sole_at_contact {
2838:                     reported_support_weight = weight;
2839:                     if left {
2840:                         memory.left_foot_plant.observe_contact(true);
2841:                         memory.left_planned_contact_phase_start = None;
2842:                     } else {
2843:                         memory.right_foot_plant.observe_contact(true);
2844:                         memory.right_planned_contact_phase_start = None;
2845:                     }
2846:                 }
2847:                 apply_two_bone_solution(upper, lower, foot, solution, &parents, &mut transforms);
2848:                 // The terrain-feasible waypoint can still lie beyond the
2849:                 // current analytic chain. Persist the end the player can
2850:                 // actually see and reach, not the rejected pre-solve
2851:                 // request, so the next sample continues from the visible
2852:                 // ankle and diagnostics report truthful release ownership.
2853:                 commit_resolved_unacquired_support_release(
2854:                     &mut memory,
2855:                     foot_side,
2856:                     bounded_unplanned_support_release,
2857:                     solution.end,
2858:                     rig_origin,
2859:                     rig_rotation,
2860:                 );
2861:                 let bend = (solution.knee - upper_snapshot.global.translation())
2862:                     .reject_from_normalized(solution.end_direction);
2863:                 if !state_delta_seconds.is_zero()
2864:                     && let Some(valid) = bend.try_normalize()
2865:                 {
2866:                     if left {
2867:                         memory.left_terrain_pole_world = Some(valid);
2868:                     } else {
2869:                         memory.right_terrain_pole_world = Some(valid);
2870:                     }
2871:                 }
2872:                 if !state_delta_seconds.is_zero() {
2873:                     if left {
2874:                         memory.left_terrain_end_direction = Some(solution.end_direction);
2875:                     } else {
2876:                         memory.right_terrain_end_direction = Some(solution.end_direction);
2877:                     }
2878:                 }
2879:             }
2880:             if left {
2881:                 memory.left_support_weight = Some(reported_support_weight);
2882:             } else {
2883:                 memory.right_support_weight = Some(reported_support_weight);
2884:             }
2885:             // The final rendered-contact result owns orientation authority.
2886:             // Planned acquisition is still airborne until its sole actually
2887:             // reaches the intended contact, so bound that transition after
2888:             // every solve/alignment path rather than inferring it from gait.
2889:             airborne_orientation_owned[leg_index] =
2890:                 !terrain_leg_has_support(reported_support_weight);
2891:             if evaluation_advances {
2892:                 if left {
2893:                     memory.left_contact_orientation_blend_active = update_contact_orientation_blend(
2894:                         memory.left_contact_orientation_blend_active,
2895:                         previous_support,
2896:                         reported_support_weight,
2897:                     );
2898:                 } else {
2899:                     memory.right_contact_orientation_blend_active =
2900:                         update_contact_orientation_blend(
2901:                             memory.right_contact_orientation_blend_active,
2902:                             previous_support,
2903:                             reported_support_weight,
2904:                         );
2905:                 }
2906:             }
2907:             if terrain_alignment_active
2908:                 && let Some(normal) = terrain.normal_at(horizontal_point)
2909:                 && let Some(sole_axis) = rig.sole_axis(foot_side)
2910:             {
2911:                 let cached_chain = if left {
2912:                     memory.left_rotation_chain
2913:                 } else {
2914:                     memory.right_rotation_chain
2915:                 };
2916:                 if evaluation_advances || cached_chain.is_none() {
2917:                     align_foot_to_slope(foot, sole_axis, normal, &parents, &mut transforms);
2918:                 }
2919:             }
2920:         }
2921:         if let Err(error) = finalize_leg_rotation_chains(
2922:             rig,
2923:             skeleton,
2924:             speed,
2925:             rig_rotation,
2926:             &mut memory,
2927:             evaluation_advances,
2928:             state_delta_seconds,
2929:             airborne_orientation_owned,
2930:             airborne_just_released,
2931:             &parents,
2932:             &mut transforms,
2933:         ) {
2934:             warn!(%error, ?owner, "Rejected final leg rotation");
2935:             continue;
2936:         }
2937:         let safe_settle_fallback = memory.settle.is_some_and(|settle| {
2938:             settle.elapsed_seconds >= ik_tuning().safe_settle_fallback_seconds
2939:                 && settle_stance_is_safe(
2940:                     projected_body_center(rig, &transforms.p0()).unwrap_or(rig_origin),
2941:                     memory.left_foot_world_target,
2942:                     memory.right_foot_world_target,
2943:                     terrain,
2944:                 )
2945:         });
2946:         let settle_requests_completion = (settle_ready_for_contact && settle_contact_reached)
2947:             || safe_settle_fallback
2948:             || settle_is_terminal(&memory);
2949:         if settle_requests_completion {
2950:             // Completion leaves two exact terrain plants for idle. A progress
2951:             // 1 settle with no active followers is terminal even if its last
2952:             // analytic solve stopped above contact; otherwise it can freeze a
2953:             // mid-stride pose forever with neither foot reporting support.
2954:             prepare_terminal_settle_contacts(&mut memory, rig_origin, rig_rotation, |xz| {
2955:                 terrain.height_at(xz)
2956:             });
2957:             if terminal_settle_contacts_are_rendered(&memory, |xz| terrain.height_at(xz)) {
2958:                 finish_settle_for_idle(&mut memory);
2959:             }
2960:         }
2961:         if let Err(error) = memory.publish(owner, &mut ik_states, &mut commands) {
2962:             warn!(%error, "IK targets rejected before publication");
2963:             continue;
2964:         }
2965:     }
2966: }
