73: pub(in crate::animation::procedural) fn retain_monotonic_contact_sequence(
74:     current: ContactSequence,
75:     observed: ContactSequence,
76: ) -> ContactSequence {
77:     // The replicated gait planner can return to its zero-valued idle plan
78:     // while authored locomotion still owns the crossfade. That is an owner
79:     // transition, not a landing, so retain the presentation sequence until
80:     // stationary raised footwork takes over. Genuine cadence increments (and
81:     // the u64 wrap) remain forward by exactly one.
82:     if observed.wrapping_distance_from(current) <= AnimationEventSpan::ONE {
83:         observed
84:     } else {
85:         current
86:     }
87: }
88: 
89: pub(in crate::animation::procedural) fn release_raised_state_for_authored_locomotion(
90:     memory: &mut LegIkMemory,
91: ) {
92:     memory.quickstep_handoff = QuickstepContactHandoff::None;
93:     // The pose-buffer transition captures the visible raised pelvis offset.
94:     // Keeping the same correction dormant here would apply it a second time
95:     // when stationary procedural footwork takes ownership again.
96:     memory.raised_pelvis_shift = SignedLength::ZERO;
97:     // Authored FK/contact weights own this interval. Do not expose the prior
98:     // procedural plant as a current terrain-contact claim while retaining the
99:     // propagated endpoints needed for the stop handoff.
100:     memory.left_support_weight = None;
101:     memory.right_support_weight = None;
102: }
103: 
104: /// Refresh contact diagnostics from propagated globals. The IK pass runs
105: /// before transform propagation, while viewer/gameplay consumers observe the
106: /// propagated hierarchy; twist bones and acquisition blending can make those
107: /// positions differ materially from the analytic endpoint.
108: pub(in crate::animation) fn refresh_raised_support_after_propagation(
109:     terrain: Query<&SceneTerrain>,
110:     owners: Query<&PresentedSkeleton>,
111:     rigs: Query<(Entity, &HumanoidRig)>,
112:     globals: Query<&GlobalTransform>,
113:     mut ik_states: Query<&mut LegIkState>,
114:     mut raised_states: Query<&mut RaisedFootworkState>,
115: ) {
116:     let Some(terrain) = terrain.single().ok() else {
117:         return;
118:     };
119:     for (owner, rig) in &rigs {
120:         let Ok(skeleton) = owners.get(owner) else {
121:             continue;
122:         };
123:         let Ok(mut state) = ik_states.get_mut(owner) else {
124:             continue;
125:         };
126:         let propagated_owner_frame = match rig
127:             .rig_scene()
128:             .and_then(|scene| globals.get(scene).ok())
129:             .map(ObservedRigFrame::from_global)
130:             .transpose()
131:         {
132:             Ok(frame) => frame,
133:             Err(error) => {
134:                 warn!(%error, ?owner, "Rejected propagated rig frame");
135:                 continue;
136:             }
137:         };
138:         // Snapshot propagated endpoints before any diagnostic filtering. These
139:         // are deliberately independent of analytic solve targets: a target can
140:         // be unreachable, while this position is the pose actually rendered.
141:         if let Err(error) = state.0.observe_rendered_endpoints(rig, &globals) {
142:             warn!(%error, ?owner, "Rejected propagated leg endpoints");
143:             continue;
144:         }
145:         // IK deliberately does not modify the authored quickstep poses. It
146:         // still observes their propagated endpoints so the first post-action
147:         // solve begins from the last pose the player actually saw.
148: 
149:         let left_rendered_world = state.0.left_last_rendered_world;
150:         let right_rendered_world = state.0.right_last_rendered_world;
151:         if skeleton.is_quickstep()
152:             && let (Some(frame), Some(left), Some(right)) = (
153:                 propagated_owner_frame,
154:                 left_rendered_world,
155:                 right_rendered_world,
156:             )
157:         {
158:             seed_quickstep_contact_handoff(&mut state.0, frame, left, right);
159:         }
160:         let owner_frame = propagated_owner_frame.or(state.0.owner_frame);
161:         state.0.left_last_rendered_owner = owner_frame.and_then(|frame| {
162:             left_rendered_world
163:                 .map(|world| frame.rotation().inverse() * (world - frame.origin()))
164:                 .filter(|owner| owner.is_finite())
165:         });
166:         state.0.right_last_rendered_owner = owner_frame.and_then(|frame| {
167:             right_rendered_world
168:                 .map(|world| frame.rotation().inverse() * (world - frame.origin()))
169:                 .filter(|owner| owner.is_finite())
170:         });
171:         if let Some(frame) = propagated_owner_frame {
172:             // Keep discontinuity detection in the same owner frame as these
173:             // freshly observed endpoints. Otherwise a long authored segment
174:             // compares its terminal root against the stale quickstep origin
175:             // and discards the continuity snapshot during handoff.
176:             state.0.owner_frame = Some(frame);
177:         }
178:         // Authored locomotion owns the leg pose, but its final propagated feet
179:         // are still the continuity boundary for the stationary follower that
180:         // may take ownership on the next tick.
181:         if locomotion::owns(skeleton) {
182:             continue;
183:         }
184:         let speed = match skeleton.animation_speed() {
185:             Ok(speed) => speed,
186:             Err(error) => {
187:                 warn!(%error, ?owner, "Rejected propagated support animation speed");
188:                 continue;
189:             }
190:         };
191:         if let Err(error) =
192:             refresh_run_support(skeleton, speed, rig, terrain, &globals, &mut state.0)
193:         {
194:             warn!(%error, ?owner, "Rejected propagated locomotion support");
195:             continue;
196:         }
197:         let Ok(mut raised) = raised_states.get_mut(owner) else {
198:             continue;
199:         };
200:         if !raised.step.initialized() {
201:             continue;
202:         }
203:         let swing_foot = raised.step.swing_foot();
204:         for (role, left, nominal_support) in [
205:             (BoneRole::FootLeft, true, swing_foot != Some(LeadFoot::Left)),
206:             (
207:                 BoneRole::FootRight,
208:                 false,
209:                 swing_foot != Some(LeadFoot::Right),
210:             ),
211:         ] {
212:             let Some(&foot) = rig.get(&role) else {
213:                 continue;
214:             };
215:             let Ok(global) = globals.get(foot) else {
216:                 continue;
217:             };
218:             let ankle = global.translation();
219:             let support = observed_support_weight(
220:                 nominal_support,
221:                 Some(ankle),
222:                 Some(terrain),
223:                 crate::animation::TerrainIkMode::Enabled,
224:             );
225:             if left {
226:                 raised.left_solve_target = Some(ankle);
227:                 state.0.left_foot_world_target = Some(ankle);
228:                 state.0.left_support_weight = support;
229:             } else {
230:                 raised.right_solve_target = Some(ankle);
231:                 state.0.right_foot_world_target = Some(ankle);
232:                 state.0.right_support_weight = support;
233:             }
234:         }
235:     }
236: }
237: /// Terrain-enabled confidence requires an actual ankle and surface sample.
238: /// Disabled terrain IK instead owns the flat semantic cadence observation.
239: pub(super) fn observed_support_weight(
240:     nominal_support: bool,
241:     ankle: Option<Vec3>,
242:     terrain: Option<&SceneTerrain>,
243:     mode: crate::animation::TerrainIkMode,
244: ) -> Option<UnitInterval> {
245:     let supported = if mode.is_enabled() {
246:         let ankle = ankle?;
247:         let point = ScenePlanPoint::from_metres(ankle.xz())?;
248:         let height = terrain?.height_at(point)?;
249:         raised_support_is_actual(nominal_support, ankle.y, height)
250:     } else {

251:         nominal_support
252:     };
253:     Some(if supported {
254:         UnitInterval::ONE
255:     } else {
256:         UnitInterval::ZERO
257:     })
258: }
