316:     opposite_acquired: bool,
317: ) -> UnitInterval {
318:     if gait != LocomotionGait::Run && acquired_plant && !opposite_acquired {
319:         // Phase requests the next step; actual replacement contact completes
320:         // the handoff. Until then the only acquired world plant remains the
321:         // support owner, even beyond its nominal lobe.
322:         UnitInterval::ONE
323:     } else {
324:         nominal_support
