341: pub(in crate::animation::procedural) fn run_retained_support_through_lobe_edge(
342:     gait: LocomotionGait,
343:     nominal_support: UnitInterval,
344:     acquired_plant: bool,
345:     at_support_exit: bool,
346: ) -> UnitInterval {
347:     if gait == LocomotionGait::Run && acquired_plant && !at_support_exit {
348:         // Once a footprint has been truthfully acquired, it remains an exact
349:         // rendered contact throughout the held stance. Raw gait confidence is
350:         // an authored blend curve, not evidence that contact was lost; letting
351:         // it dip below the acquisition threshold emitted duplicate same-foot
352:         // touchdown events before the explicit signed-phase toe-off.
353:         UnitInterval::ONE
354:     } else {
355:         nominal_support
356:     }
