374: pub(in crate::animation::procedural) fn unplanned_support_release_is_owned(
375:     was_releasing: bool,
376:     previous_transition_support: Option<UnitInterval>,
377:     previous_reported_support: Option<UnitInterval>,
378:     planned_contact: Option<Vec3>,
379:     solved_target: Vec3,
380:     planted_target: Vec3,
381:     authored_target: Vec3,
382: ) -> bool {
383:     was_releasing
384:         || previous_transition_support.is_some_and(terrain_leg_has_support)
385:         || previous_reported_support.is_some_and(terrain_leg_has_support)
386:         || solved_target.distance_squared(planted_target) > 0.000001
387:         || unplanned_terrain_solve_requires_release(planned_contact, solved_target, authored_target)
388: }
389: 
390: fn refresh_run_support(
391:     skeleton: &SkeletonState,
392:     speed: NonnegativeSpeed,
393:     rig: &HumanoidRig,
394:     terrain: &SceneTerrain,
395:     globals: &Query<&GlobalTransform>,
396:     memory: &mut LegIkMemory,
397: ) -> AnimationValueResult<()> {
398:     if locomotion_profile(skeleton, speed)?.gait == LocomotionGait::Run
399:         && skeleton.is_grounded()
400:         && skeleton.action_kind() == SkeletonAction::None
401:         && skeleton.weapon_guard() == WeaponGuardState::Lowered
402:         && speed > STATIONARY_ANIMATION_SPEED_LIMIT
403:     {
404:         let (left_nominal, right_nominal) = locomotion_support_weights(skeleton, speed)?;
405:         for (role, left, nominal, logical, target) in [
406:             (
407:                 BoneRole::FootLeft,
408:                 true,
409:                 left_nominal,
410:                 memory.left_transition_support_weight,
411:                 memory.left_foot_plant.target(),
412:             ),
413:             (
414:                 BoneRole::FootRight,
415:                 false,
416:                 right_nominal,
417:                 memory.right_transition_support_weight,
418:                 memory.right_foot_plant.target(),
419:             ),
420:         ] {
421:             let ankle = rig
422:                 .get(&role)
423:                 .and_then(|foot| globals.get(*foot).ok())
424:                 .map(GlobalTransform::translation)
425:                 .filter(|ankle| ankle.is_finite());
426:             let terrain_height = ankle
427:                 .and_then(|ankle| ScenePlanPoint::from_metres(ankle.xz()))
428:                 .and_then(|point| terrain.height_at(point));
429:             let target_distance = ankle
430:                 .zip(target)
431:                 .map(|(ankle, target)| ankle.xz().distance(target.xz()));
432:             let actual = target_distance.is_some_and(|distance| distance <= 0.02)
433:                 && ankle
434:                     .zip(terrain_height)
435:                     .is_some_and(|(ankle, height)| sole_is_at_contact(ankle.y, height));
436:             let reported = ankle.zip(terrain_height).map(|_| {
437:                 if actual {
438:                     logical.unwrap_or(nominal).max(nominal)
439:                 } else {
440:                     UnitInterval::ZERO
441:                 }
442:             });
443:             if left {
444:                 memory.left_support_weight = reported;
445:                 memory.left_foot_plant.observe_contact(actual);
446:             } else {
447:                 memory.right_support_weight = reported;
448:                 memory.right_foot_plant.observe_contact(actual);
449:             }
450:         }
451:     }
452:     Ok(())
453: }

1: //! Knee-pole, anatomical-yaw, slope, airborne-foot, and final rotation policy.
2: 
3: use super::foot_roll::run_foot_roll_world_rotation;
4: use super::*;
5: pub(in crate::animation::procedural) use anatomical_yaw::anatomical_knee_yaw_posture_is_valid;
6: pub(in crate::animation) use anatomical_yaw::enforce_anatomical_knee_yaw;
7: 
8: use adventuresim_core::linear_speed::NonnegativeSpeed;
9: use bevy::math::Dir3;
10: 
11: mod anatomical_yaw;
12: 
13: // A 576 degree/second cap is nine degrees at the 64 Hz presentation cadence,
14: // retaining numeric margin below the ten-degree review gate. Contact and swing
15: // orientation share this boundary so terrain alignment can never introduce
16: // the old one-frame ankle snap.
17: 
18: pub(in crate::animation::procedural) fn authored_knee_pole_world(
19:     hip: Vec3,
20:     authored_knee: Vec3,
21:     target: Vec3,
22:     canonical: Vec3,
23: ) -> Option<Vec3> {
24:     let target_direction = (target - hip).try_normalize()?;
25:     let bend = (authored_knee - hip).reject_from_normalized(target_direction);
26:     bend.try_normalize()
27:         .filter(|pole| pole.dot(canonical) > 0.2)
28: }
29: 
30: pub(in crate::animation::procedural) fn retained_terrain_pole(
31:     remembered: Vec3,
32:     canonical: Vec3,
33: ) -> Option<Vec3> {
34:     let remembered = remembered.try_normalize()?;
35:     // The old 0.2 cutoff discarded a still-valid shallow bend during the
36:     // support-confidence ramp and rebuilt the knee from authored FK one tick
37:     // later. Owner/mode discontinuities explicitly clear this cache, so any
38:     // finite pole in the anatomical hemisphere remains authoritative here.
39:     (remembered.dot(canonical) > 0.0).then_some(remembered)
40: }
41: 
42: pub(in crate::animation::procedural) fn transported_terrain_pole(
43:     remembered: Option<Vec3>,
44:     previous_end_direction: Option<Vec3>,
45:     next_end_direction: Vec3,
46:     canonical: Vec3,
47: ) -> Option<Vec3> {
48:     let remembered = remembered?.try_normalize()?;
49:     let Some(previous) = previous_end_direction else {
50:         return retained_terrain_pole(remembered, canonical);
51:     };
52:     let previous = previous.try_normalize()?;
53:     let next = next_end_direction.try_normalize()?;
54:     (Quat::from_rotation_arc(previous, next) * remembered).try_normalize()
55: }
56: 
57: /// Keeps a leg's authored bend plane attached to the hip-to-foot direction.
58: ///
59: /// Overgrowth's leg solve rotates the animated knee, ankle, and foot together
60: /// when the IK target moves, which transports the authored knee plane instead
61: /// of selecting a fresh world-space pole every frame. Our analytic solver does
62: /// the equivalent explicitly: parallel-transport the last rendered bend, fall
63: /// back to the current authored bend, and reject either if it crosses the
64: /// anatomical hemisphere. The canonical pole is only the final singularity
65: /// fallback.
66: pub(in crate::animation::procedural) fn stabilized_knee_pole(
67:     remembered_bend: Option<Vec3>,
68:     previous_end_direction: Option<Vec3>,
69:     hip: Vec3,
70:     authored_knee: Vec3,
71:     target: Vec3,
72:     canonical_world: Vec3,
73:     foot_facing: Option<Vec3>,
74: ) -> Option<Vec3> {
75:     let next_end_direction = (target - hip).try_normalize()?;
76:     let canonical_bend = canonical_world
77:         .reject_from_normalized(next_end_direction)
78:         .try_normalize()
79:         .or_else(|| canonical_world.try_normalize())?;
80:     let in_anatomical_hemisphere = |bend: Vec3| {
81:         let bend = bend
82:             .reject_from_normalized(next_end_direction)
83:             .try_normalize()?;
84:         let alignment = bend.dot(canonical_bend);
85:         if alignment >= 0.05 {
86:             Some(bend)
87:         } else {
88:             // Correct continuously at the boundary instead of discarding the
89:             // remembered pole and selecting an unrelated fallback next tick.
90:             (bend + canonical_bend * (0.05 - alignment)).try_normalize()
91:         }
92:     };
93: 
94:     let transported = remembered_bend
95:         .and_then(|bend| {
96:             let bend = bend.try_normalize()?;
97:             previous_end_direction.map_or(Some(bend), |previous| {
98:                 let previous = previous.try_normalize()?;
99:                 (Quat::from_rotation_arc(previous, next_end_direction) * bend).try_normalize()
100:             })
101:         })
102:         .and_then(in_anatomical_hemisphere);
103:     let authored = (authored_knee - hip)
104:         .reject_from_normalized(next_end_direction)
105:         .try_normalize()
106:         .and_then(in_anatomical_hemisphere);
107: 
108:     let selected = transported.or(authored).unwrap_or(canonical_bend);
109:     foot_facing
110:         .and_then(|facing| {
111:             constrain_knee_pole_to_foot_facing(
112:                 selected,
113:                 next_end_direction,
114:                 facing,
115:                 ik_tuning().knee_pole_maximum_foot_facing_offset_degrees,
116:             )
117:         })
118:         .or(Some(selected))
119: }
120: 
121: pub(in crate::animation::procedural) fn constrain_knee_pole_to_foot_facing(
122:     pole: Vec3,
123:     leg_direction: Vec3,
124:     foot_facing: Vec3,
125:     maximum_offset: AngularMagnitudeDegrees,
126: ) -> Option<Vec3> {
127:     let leg_direction = leg_direction.try_normalize()?;
128:     let facing_yaw = foot_facing.xz().try_normalize()?;
129:     let pole_yaw = pole.xz().try_normalize().unwrap_or(facing_yaw);
130:     let signed_offset = facing_yaw
131:         .perp_dot(pole_yaw)
132:         .atan2(facing_yaw.dot(pole_yaw));
133:     let maximum_offset_radians = maximum_offset.radians();
134:     let clamped_offset = signed_offset.clamp(-maximum_offset_radians, maximum_offset_radians);
135:     let (sin, cos) = clamped_offset.sin_cos();
136:     let clamped_yaw = Vec2::new(
137:         facing_yaw.x * cos - facing_yaw.y * sin,
138:         facing_yaw.x * sin + facing_yaw.y * cos,
139:     );
140: 
141:     // Preserve the clamped ground-plane yaw exactly, then choose the vertical
142:     // component that makes the pole perpendicular to the hip-to-foot axis.
143:     // Clamping only after projecting into that plane does not bound yaw for a
144:     // diagonal leg and was the source of visibly sideways knees.
145:     if leg_direction.y.abs() <= 0.0001 {
146:         return None;
147:     }
148:     let vertical = -clamped_yaw.dot(leg_direction.xz()) / leg_direction.y;
149:     Vec3::new(clamped_yaw.x, vertical, clamped_yaw.y).try_normalize()
150: }
151: 
152: /// Applies the anatomical knee-yaw invariant at the final leg-solve boundary.
153: ///
154: /// Individual pose owners may transport, preserve, or reconstruct their pole
155: /// differently, but every valid humanoid leg has the same hard constraint:
156: /// its effective pole stays within the foot-facing cone. Keeping this wrapper
157: /// beside the raw constraint prevents ordinary terrain and landing paths from
158: /// bypassing the combat-specific stabilizer.
159: #[expect(
160:     clippy::too_many_arguments,
161:     reason = "the final leg-pole constraint keeps the anatomical geometry and hierarchy readers explicit"
162: )]
163: pub(in crate::animation::procedural) fn constrain_rendered_leg_pole(
164:     rig: &HumanoidRig,
165:     foot_side: LeadFoot,
166:     hip: Vec3,
167:     foot_position: Vec3,
168:     target: Vec3,
169:     pole: Vec3,
170:     parents: &Query<&ChildOf>,
171:     transforms: &TransformHelper,
172: ) -> Vec3 {
173:     rendered_foot_facing(rig, foot_side, foot_position, parents, transforms)
174:         .and_then(|facing| {
175:             constrain_knee_pole_to_foot_facing(
176:                 pole,
177:                 target - hip,
178:                 facing,
179:                 ik_tuning().knee_pole_maximum_foot_facing_offset_degrees,
180:             )
181:         })
182:         // Sparse/non-humanoid rigs may not expose a toe direction. Preserve
183:         // their previous graceful fallback; canonical humanoids always take
184:         // the constrained branch.
185:         .unwrap_or(pole)
186: }
187: 
188: pub(in crate::animation::procedural) fn rendered_foot_facing(
189:     rig: &HumanoidRig,
190:     foot_side: LeadFoot,
191:     foot_position: Vec3,
192:     parents: &Query<&ChildOf>,
193:     transforms: &TransformHelper,
194: ) -> Option<Vec3> {
195:     let foot = *rig.get(&match foot_side {
196:         LeadFoot::Left => BoneRole::FootLeft,
197:         LeadFoot::Right => BoneRole::FootRight,
198:     })?;
199:     let toe = *rig.get(&match foot_side {
200:         LeadFoot::Left => BoneRole::ToeLeft,
201:         LeadFoot::Right => BoneRole::ToeRight,
202:     })?;
203:     let foot_rotation = snapshot(foot, parents, transforms)?.global.rotation();
204:     let toe_position = snapshot(toe, parents, transforms)?.global.translation();
205:     let toe_direction = (toe_position - foot_position).try_normalize()?;
206: 
207:     // Toe-to-ankle projected directly onto the ground reverses yaw when a
208:     // running or slope-aligned foot pitches through vertical. Recover yaw
209:     // from the pitch-stable lateral axis instead: forward cross sole-up gives
210:     // anatomical right, and world-up cross right gives horizontal forward.
211:     // This preserves the direction the foot is facing even at heel/toe roll.
212:     if let Some(sole_up) = rig
213:         .sole_axis(foot_side)
214:         .map(|axis| foot_rotation * axis)
215:         .and_then(Vec3::try_normalize)
216:         && let Some(lateral) = toe_direction.cross(sole_up).try_normalize()
217:         && let Some(facing) = Vec3::Y.cross(lateral).xz().try_normalize()
218:     {
219:         return Some(Vec3::new(facing.x, 0.0, facing.y));
220:     }
221: 
222:     toe_direction
223:         .xz()
224:         .try_normalize()
225:         .map(|facing| Vec3::new(facing.x, 0.0, facing.y))
226: }
227: 
228: pub(in crate::animation::procedural) fn projected_body_center(
229:     rig: &HumanoidRig,
230:     transforms: &TransformHelper,
231: ) -> Option<Vec3> {
232:     let mut weighted = Vec3::ZERO;
233:     let mut total = 0.0;
234:     for (role, weight) in [
235:         (BoneRole::Pelvis, 0.45),
236:         (BoneRole::Chest, 0.35),
237:         (BoneRole::Head, 0.20),
238:     ] {
239:         let Some(&bone) = rig.get(&role) else {
240:             continue;
241:         };
242:         let Ok(global) = transforms.compute_global_transform(bone) else {
243:             continue;
244:         };
245:         weighted += global.translation() * weight;
246:         total += weight;
247:     }
248:     (total > 0.0).then_some(weighted / total)
249: }
250:

251: pub(in crate::animation::procedural) fn align_foot_to_slope(
252:     foot: Entity,
253:     sole_up_local: Vec3,
254:     normal: Dir3,
255:     parents: &Query<&ChildOf>,
256:     transforms: &mut ParamSet<(TransformHelper, Query<&mut Transform>)>,
257: ) {
258:     let Some(snapshot) = snapshot(foot, parents, &transforms.p0()) else {
259:         return;
260:     };
261:     let world = slope_aligned_world_rotation(snapshot.global.rotation(), sole_up_local, normal);
262:     let Some(world) = world else { return };
263:     let Some(local) = local_rotation_for_world(snapshot.parent_rotation, world) else {
264:         return;
265:     };
266:     if let Ok(mut transform) = transforms.p1().get_mut(foot) {
267:         transform.rotation = local;
268:     }
269: }
270: 
271: pub(in crate::animation::procedural) fn advance_airborne_foot_rotation(
272:     previous: Option<Quat>,
273:     desired: Quat,
274:     delta_seconds: AnimationElapsed,
275:     maximum_speed_degrees: SignedAngularSpeedDegrees,
276: ) -> Quat {
277:     let Some(previous) = previous.filter(|rotation| rotation.is_finite()) else {
278:         return desired;
279:     };
280:     if !desired.is_finite() {
281:         return previous;
282:     }
283:     let angle = previous.angle_between(desired);
284:     let maximum_step = maximum_speed_degrees
285:         .degrees_per_second()
286:         .max(0.0)
287:         .to_radians()
288:         * delta_seconds.seconds();
289:     if maximum_step <= 0.0 {
290:         return previous;
291:     }
292:     if angle <= maximum_step || angle <= 0.0 {
293:         desired
294:     } else {
295:         previous.slerp(desired, maximum_step / angle).normalize()
296:     }
297: }
298: 
299: pub(in crate::animation::procedural) fn previous_airborne_foot_orientation(
300:     analytic_previous: Option<Quat>,
301:     propagated_previous: Option<Quat>,
302:     just_released: bool,
303: ) -> Option<Quat> {
304:     if just_released {
305:         // The pre-propagation analytic orientation can differ from the foot
306:         // orientation that the player saw after the full hierarchy settled.
307:         // Toe-off begins from that propagated pose so a nominally stationary
308:         // ankle cannot lever the toe through the continuity budget.
309:         propagated_previous.or(analytic_previous)
310:     } else {
311:         analytic_previous
312:     }
313: }
314: 
315: #[expect(
316:     clippy::too_many_arguments,
317:     reason = "the final leg rotation boundary keeps pose state, airborne transitions, and hierarchy access explicit"
318: )]
319: pub(in crate::animation::procedural) fn finalize_leg_rotation_chains(
320:     rig: &HumanoidRig,
321:     skeleton: &SkeletonState,
322:     speed: NonnegativeSpeed,
323:     rig_rotation: Quat,
324:     memory: &mut LegIkMemory,
325:     evaluation_advances: bool,
326:     delta_seconds: AnimationElapsed,
327:     airborne_orientation_owned: [bool; 2],
328:     airborne_just_released: [bool; 2],
329:     parents: &Query<&ChildOf>,
330:     transforms: &mut ParamSet<(TransformHelper, Query<&mut Transform>)>,
331: ) -> AnimationValueResult<()> {
332:     for (leg_index, (upper_role, lower_role, foot_role, foot_side)) in [
333:         (
334:             BoneRole::ThighLeft,
335:             BoneRole::ShinLeft,
336:             BoneRole::FootLeft,
337:             LeadFoot::Left,
338:         ),
339:         (
340:             BoneRole::ThighRight,
341:             BoneRole::ShinRight,
342:             BoneRole::FootRight,
343:             LeadFoot::Right,
344:         ),
345:     ]
346:     .into_iter()
347:     .enumerate()
348:     {
349:         let (Some(&upper), Some(&lower), Some(&foot)) = (
350:             rig.get(&upper_role),
351:             rig.get(&lower_role),
352:             rig.get(&foot_role),
353:         ) else {
354:             continue;
355:         };
356:         let current = {
357:             let query = transforms.p1();
358:             let (Ok(upper), Ok(lower), Ok(foot)) =
359:                 (query.get(upper), query.get(lower), query.get(foot))
360:             else {
361:                 continue;
362:             };
363:             LegRotationChain {
364:                 upper: upper.rotation,
365:                 lower: lower.rotation,
366:                 foot: foot.rotation,
367:             }
368:         };
369:         let cached = if foot_side == LeadFoot::Left {
370:             memory.left_rotation_chain
371:         } else {
372:             memory.right_rotation_chain
373:         };
374:         let contact_blend_active = if foot_side == LeadFoot::Left {
375:             memory.left_contact_orientation_blend_active
376:         } else {
377:             memory.right_contact_orientation_blend_active
378:         };
379:         let mut resolved = final_leg_rotation_chain(cached, current, evaluation_advances);
380:         {
381:             let mut query = transforms.p1();
382:             if let Ok(mut transform) = query.get_mut(upper) {
383:                 transform.rotation = resolved.upper;
384:             }
385:             if let Ok(mut transform) = query.get_mut(lower) {
386:                 transform.rotation = resolved.lower;
387:             }
388:             if let Ok(mut transform) = query.get_mut(foot) {
389:                 transform.rotation = resolved.foot;
390:             }
391:         }
392:         if evaluation_advances
393:             && let Some(foot_snapshot) = snapshot(foot, parents, &transforms.p0())
394:         {
395:             let desired_world = run_foot_roll_world_rotation(
396:                 skeleton,
397:                 speed,
398:                 foot_side,
399:                 rig_rotation,
400:                 foot_snapshot.global.rotation(),
401:             )?;
402:             let previous_world =
403:                 previous_foot_orientation(memory, foot_side, airborne_just_released[leg_index]);
404:             let final_world = if airborne_orientation_owned[leg_index] || contact_blend_active {
405:                 let angular_speed = if locomotion_profile(skeleton, speed)?.gait
406:                     == LocomotionGait::Run
407:                     && airborne_just_released[leg_index]
408:                 {
409:                     ik_tuning().first_run_release_foot_rotation_speed_degrees_per_second
410:                 } else {
411:                     ik_tuning().airborne_foot_rotation_speed_degrees_per_second
412:                 };
413:                 let bounded_world = advance_airborne_foot_rotation(
414:                     previous_world,
415:                     desired_world,
416:                     delta_seconds,
417:                     angular_speed,
418:                 );
419:                 if let Some(local) =
420:                     local_rotation_for_world(foot_snapshot.parent_rotation, bounded_world)
421:                 {
422:                     if let Ok(mut transform) = transforms.p1().get_mut(foot) {
423:                         transform.rotation = local;
424:                     }
425:                     resolved.foot = local;
426:                 }
427:                 bounded_world
428:             } else {
429:                 desired_world
430:             };
431:             if contact_blend_active
432:                 && final_world.angle_between(desired_world) <= 0.001_f32.to_radians()
433:             {
434:                 if foot_side == LeadFoot::Left {
435:                     memory.left_contact_orientation_blend_active = false;
436:                 } else {
437:                     memory.right_contact_orientation_blend_active = false;
438:                 }
439:             }
440:             if foot_side == LeadFoot::Left {
441:                 memory.left_foot_orientation_world = Some(final_world);
442:             } else {
443:                 memory.right_foot_orientation_world = Some(final_world);
444:             }
445:         }
446:         if foot_side == LeadFoot::Left {
447:             memory.left_rotation_chain = Some(resolved);
448:         } else {
449:             memory.right_rotation_chain = Some(resolved);
450:         }
451:     }
452:     Ok(())
453: }
454: 
455: pub(in crate::animation::procedural) fn final_leg_rotation_chain(
456:     cached: Option<LegRotationChain>,
457:     current: LegRotationChain,
458:     evaluation_advances: bool,
459: ) -> LegRotationChain {
460:     if evaluation_advances {
461:         current
462:     } else {
463:         cached.unwrap_or(current)
464:     }
465: }
466: 
467: pub(in crate::animation::procedural) fn local_rotation_for_world(
468:     parent_world: Quat,
469:     desired_world: Quat,
470: ) -> Option<Quat> {
471:     let local = parent_world.inverse() * desired_world;
472:     if local.is_finite() {
473:         Some(local.normalize())
474:     } else {
475:         None
476:     }
477: }
478: 
479: pub(in crate::animation::procedural) fn clear_slope_rotation_cache(memory: &mut LegIkMemory) {
480:     memory.left_rotation_chain = None;
481:     memory.right_rotation_chain = None;
482:     memory.slope_alignment_mode = None;
483: }
484: 
485: pub(in crate::animation::procedural) fn prepare_slope_rotation_cache(
486:     memory: &mut LegIkMemory,
487:     mode: SlopeAlignmentMode,
488: ) {
489:     if memory.slope_alignment_mode != Some(mode) {
490:         clear_slope_rotation_cache(memory);
491:         memory.slope_alignment_mode = Some(mode);
492:     }
493: }
494: 
495: pub(in crate::animation::procedural) fn slope_aligned_world_rotation(
496:     current_world: Quat,
497:     sole_up_local: Vec3,
498:     terrain_normal: Dir3,
499: ) -> Option<Quat> {
500:     let normal = (*terrain_normal).try_normalize()?;
501:     let tilt_angle = Vec3::Y.angle_between(normal).min(28.0_f32.to_radians());
502:     let bounded_normal = Vec3::Y
503:         .cross(normal)
504:         .try_normalize()
505:         .map_or(Vec3::Y, |axis| {
506:             Quat::from_axis_angle(axis, tilt_angle) * Vec3::Y
507:         });
508:     let current_up = (current_world * sole_up_local).try_normalize()?;
509:     let correction = Quat::from_rotation_arc(current_up, bounded_normal);
510:     Some((correction * current_world).normalize())
511: }
512: 
513: fn previous_foot_orientation(
514:     memory: &LegIkMemory,
515:     foot: LeadFoot,
516:     just_released: bool,
517: ) -> Option<Quat> {
518:     let (current, rendered) = if foot == LeadFoot::Left {
519:         (
520:             memory.left_foot_orientation_world,
521:             memory.left_last_rendered_foot_rotation_world,
522:         )
523:     } else {
524:         (
525:             memory.right_foot_orientation_world,
