1: //! Final standing leg constraints and rendered knee/foot yaw measurement.
2: 
3: use super::*;
4: 
5: #[derive(Clone, Copy)]
6: struct KneeYawLeg {
7:     upper: BoneRole,
8:     lower: BoneRole,
9:     foot: BoneRole,
10:     side: LeadFoot,
11: }
12: 
13: impl KneeYawLeg {
14:     const LEFT: Self = Self {
15:         upper: BoneRole::ThighLeft,
16:         lower: BoneRole::ShinLeft,
17:         foot: BoneRole::FootLeft,
18:         side: LeadFoot::Left,
19:     };
20:     const RIGHT: Self = Self {
21:         upper: BoneRole::ThighRight,
22:         lower: BoneRole::ShinRight,
23:         foot: BoneRole::FootRight,
24:         side: LeadFoot::Right,
25:     };
26: 
27:     fn constrain(
28:         self,
29:         rig: &HumanoidRig,
30:         frame: ObservedRigFrame,
31:         parents: &Query<&ChildOf>,
32:         transforms: &mut ParamSet<(TransformHelper, Query<&mut Transform>)>,
33:     ) -> AnimationValueResult<Option<AngularMagnitudeDegrees>> {
34:         let (Some(&upper), Some(&lower), Some(&foot)) = (
35:             rig.get(&self.upper),
36:             rig.get(&self.lower),
37:             rig.get(&self.foot),
38:         ) else {
39:             return Ok(None);
40:         };
41:         let Some((upper_snapshot, lower_snapshot, foot_snapshot)) =
42:             snapshot_chain(upper, lower, foot, parents, &transforms.p0())
43:         else {
44:             return Ok(None);
45:         };
46:         let hip = upper_snapshot.global.translation();
47:         let knee = lower_snapshot.global.translation();
48:         let target = foot_snapshot.global.translation();
49:         let segments = match LimbSegments::measure(hip, knee, target) {
50:             Ok(segments) => segments,
51:             Err(error) => {
52:                 warn!(%error, "IK segment measurement rejected");
53:                 return Ok(None);
54:             }
55:         };
56:         let leg_direction = (target - hip).normalize_or_zero();
57:         let side = anatomical_side(frame.rotation(), frame.origin(), hip, self.side);
58:         let canonical = pole_to_world(frame.rotation(), canonical_knee_pole(side));
59:         let current_bend = (knee - hip)
60:             .reject_from_normalized(leg_direction)
61:             .try_normalize()
62:             .unwrap_or(canonical);
63:         let pole = constrain_rendered_leg_pole(
64:             rig,
65:             self.side,
66:             hip,
67:             target,
68:             target,
69:             current_bend,
70:             parents,
71:             &transforms.p0(),
72:         );
73:         let Some(solution) = solve_two_bone_with_reach(
74:             TwoBoneChain::new(hip, knee, target, segments.upper, segments.lower, pole),
75:             target,
76:             maximum_reach(segments.upper, segments.lower),
77:         ) else {
78:             return Ok(None);
79:         };
80:         apply_two_bone_solution(upper, lower, foot, solution, parents, transforms);
81:         self.rendered_offset(rig, [upper, lower, foot], parents, &transforms.p0())
82:     }
83: 
84:     fn rendered_offset(
85:         self,
86:         rig: &HumanoidRig,
87:         [upper, lower, foot]: [Entity; 3],
88:         parents: &Query<&ChildOf>,
89:         transforms: &TransformHelper,
90:     ) -> AnimationValueResult<Option<AngularMagnitudeDegrees>> {
91:         if let Some((final_upper, final_lower, final_foot)) =
92:             snapshot_chain(upper, lower, foot, parents, transforms)
93:             && let Some(end_direction) =
94:                 (final_foot.global.translation() - final_upper.global.translation()).try_normalize()
95:             && let Some(bend) = (final_lower.global.translation()
96:                 - final_upper.global.translation())
97:             .reject_from_normalized(end_direction)
98:             .xz()
99:             .try_normalize()
100:             && let Some(facing) = rendered_foot_facing(
101:                 rig,
102:                 self.side,
103:                 final_foot.global.translation(),
104:                 parents,
105:                 transforms,
106:             )
107:             .and_then(|facing| facing.xz().try_normalize())
108:         {
109:             return AngularMagnitudeDegrees::from_degrees(bend.angle_to(facing).abs().to_degrees())
110:                 .map(Some);
111:         }
112:         Ok(None)
113:     }
114: }
115: 
116: /// Apply the standing foot-facing constraint after the earlier pose owners.
117: pub(in crate::animation) fn enforce_anatomical_knee_yaw(
118:     owners: Query<&PresentedSkeleton>,
119:     rigs: Query<(Entity, &HumanoidRig)>,
120:     parents: Query<&ChildOf>,
121:     mut states: Query<&mut LegIkState>,
122:     mut transforms: ParamSet<(TransformHelper, Query<&mut Transform>)>,
123: ) {
124:     for (owner, rig) in &rigs {
125:         let Ok(skeleton) = owners.get(owner) else {
126:             continue;
127:         };
128:         // Downed and posture-transition poses retain their authored knee planes.
129:         if !anatomical_knee_yaw_posture_is_valid(skeleton) {
130:             continue;
131:         }
132:         let mut final_offsets = [AngularMagnitudeDegrees::ZERO; 2];
133:         let frame = match ObservedRigFrame::resolve(rig, &transforms.p0()) {
134:             Ok(Some(frame)) => frame,
135:             Ok(None) => continue,
136:             Err(error) => {
137:                 warn!(%error, ?owner, "Rejected knee-yaw rig frame");
138:                 continue;
139:             }
140:         };
141:         for (leg_index, leg) in [KneeYawLeg::LEFT, KneeYawLeg::RIGHT]
142:             .into_iter()
143:             .enumerate()
144:         {
145:             match leg.constrain(rig, frame, &parents, &mut transforms) {
146:                 Ok(Some(offset)) => final_offsets[leg_index] = offset,
147:                 Ok(None) => {}
148:                 Err(error) => {
149:                     warn!(%error, "knee-foot yaw offset rejected");
150:                     continue;
151:                 }
152:             }
153:         }
154:         if let Ok(mut state) = states.get_mut(owner) {
155:             state.0.left_knee_foot_yaw_offset_degrees = final_offsets[0];
156:             state.0.right_knee_foot_yaw_offset_degrees = final_offsets[1];
157:         }
158:     }
159: }
160: 
161: pub(in crate::animation::procedural) fn anatomical_knee_yaw_posture_is_valid(
162:     skeleton: &SkeletonState,
163: ) -> bool {
164:     !skeleton.body().is_downed() && !skeleton.is_posture_transitioning() && !skeleton.is_quickstep()
165: }
