188:         match self.step {
189:             GuardStepState::Uninitialized => None,
190:             GuardStepState::Stationary { next, .. } => Some(opposite_guard_foot(next)),
191:             GuardStepState::LeftSwing { .. } => Some(LeadFoot::Right),
192:             GuardStepState::RightSwing { .. } => Some(LeadFoot::Left),
