197: impl GuardTargetRequest {
198:     /// When the body catches a visual swing, reserve its authored forward room.
199:     pub(super) fn keep_swing_ahead(
200:         &mut self,
201:         skeleton: &SkeletonState,
202:         frame: ObservedRigFrame,
203:         hip_center: Vec3,
204:     ) {
205:         if let Some(step) = skeleton.raised_footwork().step() {
206:             let local_direction = step.direction();
207:             let planned_direction = (frame.rotation()
208:                 * Vec3::new(local_direction.x, 0.0, local_direction.y))
209:             .with_y(0.0)
210:             .normalize_or_zero();
211:             let physical_direction = skeleton.world_velocity.with_y(0.0).normalize_or_zero();
212:             let direction = if physical_direction == Vec3::ZERO {
213:                 planned_direction
214:             } else {
215:                 physical_direction
216:             };
217:             if direction != Vec3::ZERO {
218:                 let support = match step.swing_foot() {
219:                     LeadFoot::Left => self.right,
220:                     LeadFoot::Right => self.left,
221:                 };
222:                 let swing = match step.swing_foot() {
223:                     LeadFoot::Left => &mut self.left,
224:                     LeadFoot::Right => &mut self.right,
225:                 };
226:                 let shortfall =
227:                     hip_center.dot(direction) - support.dot(direction).max(swing.dot(direction));
228:                 if shortfall > 0.0 {
229:                     *swing += direction * shortfall;
230:                 }
231:             }
232:         }
233:     }
234: }
