257: pub(in crate::animation::procedural) fn safer_guard_reacquire_foot(
258:     current_left: Vec3,
259:     current_right: Vec3,
260:     desired_left: Vec3,
261:     desired_right: Vec3,
262:     fallback: LeadFoot,
263: ) -> LeadFoot {
264:     let left_first_clearance = desired_left.xz().distance(current_right.xz());
265:     let right_first_clearance = desired_right.xz().distance(current_left.xz());
266:     if (left_first_clearance - right_first_clearance).abs() <= 0.001 {
267:         fallback
268:     } else if left_first_clearance > right_first_clearance {
269:         LeadFoot::Left
270:     } else {
271:         LeadFoot::Right
272:     }
