275: pub(in crate::animation::procedural) fn guard_swing_target(swing: GuardSwing) -> Vec3 {
276:     let progress = smootherstep01(swing.progress.fraction());
277:     let mut target = swing.start.lerp(swing.end, progress);
278:     target.y += (std::f32::consts::PI * progress).sin() * 0.10;
279:     target
