282: /// Keep stationary combat feet fixed in world space while the owner turns.
283: /// Once the rotating authored stance pulls a plant beyond the pole/reach
284: /// corridor, lift exactly one foot through the existing guard swing and place
285: /// it at the new authored stance target. Translating authored locomotion never
286: /// enters this path and is therefore allowed to slide instead of inventing
287: /// extra up/down foot motion.
288: pub(in crate::animation::procedural) fn advance_stationary_turn_step(
289:     current: GuardStepState,
290:     requested: GuardStepState,
291:     delta_seconds: AnimationElapsed,
292: ) -> AnimationValueResult<GuardStepState> {
293:     let GuardStepState::Stationary {
294:         left: desired_left,
295:         right: desired_right,
296:         next: _requested_next,
297:     } = requested
298:     else {
299:         return Ok(requested);
300:     };
301:     Ok(match current {
302:         GuardStepState::Uninitialized => requested,
303:         GuardStepState::Stationary { left, right, next } => {
304:             // Pole-limit stepping responds to horizontal stance displacement.
305:             // Pose-buffer/terrain settling may move the requested ankle height
306:             // after touchdown; treating that vertical correction as another
307:             // reach violation immediately relaunches the foot that just landed.
308:             let left_exceeded = left.xz().distance(desired_left.xz())
309:                 > ik_tuning().stationary_turn_foot_limit_metres.metres();
310:             let right_exceeded = right.xz().distance(desired_right.xz())
311:                 > ik_tuning().stationary_turn_foot_limit_metres.metres();
312:             let swing = match (left_exceeded, right_exceeded, next) {
313:                 (false, false, _) => return Ok(GuardStepState::Stationary { left, right, next }),
314:                 (true, false, _) => LeadFoot::Left,
315:                 (false, true, _) => LeadFoot::Right,
316:                 (true, true, next) => next,
317:             };
318:             match swing {
319:                 LeadFoot::Left => GuardStepState::LeftSwing {
320:                     right_support: right,
321:                     left: GuardSwing {
322:                         start: left,
323:                         end: desired_left,
324:                         progress: UnitInterval::ZERO,
325:                     },
326:                 },
327:                 LeadFoot::Right => GuardStepState::RightSwing {
328:                     left_support: left,
329:                     right: GuardSwing {
330:                         start: right,
331:                         end: desired_right,
332:                         progress: UnitInterval::ZERO,
333:                     },
334:                 },
335:             }
336:         }
337:         GuardStepState::LeftSwing {
338:             right_support,
339:             mut left,
340:         } => {
341:             left.end = desired_left;
342:             left.progress = ik_tuning()
343:                 .stationary_turn_step_seconds
344:                 .advance_guard(left.progress, delta_seconds)?;
345:             if left.progress == UnitInterval::ONE {
346:                 GuardStepState::Stationary {
347:                     left: left.end,
348:                     right: right_support,
349:                     next: LeadFoot::Right,
350:                 }
351:             } else {
352:                 GuardStepState::LeftSwing {
353:                     right_support,
354:                     left,
355:                 }
356:             }
357:         }
358:         GuardStepState::RightSwing {
359:             left_support,
360:             mut right,
361:         } => {
362:             right.end = desired_right;
363:             right.progress = ik_tuning()
364:                 .stationary_turn_step_seconds
365:                 .advance_guard(right.progress, delta_seconds)?;
366:             if right.progress == UnitInterval::ONE {
367:                 GuardStepState::Stationary {
368:                     left: left_support,
369:                     right: right.end,
370:                     next: LeadFoot::Left,
371:                 }
372:             } else {
373:                 GuardStepState::RightSwing {
374:                     left_support,
375:                     right,
376:                 }
377:             }
378:         }
379:     })
380: }
