382: pub(in crate::animation::procedural) fn validate_guard_frame_targets(
383:     requested: GuardTargetRequest,
384:     geometry: [GuardLegGeometry; 2],
385:     swing_foot: Option<LeadFoot>,
386: ) -> Option<ValidatedGuardTargets> {
387:     if !requested.left.is_finite()
388:         || !requested.right.is_finite()
389:         || geometry.iter().any(|leg| {
390:             !leg.hip.is_finite()
391:                 || leg
392:                     .maximum_reach
393:                     .native_metres()
394:                     .is_none_or(|reach| !reach.is_finite())
395:         })
396:     {
397:         return None;
398:     }
399:     let targets = GuardTargetRequest {
400:         left: if swing_foot == Some(LeadFoot::Left) {
401:             constrain_guard_swing_to_reach(requested.left, geometry[0])?
402:         } else {
403:             requested.left
404:         },
405:         right: if swing_foot == Some(LeadFoot::Right) {
406:             constrain_guard_swing_to_reach(requested.right, geometry[1])?
407:         } else {
408:             requested.right
409:         },
410:     };
411:     if !targets.left.is_finite() || !targets.right.is_finite() {
412:         return None;
413:     }
414:     Some(ValidatedGuardTargets {
415:         targets,
416:         adjusted_for_reach: targets.left != requested.left || targets.right != requested.right,
417:     })
418: }
419: 
420: /// Keeps the horizontal swing path monotonic even when the current hip has not
421: /// yet travelled close enough to reach a ground-level sample. Radial projection
422: /// shortens XZ as well as Y, which makes an ankle pause and then catch up near
423: /// contact. Lifting the airborne sample spends the available reach vertically
424: /// and lets it descend naturally as the hip approaches. Only a target whose
425: /// horizontal offset alone exceeds the whole leg falls back to radial clamping.
426: pub(in crate::animation::procedural) fn constrain_guard_swing_to_reach(
427:     target: Vec3,
428:     geometry: GuardLegGeometry,
429: ) -> Option<Vec3> {
430:     let maximum_reach = geometry.maximum_reach.native_metres()?.max(0.0);
431:     let offset = target - geometry.hip;
432:     let horizontal_distance_squared = offset.x * offset.x + offset.z * offset.z;
433:     let reach_squared = maximum_reach * maximum_reach;
434:     if horizontal_distance_squared > reach_squared {
435:         let vertical = target.y - geometry.hip.y;
436:         let horizontal_reach = (maximum_reach * maximum_reach - vertical * vertical)
437:             .max(0.0)
438:             .sqrt();
439:         let horizontal = (target - geometry.hip)
440:             .xz()
441:             .clamp_length_max(horizontal_reach);
442:         return Some(Vec3::new(
443:             geometry.hip.x + horizontal.x,
444:             target.y,
445:             geometry.hip.z + horizontal.y,
446:         ));
447:     }
448: 
449:     let vertical_reach = (reach_squared - horizontal_distance_squared)
450:         .max(0.0)
451:         .sqrt();
452:     Some(Vec3::new(
453:         target.x,
454:         target.y.clamp(
455:             geometry.hip.y - vertical_reach,
456:             geometry.hip.y + vertical_reach,
457:         ),
458:         target.z,
459:     ))
460: }
461: 
462: pub(in crate::animation::procedural) fn anatomical_side(
463:     rig_rotation: Quat,
464:     rig_origin: Vec3,
465:     hip: Vec3,
466:     foot_side: LeadFoot,
467: ) -> FootTrackSide {
468:     let hip_x = (rig_rotation.inverse() * (hip - rig_origin)).x;
469:     if hip_x.abs() > 0.001 {
470:         FootTrackSide::from_native_x(hip_x)
471:     } else {
472:         FootTrackSide::for_foot(foot_side)
473:     }
474: }
