476: pub(in crate::animation::procedural) fn constrain_foot_to_track(
477:     world: Vec3,
478:     rig_origin: Vec3,
479:     rig_rotation: Quat,
480:     side: FootTrackSide,
481: ) -> Vec3 {
482:     let mut local = rig_rotation.inverse() * (world - rig_origin);
483:     let signed_x = (local.x * side.coefficient()).clamp(
484:         foot_track_inner_metres().metres(),
485:         ik_tuning().outer_foot_track_metres.metres(),
486:     );
487:     local.x = signed_x * side.coefficient();
488:     rig_origin + rig_rotation * local
489: }
490: pub(in crate::animation::procedural) fn terrain_conformed_guard_target(
491:     mut flat_target: Vec3,
492:     terrain_height: Option<SupportElevation>,
493: ) -> Vec3 {
494:     if let Some(height) = terrain_height {
495:         flat_target.y = height.metres() + measured_ankle_sole_offset_metres().metres();
496:     }
497:     flat_target
498: }

1: //! Checked limb dimensions retain the reach policy up to native geometry.
2: 
3: use super::*;
4: 
5: /// The two measured segment lengths from one immutable native chain snapshot.
6: #[derive(Debug, Clone, Copy)]
7: pub(in crate::animation::procedural) struct LimbSegments {
8:     pub(in crate::animation::procedural) upper: NonnegativeLength,
9:     pub(in crate::animation::procedural) lower: NonnegativeLength,
10: }
11: 
12: /// Reach is an operation on admitted segment geometry, not an eagerly stored
13: /// scalar. The native law-of-cosines intermediate may overflow before a later
14: /// clamp produces a valid finite target; it is never retained as a measurement.
15: #[derive(Debug, Clone, Copy)]
16: pub(in crate::animation::procedural) enum ReachLimit {
17:     Fixed(NonnegativeLength),
18:     Flexed {
19:         upper: NonnegativeLength,
20:         lower: NonnegativeLength,
21:         minimum_flexion: SignedAngleDegrees,
22:     },
23:     Extended {
24:         upper: NonnegativeLength,
25:         lower: NonnegativeLength,
26:     },
27:     Landing {
28:         upper: NonnegativeLength,
29:         lower: NonnegativeLength,
30:         authored: NonnegativeLength,
31:         compression: HeightDistance,
32:     },
33: }
34: 
35: impl From<NonnegativeLength> for ReachLimit {
36:     fn from(length: NonnegativeLength) -> Self {
37:         Self::Fixed(length)
38:     }
39: }
40: 
41: impl LimbSegments {
42:     pub(in crate::animation::procedural) fn measure(
43:         root: Vec3,
44:         knee: Vec3,
45:         end: Vec3,
46:     ) -> AnimationValueResult<Self> {
47:         let upper = NonnegativeLength::from_arithmetic(root.distance(knee))?;
48:         let lower = NonnegativeLength::from_arithmetic(knee.distance(end))?;
49:         Ok(Self { upper, lower })
50:     }
51: }
52: 
53: impl ReachLimit {
54:     /// Terrain confidence weights the geometric correction before the shared
55:     /// quarter-metre downward cap. Only the completed offset is retained.
56:     pub(super) fn terrain_pelvis_shift(
57:         self,
58:         upper: Vec3,
59:         target: Vec3,
60:         weight: UnitInterval,
61:     ) -> AnimationValueResult<SignedLength> {
62:         SignedLength::from_metres(
63:             (self.vertical_correction(upper, target).ok_or(
64:                 AnimationValueError::InvertedBounds {
65:                     quantity: AnimationQuantity::Length,
66:                 },
67:             )? * weight.fraction())
68:             .clamp(-0.25, 0.0),
69:         )
70:         .map_err(|_| AnimationValueError::Overflow {
71:             quantity: AnimationQuantity::HeightOffset,
72:         })
73:     }
74: 
75:     /// Ordinary authored IK clamps its geometric correction before weighting.
76:     pub(super) fn ordinary_pelvis_shift(
77:         self,
78:         upper: Vec3,
79:         target: Vec3,
80:         maximum_drop: NonnegativeLength,
81:         weight: UnitInterval,
82:     ) -> AnimationValueResult<SignedLength> {
83:         SignedLength::from_metres(
84:             self.vertical_correction(upper, target)
85:                 .ok_or(AnimationValueError::InvertedBounds {
86:                     quantity: AnimationQuantity::Length,
87:                 })?
88:                 .clamp(-maximum_drop.metres(), 0.0)
89:                 * weight.fraction(),
90:         )
91:         .map_err(|_| AnimationValueError::Overflow {
92:             quantity: AnimationQuantity::HeightOffset,
93:         })
94:     }
95: 
96:     fn vertical_correction(self, upper: Vec3, target: Vec3) -> Option<f32> {
97:         let reach = self.native_metres()?;
98:         let horizontal_distance = (target - upper).xz().length();
99:         let maximum_vertical = (reach * reach - horizontal_distance * horizontal_distance)
100:             .max(0.0)
101:             .sqrt();
102:         Some(target.y + maximum_vertical - upper.y)
103:     }
104: 
105:     /// Native coefficient only for the complete distance/projection/analytic
106:     /// solve kernels. An unordered landing interval has no supported solution;
107:     /// callers validate their completed target or owned result.
108:     pub(in crate::animation::procedural) fn native_metres(self) -> Option<f32> {
109:         Some(match self {
110:             Self::Fixed(length) => length.metres(),
111:             Self::Flexed {
112:                 upper,
113:                 lower,
114:                 minimum_flexion,
115:             } => {
116:                 let (upper, lower) = (upper.metres(), lower.metres());
117:                 (upper * upper
118:                     + lower * lower
119:                     + 2.0 * upper * lower * minimum_flexion.radians().cos())
120:                 .sqrt()
121:             }
122:             Self::Extended { upper, lower } => upper.metres() + lower.metres() - 0.0001,
123:             Self::Landing {
124:                 upper,
125:                 lower,
126:                 authored,
127:                 compression,
128:             } => {
129:                 let reserved = maximum_reach(upper, lower).native_metres()?;
130:                 let full = upper.metres() + lower.metres() - 0.0001;
131:                 if reserved > full || reserved.is_nan() || full.is_nan() {
132:                     return None;
133:                 }
134:                 let released = authored.metres().clamp(reserved, full);
135:                 let weight = smoothstep(
136:                     ik_tuning()
137:                         .landing_knee_reserve_release_compression_metres
138:                         .metres(),
139:                     ik_tuning()
140:                         .landing_knee_reserve_full_compression_metres
141:                         .metres(),
142:                     compression.metres(),
143:                 );
144:                 released.lerp(reserved, weight)
145:             }
146:         })
147:     }
148: }

1: //! Stop/restart balance capture and terminal contact convergence.
2: 
3: use super::*;
4: pub(in crate::animation::procedural) use planning::{
5:     balance_recovery_direction, plan_settle_landing, projected_capture_point, settle_swing_side,
6: };
7: mod planning;
8: 
9: // Returning the raised pelvis consumes about 2 cm of the knee's 10 cm frame
10: // budget. Reserve that motion only for the raised-to-settle handoff; ordinary
11: // swing and settle targets retain the faster general cap.
12: 
13: pub(in crate::animation::procedural) fn preserve_raised_handoff_targets(
14:     memory: &mut LegIkMemory,
15:     raised: RaisedFootworkState,
16:     rig_origin: Vec3,
17:     rig_rotation: Quat,
18: ) {
19:     let retained = raised.step.retained_targets();
20:     let left = raised
21:         .left_solve_target
22:         .or_else(|| retained.map(|targets| targets.0));
23:     let right = raised
24:         .right_solve_target
25:         .or_else(|| retained.map(|targets| targets.1));
26:     let (Some(left), Some(right)) = (left, right) else {
27:         return;
28:     };
29:     memory.left_foot_world_target = Some(left);
30:     memory.right_foot_world_target = Some(right);
31:     memory.left_foot_target = Some(rig_rotation.inverse() * (left - rig_origin));
32:     memory.right_foot_target = Some(rig_rotation.inverse() * (right - rig_origin));
33:     memory.left_release_active = true;
34:     memory.right_release_active = true;
35:     memory.left_release_target = None;
36:     memory.right_release_target = None;
37: }
