39: pub(in crate::animation::procedural) fn terrain_ik_is_required(
40:     mode: crate::animation::TerrainIkMode,
41:     settle_active: bool,
42:     raised_handoff: bool,
43: ) -> bool {
44:     mode.is_enabled() || settle_active || raised_handoff
