47: pub(in crate::animation::procedural) fn advance_settle_state(
48:     mut settle: LocomotionSettleState,
49:     delta_seconds: AnimationElapsed,
50: ) -> AnimationValueResult<LocomotionSettleState> {
51:     settle.elapsed_seconds = settle.elapsed_seconds.checked_add(delta_seconds)?;
52:     settle.progress = ik_tuning()
53:         .settle_step_seconds
54:         .advance_settle(settle.progress, delta_seconds)?;
55:     Ok(settle)
