58: pub(in crate::animation::procedural) fn cancel_settle_for_restart(
59:     memory: &mut LegIkMemory,
60:     planar_velocity: Vec3,
61: ) {
62:     // A stop can be cancelled while its selected support is still airborne.
63:     // In that case the retained terrain plant is only a future landing goal,
64:     // not support ownership. Resume gait from the last propagated ankle the
65:     // player actually saw; otherwise the first restart sample can snap from
66:     // the clearance follower directly to the stale settle contact.
67:     for left in [true, false] {
68:         let acquired = if left {
69:             memory.left_foot_plant.is_acquired()
70:         } else {
71:             memory.right_foot_plant.is_acquired()
72:         };
73:         if acquired {
74:             continue;
75:         }
76:         let (rendered_world, rendered_owner) = if left {
77:             (
78:                 memory.left_last_rendered_world,
79:                 memory.left_last_rendered_owner,
80:             )
81:         } else {
82:             (
83:                 memory.right_last_rendered_world,
84:                 memory.right_last_rendered_owner,
85:             )
86:         };
87:         if left {
88:             memory.left_foot_plant = FootPlant::Absent;
89:             memory.left_foot_world_target = rendered_world.or(memory.left_foot_world_target);
90:             memory.left_foot_target = rendered_owner.or(memory.left_foot_target);
91:             memory.left_support_weight = Some(UnitInterval::ZERO);
92:             memory.left_transition_support_weight = Some(UnitInterval::ZERO);
93:             memory.left_release_active = true;
94:             memory.left_release_target = None;
95:         } else {
96:             memory.right_foot_plant = FootPlant::Absent;
97:             memory.right_foot_world_target = rendered_world.or(memory.right_foot_world_target);
98:             memory.right_foot_target = rendered_owner.or(memory.right_foot_target);
99:             memory.right_support_weight = Some(UnitInterval::ZERO);
100:             memory.right_transition_support_weight = Some(UnitInterval::ZERO);
101:             memory.right_release_active = true;
102:             memory.right_release_target = None;
103:         }
104:     }
105:     memory.settle = None;
106:     reset_terminal_settle_reach(memory);
107:     memory.recent_movement_velocity = planar_velocity.with_y(0.0);
108: }
109: 
110: pub(in crate::animation::procedural) fn reset_terminal_settle_reach(memory: &mut LegIkMemory) {
111:     memory.terminal_contacts = TerminalContacts::Inactive;
112: }
113: 
114: pub(in crate::animation::procedural) fn finish_settle_for_idle(memory: &mut LegIkMemory) {
115:     let terminal_reach_shift = memory.terminal_contacts.shift();
116:     memory.settle = None;
117:     reset_terminal_settle_reach(memory);
118:     // The next sparse authored-idle evaluation restores the uncorrected rig
119:     // root. Transfer the converged terminal reach offset to ordinary retained
120:     // pelvis ownership so both frozen contacts remain reachable instead of
121:     // dropping one support and starting another settle loop.
122:     memory.pelvis_shift = terminal_reach_shift;
123:     memory.recent_movement_velocity = Vec3::ZERO;
124:     // Promote both final solve targets to a stable idle stance. Clearing them
125:     // here made the next authored-idle evaluation pull a wide settled step
126:     // half a metre under the body in one frame. Movement restart still releases
127:     // these plants through the ordinary bounded gait handoff.
128:     memory.left_foot_plant = FootPlant::retain(memory.left_foot_world_target, true);
129:     memory.right_foot_plant = FootPlant::retain(memory.right_foot_world_target, true);
130:     memory.left_planned_contact = None;
131:     memory.right_planned_contact = None;
132:     memory.left_planned_contact_start = None;
133:     memory.right_planned_contact_start = None;
134:     memory.left_planned_contact_phase_start = None;
135:     memory.right_planned_contact_phase_start = None;
136:     memory.left_support_weight = Some(UnitInterval::ONE);
137:     memory.right_support_weight = Some(UnitInterval::ONE);
138:     memory.left_transition_support_weight = Some(UnitInterval::ONE);
139:     memory.right_transition_support_weight = Some(UnitInterval::ONE);
140:     memory.left_support_exhausted_until_flight = false;
141:     memory.right_support_exhausted_until_flight = false;
142:     memory.left_release_active = false;
143:     memory.right_release_active = false;
144:     memory.left_release_target = None;
145:     memory.right_release_target = None;
146: }
