148: pub(in crate::animation::procedural) fn settle_is_terminal(memory: &LegIkMemory) -> bool {
149:     memory
150:         .settle
151:         .is_some_and(|settle| settle.progress.is_complete())
152:         && !memory.left_release_active
153:         && !memory.right_release_active
