156: pub(in crate::animation::procedural) fn prepare_terminal_settle_contacts(
157:     memory: &mut LegIkMemory,
158:     rig_origin: Vec3,
159:     rig_rotation: Quat,
160:     terrain_height_at: impl Fn(ScenePlanPoint) -> Option<SupportElevation>,
161: ) -> bool {
162:     if !memory.terminal_contacts.is_prepared() {
163:         // Terminal solve changes from ordinary pelvis ownership to an
164:         // absolute rig-root correction. Seed it from the correction already
165:         // visible on the final settle sample; starting from zero restores the
166:         // authored root for one frame and lifts the whole hierarchy by the
167:         // accumulated settle drop.
168:         memory.terminal_contacts.seed(memory.pelvis_shift);
169:     }
170:     let left_seed = if memory.terminal_contacts.is_prepared() {
171:         memory.left_foot_world_target
172:     } else {
173:         memory
174:             .left_last_rendered_world
175:             .filter(|target| target.is_finite())
176:             .or(memory.left_foot_world_target)
177:     };
178:     let Some(mut left) = left_seed else {
179:         return false;
180:     };
181:     let right_seed = if memory.terminal_contacts.is_prepared() {
182:         memory.right_foot_world_target
183:     } else {
184:         memory
185:             .right_last_rendered_world
186:             .filter(|target| target.is_finite())
187:             .or(memory.right_foot_world_target)
188:     };
189:     let Some(mut right) = right_seed else {
190:         return false;
191:     };
192:     let (Some(left_point), Some(right_point)) = (
193:         ScenePlanPoint::from_metres(left.xz()),
194:         ScenePlanPoint::from_metres(right.xz()),
195:     ) else {
196:         return false;
197:     };
198:     let (Some(left_height), Some(right_height)) = (
199:         terrain_height_at(left_point),
200:         terrain_height_at(right_point),

201:     ) else {
202:         return false;
203:     };
204:     left.y = left_height.metres() + measured_ankle_sole_offset_metres().metres();
205:     right.y = right_height.metres() + measured_ankle_sole_offset_metres().metres();
206:     memory.left_foot_world_target = Some(left);
207:     memory.right_foot_world_target = Some(right);
208:     memory.left_foot_target = Some(rig_rotation.inverse() * (left - rig_origin));
209:     memory.right_foot_target = Some(rig_rotation.inverse() * (right - rig_origin));
210:     memory.left_foot_plant = FootPlant::Acquiring(left);
211:     memory.right_foot_plant = FootPlant::Acquiring(right);
212:     if let Some(settle) = memory.settle.as_mut() {
213:         settle.landing_target = if settle.support_foot == LeadFoot::Left {
214:             right
215:         } else {
216:             left
217:         };
218:     }
219:     memory.terminal_contacts.prepare();
220:     true
221: }
