223: pub(in crate::animation::procedural) fn terminal_settle_contacts_are_rendered(
224:     memory: &LegIkMemory,
225:     terrain_height_at: impl Fn(ScenePlanPoint) -> Option<SupportElevation>,
226: ) -> bool {
227:     [
228:         (
229:             memory.left_last_rendered_world,
230:             memory.left_foot_world_target,
231:             memory.left_last_rendered_toe_world,
232:         ),
233:         (
234:             memory.right_last_rendered_world,
235:             memory.right_foot_world_target,
236:             memory.right_last_rendered_toe_world,
237:         ),
238:     ]
239:     .into_iter()
240:     .all(|(rendered, target, toe)| {
241:         rendered
242:             .zip(target)
243:             .zip(toe)
244:             .is_some_and(|((rendered, target), toe)| {
245:                 let Some(ankle_point) = ScenePlanPoint::from_metres(rendered.xz()) else {
246:                     return false;
247:                 };
248:                 let Some(toe_point) = ScenePlanPoint::from_metres(toe.xz()) else {
249:                     return false;
250:                 };
251:                 rendered.xz().distance(target.xz()) <= 0.01
252:                     && terrain_height_at(ankle_point).is_some_and(|height| {
253:                         (rendered.y
254:                             - height.metres()
255:                             - measured_ankle_sole_offset_metres().metres())
256:                         .abs()
257:                             <= 0.01
258:                     })
259:                     && terrain_height_at(toe_point).is_some_and(|height| {
260:                         let clearance = toe.y - height.metres();
261:                         (-0.01..=0.10).contains(&clearance)
262:                     })
263:             })
264:     })
265: }
