292:     if let Some(right) = right.filter(|target| target.is_finite()) {
293:         memory.right_foot_world_target = Some(right);
294:         memory.right_foot_target = Some(rig_rotation.inverse() * (right - rig_origin));
295:         memory.right_foot_plant = FootPlant::Absent;
