333: pub(in crate::animation::procedural) fn settle_stance_is_safe(
334:     projected_com: Vec3,
335:     left_foot: Option<Vec3>,
336:     right_foot: Option<Vec3>,
337:     terrain: &SceneTerrain,
338: ) -> bool {
339:     let (Some(left), Some(right)) = (left_foot, right_foot) else {
340:         return false;
341:     };
342:     let at_contact = |foot: Vec3| {
343:         ScenePlanPoint::from_metres(foot.xz())
344:             .and_then(|point| terrain.height_at(point))
345:             .is_some_and(|height| sole_is_at_contact(foot.y, height))
346:     };
347:     if !at_contact(left) || !at_contact(right) {
348:         return false;
349:     }
350:     let segment = right.xz() - left.xz();
351:     let progress = if segment.length_squared() > 0.000001 {
352:         ((projected_com.xz() - left.xz()).dot(segment) / segment.length_squared()).clamp(0.0, 1.0)
353:     } else {
354:         0.0
355:     };
356:     projected_com.xz().distance(left.xz() + segment * progress) <= 0.18
357: }
358: 
359: pub(in crate::animation::procedural) fn sole_is_at_contact(
360:     ankle_y: f32,
361:     terrain_height: SupportElevation,
362: ) -> bool {
363:     (ankle_y - terrain_height.metres() - measured_ankle_sole_offset_metres().metres()).abs()
364:         <= sole_contact_tolerance_metres().metres()
365: }
366: 
367: pub(in crate::animation::procedural) fn raised_support_is_actual(
368:     nominal_support: bool,
369:     ankle_y: f32,
370:     terrain_height: SupportElevation,
371: ) -> bool {
372:     nominal_support && sole_is_at_contact(ankle_y, terrain_height)
373: }

1: //! Balance-capture planning from real rendered stance observations.
2: 
3: use super::*;
4: 
5: impl LegIkMemory {
6:     /// Prepare a balance capture only from an actual selected foot observation.
7:     pub(in crate::animation::procedural) fn begin_settle_if_needed(
8:         &mut self,
9:         rig: &HumanoidRig,
10:         transforms: &TransformHelper,
11:         frame: ObservedRigFrame,
12:         terrain: Option<&SceneTerrain>,
13:         raised_handoff: bool,
14:     ) -> AnimationValueResult<()> {
15:         let (rig_origin, rig_rotation) = (frame.origin(), frame.rotation());
16:         // A real root remains the authored COM approximation for sparse rigs;
17:         // it is never substituted for an unobserved swing foot.
18:         let projected_com = projected_body_center(rig, transforms).unwrap_or(rig_origin);
19:         let has_recent_velocity = self.recent_movement_velocity.length_squared() > 0.0025;
20:         let stance_known =
21:             self.left_foot_world_target.is_some() && self.right_foot_world_target.is_some();
22:         let stance_safe = stance_known
23:             && terrain.is_some_and(|terrain| {
24:                 settle_stance_is_safe(
25:                     projected_com,
26:                     self.left_foot_world_target,
27:                     self.right_foot_world_target,
28:                     terrain,
29:                 )
30:             });
31:         if !(raised_handoff || has_recent_velocity || (stance_known && !stance_safe)) {
32:             return Ok(());
33:         }
34:         let rendered_left = rig.get(&BoneRole::FootLeft).and_then(|&foot| {
35:             transforms
36:                 .compute_global_transform(foot)
37:                 .ok()
38:                 .map(|global| global.translation())
39:         });
40:         let rendered_right = rig.get(&BoneRole::FootRight).and_then(|&foot| {
41:             transforms
42:                 .compute_global_transform(foot)
43:                 .ok()
44:                 .map(|global| global.translation())
45:         });
46:         let visible_left = settle_visible_foot(self.left_last_rendered_world, rendered_left);
47:         let visible_right = settle_visible_foot(self.right_last_rendered_world, rendered_right);
48:         let direction = if has_recent_velocity {
49:             self.recent_movement_velocity.normalize_or_zero()
50:         } else {
51:             balance_recovery_direction(
52:                 projected_com,
53:                 self.left_foot_world_target,
54:                 self.right_foot_world_target,
55:                 rig_rotation * Vec3::NEG_Z,
56:             )
57:         };
58:         let capture_point = if has_recent_velocity {
59:             projected_capture_point(
60:                 projected_com,
61:                 self.recent_movement_velocity.clamp_length_max(
62:                     ik_tuning()
63:                         .maximum_settle_capture_speed_metres_per_second
64:                         .metres_per_second(),
65:                 ),
66:                 ik_tuning().assumed_center_of_mass_height_metres,
67:             )
68:         } else {
69:             projected_com
70:         };
71:         let support_foot = choose_settle_support(
72:             self.left_support_weight,
73:             self.right_support_weight,
74:             visible_left,
75:             visible_right,
76:             projected_com,
77:             direction,
78:         );
79:         let acquired = self.support_was_acquired(support_foot);
80:         let Some(swing_start) = (if support_foot == LeadFoot::Left {
81:             visible_right
82:         } else {
83:             visible_left
84:         }) else {
85:             return Ok(());
86:         };
87:         let side = settle_swing_side(rig_origin, rig_rotation, swing_start, support_foot);
88:         let landing_target = checked_foot_target(plan_settle_landing(
89:             rig_origin,
90:             rig_rotation,
91:             capture_point,
92:             direction,
93:             side,
94:         ))?;
95:         checked_foot_target(capture_point)?;
96:         // Preserve observation-before-seed, then selected support ownership,
97:         // then the complete settle payload publication in that order.
98:         seed_settle_from_rendered_feet(self, visible_left, visible_right, rig_origin, rig_rotation);
99:         retain_settle_support(self, support_foot, visible_left, visible_right, acquired);
100:         self.settle = Some(LocomotionSettleState {
101:             support_foot,
102:             swing_start,
103:             capture_point,
104:             landing_target,
105:             progress: SettleProgress::ZERO,
106:             elapsed_seconds: AnimationElapsed::ZERO,
107:             raised_handoff,
108:         });
109:         Ok(())
110:     }
111: }
112: 
113: pub(in crate::animation::procedural) fn balance_recovery_direction(
114:     projected_com: Vec3,
115:     left_foot: Option<Vec3>,
116:     right_foot: Option<Vec3>,
117:     body_forward: Vec3,
118: ) -> Vec3 {
119:     let unsupported_offset = match (left_foot, right_foot) {
120:         (Some(left), Some(right)) => {
121:             let segment = right.xz() - left.xz();
122:             let closest = if segment.length_squared() > 0.000001 {
123:                 let progress = ((projected_com.xz() - left.xz()).dot(segment)
124:                     / segment.length_squared())
125:                 .clamp(0.0, 1.0);
126:                 left.xz() + segment * progress
127:             } else {
128:                 (left.xz() + right.xz()) * 0.5
129:             };
130:             projected_com.xz() - closest
131:         }
132:         (Some(foot), None) | (None, Some(foot)) => projected_com.xz() - foot.xz(),
133:         (None, None) => Vec2::ZERO,
134:     };
135:     Vec3::new(unsupported_offset.x, 0.0, unsupported_offset.y)
136:         .try_normalize()
137:         .unwrap_or_else(|| body_forward.with_y(0.0).normalize_or_zero())
138: }
139: 
140: pub(in crate::animation::procedural) fn projected_capture_point(
141:     com: Vec3,
142:     velocity: Vec3,
143:     com_height: SignedLength,
144: ) -> Vec3 {
145:     let omega = (9.81 / com_height.metres().max(0.25)).sqrt();
146:     com + velocity.with_y(0.0) / omega
147: }
148: 
149: pub(in crate::animation::procedural) fn choose_settle_support(
150:     left_weight: Option<UnitInterval>,
151:     right_weight: Option<UnitInterval>,
152:     left_foot: Option<Vec3>,
153:     right_foot: Option<Vec3>,
154:     projected_com: Vec3,
155:     direction: Vec3,
156: ) -> LeadFoot {
157:     let preferred = match (left_weight, right_weight) {
158:         (Some(left), Some(right)) if (left.fraction() - right.fraction()).abs() > 0.05 => {
159:             Some(if left > right {
160:                 LeadFoot::Left
161:             } else {
162:                 LeadFoot::Right
163:             })
164:         }
165:         (Some(left), None) if left.fraction() > 0.05 => Some(LeadFoot::Left),
166:         (None, Some(right)) if right.fraction() > 0.05 => Some(LeadFoot::Right),
167:         _ => None,
168:     };
169:     if let Some(foot) = preferred {
170:         return foot;
171:     }
172:     match (left_foot, right_foot) {
173:         (Some(left), Some(right)) => {
174:             // In flight, retain the foot behind the moving body so the other
175:             // foot can capture ahead of its projected center.
176:             if (left - projected_com).dot(direction) <= (right - projected_com).dot(direction) {
177:                 LeadFoot::Left
178:             } else {
179:                 LeadFoot::Right
180:             }
181:         }
182:         (Some(_), None) => LeadFoot::Left,
183:         (None, Some(_)) => LeadFoot::Right,
184:         (None, None) => LeadFoot::Left,
185:     }
186: }
187: 
188: pub(in crate::animation::procedural) fn plan_settle_landing(
189:     rig_origin: Vec3,
190:     rig_rotation: Quat,
191:     capture_point: Vec3,
192:     direction: Vec3,
193:     side: FootTrackSide,
194: ) -> Vec3 {
195:     let direction = direction
196:         .with_y(0.0)
197:         .try_normalize()
198:         .unwrap_or(rig_rotation * Vec3::NEG_Z);
199:     let lateral =
200:         rig_rotation * Vec3::X * (foot_track_inner_metres().metres() + 0.04) * side.coefficient();
201:     let mut target = capture_point
202:         .with_y(rig_origin.y + measured_ankle_sole_offset_metres().metres())
203:         + direction * ik_tuning().settle_capture_point_margin_metres.metres()
204:         + lateral;
205:     // The capture-point requirement is stronger than the anatomical track
206:     // correction, so restore its forward margin if the corridor clamp erodes
207:     // it during diagonal movement.
208:     target = constrain_foot_to_track(target, rig_origin, rig_rotation, side);
209:     let shortfall = ik_tuning().settle_capture_point_margin_metres.metres()
210:         - (target - capture_point).dot(direction);
211:     if shortfall > 0.0 {
212:         target += direction * shortfall;
213:     }
214:     target
215: }
216: 
217: pub(in crate::animation::procedural) fn settle_swing_side(
218:     rig_origin: Vec3,
219:     rig_rotation: Quat,
220:     swing_start: Vec3,
221:     support_foot: LeadFoot,
222: ) -> FootTrackSide {
223:     let authored_side = (rig_rotation.inverse() * (swing_start - rig_origin)).x;
224:     if authored_side.abs() > 0.001 {
225:         FootTrackSide::from_native_x(authored_side)
226:     } else {
227:         match support_foot {
228:             LeadFoot::Left => FootTrackSide::PositiveX,
229:             LeadFoot::Right => FootTrackSide::NegativeX,
230:         }
231:     }
232: }
