1: use super::*;
2: 
3: // Preserve a little margin below the viewer's 2 cm pelvis-step contract.
4: // Keep the normal knee reserve while a landing visibly carries weight, then
5: // release it before the pelvis reaches the authored height. The released reach
6: // remains capped at the authored leg extension, preventing a final
7: // recovery-frame foot lift or snap without introducing a straight-leg target.
8: 
9: #[derive(Debug, Clone, Copy)]
10: pub(in crate::animation::procedural) struct TwoBoneSolution {
11:     pub(in crate::animation::procedural) knee: Vec3,
12:     pub(in crate::animation::procedural) end: Vec3,
13:     pub(in crate::animation::procedural) end_direction: Vec3,
14: }
15: 
16: #[derive(Debug, Clone, Copy)]
17: pub(in crate::animation::procedural) struct TwoBoneChain {
18:     root: Vec3,
19:     current_knee: Vec3,
20:     current_end: Vec3,
21:     upper_length: NonnegativeLength,
22:     lower_length: NonnegativeLength,
23:     pole_direction: Vec3,
24: }
25: 
26: impl TwoBoneChain {
27:     pub(in crate::animation::procedural) const fn new(
28:         root: Vec3,
29:         current_knee: Vec3,
30:         current_end: Vec3,
31:         upper_length: NonnegativeLength,
32:         lower_length: NonnegativeLength,
33:         pole_direction: Vec3,
34:     ) -> Self {
35:         Self {
36:             root,
37:             current_knee,
38:             current_end,
39:             upper_length,
40:             lower_length,
41:             pole_direction,
42:         }
43:     }
44: }
45: 
46: pub(in crate::animation::procedural) fn plant_is_continuous(
47:     plant: Vec3,
48:     current_foot: Vec3,
49: ) -> bool {
50:     plant.is_finite()
51:         && current_foot.is_finite()
52:         && plant.distance(current_foot) <= ik_tuning().maximum_plant_discontinuity_metres.metres()
53: }
54: 
55: pub(in crate::animation::procedural) fn advance_pelvis_shift(
56:     current: SignedLength,
57:     desired: SignedLength,
58:     delta_seconds: AnimationElapsed,
59: ) -> AnimationValueResult<SignedLength> {
60:     let maximum_step = (ik_tuning()
61:         .pelvis_correction_speed_metres_per_second
62:         .metres_per_second()
63:         * delta_seconds.seconds())
64:     .min(maximum_pelvis_correction_step_metres().metres());
65:     SignedLength::from_metres(
66:         current.metres() + (desired.metres() - current.metres()).clamp(-maximum_step, maximum_step),
67:     )
68:     .map_err(|_| AnimationValueError::Overflow {
69:         quantity: AnimationQuantity::HeightOffset,
70:     })
71: }
72: 
73: pub(in crate::animation::procedural) fn maximum_reach(
74:     upper_length: NonnegativeLength,
75:     lower_length: NonnegativeLength,
76: ) -> ReachLimit {
77:     ReachLimit::Flexed {
78:         upper: upper_length,
79:         lower: lower_length,
80:         minimum_flexion: ik_tuning().minimum_knee_flexion_degrees,
81:     }
82: }
83: 
84: pub(in crate::animation::procedural) fn landing_maximum_reach(
85:     upper_length: NonnegativeLength,
86:     lower_length: NonnegativeLength,
87:     authored_reach: NonnegativeLength,
88:     compression: HeightDistance,
89: ) -> ReachLimit {
90:     ReachLimit::Landing {
91:         upper: upper_length,
92:         lower: lower_length,
93:         authored: authored_reach,
94:         compression,
95:     }
96: }
97: 
98: pub(in crate::animation::procedural) fn constrain_target_to_reach(
99:     target: Vec3,
100:     root: Vec3,
101:     maximum_reach: ReachLimit,
102: ) -> Option<Vec3> {
103:     let maximum_reach = maximum_reach.native_metres()?;
104:     let vertical = target.y - root.y;
105:     let maximum_horizontal = (maximum_reach * maximum_reach - vertical * vertical)
106:         .max(0.0)
107:         .sqrt();
108:     let horizontal = (target - root).xz().clamp_length_max(maximum_horizontal);
109:     Some(Vec3::new(
110:         root.x + horizontal.x,
111:         target.y,
112:         root.z + horizontal.y,
113:     ))
114: }
115: 
116: pub(in crate::animation::procedural) fn canonical_knee_pole_world(
117:     foot: LeadFoot,
118:     rig_rotation: Quat,
119: ) -> Vec3 {
120:     let side = FootTrackSide::for_foot(foot);
121:     pole_to_world(rig_rotation, canonical_knee_pole(side))
122: }
123: 
124: pub(in crate::animation::procedural) fn canonical_knee_pole(side: FootTrackSide) -> Vec3 {
125:     (Vec3::Z + Vec3::X * side.coefficient() * 0.18).normalize()
126: }
