128: pub(in crate::animation::procedural) fn solve_two_bone(
129:     chain: TwoBoneChain,
130:     target: Vec3,
131: ) -> Option<TwoBoneSolution> {
132:     solve_two_bone_internal(
133:         chain,
134:         target,
135:         maximum_reach(chain.upper_length, chain.lower_length),
136:         true,
137:     )
138: }
139: 
140: pub(in crate::animation::procedural) fn solve_landing_two_bone(
141:     chain: TwoBoneChain,
142:     target: Vec3,
143:     compression: HeightDistance,
144: ) -> AnimationValueResult<Option<TwoBoneSolution>> {
145:     Ok(solve_two_bone_internal(
146:         chain,
147:         target,
148:         landing_maximum_reach(
149:             chain.upper_length,
150:             chain.lower_length,
151:             NonnegativeLength::from_arithmetic(chain.root.distance(chain.current_end))?,
152:             compression,
153:         ),
154:         // Landing supplies a foot-facing-constrained leg pole. Reblending the
155:         // authored knee here would occur after that constraint and could
156:         // recreate an anatomically impossible sideways bend.
157:         false,
158:     ))
159: }
160: 
161: pub(in crate::animation::procedural) fn solve_two_bone_with_reach(
162:     chain: TwoBoneChain,
163:     target: Vec3,
164:     maximum_target_reach: ReachLimit,
165: ) -> Option<TwoBoneSolution> {
166:     solve_two_bone_internal(chain, target, maximum_target_reach, false)
167: }
168: 
169: pub(in crate::animation::procedural) fn advance_foot_target_at_speed(
170:     previous: Option<Vec3>,
171:     desired: Vec3,
172:     delta_seconds: AnimationElapsed,
173:     maximum_speed: adventuresim_core::linear_speed::NonnegativeSpeed,
174: ) -> Vec3 {
175:     let Some(previous) = previous.filter(|position| position.is_finite()) else {
176:         return desired;
177:     };
178:     if !desired.is_finite() {
179:         return previous;
180:     }
181:     let maximum_step = maximum_speed.metres_per_second() * delta_seconds.seconds();
182:     previous + (desired - previous).clamp_length_max(maximum_step)
183: }
184: 
185: fn solve_two_bone_internal(
186:     chain: TwoBoneChain,
187:     target: Vec3,
188:     maximum_target_reach: ReachLimit,
189:     preserve_authored_bend: bool,
190: ) -> Option<TwoBoneSolution> {
191:     let TwoBoneChain {
192:         root,
193:         current_knee,
194:         current_end,
195:         upper_length,
196:         lower_length,
197:         pole_direction,
198:     } = chain;
199:     let upper_length = upper_length.metres();
200:     let lower_length = lower_length.metres();
201:     if !root.is_finite() || !target.is_finite() || upper_length <= 0.0001 || lower_length <= 0.0001
202:     {
203:         return None;
204:     }
205:     let target_offset = target - root;
206:     let target_direction = target_offset
207:         .try_normalize()
208:         .or_else(|| (current_end - root).try_normalize())
209:         .unwrap_or(Vec3::NEG_Y);
210:     let target_distance = target_offset.length();
211:     let minimum_distance = (upper_length - lower_length).abs() + 0.0001;
212:     let maximum_distance = maximum_target_reach
213:         .native_metres()?
214:         .min(upper_length + lower_length - 0.0001);
215:     if minimum_distance > maximum_distance || minimum_distance.is_nan() || maximum_distance.is_nan()
216:     {
217:         return None;
218:     }
219:     let distance = target_distance.clamp(minimum_distance, maximum_distance);
220:     let end = root + target_direction * distance;
221:     let along = (upper_length * upper_length - lower_length * lower_length + distance * distance)
222:         / (2.0 * distance);
223:     let height = (upper_length * upper_length - along * along)
224:         .max(0.0)
225:         .sqrt();
226:     let pole_bend = pole_direction
227:         .reject_from_normalized(target_direction)
228:         .try_normalize();
229:     let authored_bend = (current_knee - root)
230:         .reject_from_normalized(target_direction)
231:         .try_normalize();
232:     // Preserve authored continuity only while it remains in the anatomical
233:     // hemisphere. Never flip a valid authored bend through a straight-leg
234:     // singularity merely to satisfy a pole chosen on the opposite side.
235:     let stabilized_authored_bend = preserve_authored_bend
236:         .then_some(authored_bend)
237:         .flatten()
238:         .zip(pole_bend)
239:         .and_then(|(authored, pole)| {
240:             let alignment = authored.dot(pole);
241:             (alignment > 0.05)
242:                 .then(|| {
243:                     pole.lerp(authored, smoothstep(0.05, 0.5, alignment))
244:                         .try_normalize()
245:                 })
246:                 .flatten()
247:         });
248:     let bend = stabilized_authored_bend
249:         .or(pole_bend)
250:         .or(preserve_authored_bend.then_some(authored_bend).flatten())

251:         .or_else(|| target_direction.any_orthonormal_vector().try_normalize())?;
252:     let knee = root + target_direction * along + bend * height;
253:     (knee.is_finite() && end.is_finite()).then_some(TwoBoneSolution {
254:         knee,
255:         end,
256:         end_direction: target_direction,
257:     })
258: }
