260: pub(in crate::animation::procedural) fn snapshot(
261:     entity: Entity,
262:     parents: &Query<&ChildOf>,
263:     helper: &TransformHelper,
264: ) -> Option<BoneSnapshot> {
265:     let global = helper.compute_global_transform(entity).ok()?;
266:     let parent_rotation = parents
267:         .get(entity)
268:         .ok()
269:         .and_then(|parent| helper.compute_global_transform(parent.parent()).ok())
270:         .map(|global| global.rotation())
271:         .unwrap_or(Quat::IDENTITY);
272:     Some(BoneSnapshot {
273:         entity,
274:         global,
275:         parent_rotation,
276:     })
277: }
