279: pub(in crate::animation::procedural) fn snapshot_chain(
280:     upper: Entity,
281:     lower: Entity,
282:     end: Entity,
283:     parents: &Query<&ChildOf>,
284:     helper: &TransformHelper,
285: ) -> Option<(BoneSnapshot, BoneSnapshot, BoneSnapshot)> {
286:     Some((
287:         snapshot(upper, parents, helper)?,
288:         snapshot(lower, parents, helper)?,
289:         snapshot(end, parents, helper)?,
