293: fn aim_world_rotation(current: BoneSnapshot, from: Vec3, to: Vec3) -> Option<Quat> {
294:     let from = from.try_normalize()?;
295:     let to = to.try_normalize()?;
296:     let world = Quat::from_rotation_arc(from, to) * current.global.rotation();
297:     let local = current.parent_rotation.inverse() * world;
298:     local.is_finite().then_some(local.normalize())
299: }
300: 
301: pub(in crate::animation::procedural) fn apply_two_bone_solution(
302:     upper: Entity,
303:     lower: Entity,
304:     end: Entity,
305:     solution: TwoBoneSolution,
306:     parents: &Query<&ChildOf>,
307:     transforms: &mut ParamSet<(TransformHelper, Query<&mut Transform>)>,
308: ) {
309:     let Some((upper_before, lower_before, end_before)) =
310:         snapshot_chain(upper, lower, end, parents, &transforms.p0())
311:     else {
312:         return;
313:     };
314:     let Some(rotation) = aim_world_rotation(
315:         upper_before,
316:         lower_before.global.translation() - upper_before.global.translation(),
317:         solution.knee - upper_before.global.translation(),
318:     ) else {
319:         return;
320:     };
321:     if let Ok(mut transform) = transforms.p1().get_mut(upper_before.entity) {
322:         transform.rotation = rotation;
323:     }
324: 
325:     // Recompute through the actual twist hierarchy after rotating the major
326:     // upper bone. The twist local transforms remain untouched.
327:     let Some((_, lower_after, end_after)) =
328:         snapshot_chain(upper, lower, end, parents, &transforms.p0())
329:     else {
330:         return;
331:     };
332:     let Some(rotation) = aim_world_rotation(
333:         lower_after,
334:         end_after.global.translation() - lower_after.global.translation(),
335:         solution.end - solution.knee,
336:     ) else {
337:         return;
338:     };
339:     if let Ok(mut transform) = transforms.p1().get_mut(lower_after.entity) {
340:         transform.rotation = rotation;
341:     }
342: 
343:     // The analytic solve owns joint positions, not an airborne foot's authored
344:     // facing. Recompute through the newly rotated parent hierarchy and restore
345:     // the end bone's pre-solve world orientation. Contact slope alignment runs
346:     // after this seam and intentionally overrides it when the sole is loaded.
347:     let Some(end_after) = snapshot(end, parents, &transforms.p0()) else {
348:         return;
349:     };
350:     let local = end_after.parent_rotation.inverse() * end_before.global.rotation();
351:     if local.is_finite()
352:         && let Ok(mut transform) = transforms.p1().get_mut(end)
353:     {
354:         transform.rotation = local.normalize();
355:     }
356: }
