368:     /// Retain deceleration momentum and admit the existing stationary balance-capture seam.
369:     pub(super) fn observe_movement_for_settle(
370:         &mut self,
371:         ordinary_lowered: bool,
372:         raised_footwork_handoff: bool,
373:         speed: NonnegativeSpeed,
374:         planar_velocity: Vec3,
375:     ) -> bool {
376:         if ordinary_lowered && speed > STATIONARY_ANIMATION_SPEED_LIMIT && self.settle.is_none() {
377:             // Retain the strongest recent velocity through presentation deceleration,
378:             // rather than letting its final sub-threshold sample erase momentum.
379:             if planar_velocity.length_squared()
380:                 >= self.recent_movement_velocity.length_squared() * 0.25
381:             {
382:                 self.recent_movement_velocity = planar_velocity;
383:             }
384:             false
385:         } else {
386:             (ordinary_lowered || raised_footwork_handoff)
387:                 && speed <= STATIONARY_ANIMATION_SPEED_LIMIT
388:                 && self.settle.is_none()
389:         }
390:     }
