1: //! Joint native clearance and owner-motion budget projection for a run foot.
2: 
3: use super::*;
4: 
5: pub(in crate::animation::procedural) fn advance_run_airborne_world_target(
6:     previous_owner: Option<Vec3>,
7:     desired_world: Vec3,
8:     rig_origin: Vec3,
9:     rig_rotation: Quat,
10:     delta_seconds: AnimationElapsed,
11:     speed: NonnegativeSpeed,
12:     clearance_floor_at: impl Fn(ScenePlanPoint) -> AnimationValueResult<Option<FootClearanceFloor>>,
13: ) -> AnimationValueResult<Vec3> {
14:     let Some(previous_owner) = previous_owner.filter(|target| target.is_finite()) else {
15:         let mut target = desired_world;
16:         if let Some(floor) = clearance_floor_at(checked_scene_point_metres(target.xz())?)? {
17:             target.y = target.y.max(floor.minimum_height()?.metres());
18:         }
19:         return checked_foot_target(target);
20:     };
21:     let start_world = rig_origin + rig_rotation * previous_owner;
22:     let maximum_step = speed.metres_per_second() * delta_seconds.seconds();
23:     let cleared_at = |progress: f32| {
24:         let mut target = start_world.lerp(desired_world, progress.clamp(0.0, 1.0));
25:         if let Some(floor) = clearance_floor_at(checked_scene_point_metres(target.xz())?)? {
26:             target.y = target.y.max(floor.minimum_height()?.metres());
27:         }
28:         checked_foot_target(target)
29:     };
30:     let desired = cleared_at(1.0)?;
31:     if desired.distance(start_world) <= maximum_step {
32:         return Ok(desired);
33:     }
34: 
35:     // Clearance and the 3D budget are solved jointly. On an uphill release,
36:     // both full owner transport (terrain rise) and literal world hold (root
37:     // displacement) can be outside the sphere while an intermediate XZ is
38:     // feasible. That set is not monotone from either endpoint, so first scan
39:     // deterministically for its farthest feasible interval, then refine only
40:     // the local exit boundary.
41:     const SEARCH_SAMPLES: usize = 64;
42:     let mut best = None;
43:     let mut best_progress = 0.0;
44:     for index in 0..=SEARCH_SAMPLES {
45:         let progress = index as f32 / SEARCH_SAMPLES as f32;
46:         let candidate = cleared_at(progress)?;
47:         if candidate.distance(start_world) <= maximum_step + 0.000001 {
48:             best = Some(candidate);
49:             best_progress = progress;
50:         }
51:     }
52:     let Some(mut best) = best else {
53:         // The straight owner-transport-to-world-plant segment can cross a
54:         // locally high triangle even when a small lateral/fore-aft detour is
55:         // inside the same 3D motion sphere. Search that complete horizontal
56:         // disk before accepting an over-budget fallback. This matters at
57:         // toe-off: the semantic sole floor and a terrain rise can make both
58:         // line endpoints invalid while a nearby downhill point remains valid.
59:         if let Some(feasible) = terrain_feasible_target_in_step(
60:             start_world,
61:             desired_world,
62:             maximum_step,
63:             &clearance_floor_at,
64:         )? {
65:             return Ok(feasible);
66:         }
67:         // A true vertical discontinuity can leave no valid point in the full
68:         // disk. Keep clearance truthful and choose the least-discontinuous
69:         // line sample; support/reach ownership handles that rare fallback.
70:         let fallback = (0..=SEARCH_SAMPLES)
71:             .map(|index| cleared_at(index as f32 / SEARCH_SAMPLES as f32))
72:             .collect::<AnimationValueResult<Vec<_>>>()?
73:             .into_iter()
74:             .min_by(|left, right| {
75:                 left.distance_squared(start_world)
76:                     .total_cmp(&right.distance_squared(start_world))
77:             });
78:         return match fallback {
79:             Some(target) => Ok(target),
80:             None => cleared_at(0.0),
81:         };
82:     };
83:     let mut low = best_progress;
84:     let mut high = (best_progress + 1.0 / SEARCH_SAMPLES as f32).min(1.0);
85:     for _ in 0..12 {
86:         let middle = (low + high) * 0.5;
87:         let candidate = cleared_at(middle)?;
88:         if candidate.distance(start_world) <= maximum_step + 0.000001 {
89:             low = middle;
90:             best = candidate;
91:         } else {
92:             high = middle;
93:         }
94:     }
95:     Ok(best)
96: }
