100:     desired_world: Vec3,
101:     maximum_step: f32,
102:     clearance_floor_at: &impl Fn(ScenePlanPoint) -> AnimationValueResult<Option<FootClearanceFloor>>,
103: ) -> AnimationValueResult<Option<Vec3>> {
104:     if maximum_step <= 0.0 {
105:         return Ok(None);
106:     }
107:     let mut best: Option<(f32, Vec3)> = None;
108:     let mut center = start_world.xz();
109:     let mut radius = maximum_step;
110:     // A deterministic square-disk search followed by local refinements finds
111:     // terrain-feasible points off the direct swing chord without introducing
112:     // frame-rate-dependent iteration or lateral drift.
113:     for refinement in 0..4 {
114:         const HALF_GRID: i32 = 12;
115:         let spacing = radius / HALF_GRID as f32;
116:         for x in -HALF_GRID..=HALF_GRID {
117:             for z in -HALF_GRID..=HALF_GRID {
118:                 let xz = center + Vec2::new(x as f32 * spacing, z as f32 * spacing);
119:                 let offset = xz - start_world.xz();
120:                 if offset.length_squared() > maximum_step * maximum_step + 0.000001 {
121:                     continue;
122:                 }
123:                 let chord = desired_world.xz() - start_world.xz();
124:                 let chord_progress = if chord.length_squared() > 0.0 {
125:                     offset.dot(chord) / chord.length_squared()
126:                 } else {
127:                     0.0
128:                 }
129:                 .clamp(0.0, 1.0);
130:                 let nearest_chord = start_world.xz() + chord * chord_progress;
131:                 if xz.distance(nearest_chord) > 0.04 {
132:                     continue;
133:                 }
134:                 let Some(floor) = clearance_floor_at(checked_scene_point_metres(xz)?)? else {
135:                     return Ok(None);
136:                 };
137:                 let candidate = Vec3::new(
138:                     xz.x,
139:                     desired_world.y.max(floor.minimum_height()?.metres()),
140:                     xz.y,
141:                 );
142:                 if candidate.distance(start_world) > maximum_step + 0.000001 {
143:                     continue;
144:                 }
145:                 let score = candidate.distance_squared(desired_world);
146:                 if best.is_none_or(|(best_score, _)| score < best_score) {
147:                     best = Some((score, candidate));
148:                 }
149:             }
150:         }
151:         let Some((_, candidate)) = best else {
152:             break;
153:         };
154:         if refinement < 3 {
155:             center = candidate.xz();
156:             radius = spacing * 2.0;
157:         }
158:     }
159:     Ok(best.map(|(_, candidate)| candidate))
160: }
