output_text:
1: //! Authored, run-flight and stop-settle foot-height geometry kernels.
2: 
3: use super::*;
4: use adventuresim_building_generator::spatial_geometry::Elevation;
5: use adventuresim_tactical_core::scene_coordinates::Scene;
6: 
7: /// Foot-height requirements retain either a checked minimum or the
8: /// complete terrain/sole/clearance sum until the final point correction.
9: #[derive(Clone, Copy, Debug)]
10: pub(in crate::animation::procedural) enum FootClearanceFloor {
11:     Minimum(Elevation<Scene>),
12:     Terrain {
13:         surface: SupportElevation,
14:         clearance: SignedLength,
15:     },
16: }
17: 
18: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
19: pub(in crate::animation::procedural) enum FootDescent {
20:     RaiseOnly,
21:     FollowFloor,
22: }
23: 
24: impl FootDescent {
25:     pub(in crate::animation::procedural) fn permits_descent(self) -> bool {
26:         matches!(self, Self::FollowFloor)
27:     }
28: }
29: 
30: impl FootClearanceFloor {
31:     pub(in crate::animation::procedural) fn minimum_height(
32:         self,
33:     ) -> AnimationValueResult<Elevation<Scene>> {
34:         match self {
35:             Self::Minimum(height) => Ok(height),
36:             Self::Terrain { surface, clearance } => checked_scene_elevation(
37:                 surface.metres()
38:                     + measured_ankle_sole_offset_metres().metres()
39:                     + clearance.metres(),
40:             ),
41:         }
42:     }
43: 
44:     pub(in crate::animation::procedural) fn apply(
45:         self,
46:         mut target: Vec3,
47:         descent: FootDescent,
48:     ) -> AnimationValueResult<Vec3> {
49:         let required = self.minimum_height()?.metres();
50:         target.y = if descent.permits_descent() {
51:             required
52:         } else {
53:             target.y.max(required)
54:         };
55:         checked_foot_target(target)
56:     }
57: }
58: 
59: pub(crate) fn measured_ankle_sole_offset_metres() -> PositiveLength {
60:     ik_tuning().measured_ankle_sole_offset_metres
61: }
62: 
63: pub(crate) fn sole_contact_tolerance_metres() -> PositiveLength {
64:     ik_tuning().sole_contact_tolerance_metres
65: }
66: 
67: /// Conform only upward from the authored pose, then apply the solve confidence.
68: pub(in crate::animation::procedural) fn ordinary_terrain_target(
69:     foot_position: Vec3,
70:     height: SupportElevation,
71:     weight: UnitInterval,
72: ) -> AnimationValueResult<Vec3> {
73:     let minimum = checked_scene_elevation(
74:         height.metres() + measured_ankle_sole_offset_metres().metres()
75:             - ik_tuning().sole_contact_margin_metres.metres(),
76:     )?;
77:     let target = foot_position.with_y(foot_position.y.max(minimum.metres()));
78:     checked_foot_target(foot_position.lerp(target, weight.fraction().clamp(0.0, 1.0)))
79: }
80: 
81: pub(in crate::animation::procedural) fn run_swing_clearance(
82:     phase_to_contact: CycleDelta,
83:     planned_progress: Option<UnitInterval>,
84: ) -> AnimationValueResult<SignedLength> {
85:     checked_signed_length(native_run_swing_clearance(
86:         phase_to_contact,
87:         planned_progress,
88:     ))
89: }
90: 
91: pub(in crate::animation::procedural) fn run_airborne_clearance(
92:     phase_to_contact: CycleDelta,
93:     planned_progress: Option<UnitInterval>,
94:     descent: FootDescent,
95: ) -> AnimationValueResult<SignedLength> {
96:     let clearance = native_run_swing_clearance(phase_to_contact, planned_progress);
97:     // Admit the completed floor operation, so a capped temporary value is not
98:     // mistaken for a retained nonfinite measurement.
99:     checked_signed_length(if descent.permits_descent() {
100:         clearance
101:     } else {
102:         clearance.max(ik_tuning().run_swing_minimum_sole_clearance_metres.metres())
103:     })
104: }
105: 
106: pub(in crate::animation::procedural) fn run_airborne_clearance_for_sample(
107:     just_released: bool,
108:     phase_to_contact: CycleDelta,
109:     planned_progress: Option<UnitInterval>,
110:     descent: FootDescent,
111: ) -> AnimationValueResult<SignedLength> {
112:     if just_released {
113:         Ok(ik_tuning().run_swing_minimum_sole_clearance_metres)
114:     } else {
115:         run_airborne_clearance(phase_to_contact, planned_progress, descent)
116:     }
117: }
118: 
119: pub(in crate::animation::procedural) fn settle_swing_target(
120:     start: Vec3,
121:     landing: Vec3,
122:     progress: SettleProgress,
123: ) -> AnimationValueResult<Vec3> {
124:     let progress = progress.fraction().clamp(0.0, 1.0);
125:     let horizontal = smoothstep(0.0, 1.0, progress);
126:     let mut target = start.lerp(landing, horizontal);
127:     target.y +=
128:         (std::f32::consts::PI * progress).sin() * ik_tuning().settle_step_clearance_metres.metres();
129:     checked_foot_target(target)
130: }
131: 
132: /// Complete the planned run swing's terrain and clearance correction together.
133: pub(in crate::animation::procedural) fn conform_run_swing_target(
134:     terrain: &SceneTerrain,
135:     desired_target: Vec3,
136:     phase_to_contact: CycleDelta,
137:     planned_progress: Option<UnitInterval>,
138: ) -> AnimationValueResult<Vec3> {
139:     let point = checked_scene_point_metres(desired_target.xz())?;
140:     let Some(surface) = terrain.height_at(point) else {
141:         return Ok(desired_target);
142:     };
143:     FootClearanceFloor::Terrain {
144:         surface,
145:         clearance: run_swing_clearance(phase_to_contact, planned_progress)?,
146:     }
147:     .apply(desired_target, FootDescent::RaiseOnly)
148: }
149: 
150: /// Keep the settle arc, terrain blend and visible toe floor in one correction.
151: pub(in crate::animation::procedural) fn conform_settle_swing_target(
152:     terrain: &SceneTerrain,
153:     mut desired_target: Vec3,
154:     authored_foot: Vec3,
155:     progress: SettleProgress,
156:     terrain_blend: UnitInterval,
157:     rendered: Option<(Vec3, Vec3)>,
158:     elapsed: AnimationElapsed,
159: ) -> AnimationValueResult<Vec3> {
160:     let point = checked_scene_point_metres(desired_target.xz())?;
161:     let Some(height) = terrain.height_at(point) else {
162:         return Ok(desired_target);
163:     };
164:     let minimum = checked_scene_elevation(
165:         height.metres()
166:             + measured_ankle_sole_offset_metres().metres()
167:             + (ik_tuning().swing_sole_clearance_metres.metres() * (1.0 - progress.fraction())).max(
168:                 ik_tuning()
169:                     .terrain_transition_flight_toe_clearance_metres
170:                     .metres(),
171:             ),
172:     )?;
173:     desired_target.y = desired_target.y.max(
174:         authored_foot
175:             .y
176:             .lerp(minimum.metres(), terrain_blend.fraction()),
177:     );
178:     if let Some((ankle, toe)) = rendered
179:         && let Some(floor) = toe_aware_clearance_floor(
180:             ankle,
181:             toe,
182:             point,
183:             transition_toe_clearance_with_rotation_margin(ankle, toe, elapsed)?,
184:             |point| terrain.height_at(point),
185:         )?
186:     {
187:         desired_target = floor.apply(desired_target, FootDescent::RaiseOnly)?;
188:     }
189:     checked_foot_target(desired_target)
190: }
191: 
192: pub(in crate::animation::procedural) fn toe_aware_clearance_floor(
193:     rendered_ankle: Vec3,
194:     rendered_toe: Vec3,
195:     desired_ankle: ScenePlanPoint,
196:     minimum_toe_clearance: SignedLength,
197:     terrain_height_at: impl Fn(ScenePlanPoint) -> Option<SupportElevation>,
198: ) -> AnimationValueResult<Option<FootClearanceFloor>> {
199:     let ankle_point = checked_scene_point_metres(rendered_ankle.xz())?;
200:     let Some(ankle_height) = terrain_height_at(ankle_point) else {
201:         return Ok(None);
202:     };
203:     let ankle_clearance = rendered_ankle.y - ankle_height.metres();
204:     let toe_point = checked_scene_point_metres(rendered_toe.xz())?;
205:     let Some(toe_height) = terrain_height_at(toe_point) else {
206:         return Ok(None);
207:     };
208:     let toe_clearance = rendered_toe.y - toe_height.metres();
209:     let ankle_above_toe = ankle_clearance - toe_clearance;
210:     let Some(desired_height) = terrain_height_at(desired_ankle) else {

211:         return Ok(None);
212:     };
213:     checked_scene_elevation(
214:         desired_height.metres() + ankle_above_toe + minimum_toe_clearance.metres(),
215:     )
216:     .map(|height| Some(FootClearanceFloor::Minimum(height)))
217: }
218: 
219: pub(in crate::animation::procedural) fn transition_toe_clearance_with_rotation_margin(
220:     rendered_ankle: Vec3,
221:     rendered_toe: Vec3,
222:     delta_seconds: AnimationElapsed,
223: ) -> AnimationValueResult<SignedLength> {
224:     let angular_step = (ik_tuning()
225:         .airborne_foot_rotation_speed_degrees_per_second
226:         .degrees_per_second()
227:         * delta_seconds.seconds())
228:     .min(90.0)
229:     .to_radians();
230:     checked_signed_length(
231:         ik_tuning()
232:             .terrain_transition_flight_toe_clearance_metres
233:             .metres()
234:             + rendered_ankle.distance(rendered_toe) * angular_step.sin(),
235:     )
236: }
237: 
238: /// Combine the same sole-first, optional toe-second transition floor for each
239: /// candidate of the native sphere/disk search, without recomputing a plan.
240: pub(in crate::animation::procedural) fn transition_clearance_floor(
241:     terrain: &SceneTerrain,
242:     rendered: Option<(Vec3, Vec3)>,
243:     elapsed: AnimationElapsed,
244:     point: ScenePlanPoint,
245: ) -> AnimationValueResult<Option<FootClearanceFloor>> {
246:     let sole = terrain.height_at(point).map(|height| {
247:         height.metres()
248:             + measured_ankle_sole_offset_metres().metres()
249:             + ik_tuning()
250:                 .terrain_transition_flight_toe_clearance_metres
251:                 .metres()
252:     });
253:     let toe = rendered
254:         .map(|(ankle, toe)| -> AnimationValueResult<Option<f32>> {
255:             let angular_step = (ik_tuning()
256:                 .airborne_foot_rotation_speed_degrees_per_second
257:                 .degrees_per_second()
258:                 * elapsed.seconds())
259:             .min(90.0)
260:             .to_radians();
261:             let margin = ik_tuning()
262:                 .terrain_transition_flight_toe_clearance_metres
263:                 .metres()
264:                 + ankle.distance(toe) * angular_step.sin();
265:             let ankle_point = checked_scene_point_metres(ankle.xz())?;
266:             let Some(ankle_support) = terrain.height_at(ankle_point) else {
267:                 return Ok(None);
268:             };
269:             let ankle_clearance = ankle.y - ankle_support.metres();
270:             let toe_point = checked_scene_point_metres(toe.xz())?;
271:             let Some(toe_support) = terrain.height_at(toe_point) else {
272:                 return Ok(None);
273:             };
274:             let toe_clearance = toe.y - toe_support.metres();
275:             let above_toe = ankle_clearance - toe_clearance;
276:             Ok(terrain
277:                 .height_at(point)
278:                 .map(|height| height.metres() + above_toe + margin))
279:         })
280:         .transpose()?
281:         .flatten();
282:     // Complete the native sole/toe maximum before admitting a retained floor.
283:     sole.into_iter()
284:         .chain(toe)
285:         .reduce(f32::max)
286:         .map(|height| checked_scene_elevation(height).map(FootClearanceFloor::Minimum))
287:         .transpose()
288: }
289: 
290: pub(in crate::animation::procedural) fn terrain_clearance_floor(
291:     terrain: &SceneTerrain,
292:     clearance: SignedLength,
293:     point: ScenePlanPoint,
294: ) -> AnimationValueResult<Option<FootClearanceFloor>> {
295:     terrain
296:         .height_at(point)
297:         .map(|height| {
298:             checked_scene_elevation(
299:                 height.metres() + measured_ankle_sole_offset_metres().metres() + clearance.metres(),
300:             )
301:             .map(FootClearanceFloor::Minimum)
302:         })
303:         .transpose()
304: }
305: 
306: /// Admit completed native scene X/Z metres before application support queries.
307: pub(in crate::animation::procedural) fn checked_scene_point_metres(
308:     metres: Vec2,
309: ) -> AnimationValueResult<ScenePlanPoint> {
310:     ScenePlanPoint::from_metres(metres).ok_or(AnimationValueError::Overflow {
311:         quantity: AnimationQuantity::WorldPosition,
312:     })
313: }
314: 
315: /// Admit a completed absolute ankle elevation in the scene's vertical datum.
316: pub(in crate::animation::procedural) fn checked_scene_elevation(
317:     metres: f32,
318: ) -> AnimationValueResult<Elevation<Scene>> {
319:     Elevation::from_metres(metres).map_err(|_| AnimationValueError::Overflow {
320:         quantity: AnimationQuantity::WorldPosition,
321:     })
322: }
323: 
324: pub(in crate::animation::procedural) fn checked_signed_length(
325:     metres: f32,
326: ) -> AnimationValueResult<SignedLength> {
327:     SignedLength::from_metres(metres).map_err(|_| AnimationValueError::Overflow {
328:         quantity: AnimationQuantity::WorldPosition,
329:     })
330: }
331: 
332: pub(in crate::animation::procedural) fn checked_foot_target(
333:     target: Vec3,
334: ) -> AnimationValueResult<Vec3> {
335:     if !target.is_finite() {
336:         return Err(AnimationValueError::Overflow {
337:             quantity: AnimationQuantity::WorldPosition,
338:         });
339:     }
340:     Ok(target)
341: }
342: 
343: // Private constituent of the two completed clearance equations above. It
344: // carries no retained scalar or application policy handoff.
345: fn native_run_swing_clearance(
346:     phase_to_contact: CycleDelta,
347:     planned_progress: Option<UnitInterval>,
348: ) -> f32 {
349:     if let Some(progress) = planned_progress {
350:         let progress = progress.fraction().clamp(0.0, 1.0);
351:         ik_tuning().run_swing_minimum_sole_clearance_metres.metres() * (1.0 - progress)
352:             + (std::f32::consts::PI * progress).sin()
353:                 * ik_tuning().run_swing_sole_clearance_metres.metres()
354:     } else {
355:         let progress = (1.0 - phase_to_contact.cycles()).clamp(0.0, 1.0);
356:         ik_tuning().run_swing_minimum_sole_clearance_metres.metres()
357:             + (std::f32::consts::PI * progress).sin()
358:                 * ik_tuning().run_swing_sole_clearance_metres.metres()
359:     }
360: }
