1: //! Run contact reach, motion disks and terrain-conformed footprint planning.
2: 
3: use super::*;
4: 
5: pub(in crate::animation::procedural) fn run_contact_within_follower_step(
6:     previous_owner: Option<Vec3>,
7:     desired_world: Vec3,
8:     rig_origin: Vec3,
9:     rig_rotation: Quat,
10:     delta_seconds: AnimationElapsed,
11: ) -> bool {
12:     let Some(previous_owner) = previous_owner else {
13:         return true;
14:     };
15:     let desired_owner = rig_rotation.inverse() * (desired_world - rig_origin);
16:     previous_owner.distance(desired_owner)
17:         <= (ik_tuning().run_airborne_owner_step_metres.metres()
18:             * ik_tuning().continuity_sample_hz.hertz())
19:             * delta_seconds.seconds()
20:             + sole_contact_tolerance_metres().metres()
21: }
22: 
23: pub(in crate::animation::procedural) fn run_contact_within_leg_reach(
24:     target: Vec3,
25:     upper_root: Vec3,
26:     maximum_reach: ReachLimit,
27: ) -> bool {
28:     maximum_reach
29:         .native_metres()
30:         .is_some_and(|reach| target.distance(upper_root) <= reach + 0.001)
31: }
32: 
33: pub(in crate::animation::procedural) fn run_contact_within_follower_motion_step(
34:     previous_owner: Option<Vec3>,
35:     desired_world: Vec3,
36:     rig_origin: Vec3,
37:     rig_rotation: Quat,
38:     delta_seconds: AnimationElapsed,
39: ) -> bool {
40:     let Some(previous_owner) = previous_owner else {
41:         return true;
42:     };
43:     let desired_owner = rig_rotation.inverse() * (desired_world - rig_origin);
44:     previous_owner.distance(desired_owner)
45:         <= (ik_tuning().run_airborne_owner_step_metres.metres()
46:             * ik_tuning().continuity_sample_hz.hertz())
47:             * delta_seconds.seconds()
48:             + 0.0001
49: }
50: 
51: #[expect(
52:     clippy::too_many_arguments,
53:     reason = "this domain boundary names each independent input explicitly"
54: )]
55: pub(in crate::animation::procedural) fn retarget_unacquired_run_contact_for_descent(
56:     previous_owner: Option<Vec3>,
57:     fixed_contact: Vec3,
58:     rig_origin: Vec3,
59:     rig_rotation: Quat,
60:     side: FootTrackSide,
61:     upper_root: Vec3,
62:     maximum_reach: ReachLimit,
63:     delta_seconds: AnimationElapsed,
64:     terrain_height_at: impl Fn(ScenePlanPoint) -> Option<SupportElevation>,
65: ) -> Option<Vec3> {
66:     let previous_owner = previous_owner?;
67:     let maximum_reach = maximum_reach.native_metres()?;
68:     let fixed_within_motion = run_contact_within_follower_motion_step(
69:         Some(previous_owner),
70:         fixed_contact,
71:         rig_origin,
72:         rig_rotation,
73:         delta_seconds,
74:     );
75:     let fixed_within_reach = fixed_contact.distance(upper_root) <= maximum_reach + 0.001;
76:     if fixed_within_motion && fixed_within_reach {
77:         return None;
78:     }
79: 
80:     // At 5.5 m/s a fixed world contact recedes 8.6 cm in owner space per
81:     // sample. Combining that with the final 5 cm descent exceeds the 9 cm
82:     // continuity budget. A downhill target may instead be inside that motion
83:     // budget but a few millimetres beyond the analytic leg reach. Start from
84:     // the visible owner XZ for the first case or the frozen contact for the
85:     // second, then terrain-resample and project into current reach before
86:     // freezing the final acquired footprint.
87:     let start_world = rig_origin + rig_rotation * previous_owner;
88:     let maximum_motion = (ik_tuning().run_airborne_owner_step_metres.metres()
89:         * ik_tuning().continuity_sample_hz.hertz())
90:         * delta_seconds.seconds();
91:     let mut transported_contact = if fixed_within_motion {
92:         fixed_contact
93:     } else {
94:         start_world
95:     };
96:     for _ in 0..4 {
97:         transported_contact =
98:             constrain_foot_to_track(transported_contact, rig_origin, rig_rotation, side);
99:         let height = terrain_height_at(ScenePlanPoint::from_metres(transported_contact.xz())?)?;
100:         transported_contact.y = height.metres() + measured_ankle_sole_offset_metres().metres();
101:         let leg_vertical = transported_contact.y - upper_root.y;
102:         let leg_horizontal = (maximum_reach * maximum_reach - leg_vertical * leg_vertical)
103:             .max(0.0)
104:             .sqrt();
105:         let motion_vertical = transported_contact.y - start_world.y;
106:         let motion_horizontal = (maximum_motion * maximum_motion
107:             - motion_vertical * motion_vertical)
108:             .max(0.0)
109:             .sqrt();
110:         let projected = project_point_into_two_disks(
111:             transported_contact.xz(),
112:             [
113:                 (upper_root.xz(), leg_horizontal),
114:                 (start_world.xz(), motion_horizontal),
115:             ],
116:         );
117:         transported_contact.x = projected.x;
118:         transported_contact.z = projected.y;
119:     }
120:     transported_contact =
121:         constrain_foot_to_track(transported_contact, rig_origin, rig_rotation, side);
122:     let height = terrain_height_at(ScenePlanPoint::from_metres(transported_contact.xz())?)?;
123:     transported_contact.y = height.metres() + measured_ankle_sole_offset_metres().metres();
124:     let accepted = transported_contact.distance(upper_root) <= maximum_reach + 0.001
125:         && run_contact_within_follower_motion_step(
126:             Some(previous_owner),
127:             transported_contact,
128:             rig_origin,
129:             rig_rotation,
130:             delta_seconds,
131:         );
132:     if !accepted {
133:         return None;
134:     }
135:     Some(transported_contact)
136: }
137: 
138: pub(in crate::animation::procedural) fn project_point_into_two_disks(
139:     mut point: Vec2,
140:     disks: [(Vec2, f32); 2],
141: ) -> Vec2 {
142:     let mut corrections = [Vec2::ZERO; 2];
143:     for _ in 0..24 {
144:         for (index, (center, radius)) in disks.into_iter().enumerate() {
145:             let corrected = point + corrections[index];
146:             let projected = center + (corrected - center).clamp_length_max(radius.max(0.0));
147:             corrections[index] = corrected - projected;
148:             point = projected;
149:         }
150:     }
151:     point
152: }
153: 
154: #[expect(
155:     clippy::too_many_arguments,
156:     reason = "this domain boundary names each independent input explicitly"
157: )]
158: pub(in crate::animation::procedural) fn reachable_run_contact_target(
159:     mut candidate: Vec3,
160:     current_upper_root: Vec3,
161:     velocity: Vec3,
162:     step_distance: NonnegativeLength,
163:     phase_to_contact: CycleDelta,
164:     contact_ready_phase: CycleDelta,
165:     maximum_reach: ReachLimit,
166:     terrain_height_at: impl Fn(ScenePlanPoint) -> Option<SupportElevation>,
167: ) -> Option<Vec3> {
168:     let contact_ready_phase = contact_ready_phase.cycles();
169:     let direction = velocity.with_y(0.0).try_normalize().unwrap_or(Vec3::NEG_Z);
170:     let support_radius =
171:         (contact_ready_phase - ik_tuning().run_contact_chain_settle_phase.fraction()).max(0.0);
172:     let travel_per_phase = step_distance.metres() * 2.0;
173:     let current_terrain_height =
174:         terrain_height_at(ScenePlanPoint::from_metres(current_upper_root.xz())?);
175:     let [Some(entry), Some(centre), Some(exit)] = [
176:         phase_to_contact.cycles() - support_radius,
177:         phase_to_contact.cycles(),
178:         phase_to_contact.cycles() + support_radius,
179:     ]
180:     .map(|remaining_phase| {
181:         let mut root =
182:             current_upper_root + direction * (remaining_phase.max(0.0) * travel_per_phase);
183:         if let (Some(current_height), Some(predicted_height)) = (
184:             current_terrain_height,
185:             terrain_height_at(ScenePlanPoint::from_metres(root.xz())?),
186:         ) {
187:             root.y += predicted_height.metres() - current_height.metres();
188:         }
189:         Some(
190:             root - Vec3::Y
191:                 * ik_tuning()
192:                     .run_maximum_planned_reach_pelvis_drop_metres
193:                     .metres(),
194:         )
195:     }) else {
196:         return None;
197:     };
198:     let predicted_upper_roots = [entry, centre, exit];
199:     // The world footprint must remain reachable for the whole stance, not
200:     // merely at entry. Project its XZ into the intersection of the predicted
201:     // entry/center/exit reach disks. Dykstra's deterministic projection keeps
202:     // an already feasible desired footprint unchanged and finds the closest
203:     // point in the convex intersection otherwise. Resampling between passes
204:     // accounts for the changing vertical budget on sloped terrain.
205:     for _ in 0..4 {
206:         if let Some(height) = terrain_height_at(ScenePlanPoint::from_metres(candidate.xz())?) {
207:             candidate.y = height.metres() + measured_ankle_sole_offset_metres().metres();
208:         }
209:         candidate = project_run_contact_into_reach_intersection(
210:             candidate,
211:             predicted_upper_roots,
212:             maximum_reach,
213:         )?;
214:     }
215:     if let Some(height) = terrain_height_at(ScenePlanPoint::from_metres(candidate.xz())?) {
216:         candidate.y = height.metres() + measured_ankle_sole_offset_metres().metres();
217:     }
218:     if !run_contact_reachable_through_stance(candidate, predicted_upper_roots, maximum_reach) {
219:         // A cliff-like sample can have no shared stance footprint even with
220:         // the bounded pelvis allowance. Keep support entry continuous; the
221:         // reach-release latch will end the stance later without reacquiring
222:         // the same lobe if the hip path still diverges.
223:         for _ in 0..3 {
224:             candidate = project_run_contact_into_reach_intersection(
225:                 candidate,
226:                 [predicted_upper_roots[0]; 3],
227:                 maximum_reach,
228:             )?;
229:             if let Some(height) = terrain_height_at(ScenePlanPoint::from_metres(candidate.xz())?) {
230:                 candidate.y = height.metres() + measured_ankle_sole_offset_metres().metres();
231:             }
232:         }
233:     }
234:     Some(candidate)
235: }
236: 
237: pub(in crate::animation::procedural) fn project_run_contact_into_reach_intersection(
238:     mut candidate: Vec3,
239:     predicted_upper_roots: [Vec3; 3],
240:     maximum_reach: ReachLimit,
241: ) -> Option<Vec3> {
242:     let maximum_reach = maximum_reach.native_metres()?;
243:     let horizontal_reaches = predicted_upper_roots.map(|root| {
244:         let vertical_delta = candidate.y - root.y;
245:         (maximum_reach * maximum_reach - vertical_delta * vertical_delta)
246:             .max(0.0)
247:             .sqrt()
248:     });
249:     let mut point = candidate.xz();
250:     let mut corrections = [Vec2::ZERO; 3];
251:     for _ in 0..24 {
252:         for (index, root) in predicted_upper_roots.iter().enumerate() {
253:             let corrected = point + corrections[index];
254:             let offset = corrected - root.xz();
255:             let projected = root.xz() + offset.clamp_length_max(horizontal_reaches[index]);
256:             corrections[index] = corrected - projected;
257:             point = projected;
258:         }
259:     }
260:     candidate.x = point.x;
261:     candidate.z = point.y;
262:     Some(candidate)
263: }
264: 
265: pub(in crate::animation::procedural) fn run_contact_reachable_through_stance(
266:     candidate: Vec3,
267:     predicted_upper_roots: [Vec3; 3],
268:     maximum_reach: ReachLimit,
269: ) -> bool {
270:     let Some(maximum_reach) = maximum_reach.native_metres() else {
271:         return false;
272:     };
273:     predicted_upper_roots
274:         .into_iter()
275:         .all(|root| candidate.distance(root) <= maximum_reach + 0.001)
276: }

