1417: 
1418:         // Native terrain-tap-restart-crossfade frames 39 -> 40: the settle
1419:         // swing is cancelled as the owner resumes 5.5 m/s. The ordinary Run
1420:         // budget moved the reachable ankle only 9.3 cm but amplified its
1421:         // near-extension knee by 12.8 cm. The first-sample settle budget keeps
1422:         // the transported analytic chain below the same 10 cm contract.
1423:         let previous_root = Vec3::new(0.0, 3.0130908, -1.71875);
1424:         let current_root = Vec3::new(0.0, 3.017059, -1.8046875);
1425:         let previous_hip = Vec3::new(0.10195288, 3.057775, -1.7341061);
1426:         let previous_knee = Vec3::new(0.13492808, 2.5361009, -1.7145816);
1427:         let previous_ankle = Vec3::new(0.13445835, 2.1369128, -1.554793);
1428:         let current_hip = Vec3::new(0.10195502, 3.0623627, -1.817662);
1429:         let desired_ankle = Vec3::new(0.13222283, 2.1976547, -1.6857854);
1430:         let previous_owner = previous_ankle - previous_root;
1431:         let resolved_ankle = advance_run_airborne_world_target(
1432:             Some(previous_owner),
1433:             desired_ankle,
1434:             current_root,
1435:             Quat::IDENTITY,
1436:             AnimationElapsed::from_seconds(1.0 / ik_tuning().continuity_sample_hz.hertz()).unwrap(),
1437:             FootTargetSpeeds::configured()
1438:                 .unwrap()
1439:                 .run_sample(false, true),
1440:             |_| {
1441:                 checked_scene_elevation(-100.0)
1442:                     .map(|height| Some(FootClearanceFloor::Minimum(height)))
1443:             },
1444:         )
1445:         .unwrap();
1446:         assert!(
1447:             (resolved_ankle - current_root).distance(previous_owner)
1448:                 <= (ik_tuning().airborne_release_step_metres.metres()
1449:                     * ik_tuning().continuity_sample_hz.hertz())
1450:                     / ik_tuning().continuity_sample_hz.hertz()
1451:                     + 0.0001
1452:         );
1453: 
1454:         let upper_length = previous_hip.distance(previous_knee);
1455:         let lower_length = previous_knee.distance(previous_ankle);
1456:         let previous_end_direction = (previous_ankle - previous_hip).normalize();
1457:         let previous_pole = (previous_knee - previous_hip)
1458:             .reject_from_normalized(previous_end_direction)
1459:             .normalize();
1460:         let next_end_direction = (resolved_ankle - current_hip).normalize();
1461:         let pole = transported_terrain_pole(
1462:             Some(previous_pole),
