1748:     #[test]
1749:     fn terminal_settle_lowers_shared_root_until_both_contacts_are_reachable() {
1750:         // Production-like geometry from the stop capture: the ankle target is
1751:         // at terrain contact, but the restored idle hip leaves the chain more
1752:         // than eight centimetres short. Terminal settle must keep requesting
1753:         // a bounded shared-root drop instead of promoting false support.
1754:         let upper = Vec3::new(-0.10, 3.08, -1.00);
1755:         let target = Vec3::new(-0.12, 2.13, -1.38);
1756:         let reach = ReachLimit::Fixed(NonnegativeLength::from_metres(0.953).unwrap());
1757:         let required = reach
1758:             .terrain_pelvis_shift(upper, target, UnitInterval::ONE)
1759:             .unwrap()
1760:             .metres();
1761:         assert!(required < -0.05);
1762: 
1763:         let mut shift = 0.0;
1764:         let base_root = Vec3::new(0.0, 1.0, 0.0);
1765:         for _ in 0..16 {
1766:             let next = advance_pelvis_shift(
1767:                 SignedLength::from_metres(shift).unwrap(),
1768:                 SignedLength::from_metres(required).unwrap(),
1769:                 AnimationElapsed::from_seconds(1.0 / ik_tuning().continuity_sample_hz.hertz())
1770:                     .unwrap(),
1771:             )
1772:             .unwrap()
1773:             .metres();
1774:             assert!(
1775:                 (next - shift).abs() <= maximum_pelvis_correction_step_metres().metres() + 0.0001
1776:             );
1777:             shift = next;
1778:             // Sparse idle FK may preserve the preceding procedural local.
1779:             // Absolute application from the frozen base must still converge,
1780:             // rather than repeatedly adding the retained scalar.
1781:             let applied_root = base_root + Vec3::Y * shift;
1782:             assert!((applied_root.y - (base_root.y + shift)).abs() <= 0.0001);
1783:         }
1784:         assert!((shift - required).abs() <= 0.0001);
1785:         let applied_root = base_root + Vec3::Y * shift;
1786:         assert!((applied_root.y - (base_root.y + required)).abs() <= 0.0001);
1787: 
1788:         let lowered_upper = upper + Vec3::Y * shift;
1789:         assert!(lowered_upper.distance(target) <= reach.native_metres().unwrap() + 0.0001);
1790: 
1791:         let memory = LegIkMemory {
1792:             settle: Some(LocomotionSettleState {
1793:                 support_foot: LeadFoot::Left,
1794:                 swing_start: target,
1795:                 capture_point: target,
1796:                 landing_target: target,
1797:                 progress: SettleProgress::from_progress(1.0).unwrap(),
1798:                 elapsed_seconds: AnimationElapsed::from_seconds(1.0).unwrap(),
1799:                 raised_handoff: false,
1800:             }),

1801:             left_foot_world_target: Some(target),
1802:             right_foot_world_target: Some(target + Vec3::X * 0.24),
1803:             left_last_rendered_world: Some(target + Vec3::Y * 0.075),
1804:             right_last_rendered_world: Some(target + Vec3::X * 0.24),
1805:             left_last_rendered_toe_world: Some(target + Vec3::Y * 0.075),
1806:             right_last_rendered_toe_world: Some(target + Vec3::X * 0.24),
1807:             ..default()
1808:         };
1809:         assert!(!terminal_settle_contacts_are_rendered(&memory, |_| Some(
1810:             SupportElevation::from_metres(2.045).unwrap()
1811:         )));
1812:     }
