211: pub(crate) fn bind_humanoid_bones(
212:     mut commands: Commands,
213:     bones: Query<(Entity, &AuthoredRigJoint), (Added<AuthoredRigJoint>, Without<MhrBone>)>,
214:     parents: Query<&ChildOf>,
215:     roots: Query<&AnimationRigScene>,
216: ) {
217:     for (entity, identity) in &bones {
218:         if fabelgeist_rig::mhr::membership(identity.name()) == RigJointMembership::Excluded {
219:             continue;
220:         }
221:         let mut current = entity;
222:         for _ in 0..64 {
223:             if let Ok(root) = roots.get(current) {
224:                 let mut bone = commands.entity(entity);
225:                 bone.insert(MhrBone { owner: root.0 });
226:                 if let Some(role) = identity.role() {
227:                     bone.insert(HumanoidBone {
228:                         owner: root.0,
229:                         role,
230:                     });

231:                 }
232:                 break;
233:             }
234:             let Ok(parent) = parents.get(current) else {
235:                 break;
236:             };
237:             current = parent.parent();
238:         }
239:     }
240: }
