242: #[expect(
243:     clippy::too_many_arguments,
244:     reason = "Bevy injects each independently borrowed rig topology query as a system parameter"
245: )]
246: pub(crate) fn cache_humanoid_rigs(
247:     mut commands: Commands,
248:     all_bones: Query<(Entity, &HumanoidBone)>,
249:     all_mhr_bones: Query<(Entity, &MhrBone, &AuthoredRigJoint)>,
250:     cached: Query<(Entity, &HumanoidRig)>,
251:     added: Query<(), Added<HumanoidBone>>,
252:     added_mhr: Query<(), Added<MhrBone>>,
253:     mut removed: RemovedComponents<HumanoidBone>,
254:     mut removed_mhr: RemovedComponents<MhrBone>,
255:     rig_scenes: Query<(Entity, &AnimationRigScene)>,
256: ) {
257:     let topology_changed = !added.is_empty()
258:         || !added_mhr.is_empty()
259:         || removed.read().next().is_some()
260:         || removed_mhr.read().next().is_some();
261:     if !topology_changed {
262:         return;
263:     }
264:     let mut rigs = BTreeMap::<Entity, HumanoidRig>::new();
265:     for (entity, bone) in &all_bones {
266:         let rig = rigs.entry(bone.owner).or_default();
267:         if let Some(previous) = rig.retain_stable_role(bone.role, entity) {
268:             let retained = previous.min(entity);
269:             warn!(
270:                 owner = ?bone.owner,
271:                 role = ?bone.role,
272:                 ?retained,
273:                 "Duplicate humanoid bone role; retaining the lowest stable entity id"
274:             );
275:         }
276:     }
277:     let rig_roots = rig_scenes
278:         .iter()
279:         .map(|(root, scene)| (scene.0, root))
280:         .collect::<BTreeMap<_, _>>();
281:     let mut named = BTreeMap::<Entity, BTreeMap<RigJointName, Entity>>::new();
282:     for (entity, bone, name) in &all_mhr_bones {
283:         named
284:             .entry(bone.owner)
285:             .or_default()
286:             .insert(name.name().clone(), entity);
287:     }
288:     for (owner, _) in &cached {
289:         if !rigs.contains_key(&owner) {
290:             commands.entity(owner).remove::<HumanoidRig>();
291:         }
292:     }
293:     for (owner, mut rig) in rigs {
294:         let sole_axes = cached
295:             .get(owner)
296:             .map(|(_, rig)| rig.sole_axes)
297:             .unwrap_or_default();
298:         let names = named.remove(&owner).unwrap_or_default();
299:         let mirror = MhrMirrorTopology::from_names(&names);
300:         if let Ok(mut entity) = commands.get_entity(owner) {
301:             rig.rig_scene = rig_roots.get(&owner).copied();
302:             rig.sole_axes = sole_axes;
303:             rig.mirror = mirror;
304:             entity.insert(rig);
305:         }
306:     }
307: }
