309: /// Captures the foot's bind-space sole normal from the authored global bind
310: /// transform. The MHR foot joint has no guaranteed cardinal local sole-up axis,
311: /// so the authored flat bind pose defines it explicitly.
312: pub(crate) fn capture_humanoid_rig_axes(
313:     mut commands: Commands,
314:     feet: Query<(Entity, &HumanoidBone, &AuthoredBindTransform), Without<SoleAxisCaptured>>,
315:     bind_nodes: Query<(&AuthoredBindTransform, Option<&ChildOf>)>,
316:     mut rigs: Query<&mut HumanoidRig>,
317: ) {
318:     for (entity, bone, _) in &feet {
319:         let foot = match bone.role {
320:             BoneRole::FootLeft => LeadFoot::Left,
321:             BoneRole::FootRight => LeadFoot::Right,
322:             _ => continue,
323:         };
324:         let Some(bind_global) = authored_bind_global(entity, bone.owner, &bind_nodes) else {
325:             continue;
326:         };
327:         // Never infer the sole plane from the ankle-to-toe joint vector. That
328:         // vector slopes down through a normally planted foot; forcing it
329:         // horizontal raises the visible forefoot and produces the toe-up IK
330:         // pose. Sampling the live FK rotation is likewise invalid because it
331:         // permanently calibrates the sole from an arbitrary gait frame.
332:         let axis = sole_up_axis_from_bind(bind_global.rotation());
333:         if let Some(axis) = axis.try_normalize() {
334:             commands.entity(entity).insert(SoleAxisCaptured);
335:             if let Ok(mut rig) = rigs.get_mut(bone.owner) {
336:                 match foot {
337:                     LeadFoot::Left => rig.sole_axes.left = Some(axis),
338:                     LeadFoot::Right => rig.sole_axes.right = Some(axis),
339:                 }
340:             }
341:         }
342:     }
343: }
344: 
345: pub(crate) fn authored_bind_global(
346:     entity: Entity,
347:     owner: Entity,
348:     bind_nodes: &Query<(&AuthoredBindTransform, Option<&ChildOf>)>,
349: ) -> Option<GlobalTransform> {
350:     let mut current = entity;
351:     let mut locals = Vec::new();
352:     for _ in 0..64 {
353:         let Ok((bind, parent)) = bind_nodes.get(current) else {
354:             break;
355:         };
356:         if bind.owner != owner {
357:             break;
358:         }
359:         locals.push(bind.local);
360:         let Some(parent) = parent else {
361:             break;
362:         };
363:         current = parent.parent();
364:     }
365:     (!locals.is_empty()).then(|| {
366:         locals
367:             .into_iter()
368:             .rev()
369:             .fold(GlobalTransform::IDENTITY, |global, local| {
370:                 global.mul_transform(local)
371:             })
372:     })
373: }
