379: pub(crate) fn pole_to_world(owner_rotation: Quat, owner_local_pole: Vec3) -> Vec3 {
380:     owner_rotation * owner_local_pole
381: }
382: 
383: pub(crate) fn pole_to_owner(owner_rotation: Quat, world_pole: Vec3) -> Vec3 {
384:     owner_rotation.inverse() * world_pole
385: }
