327: impl BindAxis {
328:     fn resolve(self, bind: &impl Fn(BoneRole) -> Option<Transform>) -> Vec3 {
329:         bind(self.from)
330:             .zip(bind(self.to))
331:             .and_then(|(from, to)| (to.translation - from.translation).try_normalize())
332:             .unwrap_or(self.fallback)
333:     }
