336: impl RagdollDefinition {
337:     /// Build the ragdoll from a character's owner-space bind transforms.
338:     /// `None` when a driving bone is missing from the rig.
339:     pub(super) fn from_bind_pose(
340:         bind: impl Fn(BoneRole) -> Option<Transform>,
341:         capsules: &RagdollCapsulesConfig,
342:     ) -> GeometryResult<Option<Self>> {
343:         let forward = character_forward(&bind);
344:         let Some(bodies) = BODY_SPECS
345:             .iter()
346:             .map(|spec| {
347:                 let bind_transform = bind(spec.role)?;
348:                 let capsule = spec.capsule.select(capsules);
349:                 let direction = spec.axis.resolve(&bind);
350:                 Some(RagdollBody {
351:                     role: spec.role,
352:                     bind: bind_transform,
353:                     shape: CapsuleShape {
354:                         radius: capsule.radius_metres,
355:                         length: capsule.length_metres,
356:                     },
357:                     collider_local: Transform::from_translation(
358:                         direction * (capsule.length_metres.metres() * 0.5),
359:                     )
360:                     .with_rotation(Quat::from_rotation_arc(Vec3::Y, direction)),
361:                     kinematic: spec.kinematic,
362:                 })
363:             })
364:             .collect::<Option<Vec<_>>>()
365:         else {
366:             return Ok(None);
367:         };
368:         let body_index = |role: BoneRole| bodies.iter().position(|body| body.role == role);
369:         let mut joints = Vec::with_capacity(JOINT_SPECS.len());
370:         for spec in &JOINT_SPECS {
371:             let (Some(parent), Some(child)) = (body_index(spec.parent), body_index(spec.child))
372:             else {
373:                 return Ok(None);
374:             };
375:             let child_position = bodies[child].bind.translation;
376:             let anchor = match spec.anchor {
377:                 AnchorAt::Child => child_position,
378:                 AnchorAt::Midpoint => (bodies[parent].bind.translation + child_position) * 0.5,
379:                 AnchorAt::Role(role) => bind(role).map_or(child_position, |t| t.translation),
380:             };
381:             let kind = match spec.kind {
382:                 JointSpecKind::Spherical {
383:                     twist,
384:                     swing_limit,
385:                     twist_limit,
386:                 } => RagdollJointKind::Spherical {
387:                     twist_axis: twist.resolve(&bind),
388:                     swing: Radians::new(swing_limit)?,
389:                     twist: Radians::new(twist_limit)?,
390:                 },
391:                 JointSpecKind::Hinge { bone, flex, limits } => RagdollJointKind::Hinge {
392:                     axis: hinge_axis(bone.resolve(&bind), flex, forward),
393:                     limits: JointAngleLimits {
394:                         minimum: Radians::new(limits.0)?,
395:                         maximum: Radians::new(limits.1)?,
396:                     },
397:                 },
398:             };
399:             joints.push(RagdollJoint {
400:                 parent,
401:                 child,
402:                 anchor,
403:                 kind,
404:             });
405:         }
406:         Ok(Some(Self { bodies, joints }))
407:     }
408: 
409:     pub(super) fn body_of(&self, role: BoneRole) -> Option<usize> {
410:         self.bodies.iter().position(|body| body.role == role)
411:     }
412: }
