462: /// Owner-space character forward, read from the feet so the definition does
463: /// not assume which way the authored rig faces; the controller convention
464: /// (`-Z`) is the fallback.
465: fn character_forward(bind: &impl Fn(BoneRole) -> Option<Transform>) -> Vec3 {
466:     let measured = [(FootLeft, ToeLeft), (FootRight, ToeRight)]
467:         .into_iter()
468:         .filter_map(|(foot, toe)| {
469:             let toe = bind(toe)?.translation;
470:             let foot = bind(foot)?.translation;
471:             Vec3::new(toe.x - foot.x, 0.0, toe.z - foot.z).try_normalize()
472:         })
473:         .sum::<Vec3>();
474:     measured.try_normalize().unwrap_or(Vec3::NEG_Z)
475: }
476: 
477: /// The hinge axis about which a positive angle folds `bone_direction`
478: /// toward the flex direction: rotating `v` about `v × f` moves `v` toward
479: /// `f`. A limb already lying along its flex direction falls back to the
480: /// character's lateral axis.
481: fn hinge_axis(bone_direction: Vec3, flex: FlexDirection, forward: Vec3) -> Vec3 {
482:     let flex_direction = match flex {
483:         FlexDirection::Forward => forward,
484:         FlexDirection::Backward => -forward,
485:     };
486:     bone_direction
487:         .cross(flex_direction)
488:         .try_normalize()
489:         .unwrap_or_else(|| forward.cross(Vec3::Y).normalize_or_zero())
490: }
