1: //! Physics as a pose source: read the bodies back into the pose buffer,
2: //! re-assert that pose after the procedural passes, and keep the bodies out
3: //! of the authoritative terrain heightfield.
4: 
5: use super::super::pose_buffer::{LocalPose, PoseBufferRig};
6: use super::{
7:     RagdollBodyPart, Ragdolling,
8:     entry::{joint_base_affine, joint_world_affines},
9: };
10: use adventuresim_building_generator::spatial_geometry::{
11:     GeometryResult, Position as ScenePosition, SignedLength,
12: };
13: use adventuresim_tactical_core::{
14:     city_layout::grounding::SupportElevation,
15:     prelude::*,
16:     scene_coordinates::{Scene, ScenePlanPoint},
17: };
18: use bevy::{math::Affine3A, prelude::*};
19: use fabelgeist_rig::{RigJointOrdinal, RigJointTable};
20: 
21: /// Read the ragdoll bodies back into the pose buffer: driven joints follow
22: /// their body (converted to joint-local through the live parent chain),
23: /// undriven ancestors of driven joints are held exactly, and everything else
24: /// (fingers, toes, the face) keeps its last pose.
25: pub(in crate::animation) fn drive_ragdoll_pose_buffers(
26:     chain: Query<(&Transform, Option<&ChildOf>)>,
27:     mut rigs: Query<(&mut PoseBufferRig, &Ragdolling)>,
28: ) {
29:     for (mut rig, ragdoll) in &mut rigs {
30:         let count = rig.joint_count();
31:         let mut driven = RigJointTable::from(vec![false; count]);
32:         for (joint, body) in ragdoll.joint_bodies.indexed() {
33:             driven[joint] = body
34:                 .and_then(|body| ragdoll.bodies[body])
35:                 .is_some_and(|entity| chain.contains(entity));
36:         }
37:         // Undriven joints with a driven descendant must hold exactly `next`:
38:         // an interpolated or offset value there shears every physics bone
39:         // off its body.
40:         let mut ancestor_of_driven = RigJointTable::from(vec![false; count]);
41:         for &joint in ragdoll.joint_order.iter().rev() {
42:             if (driven[joint] || ancestor_of_driven[joint])
43:                 && let Some(parent) = rig.joint_parent(joint)
44:             {
45:                 ancestor_of_driven[parent] = true;
46:             }
47:         }
48:         let mut world = RigJointTable::from(vec![Affine3A::IDENTITY; count]);
49:         for &joint in &ragdoll.joint_order {
50:             let parent_affine = match rig.joint_parent(joint) {
51:                 Some(parent) => world[parent],
52:                 None => joint_base_affine(&rig, joint, &chain),
53:             };
54:             if driven[joint] {
55:                 let body = ragdoll.joint_bodies[joint].expect("driven joints map to a body");
56:                 let entity = ragdoll.bodies[body].expect("driven joints have a body entity");
57:                 let body_affine = chain
58:                     .get(entity)
59:                     .map(|(transform, _)| transform.compute_affine())
60:                     .expect("driven joints have a body transform");
61:                 let bind = ragdoll.definition.bodies[body].bind;
62:                 // `bone = body * bind_rotation`, at the scale the real
63:                 // ancestor chain carries, or the model root's scale would
64:                 // re-apply on top of world-unit locals.
65:                 let bone_world = body_affine
66:                     * Affine3A::from_scale_rotation_translation(
67:                         bind.scale * ragdoll.scale,
68:                         bind.rotation,
69:                         Vec3::ZERO,
70:                     );
71:                 let (_, rotation, translation) =
72:                     (parent_affine.inverse() * bone_world).to_scale_rotation_translation();
73:                 let scale = rig.upcoming_pose(joint).scale;
74:                 rig.pin_joint(
75:                     joint,
76:                     LocalPose {
77:                         translation,
78:                         rotation,
79:                         scale,
80:                     },
81:                 );
82:                 world[joint] = bone_world;
83:             } else {
84:                 if ancestor_of_driven[joint] {
85:                     rig.hold_joint(joint);
86:                 }
87:                 world[joint] = parent_affine * rig.upcoming_pose(joint).affine();
88:             }
89:         }
90:     }
91: }
92: 
93: /// Re-assert the physics pose after every procedural pass: while the body
94: /// is a ragdoll nothing else may displace a driven bone from its body.
95: pub(in crate::animation) fn apply_ragdoll_poses(
96:     rigs: Query<&PoseBufferRig, With<Ragdolling>>,
97:     mut transforms: Query<&mut Transform, Without<PoseBufferRig>>,
98: ) {
99:     for rig in &rigs {
100:         for joint in (0..rig.joint_count()).map(RigJointOrdinal::from) {
101:             let Some(entity) = rig.joint_entity(joint) else {
102:                 continue;
103:             };
104:             let pose = rig.displayed_pose(joint);
105:             if let Ok(mut transform) = transforms.get_mut(entity) {
106:                 transform.translation = pose.translation;
107:                 transform.rotation = pose.rotation;
108:                 transform.scale = pose.scale;
109:             }
110:         }
111:     }
112: }
113: 
114: /// Resolve body contacts against the authoritative terrain heightfield. The
115: /// client has no terrain collider; keeping terrain response out of Avian's
116: /// contact graph also keeps this client-only island apart from the disabled
117: /// replicated collision world.
118: pub(in crate::animation) fn resolve_ragdoll_terrain_contacts(
119:     terrains: Query<&SceneTerrain>,
120:     mut bodies: Query<(
121:         &RagdollBodyPart,
122:         &mut Position,
123:         &Rotation,
124:         &mut LinearVelocity,
125:     )>,
126: ) {
127:     let retention = runtime_animation_config()
128:         .ragdoll
129:         .terrain_horizontal_velocity_retention;
130:     for (part, mut position, rotation, mut velocity) in &mut bodies {
131:         if part.kinematic {
132:             continue;
133:         }
134:         let penetration = match capsule_terrain_penetration(part, position.0, rotation.0, |point| {
135:             terrains
136:                 .iter()
137:                 .filter_map(|terrain| terrain.height_at(point))
138:                 .reduce(SupportElevation::max)
139:         }) {
140:             Ok(penetration) => penetration,
141:             Err(error) => {
142:                 warn!(%error, "Ragdoll terrain penetration rejected");
143:                 continue;
144:             }
145:         };
146:         if penetration.metres() <= 0.0 {
147:             continue;
148:         }
149:         let corrected = position.0.with_y(position.0.y + penetration.metres());
150:         let corrected = match ScenePosition::<Scene>::from_metres(corrected) {
151:             Ok(corrected) => corrected,
152:             Err(error) => {
153:                 warn!(%error, "Ragdoll terrain correction rejected");
154:                 continue;
155:             }
156:         };
157:         position.0 = corrected.metres();
158:         if velocity.y < 0.0 {
159:             // Settle rather than rebound through the surface between
160:             // presentation frames.
161:             velocity.y = 0.0;
162:         }
163:         velocity.x *= retention.fraction();
164:         velocity.z *= retention.fraction();
165:     }
166: }
167: 
168: /// How far a capsule sits below the terrain, sampling both end spheres and
169: /// the centre: a single centre test lets a tilted limb tunnel into a slope
170: /// whenever its low endpoint is over higher terrain.
171: fn capsule_terrain_penetration(
172:     part: &RagdollBodyPart,
173:     position: Vec3,
174:     rotation: Quat,
175:     mut height_at: impl FnMut(ScenePlanPoint) -> Option<SupportElevation>,
176: ) -> GeometryResult<SignedLength> {
177:     let center = position + rotation * part.center_local;
178:     let axis = rotation * part.axis_local * part.half_length.metres();
179:     let penetration = [center - axis, center, center + axis]
180:         .into_iter()
181:         .filter_map(|sample| {
182:             let point = ScenePlanPoint::from_metres(sample.xz())?;
183:             height_at(point).map(|height| height.metres() + part.radius.metres() - sample.y)
184:         })
185:         .fold(0.0_f32, f32::max);
186:     SignedLength::from_metres(penetration)
187: }
