1: //! Ragdoll entry: seed every body from the live pose buffer, then spawn the
2: //! bodies, colliders, and joints.
3: //!
4: //! The seed is pure: each body's world pose comes from the buffered joint
5: //! transforms composed under the live rig base, and its velocity from the
6: //! finite difference of the two buffered samples plus the whole-body
7: //! momentum, so a mid-swing limb carries its swing into physics.
8: 
9: use super::super::pose_buffer::PoseBufferRig;
10: use super::geometry::RagdollGeometry;
11: use super::{
12:     RAGDOLL_LAYER, RagdollBodyPart, RagdollPart,
13:     definition::{RagdollDefinition, RagdollJointKind},
14: };
15: use adventuresim_building_generator::spatial_geometry::GeometryResult;
16: use adventuresim_tactical_core::prelude::*;
17: use bevy::{math::Affine3A, prelude::*};
18: use fabelgeist_rig::{RigJointOrdinal, RigJointTable};
19: 
20: /// Finite-difference denominator floor in seconds for a coincident sample pair.
21: const MINIMUM_VELOCITY_INTERVAL_SECONDS: f32 = 0.00001;
22: 
23: /// One body's entry state: world pose plus the velocities the animation was
24: /// carrying.
25: #[derive(Debug, Clone, Copy)]
26: pub(super) struct BodySeed {
27:     pub(super) position: Vec3,
28:     pub(super) rotation: Quat,
29:     pub(super) linear: Vec3,
30:     pub(super) angular: Vec3,
31: }
32: 
33: /// One motored joint: pull `child` toward `relative`, its entry orientation
34: /// expressed in `parent`'s frame. Indices into the definition's bodies.
35: #[derive(Debug, Clone, Copy)]
36: pub(super) struct MuscleTarget {
37:     pub(super) parent: usize,
38:     pub(super) child: usize,
39:     pub(super) relative: Quat,
40: }
41: 
42: pub(super) struct SpawnedRagdoll {
43:     pub(super) parts: Vec<Entity>,
44:     pub(super) bodies: Vec<Option<Entity>>,
45:     pub(super) muscles: Vec<MuscleTarget>,
46: }
47: 
48: /// World affine of `entity` from the live `Transform` chain. The cached
49: /// `GlobalTransform` is last frame's propagation, one frame behind a root
50: /// that presentation moves in `Update`; deriving bone locals through it
51: /// shifts the whole skeleton by a frame of root motion.
52: pub(super) fn live_world_affine(
53:     entity: Entity,
54:     chain: &Query<(&Transform, Option<&ChildOf>)>,
55: ) -> Affine3A {
56:     let mut affine = Affine3A::IDENTITY;
57:     let mut current = Some(entity);
58:     while let Some(entity) = current {
59:         let Ok((transform, parent)) = chain.get(entity) else {
60:             break;
61:         };
62:         affine = transform.compute_affine() * affine;
63:         current = parent.map(ChildOf::parent);
64:     }
65:     affine
66: }
67: 
68: /// Pose-buffer joints ordered parent before child.
69: pub(super) fn topological_joint_order(rig: &PoseBufferRig) -> Vec<RigJointOrdinal> {
70:     let count = rig.joint_count();
71:     let mut order = Vec::with_capacity(count);
72:     let mut placed = RigJointTable::from(vec![false; count]);
73:     while order.len() < count {
74:         let before = order.len();
75:         for joint in (0..count).map(RigJointOrdinal::from) {
76:             if !placed[joint] && rig.joint_parent(joint).is_none_or(|parent| placed[parent]) {
77:                 placed[joint] = true;
78:                 order.push(joint);
79:             }
80:         }
81:         if order.len() == before {
82:             // A parent cycle cannot happen in a scene hierarchy; refuse to
83:             // spin rather than trust it.
84:             break;
85:         }
86:     }
87:     order
88: }
89: 
90: /// World affine the parent-less joints compose under: the live world of
91: /// the scene node they hang from.
92: pub(super) fn joint_base_affine(
93:     rig: &PoseBufferRig,
94:     joint: RigJointOrdinal,
95:     chain: &Query<(&Transform, Option<&ChildOf>)>,
96: ) -> Affine3A {
97:     rig.joint_entity(joint)
98:         .and_then(|entity| chain.get(entity).ok())
99:         .and_then(|(_, parent)| parent.map(ChildOf::parent))
100:         .map(|parent| live_world_affine(parent, chain))
101:         .unwrap_or(Affine3A::IDENTITY)
102: }
103: 
104: /// World affines of every joint for the previous and upcoming buffered
105: /// samples, composed in `order`.
106: pub(super) fn joint_world_affines(
107:     rig: &PoseBufferRig,
108:     order: &[RigJointOrdinal],
109:     base: &dyn Fn(RigJointOrdinal) -> Affine3A,
110: ) -> (RigJointTable<Affine3A>, RigJointTable<Affine3A>) {
111:     let count = rig.joint_count();
112:     let mut previous = RigJointTable::from(vec![Affine3A::IDENTITY; count]);
113:     let mut next = RigJointTable::from(vec![Affine3A::IDENTITY; count]);
114:     for &joint in order {
115:         let (parent_previous, parent_next) = match rig.joint_parent(joint) {
116:             Some(parent) => (previous[parent], next[parent]),
117:             None => {
118:                 let base = base(joint);
119:                 (base, base)
120:             }
121:         };
122:         previous[joint] = parent_previous * rig.previous_pose(joint).affine();
123:         next[joint] = parent_next * rig.upcoming_pose(joint).affine();
124:     }
125:     (previous, next)
126: }
127: 
128: /// Seed each body from the buffered joint that drives it. `momentum` is the
129: /// whole-body velocity added on top of the per-bone animation velocities.
130: pub(super) fn seed_bodies(
131:     definition: &RagdollDefinition,
132:     rig: &PoseBufferRig,
133:     joint_bodies: &RigJointTable<Option<usize>>,
134:     world_previous: &RigJointTable<Affine3A>,
135:     world_next: &RigJointTable<Affine3A>,
136:     momentum: Vec3,
137:     config: &RagdollConfig,
138: ) -> Vec<Option<BodySeed>> {
139:     let sample_interval = rig.sample_interval();
140:     let mut seeds = vec![None; definition.bodies.len()];
141:     for (joint, body) in joint_bodies.indexed() {
142:         let Some(body) = *body else {
143:             continue;
144:         };
145:         let bind_rotation = definition.bodies[body].bind.rotation;
146:         let (_, rotation_next, position_next) = world_next[joint].to_scale_rotation_translation();
147:         let (_, rotation_previous, position_previous) =
148:             world_previous[joint].to_scale_rotation_translation();
149:         // `body = bone * bind_rotation⁻¹`: the body rests at identity where
150:         // the bone rests at its bind rotation.
151:         let rotation = (rotation_next * bind_rotation.inverse()).normalize();
152:         let angular = angular_velocity_between(rotation_next, rotation_previous, sample_interval)
153:             .clamp_length_max(
154:                 config
155:                     .maximum_seed_spin_radians_per_second
156:                     .radians_per_second(),
157:             );
158:         let linear = momentum
159:             + ((position_next - position_previous) / sample_interval.seconds()).clamp_length_max(
160:                 config
161:                     .maximum_seed_speed_metres_per_second
162:                     .metres_per_second(),
163:             );
164:         let kinematic = definition.bodies[body].kinematic;
165:         seeds[body] = Some(BodySeed {
166:             position: position_next,
167:             rotation,
168:             linear: if kinematic { Vec3::ZERO } else { linear },
169:             angular: if kinematic { Vec3::ZERO } else { angular },
170:         });
171:     }
172:     seeds
173: }
174: 
175: /// Spawn bodies at their seeds, colliders under them, and the joints between
176: /// them. Muscle targets capture each joint's relative orientation at entry.
177: pub(super) fn spawn_ragdoll(
178:     commands: &mut Commands,
179:     owner: Entity,
180:     definition: &RagdollDefinition,
181:     seeds: &[Option<BodySeed>],
182:     scale: f32,
183:     config: &RagdollConfig,
184: ) -> GeometryResult<SpawnedRagdoll> {
185:     let geometry = RagdollGeometry::prepare(
186:         definition,
187:         seeds,
188:         scale,
189:         config.speculative_contact_margin_metres,
190:     )?;
191:     let mut parts = Vec::new();
192:     let bodies = spawn_bodies(commands, owner, definition, seeds, &geometry, &mut parts);
193:     let muscles = spawn_joints(
194:         commands, owner, definition, seeds, scale, &bodies, &mut parts,
195:     );
196:     Ok(SpawnedRagdoll {
197:         parts,
198:         bodies,
199:         muscles,
200:     })

201: }
202: 
203: /// Angular velocity (rad/s) carrying `current` onto `next` over
204: /// `delta_seconds`, along the short arc.
205: fn angular_velocity_between(
206:     next: Quat,
207:     current: Quat,
208:     interval: adventuresim_tactical_core::animation::PositiveAnimationDuration,
209: ) -> Vec3 {
210:     let mut delta = next * current.inverse();
211:     if delta.w < 0.0 {
212:         delta = -delta;
213:     }
214:     delta.to_scaled_axis() / interval.seconds().max(MINIMUM_VELOCITY_INTERVAL_SECONDS)
215: }
216: 
217: /// Spawn one rigid body per seeded definition body, each with a capsule
218: /// collider child. Returns the body entity for each definition index.
219: fn spawn_bodies(
220:     commands: &mut Commands,
221:     owner: Entity,
222:     definition: &RagdollDefinition,
223:     seeds: &[Option<BodySeed>],
224:     geometry: &RagdollGeometry,
225:     parts: &mut Vec<Entity>,
226: ) -> Vec<Option<Entity>> {
227:     let mut bodies = vec![None; definition.bodies.len()];
228:     for (index, body) in definition.bodies.iter().enumerate() {
229:         let Some(seed) = seeds[index] else {
230:             continue;
231:         };
232:         let rigid_body = if body.kinematic {
233:             RigidBody::Kinematic
234:         } else {
235:             RigidBody::Dynamic
236:         };
237:         let Some(capsule) = &geometry.capsules[index] else {
238:             continue;
239:         };
240:         let entity = commands
241:             .spawn((
242:                 Name::new(format!("Presentation ragdoll {:?}", body.role)),
243:                 rigid_body,
244:                 Position::new(seed.position),
245:                 Rotation(seed.rotation),
246:                 Transform::from_translation(seed.position).with_rotation(seed.rotation),
247:                 LinearVelocity(seed.linear),
248:                 AngularVelocity(seed.angular),
249:                 // Render-rate easing between physics steps; the pose readback
250:                 // in `PostUpdate` then sees smooth body transforms.
251:                 TransformInterpolation,
252:                 // A resting body cycling sleep/wake reads as floor shaking,
253:                 // and these bodies despawn on exit anyway.
254:                 SleepingDisabled,
255:                 SpeculativeMargin(geometry.margin.metres()),
256:                 RagdollPart { owner },
257:                 capsule.part,
258:             ))
259:             .remove::<RigidBodyDisabled>()
260:             .id();
261:         commands.spawn((
262:             ChildOf(entity),
263:             capsule.collider_local,
264:             Collider::capsule(capsule.part.radius.metres(), capsule.segment.metres()),
265:             // A client-only collision island: non-neighbouring parts collide
266:             // with one another and nothing else.
267:             CollisionLayers::new(RAGDOLL_LAYER, RAGDOLL_LAYER),
268:         ));
269:         parts.push(entity);
270:         bodies[index] = Some(entity);
271:     }
272:     bodies
273: }
