275: /// Spawn the joint between each pair of spawned bodies and record the
276: /// muscle target that holds it at its entry orientation.
277: fn spawn_joints(
278:     commands: &mut Commands,
279:     owner: Entity,
280:     definition: &RagdollDefinition,
281:     seeds: &[Option<BodySeed>],
282:     scale: f32,
283:     bodies: &[Option<Entity>],
284:     parts: &mut Vec<Entity>,
285: ) -> Vec<MuscleTarget> {
286:     let mut muscles = Vec::with_capacity(definition.joints.len());
287:     for joint in &definition.joints {
288:         let (Some(parent), Some(child)) = (bodies[joint.parent], bodies[joint.child]) else {
289:             continue;
290:         };
291:         let (Some(parent_seed), Some(child_seed)) = (seeds[joint.parent], seeds[joint.child])
292:         else {
293:             continue;
294:         };
295:         let anchor1 = (joint.anchor - definition.bodies[joint.parent].bind.translation) * scale;
296:         let anchor2 = (joint.anchor - definition.bodies[joint.child].bind.translation) * scale;
297:         let entity = match joint.kind {
298:             RagdollJointKind::Spherical {
299:                 twist_axis,
300:                 swing,
301:                 twist,
302:             } => commands
303:                 .spawn((
304:                     SphericalJoint::new(parent, child)
305:                         .with_local_anchor1(anchor1)
306:                         .with_local_anchor2(anchor2)
307:                         .with_twist_axis(twist_axis)
308:                         .with_swing_limits(-swing.radians(), swing.radians())
309:                         .with_twist_limits(-twist.radians(), twist.radians()),
310:                     JointCollisionDisabled,
311:                     RagdollPart { owner },
312:                 ))
313:                 .id(),
314:             RagdollJointKind::Hinge { axis, limits } => commands
315:                 .spawn((
316:                     RevoluteJoint::new(parent, child)
317:                         .with_local_anchor1(anchor1)
318:                         .with_local_anchor2(anchor2)
319:                         .with_hinge_axis(axis)
320:                         .with_angle_limits(limits.minimum.radians(), limits.maximum.radians()),
321:                     JointCollisionDisabled,
322:                     RagdollPart { owner },
323:                 ))
324:                 .id(),
325:         };
326:         parts.push(entity);
327:         muscles.push(MuscleTarget {
328:             parent: joint.parent,
329:             child: joint.child,
330:             relative: parent_seed.rotation.inverse() * child_seed.rotation,
331:         });
332:     }
333:     muscles
334: }
