1: //! PD muscles and relative joint damping, stepped once per physics tick.
2: //!
3: //! Each joint chases the pose the body fell in with angular-velocity kicks,
4: //! equal and opposite across the pair. Avian's spherical joints have no
5: //! motor, so external kicks are the one uniform mechanism for every joint.
6: //! The kinematic pelvis is never written: it belongs to the authoritative
7: //! controller, and its children absorb the whole correction.
8: 
9: use adventuresim_tactical_core::animation::{AnimationValueResult, MuscleTone};
10: use adventuresim_tactical_core::prelude::*;
11: use bevy::prelude::*;
12: 
13: use super::{Ragdolling, definition::PELVIS_BODY};
14: 
15: /// Muscle tone over a ragdoll's life: overwhelmed at impact, gathering
16: /// itself over the rise, then letting go so the body settles instead of
17: /// bracing forever.
18: pub(super) fn muscle_strength(
19:     age: AnimationElapsed,
20:     muscles: &RagdollMusclesConfig,
21: ) -> AnimationValueResult<MuscleTone> {
22:     let age_seconds = age.seconds();
23:     let rise = quintic_rise(
24:         (age_seconds - muscles.stun_seconds.seconds()) / muscles.rise_seconds.seconds().max(1e-3),
25:     );
26:     let limp = match muscles.limp_at_seconds {
27:         MuscleRelease::After(start) => {
28:             1.0 - ((age_seconds - start.seconds()) / muscles.limp_seconds.seconds().max(1e-3))
29:                 .clamp(0.0, 1.0)
30:         }
31:         MuscleRelease::Never => 1.0,
32:     };
33:     MuscleTone::from_envelope(
34:         muscles.tone.gain()
35:             * (muscles.stun_floor.fraction() + (1.0 - muscles.stun_floor.fraction()) * rise)
36:             * limp,
37:     )
38: }
39: 
40: pub(in crate::animation) fn apply_muscles(
41:     time: Res<Time>,
42:     mut ragdolls: Query<&mut Ragdolling>,
43:     mut bodies: Query<(&Rotation, &mut AngularVelocity)>,
44: ) {
45:     let config = ragdoll_tuning();
46:     let elapsed = AnimationElapsed::from(time.delta());
47:     let delta_seconds = elapsed.seconds();
48:     for mut ragdoll in &mut ragdolls {
49:         let age = match ragdoll.age_seconds.checked_add(elapsed) {
50:             Ok(age) => age,
51:             Err(error) => {
52:                 warn!(%error, "Rejected presentation ragdoll age");
53:                 continue;
54:             }
55:         };
56:         let strength = match muscle_strength(age, &config.muscles) {
57:             Ok(strength) => strength,
58:             Err(error) => {
59:                 warn!(%error, "Rejected presentation muscle envelope");
60:                 continue;
61:             }
62:         };
63:         ragdoll.age_seconds = age;
64:         if strength.gain() <= 1e-4 {
65:             continue;
66:         }
67:         for muscle in &ragdoll.muscles {
68:             let (Some(parent), Some(child)) =
69:                 (ragdoll.bodies[muscle.parent], ragdoll.bodies[muscle.child])
70:             else {
71:                 continue;
72:             };
73:             let Ok(
74:                 [
75:                     (parent_rotation, mut parent_spin),
76:                     (child_rotation, mut child_spin),
77:                 ],
78:             ) = bodies.get_many_mut([parent, child])
79:             else {
80:                 continue;
81:             };
82:             // The rotation carrying the child onto its target pose relative
83:             // to the parent, along the short arc.
84:             let mut error = (parent_rotation.0 * muscle.relative) * child_rotation.0.inverse();
85:             if error.w < 0.0 {
86:                 error = -error;
87:             }
88:             let relative_spin = child_spin.0 - parent_spin.0;
89:             let kick = ((error.to_scaled_axis()
90:                 * config.muscles.proportional_gain.per_second_squared()
91:                 - relative_spin * config.muscles.derivative_gain.per_second())
92:                 * (strength.gain() * delta_seconds))
93:                 .clamp_length_max(
94:                     config
95:                         .muscles
96:                         .maximum_kick_radians_per_second
97:                         .radians_per_second(),
98:                 );
99:             if kick.length_squared() <= 1e-8 {
100:                 continue;
101:             }
102:             let (parent_delta, child_delta) = split_kick(muscle.parent, kick);
103:             if parent_delta != Vec3::ZERO {
104:                 parent_spin.0 += parent_delta;
105:             }
106:             child_spin.0 += child_delta;
107:         }
108:     }
109: }
110: 
111: /// Drain the spin of each child relative to its parent so limbs stop
112: /// flopping while the body as a whole keeps tumbling. Runs after the
113: /// muscles so it also drains what the pull created.
114: pub(in crate::animation) fn damp_joints(
115:     time: Res<Time>,
116:     ragdolls: Query<&Ragdolling>,
117:     mut velocities: Query<&mut AngularVelocity>,
118: ) {
119:     let config = ragdoll_tuning();
120:     let factor = match config
121:         .joint_relative_damping_per_second
122:         .step_fraction(AnimationElapsed::from(time.delta()))
123:     {
124:         Ok(factor) => factor,
125:         Err(error) => {
126:             warn!(%error, "Rejected ragdoll joint damping");
127:             return;
128:         }
129:     };
130:     for ragdoll in &ragdolls {
131:         for muscle in &ragdoll.muscles {
132:             let (Some(parent), Some(child)) =
133:                 (ragdoll.bodies[muscle.parent], ragdoll.bodies[muscle.child])
134:             else {
135:                 continue;
136:             };
137:             let Ok([mut parent_spin, mut child_spin]) = velocities.get_many_mut([parent, child])
138:             else {
139:                 continue;
140:             };
141:             let brake = ((child_spin.0 - parent_spin.0) * factor.fraction()).clamp_length_max(
142:                 config
143:                     .joint_maximum_brake_radians_per_second
144:                     .radians_per_second(),
145:             );
146:             // Only touch the `Mut` when there is something to drain.
147:             if brake.length_squared() <= 1e-8 {
148:                 continue;
149:             }
150:             child_spin.0 -= brake;
151:             if muscle.parent != PELVIS_BODY {
152:                 parent_spin.0 += brake * 0.5;
153:             }
154:         }
155:     }
156: }
157: 
158: fn ragdoll_tuning() -> RagdollConfig {
159:     runtime_animation_config().ragdoll
160: }
161: 
162: /// Minimum-jerk rise from zero to one.
163: fn quintic_rise(u: f32) -> f32 {
164:     let u = u.clamp(0.0, 1.0);
165:     u * u * u * (u * (u * 6.0 - 15.0) + 10.0)
166: }
167: 
168: /// Split an angular-velocity kick across a joint pair: equal and opposite,
169: /// unless the parent is the kinematic pelvis, which the child then absorbs
170: /// entirely.
171: fn split_kick(parent: usize, kick: Vec3) -> (Vec3, Vec3) {
172:     if parent == PELVIS_BODY {
173:         (Vec3::ZERO, kick)
174:     } else {
175:         (-kick * 0.5, kick * 0.5)
176:     }
177: }
