125:             return Ok(());
126:         };
127:         match sample.sampling {
128:             PoseSampling::Anchor => {
129:                 append_weighted_anchor(weighted, &start, start.anchor.frame, sample.weight, layer)
130:             }
131:             PoseSampling::Cycle { .. } | PoseSampling::Timeline { .. } => {
132:                 self.append_timed_sample(weighted, &start, sample, layer)
133:             }
134:             PoseSampling::Span { .. } => {
135:                 self.append_interpolated_span(weighted, &start, sample, layer)
136:             }
137:             PoseSampling::CurveSpan { .. } => {
138:                 self.append_curve_span(weighted, extrapolated_spans, &start, sample, layer)
139:             }
140:             sampling @ PoseSampling::ContinuationSpan { .. } => append_continuation_span(
141:                 self,
142:                 weighted,
143:                 continuation_spans,
