152:     fn append_timed_sample(
153:         &self,
154:         weighted: &mut Vec<WeightedClip>,
155:         start: &ResolvedAnchor<'_>,
156:         sample: PoseSample,
157:         layer: ClipLayer,
158:     ) -> AnimationValueResult<()> {
159:         match sample.sampling {
160:             PoseSampling::Cycle { phase } => {
161:                 let sample_phase = self.locomotion_strides.sample_phase(sample.pose, phase)?;
162:                 let clip = start.clip.at_anchor_layer(start.anchor.frame, layer);
163:                 append_weighted_clip(
164:                     weighted,
165:                     &clip,
166:                     start.mirrored,
167:                     start.clip.duration_seconds.at_phase(sample_phase)?,
168:                     sample.weight,
169:                     matches!(
170:                         sample.pose,
171:                         SemanticPose::WalkContact | SemanticPose::RunContact
172:                     )
173:                     .then_some(phase.wrapped()),
174:                 )
175:             }
176:             PoseSampling::Timeline { progress } => {
177:                 let progress = progress.fraction();
178:                 let timeline = if start.timeline_direction == TimelineDirection::Reversed {
179:                     1.0 - progress
180:                 } else {
181:                     progress
182:                 };
183:                 let clip = start.clip.at_anchor_layer(start.anchor.frame, layer);
184:                 append_weighted_clip(
185:                     weighted,
186:                     &clip,
187:                     start.mirrored,
188:                     ClipTime::from_seconds(start.clip.duration_seconds.seconds() * timeline)?,
189:                     sample.weight,
190:                     None,
191:                 )
192:             }
193:             _ => Ok(()),
194:         }
195:     }
196: }
197: 
198: fn mirror_fraction(
199:     contributions: impl Iterator<Item = (BlendWeight, BlendWeight)>,
200: ) -> AnimationValueResult<UnitInterval> {
201:     let mut total = BlendWeight::ZERO;
202:     let mut mirrored = BlendWeight::ZERO;
203:     for (weight, mirror) in contributions {
204:         total = total.checked_add(weight)?;
205:         mirrored = mirrored.checked_add(mirror)?;
206:     }
207:     if total.is_absent() {
208:         return Ok(UnitInterval::ZERO);
209:     }
210:     let fraction = mirrored.factor() / total.factor();
211:     if !fraction.is_finite() {
212:         return Err(AnimationValueError::Overflow {
213:             quantity: adventuresim_tactical_core::animation::AnimationQuantity::BlendWeight,
214:         });
215:     }
216:     Ok(UnitInterval::from_fraction(fraction.clamp(0.0, 1.0))?)
217: }
