57:         &self,
58:         weighted: &mut Vec<WeightedClip>,
59:         extrapolated_spans: &mut Vec<ExtrapolatedSpan>,
60:         start: &ResolvedAnchor<'a>,
61:         sample: PoseSample,
62:         layer: ClipLayer,
63:     ) -> AnimationValueResult<()> {
64:         let PoseSampling::CurveSpan { end, coordinate } = sample.sampling else {
65:             return Ok(());
66:         };
67:         let coordinate = coordinate.clamped_to_curve();
