107:                 frame: start.anchor.frame,
108:             },
109:             end: ResolvedSpanEndpoint {
110:                 anchor: end.clone(),
111:                 frame: end.anchor.frame,
112:             },
113:         };
114:         if start.pack_id == end.pack_id && start.anchor.motion == end.anchor.motion {
115:             return Some(span);
