117:         if let Some(reference) = self.reference_for(&end, start_pose) {
118:             span.start = ResolvedSpanEndpoint {
119:                 anchor: end,
120:                 frame: reference.frame,
121:             };
122:         } else if let Some(reference) = self.reference_for(start, end_pose) {
