145: /// Longer legs raise the pelvis instead of lowering both feet through the floor.
146: /// Animation still supplies its authored root motion and contact timing.
147: fn preserve_neutral_ground_height(rig: &mut BTreeMap<Entity, BoneReference>) {
148:     let named = |role| rig.values().find(|bone| bone.role == Some(role));
149:     let (Some(left), Some(right), Some(root)) = (
150:         named(BoneRole::FootLeft),
151:         named(BoneRole::FootRight),
152:         named(BoneRole::Pelvis),
153:     ) else {
154:         return;
155:     };
156:     let correction = [left, right]
157:         .iter()
158:         .map(|foot| foot.global(rig, false).translation.y - foot.global(rig, true).translation.y)
159:         .sum::<f32>()
160:         / 2.0;
161:     let parent = root
162:         .parent
163:         .and_then(|entity| rig.get(&entity))
164:         .map(|parent| parent.global(rig, false))
165:         .unwrap_or_default();
166:     let local_correction = parent.rotation.inverse() * Vec3::Y * correction / parent.scale;
167:     let root_entity = root.entity;
168:     rig.get_mut(&root_entity).expect("located rig root").offset += local_correction;
169: }
