655:     fn runtime_with_available(poses: impl IntoIterator<Item = SemanticPose>) -> AnimationRuntime {
656:         let catalog = AnimationPackCatalog::default();
657:         let mut assets = Assets::<AnimationClip>::default();
658:         let poses = poses.into_iter().collect::<BTreeSet<_>>();
659:         let mut library = AnimationPackLibrary::default();
660:         library
661:             .insert(AnimationPack {
662:                 id: AnimationPackId::HUMANOID_UNARMED.to_owned(),
663:                 skeleton_family: SkeletonFamily::HUMANOID,
664:                 fallback: None,
665:                 clips: poses.clone(),
666:             })
667:             .unwrap();
668:         let mut runtime = AnimationRuntime {
669:             library,
670:             ..default()
671:         };
672:         for pose in poses {
673:             let anchor = &catalog.packs[&AnimationPackId::HUMANOID_UNARMED].poses[&pose];
674:             let key = MotionKey::new(&AnimationPackId::HUMANOID_UNARMED, &anchor.motion);
675:             if runtime.clips.contains_key(&key) {
676:                 continue;
677:             }
678:             runtime.clips.insert(
679:                 key,
680:                 LoadedClip {
681:                     handle: assets.add(AnimationClip::default()),
682:                     duration_seconds: ClipDuration::from_seconds(
683:                         f32::from(u16::from(
684:                             catalog.packs[&AnimationPackId::HUMANOID_UNARMED].motions
685:                                 [&anchor.motion]
686:                                 .last_frame,
687:                         )) / animation_frames_per_second().hertz(),
688:                     )
689:                     .unwrap(),
690:                     layer: ClipLayer::Whole,
691:                 },
692:             );
693:         }
694:         runtime
695:     }
