467: pub(super) fn draw_flat_ground_grid(sequence: Res<CaptureSequence>, mut gizmos: Gizmos) {
468:     let Some(frame) = sequence.plan.get(sequence.index) else {
469:         return;
470:     };
471:     if !frame.scenario.has(ScenarioFeature::FlatGrid) {
472:         return;
473:     }
474: 
475:     const HALF_EXTENT_METRES: i32 = 20;
476:     const SUBDIVISIONS_PER_METRE: i32 = 4;
477:     let half_steps = HALF_EXTENT_METRES * SUBDIVISIONS_PER_METRE;
478:     let height = 0.012;
479:     for step in -half_steps..=half_steps {
480:         let coordinate = step as f32 / SUBDIVISIONS_PER_METRE as f32;
481:         let whole_metre = step % SUBDIVISIONS_PER_METRE == 0;
482:         let color = if step == 0 {
483:             Color::srgba(1.0, 0.45, 0.12, 0.95)
484:         } else if whole_metre {
485:             Color::srgba(0.82, 0.86, 0.92, 0.80)
486:         } else {
487:             Color::srgba(0.42, 0.47, 0.55, 0.48)
488:         };
489:         gizmos.line(
490:             Vec3::new(coordinate, height, -HALF_EXTENT_METRES as f32),
491:             Vec3::new(coordinate, height, HALF_EXTENT_METRES as f32),
492:             color,
493:         );
494:         gizmos.line(
495:             Vec3::new(-HALF_EXTENT_METRES as f32, height, coordinate),
496:             Vec3::new(HALF_EXTENT_METRES as f32, height, coordinate),
497:             color,
498:         );
499:     }
