823: pub(super) fn jitter_frames(frames: &[FrameSample]) -> Vec<JitterFrame<BoneRole>> {
824:     let mut previous: Option<&FrameSample> = None;
825:     let mut analysis_segment = 0_u64;
826:     frames
827:         .iter()
828:         // A ragdoll is intentionally non-smooth at the animation-to-physics
829:         // handoff and does not obey authored locomotion jerk thresholds.
830:         .filter(|frame| !frame.scenario.is(ScenarioId::FullRagdoll))
831:         .map(|frame| {
832:             if let Some(previous_frame) = previous {
833:                 let action_transition = previous_frame.action != frame.action;
834:                 let landing = previous_frame.landing_sequence != frame.landing_sequence;
835:                 let foot_contact = previous_frame.contact_sequence != frame.contact_sequence;
836:                 let guard_stop_handoff = is_guard_stop_transition(&frame.scenario)
837:                     && previous_frame.speed_metres_per_second
838:                         > SignedSpeed::from(STATIONARY_ANIMATION_SPEED_LIMIT)
839:                     && frame.speed_metres_per_second
840:                         <= SignedSpeed::from(STATIONARY_ANIMATION_SPEED_LIMIT);
841:                 let quickstep_takeoff = is_quickstep_scenario(&frame.scenario)
842:                     && previous_frame.left_support_weight.fraction() >= FULL_PLANT_SUPPORT_WEIGHT
843:                     && previous_frame.right_support_weight.fraction() >= FULL_PLANT_SUPPORT_WEIGHT
844:                     && frame.left_support_weight.fraction() <= 0.01
845:                     && frame.right_support_weight.fraction() <= 0.01;
846:                 if previous_frame.scenario != frame.scenario {
847:                     analysis_segment = 0;
848:                 } else if action_transition
849:                     || landing
850:                     || foot_contact
851:                     || guard_stop_handoff
852:                     || quickstep_takeoff
853:                 {
854:                     analysis_segment = analysis_segment.wrapping_add(1);
855:                 }
856:             }
857:             previous = Some(frame);
858:             JitterFrame {
859:                 scenario: frame.scenario.clone(),
860:                 analysis_segment,
861:                 scenario_frame: frame.scenario_frame,
862:                 time_seconds: frame.time_seconds,
863:                 bones: frame
864:                     .bones
865:                     .iter()
866:                     .map(|(name, bone)| {
867:                         let position = if *name == BoneRole::Pelvis {
868:                             // The capture root is authoritative locomotion, not
869:                             // a skeletal joint. Exclude its world translation
870:                             // from limb jitter while retaining pelvis rotation.
871:                             Vec3::ZERO
872:                         } else {
873:                             Vec3::from_array(bone.position)
874:                         };
875:                         let rotation = Quat::from_array(bone.rotation_xyzw);
876:                         let (position, rotation) = parent_bone(name)
877:                             .and_then(|parent| frame.bones.get(parent))
878:                             .map_or((position, rotation), |parent| {
879:                                 let parent_position = Vec3::from_array(parent.position);
880:                                 let parent_rotation = Quat::from_array(parent.rotation_xyzw);
881:                                 (
882:                                     parent_rotation.inverse() * (position - parent_position),
883:                                     parent_rotation.inverse() * rotation,
884:                                 )
885:                             });
886:                         (
887:                             *name,
888:                             JitterBone {
889:                                 position: position.to_array(),
890:                                 rotation_xyzw: rotation.to_array(),
891:                             },
892:                         )
893:                     })
894:                     .collect(),
895:             }
896:         })
897:         .collect()
898: }
