69:                 position_delta,
70:                 rotation_delta,
71:                 "repeated animation evaluation changed a captured bone"
72:             );
73:         }
74:         if !repeated_evaluation_matches && bone_mismatch.is_none() {
75:             warn!(
76:                 scenario = frame.scenario.label(),
77:                 scenario_frame = frame.scenario_frame,
78:                 baseline_contact = self.contact_sequence.encoded(),
79:                 contact = skeleton.contact_sequence.encoded(),
