91: pub(super) fn repeated_bone_mismatch(
92:     expected: &CapturedBones,
93:     actual: &CapturedBones,
94: ) -> Option<(BoneRole, f32, f32)> {
95:     if let Some(name) = expected
96:         .keys()
97:         .find(|name| !actual.contains_key(**name))
98:         .or_else(|| actual.keys().find(|name| !expected.contains_key(**name)))
99:     {
100:         return Some((*name, f32::INFINITY, f32::INFINITY));
101:     }
102:     expected.iter().find_map(|(name, expected)| {
103:         let actual = actual
104:             .get(*name)
105:             .expect("equal repeated-evaluation bone keys were checked above");
106:         let position_delta =
107:             Vec3::from_array(expected.position).distance(Vec3::from_array(actual.position));
108:         let expected_rotation = Quat::from_array(expected.rotation_xyzw);
109:         let actual_rotation = Quat::from_array(actual.rotation_xyzw);
110:         // `acos` quantizes identical f32 quaternions to roughly 0.056-0.079
111:         // degrees on some frames. Treat a direct dot match as identity, then
112:         // retain the angular report for genuine changes.
113:         let rotation_dot = expected_rotation.dot(actual_rotation).abs();
114:         let rotation_delta = if rotation_dot >= 1.0 - 0.000_001 {
115:             0.0
116:         } else {
117:             expected_rotation
118:                 .angle_between(actual_rotation)
119:                 .to_degrees()
120:         };
121:         // Re-evaluating one logical tick must be visually identical. Keep only
122:         // sub-half-millimetre/sub-twentieth-degree numeric noise.
123:         (position_delta > 0.0005 || rotation_delta > 0.05).then_some((
124:             *name,
125:             position_delta,
126:             rotation_delta,
127:         ))
128:     })
129: }
