39:             Self::MuseumNuremberg => museum::NUREMBERG_ITEMS,
40:             Self::Plate | Self::PlateTassets | Self::PlateUnderlayers => &[
41:                 "morion",
42:                 "gorget",
43:                 "cuirass",
44:                 "pauldron",
45:                 "rerebrace",
