155: impl ArmorCapture {
156:     /// Keep the complete articulated harness legible in the two inspection views.
157:     pub(super) fn review_camera(
158:         &self,
159:         view: CaptureView,
160:         subject: &Transform,
161:         head: Option<Vec3>,
162:         orbit: Quat,
163:     ) -> Option<Transform> {
164:         let harness = self.harness?;
165:         const REVIEW_CAMERA_DISTANCE_METRES: f32 = 2.4;
166:         const REVIEW_CAMERA_ELEVATION_METRES: f32 = 0.2;
167:         const HELMET_REVIEW_DISTANCE_METRES: f32 = 0.72;
168:         const HELMET_FOCUS_ABOVE_HEAD_METRES: f32 = 0.07;
169:         const TORSO_FOCUS_BELOW_HEAD_METRES: f32 = 0.30;
170:         const TORSO_REVIEW_DISTANCE_METRES: f32 = 1.15;
171:         let (focus, distance, elevation) = if matches!(harness, ArmorHarness::CloseHelmet) {
172:             (
173:                 head? + Vec3::Y * HELMET_FOCUS_ABOVE_HEAD_METRES,
174:                 HELMET_REVIEW_DISTANCE_METRES,
175:                 0.0,
176:             )
177:         } else if matches!(harness, ArmorHarness::Anime | ArmorHarness::Pauldron) {
178:             (
179:                 head? - Vec3::Y * TORSO_FOCUS_BELOW_HEAD_METRES,
180:                 TORSO_REVIEW_DISTANCE_METRES,
181:                 0.0,
182:             )
183:         } else {
184:             (
185:                 subject.translation,
186:                 REVIEW_CAMERA_DISTANCE_METRES,
187:                 REVIEW_CAMERA_ELEVATION_METRES,
188:             )
189:         };
190:         let offset = match view {
191:             CaptureView::Gameplay => return None,
192:             CaptureView::Side => Vec3::new(distance, elevation, 0.0),
193:             CaptureView::Front => Vec3::new(0.0, elevation, -distance),
194:         };
195:         Some(Transform::from_translation(focus + orbit * offset).looking_at(focus, Vec3::Y))
196:     }
197: 
198:     pub(super) fn new(harness: Option<ArmorHarness>, output: PathBuf) -> Self {
199:         if let Some(harness) = harness {
200:             let pieces = harness.placements().map(|(item, placement)| serde_json::json!({"item_id": item.id, "placement_id": placement.id})).collect::<Vec<_>>();
201:             let manifest = serde_json::json!({"harness": harness, "pieces": pieces, "renderer": "gameplay_equipment_runtime_wearer_fit", "identity": "deterministic_character_id_variation"});
202:             fs::write(
203:                 output.join("armor-fixture.json"),
204:                 serde_json::to_vec_pretty(&manifest).expect("serialize armor fixture"),
205:             )
206:             .expect("write armor fixture");
207:         }
208:         Self {
209:             harness,
210:             output,
211:             ready: harness.is_none(),
212:             waited: 0,
213:             failed: false,
214:         }
215:     }
216: 
217:     pub(super) fn spawn(&self, commands: &mut Commands, subject: Entity) {
218:         let Some(harness) = self.harness else { return };
219:         let mut previous = Vec::new();
220:         for (item, placement) in harness.placements() {
221:             let physical = &item.equipment.as_ref().expect("harness equipment").physical;
222:             let occupancies = topology::occupancies(item, placement, &previous);
223:             let entity = commands
224:                 .spawn((
225:                     CapturedArmor,
226:                     Name::new(format!("Armor review {}/{}", item.id, placement.id)),
227:                     ItemOf(subject),
228:                     ItemProperties {
229:                         id: item.id.clone(),
230:                         weight: item.weight_kg,
231:                     },
232:                     EquipmentTopology {
233:                         placement_id: Some(placement.id.clone()),
234:                         occupancies,
235:                     },
236:                     TacticalEquipmentPhysical {
237:                         dimensions_m: Vec3::from_array(physical.dimensions_m),
238:                         grip_to_tip_m: physical.grip_to_tip_m,
239:                         striking_head_length_m: 0.0,
240:                         anchor_offset_m: Vec3::from_array(physical.anchor_offset_m),
241:                     },
242:                     Transform::default(),
243:                 ))
244:                 .id();
245:             previous.push((item, entity, placement));
246:         }
247:     }
248: 
249:     fn fail(&mut self, reason: &str, exit: &mut MessageWriter<AppExit>) {
250:         self.failed = true;
251:         fs::write(self.output.join("failure.txt"), reason).expect("write armor capture failure");
252:         error!(%reason, "Armor capture cannot use unresolved equipment");
253:         exit.write(AppExit::error());
254:     }
255: }
