257: pub(super) fn update_readiness(
258:     mut capture: ResMut<ArmorCapture>,
259:     armor: Query<(Entity, &ItemProperties), With<CapturedArmor>>,
260:     visuals: EquipmentVisualStatus,

261:     equipment: Res<crate::equipment::RuntimeEquipmentBodyCache>,
262:     mut exit: MessageWriter<AppExit>,
263: ) {
264:     let Some(harness) = capture.harness else {
265:         return;
266:     };
267:     if capture.failed {
268:         return;
269:     }
270:     let was_ready = capture.ready;
271:     capture.ready = armor.iter().count() == harness.placements().count();
272:     for (entity, item) in &armor {
273:         match visuals.state(entity, harness.visual_requirements()) {
274:             EquipmentVisualState::Ready => {}
275:             EquipmentVisualState::Failed => {
276:                 fs::write(
277:                     capture.output.join("armor-readiness-failure.json"),
278:                     serde_json::to_vec_pretty(&serde_json::json!({
279:                         "item_id": item.id, "parts": visuals.summary(entity),
280:                     }))
281:                     .expect("serialize failed armor readiness"),
282:                 )
283:                 .expect("write failed armor readiness");
284:                 capture.fail(
285:                     &format!(
286:                         "Procedural equipment asset or primary skin weights failed for {}",
287:                         item.id
288:                     ),
289:                     &mut exit,
290:                 );
291:                 return;
292:             }
293:             EquipmentVisualState::Missing | EquipmentVisualState::Loading => capture.ready = false,
294:         }
295:     }
296:     if capture.ready && !was_ready {
297:         let parts = armor
298:             .iter()
299:             .map(|(entity, item)| {
300:                 serde_json::json!({
301:                     "item_id": item.id, "parts": visuals.summary(entity),
302:                 })
303:             })
304:             .collect::<Vec<_>>();
305:         fs::write(
306:             capture.output.join("armor-readiness.json"),
307:             serde_json::to_vec_pretty(&parts).expect("serialize armor readiness"),
308:         )
309:         .expect("write armor readiness");
310:     }
311:     // A requested fit includes first-use device compilation. Count unresolved
312:     // presentation frames after that asynchronous task completes.
313:     if !capture.ready && !equipment.is_preparing() {
314:         capture.waited += 1;
315:         if capture.waited >= CAPTURE_LOAD_FRAME_LIMIT {
316:             capture.fail("Timed out waiting for every armor mesh, material, morph, and wearer skin to resolve", &mut exit);
317:         }
318:     }
319: }
320: 
321: pub(super) fn ready(capture: Res<ArmorCapture>) -> bool {
322:     capture.ready && !capture.failed
323: }
