1317:         let replay = |scenario: &str| {
1318:             let mut skeleton = SkeletonState::default();
1319:             set_weapon_guard(&mut skeleton, WeaponGuardState::Raised);
1320:             let mut samples = Vec::new();
1321:             for frame in capture_plan()
1322:                 .unwrap()
1323:                 .into_iter()
1324:                 .filter(|frame| frame.scenario.label() == scenario)
