1334:                             0.0
1335:                         } else {
1336:                             locomotion_sample_rate().interval().seconds()
1337:                         })
1338:                         .unwrap(),
1339:                         AnimationSampleTick::from(frame.scenario_frame as u64),
1340:                     )
1341:                     .unwrap(),
1342:                 )
1343:                 .unwrap();
1344:                 samples.push((
1345:                     frame.scenario_frame,
1346:                     skeleton.gait_phase,
1347:                     skeleton.raised_locomotion(),
1348:                 ));
1349:             }
1350:             samples
1351:         };
1352: 
1353:         let release = replay("raised-guard-release-at-peak");
1354:         let release_frame =
1355:             (guard_step_length().unwrap().metres() * 0.75 * locomotion_sample_rate().hertz())
1356:                 .round() as usize;
1357:         assert!(
1358:             release
1359:                 .iter()
1360:                 .any(|(frame, phase, intent)| *frame > release_frame
1361:                     && phase.cycles() > 0.5
1362:                     && intent.is_moving())
1363:         );
1364:         assert!(!release.last().unwrap().2.is_moving());
1365:         assert_eq!(release.last().unwrap().1.cycles(), 0.0);
1366: 
1367:         let reversal = replay("raised-guard-left-right-reversal");
1368:         let changed = reversal
1369:             .iter()
1370:             .find(|(_, _, intent)| intent.local_direction() == Vec2::X)
1371:             .expect("reversal observation is accepted immediately");
1372:         let previous_phase = reversal
1373:             .iter()
1374:             .find(|(frame, _, _)| *frame == 15)
1375:             .expect("pre-reversal sample")
1376:             .1;
1377:         assert_eq!(changed.0, 16);
1378:         let phase_delta = (changed.1.cycles() - previous_phase.cycles()).rem_euclid(1.0);
