1: //! Deterministic force-driven quickstep stimulus and frame selection.
2: 
3: use super::*;
4: 
5: const QUICKSTEP_FIXTURE_BIOLOGICAL_MASS_KG: f32 = 70.0;
6: const QUICKSTEP_FIXTURE_TOTAL_MASS_KG: f32 = 93.9;
7: const QUICKSTEP_FIXTURE_LEG_AGILITY: f32 = 4.0;
8: 
9: pub(in crate::animation_viewer) fn quickstep_scenario(
10:     name: ScenarioMetadata<'static>,
11:     local_direction: Vec2,
12: ) -> Vec<PlannedFrame> {
13:     let planar_speeds = quickstep_fixture_planar_speeds(72);
14:     (0..72)
15:         .map(|scenario_frame| PlannedFrame {
16:             scenario: name.clone(),
17:             scenario_frame,
18:             speed: planar_speeds[scenario_frame],
19:             time_seconds: authored_frame_time(
20:                 scenario_frame as f32 / locomotion_sample_rate().hertz(),
21:             ),
22:             local_direction,
23:             camera_yaw: authored_camera_angle(0.0),
24:             camera_pitch: authored_camera_angle(0.0),
25:             action: SkeletonAction::Dodge,
26:             weapon_guard: WeaponGuardState::Raised,
27:             lead_foot: LeadFoot::Left,
28:         })
29:         .collect()
30: }
31: 
32: pub(in crate::animation_viewer) fn quickstep_action_ticks() -> AnimationSampleSpan {
33:     let config = TacticalCombatConfig::default();
34:     quickstep_action_contact_ticks(config.movement.maneuvers.quickstep_duration_seconds)
35:         .saturating_mul(2)
36: }
37: 
38: pub(in crate::animation_viewer) fn quickstep_push_ticks() -> AnimationSampleSpan {
39:     let config = TacticalCombatConfig::default();
40:     let duration =
41:         match quickstep_push_duration(QUICKSTEP_FIXTURE_LEG_AGILITY, &config.movement.motor) {
42:             Ok(duration) => duration,
43:             Err(error) => panic!("invalid authored quickstep duration: {error}"),
44:         };
45:     AnimationSampleSpan::from((duration.seconds() * locomotion_sample_rate().hertz()).ceil() as u64)
46: }
47: 
48: pub(in crate::animation_viewer) fn quickstep_fixture_planar_speeds(
49:     frame_count: usize,
50: ) -> Vec<SignedSpeed> {
51:     let config = TacticalCombatConfig::default();
52:     let action_ticks = quickstep_action_ticks().samples() as usize;
53:     let peak_force = quickstep_peak_horizontal_force_newtons(
54:         QUICKSTEP_FIXTURE_BIOLOGICAL_MASS_KG,
55:         QUICKSTEP_FIXTURE_LEG_STRENGTH,
56:         &config.movement.motor,
57:     );
58:     let target_displacement = quickstep_target_displacement_metres(
59:         CharacterDimensions::default().leg_length_metres,
60:         &config.movement.motor,
61:     );
62:     let duration = authored_frame_time(action_ticks as f32 / locomotion_sample_rate().hertz());
63:     let mut velocity: f32 = 0.0;
64:     let mut displacement: f32 = 0.0;
65:     let mut speeds = Vec::with_capacity(frame_count);
66:     for frame in 0..frame_count {
67:         speeds.push(authored_drive_speed(velocity.abs()));
68:         if frame < action_ticks {
69:             let target = match quickstep_motion_target(
70:                 (frame + 1) as f32 / action_ticks as f32,
71:                 target_displacement,
72:                 duration,
73:                 config
74:                     .movement
75:                     .motor
76:                     .quickstep_authored_displacement_profile,
77:             ) {
78:                 Ok(target) => target,
79:                 Err(error) => panic!("invalid authored quickstep speed: {error}"),
80:             };
81:             let force = quickstep_tracking_force_newtons(
82:                 displacement,
83:                 authored_drive_speed(velocity),
84:                 target,
85:                 QUICKSTEP_FIXTURE_TOTAL_MASS_KG,
86:                 peak_force,
87:                 authored_frame_time(locomotion_sample_rate().interval().seconds()),
88:             );
89:             velocity += force / QUICKSTEP_FIXTURE_TOTAL_MASS_KG / locomotion_sample_rate().hertz();
90:         } else {
91:             velocity = 0.0;
92:         }
93:         displacement += velocity / locomotion_sample_rate().hertz();
94:     }
95:     speeds
96: }
97: 
98: pub(in crate::animation_viewer) fn quickstep_release_frame() -> usize {
99:     let config = TacticalCombatConfig::default();
100:     let motor = &config.movement.motor;
101:     let ticks = quickstep_push_ticks().samples() as usize;
102:     let acceleration = quickstep_peak_horizontal_force_newtons(
103:         QUICKSTEP_FIXTURE_BIOLOGICAL_MASS_KG,
104:         QUICKSTEP_FIXTURE_LEG_STRENGTH,
105:         motor,
106:     ) / QUICKSTEP_FIXTURE_TOTAL_MASS_KG;
107:     let mut speed = 0.0;
108:     let mut displacement = 0.0;
109:     for tick in 0..ticks {
110:         speed += acceleration * quickstep_force_curve((tick as f32 + 0.5) / ticks as f32)
111:             / locomotion_sample_rate().hertz();
112:         displacement += speed / locomotion_sample_rate().hertz();
113:         if displacement >= motor.quickstep_maximum_supported_root_displacement_metres {
114:             return tick + 1;
115:         }
116:     }
117:     ticks
118: }
119: 
120: pub(in crate::animation_viewer) fn quickstep_landing_frame() -> usize {
121:     ((quickstep_release_frame() + 1)
122:         ..(quickstep_release_frame() + locomotion_sample_rate().hertz() as usize))
123:         .find(|&frame| quickstep_fixture_vertical_state(frame).0 <= 0.0)
124:         .expect("the quickstep fixture must return to ground within one second")
125: }
126: 
127: pub(in crate::animation_viewer) fn quickstep_fixture_vertical_state(
128:     scenario_frame: usize,
129: ) -> (f32, f32) {
130:     let config = TacticalCombatConfig::default();
131:     let motor = &config.movement.motor;
132:     let push_ticks = quickstep_push_ticks().samples() as usize;
133:     let release_frame = quickstep_release_frame();
134:     let peak_acceleration = quickstep_peak_horizontal_force_newtons(
135:         QUICKSTEP_FIXTURE_BIOLOGICAL_MASS_KG,
136:         QUICKSTEP_FIXTURE_LEG_STRENGTH,
137:         motor,
138:     ) / QUICKSTEP_FIXTURE_TOTAL_MASS_KG
139:         * motor.quickstep_takeoff_angle_degrees.to_radians().tan();
140:     let mut height = 0.0;
141:     let mut velocity = 0.0;
142:     for tick in 0..scenario_frame {
143:         if tick < release_frame {
144:             velocity += peak_acceleration
145:                 * quickstep_force_curve((tick as f32 + 0.5) / push_ticks as f32)
146:                 / locomotion_sample_rate().hertz();
147:         } else {
148:             velocity -= motor.gravity_metres_per_second_squared / locomotion_sample_rate().hertz();
149:         }
150:         height += velocity / locomotion_sample_rate().hertz();
151:     }
152:     (height, velocity)
153: }
154: 
155: pub(in crate::animation_viewer) fn quickstep_fixture_action_distance_metres() -> f32 {
156:     quickstep_scenario(
157:         ScenarioMetadata::authored(ScenarioId::QuickstepRight),
158:         Vec2::X,
159:     )
160:     .iter()
161:     .take(quickstep_action_ticks().samples() as usize + 1)
162:     .map(|frame| frame.speed.metres_per_second() / locomotion_sample_rate().hertz())
163:     .sum()
164: }
