1: //! Deterministic gameplay and armor inspection camera framing.
2: use super::*;
3: use adventuresim_building_generator::spatial_geometry::RigidRotation;
4: 
5: pub(super) fn position_capture_camera(
6:     sequence: Res<CaptureSequence>,
7:     armor: Res<harness::ArmorCapture>,
8:     inspection: Res<CaptureInspection>,
9:     subjects: Query<(Entity, &Transform, &PresentedSkeleton), With<CaptureSubject>>,
10:     bones: Query<(&HumanoidBone, &GlobalTransform)>,
11:     mut cameras: Query<&mut Transform, (With<TacticalGameplayCamera>, Without<CaptureSubject>)>,
12:     mut labels: Query<(&mut Text, &mut Visibility), With<CaptureLabel>>,
13: ) {
14:     let (Ok((subject_entity, subject, skeleton)), Ok(mut camera)) =
15:         (subjects.single(), cameras.single_mut())
16:     else {
17:         return;
18:     };
19:     let focus = subject.translation + Vec3::Y * 0.95;
20:     let view = sequence.view();
21:     match view {
22:         CaptureView::Gameplay => {
23:             // Physics simulation is disabled in this fixture, so ahoy does
24:             // not refresh its controller-follow base transform. Reconstruct
25:             // that default base and apply the exact gameplay camera offset;
26:             // otherwise the offset accumulates and the first raw frame is a
27:             // pelvis-level/empty view.
28:             let offset = match animation_capture_camera_offset(RigidRotation::IDENTITY) {
29:                 Ok(offset) => offset,
30:                 Err(error) => {
31:                     error!(%error, "cannot position capture camera");
32:                     return;
33:                 }
34:             };
35:             camera.translation = subject.translation + offset.metres();
36:             camera.rotation = Quat::IDENTITY;
37:         }
38:         CaptureView::Side => {
39:             camera.translation = focus + Vec3::new(5.0, 0.45, 0.0);
40:             camera.look_at(focus, Vec3::Y);
41:         }
42:         CaptureView::Front => {
43:             camera.translation = focus + Vec3::new(0.0, 0.45, -5.0);
44:             camera.look_at(focus, Vec3::Y);
45:         }
46:     }
47:     let head = bones
48:         .iter()
49:         .find(|(bone, _)| bone.owner == subject_entity && bone.role == BoneRole::Head)
50:         .map(|(_, transform)| transform.translation());
51:     if let Some(review_camera) = armor.review_camera(view, subject, head, inspection.orbit) {
52:         *camera = review_camera;
53:     } else if !matches!(view, CaptureView::Gameplay) {
54:         camera.translation = focus + inspection.orbit * (camera.translation - focus);
55:         camera.look_at(focus, Vec3::Y);
56:     }
57:     if let Some(frame) = sequence.applied_frame() {
58:         for (mut label, mut visibility) in &mut labels {
59:             *visibility = if matches!(view, CaptureView::Gameplay) {
60:                 Visibility::Hidden
61:             } else {
62:                 Visibility::Inherited
63:             };
64:             **label = format!(
65:                 "{} | {:>4.2} m/s | phase {:>5.3} | {} view | 64 Hz frame {}",
66:                 frame.scenario.label(),
67:                 frame.speed.metres_per_second(),
68:                 skeleton.gait_phase.cycles(),
69:                 view.slug(),
70:                 frame.scenario_frame,
71:             );
72:         }
73:     }
74: }

