80: pub(super) fn queue(json: &str) -> Result<(), String> {
81:     let command: DemoCommand = serde_json::from_str(json).map_err(|error| error.to_string())?;
82:     match command {
83:         DemoCommand::Orbit { delta_x, delta_y } if !delta_x.is_finite() || !delta_y.is_finite() => {
84:             return Err("orbit requires finite deltas".into());
85:         }
86:         DemoCommand::Zoom { delta } if !delta.is_finite() => {
87:             return Err("zoom requires a finite delta".into());
88:         }
89:         DemoCommand::Pan {
90:             right,
91:             forward,
92:             seconds,
93:         } if !right.is_finite() || !forward.is_finite() || !seconds.is_finite() => {
94:             return Err("pan requires finite inputs".into());
95:         }
96:         _ => {}
97:     }
98:     let mut pending = PENDING.lock().map_err(|error| error.to_string())?;
99:     if matches!(command, DemoCommand::Show { .. }) {
