226:             DemoCommand::Prefetch { exhibit } => residency::prefetch(world, exhibit),
227:             DemoCommand::Orbit { delta_x, delta_y } => {
228:                 world.resource_mut::<OrbitView>().orbit(delta_x, delta_y);
229:             }
