296:                 };
297:             } else if !assets.is_loaded_with_dependencies(scene.id()) {
298:                 status = DemoStatus::Loading {
299:                     exhibit: current.id,
300:                     completed: 0,
301:                     total: 0,
302:                 };
303:             }
304:         }
305:         Ok(None) => {}
306:     }
