149: mod tests {
150:     use super::*;
151:     #[test]
152:     fn pan_follows_camera_and_has_no_diagonal_speed_bonus() {
153:         let mut view = OrbitView::new(Vec3::ZERO, 10.0, CameraSpace::Landscape);
154:         view.yaw = std::f32::consts::FRAC_PI_2;
155:         view.pan(0.0, 1.0, 0.05);
156:         assert!(view.focus.x < 0.0);
157:         assert_eq!(view.focus.y, 0.0);
158:         let straight = view.focus.length();
159:         view.focus = Vec3::ZERO;
160:         view.pan(1.0, 1.0, 0.05);
161:         assert!((view.focus.length() - straight).abs() < 0.0001);
162:         view.space = CameraSpace::Studio;
163:         view.focus = Vec3::ZERO;
164:         view.pan(0.0, 1.0, 0.05);
165:         assert!(view.focus.y > 0.0);
166:     }
167:     #[test]
168:     fn extreme_input_preserves_a_finite_camera_and_zoom_recovers() {
169:         let mut view = OrbitView::default();
170:         view.zoom(f32::MAX);
171:         assert_eq!(view.distance, *view.limits.end());
172:         view.zoom(-100.0);
173:         assert!(view.distance < *view.limits.end());
174:         view.orbit(500.0, f32::MAX);
175:         assert!(view.pitch < std::f32::consts::FRAC_PI_2);
176:         view.zoom(-f32::MAX);
177:         assert!(view.distance > 0.0);
178:     }
179: }

