170: fn load_studio(
171:     world: &mut World,
172:     exhibit: &Exhibit,
173: ) -> SharedArtDemoResult<Option<Handle<WorldAsset>>> {
174:     if let Some(result) = world
175:         .resource::<ExhibitCache>()
176:         .studio
177:         .get(&exhibit.id())
178:         .cloned()
179:     {
180:         touch(world, exhibit.id());
181:         return result;
182:     }
183:     evict_for(world, exhibit.id());
184:     let result = exhibit.spawn(world).map_err(Arc::new);
185:     let mut cache = world.resource_mut::<ExhibitCache>();
186:     cache.studio.insert(exhibit.id(), result.clone());
187:     cache.recency.push_back(exhibit.id());
188:     result
189: }
