191: fn touch(world: &mut World, id: ExhibitId) {
192:     let mut cache = world.resource_mut::<ExhibitCache>();
193:     cache.recency.retain(|cached| *cached != id);
194:     cache.recency.push_back(id);
195: }
196: 
197: fn evict_for(world: &mut World, incoming: ExhibitId) {
198:     if world.resource::<ExhibitCache>().studio.len() < STUDIO_CACHE_CAPACITY {
199:         return;
200:     }
201:     let active = world
202:         .get_resource::<CurrentExhibit>()
203:         .map(|current| current.id);
204:     let evicted = {
205:         let mut cache = world.resource_mut::<ExhibitCache>();
206:         let position = cache
207:             .recency
208:             .iter()
209:             .position(|id| Some(*id) != active && *id != incoming);
210:         position.and_then(|position| cache.recency.remove(position))
211:     };
212:     let Some(evicted) = evicted else {
213:         return;
214:     };
215:     {
216:         let mut cache = world.resource_mut::<ExhibitCache>();
217:         cache.studio.remove(&evicted);
218:         cache.views.remove(&evicted);
219:     }
220:     let entities = world
221:         .query::<(Entity, &DemoEntity)>()
222:         .iter(world)
223:         .filter_map(|(entity, exhibit)| (exhibit.0 == evicted).then_some(entity))
224:         .collect::<Vec<_>>();
225:     for entity in entities {
226:         world.entity_mut(entity).despawn();
227:     }
228: }
