144: fn spawn_oak(
145:     world: &mut World,
146:     input: &TacticalSceneInput,
147:     generated: &SupportedSceneTerrain,
148:     environment: &SceneEnvironment,
149: ) -> ArtDemoPreparationResult<()> {
150:     let site = oak_exhibit_site(input, generated, environment)
151:         .ok_or(ArtDemoPreparationError::MissingOak)?;
152:     world.spawn((
153:         SceneObstacle::Tree,
154:         Transform::from_translation(site.root.metres()),
155:     ));
156:     let mut view = world.resource_mut::<OrbitView>();
157:     let position = site.surface.point.metres();
158:     view.focus = Vec3::new(
159:         position.x,
160:         site.surface.elevation.metres() + view.focus.y,
161:         position.y,
162:     );
163:     view.pitch = 0.06;
164:     let downhill = root_slope(&generated.terrain, site.surface);
165:     view.yaw = downhill.x.atan2(downhill.y) + std::f32::consts::FRAC_PI_2;
166:     Ok(())
167: }
