169: fn oak_exhibit_site(
170:     input: &TacticalSceneInput,
171:     generated: &SupportedSceneTerrain,
172:     environment: &SceneEnvironment,
173: ) -> Option<OakExhibitSite> {
174:     let terrain = &generated.terrain;
175:     generated
176:         .obstacles
177:         .iter()
178:         .filter_map(|obstacle| {
179:             let GeneratedObstacle::Tree { x, z } = obstacle else {
180:                 return None;
181:             };
182:             let point = ScenePlanPoint::from_metres(
183:                 Vec2::new(f32::from(*x), f32::from(*z)) * input.playable.spacing_metres
184:                     - Vec2::new(terrain.width(), terrain.depth()) * 0.5,
185:             )?;
186:             let elevation = terrain.height_at(point)?;
187:             let root = Position::from_metres(Vec3::new(
188:                 point.metres().x,
189:                 elevation.metres() + TREE_TRUNK_HEIGHT_METRES * 0.5,
190:                 point.metres().y,
191:             ))
192:             .ok()?;
193:             (crate::presentation::tree_species_for_site(point, environment)
194:                 == crate::presentation::TreePresentationSpecies::EnglishOak)
195:                 .then_some(OakCandidate {
196:                     site: OakExhibitSite {
197:                         surface: GeographicHeightControl { point, elevation },
198:                         root,
199:                     },
200:                     root_exposure: crate::presentation::oak_root_exposure_for_site(

pr-working:crates/adventuresim-tactical-client/src/art_demo/scenery.rs
201:                         point,
202:                         environment,
203:                     ),
204:                 })
205:         })
206:         .max_by(|a, b| {
207:             a.root_exposure.total_cmp(&b.root_exposure).then_with(|| {
208:                 root_slope(terrain, a.site.surface)
209:                     .length_squared()
210:                     .total_cmp(&root_slope(terrain, b.site.surface).length_squared())
211:             })
212:         })
213:         .map(|candidate| candidate.site)
214: }
215: 
216: // The local slope ranks exposed sites and orients a lit view across the hill.
217: fn root_slope(terrain: &SceneTerrain, centre: GeographicHeightControl) -> Vec2 {
218:     const ROOT_SPREAD_METRES: f32 = 1.5;
219:     let height = |offset| {
220:         ScenePlanPoint::from_metres(centre.point.metres() + offset)
221:             .and_then(|point| terrain.height_at(point))
222:             .unwrap_or(centre.elevation)
223:     };
224:     Vec2::new(
225:         height(-Vec2::X * ROOT_SPREAD_METRES).metres()
226:             - height(Vec2::X * ROOT_SPREAD_METRES).metres(),
227:         height(-Vec2::Y * ROOT_SPREAD_METRES).metres()
228:             - height(Vec2::Y * ROOT_SPREAD_METRES).metres(),
229:     )
230: }
