58: impl TacticalAudioConfig {
59:     pub(crate) fn parse(text: &str) -> Result<Self, String> {
60:         let config: Self = serde_saphyr::from_str(text)
61:             .map_err(|error| format!("audio configuration is not valid YAML: {error}"))?;
62:         config.validate()?;
63:         Ok(config)
