66:     #[cfg(not(target_family = "wasm"))]
67:     pub(crate) fn load(path: &Path) -> Result<Self, String> {
68:         let length = std::fs::metadata(path)
69:             .map_err(|error| format!("could not inspect {}: {error}", path.display()))?
70:             .len();
71:         if length == 0 || length > MAX_AUDIO_CONFIG_BYTES {
72:             return Err("audio config must contain between 1 byte and 32 KiB".into());
73:         }
74:         let text = std::fs::read_to_string(path)
75:             .map_err(|error| format!("could not read {}: {error}", path.display()))?;
76:         Self::parse(&text).map_err(|error| format!("{}: {error}", path.display()))
77:     }
78: 
79:     fn validate(&self) -> Result<(), String> {
80:         let movement = &self.movement;
81:         for (name, volume) in [
82:             (
83:                 "movement.footstep_relative_volume",
84:                 movement.footstep_relative_volume,
85:             ),
86:             (
87:                 "movement.body_impact_relative_volume",
88:                 movement.body_impact_relative_volume,
89:             ),
90:             (
91:                 "movement.tall_grass_rustle_relative_volume",
92:                 movement.tall_grass_rustle_relative_volume,
93:             ),
94:             (
95:                 "movement.bush_rustle_relative_volume",
96:                 movement.bush_rustle_relative_volume,
97:             ),
98:             (
99:                 "movement.wind.maximum_relative_volume",
100:                 movement.wind.maximum_relative_volume,
101:             ),
102:             (
103:                 "combat.impact_relative_volume",
104:                 self.combat.impact_relative_volume,
105:             ),
106:             (
107:                 "weather.rain_surface_maximum_relative_volume",
108:                 self.weather.rain_surface_maximum_relative_volume,
109:             ),
110:             (
111:                 "weather.rain_storm_maximum_relative_volume",
112:                 self.weather.rain_storm_maximum_relative_volume,
113:             ),
114:         ] {
115:             unit_interval(name, volume)?;
116:         }
117:         positive(
118:             "movement.tall_grass_rustle_pitch",
119:             movement.tall_grass_rustle_pitch,
120:         )?;
121:         positive("movement.bush_rustle_pitch", movement.bush_rustle_pitch)?;
122:         positive(
123:             "movement.bush_contact_radius_m",
124:             movement.bush_contact_radius_m,
125:         )?;
126:         pitch_range("movement.pitch_randomization", movement.pitch_randomization)?;
127:         if movement.wind.minimum_audible_speed_bps
128:             >= adventuresim_world_schema::BASIS_POINTS_PER_WHOLE
129:         {
130:             return Err("movement.wind.minimum_audible_speed_bps must be below one whole".into());
131:         }
132:         positive(
133:             "movement.wind.response_exponent",
134:             movement.wind.response_exponent,
135:         )?;
136:         pitch_range(
137:             "combat.impact_pitch_randomization",
138:             self.combat.impact_pitch_randomization,
139:         )?;
140:         unit_interval(
141:             "weather.heavy_rain_start_fraction",
142:             self.weather.heavy_rain_start_fraction,
143:         )?;
144:         if self.weather.heavy_rain_start_fraction >= 1.0 {
145:             return Err("weather.heavy_rain_start_fraction must be below 1".into());
146:         }
147:         positive(
148:             "weather.volume_response_per_second",
149:             self.weather.volume_response_per_second,
150:         )?;
151:         positive(
152:             "weather.surface_intensity_exponent",
153:             self.weather.surface_intensity_exponent,
154:         )?;
155:         unit_interval(
156:             "weather.storm_surface_ducking",
157:             self.weather.storm_surface_ducking,
158:         )
159:     }
160: }
161: 
162: fn positive(name: &str, value: f32) -> Result<(), String> {
163:     if value.is_finite() && value > 0.0 {
164:         Ok(())
165:     } else {
166:         Err(format!("{name} must be finite and positive"))
167:     }
168: }
169: 
170: fn unit_interval(name: &str, value: f32) -> Result<(), String> {
171:     if value.is_finite() && (0.0..=1.0).contains(&value) {
172:         Ok(())
173:     } else {
174:         Err(format!("{name} must be between 0 and 1"))
175:     }
176: }
177: 
178: fn pitch_range(name: &str, range: [f32; 2]) -> Result<(), String> {
179:     if range[0].is_finite() && range[0] > 0.0 && range[1].is_finite() && range[1] >= range[0] {
180:         Ok(())
181:     } else {
182:         Err(format!(
183:             "{name} must contain an ordered pair of positive values"
184:         ))
185:     }
186: }
