156: fn sync_gameplay_view(
157:     mode: Res<BrowserMode>,
158:     sky: Res<crate::presentation::AtmosphereIblCache>,
159:     settings: Res<crate::presentation::TacticalGraphicsSettings>,
160:     view: Option<Res<crate::strategic_scene::protocol::StrategicView>>,
161:     mut cameras: Query<&mut Camera, With<TacticalGameplayCamera>>,
162: ) {
163:     for mut camera in &mut cameras {
164:         if *mode == BrowserMode::Tactical {
165:             camera.is_active = true;
166:             camera.viewport = None;
167:             camera.sub_camera_view = None;
168:         } else {
169:             // The atmosphere bake validates submissions from this exact camera.
170:             // Render a masked one-pixel view until its shared environment map exists.
171:             camera.is_active = view.is_some() && !sky.is_ready(&settings);
172:             camera.viewport = Some(bevy::camera::Viewport {
173:                 physical_size: UVec2::ONE,
174:                 ..default()
175:             });
176:             camera.sub_camera_view = None;
177:         }
178:     }
179: }
