192: #[expect(
193:     clippy::too_many_arguments,
194:     reason = "the browser command bridge coordinates the complete renderer state in one exclusive drain"
195: )]
196: fn drain_browser_commands(
197:     mut commands: Commands,
198:     mut mode: ResMut<BrowserMode>,
199:     mut args: ResMut<Args>,
200:     mut local_character: ResMut<LocalCharacterId>,
201:     scene_entities: Query<Entity, With<StrategicSceneEntity>>,
202:     clients: Query<Entity, With<AdventureSimulatorClient>>,
203:     mut meshes: ResMut<Assets<Mesh>>,
204:     mut materials: ResMut<Assets<StandardMaterial>>,
205:     mut scene_roots: Query<&mut Transform, (With<StrategicSceneRoot>, Without<Camera3d>)>,
206:     mut preview_view: ResMut<ForgePreviewView>,
207: ) {
208:     let pending = pending_commands();
209: 
210:     for command in pending {
211:         match command {
212:             BrowserCommand::PrepareStrategicScene {
213:                 location,
214:                 input_json,
215:                 preparation,
216:             } => prepare_city(&mut commands, location, input_json, preparation),
217:             BrowserCommand::SyncStrategicView { view } => {
218:                 commands.insert_resource(view);
219:             }
220:             BrowserCommand::RegionalMap { command } => {
221:                 commands.queue(move |world: &mut World| command.apply(world))
222:             }
223:             BrowserCommand::ShowStrategicScene { scene } => {
224:                 *mode = BrowserMode::Strategic;
225:                 despawn_forge_preview(&mut commands, &scene_entities);
226:                 match scene {
227:                     StrategicScene::Forge {
228:                         catalog_id,
229:                         design_json,
230:                     } => spawn_forge_scene(
231:                         &mut commands,
232:                         &mut meshes,
233:                         &mut materials,
234:                         &catalog_id,
235:                         design_json.as_deref(),
236:                         &preview_view,
237:                     ),
238:                 }
239:             }
240:             BrowserCommand::OrbitForge { delta_x, delta_y } => {
241:                 preview_view.orbit(delta_x, delta_y);
242:                 for mut root in &mut scene_roots {
243:                     apply_preview_view(&preview_view, &mut root);
244:                 }
245:             }
246:             BrowserCommand::ZoomForge { delta } => {
247:                 preview_view.zoom(delta);
248:                 for mut root in &mut scene_roots {
249:                     apply_preview_view(&preview_view, &mut root);
250:                 }

251:             }
252:             BrowserCommand::HideForgePreview => {
253:                 despawn_forge_preview(&mut commands, &scene_entities);
254:                 *preview_view = ForgePreviewView::default();
255:             }
256:             BrowserCommand::EnterTactical {
257:                 server_addr,
258:                 character_id,
259:             } => {
260:                 commands.queue(|world: &mut World| {
261:                     crate::presentation::regional_map::protocol::MapCommand::Hide.apply(world)
262:                 });
263:                 commands.queue(crate::strategic_scene::release_scene);
264:                 commands.remove_resource::<crate::strategic_scene::protocol::StrategicView>();
265:                 despawn_forge_preview(&mut commands, &scene_entities);
266:                 if clients.is_empty() {
267:                     args.id = character_id;
268:                     args.server_addr.clone_from(&server_addr);
269:                     local_character.0 = character_id;
270:                     commands.spawn(AdventureSimulatorClient {
271:                         player_id: character_id,
272:                         server_url: server_addr,
273:                     });
274:                 }
275:                 *mode = BrowserMode::Tactical;
276:             }
277:             BrowserCommand::ExitTactical => {
278:                 for entity in &clients {
279:                     commands.entity(entity).despawn();
280:                 }
281:                 *mode = BrowserMode::Strategic;
282:             }
283:         }
284:     }
285: }
