287: fn pending_commands() -> Vec<BrowserCommand> {
288:     COMMANDS
289:         .get_or_init(|| Mutex::new(VecDeque::new()))
290:         .lock()
291:         .map(|mut queue| queue.drain(..).collect())
292:         .unwrap_or_default()
293: }
