304: fn spawn_forge_scene(
305:     commands: &mut Commands,
306:     meshes: &mut Assets<Mesh>,
307:     materials: &mut Assets<StandardMaterial>,
308:     catalog_id: &str,
309:     design_json: Option<&str>,
310:     view: &ForgePreviewView,
311: ) {
312:     let design = match design_json {
313:         Some(json) => match serde_json::from_str::<WeaponDesign>(json) {
314:             Ok(design) => Some(design),
315:             Err(error) => {
316:                 warn!(catalog_id, %error, "browser forge preview rejected invalid recipe");
317:                 return;
318:             }
319:         },
320:         None => default_design(catalog_id),
321:     };
322:     let Some(design) = design else {
323:         warn!(
324:             catalog_id,
325:             "browser forge preview rejected unknown weapon chassis"
326:         );
327:         return;
328:     };
329:     let Ok(generated) = generate(&design) else {
330:         warn!(
331:             catalog_id,
332:             "browser forge preview failed to generate weapon mesh"
333:         );
334:         return;
335:     };
336: 
337:     let center =
338:         (Vec3::from_array(generated.bounds.min) + Vec3::from_array(generated.bounds.max)) * 0.5;
339:     let extent = Vec3::from_array(generated.bounds.max) - Vec3::from_array(generated.bounds.min);
340:     let scale = 1.45 / extent.max_element().max(0.001);
341:     let root = commands
342:         .spawn((
343:             Name::new("Strategic forge weapon preview"),
344:             Visibility::default(),
345:             StrategicSceneEntity,
346:             StrategicSceneRoot,
347:             preview_transform(view, scale),
348:         ))
349:         .id();
350: 
351:     for part in generated.parts {
352:         let mut mesh = Mesh::new(
353:             PrimitiveTopology::TriangleList,
354:             RenderAssetUsages::MAIN_WORLD | RenderAssetUsages::RENDER_WORLD,
355:         );
356:         mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, part.positions);
357:         mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, part.normals);
358:         mesh.insert_indices(Indices::U32(part.indices));
359:         commands.spawn((
360:             Name::new(format!("Strategic forge part {}", part.component_id)),
361:             Mesh3d(meshes.add(mesh)),
362:             bevy::camera::visibility::RenderLayers::layer(
363:                 crate::strategic_scene::protocol::FORGE_LAYER,
364:             ),
365:             MeshMaterial3d(materials.add(preview_material(part.material))),
366:             Transform::from_translation(-center),
367:             ChildOf(root),
368:         ));
369:     }
370: 
371:     commands.spawn((
372:         Name::new("Strategic forge preview light"),
373:         bevy::camera::visibility::RenderLayers::layer(
374:             crate::strategic_scene::protocol::FORGE_LAYER,
375:         ),
376:         StrategicSceneEntity,
377:         DirectionalLight {
378:             illuminance: 60_000.0,
379:             shadow_maps_enabled: false,
380:             ..default()
381:         },
382:         Transform::from_xyz(-3.0, 4.0, 2.0).looking_at(Vec3::new(0.0, 0.0, -2.2), Vec3::Y),
383:     ));
384: 
385:     commands.spawn((
386:         Name::new("Strategic forge preview fill light"),
387:         bevy::camera::visibility::RenderLayers::layer(
388:             crate::strategic_scene::protocol::FORGE_LAYER,
389:         ),
390:         StrategicSceneEntity,
391:         PointLight {
392:             intensity: 12_000.0,
393:             range: 8.0,
394:             shadow_maps_enabled: false,
395:             ..default()
396:         },
397:         Transform::from_xyz(2.0, 1.5, 0.5),
398:     ));
399: }
400: 
401: fn preview_transform(view: &ForgePreviewView, scale: f32) -> Transform {
402:     Transform::from_xyz(0.0, 0.0, -view.distance)
403:         .with_rotation(Quat::from_euler(EulerRot::YXZ, view.yaw, view.pitch, -0.55))
404:         .with_scale(Vec3::splat(scale))
405: }
406: 
407: fn apply_preview_view(view: &ForgePreviewView, transform: &mut Transform) {
408:     let scale = transform.scale.x;
409:     *transform = preview_transform(view, scale);
410: }
