31: pub(super) fn sync(
32:     view: Option<Res<StrategicView>>,
33:     windows: Query<&Window>,
34:     mut cameras: Query<&mut Camera, With<ForgeCamera>>,
35: ) {
36:     for mut camera in &mut cameras {
