105: impl CloseCameraProfile {
106:     fn blend(self, distance: SignedLength) -> f32 {
107:         let t = ((self.start_distance.metres() - distance.metres())
108:             / (self.start_distance.metres() - self.full_distance.metres()))
109:         .clamp(0.0, 1.0);
