114: impl CameraVolume {
115:     pub(crate) fn new(projection: &Projection, margin: SignedLength) -> CameraResult<Self> {
116:         // Inverse projection is a native render-view numerical kernel. Its
117:         // result is admitted once before retaining physical collider geometry.
118:         let view_from_clip = projection.get_clip_from_view().inverse();
119:         let mut min = Vec3::ZERO;
120:         let mut max = Vec3::ZERO;
121:         for x in [-1.0, 1.0] {
122:             for y in [-1.0, 1.0] {
123:                 // Bevy uses reverse Z: the near plane is at clip-space Z = 1.
124:                 let corner = view_from_clip.project_point3(Vec3::new(x, y, 1.0));
125:                 min = min.min(corner);
126:                 max = max.max(corner);
127:             }
128:         }
129:         let size = CuboidDimensions::from_metres(max - min + Vec3::splat(2.0 * margin.metres()))?;
130:         let native_size = size.metres();
131:         Ok(Self {
132:             shape: Collider::cuboid(native_size.x, native_size.y, native_size.z),
133:             local_center: Displacement::from_metres((min + max) * 0.5)?,
134:             size,
135:         })
136:     }
