155:         filter: &SpatialQueryFilter,
156:         hard_obstacle: &dyn Fn(Entity) -> bool,
157:         frame: &CameraFrame,
158:         endpoint: Position<Scene>,
159:     ) -> CameraResult<CameraSweep> {
160:         // The physics cast consumes scene metres and a view-to-scene rotation.
161:         let delta = endpoint.metres() - frame.origin.metres();
162:         let Ok(direction) = Dir3::new(delta) else {
163:             return Ok(CameraSweep {
164:                 fraction: UnitInterval::from_fraction(1.0)?,
165:                 hit: None,
166:             });
167:         };
168:         let distance = delta.length();
169:         let hit = spatial.cast_shape_predicate(
170:             &self.shape,
171:             frame.origin.metres() + frame.rotation.quaternion() * self.local_center.metres(),
172:             frame.rotation.quaternion(),
173:             direction,
174:             &ShapeCastConfig::from_max_distance(distance),
175:             filter,
176:             hard_obstacle,
177:         );
178:         Ok(CameraSweep {
179:             fraction: UnitInterval::from_fraction(
180:                 hit.map_or(1.0, |hit| (hit.distance / distance).clamp(0.0, 1.0)),
181:             )?,
182:             hit: hit
183:                 .map(|hit| {
184:                     Ok::<_, super::values::CameraError>(CameraHit {
185:                         entity: hit.entity,
186:                         normal: SpatialDirection::from_normalized(hit.normal1)?,
187:                     })
188:                 })
189:                 .transpose()?,
190:         })

191:     }
