204: impl CameraFrame {
205:     fn endpoint(
206:         &self,
207:         distance: SignedLength,
208:         close: CloseCameraProfile,
209:     ) -> CameraResult<Position<Scene>> {
210:         // Native affine composition preserves the original glam lerp/order.
211:         let blend = close.blend(distance);
212:         let focus = self.focus.metres().lerp(self.anchor.metres(), blend);
213:         let offset = Vec2::new(self.shoulder_offset.metres(), 0.0).lerp(
214:             Vec2::new(close.offset.right.metres(), close.offset.up.metres()),
215:             blend,
216:         );
217:         Ok(Position::from_metres(
218:             focus + self.rotation.quaternion() * Vec3::new(offset.x, offset.y, distance.metres()),
219:         )?)
220:     }
221: }
