223: impl BoomRecovery {
224:     pub(crate) fn reset(&mut self, distance: SignedLength) {
225:         *self = Self {
226:             distance,
227:             ..default()
228:         };
229:     }
230: 
231:     fn retract(&mut self, distance: SignedLength, config: &CameraRigConfig) {
232:         self.distance = distance;
233:         self.velocity = SignedSpeed::ZERO;
234:         self.hold_remaining = config.collision_hold_time;
235:     }
236: 
237:     fn recover(
238:         &mut self,
239:         desired: SignedLength,
240:         limited: SignedLength,
241:         config: &CameraRigConfig,
242:         elapsed: AnimationElapsed,
243:     ) -> CameraResult<()> {
244:         if limited.metres() < self.distance.metres() {
245:             self.retract(limited, config);
246:             return Ok(());
247:         }
248:         if limited.metres() < desired.metres()
249:             && limited.metres() - self.distance.metres() <= config.collision_hysteresis.metres()
250:         {
251:             self.velocity = SignedSpeed::ZERO;
252:             self.hold_remaining = config.collision_hold_time;
253:             return Ok(());
254:         }
255:         if !self.hold_remaining.is_zero() {
256:             self.hold_remaining = self.hold_remaining.saturating_sub(elapsed);
257:             return Ok(());
258:         }
259:         // Analytic damping consumes metres and signed metres per second. Admit
260:         // both outputs before committing the replacement recovery sample.
261:         let mut velocity = self.velocity.metres_per_second();
262:         let distance = SignedLength::from_metres(
263:             critical_damp_scalar(
264:                 self.distance.metres(),
265:                 desired.metres().min(limited.metres()),
266:                 &mut velocity,
267:                 config.collision_recovery_time,
268:                 elapsed,
269:             )
270:             .min(limited.metres()),
271:         )?;
272:         let velocity = SignedSpeed::from_metres_per_second(velocity)?;
273:         self.distance = distance;
274:         self.velocity = velocity;
275:         Ok(())
276:     }
277: 
278:     #[expect(
279:         clippy::too_many_arguments,
280:         reason = "placement combines the retained boom with geometry, projection, framing, and timing"
281:     )]
282:     pub(crate) fn place(
283:         &mut self,
284:         frame: &CameraFrame,
285:         volume: &CameraVolume,
286:         spatial: &SpatialQuery,
287:         filter: &SpatialQueryFilter,
288:         hard_obstacle: &dyn Fn(Entity) -> bool,
289:         config: &CameraRigConfig,
290:         elapsed: AnimationElapsed,
291:     ) -> CameraResult<CameraPlacement> {
292:         let desired = frame.endpoint(frame.distance, config.close)?;
293:         let mut limited = frame.distance;
294:         let mut obstruction = None;
295:         // Solve the geometric limit independently of the previous frame. A
296:         // close shoulder offset can meet a second obstacle after the boom has
297:         // already retracted; recovery must not target that obstructed pose.
298:         for _ in 0..MAX_FRAMING_SWEEPS {
299:             let endpoint = frame.endpoint(limited, config.close)?;
300:             let sweep = volume.sweep(spatial, filter, hard_obstacle, frame, endpoint)?;
301:             obstruction = sweep.hit.or(obstruction);
302:             limited = SignedLength::from_metres(limited.metres() * sweep.fraction.fraction())?;
303:             if sweep.hit.is_none() {
304:                 break;
305:             }
306:         }
307:         let mut recovery = *self;
308:         recovery.recover(frame.distance, limited, config, elapsed)?;
309:         let candidate = frame.endpoint(recovery.distance, config.close)?;
310:         // Framing, focus lag and damping all change the tested path. Validate
311:         // their final result; no camera translation is applied after this sweep.
312:         let final_sweep = volume.sweep(spatial, filter, hard_obstacle, frame, candidate)?;
313:         let position = Position::from_metres(
314:             frame
315:                 .origin
316:                 .metres()
317:                 .lerp(candidate.metres(), final_sweep.fraction.fraction()),
318:         )?;
319:         if final_sweep.fraction.fraction() < 1.0 {
320:             recovery.retract(
321:                 SignedLength::from_metres(
322:                     recovery.distance.metres() * final_sweep.fraction.fraction(),
323:                 )?,
324:                 config,
325:             );
326:             limited = limited.min(recovery.distance);
327:         }
328:         *self = recovery;
329:         Ok(CameraPlacement {
330:             position,
331:             desired,
332:             hit: final_sweep.hit.or(obstruction),
333:             limited_distance: limited,
334:         })
335:     }
336: }
