30: pub(super) fn damp_focus(
31:     current: Position<Scene>,
32:     target: Position<Scene>,
33:     velocity: SceneVelocity,
34:     profile: CameraProfile,
35:     elapsed: AnimationElapsed,
36: ) -> CameraResult<FocusSample> {
37:     // The analytic filters consume scene metres and scene metres per second.
38:     // Keep their original horizontal/vertical operation order, then admit the
39:     // complete replacement before publishing either position or velocity.
40:     let current = current.metres();
41:     let target = target.metres();
42:     let velocity = velocity.metres_per_second();
43:     let mut horizontal_velocity = Vec3::new(velocity.x, 0.0, velocity.z);
44:     let horizontal = critical_damp_vec3(
45:         Vec3::new(current.x, 0.0, current.z),
46:         Vec3::new(target.x, 0.0, target.z),
47:         &mut horizontal_velocity,
48:         profile.horizontal_follow_time,
49:         elapsed,
50:     );
51:     let mut vertical_velocity = velocity.y;
52:     let y = critical_damp_scalar(
53:         current.y,
54:         target.y,
55:         &mut vertical_velocity,
56:         profile.vertical_follow_time,
57:         elapsed,
58:     );
59:     Ok(FocusSample {
60:         position: Position::from_metres(Vec3::new(horizontal.x, y, horizontal.z))?,
61:         velocity: SceneVelocity::from_metres_per_second(Vec3::new(
62:             horizontal_velocity.x,
63:             vertical_velocity,
64:             horizontal_velocity.z,
65:         ))?,
66:     })
67: }
