69: pub(super) fn critical_damp_vec3(
70:     current: Vec3,
71:     target: Vec3,
72:     velocity: &mut Vec3,
73:     smooth_time: ResponseShapingTime,
74:     elapsed: AnimationElapsed,
75: ) -> Vec3 {
76:     let dt = elapsed.seconds();
77:     let omega = 2.0 / smooth_time.seconds().max(0.0001);
78:     let displacement = current - target;
79:     let exponential = (-omega * dt).exp();
80:     let temporary = (*velocity + displacement * omega) * dt;
81:     *velocity = (*velocity - temporary * omega) * exponential;
82:     target + (displacement + temporary) * exponential
83: }
