149: pub(super) fn sweet_spot_target(
150:     anchor: Position<Scene>,
151:     focus: Position<Scene>,
152:     rotation: RigidRotation,
153:     distance: SignedLength,
154:     sweet_spot: ScreenWindow,
155:     view: CameraViewMetrics,
156: ) -> CameraResult<SweetSpotSample> {
157:     // Project scene metres into the render camera basis; NDC is dimensionless.
158:     let anchor = anchor.metres();
159:     let focus = focus.metres();
160:     let rotation = rotation.quaternion();
161:     let distance = distance.metres();
162:     let sweet_spot = sweet_spot.ndc_half_extents();
163:     let right = rotation * Vec3::X;
164:     let up = rotation * Vec3::Y;
165:     let error = anchor - focus;
166:     let aspect = view.aspect.ratio();
167:     let half_height = distance * view.tan_half_vertical_fov.ratio();
168:     let allowed_x = half_height * aspect * sweet_spot.x;
169:     let allowed_y = half_height * sweet_spot.y;
170:     let x = error.dot(right);
171:     let y = error.dot(up);
172:     let retained_x = x.clamp(-allowed_x, allowed_x);
173:     let retained_y = y.clamp(-allowed_y, allowed_y);
174:     let target = anchor - right * retained_x - up * retained_y;
175:     let screen_error = Vec2::new(
176:         if half_height > 0.0 {
177:             x / (half_height * aspect)
178:         } else {
179:             0.0
180:         },
181:         if half_height > 0.0 {
182:             y / half_height
183:         } else {
184:             0.0
185:         },
186:     );
187:     Ok(SweetSpotSample {
188:         target: Position::from_metres(target)?,
189:         error: ScreenError::from_ndc(screen_error)?,
190:     })
191: }
