44: #[derive(Debug, thiserror::Error)]
45: pub enum CameraError {
46:     #[error(transparent)]
47:     Geometry(#[from] GeometryError),
48:     #[error(transparent)]
49:     Speed(#[from] SpeedError),
50:     #[error(transparent)]
51:     Animation(#[from] AnimationValueError),
52:     #[error("screen half-extents must be finite and nonnegative")]
53:     InvalidScreenWindow,
54:     #[error("screen error must be finite")]
55:     InvalidScreenError,
56: }
57: 
58: impl ScreenWindow {
59:     pub const fn from_ndc_half_extents(value: Vec2) -> CameraResult<Self> {
60:         if !value.x.is_finite() || !value.y.is_finite() || value.x < 0.0 || value.y < 0.0 {
61:             return Err(CameraError::InvalidScreenWindow);
62:         }
63:         Ok(Self {
64:             horizontal: Ratio::from_ratio(value.x),
65:             vertical: Ratio::from_ratio(value.y),
66:         })
67:     }
68: 
69:     pub fn ndc_half_extents(self) -> Vec2 {
70:         Vec2::new(self.horizontal.ratio(), self.vertical.ratio())
71:     }
