76:         if !value.is_finite() {
77:             return Err(CameraError::InvalidScreenError);
78:         }
79:         Ok(Self {
80:             horizontal: Ratio::from_ratio(value.x),
81:             vertical: Ratio::from_ratio(value.y),
82:         })
83:     }
84: 
85:     pub(crate) fn ndc(self) -> Vec2 {
86:         Vec2::new(self.horizontal.ratio(), self.vertical.ratio())
