81:     let tangent = normal.any_orthonormal_vector();
82:     let bitangent = normal.cross(tangent).normalize_or_zero();
83:     (normal * 0.55 + tangent * angle.cos() + bitangent * angle.sin() + Vec3::Y * upward)
84:         .normalize_or(Vec3::Y)
85: }
