87: #[expect(
88:     clippy::too_many_arguments,
89:     reason = "combat effects independently borrow event targets, render assets, hierarchy, surfaces, and deterministic variation state"
90: )]
91: fn spawn_combat_effects(
92:     event: On<SuccessfulAttackResponse>,
93:     mut commands: Commands,
94:     targets: Query<&GlobalTransform>,
95:     mut resources: CombatEffectResources,
96:     parents: Query<&ChildOf>,
97:     surfaces: BloodSurfaceQuery,
98:     mut sound_sequences: Local<std::collections::BTreeMap<u64, u64>>,
99:     identities: Query<&CharacterId>,
100:     mut effect_sequence: Local<u64>,
101: ) {
102:     if !event.impact_effects.metal_sparks
103:         && !event.impact_effects.blood
104:         && event.impact_effects.sound == ImpactSound::None
105:     {
106:         return;
107:     }
108:     let Some(target) = event.hit.first().copied() else {
109:         return;
110:     };
111:     let Ok(target_transform) = targets.get(target) else {
112:         return;
113:     };
114:     resources
115:         .assets
116:         .prepare(&mut resources.meshes, &mut resources.materials);
117:     let world_point = target_transform.transform_point(event.impact_point);
118:     let world_normal = target_transform
119:         .affine()
120:         .transform_vector3(event.impact_normal)
121:         .normalize_or(Vec3::Y);
122:     let Some(sound_seed) = combat_sound_seed(event.attacker, &identities, &mut sound_sequences)
123:     else {
124:         return;
125:     };
126:     play_impact_sound(
127:         &mut commands,
128:         &resources.asset_server,
129:         event.impact_effects.sound,
130:         world_point,
131:         sound_seed,
132:         &resources.config,
133:     );
134: 
135:     if event.impact_effects.metal_sparks {
136:         for index in 0..SPARK_COUNT {
137:             let direction = spread_direction(world_normal, index, SPARK_COUNT, 0.35);
138:             commands.spawn((
139:                 Name::new("metal-impact-spark"),
140:                 Mesh3d(resources.assets.spark_mesh.clone()),
141:                 MeshMaterial3d(resources.assets.spark_material.clone()),
142:                 Transform::from_translation(world_point + world_normal * 0.015)
143:                     .with_rotation(Quat::from_rotation_arc(Vec3::Z, direction)),
144:                 CombatParticle {
145:                     velocity: direction * (2.8 + index as f32 * 0.09),
146:                     remaining_seconds: 0.24,
147:                     blood: false,
148:                 },
149:                 Spark,
150:             ));
151:         }
152:     }
153: 
154:     if event.impact_effects.blood {
155:         *effect_sequence = effect_sequence.wrapping_add(1);
156:         blood_decals::stamp_character_blood(
157:             &mut commands,
158:             target,
159:             world_point,
160:             *effect_sequence,
161:             &parents,
162:             &surfaces,
163:             &mut BloodMaterialAssets {
164:                 field: resources.interior.buffer.clone(),
165:                 meshes: &resources.meshes,
166:                 images: &mut resources.images,
167:                 standard: &resources.materials,
168:                 blood: &mut resources.blood_materials,
169:             },
170:         );
171:         for index in 0..BLOOD_COUNT {
172:             let direction = spread_direction(world_normal, index, BLOOD_COUNT, 0.55);
173:             commands.spawn((
174:                 Name::new("blood-particle"),
175:                 Mesh3d(resources.assets.blood_mesh.clone()),
176:                 MeshMaterial3d(resources.assets.blood_material.clone()),
177:                 Transform::from_translation(world_point + world_normal * 0.02),
178:                 CombatParticle {
179:                     velocity: direction * (1.35 + index as f32 * 0.035),
180:                     remaining_seconds: 1.6,
181:                     blood: true,
182:                 },
183:             ));
184:         }
185:     }
186: }
