199: fn play_impact_sound(
200:     commands: &mut Commands,
201:     asset_server: &AssetServer,
202:     sound: ImpactSound,
203:     world_point: Vec3,
204:     seed: Seed,
205:     config: &TacticalAudioConfig,
206: ) {
207:     let family = match sound {
208:         ImpactSound::None => return,
209:         ImpactSound::Metal => "impactMetal_medium_00",
210:         ImpactSound::CutFlesh => "impactSoft_medium_00",
211:         ImpactSound::BluntFlesh => "impactPunch_medium_00",
212:         ImpactSound::NonMetalWeapon => "impactWood_medium_00",
213:     };
214:     let context = [
215:         u64::from(world_point.x.to_bits()),
216:         u64::from(world_point.y.to_bits()),
217:         u64::from(world_point.z.to_bits()),
218:     ];
219:     let variant = StreamId::new("audio.combat-variant")
220:         .rng(seed, &context)
221:         .index(3);
222:     let pitch_fraction = StreamId::new("audio.combat-pitch")
223:         .rng(seed, &context)
224:         .inclusive_unit_f32();
225:     let pitch = config.combat.impact_pitch_randomization;
226:     let speed = pitch[0] + pitch_fraction * (pitch[1] - pitch[0]);
227:     let path = format!("audio/combat/kenney-impact-sounds/{family}{variant}.ogg");
228:     commands.spawn((
229:         Name::new("combat-impact-sound"),
230:         AudioPlayer::new(asset_server.load(path)),
231:         PlaybackSettings {
232:             mode: PlaybackMode::Despawn,
233:             speed,
234:             spatial: true,
235:             volume: Volume::Linear(config.combat.impact_relative_volume),
236:             ..default()
237:         },
238:         Transform::from_translation(world_point),
239:     ));
240: }
