242: #[expect(
243:     clippy::too_many_arguments,
244:     reason = "particle integration independently borrows collision, terrain presentation, mutable masks, and particle state"
245: )]
246: fn move_combat_particles(
247:     mut commands: Commands,
248:     time: Res<Time>,
249:     spatial: SpatialQuery,
250:     procedural_assets: Res<ProceduralTextureAssets>,
251:     terrains: Query<&SceneTerrain>,
252:     mut images: ResMut<Assets<Image>>,
253:     mut terrain_stain_sequence: Local<u64>,
254:     mut particles: Query<(Entity, &mut Transform, &mut CombatParticle)>,
255: ) {
256:     let delta_seconds = time.delta_secs();
257:     for (entity, mut transform, mut particle) in &mut particles {
258:         particle.remaining_seconds -= delta_seconds;
259:         if particle.remaining_seconds <= 0.0 {
260:             commands.entity(entity).despawn();
261:             continue;
262:         }
263:         if particle.blood {
264:             particle.velocity.y -= GRAVITY_METRES_PER_SECOND_SQUARED * delta_seconds;
265:         }
266:         let movement = particle.velocity * delta_seconds;
267:         let distance = movement.length();
268:         if particle.blood
269:             && distance > 0.0
270:             && let Ok(direction) = Dir3::new(movement)
271:             && let Some(hit) = spatial.cast_ray(
272:                 transform.translation,
273:                 direction,
274:                 distance,
275:                 true,
276:                 &SpatialQueryFilter::from_mask(TACTICAL_TERRAIN_LAYER),
277:             )
278:         {
279:             let point = transform.translation + movement.normalize() * hit.distance;
280:             if let Some(terrain) = terrains.iter().find(|terrain| {
281:                 point.x.abs() <= terrain.width() * 0.5 && point.z.abs() <= terrain.depth() * 0.5
282:             }) && let Some(mut mask) = images.get_mut(&procedural_assets.terrain_blood_mask)
283:             {
284:                 *terrain_stain_sequence = terrain_stain_sequence.wrapping_add(1);
285:                 blood_decals::stamp_terrain_blood(
286:                     &mut mask,
287:                     point,
288:                     Vec2::new(terrain.width(), terrain.depth()),
289:                     *terrain_stain_sequence,
290:                 );
291:             }
292:             commands.entity(entity).despawn();
293:             continue;
294:         }
295:         transform.translation += movement;
296:         if !particle.blood {
297:             transform.rotation =
298:                 Quat::from_rotation_arc(Vec3::Z, particle.velocity.normalize_or(Vec3::Y));
299:         }
300:     }
301: }
