303: fn fade_sparks(time: Res<Time>, mut sparks: Query<&mut Transform, With<Spark>>) {
304:     let scale = (1.0 - time.delta_secs() * 7.0).max(0.35);
305:     for mut transform in &mut sparks {
306:         transform.scale *= scale;
307:     }
308: }

