118: struct SurfaceUvHit<'a> {
119:     entity: Entity,
120:     uv: Vec2,
121:     distance_squared: f32,
122:     material: Option<&'a Handle<StandardMaterial>>,
123:     surface: Option<&'a BloodMaskSurface>,
124: }
