126: fn closest_surface_uv<'a>(
127:     target: Entity,
128:     world_point: Vec3,
129:     parents: &Query<&ChildOf>,
130:     surfaces: &'a BloodSurfaceQuery,
131:     meshes: &Assets<Mesh>,
132: ) -> Option<SurfaceUvHit<'a>> {
133:     surfaces
134:         .iter()
135:         .filter(|(entity, _, _, material, surface)| {
136:             (material.is_some() || surface.is_some()) && is_descendant_of(*entity, target, parents)
137:         })
138:         .filter_map(|(entity, mesh_handle, global, material, surface)| {
139:             let mesh = meshes.get(&mesh_handle.0)?;
140:             let local_point = global.affine().inverse().transform_point3(world_point);
141:             let (uv, distance_squared) = closest_mesh_uv(mesh, local_point)?;
142:             Some(SurfaceUvHit {
143:                 entity,
144:                 uv,
145:                 distance_squared,
146:                 material: material.map(|handle| &handle.0),
147:                 surface,
148:             })
149:         })
150:         .min_by(|left, right| left.distance_squared.total_cmp(&right.distance_squared))
151: }
