153: fn is_descendant_of(mut entity: Entity, ancestor: Entity, parents: &Query<&ChildOf>) -> bool {
154:     while let Ok(parent) = parents.get(entity) {
155:         entity = parent.parent();
156:         if entity == ancestor {
157:             return true;
158:         }
159:     }
160:     false
161: }
