163: fn closest_mesh_uv(mesh: &Mesh, point: Vec3) -> Option<(Vec2, f32)> {
164:     let VertexAttributeValues::Float32x3(positions) = mesh.attribute(Mesh::ATTRIBUTE_POSITION)?
165:     else {
166:         return None;
167:     };
168:     let VertexAttributeValues::Float32x2(uvs) = mesh.attribute(Mesh::ATTRIBUTE_UV_0)? else {
169:         return None;
170:     };
171:     let indices: Vec<usize> = match mesh.indices() {
172:         Some(Indices::U16(values)) => values.iter().map(|value| usize::from(*value)).collect(),
173:         Some(Indices::U32(values)) => values.iter().map(|value| *value as usize).collect(),
174:         None => (0..positions.len()).collect(),
175:     };
176: 
177:     indices
178:         .as_chunks::<3>()
179:         .0
180:         .iter()

181:         .filter_map(|triangle| {
182:             let a = Vec3::from(*positions.get(triangle[0])?);
183:             let b = Vec3::from(*positions.get(triangle[1])?);
184:             let c = Vec3::from(*positions.get(triangle[2])?);
185:             let barycentric = closest_triangle_barycentric(point, a, b, c);
186:             let closest = a * barycentric.x + b * barycentric.y + c * barycentric.z;
187:             let uv_a = Vec2::from(*uvs.get(triangle[0])?);
188:             let uv_b = Vec2::from(*uvs.get(triangle[1])?);
189:             let uv_c = Vec2::from(*uvs.get(triangle[2])?);
190:             Some((
191:                 uv_a * barycentric.x + uv_b * barycentric.y + uv_c * barycentric.z,
192:                 closest.distance_squared(point),
193:             ))
194:         })
195:         .min_by(|left, right| left.1.total_cmp(&right.1))
196: }
197: 
198: // Real-Time Collision Detection, Christer Ericson, section 5.1.5.
199: fn closest_triangle_barycentric(point: Vec3, a: Vec3, b: Vec3, c: Vec3) -> Vec3 {
200:     let ab = b - a;
201:     let ac = c - a;
202:     let ap = point - a;
203:     let d1 = ab.dot(ap);
204:     let d2 = ac.dot(ap);
205:     if d1 <= 0.0 && d2 <= 0.0 {
206:         return Vec3::X;
207:     }
208:     let bp = point - b;
209:     let d3 = ab.dot(bp);
210:     let d4 = ac.dot(bp);
211:     if d3 >= 0.0 && d4 <= d3 {
212:         return Vec3::Y;
213:     }
214:     let vc = d1 * d4 - d3 * d2;
215:     if vc <= 0.0 && d1 >= 0.0 && d3 <= 0.0 {
216:         let v = d1 / (d1 - d3);
217:         return Vec3::new(1.0 - v, v, 0.0);
218:     }
219:     let cp = point - c;
220:     let d5 = ab.dot(cp);
221:     let d6 = ac.dot(cp);
222:     if d6 >= 0.0 && d5 <= d6 {
223:         return Vec3::Z;
224:     }
225:     let vb = d5 * d2 - d1 * d6;
226:     if vb <= 0.0 && d2 >= 0.0 && d6 <= 0.0 {
227:         let w = d2 / (d2 - d6);
228:         return Vec3::new(1.0 - w, 0.0, w);
229:     }
230:     let va = d3 * d6 - d5 * d4;
231:     if va <= 0.0 && d4 - d3 >= 0.0 && d5 - d6 >= 0.0 {
232:         let w = (d4 - d3) / ((d4 - d3) + (d5 - d6));
233:         return Vec3::new(0.0, 1.0 - w, w);
234:     }
235:     let denominator = 1.0 / (va + vb + vc);
236:     Vec3::new(va, vb, vc) * denominator
237: }
