264: pub(super) fn stamp_terrain_blood(
265:     image: &mut Image,
266:     world_point: Vec3,
267:     terrain_size: Vec2,
268:     sequence: u64,
269: ) {
270:     let dimensions = Vec2::new(
271:         image.texture_descriptor.size.width as f32,
272:         image.texture_descriptor.size.height as f32,
273:     );
274:     let uv = world_point.xz() / terrain_size + Vec2::splat(0.5);
275:     let radius = Vec2::splat(TERRAIN_BLOOD_STAIN_RADIUS_METRES) / terrain_size * dimensions;
276:     stamp_mask_with_radius(image, uv, radius, sequence);
277: }
278: 
279: fn stamp_mask_with_radius(image: &mut Image, uv: Vec2, radius: Vec2, sequence: u64) {
280:     let width = image.texture_descriptor.size.width;
281:     let height = image.texture_descriptor.size.height;
282:     let Some(pixels) = image.data.as_mut() else {
283:         return;
284:     };
285:     let centre = Vec2::new(
286:         uv.x.clamp(0.0, 1.0) * (width - 1) as f32,
287:         (1.0 - uv.y.clamp(0.0, 1.0)) * (height - 1) as f32,
288:     );
289:     let angle = (sequence as f32 * 2.399_963_1).rem_euclid(std::f32::consts::TAU);
290:     let minimum = (centre - radius - Vec2::splat(2.0)).max(Vec2::ZERO);
291:     let maximum = (centre + radius + Vec2::splat(2.0))
292:         .min(Vec2::new((width - 1) as f32, (height - 1) as f32));
293:     for y in minimum.y as u32..=maximum.y as u32 {
294:         for x in minimum.x as u32..=maximum.x as u32 {
295:             let delta = Vec2::new(x as f32, y as f32) - centre;
296:             let polar = delta.y.atan2(delta.x) + angle;
297:             let normalized_distance = (delta / radius.max(Vec2::ONE)).length();
298:             let edge = 0.78 + 0.12 * (polar * 5.0).sin() + 0.07 * (polar * 9.0 + 0.8).sin();
299:             let alpha =
300:                 ((edge - normalized_distance) * radius.min_element() * 0.45).clamp(0.0, 1.0);
301:             let index = (y * width + x) as usize;
302:             pixels[index] = pixels[index].max((alpha * 235.0) as u8);
303:         }
304:     }
305: }
