42: /// `bevy_enhanced_input`'s action components (`Actions<C>`, `ActionMock`)
43: /// derive `Reflect` but don't attach `#[reflect(Component)]` themselves (as
44: /// of 0.23), so BRP can't see them without this - it doesn't touch the
45: /// external crate, just fills in the missing type data on our own
46: /// `App`. Also used by `crates/adventuresim-tactical-brp-generator` so
47: /// `ActionMock`/`Actions<Player>` show up as generated Python classes.
48: ///
49: /// Inserting `ActionMock` via BRP is how tests simulate an attack/dodge/
50: /// parry: it reproduces the *real* input-processing pipeline
51: /// (`bevy_enhanced_input::action::mock` - `Fire<A>`/`Start<A>`/etc all still
52: /// fire), not a bypass of it. Finding the right action entity to insert it
53: /// on still needs `Actions<Player>` (this client's `Player` input context,
54: /// `adventuresim_tactical_core::player::Player`) read via BRP.
55: pub fn register_input_mock_types(app: &mut App) {
56:     app.register_type::<Actions<Player>>();
57:     app.register_type_data::<Actions<Player>, ReflectComponent>();
58:     app.register_type::<ActionMock>();
59:     app.register_type_data::<ActionMock, ReflectComponent>();
60: }
