101: )]
102: fn toggle_debug_visuals(
103:     keyboard: Res<ButtonInput<KeyCode>>,
104:     mut config: ResMut<DebugVisualsConfig>,
105:     mut terrain_ik: ResMut<TerrainIkMode>,
106:     mut game_speed: ResMut<DebugGameSpeed>,
107:     mut virtual_time: ResMut<Time<Virtual>>,
108:     q_colliders: Query<(Entity, Option<&LimbHitbox>), (With<Collider>, Without<ClientPlayer>)>,
109:     headless_target: Option<Res<HeadlessScreenshotTarget>>,
110:     mut cmd: Commands,
111: ) {
112:     if keyboard.just_pressed(KeyCode::F7) {
113:         game_speed.quarter_speed = !game_speed.quarter_speed;
114:         let request = DebugGameTimeScaleRequest {
115:             quarter_speed: game_speed.quarter_speed,
116:         };
117:         let relative_speed = request.relative_speed();
118:         virtual_time.set_relative_speed(relative_speed);
119:         cmd.client_trigger(request);
120:         info!(relative_speed, "Debug game speed toggled");
121:     }
122: 
123:     if keyboard.just_pressed(KeyCode::F2) {
124:         config.physics_colliders = !config.physics_colliders;
125:         for (entity, hitbox) in &q_colliders {
126:             if hitbox.is_none() {
127:                 cmd.entity(entity).insert(if config.physics_colliders {
128:                     DebugRender::collider(tailwind::AMBER_200.into()).with_axes(Vec3::splat(0.33))
129:                 } else {
130:                     DebugRender::none()
131:                 });
132:             }
133:         }
134:     }
135: 
136:     if keyboard.just_pressed(KeyCode::F3) {
137:         config.hitboxes = !config.hitboxes;
138:         for (entity, hitbox) in &q_colliders {
139:             if let Some(hitbox) = hitbox {
140:                 let color = limb_hitbox_color(hitbox.0);
141:                 cmd.entity(entity).insert(if config.hitboxes {
142:                     DebugRender::collider(color)
143:                 } else {
144:                     DebugRender::none()
145:                 });
146:             }
147:         }
148:     }
149: 
150:     if keyboard.just_pressed(KeyCode::F4) {
151:         config.raycast = !config.raycast;
152:     }
153: 
154:     if keyboard.just_pressed(KeyCode::F8) {
155:         terrain_ik.toggle();
156:         info!(enabled = terrain_ik.is_enabled(), "Terrain leg IK toggled");
157:     }
158: 
159:     if keyboard.just_pressed(KeyCode::F10) {
160:         cmd.client_trigger(DebugDumpWorldRequest);
161:         info!("Requested a server-side world dump");
162:     }
163: 
164:     if keyboard.just_pressed(KeyCode::F12) {
165:         request_screenshot(&mut cmd, headless_target.as_deref());
166:     }
167: }
