169: /// Captures whatever the gameplay camera currently sees, windowed or
170: /// headless. In headless mode there's no window to capture from - see
171: /// `configure_headless_render_target` in `main.rs`, which points the camera
172: /// at an off-screen render target instead and publishes it here as
173: /// [`HeadlessScreenshotTarget`].
174: fn request_screenshot(cmd: &mut Commands, headless_target: Option<&HeadlessScreenshotTarget>) {
175:     let dir = std::path::Path::new("screenshots");
176:     if let Err(error) = std::fs::create_dir_all(dir) {
177:         error!(?error, "Failed to create screenshots directory");
178:         return;
179:     }
180:     let timestamp = std::time::SystemTime::now()
181:         .duration_since(std::time::UNIX_EPOCH)
182:         .unwrap_or_default()
183:         .as_millis();
184:     let path = dir.join(format!("screenshot_{timestamp}.png"));
185: 
186:     let screenshot = match headless_target {
187:         Some(target) => Screenshot::image(target.0.clone()),
188:         None => Screenshot::primary_window(),
189:     };
190:     cmd.spawn(screenshot).observe(save_to_disk(path.clone()));
191:     info!(path = %path.display(), "Requested a screenshot");
192: }
