194: /// Debug-only: a BRP-settable equivalent of the F10 keypress
195: /// (`DebugDumpWorldRequest`) - lets tests request a server-side world dump
196: /// without simulating a key event. Set to `true` via BRP
197: /// (`world.insert_resources`); `trigger_debug_dump_from_brp` sends the
198: /// request on the next frame and resets this back to `false`.
199: #[derive(Resource, Default, Reflect)]
200: #[reflect(Resource)]

201: pub(crate) struct DebugDumpWorldTrigger(pub(crate) bool);
