203: fn trigger_debug_dump_from_brp(mut cmd: Commands, mut trigger: ResMut<DebugDumpWorldTrigger>) {
204:     if !trigger.0 {
205:         return;
206:     }
207:     trigger.0 = false;
208:     cmd.client_trigger(DebugDumpWorldRequest);
209:     info!("Debug: requested a server-side world dump via BRP");
210: }
