212: fn limb_hitbox_color(body_part: BodyPart) -> Color {
213:     match body_part {
214:         BodyPart::LeftArm | BodyPart::RightArm => tailwind::LIME_600,
215:         BodyPart::LeftLeg | BodyPart::RightLeg => tailwind::SKY_600,
216:         BodyPart::Head => tailwind::RED_300,
217:         BodyPart::Chest => tailwind::PINK_300,
218:         BodyPart::Stomach => tailwind::PURPLE_300,
219:     }
220:     .into()
221: }
222: 
223: fn on_hit_performed(
224:     event: On<HitPerformed>,
225:     mut cmd: Commands,
226:     mut gizmo_assets: ResMut<Assets<GizmoAsset>>,
227:     config: Res<DebugVisualsConfig>,
228: ) {
229:     if !config.raycast {
230:         return;
231:     }
232: 
233:     let hit = event.event();
234:     let end = hit.origin + *hit.direction * hit.length;
235: 
236:     let mut asset = GizmoAsset::default();
237:     asset.line(hit.origin, end, tailwind::ROSE_600);
238:     let handle = gizmo_assets.add(asset);
239: 
240:     cmd.spawn((
241:         DebugRay {
242:             timer: Timer::from_seconds(2.0, TimerMode::Once),
243:             handle: handle.clone(),
244:         },
245:         Gizmo {
246:             handle,
247:             line_config: GizmoLineConfig {
248:                 width: 8.0,
249:                 ..default()
250:             },
251:             depth_bias: 0.0,
252:         },
253:     ));
254: }
255: 
256: fn draw_debug_rays(
257:     time: Res<Time>,
258:     mut cmd: Commands,
259:     mut gizmo_assets: ResMut<Assets<GizmoAsset>>,
260:     mut q_rays: Query<(Entity, &mut DebugRay)>,
261: ) {
262:     for (entity, mut ray) in &mut q_rays {
263:         ray.timer.tick(time.delta());
264: 
265:         if ray.timer.is_finished() {
266:             cmd.entity(entity).despawn();
267:             continue;
268:         }
269: 
270:         let alpha = EaseFunction::QuadraticOut.sample_unchecked(ray.timer.fraction_remaining());
271:         if let Some(mut asset) = gizmo_assets.get_mut(&ray.handle) {
272:             for color in &mut asset.list_colors {
273:                 color.set_alpha(alpha);
274:             }
275:         }
276:     }
277: }
