279: fn draw_camera_rig(
280:     enabled: Res<CameraDebugEnabled>,
281:     rig: Res<CameraRigDebugState>,
282:     aim: Res<CameraAimState>,
283:     mut gizmos: Gizmos,
284: ) {
285:     if !enabled.0 {
286:         return;
287:     }
288:     let Some(rig) = rig.0 else {
289:         return;
290:     };
291:     gizmos.line(rig.subject.metres(), rig.focus.metres(), tailwind::LIME_400);
292:     gizmos.line(
293:         rig.focus.metres(),
294:         rig.collision_origin.metres(),
295:         tailwind::SKY_300,
296:     );
297:     gizmos.line(
298:         rig.collision_origin.metres(),
299:         rig.desired_endpoint.metres(),
300:         tailwind::AMBER_300,
301:     );
302:     gizmos.line(
303:         rig.collision_origin.metres(),
304:         rig.final_endpoint.metres(),
305:         tailwind::CYAN_300,
306:     );
307:     if let Some(collision) = rig.collision {
308:         gizmos.line(
309:             rig.final_endpoint.metres(),
310:             rig.final_endpoint.metres() + collision.normal.vector() * 0.6,
311:             tailwind::RED_400,
312:         );
313:     }
314:     if let Some(occluder) = rig.soft_occluder {
315:         gizmos.line(
316:             occluder.point.metres() - Vec3::Y * 0.25,
317:             occluder.point.metres() + Vec3::Y * 0.25,
318:             tailwind::ORANGE_400,
319:         );
320:     }
321:     gizmos.cube(rig.collision_volume.native_transform(), tailwind::CYAN_200);
322:     if let Some(aim) = aim.0 {
323:         gizmos.line(
324:             aim.camera_origin.metres(),
325:             aim.camera_target.metres(),
326:             tailwind::PURPLE_300,
327:         );
328:         gizmos.line(
329:             aim.muzzle_origin.metres(),
330:             aim.actual_target.metres(),
331:             if aim.blocked() {
332:                 tailwind::RED_500
333:             } else {
334:                 tailwind::GREEN_400
335:             },
336:         );
337:     }
338: }
