197: impl DiagnosticPlugin {
198:     pub(crate) fn new(
199:         script_path: Option<&str>,
200:         log_path: Option<&str>,
201:         frame_timing_log_path: Option<&str>,
202:         frame_timing_seconds: Option<f64>,
203:         frame_timing_warmup_seconds: f64,
204:         exit_after_script: bool,
205:     ) -> Result<Self, String> {
206:         let script = script_path
207:             .map(|path| -> Result<InputScript, String> {
208:                 let bytes = std::fs::read(path)
209:                     .map_err(|error| format!("failed to read input script {path}: {error}"))?;
210:                 let script: InputScript = serde_json::from_slice(&bytes)
211:                     .map_err(|error| format!("failed to parse input script {path}: {error}"))?;
212:                 validate_script(&script)?;
213:                 Ok(script)
214:             })
215:             .transpose()?;
216:         let log = log_path
217:             .map(|path| create_diagnostic_file(path, "animation log"))
218:             .transpose()?;
219:         let frame_timing_log = frame_timing_log_path
220:             .map(|path| create_diagnostic_file(path, "frame timing log"))
221:             .transpose()?;
222:         if exit_after_script && script.is_none() {
223:             return Err("--exit-after-script requires --input-script".to_owned());
224:         }
225:         if frame_timing_log.is_some() != frame_timing_seconds.is_some() {
226:             return Err(
227:                 "--frame-timing-log and --frame-timing-seconds must be supplied together"
228:                     .to_owned(),
229:             );
230:         }

231:         if frame_timing_seconds.is_some_and(|seconds| !seconds.is_finite() || seconds <= 0.0) {
232:             return Err("--frame-timing-seconds must be finite and greater than zero".to_owned());
233:         }
234:         if !frame_timing_warmup_seconds.is_finite() || frame_timing_warmup_seconds < 0.0 {
235:             return Err("--frame-timing-warmup-seconds must be finite and non-negative".to_owned());
236:         }
237:         let render_schedule =
238:             (log.is_some() || frame_timing_log.is_some()).then(RenderScheduleTelemetry::new);
239:         Ok(Self {
240:             script,
241:             log,
242:             frame_timing_log,
243:             frame_timing_seconds,
244:             frame_timing_warmup_seconds,
245:             exit_after_script,
246:             render_schedule,
247:         })
248:     }
249: }
