255:                 writer: std::io::BufWriter::new(file),
256:                 frame: 0,
257:             });
258:         }
259:         if let Some(telemetry) = &self.render_schedule {
260:             app.insert_resource(telemetry.clone());
261:         }
262:         if let (Some(file), Some(sample_seconds)) = (
263:             self.frame_timing_log
264:                 .as_ref()
265:                 .and_then(|file| file.try_clone().ok()),
266:             self.frame_timing_seconds,
267:         ) {
268:             app.insert_resource(FrameTimingTrace {
269:                 writer: BufWriter::new(file),
270:                 frame: 0,
271:                 ready_elapsed_seconds: None,
272:                 sample_seconds,
273:                 warmup_seconds: self.frame_timing_warmup_seconds,
274:             })
275:             .add_systems(Last, record_frame_timing);
276:         }
277:         if let Some(script) = &self.script {
278:             app.insert_resource(ScriptedInput {
279:                 commands: script.commands.clone(),
280:                 command_index: 0,
281:                 command_elapsed: 0.0,
282:                 look: Vec2::ZERO,
283:                 weapon_guard: WeaponGuardState::Lowered,
284:                 pace: MovementPace::Sprint,
285:                 posture_sequence: 0,
286:                 jump_sequence: 0,
287:                 started: false,
288:                 exit_after_script: self.exit_after_script,
289:                 finished_elapsed: None,
290:             })
291:             .init_resource::<DiagnosticInputStatus>()
292:             .init_resource::<PendingDiagnosticCaptures>()
293:             .add_systems(
294:                 PreUpdate,
295:                 (
296:                     suppress_physical_input.after(InputSystems),
297:                     drive_scripted_input.after(suppress_physical_input),
298:                 ),
299:             );
300:         }
301:     }
302: 
303:     fn finish(&self, app: &mut App) {
304:         let Some(telemetry) = &self.render_schedule else {
305:             return;
306:         };
307:         let Some(render_app) = app.get_sub_app_mut(RenderApp) else {
308:             return;
309:         };
310:         render_app.insert_resource(telemetry.clone()).add_systems(
311:             Render,
312:             record_render_schedule_completion.after(RenderSystems::Render),
313:         );
314:     }
315: }
