327: fn record_frame_timing(
328:     time: Res<Time>,
329:     mut trace: ResMut<FrameTimingTrace>,
330:     render_schedule: Res<RenderScheduleTelemetry>,
331:     players: Query<(), (With<Player>, With<ClientPlayer>)>,
332:     mut exit: MessageWriter<AppExit>,
333: ) {
334:     if players.is_empty() {
335:         return;
336:     }
337:     let now = time.elapsed_secs_f64();
338:     let ready = *trace.ready_elapsed_seconds.get_or_insert(now);
339:     let elapsed_since_ready = now - ready;
340:     if elapsed_since_ready < trace.warmup_seconds {
341:         return;
342:     }
343:     let sample_elapsed_seconds = elapsed_since_ready - trace.warmup_seconds;
344:     let (render_count, render_elapsed_micros) = render_schedule.snapshot();
345:     let wall_clock_unix_micros = std::time::SystemTime::now()
346:         .duration_since(std::time::UNIX_EPOCH)
347:         .map(|duration| duration.as_micros().min(u64::MAX as u128) as u64)
348:         .unwrap_or_default();
349:     let record = FrameTimingRecord {
350:         trace_format: "real-client-frame-timing-v1",
351:         frame: trace.frame,
352:         sample_elapsed_seconds,
353:         render_delta_seconds: time.delta_secs(),
354:         wall_clock_unix_micros,
355:         render_schedule_completion_count: render_count,
356:         render_schedule_completion_elapsed_micros: render_elapsed_micros,
357:     };
358:     serde_json::to_writer(&mut trace.writer, &record)
359:         .expect("frame timing log should remain writable");
360:     trace
361:         .writer
362:         .write_all(b"\n")
363:         .expect("frame timing log should remain writable");
364:     trace.frame += 1;
365:     if sample_elapsed_seconds >= trace.sample_seconds {
366:         trace
367:             .writer
368:             .flush()
369:             .expect("frame timing log should remain writable");
370:         exit.write(AppExit::Success);
371:     }
372: }
