397: fn validate_script(script: &InputScript) -> Result<(), String> {
398:     if script.commands.is_empty() {
399:         return Err("input script must contain at least one command".to_owned());
400:     }
401:     for command in &script.commands {
402:         match command {
403:             ScriptCommand::Rotate { degrees_right } if !degrees_right.is_finite() => {
404:                 return Err("rotate degrees_right must be finite".to_owned());
405:             }
406:             ScriptCommand::Move {
407:                 input_speed,
408:                 duration_seconds,
409:                 attack_at_seconds: _,
410:                 turn_degrees_right,
411:                 ..
412:             } if !(0.0..=1.0).contains(input_speed)
413:                 || !duration_seconds.is_finite()
414:                 || *duration_seconds <= 0.0
415:                 || turn_degrees_right.is_some_and(|degrees| !degrees.is_finite()) =>
416:             {
417:                 return Err(
418:                     "move input_speed must be 0..=1 and duration_seconds must be positive"
419:                         .to_owned(),
420:                 );
421:             }
422:             ScriptCommand::Move {
423:                 duration_seconds,
424:                 attack_at_seconds: Some(attack_at_seconds),
425:                 ..
426:             } if !attack_at_seconds.is_finite()
427:                 || *attack_at_seconds < 0.0
428:                 || *attack_at_seconds >= *duration_seconds =>
429:             {
430:                 return Err(
431:                     "move attack_at_seconds must be finite and within the move duration".to_owned(),
432:                 );
433:             }
434:             ScriptCommand::Dive {
435:                 duration_seconds, ..
436:             }
437:             | ScriptCommand::Slide {
438:                 duration_seconds, ..
439:             } if !duration_seconds.is_finite() || *duration_seconds <= 0.0 => {
440:                 return Err("dive/slide duration_seconds must be positive".to_owned());
441:             }
442:             ScriptCommand::Quickstep {
443:                 duration_seconds, ..
444:             } if !duration_seconds.is_finite() || *duration_seconds <= 0.0 => {
445:                 return Err("quickstep duration_seconds must be positive".to_owned());
446:             }
447:             ScriptCommand::TogglePosture { duration_seconds }
448:                 if !duration_seconds.is_finite() || *duration_seconds <= 0.0 =>
449:             {
450:                 return Err("toggle_posture duration_seconds must be positive".to_owned());
451:             }
452:             ScriptCommand::Wait { duration_seconds }
453:                 if !duration_seconds.is_finite() || *duration_seconds <= 0.0 =>
454:             {
455:                 return Err("wait duration_seconds must be positive".to_owned());
456:             }
457:             ScriptCommand::Attack { duration_seconds }
458:                 if !duration_seconds.is_finite() || *duration_seconds <= 0.0 =>
459:             {
460:                 return Err("attack duration_seconds must be positive".to_owned());

461:             }
462:             ScriptCommand::Screenshot { path } if path.trim().is_empty() => {
463:                 return Err("screenshot path must not be empty".to_owned());
464:             }
465:             ScriptCommand::WaitForSignal { path } if path.trim().is_empty() => {
466:                 return Err("wait_for_signal path must not be empty".to_owned());
467:             }
468:             _ => {}
469:         }
470:     }
471:     Ok(())
472: }
