478: fn drive_scripted_input(
479:     mut commands: Commands,
480:     time: Res<Time>,
481:     player: Query<(), With<ClientPlayer>>,
482:     mut script: ResMut<ScriptedInput>,
483:     mut input_override: ResMut<PlayerInputOverride>,
484:     mut direct_controls: ResMut<DirectControlState>,
485:     mut force_attack: ResMut<DebugForceAttackTrigger>,
486:     mut pending_captures: ResMut<PendingDiagnosticCaptures>,
487:     mut status: ResMut<DiagnosticInputStatus>,
488:     mut exit: MessageWriter<AppExit>,
489: ) {
490:     if player.is_empty() {
491:         input_override.0 = None;
492:         return;
493:     }
494:     if !script.started {
495:         script.started = true;
496:         info!(
497:             commands = script.commands.len(),
498:             "Started scripted real-client input"
499:         );
500:     }
501: 
502:     let delta = time.delta_secs().max(0.0);
503:     loop {
504:         let Some(command) = script.commands.get(script.command_index).cloned() else {
505:             input_override.0 = Some(PlayerInputRequest {
506:                 look: script.look,
507:                 ..default()
508:             });
509:             let exit_after_script = script.exit_after_script;
510:             let elapsed = script.finished_elapsed.get_or_insert(0.0);
511:             *elapsed += delta;
512:             if exit_after_script && *elapsed >= 0.25 && pending_captures.0 == 0 {
513:                 info!("Scripted real-client input completed");
514:                 exit.write(AppExit::Success);
515:             }
516:             return;
517:         };
518: 
519:         if let ScriptCommand::Rotate { degrees_right } = &command {
520:             script.look.x = (script.look.x + degrees_right.to_radians() + std::f32::consts::PI)
521:                 .rem_euclid(std::f32::consts::TAU)
522:                 - std::f32::consts::PI;
523:             script.command_index += 1;
524:             script.command_elapsed = 0.0;
525:             continue;
526:         }
527: 
528:         if let ScriptCommand::Guard { raised } = command {
529:             script.weapon_guard = if raised {
530:                 WeaponGuardState::Raised
531:             } else {
532:                 WeaponGuardState::Lowered
533:             };
534:             script.command_index += 1;
535:             script.command_elapsed = 0.0;
536:             continue;
537:         }
538: 
539:         if let ScriptCommand::Pace { pace } = command {
540:             script.pace = pace;
541:             script.command_index += 1;
542:             script.command_elapsed = 0.0;
543:             continue;
544:         }
545: 
546:         if let ScriptCommand::Screenshot { path } = &command {
547:             let path = Path::new(path).to_path_buf();
548:             if let Some(parent) = path.parent()
549:                 && let Err(error) = std::fs::create_dir_all(parent)
550:             {
551:                 error!(path = %path.display(), ?error, "Failed to create diagnostic screenshot directory");
552:             } else {
553:                 pending_captures.0 += 1;
554:                 let capture_path = path.clone();
555:                 commands.spawn(Screenshot::primary_window()).observe(
556:                     move |captured: On<ScreenshotCaptured>,
557:                           mut pending: ResMut<PendingDiagnosticCaptures>| {
558:                         save_to_disk(&capture_path)(captured);
559:                         pending.0 = pending.0.saturating_sub(1);
560:                     },
561:                 );
562:                 info!(path = %path.display(), "Requested a scripted diagnostic screenshot");
563:             }
564:             script.command_index += 1;
565:             script.command_elapsed = 0.0;
566:             continue;
567:         }
568: 
569:         if let ScriptCommand::WaitForSignal { path } = &command {
570:             let request = PlayerInputRequest {
571:                 look: script.look,
572:                 weapon_guard: script.weapon_guard,
573:                 ..default()
574:             };
575:             input_override.0 = Some(request);
576:             *status = DiagnosticInputStatus {
577:                 command_index: script.command_index,
578:                 command_kind: "wait_for_signal".to_owned(),
579:                 command_elapsed_seconds: script.command_elapsed,
580:                 request,
581:             };
582:             if Path::new(path).is_file() {
583:                 script.command_index += 1;
584:                 script.command_elapsed = 0.0;
585:                 continue;
586:             }
587:             return;
588:         }
589: 
590:         let command_start = script.command_elapsed == 0.0;
591:         if command_start
592:             && let ScriptCommand::Move {
593:                 turn_degrees_right: Some(degrees_right),
594:                 ..
595:             } = &command
596:         {
597:             script.look.x = (script.look.x + degrees_right.to_radians() + std::f32::consts::PI)
598:                 .rem_euclid(std::f32::consts::TAU)
599:                 - std::f32::consts::PI;
600:         }
601:         if command_start
602:             && matches!(
603:                 &command,
604:                 ScriptCommand::Dive { .. }
605:                     | ScriptCommand::Slide { .. }
606:                     | ScriptCommand::TogglePosture { .. }
607:             )
608:         {
609:             script.posture_sequence = script.posture_sequence.wrapping_add(1);
610:         }
611:         if command_start && let ScriptCommand::Quickstep { direction, .. } = &command {
612:             script.jump_sequence = script.jump_sequence.wrapping_add(1);
613:             direct_controls.dodge_just_pressed = true;
614:             direct_controls.quickstep_direction = direction.vector();
615:         }
616:         if command_start && matches!(&command, ScriptCommand::Attack { .. }) {
617:             force_attack.0 = true;
618:         }
619:         let previous_command_elapsed = script.command_elapsed;
620:         script.command_elapsed += delta;
621:         let move_attack_due = matches!(
622:             &command,
623:             ScriptCommand::Move {
624:                 attack_at_seconds: Some(attack_at_seconds),
625:                 ..
626:             } if previous_command_elapsed <= *attack_at_seconds
627:                 && script.command_elapsed > *attack_at_seconds
628:         );
629:         let (kind, duration, movement, posture, jump) = match command {
630:             ScriptCommand::Move {
631:                 direction,
632:                 input_speed,
633:                 duration_seconds,
634:                 attack_at_seconds: _,
635:                 turn_degrees_right: _,
636:             } => (
637:                 "move",
638:                 duration_seconds,
639:                 Some(direction.vector() * input_speed),
640:                 PostureCommand::default(),
641:                 JumpCommand::default(),
642:             ),
643:             ScriptCommand::Dive {
644:                 direction,
645:                 duration_seconds,
646:             } => (
647:                 "dive",
648:                 duration_seconds,
649:                 Some(direction.vector()),
650:                 PostureCommand {
651:                     sequence: script.posture_sequence,
652:                     action: Some(PostureActionRequest::Dive {
653:                         animation_direction: direction.dive_direction(),
654:                         travel_direction: direction.dive_direction(),
655:                     }),
656:                 },
657:                 JumpCommand::default(),
658:             ),
659:             ScriptCommand::Slide {
660:                 direction,
661:                 duration_seconds,
662:             } => (
663:                 "slide",
664:                 duration_seconds,
665:                 Some(direction.vector()),
666:                 PostureCommand {
667:                     sequence: script.posture_sequence,
668:                     action: Some(PostureActionRequest::Dive {
669:                         animation_direction: direction.dive_direction().opposite(),
670:                         travel_direction: direction.dive_direction(),
671:                     }),
672:                 },
673:                 JumpCommand::default(),
674:             ),
675:             ScriptCommand::Quickstep {
676:                 direction,
677:                 duration_seconds,
678:             } => (
679:                 "quickstep",
680:                 duration_seconds,
681:                 Some(direction.vector()),
682:                 PostureCommand::default(),
683:                 JumpCommand {
684:                     sequence: script.jump_sequence,
685:                     quickstep: Some(direction.vector()),
686:                 },
687:             ),
688:             ScriptCommand::TogglePosture { duration_seconds } => (
689:                 "toggle_posture",
690:                 duration_seconds,

