488: /// not asset-root files at all.
489: fn validate_native_presentation_assets(asset_root: &std::path::Path) -> Result<(), String> {
490:     // Only filesystem assets belong here; ProceduralMaterialsPlugin embeds its shaders.
491:     const REQUIRED_ASSETS: &[&str] = &[
492:         "shaders/tactical_foliage.wgsl",
493:         "shaders/tactical_clouds.wgsl",
494:         "shaders/tactical_moon.wgsl",
495:         "shaders/tactical_stars.wgsl",
496:         "shaders/tactical_terrain.wgsl",
497:         "shaders/tactical_weather.wgsl",
498:         "shaders/tactical_tree_impostor.wgsl",
499:         "tactical-equipment-icons.png",
500:         "textures/moon/lroc_color_2k.jpg",
501:     ];
502:     let missing = REQUIRED_ASSETS
503:         .iter()
504:         .filter(|path| !asset_root.join(path).is_file())
505:         .copied()
506:         .collect::<Vec<_>>();
507:     if missing.is_empty() {
508:         Ok(())
509:     } else {
510:         Err(format!(
511:             "{} is missing required presentation assets: {}",
512:             asset_root.display(),
513:             missing.join(", ")
514:         ))
515:     }
516: }
