68: fn update_wind_volume(
69:     environments: Query<&SceneEnvironment>,
70:     mut wind: Query<&mut AudioSink, With<TacticalWindAudio>>,
71:     config: Res<TacticalAudioConfig>,
72: ) {
73:     let Some(environment) = environments.iter().next() else {
74:         return;
75:     };
76:     let wind_speed = UnitBasisPoints::saturating(environment.weather.wind_speed_bps).as_unit_f32();
77:     let audible_threshold =
78:         UnitBasisPoints::saturating(config.movement.wind.minimum_audible_speed_bps).as_unit_f32();
79:     let wind_fraction =
80:         ((wind_speed - audible_threshold) / (1.0 - audible_threshold)).clamp(0.0, 1.0);
81:     let volume = config.movement.wind.maximum_relative_volume
82:         * wind_fraction.powf(config.movement.wind.response_exponent);
83:     for mut sink in &mut wind {
84:         sink.set_volume(Volume::Linear(volume));
85:     }
86: }
