88: fn play_locomotion_audio(
89:     mut commands: Commands,
90:     mut events: MessageReader<LocomotionPresentationEvent>,
91:     characters: Query<(&GlobalTransform, &SkeletonState, &CharacterId), With<Player>>,
92:     grounds: Query<&SceneGround>,
93:     understory: Query<(&GlobalTransform, &GroundScatterLayer)>,
94:     asset_server: Res<AssetServer>,
95:     config: Res<TacticalAudioConfig>,
96: ) {
97:     let ground = grounds.iter().next();
98:     for event in events.read() {
99:         let Ok((transform, skeleton, character_id)) = characters.get(event.owner) else {
100:             continue;
101:         };
102:         let position = match Position::<Scene>::from_metres(transform.translation()) {
103:             Ok(position) => position,
104:             Err(error) => {
105:                 warn!(%error, owner = ?event.owner, "Invalid movement audio position");
106:                 continue;
107:             }
108:         };
109:         let event_seed = StreamId::new("audio.locomotion-event")
110:             .seed((character_id.0).into(), &[event.payload.encoded_sequence()]);
111:         match event.payload {
112:             LocomotionPresentationPayload::Contact { .. } => {
113:                 let surface =
114:                     ground.and_then(|ground| ground.ground_at(ScenePlanPoint::from(position)));
115:                 let on_grass = surface.is_some_and(|surface| {
116:                     matches!(surface.cover, GroundCover::TallGrass | GroundCover::Reeds)
117:                 });
118:                 let family = if on_grass {
119:                     "footstep_grass_00"
120:                 } else {
121:                     "footstep_concrete_00"
122:                 };
123:                 spawn_spatial_variant(
124:                     &mut commands,
125:                     &asset_server,
126:                     family,
127:                     event_seed,
128:                     position,
129:                     config.movement.footstep_relative_volume,
130:                     config.movement.pitch_randomization,
131:                 );
132:                 if on_grass {
133:                     spawn_rustle(
134:                         &mut commands,
135:                         &asset_server,
136:                         event_seed,
137:                         position,
138:                         config.movement.tall_grass_rustle_relative_volume,
139:                         config.movement.tall_grass_rustle_pitch,
140:                         config.movement.pitch_randomization,
141:                     );
142:                 }
143:                 if near_understory(position, &understory, config.movement.bush_contact_radius_m) {
144:                     spawn_rustle(
145:                         &mut commands,
146:                         &asset_server,
147:                         StreamId::new("audio.understory-rustle").seed(event_seed, &[]),
148:                         position,
149:                         config.movement.bush_rustle_relative_volume,
150:                         config.movement.bush_rustle_pitch,
151:                         config.movement.pitch_randomization,
152:                     );
153:                 }
154:             }
155:             LocomotionPresentationPayload::Landing { .. }
156:                 if matches!(
157:                     skeleton
158:                         .posture_transition()
159:                         .map(|transition| transition.kind()),
160:                     Some(PostureTransitionKind::DiveToDowned { .. })
161:                 ) =>
162:             {
163:                 spawn_spatial_variant(
164:                     &mut commands,
165:                     &asset_server,
166:                     "impactSoft_heavy_00",
167:                     event_seed,
168:                     position,
169:                     config.movement.body_impact_relative_volume,
170:                     config.movement.pitch_randomization,
171:                 );
172:             }
173:             LocomotionPresentationPayload::Landing { .. } => {}
174:         }
175:     }
176: }
