178: fn play_grounded_dive_impacts(
179:     mut commands: Commands,
180:     mut characters: GroundedDiveAudioQuery,
181:     asset_server: Res<AssetServer>,
182:     config: Res<TacticalAudioConfig>,
183: ) {
184:     for (entity, character_id, transform, skeleton, state) in &mut characters {
185:         let grounded_dive_active = matches!(
186:             skeleton
187:                 .posture_transition()
188:                 .map(|transition| transition.kind()),
189:             Some(PostureTransitionKind::DiveToDowned {
190:                 trajectory: DiveTrajectory::GroundedSlide,
191:                 ..
192:             })
193:         );
194:         let was_active = state
195:             .as_deref()
196:             .is_some_and(|state| state.grounded_dive_active);
197:         if grounded_dive_active && !was_active {
198:             let position = match Position::<Scene>::from_metres(transform.translation()) {
199:                 Ok(position) => position,
200:                 Err(error) => {

201:                     warn!(%error, ?entity, "Invalid grounded dive audio position");
202:                     continue;
203:                 }
204:             };
205:             spawn_spatial_variant(
206:                 &mut commands,
207:                 &asset_server,
208:                 "impactSoft_heavy_00",
209:                 StreamId::new("audio.grounded-dive").seed(
210:                     (character_id.0).into(),
211:                     &[skeleton.locomotion_sample_tick.encoded()],
212:                 ),
213:                 position,
214:                 config.movement.body_impact_relative_volume,
215:                 config.movement.pitch_randomization,
216:             );
217:         }
218:         if let Some(mut state) = state {
219:             state.grounded_dive_active = grounded_dive_active;
220:         } else {
221:             commands.entity(entity).insert(MovementAudioState {
222:                 grounded_dive_active,
223:             });
224:         }
225:     }
226: }
