228: fn near_understory(
229:     position: Position<Scene>,
230:     scatter: &Query<(&GlobalTransform, &GroundScatterLayer)>,
231:     contact_radius_m: f32,
232: ) -> bool {
233:     scatter.iter().any(|(transform, layer)| {
234:         if *layer != GroundScatterLayer::Understory {
235:             return false;
236:         }
237:         let offset = transform.translation() - position.metres();
238:         offset.xz().length_squared() <= contact_radius_m.powi(2)
239:     })
240: }
