242: fn spawn_spatial_variant(
243:     commands: &mut Commands,
244:     asset_server: &AssetServer,
245:     family: &str,
246:     event_seed: Seed,
247:     position: Position<Scene>,
248:     volume: f32,
249:     pitch_randomization: [f32; 2],
250: ) {
251:     let sample =
252:         sound_seed(event_seed, position).child(StreamId::new("audio.family"), &[family.as_bytes()]);
253:     let variant = sample
254:         .child(StreamId::new("audio.variant"), &[])
255:         .rng()
256:         .index(3);
257:     let path = format!("audio/movement/{family}{variant}.ogg");
258:     spawn_spatial_sound(
259:         commands,
260:         asset_server.load(path),
261:         sample,
262:         position,
263:         volume,
264:         1.0,
265:         pitch_randomization,
266:     );
267: }
