269: fn spawn_rustle(
270:     commands: &mut Commands,
271:     asset_server: &AssetServer,
272:     event_seed: Seed,
273:     position: Position<Scene>,
274:     volume: f32,
275:     base_speed: f32,
276:     pitch_randomization: [f32; 2],
277: ) {
278:     let sample = sound_seed(event_seed, position);
279:     spawn_spatial_sound(
280:         commands,
281:         asset_server.load("audio/movement/foliage_rustle.ogg"),
282:         sample,
283:         position,
284:         volume,
285:         base_speed,
286:         pitch_randomization,
287:     );
288: }
289: 
290: fn spawn_spatial_sound(
291:     commands: &mut Commands,
292:     source: Handle<AudioSource>,
293:     sample: Seed,
294:     position: Position<Scene>,
295:     volume: f32,
296:     base_speed: f32,
297:     pitch_randomization: [f32; 2],
298: ) {
299:     let pitch_fraction = sample
300:         .child(StreamId::new("audio.pitch"), &[])
301:         .rng()
302:         .inclusive_unit_f32();
303:     let pitch =
304:         pitch_randomization[0] + pitch_fraction * (pitch_randomization[1] - pitch_randomization[0]);
305:     commands.spawn((
306:         Name::new("tactical-movement-sound"),
307:         AudioPlayer::new(source),
308:         PlaybackSettings {
309:             mode: PlaybackMode::Despawn,
310:             speed: base_speed * pitch,
311:             spatial: true,
312:             volume: Volume::Linear(volume),
313:             ..default()
314:         },
315:         Transform::from_translation(position.metres()),
316:     ));
317: }
318: 
319: fn sound_seed(event_seed: Seed, position: Position<Scene>) -> Seed {
320:     // Seed framing preserves the native scene position's three f32 bit patterns.
321:     let position = position.metres();
322:     StreamId::new("audio.spatial-event").seed(
323:         event_seed,
324:         &[
325:             u64::from(position.x.to_bits()),
326:             u64::from(position.y.to_bits()),
327:             u64::from(position.z.to_bits()),
328:         ],
329:     )
330: }
