304:                             |(_, _, _, impact_collider, _)| impact_collider.body == target,
305:                         );
306:                     let surface_distance = impact.distance;
307:                     let resolved_strike = if let Some(lunge_timing) = lunge_timing {
308:                         let maximum_travel = reach.1.min(horizontal_collider_clearance(
309:                             transform.translation,
310:                             collider,
311:                             body_transform,
312:                             body_collider,
313:                         ));
314:                         let surface_measure = (transform
315:                             .translation
316:                             .xz()
317:                             .distance(body_transform.translation.xz())
318:                             - adventuresim_core::combat::HUMANOID_MELEE_MINIMUM_CENTER_SEPARATION_METRES)
319:                             .max(0.0);
320:                         lunge_timing.contact_arrival(surface_measure, reach.0, maximum_travel)?
321:                             .map(|arrival| (position, arrival))
322:                     } else {
323:                         Some((position, MeleeLungeArrival::NotNeeded))
324:                     };
325:                     if !attack_target_within_angular_threshold(
326:                         camera_transform.forward().as_vec3(),
327:                         position - camera_transform.translation,
328:                         surface_distance,
329:                     ) {
330:                         return Ok(None);
331:                     }
332:                     Ok(visible.then_some(BodyStableChoice {
333:                         body: target,
334:                         resolved: resolved_strike.map(|(strike_point, arrival)| {
335:                             (
336:                                 AttackTarget {
337:                                     body: target,
338:                                     hitbox,
339:                                     body_part: limb.0,
340:                                     local_strike_point: target_transform
341:                                         .affine()
342:                                         .inverse()
343:                                         .transform_point3(strike_point),
344:                                     arrival,
345:                                 },
346:                                 strike_point,
347:                             )
348:                         }),
349:                         ideal_position: position,
350:                         stable_key: hitbox.to_bits(),
351:                     }))
352:                 },
353:             )
354:             .collect::<AnimationValueResult<Vec<_>>>()?
355:             .into_iter().flatten().collect();
356:         let selected = body_stable_auto_aim(
357:             camera_transform.translation,
358:             camera_transform.forward().as_vec3(),
359:             origin,
360:             if lunge_timing.is_some() {
361:                 f32::MAX
362:             } else {
363:                 reach.0
364:             },
365:             &choices,
366:         );
367:         Ok(match selected {
368:             Some((target, position)) => (Some(target), Some(position), camera_transform.forward()),
369:             None => (None, None, camera_transform.forward()),
370:         })
371:     }
372: }
