374: fn attack_origin(
375:     transform: &Transform,
376:     collider: &Collider,
377:     dimensions: CharacterDimensions,
378: ) -> Vec3 {
379:     let body_base = collider
380:         .aabb(transform.translation, Rotation(transform.rotation))
381:         .min
382:         .y;
383:     transform
384:         .translation
385:         .with_y(body_base + dimensions.body_height_metres * (2.0 / 3.0))
386: }
387: 
388: fn horizontal_collider_clearance(
389:     attacker: Vec3,
390:     attacker_collider: &Collider,
391:     target_transform: &Transform,
392:     target_collider: &Collider,
393: ) -> f32 {
394:     let attacker_bounds = attacker_collider.aabb(attacker, Rotation::default());
395:     let target_bounds = target_collider.aabb(
396:         target_transform.translation,
397:         Rotation(target_transform.rotation),
398:     );
399:     let attacker_radius = ((attacker_bounds.max - attacker_bounds.min) * 0.5)
400:         .xz()
401:         .max_element();
402:     let target_radius = ((target_bounds.max - target_bounds.min) * 0.5)
403:         .xz()
404:         .max_element();
405:     (attacker.xz().distance(target_transform.translation.xz()) - attacker_radius - target_radius)
406:         .max(0.0)
407: }
408: 
409: fn attack_target_angular_threshold_degrees(surface_distance_metres: f32) -> f32 {
410:     90.0 / surface_distance_metres.max(0.5)
411: }
412: 
413: fn attack_target_within_angular_threshold(
414:     camera_forward: Vec3,
415:     direction_to_candidate: Vec3,
416:     surface_distance_metres: f32,
417: ) -> bool {
418:     let Some(camera_forward) = camera_forward.try_normalize() else {
419:         return false;
420:     };
421:     let Some(direction) = direction_to_candidate.try_normalize() else {
422:         return false;
423:     };
424:     let threshold = attack_target_angular_threshold_degrees(surface_distance_metres).to_radians();
425:     camera_forward.dot(direction).clamp(-1.0, 1.0) >= threshold.cos()
426: }
