584: fn update_attack_state_system(
585:     mut cmd: Commands,
586:     spatial: SpatialQuery,
587:     time: Res<Time>,
588:     mut q_attacker: Query<(
589:         Entity,
590:         &Transform,
591:         &Collider,
592:         &CharacterDimensions,
593:         &mut AttackState,
594:     )>,
595:     q_collider: Query<(&GlobalTransform, &ColliderOf, &LimbHitbox)>,
596:     q_scene_items: Query<Entity, With<TacticalSceneItem>>,
597:     combat_config: Res<TacticalCombatConfig>,
598: ) {
599:     for (attacker, attacker_transform, attacker_collider, dimensions, mut state) in &mut q_attacker
600:     {
601:         if let Some(target) = state.target
602:             && let Ok((transform, _, _)) = q_collider.get(target.hitbox)
603:         {
604:             state.target_position = Some(transform.transform_point(target.local_strike_point));
605:         }
606:         state.pre_hit_timer.tick(time.delta());
607:         state.facing_timer.tick(time.delta());
608:         if !state.pre_hit_timer.is_finished() {
609:             continue;
610:         }
611: 
612:         cmd.entity(attacker).remove::<AttackState>();
613:         let reach = if state.ranged {
614:             state.reach
615:         } else {
616:             melee_interaction_range(dimensions.arm_reach_metres, state.reach)
617:         };
618:         let origin = attack_origin(attacker_transform, attacker_collider, *dimensions);
619:         let Some(target) = state.target else {
620:             if state.ranged {
621:                 cmd.client_trigger(RangedActionRequest::CompleteMiss);
622:             }
623:             cmd.trigger(HitPerformed {
624:                 entity: attacker,
625:                 direction: state.aim_direction,
626:                 origin,
627:                 length: reach,
628:             });
629:             continue;
630:         };
631:         let intended_point = state
632:             .target_position
633:             .unwrap_or(origin + *state.aim_direction * reach);
634:         let delta = intended_point - origin;
635:         let direction = Dir3::new(delta).unwrap_or(state.aim_direction);
636:         let excluded: Vec<_> = q_scene_items.iter().chain([attacker]).collect();
637:         let obstruction_filter = SpatialQueryFilter::from_excluded_entities(excluded);
638:         let obstruction = spatial.cast_ray(
639:             origin,
640:             direction,
641:             delta.length().min(reach),
642:             true,
643:             &obstruction_filter,
644:         );
645:         let unobstructed = obstruction.is_some_and(|hit| {
646:             hit.entity == target.body
647:                 || q_collider
648:                     .get(hit.entity)
649:                     .is_ok_and(|(_, collider, _)| collider.body == target.body)
650:         });
651: 
652:         if unobstructed {
653:             if state.ranged {
654:                 cmd.client_trigger(RangedActionRequest::CompleteHit {
655:                     target: target.body,
656:                     body_part: target.body_part,
657:                     reported_precision: combat_config.targeting.reported_hit_precision,
658:                 });
659:             }
660:             cmd.trigger(HitPerformed {
661:                 entity: attacker,
662:                 direction,
663:                 origin,
664:                 length: obstruction.map_or(delta.length(), |hit| hit.distance),
665:             });
666:         } else {
667:             if state.ranged {
668:                 cmd.client_trigger(RangedActionRequest::CompleteMiss);
669:             }
670:             cmd.trigger(HitPerformed {
671:                 entity: attacker,
672:                 direction,
673:                 origin,
674:                 length: obstruction.map_or(delta.length().min(reach), |hit| hit.distance),
675:             });
676:         }
677:     }
678: }
