687: fn attack_reach_is_usable(ranged: bool, melee: bool, weapon_reach: f32, arm_reach: f32) -> bool {
688:     if ranged {
689:         weapon_reach.is_finite() && weapon_reach > 0.0
690:     } else {
691:         melee && arm_reach.is_finite() && arm_reach > 0.0
692:     }
