695: #[expect(
696:     clippy::too_many_arguments,
697:     reason = "Bevy injects direct controls, player queries, combat resources, and targeting state independently"
698: )]
699: fn apply_direct_combat_controls(
700:     controls: Res<DirectControlState>,
701:     mut cmd: Commands,
702:     players: Query<Entity, With<ControlledPlayer>>,
703:     mut q_character: Query<(Has<AttackState>, &mut SkeletonState)>,
704:     viewer: TacticalPlayerViewer,
705:     time: Res<Time>,
706:     combat_config: Res<TacticalCombatConfig>,
707:     targeting: CombatTargeting,
708: ) {
709:     for entity in &players {
710:         if let Ok((_, mut skeleton)) = q_character.get_mut(entity)
711:             && let Ok(view) = viewer.get_for_attack(entity, AttackHand::Main)
712:         {
713:             let preferred = StrikeFamily::from_melee_style(view.weapon_preferred_melee_style());
714:             let resolve = |input: MeleePreparationInput| match input {
715:                 MeleePreparationInput::Preferred => AttackAnimation::initial(
716:                     skeleton
717:                         .available_strike_family(preferred)
718:                         .unwrap_or(preferred),
719:                 ),
720:                 MeleePreparationInput::Alternate => AttackAnimation::initial(

721:                     skeleton
722:                         .available_strike_family(preferred.alternate())
723:                         .unwrap_or(preferred),
724:                 ),
725:                 MeleePreparationInput::Offhand
726:                     if skeleton.attack_animations.offhand_preparation =>
727:                 {
728:                     AttackAnimation::Offhand
729:                 }
730:                 MeleePreparationInput::Offhand => AttackAnimation::initial(
731:                     skeleton
732:                         .available_strike_family(preferred)
733:                         .unwrap_or(preferred),
734:                 ),
735:             };
736:             let from = resolve(controls.local_preparation_from);
737:             let to = resolve(controls.local_preparation_to);
738:             skeleton.set_attack_preparation(AttackPreparation {
739:                 from,
740:                 to,
741:                 progress: controls.local_preparation_progress,
742:             });
743:         }
744:         if controls.attack_just_pressed
745:             && let Err(error) = try_start_attack(
746:                 AttackStartRequest {
747:                     entity,
748:                     alternate_attack: controls.alternate_attack,
749:                     hand: controls.attack_hand,
750:                 },
751:                 &mut cmd,
752:                 &mut q_character,
753:                 &viewer,
754:                 &time,
755:                 &combat_config,
756:                 &targeting,
757:             )
758:         {
759:             warn!(?entity, %error, "cannot schedule attack");
760:         }
761:         // Quicksteps travel on the sequenced PlayerInputRequest stream. Do not
762:         // predict only the SkeletonState here: the client does not simulate the
763:         // matching QuickstepPush, so an authoritative rejection would otherwise
764:         // animate a dodge over a stationary replicated transform.
765:         if controls.roll_just_pressed {
766:             cmd.client_trigger(DefendRequest::Roll);
767:         }
768:     }
769: }
