1: //! Native combat seconds and the client prediction sample clock.
2: 
3: use super::*;
4: use adventuresim_core::linear_speed::NonnegativeSpeed;
5: use adventuresim_tactical_core::animation::{
6:     AnimationElapsed, AnimationValueResult, PositiveAnimationDuration,
7: };
8: 
9: /// Timing available only to melee surface-range acquisition. Ranged targeting
10: /// has no movement-assisted timing input.
11: #[derive(Clone, Copy)]
12: pub(super) struct MeleeAcquisitionTiming {
13:     forward_speed: NonnegativeSpeed,
14:     acceleration: ForwardLungeAcceleration,
15:     quickstep_duration: PositiveAnimationDuration,
16: }
17: 
18: #[derive(Clone, Copy)]
19: pub(super) struct MeleePlaybackTiming {
20:     pub(super) start: AnimationSampleTick,
21:     pub(super) contact: AnimationSampleTick,
22:     pub(super) end: AnimationSampleTick,
23:     /// Native seconds consumed by the predicted AttackState timers.
24:     pub(super) contact_from_input_seconds: AnimationElapsed,
25: }
26: 
27: impl TryFrom<&adventuresim_tactical_core::combat_config::TacticalMovementConfig>
28:     for MeleeAcquisitionTiming
29: {
30:     type Error = adventuresim_tactical_core::animation::AnimationValueError;
31: 
32:     fn try_from(
33:         movement: &adventuresim_tactical_core::combat_config::TacticalMovementConfig,
34:     ) -> AnimationValueResult<Self> {
35:         Ok(Self {
36:             forward_speed: movement.speeds_metres_per_second.run,
37:             acceleration: conservative_forward_lunge_acceleration(&movement.motor)?,
38:             quickstep_duration: movement.maneuvers.quickstep_duration_seconds,
39:         })
40:     }
41: }
42: 
43: impl MeleeAcquisitionTiming {
44:     /// A reachable melee surface target owns its movement-assisted delay.
45:     pub(super) fn contact_arrival(
46:         self,
47:         surface_measure: f32,
48:         reach: f32,
49:         maximum_travel: f32,
50:     ) -> AnimationValueResult<Option<MeleeLungeArrival>> {
51:         let closure = (surface_measure - reach).max(0.0);
52:         if closure > maximum_travel + 1.0e-5 {
53:             return Ok(None);
54:         }
55:         let arrival = melee_lunge_arrival(
56:             melee_lunge(surface_measure, reach, 0.0, maximum_travel),
57:             self.forward_speed,
58:             self.acceleration,
59:             self.quickstep_duration,
60:         )?;
61:         Ok(match arrival {
62:             MeleeLungeArrival::CannotArrive => None,
63:             admitted => Some(admitted),
64:         })
65:     }
66: }
67: 
68: impl MeleePlaybackTiming {
69:     pub(super) fn delayed(
70:         skeleton: &SkeletonState,
71:         spec: &AttackSpec,
72:         input: AnimationSampleTick,
73:         delay: AnimationElapsed,
74:         contact_seconds: AnimationElapsed,
75:         recovery: AnimationElapsed,
76:     ) -> AnimationValueResult<Self> {
77:         let sequence_start = if spec.continuation {
78:             skeleton.attack_continuation_tick().unwrap_or(input)
79:         } else {
80:             input
81:         };
82:         let start = sequence_start.saturating_add(delay_ticks(delay)?);
83:         let contact = sequence_start.saturating_add(animation_ticks(contact_seconds)?);
84:         let end =
85:             sequence_start.saturating_add(animation_ticks(contact_seconds.checked_add(recovery)?)?);
86:         let contact_from_input_seconds =
87:             melee_contact_delay_from_input(skeleton, spec.continuation, contact, contact_seconds)?;
88:         Ok(Self {
89:             start,
90:             contact,
91:             end,
92:             contact_from_input_seconds,
93:         })
94:     }
95: }
96: pub(super) fn on_attack_fired_hook(
97:     event: On<Fire<Attack>>,
98:     mut cmd: Commands,
99:     mut q_character: Query<(Has<AttackState>, &mut SkeletonState)>,
100:     viewer: TacticalPlayerViewer,
101:     time: Res<Time>,
102:     combat_config: Res<TacticalCombatConfig>,
103:     targeting: CombatTargeting,
104: ) {
105:     if let Err(error) = try_start_attack(
106:         AttackStartRequest {
107:             entity: event.context,
108:             alternate_attack: false,
109:             hand: AttackHand::Main,
110:         },
111:         &mut cmd,
112:         &mut q_character,
113:         &viewer,
114:         &time,
115:         &combat_config,
116:         &targeting,
117:     ) {
118:         warn!(%error, "cannot schedule attack");
119:     }
120: }
121: 
122: pub(super) fn animation_ticks(
123:     seconds: AnimationElapsed,
124: ) -> AnimationValueResult<AnimationSampleSpan> {
125:     let samples = seconds
126:         .seconds()
127:         .max(locomotion_sample_rate().interval().seconds())
128:         * locomotion_sample_rate().hertz();
129:     rounded_samples(samples)
130: }
131: 
132: pub(super) fn delay_ticks(seconds: AnimationElapsed) -> AnimationValueResult<AnimationSampleSpan> {
133:     rounded_samples(seconds.seconds().max(0.0) * locomotion_sample_rate().hertz())
134: }
135: 
136: fn rounded_samples(samples: f32) -> AnimationValueResult<AnimationSampleSpan> {
137:     if !samples.is_finite() {
138:         return Err(
139:             adventuresim_tactical_core::animation::AnimationValueError::Overflow {
140:                 quantity: adventuresim_tactical_core::animation::AnimationQuantity::Elapsed,
141:             },
142:         );
143:     }
144:     // Finite values retain Rust's saturating integer conversion at this native
145:     // sample-count boundary; overflow of the seconds product is not a deadline.
146:     Ok(AnimationSampleSpan::from(samples.round() as u64))
147: }
148: 
149: pub(super) fn melee_contact_delay_from_input(
150:     skeleton: &SkeletonState,
151:     continuation: bool,
152:     contact_tick: AnimationSampleTick,
153:     ordinary_contact_seconds: AnimationElapsed,
154: ) -> AnimationValueResult<AnimationElapsed> {
155:     if continuation {
156:         Ok(AnimationElapsed::from_seconds(
157:             contact_tick
158:                 .saturating_sub(skeleton.locomotion_sample_tick)
159:                 .samples() as f32
160:                 / locomotion_sample_rate().hertz(),
161:         )?)
162:     } else {
163:         Ok(ordinary_contact_seconds)
164:     }
165: }
166: 
167: #[cfg(test)]
168: mod tests {
169:     use super::melee_contact_delay_from_input;
170:     use adventuresim_tactical_core::animation::{AnimationSampleTick, SkeletonState};
171: 
172:     #[test]
173:     fn continuation_cooldown_uses_the_replicated_animation_clock() {
174:         let skeleton = SkeletonState::default().with_locomotion_sample_tick(
175:             adventuresim_tactical_core::animation::AnimationSampleTick::from(700u64),
176:         );
177: 
178:         assert_eq!(
179:             melee_contact_delay_from_input(
180:                 &skeleton,
181:                 true,
182:                 AnimationSampleTick::from(732u64),
183:                 adventuresim_core::elapsed::AnimationElapsed::from_seconds(0.3).unwrap()
184:             )
185:             .unwrap()
186:             .seconds(),
187:             0.5
188:         );
189:         assert_eq!(
190:             melee_contact_delay_from_input(
191:                 &skeleton,
192:                 false,
193:                 AnimationSampleTick::from(732u64),
194:                 adventuresim_core::elapsed::AnimationElapsed::from_seconds(0.3).unwrap()
195:             )
196:             .unwrap()
197:             .seconds(),
198:             0.3
199:         );
200:     }
201: }
