1: //! Predicted attack admission, buffering and publication.
2: 
3: use super::*;
4: 
5: struct AttackWeaponFacts {
6:     reach: f32,
7:     ranged: bool,
8:     melee: bool,
9:     windup: adventuresim_core::elapsed::ElapsedResult<AnimationElapsed>,
10:     recovery: adventuresim_core::elapsed::ElapsedResult<AnimationElapsed>,
11:     curve: adventuresim_tactical_core::animation::AttackCurve,
12:     preferred_style: MeleeAttackStyle,
13: }
14: 
15: struct SelectedMeleeAttack {
16:     entity: Entity,
17:     hand: AttackHand,
18:     family: StrikeFamily,
19:     spec: AttackSpec,
20:     start: AnimationSampleTick,
21:     reach: f32,
22: }
23: 
24: struct PreparedMeleeAttack {
25:     spec: AttackSpec,
26:     timing: MeleePlaybackTiming,
27:     attack_state: AttackState,
28:     target: Option<AttackTarget>,
29: }
30: 
31: struct PredictedRangedAttack {
32:     entity: Entity,
33:     reach: f32,
34:     windup: AnimationElapsed,
35:     recovery: AnimationElapsed,
36:     curve: adventuresim_tactical_core::animation::AttackCurve,
37:     start: AnimationSampleTick,
38: }
39: 
40: struct ImmediateMeleeAttack {
41:     entity: Entity,
42:     hand: AttackHand,
43:     alternate_attack: bool,
44:     attacking: bool,
45:     reach: f32,
46:     preferred_style: MeleeAttackStyle,
47:     start: AnimationSampleTick,
48: }
49: 
50: impl AttackWeaponFacts {
51:     fn observe(
52:         viewer: &TacticalPlayerViewer,
53:         entity: Entity,
54:         hand: AttackHand,
55:         config: &TacticalCombatConfig,
56:     ) -> Option<Self> {
57:         viewer
58:             .get_for_attack(entity, hand)
59:             .ok()
60:             .map(|character| Self {
61:                 reach: character.weapon_reach(),
62:                 ranged: hand == AttackHand::Main && character.weapon_is_ranged(),
63:                 melee: character.weapon_is_melee(),
64:                 windup: character.weapon_ranged_windup_secs(),
65:                 recovery: attack_recovery_secs(
66:                     &character,
67:                     character.weapon_preferred_melee_style(),
68:                     false,
69:                 ),
70:                 curve: configure_attack_curve(
71:                     AttackSpec::default(),
72:                     &character,
73:                     &config.presentation.attack_curve,
74:                 )
75:                 .curve,
76:                 preferred_style: character.weapon_preferred_melee_style(),
77:             })
78:     }
79: }
80: 
81: impl PreparedMeleeAttack {
82:     fn admit(
83:         request: SelectedMeleeAttack,
84:         skeleton: &SkeletonState,
85:         viewer: &TacticalPlayerViewer,
86:         targeting: &CombatTargeting,
87:         config: &TacticalCombatConfig,
88:     ) -> AnimationValueResult<Option<Self>> {
89:         let Ok(character) = viewer.get_for_attack(request.entity, request.hand) else {
90:             return Ok(None);
91:         };
92:         let style = request.family.melee_style();
93:         let windup = attack_preparation_secs(&character, style)?;
94:         let recovery = attack_recovery_secs(&character, style, request.spec.continuation)?;
95:         let spec = AttackSpec {
96:             curve: configure_attack_curve(
97:                 AttackSpec::default(),
98:                 &character,
99:                 &config.presentation.attack_curve,
100:             )
101:             .curve,
102:             ..request.spec
103:         };
104:         Self::prepare(
105:             SelectedMeleeAttack { spec, ..request },
106:             skeleton,
107:             targeting,
108:             config,
109:             windup,
110:             recovery,
111:         )
112:         .map(Some)
113:     }
114: 
115:     fn prepare(
116:         request: SelectedMeleeAttack,
117:         skeleton: &SkeletonState,
118:         targeting: &CombatTargeting,
119:         config: &TacticalCombatConfig,
120:         windup: AnimationElapsed,
121:         recovery: AnimationElapsed,
122:     ) -> AnimationValueResult<Self> {
123:         let range = targeting.melee_acquisition_range(request.entity, request.reach, config);
124:         let (target, position, direction) = targeting.acquire(
125:             request.entity,
126:             range,
127:             Some(MeleeAcquisitionTiming::try_from(&config.movement)?),
128:         )?;
129:         let arrival = target.map_or(MeleeLungeArrival::NotNeeded, |target| target.arrival);
130:         let contact = arrival.contact_timing(windup)?;
131:         let timing = MeleePlaybackTiming::delayed(
132:             skeleton,
133:             &request.spec,
134:             request.start,
135:             contact.delay,
136:             contact.contact,
137:             recovery,
138:         )?;
139:         let attack_state = AttackState::new(
140:             timing.contact_from_input_seconds,
141:             timing.contact_from_input_seconds,
142:             request.reach,
143:             false,
144:             target,
145:             position,
146:             direction,
147:         )?;
148:         Ok(Self {
149:             spec: request.spec,
150:             timing,
151:             attack_state,
152:             target,
153:         })
154:     }
155: }
156: 
157: impl PredictedRangedAttack {
158:     fn start(
159:         self,
160:         cmd: &mut Commands,
161:         skeleton: &mut SkeletonState,
162:         targeting: &CombatTargeting,
163:     ) -> AnimationValueResult<()> {
164:         let Self {
165:             entity,
166:             reach,
167:             windup,
168:             recovery,
169:             curve,
170:             start,
171:         } = self;
172:         let spec = AttackSpec { curve, ..default() };
173:         let (target, position, direction) = targeting.acquire(entity, (reach, 0.0), None)?;
174:         let attack_state =
175:             AttackState::new(windup, windup, reach, true, target, position, direction)?;
176:         let contact = start.saturating_add(animation_ticks(windup)?);
177:         let end = start.saturating_add(animation_ticks(windup.checked_add(recovery)?)?);
178:         if skeleton
179:             .begin_attack_timed(spec, start, contact, end)
180:             .is_err()
181:         {
182:             return Ok(());
183:         }
184:         cmd.entity(entity).insert(attack_state);
185:         cmd.client_trigger(RangedActionRequest::Start {
186:             target: target.map(|target| target.body),
187:         });
188:         Ok(())
189:     }
190: }
191: 
192: impl ImmediateMeleeAttack {
193:     fn start(
194:         self,
195:         cmd: &mut Commands,
196:         skeleton: &mut SkeletonState,
197:         viewer: &TacticalPlayerViewer,
198:         targeting: &CombatTargeting,
199:         combat_config: &TacticalCombatConfig,
200:     ) -> AnimationValueResult<()> {
201:         let Self {
202:             entity,
203:             hand,
204:             alternate_attack,
205:             attacking,
206:             reach,
207:             preferred_style,
208:             start,
209:         } = self;
210:         let preferred_family = StrikeFamily::from_melee_style(preferred_style);
211:         let requested_family = if alternate_attack && hand == AttackHand::Main {
212:             preferred_family.alternate()
213:         } else {
214:             preferred_family
215:         };
216:         let Some(strike_family) = skeleton.available_strike_family(requested_family) else {
217:             return Ok(());
218:         };
219:         let Some(spec) = (!attacking)
220:             .then(|| match hand {
221:                 AttackHand::Main => skeleton.select_main_attack(strike_family),
222:                 AttackHand::Offhand => skeleton.select_offhand_attack(strike_family),
223:             })
224:             .flatten()
225:         else {
226:             cmd.entity(entity).insert(BufferedMeleeAttack {
227:                 family: strike_family,
228:                 hand,
229:             });
230:             return Ok(());

231:         };
232:         let Some(prepared) = PreparedMeleeAttack::admit(
233:             SelectedMeleeAttack {
234:                 entity,
235:                 hand,
236:                 family: strike_family,
237:                 spec,
238:                 start,
239:                 reach,
240:             },
241:             skeleton,
242:             viewer,
243:             targeting,
244:             combat_config,
245:         )?
246:         else {
247:             return Ok(());
248:         };
249:         let PreparedMeleeAttack {
250:             spec,
251:             timing,
252:             attack_state,
253:             target,
254:         } = prepared;
255:         match skeleton.begin_attack_timed(spec, timing.start, timing.contact, timing.end) {
256:             Ok(()) => {}
257:             Err(ActionTransitionError::InvalidAnimationValue(error)) => return Err(error),
258:             Err(ActionTransitionError::ActionBusy) => {
259:                 cmd.entity(entity).insert(BufferedMeleeAttack {
260:                     family: strike_family,
261:                     hand,
262:                 });
263:                 return Ok(());
264:             }
265:             Err(ActionTransitionError::Downed | ActionTransitionError::PostureTransitionActive) => {
266:                 return Ok(());
267:             }
268:         }
269:         cmd.entity(entity)
270:             .insert(attack_state)
271:             .remove::<BufferedMeleeAttack>();
272:         cmd.client_trigger(MeleeActionRequest {
273:             strike_family,
274:             hand,
275:             target: target.map(|target| target.body),
276:         });
277:         Ok(())
278:     }
279: }
280: 
281: pub(super) fn try_start_attack(
282:     request: AttackStartRequest,
283:     cmd: &mut Commands,
284:     q_character: &mut Query<(Has<AttackState>, &mut SkeletonState)>,
285:     viewer: &TacticalPlayerViewer,
286:     time: &Time,
287:     combat_config: &TacticalCombatConfig,
288:     targeting: &CombatTargeting,
289: ) -> AnimationValueResult<()> {
290:     let AttackStartRequest {
291:         entity,
292:         alternate_attack,
293:         hand,
294:     } = request;
295:     let Ok((attacking, mut skeleton)) = q_character.get_mut(entity) else {
296:         return Ok(());
297:     };
298:     let Some(weapon) = AttackWeaponFacts::observe(viewer, entity, hand, combat_config) else {
299:         warn!("Trying to attack, but can't get weapon reach. Not holding any weapons ?");
300:         return Ok(());
301:     };
302:     let AttackWeaponFacts {
303:         reach,
304:         ranged,
305:         melee,
306:         windup: windup_secs,
307:         recovery: recovery_secs,
308:         curve,
309:         preferred_style,
310:     } = weapon;
311: 
312:     let arm_reach = targeting.arm_reach(entity);
313:     if !attack_reach_is_usable(ranged, melee, reach, arm_reach) {
314:         warn!("Trying to attack without a usable equipped weapon");
315:         return Ok(());
316:     }
317:     if targeting
318:         .combatants
319:         .get(entity)
320:         .is_ok_and(|(_, state, _, _)| state.is_incapacitated())
321:     {
322:         return Ok(());
323:     }
324:     let windup_secs = windup_secs?;
325:     let recovery_secs = recovery_secs?;
326:     let start = AnimationSampleTick::from(
327:         (time.elapsed_secs_f64() * locomotion_sample_rate().hertz() as f64).round() as u64,
328:     );
329:     if ranged {
330:         if attacking {
331:             return Ok(());
332:         }
333:         PredictedRangedAttack {
334:             entity,
335:             reach,
336:             windup: windup_secs,
337:             recovery: recovery_secs,
338:             curve,
339:             start,
340:         }
341:         .start(cmd, &mut skeleton, targeting)?;
342:     } else {
343:         ImmediateMeleeAttack {
344:             entity,
345:             hand,
346:             alternate_attack,
347:             attacking,
348:             reach,
349:             preferred_style,
350:             start,
351:         }
352:         .start(cmd, &mut skeleton, viewer, targeting, combat_config)?;
353:     }
354:     Ok(())
355: }
356: 
357: pub(super) fn flush_buffered_melee_attacks(
358:     mut cmd: Commands,
359:     mut characters: Query<
360:         (Entity, &BufferedMeleeAttack, &mut SkeletonState),
361:         With<ControlledPlayer>,
362:     >,
363:     viewer: TacticalPlayerViewer,
364:     time: Res<Time>,
365:     combat_config: Res<TacticalCombatConfig>,
366:     targeting: CombatTargeting,
367: ) {
368:     for (entity, buffered, mut skeleton) in &mut characters {
369:         let attempt = (|| -> AnimationValueResult<()> {
370:             let Some(spec) = (match buffered.hand {
371:                 AttackHand::Main => skeleton.select_main_attack(buffered.family),
372:                 AttackHand::Offhand => skeleton.select_offhand_attack(buffered.family),
373:             }) else {
374:                 return Ok(());
375:             };
376:             let Ok((reach, melee, windup_secs, recovery_secs, curve)) = viewer
377:                 .get_for_attack(entity, buffered.hand)
378:                 .map(|character| {
379:                     (
380:                         character.weapon_reach(),
381:                         character.weapon_is_melee(),
382:                         attack_preparation_secs(&character, buffered.family.melee_style()),
383:                         attack_recovery_secs(
384:                             &character,
385:                             buffered.family.melee_style(),
386:                             spec.continuation,
387:                         ),
388:                         configure_attack_curve(
389:                             AttackSpec::default(),
390:                             &character,
391:                             &combat_config.presentation.attack_curve,
392:                         )
393:                         .curve,
394:                     )
395:                 })
396:             else {
397:                 return Ok(());
398:             };
399:             if !attack_reach_is_usable(false, melee, reach, targeting.arm_reach(entity)) {
400:                 return Ok(());
401:             }
402:             if targeting
403:                 .combatants
404:                 .get(entity)
405:                 .is_ok_and(|(_, state, _, _)| state.is_incapacitated())
406:             {
407:                 return Ok(());
408:             }
409:             let start = AnimationSampleTick::from(
410:                 (time.elapsed_secs_f64() * locomotion_sample_rate().hertz() as f64).round() as u64,
411:             );
412:             let prepared = PreparedMeleeAttack::prepare(
413:                 SelectedMeleeAttack {
414:                     entity,
415:                     hand: buffered.hand,
416:                     family: buffered.family,
417:                     spec: AttackSpec { curve, ..spec },
418:                     start,
419:                     reach,
420:                 },
421:                 &skeleton,
422:                 &targeting,
423:                 &combat_config,
424:                 windup_secs?,
425:                 recovery_secs?,
426:             )?;
427:             let PreparedMeleeAttack {
428:                 spec,
429:                 timing,
430:                 attack_state,
431:                 target,
432:             } = prepared;
433:             if skeleton
434:                 .begin_attack_timed(spec, timing.start, timing.contact, timing.end)
435:                 .is_err()
436:             {
437:                 return Ok(());
438:             }
439:             cmd.entity(entity)
440:                 .insert(attack_state)
441:                 .remove::<BufferedMeleeAttack>();
442:             cmd.client_trigger(MeleeActionRequest {
443:                 strike_family: buffered.family,
444:                 hand: buffered.hand,
445:                 target: target.map(|target| target.body),
446:             });
447:             Ok(())
448:         })();
449:         if let Err(error) = attempt {
450:             warn!(?entity, %error, "cannot schedule buffered melee attack");
451:         }
452:     }
453: }
