30: impl QuickstepTraceObservation {
31:     fn has_changed_since(self, previous: Self) -> bool {
32:         (self.action == SkeletonAction::Dodge) != (previous.action == SkeletonAction::Dodge)
33:             || self.actuator.is_active() != previous.actuator.is_active()
34:             || self.actuator.start_tick() != previous.actuator.start_tick()
35:     }
36: }
