38: impl ObservedQuickstepActuator {
39:     fn is_active(self) -> bool {
40:         matches!(self, Self::Active { .. })
41:     }
42: 
43:     fn start_tick(self) -> AnimationSampleTick {
44:         match self {
45:             Self::Inactive {
46:                 retained_start_tick,
47:             } => retained_start_tick,
48:             Self::Active { start_tick } => start_tick,
49:         }
50:     }
51: }
