53: pub(super) fn trace_local_quickstep_state(
54:     mut players: Query<
55:         (
56:             Entity,
57:             &SkeletonState,
58:             &CharacterMotionSnapshot,
59:             &Transform,
60:             &mut LocalQuickstepTrace,
61:         ),
62:         With<ControlledPlayer>,
63:     >,
64: ) {
65:     for (entity, skeleton, snapshot, transform, mut trace) in &mut players {
66:         let action = skeleton.action_kind();
67:         let dodge_action = action == SkeletonAction::Dodge;
68:         let push = snapshot.quickstep_push;
69:         let observation = QuickstepTraceObservation {
70:             action,
71:             actuator: if push.active {
72:                 ObservedQuickstepActuator::Active {
73:                     start_tick: push.start_tick,
74:                 }
75:             } else {
76:                 ObservedQuickstepActuator::Inactive {
77:                     retained_start_tick: push.start_tick,
78:                 }
79:             },
80:         };
81:         let changed = trace
82:             .observation
83:             .is_none_or(|previous| observation.has_changed_since(previous));
84:         if !changed {
85:             continue;
86:         }
87: 
88:         let attack_lunge = snapshot.melee_lunge.is_some_and(|lunge| lunge.quickstep);
89:         if (dodge_action || attack_lunge) != push.active {
90:             warn!(
91:                 target: "quickstep_trace",
92:                 ?entity,
93:                 dodge_action,
94:                 action_direction = ?skeleton.action_direction(),
95:                 skeleton_tick = skeleton.locomotion_sample_tick.encoded(),
96:                 push_active = push.active,
97:                 push_start_tick = push.start_tick.encoded(),
98:                 push_direction = ?push.direction,
99:                 acknowledged_input_tick = snapshot.acknowledged_input_tick.map(PlayerInputTick::encoded),
100:                 render_translation = ?transform.translation,
101:                 snapshot_translation = ?snapshot.translation,
102:                 "[quickstep][client-state] animation/actuator discrepancy"
103:             );
104:         } else if dodge_action
105:             || push.active
106:             || trace.observation.is_some_and(|previous| {
107:                 previous.action == SkeletonAction::Dodge || previous.actuator.is_active()
108:             })
109:         {
110:             info!(
111:                 target: "quickstep_trace",
112:                 ?entity,
113:                 dodge_action,
114:                 action_direction = ?skeleton.action_direction(),
115:                 skeleton_tick = skeleton.locomotion_sample_tick.encoded(),
116:                 push_active = push.active,
117:                 push_start_tick = push.start_tick.encoded(),
118:                 push_direction = ?push.direction,
