230: fn cached_building_levels(
231:     _owner: PresentationOwner,
232:     cache: &mut TacticalBuildingMeshCache,
233:     program: &BuildingProgram,
234:     detail: BuildingDetail,
235:     meshes: &mut Assets<Mesh>,
236:     prepared: Option<&GeneratedBuildingRecipe>,
237: ) -> Result<Arc<CompiledBuildingLevels>> {
238:     if let Some(compiled) = cache
239:         .levels
240:         .iter()
241:         .find(|compiled| compiled.program == *program && compiled.detail == detail)
242:     {
243:         return Ok(compiled.clone());
244:     }
245: 
246:     #[cfg(target_family = "wasm")]
247:     if detail == BuildingDetail::Facade {
248:         let prepared = super::generation::take_facade(_owner, program)?;
249:         return kit::install_facade(cache, prepared, meshes);
250:     }
251: 
252:     let generated;
253:     let geometry = if let Some(prepared) = prepared {
254:         prepared
255:     } else {
256:         generated = match cache.recipes.take(program) {
257:             Some(recipe) => recipe,
258:             None => GeneratedBuildingRecipe::generate(program.clone())?,
259:         };
260:         &generated
261:     };
262:     let plan = &geometry.plan;
263:     #[cfg(target_family = "wasm")]
264:     if detail == BuildingDetail::Dynamic && prepared.is_some() {
265:         let meshes_ready = super::generation::take_venue_geometry(_owner, program)?;
266:         return self::prepared::install(cache, program, meshes_ready, geometry, meshes);
267:     }
268:     let collision = &geometry.collision;
269:     let local_origin = collision.bounds.centre()?;
270:     let RecipeMeshes {
271:         kit,
272:         detail_meshes,
273:         facade,
274:     } = RecipeMeshes::compile(plan, detail)?;
275:     let shell = match (detail == BuildingDetail::Facade)
276:         .then(|| adventuresim_building_generator::compile_program_shell(program))
277:         .flatten()
278:     {
279:         Some(shell) => shell,
280:         None => compile_building_lod(plan, BuildingLodLevel::Shell)?,
281:     };
282:     let compile_batches = |source: &[LodMesh], meshes: &mut Assets<Mesh>| {
283:         source
284:             .iter()
285:             .map(|batch| {
286:                 CompiledBuildingBatch::from_recipe(batch, local_origin.metres(), detail, meshes)
287:             })
288:             .collect()
289:     };
290:     let mut compiled = CompiledBuildingLevels {
291:         facade_openings: if detail == BuildingDetail::Dynamic {
292:             plan.facade_dynamic_openings()?
293:         } else {
294:             Default::default()
295:         },
296:         interior: (detail == BuildingDetail::Dynamic).then(|| {
297:             super::interior_lighting::InteriorField::from_plan(plan, local_origin.metres())
298:         }),
299:         program: program.clone(),
300:         detail,
301:         local_origin,
302:         sign_sites: if program
303:             .usage
304:             .and_then(adventuresim_building_generator::signs::shop_trade)
305:             .is_some()
306:         {
307:             signs::sites(plan)
308:         } else {
309:             Vec::new()
310:         },
311:         lod0: detail_meshes.map_or_else(Vec::new, |detail| compile_batches(&detail.meshes, meshes)),
312:         lod1: compile_batches(&facade.meshes, meshes),
313:         lod2: compile_batches(&shell.meshes, meshes),
314:     };
315:     if let Some(kit) = kit {
316:         cache
317:             .components
318:             .append(&kit.instances, &mut compiled, meshes);
319:     }
320:     let compiled = Arc::new(compiled);
321:     cache.levels.push(compiled.clone());
322:     Ok(compiled)
323: }
