325: fn spawn_building_levels(
326:     parent: &mut ChildSpawnerCommands,
327:     building_id: u64,
328:     compiled: &CompiledBuildingLevels,
329:     materials: &TacticalBuildingMaterials,
330: ) {
331:     let palette = materials.for_building(building_id);
332:     for (level, batches) in [
333:         (BuildingRenderLevel::Lod0, &compiled.lod0),
334:         (BuildingRenderLevel::Lod1, &compiled.lod1),
335:         (BuildingRenderLevel::Lod2, &compiled.lod2),
336:     ] {
337:         for batch in batches {
338:             parent.spawn((
339:                 Name::new(format!("Building {:?} {:?}", level, batch.material)),
340:                 PresentedBuildingMesh {
341:                     level,
342:                     material: batch.material,
343:                     triangles: batch.triangles,
344:                 },
345:                 Mesh3d(batch.mesh.clone()),
346:                 Transform::from_matrix(batch.transform),
347:                 MeshMaterial3d(palette.get(batch.material)),
348:                 if matches!(
349:                     (compiled.detail, level),
350:                     (BuildingDetail::Facade, BuildingRenderLevel::Lod1)
351:                 ) {
352:                     VisibilityRange {
353:                         start_margin: 0.0..0.0,
354:                         ..building_lod_visibility(level)
355:                     }
356:                 } else {
357:                     building_lod_visibility(level)
358:                 },
359:             ));
360:         }
361:     }
362: }
363: 
364: pub(super) fn building_lod_visibility(level: BuildingRenderLevel) -> VisibilityRange {
365:     match level {
366:         BuildingRenderLevel::Lod0 => VisibilityRange {
367:             start_margin: 0.0..0.0,
368:             end_margin: DETAIL_LOD_END_START_METRES..DETAIL_LOD_END_END_METRES,
369:             use_aabb: false,
370:         },
371:         BuildingRenderLevel::Lod1 => VisibilityRange {
372:             start_margin: DETAIL_LOD_END_START_METRES..DETAIL_LOD_END_END_METRES,
373:             end_margin: FACADE_LOD_END_START_METRES..FACADE_LOD_END_END_METRES,
374:             use_aabb: false,
375:         },
376:         BuildingRenderLevel::Lod2 => VisibilityRange {
377:             start_margin: FACADE_LOD_END_START_METRES..FACADE_LOD_END_END_METRES,
378:             // The generated settlement is already finite. Keeping its cheapest
379:             // shell visible avoids cutting the far half of a city from elevated
380:             // or exterior viewpoints.
381:             end_margin: f32::MAX..f32::MAX,
382:             use_aabb: false,
383:         },
384:     }
385: }
