387: struct RecipeMeshes<'a> {
388:     kit: Option<adventuresim_building_generator::BuildingKit<'a>>,
389:     detail_meshes: Option<adventuresim_building_generator::BuildingDetail>,
390:     facade: adventuresim_building_generator::BuildingLod,
391: }
392: impl<'a> RecipeMeshes<'a> {
393:     fn compile(
394:         plan: &'a adventuresim_building_generator::BuildingPlan,
395:         detail: BuildingDetail,
396:     ) -> Result<Self> {
397:         Ok(match detail {
398:             BuildingDetail::Dynamic => Self {
399:                 kit: None,
400:                 detail_meshes: Some(compile_static_building_detail(plan)?),

401:                 facade: compile_static_building_lod(plan, BuildingLodLevel::Facade)?,
402:             },
403:             BuildingDetail::Static | BuildingDetail::Facade => {
404:                 let kit = adventuresim_building_generator::BuildingKit::new(plan)?;
405:                 let meshes = if detail == BuildingDetail::Static {
406:                     Some(kit.detail()?)
407:                 } else {
408:                     None
409:                 };
410:                 let facade = kit.facade()?;
411:                 Self {
412:                     kit: Some(kit),
413:                     detail_meshes: meshes,
414:                     facade,
415:                 }
416:             }
417:         })
418:     }
419: }
