12: // Keep culling spatially useful without retaining an entity for every wall cap.
13: const BOUNDARY_BATCH_METRES: f32 = 128.0;
14: 
15: type BoundaryBatchResult<T> = std::result::Result<T, BoundaryBatchError>;
16: 
17: pub(super) struct BoundaryMesh {
