47: impl PendingDistantBoundaries {
48:     fn take_for_scene(
49:         &mut self,
50:         terrain: &SceneTerrain,
51:         environment: &SceneEnvironment,
52:     ) -> std::result::Result<
53:         Option<Vec<GeneratedBoundary>>,
54:         adventuresim_tactical_core::scene_input::SceneInputError,
55:     > {
56:         let Some(projection) = &self.0 else {
57:             return Ok(None);
58:         };
59:         if projection.scene_digest != environment.scene_digest {
60:             return Ok(None);
61:         }
62:         let Some(projection) = self.0.take() else {
63:             return Ok(None);
64:         };
65:         projection
66:             .compounds
67:             .iter()
68:             .map(|compound| GeneratedBoundary::project(compound, terrain))
69:             .collect::<std::result::Result<Vec<_>, _>>()
70:             .map(Some)
71:     }
72: }
