121: fn spawn_batch(
122:     world: &mut World,
123:     owner: PresentationOwner,
124:     handle: Handle<StandardMaterial>,
125:     grouped: ranges::InstanceRanges,
126:     vertices: &Handle<ShaderBuffer>,
127:     indices: &Handle<ShaderBuffer>,
128:     anchor: &Handle<Mesh>,
129: ) -> AssemblyResult<GpuBatch> {
130:     let authored = world
131:         .resource::<Assets<StandardMaterial>>()
132:         .get(&handle)
133:         .ok_or(AssemblyError::MissingMaterial)?
134:         .clone();
135:     let ranges = grouped.ranges.len() as u32;
136:     let capacity = grouped.capacity;
137:     let owners = world
138:         .resource_mut::<Assets<ShaderBuffer>>()
139:         .add(ShaderBuffer::from(grouped.owners));
140:     let source = world
141:         .resource_mut::<Assets<ShaderBuffer>>()
142:         .add(ShaderBuffer::from(grouped.ranges));
143:     let material = world
144:         .resource_mut::<Assets<material::CityMaterial>>()
145:         .add(material::CityMaterial::from_source(authored));
146:     let entity = world
147:         .spawn((
148:             Name::new("GPU city material batch"),
149:             DistantCityBuildingPresentation,
150:             CityBatchAnchor,
151:             owner,
152:             Mesh3d(anchor.clone()),
153:             MeshMaterial3d(material.clone()),
154:             Transform::default(),
155:             NoFrustumCulling,
156:             NoAutomaticBatching,
157:             owner.render_layers(),
158:             Aabb {
159:                 center: Vec3::ZERO.into(),
160:                 half_extents: Vec3::splat(1.0).into(),
161:             },
162:         ))
163:         .id();
164:     Ok(GpuBatch {
165:         anchor: entity,
166:         owners,
167:         material,
168:         source,
169:         vertices: vertices.clone(),
170:         indices: indices.clone(),
171:         ranges,
172:         capacity,
173:     })
174: }
