193:         return Err(AssemblyError::MissingMaterial);
194:     }
195:     let count = buildings.len() as u32;
196:     let frame_buffer = world
197:         .resource_mut::<Assets<ShaderBuffer>>()
198:         .add(ShaderBuffer::from(frame));
199:     let geometry_bytes: usize = geometry
200:         .pages

201:         .iter()
202:         .map(|p| p.vertices.len() * size_of::<Vec4>() + p.indices.len() * size_of::<u32>())
203:         .sum();
204:     let unshared_ranges = batches
205:         .values()
206:         .map(|(_, jobs)| jobs.unshared_ranges())
207:         .sum::<usize>();
208:     let clusters: u32 = batches.values().map(|(_, jobs)| jobs.capacity).sum();
209:     let pages: Vec<_> = geometry
210:         .pages
211:         .into_iter()
212:         .map(|page| {
213:             let mut buffers = world.resource_mut::<Assets<ShaderBuffer>>();
214:             (
215:                 buffers.add(ShaderBuffer::from(page.vertices)),
216:                 buffers.add(ShaderBuffer::from(page.indices)),
217:             )
218:         })
219:         .collect();
220:     let buildings = world
221:         .resource_mut::<Assets<ShaderBuffer>>()
222:         .add(ShaderBuffer::from(buildings));
223:     let selection = world
224:         .resource_mut::<Assets<ShaderBuffer>>()
225:         .add(ShaderBuffer::with_size(
226:             count as usize * MAX_CITY_VIEWS * size_of::<u32>(),
227:             bevy::asset::RenderAssetUsages::RENDER_WORLD,
228:         ));
229:     let anchor = world
230:         .resource_mut::<Assets<Mesh>>()
231:         .add(Cuboid::new(1.0, 1.0, 1.0));
232:     let mut gpu_batches = Vec::new();
233:     for ((page, _), (handle, jobs)) in batches {
234:         gpu_batches.push(spawn_batch(
235:             world,
236:             owner,
237:             handle,
238:             jobs,
239:             &pages[page].0,
240:             &pages[page].1,
241:             &anchor,
242:         )?);
243:     }
244:     info!(
245:         buildings = count,
246:         batches = gpu_batches.len(),
247:         clusters,
248:         unshared_ranges,
249:         ranges = gpu_batches.iter().map(|batch| batch.ranges).sum::<u32>(),
250:         geometry_bytes,
251:         pages = pages.len(),
252:         "GPU city resident"
253:     );
