264: fn assemble_owner(world: &mut World, owner: PresentationOwner) {
265:     let mut pending = std::mem::take(
266:         world
267:             .resource_mut::<PendingGpuCities>()
268:             .owners
269:             .get_mut(owner),
270:     );
271:     if pending
272:         .publication
273:         .as_ref()
274:         .is_some_and(|publication| world.get_entity(publication.root).is_err())
275:     {
276:         return;
277:     }
278:     // Only publish alongside a completed city; interactive furniture is never
279:     // consumed by this static scenery path.
280:     if pending.is_empty() {
281:         if let Some(publication) = pending.publication {
282:             super::reset(world, owner);
283:             world
284:                 .resource_mut::<CityGpuScenes>()
285:                 .owners
286:                 .get_mut(owner)
287:                 .frame = publication.frame;
288:             world
289:                 .entity_mut(publication.root)
290:                 .insert(CityAssemblyPublished)
291:                 .remove::<CityAssemblyFailure>();
292:             READY.get(owner).store(true, Ordering::Relaxed);
293:         }
294:         return;
295:     }
296:     if owner == PresentationOwner::Scene {
297:         pending.parts.extend(props::parts(world));
298:     }
299:     let frame = pending
300:         .publication
301:         .as_ref()
302:         .map(|publication| publication.frame)
303:         .unwrap_or(world.resource::<CityGpuScenes>().owners.get(owner).frame);
304:     let scene = pending
305:         .groups(world.get_resource())
306:         .and_then(|groups| pack(world, groups))
307:         .and_then(|packed| upload(world, owner, packed, frame));
308:     let scene = match scene {
309:         Ok(scene) => scene,
310:         Err(error) => {
311:             warn!(?owner, %error, "Could not assemble GPU city");
312:             if let Some(publication) = &pending.publication {
313:                 world
314:                     .entity_mut(publication.root)
315:                     .insert(CityAssemblyFailure(error));
316:             }
317:             return;
318:         }
319:     };
320:     if let Some(publication) = &pending.publication {
321:         world
322:             .entity_mut(publication.root)
323:             .insert(CityAssemblyPublished)
324:             .remove::<CityAssemblyFailure>();
325:     }
326:     READY.get(owner).store(false, Ordering::Relaxed);
327:     let prop_roots: std::collections::HashSet<_> = pending
328:         .parts
329:         .iter()
330:         .filter(|part| part.fade.is_some())
331:         .map(|part| part.root)
332:         .collect();
333:     for part in pending.parts {
334:         if let Some(entity) = part.entity {
335:             world.entity_mut(entity).despawn();
336:         }
337:     }
338:     // Vista descriptors still retain the recipes and identities. These roots
339:     // have no physics, animation or remaining render children to update.
340:     for root in prop_roots {
341:         world.entity_mut(root).despawn();
342:     }
343:     let previous = std::mem::replace(
344:         world.resource_mut::<CityGpuScenes>().owners.get_mut(owner),
345:         scene,
346:     );
347:     for batch in previous.batches.iter() {
348:         if let Ok(entity) = world.get_entity_mut(batch.anchor) {
349:             entity.despawn();
350:         }
351:     }
352: }
