256: pub(super) fn install(app: &mut App) {
257:     app.sub_app_mut(RenderApp)
258:         .init_resource::<CityViews>()
259:         .init_resource::<scratch::Scratch>()
260:         .add_systems(RenderStartup, initialize)
261:         .add_systems(Render, prepare.in_set(RenderSystems::PrepareBindGroups))
262:         .add_systems(
263:             Core3d,
264:             cull.before(Core3dSystems::Prepass)
