270: fn initialize(mut commands: Commands, cache: Res<PipelineCache>, server: Res<AssetServer>) {
271:     let layout = BindGroupLayoutDescriptor::new(
272:         "city GPU culling",
273:         &BindGroupLayoutEntries::sequential(
274:             ShaderStages::COMPUTE,
275:             (
276:                 uniform_buffer::<ViewParameters>(true),
277:                 storage_buffer_read_only::<assembly::Building>(false),
278:                 storage_buffer::<u32>(false),
279:                 storage_buffer_read_only::<assembly::DrawRange>(false),
280:                 storage_buffer::<UVec2>(false),
281:                 storage_buffer::<UVec4>(false),
282:                 storage_buffer_read_only::<u32>(false),
283:             ),
284:         ),
285:     );
286:     let shader = server.load(CULL_SHADER);
287:     let pipeline = |entry: &str| {
288:         cache.queue_compute_pipeline(ComputePipelineDescriptor {
289:             label: Some(format!("city_{entry}").into()),
290:             layout: vec![layout.clone()],
291:             shader: shader.clone(),
292:             entry_point: Some(entry.to_owned().into()),
293:             ..default()
294:         })
295:     };
296:     let select = pipeline("select_buildings");
297:     let compact = pipeline("compact_ranges");
298:     commands.insert_resource(Pipelines {
299:         layout,
300:         select,
301:         compact,
302:     });
