15: #[derive(Clone)]
16: pub(super) struct Slice {
17:     pub page: usize,
18:     pub start: u32,
19:     pub count: u32,
20:     pub radius: f32,
21: }
22: 
23: pub(super) struct Geometry {
24:     pub pages: Vec<Page>,
25:     limit: usize,
26: }
