28: impl Default for Geometry {
29:     fn default() -> Self {
30:         Self {
31:             pages: vec![Page::default()],
32:             limit: PAGE_BYTES,
33:         }
34:     }
35: }
36: 
37: fn float3(mesh: &Mesh, attribute: bevy::mesh::MeshVertexAttribute) -> &[[f32; 3]] {
38:     let values = mesh
39:         .attribute(attribute)
40:         .expect("generated city vertex attribute");
41:     match values {
42:         VertexAttributeValues::Float32x3(values) => values,
43:         _ => panic!("generated city attribute must be float3"),
44:     }
45: }
46: 
47: impl Geometry {
48:     pub fn insert(&mut self, mesh: &Mesh) -> Vec<Slice> {
49:         let positions = float3(mesh, Mesh::ATTRIBUTE_POSITION);
50:         let normals = float3(mesh, Mesh::ATTRIBUTE_NORMAL);
51:         let Some(VertexAttributeValues::Float32x2(uvs)) = mesh.attribute(Mesh::ATTRIBUTE_UV_0)
52:         else {
53:             panic!("generated city requires UVs");
54:         };
55:         let tangents = mesh.attribute(Mesh::ATTRIBUTE_TANGENT);
56:         let source: Vec<_> = mesh
57:             .indices()
58:             .expect("generated city is indexed")
59:             .iter()
60:             .collect();
61:         assert_eq!(
62:             source.len() % 3,
63:             0,
64:             "city geometry must contain whole triangles"
65:         );
66:         let mut remap = HashMap::new();
67:         let mut slices: Vec<Slice> = Vec::new();
68:         for triangle in source.as_chunks::<3>().0 {
69:             let page = self.pages.last().expect("geometry page");
70:             let missing = triangle
71:                 .iter()
72:                 .filter(|index| !remap.contains_key(*index))
73:                 .count();
74:             if (page.vertices.len() + missing * 3) * size_of::<Vec4>() > self.limit
75:                 || (page.indices.len() + 3) * size_of::<u32>() > self.limit
76:             {
77:                 self.pages.push(Page::default());
78:                 remap.clear();
79:             }
80:             let page_index = self.pages.len() - 1;
81:             let page = self.pages.last_mut().expect("geometry page");
82:             if slices.last().is_none_or(|slice| slice.page != page_index) {
83:                 slices.push(Slice {
84:                     page: page_index,
85:                     start: page.indices.len() as u32,
86:                     count: 0,
87:                     radius: 0.0,
88:                 });
89:             }
90:             let slice = slices.last_mut().expect("mesh page slice");
91:             for &index in triangle {
92:                 let vertex = *remap.entry(index).or_insert_with(|| {
93:                     let vertex = (page.vertices.len() / 3) as u32;
94:                     page.vertices
95:                         .push(Vec3::from_array(positions[index]).extend(uvs[index][0]));
96:                     page.vertices
97:                         .push(Vec3::from_array(normals[index]).extend(uvs[index][1]));
98:                     page.vertices.push(match tangents {
99:                         Some(VertexAttributeValues::Float32x4(values)) => {
100:                             Vec4::from_array(values[index])
101:                         }
102:                         _ => Vec3::from_array(normals[index])
103:                             .any_orthonormal_vector()
104:                             .extend(1.0),
105:                     });
106:                     vertex
107:                 });
108:                 page.indices.push(vertex);
109:                 slice.radius = slice
110:                     .radius
111:                     .max(Vec3::from_array(positions[index]).length());
112:                 slice.count += 1;
113:             }
114:         }
115:         slices
116:     }
117: }
