26:                         let mut mesh = recipe_mesh(batch, Vec3::ZERO);
27:                         mesh.asset_usage = RenderAssetUsages::MAIN_WORLD;
28:                         CompiledBuildingBatch {
29:                             material: batch.material,
30:                             mesh: meshes.add(mesh),
31:                             triangles: batch.indices.len() / 3,
