40:     pub(super) fn append(
41:         &mut self,
42:         instances: &[TimberInstance],
43:         compiled: &mut CompiledBuildingLevels,
44:         meshes: &mut Assets<Mesh>,
45:     ) {
46:         for instance in instances {
47:             if compiled.detail == BuildingDetail::Facade && !instance.facade {
48:                 continue;
49:             }
50:             for batch in self.get(instance.component, meshes) {
51:                 let mut batch = batch.clone();
52:                 batch.transform =
53:                     Mat4::from_translation(-compiled.local_origin.metres()) * instance.transform;
54:                 batch.uv_offset = instance.uv_offset;
55:                 if compiled.detail == BuildingDetail::Static {
56:                     compiled.lod0.push(batch.clone());
57:                 }
58:                 if instance.facade {
59:                     compiled.lod1.push(batch);
60:                 }
61:             }
62:         }
63:     }
