2: use adventuresim_building_generator::spatial_geometry::LeafDimensions;
3: use adventuresim_building_generator::{
4:     BuildingLodMaterial, ClosureState, WindowLeafKind, compile_window_leaf,
5: };
6: use bevy::prelude::*;
7: use std::collections::HashMap;
