9: #[derive(Clone, Copy, PartialEq, Eq, Hash)]
10: struct Dimensions([u32; 3]);
11: 
12: impl From<Vec3> for Dimensions {
13:     fn from(size: Vec3) -> Self {
14:         Self(size.to_array().map(f32::to_bits))
15:     }
16: }
