18: pub(super) struct LeafSurface {
19:     pub mesh: Handle<Mesh>,
20:     pub material: BuildingLodMaterial,
21: }
22: 
23: #[derive(Debug, thiserror::Error)]
24: pub(super) enum ClosureMeshError {
25:     #[error(transparent)]
26:     Construction(#[from] adventuresim_building_generator::CollisionError),
27:     #[error("window leaf {kind:?} has no primary material")]
28:     MissingPrimaryMaterial { kind: WindowLeafKind },
29: }
30: 
31: type Result<T> = std::result::Result<T, ClosureMeshError>;
32: 
33: #[derive(Default, Resource)]
34: pub(super) struct ClosureMeshes {
35:     doors: HashMap<Dimensions, Handle<Mesh>>,
36:     glass: HashMap<Dimensions, Vec<LeafSurface>>,
37:     shutters: HashMap<Dimensions, Vec<LeafSurface>>,
38: }
39: 
40: impl ClosureMeshes {
41:     pub fn door(&mut self, size: LeafDimensions, meshes: &mut Assets<Mesh>) -> Handle<Mesh> {
42:         let size = size.metres();
43:         self.doors
44:             .entry(size.into())
45:             .or_insert_with(|| meshes.add(Cuboid::from_size(size)))
46:             .clone()
47:     }
48: 
49:     pub fn window(
50:         &mut self,
51:         size: LeafDimensions,
52:         kind: WindowLeafKind,
53:         meshes: &mut Assets<Mesh>,
54:     ) -> Result<&[LeafSurface]> {
55:         let cache = match kind {
56:             WindowLeafKind::LeadedGlass => &mut self.glass,
57:             WindowLeafKind::TimberShutter => &mut self.shutters,
58:         };
59:         let parts = match cache.entry(size.metres().into()) {
60:             std::collections::hash_map::Entry::Occupied(entry) => entry.into_mut(),
61:             std::collections::hash_map::Entry::Vacant(entry) => entry.insert(
62:                 compile_window_leaf(size.cuboid(), kind, ClosureState::Operable)?
63:                     .iter()
64:                     .map(|batch| LeafSurface {
65:                         mesh: meshes.add(super::recipe_mesh::recipe_mesh(batch, Vec3::ZERO)),
66:                         material: batch.material,
67:                     })
68:                     .collect(),
69:             ),
70:         };
71:         Ok(parts)
72:     }
73: }
