81: /// Coordinate in the dimensionless three-axis cloud density lattice.
82: /// World metres are scaled by the layer recipe before this value is produced.
83: #[derive(Clone, Copy)]
84: pub(super) struct CloudDensityCoordinate(Vec3);
85: 
86: impl CloudDensityCoordinate {
87:     /// Native axes at the owning layer-to-lattice numerical boundary.
88:     pub(super) fn from_layer_axes(axes: Vec3) -> Self {
89:         Self(axes)
90:     }
91:     pub(super) fn axes(self) -> Vec3 {
92:         self.0
93:     }
94: }
95: 
96: impl std::ops::Mul<f32> for CloudDensityCoordinate {
97:     type Output = Self;
98:     fn mul(self, frequency: f32) -> Self {
99:         Self(self.0 * frequency)
100:     }
101: }
102: impl std::ops::Add<Vec3> for CloudDensityCoordinate {
103:     type Output = Self;
104:     /// Native authored offsets are dimensionless lattice axes.
105:     fn add(self, offset: Vec3) -> Self {
106:         Self(self.0 + offset)
107:     }
108: }
109: impl std::ops::Add<CloudDensityWarp> for CloudDensityCoordinate {
110:     type Output = Self;
111:     fn add(self, warp: CloudDensityWarp) -> Self {
112:         Self(self.0 + warp.0)
113:     }
