220:             TacticalCloudCaptureProfile::Cumulus => 117,
221:             TacticalCloudCaptureProfile::Stratocumulus => 283,
222:             TacticalCloudCaptureProfile::Cirrus => 419,
223:             TacticalCloudCaptureProfile::Overcast => 631,
224:             TacticalCloudCaptureProfile::Storm => 887,
225:         };
226:         let layer = match profile {
227:             TacticalCloudCaptureProfile::Clear => return None,
228:             TacticalCloudCaptureProfile::Cumulus => CloudLayerSnapshot {
229:                 form: CloudForm::Cumulus,
230:                 coverage_bps: 4_800,
231:                 optical_density_bps: 5_000,
232:                 base_metres: 1_250,
233:                 top_metres: 3_100,
234:             },
235:             TacticalCloudCaptureProfile::Stratocumulus => CloudLayerSnapshot {
236:                 form: CloudForm::Stratocumulus,
237:                 coverage_bps: 5_700,
238:                 optical_density_bps: 5_500,
239:                 base_metres: 1_050,
240:                 top_metres: 1_950,
241:             },
242:             TacticalCloudCaptureProfile::Cirrus => CloudLayerSnapshot {
243:                 form: CloudForm::Cirrus,
244:                 coverage_bps: 4_200,
245:                 optical_density_bps: 2_000,
246:                 base_metres: 5_500,
247:                 top_metres: 8_500,
248:             },
249:             TacticalCloudCaptureProfile::Overcast => CloudLayerSnapshot {
250:                 form: CloudForm::Stratus,
251:                 coverage_bps: 9_400,
252:                 optical_density_bps: 7_000,
253:                 base_metres: 700,
254:                 top_metres: 1_350,
255:             },
256:             TacticalCloudCaptureProfile::Storm => CloudLayerSnapshot {
257:                 form: CloudForm::Cumulonimbus,
258:                 coverage_bps: 7_200,
259:                 optical_density_bps: 9_000,
260:                 base_metres: 720,
261:                 top_metres: 10_500,
262:             },
263:         };
