273:             CloudForm::Cirrus => (2.0, 0.000_27),
274:             CloudForm::Cumulonimbus => (3.0, 0.000_34),
275:             CloudForm::Stratus => (4.0, 0.000_25),
276:             CloudForm::Altocumulus => (5.0, 0.000_58),
277:             CloudForm::Altostratus => (6.0, 0.000_22),
278:             CloudForm::Nimbostratus => (7.0, 0.000_21),
279:             CloudForm::Cirrocumulus => (8.0, 0.000_68),
280:             CloudForm::Cirrostratus => (9.0, 0.000_16),
281:             CloudForm::CumulusCongestus => (10.0, 0.000_48),
