331: pub(in crate::presentation) fn update_tactical_cloud_offscreen_target(
332:     target: Option<Res<TacticalCloudOffscreenTarget>>,
333:     mut images: ResMut<Assets<Image>>,
334:     main_camera: Query<&Camera, (With<Camera3d>, Without<TacticalCloudOffscreenCamera>)>,
335:     main_projection: Query<
336:         &Projection,
337:         (
338:             With<Camera3d>,
339:             Without<TacticalCloudOffscreenCamera>,
340:             Changed<Projection>,
341:         ),
342:     >,
343:     mut offscreen_projection: Query<&mut Projection, With<TacticalCloudOffscreenCamera>>,
344: ) {
345:     let Some(target) = target else {
346:         return;
347:     };
348:     if let Some(target_size) = main_camera
349:         .iter()
350:         .next()
351:         .and_then(Camera::physical_target_size)
352:     {
353:         let desired = cloud_offscreen_size(target_size, target.resolution_scale);
354:         let stale = images
355:             .get(&target.image)
356:             .is_some_and(|image| image.texture_descriptor.size != desired);
357:         if stale && let Some(mut image) = images.get_mut(&target.image) {
358:             image.resize(desired);
359:         }
360:     }
361:     if let (Some(main), Some(mut offscreen)) = (
362:         main_projection.iter().next(),
363:         offscreen_projection.iter_mut().next(),
364:     ) {
365:         *offscreen = main.clone();
366:     }
