411: pub(in crate::presentation) fn setup_tactical_clouds(
412:     mut commands: Commands,
413:     mut meshes: ResMut<Assets<Mesh>>,
414:     mut images: ResMut<Assets<Image>>,
415:     mut materials: ResMut<Assets<TacticalCloudMaterial>>,
416:     mut composite_materials: ResMut<Assets<TacticalCloudCompositeMaterial>>,
417:     settings: Res<TacticalGraphicsSettings>,
418:     cameras: Query<(Entity, &Projection, &Camera), With<Camera3d>>,
419: ) {
420:     commands.insert_resource(CloudBakeState::default());
421:     commands.insert_resource(TacticalCloudAnimationStatus::default());
422:     if !settings.config.rendering.clouds.enabled {
423:         return;
424:     }
425:     // The baked shell can render at a reduced offscreen resolution and
426:     // composite through one dome; clouds are soft enough that the bilinear
427:     // upsample is close to invisible while the fragment cost drops with the
428:     // resolution squared. The full-resolution in-view path (1.0) stays
429:     // authoritative for capture tooling.
430:     let offscreen = if settings.config.rendering.clouds.resolution_scale < 0.999 {
431:         cameras.iter().next().map(|(camera, projection, main)| {
432:             (camera, projection.clone(), main.physical_target_size())
433:         })
434:     } else {
435:         None
436:     };
437:     let mesh = meshes.add(cloud_hemisphere_mesh());
438:     let empty_request = CloudBakeRequest {
439:         key: CloudBakeKey {
440:             layers: [None, None, None],
441:             seed: fabelgeist_determinism::Seed::from_u64(0),
442:         },
443:         endpoint: 0,
444:         wind_velocity: Vec2::ZERO,
445:     };
446:     let baked_texture_a = images.add(cloud_bake_image(&empty_request));
447:     let baked_texture_b = images.add(cloud_bake_image(&empty_request));
448:     let mut shell = commands.spawn((
449:         Name::new("Baked tactical cloud shell"),
450:         TacticalCloudLayer { active: false },
451:         NoFrustumCulling,
452:         NotShadowCaster,
453:         Mesh3d(mesh.clone()),
454:         MeshMaterial3d(materials.add(TacticalCloudMaterial {
455:             lighting: Vec4::new(0.0, 1.0, 0.0, 1.43),
456:             shape: Vec4::ZERO,
457:             layer: Vec4::new(2_000.0, 1.0, 0.0, 0.0),
458:             motion: Vec4::new(0.0, 0.0, 1.0, 1.0),
459:             spectral: Vec4::ONE,
460:             geometry: cloud_shell_geometry(),
461:             baked_texture_a,
462:             baked_texture_b,
463:         })),
464:         Transform::default(),
465:     ));
466:     if offscreen.is_some() {
467:         shell.insert(RenderLayers::layer(CLOUD_OFFSCREEN_LAYER));
468:     }
469:     let Some((camera, projection, target_size)) = offscreen else {
470:         return;
471:     };
472:     let resolution_scale = settings
473:         .config
474:         .rendering
475:         .clouds
476:         .resolution_scale
477:         .clamp(0.25, 1.0);
478:     // The camera's computed target size is often not known yet during
479:     // startup; the per-frame update system re-sizes the image on the first
480:     // frame where it is.
481:     let size = cloud_offscreen_size(
482:         target_size.unwrap_or(UVec2::new(960, 540)),
483:         resolution_scale,
484:     );
485:     let image = images.add(cloud_offscreen_image(size));
486:     commands.insert_resource(TacticalCloudOffscreenTarget {
487:         image: image.clone(),
488:         resolution_scale,
489:     });
490:     commands.spawn((
491:         Name::new("Tactical cloud composite dome"),
492:         TacticalCloudComposite,
493:         NoFrustumCulling,
494:         NotShadowCaster,
495:         Mesh3d(mesh),
496:         MeshMaterial3d(composite_materials.add(TacticalCloudCompositeMaterial {
497:             source: image.clone(),
498:         })),
499:         Transform::default(),
500:     ));
501:     commands.entity(camera).with_children(|children| {
502:         children.spawn((
503:             Name::new("Tactical cloud offscreen camera"),
504:             TacticalCloudOffscreenCamera,
505:             Camera3d::default(),
506:             Camera {
507:                 // Render before the main camera consumes the target.
508:                 order: -1,
509:                 clear_color: ClearColorConfig::Custom(Color::NONE),
510:                 ..default()
511:             },
512:             RenderTarget::Image(image.into()),
513:             projection,
514:             // The main pass tonemaps the composited result exactly once,
515:             // like the legacy in-view shells.
516:             Tonemapping::None,
517:             Msaa::Off,
518:             RenderLayers::layer(CLOUD_OFFSCREEN_LAYER),
519:             Transform::IDENTITY,
520:         ));
521:     });
522: }
