524: /// Bakes one endpoint from a stable tactical eye point into the upper dome's
525: /// angular coordinates. Runtime sees the same coherent clouds as a ray march
526: /// without repeating that integration every frame.
527: fn cloud_bake_image(request: &CloudBakeRequest) -> Image {
528:     let mut pixels = Vec::with_capacity(
529:         CLOUD_BAKE_TEXTURE_WIDTH as usize
530:             * CLOUD_BAKE_TEXTURE_HEIGHT as usize
531:             * CLOUD_BAKE_CHANNELS,
532:     );
533:     let reference_eye = Vec3::new(0.0, CLOUD_BAKE_REFERENCE_EYE_METRES, 0.0);
534:     let advection_metres = request.advection_metres();
535:     let evolution = request.evolution();
536:     for y in 0..CLOUD_BAKE_TEXTURE_HEIGHT {
537:         for x in 0..CLOUD_BAKE_TEXTURE_WIDTH {
538:             let direction = cloud_bake_direction(x, y);
539:             let mut optical_depth = 0.0;
540:             let mut lighting = 0.0;
541:             let mut variation = 0.0;
542:             for (slot, layer) in request.key.layers.iter().flatten().enumerate() {
543:                 let Some((start, end)) = cloud_ray_layer_interval(reference_eye, direction, *layer)
544:                 else {
545:                     continue;
546:                 };
547:                 let step = (end - start) / CLOUD_BAKE_VERTICAL_SAMPLES as f32;
548:                 for sample in 0..CLOUD_BAKE_VERTICAL_SAMPLES {
549:                     let distance = start + (sample as f32 + 0.5) * step;
550:                     let position = reference_eye + direction * distance;
551:                     let height = ((cloud_shell_altitude(position) - layer.bottom_metres)
552:                         / layer.thickness_metres)
553:                         .clamp(0.0, 1.0);
554:                     let density = baked_cloud_density(
555:                         position.xz() - advection_metres,
556:                         height,
557:                         *layer,
558:                         request.key.seed,
559:                         ActiveCloudLayerOrdinal::new(slot),
560:                         evolution,
561:                     );
562:                     let contribution = density * step * 0.001_45;
563:                     optical_depth += contribution;
564:                     let detail = cloud_bake_lighting_variation(
565:                         position.xz() - advection_metres,
566:                         height,
567:                         *layer,
568:                         request.key.seed,
569:                         ActiveCloudLayerOrdinal::new(slot),
570:                         evolution,
571:                     );
572:                     lighting += contribution * (0.18 + height * 0.76) * (0.18 + detail * 0.82);
573:                     variation += contribution * detail;
574:                 }
575:             }
576:             let alpha = 1.0 - (-optical_depth).exp();
577:             let lighting = if optical_depth > 0.0001 {
578:                 lighting / optical_depth
579:             } else {
580:                 0.0
581:             };
582:             let variation = if optical_depth > 0.0001 {
583:                 variation / optical_depth
584:             } else {
585:                 0.0
586:             };
587:             let sun_transmission = (-optical_depth * (0.45 + variation * 0.55)).exp();
588:             pixels.extend([
589:                 (alpha * 255.0).round() as u8,
590:                 (lighting.clamp(0.0, 1.0) * 255.0).round() as u8,
591:                 (sun_transmission * 255.0).round() as u8,
592:                 (variation.clamp(0.0, 1.0) * 255.0).round() as u8,
593:             ]);
594:         }
595:     }
596:     let mut image = Image::new(
597:         Extent3d {
598:             width: CLOUD_BAKE_TEXTURE_WIDTH,
599:             height: CLOUD_BAKE_TEXTURE_HEIGHT,
600:             depth_or_array_layers: 1,

601:         },
602:         TextureDimension::D2,
603:         pixels,
604:         TextureFormat::Rgba8Unorm,
605:         RenderAssetUsages::RENDER_WORLD,
606:     );
607:     use bevy::image::{ImageAddressMode, ImageSamplerDescriptor};
608:     image.sampler = ImageSampler::Descriptor(ImageSamplerDescriptor {
609:         address_mode_u: ImageAddressMode::ClampToEdge,
610:         address_mode_v: ImageAddressMode::ClampToEdge,
611:         ..ImageSamplerDescriptor::linear()
612:     });
613:     image
614: }
