616: /// Maps the same equirectangular UV as the dome mesh: U is azimuth and V is
617: /// elevation. The first and final columns intentionally evaluate the exact
618: /// same ray, allowing clamp sampling to cross the visible seam continuously.
619: fn cloud_bake_direction(x: u32, y: u32) -> Vec3 {
620:     let azimuth_index = if x == CLOUD_BAKE_AZIMUTH_SEGMENTS {
621:         0
622:     } else {
623:         x
624:     };
625:     let azimuth =
626:         (azimuth_index as f32 / CLOUD_BAKE_AZIMUTH_SEGMENTS as f32 - 0.5) * core::f32::consts::TAU;
627:     let elevation = y as f32 / CLOUD_BAKE_ELEVATION_SEGMENTS as f32 * core::f32::consts::FRAC_PI_2;
628:     let horizontal = elevation.cos();
629:     Vec3::new(
630:         horizontal * azimuth.cos(),
631:         elevation.sin(),
632:         horizontal * azimuth.sin(),
633:     )
634: }
635: 
636: fn cloud_shell_altitude(position: Vec3) -> f32 {
637:     (position - Vec3::new(0.0, -CLOUD_CURVATURE_RADIUS_METRES, 0.0)).length()
638:         - CLOUD_CURVATURE_RADIUS_METRES
639: }
640: 
641: fn cloud_ray_layer_interval(
642:     origin: Vec3,
643:     direction: Vec3,
644:     layer: CloudLayerParameters,
645: ) -> Option<(f32, f32)> {
646:     let center = Vec3::new(0.0, -CLOUD_CURVATURE_RADIUS_METRES, 0.0);
647:     let roots = |radius: f32| {
648:         let relative = origin - center;
649:         let projected = relative.dot(direction);
650:         let discriminant = projected * projected - (relative.length_squared() - radius * radius);
651:         (discriminant >= 0.0).then(|| {
652:             Vec2::new(
653:                 -projected - discriminant.sqrt(),
654:                 -projected + discriminant.sqrt(),
655:             )
656:         })
657:     };
658:     let inner = roots(CLOUD_CURVATURE_RADIUS_METRES + layer.bottom_metres)?;
659:     let outer =
660:         roots(CLOUD_CURVATURE_RADIUS_METRES + layer.bottom_metres + layer.thickness_metres)?;
661:     let start = inner.y.max(0.0);
662:     // Match the former ray marcher: distant grazing intersections beyond the
663:     // tactical cloud horizon are not part of the rendered volume.
664:     let end = outer.y.min(CLOUD_DOME_DISTANCE_METRES);
665:     (end > start).then_some((start, end))
666: }
667: 
668: fn baked_cloud_density(
669:     world: Vec2,
670:     height: f32,
671:     layer: CloudLayerParameters,
672:     seed: Seed,
673:     slot: ActiveCloudLayerOrdinal,
674:     evolution: f32,
675: ) -> f32 {
676:     let kind = layer.profile as u32;
677:     let coordinate = cloud_density_coordinate(world, height, layer, seed, evolution);
678:     // Broad coverage, domain warp, and fine erosion all sample a genuine
679:     // finite 3-D lattice. Height is an independent coordinate, not a planar
680:     // translation, so integrating a ray cannot turn a single 2-D field into
681:     // radial wedges.
682:     let warp = noise::density_warp(coordinate, seed, slot);
683:     let warped = coordinate + warp * Vec3::new(0.85, 0.42, 0.85);
684:     // Three incommensurate, non-periodic frequencies form clustered lobes;
685:     // no individual octave can reveal a repeated cell over the dome.
686:     let broad = non_periodic_value_noise_3d(
687:         warped * 0.58,
688:         streams::BROAD.seed(seed, &[slot.context_word()]),
689:     ) * 0.29
690:         + non_periodic_value_noise_3d(
691:             warped * 1.23,
692:             streams::MEDIUM.seed(seed, &[slot.context_word()]),
693:         ) * 0.44
694:         + non_periodic_value_noise_3d(
695:             warped * 2.61,
696:             streams::FINE.seed(seed, &[slot.context_word()]),
697:         ) * 0.27;
698:     let detail = non_periodic_value_noise_3d(
699:         warped * 5.9 + Vec3::new(9.7, 1.3, 4.1),
700:         streams::DETAIL.seed(seed, &[slot.context_word()]),
701:     );
702:     let profile = cloud_vertical_profile(height, kind, broad);
703:     let mut threshold = 0.78 - layer.coverage * 0.34;
704:     if matches!(kind, 4 | 6 | 7 | 9) {
705:         threshold -= 0.08;
706:     }
707:     if kind == 0 {
708:         // Representative fair-weather coverage needs cores above the stable
709:         // tactical reference point, not only at long grazing paths.
710:         threshold += height * 0.07 - 0.24;
711:     }
712:     if kind == 3 {
713:         threshold += height * 0.24 - smoothstep(0.68, 0.82, height) * 0.11;
714:         threshold -= 0.10;
715:     }
716:     if kind == 10 {
717:         threshold += height * 0.14;
718:     }
719:     let body = if matches!(kind, 4 | 6 | 7 | 9) {
720:         smoothstep(threshold, threshold + 0.17, broad) * (0.58 + detail * 0.50)
721:     } else {
722:         smoothstep(threshold, threshold + 0.16, broad - (1.0 - detail) * 0.20)
723:     };
724:     (body * profile * layer.density).clamp(0.0, 1.35)
725: }
726: 
727: fn cloud_density_coordinate(
728:     world: Vec2,
729:     height: f32,
730:     layer: CloudLayerParameters,
731:     seed: Seed,
732:     evolution: f32,
733: ) -> CloudDensityCoordinate {
734:     let family_scale = match layer.profile as u32 {
735:         2 => Vec2::new(0.32, 1.8),
736:         5 | 8 => Vec2::splat(1.75),
737:         4 | 6 | 7 | 9 => Vec2::splat(0.58),
738:         _ => Vec2::ONE,
739:     };
740:     let seed_offset = layer.seed + (seed.to_u64() & 0x0fff) as f32;
741:     let mut coordinate = Vec3::new(
742:         world.x * layer.horizontal_scale + seed_offset * 0.013,
743:         height * 1.8 + seed_offset * 0.007,
744:         world.y * layer.horizontal_scale - seed_offset * 0.011,
745:     );
746:     // Slow non-rigid evolution changes cell edges between endpoints. Known
747:     // horizontal wind translation is handled separately and removed by the
748:     // runtime warp before the two optical solutions are blended.
749:     coordinate += Vec3::new(evolution * 0.37, evolution, -evolution * 0.23);
750:     coordinate.x *= family_scale.x;
751:     coordinate.z *= family_scale.y;
752:     CloudDensityCoordinate::from_layer_axes(coordinate)
753: }
754: 
755: fn cloud_bake_lighting_variation(
756:     world: Vec2,
757:     height: f32,
758:     layer: CloudLayerParameters,
759:     seed: Seed,
760:     slot: ActiveCloudLayerOrdinal,
761:     evolution: f32,
762: ) -> f32 {
763:     non_periodic_value_noise_3d(
764:         cloud_density_coordinate(world, height, layer, seed, evolution) * 3.17
765:             + Vec3::new(2.1, 7.3, 11.9),
766:         streams::VERTICAL.seed(seed, &[slot.context_word()]),
767:     )
768: }
769: 
770: fn cloud_vertical_profile(height: f32, kind: u32, noise: f32) -> f32 {
771:     match kind {
772:         0 => smoothstep(0.0, 0.08, height) * (1.0 - smoothstep(0.58 + noise * 0.2, 1.0, height)),
773:         1 => smoothstep(0.0, 0.13, height) * (1.0 - smoothstep(0.72, 1.0, height)),
774:         2 => (1.0 - smoothstep(0.08, 0.34, (height - 0.52).abs())) * (0.55 + noise * 0.45),
775:         3 => (smoothstep(0.0, 0.035, height)
776:             * (1.0 - smoothstep(0.78 + noise * 0.12, 1.0, height)))
777:         .max(smoothstep(0.68, 0.78, height) * (1.0 - smoothstep(0.9, 1.0, height)) * 0.85),
778:         4 | 6 | 7 => {
779:             smoothstep(0.0, if kind == 4 { 0.06 } else { 0.12 }, height)
780:                 * (1.0 - smoothstep(if kind == 4 { 0.82 } else { 0.9 }, 1.0, height))
781:         }
782:         5 => (1.0 - smoothstep(0.18, 0.46, (height - 0.5).abs())) * (0.7 + noise * 0.3),
783:         8 => (1.0 - smoothstep(0.12, 0.34, (height - 0.52).abs())) * (0.65 + noise * 0.35),
784:         9 => 1.0 - smoothstep(0.24, 0.48, (height - 0.5).abs()),
785:         _ => smoothstep(0.0, 0.05, height) * (1.0 - smoothstep(0.72 + noise * 0.18, 1.0, height)),
786:     }
787: }
788: 
789: fn cloud_hemisphere_mesh() -> Mesh {
790:     // The mesh supplies only view directions. This moderate tessellation keeps
791:     // a smooth horizon while eliminating the old ray-march proxy density.
792:     const AZIMUTH_SEGMENTS: u32 = 128;
793:     const ELEVATION_SEGMENTS: u32 = 64;
794:     let mut positions =
795:         Vec::with_capacity(((AZIMUTH_SEGMENTS + 1) * (ELEVATION_SEGMENTS + 1)) as usize);
796:     let mut normals = Vec::with_capacity(positions.capacity());
797:     let mut uvs = Vec::with_capacity(positions.capacity());
798:     for elevation_index in 0..=ELEVATION_SEGMENTS {
799:         let elevation =
800:             elevation_index as f32 / ELEVATION_SEGMENTS as f32 * core::f32::consts::FRAC_PI_2;
801:         let horizontal = elevation.cos();
802:         let y = elevation.sin();
803:         for azimuth_index in 0..=AZIMUTH_SEGMENTS {
804:             let azimuth = azimuth_index as f32 / AZIMUTH_SEGMENTS as f32 * core::f32::consts::TAU;
805:             let direction = Vec3::new(horizontal * azimuth.cos(), y, horizontal * azimuth.sin());
806:             positions.push((direction * CLOUD_DOME_DISTANCE_METRES).to_array());
807:             normals.push(direction.to_array());
808:             uvs.push([
809:                 azimuth_index as f32 / AZIMUTH_SEGMENTS as f32,
810:                 elevation_index as f32 / ELEVATION_SEGMENTS as f32,
811:             ]);
812:         }
813:     }
814:     let mut indices = Vec::with_capacity((AZIMUTH_SEGMENTS * ELEVATION_SEGMENTS * 6) as usize);
815:     let stride = AZIMUTH_SEGMENTS + 1;
816:     for elevation_index in 0..ELEVATION_SEGMENTS {
817:         for azimuth_index in 0..AZIMUTH_SEGMENTS {
818:             let lower_left = elevation_index * stride + azimuth_index;
819:             let lower_right = lower_left + 1;
820:             let upper_left = lower_left + stride;
821:             let upper_right = upper_left + 1;
822:             indices.extend_from_slice(&[
823:                 lower_left,
824:                 upper_left,
825:                 lower_right,
826:                 lower_right,
827:                 upper_left,
828:                 upper_right,
829:             ]);
830:         }
831:     }
832:     let mut mesh = Mesh::new(
833:         PrimitiveTopology::TriangleList,
834:         RenderAssetUsages::RENDER_WORLD | RenderAssetUsages::MAIN_WORLD,
835:     );
836:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
837:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
838:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
839:     mesh.insert_indices(Indices::U32(indices));
840:     mesh
841: }
