843: #[expect(
844:     clippy::too_many_arguments,
845:     reason = "Bevy injects cloud scene state, lighting, capture controls, and material storage independently"
846: )]
847: pub(in crate::presentation) fn update_tactical_clouds(
848:     _time: Res<Time>,
849:     active: Res<ActiveTacticalScene>,
850:     environments: Query<&SceneEnvironment>,
851:     celestial: Res<PresentedCelestialLighting>,
852:     capture: Res<TacticalCloudCaptureOverride>,
853:     settings: Res<super::TacticalGraphicsSettings>,
854:     isolation: Res<TacticalCloudBenchmarkIsolation>,
855:     camera: Single<&GlobalTransform, With<TacticalGameplayCamera>>,
856:     mut clouds: Query<(
857:         &mut TacticalCloudLayer,
858:         &MeshMaterial3d<TacticalCloudMaterial>,
859:         &mut Transform,
860:         &mut Visibility,
861:     )>,
862:     mut composites: Query<
863:         &mut Transform,
864:         (With<TacticalCloudComposite>, Without<TacticalCloudLayer>),
865:     >,
866:     mut materials: ResMut<Assets<TacticalCloudMaterial>>,
867:     mut images: ResMut<Assets<Image>>,
868:     mut bake_state: ResMut<CloudBakeState>,
869:     mut animation_status: ResMut<TacticalCloudAnimationStatus>,
870:     prebaked: Option<Res<PrebakedCloudEnvironment>>,
871: ) {
872:     for mut transform in &mut composites {
873:         transform.translation = camera.translation();
874:     }
875:     animation_status.ready = false;
876:     let environment = active
877:         .entity
878:         .and_then(|entity| environments.get(entity).ok());
879:     let celestial = celestial.snapshot.as_ref();
880:     let layers = environment
881:         .map(|environment| CloudLayerParameters::layers_from_environment(environment, capture.0));
882: 
883:     for (mut cloud, handle, mut transform, mut visibility) in &mut clouds {
884:         transform.translation = camera.translation();
885:         let Some(environment) = environment else {
886:             cloud.active = false;
887:             *visibility = cloud_visibility(cloud.active, *isolation);
888:             continue;
889:         };
890:         let Some(celestial) = celestial else {
891:             cloud.active = false;
892:             *visibility = cloud_visibility(false, *isolation);
893:             continue;
894:         };
895:         let Some(layers) = layers else {
896:             cloud.active = false;
897:             *visibility = cloud_visibility(false, *isolation);
898:             continue;
899:         };
900:         if layers

901:             .iter()
902:             .flatten()
903:             .all(|layer| layer.coverage <= 0.001 || layer.density <= 0.001)
904:         {
905:             cloud.active = false;
906:             *visibility = cloud_visibility(cloud.active, *isolation);
907:             continue;
908:         }
909:         let seed = cloud_seed(environment);
910:         let bake_key = CloudBakeKey { layers, seed };
911:         let Some(mut material) = materials.get_mut(&handle.0) else {
912:             continue;
913:         };
914:         if bake_state.key.as_ref() != Some(&bake_key) {
915:             #[cfg(not(target_family = "wasm"))]
916:             {
917:                 bake_state.pending = None;
918:             }
919:             bake_state.queued = None;
920:             bake_state.elapsed_seconds = 0.0;
921:             bake_state.end_ready = false;
922: 
923:             if let Some(prebaked) = prebaked.as_deref() {
924:                 let initial = image_from_rgba8(prebaked.rgba8);
925:                 if let Some(mut image) = images.get_mut(&material.baked_texture_a) {
926:                     *image = initial.clone();
927:                 }
928:                 if let Some(mut image) = images.get_mut(&material.baked_texture_b) {
929:                     *image = initial;
930:                 }
931:             }
932:             bake_state.key = Some(bake_key.clone());
933:             #[cfg(not(target_family = "wasm"))]
934:             {
935:                 let wind_velocity = cloud_wind_velocity(environment);
936:                 bake_state.pending = Some(spawn_cloud_bake(CloudBakeRequest {
937:                     key: bake_key.clone(),
938:                     endpoint: u64::from(prebaked.is_some()),
939:                     wind_velocity,
940:                 }));
941:             }
942:         }
943: 
944:         #[cfg(not(target_family = "wasm"))]
945:         advance_cloud_bake_pipeline(
946:             &mut bake_state,
947:             &mut material,
948:             &mut images,
949:             if isolation.freeze_animation {
950:                 0.0
951:             } else {
952:                 _time.delta_secs()
953:             },
954:         );
955:         let representative_altitude = cloud_representative_altitude(layers);
956:         let storminess = layers
957:             .iter()
958:             .flatten()
959:             .any(|layer| matches!(layer.profile as u32, 3 | 7)) as u8
960:             as f32;
961:         cloud.active = true;
962:         let daylight = smoothstep(-8.0, 8.0, celestial.sun_altitude_degrees);
963:         let scene_luminance = 0.08 + daylight * 1.35;
964:         let solar_color = cloud_solar_color(celestial.sun_altitude_degrees);
965:         material.lighting = celestial.sun_direction.extend(scene_luminance);
966:         let blend = if bake_state.end_ready {
967:             (bake_state.elapsed_seconds / CLOUD_ANIMATION_INTERVAL_SECONDS).clamp(0.0, 1.0)
968:         } else {
969:             0.0
970:         };
971:         let wind_velocity = cloud_wind_velocity(environment);
972:         material.shape = Vec4::new(
973:             storminess,
974:             blend,
975:             CLOUD_ANIMATION_INTERVAL_SECONDS,
976:             CLOUD_BAKE_REFERENCE_EYE_METRES,
977:         );
978:         material.layer = Vec4::new(representative_altitude, 1.0, 0.0, 0.0);
979:         material.motion = Vec4::new(
980:             wind_velocity.x,
981:             wind_velocity.y,
982:             daylight,
983:             celestial.weather_transmission,
984:         );
985:         material.spectral = solar_color.extend(
986:             settings
987:                 .config
988:                 .rendering
989:                 .clouds
990:                 .quality_scale
991:                 .clamp(0.35, 1.0),
992:         );
993:         material.geometry = cloud_shell_geometry();
994:         #[cfg(not(target_family = "wasm"))]
995:         {
996:             animation_status.ready = bake_state.end_ready && bake_state.queued.is_some();
997:         }
998:         #[cfg(target_family = "wasm")]
999:         {
1000:             animation_status.ready = true;
1001:         }
1002:         *visibility = cloud_visibility(true, *isolation);
1003:     }
1004: }
