1006: fn cloud_wind_velocity(environment: &SceneEnvironment) -> Vec2 {
1007:     let bearing = f32::from(environment.weather.atmosphere.wind_direction_degrees).to_radians();
1008:     let speed = bps(environment.weather.wind_speed_bps) * CLOUD_MAX_WIND_METRES_PER_SECOND;
1009:     Vec2::new(bearing.sin(), -bearing.cos()) * speed
1010: }
1011: 
1012: fn cloud_representative_altitude(layers: [Option<CloudLayerParameters>; 3]) -> f32 {
1013:     let mut weighted_altitude = 0.0;
1014:     let mut total_weight = 0.0;
1015:     for layer in layers.into_iter().flatten() {
1016:         let weight = (layer.coverage * layer.density).max(0.001);
1017:         weighted_altitude += (layer.bottom_metres + layer.thickness_metres * 0.5) * weight;
1018:         total_weight += weight;
1019:     }
1020:     if total_weight > 0.0 {
1021:         weighted_altitude / total_weight
1022:     } else {
1023:         2_000.0
1024:     }
1025: }
