1028: fn spawn_cloud_bake(request: CloudBakeRequest) -> Task<CompletedCloudBake> {
1029:     AsyncComputeTaskPool::get().spawn(async move {
1030:         let image = cloud_bake_image(&request);
1031:         CompletedCloudBake { request, image }
1032:     })
1033: }
