1035: #[cfg(not(target_family = "wasm"))]
1036: fn advance_cloud_bake_pipeline(
1037:     state: &mut CloudBakeState,
1038:     material: &mut TacticalCloudMaterial,
1039:     images: &mut Assets<Image>,
1040:     delta_seconds: f32,
1041: ) {
1042:     if state.pending.as_ref().is_some_and(Task::is_finished) {
1043:         let completed = block_on(
1044:             state
1045:                 .pending
1046:                 .take()
1047:                 .expect("finished cloud bake task remains present"),
1048:         );
1049:         if let Some(next_request) = install_completed_cloud_bake(state, material, images, completed)
1050:         {
1051:             state.pending = Some(spawn_cloud_bake(next_request));
1052:         }
1053:     }
1054: 
1055:     if !state.end_ready {
1056:         return;
1057:     }
1058:     state.elapsed_seconds =
1059:         (state.elapsed_seconds + delta_seconds).min(CLOUD_ANIMATION_INTERVAL_SECONDS);
1060:     if state.elapsed_seconds < CLOUD_ANIMATION_INTERVAL_SECONDS {
1061:         return;
1062:     }
1063:     let Some(completed) = state.queued.take() else {
1064:         return;
1065:     };
1066: 
1067:     let recycled = material.baked_texture_a.clone();
1068:     material.baked_texture_a = material.baked_texture_b.clone();
1069:     material.baked_texture_b = recycled;
1070:     if let Some(mut image) = images.get_mut(&material.baked_texture_b) {
1071:         *image = completed.image;
1072:     }
1073:     state.elapsed_seconds = 0.0;
1074:     state.pending = Some(spawn_cloud_bake(CloudBakeRequest {
