1081: #[cfg(not(target_family = "wasm"))]
1082: fn install_completed_cloud_bake(
1083:     state: &mut CloudBakeState,
1084:     material: &mut TacticalCloudMaterial,
1085:     images: &mut Assets<Image>,
1086:     completed: CompletedCloudBake,
1087: ) -> Option<CloudBakeRequest> {
1088:     if state.key.as_ref() != Some(&completed.request.key) {
1089:         return None;
1090:     }
1091:     if state.end_ready {
1092:         state.queued = Some(completed);
1093:         return None;
1094:     }
1095:     if completed.request.endpoint == 0
1096:         && let Some(mut image) = images.get_mut(&material.baked_texture_a)
1097:     {
1098:         *image = completed.image.clone();
1099:     }
1100:     if let Some(mut image) = images.get_mut(&material.baked_texture_b) {
1101:         *image = completed.image;
1102:     }
1103:     state.end_ready = true;
1104:     state.elapsed_seconds = 0.0;
1105:     Some(CloudBakeRequest {
1106:         key: completed.request.key,
1107:         endpoint: completed.request.endpoint + 1,
1108:         wind_velocity: completed.request.wind_velocity,
1109:     })
1110: }
