1150: fn smoothstep(edge0: f32, edge1: f32, value: f32) -> f32 {
1151:     let t = ((value - edge0) / (edge1 - edge0)).clamp(0.0, 1.0);
1152:     t * t * (3.0 - 2.0 * t)
1153: }
1154: 
1155: fn cloud_solar_color(sun_altitude_degrees: f32) -> Vec3 {
1156:     let warmth = 1.0 - smoothstep(4.0, 22.0, sun_altitude_degrees);
1157:     Vec3::ONE.lerp(Vec3::new(1.0, 0.78, 0.60), warmth)
1158: }
