3: /// Presentation-owned selector for the one playable tactical scene.
4: ///
5: /// Scene data remains authoritative on its entity. This resource only makes
6: /// the presentation-wide choice explicit: the most recently activated live
7: /// scene entity wins, and removal deterministically falls back to the prior
8: /// live scene.
9: #[derive(Resource, Debug, Clone, Default)]
10: pub(in crate::presentation) struct ActiveTacticalScene {
11:     pub(in crate::presentation) entity: Option<Entity>,
12:     activation_order: Vec<Entity>,
13: }
14: 
15: pub(in crate::presentation) fn activate_tactical_scene(
16:     event: On<Add, SceneEnvironment>,
17:     mut active: ResMut<ActiveTacticalScene>,
18: ) {
19:     active
20:         .activation_order
21:         .retain(|entity| *entity != event.entity);
22:     active.activation_order.push(event.entity);
23:     active.entity = Some(event.entity);
24: }
25: 
26: pub(in crate::presentation) fn refresh_active_tactical_scene(
27:     environments: Query<(), With<SceneEnvironment>>,
28:     mut active: ResMut<ActiveTacticalScene>,
29: ) {
30:     let selected = active
31:         .activation_order
32:         .iter()
33:         .rev()
34:         .copied()
35:         .find(|entity| environments.contains(*entity));
36:     if selected == active.entity
37:         && active
38:             .activation_order
39:             .iter()
40:             .all(|entity| environments.contains(*entity))
41:     {
42:         return;
43:     }
44:     active
45:         .activation_order
46:         .retain(|entity| environments.contains(*entity));
47:     active.entity = selected;
48: }
