50: /// Solar source energy presented to Bevy's atmosphere. This remains available
51: /// while the Sun is below the horizon so
52: /// the atmosphere can scatter civil and nautical twilight. Bevy's atmosphere
53: /// transmittance and visible-disc calculation prevent this source from lighting
54: /// ground surfaces from below the planet horizon.
55: pub(super) fn scene_atmosphere_solar_illuminance(environment: &SceneEnvironment) -> f32 {
56:     let intensity = bps(environment.weather.intensity_bps);
57:     let precipitation_transmission = match environment.weather.precipitation {
58:         Precipitation::Clear => 1.0,
59:         Precipitation::Rain => 0.62 - intensity * 0.27,
60:         Precipitation::Snow => 0.72 - intensity * 0.22,
61:     };
62:     let transmission = cloud_solar_transmission(environment.weather) * precipitation_transmission;
63:     lux::RAW_SUNLIGHT * transmission.clamp(0.25, 1.0)
64: }
65: 
66: pub(super) fn cloud_solar_transmission(weather: WeatherSnapshot) -> f32 {
67:     weather
68:         .cloud_layers()
69:         .fold(1.0, |transmission, layer| {
70:             let coverage = bps(layer.coverage_bps);
71:             let density = bps(layer.optical_density_bps);
72:             transmission * (1.0 - coverage * density * 0.82)
73:         })
74:         .clamp(0.12, 1.0)
75: }
76: 
77: pub(super) fn scene_distance_fog(environment: &SceneEnvironment) -> DistanceFog {
78:     let intensity = bps(environment.weather.intensity_bps);
79:     let humidity = ((f32::from(environment.weather.atmosphere.relative_humidity_bps) - 7_000.0)
80:         / 3_000.0)
81:         .clamp(0.0, 1.0);
82:     let low_stratus = environment
83:         .weather
84:         .atmosphere
85:         .low_cloud
86:         .is_some_and(|layer| matches!(layer.form, CloudForm::Stratus) && layer.base_metres <= 250);
87:     let clear_air_fog = if low_stratus {
88:         humidity.max(0.8)
89:     } else {
90:         humidity * humidity * 0.65
91:     };
92:     let (start, end, color) = match environment.weather.precipitation {
93:         // Even clear continental air loses contrast over kilometres. Starting
94:         // the blend beyond tactical ranges gives regional ridges and tree
95:         // lines depth without washing out nearby gameplay silhouettes.
96:         Precipitation::Clear => (
97:             2_500.0 + (120.0 - 2_500.0) * clear_air_fog,
98:             42_000.0 + (1_800.0 - 42_000.0) * clear_air_fog,
99:             Color::srgb_u8(188, 201, 207),
100:         ),
101:         Precipitation::Rain => {
102:             // Rain curtains provide structured mid-distance extinction, while
103:             // this ordinary depth fog supplies the unresolved droplets between
104:             // them. Pull it into tactical range only for genuinely heavy rain;
105:             // light showers retain long visibility without volumetric lighting.
106:             let downpour = smoothstep(0.45, 0.92, intensity);
107:             let ordinary_start = 800.0 + 3_500.0 * (1.0 - intensity);
108:             let ordinary_end = 3_000.0 + 14_000.0 * (1.0 - intensity);
109:             (
110:                 ordinary_start + (40.0 - ordinary_start) * downpour,
111:                 ordinary_end + (340.0 - ordinary_end) * downpour,
112:                 Color::srgb_u8(112, 126, 135),
113:             )
114:         }
115:         Precipitation::Snow => (
116:             600.0 + 2_500.0 * (1.0 - intensity),
117:             2_500.0 + 10_000.0 * (1.0 - intensity),
118:             Color::srgb_u8(207, 216, 220),
119:         ),
120:     };
121:     DistanceFog {
122:         color,
123:         falloff: FogFalloff::Linear { start, end },
124:         ..default()
125:     }
126: }
127: 
128: pub(super) fn scene_night_factor(
129:     sun_altitude_degrees: f32,
130:     moon_altitude_degrees: f32,
131:     lunar_illumination: f32,
132: ) -> f32 {
133:     let daylight = smoothstep(-8.0, 2.0, sun_altitude_degrees);
134:     let moon = lunar_illumination * smoothstep(-2.0, 8.0, moon_altitude_degrees);
135:     (daylight + moon * 0.12).clamp(0.0, 1.0)
136: }
137: 
138: pub(super) fn scene_ambient_response(
139:     sun_altitude_degrees: f32,
140:     moon_altitude_degrees: f32,
141:     lunar_illumination: f32,
142: ) -> f32 {
143:     let daylight = smoothstep(-8.0, 4.0, sun_altitude_degrees);
144:     let moon = lunar_illumination * smoothstep(-2.0, 8.0, moon_altitude_degrees);
145:     (0.05 + daylight * 0.23 + moon * 0.04).clamp(0.05, 0.28)
146: }
147: 
148: fn smoothstep(edge0: f32, edge1: f32, value: f32) -> f32 {
149:     let t = ((value - edge0) / (edge1 - edge0)).clamp(0.0, 1.0);
150:     t * t * (3.0 - 2.0 * t)
151: }
152: 
153: fn tactical_msaa(anti_aliasing: AntiAliasingConfig) -> Msaa {
154:     // Browser WebGPU only exposes 1x and 4x hardware MSAA; sample count 2 is a
155:     // wgpu-native-only capability and fails device validation in the browser
156:     // (the whole renderer quits on the invalid multisampled textures). Fablegeist
157:     // renders identically on native and web, so we never emit Sample2 -- any
158:     // configured sample count resolves to 4x, which both backends support.
159:     // Fixed-function resolve is particularly valuable for thin grass and branch
160:     // silhouettes.
161:     match anti_aliasing {
162:         AntiAliasingConfig::Msaa { .. } => Msaa::Sample4,
163:         _ => Msaa::Off,
164:     }
165: }
