167: fn tactical_tonemapping(tonemapping: TonemappingConfig) -> Tonemapping {
168:     match tonemapping {
169:         TonemappingConfig::None => Tonemapping::None,
170:         TonemappingConfig::AcesFitted => Tonemapping::AcesFitted,
171:         TonemappingConfig::AgX => Tonemapping::AgX,
172:         TonemappingConfig::TonyMcMapface => Tonemapping::TonyMcMapface,
173:     }
174: }
