66: pub(super) fn jobs(
67:     ticket: PreparationTicket,
68:     document_json: &str,
69:     graphics: &str,
70: ) -> PreparationResult<Vec<String>> {
71:     ticket.require_owner(PresentationOwner::RegionalMap)?;
72:     let products = staged_products(ticket)?;
73:     let document: RegionalCityInput = serde_json::from_str(document_json)?;
74:     crate::presentation::config::TacticalGraphicsConfig::parse(graphics)
75:         .map_err(|message| PreparationError::GraphicsConfiguration { message })?;
76:     let mut jobs = Vec::new();
77:     if !products
78:         .regional_city
79:         .as_ref()
80:         .is_some_and(|city| city.matches(&document, graphics))
81:     {
82:         jobs.push(GenerationJob::RegionalCity {
83:             input: Box::new(document.clone()),
84:             graphics: graphics.into(),
85:         });
86:     }
87:     let mut programs = Vec::new();
88:     for placement in document.input().physical_placements() {
89:         if !products.resident_facades().contains(&placement.program)
90:             && !programs.contains(&placement.program)
91:         {
92:             programs.push(placement.program);
93:         }
94:     }
95:     jobs.extend(
96:         programs
97:             .into_iter()
98:             .map(|program| GenerationJob::Building(Box::new(program))),
99:     );
100:     jobs.into_iter()
101:         .map(|job| serde_json::to_string(&job).map_err(PreparationError::from))
102:         .collect()
103: }

