205: pub(super) fn cancel(ticket: PreparationTicket) -> PreparationResult<()> {
206:     let mut residency = residency()?;
207:     let slot = residency.owner_mut(ticket.owner);
208:     if slot.preparing == Some(ticket) {
209:         slot.preparing = None;
210:         slot.staged = Default::default();
211:     }
212:     if slot
213:         .completed
214:         .as_ref()
215:         .is_some_and(|snapshot| snapshot.ticket == ticket)
216:     {
217:         slot.completed = None;
218:     }
219:     Ok(())
220: }
