223: /// Starting another request cannot replace dependencies of pending old meshes.
224: pub(crate) fn activate(
225:     ticket: PreparationTicket,
226:     input: &TacticalSceneInput,
227: ) -> PreparationResult<PreparedStrategicScene> {
228:     ticket.require_owner(PresentationOwner::Scene)?;
229:     let mut residency = residency()?;
230:     let slot = residency.owner_mut(PresentationOwner::Scene);
231:     let snapshot = slot
232:         .completed
233:         .as_ref()
234:         .filter(|snapshot| snapshot.ticket == ticket)
235:         .ok_or(PreparationError::StalePreparation)?;
236:     if snapshot.input != PreparationInputIdentity::from_input(input)? {
237:         return Err(PreparationError::PreparationInputMismatch);
238:     }
239:     let scene = snapshot.products.generated_scene(input)?;
240:     if let Some(snapshot) = slot.completed.take() {
241:         slot.active = snapshot.products;
242:     }
