2: use super::*;
3: use adventuresim_tactical_core::scene_input::furniture::FurnitureLayout;
4: use adventuresim_tactical_core::scene_input::{GeneratedBuilding, GeneratedBuildingRecipes};
5: 
6: impl PreparedStrategicScene {
7:     pub(super) fn from_products(
8:         input: &TacticalSceneInput,
9:         products: &PreparedProducts,
10:     ) -> PreparationResult<Self> {
11:         let mut scene = Self {
12:             digest: input.digest()?,
13:             buildings: Vec::new(),
14:             building_recipes: Default::default(),
15:             furniture: Default::default(),
16:         };
17:         scene.building_recipes.sites = products.sites.clone();
18:         for placement in &products.placements {
19:             if let Some(primary) = input
20:                 .buildings
21:                 .iter()
22:                 .find(|primary| primary.id == placement.id)
23:             {
24:                 if primary != placement {
25:                     return Err(PreparationError::SceneBindingsMismatch);
26:                 }
27:             } else {
28:                 let distant = input
29:                     .distant_buildings
30:                     .iter()
31:                     .find(|distant| distant.id == placement.id)
32:                     .ok_or(PreparationError::MissingDistantPlacement {
33:                         building: placement.id,
34:                     })?;
35:                 if *placement != (*distant).into() {
36:                     return Err(PreparationError::PromotedPlacementMismatch {
37:                         building: placement.id,
38:                     });
39:                 }
40:             }
41:             let venue = products
42:                 .venues
43:                 .iter()
44:                 .find(|venue| venue.recipe.program == placement.program)
45:                 .ok_or(PreparationError::NotPrepared {
46:                     product: ProductKind::Venue,
47:                 })?;
48:             scene.building_recipes.insert(venue.recipe.clone());
49:             let building = GeneratedBuilding {
50:                 placement: placement.clone(),
51:                 plan: venue.recipe.plan.clone(),
52:                 collision: venue.recipe.collision.clone(),
53:             };
54:             scene
55:                 .furniture
56:                 .install_interior(&building, venue.interior.clone())?;
57:             scene.buildings.push(building);
58:         }
59:         if input.buildings.iter().any(|primary| {
60:             !scene
61:                 .buildings
62:                 .iter()
63:                 .any(|building| building.placement == *primary)
64:         }) {
65:             return Err(PreparationError::SceneBindingsMismatch);
66:         }
67:         Ok(scene)
68:     }
69: }

