6: #[test]
7: #[ignore = "writes explicit benchmark scene inputs to STRATEGIC_TRAVEL_FIXTURE_DIR"]
8: fn distinct_city_inputs_validate_occupied_layouts() {
9:     let output = std::env::var("STRATEGIC_TRAVEL_FIXTURE_DIR").expect("fixture output directory");
10:     std::fs::create_dir_all(&output).unwrap();
11:     let base: TacticalSceneInput = serde_json::from_str(include_str!(
12:         "../../../../../assets/tactical-scenes/massive-city.json"
13:     ))
14:     .unwrap();
15:     let request: venue::VenueRequest = serde_json::from_value(serde_json::json!({
16:         "places": [
17:             {"id":"public-square","kind":"square"}, {"id":"residences","kind":"residence"},
18:             {"id":"keep","kind":"keep"}, {"id":"merchants","kind":"market"},
19:             {"id":"weapons","kind":"smith"}, {"id":"armor","kind":"armor"},
20:             {"id":"clothing","kind":"tailor"}, {"id":"herbalist","kind":"apothecary"},
21:             {"id":"books","kind":"books"}, {"id":"inn","kind":"inn"},
22:             {"id":"religion","kind":"church"}
23:         ], "people": []
24:     }))
25:     .unwrap();
26:     let occupied = request.placements(&base);
27:     for (index, (offset, destination_seeds)) in [1_u64, 1001]
28:         .into_iter()
29:         .zip(DESTINATION_SEEDS.iter())
30:         .enumerate()
31:     {
32:         let mut input = base.clone();
33:         input.seed = input.seed.wrapping_offset(offset);
34:         input.scene_key = format!("travel-distinct-{}", index + 1);
35:         for &DestinationSeed { building, seed } in destination_seeds {
36:             if let Some(placement) = input.buildings.iter_mut().find(|p| p.id == building) {
37:                 placement.program.seed = seed;
38:             } else {
39:                 input
40:                     .distant_buildings
41:                     .iter_mut()
42:                     .find(|p| p.id == building)
43:                     .unwrap()
44:                     .seed = seed;
45:             }
46:         }
47:         let destinations = request.placements(&input);
48:         assert_eq!(destinations.len(), destination_seeds.len());
49:         for placement in destinations {
50:             let original = occupied.iter().find(|p| p.id == placement.id).unwrap();
51:             assert_ne!(original.program, placement.program);
52:             let recipe =
53:                 adventuresim_tactical_core::scene_input::GeneratedBuildingRecipe::generate(
54:                     placement.program,
55:                 )
56:                 .unwrap();
57:             adventuresim_building_generator::interior::furnish(&recipe.plan, &recipe.program)
58:                 .unwrap();
59:         }
60:         input.generate().unwrap();
61:         let path =
62:             std::path::Path::new(&output).join(format!("travel-distinct-{}.json", index + 1));
63:         std::fs::write(path, serde_json::to_vec(&input).unwrap()).unwrap();
64:         println!(
65:             "validated destination {}: {} distinct occupied programs",
66:             index + 1,
67:             occupied.len()
68:         );
69:     }
70: }
