28: impl VenueRequest {
29:     pub(super) fn placements(&self, input: &TacticalSceneInput) -> Vec<TacticalBuildingPlacement> {
30:         let mut placements = input.buildings.clone();
31:         for place in &self.places {
32:             let operators = self
33:                 .people
34:                 .iter()
35:                 .filter(|p| p.place == place.id)
36:                 .map(|p| p.id.0);
37:             let Some(id) = select_building(input, place.kind, operators) else {
38:                 continue;
39:             };
40:             if placements.iter().any(|p| p.id == id) {
41:                 continue;
42:             }
43:             if let Some(distant) = input.distant_buildings.iter().find(|p| p.id == id) {
44:                 placements.push((*distant).into());
45:             }
46:         }
47:         placements
48:     }
49: }
