65: #[derive(Clone, Serialize, Deserialize)]
66: pub(in crate::presentation) struct PreparedBatch {
67:     pub material: BuildingLodMaterial,
68:     #[serde(with = "super::packed")]
69:     positions: Vec<[f32; 3]>,
70:     #[serde(with = "super::packed")]
71:     normals: Vec<[f32; 3]>,
72:     #[serde(with = "super::packed")]
73:     uvs: Vec<[f32; 2]>,
74:     #[serde(with = "super::packed")]
75:     tangents: Vec<[f32; 4]>,
76:     #[serde(with = "super::packed")]
77:     indices: Vec<u32>,
78: }
79: 
80: impl PreparedBatch {
81:     pub(in crate::presentation) fn triangle_count(&self) -> usize {
82:         self.indices.len() / 3
83:     }
84: 
85:     fn new(batch: &LodMesh, origin: Vec3) -> Self {
86:         let mut mesh = super::super::recipe_mesh::recipe_mesh(batch, origin);
87:         let Some(VertexAttributeValues::Float32x3(positions)) =
88:             mesh.remove_attribute(Mesh::ATTRIBUTE_POSITION)
89:         else {
90:             unreachable!()
91:         };
92:         let Some(VertexAttributeValues::Float32x3(normals)) =
93:             mesh.remove_attribute(Mesh::ATTRIBUTE_NORMAL)
94:         else {
95:             unreachable!()
96:         };
97:         let Some(VertexAttributeValues::Float32x2(uvs)) =
98:             mesh.remove_attribute(Mesh::ATTRIBUTE_UV_0)
99:         else {
100:             unreachable!()
101:         };
102:         let tangents = match mesh.remove_attribute(Mesh::ATTRIBUTE_TANGENT) {
103:             Some(VertexAttributeValues::Float32x4(values)) => values,
104:             None => Vec::new(),
105:             _ => unreachable!(),
106:         };
107:         Self {
108:             material: batch.material,
109:             positions,
110:             normals,
111:             uvs,
112:             tangents,
113:             indices: batch.indices.clone(),
114:         }
115:     }
116: 
117:     pub(in crate::presentation) fn into_mesh(self) -> Mesh {
118:         let mut mesh = Mesh::new(
119:             PrimitiveTopology::TriangleList,
120:             RenderAssetUsages::MAIN_WORLD | RenderAssetUsages::RENDER_WORLD,
121:         );
122:         mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, self.positions);
123:         mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, self.normals);
124:         mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, self.uvs);
125:         if !self.tangents.is_empty() {
126:             mesh.insert_attribute(Mesh::ATTRIBUTE_TANGENT, self.tangents);
127:         }
128:         mesh.insert_indices(Indices::U32(self.indices));
129:         mesh
130:     }
131: }
