133: impl PreparedVenue {
134:     pub(super) fn generate(
135:         program: BuildingProgram,
136:         recipe: Option<GeneratedBuildingRecipe>,
137:     ) -> PreparationResult<Self> {
138:         let recipe = match recipe {
139:             Some(recipe) if recipe.program == program => recipe,
140:             Some(_) => return Err(PreparationError::ProductMismatch),
141:             None => GeneratedBuildingRecipe::generate(program)?,
142:         };
143:         let origin = recipe.collision.bounds.centre()?.metres();
144:         let batches = |meshes: Vec<LodMesh>| {
145:             meshes
146:                 .iter()
147:                 .map(|batch| PreparedBatch::new(batch, origin))
148:                 .collect()
149:         };
150:         let geometry = VenueGeometry {
151:             detail: batches(compile_static_building_detail(&recipe.plan)?.meshes),
152:             facade: batches(
153:                 compile_static_building_lod(&recipe.plan, BuildingLodLevel::Facade)?.meshes,
154:             ),
155:             shell: batches(compile_building_lod(&recipe.plan, BuildingLodLevel::Shell)?.meshes),
156:         };
157:         let interior = furnish(&recipe.plan, &recipe.program)?;
158:         Ok(Self {
159:             recipe,
160:             interior,
161:             geometry: Some(Arc::new(geometry)),
162:         })
163:     }
164: }
