33: // A 32 x 32 grid preserves the established macro-patch footprint and overlap
34: // while reducing the close interactive sward to the density that still reads
35: // as individual grass at its short 10 m range. Density lives inside the shared
36: // mesh rather than in more ECS entities, so extraction and visibility costs
37: // stay bounded.
38: const GRASS_PATCH_GRID_SIDE: usize = 32;
39: // Deliberately stylized for third-person readability: the former 19 mm body
40: // became too thin once centreline lean stopped being misread as shader width.
41: // Taper still converges to one zero-width terminal vertex.
42: const GRASS_BLADE_WIDTH_METRES: f32 = 0.076;
43: // Far and Vista retain one deterministic Near root per square stratum. The
44: // hashed root within each stratum prevents the reduced meshes from exposing a
45: // Cartesian row pattern, while the strata preserve uniform coverage and exact
46: // Near-root correspondence through the LOD crossfade.
47: const GRASS_FAR_STRATUM_SIDE: usize = 4;
48: const GRASS_VISTA_STRATUM_SIDE: usize = 8;
49: /// The terrain begins replacing the physical coverage removed by the Far LOD
50: /// during the same dithered interval that exchanges Near blades for Far
51: /// survivors. This is deliberately shared with [`grass_lod_visibility`] so
52: /// neither representation can expose a bare circular band.
53: pub(in crate::presentation) const NEAR_TO_FAR_SWARD_FADE_START_METRES: f32 = 7.0;
54: pub(in crate::presentation) const NEAR_TO_FAR_SWARD_FADE_END_METRES: f32 = 14.0;
55: /// Far retains an evenly spaced 8-by-8 subset of Near's 32-by-32 roots. Dense
56: /// Near ribbons overlap heavily in screen space, so removed root count
57: /// overstates the optical coverage that the terrain must replace. This
58: /// calibrated fraction leaves the unchanged wide Far survivors carrying part
59: /// of the sward instead of double-darkening the transition with solid ground.
60: pub(in crate::presentation) const FAR_LOD_GAP_FILL_FRACTION: f32 = 0.75;
61: /// The final physical-grass fade overlaps the terrain's band-limited sward.
62: /// Keeping these bounds here makes the playable and vista lattices share the
63: /// same terminal representation contract.
64: pub(in crate::presentation) const TERMINAL_SWARD_FADE_START_METRES: f32 = 42.0;
65: pub(in crate::presentation) const TERMINAL_SWARD_FADE_END_METRES: f32 = 50.0;
66: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
67: pub(in crate::presentation) enum GrassMeshLod {
68:     Near,
69:     /// Instanced-only outer ring of the near band. Same tuft placements as
70:     /// `Near`, but a thinner blade grid at reduced ribbon vertices: past ~9 m
71:     /// individual blades stop being countable while the near band's area is
72:     /// dominated by this ring (area grows with radius squared).
73:     NearEdge,
74:     Far,
75:     /// Patch-level vista representation. Broad five-vertex tuft ribbons carry
76:     /// the field here instead of merely thinning the close-range blade mesh.
77:     Vista,
78: }
79: 
80: impl GrassMeshLod {
81:     /// Position of this tier in the instanced renderer's per-tier batch array.
82:     pub(in crate::presentation) const fn tier_index(self) -> usize {
83:         match self {
84:             Self::Near => 0,
85:             Self::NearEdge => 1,
86:             Self::Far => 2,
87:             Self::Vista => 3,
88:         }
89:     }
90: 
91:     fn configured_tier(self, grass: &GrassConfig) -> &GrassTierConfig {
92:         match self {
93:             Self::Near => &grass.lod.near,
94:             Self::NearEdge => &grass.lod.near_edge,
95:             Self::Far => &grass.lod.far,
96:             Self::Vista => &grass.lod.vista,
97:         }
98:     }
99: 
100:     fn row_heights(self) -> &'static [f32] {
101:         match self {
102:             // Five paired rows plus a shared tip: eleven vertices preserve the
103:             // original base, shoulder, tip, and monotonic UV progression while
104:             // removing two intermediate ribbon segments from ordinary Near
105:             // grass.
106:             Self::Near => &[0.0, 0.22, 0.45, 0.68, 0.9],
107:             // Instanced-only outer near ring. Four paired rows plus a shared
108:             // tip: nine vertices keep the ribbon bend readable while shedding
109:             // cost past the countable-blade distance.
110:             Self::NearEdge => &[0.0, 0.3, 0.58, 0.83],
111:             // Three paired rows plus a shared tip: seven vertices at distance.
112:             Self::Far => &[0.0, 0.45, 0.82],
113:             Self::Vista => &[0.0, 0.62],
114:         }
115:     }
116: 
117:     fn blade_grid_indices(self, grass_density: f32) -> impl Iterator<Item = usize> {
118:         (0..GRASS_PATCH_GRID_SIDE * GRASS_PATCH_GRID_SIDE).filter(move |index| {
119:             let row = index / GRASS_PATCH_GRID_SIDE;
120:             let column = index % GRASS_PATCH_GRID_SIDE;
121:             let selected_for_lod = self.selects_grid_root(row, column);
122:             selected_for_lod
123:                 && (grass_density >= 1.0
124:                     || streams::DENSITY
125:                         .rng(0.into(), &[*index as u64])
126:                         .inclusive_unit_f32()
127:                         < grass_density)
128:         })
129:     }
130: 
131:     fn selects_grid_root(self, row: usize, column: usize) -> bool {
132:         let (stratum_side, purpose) = match self {
133:             // Both near tiers keep every grid root; `NearEdge` is instanced-only
134:             // and never reaches the legacy stratified selection.
135:             Self::Near | Self::NearEdge => return true,
136:             Self::Far => (GRASS_FAR_STRATUM_SIDE, streams::FAR_ROOT),
137:             Self::Vista => (GRASS_VISTA_STRATUM_SIDE, streams::VISTA_ROOT),
138:         };
139:         let strata_per_side = GRASS_PATCH_GRID_SIDE / stratum_side;
140:         let stratum_row = row / stratum_side;
141:         let stratum_column = column / stratum_side;
142:         let stratum = stratum_row * strata_per_side + stratum_column;
143:         let mut random = purpose.rng(0.into(), &[stratum as u64]);
144:         let selected_row = if stratum_row == 0 {
145:             0
146:         } else if stratum_row + 1 == strata_per_side {
147:             GRASS_PATCH_GRID_SIDE - 1
148:         } else {
149:             stratum_row * stratum_side + random.index(stratum_side)
150:         };
151:         let selected_column = if stratum_column == 0 {
152:             0
153:         } else if stratum_column + 1 == strata_per_side {
154:             GRASS_PATCH_GRID_SIDE - 1
155:         } else {
156:             stratum_column * stratum_side + random.index(stratum_side)
157:         };
158:         row == selected_row && column == selected_column
159:     }
160: 
161:     fn blade_count(self, grass_density: f32) -> usize {
162:         self.blade_grid_indices(grass_density).count()
163:     }
164: 
165:     pub(in crate::presentation) fn width_compensation(self, grass_density: f32) -> f32 {
166:         match self {
167:             Self::Near => return 1.0,
168:             // Compensates the thinned instanced edge tuft (6x6) against the near
169:             // tuft (8x8) so projected ground cover holds through the sub-tier
170:             // crossfade. Instanced-only; the legacy renderer never asks for it.
171:             Self::NearEdge => return (64.0_f32 / 36.0).sqrt(),
172:             // Vista represents small tufts, but must not become the broad
173:             // rectangular cards that were conspicuous in traversal views.
174:             Self::Vista => return 1.8,
175:             Self::Far => {}
176:         }
177:         // Compensate only for blades discarded by the Far LOD. The square-root
178:         // response retains clumped negative space while keeping projected
179:         // cover close to Near through the crossfade.
180:         let near_count =
181:             (GRASS_PATCH_GRID_SIDE * GRASS_PATCH_GRID_SIDE) as f32 * grass_density.clamp(0.0, 1.0);
182:         let lod_count = Self::Far.blade_count(grass_density).max(1) as f32;
183:         (near_count.max(1.0) / lod_count).sqrt().min(1.65)
184:     }
185: }
