349: pub(in crate::presentation) fn grass_species(
350:     community: GrassCommunity,
351:     hash: Seed,
352: ) -> GrassSpecies {
353:     let (species, weights) = match community {
354:         GrassCommunity::MesicMeadow => (
355:             [GrassSpecies::FalseOatGrass, GrassSpecies::Cocksfoot],
356:             [68, 32],
357:         ),
358:         GrassCommunity::LeanSward => (
359:             [GrassSpecies::RedFescue, GrassSpecies::CommonBent],
360:             [64, 36],
361:         ),
362:         GrassCommunity::WetTussock => (
363:             [GrassSpecies::TuftedHairGrass, GrassSpecies::YorkshireFog],
364:             [66, 34],
365:         ),
366:     };
367:     let index = streams::SPECIES
368:         .rng(hash, &[])
369:         .weighted_index(&weights)
370:         .expect("authored species weights are positive");
371:     species[index]
372: }
