388:     }
389: 
390:     fn inflorescence_branch_count(self) -> usize {
391:         match self {
392:             Self::FalseOatGrass => 2,
393:             Self::Cocksfoot => 3,
394:             Self::CommonBent | Self::TuftedHairGrass => 4,
395:             Self::RedFescue | Self::YorkshireFog => 0,
396:         }
397:     }
398: 
399:     fn spikelets_per_branch(self) -> usize {
400:         match self {
401:             Self::Cocksfoot | Self::TuftedHairGrass => 3,
402:             Self::FalseOatGrass | Self::CommonBent => 2,
403:             Self::RedFescue | Self::YorkshireFog => 0,
404:         }
405:     }
406: 
407:     fn height_scale(self) -> f32 {
408:         match self {
409:             Self::FalseOatGrass => 1.24,
410:             Self::Cocksfoot => 0.94,
411:             Self::RedFescue => 0.64,
412:             Self::CommonBent => 0.78,
413:             Self::TuftedHairGrass => 1.08,
414:             Self::YorkshireFog => 0.82,
415:         }
416:     }
417: 
418:     fn width_scale(self) -> f32 {
419:         match self {
420:             Self::FalseOatGrass => 0.88,
421:             Self::Cocksfoot => 1.34,
422:             Self::RedFescue => 0.48,
423:             Self::CommonBent => 0.58,
424:             Self::TuftedHairGrass => 0.76,
425:             Self::YorkshireFog => 1.04,
426:         }
427:     }
428: 
429:     fn pigment_scale(self) -> [f32; 3] {
430:         match self {
431:             Self::FalseOatGrass => [1.02, 1.0, 0.84],
432:             Self::Cocksfoot => [0.72, 0.86, 0.74],
433:             Self::RedFescue => [0.80, 0.86, 0.72],
434:             Self::CommonBent => [0.92, 0.94, 0.78],
435:             Self::TuftedHairGrass => [0.82, 0.90, 0.82],
436:             Self::YorkshireFog => [1.02, 0.94, 0.88],
437:         }
438:     }
439: }
440: 
441: fn grass_ribbon_patch_mesh_with_rows(
442:     width: f32,
443:     height: f32,
444:     color: Color,
445:     lod: GrassMeshLod,
446:     blades: &[GrassBlade],
447:     rows: &[f32],
448: ) -> Mesh {
449:     let vertices_per_blade = rows.len() * 2 + 1;
450:     let triangles_per_blade = (rows.len() - 1) * 2 + 1;
451:     let mut positions = Vec::with_capacity(blades.len() * vertices_per_blade);
452:     let mut normals = Vec::with_capacity(blades.len() * vertices_per_blade);
453:     let mut uvs = Vec::with_capacity(blades.len() * vertices_per_blade);
454:     let mut blade_roots = Vec::with_capacity(blades.len() * vertices_per_blade);
455:     let mut colors = Vec::with_capacity(blades.len() * vertices_per_blade);
456:     let mut indices = Vec::with_capacity(blades.len() * triangles_per_blade * 3);
457:     let mut inflorescences = Vec::new();
458:     let linear = color.to_linear().to_f32_array();
459: 
460:     for &GrassBlade {
461:         offset_x,
462:         offset_z,
463:         height_scale,
464:         width_scale,
465:         seed: blade_seed,
466:         species,
467:     } in blades
468:     {
469:         let root = Vec3::new(offset_x, 0.0, offset_z);
470:         let hash = streams::BLADE_STYLE.seed(blade_seed, &[]);
471:         let angle = streams::blade_angle(hash);
472:         let half_width = Vec3::new(angle.cos(), 0.0, angle.sin())
473:             * width
474:             * width_scale
475:             * species.width_scale()
476:             * 0.5;
477:         let normal = Vec3::Y.cross(half_width).normalize_or_zero().to_array();
478:         let blade_threshold = streams::BLADE_THRESHOLD.rng(hash, &[]).inclusive_unit_f32();
479:         let age = streams::AGE.rng(hash, &[]).inclusive_unit_f32();
480:         let lean_direction = Vec3::new(-angle.sin(), 0.0, angle.cos());
481:         let lean_metres = height
482:             * height_scale
483:             * species.height_scale()
484:             * (0.008 + streams::LEAN.rng(hash, &[]).inclusive_unit_f32() * 0.027);
485:         // Healthy blades share their species pigment. Senescent tips retain a
486:         // hard straw region, while blade separation comes from the material's
487:         // specular response rather than randomized albedo.
488:         let species_scale = species.pigment_scale();
489:         let blade_color = [
490:             (linear[0] * species_scale[0]).clamp(0.0, 1.0),
491:             (linear[1] * species_scale[1]).clamp(0.0, 1.0),
492:             (linear[2] * species_scale[2]).clamp(0.0, 1.0),
493:             blade_threshold,
494:         ];
495:         let luminance = blade_color[0] * 0.2126 + blade_color[1] * 0.7152 + blade_color[2] * 0.0722;
496:         let straw_color = [luminance * 1.12, luminance * 0.88, luminance * 0.42];
497:         let senescent = age > 0.82;
498:         let base = positions.len() as u32;
499: 
500:         for &height_fraction in rows {

501:             let taper = (1.0 - height_fraction).powf(0.72);
502:             let side = half_width * taper;
503:             let centre = root
504:                 + Vec3::Y * height * height_scale * species.height_scale() * height_fraction
505:                 + lean_direction * lean_metres * height_fraction.powf(1.65);
506:             positions.extend_from_slice(&[(centre - side).to_array(), (centre + side).to_array()]);
507:             normals.extend_from_slice(&[normal; 2]);
508:             uvs.extend_from_slice(&[[0.0, height_fraction], [1.0, height_fraction]]);
509:             blade_roots.extend_from_slice(&[[offset_x, offset_z]; 2]);
510:             let row_color = if senescent && height_fraction >= 0.72 {
511:                 [
512:                     straw_color[0],
513:                     straw_color[1],
514:                     straw_color[2],
515:                     blade_threshold,
516:                 ]
517:             } else {
518:                 blade_color
519:             };
520:             colors.extend_from_slice(&[row_color; 2]);
521:         }
522:         positions.push(
523:             (root
524:                 + Vec3::Y * height * height_scale * species.height_scale()
525:                 + lean_direction * lean_metres)
526:                 .to_array(),
527:         );
528:         normals.push(normal);
529:         uvs.push([0.5, 1.0]);
530:         blade_roots.push([offset_x, offset_z]);
531:         colors.push(if senescent {
532:             [
533:                 straw_color[0],
534:                 straw_color[1],
535:                 straw_color[2],
536:                 blade_threshold,
537:             ]
538:         } else {
539:             blade_color
540:         });
541: 
542:         for row in 0..rows.len() - 1 {
543:             let lower = base + (row * 2) as u32;
544:             let upper = lower + 2;
545:             indices.extend_from_slice(&[lower, lower + 1, upper + 1, lower, upper + 1, upper]);
546:         }
547:         let shoulder = base + ((rows.len() - 1) * 2) as u32;
548:         let tip = base + (vertices_per_blade - 1) as u32;
549:         indices.extend_from_slice(&[shoulder, shoulder + 1, tip]);
550: 
551:         // Seed heads are sparse Near-only geometry. Close cocksfoot reads as
552:         // compact offset clusters and oat/bent/hair-grass as open panicles;
553:         // ordinary ribbons remain smoothly pointed at every LOD. Only about
554:         // one shoot in eight bears a seed head, keeping the cost bounded and
555:         // avoiding sub-pixel triangles at distance.
556:         let branch_count = species.inflorescence_branch_count();
557:         if lod == GrassMeshLod::Near
558:             && branch_count > 0
559:             && streams::PANICLE.rng(hash, &[]).inclusive_unit_f32() < 0.125
560:         {
561:             let total_height = height * height_scale * species.height_scale();
562:             inflorescences.push(GrassInflorescence {
563:                 root,
564:                 angle,
565:                 total_height,
566:                 species,
567:                 normal,
568:                 color: blade_color,
569:                 blade_root: [offset_x, offset_z],
570:             });
571:         }
572:     }
573: 
574:     for GrassInflorescence {
575:         root,
576:         angle,
577:         total_height,
578:         species,
579:         normal,
580:         color,
581:         blade_root,
582:     } in inflorescences
583:     {
584:         let compact = species == GrassSpecies::Cocksfoot;
585:         let branch_count = species.inflorescence_branch_count();
586:         let stem_side = Vec3::new(angle.cos(), 0.0, angle.sin()) * 0.0025;
587:         for (start_fraction, end_fraction) in [(0.62, 0.82), (0.82, 1.03)] {
588:             let start = root + Vec3::Y * total_height * start_fraction;
589:             let end = root + Vec3::Y * total_height * end_fraction;
590:             append_attached_quad(
591:                 &mut positions,
592:                 &mut normals,
593:                 &mut uvs,
594:                 &mut blade_roots,
595:                 &mut colors,
596:                 &mut indices,
597:                 start - stem_side,
598:                 start + stem_side,
599:                 end - stem_side * 0.62,
600:                 end + stem_side * 0.62,
601:                 normal,
602:                 color,
603:                 blade_root,
604:                 start.y,
605:                 start_fraction,
606:             );
607:         }
608: 
609:         for branch in 0..branch_count {
610:             let fraction = branch as f32 / branch_count as f32;
611:             let side_sign = if branch % 2 == 0 { 1.0 } else { -1.0 };
612:             let branch_angle = angle + side_sign * (0.72 + fraction * 0.38);
613:             let direction = Vec3::new(branch_angle.cos(), 0.0, branch_angle.sin());
614:             let length = if compact {
615:                 0.035 + fraction * 0.022
616:             } else {
617:                 0.075 + fraction * 0.055
618:             };
619:             let thickness = if compact { 0.010 } else { 0.005 };
620:             let start = root
621:                 + Vec3::Y
622:                     * total_height
623:                     * (if compact {
624:                         0.78 + fraction * 0.045
625:                     } else {
626:                         0.70 + fraction * 0.055
627:                     });
628:             let end = start
629:                 + direction * length
630:                 + Vec3::Y * total_height * if compact { 0.018 } else { 0.045 };
631:             let side = Vec3::new(-direction.z, 0.0, direction.x) * thickness;
632:             let attachment_fraction = start.y / total_height;
633:             append_attached_quad(
634:                 &mut positions,
635:                 &mut normals,
636:                 &mut uvs,
637:                 &mut blade_roots,
638:                 &mut colors,
639:                 &mut indices,
640:                 start - side,
641:                 start + side,
642:                 end - side * 0.55,
643:                 end + side * 0.55,
644:                 normal,
645:                 color,
646:                 blade_root,
647:                 start.y,
648:                 attachment_fraction,
649:             );
650: 
651:             for spikelet in 0..species.spikelets_per_branch() {
652:                 let along = if compact {
653:                     0.52 + spikelet as f32 * 0.18
654:                 } else {
655:                     0.64 + spikelet as f32 * 0.27
656:                 };
657:                 let centre = start.lerp(end, along.min(1.0));
658:                 append_crossed_spikelet(
659:                     &mut positions,
660:                     &mut normals,
661:                     &mut uvs,
662:                     &mut blade_roots,
663:                     &mut colors,
664:                     &mut indices,
665:                     centre,
666:                     direction,
667:                     if compact { 0.008 } else { 0.005 },
668:                     if compact { 0.014 } else { 0.010 },
669:                     color,
670:                     blade_root,
671:                     start.y,
672:                     attachment_fraction,
673:                 );
674:             }
675:         }
676:     }
677: 
678:     let mut mesh = Mesh::new(
679:         PrimitiveTopology::TriangleList,
680:         RenderAssetUsages::RENDER_WORLD,
681:     );
682:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
683:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
684:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
685:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_1, blade_roots);
686:     mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, colors);
687:     mesh.insert_indices(Indices::U32(indices));
688:     mesh
689: }
690: 
691: #[expect(
692:     clippy::too_many_arguments,
693:     reason = "this domain boundary names each independent input explicitly"
694: )]
695: fn append_attached_quad(
696:     positions: &mut Vec<[f32; 3]>,
697:     normals: &mut Vec<[f32; 3]>,
698:     uvs: &mut Vec<[f32; 2]>,
699:     blade_roots: &mut Vec<[f32; 2]>,
700:     colors: &mut Vec<[f32; 4]>,
701:     indices: &mut Vec<u32>,
702:     lower_left: Vec3,
703:     lower_right: Vec3,
704:     upper_left: Vec3,
705:     upper_right: Vec3,
706:     normal: [f32; 3],
707:     color: [f32; 4],
708:     blade_root: [f32; 2],
709:     attachment_height: f32,
710:     attachment_fraction: f32,
711: ) {
712:     let base = positions.len() as u32;
713:     positions.extend_from_slice(&[
714:         lower_left.to_array(),
715:         lower_right.to_array(),
716:         upper_left.to_array(),
717:         upper_right.to_array(),
718:     ]);
719:     normals.extend_from_slice(&[normal; 4]);
720:     // Negative V identifies rigid seed-head geometry. U carries its authored
721:     // stalk attachment height so the shader can preserve the mesh while
722:     // inheriting the parent shoot's deformation.
723:     uvs.extend_from_slice(&[[attachment_height, -attachment_fraction]; 4]);
724:     blade_roots.extend_from_slice(&[blade_root; 4]);
725:     colors.extend_from_slice(&[color; 4]);
726:     indices.extend_from_slice(&[base, base + 1, base + 3, base, base + 3, base + 2]);
727: }
728: 
729: #[expect(
730:     clippy::too_many_arguments,
731:     reason = "this domain boundary names each independent input explicitly"
732: )]
733: fn append_crossed_spikelet(
734:     positions: &mut Vec<[f32; 3]>,
735:     normals: &mut Vec<[f32; 3]>,
736:     uvs: &mut Vec<[f32; 2]>,
737:     blade_roots: &mut Vec<[f32; 2]>,
738:     colors: &mut Vec<[f32; 4]>,
739:     indices: &mut Vec<u32>,
740:     centre: Vec3,
741:     branch_direction: Vec3,
742:     half_width: f32,
743:     half_height: f32,
744:     color: [f32; 4],
745:     blade_root: [f32; 2],
746:     attachment_height: f32,
747:     attachment_fraction: f32,
748: ) {
749:     let horizontal =
750:         Vec3::new(-branch_direction.z, 0.0, branch_direction.x).normalize_or_zero() * half_width;

751:     let along = branch_direction.normalize_or_zero() * half_width;
752:     for side in [horizontal, along] {
753:         let normal = Vec3::Y.cross(side).normalize_or_zero().to_array();
754:         append_attached_quad(
755:             positions,
756:             normals,
757:             uvs,
758:             blade_roots,
759:             colors,
760:             indices,
761:             centre - Vec3::Y * half_height,
762:             centre - side,
763:             centre + side,
764:             centre + Vec3::Y * half_height,
765:             normal,
766:             color,
767:             blade_root,
768:             attachment_height,
769:             attachment_fraction,
770:         );
771:     }
772: }
