1044:     fn ordinary_blade_ribbons_reconstruct_to_pointed_nondegenerate_tips() {
1045:         let species = [
1046:             GrassSpecies::FalseOatGrass,
1047:             GrassSpecies::Cocksfoot,
1048:             GrassSpecies::RedFescue,
1049:             GrassSpecies::CommonBent,
1050:             GrassSpecies::TuftedHairGrass,
1051:             GrassSpecies::YorkshireFog,
1052:         ];
1053: 
1054:         for lod in [GrassMeshLod::Near, GrassMeshLod::Far, GrassMeshLod::Vista] {
1055:             for species in species {
1056:                 let mesh = grass_ribbon_patch_mesh(
1057:                     0.026,
1058:                     0.82,
1059:                     Color::WHITE,
1060:                     lod,
1061:                     &[GrassBlade {
1062:                         offset_x: 0.0,
1063:                         offset_z: 0.0,
1064:                         height_scale: 1.0,
1065:                         width_scale: 1.0,
1066:                         seed: fabelgeist_determinism::Seed::from_u64(0),
1067:                         species,
1068:                     }],
1069:                 );
1070:                 let positions = mesh
1071:                     .attribute(Mesh::ATTRIBUTE_POSITION)
1072:                     .and_then(VertexAttributeValues::as_float3)
1073:                     .expect("ordinary blades should retain authored positions");
1074:                 let normals = mesh
1075:                     .attribute(Mesh::ATTRIBUTE_NORMAL)
1076:                     .and_then(VertexAttributeValues::as_float3)
1077:                     .expect("ordinary blades should retain authored normals");
1078:                 let Some(VertexAttributeValues::Float32x2(uvs)) =
1079:                     mesh.attribute(Mesh::ATTRIBUTE_UV_0)
1080:                 else {
1081:                     panic!("ordinary blades should retain side and height metadata");
1082:                 };
1083:                 let paired_rows = lod.row_heights().len();
1084:                 let widths = positions[..paired_rows * 2]
1085:                     .as_chunks::<2>()
1086:                     .0
1087:                     .iter()
1088:                     .map(|row| Vec3::from_array(row[0]).distance(Vec3::from_array(row[1])))
1089:                     .collect::<Vec<_>>();
1090:                 assert!(
1091:                     widths.windows(2).all(|pair| pair[1] < pair[0]),
1092:                     "{species:?} {lod:?} ordinary blade must narrow at every row"
1093:                 );
1094:                 let tip_index = paired_rows * 2;
1095:                 let shoulder = tip_index - 2;
1096:                 assert!(
1097:                     uvs[tip_index] == [0.5, 1.0],
1098:                     "the shared tip must carry the centre-vertex UV contract"
1099:                 );
1100:                 let indices = mesh.indices().unwrap().iter().collect::<Vec<_>>();
1101:                 let ordinary_index_count = ((paired_rows - 1) * 2 + 1) * 3;
1102:                 assert_eq!(
1103:                     &indices[ordinary_index_count - 3..ordinary_index_count],
1104:                     &[shoulder, shoulder + 1, tip_index],
1105:                     "the final primitive must be one shoulder-to-tip triangle"
1106:                 );
1107: 
1108:                 let normal = Vec3::from_array(normals[0]);
1109:                 let local_side = Vec2::new(-normal.z, normal.x).normalize();
1110:                 let reconstruct = |index: usize| {
1111:                     let authored = Vec3::from_array(positions[index]);
1112:                     let authored_half_width =
1113:                         Vec2::new(authored.x, authored.z).dot(local_side).abs();
1114:                     let half_width = if (uvs[index][0] - 0.5).abs() < 0.001 {
1115:                         0.0
1116:                     } else {
1117:                         authored_half_width
1118:                     };
1119:                     let signed_side = if uvs[index][0] >= 0.5 { 1.0 } else { -1.0 };
1120:                     Vec3::new(
1121:                         local_side.x * half_width * signed_side,
1122:                         authored.y,
1123:                         local_side.y * half_width * signed_side,
1124:                     )
1125:                 };
1126:                 let left = reconstruct(shoulder);
1127:                 let right = reconstruct(shoulder + 1);
1128:                 let tip = reconstruct(tip_index);
1129:                 assert!(
1130:                     Vec2::new(positions[tip_index][0], positions[tip_index][2]).length() > 0.0,
1131:                     "the fixture must exercise an authored centreline lean"
1132:                 );
1133:                 assert_eq!(Vec2::new(tip.x, tip.z), Vec2::ZERO);
1134:                 let terminal_area = (right - left).cross(tip - left).length() * 0.5;
1135:                 assert!(
1136:                     terminal_area > 0.00001,
1137:                     "{species:?} {lod:?} reconstructed terminal triangle must remain visible"
1138:                 );
1139:             }
1140:         }
