1: //! Spatially coherent grass communities and local habitat selection.
2: use super::*;
3: use adventuresim_tactical_core::scene_coordinates::ScenePlanPoint;
4: use fabelgeist_determinism::Seed;
5: 
6: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
7: pub(in crate::presentation) enum GrassCommunity {
8:     /// Fertile lowland hay meadow: tall false oat-grass with coarse cocksfoot clumps.
9:     MesicMeadow,
10:     /// Leaner or more exposed turf: fine red fescue with airy common bent.
11:     LeanSward,
12:     /// Damp meadow and wet woodland gap: tufted hair-grass with Yorkshire fog.
13:     WetTussock,
14: }
15: 
16: impl GrassCommunity {
17:     pub(in crate::presentation) const ALL: [Self; 3] =
18:         [Self::MesicMeadow, Self::LeanSward, Self::WetTussock];
19:     pub(in crate::presentation) const COUNT: usize = Self::ALL.len();
20: 
21:     pub(super) const fn index(self) -> usize {
22:         self as usize
23:     }
24: }
25: 
26: #[derive(Clone, Copy, Debug)]
27: pub(in crate::presentation) struct GrassCommunityProfile {
28:     pub(super) weights: [f32; GrassCommunity::COUNT],
29: }
30: 
31: impl GrassCommunityProfile {
32:     pub(in crate::presentation) fn from_environment(environment: &SceneEnvironment) -> Self {
33:         let wet = (bps(environment.wetland_bps)
34:             + bps(environment.water_bps) * 0.55
35:             + bps(environment.weather.ground_moisture_bps) * 0.35)
36:             .clamp(0.0, 1.0);
37:         let exposed = (bps(environment.hilly_bps) * 0.72
38:             + (1.0 - bps(environment.cultivation_bps)) * 0.18)
39:             .clamp(0.0, 1.0);
40:         Self::from_site_drivers(wet, exposed)
41:     }
42: 
43:     pub(super) fn from_site_drivers(wet: f32, exposed: f32) -> Self {
44:         let wet = wet.clamp(0.0, 1.0);
45:         let exposed = exposed.clamp(0.0, 1.0);
46:         let mesic = (1.0 - wet) * (1.0 - exposed * 0.55);
47:         let lean = exposed * (1.0 - wet * 0.65);
48:         // A dry scene has no token wet-tussock cells. Deschampsia and
49:         // Yorkshire fog appear only once the available moisture signal is
50:         // material, while mesic and lean communities trade off continuously.
51:         let wet_tussock = (wet - 0.18).max(0.0) * 1.25;
52:         Self {
53:             weights: [mesic.max(0.001), lean, wet_tussock],
54:         }
55:     }
56: 
57:     pub(in crate::presentation) fn localized(self, sample: EnvironmentalSample) -> Self {
58:         let surface_wet = match sample.surface {
59:             TacticalSurface::Water | TacticalSurface::Wetland => 1.0,
60:             _ => 0.0,
61:         };
62:         let wet = (bps(sample.wetland_bps) + bps(sample.water_bps) * 0.7 + surface_wet * 0.7)
63:             .clamp(0.0, 1.0);
64:         let exposed = (bps(sample.hilly_bps) * 0.8 + (1.0 - bps(sample.cultivation_bps)) * 0.12)
65:             .clamp(0.0, 1.0);
66:         let local = Self::from_site_drivers(wet, exposed);
67:         Self {
68:             weights: core::array::from_fn(|index| {
69:                 self.weights[index] * 0.35 + local.weights[index] * 0.65
70:             }),
71:         }
72:     }
73: 
74:     #[cfg(test)]
75:     fn select(self, site_hash: Seed) -> GrassCommunity {
76:         // Stable low-frequency pseudo-fields stand in for finer soil data we
77:         // do not yet have. They modulate, but never invent, a habitat that the
78:         // scene/local environmental sample assigned zero weight.
79:         let moisture_field =
80:             0.68 + streams::MOISTURE.rng(site_hash, &[]).inclusive_unit_f32() * 0.64;
81:         let exposure_field =
82:             0.68 + streams::EXPOSURE.rng(site_hash, &[]).inclusive_unit_f32() * 0.64;
83:         let fertility_field =
84:             0.76 + streams::FERTILITY.rng(site_hash, &[]).inclusive_unit_f32() * 0.48;
85:         let weights = [
86:             self.weights[0] * fertility_field,
87:             self.weights[1] * exposure_field,
88:             self.weights[2] * moisture_field,
89:         ];
90:         // Habitat interpolation is spatial math; quantize only the final
91:         // selection weights, preserving hard-zero exclusions.
92:         let weights = weights.map(|weight| {
93:             (weight * adventuresim_world_schema::BASIS_POINTS_PER_WHOLE as f32).round() as u64
94:         });
95:         let selected = streams::COMMUNITY_SPECIES
96:             .rng(site_hash, &[])
97:             .weighted_index(&weights)
98:             .expect("a grass habitat always has a positive mesic weight");
99:         [
100:             GrassCommunity::MesicMeadow,
101:             GrassCommunity::LeanSward,
102:             GrassCommunity::WetTussock,
103:         ][selected]
104:     }
105: }
