107: #[cfg(test)]
108: pub(in crate::presentation) fn grass_community_at(
109:     point: ScenePlanPoint,
110:     seed: Seed,
111:     profile: GrassCommunityProfile,
112: ) -> GrassCommunity {
113:     let point = point.metres();
114:     // Jittered Voronoi cells create coherent 12-40 m sward communities. A
115:     // patch selects one community; species vary within that community rather
116:     // than becoming independent blade-by-blade confetti.
117:     const CELL_SIZE: f32 = 24.0;
118:     let cell = (point / CELL_SIZE).floor().as_ivec2();
119:     let mut nearest_distance = f32::INFINITY;
120:     let mut nearest_hash = Seed::from_u64(0);
121:     for offset_z in -1..=1 {
122:         for offset_x in -1..=1 {
123:             let candidate = cell + bevy::math::IVec2::new(offset_x, offset_z);
124:             let hash = streams::COMMUNITY.seed(
125:                 seed,
126:                 &[candidate.x as u32 as u64, candidate.y as u32 as u64],
127:             );
128:             let site = (candidate.as_vec2()
129:                 + Vec2::new(
130:                     0.18 + streams::JITTER_X.rng(hash, &[]).inclusive_unit_f32() * 0.64,
131:                     0.18 + streams::JITTER_Z.rng(hash, &[]).inclusive_unit_f32() * 0.64,
132:                 ))
133:                 * CELL_SIZE;
134:             let distance = point.distance_squared(site);
135:             if distance < nearest_distance {
136:                 nearest_distance = distance;
137:                 nearest_hash = hash;
138:             }
139:         }
140:     }
141:     profile.select(nearest_hash)
142: }
143: 
144: /// Temporary habitat lattice shared by all tufts sampled during a scatter pass.
145: /// Site positions and random fields depend on the seed, never the local profile.
146: pub(in crate::presentation) struct GrassCommunityField {
147:     seed: Seed,
148:     sites: std::collections::BTreeMap<(i32, i32), CommunitySite>,
149:     neighbourhood: Option<(bevy::math::IVec2, [CommunitySite; 9])>,
150: }
151: 
152: #[derive(Clone, Copy)]
153: struct CommunitySite {
154:     position: Vec2,
155:     modulation: [f32; GrassCommunity::COUNT],
156:     selection: fabelgeist_determinism::Seed,
157: }
158: 
159: impl CommunitySite {
160:     fn new(cell: bevy::math::IVec2, seed: Seed) -> Self {
161:         let hash = streams::COMMUNITY.seed(seed, &[cell.x as u32 as u64, cell.y as u32 as u64]);
162:         Self {
163:             position: (cell.as_vec2()
164:                 + Vec2::new(
165:                     0.18 + streams::JITTER_X.rng(hash, &[]).inclusive_unit_f32() * 0.64,
166:                     0.18 + streams::JITTER_Z.rng(hash, &[]).inclusive_unit_f32() * 0.64,
167:                 ))
168:                 * COMMUNITY_CELL_SIZE_METRES,
169:             modulation: [
170:                 0.76 + streams::FERTILITY.rng(hash, &[]).inclusive_unit_f32() * 0.48,
171:                 0.68 + streams::EXPOSURE.rng(hash, &[]).inclusive_unit_f32() * 0.64,
172:                 0.68 + streams::MOISTURE.rng(hash, &[]).inclusive_unit_f32() * 0.64,
173:             ],
174:             selection: streams::COMMUNITY_SPECIES.seed(hash, &[]),
175:         }
176:     }
177:     fn select(self, profile: GrassCommunityProfile) -> GrassCommunity {
178:         let weights = core::array::from_fn::<_, { GrassCommunity::COUNT }, _>(|i| {
179:             (profile.weights[i]
180:                 * self.modulation[i]
181:                 * adventuresim_world_schema::BASIS_POINTS_PER_WHOLE as f32)
182:                 .round() as u64
183:         });
184:         GrassCommunity::ALL[self
185:             .selection
186:             .rng()
187:             .weighted_index(&weights)
188:             .expect("a grass habitat always has a positive mesic weight")]
189:     }
190: }
191: 
192: const COMMUNITY_CELL_SIZE_METRES: f32 = 24.0;
193: 
194: impl GrassCommunityField {
195:     pub(in crate::presentation) fn new(seed: Seed) -> Self {
196:         Self {
197:             seed,
198:             sites: Default::default(),
199:             neighbourhood: None,
200:         }
201:     }
202: 
203:     pub(in crate::presentation) fn at(
204:         &mut self,
205:         point: ScenePlanPoint,
206:         profile: GrassCommunityProfile,
207:     ) -> GrassCommunity {
208:         let point = point.metres();
209:         let cell = (point / COMMUNITY_CELL_SIZE_METRES).floor().as_ivec2();
210:         if self
211:             .neighbourhood
212:             .as_ref()
213:             .is_none_or(|(previous, _)| *previous != cell)
214:         {
215:             let sites = std::array::from_fn(|i| {
216:                 let candidate = cell + bevy::math::IVec2::new(i as i32 % 3 - 1, i as i32 / 3 - 1);
217:                 *self
218:                     .sites
219:                     .entry((candidate.x, candidate.y))
220:                     .or_insert_with(|| CommunitySite::new(candidate, self.seed))
221:             });
222:             self.neighbourhood = Some((cell, sites));
223:         }
224:         let sites = &self.neighbourhood.as_ref().unwrap().1;
225:         let mut nearest = &sites[0];
226:         let mut distance = f32::INFINITY;
227:         for site in sites {
228:             let candidate = point.distance_squared(site.position);
229:             if candidate < distance {
230:                 distance = candidate;
231:                 nearest = site;
232:             }
233:         }
