1: //! Terrain cover, slope and deterministic jitter admission for grass cells.
2: use super::streams;
3: use adventuresim_tactical_core::{
4:     prelude::{GroundCover, SceneGround, SceneTerrain},
5:     scene_coordinates::ScenePlanPoint,
6: };
7: use bevy::prelude::{Quat, Transform, Vec2, Vec3};
8: 
9: /// Applies the canonical render-centre cover and slope gates for one placement
10: /// cell in the instanced renderer.
11: pub(in crate::presentation::ground_scatter) fn cell_allows_grass(
12:     terrain: &SceneTerrain,
13:     ground: &SceneGround,
14:     cell_hash: fabelgeist_determinism::Seed,
15:     x: i32,
16:     z: i32,
17:     cell_spacing: f32,
18:     jitter_fraction: f32,
19: ) -> bool {
20:     let jitter_x = streams::JITTER_X.rng(cell_hash, &[]).inclusive_unit_f32() - 0.5;
21:     let jitter_z = streams::JITTER_Z.rng(cell_hash, &[]).inclusive_unit_f32() - 0.5;
22:     let render_centre = Vec2::new(
23:         (x as f32 + jitter_x * jitter_fraction) * cell_spacing,
24:         (z as f32 + jitter_z * jitter_fraction) * cell_spacing,
25:     );
26:     ScenePlanPoint::from_metres(render_centre)
27:         .and_then(|centre| {
28:             grass_patch_placement_with_spacing(terrain, ground, centre, cell_spacing)
29:         })
30:         .is_some()
31: }
32: 
33: fn ground_allows_grass_patch_with_spacing(
34:     ground: &SceneGround,
35:     centre: ScenePlanPoint,
36:     patch_spacing: f32,
37: ) -> bool {
38:     let half_extent = patch_spacing * 0.58;
39:     [-1.0, 0.0, 1.0].into_iter().any(|z| {
40:         [-1.0, 0.0, 1.0].into_iter().any(|x| {
41:             ScenePlanPoint::from_metres(centre.metres() + Vec2::new(x, z) * half_extent)
42:                 .and_then(|point| ground.ground_at(point))
43:                 .is_some_and(|sample| sample.cover == GroundCover::TallGrass)
44:         })
45:     })
46: }
47: 
48: fn grass_patch_transform(terrain: &SceneTerrain, point: ScenePlanPoint) -> Option<Transform> {
49:     let height = terrain.height_at(point)?;
50:     let normal = terrain.normal_at(point)?;
51:     if normal.y < 0.72 {
52:         return None;
53:     }
54:     Some(
55:         Transform::from_xyz(point.metres().x, height.metres(), point.metres().y)
56:             .with_rotation(Quat::from_rotation_arc(Vec3::Y, *normal)),
57:     )
58: }
59: 
60: fn grass_patch_placement_with_spacing(
61:     terrain: &SceneTerrain,
62:     ground: &SceneGround,
63:     render_centre: ScenePlanPoint,
64:     patch_spacing: f32,
65: ) -> Option<Transform> {
66:     if !ground_allows_grass_patch_with_spacing(ground, render_centre, patch_spacing) {
67:         return None;
68:     }
69:     grass_patch_transform(terrain, render_centre)
70: }
