159: impl TuftPlacement for ScenePlacement<'_> {
160:     fn lattice_bounds(&self, cell_spacing: f32) -> (IVec2, IVec2) {
161:         let half = Vec2::new(self.terrain.width(), self.terrain.depth()) * 0.5;
162:         (
163:             (-half / cell_spacing).floor().as_ivec2(),
164:             (half / cell_spacing).ceil().as_ivec2(),
165:         )
166:     }
167: 
168:     fn cell_allows(&self, cell_hash: Seed, cell: IVec2, cell_spacing: f32, jitter: f32) -> bool {
169:         cell_allows_grass(
170:             self.terrain,
171:             self.ground,
172:             cell_hash,
173:             cell.x,
174:             cell.y,
175:             cell_spacing,
176:             jitter,
177:         )
178:     }
179: 
180:     fn coverage(&self, centre: ScenePlanPoint) -> u8 {
181:         self.mask.coverage_byte(centre)
182:     }
183: 
184:     fn height(&self, centre: ScenePlanPoint) -> Option<SupportElevation> {
185:         let hit = self
186:             .terrain
187:             .surface_below(SupportQuery::unbounded(centre))?;
188:         (hit.normal.y >= MINIMUM_GRASS_SLOPE_NORMAL_Y).then_some(hit.elevation)
189:     }
190: 
191:     fn community(&mut self, centre: ScenePlanPoint) -> GrassCommunity {
192:         self.communities.at(centre, self.profile)
193:     }
194: }
