196: pub(in crate::presentation) fn prepare_scene_tufts(
197:     terrain: &SceneTerrain,
198:     ground: &SceneGround,
199:     environment: &SceneEnvironment,
200:     grass: &crate::presentation::config::GrassConfig,
201:     fault_scarp: Option<&adventuresim_tactical_core::prelude::TerrainLandformRecipe>,
202: ) -> GeometryResult<TierSpeciesBatches> {
203:     if !grass.enabled {
204:         return Ok(Default::default());
205:     }
206:     let masked_ground = fault_scarp.map(|recipe| {
207:         super::scene_mask::scatter_ground_without_patch(ground, recipe.transition_collar())
208:     });
209:     let ground = masked_ground.as_ref().unwrap_or(ground);
210:     let base_seed = stable_text_seed(&environment.scene_digest).xor_word(0x6772_6173_735f_6c6f);
211:     let mut placement = ScenePlacement {
212:         terrain,
213:         ground,
214:         mask: CoverageMask::new(ground, stable_text_seed(&environment.scene_digest))?,
215:         profile: GrassCommunityProfile::from_environment(environment),
216:         communities: GrassCommunityField::new(base_seed),
217:     };
218:     let mut batches = TierSpeciesBatches::default();
219:     for lod in [GrassMeshLod::Near, GrassMeshLod::Far] {
220:         scatter_cell_tufts(
221:             &mut batches[lod.tier_index()],
222:             &mut placement,
223:             base_seed,
224:             lod,
225:             grass.placement.playable_patch_spacing_m,

226:             grass,
227:         );
228:     }
229:     // Reuse near placements so the near-edge crossfade does not move tufts.
230:     for species in GrassSpecies::ALL {
231:         batches[GrassMeshLod::NearEdge.tier_index()][species.index()] =
232:             batches[GrassMeshLod::Near.tier_index()][species.index()].clone();
233:     }
234:     scatter_cell_tufts(
235:         &mut batches[GrassMeshLod::Vista.tier_index()],
236:         &mut placement,
237:         base_seed.xor_word(0x7669_7374_615f_6c6f),
238:         GrassMeshLod::Vista,
239:         grass.placement.vista_patch_spacing_m,
240:         grass,
241:     );
242:     Ok(batches)
243: }
