245: /// Tight bounds over a batch's actual instances. The initial implementation
246: /// used one whole-terrain slab per batch; a fitted box keeps Bevy's
247: /// batch-level frustum test and the compute cull's chunk test conservative
248: /// without extending the volume past the sward's real extent.
249: pub(super) fn fitted_batch_aabb(instances: &[InstanceData], footprint: f32) -> Aabb {
250:     let mut minimum = Vec3::splat(f32::INFINITY);
251:     let mut maximum = Vec3::splat(f32::NEG_INFINITY);
252:     for instance in instances {
253:         minimum = minimum.min(instance.position);
254:         maximum = maximum.max(instance.position);
255:     }
256:     let margin = Vec3::new(footprint, TUFT_HEIGHT_MARGIN_METRES, footprint);
257:     let minimum = minimum - margin * Vec3::new(1.0, 0.2, 1.0);
258:     let maximum = maximum + margin;
259:     Aabb {
260:         center: ((minimum + maximum) * 0.5).into(),
261:         half_extents: ((maximum - minimum) * 0.5).into(),
262:     }
263: }
264: 
265: /// Walks the jittered placement cells and fills per-species instance vectors
266: /// with tuft placements.
267: pub(in crate::presentation) fn scatter_cell_tufts(
268:     species_batches: &mut [Vec<InstanceData>; GrassSpecies::ALL.len()],
269:     placement: &mut impl TuftPlacement,
270:     base_seed: Seed,
271:     lod: GrassMeshLod,
272:     cell_spacing: f32,
273:     grass: &crate::presentation::config::GrassConfig,
274: ) -> u32 {
275:     let (minimum, maximum) = placement.lattice_bounds(cell_spacing);
276:     let side = match lod {
277:         GrassMeshLod::Near => grass.lod.near.native_tufts_per_cell_side,
278:         GrassMeshLod::NearEdge => grass.lod.near_edge.native_tufts_per_cell_side,
279:         GrassMeshLod::Far => grass.lod.far.native_tufts_per_cell_side,
280:         GrassMeshLod::Vista => grass.lod.vista.native_tufts_per_cell_side,
281:     } as i32;
282:     let footprint = configured_tuft_footprint_metres(lod, grass);
283:     let mut emitted = 0_u32;
284:     for z in minimum.y..=maximum.y {
285:         for x in minimum.x..=maximum.x {
286:             let cell_hash = streams::CELL.seed(base_seed, &[x as u32 as u64, z as u32 as u64]);
287:             if !placement.cell_allows(
288:                 cell_hash,
289:                 IVec2::new(x, z),
290:                 cell_spacing,
291:                 grass.placement.jitter_fraction,
292:             ) {
293:                 continue;
294:             }
295:             let cell_origin = Vec2::new(x as f32, z as f32) * cell_spacing
296:                 - Vec2::splat((side - 1) as f32 * 0.5 * footprint);
297:             for tuft_z in 0..side {
298:                 for tuft_x in 0..side {
299:                     let variation = variation::TuftVariation::new(
300:                         streams::TUFT.seed(cell_hash, &[tuft_x as u64, tuft_z as u64]),
301:                     );
302:                     let jitter = variation.jitter * footprint * 0.35;
303:                     let centre =
304:                         cell_origin + Vec2::new(tuft_x as f32, tuft_z as f32) * footprint + jitter;
305:                     let Some(centre) = ScenePlanPoint::from_metres(centre) else {
306:                         continue;
307:                     };
308:                     let coverage = placement.coverage(centre);
309:                     if coverage == 0 {
310:                         continue;
311:                     }
312:                     let Some(height) = placement.height(centre) else {
313:                         continue;
314:                     };
315:                     let community = placement.community(centre);
316:                     let species = grass_species(community, variation.species);
317:                     let batch = &mut species_batches[species.index()];
318:                     batch.push(InstanceData {
319:                         position: Vec3::new(centre.metres().x, height.metres(), centre.metres().y),
320:                         scale: 1.0,
321:                         rotation: variation.rotation,
322:                         index: batch.len() as u32,
323:                         batch_id: 0,
324:                         seed: u32::from(coverage) | (variation.shader_seed << 8),
325:                     });
326:                     emitted += 1;
327:                 }
328:             }
329:         }
330:     }
331:     emitted
332: }
333: 
334: /// Instanced counterpart of the grass portion of `present_ground_scatter`.
335: /// Builds the playable scene's sward once per scene, alongside the vista rings
336: /// that `presentation::vista` spawns from the same lattice and batching path.
337: fn present_instanced_grass(
338:     scenes: super::scene_mask::InstancedGrassSceneQuery,
339:     mut commands: Commands,
340:     mut meshes: ResMut<Assets<Mesh>>,
341:     mut materials: ResMut<Assets<TacticalGrassInstancedMaterial>>,
342:     settings: Res<crate::presentation::TacticalGraphicsSettings>,
343: ) {
344:     for (entity, _scene_id, terrain, ground, environment, fault_scarp) in &scenes {
345:         if !settings.config.grass.enabled {
346:             commands.entity(entity).insert(InstancedGrassPresented);
347:             continue;
348:         }
349:         let started = web_time::Instant::now();
350:         let (grass_color, grass_dryness) = grass_pigment(environment);
351:         let grass_density = grass_scatter_density(
352:             bps(environment.canopy_bps),
353:             bps(environment.water_bps),
354:             bps(environment.cultivation_bps),
355:             bps(environment.weather.snow_cover_bps),
356:         ) * settings.config.grass.density_scale;
357:         let wind_scale = 0.16 + bps(environment.weather.wind_speed_bps) * 0.36;
358:         let grass = &settings.config.grass;
359:         let base_seed = stable_text_seed(&environment.scene_digest).xor_word(0x6772_6173_735f_6c6f);
360:         let mut batches =
361:             match prepare_scene_tufts(terrain, ground, environment, grass, fault_scarp) {
362:                 Ok(batches) => batches,
363:                 Err(error) => {
364:                     warn!(%error, ?entity, "Invalid instanced grass ground mask");
365:                     continue;
366:                 }
367:             };
368:         spawn_tuft_batches(
369:             GrassWorld {
370:                 commands: &mut commands,
371:                 meshes: &mut meshes,
372:                 materials: &mut materials,
373:             },
374:             &mut batches,
375:             "Instanced grass",
376:             (),
377:             base_seed,
378:             TuftPigment {
379:                 color: grass_color,
380:                 density: grass_density,
381:                 dryness: grass_dryness,
382:                 wind_scale,
383:             },
384:             grass,
385:         );
386:         tracing::info!(
387:             elapsed_ms = started.elapsed().as_millis(),
388:             "Generated instanced tactical grass"
389:         );
390:         commands.entity(entity).insert(InstancedGrassPresented);
391:     }
392: }
393: 
394: /// Every gameplay/viewer camera drives eidolon's per-instance compute cull.
395: #[expect(
396:     clippy::type_complexity,
397:     reason = "the Bevy camera filter selects uncoupled gameplay cameras and excludes the offscreen cloud pass"
398: )]
399: fn enable_camera_cull_compute(
400:     mut commands: Commands,
401:     cameras: Query<
402:         Entity,
403:         (
404:             With<Camera3d>,
405:             Without<CullComputeCamera>,
406:             // The grass never renders on the offscreen cloud layer, and the
407:             // compute cull must follow the gameplay camera.
408:             Without<crate::presentation::TacticalCloudOffscreenCamera>,
409:         ),
410:     >,
411: ) {
412:     for camera in &cameras {
413:         commands.entity(camera).insert(CullComputeCamera);
414:     }
415: }
416: 
417: fn update_instanced_grass_interaction(
418:     time: Res<Time>,
419:     interactors: Query<&GlobalTransform, With<GrassInteractor>>,
420:     mut state: ResMut<InstancedGrassInteractionState>,
421:     mut materials: ResMut<Assets<TacticalGrassInstancedMaterial>>,
422:     settings: Res<crate::presentation::TacticalGraphicsSettings>,
423: ) {
424:     let Some(position) = interactors.iter().next().map(GlobalTransform::translation) else {
425:         if state.written.take().is_some() {
426:             for (_, material) in materials.iter_mut() {
427:                 material.interaction = Vec4::ZERO;
428:                 material.interaction_motion = Vec4::ZERO;
429:             }
430:         }
431:         state.previous_position = None;
432:         state.smoothed_velocity = Vec3::ZERO;
433:         return;
434:     };
435:     let delta_seconds = time.delta_secs().max(1.0 / 240.0);
436:     let velocity = state
437:         .previous_position
438:         .map(|previous| ((position - previous) / delta_seconds).clamp_length_max(8.0))
439:         .unwrap_or_default();
440:     let response = 1.0 - (-delta_seconds * 10.0).exp();
441:     state.smoothed_velocity = state.smoothed_velocity.lerp(velocity, response);
442:     state.previous_position = Some(position);
443: 
444:     // Idle interactors converge to constants; stop dirtying material assets
445:     // once the written values are close enough that no motion is visible.
446:     if state
447:         .written
448:         .is_some_and(|(written_position, written_velocity)| {
449:             written_position.distance_squared(position) < 1e-6
450:                 && written_velocity.distance_squared(state.smoothed_velocity) < 1e-6

451:         })
452:     {
453:         return;
454:     }
455: 
456:     let speed = state.smoothed_velocity.length();
457:     for (_, material) in materials.iter_mut() {
458:         let interaction = &settings.config.grass.interaction;
459:         material.interaction = position.extend(interaction.radius_m);
460:         material.interaction_motion = Vec4::new(
461:             state.smoothed_velocity.x,
462:             state.smoothed_velocity.y,
463:             state.smoothed_velocity.z,
464:             (interaction.minimum_push + speed * 0.11)
465:                 .clamp(interaction.minimum_push, interaction.maximum_push),
466:         );
467:     }
468:     state.written = Some((position, state.smoothed_velocity));
469: }
