471: /// Number of tuft columns/rows that subdivide one placement cell, per tier.
472: fn tufts_per_cell_side(lod: GrassMeshLod) -> i32 {
473:     match lod {
474:         GrassMeshLod::Near | GrassMeshLod::NearEdge => 12,
475:         GrassMeshLod::Far => 4,
476:         GrassMeshLod::Vista => 2,
477:     }
478: }
479: 
480: /// Eidolon fade bands per tier: `xy` fade-in, `zw` fade-out, mirroring the
481: /// legacy `grass_lod_visibility` crossfade margins. The near tier's epsilon
482: /// fade-in keeps the dither-level math well-defined at zero distance.
483: ///
484: /// `range_scale` contracts every band edge uniformly, so tier hand-offs stay
485: /// contiguous while the geometric sward trades reach for vertex throughput.
486: /// Near-tier cost scales with the square of its radius, making this the
487: /// single most effective grass performance lever.
488: fn tier_visibility_range(lod: GrassMeshLod, range_scale: f32) -> Vec4 {
489:     let scale = range_scale.clamp(0.35, 1.0);
490:     (match lod {
491:         // #560's legacy near band (0..14 m) splits into a full-detail field and
492:         // a slimmer edge ring; the ring covers most of the band's area, so most
493:         // near verts move to the nine-vertex 6x6 mesh. The instanced tiers
494:         // reproduce the legacy `grass_lod_visibility` bands so the native and
495:         // wasm swards fade out at the same distances (~50 m terminal).
496:         GrassMeshLod::Near => Vec4::new(0.0, 0.001, 4.0, 6.0),
497:         GrassMeshLod::NearEdge => Vec4::new(4.0, 6.0, 7.0, 14.0),
498:         GrassMeshLod::Far => Vec4::new(7.0, 14.0, 36.0, 44.0),
499:         // The vista fade-in shares the far tier's fade-out endpoints so the
500:         // complementary crossfade partition hands off exactly.
501:         GrassMeshLod::Vista => Vec4::new(34.0, 42.0, 42.0, 50.0),
502:     }) * scale
503: }
504: 
505: fn configured_tier_visibility_range(
506:     lod: GrassMeshLod,
507:     grass: &crate::presentation::config::GrassConfig,
508: ) -> Vec4 {
509:     let tier = match lod {
510:         GrassMeshLod::Near => &grass.lod.near,
511:         GrassMeshLod::NearEdge => &grass.lod.near_edge,
512:         GrassMeshLod::Far => &grass.lod.far,
513:         GrassMeshLod::Vista => &grass.lod.vista,
514:     };
515:     Vec4::new(
516:         tier.fade_in_m[0],
517:         tier.fade_in_m[1],
518:         tier.fade_out_m[0],
519:         tier.fade_out_m[1],
520:     )
521: }
