1: //! Construct retained GPU instance batches from the procedural tuft lattice.
2: use super::*;
3: use fabelgeist_determinism::Seed;
4: 
5: /// Turns filled instance batches into one entity per (tier, species), each
6: /// carrying `marker` on top of the shared instanced-draw components.
7: pub(in crate::presentation) fn spawn_tuft_batches(
8:     world: GrassWorld<'_, '_, '_>,
9:     batches: &mut TierSpeciesBatches,
10:     label: &str,
11:     marker: impl Bundle + Clone,
12:     base_seed: Seed,
13:     pigment: TuftPigment,
14:     grass: &crate::presentation::config::GrassConfig,
15: ) {
16:     let GrassWorld {
17:         commands,
18:         meshes,
19:         materials,
20:     } = world;
21:     for lod in TIERS {
22:         let material = materials.add(diagnostics::material(
23:             lod,
24:             grass,
25:             pigment.density,
26:             pigment.dryness,
27:             pigment.wind_scale,
28:         ));
29:         for species in GrassSpecies::ALL {
30:             let instances = std::mem::take(&mut batches[lod.tier_index()][species.index()]);
31:             if instances.is_empty() {
32:                 continue;
33:             }
34:             let (mesh, triangle_count) = diagnostics::add_mesh(
35:                 meshes,
36:                 grass_tuft_mesh(
37:                     pigment.color,
38:                     lod,
39:                     pigment.density,
40:                     species,
41:                     streams::TUFT_MESH.seed(
42:                         base_seed,
43:                         &[species.index() as u64, lod.tier_index() as u64],
44:                     ),
45:                     grass,
46:                 ),
47:             );
48:             let metadata = culling::metadata(
49:                 meshes.get(&mesh).expect("generated tuft"),
50:                 lod.width_compensation(pigment.density),
51:                 pigment.wind_scale,
52:                 grass.interaction.maximum_push,
53:             );
54:             let mut entity = commands.spawn((
55:                 Name::new(format!(
56:                     "{label} {species:?} {lod:?} tufts ({})",
57:                     instances.len()
58:                 )),
59:                 GroundScatterLayer::Grass,
60:                 triangle_count,
61:                 GpuCullCompute,
62:                 // Batches span the whole scene, so CPU frustum culling can
63:                 // only ever hide them wholesale - and worse, a culled frame
64:                 // drops the batch from `RenderMeshInstances`, which makes
65:                 // eidolon free and re-upload the retained instance buffers
66:                 // every time the camera pitch crosses the horizon. Culling
67:                 // belongs solely to the GPU compute pass.
68:                 NoFrustumCulling,
69:                 Mesh3d(mesh),
70:                 InstancedMeshMaterial(material.clone()),
71:                 fitted_batch_aabb(&instances, configured_tuft_footprint_metres(lod, grass)),
72:                 InstanceMaterialData {
73:                     instances: Arc::new(instances),
74:                     color: metadata,
75:                     visibility_range: configured_tier_visibility_range(lod, grass),
76:                 },
77:                 Transform::default(),
78:                 Visibility::Inherited,
79:             ));
80:             entity.insert(marker.clone());
81:             if !diagnostics::casts_shadows(lod, grass) {
82:                 entity.insert(NotShadowCaster);
83:             }
84:         }
85:     }
86: }
