1: //! Encode each tuft's animated bound for the custom GPU visibility pass.
2: use bevy::{mesh::VertexAttributeValues, prelude::*};
3: 
4: // Bounds for the deformation terms in tactical_grass_instanced.wgsl.
5: const MAX_BLADE_VIGOR: f32 = 1.06;
6: const MAX_NATURAL_AND_AUTHORED_LEAN_METRES: f32 = 0.157;
7: const MAX_WIND_ENVELOPE: f32 = 1.18;
8: const MAX_INTERACTION_DISPLACEMENT: f32 = 1.24;
9: 
10: pub(super) fn metadata(mesh: &Mesh, width: f32, wind: f32, maximum_push: f32) -> LinearRgba {
11:     let Some(VertexAttributeValues::Float32x3(positions)) =
12:         mesh.attribute(Mesh::ATTRIBUTE_POSITION)
13:     else {
14:         panic!("grass tuft positions are float3");
15:     };
16:     let Some(VertexAttributeValues::Float32x2(roots)) = mesh.attribute(Mesh::ATTRIBUTE_UV_1) else {
17:         panic!("grass tufts retain their blade roots");
18:     };
19:     let geometry_radius = positions
20:         .iter()
21:         .zip(roots)
22:         .map(|(position, root)| {
23:             let root = Vec2::from_array(*root);
24:             root.length()
25:                 + position[1].abs() * MAX_BLADE_VIGOR
26:                 + (Vec2::new(position[0], position[2]) - root).length() * width.max(1.0)
27:         })
28:         .fold(0.0, f32::max);
29:     let radius = geometry_radius
30:         + MAX_NATURAL_AND_AUTHORED_LEAN_METRES
31:         + wind.abs() * MAX_WIND_ENVELOPE
32:         + maximum_push.abs() * MAX_INTERACTION_DISPLACEMENT;
33:     // The grass shader has its own coverage alpha. Its unused batch alpha lane
34:     // carries a root-centred radius, while RGB retains the white pigment tint.
35:     LinearRgba::new(1.0, 1.0, 1.0, radius)
36: }
37: 
38: #[cfg(test)]
39: mod tests {
40:     use super::*;
41: 
42:     #[test]
43:     fn animated_bound_encloses_rotated_width_and_maximum_push() {
44:         let mut mesh = Mesh::new(bevy::mesh::PrimitiveTopology::TriangleList, default());
45:         mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, vec![[0.9, 1.4, -0.2]]);
46:         mesh.insert_attribute(Mesh::ATTRIBUTE_UV_1, vec![[0.6, -0.2]]);
47:         let bound = metadata(&mesh, 2.0, 0.5, 1.35);
48:         // Worst-direction wind, player push and lean, with camera-facing width.
49:         let extreme = Vec3::new(0.6 + 0.6 + 0.59 + 1.215 + 0.157, 1.484 + 0.459, -0.2);
50:         assert!(bound.alpha >= extreme.length());
51:         assert_eq!([bound.red, bound.green, bound.blue], [1.0; 3]);
52:         assert!(metadata(&mesh, 2.0, 1.0, 2.0).alpha > bound.alpha);
53:     }
54: }
