1: //! The instanced grass material: the uniforms the sward shader reads and the
2: //! pipeline tweaks thin double-sided ribbons need.
3: 
4: use bevy::{
5:     prelude::*,
6:     render::render_resource::{
7:         AsBindGroup, RenderPipelineDescriptor, ShaderType, SpecializedMeshPipelineError,
8:     },
9:     shader::ShaderRef,
10: };
11: use bevy_eidolon::prelude::InstancedMaterial;
12: 
13: const GRASS_INSTANCED_SHADER: &str = "shaders/tactical_grass_instanced.wgsl";
14: const GRASS_CULL_SHADER: &str = "shaders/tactical_grass_cull.wgsl";
15: 
16: #[derive(Asset, TypePath, AsBindGroup, Debug, Clone)]
17: #[uniform(0, TacticalGrassInstancedUniform)]
18: pub(in crate::presentation) struct TacticalGrassInstancedMaterial {
19:     /// Wind direction xy, strength, time scale.
20:     pub wind: Vec4,
21:     /// Interactor position (xyz) and interaction radius (w; 0 disables).
22:     pub interaction: Vec4,
23:     /// Interactor smoothed velocity (xyz) and push strength.
24:     pub interaction_motion: Vec4,
25:     /// Root occlusion, dryness lane, authored lean, width compensation.
26:     pub params: Vec4,
27:     /// y scales the flat ambient term to approximate the skipped image-based
28:     /// lighting. Every tier now shades fast (ambient + wrapped Lambert + one
29:     /// clamped shadow fetch), so x/z/w are reserved.
30:     pub shading: Vec4,
31: }
32: 
33: #[derive(Clone, Default, ShaderType)]
34: pub(in crate::presentation) struct TacticalGrassInstancedUniform {
35:     wind: Vec4,
36:     interaction: Vec4,
37:     interaction_motion: Vec4,
38:     params: Vec4,
39:     shading: Vec4,
40: }
41: 
42: impl From<&TacticalGrassInstancedMaterial> for TacticalGrassInstancedUniform {
43:     fn from(material: &TacticalGrassInstancedMaterial) -> Self {
44:         Self {
45:             wind: material.wind,
46:             interaction: material.interaction,
47:             interaction_motion: material.interaction_motion,
48:             params: material.params,
49:             shading: material.shading,
50:         }
51:     }
52: }
53: 
54: impl InstancedMaterial for TacticalGrassInstancedMaterial {
55:     fn cull_shader() -> ShaderRef {
56:         GRASS_CULL_SHADER.into()
57:     }
58: 
59:     fn vertex_shader() -> ShaderRef {
60:         GRASS_INSTANCED_SHADER.into()
61:     }
62: 
63:     fn fragment_shader() -> ShaderRef {
64:         GRASS_INSTANCED_SHADER.into()
65:     }
66: 
67:     /// Legacy grass renders without a prepass; keep the instanced sward
68:     /// identical so the depth interplay with the terrain detail patch and
69:     /// transparent weather stays unchanged.
70:     fn disable_prepass(&self) -> bool {
71:         true
72:     }
73: 
74:     fn specialize(
75:         descriptor: &mut RenderPipelineDescriptor,
76:         _layout: &bevy::mesh::MeshVertexBufferLayoutRef,
77:         _key: Self::Data,
78:     ) -> Result<(), SpecializedMeshPipelineError> {
79:         // Thin ribbons are shaded double-sided, and the LOD dither converts
80:         // to hardware coverage samples under MSAA exactly like the legacy
81:         // AlphaToCoverage foliage material.
82:         descriptor.primitive.cull_mode = None;
83:         if descriptor.multisample.count > 1 {
84:             descriptor.multisample.alpha_to_coverage_enabled = true;
85:         }
86:         Ok(())
87:     }
88: }
