1: //! One domain-derived seed owns the fixed draw slots of one visual tuft.
2: use bevy::prelude::*;
3: 
4: pub(super) struct TuftVariation {
5:     pub jitter: Vec2,
6:     pub species: fabelgeist_determinism::Seed,
7:     pub rotation: f32,
8:     pub shader_seed: u32,
9: }
10: 
11: impl TuftVariation {
12:     pub fn new(seed: fabelgeist_determinism::Seed) -> Self {
13:         let mut rng = seed.rng();
14:         // Draw every slot before coverage rejection. Nearby tufts, density
15:         // changes and species selection cannot consume one another's draws.
16:         Self {
