1: //! Per-camera tuft culling. Grass has no prepass or shadow pass, so retained
2: //! output buffers can be reused immediately before each camera's main pass.
3: use std::collections::HashMap;
4: 
5: use bevy::{
6:     camera::primitives::Frustum,
7:     core_pipeline::schedule::{Core3d, Core3dSystems},
8:     prelude::*,
9:     render::{
10:         Render, RenderApp, RenderSystems,
11:         render_resource::*,
12:         renderer::{RenderContext, RenderDevice, RenderQueue, ViewQuery},
13:         view::ExtractedView,
14:     },
15: };
16: use bevy_eidolon::{
17:     allocator::resources::GlobalInstanceAllocator,
18:     cull::{pipeline::InstancedComputePipeline, resources::CameraCullData},
19:     prepass::CullComputeCamera,
20: };
21: 
22: use super::TacticalGrassInstancedMaterial;
23: 
24: const WORKGROUP_SIZE: u32 = 64;
25: const MAX_WORKGROUPS: u32 = 65_535;
26: type GrassPipeline = InstancedComputePipeline<TacticalGrassInstancedMaterial>;
27: 
28: pub(super) struct GrassCullingPlugin;
29: 
30: impl Plugin for GrassCullingPlugin {
31:     fn build(&self, app: &mut App) {
32:         app.sub_app_mut(RenderApp)
33:             .init_resource::<GrassViews>()
34:             .add_systems(Render, prepare.in_set(RenderSystems::PrepareBindGroups))
35:             .add_systems(
36:                 Core3d,
37:                 cull.after(Core3dSystems::Prepass)
38:                     .before(Core3dSystems::MainPass),
39:             );
40:     }
41: 
42:     fn finish(&self, app: &mut App) {
43:         let render = app.sub_app_mut(RenderApp);
44:         render.init_resource::<GrassPipeline>();
45:         let pipeline = render.world().resource::<GrassPipeline>();
46:         let cache = render.world().resource::<PipelineCache>();
47:         let queue = |entry: &str| {
48:             cache.queue_compute_pipeline(ComputePipelineDescriptor {
49:                 label: Some(format!("grass_{entry}").into()),
50:                 layout: vec![
51:                     pipeline.compute_layout.clone(),
52:                     pipeline.common_layout.clone(),
53:                     pipeline.global_layout.clone(),
54:                 ],
55:                 shader: pipeline.shader.clone(),
56:                 entry_point: Some(entry.to_owned().into()),
57:                 ..default()
58:             })
59:         };
60:         let pipelines = Pipelines {
61:             reset: queue("reset"),
62:             select: queue("main"),
63:         };
64:         render.insert_resource(pipelines);
65:     }
66: }
67: 
68: #[derive(Resource)]
69: struct Pipelines {
70:     reset: CachedComputePipelineId,
71:     select: CachedComputePipelineId,
72: }
73: 
74: struct ViewBuffer {
75:     uniform: UniformBuffer<CameraCullData>,
76:     binding: BindGroup,
77: }
78: 
79: #[derive(Resource, Default)]
80: struct GrassViews(HashMap<Entity, ViewBuffer>);
81: 
82: fn prepare(
83:     views: Query<(Entity, &ExtractedView, &Frustum, &Camera), With<CullComputeCamera>>,
84:     mut prepared: ResMut<GrassViews>,
85:     pipeline: Res<GrassPipeline>,
86:     cache: Res<PipelineCache>,
87:     device: Res<RenderDevice>,
88:     queue: Res<RenderQueue>,
89: ) {
90:     prepared.0.retain(|entity, _| {
91:         views
92:             .get(*entity)
93:             .is_ok_and(|(_, _, _, camera)| camera.is_active)
94:     });
95:     for (entity, view, frustum, camera) in &views {
96:         if !camera.is_active {
97:             continue;
98:         }
99:         let data = CameraCullData {
100:             view_pos: view.world_from_view.translation().extend(1.0),
101:             frustum: frustum.half_spaces.map(|plane| plane.normal_d()),
102:         };
103:         if let Some(buffer) = prepared.0.get_mut(&entity) {
104:             buffer.uniform.set(data);
105:             buffer.uniform.write_buffer(&device, &queue);
106:         } else {
107:             let mut uniform = UniformBuffer::from(data);
108:             uniform.write_buffer(&device, &queue);
109:             let binding = device.create_bind_group(
110:                 "grass culling camera",
111:                 &cache.get_bind_group_layout(&pipeline.global_layout),
112:                 &BindGroupEntries::single(uniform.binding().expect("uploaded camera")),
113:             );
114:             prepared.0.insert(entity, ViewBuffer { uniform, binding });
115:         }
116:     }
117: }
118: 
119: fn cull(
120:     mut context: RenderContext,
121:     current: ViewQuery<Entity>,
122:     views: Res<GrassViews>,
123:     pipelines: Res<Pipelines>,
124:     cache: Res<PipelineCache>,
125:     allocator: Res<GlobalInstanceAllocator<TacticalGrassInstancedMaterial>>,
126: ) {
127:     let Some(view) = views.0.get(&current.into_inner()) else {
128:         return;
129:     };
130:     let (Some(reset), Some(select)) = (
131:         cache.get_compute_pipeline(pipelines.reset),
132:         cache.get_compute_pipeline(pipelines.select),
133:     ) else {
134:         return;
135:     };
136:     let mut pass = context
137:         .command_encoder()
138:         .begin_compute_pass(&ComputePassDescriptor {
139:             label: Some("grass_view_cull"),
140:             timestamp_writes: None,
141:         });
142:     pass.set_bind_group(2, &view.binding, &[]);
143:     for page in &allocator.pages {
144:         if page.compute_capacity == 0 {
145:             continue;
146:         }
147:         let (Some(compute), Some(common), Some(indirect)) = (
148:             &page.compute_bind_group,
149:             &page.common_bind_group,
150:             &page.indirect_buffer,
151:         ) else {
152:             continue;
153:         };
154:         pass.set_bind_group(0, compute, &[]);
155:         pass.set_bind_group(1, common, &[]);
156:         pass.set_pipeline(reset);
157:         let draws = indirect.size() / size_of::<DrawIndexedIndirectArgs>() as u64;
158:         pass.dispatch_workgroups((draws as u32).div_ceil(WORKGROUP_SIZE), 1, 1);
159:         pass.set_pipeline(select);
160:         let groups = page.compute_capacity.div_ceil(WORKGROUP_SIZE);
161:         pass.dispatch_workgroups(
162:             groups.min(MAX_WORKGROUPS),
163:             groups.div_ceil(MAX_WORKGROUPS),
164:             1,
165:         );
166:     }
167: }
