131:         descriptor: &mut RenderPipelineDescriptor,
132:         _layout: &bevy::mesh::MeshVertexBufferLayoutRef,
133:         _key: Self::Data,
134:     ) -> Result<(), SpecializedMeshPipelineError> {
135:         // Leaf cards are shaded double-sided and cut out via A2C.
136:         descriptor.primitive.cull_mode = None;
137:         if descriptor.multisample.count > 1 {
138:             descriptor.multisample.alpha_to_coverage_enabled = true;
139:         }
