149:         ShrubRepresentation::CamberedLeaves => Vec4::new(0.0, 0.001, 26.0, 34.0),
150:         ShrubRepresentation::LeafCards => Vec4::new(26.0, 34.0, 84.0, 96.0),
151:     }
152: }
