161: const REPRESENTATIONS: [ShrubRepresentation; 3] = [
162:     ShrubRepresentation::Branches,
163:     ShrubRepresentation::CamberedLeaves,
164:     ShrubRepresentation::LeafCards,
165: ];
166: 
167: #[expect(
168:     clippy::too_many_arguments,
169:     reason = "the instanced-understory construction boundary keeps asset stores, habitat, and placement inputs explicit"
170: )]
171: pub(super) fn spawn(
172:     commands: &mut Commands,
173:     bark_materials: &mut Assets<TacticalShrubBarkInstancedMaterial>,
174:     leaf_materials: &mut Assets<TacticalShrubLeafInstancedMaterial>,
175:     standard_materials: &Assets<StandardMaterial>,
176:     leaf_sources: &Assets<super::TacticalTreeLeafCardMaterial>,
177:     cache: &WoodyUnderstoryPresentationCache,
178:     terrain: &SceneTerrain,
179:     ground: &SceneGround,
180:     base_seed: Seed,
181:     chance: f32,
182:     habitat: UnderstoryHabitat,
183: ) {
184:     let mut per_species: [Vec<InstanceData>; 3] = Default::default();
185:     for ShrubPlacement {
186:         species,
187:         point,
188:         hash,
189:     } in understory::placements(terrain, ground, base_seed, chance, habitat)
190:     {
191:         // Preserve the shared understory/litter placement purposes, terrain
192:         // height and slope admission before projecting to the GPU instance.
193:         let (Some(height), Some(normal)) = (terrain.height_at(point), terrain.normal_at(point))
194:         else {
195:             continue;
196:         };
197:         if normal.y < 0.72 {
198:             continue;
199:         }
200:         let Ok(root) = Position::from_metres(Vec3::new(
201:             point.metres().x,
202:             height.metres(),
203:             point.metres().y,
204:         )) else {
205:             continue;
206:         };
207:         per_species[species_index(species)].push(shrub_instance(hash, root));
208:     }
209: 
210:     for species in [
211:         UnderstorySpecies::CommonHazel,
212:         UnderstorySpecies::Blackthorn,
213:         UnderstorySpecies::CommonHawthorn,
214:     ] {
215:         let instances = Arc::new(std::mem::take(&mut per_species[species_index(species)]));
216:         if instances.is_empty() {
217:             continue;
218:         }
219:         let presentation = cache.presentation(species);
220:         let (Some(branches), Some(cambered), Some(cards), Some(bark_handle), Some(leaf_handle)) = (
221:             presentation.branches.clone(),
222:             presentation.cambered_leaves.clone(),
223:             presentation.leaf_cards.clone(),
224:             presentation.bark.as_ref(),
225:             presentation.leaves.as_ref(),
226:         ) else {
227:             continue;
228:         };
229:         let bark_color = standard_materials
230:             .get(bark_handle)
231:             .map(|material| {
232:                 let linear = material.base_color.to_linear();
233:                 Vec4::new(
234:                     linear.red,
235:                     linear.green,
236:                     linear.blue,
237:                     material.perceptual_roughness,
238:                 )
239:             })
240:             .unwrap_or(Vec4::new(0.16, 0.13, 0.10, 0.96));
241:         let Some(leaf) = leaf_sources.get(leaf_handle) else {
242:             continue;
243:         };
244:         let aabb = fitted_batch_aabb(&instances, SHRUB_FOOTPRINT_METRES);
245:         let bark = bark_materials.add(TacticalShrubBarkInstancedMaterial { color: bark_color });
246:         for representation in REPRESENTATIONS {
247:             let (mesh, name) = match representation {
248:                 ShrubRepresentation::Branches => (branches.clone(), "wood"),
249:                 ShrubRepresentation::CamberedLeaves => (cambered.clone(), "cambered leaves"),
250:                 ShrubRepresentation::LeafCards => (cards.clone(), "leaf cards"),
251:             };
252:             let mut entity = commands.spawn((
253:                 Name::new(format!(
254:                     "Instanced {species:?} shrub {name} ({})",
255:                     instances.len()
256:                 )),
257:                 super::GroundScatterLayer::Understory,
258:                 GpuCullCompute,
259:                 // Whole-scene batches: culling belongs to the GPU compute
260:                 // pass, and CPU frustum culling would free the retained
261:                 // instance buffers (see the grass batches).
262:                 bevy::camera::visibility::NoFrustumCulling,
263:                 Mesh3d(mesh),
264:                 aabb,
265:                 InstanceMaterialData {
266:                     instances: instances.clone(),
267:                     color: LinearRgba::WHITE,
268:                     visibility_range: representation_band(representation),
269:                 },
270:                 Transform::default(),
271:                 Visibility::Inherited,
272:             ));
273:             match representation {
274:                 ShrubRepresentation::Branches => {
275:                     entity.insert(InstancedMeshMaterial(bark.clone()));
276:                 }
277:                 ShrubRepresentation::CamberedLeaves | ShrubRepresentation::LeafCards => {
278:                     // Both the cambered near leaves and the distant cards shade
279:                     // fast now; the cambered path's former full PBR was pure
280:                     // per-fragment cost. y=0.72 scales the flat ambient.
281:                     entity.insert(InstancedMeshMaterial(leaf_materials.add(
282:                         TacticalShrubLeafInstancedMaterial {
283:                             opacity: leaf.opacity.clone(),
284:                             front_albedo: leaf.front_albedo.clone(),
285:                             back_albedo: leaf.back_albedo.clone(),
286:                             front_normal: leaf.front_normal.clone(),
287:                             back_normal: leaf.back_normal.clone(),
288:                             arm: leaf.arm.clone(),
289:                             parameters: leaf.parameters,
290:                             surface_parameters: leaf.surface_parameters,
291:                             physical_parameters: leaf.physical_parameters,
292:                             shading: Vec4::new(1.0, 0.72, 0.0, 0.0),
293:                         },
294:                     )));
295:                 }
296:             }
297:         }
298:     }
299: }
300: 
301: fn species_index(species: UnderstorySpecies) -> usize {
302:     match species {
303:         UnderstorySpecies::CommonHazel => 0,
304:         UnderstorySpecies::Blackthorn => 1,
305:         UnderstorySpecies::CommonHawthorn => 2,
306:     }
307: }
308: 
309: fn shrub_instance(hash: Seed, root: Position<Scene>) -> InstanceData {
310:     let yaw = PLACEMENT_YAW.rng(hash, &[]).inclusive_unit_f32() * core::f32::consts::TAU;
311:     let scale = 0.72 + PLACEMENT_SCALE.rng(hash, &[]).inclusive_unit_f32() * 0.58;
312:     InstanceData {
313:         position: root.metres(),
314:         scale,
315:         rotation: yaw,
316:         seed: (StreamId::new("visual.ground-scatter.instanced-understory.shader-seed")
317:             .seed(hash, &[])
318:             .to_u64()
319:             & 0xffff_ffff) as u32,
320:         ..Default::default()
321:     }
322: }
