81: #[derive(Clone, Copy)]
82: enum BatchKind {
83:     Leaves,
84:     Twigs,
85:     Plants,
86: }
87: 
88: /// Static, vertex-colored wood for batched forest-floor twigs.
89: ///
90: /// Twigs are fully modeled opaque geometry, so the stock PBR path preserves
91: /// their per-vertex bark pigment, fog, and lighting without foliage wind,
92: /// interaction, coverage-mask, or transmission work.
93: pub(super) fn static_twig_material() -> StandardMaterial {
94:     StandardMaterial {
95:         base_color: Color::WHITE,
96:         perceptual_roughness: 0.96,
97:         double_sided: true,
98:         cull_mode: None,
99:         ..default()
100:     }
101: }
102: 
103: pub(super) fn spawn(
104:     commands: &mut Commands,
105:     meshes: &mut bevy::prelude::Assets<Mesh>,
106:     terrain: &SceneTerrain,
107:     ground: &SceneGround,
108:     base_seed: Seed,
109:     assets: &Assets,
110: ) -> Result<(), bevy::mesh::MeshMergeError> {
111:     let mut batches = BTreeMap::<(i32, i32), LitterBatch>::new();
112:     let mut leaf_anchors = Vec::new();
113:     let mut twig_anchors = Vec::new();
114:     let mut dry_leaf_patch_instances = 0;
115:     for (index, sample) in ground.samples().iter().enumerate() {
116:         let grid_x = index % ground.grid_width();
117:         let grid_z = index / ground.grid_width();
118:         let transition = match sample.cover {
119:             GroundCover::LeafLitter => 1.0,
120:             GroundCover::TallGrass => leaf_litter_proximity(ground, grid_x, grid_z),
121:             _ => 0.0,
122:         };
123:         if transition <= 0.0 {
124:             continue;
125:         }
126:         let cell_origin = Vec2::new(
127:             grid_x as f32 * ground.grid_scale() - ground.width() * 0.5,
128:             grid_z as f32 * ground.grid_scale() - ground.depth() * 0.5,
129:         );
130:         let Some(cell_origin) = ScenePlanPoint::from_metres(cell_origin) else {
131:             continue;
132:         };
133:         let density = if sample.cover == GroundCover::LeafLitter {
134:             bps(sample.cover_density_bps)
135:         } else {
136:             transition * 0.34
137:         };
138:         for pass in 0..DRY_LEAF_PASSES_PER_SAMPLE {
139:             let hash = streams::LEAF_PATCH.seed(base_seed, &[index as u64, pass]);
140:             if streams::PRESENCE.rng(hash, &[]).inclusive_unit_f32() >= density * 0.97 {
141:                 continue;
142:             }
143:             let Some(placement) =
144:                 LitterPlacement::new(terrain, ground, cell_origin, hash, BatchKind::Leaves)
145:             else {
146:                 continue;
147:             };
148:             if sample.cover == GroundCover::LeafLitter {
149:                 leaf_anchors.push(placement.root);
150:             }
151:             dry_leaf_patch_instances += 1;
152:             append_litter_batch(
153:                 meshes,
154:                 &assets.dry_leaf_meshes[streams::DRY_LEAF_MESHES_VARIANT
155:                     .rng(hash, &[])
156:                     .index(assets.dry_leaf_meshes.len())],
157:                 placement,
158:                 &mut batches,
159:             )?;
160:         }
161:         for pass in 0..TWIG_PASSES_PER_SAMPLE {
162:             let hash = streams::TWIG_PATCH.seed(base_seed, &[index as u64, pass]);
163:             if streams::PRESENCE.rng(hash, &[]).inclusive_unit_f32() >= density * 0.62 {
164:                 continue;
165:             }
166:             let Some(placement) =
167:                 LitterPlacement::new(terrain, ground, cell_origin, hash, BatchKind::Twigs)
168:             else {
169:                 continue;
170:             };
171:             if sample.cover == GroundCover::LeafLitter {
172:                 twig_anchors.push(placement.root);
173:             }
174:             append_litter_batch(
175:                 meshes,
176:                 &assets.twig_meshes[streams::TWIG_MESHES_VARIANT
177:                     .rng(hash, &[])
178:                     .index(assets.twig_meshes.len())],
179:                 placement,
180:                 &mut batches,
181:             )?;
182:         }
183:         let plant_chance = if sample.cover == GroundCover::LeafLitter {
184:             0.055
185:         } else {
186:             transition * 0.38
187:         };
188:         for pass in 0..WOODLAND_PLANT_PASSES_PER_SAMPLE {
189:             let hash = streams::PLANT_PATCH.seed(base_seed, &[index as u64, pass]);
190:             if streams::PRESENCE.rng(hash, &[]).inclusive_unit_f32() >= plant_chance {
191:                 continue;
192:             }
193:             let Some(placement) =
194:                 LitterPlacement::new(terrain, ground, cell_origin, hash, BatchKind::Plants)
195:             else {
196:                 continue;
197:             };
198:             append_litter_batch(
199:                 meshes,
200:                 &assets.woodland_plant_meshes[streams::WOODLAND_PLANT_MESHES_VARIANT
201:                     .rng(hash, &[])
202:                     .index(assets.woodland_plant_meshes.len())],
203:                 placement,
204:                 &mut batches,
205:             )?;
206:         }
207:     }
208:     let pairs = GroundLitterCapturePair::closest(
209:         &leaf_anchors,
210:         &twig_anchors,
211:         GroundLitterCapturePair::MAXIMUM_SEPARATION,
212:         64,
213:     );
214:     if !pairs.is_empty() {
215:         commands.spawn((
216:             Name::new("Tactical litter capture anchors"),
217:             GroundLitterCaptureAnchors { pairs },
218:         ));
219:     }
220:     commands.spawn((
221:         Name::new("Tactical litter diagnostics"),
222:         super::GroundLitterDiagnostics {
223:             dry_leaf_patch_instances,
224:             physical_dry_leaf_count: dry_leaf_patch_instances * DRY_LEAVES_PER_PATCH as usize,
225:         },
226:     ));
227:     batching::spawn_batches(commands, meshes, assets, batches);
228:     Ok(())
229: }
