231: pub(super) fn forest_floor_leaf_material(
232:     assets: &ProceduralTextureAssets,
233: ) -> TacticalTreeLeafCardMaterial {
234:     let mut material = leaf_material(&assets.dry_oak_leaf, 0.28, 0.72, 0.0, 0.035);
235:     // Fallen leaves reuse the oak surface maps/PBR response but do not inherit
236:     // canopy wind displacement. NotShadowCaster on every litter entity keeps
237:     // their dense alpha geometry out of the shadow pass.
238:     material.parameters.z = 0.0;
239:     material.surface_parameters.z = 0.0;
240:     material.surface_parameters.w = 0.035;
241:     // The dry-leaf height map remains available to close inspection, but its
242:     // embossed midrib must not make every geometry leaf readable from the
243:     // acceptance distance when the terrain layer's relief has minified.
244:     material.surface_parameters.y = 0.18;
245:     material.physical_parameters.x = 0.96;
246:     material.physical_parameters.y = 0.00035;
247:     // Fallen-leaf meshes already carry deterministic dry pigments per leaf.
248:     // Blend those pigments over the shared dry-oak texture; live canopy cards
249:     // keep zero here and retain their species albedo unchanged.
250:     material.physical_parameters.z = 0.38;

251:     material
252: }
