254: pub(super) fn dry_leaf_patch_mesh(variant: u64) -> GeometryResult<Mesh> {
255:     let mut data = GroundLitterMeshData::default();
256:     // Keep the vertex pigments in the same narrow value bands as the packed
257:     // terrain litter. Variation remains legible up close without turning the
258:     // physical leaves into isolated copper markers.
259:     let leaf_colors = [
260:         Color::srgb_u8(106, 90, 69),
261:         Color::srgb_u8(99, 86, 68),
262:         Color::srgb_u8(112, 95, 72),
263:         Color::srgb_u8(95, 83, 67),
264:         Color::srgb_u8(104, 91, 72),
265:     ];
266:     // Keep a clustered tail even after reducing the patch population so
267:     // variants retain their loose-pile silhouette differences.
268:     const STRATIFIED_LEAVES: u64 = 40;
269:     const STRATIFIED_COLUMNS: u64 = 8;
270:     const CLUSTER_COUNT: u64 = 7;
271:     let clusters = (0..CLUSTER_COUNT)
272:         .map(|cluster| {
273:             let hash = streams::LEAF_CLUSTER.seed(variant.into(), &[cluster]);
274:             Vec2::new(
275:                 streams::CENTER_X.rng(hash, &[]).inclusive_unit_f32() - 0.5,
276:                 streams::CENTER_Z.rng(hash, &[]).inclusive_unit_f32() - 0.5,
277:             ) * 0.68
278:         })
279:         .collect::<Vec<_>>();
280:     for leaf in 0..DRY_LEAVES_PER_PATCH {
281:         let hash = streams::LEAF.seed(variant.into(), &[leaf]);
282:         let scatter_angle =
283:             streams::SCATTER_ANGLE.rng(hash, &[]).inclusive_unit_f32() * core::f32::consts::TAU;
284:         let centre = if leaf < STRATIFIED_LEAVES {
285:             let column = leaf % STRATIFIED_COLUMNS;
286:             let row = leaf / STRATIFIED_COLUMNS;
287:             let jitter = Vec2::new(
288:                 streams::STRATUM_JITTER_X
289:                     .rng(hash, &[])
290:                     .inclusive_unit_f32()
291:                     - 0.5,
292:                 streams::STRATUM_JITTER_Z
293:                     .rng(hash, &[])
294:                     .inclusive_unit_f32()
295:                     - 0.5,
296:             ) * 0.075;
297:             Vec2::new(
298:                 (column as f32 + 0.5) / STRATIFIED_COLUMNS as f32 - 0.5,
299:                 (row as f32 + 0.5) / (STRATIFIED_LEAVES / STRATIFIED_COLUMNS) as f32 - 0.5,
300:             ) * 0.90
301:                 + jitter
302:         } else {
303:             let cluster = clusters[leaf as usize % clusters.len()];
304:             let radial = 0.025 + streams::RADIAL.rng(hash, &[]).inclusive_unit_f32() * 0.12;
305:             cluster + Vec2::new(scatter_angle.cos(), scatter_angle.sin()) * radial
306:         };
307:         let angle = streams::ANGLE.rng(hash, &[]).inclusive_unit_f32() * core::f32::consts::TAU;
308:         let long = Vec2::new(angle.cos(), angle.sin())
309:             * (0.045 + streams::LENGTH.rng(hash, &[]).inclusive_unit_f32() * 0.040);
310:         let side = Vec2::new(-long.y, long.x)
311:             * (0.45 + streams::WIDTH.rng(hash, &[]).inclusive_unit_f32() * 0.18);
312:         data.append_cambered_leaf(
313:             CamberedLeaf {
314:                 centre: Position::<LitterPatch>::from_metres(Vec3::new(centre.x, 0.0, centre.y))?,
315:                 long: Displacement::from_metres(Vec3::new(long.x, 0.0, long.y))?,
316:                 side: Displacement::from_metres(Vec3::new(side.x, 0.0, side.y))?,
317:                 height: Elevation::from_metres(if leaf % 5 == 0 {
318:                     0.004 + streams::LEAF_HEIGHT.rng(hash, &[]).inclusive_unit_f32() * 0.008
319:                 } else {
320:                     streams::LEAF_HEIGHT.rng(hash, &[]).inclusive_unit_f32() * 0.0015
321:                 })?,
322:             },
323:             hash,
324:             leaf_colors[leaf as usize % leaf_colors.len()],
325:         );
326:     }
327:     Ok(data.into_mesh())
328: }
