330: /// Independent twig mesh. Longer, thinner pieces and a lower spawn density
331: /// let twigs form irregular accents over the denser dry-leaf carpet.
332: pub(super) fn twig_patch_mesh(variant: u64) -> GeometryResult<Mesh> {
333:     let mut data = GroundLitterMeshData::default();
334:     let twig_colors = [
335:         Color::srgb_u8(79, 47, 24),
336:         Color::srgb_u8(102, 62, 29),
337:         Color::srgb_u8(62, 40, 25),
338:     ];
339:     for twig in 0..TWIGS_PER_PATCH {
340:         let hash = streams::TWIG.seed(variant.into(), &[twig]);
341:         let centre = Vec2::new(
342:             streams::CENTER_X.rng(hash, &[]).inclusive_unit_f32() - 0.5,
343:             streams::CENTER_Z.rng(hash, &[]).inclusive_unit_f32() - 0.5,
344:         ) * 1.02;
345:         let angle = streams::ANGLE.rng(hash, &[]).inclusive_unit_f32() * core::f32::consts::TAU;
346:         let long = Vec2::new(angle.cos(), angle.sin())
347:             * (0.075 + streams::LENGTH.rng(hash, &[]).inclusive_unit_f32() * 0.07);
348:         let lateral = Vec2::new(-long.y, long.x).normalize_or_zero();
349:         let start = Vec3::new(centre.x - long.x, -0.004, centre.y - long.y);
350:         let bend = (streams::WIDTH.rng(hash, &[]).inclusive_unit_f32() - 0.5) * 0.055;
351:         let middle = Vec3::new(
352:             centre.x + lateral.x * bend,
353:             0.002 + streams::TWIG_LIFT.rng(hash, &[]).inclusive_unit_f32() * 0.004,
354:             centre.y + lateral.y * bend,
355:         );
356:         let end = Vec3::new(centre.x + long.x, -0.006, centre.y + long.y);
357:         let cross_section = if streams::TWIG_SIDES.rng(hash, &[]).index(2) == 0 {
358:             TwigCrossSection::Pentagonal
359:         } else {
360:             TwigCrossSection::Hexagonal
361:         };
362:         let radius = 0.006 + streams::TWIG_RADIUS.rng(hash, &[]).inclusive_unit_f32() * 0.005;
363:         let color = twig_colors[twig as usize % twig_colors.len()];
364:         data.append_bent_twig(
365:             BentTwig {
366:                 stations: [
367:                     TwigStation {
368:                         centre: Position::from_metres(start)?,
369:                         radius: PositiveLength::from_metres(radius)?,
370:                     },
371:                     TwigStation {
372:                         centre: Position::from_metres(middle)?,
373:                         radius: PositiveLength::from_metres(radius * 0.58)?,
374:                     },
375:                     TwigStation {
376:                         centre: Position::from_metres(end)?,
377:                         radius: PositiveLength::from_metres(radius * 0.08)?,
378:                     },
379:                 ],
380:                 cross_section,
381:                 base: TwigBase::Closed,
382:                 root: Position::from_metres(Vec3::new(centre.x, 0.0, centre.y))?,
383:             },
384:             color,
385:         );
386:         if twig < 2 && streams::TWIG_FORK.rng(hash, &[]).inclusive_unit_f32() > 0.46 {
387:             let attach = middle.lerp(end, 0.22);
388:             let direction = (end - middle).normalize();
389:             let lateral = Vec3::new(-direction.z, 0.12, direction.x).normalize();
390:             let fork_end = attach
391:                 + (direction * 0.38
392:                     + lateral
393:                         * if streams::TWIG_FORK_SIDE.rng(hash, &[]).boolean() {
394:                             0.62
395:                         } else {
396:                             -0.62
397:                         })
398:                 .normalize()
399:                     * long.length()
400:                     * 0.72;
401:             let fork_middle = attach.lerp(fork_end, 0.52) + Vec3::Y * 0.002;
402:             data.append_bent_twig(
403:                 BentTwig {
404:                     stations: [
405:                         TwigStation {
406:                             centre: Position::from_metres(attach)?,
407:                             radius: PositiveLength::from_metres(radius * 0.55)?,
408:                         },
409:                         TwigStation {
410:                             centre: Position::from_metres(fork_middle)?,
411:                             radius: PositiveLength::from_metres(radius * 0.3)?,
412:                         },
413:                         TwigStation {
414:                             centre: Position::from_metres(fork_end)?,
415:                             radius: PositiveLength::from_metres(radius * 0.05)?,
416:                         },
417:                     ],
418:                     cross_section,
419:                     base: TwigBase::ForkAttachment,
420:                     root: Position::from_metres(Vec3::new(centre.x, 0.0, centre.y))?,
421:                 },
422:                 color,
423:             );
424:         }
425:     }
426:     Ok(data.into_mesh())
427: }
