429: /// A sparse shade-floor rosette. Seven-vertex cambered leaves provide a
430: /// readable close silhouette without introducing a textured albedo or the
431: /// single-triangle markers formerly used for tiny meadow accents.
432: pub(super) fn woodland_plant_patch_mesh(variant: u64) -> GeometryResult<Mesh> {
433:     let mut data = GroundLitterMeshData::default();
434:     let palette = [
435:         Color::srgb_u8(48, 79, 35),
436:         Color::srgb_u8(57, 91, 40),
437:         Color::srgb_u8(40, 68, 31),
438:     ];
439:     let plant_count = 2 + variant % 2;
440:     for plant in 0..plant_count {
441:         let plant_hash = streams::PLANT.seed(variant.into(), &[plant]);
442:         let centre = Vec2::new(
443:             streams::PLANT_CENTER_X
444:                 .rng(plant_hash, &[])
445:                 .inclusive_unit_f32()
446:                 - 0.5,
447:             streams::PLANT_CENTER_Z
448:                 .rng(plant_hash, &[])
449:                 .inclusive_unit_f32()
450:                 - 0.5,
451:         ) * 0.62;
452:         let leaf_count = 5 + streams::LEAF_COUNT.rng(plant_hash, &[]).index(3) as u64;
453:         let phase = streams::PLANT_PHASE
454:             .rng(plant_hash, &[])
455:             .inclusive_unit_f32()
456:             * core::f32::consts::TAU;
457:         for leaf in 0..leaf_count {
458:             let hash = streams::PLANT_LEAF.seed(plant_hash, &[leaf]);
459:             let angle = phase
460:                 + leaf as f32 * core::f32::consts::TAU / leaf_count as f32
461:                 + (streams::CENTER_X.rng(hash, &[]).inclusive_unit_f32() - 0.5) * 0.28;
462:             let length = 0.11 + streams::LENGTH.rng(hash, &[]).inclusive_unit_f32() * 0.075;
463:             let width = length * (0.19 + streams::WIDTH.rng(hash, &[]).inclusive_unit_f32() * 0.08);
464:             data.append_rosette_leaf(
465:                 RosetteLeaf {
466:                     root: Position::from_metres(Vec3::new(centre.x, 0.0, centre.y))?,
467:                     direction: PlanDirection::from_normalized(Vec2::new(angle.cos(), angle.sin()))?,
468:                     length: PositiveLength::from_metres(length)?,
469:                     width: PositiveLength::from_metres(width)?,
470:                     rise: Elevation::from_metres(
471:                         0.055 + streams::TWIG_RADIUS.rng(hash, &[]).inclusive_unit_f32() * 0.055,
472:                     )?,
473:                 },
474:                 palette[(plant as usize + leaf as usize) % palette.len()],
475:             );
476:         }
477:     }
478:     Ok(data.into_mesh())
479: }
