481: fn batched_litter_visibility(local_end_metres: f32) -> VisibilityRange {
482:     // Each entity contains debris distributed across a large cell. Measuring
483:     // visibility from the cell-corner entity translation can therefore hide
484:     // geometry beside the camera. Use the merged mesh bounds and pad the
485:     // cutoff by the greatest possible centre-to-edge distance so the range
486:     // still describes distance from the debris itself.
487:     let batch_end = local_end_metres + LITTER_BATCH_HALF_DIAGONAL_METRES;
488:     VisibilityRange {
489:         start_margin: 0.0..0.0,
490:         end_margin: batch_end..batch_end,
491:         use_aabb: true,
492:     }
493: }
494: 
495: fn leaf_litter_proximity(ground: &SceneGround, grid_x: usize, grid_z: usize) -> f32 {
496:     let radius = (WOODLAND_FLOOR_TRANSITION_METRES / ground.grid_scale()).ceil() as isize;
497:     let mut nearest: Option<NonnegativeLength> = None;
498:     for dz in -radius..=radius {
499:         for dx in -radius..=radius {
500:             let x = grid_x as isize + dx;

501:             let z = grid_z as isize + dz;
502:             if x < 0
503:                 || z < 0
504:                 || x >= ground.grid_width() as isize
505:                 || z >= ground.grid_depth() as isize
506:                 || ground.samples()[z as usize * ground.grid_width() + x as usize].cover
507:                     != GroundCover::LeafLitter
508:             {
509:                 continue;
510:             }
511:             let distance = Vec2::new(dx as f32, dz as f32).length() * ground.grid_scale();
512:             let Ok(distance) = NonnegativeLength::from_arithmetic(distance) else {
513:                 continue;
514:             };
515:             nearest = Some(nearest.map_or(distance, |nearest| {
516:                 if distance < nearest {
517:                     distance
518:                 } else {
519:                     nearest
520:                 }
521:             }));
522:         }
523:     }
524:     nearest.map_or(0.0, |nearest| {
525:         (1.0 - nearest.metres() / WOODLAND_FLOOR_TRANSITION_METRES).clamp(0.0, 1.0)
526:     })
527: }
