1: //! Admit complete authored litter meshes before publishing retained handles.
2: use super::*;
3: use crate::presentation::ground_scatter::GroundFoliagePresentationCache;
4: use bevy::asset::Assets as MeshAssets;
5: 
6: pub(in crate::presentation::ground_scatter) struct PatchMeshes {
7:     pub dry_leaves: Vec<Handle<Mesh>>,
8:     pub twigs: Vec<Handle<Mesh>>,
9:     pub plants: Vec<Handle<Mesh>>,
10: }
11: 
12: enum PreparedFamily {
13:     Retained(Vec<Handle<Mesh>>),
14:     Generated(Vec<Mesh>),
15: }
16: impl PreparedFamily {
17:     fn prepare(
18:         existing: &Option<Vec<Handle<Mesh>>>,
19:         variant_count: u64,
20:         generate: fn(u64) -> GeometryResult<Mesh>,
21:     ) -> GeometryResult<Self> {
22:         if let Some(existing) = existing {
23:             return Ok(Self::Retained(existing.clone()));
24:         }
25:         // Native catalogue ordinals are admitted to checked recipe geometry.
26:         (0..variant_count)
27:             .map(generate)
28:             .collect::<GeometryResult<Vec<_>>>()
29:             .map(Self::Generated)
30:     }
31:     fn install(
32:         self,
33:         cache: &mut Option<Vec<Handle<Mesh>>>,
34:         meshes: &mut MeshAssets<Mesh>,
35:     ) -> Vec<Handle<Mesh>> {
36:         match self {
37:             Self::Retained(handles) => handles,
38:             Self::Generated(generated) => {
39:                 let handles: Vec<_> = generated.into_iter().map(|mesh| meshes.add(mesh)).collect();
40:                 *cache = Some(handles.clone());
41:                 handles
42:             }
43:         }
44:     }
45: }
46: 
47: pub(in crate::presentation::ground_scatter) fn prepare_meshes(
48:     cache: &mut GroundFoliagePresentationCache,
49:     meshes: &mut MeshAssets<Mesh>,
50: ) -> GeometryResult<PatchMeshes> {
51:     // Validate every missing family before changing any retained cache entry.
52:     let dry_leaves = PreparedFamily::prepare(
53:         &cache.dry_leaf_meshes,
54:         DRY_LEAF_MESH_VARIANTS,
55:         dry_leaf_patch_mesh,
56:     )?;
57:     let twigs = PreparedFamily::prepare(&cache.twig_meshes, TWIG_MESH_VARIANTS, twig_patch_mesh)?;
58:     let plants = PreparedFamily::prepare(
59:         &cache.woodland_plant_meshes,
60:         WOODLAND_PLANT_MESH_VARIANTS,
61:         woodland_plant_patch_mesh,
62:     )?;
63:     Ok(PatchMeshes {
64:         dry_leaves: dry_leaves.install(&mut cache.dry_leaf_meshes, meshes),
65:         twigs: twigs.install(&mut cache.twig_meshes, meshes),
66:         plants: plants.install(&mut cache.woodland_plant_meshes, meshes),
67:     })
68: }
