1: //! Keep reusable litter prototypes on the CPU and upload only assembled batches.
2: 
3: use super::*;
4: use bevy::asset::RenderAssetUsages;
5: 
6: pub(super) fn append_litter_batch(
7:     meshes: &bevy::prelude::Assets<Mesh>,
8:     source: &Handle<Mesh>,
9:     placement: LitterPlacement,
10:     batches: &mut BTreeMap<(i32, i32), LitterBatch>,
11: ) -> Result<(), bevy::mesh::MeshMergeError> {
12:     let mut transform = Transform {
13:         translation: placement.root.metres(),
14:         rotation: placement.rotation,
15:         scale: placement.scale,
16:     };
17:     let cell_size = LITTER_BATCH_CELL_METRES;
18:     let cell = (
19:         (transform.translation.x / cell_size).floor() as i32,
20:         (transform.translation.z / cell_size).floor() as i32,
21:     );
22:     transform.translation.x -= cell.0 as f32 * cell_size;
23:     transform.translation.z -= cell.1 as f32 * cell_size;
24:     let Some(source) = meshes.get(source) else {
25:         return Ok(());
26:     };
27:     let mut transformed = source.clone().transformed_by(transform);
28:     transformed.asset_usage = RenderAssetUsages::RENDER_WORLD;
29:     let batch = batches.entry(cell).or_default();
30:     let slot = match placement.kind {
31:         BatchKind::Leaves => &mut batch.leaves,
32:         BatchKind::Twigs => &mut batch.twigs,
33:         BatchKind::Plants => &mut batch.plants,
34:     };
35:     if let Some(batch) = slot {
36:         batch.merge(&transformed)?;
37:     } else {
38:         *slot = Some(transformed);
39:     }
40:     Ok(())
41: }
42: 
43: pub(super) fn spawn_batches(
44:     commands: &mut Commands,
45:     meshes: &mut bevy::prelude::Assets<Mesh>,
46:     assets: &Assets,
47:     batches: BTreeMap<(i32, i32), LitterBatch>,
48: ) {
49:     for ((cell_x, cell_z), batch) in batches {
50:         let transform = Transform::from_xyz(
51:             cell_x as f32 * LITTER_BATCH_CELL_METRES,
52:             0.0,
53:             cell_z as f32 * LITTER_BATCH_CELL_METRES,
54:         );
55:         if let Some(mesh) = batch.leaves {
56:             commands.spawn((
57:                 Name::new("Batched tactical dry leaves"),
58:                 GroundScatterLayer::DryLeaves,
59:                 NotShadowCaster,
60:                 Mesh3d(meshes.add(mesh)),
61:                 MeshMaterial3d(assets.dry_leaf_material.clone()),
62:                 batched_litter_visibility(DRY_LEAF_LOCAL_END_METRES),
63:                 transform,
64:             ));
65:         }
66:         if let Some(mesh) = batch.twigs {
67:             commands.spawn((
68:                 Name::new("Batched tactical twigs"),
69:                 GroundScatterLayer::Twigs,
70:                 NotShadowCaster,
71:                 Mesh3d(meshes.add(mesh)),
72:                 MeshMaterial3d(assets.twig_material.clone()),
73:                 batched_litter_visibility(TWIG_LOCAL_END_METRES),
74:                 transform,
75:             ));
76:         }
77:         if let Some(mesh) = batch.plants {
78:             commands.spawn((
79:                 Name::new("Batched tactical woodland-floor plants"),
80:                 GroundScatterLayer::Understory,
81:                 NotShadowCaster,
82:                 Mesh3d(meshes.add(mesh)),
83:                 MeshMaterial3d(assets.woodland_plant_material.clone()),
