1: //! Select nearby rendered litter roots independently of mesh batch origins.
2: use adventuresim_building_generator::spatial_geometry::Position;
3: use adventuresim_tactical_core::{animation::NonnegativeLength, scene_coordinates::Scene};
4: use bevy::math::Vec2;
5: use std::collections::BTreeMap;
6: 
7: /// Real generated litter placements retained independently of batched mesh origins.
8: /// Capture diagnostics use this pair to frame dry leaves and twigs without
9: /// mistaking a shared batch-cell transform for the rendered subjects.
10: #[derive(Clone, Copy, Debug, PartialEq)]
11: pub(crate) struct GroundLitterCapturePair {
12:     pub(crate) dry_leaf: Position<Scene>,
13:     pub(crate) twig: Position<Scene>,
14: }
15: 
16: struct PairCandidate {
17:     separation: NonnegativeLength,
18:     pair: GroundLitterCapturePair,
19: }
20: 
21: impl GroundLitterCapturePair {
22:     pub(crate) const MAXIMUM_SEPARATION: NonnegativeLength =
23:         match NonnegativeLength::from_metres(0.55) {
24:             Ok(distance) => distance,
25:             Err(_) => {
26:                 panic!("the authored litter capture separation must be finite and nonnegative")
27:             }
28:         };
29: 
30:     pub(in crate::presentation::ground_scatter::litter) fn closest(
31:         leaf_positions: &[Position<Scene>],
32:         twig_positions: &[Position<Scene>],
33:         maximum_separation: NonnegativeLength,
34:         maximum_pairs: usize,
35:     ) -> Vec<Self> {
36:         if maximum_separation == NonnegativeLength::ZERO || maximum_pairs == 0 {
37:             return Vec::new();
38:         }
39:         // The native spatial hash and distance sort operate in scene metres;
40:         // candidates retain checked roots and lengths outside those equations.
41:         let cell_size = maximum_separation.metres();
42:         let cell = |position: Position<Scene>| {
43:             let position = position.metres();
44:             (
45:                 (position.x / cell_size).floor() as i32,
46:                 (position.z / cell_size).floor() as i32,
47:             )
48:         };
49:         let mut leaves_by_cell = BTreeMap::<(i32, i32), Vec<Position<Scene>>>::new();
50:         for &leaf in leaf_positions {
51:             leaves_by_cell.entry(cell(leaf)).or_default().push(leaf);
52:         }
53:         let mut candidates = Vec::<PairCandidate>::new();
54:         for &twig in twig_positions {
55:             let (cell_x, cell_z) = cell(twig);
56:             for dz in -1..=1 {
57:                 for dx in -1..=1 {
58:                     let Some(leaves) = leaves_by_cell.get(&(cell_x + dx, cell_z + dz)) else {
59:                         continue;
60:                     };
61:                     for &leaf in leaves {
62:                         let leaf_metres = leaf.metres();
63:                         let twig_metres = twig.metres();
64:                         let distance = Vec2::new(leaf_metres.x, leaf_metres.z)
65:                             .distance(Vec2::new(twig_metres.x, twig_metres.z));
66:                         if distance > cell_size {
67:                             continue;
68:                         }
69:                         let Ok(separation) = NonnegativeLength::from_arithmetic(distance) else {
70:                             continue;
71:                         };
72:                         candidates.push(PairCandidate {
73:                             separation,
74:                             pair: Self {
75:                                 dry_leaf: leaf,
76:                                 twig,
77:                             },
78:                         });
79:                     }
80:                 }
81:             }
82:         }
83:         candidates.sort_by(|left, right| {
84:             left.separation
85:                 .metres()
86:                 .total_cmp(&right.separation.metres())
87:                 .then_with(|| {
88:                     left.pair
89:                         .dry_leaf
90:                         .metres()
91:                         .x
92:                         .total_cmp(&right.pair.dry_leaf.metres().x)
93:                 })
94:                 .then_with(|| {
95:                     left.pair
96:                         .dry_leaf
97:                         .metres()
98:                         .z
99:                         .total_cmp(&right.pair.dry_leaf.metres().z)
100:                 })
101:                 .then_with(|| {
102:                     left.pair
103:                         .twig
104:                         .metres()
105:                         .x
106:                         .total_cmp(&right.pair.twig.metres().x)
107:                 })
108:                 .then_with(|| {
109:                     left.pair
110:                         .twig
111:                         .metres()
112:                         .z
113:                         .total_cmp(&right.pair.twig.metres().z)
114:                 })
115:         });
116:         candidates
117:             .into_iter()
118:             .take(maximum_pairs)
119:             .map(|candidate| candidate.pair)
120:             .collect()
121:     }
122: }

