10: use fabelgeist_determinism::Seed;
11: 
12: pub(super) struct LitterPlacement {
13:     pub(super) root: Position<Scene>,
14:     pub(super) rotation: Quat,
15:     pub(super) scale: Vec3,
16:     pub(super) kind: BatchKind,
17: }
18: 
19: impl LitterPlacement {
20:     pub(super) fn new(
21:         terrain: &SceneTerrain,
22:         ground: &SceneGround,
23:         cell_origin: ScenePlanPoint,
24:         hash: Seed,
25:         kind: BatchKind,
26:     ) -> Option<Self> {
27:         // Native seeded jitter and slope alignment share the original draw and
28:         // arithmetic order; the completed root is admitted before retaining it.
29:         let jitter = ground.grid_scale() * 0.78;
30:         let position = cell_origin.metres()
31:             + Vec2::new(
32:                 streams::CELL_JITTER_X.rng(hash, &[]).inclusive_unit_f32() - 0.5,
33:                 streams::CELL_JITTER_Z.rng(hash, &[]).inclusive_unit_f32() - 0.5,
34:             ) * jitter;
35:         let point = ScenePlanPoint::from_metres(position)?;
36:         if ground.ground_at(point).is_none_or(|sample| {
37:             !matches!(
38:                 sample.cover,
39:                 GroundCover::LeafLitter | GroundCover::TallGrass
40:             )
41:         }) {
42:             return None;
43:         }
44:         let height = terrain.height_at(point)?;
45:         let normal = terrain.normal_at(point)?;
46:         if normal.y < 0.72 {
47:             return None;
48:         }
49:         let terrain_rotation = Quat::from_rotation_arc(Vec3::Y, *normal);
50:         let yaw = Quat::from_rotation_y(
51:             PLACEMENT_YAW.rng(hash, &[]).inclusive_unit_f32() * core::f32::consts::TAU,
52:         );
53:         let scale = 0.72 + PLACEMENT_SCALE.rng(hash, &[]).inclusive_unit_f32() * 0.58;
54:         let height_offset = match kind {
55:             BatchKind::Leaves => 0.001,
56:             BatchKind::Twigs => 0.006,
57:             BatchKind::Plants => 0.004,
58:         };
59:         let root = Position::from_metres(Vec3::new(
60:             point.metres().x,
61:             height.metres() + height_offset,
62:             point.metres().y,
63:         ))
64:         .ok()?;
65:         let scale = Vec3::splat(scale)
66:             * match kind {
67:                 BatchKind::Leaves => 0.8,
68:                 BatchKind::Twigs => 0.72,
69:                 BatchKind::Plants => 0.7,
70:             };
71:         Some(Self {
72:             root,
73:             rotation: terrain_rotation * yaw,
74:             scale,
75:             kind,
76:         })
77:     }
78: }
