100: struct PatchAssets {
101:     hero_meshes: Vec<Handle<Mesh>>,
102:     near_meshes: Vec<Handle<Mesh>>,
103:     billboard_meshes: Vec<Handle<Mesh>>,
104:     pebble_counts: Vec<usize>,
105:     stone_material: Handle<TacticalPebbleMaterial>,
