166: struct PatchPlacement {
167:     variant: usize,
168:     woodland: bool,
169:     transform: Transform,
170: }
171: impl PatchPlacement {
172:     fn new(
173:         ground: &SceneGround,
174:         terrain: &SceneTerrain,
175:         index: usize,
176:         sample: GroundSurface,
177:         base_seed: Seed,
178:         half_extent: f32,
179:     ) -> Option<Self> {
180:         if !matches!(
181:             sample.cover,
182:             GroundCover::LooseStone | GroundCover::LeafLitter
183:         ) {
184:             return None;
185:         }
186:         let grid_x = index % ground.grid_width();
187:         let grid_z = index / ground.grid_width();
188:         let position = Vec2::new(
189:             grid_x as f32 * ground.grid_scale() - ground.width() * 0.5,
190:             grid_z as f32 * ground.grid_scale() - ground.depth() * 0.5,
191:         );
192:         let position = ScenePlanPoint::from_metres(position)?;
193:         // The patch can rotate and tilt. Exclude its full existing bounds,
194:         // including pebble overhang, from exact managed-ground ownership.
195:         let envelope_radius = Vec3::new(half_extent + 0.3, 0.4, half_extent + 0.3).length();
196:         if ground.urban.overlaps_disk(position, envelope_radius) {
197:             return None;
198:         }
199:         let (Some(height), Some(normal)) =
200:             (terrain.height_at(position), terrain.normal_at(position))
201:         else {
202:             return None;
203:         };
204:         if normal.y < 0.72 {
205:             return None;
206:         }
207:         let hash = StreamId::new("visual.ground-scatter.loose-stone.scatter")
208:             .seed(base_seed, &[index as u64]);
209:         let woodland = sample.cover == GroundCover::LeafLitter;
210:         let density = if woodland {
211:             // Every woodland cell gets a sparse candidate patch. Individual
212:             // survival still leaves irregular gaps, but keeping the patches
213:             // continuous yields roughly one visible 3--8 cm stone per square
214:             // metre instead of making rocks disappear from review frames.
215:             PebbleDensity::Woodland
216:         } else {
217:             let coverage = scree_patch_coverage(base_seed, position, normal);
218:             if coverage >= 0.61 {
219:                 PebbleDensity::Dense
220:             } else if coverage >= 0.34 {
221:                 PebbleDensity::Sparse
222:             } else {
223:                 return None;
224:             }
225:         };
226:         let variant = density.asset_offset()
227:             + StreamId::new("visual.ground-scatter.loose-stone.spawn.mesh-variant")
228:                 .rng(hash, &[])
229:                 .index(MESH_VARIANTS as usize);
230:         let yaw = Quat::from_rotation_y(
231:             StreamId::new("visual.ground-scatter.loose-stone.spawn.yaw")
232:                 .rng(hash, &[])
233:                 .inclusive_unit_f32()
234:                 * core::f32::consts::TAU,
235:         );
236:         let transform = Transform::from_xyz(
237:             position.metres().x,
238:             height.metres() + if woodland { -0.006 } else { 0.006 },
239:             position.metres().y,
240:         )
241:         .with_rotation(Quat::from_rotation_arc(Vec3::Y, *normal) * yaw)
242:         .with_scale(Vec3::splat(if woodland { 0.58 } else { 1.0 }));
243: 
244:         Some(Self {
245:             variant,
246:             woodland,
247:             transform,
248:         })
249:     }
250: }

