231: pub(super) fn update_celestial_material_lighting(
232:     celestial: Res<PresentedCelestialLighting>,
233:     mut bark_materials: ResMut<Assets<TacticalTreeBarkMaterial>>,
234:     mut impostor_materials: ResMut<Assets<TacticalTreeImpostorMaterial>>,
235:     mut pebble_materials: ResMut<Assets<TacticalPebbleBillboardMaterial>>,
236:     mut written: Local<Option<(Vec4, Vec4)>>,
237:     mut foliage_materials: ResMut<Assets<TacticalFoliageMaterial>>,
238: ) {
239:     if !celestial.is_changed() {
240:         return;
241:     }
242:     let Some(celestial) = celestial.snapshot.as_ref() else {
243:         return;
244:     };
245:     let direction = if celestial.sun_altitude_degrees > -6.0 {
246:         celestial.sun_direction
247:     } else if celestial.moon_altitude_degrees > -2.0 {
248:         celestial.moon_direction
249:     } else {
250:         Vec3::new(0.25, 0.92, 0.3).normalize()
251:     };
252:     // The presented snapshot refreshes on every replicated environment tick,
253:     // but celestial motion is glacial on gameplay timescales. Rewriting the
254:     // material assets dirties them and re-queues every tree and pebble, so
255:     // skip the write until the change would be visible.
256:     let lighting = direction.extend(celestial.material_light_factor);
257:     let ambient = celestial
258:         .ambient_color
259:         .extend(celestial.material_ambient_response);
260:     if written.is_some_and(|(written_lighting, written_ambient)| {
261:         written_lighting.distance_squared(lighting) < 1e-6
262:             && written_ambient.distance_squared(ambient) < 1e-6
263:     }) {
264:         return;
265:     }
266:     *written = Some((lighting, ambient));
267:     for (_, material) in bark_materials.iter_mut() {
268:         material.extension.lighting = lighting;
269:     }
270:     for (_, material) in impostor_materials.iter_mut() {
271:         material.lighting = lighting;
272:         material.ambient = ambient;
273:     }
274:     for (_, material) in pebble_materials.iter_mut() {
275:         material.lighting = lighting;
276:         material.ambient = ambient;
277:     }
278:     for (_, material) in foliage_materials.iter_mut() {
279:         if material.quality.x > 0.5 {
280:             material.lighting = direction.extend(celestial.material_light_factor);
281:             material.ambient = celestial
282:                 .ambient_color
283:                 .extend(celestial.material_ambient_response);
284:         }
285:     }
286: }
