292: pub(super) fn spawn_ground_foliage(
293:     commands: &mut Commands,
294:     meshes: &mut Assets<Mesh>,
295:     materials: &mut Assets<TacticalFoliageMaterial>,
296:     standard_materials: &mut Assets<StandardMaterial>,
297:     pebble_materials: &mut Assets<TacticalPebbleMaterial>,
298:     pebble_billboard_materials: &mut Assets<TacticalPebbleBillboardMaterial>,
299:     leaf_materials: &mut Assets<TacticalTreeLeafCardMaterial>,
300:     understory_cache: &mut WoodyUnderstoryPresentationCache,
301:     ground_foliage_cache: &mut GroundFoliagePresentationCache,
302:     procedural_assets: &ProceduralTextureAssets,
303:     scene_id: &SceneId,
304:     terrain: &SceneTerrain,
305:     ground: &SceneGround,
306:     environment: &SceneEnvironment,
307:     shrub_bark_materials: &mut Assets<TacticalShrubBarkInstancedMaterial>,
308:     shrub_leaf_materials: &mut Assets<TacticalShrubLeafInstancedMaterial>,
309: ) -> GroundScatterResult<()> {
310:     let canopy = bps(environment.canopy_bps);
311:     let wetland = bps(environment.wetland_bps);
312:     let cultivation = bps(environment.cultivation_bps);
313:     // Equal-area QHD benchmarks show that the full woody hazel/reed-like
314:     // specimen, rather than the trees themselves, dominates dense woodland
315:     // and wetland cost. Keep sparse woodland's established occupancy while
316:     // capping denser biomes near one plant in four lattice cells. This leaves
317:     // traversable openings and gives every terrain family a comparable GPU
318:     // budget without reducing the much cheaper canopy-tree population.
319:     let understory_chance = understory_scatter_chance(canopy, wetland, cultivation);
320:     // The playable grass sward is generated by `instanced_grass`; this pass
321:     // only builds the litter, loose stone, and woody understory layers.
322:     ensure_understory_presentations(
323:         meshes,
324:         standard_materials,
325:         leaf_materials,
326:         understory_cache,
327:         procedural_assets,
328:     );
329:     let litter::PatchMeshes {
330:         dry_leaves: dry_leaf_meshes,
331:         twigs: twig_meshes,
332:         plants: woodland_plant_meshes,
333:     } = litter::prepare_meshes(ground_foliage_cache, meshes)?;
334:     let dry_leaf_material = ground_foliage_cache
335:         .forest_floor_leaves
336:         .get_or_insert_with(|| leaf_materials.add(forest_floor_leaf_material(procedural_assets)))
337:         .clone();
338:     let twig_material = ground_foliage_cache
339:         .twig_material
340:         .get_or_insert_with(|| standard_materials.add(litter::static_twig_material()))
341:         .clone();
342:     let woodland_plant_material = ground_foliage_cache
343:         .woodland_plant_material
344:         .get_or_insert_with(|| materials.add(foliage_material(0.035, false)))
345:         .clone();
346:     let base_seed = scatter_seed(&environment.scene_digest, &scene_id.0);
347:     // Grass uses a macro patch whose internal blade spacing matches the old
348:     // one-metre patch. A roughly ten-times larger footprint therefore retains
349:     // density while cutting extraction, visibility, and instance entities by
350:     // an order of magnitude. Macro patches stay unit-scale and nearly gridded:
351:     // randomly shrinking/rotating the square footprint opened visible seams.
352:     // Aligning each patch to the sampled terrain normal keeps the shared plane
353:     // seated on slopes while its blades retain deterministic local variation.
354: 
355:     let understory_habitat = understory::UnderstoryHabitat {
356:         canopy,
357:         wetland,
358:         cultivation,
359:         moisture: bps(environment.weather.ground_moisture_bps),
360:     };
361:     instanced_understory::spawn(
362:         commands,
363:         shrub_bark_materials,
364:         shrub_leaf_materials,
365:         standard_materials,
366:         leaf_materials,
367:         understory_cache,
368:         terrain,
369:         ground,
370:         base_seed,
371:         understory_chance,
372:         understory_habitat,
373:     );
374: 
375:     litter::spawn(
376:         commands,
377:         meshes,
378:         terrain,
379:         ground,
380:         base_seed,
381:         &litter::Assets {
382:             dry_leaf_meshes,
383:             twig_meshes,
384:             dry_leaf_material,
385:             twig_material,
386:             woodland_plant_meshes,
387:             woodland_plant_material,
388:         },
389:     )?;
390: 
391:     loose_stone::spawn(
392:         commands,
393:         meshes,
394:         pebble_materials,
395:         pebble_billboard_materials,
396:         terrain,
397:         ground,
398:         base_seed,
399:     );
400:     Ok(())
401: }
