403: fn understory_scatter_chance(canopy: f32, wetland: f32, cultivation: f32) -> f32 {
404:     // This is intentionally about 70% below the original physical-shrub
405:     // occupancy. Community multipliers retain dense, readable clumps rather
406:     // than turning the reduced population into evenly spaced specimens.
407:     (canopy * 0.156 + wetland * 0.09 + cultivation * 0.024).clamp(0.0, 0.075)
408: }
