410: pub(in crate::presentation) fn grass_scatter_density(
411:     canopy: f32,
412:     water: f32,
413:     cultivation: f32,
414:     snow: f32,
415: ) -> f32 {
416:     // Deep shade and standing water should expose litter, mud, and hummocks;
417:     // a quarter-density floor still read as an implausible meadow and made
418:     // woodland traversal a wall of overlapping rectangular blade ribbons.
419:     (0.98 - canopy * 0.95 - water * 0.88 + cultivation * 0.04).clamp(0.08, 0.98)
420:         * (1.0 - snow * 1.25).clamp(0.12, 1.0)
421: }
