111: fn placements(
112:     terrain: &SceneTerrain,
113:     ground: &SceneGround,
114:     environment: &SceneEnvironment,
115:     seed: Seed,
116: ) -> GeometryResult<Vec<PlantSite>> {
117:     let count_x = (terrain.width() / SITE_SPACING_METRES).floor() as i32;
118:     let count_z = (terrain.depth() / SITE_SPACING_METRES).floor() as i32;
119:     let mut candidates = Vec::new();
120:     let cover =
121:         super::cover_mask::CoverageMask::new(ground, stable_text_seed(&environment.scene_digest))?;
122:     for z in 0..count_z {
123:         for x in 0..count_x {
124:             let hash = streams::SITE.seed(seed, &[x as u64, z as u64]);
125:             if streams::PRESENCE.rng(hash, &[]).inclusive_unit_f32() > OCCUPANCY {
126:                 continue;
127:             }
128:             let world = Vec2::new(
129:                 -terrain.width() * 0.5
130:                     + (x as f32
131:                         + 0.15
132:                         + streams::JITTER_X.rng(hash, &[]).inclusive_unit_f32() * 0.7)
133:                         * SITE_SPACING_METRES,
134:                 -terrain.depth() * 0.5
135:                     + (z as f32
136:                         + 0.15
137:                         + streams::JITTER_Z.rng(hash, &[]).inclusive_unit_f32() * 0.7)
138:                         * SITE_SPACING_METRES,
139:             );
140:             let Some(world) = ScenePlanPoint::from_metres(world) else {
141:                 continue;
142:             };
143:             let (Some(surface), Some(height), Some(normal)) = (
144:                 ground.ground_at(world),
145:                 terrain.height_at(world),
146:                 terrain.normal_at(world),
147:             ) else {
148:                 continue;
149:             };
150:             if normal.y < MIN_SLOPE_NORMAL_Y || !open_understory_site(&cover, world) {
151:                 continue;
152:             }
153:             let habitat = habitat(surface, environment);
154:             // A shared macro-cell roll gives patches botanical coherence; roots
155:             // retain independent jitter so the planting lattice is not visible.
156:             let community = streams::COMMUNITY.seed(seed, &[(x / 3) as u64, (z / 3) as u64]);
157:             let weights = PlantSpecies::ALL.map(|species| {
158:                 (species.habitat_weight(habitat)
159:                     * f32::from(adventuresim_world_schema::BASIS_POINTS_PER_WHOLE))
160:                 .round() as u64
161:             });
162:             let Ok(species) = streams::SPECIES
163:                 .rng(community, &[])
164:                 .weighted_index(&weights)
165:             else {
166:                 continue;
167:             };
168:             let Ok(root) = Position::from_metres(Vec3::new(
169:                 world.metres().x,
170:                 height.metres() - ROOT_EMBED_METRES,
171:                 world.metres().y,
172:             )) else {
173:                 continue;
174:             };
175:             candidates.push(PlantSite {
176:                 root,
177:                 species: PlantSpecies::ALL[species],
178:                 hash,
179:             });
180:         }
181:     }
182:     // Stable priority sampling spreads the bounded population over the entire
183:     // scene; truncating row order would leave one populated corner.
184:     candidates.sort_by_key(|site| {
185:         (
186:             site.hash,
187:             site.root.metres().x.to_bits(),
188:             site.root.metres().z.to_bits(),
189:         )
190:     });
191:     candidates.truncate(MAX_SPECIMENS);
192:     Ok(candidates)
193: }
194: 
195: /// Shoots occupy existing vegetation openings, never clear their own.
196: fn open_understory_site(cover: &super::cover_mask::CoverageMask, point: ScenePlanPoint) -> bool {
197:     const MAX_GRASS_COVERAGE: u8 = 64;
198:     const SHOOT_CLEARANCE_METRES: f32 = 0.4;
199:     [Vec2::ZERO, Vec2::X, Vec2::NEG_X, Vec2::Y, Vec2::NEG_Y]
200:         .into_iter()
201:         .all(|offset| {
202:             ScenePlanPoint::from_metres(point.metres() + offset * SHOOT_CLEARANCE_METRES)
203:                 .is_some_and(|point| cover.coverage_byte(point) <= MAX_GRASS_COVERAGE)
204:         })
205: }
206: 
207: fn habitat(surface: GroundSurface, e: &SceneEnvironment) -> PlantHabitat {
208:     let ground = if !matches!(
209:         surface.substrate,
210:         GroundSubstrate::Soil | GroundSubstrate::Mud
211:     ) {
212:         PlantGround::Unsuitable
213:     } else {
214:         match surface.cover {
215:             GroundCover::LeafLitter => PlantGround::WoodlandLitter,
216:             GroundCover::TallGrass => PlantGround::Grass,
217:             GroundCover::Bare => PlantGround::Soil,
218:             GroundCover::LooseStone | GroundCover::Reeds => PlantGround::Unsuitable,
219:         }
220:     };
221:     PlantHabitat {
222:         canopy: bps(e.canopy_bps),
223:         cultivation: bps(e.cultivation_bps),
224:         moisture: bps(e.weather.ground_moisture_bps),
225:         snow: bps(e.weather.snow_cover_bps),
226:         day_of_year: e.absolute_minute.day_of_year(),
227:         ground,
228:     }
229: }
