10: #[derive(Clone, Copy, Debug)]
11: pub(super) struct UnderstoryHabitat {
12:     pub(super) canopy: f32,
13:     pub(super) wetland: f32,
14:     pub(super) cultivation: f32,
15:     pub(super) moisture: f32,
