18: /// One shrub site produced by the shared placement walk, consumed by both
19: /// the legacy per-entity renderer and the instanced batches.
20: pub(super) struct ShrubPlacement {
21:     pub(super) species: UnderstorySpecies,
22:     pub(super) point: ScenePlanPoint,
23:     pub(super) hash: Seed,
24: }
