60: /// Deterministic shrub placement walk shared by both renderers, so the
61: /// instanced path reproduces the legacy thickets exactly.
62: pub(super) fn placements(
63:     terrain: &SceneTerrain,
64:     ground: &SceneGround,
65:     base_seed: Seed,
66:     chance: f32,
67:     habitat: UnderstoryHabitat,
68: ) -> Vec<ShrubPlacement> {
69:     let spacing = 3.2;
70:     let count_x = (terrain.width() / spacing).floor() as i32;
71:     let count_z = (terrain.depth() / spacing).floor() as i32;
72:     let half_x = terrain.width() * 0.5;
73:     let half_z = terrain.depth() * 0.5;
74:     let mut sites = Vec::new();
75:     for z in 0..count_z {
76:         for x in 0..count_x {
77:             let hash = streams::SPECIMEN.seed(base_seed, &[x as u32 as u64, z as u32 as u64]);
78:             let community = community_hash(base_seed, x, z);
79:             let local_chance = (chance * community_density_multiplier(community)).min(0.82);
80:             if streams::PRESENCE.rng(hash, &[]).inclusive_unit_f32() >= local_chance {
81:                 continue;
82:             }
83:             let jitter_x = streams::JITTER_X.rng(hash, &[]).inclusive_unit_f32() - 0.5;
84:             let jitter_z = streams::JITTER_Z.rng(hash, &[]).inclusive_unit_f32() - 0.5;
85:             let world_x = -half_x + (x as f32 + 0.5 + jitter_x * 0.72) * spacing;
86:             let world_z = -half_z + (z as f32 + 0.5 + jitter_z * 0.72) * spacing;
87:             let Some(point) = ScenePlanPoint::from_metres(Vec2::new(world_x, world_z)) else {
88:                 continue;
89:             };
90:             let species = select_species(community, habitat);
91:             if ground
92:                 .ground_at(point)
93:                 .is_none_or(|sample| !ground_allows_species(sample, species))
94:             {
95:                 continue;
96:             }
97:             sites.push(ShrubPlacement {
98:                 species,
99:                 point,
100:                 hash,
101:             });
102:         }
103:     }
104:     sites
105: }
