107: fn community_hash(base_seed: Seed, x: i32, z: i32) -> Seed {
108:     // Four-by-four lattice communities produce roughly 13-metre thickets.
109:     // Species identity varies between communities, while each specimen keeps
110:     // its independent placement/rotation hash within the selected thicket.
111:     let community_x = x.div_euclid(4);
112:     let community_z = z.div_euclid(4);
113:     streams::COMMUNITY.seed(
114:         base_seed,
115:         &[community_x as u32 as u64, community_z as u32 as u64],
116:     )
117: }
118: 
119: fn community_density_multiplier(hash: Seed) -> f32 {
120:     // Concentrate the same approximate population into legible thickets.
121:     // Dense cores, loose margins, and mostly open cells keep shrubs from
122:     // reading as evenly-spaced miniature trees across the whole landscape.
123:     let structure = streams::COMMUNITY_STRUCTURE
124:         .rng(hash, &[])
125:         .inclusive_unit_f32();
126:     if structure < 0.25 {
127:         2.5
128:     } else if structure < 0.60 {
129:         1.0
130:     } else {
131:         0.15
132:     }
133: }
