135: fn ground_allows_species(surface: GroundSurface, species: UnderstorySpecies) -> bool {
136:     if surface.substrate == GroundSubstrate::Water
137:         || surface.cover == GroundCover::Reeds
138:         || (surface.cover == GroundCover::Bare && surface.cover_density_bps == 0)
139:     {
140:         return false;
141:     }
