1: //! Exposure follows interior daylight gradually, while preserving the authored night response.
2: use super::{InteriorField, daylight_response};
3: use crate::presentation::{PresentedCelestialLighting, TacticalGameplayCamera};
4: use bevy::{camera::Exposure, prelude::*};
5: 
6: const MAX_INTERIOR_EXPOSURE_STOPS: f32 = 6.0;
7: const DARK_ADAPTATION_SECONDS: f32 = 1.5;
8: const LIGHT_ADAPTATION_SECONDS: f32 = 0.35;
9: const EXPOSURE_SETTLED_TOLERANCE_STOPS: f32 = 0.005;
10: 
11: /// A composed view uses the settled tactical exposure at its own position.
12: #[derive(Component)]
13: pub(crate) struct FixedViewExposure;
14: 
15: #[derive(Resource, Default)]
16: pub(crate) struct InteriorExposure {
17:     compensation: f32,
18:     scene: Option<Entity>,
19:     settled: bool,
20: }
21: 
22: impl InteriorExposure {
23:     pub(crate) fn is_settled(&self) -> bool {
24:         self.scene.is_none() || self.settled
25:     }
26: }
27: 
28: fn approach(current: f32, target: f32, elapsed: f32) -> f32 {
29:     let seconds = if target > current {
30:         DARK_ADAPTATION_SECONDS
31:     } else {
32:         LIGHT_ADAPTATION_SECONDS
33:     };
34:     let next = current + (target - current) * (1.0 - (-elapsed / seconds).exp());
35:     if (next - target).abs() <= EXPOSURE_SETTLED_TOLERANCE_STOPS {
36:         target
37:     } else {
38:         next
39:     }
40: }
41: 
42: pub(super) fn adapt_exposure(
43:     camera: Option<Single<(&GlobalTransform, &mut Exposure), With<TacticalGameplayCamera>>>,
44:     fields: Query<(&InteriorField, &GlobalTransform)>,
45:     celestial: Res<PresentedCelestialLighting>,
46:     // Eye adaptation follows the camera even when the simulation is paused.
47:     time: Res<Time<Real>>,
48:     mut state: ResMut<InteriorExposure>,
49: ) {
50:     let Some(camera) = camera else {
51:         return;
52:     };
53:     let (transform, mut exposure) = camera.into_inner();
54:     let Some(snapshot) = &celestial.snapshot else {
55:         *state = InteriorExposure::default();
56:         exposure.ev100 = Exposure::SUNLIGHT.ev100;
57:         return;
58:     };
59:     if state.scene != Some(snapshot.scene) {
60:         state.compensation = 0.0;
61:         state.scene = Some(snapshot.scene);
62:     }
63:     let target = compensation_at(transform.translation(), &fields, &celestial);
64:     state.compensation = approach(state.compensation, target, time.delta_secs());
65:     state.settled = state.compensation == target;
66:     exposure.ev100 = snapshot.exposure_ev100
67:         - state
68:             .compensation
69:             .min(MAX_INTERIOR_EXPOSURE_STOPS * daylight_response(&celestial).w);
70: }
71: 
72: fn compensation_at(
73:     position: Vec3,
74:     fields: &Query<(&InteriorField, &GlobalTransform)>,
75:     celestial: &PresentedCelestialLighting,
76: ) -> f32 {
77:     let mut target: f32 = 0.0;
78:     for (field, building_transform) in fields {
79:         let point = building_transform
80:             .affine()
81:             .inverse()
82:             .transform_point3(position);
83:         if let Some(sample) = field.sample(point) {
84:             let brightness =
85:                 (sample.positive.truncate() + sample.negative.truncate()).element_sum() / 6.0;
86:             // Match the daylight field's irradiance to the outdoor sunlight
87:             // exposure. Stops are logarithmic; a linear two-stop cap leaves
88:             // physically shaded rooms almost black even when their field is lit.
89:             let reference =
90:                 bevy::light::light_consts::lux::RAW_SUNLIGHT / super::DAYLIGHT_IRRADIANCE;
91:             let stops = (reference / brightness.max(f32::MIN_POSITIVE))
92:                 .log2()
93:                 .clamp(0.0, MAX_INTERIOR_EXPOSURE_STOPS);
94:             target = target.max(stops * daylight_response(celestial).w);
95:         }
96:     }
97:     target
98: }
99: 
100: pub(super) fn expose_fixed_views(
101:     mut cameras: Query<(&GlobalTransform, &mut Exposure), With<FixedViewExposure>>,
102:     fields: Query<(&InteriorField, &GlobalTransform)>,
103:     celestial: Res<PresentedCelestialLighting>,
104: ) {
105:     let Some(snapshot) = &celestial.snapshot else {
106:         return;
107:     };
108:     for (transform, mut exposure) in &mut cameras {
109:         exposure.ev100 =
110:             snapshot.exposure_ev100 - compensation_at(transform.translation(), &fields, &celestial);
111:     }
112: }
