36:     gpu: Res<InteriorLightingGpu>,
37:     sources: Res<Assets<StandardMaterial>>,
38:     mut materials: ResMut<Assets<InteriorMaterial>>,
39:     mut cache: ResMut<InteriorMaterials>,
40:     incoming: Query<(Entity, &MeshMaterial3d<StandardMaterial>)>,
41:     mut events: MessageReader<AssetEvent<StandardMaterial>>,
42: ) {
43:     for event in events.read() {
44:         match event {
