46:                 if let Some(mut material) =
47:                     cache.0.get(id).and_then(|handle| materials.get_mut(handle))
48:                     && let Some(source) = sources.get(*id)
49:                 {
50:                     material.base = source.clone();
51:                     material.base.opaque_render_method = OpaqueRendererMethod::Forward;
52:                 }
53:             }
54:             AssetEvent::Unused { id } | AssetEvent::Removed { id } => {
55:                 cache.0.remove(id);
56:             }
57:             _ => {}
58:         }
59:     }
