61:         let Some(source) = sources.get(&handle.0) else {
62:             continue;
63:         };
64:         let material = cache.0.entry(handle.0.id()).or_insert_with(|| {
65:             let mut base = source.clone();
66:             base.opaque_render_method = OpaqueRendererMethod::Forward;
67:             materials.add(InteriorMaterial {
