14: 
15: impl InteriorField {
16:     fn update_apertures(
17:         &mut self,
18:         apertures: &[(adventuresim_building_generator::OpeningAssemblyId, f32)],
19:     ) -> bool {
20:         let mut changed = false;
21:         for shutter in &mut self.shutters {
22:             let openness = apertures
23:                 .iter()
24:                 .find(|entry| entry.0 == shutter.opening_id)
25:                 .map_or(0.0, |entry| entry.1.clamp(0.0, 1.0));
26:             if (shutter.openness - openness).abs() > APERTURE_CHANGE_TOLERANCE {
27:                 shutter.openness = openness;
28:                 changed = true;
29:             }
30:         }
31:         if changed {
32:             self.samples.clone_from(&self.base_samples);
33:             for shutter in &self.shutters {
34:                 for &(index, light) in &shutter.contributions {
35:                     self.samples[index].positive += light.positive * shutter.openness;
36:                     self.samples[index].negative += light.negative * shutter.openness;
37:                 }
38:             }
39:             for sample in &mut self.samples {
40:                 sample.positive = sample
41:                     .positive
42:                     .truncate()
43:                     .min(Vec3::ONE)
44:                     .extend(sample.positive.w);
45:                 sample.negative = sample.negative.truncate().min(Vec3::ONE).extend(0.0);
46:             }
47:         }
48:         changed
49:     }
50: }
