37: // The presentation facade is compiled into several binaries, while only the
38: // deterministic scene viewer consumes this review-specimen helper.
39: pub(crate) fn oak_review_terminal_specimen(
40:     root: adventuresim_tactical_core::scene_coordinates::ScenePlanPoint,
41:     canopy_bps: u16,
42: ) -> (Mesh, Mesh, Mesh, Mesh, Vec3, Vec3) {
43:     let seed = obstacle_seed(root);
44:     let variant_seed = crate::presentation::obstacles::tree::specimen::oak_variant_seed(
45:         StreamId::new("visual.tree.preview-variant")
46:             .rng(seed, &[])
47:             .index(4),
48:     );
49:     let branches = procedural_tree_skeleton(variant_seed, canopy_competition(canopy_bps));
50:     let competition = canopy_competition(canopy_bps);
51:     let leaves = procedural_oak_leaves(variant_seed, &branches, competition);
52:     let camera_direction = Vec3::new(1.0, 0.0, 1.0).normalize();
53:     let preferred_height = 2.5;
54:     let (shoot_id, shoot) = branches
55:         .iter()
56:         .filter(|branch| branch.depth == 3 && branch.is_limb_tip)
57:         .enumerate()
58:         .max_by(|(_, left), (_, right)| {
59:             let score = |branch: &TreeBranchSegment| {
60:                 branch.end.dot(camera_direction) - (branch.end.y - preferred_height).abs() * 0.35
61:             };
62:             score(left).total_cmp(&score(right))
63:         })
64:         .map(|(_, branch)| (tree::shoot_identity(branch), *branch))
65:         .expect("procedural oak has terminal shoots");
66:     let offset = -shoot.start;
67:     let mut specimen_shoot = shoot;
68:     specimen_shoot.start += offset;
69:     specimen_shoot.end += offset;
70:     let specimen_leaves = leaves
71:         .iter()
72:         .filter(|leaf| leaf.shoot_id == shoot_id)
73:         .copied()
74:         .map(|mut leaf| {
75:             leaf.petiole_start += offset;
76:             leaf.center += offset;
77:             leaf
78:         })
79:         .collect::<Vec<_>>();
80:     // Frame the entire biological unit, not merely the leaf centroid: the
81:     // parent junction and terminal bud are both required to judge shoot
82:     // phyllotaxy. Blade length is included as a conservative bound because
83:     // leaves can tilt substantially out of the shoot's local frame.
84:     let mut minimum = specimen_shoot.start.min(specimen_shoot.end);
85:     let mut maximum = specimen_shoot.start.max(specimen_shoot.end);
86:     for leaf in &specimen_leaves {
87:         let extent = Vec3::splat(leaf.length.max(leaf.width) * 0.6);
88:         minimum = minimum.min(leaf.center - extent);
89:         maximum = maximum.max(leaf.center + extent);
90:     }
91:     let focus = (minimum + maximum) * 0.5;
92:     let shoot_direction = (specimen_shoot.end - specimen_shoot.start).normalize();
93:     let mut review_direction = Vec3::Z;
94:     let mut review_score = f32::NEG_INFINITY;
95:     for elevation in [-0.2_f32, 0.1, 0.35] {
96:         for azimuth_index in 0..24 {
97:             let azimuth = azimuth_index as f32 * core::f32::consts::TAU / 24.0;
98:             let candidate = Vec3::new(
99:                 azimuth.cos() * elevation.cos(),
100:                 elevation.sin(),
101:                 azimuth.sin() * elevation.cos(),
102:             );
103:             let face_area = specimen_leaves
104:                 .iter()
105:                 .map(|leaf| leaf.right.cross(leaf.up).normalize().dot(candidate).abs())
106:                 .sum::<f32>();
107:             let axial_penalty =
108:                 shoot_direction.dot(candidate).abs() * specimen_leaves.len() as f32 * 0.55;
109:             let score = face_area - axial_penalty;
110:             if score > review_score {
111:                 review_score = score;
112:                 review_direction = candidate;
113:             }
114:         }
115:     }
116:     (
117:         procedural_tree_branch_mesh(&[specimen_shoot], 3),
118:         procedural_oak_textured_leaf_mesh(&specimen_leaves),
119:         procedural_oak_leaf_card_mesh(&specimen_leaves),
120:         procedural_oak_bud_mesh(&[specimen_shoot]),
121:         focus,
122:         review_direction,
123:     )
124: }
