16: 
17: impl RockField {
18:     fn new(recipe: RockRecipe) -> Self {
19:         let dimensions = Vec3::from_array(recipe.dimensions_metres());
20:         let phase = StreamId::new("visual.obstacles.rock.phase")
21:             .rng(recipe.seed, &[])
22:             .inclusive_unit_f32()
23:             * core::f32::consts::TAU;
24:         let (sin_phase, cos_phase) = phase.sin_cos();
25:         Self {
26:             archetype: recipe.archetype,
27:             half_extents: dimensions * 0.5,
28:             phase,
29:             sin_phase,
30:             cos_phase,
31:             radius: recipe.collision_radius_metres(),
32:         }
33:     }
34: 
35:     fn sample(&self, point: Vec3) -> f32 {
36:         let normalized = point / self.half_extents;
37:         let phase = self.phase;
38:         let sin_phase = self.sin_phase;
39:         let cos_phase = self.cos_phase;
40:         let oriented = Vec3::new(
41:             normalized.x * cos_phase - normalized.z * sin_phase,
42:             normalized.y,
43:             normalized.x * sin_phase + normalized.z * cos_phase,
44:         );
45:         let broad = (normalized.dot(Vec3::new(2.73, 1.91, 2.27)) + phase).sin();
46:         let cross = (normalized.dot(Vec3::new(-1.37, 3.11, 1.73)) - phase * 0.61).sin();
47:         let radius = 0.84 + broad * 0.055 + cross * 0.035;
48:         let shape = match self.archetype {
49:             RockArchetype::Rounded => {
50:                 let softly_faceted = oriented.abs().dot(Vec3::new(0.48, 0.58, 0.46)) / 0.88;
51:                 normalized.length().lerp(softly_faceted, 0.17)
52:             }
53:             RockArchetype::Angular => {
54:                 let primary = oriented.abs().max_element() * 0.72 + normalized.length() * 0.28;
55:                 let fracture = oriented.dot(Vec3::new(0.61, 0.27, -0.74)).abs() / 0.94;
56:                 primary.max(fracture * 0.92)
