281: fn branch_frame(direction: Vec3) -> (Vec3, Vec3) {
282:     let reference = if direction.y.abs() < 0.9 {
283:         Vec3::Y
284:     } else {
285:         Vec3::X
286:     };
287:     let right = direction.cross(reference).normalize();
288:     (right, right.cross(direction).normalize())
289: }
290: 
291: /// Carries a cylindrical frame along a curved woody axis without the abrupt
292: /// reference-axis changes produced by rebuilding each ring independently.
293: fn transport_branch_frame(
294:     previous_tangent: Vec3,
295:     previous_right: Vec3,
296:     tangent: Vec3,
297: ) -> (Vec3, Vec3) {
298:     let rotated = if previous_tangent.dot(tangent) < -0.999 {
299:         branch_frame(tangent).0
300:     } else {
301:         Quat::from_rotation_arc(previous_tangent, tangent) * previous_right
302:     };
303:     let mut right = (rotated - tangent * rotated.dot(tangent)).normalize_or_zero();
304:     if right.length_squared() < 0.5 {
305:         right = branch_frame(tangent).0;
306:     }
307:     if right.dot(previous_right) < 0.0 {
308:         right = -right;
309:     }
310:     (right, right.cross(tangent).normalize())
311: }
