335: pub(in crate::presentation) fn tree_crown_bounds(
336:     branches: &[TreeBranchSegment],
337:     mut includes: impl FnMut(&TreeBranchSegment) -> bool,
338: ) -> TreeCrownBounds {
339:     let mut minimum = Vec3::splat(f32::INFINITY);
340:     let mut maximum = Vec3::splat(f32::NEG_INFINITY);
341:     for branch in branches.iter().filter(|branch| includes(branch)) {
342:         minimum = minimum.min(branch.start).min(branch.end);
343:         maximum = maximum.max(branch.start).max(branch.end);
344:     }
345:     debug_assert!(minimum.is_finite() && maximum.is_finite());
346:     TreeCrownBounds { minimum, maximum }
347: }
