44: pub(in crate::presentation) fn oak_leaf_card_bounds(leaf: TreeLeaf) -> (Vec3, f32, f32) {
45:     let blade_tip = leaf.center + leaf.up * leaf.length * 0.5;
46:     let bottom = leaf.petiole_start.dot(leaf.up);
47:     let top = blade_tip.dot(leaf.up);
48:     let height = (top - bottom).max(leaf.length) * 1.04;
49:     let center = leaf.center + leaf.up * (((top + bottom) * 0.5) - leaf.center.dot(leaf.up));
50:     (center, leaf.width * 1.08, height)
51: }
