79: fn procedural_woody_leaf_card_mesh_scaled(leaves: &[TreeLeaf], coverage_scale: f32) -> Mesh {
80:     let mut positions = Vec::with_capacity(leaves.len() * 4);
81:     let mut normals = Vec::with_capacity(leaves.len() * 4);
82:     let mut uvs = Vec::with_capacity(leaves.len() * 4);
83:     let mut colors = Vec::with_capacity(leaves.len() * 4);
84:     let mut indices = Vec::with_capacity(leaves.len() * 6);
85:     for leaf in leaves {
86:         let (mut center, width, height) = oak_leaf_card_bounds(*leaf);
87:         // A single plane loses the accepted leaf's projected camber when seen
88:         // obliquely. Enlarge about the fixed petiole (not the card centre) so
89:         // the intermediate LOD preserves crown coverage without swimming at
90:         // its biological attachment.
91:         const CARD_COVERAGE_SCALE: f32 = 1.24;
92:         let scaled_width = width * CARD_COVERAGE_SCALE * coverage_scale;
93:         let scaled_height = height * CARD_COVERAGE_SCALE * coverage_scale;
94:         center += leaf.up * (scaled_height - height) * 0.5;
95:         let right = leaf.right * scaled_width * 0.5;
96:         let up = leaf.up * scaled_height * 0.5;
97:         let normal = leaf.right.cross(leaf.up).normalize();
98:         let base = positions.len() as u32;
99:         positions.extend_from_slice(&[
100:             (center - right - up).to_array(),
101:             (center + right - up).to_array(),
102:             (center + right + up).to_array(),
103:             (center - right + up).to_array(),
104:         ]);
105:         normals.extend_from_slice(&[normal.to_array(); 4]);
106:         // Image-space V grows downward. Keep the generated petiole at the
107:         // biological attachment and the blade tip at the distal end.
108:         uvs.extend_from_slice(&[[0.0, 1.0], [1.0, 1.0], [1.0, 0.0], [0.0, 0.0]]);
109:         let shade = (leaf.shade / 0.82).clamp(0.72, 1.18);
110:         let ambient_visibility = ((leaf.shade - 0.52) / 0.44).clamp(0.32, 1.0);
111:         let shadow_selector = leaf_shadow_selector(*leaf);
112:         colors.extend_from_slice(&[[shade, shade, shadow_selector, ambient_visibility]; 4]);
113:         indices.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
114:     }
115:     let mut mesh = Mesh::new(
116:         PrimitiveTopology::TriangleList,
117:         RenderAssetUsages::RENDER_WORLD,
118:     );
119:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
120:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
121:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
122:     mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, colors);
123:     mesh.insert_indices(Indices::U32(indices));
124:     mesh
125: }
