127: /// The near leaf is a small cambered grid: the geometry retains fold, cupping,
128: /// torsion, and grazing-angle area while the generated opacity texture owns its
129: /// fine lobed silhouette. It transitions directly to the flat card.
130: pub(in crate::presentation) fn procedural_oak_textured_leaf_mesh(leaves: &[TreeLeaf]) -> Mesh {
131:     procedural_woody_cambered_leaf_mesh(leaves)
132: }
133: 
134: pub(in crate::presentation) fn procedural_woody_cambered_leaf_mesh(leaves: &[TreeLeaf]) -> Mesh {
135:     const GRID: u32 = 3;
136:     const VERTICES_PER_LEAF: usize = (GRID * GRID) as usize;
137:     const INDICES_PER_LEAF: usize = ((GRID - 1) * (GRID - 1) * 6) as usize;
138:     let mut positions = Vec::with_capacity(leaves.len() * VERTICES_PER_LEAF);
139:     let mut normals = Vec::with_capacity(leaves.len() * VERTICES_PER_LEAF);
140:     let mut uvs = Vec::with_capacity(leaves.len() * VERTICES_PER_LEAF);
141:     let mut colors = Vec::with_capacity(leaves.len() * VERTICES_PER_LEAF);
142:     let mut indices = Vec::with_capacity(leaves.len() * INDICES_PER_LEAF);
143:     for leaf in leaves {
144:         let (mut center, width, height) = oak_leaf_card_bounds(*leaf);
145:         const COVERAGE_SCALE: f32 = 1.10;
146:         let scaled_width = width * COVERAGE_SCALE;
147:         let scaled_height = height * COVERAGE_SCALE;
148:         center += leaf.up * (scaled_height - height) * 0.5;
149:         let shade = (leaf.shade / 0.82).clamp(0.72, 1.18);
150:         let ambient_visibility = ((leaf.shade - 0.52) / 0.44).clamp(0.32, 1.0);
151:         let shadow_selector = leaf_shadow_selector(*leaf);
152:         let base = positions.len() as u32;
153:         let curl_sign = if leaf.torsion.is_sign_negative() {
154:             -1.0
155:         } else {
156:             1.0
157:         };
158:         for row in 0..GRID {
159:             let v = row as f32 / (GRID - 1) as f32;
160:             // Even an almost-untwisted source leaf needs enough geometric
161:             // change to justify this near representation over the flat card.
162:             // Accumulate a small asymmetric twist toward the tip while the
163:             // source torsion keeps every leaf from curling identically.
164:             let twist_angle = (leaf.torsion * 1.15 + curl_sign * 0.08) * (v - 0.20);
165:             let twist = Quat::from_axis_angle(leaf.up, twist_angle);
166:             let cross_right = (twist * leaf.right).normalize();
167:             let cross_normal = cross_right.cross(leaf.up).normalize();
168:             for column in 0..GRID {
169:                 let u = column as f32 / (GRID - 1) as f32;
170:                 let side = (u - 0.5) * 2.0;
171:                 let lateral = side * scaled_width * 0.5;
172:                 let length_profile = (core::f32::consts::PI * v).sin();
173:                 let midrib_ridge = length_profile * (1.0 - side.abs()) * leaf.width * 0.08;
174:                 let margin_cup = length_profile * side.abs() * leaf.width * 0.11;
175:                 let tip_curl = v * v * v * scaled_height * 0.035 * curl_sign;
176:                 positions.push(
177:                     (center
178:                         + leaf.up * (v - 0.5) * scaled_height
179:                         + cross_right * lateral
180:                         + cross_normal * (midrib_ridge - margin_cup + tip_curl))

181:                         .to_array(),
182:                 );
183:                 normals.push(
184:                     (cross_normal + cross_right * -side * 0.52 - leaf.up * v * curl_sign * 0.08)
185:                         .normalize()
186:                         .to_array(),
187:                 );
188:                 uvs.push([u, 1.0 - v]);
189:                 colors.push([shade, shade, shadow_selector, ambient_visibility]);
190:             }
191:         }
192:         for row in 0..(GRID - 1) {
193:             for column in 0..(GRID - 1) {
194:                 let lower_left = base + row * GRID + column;
195:                 let lower_right = lower_left + 1;
196:                 let upper_left = lower_left + GRID;
197:                 let upper_right = upper_left + 1;
198:                 indices.extend_from_slice(&[
199:                     lower_left,
200:                     lower_right,
201:                     upper_right,
202:                     lower_left,
203:                     upper_right,
204:                     upper_left,
205:                 ]);
206:             }
207:         }
208:     }
209:     let mut mesh = Mesh::new(
210:         PrimitiveTopology::TriangleList,
211:         RenderAssetUsages::RENDER_WORLD,
212:     );
213:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
214:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
215:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
216:     mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, colors);
217:     mesh.insert_indices(Indices::U32(indices));
218:     mesh
219: }
