241: /// Models the compact, scaled winter bud at every current-year shoot tip.
242: /// It is a separate production mesh so its warm color and overlapping scale
243: /// silhouette remain legible instead of disappearing into the bark tube cap.
244: pub(in crate::presentation) fn procedural_oak_bud_mesh(branches: &[TreeBranchSegment]) -> Mesh {
245:     let mut positions = Vec::new();
246:     let mut normals = Vec::new();
247:     let mut uvs = Vec::new();
248:     let mut indices = Vec::new();
249:     const SIDES: u32 = 6;
250:     const BUD_LENGTH: f32 = 0.008;
251:     for branch in branches
252:         .iter()
253:         .filter(|branch| branch.depth == 3 && branch.is_limb_tip)
254:     {
255:         let direction = (branch.end - branch.start).normalize();
256:         let (frame_right, frame_forward) = branch_frame(direction);
257:         let base = positions.len() as u32;
258:         let rings = [(0.0_f32, 0.0018_f32), (0.38, 0.0038), (0.78, 0.0025)];
259:         for (ring_index, (along, radius)) in rings.into_iter().enumerate() {
260:             let center = branch.end + direction * (along * BUD_LENGTH);
261:             let phase_offset = if ring_index & 1 == 0 { 0.0 } else { 0.22 };
262:             for side in 0..SIDES {
263:                 let phase = side as f32 * core::f32::consts::TAU / SIDES as f32 + phase_offset;
264:                 // Alternating ridges suggest overlapping protective scales at
265:                 // the close-review distance without inflating the tiny bud.
266:                 let scale_ridge = if (side + ring_index as u32) & 1 == 0 {
267:                     1.12
268:                 } else {
269:                     0.94
270:                 };
271:                 let radial = frame_right * phase.cos() + frame_forward * phase.sin();
272:                 positions.push((center + radial * radius * scale_ridge).to_array());
273:                 normals.push((radial * 0.86 + direction * 0.18).normalize().to_array());
274:                 uvs.push([side as f32 / SIDES as f32, along]);
275:             }
276:         }
277:         for ring in 0..rings.len() as u32 - 1 {
278:             let from = base + ring * SIDES;
279:             let to = from + SIDES;
280:             for side in 0..SIDES {
281:                 let next = (side + 1) % SIDES;
282:                 indices.extend_from_slice(&[
283:                     from + side,
284:                     to + side,
285:                     to + next,
286:                     from + side,
287:                     to + next,
288:                     from + next,
289:                 ]);
290:             }
291:         }
292:         let tip = positions.len() as u32;
293:         positions.push((branch.end + direction * BUD_LENGTH).to_array());
294:         normals.push(direction.to_array());
295:         uvs.push([0.5, 1.0]);
296:         let last_ring = base + (rings.len() as u32 - 1) * SIDES;
297:         for side in 0..SIDES {
298:             let next = (side + 1) % SIDES;
299:             indices.extend_from_slice(&[tip, last_ring + side, last_ring + next]);
300:         }
301:     }
302:     let mut mesh = Mesh::new(
303:         PrimitiveTopology::TriangleList,
304:         RenderAssetUsages::RENDER_WORLD,
305:     );
306:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
307:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
308:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
309:     mesh.insert_indices(Indices::U32(indices));
310:     mesh
311: }
