1: //! Species-specific leaf positions and terminal-shoot arrangement.
2: use super::*;
3: 
4: pub(in crate::presentation) fn procedural_oak_leaves(
5:     seed: Seed,
6:     branches: &[TreeBranchSegment],
7:     canopy_competition: f32,
8: ) -> Vec<TreeLeaf> {
9:     let mut leaves = Vec::new();
10:     let _ = canopy_competition;
11:     // A compact terminal flush gives each shoot one readable foliage mass.
12:     // The pulsed shoot layout then cuts redundant alpha overlap while
13:     // retaining the oak's irregular shell.
14:     let leaves_per_shoot = 16_u64;
15:     for shoot in branches
16:         .iter()
17:         .filter(|branch| branch.depth == 3 && branch.is_limb_tip)
18:     {
19:         let shoot_id = shoot_identity(shoot);
20:         let direction = (shoot.end - shoot.start).normalize();
21:         let tangent = direction.cross(Vec3::Y).normalize_or_zero();
22:         let tangent = if tangent.length_squared() < 0.25 {
23:             Vec3::X
24:         } else {
25:             tangent
26:         };
27:         let binormal = direction.cross(tangent).normalize();
28:         for leaf_index in 0..leaves_per_shoot {
29:             let leaf_seed = streams::LEAF.seed(seed, &[shoot_id, leaf_index]);
30:             let leaf_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
31:                 purpose.rng(leaf_seed, &[]).inclusive_unit_f32()
32:             };
33:             // Alternate leaves along each current-year shoot, then finish in
34:             // the tighter terminal flush characteristic of pedunculate oak.
35:             let along = if leaf_index < 2 {
36:                 0.12 + leaf_index as f32 * 0.28
37:             } else {
38:                 (0.70
39:                     + (leaf_index - 2) as f32 / (leaves_per_shoot - 3) as f32 * 0.285
40:                     + (leaf_unit_draw(streams::TERMINAL_ATTACHMENT) - 0.5) * 0.008)
41:                     .clamp(0.69, 0.99)
42:             };
43:             let alternate = if leaf_index & 1 == 0 { 1.0 } else { -1.0 };
44:             let spiral =
45:                 leaf_index as f32 * 2.399_963_1 + (leaf_unit_draw(streams::SPIRAL) - 0.5) * 0.65;
46:             let radial = (tangent * spiral.cos() + binormal * spiral.sin()).normalize();
47:             let leaf_up = (radial * (0.46 + leaf_unit_draw(streams::RADIAL_LIFT) * 0.24)
48:                 + direction * (0.42 + leaf_unit_draw(streams::DIRECTION_LIFT) * 0.18)
49:                 + Vec3::Y * (0.08 + leaf_unit_draw(streams::VERTICAL_LIFT) * 0.18))
50:                 .normalize();
51:             let leaf_normal_candidate = direction.cross(radial)
52:                 + radial * (leaf_unit_draw(streams::NORMAL_RADIAL) - 0.5) * 0.7
53:                 + Vec3::Y * (leaf_unit_draw(streams::NORMAL_VERTICAL) - 0.5) * 0.35;
54:             let leaf_normal = if leaf_normal_candidate.length_squared() > 0.001 {
55:                 leaf_normal_candidate.normalize()
56:             } else {
57:                 branch_frame(leaf_up).1
58:             };
59:             let right_candidate = leaf_up.cross(leaf_normal);
60:             let leaf_right = if right_candidate.length_squared() > 0.001 {
61:                 right_candidate.normalize()
62:             } else {
63:                 branch_frame(leaf_up).0 * alternate
64:             };
65:             let petiole_start = shoot.start.lerp(shoot.end, along.min(0.98));
66:             // Pedunculate-oak leaf stalks are only a few millimetres long.
67:             // Keeping this independent of blade size avoids the long-stalked,
68:             // bilateral-comb silhouette of other broadleaf genera.
69:             let petiole_length = 0.003 + leaf_unit_draw(streams::PETIOLE_LENGTH) * 0.004;
70:             let blade_base =
71:                 petiole_start + (radial * 0.82 + leaf_up * 0.18).normalize() * petiole_length;
72:             let leaf_length = 0.1 + leaf_unit_draw(streams::LENGTH) * 0.06;
73:             let leaf_width = 0.065 + leaf_unit_draw(streams::WIDTH) * 0.04;
74:             let shell_exposure = ((shoot.end.xz().length() - 1.25) / 4.75).clamp(0.0, 1.0);
75:             let shade = if leaf_index < 2 {
76:                 0.58 + shell_exposure * 0.22 + leaf_unit_draw(streams::SHADE) * 0.12
77:             } else {
78:                 0.68 + shell_exposure * 0.25 + leaf_unit_draw(streams::SHADE) * 0.14
79:             };
80:             leaves.push(TreeLeaf {
81:                 petiole_start,
82:                 center: blade_base + leaf_up * leaf_length * 0.5,
83:                 right: leaf_right.normalize(),
84:                 up: leaf_up,
85:                 length: leaf_length,
86:                 width: leaf_width,
87:                 primary_group: shoot.primary_group,
88:                 secondary_group: shoot.secondary_group,
89:                 shoot_id,
90:                 leaf_ordinal: leaf_index as u8,
91:                 shade,
92:                 torsion: (leaf_unit_draw(streams::TORSION) - 0.5) * 0.42,
