114: /// Arranges beech leaves in overlapping, approximately two-ranked sprays.
115: /// The broad, mostly horizontal leaf planes build a closed shade-casting crown
116: /// from the existing twig and leaf budget instead of filling it by count.
117: fn procedural_beech_leaves(
118:     seed: Seed,
119:     branches: &[TreeBranchSegment],
120:     parameters: WoodyPlantParameters,
121: ) -> Vec<TreeLeaf> {
122:     let mut leaves = Vec::new();
123:     let leaves_per_shoot = u64::from(parameters.leaves_per_shoot.max(4));
124:     for shoot in branches
125:         .iter()
126:         .filter(|branch| branch.depth == 3 && branch.is_limb_tip)
127:     {
128:         let shoot_id = shoot_identity(shoot);
129:         let direction = (shoot.end - shoot.start).normalize();
130:         let horizontal = Vec3::new(direction.x, 0.0, direction.z).normalize_or_zero();
131:         let spray_forward = if horizontal.length_squared() > 0.25 {
132:             horizontal
133:         } else {
134:             branch_frame(direction).0
135:         };
136:         let spray_side = Vec3::Y.cross(spray_forward).normalize();
137:         for leaf_index in 0..leaves_per_shoot {
138:             let leaf_seed = streams::LEAF.seed(seed, &[shoot_id, leaf_index]);
139:             let leaf_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
140:                 purpose.rng(leaf_seed, &[]).inclusive_unit_f32()
141:             };
142:             let along = (0.1
143:                 + leaf_index as f32 / (leaves_per_shoot - 1) as f32 * 0.84
144:                 + (leaf_unit_draw(streams::ATTACHMENT) - 0.5) * 0.018)
145:                 .clamp(0.06, 0.97);
146:             let side = if leaf_index & 1 == 0 { 1.0 } else { -1.0 };
147:             let blade_outward = (spray_forward * (0.56 + leaf_unit_draw(streams::SPIRAL) * 0.18)
148:                 + spray_side * side * (0.7 + leaf_unit_draw(streams::RADIAL_LIFT) * 0.16)
149:                 + Vec3::Y * (0.06 + leaf_unit_draw(streams::PETIOLE_LENGTH) * 0.1))
150:                 .normalize();

151:             // Keep the lamina close to horizontal while allowing a small,
152:             // deterministic ripple through each spray.
153:             let horizontal_weight = if leaf_index & 3 < 2 { 1.0 } else { 0.62 };
154:             let posture_normal = (Vec3::Y * horizontal_weight
155:                 + spray_forward * (1.0 - horizontal_weight) * 1.35
156:                 + spray_side * (leaf_unit_draw(streams::LENGTH) - 0.5) * 0.28
157:                 + spray_forward * (leaf_unit_draw(streams::WIDTH) - 0.5) * 0.18)
158:                 .normalize();
159:             let right = blade_outward.cross(posture_normal).normalize_or_zero();
160:             let right = if right.length_squared() > 0.25 {
161:                 right
162:             } else {
163:                 branch_frame(blade_outward).0
164:             };
165:             let petiole_start = shoot.start.lerp(shoot.end, along);
166:             let petiole_length = parameters.petiole_length_metres[0]
167:                 + leaf_unit_draw(streams::SHADE)
168:                     * (parameters.petiole_length_metres[1] - parameters.petiole_length_metres[0]);
169:             // At mature-tree scale this card represents a small overlapping
170:             // beech spray, not a single isolated lamina. Keeping the card
171:             // count bounded while expanding the spray footprint produces the
172:             // species' closed, shade-casting crown without multiplying draw
173:             // and streaming work across a dense stand.
174:             let length = (parameters.leaf_length_metres[0]
175:                 + leaf_unit_draw(streams::DIRECTION_LIFT)
176:                     * (parameters.leaf_length_metres[1] - parameters.leaf_length_metres[0]))
177:                 * 3.0;
178:             let width = length
179:                 * (parameters.leaf_width_ratio[0]
180:                     + leaf_unit_draw(streams::VERTICAL_LIFT)
181:                         * (parameters.leaf_width_ratio[1] - parameters.leaf_width_ratio[0]));
182:             let blade_base = petiole_start + blade_outward * petiole_length;
183:             leaves.push(TreeLeaf {
184:                 petiole_start,
185:                 center: blade_base + blade_outward * length * 0.5,
186:                 right,
187:                 up: blade_outward,
188:                 length,
189:                 width,
190:                 primary_group: shoot.primary_group,
191:                 secondary_group: shoot.secondary_group,
192:                 shoot_id,
193:                 leaf_ordinal: leaf_index as u8,
194:                 shade: 0.7 + leaf_unit_draw(streams::NORMAL_RADIAL) * 0.2,
195:                 torsion: (leaf_unit_draw(streams::NORMAL_VERTICAL) - 0.5) * 0.18,
196:             });
197:         }
198:     }
199:     leaves
200: }
