202: fn procedural_multistem_shrub_leaves(
203:     seed: Seed,
204:     branches: &[TreeBranchSegment],
205:     parameters: WoodyPlantParameters,
206: ) -> Vec<TreeLeaf> {
207:     let mut leaves = Vec::new();
208:     let leaves_per_shoot = u64::from(parameters.leaves_per_shoot.max(4));
209:     for shoot in branches
210:         .iter()
211:         .filter(|branch| branch.depth == 3 && branch.is_limb_tip)
212:     {
213:         let shoot_id = shoot_identity(shoot);
214:         let direction = (shoot.end - shoot.start).normalize();
215:         let (frame_right, frame_up) = branch_frame(direction);
216:         for leaf_index in 0..leaves_per_shoot {
217:             let leaf_seed = streams::LEAF.seed(seed, &[shoot_id, leaf_index]);
218:             let leaf_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
219:                 purpose.rng(leaf_seed, &[]).inclusive_unit_f32()
220:             };
221:             // Common hazel leaves are alternate and loosely distichous. The
222:             // golden-angle perturbation prevents a flat bilateral comb while
223:             // retaining opposite-side succession along each current shoot.
224:             let along = 0.08
225:                 + leaf_index as f32 / (leaves_per_shoot - 1) as f32 * 0.84
226:                 + (leaf_unit_draw(streams::ATTACHMENT) - 0.5) * 0.025;
227:             let side = if leaf_index & 1 == 0 { 1.0 } else { -1.0 };
228:             let phase =
229:                 side * (0.82 + leaf_unit_draw(streams::SPIRAL) * 0.28) + leaf_index as f32 * 0.32;
230:             let radial = (frame_right * phase.cos() + frame_up * phase.sin()).normalize();
231:             let leaf_up = (radial * 0.72 + direction * 0.48 + Vec3::Y * 0.16).normalize();
232:             let azimuth_normal = direction.cross(radial).normalize_or_zero();
233:             let azimuth_normal = if azimuth_normal.length_squared() > 0.25 {
234:                 azimuth_normal
235:             } else {
236:                 frame_up
237:             };
238:             // Hazel blades are generally held obliquely upward rather than as
239:             // vertical fins around an upright shoot. Bias the generated plane
240:             // normal toward the sky while retaining azimuthal variation, then
241:             // project it perpendicular to the blade's midrib. This lets the
242:             // ordinary PBR response to the sun light the shrub naturally.
243:             let posture_normal = (Vec3::Y * 0.82 + azimuth_normal * 0.38).normalize();
244:             let right = leaf_up.cross(posture_normal).normalize_or_zero();
245:             let right = if right.length_squared() > 0.25 {
246:                 right
247:             } else {
248:                 leaf_up.cross(frame_right).normalize()
249:             };
250:             let petiole_start = shoot.start.lerp(shoot.end, along.clamp(0.04, 0.96));
251:             let petiole_length = parameters.petiole_length_metres[0]
252:                 + leaf_unit_draw(streams::RADIAL_LIFT)
253:                     * (parameters.petiole_length_metres[1] - parameters.petiole_length_metres[0]);
254:             let length = parameters.leaf_length_metres[0]
255:                 + leaf_unit_draw(streams::PETIOLE_LENGTH)
256:                     * (parameters.leaf_length_metres[1] - parameters.leaf_length_metres[0]);
257:             let width = length
258:                 * (parameters.leaf_width_ratio[0]
259:                     + leaf_unit_draw(streams::LENGTH)
260:                         * (parameters.leaf_width_ratio[1] - parameters.leaf_width_ratio[0]));
261:             let blade_base = petiole_start + radial * petiole_length;
262:             leaves.push(TreeLeaf {
263:                 petiole_start,
264:                 center: blade_base + leaf_up * length * 0.5,
265:                 right,
266:                 up: leaf_up,
267:                 length,
268:                 width,
269:                 primary_group: shoot.primary_group,
270:                 secondary_group: shoot.secondary_group,
271:                 shoot_id,
272:                 leaf_ordinal: leaf_index as u8,
273:                 shade: 0.68 + leaf_unit_draw(streams::WIDTH) * 0.24,
274:                 torsion: (leaf_unit_draw(streams::SHADE) - 0.5) * 0.28,
275:             });
276:         }
277:     }
278:     leaves
279: }

