3: 
4: /// Selects one stable ordinal lane from every source shoot. Sorting the
5: /// retained leaves makes the resulting mesh byte-for-byte deterministic even
6: /// if the source generator changes its iteration order.
7: pub(super) fn sparse_woody_far_card_leaves(leaves: &[TreeLeaf]) -> Vec<TreeLeaf> {
8:     let mut retained = leaves
9:         .iter()
10:         .filter(|leaf| sparse_woody_far_card_retained(**leaf))
11:         .copied()
12:         .collect::<Vec<_>>();
13:     retained.sort_unstable_by_key(|leaf| {
14:         (
15:             leaf.primary_group,
16:             leaf.secondary_group,
17:             leaf.shoot_id,
18:             leaf.leaf_ordinal,
19:         )
20:     });
21:     retained
22: }
23: 
24: pub(super) fn sparse_woody_far_card_retained(leaf: TreeLeaf) -> bool {
25:     let shoot_key = leaf.shoot_id;
26:     let retained_ordinal_lane = streams::RETAINED_LANE.rng(shoot_key.into(), &[]).index(4) as u8;
27:     leaf.leaf_ordinal & 3 == retained_ordinal_lane
28: }
29: 
30: /// Returns the deterministic 75% subset used exclusively by streamed
31: /// playable-tree flat cards. Each shoot omits one of its four ordinal lanes;
32: /// the omitted lane is salted by stable source identity, keeping the crown
33: /// distributed when source vectors are reordered. Cambered leaves and baked
34: /// aggregate canopy cards deliberately retain the full source set.
35: pub(in crate::presentation) fn detailed_flat_card_group_leaves(
36:     leaves: &[TreeLeaf],
37:     primary_group: u8,
38: ) -> Vec<TreeLeaf> {
39:     let mut retained = leaves
40:         .iter()
41:         .filter(|leaf| {
42:             leaf.primary_group == primary_group && detailed_flat_card_leaf_retained(**leaf)
43:         })
44:         .copied()
45:         .collect::<Vec<_>>();
46:     retained.sort_unstable_by_key(|leaf| {
47:         (
48:             leaf.primary_group,
49:             leaf.secondary_group,
50:             leaf.shoot_id,
51:             leaf.leaf_ordinal,
52:         )
53:     });
54:     retained
55: }
56: 
57: pub(super) fn detailed_flat_card_leaf_retained(leaf: TreeLeaf) -> bool {
58:     let shoot_key = leaf.shoot_id;
59:     let omitted_ordinal_lane = streams::OMITTED_LANE.rng(shoot_key.into(), &[]).index(4) as u8;
60:     leaf.leaf_ordinal & 3 != omitted_ordinal_lane
61: }
