65: fn oak_primary_scaffold_phase(crown_phase: f32, primary_index: u64, primary_seed: Seed) -> f32 {
66:     crown_phase
67:         + primary_index as f32 * 2.399_963_1
68:         + (streams::PRIMARY_PHASE
69:             .rng(primary_seed, &[])
70:             .inclusive_unit_f32()
71:             - 0.5)
72:             * 0.42
73: }
