75: fn signed_angular_delta(from: f32, to: f32) -> f32 {
76:     let mut delta = (to - from) % core::f32::consts::TAU;
77:     if delta > core::f32::consts::PI {
78:         delta -= core::f32::consts::TAU;
79:     } else if delta < -core::f32::consts::PI {
80:         delta += core::f32::consts::TAU;
81:     }
82:     delta
83: }
