102: pub(in crate::presentation) fn procedural_oak_skeleton_with_gnarling(
103:     seed: Seed,
104:     canopy_competition: f32,
105:     gnarling: OakGnarlingParameters,
106: ) -> Vec<TreeBranchSegment> {
107:     let seed_unit_draw =
108:         |purpose: fabelgeist_determinism::StreamId| purpose.rng(seed, &[]).inclusive_unit_f32();
109:     let mut branches = Vec::new();
110:     let canopy_competition = canopy_competition.clamp(0.0, 1.0);
111:     let crown_phase = seed_unit_draw(streams::OAK_CROWN_PHASE) * core::f32::consts::TAU;
112:     let lean_phase =
113:         gnarling.stress_azimuth_radians + (seed_unit_draw(streams::TRUNK_BIAS) - 0.5) * 0.34;
114:     let trunk_points = oak_trunk_points(canopy_competition, crown_phase, lean_phase, gnarling);
115:     append_branch_curve(
116:         &mut branches,
117:         &trunk_points,
118:         0.72_f32.lerp(0.56, canopy_competition)
119:             * (1.0 + gnarling.taper_irregularity.clamp(0.0, 1.0) * 0.16),
120:         0.045_f32.lerp(0.035, canopy_competition),
121:         0,
122:         u8::MAX,
123:         u16::MAX,
124:     );
125: 
126:     // Unequal surface roots visually carry the weight of the low, spreading
127:     // scaffold limbs without changing the authoritative collider. Their plan
128:     // is presentation-only: a bounded irregular partition avoids a radial
129:     // star, while the broadest buttresses share the major scaffold azimuths.
130:     let root_specs = procedural_oak_root_specs_with_gnarling(seed, crown_phase, gnarling);
131:     debug_assert!(oak_root_segment_count(&root_specs) <= OAK_ROOT_MAX_SEGMENTS);
132:     for root in root_specs {
133:         // Roots begin below grade, expose a shoulder according to the site's
134:         // gnarling recipe, and taper back into the soil.
135:         let points = oak_root_points(trunk_points[0] - Vec3::Y * 0.07, root, gnarling);
136:         append_branch_curve(
137:             &mut branches,
138:             &points,
139:             root.base_radius,
140:             root.tip_radius,
141:             0,
142:             u8::MAX,
143:             u16::MAX,
144:         );
145:         if let Some(fork) = root.fork {
146:             let fork_points = oak_root_fork_points(&points, root, fork);
147:             append_branch_curve(
148:                 &mut branches,
149:                 &fork_points,
150:                 root.base_radius * 0.34,
151:                 root.tip_radius * 0.72,
152:                 0,
153:                 u8::MAX,
154:                 u16::MAX,
155:             );
156:         }
157:     }
158: 
159:     append_oak_knots(&mut branches, seed, &trunk_points, gnarling);
160: 
161:     // Seven crown sectors fill a low, wide, irregular dome. Four are heavy,
162:     // load-bearing scaffold axes; the other three are subordinate crown-fill
163:     // limbs. This avoids both a radial whorl and an implausibly symmetrical
164:     // crown while retaining an even distribution of terminal foliage.
165:     let mut dominant_scaffolds: Vec<(Vec<Vec3>, f32, f32)> = Vec::with_capacity(4);
166:     for primary_index in 0..u64::from(TREE_PRIMARY_GROUP_COUNT) {
167:         let dominant = primary_index < 4;
168:         let rank = if dominant {
169:             primary_index as f32
170:         } else {
171:             (primary_index - 4) as f32
172:         };
173:         let primary_seed = streams::OAK_PRIMARY.seed(seed, &[primary_index]);
174:         let primary_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
175:             purpose.rng(primary_seed, &[]).inclusive_unit_f32()
176:         };
177:         let phase = oak_primary_scaffold_phase(crown_phase, primary_index, primary_seed);
178:         let outward = Vec3::new(phase.cos(), 0.0, phase.sin());
179:         let tangent = Vec3::new(-phase.sin(), 0.0, phase.cos());
180:         let (isolated_attach, competitive_attach) = if dominant {
181:             (
182:                 [0.38, 0.56, 0.72, 0.86][primary_index as usize],
183:                 [0.58, 0.72, 0.84, 0.93][primary_index as usize],
184:             )
185:         } else {
186:             (0.35 + rank * 0.17, 0.48 + rank * 0.12)
187:         };
188:         let attach = isolated_attach.lerp(competitive_attach.min(0.975), canopy_competition);
189:         let start = if dominant {
190:             sample_polyline(&trunk_points, attach)
191:         } else {
192:             sample_polyline(&dominant_scaffolds[rank as usize].0, attach)
193:         };
194:         // In the open, every principal axis contributes to the same broad,
195:         // ascending dome. Keeping separate vertical "leader" axes produces
196:         // a pollarded V silhouette instead of the decurrent habit of a mature
197:         // oak. Competition progressively shortens these lateral reaches and
198:         // raises their attachment points, leaving a tall clear bole.
199:         let (isolated_reach, isolated_lift, isolated_sag) = if dominant {
200:             // Lower axes carry the widest crown sectors while progressively

201:             // shorter upper axes close a deep, layered dome. Equal reaches
202:             // make the crown read as stacked shelves around a horizontal
203:             // beam, which is especially unconvincing in open-grown oaks.
204:             let reach_profile = [5.55, 5.15, 4.65, 3.75][primary_index as usize];
205:             let lift_profile = [0.72, 1.0, 1.2, 1.55][primary_index as usize];
206:             let sag_profile = [0.62, 0.52, 0.4, 0.28][primary_index as usize];
207:             (
208:                 reach_profile + primary_unit_draw(streams::PRIMARY_REACH) * 0.28,
209:                 lift_profile + primary_unit_draw(streams::PRIMARY_LIFT) * 0.24,
210:                 sag_profile,
211:             )
212:         } else {
213:             (
214:                 2.9 - rank * 0.14 + primary_unit_draw(streams::PRIMARY_REACH) * 0.28,
215:                 0.78 + rank * 0.18 + primary_unit_draw(streams::PRIMARY_LIFT) * 0.16,
216:                 0.36,
217:             )
218:         };
219:         let (competitive_reach, competitive_lift) = if dominant {
220:             (2.75 - rank * 0.14, 2.35 + rank * 0.15)
221:         } else {
222:             // High attachment already lifts these crown-fill axes. Keeping
223:             // their extension below the dominant scaffold tips rounds the
224:             // competitive crown instead of growing a false central spear.
225:             (2.1 - rank * 0.1, 2.15 + rank * 0.08)
226:         };
227:         let asymmetry =
228:             1.0 + gnarling.crown_asymmetry.clamp(0.0, 1.0) * 0.38 * (phase - lean_phase).cos();
229:         let reach = isolated_reach.lerp(competitive_reach, canopy_competition) * asymmetry;
230:         let lift = isolated_lift.lerp(competitive_lift, canopy_competition);
231:         let sag = isolated_sag.lerp(0.32, canopy_competition);
232:         let lateral = (primary_unit_draw(streams::PRIMARY_LATERAL) - 0.5)
233:             * (1.25 + gnarling.scaffold_sweep.clamp(0.0, 1.0) * 2.8);
234:         let torsion_phase = primary_unit_draw(streams::PRIMARY_TORSION) * core::f32::consts::TAU;
235:         let primary_points = (0..=10)
236:             .map(|point_index| {
237:                 let t = point_index as f32 / 10.0;
238:                 let eased = t * (0.72 + 0.28 * t);
239:                 start
240:                     + outward * reach * eased
241:                     + tangent * lateral * (core::f32::consts::PI * t).sin()
242:                     + tangent
243:                         * (0.22 + gnarling.scaffold_contortion.clamp(0.0, 1.0) * 0.62)
244:                         * (core::f32::consts::TAU * t + torsion_phase).sin()
245:                         * (core::f32::consts::PI * t).sin()
246:                     + Vec3::Y
247:                         * (-sag * (core::f32::consts::PI * t).sin()
248:                             - gnarling.scaffold_droop.clamp(0.0, 1.0)
249:                                 * reach
250:                                 * 0.16
251:                                 * (core::f32::consts::PI * t).sin().powi(2)
252:                             + lift * t.powf(1.85)
253:                             + 0.16
254:                                 * (core::f32::consts::TAU * t + torsion_phase * 0.7).sin()
255:                                 * (core::f32::consts::PI * t).sin())
256:             })
257:             .collect::<Vec<_>>();
258:         let (authored_primary_start_radius, primary_end_radius) = if dominant {
259:             (
260:                 0.36 - rank * 0.043 + primary_unit_draw(streams::PRIMARY_RADIUS) * 0.035,
261:                 0.028,
262:             )
263:         } else {
264:             (
265:                 0.17 + primary_unit_draw(streams::PRIMARY_RADIUS) * 0.035,
266:                 0.02,
267:             )
268:         };
269:         let parent_radius = if dominant {
270:             curve_radius_at(
271:                 0.72_f32.lerp(0.56, canopy_competition),
272:                 0.045_f32.lerp(0.035, canopy_competition),
273:                 attach,
274:             )
275:         } else {
276:             let parent = &dominant_scaffolds[rank as usize];
277:             curve_radius_at(parent.1, parent.2, attach)
278:         };
279:         let primary_start_radius = child_base_radius(authored_primary_start_radius, parent_radius);
280:         append_branch_curve(
281:             &mut branches,
282:             &primary_points,
283:             primary_start_radius,
284:             primary_end_radius,
285:             1,
286:             primary_index as u8,
287:             u16::MAX,
288:         );
289:         if dominant {
290:             dominant_scaffolds.push((
291:                 primary_points.clone(),
292:                 primary_start_radius,
293:                 primary_end_radius,
294:             ));
295:         }
296: 
297:         // Organize the crown into readable scaffold masses rather than a
298:         // uniformly filled wire cage. Fewer secondary axes leave deliberate
299:         // windows and remove wood hidden behind several alpha-tested leaves.
300:         let secondary_count = if dominant { 18_u64 } else { 11_u64 };
301:         for secondary_index in 0..secondary_count {
302:             let secondary_seed = streams::OAK_SECONDARY.seed(primary_seed, &[secondary_index]);
303:             let secondary_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
304:                 purpose.rng(secondary_seed, &[]).inclusive_unit_f32()
305:             };
306:             // The last axis inherits the scaffold direction and carries
307:             // foliage over its end. The remaining axes alternate laterally,
308:             // avoiding the bare antler tips produced by stopping all child
309:             // branches well before their parent.
310:             let is_terminal_axis = secondary_index + 1 == secondary_count;
311:             let attach = if is_terminal_axis {
312:                 0.96
313:             } else {
314:                 let normalized = secondary_index as f32 / (secondary_count - 2) as f32;
315:                 0.14_f32.lerp(0.24, canopy_competition) + normalized.powf(0.7) * 0.72
316:             };
317:             let secondary_start = sample_polyline(&primary_points, attach);
318:             let inherited = polyline_tangent(&primary_points, attach);
319:             let (frame_right, frame_up) = branch_frame(inherited);
320:             let branch_phase = secondary_index as f32 * 2.399_963_1
321:                 + secondary_unit_draw(streams::SECONDARY_PHASE) * 0.55;
322:             let radial = frame_right * branch_phase.cos() + frame_up * branch_phase.sin();
323:             let inherited_weight = if is_terminal_axis { 0.78 } else { 0.38 };
324:             let lateral_weight = if is_terminal_axis { 0.2 } else { 0.68 };
325:             let mut secondary_direction = (inherited
326:                 * (inherited_weight + secondary_unit_draw(streams::SECONDARY_INHERITANCE) * 0.16)
327:                 + radial * (lateral_weight + secondary_unit_draw(streams::SECONDARY_RADIAL) * 0.2)
328:                 + outward * 0.2
329:                 + Vec3::Y * (0.08 + secondary_unit_draw(streams::SECONDARY_LIFT) * 0.26))
330:                 .normalize();
331:             let maximum_rise = 0.5_f32.lerp(0.68, canopy_competition);
332:             if secondary_direction.y > maximum_rise {
333:                 let horizontal = secondary_direction.xz().normalize_or_zero();
334:                 secondary_direction =
335:                     Vec3::new(horizontal.x, maximum_rise, horizontal.y).normalize();
336:             }
337:             let secondary_length = (1.75 + secondary_unit_draw(streams::SECONDARY_LENGTH) * 0.95)
338:                 * 1.0_f32.lerp(0.76, canopy_competition);
339:             let secondary_bend =
340:                 radial * (secondary_unit_draw(streams::SECONDARY_BEND) - 0.5) * 0.55;
341:             let secondary_points = (0..=3)
342:                 .map(|point_index| {
343:                     let t = point_index as f32 / 3.0;
344:                     secondary_start
345:                         + secondary_direction * secondary_length * t
346:                         + secondary_bend * (core::f32::consts::PI * t).sin()
347:                         + Vec3::Y * (0.2 * t.powf(1.7))
348:                 })
349:                 .collect::<Vec<_>>();
350:             let secondary_group =
351:                 (primary_index * u64::from(TREE_SECONDARY_GROUP_STRIDE) + secondary_index) as u16;
352:             let (authored_secondary_start_radius, secondary_end_radius) = if dominant {
353:                 (0.072, 0.013)
354:             } else {
355:                 (0.05, 0.01)
356:             };
357:             let secondary_start_radius = child_base_radius(
358:                 authored_secondary_start_radius,
359:                 curve_radius_at(primary_start_radius, primary_end_radius, attach),
360:             );
361:             append_branch_curve(
362:                 &mut branches,
363:                 &secondary_points,
364:                 secondary_start_radius,
365:                 secondary_end_radius,
366:                 2,
367:                 primary_index as u8,
368:                 secondary_group,
369:             );
370: 
371:             // Short shoots are distributed around the secondary limb rather
372:             // than combed vertically.  Their terminal leaf rosettes overlap
373:             // into porous masses while leaving glimpses of the scaffold.
374:             // Open-grown sectors cover much more crown surface. Allocate
375:             // current-year shoots in proportion to that larger envelope;
376:             // competition progressively self-prunes the surplus shoots.
377:             let shoot_count = if dominant {
378:                 34.0_f32.lerp(24.0, canopy_competition).round() as u64
379:             } else {
380:                 22.0_f32.lerp(15.0, canopy_competition).round() as u64
381:             };
382:             for shoot_index in 0..shoot_count {
383:                 let shoot_seed = streams::OAK_SHOOT.seed(secondary_seed, &[shoot_index]);
384:                 let shoot_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
385:                     purpose.rng(shoot_seed, &[]).inclusive_unit_f32()
386:                 };
387:                 let first_attach = 0.08_f32.lerp(0.22, canopy_competition);
388:                 let attach =
389:                     oak_clustered_shoot_attach(shoot_index, shoot_count, first_attach, shoot_seed);
390:                 let shoot_start = sample_polyline(&secondary_points, attach);
391:                 let inherited = polyline_tangent(&secondary_points, attach);
392:                 let (frame_right, frame_up) = branch_frame(inherited);
393:                 let spiral = shoot_index as f32 * 2.399_963_1
394:                     + shoot_unit_draw(streams::SHOOT_PHASE) * core::f32::consts::TAU;
395:                 let radial = frame_right * spiral.cos() + frame_up * spiral.sin();
396:                 let open_vertical = -0.2 + shoot_unit_draw(streams::SHOOT_LIFT) * 0.48;
397:                 let competitive_vertical = 0.04 + shoot_unit_draw(streams::SHOOT_LIFT) * 0.24;
398:                 let vertical = open_vertical.lerp(competitive_vertical, canopy_competition);
399:                 let shoot_direction = (inherited * 0.46
400:                     + radial * (0.58 + shoot_unit_draw(streams::SHOOT_RADIAL) * 0.24)

401:                     + Vec3::Y * vertical)
402:                     .normalize();
403:                 let shoot_length = 0.24 + shoot_unit_draw(streams::SHOOT_LENGTH) * 0.28;
404:                 let shoot_mid =
405:                     shoot_start + shoot_direction * shoot_length * 0.52 + radial * 0.035;
406:                 let shoot_end = shoot_start
407:                     + shoot_direction * shoot_length
408:                     + radial * (shoot_unit_draw(streams::SHOOT_BEND) - 0.5) * 0.11;
409:                 append_branch_curve(
410:                     &mut branches,
411:                     &[shoot_start, shoot_mid, shoot_end],
412:                     child_base_radius(
413:                         0.012,
414:                         curve_radius_at(secondary_start_radius, secondary_end_radius, attach),
415:                     ),
416:                     0.0032,
417:                     3,
418:                     primary_index as u8,
419:                     secondary_group,
420:                 );
421:             }
422:         }
423:     }
424:     branches
425: }
