427: /// Distributes current-year shoots in five separated pulses along a secondary
428: /// axis. Stable pulses retain terminal coverage while leaving recognizable sky
429: /// and interior windows between foliage masses.
430: fn oak_clustered_shoot_attach(
431:     shoot_index: u64,
432:     shoot_count: u64,
433:     first_attach: f32,
434:     shoot_seed: Seed,
435: ) -> f32 {
436:     const CLUSTER_COUNT: u64 = 5;
437:     let cluster = (shoot_index * CLUSTER_COUNT / shoot_count.max(1)).min(CLUSTER_COUNT - 1);
438:     let cluster_start = cluster * shoot_count / CLUSTER_COUNT;
439:     let cluster_end = ((cluster + 1) * shoot_count / CLUSTER_COUNT).max(cluster_start + 1);
440:     let within = (shoot_index - cluster_start) as f32 / (cluster_end - cluster_start) as f32;
441:     let center = first_attach.lerp(0.965, cluster as f32 / (CLUSTER_COUNT - 1) as f32);
442:     let spread = 0.052_f32.lerp(0.082, cluster as f32 / (CLUSTER_COUNT - 1) as f32);
443:     (center
444:         + (within - 0.5) * spread
445:         + (streams::SHOOT_ATTACHMENT
446:             .rng(shoot_seed, &[])
447:             .inclusive_unit_f32()
448:             - 0.5)
449:             * 0.018)
450:         .clamp(0.04, 0.992)
451: }
