453: fn procedural_oak_skeleton(seed: Seed, canopy_competition: f32) -> Vec<TreeBranchSegment> {
454:     procedural_oak_skeleton_with_gnarling(seed, canopy_competition, NATURAL_OAK_GNARLING)
