457: fn append_oak_knots(
458:     branches: &mut Vec<TreeBranchSegment>,
459:     seed: Seed,
460:     trunk: &[Vec3],
461:     gnarling: OakGnarlingParameters,
462: ) {
463:     let count = (gnarling.knot_frequency.clamp(0.0, 1.0) * 6.0).round() as u64;
464:     for index in 0..count {
465:         let knot_seed = streams::KNOT.seed(seed, &[index]);
466:         let knot_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
467:             purpose.rng(knot_seed, &[]).inclusive_unit_f32()
468:         };
469:         let attach = 0.1 + knot_unit_draw(streams::KNOT_ATTACHMENT) * 0.68;
470:         let center = sample_polyline(trunk, attach);
471:         let axis = polyline_tangent(trunk, attach);
472:         let (right, forward) = branch_frame(axis);
473:         let phase = knot_unit_draw(streams::KNOT_PHASE) * core::f32::consts::TAU;
474:         let radial = right * phase.cos() + forward * phase.sin();
475:         let scale = 0.055
476:             + gnarling.knot_scale.clamp(0.0, 1.0) * 0.18
477:             + gnarling.burl_scale.clamp(0.0, 1.0) * knot_unit_draw(streams::KNOT_SCALE) * 0.24;
478:         append_branch_curve(
479:             branches,
480:             &[
481:                 center,
482:                 center + radial * scale * 0.75,
483:                 center + radial * scale + axis * scale * 0.18,
484:             ],
485:             scale,
486:             scale * 0.38,
487:             0,
488:             u8::MAX,
489:             u16::MAX,
490:         );
491:     }
492: }
