494: fn procedural_beech_skeleton(
495:     seed: Seed,
496:     canopy_competition: f32,
497:     parameters: WoodyPlantParameters,
498: ) -> Vec<TreeBranchSegment> {
499:     let mut branches = Vec::new();
500:     let competition = canopy_competition.clamp(0.0, 1.0);
501:     let height = parameters.height_metres * (1.0 + competition * 0.13);
502:     let crown_radius = parameters.crown_radius_metres * (1.0 - competition * 0.18);
503:     let clear_bole_fraction = 0.38 + competition * 0.14;
504:     let crown_phase = streams::BEECH_CROWN_PHASE
505:         .rng(seed, &[])
506:         .inclusive_unit_f32()
507:         * core::f32::consts::TAU;
508:     let trunk_base = Vec3::new(0.0, -TREE_TRUNK_HEIGHT_METRES * 0.5, 0.0);
509:     let trunk_points = (0..=10)
510:         .map(|index| {
511:             let t = index as f32 / 10.0;
512:             let sweep = (core::f32::consts::PI * t).sin() * (0.045 + 0.025 * competition);
513:             Vec3::new(
514:                 crown_phase.cos() * sweep,
515:                 trunk_base.y + height * t,
516:                 crown_phase.sin() * sweep,
517:             )
518:         })
519:         .collect::<Vec<_>>();
520:     append_branch_curve(
521:         &mut branches,
522:         &trunk_points,
523:         0.5,
524:         0.055,
525:         0,
526:         u8::MAX,
527:         u16::MAX,
528:     );
529: 
530:     append_beech_roots(&mut branches, seed, crown_phase, trunk_base);
531: 
532:     for primary_index in 0..20_u64 {
533:         let primary_seed = streams::BEECH_PRIMARY.seed(seed, &[primary_index]);
534:         let primary_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
535:             purpose.rng(primary_seed, &[]).inclusive_unit_f32()
536:         };
537:         let layer = primary_index as f32 / 19.0;
538:         let height_fraction = (clear_bole_fraction
539:             + layer.powf(0.88) * (0.95 - clear_bole_fraction)
540:             + (primary_unit_draw(streams::BEECH_PRIMARY_ATTACHMENT) - 0.5) * 0.032)
541:             .clamp(clear_bole_fraction, 0.96);
542:         let start = sample_polyline(&trunk_points, height_fraction);
543:         let phase = crown_phase
544:             + primary_index as f32 * 2.399_963_1
545:             + (primary_unit_draw(streams::PRIMARY_PHASE) - 0.5) * 0.42;
546:         let radial = Vec3::new(phase.cos(), 0.0, phase.sin());
547:         let tangent = Vec3::new(-phase.sin(), 0.0, phase.cos());
548:         // A continuous ovate crown is widest below mid-crown and closes
549:         // steadily toward the leader. Unequal reach prevents shelf tiers from
550:         // reading as repeated horizontal plates.
551:         let crown_profile = (core::f32::consts::PI * (0.12 + layer * 0.8))
552:             .sin()
553:             .max(0.28);
554:         let reach = crown_radius
555:             * crown_profile
556:             * (0.78 + primary_unit_draw(streams::PRIMARY_REACH) * 0.36);
557:         let primary_points = (0..=5)
558:             .map(|index| {
559:                 let t = index as f32 / 5.0;
560:                 let arch = (core::f32::consts::PI * t).sin();
561:                 start
562:                     + radial * reach * (t * (0.86 + 0.14 * t))
563:                     + Vec3::Y * (reach * (0.18 * arch + (0.5 + layer * 0.3) * t.powf(1.35)))
564:                     + tangent * (primary_unit_draw(streams::PRIMARY_LIFT) - 0.5) * 0.42 * arch
565:             })
566:             .collect::<Vec<_>>();
567:         // LOD clusters are spatial crown sectors, not every seventh scaffold
568:         // in generation order. The latter mixed opposing azimuths into each
569:         // card and made a beech collapse into repeated full-height shelves at
570:         // aggregate distances.
571:         let primary_group = ((phase.rem_euclid(core::f32::consts::TAU) / core::f32::consts::TAU
572:             * f32::from(TREE_PRIMARY_GROUP_COUNT))
573:         .floor() as u8)
574:             .min(TREE_PRIMARY_GROUP_COUNT - 1);
575:         append_branch_curve(
576:             &mut branches,
577:             &primary_points,
578:             0.24 - layer * 0.095,
579:             0.018,
580:             1,
581:             primary_group,
582:             u16::MAX,
583:         );
584: 
585:         for secondary_index in 0..5_u64 {
586:             let secondary_seed = streams::BEECH_SECONDARY.seed(primary_seed, &[secondary_index]);
587:             let secondary_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
588:                 purpose.rng(secondary_seed, &[]).inclusive_unit_f32()
589:             };
590:             let along = (0.12
591:                 + secondary_index as f32 * 0.17
592:                 + (secondary_unit_draw(streams::BEECH_SECONDARY_ATTACHMENT) - 0.5) * 0.055)
593:                 .clamp(0.08, 0.84);
594:             let secondary_start = sample_polyline(&primary_points, along);
595:             let side = if secondary_index & 1 == 0 { 1.0 } else { -1.0 };
596:             let vertical_bias =
597:                 0.06 + secondary_unit_draw(streams::SECONDARY_RADIAL) * 0.42 + layer * 0.12;
598:             let direction = (radial * (0.38 + along * 0.25)
599:                 + tangent
600:                     * side

601:                     * (0.62 + secondary_unit_draw(streams::SECONDARY_INHERITANCE) * 0.22)
602:                 + Vec3::Y * vertical_bias)
603:                 .normalize();
604:             let length = crown_radius
605:                 * crown_profile
606:                 * (0.3 + secondary_unit_draw(streams::SECONDARY_LIFT) * 0.15);
607:             let secondary_points = [
608:                 secondary_start,
609:                 secondary_start + direction * length * 0.5 + Vec3::Y * 0.04,
610:                 secondary_start + direction * length + Vec3::Y * (0.16 + layer * 0.12),
611:             ];
612:             let secondary_group = (primary_index * 8 + secondary_index) as u16;
613:             append_branch_curve(
614:                 &mut branches,
615:                 &secondary_points,
616:                 0.048,
617:                 0.007,
618:                 2,
619:                 primary_group,
620:                 secondary_group,
621:             );
622:             for twig_index in 0..6_u64 {
623:                 let twig_seed = streams::BEECH_TWIG.seed(secondary_seed, &[twig_index]);
624:                 let twig_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
625:                     purpose.rng(twig_seed, &[]).inclusive_unit_f32()
626:                 };
627:                 let twig_start = sample_polyline(&secondary_points, 0.1 + twig_index as f32 * 0.15);
628:                 let (right, up) = branch_frame(direction);
629:                 let phase = twig_index as f32 * 2.399_963_1 + twig_unit_draw(streams::TWIG_PHASE);
630:                 let twig_direction = (direction * 0.48
631:                     + right * phase.cos() * 0.52
632:                     + up * phase.sin() * 0.3
633:                     + Vec3::Y * (0.08 + layer * 0.08))
634:                     .normalize();
635:                 let twig_length = 0.4 + twig_unit_draw(streams::TWIG_LENGTH) * 0.27;
636:                 append_branch_curve(
637:                     &mut branches,
638:                     &[
639:                         twig_start,
640:                         twig_start + twig_direction * twig_length * 0.52,
641:                         twig_start + twig_direction * twig_length,
642:                     ],
643:                     0.008,
644:                     0.002,
645:                     3,
646:                     primary_group,
647:                     secondary_group,
648:                 );
649:             }
650:         }
651:     }
652:     branches
653: }
