655: fn procedural_multistem_shrub_skeleton(
656:     seed: fabelgeist_determinism::Seed,
657:     parameters: WoodyPlantParameters,
658: ) -> Vec<TreeBranchSegment> {
659:     let mut branches = Vec::new();
660:     let stem_count = u64::from(parameters.basal_stems.max(3));
661:     for stem_index in 0..stem_count {
662:         let stem_seed = streams::SHRUB_STEM.seed(seed, &[stem_index]);
663:         let stem_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
664:             purpose.rng(stem_seed, &[]).inclusive_unit_f32()
665:         };
666:         let phase = stem_index as f32 * 2.399_963_1 + stem_unit_draw(streams::STEM_PHASE) * 0.55;
667:         let outward = Vec3::new(phase.cos(), 0.0, phase.sin());
668:         let tangent = Vec3::new(-phase.sin(), 0.0, phase.cos());
669:         let height =
670:             parameters.height_metres * (0.76 + stem_unit_draw(streams::STEM_HEIGHT) * 0.24);
671:         let lean =
672:             parameters.crown_radius_metres * (0.34 + stem_unit_draw(streams::STEM_LEAN) * 0.32);
673:         let stem_points = (0..=6)
674:             .map(|point_index| {
675:                 let t = point_index as f32 / 6.0;
676:                 Vec3::Y * height * t
677:                     + outward * lean * t.powf(1.35)
678:                     + tangent * 0.11 * (core::f32::consts::PI * t).sin()
679:             })
680:             .collect::<Vec<_>>();
681:         append_branch_curve(
682:             &mut branches,
683:             &stem_points,
684:             0.035 + stem_unit_draw(streams::STEM_RADIUS) * 0.018,
685:             0.008,
686:             0,
687:             stem_index as u8,
688:             u16::MAX,
689:         );
690:         for branch_index in 0..10_u64 {
691:             let branch_seed = streams::SHRUB_BRANCH.seed(stem_seed, &[branch_index]);
692:             let attach = 0.2 + branch_index as f32 / 10.0 * 0.76;
693:             let start = sample_polyline(&stem_points, attach);
694:             let inherited = polyline_tangent(&stem_points, attach);
695:             let spiral = phase + branch_index as f32 * 2.399_963_1;
696:             let radial = Vec3::new(spiral.cos(), 0.0, spiral.sin());
697:             let direction =
698:                 (inherited * 0.26 + radial * 0.88 + Vec3::Y * (0.3 - attach * 0.17)).normalize();
699:             let length = parameters.crown_radius_metres
700:                 * (0.42
701:                     + streams::BRANCH_LENGTH
702:                         .rng(branch_seed, &[])
703:                         .inclusive_unit_f32()
704:                         * 0.34)
705:                 * (1.0 - attach * 0.22);
706:             let branch_points = [
707:                 start,
708:                 start + direction * length * 0.5 + Vec3::Y * 0.08,
709:                 start + direction * length + Vec3::Y * 0.16,
710:             ];
711:             let secondary_group = (stem_index * 16 + branch_index) as u16;
712:             let branch_start_radius = child_base_radius(
713:                 0.014,
714:                 curve_radius_at(
715:                     0.035 + stem_unit_draw(streams::STEM_RADIUS) * 0.018,
716:                     0.008,
717:                     attach,
718:                 ),
719:             );
720:             append_branch_curve(
721:                 &mut branches,
722:                 &branch_points,
723:                 branch_start_radius,
724:                 0.0036,
725:                 2,
726:                 stem_index as u8,
727:                 secondary_group,
728:             );
729:             append_shrub_shoots(
730:                 &mut branches,
731:                 branch_seed,
732:                 &branch_points,
733:                 branch_start_radius,
734:                 direction,
735:                 (stem_index as u8, secondary_group),
736:             );
737:         }
738:         // The stem itself ends in a short leafy flush. Without this terminal
739:         // continuation the shared shrub reads as a bundle of pruned rods and
740:         // develops an artificial flat top.
741:         let stem_tip = *stem_points.last().unwrap();
742:         let stem_direction = polyline_tangent(&stem_points, 1.0);
743:         let (stem_right, stem_up) = branch_frame(stem_direction);
744:         for tip_index in 0..5_u64 {
745:             let tip_seed = streams::SHRUB_TIP.seed(stem_seed, &[tip_index]);
746:             let tip_unit_draw = |purpose: fabelgeist_determinism::StreamId| {
747:                 purpose.rng(tip_seed, &[]).inclusive_unit_f32()
748:             };
749:             let phase = tip_index as f32 * 2.399_963_1 + tip_unit_draw(streams::TIP_PHASE) * 0.4;
750:             let direction = (stem_direction * 0.5
751:                 + stem_right * phase.cos() * 0.58
752:                 + stem_up * phase.sin() * 0.42)
753:                 .normalize();
754:             let length = 0.16 + tip_unit_draw(streams::TIP_LENGTH) * 0.12;
755:             append_branch_curve(
756:                 &mut branches,
757:                 &[
758:                     stem_tip,
759:                     stem_tip + direction * length * 0.5,
760:                     stem_tip + direction * length,
761:                 ],
762:                 0.0045,
763:                 0.0014,
764:                 3,
765:                 stem_index as u8,
766:                 (stem_index * 16 + 15) as u16,
767:             );
768:         }
769:     }
770:     branches
771: }
772: 
773: fn append_branch_curve(
774:     branches: &mut Vec<TreeBranchSegment>,
775:     points: &[Vec3],
776:     start_radius: f32,
777:     end_radius: f32,
778:     depth: u8,
779:     primary_group: u8,
780:     secondary_group: u16,
781: ) {
782:     let segment_count = points.len() - 1;
783:     for index in 0..segment_count {
784:         let t0 = index as f32 / segment_count as f32;
785:         let t1 = (index + 1) as f32 / segment_count as f32;
786:         branches.push(TreeBranchSegment {
787:             start: points[index],
788:             end: points[index + 1],
789:             start_radius: start_radius.lerp(end_radius, t0.powf(0.64)),
790:             end_radius: start_radius.lerp(end_radius, t1.powf(0.64)),
791:             depth,
792:             primary_group,
793:             secondary_group,
794:             is_limb_tip: index + 1 == segment_count,
795:         });
796:     }
797: }
