799: fn sample_polyline(points: &[Vec3], t: f32) -> Vec3 {
800:     let scaled = t.clamp(0.0, 1.0) * (points.len() - 1) as f32;

801:     let index = scaled.floor().min((points.len() - 2) as f32) as usize;
802:     points[index].lerp(points[index + 1], scaled - index as f32)
803: }
804: 
805: fn polyline_tangent(points: &[Vec3], t: f32) -> Vec3 {
806:     let scaled = t.clamp(0.0, 1.0) * (points.len() - 1) as f32;
807:     let index = scaled.floor().min((points.len() - 2) as f32) as usize;
808:     (points[index + 1] - points[index]).normalize()
809: }
