15: /// Geometry budgets for live woody branch sweeps.
16: ///
17: /// `FullDetail` is the authored trunk/root and LOD0 branch mesh. The mid
18: /// trunk and aggregate crown tiers deliberately opt into their own budgets so
19: /// reducing distant geometry cannot silently change close tree silhouettes or
20: /// root contact.
21: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
22: pub(in crate::presentation) enum WoodyBranchMeshQuality {
23:     FullDetail,
24:     MidDistanceTrunk,
25:     AggregateLod1,
26:     AggregateLod2,
27: }
28: 
29: impl WoodyBranchMeshQuality {
30:     fn radial_sides(self, depth: u8) -> u32 {
31:         match self {
32:             Self::FullDetail => {
33:                 if depth == 0 {
34:                     16
35:                 } else {
36:                     (8_u32.saturating_sub(u32::from(depth))).max(4)
37:                 }
38:             }
39:             // The middle tier carries only the upright bole. Its faceting is
40:             // hidden by distance while retaining enough sides for stable bark
41:             // highlights through the LOD3 handoff.
42:             Self::MidDistanceTrunk => {
43:                 if depth == 0 {
44:                     9
45:                 } else {
46:                     4
47:                 }
48:             }
49:             // LOD1 keeps a little more roundness on scaffold branches, while
50:             // its covered terminal wood falls to four sides.
51:             Self::AggregateLod1 => match depth {
52:                 0 => 16,
53:                 1 => 5,
54:                 _ => 4,
55:             },
56:             // LOD2 contains only depth-one scaffold wood. Four sides are
57:             // enough behind its larger impostor cards.
58:             Self::AggregateLod2 => {
59:                 if depth == 0 {
60:                     16
61:                 } else {
62:                     4
63:                 }
64:             }
65:         }
66:     }
67: 
68:     fn axial_spacing_metres(self) -> f32 {
69:         match self {
70:             Self::FullDetail => 0.45,
71:             Self::MidDistanceTrunk => 0.9,
72:             Self::AggregateLod1 => 0.75,
73:             Self::AggregateLod2 => 1.1,
74:         }
75:     }
76: 
77:     fn uses_rounded_terminal(self) -> bool {
78:         matches!(self, Self::FullDetail)
79:     }
80: }
