100: /// Mid-distance playable-tree trunk mesh.
101: ///
102: /// This deliberately retains only the upright depth-zero bole. The authored
103: /// full-detail mesh keeps the root flare and contact geometry near the
104: /// camera; reproducing those roots in this tier would spend geometry on
105: /// detail that is no longer readable and would make the near/mid overlap
106: /// visually muddy.
107: pub(in crate::presentation) fn procedural_woody_mid_trunk_mesh(
108:     branches: &[TreeBranchSegment],
109: ) -> Mesh {
110:     let upright_bole = branches
111:         .iter()
112:         .filter(|branch| {
113:             if branch.depth != 0 {
114:                 return false;
115:             }
116:             let axis = branch.end - branch.start;
117:             axis.length_squared() > 0.000_001 && axis.y.abs() >= axis.xz().length() * 0.7
118:         })
119:         .copied()
120:         .collect::<Vec<_>>();
121:     procedural_woody_branch_mesh_with_quality(
122:         &upright_bole,
123:         0,
124:         WoodyBranchMeshQuality::MidDistanceTrunk,
125:     )
126: }
