128: fn procedural_woody_branch_mesh_with_quality(
129:     branches: &[TreeBranchSegment],
130:     maximum_depth: u8,
131:     quality: WoodyBranchMeshQuality,
132: ) -> Mesh {
133:     let mut positions = Vec::new();
134:     let mut normals = Vec::new();
135:     let mut uvs = Vec::new();
136:     let mut indices = Vec::new();
137:     // Explicit root curves preserve their authored branching and overlap the
138:     // continuous trunk sweep below its surface. The former implicit flare
139:     // collapsed those roots into a bulb and exposed a horizontal handoff.
140:     let visible = branches
141:         .iter()
142:         .filter(|branch| branch.depth <= maximum_depth)
143:         .copied()
144:         .collect::<Vec<_>>();
145:     let mut curve_start = 0;
146:     while curve_start < visible.len() {
147:         let curve_end = visible[curve_start..]
148:             .iter()
149:             .position(|branch| branch.is_limb_tip)
150:             .map(|offset| curve_start + offset + 1)
151:             .unwrap_or(visible.len());
152:         let curve = &visible[curve_start..curve_end];
153:         append_branch_curve_tube(
154:             curve,
155:             quality,
156:             &mut positions,
157:             &mut normals,
158:             &mut uvs,
159:             &mut indices,
160:         );
161:         curve_start = curve_end;
162:     }
163:     let mut mesh = Mesh::new(
164:         PrimitiveTopology::TriangleList,
165:         RenderAssetUsages::RENDER_WORLD,
166:     );
167:     if visible.iter().any(|branch| branch.depth == 0) {
168:         // The bark shader needs metric height above the root contact plane for
169:         // its UV-free soil-deposition mask. Vertex colour is an interpolated
170:         // geometry channel here, not pigment: local Y remains exact across a
171:         // triangle and avoids creating a unique material for every tree.
172:         let ground_y = -TREE_TRUNK_HEIGHT_METRES * 0.5;
173:         let root_heights = positions
174:             .iter()
175:             .map(|position| [position[1] - ground_y, 1.0, 1.0, 1.0])
176:             .collect::<Vec<_>>();
177:         mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, root_heights);
178:     }
179:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
180:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
181:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
182:     mesh.insert_indices(Indices::U32(indices));
183:     mesh
184: }
