443: /// A longitudinal groove with raised lips, evaluated in branch space.
444: ///
445: /// The angular signal is periodic rather than UV-based, so crossing the
446: /// cylindrical wrap cannot create a discontinuity. The world-space warp makes
447: /// the fissures wander without baking any colour variation into the material.
448: #[cfg(test)]
449: fn bark_relief(point: Vec3, segment: &TreeBranchSegment, bark: BarkRecipe, bark_phase: f32) -> f32 {
450:     let axis = segment.end - segment.start;
451:     let length_squared = axis.length_squared();
452:     if length_squared <= 1.0e-6 {
453:         return 0.0;
454:     }
455:     let along = ((point - segment.start).dot(axis) / length_squared).clamp(0.0, 1.0);
456:     let tangent = axis.normalize();
457:     let center = segment.start + axis * along;
458:     let radius = segment
459:         .start_radius
460:         .lerp(segment.end_radius, along.powf(0.64));
461:     let radial = (point - center).normalize_or_zero();
462:     if radial.length_squared() < 0.5 {
463:         return 0.0;
464:     }
465:     let (right, forward) = branch_frame(tangent);
466:     let theta = radial.dot(forward).atan2(radial.dot(right));
467:     const CRACK_PHASES: [f32; 13] = [
468:         0.08, 0.55, 0.91, 1.53, 1.86, 2.44, 2.86, 3.27, 3.82, 4.17, 4.78, 5.31, 5.83,
469:     ];
470:     let axial_metres = (point - segment.start).dot(tangent);
471:     let mut nearest_crack = f32::INFINITY;
472:     let mut signed_crack = 0.0;
473:     let mut nearest_crack_index = 0;
474:     for (index, base_phase) in CRACK_PHASES.into_iter().enumerate() {
475:         let seed_phase = index as f32 * 1.618_034;
476:         let drift = 0.11 * (point.dot(Vec3::new(0.17, 0.83, -0.29)) * 1.18 + seed_phase).sin()
477:             + 0.045 * (point.dot(Vec3::new(-0.53, 0.24, 0.47)) * 2.37 - seed_phase * 0.7).sin();
478:         let delta = (theta - base_phase - bark_phase - drift + core::f32::consts::PI)
479:             .rem_euclid(core::f32::consts::TAU)
480:             - core::f32::consts::PI;
481:         let distance = delta.abs() * radius;
482:         if distance < nearest_crack {
483:             nearest_crack = distance;
484:             signed_crack = delta * radius;
485:             nearest_crack_index = index;
486:         }
487:     }
488:     let arc_distance = nearest_crack;
489:     let depth_index = usize::from(segment.depth.min(3));
490:     let hierarchy = bark.branch_depth_attenuation[depth_index];
491:     let maturity = ((radius - bark.minimum_radius_metres)
492:         / (bark.mature_radius_metres - bark.minimum_radius_metres).max(1.0e-4))
493:     .clamp(0.0, 1.0);
494:     let strength = hierarchy * maturity * maturity * (3.0 - 2.0 * maturity);
495:     if strength <= 1.0e-4 {
496:         return 0.0;
497:     }
498: 
499:     // Mature oak fissures are streams, not uninterrupted flutes. Each stream
500:     // closes on a different, softly staggered cadence so adjacent plates
501:     // interlock rather than forming horizontal bands. A small residual keeps
502:     // the relief continuous while the dominant groove visibly terminates.
503:     let plate_phase = nearest_crack_index as f32 * 2.399_963
504:         + segment.primary_group as f32 * 0.37
505:         + bark_phase * 0.73;
506:     let plate_length = bark.plate_length_metres.max(0.08);
507:     let break_signal = (axial_metres * core::f32::consts::TAU / plate_length + plate_phase).sin()
508:         + 0.38
509:             * (axial_metres * core::f32::consts::TAU / (plate_length * 0.47) - plate_phase * 0.6)
510:                 .sin();
511:     let fissure_continuity = smoothstep(-0.52, -0.05, break_signal);
512:     // A closed plate should actually interrupt a fissure. Retaining most of
513:     // the groove made one angular stream read as a manufactured longitudinal
514:     // seam even though the cylindrical wrap itself was continuous.
515:     let fissure_strength = 0.18 + 0.82 * fissure_continuity * fissure_continuity;
516:     let groove = (-bark.fissure_depth_metres
517:         * (-0.5 * (arc_distance / bark.fissure_width_metres.max(1.0e-4)).powi(2)).exp())
518:     .max(-radius * 0.035)
519:         * fissure_strength;
520:     let lip_center = bark.fissure_width_metres * 2.25;
521:     let lip_width = bark.fissure_width_metres * 1.15;
522:     let lip_distance = (arc_distance - lip_center) / lip_width.max(1.0e-4);
523:     let lip_asymmetry = 1.0 + 0.18 * (signed_crack / bark.fissure_width_metres.max(1.0e-4)).tanh();
524:     let lips = (bark.lip_height_metres * lip_asymmetry * (-0.5 * lip_distance.powi(2)).exp())
525:         .min(radius * 0.035)
526:         * (0.72 + 0.28 * fissure_continuity);
527:     let plate_t = (arc_distance / (radius * 0.24).max(0.035)).clamp(0.0, 1.0);
528:     let plate_crown = bark.plate_height_metres * (core::f32::consts::PI * plate_t).sin().powi(2);
529:     let transverse_breaks = 0.48
530:         + 0.32 * (axial_metres * core::f32::consts::TAU / plate_length - plate_phase * 0.4).sin()
531:         + 0.20 * (theta * 3.0 + plate_phase).sin();
532:     let broad_warp = 0.27 * (point.dot(Vec3::new(0.21, 0.62, -0.37)) * 0.74).sin();
533:     let broad_fold = 0.007 * (5.0 * theta + broad_warp).cos() * (radius / 0.7).clamp(0.2, 1.0);
534:     let closure = 1.0 - fissure_continuity;
535:     let between_fissures = smoothstep(
536:         bark.fissure_width_metres * 2.8,
537:         bark.fissure_width_metres * 5.5,
538:         arc_distance,
539:     );
540:     let transverse_closure = -bark.fissure_depth_metres * 0.16 * closure * between_fissures;
541:     // Horizontal roots carry broader, quieter folds than the upright trunk.
542:     // This prevents fine bark relief from turning the root crown into a pile
543:     // of inflated cords while preserving the same continuous surface field.
544:     let upright = tangent.y.abs();
545:     let orientation_attenuation = 0.88 + 0.12 * upright;
546:     (groove + lips + plate_crown * transverse_breaks.max(0.18) + broad_fold + transverse_closure)
547:         * strength
548:         * orientation_attenuation
549: }
