551: #[cfg(test)]
552: fn smoothstep(edge0: f32, edge1: f32, value: f32) -> f32 {
553:     let t = ((value - edge0) / (edge1 - edge0).max(1.0e-6)).clamp(0.0, 1.0);
554:     t * t * (3.0 - 2.0 * t)
555: }
