557: /// Blend branch-space relief with the same proximity semantics as the smooth
558: /// implicit union. No nearest-segment switch is exposed at root junctions.
559: #[cfg(test)]
560: fn blended_bark_relief(
561:     point: Vec3,
562:     segments: &[TreeBranchSegment],
563:     blend: f32,
564:     bark: BarkRecipe,
565:     bark_phase: f32,
566: ) -> f32 {
567:     let nearest = segments
568:         .iter()
569:         .map(|segment| capsule_distance(point, segment))
570:         .fold(f32::INFINITY, f32::min);
571:     let mut weighted = 0.0;
572:     let mut total = 0.0;
573:     for segment in segments {
574:         let delta = (capsule_distance(point, segment) - nearest).max(0.0);
575:         let weight = (-4.0 * delta / blend.max(1.0e-4)).exp();
576:         if weight > 1.0e-4 {
577:             weighted += bark_relief(point, segment, bark, bark_phase) * weight;
578:             total += weight;
579:         }
580:     }
581:     if total > 0.0 { weighted / total } else { 0.0 }
582: }
