584: #[cfg(test)]
585: fn capsule_distance(point: Vec3, segment: &TreeBranchSegment) -> f32 {
586:     let axis = segment.end - segment.start;
587:     let length_squared = axis.length_squared();
588:     let along = if length_squared > 1.0e-6 {
589:         ((point - segment.start).dot(axis) / length_squared).clamp(0.0, 1.0)
590:     } else {
591:         0.0
592:     };
593:     let radius = segment
594:         .start_radius
595:         .lerp(segment.end_radius, along.powf(0.64));
596:     point.distance(segment.start + axis * along) - radius
597: }
