652: fn append_branch_curve_tube(
653:     curve: &[TreeBranchSegment],
654:     quality: WoodyBranchMeshQuality,
655:     positions: &mut Vec<[f32; 3]>,
656:     normals: &mut Vec<[f32; 3]>,
657:     uvs: &mut Vec<[f32; 2]>,
658:     indices: &mut Vec<u32>,
659: ) {
660:     const BARK_TEXTURE_WIDTH_METRES: f32 = 1.0;
661:     const BARK_TEXTURE_HEIGHT_METRES: f32 = 2.0;
662: 
663:     let first = curve[0];
664:     let last = curve[curve.len() - 1];
665:     let sides = quality.radial_sides(first.depth);
666:     let first_direction = (first.end - first.start).normalize();
667:     let last_direction = (last.end - last.start).normalize();
668:     let surface_root = first.depth == 0
669:         && first.start.y < -0.75
670:         && first_direction.xz().length() > first_direction.y.abs() * 0.7;
671:     let mut rings = Vec::with_capacity(curve.len() + 2);
672:     if first.depth > 0 {
673:         // One basal collar belongs at the biological attachment. Repeating a
674:         // collar at every polygon joint makes a smooth axis look assembled.
675:         rings.push((
676:             first.start - first_direction * first.start_radius * 0.12,
677:             first.start_radius * 1.12,
678:             first_direction,
679:         ));
680:         rings.push((
681:             first.start + first_direction * first.start_radius * 0.28,
682:             first.start_radius * 1.06,
683:             first_direction,
684:         ));
685:         rings.push((
686:             first.start + first_direction * first.start_radius * 0.72,
687:             first.start_radius * 0.98,
688:             first_direction,
689:         ));
690:     } else {
691:         rings.push((
692:             first.start - first_direction * first.start_radius * 0.18,
693:             first.start_radius,
694:             first_direction,
695:         ));
696:     }
697:     for (index, branch) in curve.iter().enumerate() {
698:         let direction = (branch.end - branch.start).normalize();
699:         let tangent = if index + 1 < curve.len() {
700:             (direction + (curve[index + 1].end - curve[index + 1].start).normalize()).normalize()
701:         } else {
702:             direction
703:         };
704:         // Smooth wood needs only enough axial sampling to preserve the authored
705:         // skeleton curve and taper. Fine bark is intentionally material-only.
706:         let spacing = quality.axial_spacing_metres();
707:         let steps = ((branch.end - branch.start).length() / spacing)
708:             .ceil()
709:             .max(1.0) as u32;
710:         for step in 1..=steps {
711:             let along = step as f32 / steps as f32;
712:             rings.push((
713:                 branch.start.lerp(branch.end, along),
714:                 branch
715:                     .start_radius
716:                     .lerp(branch.end_radius, along.powf(0.64)),
717:                 tangent,
718:             ));
719:         }
720:     }
721:     if surface_root {
722:         let ground_y = -TREE_TRUNK_HEIGHT_METRES * 0.5;
723:         for (center, radius, _) in &mut rings {
724:             center.y += *radius * 0.75;
725:             center.y = center.y.max(ground_y + *radius * 0.05);
726:         }
727:     }
728:     let ring_stride = sides + 1;
729:     // A whole-number wrap keeps the duplicated cylindrical seam texel-exact.
730:     // Choose it from the biological base circumference so scale is physical
731:     // and stable along a tapering axis rather than resetting per segment.
732:     let circumference_tiles = (core::f32::consts::TAU * first.start_radius
733:         / BARK_TEXTURE_WIDTH_METRES)
734:         .round()
735:         .max(1.0);
736:     let base = positions.len() as u32;
737:     let mut accumulated_distance = 0.0;
738:     let (mut right, mut forward) = branch_frame(rings[0].2);
739:     let mut previous_center = rings[0].0;
740:     let mut previous_tangent = rings[0].2;
741:     for (ring, (center, radius, tangent)) in rings.iter().copied().enumerate() {
742:         if ring > 0 {
743:             accumulated_distance += center.distance(previous_center);
744:             (right, forward) = transport_branch_frame(previous_tangent, right, tangent);
745:         }
746:         let ring_base = positions.len();
747:         for side in 0..sides {
748:             let phase = side as f32 * core::f32::consts::TAU / sides as f32;
749:             let radial = right * phase.cos() + forward * phase.sin();
750:             let offset = if surface_root {
751:                 Vec3::new(radial.x * 1.25, radial.y * 0.45, radial.z * 1.25) * radius
752:             } else {
753:                 radial * radius
754:             };
755:             let normal = if surface_root {
756:                 Vec3::new(radial.x / 1.25, radial.y / 0.45, radial.z / 1.25).normalize()
757:             } else {
758:                 radial
759:             };
760:             positions.push((center + offset).to_array());
761:             normals.push(normal.to_array());
762:             uvs.push([
763:                 side as f32 / sides as f32 * circumference_tiles,
764:                 accumulated_distance / BARK_TEXTURE_HEIGHT_METRES,
765:             ]);
766:         }
767:         // Duplicate the first evaluated vertex bit-for-bit at the cylindrical
768:         // wrap. Re-evaluating sin(TAU), relief, and its finite-difference normal
769:         // can otherwise produce a hairline lighting discontinuity.
770:         positions.push(positions[ring_base]);
771:         normals.push(normals[ring_base]);
772:         uvs.push([
773:             circumference_tiles,
774:             accumulated_distance / BARK_TEXTURE_HEIGHT_METRES,
775:         ]);
776:         previous_center = center;
777:         previous_tangent = tangent;
778:     }
779:     for ring in 0..rings.len() as u32 - 1 {
780:         let from = base + ring * ring_stride;
781:         let to = from + ring_stride;
782:         for side in 0..sides {
783:             let next = side + 1;
784:             indices.extend_from_slice(&[
785:                 from + side,
786:                 to + side,
787:                 to + next,
788:                 from + side,
789:                 to + next,
790:                 from + next,
791:             ]);
792:         }
793:     }
794:     let end_ring = base + (rings.len() as u32 - 1) * ring_stride;
795:     if last.is_limb_tip && quality.uses_rounded_terminal() {
796:         // A pair of shrinking rings gives every terminal axis a rounded,
797:         // natural taper. Flat caps read as sawn-off limbs and become black
798:         // rectangular artifacts in the descendant renders.
799:         let shoulder = positions.len() as u32;
800:         let bud_length = last.end_radius;

801:         let (right, forward) = transport_branch_frame(previous_tangent, right, last_direction);
802:         let mut terminal_distance = accumulated_distance;
803:         let mut terminal_center = last.end;
804:         for (distance, radius_scale) in [(0.55, 0.58), (0.92, 0.12)] {
805:             let radius = last.end_radius * radius_scale;
806:             let center = last.end
807:                 + last_direction * bud_length * distance
808:                 + Vec3::Y * if surface_root { radius * 0.75 } else { 0.0 };
809:             let center = if surface_root {
810:                 center.with_y(
811:                     center
812:                         .y
813:                         .max(-TREE_TRUNK_HEIGHT_METRES * 0.5 + radius * 0.05),
814:                 )
815:             } else {
816:                 center
817:             };
818:             terminal_distance += center.distance(terminal_center);
819:             for side in 0..=sides {
820:                 let phase = side as f32 * core::f32::consts::TAU / sides as f32;
821:                 let radial = right * phase.cos() + forward * phase.sin();
822:                 let offset = if surface_root {
823:                     Vec3::new(radial.x * 1.25, radial.y * 0.45, radial.z * 1.25) * radius
824:                 } else {
825:                     radial * radius
826:                 };
827:                 let surface_radial = if surface_root {
828:                     Vec3::new(radial.x / 1.25, radial.y / 0.45, radial.z / 1.25).normalize()
829:                 } else {
830:                     radial
831:                 };
832:                 let normal = (surface_radial * 0.75 + last_direction * 0.66).normalize();
833:                 positions.push((center + offset).to_array());
834:                 normals.push(normal.to_array());
835:                 uvs.push([
836:                     side as f32 / sides as f32 * circumference_tiles,
837:                     terminal_distance / BARK_TEXTURE_HEIGHT_METRES,
838:                 ]);
839:             }
840:             terminal_center = center;
841:         }
842:         for ring in 0..2_u32 {
843:             let from = if ring == 0 { end_ring } else { shoulder };
844:             let to = shoulder + ring * ring_stride;
845:             for side in 0..sides {
846:                 let next = side + 1;
847:                 indices.extend_from_slice(&[
848:                     from + side,
849:                     to + side,
850:                     to + next,
851:                     from + side,
852:                     to + next,
853:                     from + next,
854:                 ]);
855:             }
856:         }
857:         let tip = positions.len() as u32;
858:         positions.push((last.end + last_direction * bud_length).to_array());
859:         normals.push(last_direction.to_array());
860:         uvs.push([
861:             0.0,
862:             (accumulated_distance + bud_length) / BARK_TEXTURE_HEIGHT_METRES,
863:         ]);
864:         for side in 0..sides {
865:             let next = side + 1;
866:             indices.extend_from_slice(&[
867:                 tip,
868:                 shoulder + ring_stride + side,
869:                 shoulder + ring_stride + next,
870:             ]);
871:         }
872:     } else if last.is_limb_tip {
873:         // Aggregate wood sits behind baked canopy cards. A single tapered cap
874:         // preserves the branch silhouette without the two extra rounded rings
875:         // that close the near-field mesh.
876:         let tip = positions.len() as u32;
877:         let bud_length = last.end_radius;
878:         positions.push((last.end + last_direction * bud_length * 0.7).to_array());
879:         normals.push(last_direction.to_array());
880:         uvs.push([
881:             0.0,
882:             (accumulated_distance + bud_length * 0.7) / BARK_TEXTURE_HEIGHT_METRES,
883:         ]);
884:         for side in 0..sides {
885:             let next = side + 1;
886:             indices.extend_from_slice(&[tip, end_ring + side, end_ring + next]);
887:         }
888:     }
889: }
