1257:     #[test]
1258:     fn bark_relief_is_periodic_and_blends_at_root_influence_boundaries() {
1259:         let branches = procedural_tree_skeleton(fabelgeist_determinism::Seed::from_u64(42), 0.0);
1260:         let bark_phase = bark_phase_from_branches(&branches);
1261:         let field = RootFlareField::from_branches(&branches, 0, ENGLISH_OAK_BARK)
1262:             .expect("oak has a root flare");
1263:         let trunk = field
1264:             .segments
1265:             .iter()
1266:             .find(|segment| (segment.end - segment.start).xz().length() < 0.1)
1267:             .expect("oak flare includes a vertical trunk segment");
1268:         let axis = trunk.end - trunk.start;
1269:         let center = trunk.start + axis * 0.35;
1270:         let tangent = axis.normalize();
1271:         let (right, forward) = branch_frame(tangent);
1272:         let radius = trunk
1273:             .start_radius
1274:             .lerp(trunk.end_radius, 0.35_f32.powf(0.64));
1275:         let epsilon = 1.0e-5_f32;
1276:         let before = center + (right * epsilon.cos() + forward * (-epsilon).sin()) * radius;
1277:         let after = center + (right * epsilon.cos() + forward * epsilon.sin()) * radius;
1278:         assert!(
1279:             (bark_relief(before, trunk, ENGLISH_OAK_BARK, bark_phase)
1280:                 - bark_relief(after, trunk, ENGLISH_OAK_BARK, bark_phase))
1281:             .abs()
1282:                 < 1.0e-3
1283:         );
1284: 
1285:         let junction = field
1286:             .segments
1287:             .iter()
1288:             .filter(|segment| (segment.end - segment.start).xz().length() > 0.2)
1289:             .map(|segment| segment.start)
1290:             .next()
1291:             .expect("oak flare includes a root junction");
1292:         let left = blended_bark_relief(
1293:             junction - Vec3::X * 0.002,
1294:             &field.segments,
1295:             field.blend,
1296:             ENGLISH_OAK_BARK,
1297:             bark_phase,
1298:         );
1299:         let right = blended_bark_relief(
1300:             junction + Vec3::X * 0.002,
1301:             &field.segments,
1302:             field.blend,
1303:             ENGLISH_OAK_BARK,
1304:             bark_phase,
1305:         );
1306:         assert!(left.is_finite() && right.is_finite());
1307:         assert!((left - right).abs() < 0.01);
1308:     }
