1340:         let field = RootFlareField::from_branches(&branches, 0, ENGLISH_OAK_BARK)
1341:             .expect("oak has a root flare");
1342:         let base = field
1343:             .segments
1344:             .iter()
1345:             .map(|segment| segment.start.y)
1346:             .fold(f32::INFINITY, f32::min);
1347:         let lobes = (0..128)
1348:             .map(|index| {
1349:                 let phase = index as f32 * core::f32::consts::TAU / 128.0;
1350:                 let outward = Vec3::new(phase.cos(), 0.0, phase.sin());
1351:                 (
1352:                     outward,
1353:                     field.root_profile_relief(Vec3::new(0.0, base + 0.15, 0.0), outward),
1354:                 )
