143: #[derive(Clone, Copy)]
144: pub(in crate::presentation) struct TreeBakeCard {
145:     center: Vec3,
146:     right: Vec3,
147:     up: Vec3,
148:     width: f32,
149:     height: f32,
150:     primary_mask: u8,
151:     /// LOD1 cards group a contiguous run of secondary limbs from one primary
152:     /// crown sector. The production group IDs deliberately leave room between
153:     /// sectors, so the range never spills into a neighbouring sector.
154:     secondary_group_range: Option<(u16, u16)>,
155:     source_group: u16,
156:     minimum_branch_depth: u8,
157: }
158: 
159: impl TreeBakeCard {
160:     fn includes_branch(self, branch: &TreeBranchSegment) -> bool {
161:         match (self.secondary_group_range, self.primary_mask) {
162:             (Some((first, last)), _) => {
163:                 (first..=last).contains(&branch.secondary_group)
164:                     && branch.depth >= self.minimum_branch_depth
165:             }
166:             (None, mask) if mask != 0 => {
167:                 branch.primary_group < 8
168:                     && mask & (1 << branch.primary_group) != 0
169:                     && branch.depth >= self.minimum_branch_depth
170:             }
171:             (None, _) => true,
172:         }
173:     }
174: 
175:     fn includes_leaf(self, leaf: &TreeLeaf) -> bool {
176:         match (self.secondary_group_range, self.primary_mask) {
177:             (Some((first, last)), _) => (first..=last).contains(&leaf.secondary_group),
178:             (None, mask) if mask != 0 => mask & (1 << leaf.primary_group) != 0,
179:             (None, _) => true,
180:         }
181:     }
182: 
183:     fn normal(self) -> Vec3 {
184:         self.right.cross(self.up).normalize()
185:     }
186: }
