188: pub(in crate::presentation) fn bake_tree_lod(
189:     seed: Seed,
190:     branches: &[TreeBranchSegment],
191:     leaves: &[TreeLeaf],
192:     lod: u8,
193: ) -> TreeLodBake {
194:     bake_tree_lod_with_style(seed, branches, leaves, lod, OAK_TREE_BAKE_STYLE)
