196: 
197: pub(in crate::presentation) fn bake_tree_lod_with_style(
198:     seed: Seed,
199:     branches: &[TreeBranchSegment],
200:     leaves: &[TreeLeaf],

201:     lod: u8,
202:     style: TreeBakeStyle,
203: ) -> TreeLodBake {
204:     let started = web_time::Instant::now();
205:     let cards = tree_bake_cards_with_style(seed, branches, leaves, lod, style);
206:     let tile_size = TREE_IMPOSTOR_TILE_SIZES
207:         .get(
208:             lod.checked_sub(1)
209:                 .expect("only aggregate tree LODs are baked") as usize,
210:         )
211:         .copied()
212:         .expect("only aggregate tree LODs are baked");
213:     let columns = (cards.len() as f32).sqrt().ceil() as u32;
214:     let rows = (cards.len() as u32).div_ceil(columns);
215:     let atlas_width = columns * tile_size;
216:     let atlas_height = rows * tile_size;
217:     let mut pixels = vec![0_u8; (atlas_width * atlas_height * 4) as usize];
218:     let mut positions = Vec::new();
219:     let mut normals = Vec::new();
220:     let mut uvs = Vec::new();
221:     let mut indices = Vec::new();
222:     let source_geometry_hash = tree_source_geometry_hash(branches, leaves);
223:     let mut records = Vec::with_capacity(cards.len());
224: 
225:     for (index, card) in cards.iter().copied().enumerate() {
226:         let tile_x = index as u32 % columns;
227:         let tile_y = index as u32 / columns;
228:         render_tree_card(
229:             card,
230:             branches,
231:             leaves,
232:             lod,
233:             TreeAtlasRegion {
234:                 tile_size,
235:                 atlas_width,
236:                 atlas_height,
237:                 tile_x,
238:                 tile_y,
239:             },
240:             &mut pixels,
241:             style,
242:         );
243:         let (opaque_pixel_count, silhouette_centroid) = tree_tile_alpha_stats(
244:             &pixels,
245:             atlas_width,
246:             tile_x * tile_size,
247:             tile_y * tile_size,
248:             tile_size,
249:         );
250:         let uv_min = Vec2::new(
251:             tile_x as f32 * tile_size as f32 / atlas_width as f32,
252:             tile_y as f32 * tile_size as f32 / atlas_height as f32,
253:         );
254:         let uv_max = Vec2::new(
255:             (tile_x + 1) as f32 * tile_size as f32 / atlas_width as f32,
256:             (tile_y + 1) as f32 * tile_size as f32 / atlas_height as f32,
257:         );
258:         if lod != 4 || index == 0 {
259:             let (mesh_uv_min, mesh_uv_max) = if lod == 4 {
260:                 (Vec2::ZERO, Vec2::ONE)
261:             } else {
262:                 (uv_min, uv_max)
263:             };
264:             append_tree_card_with_uv(
265:                 TreeCardGeometry {
266:                     center: card.center,
267:                     right: card.right,
268:                     up: card.up,
269:                     width: card.width
270:                         * match lod {
271:                             1 => style.lod1_runtime_width_scale,
272:                             4 => WHOLE_TREE_RUNTIME_WIDTH_SCALE,
273:                             _ => 1.0,
274:                         },
275:                     height: card.height,
276:                     uv_min: mesh_uv_min,
277:                     uv_max: mesh_uv_max,
278:                 },
279:                 TreeCardMeshBuffers {
280:                     positions: &mut positions,
281:                     normals: &mut normals,
282:                     uvs: &mut uvs,
283:                     indices: &mut indices,
284:                 },
285:             );
286:         }
287:         records.push(TreeImpostorBakeRecord {
288:             source_group: card.source_group,
289:             source_leaf_count: leaves
290:                 .iter()
291:                 .filter(|leaf| card.includes_leaf(leaf))
292:                 .count() as u16,
293:             source_branch_count: branches
294:                 .iter()
295:                 .filter(|branch| card.includes_branch(branch))
296:                 .count() as u16,
297:             view_direction: card.normal(),
298:             projected_bounds: Vec4::new(card.center.x, card.center.y, card.width, card.height),
299:             atlas_region: UVec4::new(tile_x * tile_size, tile_y * tile_size, tile_size, tile_size),
300:             opaque_pixel_count,
301:             silhouette_centroid,
302:         });
303:     }
304: 
305:     if lod == 4 {
306:         // The aggregate crown has fewer overlapping depth layers than LOD3.
307:         // A bounded bake-space exposure restores comparable interior depth
308:         // without a runtime material multiplier or changing alpha coverage.
309:         for pixel in pixels.as_chunks_mut::<4>().0 {
310:             if pixel[3] != 0 {
311:                 pixel[0] = (f32::from(pixel[0]) * WHOLE_TREE_BAKE_EXPOSURE) as u8;
312:                 pixel[1] = (f32::from(pixel[1]) * WHOLE_TREE_BAKE_EXPOSURE) as u8;
313:                 pixel[2] = (f32::from(pixel[2]) * WHOLE_TREE_BAKE_EXPOSURE) as u8;
314:             }
315:         }
316:     }
317: 
318:     let mut mesh = Mesh::new(
319:         PrimitiveTopology::TriangleList,
320:         RenderAssetUsages::RENDER_WORLD,
321:     );
322:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
323:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
324:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
325:     mesh.insert_indices(Indices::U32(indices));
326:     let clusters = if lod < 4 {
327:         (0..TREE_PRIMARY_GROUP_COUNT)
328:             .filter_map(|primary_group| {
329:                 let (center, radius) = tree_primary_group_sphere(branches, leaves, primary_group)?;
330:                 Some(TreeLodClusterBake {
331:                     primary_group,
332:                     center,
333:                     radius,
334:                 })
335:             })
336:             .collect()
337:     } else {
338:         Vec::new()
339:     };
340:     let image = Image::new(
341:         Extent3d {
342:             width: atlas_width,
343:             height: atlas_height,
344:             depth_or_array_layers: 1,
345:         },
