378: fn tree_primary_group_sphere(
379:     branches: &[TreeBranchSegment],
380:     leaves: &[TreeLeaf],
381:     primary_group: u8,
382: ) -> Option<(Vec3, f32)> {
383:     let group_branches = branches
384:         .iter()
385:         .filter(|branch| branch.depth > 0 && branch.primary_group == primary_group)
386:         .collect::<Vec<_>>();
387:     let group_leaves = leaves
388:         .iter()
389:         .filter(|leaf| leaf.primary_group == primary_group)
390:         .collect::<Vec<_>>();
391:     if group_branches.is_empty() && group_leaves.is_empty() {
392:         return None;
393:     }
394:     let mut minimum = Vec3::splat(f32::INFINITY);
395:     let mut maximum = Vec3::splat(f32::NEG_INFINITY);
396:     for branch in &group_branches {
397:         let extent = Vec3::splat(branch.start_radius.max(branch.end_radius));
398:         minimum = minimum.min(branch.start - extent).min(branch.end - extent);
399:         maximum = maximum.max(branch.start + extent).max(branch.end + extent);
400:     }

401:     for leaf in &group_leaves {
402:         let extent = Vec3::splat(leaf.length.max(leaf.width) * 0.65);
403:         minimum = minimum.min(leaf.center - extent);
404:         maximum = maximum.max(leaf.center + extent);
405:     }
406:     let center = (minimum + maximum) * 0.5;
407:     let radius = group_branches
408:         .iter()
409:         .flat_map(|branch| {
410:             [
411:                 branch.start.distance(center) + branch.start_radius,
412:                 branch.end.distance(center) + branch.end_radius,
413:             ]
414:         })
415:         .chain(
416:             group_leaves
417:                 .iter()
418:                 .map(|leaf| leaf.center.distance(center) + leaf.length.max(leaf.width) * 0.65),
419:         )
420:         .fold(0.0_f32, f32::max);
421:     Some((center, radius.max(0.01)))
422: }
