424: fn tree_tile_alpha_stats(
425:     pixels: &[u8],
426:     atlas_width: u32,
427:     tile_x: u32,
428:     tile_y: u32,
429:     tile_size: u32,
430: ) -> (u32, Vec2) {
431:     let mut count = 0_u32;
432:     let mut sum = Vec2::ZERO;
433:     for y in 0..tile_size {
434:         for x in 0..tile_size {
435:             let pixel = (((tile_y + y) * atlas_width + tile_x + x) * 4) as usize;
436:             if pixels[pixel + 3] != 0 {
437:                 count += 1;
438:                 sum += Vec2::new(x as f32 + 0.5, y as f32 + 0.5) / tile_size as f32;
439:             }
440:         }
441:     }
442:     (count, sum / count.max(1) as f32)
443: }
