455: fn tree_bake_cards_with_style(
456:     seed: Seed,
457:     branches: &[TreeBranchSegment],
458:     leaves: &[TreeLeaf],
459:     lod: u8,
460:     style: TreeBakeStyle,
461: ) -> Vec<TreeBakeCard> {
462:     let mut cards = Vec::new();
463:     match lod {
464:         1 => {
465:             // LOD1 used to create two cards for every secondary limb. An oak
466:             // therefore baked roughly 210 cards, repeating a great deal of
467:             // overlapping foliage just as the player leaves detailed range.
468:             // Keep the same primary crown sectors but partition each into two
469:             // contiguous limb runs. Secondary limbs are generated in scaffold
470:             // order, making each run a stable local crown mass rather than a
471:             // random sampling of opposing sides of the tree. Two perpendicular
472:             // cards for each run preserve broad crown occupancy from an
473:             // oblique approach, producing four cards per primary sector.
474:             for primary_group in 0..TREE_PRIMARY_GROUP_COUNT {
475:                 for (subcluster, secondary_group_range) in
476:                     lod1_macro_cluster_ranges(branches, primary_group)
477:                         .into_iter()
478:                         .enumerate()
479:                 {
480:                     let axis =
481:                         lod1_macro_cluster_axis(branches, primary_group, secondary_group_range);
482:                     // All aggregate tiers inherit the source primary-sector
483:                     // orientation. This prevents each LOD from rotating the same
484:                     // crown mass into a visibly different silhouette at handoff.
485:                     let (card_up, frame_right, rotation_axis) = if style.lod1_world_vertical {
486:                         let horizontal_axis = Vec3::new(axis.x, 0.0, axis.z).normalize_or_zero();
487:                         let frame_right = if horizontal_axis.length_squared() > 0.25 {
488:                             horizontal_axis
489:                         } else {
490:                             Vec3::X
491:                         };
492:                         (Vec3::Y, frame_right, Vec3::Y)
493:                     } else {
494:                         let frame_reference = if axis.y.abs() < 0.9 { Vec3::Y } else { Vec3::X };
495:                         (axis, axis.cross(frame_reference).normalize(), axis)
496:                     };
497:                     let subcluster_key = u16::from(primary_group)
498:                         * LOD1_MACRO_SUBCLUSTERS_PER_PRIMARY as u16
499:                         + subcluster as u16;
500:                     let phase = subcluster_phase(seed, subcluster_key);
501:                     for facing in 0..LOD1_CARD_FACINGS_PER_SUBCLUSTER {
502:                         let source_group = u16::from(primary_group)
503:                             * LOD1_MACRO_CARDS_PER_PRIMARY as u16
504:                             + subcluster as u16 * LOD1_CARD_FACINGS_PER_SUBCLUSTER as u16
505:                             + facing as u16;
506:                         let right = bevy::math::Quat::from_axis_angle(
507:                             rotation_axis,
508:                             phase + facing as f32 * core::f32::consts::FRAC_PI_2,
509:                         ) * frame_right;
510:                         cards.push(fit_tree_bake_card(
511:                             branches,
512:                             leaves,
513:                             right,
514:                             card_up,
515:                             1 << primary_group,
516:                             Some(secondary_group_range),
517:                             source_group,
518:                             3,
519:                         ));
520:                     }
521:                 }
522:             }
523:         }
524:         2 => {
525:             for group in 0..TREE_PRIMARY_GROUP_COUNT {
526:                 let right = crown_group_right(branches, group);
527:                 for facing in 0..2 {
528:                     let right = if facing == 0 {
529:                         right
530:                     } else {
531:                         Vec3::Y.cross(right).normalize()
532:                     };
533:                     cards.push(fit_tree_bake_card(
534:                         branches,
535:                         leaves,
536:                         right,
537:                         Vec3::Y,
538:                         1 << group,
539:                         None,
540:                         u16::from(group) * 2 + facing,
541:                         2,
542:                     ));
543:                 }
544:             }
545:         }
546:         3 => {
547:             for group in 0..TREE_PRIMARY_GROUP_COUNT {
548:                 let right = crown_group_right(branches, group);
549:                 for facing in 0..2 {
550:                     let right = if facing == 0 {
551:                         right
552:                     } else {
553:                         Vec3::Y.cross(right).normalize()
554:                     };
555:                     let mut card = fit_tree_bake_card(
556:                         branches,
557:                         leaves,
558:                         right,
559:                         Vec3::Y,
560:                         1 << group,
561:                         None,
562:                         u16::from(group) * 2 + facing,
563:                         1,
564:                     );
565:                     // Each card renders its assigned primary crown sectors;
566:                     // overlapping sector cards retain parallax volume.
567:                     card.width *= 1.02;
568:                     card.height *= 1.02;
569:                     cards.push(card);
570:                 }
571:             }
572:         }
573:         4 => {
574:             let bounds = tree_crown_bounds(branches, |_| true);
575:             let center = bounds.center();
576:             let width = (bounds.maximum.x - bounds.minimum.x)
577:                 .max(bounds.maximum.z - bounds.minimum.z)
578:                 + 0.6;
579:             let height = bounds.maximum.y - bounds.minimum.y + 0.5;
580:             for view in 0..8_u16 {
581:                 let angle = view as f32 * core::f32::consts::TAU / 8.0;
582:                 cards.push(TreeBakeCard {
583:                     center,
584:                     right: Vec3::new(angle.cos(), 0.0, angle.sin()),
585:                     up: Vec3::Y,
586:                     width,
587:                     height,
588:                     primary_mask: 0,
589:                     secondary_group_range: None,
590:                     source_group: view,
591:                     minimum_branch_depth: 0,
592:                 });
593:             }
594:         }
595:         _ => unreachable!("tree LOD is bounded"),
596:     }
597:     cards
598: }
599: 
600: const LOD1_MACRO_SUBCLUSTERS_PER_PRIMARY: usize = 2;

601: const LOD1_CARD_FACINGS_PER_SUBCLUSTER: usize = 2;
602: const LOD1_MACRO_CARDS_PER_PRIMARY: usize =
603:     LOD1_MACRO_SUBCLUSTERS_PER_PRIMARY * LOD1_CARD_FACINGS_PER_SUBCLUSTER;
604: 
605: /// Divides one primary crown sector into deterministic, similarly sized
606: /// secondary-limb runs. A malformed or intentionally sparse morphology can
607: /// use fewer than two runs, but the mature playable-tree recipes supply both
608: /// in each of their seven primary sectors.
609: fn lod1_macro_cluster_ranges(branches: &[TreeBranchSegment], primary_group: u8) -> Vec<(u16, u16)> {
610:     let mut groups = branches
611:         .iter()
612:         .filter(|branch| branch.depth == 2 && branch.primary_group == primary_group)
613:         .map(|branch| branch.secondary_group)
614:         .collect::<Vec<_>>();
615:     groups.sort_unstable();
616:     groups.dedup();
617: 
618:     let cluster_count = groups.len().min(LOD1_MACRO_SUBCLUSTERS_PER_PRIMARY);
619:     (0..cluster_count)
620:         .map(|subcluster| {
621:             let first = subcluster * groups.len() / cluster_count;
622:             let last = (subcluster + 1) * groups.len() / cluster_count - 1;
623:             (groups[first], groups[last])
624:         })
625:         .collect()
626: }
627: 
628: #[expect(
629:     clippy::too_many_arguments,
630:     reason = "this domain boundary names each independent input explicitly"
631: )]
632: pub(in crate::presentation) fn fit_tree_bake_card(
633:     branches: &[TreeBranchSegment],
634:     leaves: &[TreeLeaf],
635:     right: Vec3,
636:     up: Vec3,
637:     primary_mask: u8,
638:     secondary_group_range: Option<(u16, u16)>,
639:     source_group: u16,
640:     minimum_branch_depth: u8,
641: ) -> TreeBakeCard {
642:     let up = up.normalize();
643:     let right = (right - up * right.dot(up)).normalize_or_zero();
644:     let right = if right.length_squared() < 0.25 {
645:         Vec3::X
646:     } else {
647:         right
648:     };
649:     let probe = TreeBakeCard {
650:         center: Vec3::ZERO,
651:         right,
652:         up,
653:         width: 1.0,
654:         height: 1.0,
655:         primary_mask,
656:         secondary_group_range,
657:         source_group,
658:         minimum_branch_depth,
659:     };
660:     let mut min = Vec2::splat(f32::INFINITY);
661:     let mut max = Vec2::splat(f32::NEG_INFINITY);
662:     let normal = right.cross(up).normalize();
663:     let mut minimum_depth = f32::INFINITY;
664:     let mut maximum_depth = f32::NEG_INFINITY;
665:     for branch in branches
666:         .iter()
667:         .filter(|branch| probe.includes_branch(branch))
668:     {
669:         for point in [branch.start, branch.end] {
670:             let projected = Vec2::new(point.dot(right), point.dot(up));
671:             let radius = branch.start_radius.max(branch.end_radius);
672:             min = min.min(projected - Vec2::splat(radius));
673:             max = max.max(projected + Vec2::splat(radius));
674:             let depth = point.dot(normal);
675:             minimum_depth = minimum_depth.min(depth - radius);
676:             maximum_depth = maximum_depth.max(depth + radius);
677:         }
678:     }
679:     for leaf in leaves.iter().filter(|leaf| probe.includes_leaf(leaf)) {
680:         let radius = leaf.length.max(leaf.width) * 0.65;
681:         let projected = Vec2::new(leaf.center.dot(right), leaf.center.dot(up));
682:         min = min.min(projected - Vec2::splat(radius));
683:         max = max.max(projected + Vec2::splat(radius));
684:         let depth = leaf.center.dot(normal);
685:         minimum_depth = minimum_depth.min(depth - radius);
686:         maximum_depth = maximum_depth.max(depth + radius);
687:     }
688:     let margin = Vec2::splat(0.08) + (max - min) * 0.035;
689:     min -= margin;
690:     max += margin;
691:     let projected_center = (min + max) * 0.5;
692:     TreeBakeCard {
693:         center: right * projected_center.x
694:             + up * projected_center.y
695:             + normal * ((minimum_depth + maximum_depth) * 0.5),
696:         right,
697:         up,
698:         width: max.x - min.x,
699:         height: max.y - min.y,
700:         primary_mask,
701:         secondary_group_range,
702:         source_group,
703:         minimum_branch_depth,
704:     }
705: }
