707: pub(in crate::presentation) fn tree_source_geometry_hash(
708:     branches: &[TreeBranchSegment],
709:     leaves: &[TreeLeaf],
710: ) -> u64 {
711:     let mut hash = 0xcbf2_9ce4_8422_2325_u64;
712:     for value in branches.iter().flat_map(|branch| {
713:         [
714:             branch.start.x,
715:             branch.start.y,
716:             branch.start.z,
717:             branch.end.x,
718:             branch.end.y,
719:             branch.end.z,
720:             branch.start_radius,
721:             branch.end_radius,
722:         ]
723:     }) {
724:         hash ^= u64::from(value.to_bits());
725:         hash = hash.wrapping_mul(0x100_0000_01b3);
726:     }
727:     for leaf in leaves {
728:         for value in [
729:             leaf.petiole_start.x,
730:             leaf.petiole_start.y,
731:             leaf.petiole_start.z,
732:             leaf.center.x,
733:             leaf.center.y,
734:             leaf.center.z,
735:             leaf.length,
736:             leaf.width,
737:             leaf.shoot_id as f32,
738:         ] {
739:             hash ^= u64::from(value.to_bits());
740:             hash = hash.wrapping_mul(0x100_0000_01b3);
741:         }
742:     }
743:     hash
744: }
