766: pub(in crate::presentation) fn tree_lod_visibility(lod: u8) -> VisibilityRange {
767:     tree_projected_lod_visibility(lod, 1.0, 3.5)
768: }
769: 
770: pub(in crate::presentation) fn tree_projected_lod_visibility(
771:     lod: u8,
772:     focal_scale: f32,
773:     cluster_radius: f32,
774: ) -> VisibilityRange {
775:     let cluster_scale = (cluster_radius / 3.5).sqrt().clamp(0.65, 1.35);
776:     let transition = |index: usize| {
777:         // Dense real-world forest profiling showed that the prior ranges kept
778:         // tens of millions of live leaf vertices active after their detail
779:         // was no longer readable. Preserve overlap, but hand off one botanical
780:         // order earlier at every stage.
781:         let base = [6.0..8.0, 12.0..16.0, 24.0..32.0, 50.0..60.0][index].clone();
782:         let spatial_scale = if index < 3 { cluster_scale } else { 1.0 };
783:         (base.start * focal_scale * spatial_scale)..(base.end * focal_scale * spatial_scale)
784:     };
785:     let delayed_transition_out = |index: usize| {
786:         let handoff = transition(index);
787:         let width = handoff.end - handoff.start;
788:         handoff.end..(handoff.end + width)
789:     };
790:     let (start, end) = match lod {
791:         // Keep detailed clusters opaque while LOD1 dithers in, then retire
792:         // them over a trailing band. Complementary fading exposed a bare-tree
793:         // frame around seven metres on a cold first approach.
794:         0 => (0.0..0.0, delayed_transition_out(0)),
795:         // Keep the outgoing aggregate fully visible while the next one
796:         // dithers in, then fade it out over an equally wide trailing band.
797:         // The baked silhouettes are not pixel-identical, so exact
798:         // complementary dithering can otherwise expose crown holes.
799:         1 => (transition(0), delayed_transition_out(1)),
800:         2 => (transition(1), delayed_transition_out(2)),

801:         3 => (transition(2), delayed_transition_out(3)),
802:         4 => (transition(3), (190.0 * focal_scale)..(200.0 * focal_scale)),
803:         _ => unreachable!("tree LOD is bounded"),
804:     };
805:     VisibilityRange {
806:         start_margin: start,
807:         end_margin: end,
808:         // Every representation must measure from the same anchor. Using each
809:         // mesh AABB made a camera beside the trunk appear close to an
810:         // aggregate whole-tree mesh but far from every crown cluster. The
811:         // aggregate then hid before the detailed leaves became eligible,
812:         // producing a leafless tree. All tree LODs share the obstacle origin.
813:         use_aabb: false,
814:     }
815: }
816: 
817: pub(in crate::presentation) fn tree_leaf_visibility(
818:     representation: TreeLeafRepresentation,
819:     focal_scale: f32,
820:     cluster_radius: f32,
821: ) -> VisibilityRange {
822:     let cluster_scale = (cluster_radius / 3.5).sqrt().clamp(0.65, 1.35);
823:     let leaf_transition = (TREE_LEAF_HANDOFF_START * focal_scale * cluster_scale)
824:         ..(TREE_LEAF_HANDOFF_END * focal_scale * cluster_scale);
825:     let aggregate_transition =
826:         tree_projected_lod_visibility(0, focal_scale, cluster_radius).end_margin;
827:     let (start_margin, end_margin) = match representation {
828:         TreeLeafRepresentation::TexturedMesh => (0.0..0.0, leaf_transition.clone()),
829:         TreeLeafRepresentation::AlphaCard => (leaf_transition, aggregate_transition),
830:     };
831:     VisibilityRange {
832:         start_margin,
833:         end_margin,
834:         use_aabb: false,
835:     }
836: }
