838: pub(in crate::presentation) const TREE_TRUNK_HANDOFF_START: f32 = 12.0;
839: pub(in crate::presentation) const TREE_TRUNK_HANDOFF_END: f32 = 16.0;
840: 
841: /// Default close trunk/root range before projected-size adjustment.
842: pub(in crate::presentation) fn tree_trunk_visibility() -> VisibilityRange {
843:     tree_projected_trunk_visibility(false, 1.0)
844: }
845: 
846: /// Default low-poly mid-trunk range before projected-size adjustment.
847: pub(in crate::presentation) fn tree_mid_trunk_visibility() -> VisibilityRange {
848:     tree_projected_trunk_visibility(true, 1.0)
849: }
850: 
851: /// Keeps the two live trunk representations on the same obstacle-origin
852: /// distance metric. The mid trunk enters over 12..16 metres; the detailed root
853: /// mesh retires over the trailing 16..20 metre band. Mid then persists through
854: /// the existing LOD3-to-billboard tail.
855: pub(in crate::presentation) fn tree_projected_trunk_visibility(
856:     mid_distance: bool,
857:     focal_scale: f32,
858: ) -> VisibilityRange {
859:     let handoff = (TREE_TRUNK_HANDOFF_START * focal_scale)..(TREE_TRUNK_HANDOFF_END * focal_scale);
860:     let handoff_width = handoff.end - handoff.start;
861:     VisibilityRange {
862:         start_margin: if mid_distance {
863:             handoff.clone()
864:         } else {
865:             0.0..0.0
866:         },
867:         end_margin: if mid_distance {
868:             tree_projected_lod_visibility(3, focal_scale, 3.5).end_margin
869:         } else {
870:             // Do not complement-dither two non-identical trunk meshes. Keep
871:             // the detailed bole opaque while Mid enters, then retire it over
872:             // a trailing band so the supporting trunk cannot vanish.
873:             handoff.end..(handoff.end + handoff_width)
874:         },
875:         use_aabb: false,
876:     }
877: }
