253: fn baked_leaf_color(tint: Vec4, light: f32, style: TreeBakeStyle) -> [u8; 4] {
254:     // Vertex color RGB is semantic data, not an albedo tint: X/Y carry the
255:     // authored shade, Z selects a live directional self-shadow, and W carries
256:     // ambient visibility. The old bake accidentally treated XYZ as pigment,
257:     // producing lime cards and using the binary shadow selector as blue.
258:     let shade = ((tint.x + tint.y) * 0.5).clamp(0.0, 1.5);
259:     let canopy_visibility =
260:         1.0 + canopy_ao_strength(style.crown_radius_metres) * (tint.w.clamp(0.32, 1.0) - 1.0);
261:     let response = (shade * canopy_visibility * light).max(0.0);
262:     [
263:         (style.leaf_srgb[0] * response).min(255.0) as u8,
264:         (style.leaf_srgb[1] * response).min(255.0) as u8,
265:         (style.leaf_srgb[2] * response).min(255.0) as u8,
266:         255,
267:     ]
268: }
