270: pub(super) fn project_to_tile(card: TreeBakeCard, point: Vec3, tile_size: u32) -> Vec3 {
271:     let relative = point - card.center;
272:     Vec3::new(
273:         (relative.dot(card.right) / card.width + 0.5) * (tile_size - 1) as f32,
274:         (0.5 - relative.dot(card.up) / card.height) * (tile_size - 1) as f32,
275:         relative.dot(card.normal()),
276:     )
277: }
278: fn write_tree_pixel(sample: TreeRasterSample, target: &mut TreeRasterTarget<'_>) {
279:     let TreeRasterSample { x, y, depth, color } = sample;
280:     let TreeAtlasRegion {
281:         tile_size,
282:         atlas_width,
283:         atlas_height,
284:         tile_x,
285:         tile_y,
286:     } = target.region;
287:     let local_index = (y * tile_size + x) as usize;
288:     if depth <= target.depth[local_index] {
289:         return;
290:     }
291:     target.depth[local_index] = depth;
292:     let atlas_x = tile_x * tile_size + x;
293:     let atlas_y = tile_y * tile_size + y;
294:     debug_assert!(atlas_x < atlas_width && atlas_y < atlas_height);
295:     let index = ((atlas_y * atlas_width + atlas_x) * 4) as usize;
296:     target.pixels[index..index + 4].copy_from_slice(&color);
297: }
