314:     #[derive(Clone, Copy, Debug)]
315:     struct ProjectedCrownCoverage {
316:         occupied_fraction: f32,
317:         bounds: Vec4,
318:         silhouette_centroid: Vec2,
319:     }
320: 
321:     fn bounds_minimum(bounds: Vec4) -> Vec2 {
322:         Vec2::new(bounds.x, bounds.y)
323:     }
324: 
325:     fn bounds_maximum(bounds: Vec4) -> Vec2 {
326:         Vec2::new(bounds.z, bounds.w)
