328: 
329:     /// Measures the crown-space effect of a bake recipe without coupling the
330:     /// regression to a species' raw leaf count. A small projected grid is
331:     /// sufficient to catch both holes and loss of the source silhouette.
332:     fn projected_crown_coverage(
333:         card: TreeBakeCard,
334:         leaves: &[TreeLeaf],
335:         lod: u8,
336:         style: TreeBakeStyle,
337:     ) -> ProjectedCrownCoverage {
338:         const GRID: usize = 96;
339:         let (stride, scale) = if lod == 0 {
340:             (1, 1.0)
341:         } else {
342:             style.aggregate_leaf_recipe(lod)
343:         };
344:         let sampled = stratified_tree_bake_leaves(card, leaves, stride);
345:         let mut occupied = [false; GRID * GRID];
346:         let mut minimum = Vec2::splat(f32::INFINITY);
347:         let mut maximum = Vec2::splat(f32::NEG_INFINITY);
348: 
349:         for leaf in sampled {
350:             let half_right = leaf.right * leaf.width * scale * 0.5;
351:             let half_up = leaf.up * leaf.length * scale * 0.5;
352:             let projected = [
353:                 leaf.center - half_right - half_up,
354:                 leaf.center + half_right - half_up,
355:                 leaf.center - half_right + half_up,
356:                 leaf.center + half_right + half_up,
357:             ]
358:             .map(|point| {
359:                 let relative = point - card.center;
360:                 Vec2::new(

361:                     relative.dot(card.right) / card.width + 0.5,
362:                     0.5 - relative.dot(card.up) / card.height,
363:                 )
364:             });
365:             let leaf_minimum = projected
366:                 .into_iter()
367:                 .fold(Vec2::splat(f32::INFINITY), Vec2::min);
368:             let leaf_maximum = projected
369:                 .into_iter()
370:                 .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max);
371:             minimum = minimum.min(leaf_minimum);
372:             maximum = maximum.max(leaf_maximum);
373: 
374:             let grid_minimum = (leaf_minimum * GRID as f32)
375:                 .floor()
376:                 .clamp(Vec2::ZERO, Vec2::splat((GRID - 1) as f32));
377:             let grid_maximum = (leaf_maximum * GRID as f32)
378:                 .ceil()
379:                 .clamp(Vec2::ZERO, Vec2::splat((GRID - 1) as f32));
380:             for y in grid_minimum.y as usize..=grid_maximum.y as usize {
381:                 for x in grid_minimum.x as usize..=grid_maximum.x as usize {
382:                     occupied[y * GRID + x] = true;
383:                 }
384:             }
385:         }
386: 
387:         let (occupied_count, centroid_sum) = occupied.iter().enumerate().fold(
388:             (0_usize, Vec2::ZERO),
389:             |(count, sum), (index, cell)| {
390:                 if *cell {
391:                     let x = index % GRID;
392:                     let y = index / GRID;
393:                     (
394:                         count + 1,
395:                         sum + Vec2::new(x as f32 + 0.5, y as f32 + 0.5) / GRID as f32,
396:                     )
397:                 } else {
398:                     (count, sum)
399:                 }
400:             },
401:         );
402:         ProjectedCrownCoverage {
403:             occupied_fraction: occupied_count as f32 / (GRID * GRID) as f32,
404:             bounds: Vec4::new(minimum.x, minimum.y, maximum.x, maximum.y),
405:             silhouette_centroid: centroid_sum / occupied_count.max(1) as f32,
406:         }
407:     }
408: 
409:     fn coverage_from_mask(occupied: &[bool], grid: usize) -> ProjectedCrownCoverage {
410:         let mut count = 0_usize;
411:         let mut centroid_sum = Vec2::ZERO;
412:         let mut minimum = Vec2::splat(f32::INFINITY);
413:         let mut maximum = Vec2::splat(f32::NEG_INFINITY);
414:         for (index, cell) in occupied.iter().copied().enumerate() {
415:             if !cell {
416:                 continue;
417:             }
418:             let x = index % grid;
419:             let y = index / grid;
420:             let center = Vec2::new(x as f32 + 0.5, y as f32 + 0.5) / grid as f32;
421:             count += 1;
422:             centroid_sum += center;
423:             minimum = minimum.min(Vec2::new(x as f32, y as f32) / grid as f32);
424:             maximum = maximum.max(Vec2::new((x + 1) as f32, (y + 1) as f32) / grid as f32);
425:         }
426:         ProjectedCrownCoverage {
427:             occupied_fraction: count as f32 / (grid * grid) as f32,
428:             bounds: Vec4::new(minimum.x, minimum.y, maximum.x, maximum.y),
429:             silhouette_centroid: centroid_sum / count.max(1) as f32,
430:         }
431:     }
432: 
433:     fn projected_lod0_leaf_mesh_coverage(
434:         reference: TreeBakeCard,
435:         leaves: &[TreeLeaf],
436:     ) -> ProjectedCrownCoverage {
437:         const GRID: usize = 192;
438:         let mesh = procedural_woody_cambered_leaf_mesh(leaves);
439:         let positions = mesh
440:             .attribute(Mesh::ATTRIBUTE_POSITION)
441:             .and_then(VertexAttributeValues::as_float3)
442:             .expect("procedural leaf mesh has float positions");
443:         let Indices::U32(indices) = mesh.indices().expect("procedural leaf mesh is indexed") else {
444:             unreachable!("procedural leaf mesh uses u32 indices")
445:         };
446:         let mut occupied = vec![false; GRID * GRID];
447:         for triangle in indices.as_chunks::<3>().0 {
448:             let projected = [triangle[0], triangle[1], triangle[2]].map(|index| {
449:                 let relative = Vec3::from_array(positions[index as usize]) - reference.center;
450:                 Vec2::new(
451:                     relative.dot(reference.right) / reference.width + 0.5,
452:                     0.5 - relative.dot(reference.up) / reference.height,
453:                 ) * GRID as f32
454:             });
455:             let [a, b, c] = projected;
456:             let denominator = (b - a).perp_dot(c - a);
457:             if denominator.abs() < 0.0001 {
458:                 continue;
459:             }
460:             let minimum = a
461:                 .min(b)
462:                 .min(c)
463:                 .floor()
464:                 .clamp(Vec2::ZERO, Vec2::splat((GRID - 1) as f32));
465:             let maximum = a
466:                 .max(b)
467:                 .max(c)
468:                 .ceil()
469:                 .clamp(Vec2::ZERO, Vec2::splat((GRID - 1) as f32));
470:             for y in minimum.y as usize..=maximum.y as usize {
471:                 for x in minimum.x as usize..=maximum.x as usize {
472:                     let sample = Vec2::new(x as f32 + 0.5, y as f32 + 0.5);
473:                     let weight_b = (sample - a).perp_dot(c - a) / denominator;
474:                     let weight_c = (b - a).perp_dot(sample - a) / denominator;
475:                     let weight_a = 1.0 - weight_b - weight_c;
476:                     if weight_a >= -0.001 && weight_b >= -0.001 && weight_c >= -0.001 {
477:                         occupied[y * GRID + x] = true;
478:                     }
479:                 }
480:             }
481:         }
482:         coverage_from_mask(&occupied, GRID)
483:     }
484: 
485:     fn projected_lod1_raster_alpha_coverage(
486:         reference: TreeBakeCard,
487:         cards: &[TreeBakeCard],
488:         branches: &[TreeBranchSegment],
489:         leaves: &[TreeLeaf],
490:         style: TreeBakeStyle,
491:     ) -> ProjectedCrownCoverage {
492:         const GRID: usize = 192;
493:         const TILE: u32 = 96;
494:         const ALPHA_DISCARD: u8 = 51; // shader cutoff 0.2
495:         let mut tile_alpha = Vec::with_capacity(cards.len());
496:         for card in cards.iter().copied() {
497:             let mut pixels = vec![0_u8; (TILE * TILE * 4) as usize];
498:             render_tree_card(
499:                 card,
500:                 branches,
501:                 leaves,
502:                 1,
503:                 TreeAtlasRegion {
504:                     tile_size: TILE,
505:                     atlas_width: TILE,
506:                     atlas_height: TILE,
507:                     tile_x: 0,
508:                     tile_y: 0,
509:                 },
510:                 &mut pixels,
511:                 style,
512:             );
513:             tile_alpha.push(
514:                 pixels
515:                     .as_chunks::<4>()
516:                     .0
517:                     .iter()
518:                     .map(|pixel| pixel[3])
519:                     .collect::<Vec<_>>(),
520:             );
521:         }
522: 
523:         let view_normal = reference.normal();
524:         let mut occupied = vec![false; GRID * GRID];
525:         for y in 0..GRID {
526:             for x in 0..GRID {
527:                 let screen = reference.center
528:                     + reference.right * (((x as f32 + 0.5) / GRID as f32 - 0.5) * reference.width)
529:                     + reference.up * ((0.5 - (y as f32 + 0.5) / GRID as f32) * reference.height);
530:                 for (card, alpha) in cards.iter().zip(&tile_alpha) {
531:                     let normal = card.normal();
532:                     let denominator = view_normal.dot(normal);
533:                     if denominator.abs() < 0.0001 {
534:                         continue;
535:                     }
536:                     let point =
537:                         screen + view_normal * ((card.center - screen).dot(normal) / denominator);
538:                     let relative = point - card.center;
539:                     let uv = Vec2::new(
540:                         relative.dot(card.right) / (card.width * style.lod1_runtime_width_scale)
541:                             + 0.5,
542:                         0.5 - relative.dot(card.up) / card.height,
543:                     );
544:                     if !(0.0..=1.0).contains(&uv.x) || !(0.0..=1.0).contains(&uv.y) {
545:                         continue;
546:                     }
547:                     let tx = (uv.x * TILE as f32).floor().min((TILE - 1) as f32) as usize;
548:                     let ty = (uv.y * TILE as f32).floor().min((TILE - 1) as f32) as usize;
549:                     if alpha[ty * TILE as usize + tx] >= ALPHA_DISCARD {
550:                         occupied[y * GRID + x] = true;
551:                         break;
552:                     }
553:                 }
554:             }
555:         }
556:         coverage_from_mask(&occupied, GRID)
557:     }
