559:     fn assert_aggregate_crown_continuity(
560:         card: TreeBakeCard,

561:         leaves: &[TreeLeaf],
562:         style: TreeBakeStyle,
563:     ) {
564:         let source = projected_crown_coverage(card, leaves, 0, style);
565:         let source_extent = bounds_maximum(source.bounds) - bounds_minimum(source.bounds);
566:         let mut previous = source;
567:         for lod in 1..=4 {
568:             let aggregate = projected_crown_coverage(card, leaves, lod, style);
569:             let coverage_ratio = aggregate.occupied_fraction / source.occupied_fraction;
570:             assert!(
571:                 (0.72..=1.20).contains(&coverage_ratio),
572:                 "LOD {lod} projected occupancy ratio {coverage_ratio:.3} left the source crown envelope"
573:             );
574:             let adjacent_ratio = aggregate.occupied_fraction / previous.occupied_fraction;
575:             assert!(
576:                 (0.78..=1.22).contains(&adjacent_ratio),
577:                 "LOD {lod} projected occupancy jumped {adjacent_ratio:.3} across its handoff"
578:             );
579:             let extent = bounds_maximum(aggregate.bounds) - bounds_minimum(aggregate.bounds);
580:             let extent_ratio = extent / source_extent;
581:             assert!(
582:                 extent_ratio.cmpge(Vec2::splat(0.88)).all()
583:                     && extent_ratio.cmple(Vec2::splat(1.15)).all(),
584:                 "LOD {lod} projected crown extent {extent_ratio:?} diverged from its source"
585:             );
586:             previous = aggregate;
587:         }
588:     }
589: 
590:     fn projected_lod1_runtime_coverage(
591:         reference: TreeBakeCard,
592:         cards: &[TreeBakeCard],
593:         leaves: &[TreeLeaf],
594:         style: TreeBakeStyle,
595:     ) -> ProjectedCrownCoverage {
596:         let (stride, scale) = style.aggregate_leaf_recipe(1);
597:         let mut flattened = Vec::new();
598:         for card in cards {
599:             for mut leaf in stratified_tree_bake_leaves(*card, leaves, stride) {
600:                 let relative = leaf.center - card.center;
601:                 leaf.center = card.center
602:                     + card.right * relative.dot(card.right) * style.lod1_runtime_width_scale
603:                     + card.up * relative.dot(card.up);
604:                 leaf.right =
605:                     card.right * leaf.right.dot(card.right) * style.lod1_runtime_width_scale
606:                         + card.up * leaf.right.dot(card.up);
607:                 leaf.up = card.right * leaf.up.dot(card.right) + card.up * leaf.up.dot(card.up);
608:                 leaf.length *= scale;
609:                 leaf.width *= scale;
610:                 flattened.push(leaf);
611:             }
612:         }
613:         projected_crown_coverage(reference, &flattened, 0, style)
614:     }
