616:     fn assert_lod1_runtime_transition_preserves_source_crown(
617:         seed: Seed,
618:         branches: &[TreeBranchSegment],
619:         leaves: &[TreeLeaf],
620:         style: TreeBakeStyle,
621:     ) {
622:         let reference = tree_bake_cards_with_style(seed, branches, leaves, 4, style)[0];
623:         let source = projected_crown_coverage(reference, leaves, 0, style);
624:         let lod1_cards = tree_bake_cards_with_style(seed, branches, leaves, 1, style);
625:         let aggregate = projected_lod1_runtime_coverage(reference, &lod1_cards, leaves, style);
626:         let occupancy_ratio = aggregate.occupied_fraction / source.occupied_fraction;
627:         assert!(
628:             (0.70..=1.18).contains(&occupancy_ratio),
629:             "LOD1 runtime occupancy ratio {occupancy_ratio:.3} diverged from high detail"
630:         );
631:         let source_extent = bounds_maximum(source.bounds) - bounds_minimum(source.bounds);
632:         let aggregate_extent = bounds_maximum(aggregate.bounds) - bounds_minimum(aggregate.bounds);
633:         let extent_ratio = aggregate_extent / source_extent;
634:         assert!(
635:             extent_ratio.cmpge(Vec2::splat(0.88)).all()
636:                 && extent_ratio.cmple(Vec2::splat(1.15)).all(),
637:             "LOD1 runtime crown extent {extent_ratio:?} diverged from high detail"
638:         );
639:         let center_shift = (bounds_minimum(aggregate.bounds) + bounds_maximum(aggregate.bounds)
640:             - bounds_minimum(source.bounds)
641:             - bounds_maximum(source.bounds))
642:             * 0.5;
643:         assert!(
644:             center_shift.abs().cmple(Vec2::splat(0.06)).all(),
645:             "LOD1 runtime crown center shifted {center_shift:?} from high detail"
646:         );
647:     }
