71: #[expect(
72:     clippy::type_complexity,
73:     reason = "the Bevy queries encode the exact tree representation markers controlled by projected LOD"
74: )]
75: pub(in crate::presentation) fn update_tree_projected_lod_ranges(
76:     cameras: Query<(&Camera, &Projection), With<TacticalGameplayCamera>>,
77:     lod_override: Res<TreeLodRenderOverride>,
78:     isolation: Res<TacticalTreeBenchmarkIsolation>,
79:     mut lods: Query<(
80:         &TreeLod,
81:         Option<&TreeLodCluster>,
82:         Option<&TreeLeafRepresentation>,
83:         Has<PlayableTreeDetailedLeaves>,
84:         Has<PlayableTreeDetailedWood>,
85:         Has<PlayableTreeAggregateWood>,
86:         Has<PlayableTreeBuds>,
87:         Has<PlayableTreeCanopyCard>,
88:         &mut VisibilityRange,
89:         &mut Visibility,
90:     )>,
91:     mut trunks: Query<
92:         (
93:             Has<PlayableTreeMidTrunk>,
94:             &mut VisibilityRange,
95:             &mut Visibility,
96:         ),
97:         (
98:             With<TreeTrunkLod>,
99:             With<PlayableTreeTrunk>,
100:             Without<TreeLod>,
101:         ),
102:     >,
103: ) {
104:     let Ok((camera, projection)) = cameras.single() else {
105:         return;
106:     };
107:     let viewport_height = camera
108:         .physical_viewport_size()
109:         .map_or(720.0, |size| size.y as f32);
110:     let reference_focal = 720.0 / (2.0 * (80.0_f32.to_radians() * 0.5).tan());
111:     let focal = match projection {
112:         Projection::Perspective(perspective) => {
113:             viewport_height / (2.0 * (perspective.fov * 0.5).tan())
114:         }
115:         _ => reference_focal,
116:     };
117:     let focal_scale =
118:         (focal / reference_focal * lod_override.projected_scale.unwrap_or(1.0)).clamp(0.25, 4.0);
119:     for (
120:         lod,
121:         cluster,
122:         leaf_representation,
123:         detailed_leaves,
124:         detailed_wood,
125:         aggregate_wood,
126:         buds,
127:         canopy_card,
128:         mut range,
129:         mut visibility,
130:     ) in &mut lods
131:     {
132:         let (next_range, next_visibility) = if let Some(forced_lod) = lod_override.lod {
133:             let selected_leaf = match (leaf_representation, lod_override.leaf) {
134:                 (
135:                     Some(TreeLeafRepresentation::TexturedMesh),
136:                     None | Some(TreeLeafRepresentation::TexturedMesh),
137:                 ) => true,
138:                 (
139:                     Some(TreeLeafRepresentation::AlphaCard),
140:                     Some(TreeLeafRepresentation::AlphaCard),
141:                 ) => true,
142:                 (Some(_), _) => false,
143:                 (None, _) => true,
144:             };
145:             (
146:                 VisibilityRange::abrupt(0.0, f32::MAX),
147:                 if lod.0 == forced_lod && selected_leaf {
148:                     Visibility::Inherited
149:                 } else {
150:                     Visibility::Hidden
151:                 },
152:             )
153:         } else {
154:             let radius = cluster.map_or(3.5, |cluster| {
155:                 debug_assert!(cluster.center.is_finite());
156:                 debug_assert!(cluster.primary_group < TREE_PRIMARY_GROUP_COUNT);
157:                 cluster.radius
158:             });
159:             (
160:                 match leaf_representation {
161:                     Some(TreeLeafRepresentation::TexturedMesh) => tree_leaf_visibility(
162:                         TreeLeafRepresentation::TexturedMesh,
163:                         focal_scale,
164:                         radius,
165:                     ),
166:                     Some(TreeLeafRepresentation::AlphaCard) => {
167:                         tree_leaf_visibility(TreeLeafRepresentation::AlphaCard, focal_scale, radius)
168:                     }
169:                     None => tree_projected_lod_visibility(lod.0, focal_scale, radius),
170:                 },
171:                 Visibility::Inherited,
172:             )
173:         };
174:         let isolated = (isolation.hide_detailed_leaves && detailed_leaves)
175:             || (isolation.hide_canopy_cards && canopy_card)
176:             || (isolation.hide_buds && buds)
177:             || (isolation.hide_branches && (detailed_wood || aggregate_wood));
178:         let next_visibility = if isolated {
179:             Visibility::Hidden
180:         } else {
181:             next_visibility
182:         };
183:         if *range != next_range {
184:             *range = next_range;
185:         }
186:         if *visibility != next_visibility {
187:             *visibility = next_visibility;
188:         }
189:     }
190:     for (mid_trunk, mut range, mut visibility) in &mut trunks {
191:         let (next_range, next_visibility) = if let Some(forced_lod) = lod_override.lod {
192:             (
193:                 VisibilityRange::abrupt(0.0, f32::MAX),
194:                 if forced_lod < 4 {
195:                     Visibility::Inherited
196:                 } else {
197:                     Visibility::Hidden
198:                 },
199:             )
200:         } else {
201:             (
202:                 super::impostor::tree_projected_trunk_visibility(mid_trunk, focal_scale),
203:                 Visibility::Inherited,
204:             )
205:         };

206:         let next_visibility = if isolation.hide_trunks {
207:             Visibility::Hidden
208:         } else {
209:             next_visibility
210:         };
211:         if *range != next_range {
212:             *range = next_range;
213:         }
214:         if *visibility != next_visibility {
215:             *visibility = next_visibility;
216:         }
217:     }
218: }
