602:             cached,
603:             1,
604:             prepared,
605:             meshes,
606:             tree_materials,
607:             images,
608:             diagnostics,
609:         );
610:         ensure_detailed_tree_assets_resident(cached, selected_leaf, meshes, diagnostics);
611:     }
612:     for lod in 1..=4 {
613:         if mask & (1 << (lod + 1)) == 0 {
614:             continue;
615:         }
616:         ensure_tree_card_resident(
617:             cached,
618:             lod,
619:             prepared,
620:             meshes,
621:             tree_materials,
622:             images,
623:             diagnostics,
624:         );
625:         if lod <= 2 && cached.aggregate_branch_meshes[lod as usize - 1].is_none() {
626:             let (depth, quality) = if lod == 1 {
627:                 (2, WoodyBranchMeshQuality::AggregateLod1)
628:             } else {
629:                 (1, WoodyBranchMeshQuality::AggregateLod2)
630:             };
631:             let mesh = procedural_woody_crown_mesh(&cached.branches, depth, quality);
632:             let aggregate_index = lod as usize - 1;
633:             let vertices = mesh.count_vertices();
634:             let triangles = mesh
635:                 .indices()
636:                 .expect("aggregate branch mesh is indexed")
637:                 .len()
638:                 / 3;
639:             diagnostics.aggregate_branch_vertices += vertices;
640:             diagnostics.aggregate_branch_vertices_by_lod[aggregate_index] += vertices;
641:             diagnostics.aggregate_branch_triangles_by_lod[aggregate_index] += triangles;
642:             cached.aggregate_branch_meshes[lod as usize - 1] = Some(meshes.add(mesh));
643:         }
644:     }
645:     let elapsed = started.elapsed().as_millis();
646:     diagnostics.generation_milliseconds += elapsed;
647:     if elapsed > 0 {
648:         info!(
649:             species = cached.species_name,
650:             requested_mask = mask,
651:             elapsed_ms = elapsed,
652:             resident_mask =
653:                 cached.resident_assets.generated_lod_mask | diagnostics.generated_lod_mask,
654:             "Generated demand-driven tactical tree assets"
655:         );
656:     }
657: }
