659: #[expect(
660:     clippy::too_many_arguments,
661:     reason = "Bevy injects tree streaming state and each independently borrowed asset store as system parameters"
662: )]
663: pub(in crate::presentation) fn stream_tree_lod_children(
664:     mut commands: Commands,
665:     camera: Single<(&GlobalTransform, &Projection), With<TacticalGameplayCamera>>,
666:     lod_override: Res<TreeLodRenderOverride>,
667:     mut trees: Query<(Entity, &GlobalTransform, &mut StreamedTreePresentation)>,
668:     mut meshes: ResMut<Assets<Mesh>>,
669:     mut tree_materials: ResMut<Assets<TacticalTreeImpostorMaterial>>,
670:     mut images: ResMut<Assets<Image>>,
671:     mut tree_cache: ResMut<TreePresentationCache>,
672:     mut residency: ResMut<TreeAssetResidencyDiagnostics>,
673:     prepared: PreparedTreeImpostors,
674: ) {
675:     let focal_scale = match camera.1 {
676:         Projection::Perspective(projection) => {
677:             (80.0_f32.to_radians() * 0.5).tan() / (projection.fov * 0.5).tan()
678:         }
679:         _ => 1.0,
680:     } * lod_override.projected_scale.unwrap_or(1.0);
681:     for (entity, transform, mut presentation) in &mut trees {
682:         let distance = camera.0.translation().distance(transform.translation());
683:         let scaled = distance / focal_scale.max(0.25);
684:         let mask = if let Some(lod) = lod_override.lod {
685:             (1 << (lod + 1)) | u8::from(lod < 4)
686:         } else {
687:             tree_streaming_mask(scaled)
688:         };
689:         let selected_leaf = lod_override
690:             .leaf
691:             .or_else(|| tree_streamed_leaf_representation(scaled));
692:         if presentation.active_mask == mask && presentation.active_leaf == selected_leaf {
693:             continue;
694:         }
695:         debug!(
696:             distance,
697:             scaled_distance = scaled,
698:             requested_mask = mask,
699:             ?selected_leaf,
700:             "Changed streamed tactical tree residency"
701:         );
702:         let cached = tree_cache
703:             .variants
704:             .get_mut(&presentation.cache_key)
705:             .expect("streamed tree cache entry remains resident");
706:         let prepared = prepared.get();
707:         ensure_tree_assets_resident(
708:             cached,
709:             mask,
710:             selected_leaf,
711:             prepared,
712:             &mut meshes,
713:             &mut tree_materials,
714:             &mut images,
715:             &mut residency,
716:         );
717:         let desired_leaf_mask = if mask & (1 << 1) == 0 {
718:             0
719:         } else {
720:             match selected_leaf {
721:                 Some(TreeLeafRepresentation::TexturedMesh) => 1,
722:                 Some(TreeLeafRepresentation::AlphaCard) => 2,
723:                 None => 3,
724:             }
725:         };
726:         let new_mask = mask & !presentation.resident_mask;
727:         let new_leaf_mask = desired_leaf_mask & !presentation.resident_leaf_mask;
728:         spawn_streamed_tree_children(&mut commands, entity, cached, new_mask, new_leaf_mask);
729:         presentation.resident_mask |= new_mask;
730:         presentation.resident_leaf_mask |= new_leaf_mask;
731:         presentation.active_mask = mask;
732:         presentation.active_leaf = selected_leaf;
733:     }
734: }
735: 
736: fn tree_streamed_leaf_representation(scaled_distance: f32) -> Option<TreeLeafRepresentation> {
737:     // Keep residency decisions on the same projected-scale-aware base band as
738:     // tree_leaf_visibility. The cluster-specific visibility range may widen
739:     // this overlap, but it must never request a representation after its
740:     // corresponding visibility range has become active.
741:     if scaled_distance < TREE_LEAF_HANDOFF_START {
742:         Some(TreeLeafRepresentation::TexturedMesh)
743:     } else if scaled_distance > TREE_LEAF_HANDOFF_END {
744:         Some(TreeLeafRepresentation::AlphaCard)
745:     } else {
746:         None
747:     }
748: }
749: 
750: fn tree_streaming_mask(scaled_distance: f32) -> u8 {
751:     // Generate each incoming crown tier one full outgoing LOD band before it
752:     // becomes visible. Mesh/material insertion is asynchronous in the render
753:     // world: the old four-metre lead could leave only the already-resident
754:     // trunk on a first approach, while a second approach was correct because
755:     // the crown assets remained cached. This changes when eventual residency
756:     // is paid, not which tiers are drawn or retained.
757:     u8::from(scaled_distance < 75.0)
758:         | (u8::from(scaled_distance < 24.0) << 1)
759:         | (u8::from((3.0..44.0).contains(&scaled_distance)) << 2)
760:         | (u8::from((8.0..75.0).contains(&scaled_distance)) << 3)
761:         | (u8::from((18.0..100.0).contains(&scaled_distance)) << 4)
762:         | (u8::from((40.0..220.0).contains(&scaled_distance)) << 5)
763: }
764: 
765: fn tree_cluster_aabb(center: Vec3, radius: f32) -> Aabb {
766:     let extent = Vec3::splat(radius.max(0.01));
767:     Aabb::from_min_max(center - extent, center + extent)
768: }
