774: pub(in crate::presentation) fn ensure_vista_tree_variant(
775:     variant_seed: Seed,
776:     competition: f32,
777:     species: TreePresentationSpecies,
778:     meshes: &mut Assets<Mesh>,
779:     tree_materials: &mut Assets<TacticalTreeImpostorMaterial>,
780:     images: &mut Assets<Image>,
781:     cache: &mut VistaTreePresentationCache,
782:     prepared: Option<&PreparedTreeImpostorAsset>,
783: ) -> CachedVistaTreePresentation {
784:     let competition_key = (competition * 4095.0).round() as u64;
785:     let cache_key = StreamId::new("visual.tree.vista-cache-key")
786:         .seed(variant_seed, &[competition_key, species.cache_salt()]);
787:     if let Some(cached) = cache.variants.get(&cache_key) {
788:         return cached.clone();
789:     }
790:     let (branches, leaves) = vista_tree_source(variant_seed, competition, species);
791:     let bake = if let Some(prepared) = prepared {
792:         prepared
793:             .resolve(PreparedTreeImpostorUsage::Vista, species, variant_seed, 4)
794:             .unwrap_or_else(|| {
795:                 panic!("prepared tree impostors do not match the requested vista tree")
796:             })
797:     } else if species == TreePresentationSpecies::EnglishOak {
798:         bake_tree_lod(variant_seed, &branches, &leaves, 4)
799:     } else {
800:         bake_tree_lod_with_style(variant_seed, &branches, &leaves, 4, species.bake_style())

801:     };
802:     validate_tree_bake_provenance(&bake.provenance);
803:     let texture = images.add(bake.image.clone());
804:     let cached = CachedVistaTreePresentation {
805:         mesh: meshes.add(bake.mesh),
806:         material: tree_materials.add(tree_impostor_material(variant_seed, 4, texture)),
807:         provenance: bake.provenance,
808:     };
809:     cache.variants.insert(cache_key, cached.clone());
810:     cached
811: }
