817: pub(in crate::presentation) fn present_pending_trees(
818:     mut commands: Commands,
819:     pending: Query<(Entity, &Transform), With<PendingTreePresentation>>,
820:     active: Res<ActiveTacticalScene>,
821:     environments: Query<&SceneEnvironment>,
822:     terrains: Query<&SceneTerrain>,
823:     mut materials: ResMut<Assets<StandardMaterial>>,
824:     mut bark_materials: ResMut<Assets<TacticalTreeBarkMaterial>>,
825:     mut aggregate_bark_materials: ResMut<Assets<TacticalTreeAggregateBarkMaterial>>,
826:     mut leaf_card_materials: ResMut<Assets<TacticalTreeLeafCardMaterial>>,
827:     mut images: ResMut<Assets<Image>>,
828:     mut tree_cache: ResMut<TreePresentationCache>,
829:     mut retained: ResMut<RetainedTreePresentations>,
830:     mut residency: ResMut<TreeAssetResidencyDiagnostics>,
831:     procedural_assets: Res<ProceduralTextureAssets>,
832: ) {
833:     let Some(environment) = active
834:         .entity
835:         .and_then(|entity| environments.get(entity).ok())
836:     else {
837:         return;
838:     };
839:     let Some(terrain) = active.entity.and_then(|entity| terrains.get(entity).ok()) else {
840:         return;
841:     };
842:     if let Err(error) = retained.activate(
843:         environment,
844:         terrain,
845:         &mut tree_cache,
846:         &mut residency,
847:         &mut images,
848:     ) {
849:         warn!(%error, "Tree contact heightmap rejected");
850:         return;
851:     }
852:     let Some(terrain_contact) = tree_cache.terrain_contact.clone() else {
853:         return;
854:     };
855:     let competition = canopy_competition(environment.canopy_bps);
856:     let site_key = oak_site_key(environment);
857:     let mut bark_binding = TerrainBarkBinding {
858:         procedural_assets: &procedural_assets,
859:         contact: &terrain_contact,
860:         terrain,
861:         materials: &mut bark_materials,
862:     };
863:     for (entity, transform) in &pending {
864:         let started = web_time::Instant::now();
865:         info!("Generating playable tactical tree presentation");
866:         let Some(point) = ScenePlanPoint::from_metres(transform.translation.xz()) else {
867:             warn!("Tree presentation has a nonfinite scene footprint");
868:             continue;
869:         };
870:         let species = tree_species_for_site(point, environment);
871:         let (variant_index, variant_seed) = super::specimen::oak_variant_for_site(point);
872:         let competition_key = (competition * 4095.0).round() as u64;
873:         let cache_key = StreamId::new("visual.tree.playable-cache-key").seed(
874:             variant_seed,
875:             &[competition_key, site_key, species.cache_salt()],
876:         );
877:         retained.restore_variant(
878:             cache_key,
879:             &mut tree_cache,
880:             &mut residency,
881:             species,
882:             &mut bark_binding,
883:         );
884:         if !tree_cache.variants.contains_key(&cache_key) {
885:             let (branches, leaves) = playable_tree_source(
886:                 species,
887:                 variant_seed,
888:                 variant_index,
889:                 competition,
890:                 environment,
891:             );
892:             info!(
893:                 elapsed_ms = started.elapsed().as_millis(),
894:                 branches = branches.len(),
895:                 leaves = leaves.len(),
896:                 "Generated playable tactical tree source geometry"
897:             );
898:             let bark_material = tree_cache.bark_for_terrain(species, &mut bark_binding);
899:             let aggregate_bark_material = match species {
900:                 TreePresentationSpecies::EnglishOak => tree_cache
901:                     .oak_aggregate_bark_material
902:                     .clone()
903:                     .unwrap_or_else(|| {
904:                         let material = aggregate_bark_materials.add(oak_aggregate_bark_material());
905:                         tree_cache.oak_aggregate_bark_material = Some(material.clone());
906:                         material
907:                     }),
908:                 TreePresentationSpecies::CommonBeech => tree_cache
909:                     .beech_aggregate_bark_material
910:                     .clone()
911:                     .unwrap_or_else(|| {
912:                         let material =
913:                             aggregate_bark_materials.add(beech_aggregate_bark_material());
914:                         tree_cache.beech_aggregate_bark_material = Some(material.clone());
915:                         material
916:                     }),
917:             };
918:             let leaf_material = leaf_card_materials.add(match species {
919:                 TreePresentationSpecies::EnglishOak => oak_leaf_material(&procedural_assets),
920:                 TreePresentationSpecies::CommonBeech => beech_leaf_material(&procedural_assets),
921:             });
922:             let bud_material = materials.add(StandardMaterial {
923:                 base_color: match species {
924:                     TreePresentationSpecies::EnglishOak => Color::srgb(0.36, 0.27, 0.1),
925:                     TreePresentationSpecies::CommonBeech => Color::srgb_u8(112, 68, 43),
926:                 },
927:                 perceptual_roughness: 0.92,
928:                 ..default()
929:             });
930:             let mut cached = CachedTreePresentation {
931:                 variant_seed,
932:                 species,
933:                 species_name: species.name(),
934:                 branches: branches.into(),
935:                 leaves: leaves.into(),
936:                 trunk_mesh: None,
937:                 mid_trunk_mesh: None,
938:                 cluster_layout: None,
939:                 clusters: None,
940:                 aggregate_branch_meshes: [None, None],
941:                 lod_cards: [None, None, None, None],
942:                 bark_material,
943:                 aggregate_bark_material,
944:                 leaf_material,
945:                 bud_material,
946:                 resident_assets: TreeAssetResidencyDiagnostics::default(),
947:             };
948:             cached.resident_assets.variants = 1;
949:             cached.resident_assets.source_branches = cached.branches.len();
950:             cached.resident_assets.source_leaves = cached.leaves.len();
951:             residency.add_resident_assets(&cached.resident_assets);
952:             tree_cache.variants.insert(cache_key, cached);
953:         }
954:         spawn_cached_tree(&mut commands, entity, cache_key, species);
955:         info!(
956:             elapsed_ms = started.elapsed().as_millis(),
957:             "Generated playable tactical tree presentation"
958:         );
959:         commands.entity(entity).remove::<PendingTreePresentation>();
960:     }
961:     retained.update_diagnostics(&tree_cache, &mut residency);
962: }
