1: //! Retain terrain bindings and share matching plant assets across scenes.
2: use super::*;
3: use crate::presentation::terrain::{TerrainContactHeightmap, TerrainHeightmapResult};
4: use adventuresim_tactical_core::scene::SceneElevationRange;
5: use std::collections::VecDeque;
6: 
7: // Active scene plus two previous scenes bounds retained geometry and atlases.
8: const PREVIOUS_TREE_SCENES: usize = 2;
9: 
10: #[derive(Resource, Default)]
11: pub(in crate::presentation) struct RetainedTreePresentations {
12:     scenes: VecDeque<RetainedScene>,
13: }
14: 
15: #[derive(Clone)]
16: pub(super) struct CachedTerrainContactHeightmap {
17:     scene_digest: String,
18:     image: Handle<Image>,
19:     range: SceneElevationRange,
20: }
21: 
22: pub(super) struct TerrainBarkBinding<'a> {
23:     pub(super) procedural_assets: &'a ProceduralTextureAssets,
24:     pub(super) contact: &'a CachedTerrainContactHeightmap,
25:     pub(super) terrain: &'a SceneTerrain,
26:     pub(super) materials: &'a mut Assets<TacticalTreeBarkMaterial>,
27: }
28: 
29: struct RetainedScene {
30:     cache: TreePresentationCache,
31:     diagnostics: TreeAssetResidencyDiagnostics,
32: }
33: 
34: impl TreePresentationCache {
35:     pub(super) fn bark_for_terrain(
36:         &mut self,
37:         species: TreePresentationSpecies,
38:         binding: &mut TerrainBarkBinding<'_>,
39:     ) -> Handle<TacticalTreeBarkMaterial> {
40:         match species {
41:             TreePresentationSpecies::EnglishOak => {
42:                 self.oak_bark_material.clone().unwrap_or_else(|| {
43:                     let material = binding.materials.add(oak_bark_material(
44:                         binding.procedural_assets,
45:                         binding.contact.image.clone(),
46:                         binding.contact.range,
47:                         binding.terrain,
48:                     ));
49:                     self.oak_bark_material = Some(material.clone());
50:                     material
51:                 })
52:             }
53:             TreePresentationSpecies::CommonBeech => {
54:                 self.beech_bark_material.clone().unwrap_or_else(|| {
55:                     let material = binding.materials.add(beech_bark_material(
56:                         binding.procedural_assets,
57:                         binding.contact.image.clone(),
58:                         binding.contact.range,
59:                         binding.terrain,
60:                     ));
61:                     self.beech_bark_material = Some(material.clone());
62:                     material
63:                 })
64:             }
65:         }
66:     }
67: }
68: 
69: impl RetainedTreePresentations {
70:     pub(super) fn activate(
71:         &mut self,
72:         environment: &SceneEnvironment,
73:         terrain: &SceneTerrain,
74:         cache: &mut TreePresentationCache,
75:         diagnostics: &mut TreeAssetResidencyDiagnostics,
76:         images: &mut Assets<Image>,
77:     ) -> TerrainHeightmapResult<()> {
78:         if cache
79:             .terrain_contact
80:             .as_ref()
81:             .is_some_and(|contact| contact.scene_digest == environment.scene_digest)
82:         {
83:             return Ok(());
84:         }
85:         let restored = self
86:             .scenes
87:             .iter()
88:             .position(|scene| {
89:                 scene
90:                     .cache
91:                     .terrain_contact
92:                     .as_ref()
93:                     .is_some_and(|contact| contact.scene_digest == environment.scene_digest)
94:             })
95:             .and_then(|index| self.scenes.remove(index));
96:         let next = match restored {
97:             Some(restored) => restored,
98:             None => {
99:                 let contact = TerrainContactHeightmap::from_terrain(terrain)?;
100:                 let range = contact.range();
101:                 RetainedScene {
102:                     cache: TreePresentationCache {
103:                         terrain_contact: Some(CachedTerrainContactHeightmap {
104:                             scene_digest: environment.scene_digest.clone(),
105:                             image: images.add(contact.into_image()),
106:                             range,
107:                         }),
108:                         ..default()
109:                     },
110:                     diagnostics: default(),
111:                 }
112:             }
113:         };
114:         if cache.terrain_contact.is_some() {
115:             self.scenes.push_back(RetainedScene {
116:                 cache: std::mem::take(cache),
117:                 diagnostics: std::mem::take(diagnostics),
118:             });
119:         }
120:         while self.scenes.len() > PREVIOUS_TREE_SCENES {
121:             self.scenes.pop_front();
122:         }
123:         *cache = next.cache;
124:         *diagnostics = next.diagnostics;
125:         self.update_diagnostics(cache, diagnostics);
126:         Ok(())
127:     }
128: 
129:     pub(super) fn restore_variant(
130:         &self,
131:         key: Seed,
132:         cache: &mut TreePresentationCache,
133:         diagnostics: &mut TreeAssetResidencyDiagnostics,
134:         species: TreePresentationSpecies,
135:         binding: &mut TerrainBarkBinding<'_>,
136:     ) {
137:         if cache.variants.contains_key(&key) {
138:             return;
139:         }
140:         let Some(mut cached) = self.variant(key) else {
141:             return;
142:         };
143:         // Plant geometry is site-local; bind only bark to destination terrain.
144:         cached.bark_material = cache.bark_for_terrain(species, binding);
145:         diagnostics.add_resident_assets(&cached.resident_assets);
146:         cache.variants.insert(key, cached);
147:     }
148: 
149:     pub(super) fn variant(&self, key: Seed) -> Option<CachedTreePresentation> {
150:         self.scenes
151:             .iter()
152:             .rev()
153:             .find_map(|scene| scene.cache.variants.get(&key).cloned())
154:     }
155: 
156:     pub(super) fn update_diagnostics(
157:         &self,
158:         active: &TreePresentationCache,
159:         diagnostics: &mut TreeAssetResidencyDiagnostics,
160:     ) {
161:         diagnostics.retained_scenes = self.scenes.len();
162:         let mut variants = active
163:             .variants
164:             .keys()
165:             .copied()
166:             .collect::<std::collections::HashSet<_>>();
167:         let mut atlases = active
168:             .variants
169:             .values()
170:             .flat_map(|variant| {
171:                 variant
172:                     .lod_cards
173:                     .iter()
174:                     .flatten()
175:                     .map(|card| card.material.id())
176:             })
177:             .collect::<std::collections::HashSet<_>>();
178:         diagnostics.retained_variants = 0;
179:         diagnostics.retained_impostor_texture_bytes = 0;
180:         for scene in &self.scenes {
181:             for (key, variant) in &scene.cache.variants {
182:                 diagnostics.retained_variants += usize::from(variants.insert(*key));
183:                 for card in variant.lod_cards.iter().flatten() {
184:                     if atlases.insert(card.material.id()) {
185:                         diagnostics.retained_impostor_texture_bytes += card.provenance.atlas_width
186:                             as usize
187:                             * card.provenance.atlas_height as usize
188:                             * 4;
189:                     }
190:                 }
191:             }
192:         }
193:     }
194: }
