78: pub(super) fn oak_gnarling_for_site(
79:     mut recipe: OakGnarlingParameters,
80:     environment: &SceneEnvironment,
81:     tree_seed: Seed,
82: ) -> OakGnarlingParameters {
83:     let canopy = crate::presentation::procedural::bps(environment.canopy_bps);
84:     let open_exposure = 1.0 - canopy;
85:     let slope = crate::presentation::procedural::bps(environment.hilly_bps);
86:     let wetland = crate::presentation::procedural::bps(environment.wetland_bps);
87:     let cultivation = crate::presentation::procedural::bps(environment.cultivation_bps);
88:     let elevation =
89:         ((f32::from(environment.absolute_elevation_metres.get()) - 40.0) / 900.0).clamp(0.0, 1.0);
90:     let susceptibility = 0.72
91:         + StreamId::new("visual.obstacles.tree.source.susceptibility")
92:             .rng(tree_seed, &[])
93:             .inclusive_unit_f32()
94:             * 0.28;
95:     let wind_exposure =
96:         (open_exposure * 0.46 + slope * 0.34 + elevation * 0.2).clamp(0.0, 1.0) * susceptibility;
97:     let age_and_wounds = StreamId::new("visual.obstacles.tree.source.age-wounds")
98:         .rng(tree_seed, &[])
99:         .inclusive_unit_f32();
100:     let location = u64::from(environment.latitude_microdegrees.get() as u32) << 32
101:         | u64::from(environment.longitude_microdegrees.get() as u32);
102:     recipe.stress_azimuth_radians = StreamId::new("visual.obstacles.tree.source.wind-azimuth")
103:         .rng(location.into(), &[])
104:         .inclusive_unit_f32()
105:         * core::f32::consts::TAU;
106:     let add = |value: f32, stress: f32| (value + stress).clamp(0.0, 1.0);
107:     recipe.root_spread = add(
108:         recipe.root_spread,
109:         slope * 0.34 + wetland * 0.24 + wind_exposure * 0.2,
110:     );
111:     recipe.root_meander = add(recipe.root_meander, slope * 0.28 + wetland * 0.18);
112:     recipe.root_exposure = add(recipe.root_exposure, slope * 0.5 + open_exposure * 0.12);
113:     recipe.root_forking = add(recipe.root_forking, slope * 0.2 + age_and_wounds * 0.12);
114:     recipe.trunk_lean = add(recipe.trunk_lean, wind_exposure * 0.62 + wetland * 0.18);
115:     recipe.trunk_sweep = add(recipe.trunk_sweep, wind_exposure * 0.7);
116:     recipe.trunk_twist = add(
117:         recipe.trunk_twist,
118:         wind_exposure * 0.24 + age_and_wounds * 0.16,
119:     );
120:     recipe.trunk_crooks = add(
121:         recipe.trunk_crooks,
122:         cultivation * 0.3 + age_and_wounds * 0.16,
123:     );
124:     recipe.taper_irregularity = add(
125:         recipe.taper_irregularity,
126:         wetland * 0.18 + cultivation * 0.22 + age_and_wounds * 0.14,
127:     );
128:     recipe.knot_frequency = add(
129:         recipe.knot_frequency,
130:         cultivation * 0.38 + age_and_wounds * 0.24,
131:     );
132:     recipe.knot_scale = add(recipe.knot_scale, cultivation * 0.24 + age_and_wounds * 0.2);
133:     recipe.burl_scale = add(recipe.burl_scale, wetland * 0.3 + age_and_wounds * 0.16);
134:     recipe.scaffold_droop = add(
135:         recipe.scaffold_droop,
136:         age_and_wounds * 0.18 + wetland * 0.12,
137:     );
138:     recipe.scaffold_sweep = add(recipe.scaffold_sweep, wind_exposure * 0.76);
139:     recipe.scaffold_contortion = add(
140:         recipe.scaffold_contortion,
141:         wind_exposure * 0.32 + age_and_wounds * 0.18,
142:     );
143:     recipe.crown_asymmetry = add(recipe.crown_asymmetry, wind_exposure * 0.82);
144:     recipe
145: }
