214: // Vista communities retain their LOD-local key; playable communities use scene metres.
215: fn species_for_native_community_point(
216:     position: Vec2,
217:     environment: &SceneEnvironment,
218: ) -> TreePresentationSpecies {
219:     let canopy = crate::presentation::procedural::bps(environment.canopy_bps);
220:     let moisture = crate::presentation::procedural::bps(environment.weather.ground_moisture_bps);
221:     let wetland = crate::presentation::procedural::bps(environment.wetland_bps);
222:     let cultivation = crate::presentation::procedural::bps(environment.cultivation_bps);
223:     // Beech is concentrated in mesic, closed-canopy communities. Using a
224:     // 30-metre community key produces stands instead of tree-by-tree confetti
225:     // and places it where the existing canopy mask already strongly suppresses
226:     // grass. Species remains deterministic presentation data until the compact
227:     // server tree recipe grows an explicit species field.
228:     let probability =
229:         (canopy * 0.62 + moisture * 0.26 - wetland * 0.38 - cultivation * 0.18 - 0.12)
230:             .clamp(0.0, 0.68);
231:     let community_x = (position.x / 30.0).floor() as i32;
232:     let community_z = (position.y / 30.0).floor() as i32;
233:     let community = ((community_x as u32 as u64) << 32) | community_z as u32 as u64;
234:     let hash = StreamId::new("visual.obstacles.tree.source.community")
235:         .seed(oak_site_key(environment).into(), &[community]);
236:     if RNG_VISUAL_OBSTACLES_TREE_SOURCE_SPECIES
237:         .rng(hash, &[])
238:         .inclusive_unit_f32()
239:         < probability
240:     {
241:         TreePresentationSpecies::CommonBeech
242:     } else {
243:         TreePresentationSpecies::EnglishOak
244:     }
245: }
EOF 245

