1: //! Shared conversion of generator geometry into production render assets.
2: use super::*;
3: use adventuresim_building_generator::{BuildingLodMaterial, LodMesh};
4: 
5: /// Cuboid surfaces tile at the generator's material scale, irrespective of wall length.
6: pub(super) fn metric_cuboid(size: Vec3) -> Mesh {
7:     use bevy::mesh::VertexAttributeValues;
8:     let mut mesh = Mesh::from(Cuboid::from_size(size));
9:     let Some(VertexAttributeValues::Float32x3(positions)) =
10:         mesh.attribute(Mesh::ATTRIBUTE_POSITION)
11:     else {
12:         unreachable!()
13:     };
14:     let Some(VertexAttributeValues::Float32x3(normals)) = mesh.attribute(Mesh::ATTRIBUTE_NORMAL)
15:     else {
16:         unreachable!()
17:     };
18:     let uvs = positions
19:         .iter()
20:         .zip(normals)
21:         .map(|(position, normal)| {
22:             let p = Vec3::from_array(*position);
23:             let n = Vec3::from_array(*normal).abs();
24:             let uv = if n.x > 0.5 {
25:                 Vec2::new(p.z, p.y)
26:             } else if n.y > 0.5 {
27:                 Vec2::new(p.x, p.z)
28:             } else {
29:                 Vec2::new(p.x, p.y)
30:             };
31:             (uv / adventuresim_building_generator::BUILDING_DETAIL_UV_METRES_PER_UNIT).to_array()
32:         })
33:         .collect::<Vec<_>>();
34:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
35:     mesh.generate_tangents()
36:         .expect("metric box faces have valid UVs");
37:     mesh
38: }
39: 
40: pub(crate) fn recipe_mesh(batch: &LodMesh, local_origin: Vec3) -> Mesh {
41:     let mut mesh = Mesh::new(
42:         PrimitiveTopology::TriangleList,
43:         RenderAssetUsages::RENDER_WORLD | RenderAssetUsages::MAIN_WORLD,
44:     );
45:     mesh.insert_attribute(
46:         Mesh::ATTRIBUTE_POSITION,
47:         batch
48:             .vertices
49:             .iter()
50:             .map(|vertex| (vertex.position - local_origin).to_array())
51:             .collect::<Vec<_>>(),
52:     );
53:     mesh.insert_attribute(
54:         Mesh::ATTRIBUTE_NORMAL,
55:         batch
56:             .vertices
57:             .iter()
58:             .map(|vertex| vertex.normal.to_array())
59:             .collect::<Vec<_>>(),
60:     );
61:     mesh.insert_attribute(
62:         Mesh::ATTRIBUTE_UV_0,
63:         batch
64:             .vertices
65:             .iter()
66:             .map(|vertex| vertex.uv.to_array())
67:             .collect::<Vec<_>>(),
68:     );
69:     mesh.insert_indices(Indices::U32(batch.indices.clone()));
70:     if matches!(
71:         batch.material,
72:         BuildingLodMaterial::Wall(_)
73:             | BuildingLodMaterial::CrownMasonry
74:             | BuildingLodMaterial::Roof(_)
75:             | BuildingLodMaterial::Timber
76:             | BuildingLodMaterial::InteriorTimber
77:             | BuildingLodMaterial::FurnitureWood(_)
78:             | BuildingLodMaterial::Iron
79:             | BuildingLodMaterial::InteriorPlaster
80:             | BuildingLodMaterial::Floor
81:             | BuildingLodMaterial::Glass
82:     ) {
83:         mesh.generate_tangents()
84:             .expect("interior building UVs must support tangent-space normal maps");
85:     }
86:     mesh
87: }
