1: //! Isolated map lighting from the existing celestial presentation authority.
2: use crate::presentation::ownership::RegionalMapRoot;
3: use crate::presentation::sky::{TacticalMoonlight, TacticalSunlight};
4: use bevy::{camera::visibility::RenderLayers, prelude::*};
5: 
6: #[derive(Component)]
7: pub(super) struct MapLightSource(Entity);
8: 
9: #[expect(
10:     clippy::type_complexity,
11:     reason = "Copy the two authoritative celestial lights into an isolated presentation layer"
12: )]
13: pub(super) fn sync(
14:     mut commands: Commands,
15:     roots: Query<Entity, With<RegionalMapRoot>>,
16:     sources: Query<
17:         (
18:             Entity,
19:             Ref<DirectionalLight>,
20:             Ref<Transform>,
21:             Option<&TacticalSunlight>,
22:         ),
23:         (
24:             Or<(With<TacticalSunlight>, With<TacticalMoonlight>)>,
25:             Without<MapLightSource>,
26:         ),
27:     >,
28:     mut targets: Query<(
29:         Entity,
30:         &MapLightSource,
31:         &mut DirectionalLight,
32:         &mut Transform,
33:     )>,
34: ) {
35:     let Ok(root) = roots.single() else {
36:         return;
37:     };
38:     for (entity, source, _, _) in &targets {
39:         if sources.get(source.0).is_err() {
40:             commands.entity(entity).despawn();
41:         }
42:     }
43:     for (source_entity, light, transform, sunlight) in &sources {
44:         let existing = targets
45:             .iter_mut()
46:             .find(|(_, source, _, _)| source.0 == source_entity);
47:         if existing.is_some() && !light.is_changed() && !transform.is_changed() {
48:             continue;
49:         }
50:         let mut map_light = *light;
51:         // The source supplies top-of-atmosphere sunlight: its PBR atmosphere
52:         // normally applies planetary horizon occlusion. Map views omit that
53:         // atmospheric pass, so never expose raw sunlight below their shared
54:         // local horizon. Transform::back is the direction towards the light.
55:         if sunlight.is_some() && transform.back().y <= 0.0 {
56:             map_light.illuminance = 0.0;
57:         }
58:         // The initial terrain view needs no short-range tactical shadow maps.
59:         map_light.shadow_maps_enabled = false;
60:         // The sky owner already adapts east/up/north celestial vectors into
61:         // Bevy east/up/south. Unlike terrain samples, its Z needs no reflection.
62:         let map_transform = *transform;
63:         if let Some((_, _, mut light, mut transform)) = existing {
64:             *light = map_light;
65:             *transform = map_transform;
66:         } else {
67:             commands.spawn((
68:                 Name::new("Regional celestial light"),
69:                 MapLightSource(source_entity),
70:                 map_light,
