1: //! Retained geographic camera pose. Native view X is east, Y is elevation and
2: //! Z is south; the source sampler retains its canonical east/north convention.
3: use super::protocol::{CanvasRect, MapPointerDisplacement, MapProtocolError};
4: use adventuresim_building_generator::spatial_geometry::{PositiveLength, Radians};
5: use adventuresim_tactical_core::{
6:     regional_map::{MAX_MAP_SPAN_METRES, MIN_MAP_SPAN_METRES, MapRoute, MapSpan, MapZoomRatio},
7:     regional_terrain::{REGIONAL_TERRAIN_SIDE, RegionalTerrainRequest, RegionalTerrainScale},
8: };
9: use adventuresim_world_schema::coordinates::{
10:     LatitudeMicrodegrees, LongitudeMicrodegrees, Wgs84CoordinateMicrodegrees,
11:     terrain_projection::NativeTerrainCoordinate,
12: };
13: use adventuresim_world_schema::source_package::SourcePackageDigest;
14: use bevy::{math::DVec2, prelude::*};
15: 
16: pub(super) const MAP_PITCH_RADIANS: f32 = std::f32::consts::PI / 3.0;
17: const WINDOW_COVERAGE_MARGIN: f64 = 2.0;
18: const WINDOW_CENTER_STEP_CELLS: usize = (REGIONAL_TERRAIN_SIDE - 1) / 4;
19: const ROUTE_FRAMING_MARGIN: f64 = 1.25;
20: pub(super) type Result<T> = std::result::Result<T, MapProtocolError>;
21: 
22: pub(super) struct MapPose {
23:     pub source: SourcePackageDigest,
24:     pub home: Wgs84CoordinateMicrodegrees,
25:     pub origin: NativeTerrainCoordinate,
26:     pub span: MapSpan,
27:     pub yaw: Radians,
28:     pub rect: Option<CanvasRect>,
29:     home_span: MapSpan,
30: }
31: 
32: impl MapPose {
33:     pub fn new(
34:         source: SourcePackageDigest,
35:         home: Wgs84CoordinateMicrodegrees,
36:         span: MapSpan,
37:         rect: CanvasRect,
38:     ) -> Self {
39:         Self {
40:             source,
41:             home,
42:             origin: home.to_e7().into(),
43:             span,
44:             yaw: Radians::ZERO,
45:             rect: Some(rect),
46:             home_span: span,
47:         }
48:     }
49: 
50:     pub fn reset(&mut self) {
51:         self.origin = self.home.to_e7().into();
52:         self.span = self.home_span;
53:         self.yaw = Radians::ZERO;
54:     }
55: 
56:     pub fn zoom(&mut self, ratio: MapZoomRatio) -> Result<()> {
57:         self.span = self.span.zoomed(ratio)?;
58:         Ok(())
59:     }
60: 
61:     pub fn rotate(&mut self, angle: Radians) -> Result<()> {
62:         let radians = (f64::from(self.yaw.radians()) + f64::from(angle.radians()))
63:             .rem_euclid(std::f64::consts::TAU) as f32;
64:         self.yaw = Radians::new(radians)?;
65:         Ok(())
66:     }
67: 
68:     pub fn pan(
69:         &mut self,
70:         delta: MapPointerDisplacement,
71:         frame: Wgs84CoordinateMicrodegrees,
72:     ) -> Result<()> {
73:         let Some(rect) = self.rect else {
74:             return Ok(());
75:         };
76:         // Physical canvas pixels enter the orthographic/geographic arithmetic
77:         // port once. f64 retains finite products for all admitted input floats.
78:         let pixels = delta.pixels();
79:         let metres_per_pixel = f64::from(self.span.metres()) / f64::from(rect.full_height.max(1));
80:         let horizontal = -f64::from(pixels.x) * metres_per_pixel;
81:         let vertical = f64::from(pixels.y) * metres_per_pixel / f64::from(MAP_PITCH_RADIANS.sin());
82:         let yaw = f64::from(self.yaw.radians());
83:         let east = horizontal * yaw.cos() - vertical * yaw.sin();
84:         let north = horizontal * yaw.sin() + vertical * yaw.cos();
85:         let frame = NativeTerrainCoordinate::from(frame.to_e7());
86:         let current = frame.offset_to(self.origin);
87:         let point = frame.at_offset(current.east_metres + east, current.north_metres + north);
88:         self.origin = bounded_origin(point)?;
89:         Ok(())
90:     }
91: 
92:     pub fn geographic_origin(&self) -> Result<Wgs84CoordinateMicrodegrees> {
93:         geographic_origin(self.origin)
94:     }
95: 
96:     pub fn frame_route(&mut self, route: &MapRoute) -> Result<()> {
97:         let Some(rect) = self.rect else {
98:             return Ok(());
99:         };
100:         let frame = NativeTerrainCoordinate::from(self.home.to_e7());
101:         let yaw = f64::from(self.yaw.radians());
102:         let right = DVec2::new(yaw.cos(), yaw.sin());
103:         let forward = DVec2::new(-yaw.sin(), yaw.cos());
104:         let mut minimum = DVec2::splat(f64::INFINITY);
105:         let mut maximum = DVec2::splat(f64::NEG_INFINITY);
106:         // Native fitting port: route points become rotated east/north metres.
107:         for point in route.points() {
108:             let offset = frame.offset_to(point.to_e7().into());
109:             let native = DVec2::new(offset.east_metres, offset.north_metres);
110:             let camera = DVec2::new(native.dot(right), native.dot(forward));
111:             minimum = minimum.min(camera);
112:             maximum = maximum.max(camera);
113:         }
114:         let centre = (minimum + maximum) * 0.5;
115:         let native = right * centre.x + forward * centre.y;
116:         let extent = maximum - minimum;
117:         let aspect = f64::from(rect.full_width) / f64::from(rect.full_height);
118:         let span = (extent.x / aspect).max(extent.y * f64::from(MAP_PITCH_RADIANS.sin()))
119:             * ROUTE_FRAMING_MARGIN;
120:         let span = MapSpan::try_from(PositiveLength::from_metres(span.clamp(
121:             f64::from(MIN_MAP_SPAN_METRES),
122:             f64::from(MAX_MAP_SPAN_METRES),
123:         ) as f32)?)?;
124:         self.origin = bounded_origin(frame.at_offset(native.x, native.y))?;
125:         self.span = span;
126:         Ok(())
127:     }
128: 
129:     pub fn requested_window(&self) -> Result<Option<RegionalTerrainRequest>> {
130:         let Some(rect) = self.rect else {
131:             return Ok(None);
132:         };
133:         let aspect = f64::from(rect.full_width.max(1)) / f64::from(rect.full_height.max(1));
134:         let width = f64::from(self.span.metres()) * aspect;
135:         let height = f64::from(self.span.metres()) / f64::from(MAP_PITCH_RADIANS.sin());
136:         let yaw = f64::from(self.yaw.radians());
137:         let east_extent = width * yaw.cos().abs() + height * yaw.sin().abs();
138:         let north_extent = width * yaw.sin().abs() + height * yaw.cos().abs();
139:         let needed = east_extent.max(north_extent) * WINDOW_COVERAGE_MARGIN;
140:         let scale = [
141:             RegionalTerrainScale::Neighborhood,
142:             RegionalTerrainScale::District,
143:             RegionalTerrainScale::Region,
144:             RegionalTerrainScale::Country,
145:             RegionalTerrainScale::Continent,
146:         ]
147:         .into_iter()
148:         .find(|scale| {
149:             f64::from(scale.spacing_metres()) * (REGIONAL_TERRAIN_SIDE - 1) as f64 >= needed
150:         })
151:         .unwrap_or(RegionalTerrainScale::Continent);
152:         let home = NativeTerrainCoordinate::from(self.home.to_e7());
153:         let offset = home.offset_to(self.origin);
154:         let step = f64::from(scale.spacing_metres()) * WINDOW_CENTER_STEP_CELLS as f64;
155:         let point = home.at_offset(
156:             (offset.east_metres / step).round() * step,
157:             (offset.north_metres / step).round() * step,
158:         );
159:         Ok(Some(RegionalTerrainRequest {
160:             origin: geographic_origin(point)?,
161:             scale,
162:         }))
163:     }
164: }
165: 
166: fn geographic_origin(point: NativeTerrainCoordinate) -> Result<Wgs84CoordinateMicrodegrees> {
167:     let point = bounded_origin(point)?;
168:     Wgs84CoordinateMicrodegrees::from_longitude_latitude_degrees(
169:         point.longitude_degrees,
170:         point.latitude_degrees,
171:     )
172:     .ok_or(MapProtocolError::Origin)
173: }
174: 
175: fn bounded_origin(point: NativeTerrainCoordinate) -> Result<NativeTerrainCoordinate> {
176:     if !point.longitude_degrees.is_finite() || !point.latitude_degrees.is_finite() {
177:         return Err(MapProtocolError::Origin);
178:     }
179:     Ok(NativeTerrainCoordinate {
180:         longitude_degrees: point.longitude_degrees.clamp(
181:             LongitudeMicrodegrees::MIN.degrees(),
182:             LongitudeMicrodegrees::MAX.degrees(),
183:         ),
184:         latitude_degrees: point.latitude_degrees.clamp(
185:             LatitudeMicrodegrees::MIN.degrees(),
186:             LatitudeMicrodegrees::MAX.degrees(),
187:         ),
188:     })
189: }
