11: pub(in crate::presentation::regional_map) fn install(
12:     world: &mut World,
13:     json: &str,
14:     preparation: PreparationTicket,
15: ) {
16:     let result = admit(world, json, preparation);
17:     let retired = {
18:         let mut state = world.resource_mut::<MapState>();
19:         match result {
20:             Ok(Admission::Resident) => {
21:                 state.city.status = Some(InstallationStatus {
22:                     preparation,
23:                     phase: InstallationPhase::Ready,
24:                     error: None,
25:                 });
26:                 None
27:             }
28:             Ok(Admission::Replacement(city)) => {
29:                 let old = state.city.pending.replace(*city);
30:                 state.city.status = Some(InstallationStatus {
31:                     preparation,
32:                     phase: InstallationPhase::Preparing,
33:                     error: None,
34:                 });
35:                 state.city.settled_frames = 0;
36:                 old.map(|old| old.root)
37:             }
38:             Err(error) => {
39:                 state.city.status = Some(InstallationStatus::failed(preparation, error));
40:                 None
41:             }
42:         }
43:     };
44:     if let Some(root) = retired
45:         && let Ok(entity) = world.get_entity_mut(root)
46:     {
47:         entity.despawn();
48:     }
49: }
50: 
51: fn admit(
52:     world: &mut World,
53:     json: &str,
54:     preparation: PreparationTicket,
55: ) -> std::result::Result<Admission, InstallationFailure> {
56:     let document: RegionalCityInput = serde_json::from_str(json).map_err(|error| {
57:         warn!(%error, "Invalid focused city document");
58:         InstallationFailure::Input
59:     })?;
60:     let state = world.resource::<MapState>();
61:     let origin = state
62:         .presented
63:         .as_ref()
64:         .filter(|surface| &surface.source == document.source())
65:         .filter(|_| state.requested_city() == Some(document.place()))
66:         .map(|surface| surface.request.origin)
67:         .ok_or(InstallationFailure::Focus)?;
68:     let product = activate_city(preparation, &document).map_err(|error| {
69:         warn!(%error, "Could not activate focused city preparation");
70:         InstallationFailure::Preparation
71:     })?;
72:     let residency = &world.resource::<MapState>().city;
73:     if residency.pending.is_none()
74:         && residency
75:             .installed
76:             .as_ref()
77:             .is_some_and(|city| Arc::ptr_eq(&city.product, &product))
78:     {
79:         return Ok(Admission::Resident);
80:     }
81:     let frame = CityFrame::from_geographic_city(&document, origin);
82:     let owner = PresentationOwner::RegionalMap;
83:     let root = world
84:         .spawn((
85:             Name::new("Focused map city"),
86:             owner,
87:             owner.render_layers(),
88:             Transform::from_matrix(frame.world_from_city()),
89:             Visibility::Hidden,
90:         ))
91:         .id();
92:     let installation = FocusedGround::install(world, &product, root, frame)
93:         .map_err(|error| {
94:             warn!(%error, "Could not install canonical city ground");
95:             InstallationFailure::Ground
96:         })
97:         .and_then(|ground| {
98:             buildings::queue_focused_city(world, &document, root, origin).map_err(|error| {
99:                 warn!(%error, "Could not queue complete focused city");
100:                 InstallationFailure::Buildings
101:             })?;
102:             Ok(InstalledCity {
103:                 root,
104:                 product,
105:                 ground,
106:                 frame,
107:             })
108:         });
109:     if installation.is_err()
110:         && let Ok(entity) = world.get_entity_mut(root)
111:     {
112:         entity.despawn();
113:     }
114:     installation.map(|city| Admission::Replacement(Box::new(city)))
115: }
