1: //! Spatial marker projection belongs to the camera; HTML retains link semantics.
2: use super::{MapState, RegionalMapCamera};
3: use adventuresim_core::strategic_place::StrategicPlaceId;
4: use adventuresim_tactical_core::regional_map::{MapMarkerEmphasis, MapMarkerRank};
5: use bevy::prelude::*;
6: use serde::Serialize;
7: 
8: const VILLAGE_VIEW_SPAN_METRES: f32 = 100_000.0;
9: const TOWN_VIEW_SPAN_METRES: f32 = 300_000.0;
10: const CITY_VIEW_SPAN_METRES: f32 = 1_000_000.0;
11: 
12: /// Absolute logical canvas pixels, from Bevy's actual cropped camera projection.
13: #[derive(Serialize)]
14: pub(super) struct ProjectedMarker<'a> {
15:     place: &'a StrategicPlaceId,
16:     x: f32,
17:     y: f32,
18: }
19: 
20: pub(super) fn project<'a>(
21:     state: &'a MapState,
22:     cameras: &Query<(&Camera, &GlobalTransform), With<RegionalMapCamera>>,
23: ) -> Vec<ProjectedMarker<'a>> {
24:     let (Some(pose), Some(terrain), Some(surface), Some(overlay)) = (
25:         &state.pose,
26:         state.terrain(),
27:         &state.presented,
28:         &state.overlay,
29:     ) else {
30:         return Vec::new();
31:     };
32:     if pose.rect.is_none()
33:         || overlay.source() != &pose.source
34:         || terrain.source() != &pose.source
35:         || terrain.request() != surface.request
36:     {
37:         return Vec::new();
38:     }
39:     let Ok((camera, transform)) = cameras.single() else {
40:         return Vec::new();
41:     };
42:     let Some(viewport) = camera.logical_viewport_rect() else {
43:         return Vec::new();
44:     };
45:     if !camera.is_active {
46:         return Vec::new();
47:     }
48:     overlay
49:         .markers()
50:         .iter()
51:         .filter_map(|marker| {
52:             let essential = marker.emphasis != MapMarkerEmphasis::Ordinary;
53:             let visible = essential
54:                 || match marker.rank {
55:                     MapMarkerRank::Hamlet | MapMarkerRank::Village => {
56:                         pose.span.metres() <= VILLAGE_VIEW_SPAN_METRES
57:                     }
58:                     MapMarkerRank::Town => pose.span.metres() <= TOWN_VIEW_SPAN_METRES,
59:                     MapMarkerRank::City => pose.span.metres() <= CITY_VIEW_SPAN_METRES,
60:                     MapMarkerRank::Capital | MapMarkerRank::CaseSite => true,
61:                 };
62:             if !visible {
63:                 return None;
64:             }
65:             let point = state.ground_position(marker.origin.to_e7().into())?;
66:             let screen = camera.world_to_viewport(transform, point).ok()?;
67:             viewport.contains(screen).then_some(ProjectedMarker {
68:                 place: &marker.place,
69:                 x: screen.x,
70:                 y: screen.y,
71:             })
72:         })
73:         .collect()
74: }
