135:                     .is_some_and(|pose| pose.source == *environment.terrain().source())
136:                 {
137:                     state.environment = Some(environment);
138:                 }
139:                 Ok(())
140:             }
141:             Self::InstallOverlay { revision, overlay } => {
142:                 if state
143:                     .pose
144:                     .as_ref()
145:                     .is_some_and(|pose| &pose.source == overlay.source())
146:                     && state
147:                         .overlay_revision
148:                         .is_none_or(|current| revision > current)
149:                 {
150:                     state.overlay = Some(overlay);
151:                     state.overlay_revision = Some(revision);
152:                     state.settled_frames = 0;
153:                 }
154:                 Ok(())
155:             }
156:         };
157:         state.failure = result.err();
158:     }
159: }
160: 
161: impl MapState {
162:     fn terrain(&self) -> Option<&RegionalTerrain> {
163:         self.environment
164:             .as_ref()
165:             .map(|environment| environment.terrain())
166:     }
167: 
168:     fn open(
169:         &mut self,
170:         source: SourcePackageDigest,
171:         origin: Wgs84CoordinateMicrodegrees,
172:         span: MapSpan,
173:         rect: protocol::CanvasRect,
174:     ) {
175:         if let Some(pose) = self.pose.as_mut()
176:             && pose.source == source
177:             && pose.home == origin
178:         {
179:             pose.rect = Some(rect);
180:         } else {
181:             self.pose = Some(MapPose::new(source, origin, span, rect));
182:             self.environment = None;
183:             self.overlay = None;
184:             self.overlay_revision = None;
185:         }
186:     }
187: 
188:     fn pan(&mut self, delta: protocol::MapPointerDisplacement) -> camera::Result<()> {
189:         let Some(pose) = self.pose.as_mut() else {
190:             return Ok(());
191:         };
192:         let frame = self
193:             .presented
194:             .as_ref()
195:             .filter(|surface| surface.source == pose.source)
196:             .map_or(pose.home, |surface| surface.request.origin);
197:         pose.pan(delta, frame)
198:     }
199: 
200:     fn frame_route(&mut self) -> camera::Result<()> {
201:         match (
202:             self.pose.as_mut(),
203:             self.overlay.as_ref().and_then(MapOverlay::route),
204:         ) {
205:             (Some(pose), Some(route)) => pose.frame_route(route),
206:             _ => Ok(()),
207:         }
208:     }
209: }
210: 
211: fn setup(mut commands: Commands) {
212:     commands.spawn((RegionalMapRoot, Transform::default(), Visibility::Hidden));
213:     commands.spawn((
214:         RegionalMapCamera,
215:         crate::strategic_scene::StrategicCamera,
216:         crate::presentation::interior_lighting::FixedViewExposure,
217:         Camera3d::default(),
218:         Camera {
219:             order: MAP_CAMERA_ORDER,
220:             is_active: false,
221:             clear_color: ClearColorConfig::Custom(Color::srgb(0.13, 0.16, 0.19)),
222:             ..default()
223:         },
224:         Projection::Orthographic(OrthographicProjection::default_3d()),
225:         bevy::camera::visibility::RenderLayers::layer(
226:             crate::presentation::ownership::REGIONAL_MAP_LAYER,
227:         ),
228:         bevy::camera::Exposure::SUNLIGHT,
229:         Msaa::Off,
230:     ));
231: }
