1: //! One geographic surface, sharing the existing environment material and assets.
2: use super::{MapState, RegionalMapCamera, RegionalMapRoot, camera::MAP_PITCH_RADIANS};
3: use crate::presentation::{
4:     ActiveTacticalScene, SceneEnvironment,
5:     ground_scatter::grass_terminal_pigment,
6:     vista::{TacticalVistaMaterial, regional::regional_mesh, vista_material},
7: };
8: use adventuresim_core::weather::WeatherSnapshot;
9: use adventuresim_tactical_core::regional_terrain::{RegionalTerrain, RegionalTerrainRequest};
10: use adventuresim_world_schema::source_package::SourcePackageDigest;
11: use adventuresim_world_schema::{
12:     ElevationMeters, coordinates::terrain_projection::NativeTerrainCoordinate,
13: };
14: use bevy::{camera::visibility::RenderLayers, prelude::*};
15: 
16: const CAMERA_STANDOFF_SPANS: f32 = 2.0;
17: const CAMERA_CLIP_MARGIN: f32 = 4.0;
18: 
19: pub(super) struct PresentedSurface {
20:     pub source: SourcePackageDigest,
21:     pub request: RegionalTerrainRequest,
22:     weather: WeatherSnapshot,
23:     grass: Color,
24:     pub coverage: SurfaceCoverage,
25: }
26: 
27: pub(super) enum SurfaceCoverage {
28:     Empty,
29:     Drawn {
30:         entity: Entity,
31:         mesh: Handle<Mesh>,
32:         material: Handle<TacticalVistaMaterial>,
33:         datum: ElevationMeters,
34:         minimum: ElevationMeters,
35:         maximum: ElevationMeters,
36:     },
37: }
38: 
39: struct ElevationBounds {
40:     minimum: ElevationMeters,
41:     maximum: ElevationMeters,
42: }
43: 
44: impl ElevationBounds {
45:     fn from_terrain(terrain: &RegionalTerrain) -> Option<Self> {
46:         let mut elevations = terrain
47:             .vertices()
48:             .iter()
49:             .flatten()
50:             .map(|vertex| vertex.elevation);
51:         let first = elevations.next()?;
52:         let mut bounds = Self {
53:             minimum: first,
54:             maximum: first,
55:         };
56:         for elevation in elevations {
57:             if elevation.get() < bounds.minimum.get() {
58:                 bounds.minimum = elevation;
59:             }
60:             if elevation.get() > bounds.maximum.get() {
61:                 bounds.maximum = elevation;
62:             }
63:         }
64:         Some(bounds)
65:     }
66: }
67: 
68: pub(super) fn present(
69:     mut commands: Commands,
70:     mut state: ResMut<MapState>,
71:     active: Res<ActiveTacticalScene>,
72:     environments: Query<&SceneEnvironment>,
73:     roots: Query<Entity, With<RegionalMapRoot>>,
74:     mut meshes: ResMut<Assets<Mesh>>,
75:     mut materials: ResMut<Assets<TacticalVistaMaterial>>,
76: ) {
77:     let Some(pose) = &state.pose else {
78:         return;
79:     };
80:     if pose.rect.is_none() {
81:         return;
82:     }
83:     let Some(terrain) = state.terrain() else {
84:         return;
85:     };
86:     let Some(environment) = active
87:         .entity
88:         .and_then(|entity| environments.get(entity).ok())
89:     else {
90:         return;
91:     };
92:     let grass = grass_terminal_pigment(environment);
93:     if state.presented.as_ref().is_some_and(|surface| {
94:         surface.source == *terrain.source()
95:             && surface.request == terrain.request()
96:             && surface.weather == environment.weather
97:             && surface.grass == grass
98:     }) {
99:         return;
100:     }
101:     let Ok(root) = roots.single() else {
102:         return;
103:     };
104:     let mesh = regional_mesh(terrain, environment.weather);
105:     let surface = PresentedSurface {
106:         source: terrain.source().clone(),
107:         request: terrain.request(),
108:         weather: environment.weather,
109:         grass,
110:         coverage: match mesh {
111:             Some(mesh) => {
112:                 let Some(bounds) = ElevationBounds::from_terrain(terrain) else {
113:                     return;
114:                 };
115:                 let datum = terrain.vertices()[terrain.vertices().len() / 2]
116:                     .map_or(bounds.minimum, |vertex| vertex.elevation);
117:                 let mesh = meshes.add(mesh);
118:                 let material = materials.add(vista_material(environment.weather, grass));
119:                 let entity = commands
120:                     .spawn((
121:                         Name::new("Regional environment surface"),
122:                         Mesh3d(mesh.clone()),
123:                         MeshMaterial3d(material.clone()),
124:                         Transform::default(),
125:                         ChildOf(root),
126:                         RenderLayers::layer(crate::presentation::ownership::REGIONAL_MAP_LAYER),
127:                     ))
128:                     .id();
129:                 SurfaceCoverage::Drawn {
130:                     entity,
131:                     mesh,
132:                     material,
133:                     datum,
134:                     minimum: bounds.minimum,
135:                     maximum: bounds.maximum,
136:                 }
137:             }
138:             None => SurfaceCoverage::Empty,
139:         },
140:     };
141:     if let Some(old) = state.presented.replace(surface)
142:         && let SurfaceCoverage::Drawn {
143:             entity,
144:             mesh,
145:             material,
146:             ..
147:         } = old.coverage
148:     {
149:         commands.entity(entity).despawn();
150:         meshes.remove(mesh.id());
151:         materials.remove(material.id());
152:     }
153:     state.settled_frames = 0;
154: }
155: 
156: pub(super) fn sync_camera(
157:     state: Res<MapState>,
158:     windows: Query<&Window>,
159:     mut roots: Query<&mut Visibility, With<RegionalMapRoot>>,
160:     mut cameras: Query<(&mut Camera, &mut Transform, &mut Projection), With<RegionalMapCamera>>,
161: ) {
162:     let Ok((mut camera, mut transform, mut projection)) = cameras.single_mut() else {
163:         return;
164:     };
165:     camera.is_active = false;
166:     for mut root in &mut roots {
167:         *root = Visibility::Hidden;
168:     }
169:     let (Some(pose), Some(surface)) = (&state.pose, &state.presented) else {
170:         return;
171:     };
172:     let Some(rect) = pose.rect else {
173:         return;
174:     };
175:     if surface.source != pose.source {
176:         return;
177:     }
178:     let Ok(window) = windows.single() else {
179:         return;
180:     };
181:     rect.apply(&mut camera, window.resolution.physical_size());
182:     if !camera.is_active {
183:         return;
184:     }
185:     // An empty admitted window still clears its viewport. Deactivating the
186:     // last camera could leave the previous frame painted on the canvas.
187:     let SurfaceCoverage::Drawn {
188:         datum,
189:         minimum,
190:         maximum,
191:         ..
192:     } = surface.coverage
193:     else {
194:         return;
195:     };
196:     let offset =
197:         NativeTerrainCoordinate::from(surface.request.origin.to_e7()).offset_to(pose.origin);
198:     // Only the camera may retain the window datum over a coverage hole. Covered
199:     // focus positions use the same interpolated source plane as pins and routes.
200:     let elevation = state
201:         .terrain()
202:         .filter(|terrain| terrain.request() == surface.request)
203:         .and_then(|_| state.ground_position(pose.origin))
204:         .map_or(f32::from(datum.get()), |point| point.y);
205:     let target = Vec3::new(
206:         offset.east_metres as f32,
207:         elevation,
208:         -offset.north_metres as f32,
209:     );
210:     let elevation_range = f32::from(maximum.get()) - f32::from(minimum.get());
211:     let distance = pose.span.metres().max(elevation_range) * CAMERA_STANDOFF_SPANS;
212:     let yaw = pose.yaw.radians();
213:     let direction = Vec3::new(
214:         yaw.sin() * MAP_PITCH_RADIANS.cos(),
215:         MAP_PITCH_RADIANS.sin(),
216:         yaw.cos() * MAP_PITCH_RADIANS.cos(),
217:     );
218:     *transform =
219:         Transform::from_translation(target + direction * distance).looking_at(target, Vec3::Y);
220:     *projection = Projection::Orthographic(OrthographicProjection {
221:         scaling_mode: bevy::camera::ScalingMode::FixedVertical {
222:             viewport_height: pose.span.metres(),
223:         },
224:         near: 0.0,
225:         far: distance * CAMERA_CLIP_MARGIN,
226:         ..OrthographicProjection::default_3d()
227:     });
228:     for mut root in &mut roots {
229:         *root = Visibility::Inherited;
230:     }
231: }
EOF 231
