1: //! Rotation from equatorial star coordinates into the local sky.
2: 
3: use adventuresim_world_schema::calendar::StrategicMinute;
4: use adventuresim_world_schema::coordinates::{LatitudeMicrodegrees, LongitudeMicrodegrees};
5: use bevy::math::{Mat3, Mat4, Vec3};
6: 
7: pub(super) fn equatorial_to_world(
8:     absolute_minute: StrategicMinute,
9:     latitude: LatitudeMicrodegrees,
10:     longitude: LongitudeMicrodegrees,
11: ) -> Mat4 {
12:     let latitude = (latitude.degrees() as f32).to_radians();
13:     let longitude = (longitude.degrees() as f32).to_radians();
14:     let day = absolute_minute.days_since_epoch_f32();
15:     let sidereal = (4.383_4 + day * core::f32::consts::TAU * 1.002_737_9 + longitude)
16:         .rem_euclid(core::f32::consts::TAU);
17:     let (sin_latitude, cos_latitude) = latitude.sin_cos();
18:     let (sin_sidereal, cos_sidereal) = sidereal.sin_cos();
19:     Mat4::from_mat3(Mat3::from_cols(
20:         Vec3::new(
21:             -sin_sidereal,
22:             cos_latitude * cos_sidereal,
23:             sin_latitude * cos_sidereal,
24:         ),
25:         Vec3::new(0.0, sin_latitude, -cos_latitude),
26:         Vec3::new(
27:             cos_sidereal,
28:             cos_latitude * sin_sidereal,
29:             sin_latitude * sin_sidereal,
30:         ),
31:     ))
32: }
EOF 32

