230: impl CelestialLightingSnapshot {
231:     fn from_environment(scene: Entity, environment: &SceneEnvironment) -> Self {
232:         let latitude = environment.latitude_microdegrees;
233:         let longitude = environment.longitude_microdegrees;
234:         let celestial = celestial_directions_with_phase(
235:             environment.absolute_minute,
236:             environment.lunar_phase_minute,
237:             latitude,
238:             longitude,
239:         );
240:         let sun_direction = to_bevy_direction(celestial.sun);
241:         let moon_direction = to_bevy_direction(celestial.moon);
242:         let sun_altitude_degrees = sun_direction.y.asin().to_degrees();
243:         let moon_altitude_degrees = moon_direction.y.asin().to_degrees();
244:         Self {
245:             scene,
246:             sun_direction,
