307: pub(in crate::presentation) fn apply_presented_celestial_lighting(
308:     active: Res<ActiveTacticalScene>,
309:     celestial: Res<PresentedCelestialLighting>,
310:     settings: Res<TacticalGraphicsSettings>,
311:     sunlight: Single<(&mut DirectionalLight, &mut Transform), With<TacticalSunlight>>,
312:     moonlight: Single<
313:         (&mut DirectionalLight, &mut Transform),
314:         (With<TacticalMoonlight>, Without<TacticalSunlight>),
315:     >,
316:     camera: Single<&mut Exposure, With<TacticalGameplayCamera>>,
317:     mut ambient: ResMut<GlobalAmbientLight>,
318:     mut moon: Query<
319:         (&MeshMaterial3d<TacticalMoonMaterial>, &mut Visibility),
320:         (With<TacticalMoon>, Without<TacticalStars>),
321:     >,
322:     mut stars: Query<
323:         (&MeshMaterial3d<TacticalStarMaterial>, &mut Visibility),
324:         (With<TacticalStars>, Without<TacticalMoon>),
325:     >,
326:     mut moon_materials: ResMut<Assets<TacticalMoonMaterial>>,
327:     mut star_materials: ResMut<Assets<TacticalStarMaterial>>,
328:     environments: Query<&SceneEnvironment>,
329: ) {
330:     if !celestial.is_changed() && !settings.is_changed() {
331:         return;
332:     }
333:     let Some(celestial) = celestial.snapshot.as_ref() else {
334:         let (mut sun, _) = sunlight.into_inner();
335:         sun.illuminance = 0.0;
336:         sun.shadow_maps_enabled = false;
337:         let (mut moon_light, _) = moonlight.into_inner();
338:         moon_light.illuminance = 0.0;
339:         moon_light.shadow_maps_enabled = false;
340:         camera.into_inner().ev100 = Exposure::SUNLIGHT.ev100;
341:         ambient.brightness = 0.0;
342:         if let Ok((handle, mut visibility)) = moon.single_mut() {
343:             *visibility = Visibility::Hidden;
344:             if let Some(mut material) = moon_materials.get_mut(&handle.0) {
345:                 material.light = Vec4::ZERO;
346:             }
347:         }
348:         if let Ok((handle, mut visibility)) = stars.single_mut() {
349:             *visibility = Visibility::Hidden;
350:             if let Some(mut material) = star_materials.get_mut(&handle.0) {
351:                 material.settings.x = 0.0;
352:             }
353:         }
354:         return;
355:     };
356:     let Some(environment) = active
357:         .entity
358:         .filter(|entity| *entity == celestial.scene)
359:         .and_then(|entity| environments.get(entity).ok())
360:     else {
361:         return;
362:     };
363: 
364:     let (mut sun, mut sun_transform) = sunlight.into_inner();
365:     sun.illuminance = scene_atmosphere_solar_illuminance(environment);
366:     sun.shadow_maps_enabled =
367:         settings.config.rendering.shadows.enabled && celestial.sun_altitude_degrees > 0.0;
368:     *sun_transform = light_transform(celestial.sun_direction);
369: 
370:     let (mut moon_light, mut moon_transform) = moonlight.into_inner();
371:     moon_light.illuminance = 0.25
372:         * celestial.lunar_illumination
373:         * smoothstep(-2.0, 4.0, celestial.moon_altitude_degrees)
374:         * celestial.weather_transmission;
375:     moon_light.shadow_maps_enabled = settings.config.rendering.shadows.enabled
376:         && celestial.sun_altitude_degrees <= -2.0
377:         && celestial.moon_altitude_degrees > 0.0
378:         && celestial.lunar_illumination > 0.15;
379:     *moon_transform = light_transform(celestial.moon_direction);
380: 
381:     camera.into_inner().ev100 = celestial.exposure_ev100;
382:     ambient.brightness = 0.0;
383: 
384:     if let Ok((handle, mut visibility)) = moon.single_mut()
385:         && let Some(mut material) = moon_materials.get_mut(&handle.0)
386:     {
387:         *visibility = Visibility::Inherited;
388:         material.light = celestial
389:             .sun_direction
390:             .extend(celestial.weather_transmission);
391:         material.appearance.z = celestial.lunar_phase;
392:     }
393:     if let Ok((handle, mut visibility)) = stars.single_mut()
394:         && let Some(mut material) = star_materials.get_mut(&handle.0)
395:     {
396:         *visibility = Visibility::Inherited;
397:         material.equatorial_to_world = celestial.equatorial_to_world;
398:         material.settings.x =
399:             star_visibility(celestial.sun_altitude_degrees) * celestial.weather_transmission;
400:     }
401: }
