556: pub(in crate::presentation) fn keep_celestial_visuals_centered(
557:     camera: Single<&GlobalTransform, With<TacticalGameplayCamera>>,
558:     celestial: Res<PresentedCelestialLighting>,
559:     mut moon: Query<&mut Transform, With<TacticalMoon>>,
560: ) {
561:     let Some(celestial) = celestial.snapshot.as_ref() else {
562:         return;
563:     };
564:     let Ok(mut moon_transform) = moon.single_mut() else {
565:         return;
566:     };
567:     moon_transform.translation =
568:         camera.translation() + celestial.moon_direction * MOON_DISTANCE_METRES;
569:     moon_transform.rotation = moon_near_side_rotation(celestial.moon_direction);
570: }
571: 
572: /// Keeps the map's zero-longitude near side pointed at the observer while
573: /// retaining a stable celestial north. This is the bounded synchronous-rotation
574: /// model appropriate at the Moon's sub-pixel libration scale here.
575: fn moon_near_side_rotation(direction_to_moon: Vec3) -> Quat {
576:     let local_x_world = -direction_to_moon.normalize();
577:     let mut local_z_world = Vec3::Y - local_x_world * Vec3::Y.dot(local_x_world);
578:     if local_z_world.length_squared() < 1.0e-4 {
579:         local_z_world = Vec3::Z - local_x_world * Vec3::Z.dot(local_x_world);
580:     }
581:     local_z_world = local_z_world.normalize();
582:     let local_y_world = local_z_world.cross(local_x_world).normalize();
583:     Quat::from_mat3(&Mat3::from_cols(
584:         local_x_world,
585:         local_y_world,
586:         local_z_world,
587:     ))
588: }
