598: fn sky_weather_transmission(environment: &SceneEnvironment) -> f32 {
599:     let intensity = crate::presentation::procedural::bps(environment.weather.intensity_bps);
600:     let precipitation = match environment.weather.precipitation {
601:         Precipitation::Clear => 1.0,
602:         Precipitation::Rain => 0.12 * (1.0 - intensity * 0.7),
603:         Precipitation::Snow => 0.2 * (1.0 - intensity * 0.6),
604:     };
605:     precipitation * cloud_solar_transmission(environment.weather)
606: }
