608: pub(super) fn scene_exposure_ev100(
609:     sun_altitude_degrees: f32,
610:     moon_altitude_degrees: f32,
611:     lunar_illumination: f32,
612: ) -> f32 {
613:     if sun_altitude_degrees >= 12.0 {
614:         15.0
615:     } else if sun_altitude_degrees >= 0.0 {
616:         11.0 + sun_altitude_degrees / 3.0
617:     } else if sun_altitude_degrees >= -6.0 {
618:         8.0 + (sun_altitude_degrees + 6.0) * 0.5
619:     } else if sun_altitude_degrees >= -12.0 {
620:         4.0 + (sun_altitude_degrees + 12.0) * (4.0 / 6.0)
621:     } else if sun_altitude_degrees >= -18.0 {
622:         let night_target = night_exposure_ev100(moon_altitude_degrees, lunar_illumination);
623:         let transition = smoothstep(12.0, 18.0, -sun_altitude_degrees);
624:         4.0 + (night_target - 4.0) * transition
625:     } else {
626:         // Preserve genuinely dark, obstacle-obscuring moonless nights. A risen
627:         // moon lowers EV100 as the eye adapts to reveal the 0.25-lux surface
628:         // response; a below-horizon moon does neither. The former positive
629:         // sign darkened the camera as lunar illumination increased.
630:         night_exposure_ev100(moon_altitude_degrees, lunar_illumination)
631:     }
632: }
633: 
634: fn night_exposure_ev100(moon_altitude_degrees: f32, lunar_illumination: f32) -> f32 {
635:     -0.5 - 0.75 * lunar_illumination * smoothstep(-2.0, 8.0, moon_altitude_degrees)
636: }
637: 
638: fn star_visibility(sun_altitude_degrees: f32) -> f32 {
639:     1.0 - smoothstep(-15.0, -7.0, sun_altitude_degrees)
640: }
641: 
642: fn smoothstep(edge0: f32, edge1: f32, value: f32) -> f32 {
643:     let t = ((value - edge0) / (edge1 - edge0)).clamp(0.0, 1.0);
644:     t * t * (3.0 - 2.0 * t)
645: }
