154:             )
155:             .map(|()| true)
156:         };
157:         match presented {
158:             Ok(true) => {
159:                 prepared_first_terrain = true;
160:                 commands
161:                     .entity(entity)
162:                     .remove::<PendingTerrainPresentation>();
163:             }
164:             Ok(false) => {}
165:             Err(error) => warn!(%error, ?entity, "Invalid terrain ground texture"),
166:         }
167:     }
168:     if prepared_first_terrain && let Some(startup) = startup.as_mut() {
169:         startup.mark_terrain_prepared_once();
170:     }
171: }
