173: /// Moves the bounded high-resolution patch in one-metre increments. All
174: /// heights are sampled in world space, so snapping changes only the fully
175: /// morphed transition ring rather than making the surface swim under the player.
176: pub(in crate::presentation) fn update_terrain_detail_patch(
177:     camera: Single<&GlobalTransform, With<TacticalGameplayCamera>>,
178:     active: Res<ActiveTacticalScene>,
179:     scenes: Query<(
180:         &SceneTerrain,
181:         &SceneEnvironment,
182:         Option<&TerrainLandformRecipe>,
183:     )>,
184:     mut patches: Query<(
185:         &ScenePresentationOf,
186:         &mut TerrainDetailPatch,
187:         &Mesh3d,
188:         &mut TerrainTriangleCount,
189:     )>,
190:     vista: Res<ActiveVistaSurface>,
191:     mut meshes: ResMut<Assets<Mesh>>,
192: ) {
193:     let camera_position = camera.translation().xz();
194:     let Some(desired_centre) = ScenePlanPoint::from_metres(
195:         (camera_position / DETAIL_PATCH_SNAP_METRES).round() * DETAIL_PATCH_SNAP_METRES,
196:     ) else {
197:         return;
198:     };
199:     for (source, mut patch, mesh_handle, mut triangle_count) in &mut patches {
200:         if active.entity.is_some_and(|entity| entity != source.0)
201:             || (patch.vista_revision == vista.revision()
202:                 && patch
203:                     .centre
204:                     .metres()
205:                     .distance_squared(desired_centre.metres())
206:                     < DETAIL_PATCH_SNAP_METRES * DETAIL_PATCH_SNAP_METRES * 0.25)
207:         {
208:             continue;
209:         }
210:         let Ok((terrain, environment, landform)) = scenes.get(source.0) else {
211:             continue;
212:         };
213:         if urban::GroundTopology::for_scene(terrain, environment, &vista)
214:             == urban::GroundTopology::Canonical
215:         {
216:             continue;
217:         }
218:         let Some(mut mesh) = meshes.get_mut(&mesh_handle.0) else {
219:             continue;
220:         };

221:         let replacement = terrain_detail_patch_mesh(
222:             terrain,
223:             environment,
224:             &vista,
225:             desired_centre,
226:             landform.map(|recipe| recipe.transition_collar()),
227:         );
228:         triangle_count.0 = mesh_triangle_count(&replacement);
229:         *mesh = replacement;
230:         patch.centre = desired_centre;
231:         patch.vista_revision = vista.revision();
232:     }
233: }
234: 
235: fn terrain_detail_patch_mesh(
236:     terrain: &SceneTerrain,
237:     environment: &SceneEnvironment,
238:     vista: &ActiveVistaSurface,
239:     centre: ScenePlanPoint,
240:     transition_collar: Option<TerrainTransitionCollar>,
241: ) -> Mesh {
242:     // Canonical urban geometry owns the entire playable surface. Coverage hides
243:     // this moving patch, so preserve its refresh slot without sampling a mesh.
244:     if urban::GroundTopology::for_scene(terrain, environment, vista)
245:         == urban::GroundTopology::Canonical
246:     {
247:         return Mesh::new(
248:             PrimitiveTopology::TriangleList,
249:             RenderAssetUsages::MAIN_WORLD | RenderAssetUsages::RENDER_WORLD,
250:         )
251:         .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, Vec::<[f32; 3]>::new())
252:         .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, Vec::<[f32; 3]>::new())
253:         .with_inserted_attribute(Mesh::ATTRIBUTE_UV_0, Vec::<[f32; 2]>::new())
254:         .with_inserted_indices(Indices::U32(Vec::new()));
255:     }
256:     let diameter_steps =
257:         (DETAIL_PATCH_RADIUS_METRES * 2.0 / DETAIL_PATCH_SPACING_METRES).round() as usize;
258:     let width = diameter_steps + 1;
259:     let centre = centre.metres();
260:     let minimum = centre - Vec2::splat(DETAIL_PATCH_RADIUS_METRES);
261:     let mut positions = Vec::with_capacity(width * width);
262:     let mut uvs = Vec::with_capacity(width * width);
263:     let mut valid = Vec::with_capacity(width * width);
264: 
265:     for z in 0..width {
266:         for x in 0..width {
267:             let metres = minimum + Vec2::new(x as f32, z as f32) * DETAIL_PATCH_SPACING_METRES;
268:             let point = ScenePlanPoint::from_metres(metres);
269:             let fine_height = point.and_then(|point| {
270:                 vista.presented_height_at(&environment.scene_digest, terrain, point)
271:             });
272:             let coarse_height = point
273:                 .and_then(|point| terrain.coarse_height_at(point))
274:                 .or(fine_height);
275:             let radius = metres.distance(centre);
276:             let morph = 1.0
277:                 - terrain_smoothstep(
278:                     DETAIL_PATCH_MORPH_START_METRES,
279:                     DETAIL_PATCH_RADIUS_METRES - DETAIL_PATCH_SPACING_METRES * 1.5,
280:                     radius,
281:                 );
282:             let height = fine_height
283:                 .zip(coarse_height)
284:                 .map(|(fine, coarse)| coarse.metres() + (fine.metres() - coarse.metres()) * morph)
285:                 .filter(|height| height.is_finite());
286:             positions.push([metres.x, height.unwrap_or_default(), metres.y]);
287:             uvs.push([
288:                 (metres.x / terrain.width() + 0.5).clamp(0.0, 1.0),
289:                 (metres.y / terrain.depth() + 0.5).clamp(0.0, 1.0),
290:             ]);
291:             valid.push(height.is_some());
292:         }
293:     }
294: 
295:     let mut indices = Vec::with_capacity(diameter_steps * diameter_steps * 6);
296:     for z in 0..diameter_steps {
297:         for x in 0..diameter_steps {
298:             let i = z * width + x;
299:             if !valid[i] || !valid[i + 1] || !valid[i + width] || !valid[i + width + 1] {
300:                 continue;
301:             }
302:             volumetric::append_detail_cell(
303:                 &mut indices,
304:                 &positions,
305:                 width,
306:                 i as u32,
307:                 centre,
308:                 transition_collar,
309:             );
310:         }
311:     }
312: 
313:     let mut mesh = Mesh::new(
314:         PrimitiveTopology::TriangleList,
315:         RenderAssetUsages::MAIN_WORLD | RenderAssetUsages::RENDER_WORLD,
316:     );
317:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
318:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
319:     mesh.insert_indices(Indices::U32(indices));
320:     mesh.with_computed_area_weighted_normals()
321: }
