324: // is the authoritative scene generator in adventuresim-tactical-core.
325: #[cfg(test)]
326: #[derive(Debug, Clone, Copy)]
327: struct TerrainShapeSample {
328:     downhill: Vec2,
329:     slope: f32,
330:     concavity: f32,
331: }
332: 
333: #[expect(
334:     clippy::too_many_arguments,
335:     reason = "terrain relief keeps the sampled point, source layers, vista seam, and obstacle influences explicit"
336: )]
337: #[cfg(test)]
338: fn terrain_surface_relief(
339:     seed: Seed,
340:     point: Vec2,
341:     terrain: &SceneTerrain,
342:     ground: Option<&SceneGround>,
343:     environment: &SceneEnvironment,
344:     vista: &ActiveVistaSurface,
345:     tree_positions: &[Vec2],
346:     rock_influences: &[DetailRockInfluence],
347: ) -> f32 {
348:     let surface = ScenePlanPoint::from_metres(point)
349:         .and_then(|point| ground.and_then(|ground| ground.ground_at(point)));
350:     if surface.is_some_and(|surface| surface.substrate == GroundSubstrate::Water) {
351:         return 0.0;
352:     }
353:     if surface.is_some_and(|surface| surface.substrate == GroundSubstrate::Road) {
354:         return road_surface_relief(seed, point, ground.expect("road came from SceneGround"));
355:     }
356: 
357:     let broad = signed_ground_noise(streams::BROAD.seed(seed, &[]), point / 3.2) * 0.024;
358:     let fine = signed_ground_noise(streams::FINE.seed(seed, &[]), point / 0.92) * 0.009;
359:     let clod_strength = match surface.map(|surface| surface.substrate) {
360:         Some(GroundSubstrate::Stone) => 0.0,
361:         Some(GroundSubstrate::Gravel) => 0.25,
362:         Some(GroundSubstrate::Mud | GroundSubstrate::Soil) => 1.0,
363:         Some(GroundSubstrate::Road | GroundSubstrate::Water) => unreachable!(),
364:         None => 1.0,
365:     };
366:     let clods = terrain_clod_relief(seed, point) * clod_strength;
367:     let shape = terrain_shape_sample(
368:         &environment.scene_digest,
369:         terrain,
370:         vista,
371:         point,
372:         DETAIL_PATCH_SPACING_METRES * 3.0,
373:     );
374:     let process_relief = shape.map_or(0.0, |shape| {
375:         drainage_relief(seed, point, shape, environment)
376:             + soil_creep_relief(seed, point, shape)
377:             + shape.concavity.clamp(-0.018, 0.024)
378:     });
379:     let roots = tree_root_relief(seed, point, tree_positions);
380:     let rock_contact = boulder_ground_relief(seed, point, shape, rock_influences);
381:     let rock_strata = match surface.map(|surface| surface.substrate) {
382:         Some(GroundSubstrate::Stone) => rocky_substrate_relief(seed, point, shape, 1.0),
383:         Some(GroundSubstrate::Gravel) => rocky_substrate_relief(seed, point, shape, 0.62),
384:         _ => 0.0,
385:     };
386:     let substrate_strength = match surface.map(|surface| surface.substrate) {
387:         Some(GroundSubstrate::Stone) => 0.54,
388:         Some(GroundSubstrate::Gravel) => 0.68,
389:         Some(GroundSubstrate::Mud) => 0.78,
390:         Some(GroundSubstrate::Soil) => 1.0,
391:         Some(GroundSubstrate::Road | GroundSubstrate::Water) => unreachable!(),
392:         None => 0.62,
393:     };
394:     let cover_strength = match surface.map(|surface| surface.cover) {
395:         Some(GroundCover::Reeds) => 0.35,
396:         Some(GroundCover::LooseStone) => 0.78,
397:         _ => 1.0,
398:     };
399:     ((broad + fine + clods + process_relief) * substrate_strength * cover_strength
400:         + roots
401:         + rock_contact
402:         + rock_strata)
403:         .clamp(DETAIL_RELIEF_MINIMUM_METRES, DETAIL_RELIEF_MAXIMUM_METRES)
404: }
