417: #[cfg(test)]
418: fn terrain_shape_sample(
419:     scene_digest: &str,
420:     terrain: &SceneTerrain,
421:     vista: &ActiveVistaSurface,
422:     point: Vec2,
423:     radius: f32,
424: ) -> Option<TerrainShapeSample> {
425:     let centre =
426:         vista.presented_height_at(scene_digest, terrain, ScenePlanPoint::from_metres(point)?)?;
427:     let east = vista.presented_height_at(
428:         scene_digest,
429:         terrain,
430:         ScenePlanPoint::from_metres(point + Vec2::X * radius)?,
431:     )?;
432:     let west = vista.presented_height_at(
433:         scene_digest,
434:         terrain,
435:         ScenePlanPoint::from_metres(point - Vec2::X * radius)?,
436:     )?;
437:     let north = vista.presented_height_at(
438:         scene_digest,
439:         terrain,
440:         ScenePlanPoint::from_metres(point + Vec2::Y * radius)?,

441:     )?;
442:     let south = vista.presented_height_at(
443:         scene_digest,
444:         terrain,
445:         ScenePlanPoint::from_metres(point - Vec2::Y * radius)?,
446:     )?;
447:     let gradient = Vec2::new(
448:         east.metres() - west.metres(),
449:         north.metres() - south.metres(),
450:     ) / (radius * 2.0);
451:     let slope = gradient.length();
452:     let downhill = if slope > 0.000_1 {
453:         -gradient / slope
454:     } else {
455:         Vec2::X
456:     };
457:     // Positive values are bowls where transported material plausibly settles;
458:     // negative values are exposed convexities. Keep this a small residual,
459:     // rather than changing the authoritative broad landform.
460:     let concavity = ((east.metres() + west.metres() + north.metres() + south.metres()) * 0.25
461:         - centre.metres())
462:         * 0.18;
463:     Some(TerrainShapeSample {
464:         downhill,
465:         slope,
466:         concavity,
467:     })
468: }
