471: fn drainage_relief(
472:     seed: Seed,
473:     point: Vec2,
474:     shape: TerrainShapeSample,
475:     environment: &SceneEnvironment,
476: ) -> f32 {
477:     let slope_weight = terrain_smoothstep(0.012, 0.16, shape.slope);
478:     if slope_weight <= 0.0 {
479:         return 0.0;
480:     }
481:     let normal = Vec2::new(-shape.downhill.y, shape.downhill.x);
482:     let warp = signed_ground_noise(streams::RILL_WARP.seed(seed, &[]), point / 5.5) * 0.85;
483:     let spacing =
484:         2.6 + ground_mask_noise(streams::RILL_SPACING.seed(seed, &[]), point / 11.0) * 1.4;
485:     let across = point.dot(normal) + warp;
486:     let distance = periodic_distance(across, spacing);
487:     let channel = 1.0 - terrain_smoothstep(0.08, 0.34, distance);
488:     let shoulder =
489:         terrain_smoothstep(0.18, 0.42, distance) * (1.0 - terrain_smoothstep(0.42, 0.72, distance));
490:     let moisture = bps(environment.weather.ground_moisture_bps);
491:     (-channel * (0.026 + moisture * 0.012) + shoulder * 0.009) * slope_weight
492: }
