495: fn soil_creep_relief(seed: Seed, point: Vec2, shape: TerrainShapeSample) -> f32 {
496:     let slope_weight = terrain_smoothstep(0.035, 0.22, shape.slope);
497:     let warp = signed_ground_noise(streams::CREEP_WARP.seed(seed, &[]), point / 7.0) * 0.55;
498:     let downhill_coordinate = point.dot(shape.downhill) + warp;
499:     let distance = periodic_distance(downhill_coordinate, 3.1);
500:     let ridge = 1.0 - terrain_smoothstep(0.12, 0.52, distance);
501:     ridge * 0.019 * slope_weight
502: }
