504: /// Exposed rock is organized into broad ledges with sparse intersecting
505: /// fractures. The wavelengths stay above the detail grid spacing, so this
506: /// adds readable form rather than sub-pixel noise.
507: #[cfg(test)]
508: fn rocky_substrate_relief(
509:     seed: Seed,
510:     point: Vec2,
511:     shape: Option<TerrainShapeSample>,
512:     strength: f32,
513: ) -> f32 {
514:     let fallback_angle = streams::STRATA_DIRECTION
515:         .rng(seed, &[])
516:         .inclusive_unit_f32()
517:         * core::f32::consts::TAU;
518:     let downhill = shape
519:         .map(|shape| shape.downhill)
520:         .unwrap_or(Vec2::new(fallback_angle.cos(), fallback_angle.sin()));
521:     let across = Vec2::new(-downhill.y, downhill.x);
522:     let slope_weight = shape
523:         .map(|shape| terrain_smoothstep(0.018, 0.18, shape.slope))
524:         .unwrap_or(0.35);
525:     let warp = signed_ground_noise(streams::STRATA_WARP.seed(seed, &[]), point / 6.5) * 0.72;
526:     let contour = point.dot(downhill) + warp;
527:     let ledge_distance = periodic_distance(contour, 2.15);
528:     let shelf =
529:         (1.0 - terrain_smoothstep(0.08, 0.48, ledge_distance)) * (0.019 + slope_weight * 0.029);
530: 
531:     let fracture_a = periodic_distance(
532:         point.dot(across)
533:             + signed_ground_noise(streams::FRACTURE_A.seed(seed, &[]), point / 4.8) * 0.4,
534:         3.7,
535:     );
536:     let diagonal = (across * 0.72 + downhill * 0.69).normalize_or_zero();
537:     let fracture_b = periodic_distance(
538:         point.dot(diagonal)
539:             + signed_ground_noise(streams::FRACTURE_B.seed(seed, &[]), point / 5.6) * 0.34,
540:         5.3,
541:     );
542:     let crack = (1.0 - terrain_smoothstep(0.035, 0.17, fracture_a))
543:         .max((1.0 - terrain_smoothstep(0.035, 0.15, fracture_b)) * 0.72);
544:     (shelf - crack * 0.019) * strength
545: }
