547: /// Formula-level regression for the boulder socket now baked by tactical-core
548: /// into the authoritative terrain: a shallow socket, contact apron,
549: /// and downhill debris tail visually seat each generated rock in the landform.
550: #[cfg(test)]
551: fn boulder_ground_relief(
552:     seed: Seed,
553:     point: Vec2,
554:     shape: Option<TerrainShapeSample>,
555:     rocks: &[DetailRockInfluence],
556: ) -> f32 {
557:     let mut relief = 0.0;
558:     for rock in rocks {
559:         let offset = point - rock.centre;
560:         let distance = offset.length();
561:         let radius = rock.radius.max(0.35);
562:         if distance > radius * 5.0 {
563:             continue;
564:         }
565:         let rock_seed = streams::ROCK_INFLUENCE.seed(
566:             seed,
567:             &[
568:                 u64::from(rock.centre.x.to_bits()),
569:                 u64::from(rock.centre.y.to_bits()),
570:             ],
571:         );
572:         let fallback_angle = streams::ROCK_DOWNHILL
573:             .rng(rock_seed, &[])
574:             .inclusive_unit_f32()
575:             * core::f32::consts::TAU;
576:         let downhill = shape
577:             .map(|shape| shape.downhill)
578:             .unwrap_or(Vec2::new(fallback_angle.cos(), fallback_angle.sin()));
579:         let across_axis = Vec2::new(-downhill.y, downhill.x);
580: 
581:         let socket = (1.0 - terrain_smoothstep(radius * 0.48, radius * 1.08, distance)) * -0.042;
582:         let apron = terrain_smoothstep(radius * 0.72, radius * 1.04, distance)
583:             * (1.0 - terrain_smoothstep(radius * 1.04, radius * 1.72, distance))
584:             * 0.033;
585: 
586:         let downstream = offset.dot(downhill);
587:         let across = offset.dot(across_axis).abs();
588:         let tail_length =
589:             radius * (3.2 + streams::ROCK_TAIL.rng(rock_seed, &[]).inclusive_unit_f32() * 1.1);
590:         let longitudinal = terrain_smoothstep(radius * 0.45, radius * 0.95, downstream)
591:             * (1.0 - terrain_smoothstep(tail_length * 0.62, tail_length, downstream));
592:         let tail_width = radius * 0.42 + downstream.max(0.0) * 0.24;
593:         let lateral = 1.0 - terrain_smoothstep(tail_width * 0.42, tail_width, across);
594:         let granular = 0.72
595:             + ground_mask_noise(
596:                 streams::ROCK_DEBRIS.seed(rock_seed, &[]),
597:                 Vec2::new(downstream / 1.7, across / 0.8),
598:             ) * 0.28;
599:         let debris_tail = longitudinal * lateral * granular * 0.034;
600: 
601:         relief += socket + apron + debris_tail;
602:     }
603:     relief.clamp(-0.055, 0.07)
604: }
605: 
606: #[cfg(test)]
607: fn periodic_distance(value: f32, period: f32) -> f32 {
608:     let wrapped = value.rem_euclid(period);
609:     wrapped.min(period - wrapped)
610: }
