612: #[cfg(test)]
613: fn tree_root_relief(seed: Seed, point: Vec2, tree_positions: &[Vec2]) -> f32 {
614:     let mut relief = 0.0;
615:     for &tree in tree_positions {
616:         let offset = point - tree;
617:         let radius = offset.length();
618:         if radius > 8.0 {
619:             continue;
620:         }
621:         let tree_seed = streams::TREE_ROOTS.seed(
622:             seed,
623:             &[u64::from(tree.x.to_bits()), u64::from(tree.y.to_bits())],
624:         );
625:         let mound = (-(radius / 1.35).powi(2)).exp() * 0.045;
626:         let basin = terrain_smoothstep(0.9, 1.8, radius)
627:             * (1.0 - terrain_smoothstep(5.2, 7.7, radius))
628:             * -0.012;
629:         let angle = offset.y.atan2(offset.x);
630:         let mut ridges = 0.0_f32;
631:         for root in 0..7_u64 {
632:             let mut random = streams::ROOT_SHAPE.rng(tree_seed, &[root]);
633:             let origin = random.inclusive_unit_f32() * core::f32::consts::TAU;
634:             let phase = random.inclusive_unit_f32() * core::f32::consts::TAU;
635:             let length = 4.8 + random.inclusive_unit_f32() * 2.9;
636:             if radius > length || radius < 0.28 {
637:                 continue;
638:             }
639:             let curved_angle = origin + (radius * 0.9 + phase).sin() * 0.11;
640:             let angular_distance = wrapped_angle_difference(angle, curved_angle).abs() * radius;
641:             let width = 0.16 + radius * 0.045;
642:             let ridge = 1.0 - terrain_smoothstep(width * 0.3, width, angular_distance);
643:             let taper = 1.0 - terrain_smoothstep(length * 0.58, length, radius);
644:             ridges = ridges.max(ridge * taper * (0.082 - radius * 0.007).max(0.025));
645:         }
646:         relief += mound + basin + ridges;
647:     }
648:     relief.clamp(-0.02, 0.115)
649: }
