651: #[cfg(test)]
652: fn wrapped_angle_difference(left: f32, right: f32) -> f32 {
653:     (left - right + core::f32::consts::PI).rem_euclid(core::f32::consts::TAU)
654:         - core::f32::consts::PI
655: }
