657: #[cfg(test)]
658: fn road_surface_relief(seed: Seed, point: Vec2, ground: &SceneGround) -> f32 {
659:     let is_road = |sample: Vec2| {
660:         ScenePlanPoint::from_metres(sample)

661:             .and_then(|point| ground.ground_at(point))
662:             .is_some_and(|surface| surface.substrate == GroundSubstrate::Road)
663:     };
664:     let mut tangent = Vec2::X;
665:     let mut best_score: Option<i32> = None;
666:     for direction_index in 0..8 {
667:         let angle = direction_index as f32 * core::f32::consts::PI / 8.0;
668:         let candidate = Vec2::new(angle.cos(), angle.sin());
669:         let score = [0.75_f32, 1.5, 2.5]
670:             .into_iter()
671:             .map(|distance| {
672:                 i32::from(is_road(point + candidate * distance))
673:                     + i32::from(is_road(point - candidate * distance))
674:             })
675:             .sum();
676:         if best_score.is_none_or(|best| score > best) {
677:             best_score = Some(score);
678:             tangent = candidate;
679:         }
680:     }
681:     let normal = Vec2::new(-tangent.y, tangent.x);
682:     let edge_distance = |direction: f32| {
683:         (1..=24)
684:             .map(|step| step as f32 * 0.25)
685:             .find(|distance| !is_road(point + normal * direction * *distance))
686:             .unwrap_or(6.0)
687:     };
688:     let positive_edge = edge_distance(1.0);
689:     let negative_edge = edge_distance(-1.0);
690:     let half_width = ((positive_edge + negative_edge) * 0.5).max(0.6);
691:     let across = (negative_edge - positive_edge) * 0.5;
692:     let rut_offset = (half_width * 0.46).clamp(0.38, 0.82);
693:     let rut_width = (half_width * 0.12).clamp(0.14, 0.27);
694:     let gaussian = |distance: f32| (-(distance / rut_width).powi(2) * 1.7).exp();
695:     let ruts = gaussian(across - rut_offset) + gaussian(across + rut_offset);
696:     let crown = (1.0 - (across / half_width).powi(2)).max(0.0) * 0.026;
697:     let travelled = point.dot(tangent);
698:     let irregularity = signed_ground_noise(
699:         streams::ROAD_RUT.seed(seed, &[]),
700:         Vec2::new(travelled / 2.4, across / 1.1),
701:     ) * 0.004;
702:     (crown - ruts * 0.038 + irregularity).clamp(-0.048, 0.032)
703: }
704: 
705: fn terrain_smoothstep(edge0: f32, edge1: f32, value: f32) -> f32 {
706:     let t = ((value - edge0) / (edge1 - edge0)).clamp(0.0, 1.0);
707:     t * t * (3.0 - 2.0 * t)
708: }
