11: const GROUND_PRESENTATION_SAMPLES_PER_CELL: usize = 6;
12: const BROAD_WARP_NOISE_SCALE: f32 = 0.38;
13: const FINE_WARP_NOISE_SCALE: f32 = 0.93;
