15: pub(super) fn ground_surface_pixel(sample: GroundSurface) -> [u8; 4] {
16:     let cover = match sample.cover {
17:         GroundCover::Bare => 0,
18:         GroundCover::TallGrass => 1,
19:         GroundCover::LeafLitter => 2,
20:         GroundCover::LooseStone => 3,
21:         GroundCover::Reeds => 4,
22:     };
23:     let substrate = match sample.substrate {
24:         GroundSubstrate::Soil => 0,
25:         GroundSubstrate::Stone => 1,
26:         GroundSubstrate::Gravel => 2,
27:         GroundSubstrate::Mud => 3,
28:         GroundSubstrate::Road => 4,
29:         GroundSubstrate::Water => 5,
30:     };
31:     [
32:         cover,
33:         substrate,
34:         adventuresim_world_schema::UnitBasisPoints::saturating(sample.cover_density_bps)
35:             .scale_u32_floor(255) as u8,
36:         sample.cover_height_cm.min(255) as u8,
37:     ]
38: }
