41: pub(super) fn ground_mask_noise(seed: Seed, point: Vec2) -> f32 {
42:     let cell = point.floor();
43:     let local = point - cell;
44:     let curve = local * local * (Vec2::splat(3.0) - local * 2.0);
45:     let hash = |offset: Vec2| {
46:         let coordinate = cell + offset;
47:         let x = i64::from(coordinate.x as i32) as u64;
48:         let y = i64::from(coordinate.y as i32) as u64;
49:         terrain_streams::GROUND_MASK_LATTICE
50:             .rng(seed, &[x, y])
51:             .inclusive_unit_f32()
52:     };
53:     let bottom = hash(Vec2::ZERO).lerp(hash(Vec2::X), curve.x);
54:     let top = hash(Vec2::Y).lerp(hash(Vec2::ONE), curve.x);
55:     bottom.lerp(top, curve.y)
56: }
