58: pub(super) fn organic_ground_pixels(
59:     ground: &SceneGround,
60:     seed: Seed,
61: ) -> GeometryResult<(u32, u32, Vec<u8>)> {
62:     let source_width = ground.grid_width();
63:     let source_depth = ground.grid_depth();
64:     let width = (source_width - 1) * GROUND_PRESENTATION_SAMPLES_PER_CELL + 1;
65:     let depth = (source_depth - 1) * GROUND_PRESENTATION_SAMPLES_PER_CELL + 1;
66:     let mut pixels = Vec::with_capacity(width * depth * 4);
67:     let scale = GROUND_PRESENTATION_SAMPLES_PER_CELL as f32;
68:     let maximum = Vec2::new((source_width - 1) as f32, (source_depth - 1) as f32);
69:     let broad_offset = Vec2::new(17.3, -9.1);
70:     let fine_x_offset = Vec2::new(31.7, 5.9);
71:     let fine_y_offset = Vec2::new(-7.7, 23.1);
72:     let broad_x = GroundMaskNoise::new(
73:         seed.xor_word(0x2f31_9a87),
74:         Vec2::ZERO,
75:         maximum * BROAD_WARP_NOISE_SCALE,
76:     );
77:     let broad_y = GroundMaskNoise::new(
78:         seed.xor_word(0x91b7_43cd),
79:         broad_offset,
80:         maximum * BROAD_WARP_NOISE_SCALE + broad_offset,
81:     );
82:     let fine_x = GroundMaskNoise::new(
83:         seed.xor_word(0x6d25_e9f1),
84:         fine_x_offset,
85:         maximum * FINE_WARP_NOISE_SCALE + fine_x_offset,
86:     );
87:     let fine_y = GroundMaskNoise::new(
88:         seed.xor_word(0xc4ab_1283),
89:         fine_y_offset,
90:         maximum * FINE_WARP_NOISE_SCALE + fine_y_offset,
91:     );
92:     for z in 0..depth {
93:         for x in 0..width {
94:             let point = Vec2::new(x as f32 / scale, z as f32 / scale);
95:             let broad_point = point * BROAD_WARP_NOISE_SCALE;
96:             let fine_point = point * FINE_WARP_NOISE_SCALE;
97:             let broad_warp = Vec2::new(
98:                 broad_x.sample(broad_point),
99:                 broad_y.sample(broad_point + broad_offset),
100:             ) * 2.0
101:                 - Vec2::ONE;
102:             let fine_warp = Vec2::new(
103:                 fine_x.sample(fine_point + fine_x_offset),
104:                 fine_y.sample(fine_point + fine_y_offset),
105:             ) * 2.0
106:                 - Vec2::ONE;
107:             let warped = point + broad_warp * 0.78 + fine_warp * 0.22;
108:             let source_x = (warped.x.round() as isize).clamp(0, source_width as isize - 1) as usize;
109:             let source_z = (warped.y.round() as isize).clamp(0, source_depth as isize - 1) as usize;
110:             pixels.extend_from_slice(&ground_surface_pixel(
111:                 ground
112:                     .urban
113:                     .surface_at(ScenePlanPoint::try_from(
114:                         point * ground.grid_scale()
115:                             - Vec2::new(ground.width(), ground.depth()) * 0.5,
116:                     )?)
117:                     .unwrap_or(ground.samples()[source_z * source_width + source_x]),
118:             ));
119:         }
120:     }
121:     encode_canopy_floor_distance(ground, width, depth, &mut pixels);
122:     Ok((width as u32, depth as u32, pixels))
123: }
124: 
125: pub(in crate::presentation) fn grass_cover_mask_pixels(
126:     ground: &SceneGround,
127:     seed: Seed,
128: ) -> GeometryResult<(u32, u32, Vec<u8>)> {
129:     let (width, height, ground_pixels) = organic_ground_pixels(ground, seed)?;
130:     let mut mask = vec![0_u8; width as usize * height as usize];
131:     let metres_per_pixel = ground.grid_scale() / GROUND_PRESENTATION_SAMPLES_PER_CELL as f32;
132:     let radius = (4.8 / metres_per_pixel).ceil().max(1.0) as usize;
133:     let width_usize = width as usize;
134:     let height_usize = height as usize;
135:     // The playable rectangle is a data-authority boundary, not a vegetation
136:     // boundary. Only authored non-grass pixels seed this distance field.
137:     let distance = chamfer_distance_to(
138:         width_usize,
139:         height_usize,
140:         |index| ground_pixels[index * 4] != GroundCover::TallGrass as u8,
141:         radius,
142:     );
143:     for z in 0..height as usize {
144:         for x in 0..width as usize {
145:             let pixel = (z * width as usize + x) * 4;
146:             if ground_pixels[pixel] != GroundCover::TallGrass as u8 {
147:                 continue;
148:             }
149:             let density = ground_pixels[pixel + 2];
150:             let feather = (distance[z * width_usize + x] as f32 / radius as f32)
151:                 .clamp(0.0, 1.0)
152:                 .powf(1.28);
153:             mask[z * width as usize + x] = (f32::from(density) * feather) as u8;
154:         }
155:     }
156:     Ok((width, height, mask))
157: }
