63:         &self,
64:         terrain: &SceneTerrain,
65:         landform: Option<&TerrainLandformRecipe>,
66:     ) -> Mesh {
67:         match self.topology {
68:             GroundTopology::Canonical => urban_playable_mesh(terrain, landform),
69:             GroundTopology::Sampled => landform.map_or_else(
70:                 || terrain.coarse_mesh(),
71:                 |recipe| terrain.coarse_mesh_with_transition(recipe.transition_collar()),
72:             ),
73:         }
74:     }
75: }
