77: pub(in crate::presentation) fn urban_playable_mesh(
78:     terrain: &SceneTerrain,
79:     landform: Option<&TerrainLandformRecipe>,
80: ) -> Mesh {
81:     if let Some(mesh) = super::super::vista::owned::playable_mesh(
82:         terrain,
83:         landform.map(|recipe| recipe.transition_collar()),
84:     ) {
85:         return mesh;
86:     }
87:     landform.map_or_else(
88:         || terrain.mesh(),
89:         |recipe| terrain.mesh_with_transition(recipe.transition_collar()),
90:     )
91: }
