97: fn update_coverage(
98:     mut commands: Commands,
99:     vista: Res<ActiveVistaSurface>,
100:     scenes: Query<(
101:         &SceneTerrain,
102:         &SceneEnvironment,
103:         Option<&TerrainLandformRecipe>,
104:     )>,
105:     mut bases: Query<
106:         (
107:             Entity,
108:             &ScenePresentationOf,
109:             &mut Mesh3d,
110:             &MeshMaterial3d<TacticalTerrainMaterial>,
111:             &mut TerrainTriangleCount,
112:             Option<&GroundCoverage>,
113:         ),
114:         With<TerrainMaterialPresentation>,
115:     >,
116:     mut details: Query<(&ScenePresentationOf, &mut Visibility), With<TerrainDetailPatch>>,
117:     mut meshes: ResMut<Assets<Mesh>>,
118:     mut materials: ResMut<Assets<TacticalTerrainMaterial>>,
119: ) {
120:     for (entity, source, mut mesh, material, mut triangle_count, previous) in &mut bases {
121:         let Ok((terrain, environment, landform)) = scenes.get(source.0) else {
122:             continue;
123:         };
124:         let topology = GroundTopology::for_scene(terrain, environment, &vista);
125:         let cutout = if topology == GroundTopology::Canonical {
126:             0.0
127:         } else {
128:             1.0
129:         };
130:         if materials
131:             .get(&material.0)
132:             .is_some_and(|material| material.extension.detail_patch.x != cutout)
133:             && let Some(mut material) = materials.get_mut(&material.0)
134:         {
135:             material.extension.detail_patch.x = cutout;
136:         }
137:         let changed = previous.map_or(topology == GroundTopology::Canonical, |previous| {
138:             previous.topology != topology || previous.revision != vista.revision()
139:         });
140:         if changed {
141:             let replacement = if topology == GroundTopology::Canonical {
142:                 urban_playable_mesh(terrain, landform)
143:             } else {
144:                 landform.map_or_else(
145:                     || terrain.coarse_mesh(),
146:                     |recipe| terrain.coarse_mesh_with_transition(recipe.transition_collar()),
147:                 )
148:             };
149:             triangle_count.0 = mesh_triangle_count(&replacement);
150:             mesh.0 = meshes.add(replacement);
151:             commands.entity(entity).insert(GroundCoverage {
152:                 revision: vista.revision(),
153:                 topology,
154:             });
155:             if topology == GroundTopology::Canonical {
156:                 info!(triangles = triangle_count.0, scene = %environment.scene_digest, "Retained canonical urban terrain topology");
157:             }
158:         }
159:     }
160:     for (source, mut visibility) in &mut details {
161:         let Ok((terrain, environment, _)) = scenes.get(source.0) else {
162:             continue;
163:         };
164:         let desired = if GroundTopology::for_scene(terrain, environment, &vista)
165:             == GroundTopology::Canonical
166:         {
167:             Visibility::Hidden
168:         } else {
169:             Visibility::Inherited
170:         };
171:         if *visibility != desired {
172:             *visibility = desired;
173:         }
174:     }
175: }
