192: pub(in crate::presentation) fn terrain_patch_mesh(
193:     patch: SceneTerrainPatch,
194:     terrain: &SceneTerrain,
195: ) -> Mesh {
196:     let uvs = patch
197:         .positions()
198:         .iter()
199:         .map(|position| {
200:             [
201:                 position[0] / terrain.width() + 0.5,
202:                 position[2] / terrain.depth() + 0.5,
203:             ]
204:         })
205:         .collect::<Vec<_>>();
206:     let mut mesh = Mesh::new(
207:         PrimitiveTopology::TriangleList,
208:         RenderAssetUsages::MAIN_WORLD | RenderAssetUsages::RENDER_WORLD,
209:     );
210:     let buffers = patch.into_mesh_buffers();
211:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, buffers.positions);
212:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, buffers.normals);
213:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
214:     mesh.insert_indices(Indices::U32(buffers.indices));
215:     mesh
216: }
