218: pub(super) fn append_detail_cell(
219:     indices: &mut Vec<u32>,
220:     positions: &[[f32; 3]],
221:     width: usize,
222:     index: u32,
223:     centre: Vec2,
224:     collar: Option<TerrainTransitionCollar>,
225: ) {
226:     let width = width as u32;
227:     for triangle in [
228:         [index, index + width, index + 1],
229:         [index + 1, index + width, index + width + 1],
230:     ] {
231:         let triangle_centre = triangle
232:             .iter()
233:             .map(|&index| {
234:                 let position = positions[index as usize];
235:                 Vec2::new(position[0], position[2])
236:             })
237:             .sum::<Vec2>()
238:             / 3.0;
239:         if triangle_centre.distance(centre) <= DETAIL_PATCH_RADIUS_METRES
240:             && !collar.is_some_and(|collar| {
241:                 adventuresim_tactical_core::scene_coordinates::ScenePlanPoint::try_from(
242:                     triangle_centre,
243:                 )
244:                 .is_ok_and(|point| collar.cuts_out(point))
245:             })
246:         {
247:             indices.extend_from_slice(&triangle);
248:         }
249:     }
250: }
