298:     playable_half_extent: Vec2,
299:     playable_ground: &SceneGround,
300:     point: ScenePlanPoint,
301:     urban_ground: &UrbanGround,
302: ) -> f32 {
303:     if urban_ground.suppresses_grass(point) {
304:         return 0.0;
305:     }
306:     let boundary = point
307:         .metres()
308:         .clamp(-playable_half_extent, playable_half_extent);
309:     let playable_coverage = ScenePlanPoint::from_metres(boundary)
310:         .and_then(|point| playable_ground.ground_at(point))
311:         .filter(|sample| sample.cover == GroundCover::TallGrass)
312:         .map_or(0.0, |sample| bps(sample.cover_density_bps));
313:     let outside = (point.metres().abs() - playable_half_extent)
314:         .max(Vec2::ZERO)
315:         .max_element();
316:     if outside <= 0.0 {
317:         return playable_coverage;
318:     }
319:     let vista_coverage = sample_vista_environment(lod, point)
320:         .map(vista_sward_coverage)
321:         .unwrap_or(0.0);
322:     playable_coverage.lerp(
323:         vista_coverage,
324:         smoothstep01(outside / VISTA_GRASS_BOUNDARY_STITCH_METRES),
325:     )
326: }
