1: //! Distant rock and tree presentation from the admitted source terrain.
2: use super::*;
3: use adventuresim_building_generator::spatial_geometry::SignedLength;
4: use adventuresim_tactical_core::scene_coordinates::ScenePlanPoint;
5: use fabelgeist_determinism::Seed;
6: 
7: #[expect(
8:     clippy::too_many_arguments,
9:     reason = "this domain boundary names each independent input explicitly"
10: )]
11: pub(super) fn spawn_vista_rocks(
12:     commands: &mut Commands,
13:     lod: &VistaLod,
14:     coarser_lod: Option<&VistaLod>,
15:     playable_half_extent: Vec2,
16:     playable_terrain: &SceneTerrain,
17:     scene_seed: Seed,
18:     meshes: &mut Assets<Mesh>,
19:     materials: &mut Assets<StandardMaterial>,
20: ) {
21:     let lift = match SignedLength::from_metres(0.08) {
22:         Ok(lift) => lift,
23:         Err(error) => {
24:             warn!(%error, "Invalid vista rock elevation offset");
25:             return;
26:         }
27:     };
28:     let recipe = RockRecipe {
29:         seed: 0x7669_7374_615f_726f.into(),
30:         archetype: RockArchetype::Rounded,
31:         lithology: RockLithology::Granite,
32:         dimensions_cm: [120, 92, 108],
33:         collision_radius_cm: 80,
34:     };
35:     let near_mesh = meshes.add(super::obstacles::rock::procedural_rock_mesh(recipe));
36:     let far_mesh = meshes.add(vista_rock_mesh());
37:     let material = materials.add(StandardMaterial {
38:         base_color: super::obstacles::rock::rock_color(RockLithology::Granite),
39:         perceptual_roughness: 0.92,
40:         ..default()
41:     });
42:     let spacing = 24.0;
43:     let outer = playable_half_extent + Vec2::splat(420.0);
44:     let minimum = (-outer / spacing).floor().as_ivec2();
45:     let maximum = (outer / spacing).ceil().as_ivec2();
46:     for z in minimum.y..=maximum.y {
47:         for x in minimum.x..=maximum.x {
48:             let (hash, jitter) = streams::rock_cell(scene_seed, x, z, spacing);
49:             let point = Vec2::new(x as f32, z as f32) * spacing + jitter;
50:             if point.x.abs() <= playable_half_extent.x + 2.0
51:                 && point.y.abs() <= playable_half_extent.y + 2.0
52:             {
53:                 continue;
54:             }
55:             let Some(point) = ScenePlanPoint::from_metres(point) else {
56:                 continue;
57:             };
58:             let Some(sample) = sample_vista_environment(lod, point) else {
59:                 continue;
60:             };
61:             let exposed = bps(sample.hilly_bps)
62:                 * (1.0 - bps(sample.water_bps))
63:                 * (1.0 - bps(sample.wetland_bps) * 0.75)
64:                 * (1.0 - bps(sample.canopy_bps) * 0.42);
65:             if streams::ROCK_PRESENCE.rng(hash, &[]).inclusive_unit_f32() > exposed * 0.46 {
66:                 continue;
67:             }
68:             let Some(mut transform) = vista_scatter_transform(
69:                 lod,
70:                 coarser_lod,
71:                 playable_terrain,
72:                 playable_half_extent,
73:                 point,
74:                 hash,
75:                 lift,
76:             ) else {
77:                 continue;
78:             };
79:             let scale = 0.55 + streams::ROCK_SCALE.rng(hash, &[]).inclusive_unit_f32() * 1.35;
80:             transform.scale = Vec3::new(scale, scale * 0.72, scale * 0.9);
81:             spawn_rock_bands(
82:                 commands, lod.level, &near_mesh, &far_mesh, &material, transform,
83:             );
84:         }
85:     }
86: }
