88: pub(super) fn sample_vista_environment(
89:     lod: &VistaLod,
90:     world: ScenePlanPoint,
91: ) -> Option<EnvironmentalSample> {
92:     let width = usize::from(lod.width);
93:     let depth = usize::from(lod.depth);
94:     let origin = Vec2::new(
95:         lod.origin_east_metres as f32,
96:         lod.origin_north_metres as f32,
97:     );
98:     let coordinate = (world.metres() - origin) / lod.spacing_metres
99:         + Vec2::new((width - 1) as f32 * 0.5, (depth - 1) as f32 * 0.5);
100:     if coordinate.x < 0.0
101:         || coordinate.y < 0.0
102:         || coordinate.x > (width - 1) as f32
103:         || coordinate.y > (depth - 1) as f32
104:     {
105:         return None;
106:     }
107:     let nearest = coordinate.round().as_uvec2();
108:     lod.environment
109:         .get(nearest.y as usize * width + nearest.x as usize)
110:         .copied()
111: }
