72:         material.extension.set_geographic_frame(frame);
73:         let mut terrain_handles = Vec::new();
74:         if let Some(landform) = ground.landform {
75:             let mut patch_material = material.clone();
76:             enable_cliff_surface(&mut patch_material, landform.surface);
77:             patch_material.base.depth_bias = LANDFORM_PATCH_DEPTH_BIAS;
78:             let handle = terrain_materials.add(patch_material);
79:             landform
80:                 .chunk
81:                 .spawn(&mut commands, root, &mut meshes, handle.clone());
82:             terrain_handles.push(handle);
83:         }
84:         let terrain_material = terrain_materials.add(material);
85:         ground
86:             .fine
87:             .spawn(&mut commands, root, &mut meshes, terrain_material.clone());
88:         terrain_handles.push(terrain_material);
89:         let vista_material = vista_materials.add(vista_material(
90:             environment.weather,
91:             grass_terminal_pigment(&environment),
92:         ));
93:         for chunk in ground.vista {
94:             chunk.spawn(&mut commands, root, &mut meshes, vista_material.clone());
95:         }
96:         let paving_materials = paving.spawn_focused(
97:             &mut commands,
98:             &product.ground,
99:             streets::FocusedPavingPlacement {
100:                 root,
101:                 frame,
102:                 weather: environment.weather,
103:             },
104:             &mut meshes,
105:             &mut images,
106:         )?;
107:         state.apply(world);
108:         Ok(Self {
109:             support: ground.support,
110:             terrain_materials: terrain_handles,
111:             paving_materials,
112:             half_extent: ground.half_extent,
113:         })
114:     }
115: }
116: 
117: impl GroundChunk {
118:     fn spawn<M: bevy::pbr::Material>(
119:         self,
120:         commands: &mut Commands,
121:         root: Entity,
122:         meshes: &mut Assets<Mesh>,
123:         material: Handle<M>,
124:     ) {
125:         let owner = PresentationOwner::RegionalMap;
126:         commands.spawn((
127:             Name::new("Map city canonical ground"),
128:             owner,
129:             owner.render_layers(),
130:             NotShadowCaster,
131:             Mesh3d(meshes.add(self.mesh)),
132:             MeshMaterial3d(material),
133:             Transform::from_translation(self.origin),
134:             ChildOf(root),
135:         ));
136:     }
137: 
138:     fn reflected(self) -> std::result::Result<Self, geographic_ground::GeographicGroundError> {
139:         Ok(Self {
140:             mesh: geographic_ground::reflected(self.mesh)?,
141:             ..self
142:         })
143:     }
144: }

1: //! Admit complete source ground, including the implicit landform cutout owner.
2: use super::*;
3: use crate::presentation::terrain::{
4:     PreparedTerrainLandform, terrain_patch_mesh, urban_playable_mesh,
5: };
6: 
7: type GroundPreparationResult<T> = std::result::Result<T, GroundPreparationError>;
8: 
9: pub(super) struct GroundMeshes {
10:     pub fine: GroundChunk,
11:     pub landform: Option<LandformChunk>,
12:     pub vista: Vec<GroundChunk>,
13:     pub support: streets::GroundSupport,
14:     /// Native producer boundary: canonical east/north half extents in metres.
15:     pub half_extent: Vec2,
16: }
17: 
18: pub(super) struct LandformChunk {
19:     pub chunk: GroundChunk,
20:     pub surface: TerrainSurfaceRecipe,
21: }
22: 
23: struct VistaChunks {
24:     chunks: Vec<GroundChunk>,
25:     /// Native producer boundary: canonical east/north half extents in metres.
26:     half_extent: Vec2,
27: }
28: 
29: #[derive(Debug, thiserror::Error)]
30: pub(super) enum GroundPreparationError {
31:     #[error("city landform geometry has no surface recipe")]
32:     LandformRecipe,
33:     #[error(transparent)]
34:     Reflection(#[from] geographic_ground::GeographicGroundError),
35:     #[error(transparent)]
36:     VistaMesh(#[from] VistaMeshError),
37: }
38: 
39: impl GroundMeshes {
40:     pub(super) fn new(
41:         product: &PreparedCityProduct,
42:         environment: &SceneEnvironment,
43:         maximum_lods: usize,
44:     ) -> GroundPreparationResult<Self> {
45:         let started = web_time::Instant::now();
46:         let input = product.document.input();
47:         let fine = GroundChunk {
48:             mesh: urban_playable_mesh(&product.terrain, input.landform.as_ref()),
49:             origin: Vec3::ZERO,
50:         };
51:         let landform = match &product.landform {
52:             PreparedTerrainLandform::Natural => None,
53:             PreparedTerrainLandform::Patch(patch) => Some(LandformChunk {
54:                 chunk: GroundChunk {
55:                     mesh: terrain_patch_mesh(patch.clone(), &product.terrain),
56:                     origin: Vec3::ZERO,
57:                 },
58:                 surface: input
59:                     .landform
60:                     .ok_or(GroundPreparationError::LandformRecipe)?
61:                     .surface(),
62:             }),
63:         };
64:         let vista = VistaChunks::new(product, environment, maximum_lods)?;
65:         let geometry_time = started.elapsed();
66:         let mut support = streets::GroundSupport::default();
67:         for chunk in std::iter::once(&fine)
68:             .chain(landform.iter().map(|landform| &landform.chunk))
69:             .chain(&vista.chunks)
70:         {
71:             support.add_mesh(&chunk.mesh, chunk.origin);
72:         }
73:         info!(
74:             geometry_ms = geometry_time.as_millis(),
75:             support_ms = (started.elapsed() - geometry_time).as_millis(),
76:             vista_chunks = vista.chunks.len(),
77:             "Focused city ground preparation"
78:         );
79:         // Finish all fallible reflection before publishing renderer entities.
80:         Ok(Self {
81:             fine: fine.reflected()?,
82:             landform: landform
83:                 .map(|landform| {
84:                     Ok::<_, GroundPreparationError>(LandformChunk {
85:                         chunk: landform.chunk.reflected()?,
86:                         surface: landform.surface,
87:                     })
88:                 })
89:                 .transpose()?,
90:             vista: vista
91:                 .chunks
92:                 .into_iter()
93:                 .map(GroundChunk::reflected)
94:                 .collect::<std::result::Result<_, _>>()?,
95:             support,
96:             half_extent: vista.half_extent,
97:         })
98:     }
99: }
100: 
101: impl VistaChunks {
102:     fn new(
103:         product: &PreparedCityProduct,
104:         environment: &SceneEnvironment,
105:         maximum_lods: usize,
106:     ) -> GroundPreparationResult<Self> {
107:         let input = product.document.input();
108:         let lods = input
109:             .vista
110:             .lods
111:             .iter()
112:             .take(maximum_lods)
113:             .collect::<Vec<_>>();
114:         let mut inner = Vec2::new(product.terrain.width(), product.terrain.depth()) * 0.5;
115:         let mut chunks = Vec::new();
116:         for (index, lod) in lods.iter().copied().enumerate() {
117:             let origin = Vec3::new(
118:                 lod.origin_east_metres as f32,
119:                 0.0,
120:                 lod.origin_north_metres as f32,
121:             );
122:             chunks.extend(
123:                 vista_lod_meshes_with_morph(
124:                     lod,
125:                     inner,
126:                     lods.get(index + 1).copied(),
127:                     Some(&product.terrain),
128:                     (index == 0).then_some(environment),
129:                     environment.weather,
130:                     input.landform.map(|recipe| recipe.transition_collar()),
131:                 )?
132:                 .into_iter()
133:                 .map(|mesh| GroundChunk { mesh, origin }),
134:             );
135:             inner = Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1))
136:                 * lod.spacing_metres
137:                 * 0.5;
138:         }
139:         Ok(Self {
140:             chunks,
141:             half_extent: inner,
142:         })
143:     }
144: }

