2: use super::*;
3: use adventuresim_building_generator::spatial_geometry::{Position, PositiveLength, SignedLength};
4: use adventuresim_tactical_core::scene_coordinates::Scene;
5: use adventuresim_tactical_core::{
6:     city_layout::grounding::{SupportElevation, SupportQuery, SurfaceHit},
7:     scene_coordinates::ScenePlanPoint,
8: };
