11: const MINIMUM_VISTA_ROCK_SLOPE_NORMAL_Y: f32 = 0.72;
12: const VISTA_SCENERY_NORMAL_SAMPLE_DISTANCE_METRES: f32 = 2.0;
13: 
14: pub(super) fn vista_lod_meshes_with_morph(
15:     lod: &VistaLod,
16:     inner_half_extent: Vec2,
17:     coarser_lod: Option<&VistaLod>,
18:     playable_terrain: Option<&SceneTerrain>,
19:     playable_environment: Option<&SceneEnvironment>,
20:     weather: WeatherSnapshot,
21:     transition_collar: Option<TerrainTransitionCollar>,
22: ) -> VistaMeshResult<Vec<Mesh>> {
23:     if let Some(surface) = playable_terrain.and_then(SceneTerrain::property_surface) {
24:         natural::validate_source(lod)?;
25:         if let Some(coarser) = coarser_lod {
26:             natural::validate_source(coarser)?;
27:         }
28:         return owned::vista_meshes(
29:             surface,
30:             lod,
31:             inner_half_extent,
32:             coarser_lod,
33:             playable_environment,
34:             weather,
35:             transition_collar,
36:         );
37:     }
38:     natural::sampled_vista_lod_meshes_with_morph(
39:         lod,
40:         inner_half_extent,
41:         coarser_lod,
42:         playable_terrain.filter(|terrain| {
43:             inner_half_extent == Vec2::new(terrain.width(), terrain.depth()) * 0.5
44:         }),
45:         playable_environment,
46:         weather,
47:     )
48: }
49: 
50: pub(super) fn vista_scatter_transform(
51:     lod: &VistaLod,
52:     coarser_lod: Option<&VistaLod>,
53:     playable_terrain: &SceneTerrain,
54:     playable_half_extent: Vec2,
55:     point: ScenePlanPoint,
56:     hash: Seed,
57:     lift: SignedLength,
58: ) -> Option<Transform> {
59:     let hit = scenery_surface(
60:         lod,
61:         coarser_lod,
62:         playable_terrain,
63:         playable_half_extent,
64:         point,
65:     )?;
66:     if hit.normal.y < MINIMUM_VISTA_ROCK_SLOPE_NORMAL_Y {
67:         return None;
68:     }
69:     let position = Position::<Scene>::from_metres(Vec3::new(
70:         point.metres().x,
71:         hit.elevation.metres() + lift.metres(),
72:         point.metres().y,
73:     ))
74:     .ok()?;
75:     Some(
76:         Transform::from_translation(position.metres()).with_rotation(
77:             Quat::from_rotation_arc(Vec3::Y, *hit.normal)
78:                 * Quat::from_rotation_y(
79:                     streams::ROCK_YAW.rng(hash, &[]).inclusive_unit_f32() * core::f32::consts::TAU,
80:                 ),
81:         ),
82:     )
83: }
84: 
85: pub(super) fn tree_root_height(
86:     terrain: &SceneTerrain,
87:     lod: &VistaLod,
88:     coarser: Option<&VistaLod>,
89:     world: ScenePlanPoint,
90: ) -> Option<SupportElevation> {
91:     if terrain.property_surface().is_some() {
92:         return terrain
93:             .surface_below(SupportQuery::unbounded(world))
94:             .map(|hit| hit.elevation);
95:     }
96:     presented_height_at(lod, world, coarser)
97: }
98: 
99: /// Owned scenery uses the same highest exterior support as the rendered ground.
100: /// Sampled scenes retain their stitched heightfield and finite-difference normal.
101: fn scenery_surface(
102:     lod: &VistaLod,
103:     coarser_lod: Option<&VistaLod>,
104:     playable_terrain: &SceneTerrain,
105:     playable_half_extent: Vec2,
106:     point: ScenePlanPoint,
107: ) -> Option<SurfaceHit> {
108:     if playable_terrain.property_surface().is_some() {
109:         return playable_terrain.surface_below(SupportQuery::unbounded(point));
110:     }
111:     let local = lod.local_offset(point).ok()?;
112:     let geometry = VistaVertexGeometry::sample(
113:         lod,
114:         coarser_lod,
115:         Some(playable_terrain),
116:         local,
117:         playable_half_extent,
118:         PositiveLength::from_metres(VISTA_SCENERY_NORMAL_SAMPLE_DISTANCE_METRES).ok()?,
119:     )?;
120:     let tangent_x = geometry.east_tangent().metres();
121:     let tangent_z = geometry.north_tangent().metres();
122:     let normal = tangent_z.cross(tangent_x);
123:     Some(SurfaceHit::new(
124:         geometry.elevation(),
125:         Dir3::new(normal).ok()?,
126:     ))
127: }
