1: //! Existing sampled-ring presentation for unoccupied geographic scenes.
2: use super::*;
3: use adventuresim_building_generator::spatial_geometry::PositiveLength;
4: use adventuresim_tactical_core::scene::TerrainSupportError;
5: 
6: struct SampledVistaMesher<'a> {
7:     lod: &'a VistaLod,
8:     inner_half_extent: Vec2,
9:     coarser_lod: Option<&'a VistaLod>,
10:     playable_terrain: Option<&'a SceneTerrain>,
11:     colors: VistaVertexColors<'a>,
12:     normal_sample_distance: PositiveLength,
13: }
14: 
15: impl SampledVistaMesher<'_> {
16:     fn chunk(
17:         &self,
18:         chunk_x: usize,
19:         chunk_z: usize,
20:         chunk_cells: usize,
21:     ) -> VistaMeshResult<Option<Mesh>> {
22:         let width = usize::from(self.lod.width);
23:         let depth = usize::from(self.lod.depth);
24:         let center_x = (width - 1) as f32 * 0.5;
25:         let center_z = (depth - 1) as f32 * 0.5;
26:         let mut positions = Vec::new();
27:         let mut normals = Vec::new();
28:         let mut colors = Vec::new();
29:         let mut indices = Vec::new();
30:         for z in chunk_z..(chunk_z + chunk_cells).min(depth - 1) {
31:             for x in chunk_x..(chunk_x + chunk_cells).min(width - 1) {
32:                 let cell_min = Vec2::new(
33:                     (x as f32 - center_x) * self.lod.spacing_metres,
34:                     (z as f32 - center_z) * self.lod.spacing_metres,
35:                 );
36:                 let cell_max = cell_min + Vec2::splat(self.lod.spacing_metres);
37:                 for rectangle in cell_rectangles_outside_inner_rectangle(
38:                     cell_min,
39:                     cell_max,
40:                     self.inner_half_extent,
41:                 ) {
42:                     for [minimum_x, maximum_x, minimum_z, maximum_z] in
43:                         subdivide_playable_boundary_rectangle(
44:                             rectangle,
45:                             self.inner_half_extent,
46:                             self.playable_terrain,
47:                         )
48:                     {
49:                         let base = positions.len() as u32;
50:                         let vertices = [
51:                             self.vertex(PlanDisplacement::try_from(Vec2::new(
52:                                 minimum_x, minimum_z,
53:                             ))?)?,
54:                             self.vertex(PlanDisplacement::try_from(Vec2::new(
55:                                 maximum_x, minimum_z,
56:                             ))?)?,
57:                             self.vertex(PlanDisplacement::try_from(Vec2::new(
58:                                 maximum_x, maximum_z,
59:                             ))?)?,
60:                             self.vertex(PlanDisplacement::try_from(Vec2::new(
61:                                 minimum_x, maximum_z,
62:                             ))?)?,
63:                         ];
64:                         positions.extend(vertices.map(|vertex| vertex.0));
65:                         normals.extend(vertices.map(|vertex| vertex.1));
66:                         colors.extend(vertices.map(|vertex| vertex.2));
67:                         indices.extend_from_slice(&[
68:                             base,
69:                             base + 2,
70:                             base + 1,
71:                             base,
72:                             base + 3,
73:                             base + 2,
74:                         ]);
75:                     }
76:                 }
77:             }
78:         }
79:         if positions.is_empty() {
80:             return Ok(None);
81:         }
82:         let mut mesh = Mesh::new(
83:             PrimitiveTopology::TriangleList,
84:             RenderAssetUsages::RENDER_WORLD,
85:         );
86:         mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
87:         mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
88:         mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, colors);
89:         mesh.insert_indices(Indices::U32(indices));
90:         Ok(Some(mesh))
91:     }
92:     // The positional arrays are Bevy's native vertex attribute encodings.
93:     fn vertex(&self, local: PlanDisplacement) -> VistaMeshResult<([f32; 3], [f32; 3], [f32; 4])> {
94:         let point = self.lod.scene_point(local)?;
95:         let geometry = VistaVertexGeometry::sample(
96:             self.lod,
97:             self.coarser_lod,
98:             self.playable_terrain,
99:             local,
100:             self.inner_half_extent,
101:             self.normal_sample_distance,
102:         )
103:         .ok_or(TerrainSupportError::MissingSupport { point })?;
104:         let tangent_x = geometry.east_tangent().metres();
105:         let tangent_z = geometry.north_tangent().metres();
106:         let normal = tangent_z
107:             .cross(tangent_x)
108:             .try_normalize()
109:             .ok_or(VistaMeshError::DegenerateNormal { point })?;
110:         let color = self
111:             .colors
112:             .at(local, self.inner_half_extent)
113:             .ok_or(VistaMeshError::MissingColor { point })?;
114:         let local = local.metres();
115:         Ok((
116:             [local.x, geometry.elevation().metres(), local.y],
117:             normal.to_array(),
118:             color,
119:         ))
120:     }
121: }
122: 
123: pub(super) fn sampled_vista_lod_meshes_with_morph(
124:     lod: &VistaLod,
125:     inner_half_extent: Vec2,
126:     coarser_lod: Option<&VistaLod>,
127:     playable_terrain: Option<&SceneTerrain>,
128:     playable_environment: Option<&SceneEnvironment>,
129:     weather: WeatherSnapshot,
130: ) -> VistaMeshResult<Vec<Mesh>> {
131:     validate_source(lod)?;
132:     if let Some(coarser) = coarser_lod {
133:         validate_source(coarser)?;
134:     }
135:     let width = usize::from(lod.width);
136:     let depth = usize::from(lod.depth);
137:     let mesher = SampledVistaMesher {
138:         lod,
139:         inner_half_extent,
140:         coarser_lod,
141:         playable_terrain,
142:         colors: VistaVertexColors::new(lod, coarser_lod, playable_environment, weather),
143:         normal_sample_distance: PositiveLength::from_metres(lod.spacing_metres.min(100.0))?,
144:     };
145:     // Small rings keep at least two chunks across the longer axis for culling.
146:     let chunk_cells = VISTA_CHUNK_CELLS.min((width.max(depth) - 1).div_ceil(2).max(1));
147:     let mut meshes = Vec::new();
148:     for z in (0..depth - 1).step_by(chunk_cells) {
149:         for x in (0..width - 1).step_by(chunk_cells) {
150:             if let Some(mesh) = mesher.chunk(x, z, chunk_cells)? {
151:                 meshes.push(mesh);
152:             }
153:         }
154:     }
155:     Ok(meshes)
156: }
