158: pub(super) fn validate_source(lod: &VistaLod) -> VistaMeshResult<()> {
159:     if !lod.has_height_grid() || lod.environment.len() != lod.heights_metres.len() {
160:         return Err(VistaMeshError::InvalidLod { level: lod.level });
161:     }
162:     Ok(())
163: }

1: //! Partition accepted support into existing material and culling regions.
2: use super::*;
3: use adventuresim_tactical_core::city_layout::grounding::BoundedSettlementTerrain;
4: use bevy::math::{DVec3, Vec3Swizzles};
5: use exterior::GroundPresentation;
6: 
7: mod clip;
8: mod exterior;
9: mod ground_support;
10: 
11: struct RectangleMesh {
12:     minimum: Vec2,
13:     maximum: Vec2,
14:     positions: Vec<[f32; 3]>,
15: }
16: 
17: /// The fine material covers its original rectangle. The complete accepted
18: /// surface, including distant properties, is partitioned into vista chunks.
19: pub(in crate::presentation) fn playable_mesh(
20:     terrain: &SceneTerrain,
21:     transition_collar: Option<TerrainTransitionCollar>,
22: ) -> Option<Mesh> {
23:     let surface = terrain.property_surface()?;
24:     let half = Vec2::new(terrain.width(), terrain.depth()) * 0.5;
25:     let presentation = GroundPresentation::in_rectangles(surface, &[[-half, half]]);
26:     let triangles = presentation
27:         .triangles(transition_collar)
28:         .flat_map(|triangle| clip::PreparedTriangle::new(triangle).in_rectangle(-half, half));
29:     let mut mesh = triangle_mesh(triangles);
30:     let positions = mesh
31:         .attribute(Mesh::ATTRIBUTE_POSITION)
32:         .unwrap()
33:         .as_float3()
34:         .unwrap();
35:     let uvs = positions
36:         .iter()
37:         .map(|p| [p[0] / terrain.width() + 0.5, p[2] / terrain.depth() + 0.5])
38:         .collect::<Vec<_>>();
39:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
40:     Some(mesh)
41: }
42: 
43: pub(super) fn vista_meshes(
44:     surface: &BoundedSettlementTerrain,
45:     lod: &VistaLod,
46:     inner: Vec2,
47:     coarser: Option<&VistaLod>,
48:     environment: Option<&SceneEnvironment>,
49:     weather: WeatherSnapshot,
50:     transition_collar: Option<TerrainTransitionCollar>,
51: ) -> VistaMeshResult<Vec<Mesh>> {
52:     let size = Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1));
53:     let half = size * lod.spacing_metres * 0.5;
54:     let cells = VISTA_CHUNK_CELLS.min(
55:         (usize::from(lod.width.max(lod.depth)) - 1)
56:             .div_ceil(2)
57:             .max(1),
58:     );
59:     let colors = VistaVertexColors::new(lod, coarser, environment, weather);
60:     let mut chunks = Vec::new();
61:     for z in (0..usize::from(lod.depth - 1)).step_by(cells) {
62:         for x in (0..usize::from(lod.width - 1)).step_by(cells) {
63:             let minimum = Vec2::new(x as f32, z as f32) * lod.spacing_metres - half;
64:             let maximum = (minimum + Vec2::splat(cells as f32 * lod.spacing_metres)).min(half);
65:             let rectangles = cell_rectangles_outside_inner_rectangle(minimum, maximum, inner);
66:             chunks.push(
67:                 rectangles
68:                     .into_iter()
69:                     .map(|[x0, x1, z0, z1]| RectangleMesh {
70:                         minimum: Vec2::new(x0, z0),
71:                         maximum: Vec2::new(x1, z1),
72:                         positions: Vec::new(),
73:                     })
74:                     .collect::<Vec<_>>(),
75:             );
76:         }
77:     }
78:     let regions = chunks
79:         .iter()
80:         .flatten()
81:         .map(|rectangle| [rectangle.minimum, rectangle.maximum])
82:         .collect::<Vec<_>>();
83:     let presentation = GroundPresentation::in_rectangles(surface, &regions);
84:     // One source-ordered pass preserves each rectangle's triangle order while
85:     // avoiding repeated face filtering and bound calculations.
86:     for triangle in presentation.triangles(transition_collar) {
87:         let prepared = clip::PreparedTriangle::new(triangle);
88:         for rectangle in chunks.iter_mut().flatten() {
89:             rectangle.positions.extend(
90:                 prepared
91:                     .in_rectangle(rectangle.minimum, rectangle.maximum)
92:                     .flatten()
93:                     .map(|p| p.to_array()),
94:             );
95:         }
96:     }
97:     let mut meshes = Vec::new();
98:     for chunk in chunks {
99:         let mut rectangles = chunk.into_iter();
100:         let mut positions = rectangles.next().map(|r| r.positions).unwrap_or_default();
101:         for rectangle in rectangles {
102:             positions.extend(rectangle.positions);
103:         }
104:         if positions.is_empty() {
105:             continue;
106:         }
107:         let colors = positions
108:             .iter()
109:             .map(|p| {
110:                 let local = PlanDisplacement::try_from(Vec2::new(p[0], p[2]))?;
111:                 let point = lod.scene_point(local)?;
112:                 colors
113:                     .at(local, inner)
114:                     .ok_or(VistaMeshError::MissingColor { point })
115:             })
116:             .collect::<VistaMeshResult<Vec<_>>>()?;
117:         let mut mesh = position_mesh(positions);
118:         mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, colors);
119:         meshes.push(mesh);
120:     }
121:     Ok(meshes)
122: }
123: 
124: fn triangle_mesh(triangles: impl IntoIterator<Item = [Vec3; 3]>) -> Mesh {
125:     position_mesh(
126:         triangles
127:             .into_iter()
128:             .flat_map(|t| t.map(|p| p.to_array()))
129:             .collect(),
130:     )
131: }
132: 
133: fn position_mesh(positions: Vec<[f32; 3]>) -> Mesh {
134:     let count = u32::try_from(positions.len()).expect("bounded terrain fits u32 mesh indices");
135:     let indices = (0..count).collect();
136:     let mut mesh = Mesh::new(
137:         PrimitiveTopology::TriangleList,
138:         RenderAssetUsages::RENDER_WORLD,
139:     );
140:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
141:     mesh.insert_indices(Indices::U32(indices));
142:     mesh.with_computed_area_weighted_normals()
143: }
