1: //! Rectangle intersections retain faces instead of dropping crossing triangles.
2: use super::*;
3: 
4: pub(super) struct PreparedTriangle {
5:     triangle: [Vec3; 3],
6:     low: Vec2,
7:     high: Vec2,
8: }
9: 
10: /// Interior faces pass straight through without allocating a temporary vector.
11: pub(super) enum ClippedTriangles {
12:     Interior(Option<[Vec3; 3]>),
13:     Boundary(std::vec::IntoIter<[Vec3; 3]>),
14: }
15: 
16: impl Iterator for ClippedTriangles {
17:     type Item = [Vec3; 3];
18: 
19:     fn next(&mut self) -> Option<Self::Item> {
20:         match self {
21:             Self::Interior(triangle) => triangle.take(),
22:             Self::Boundary(triangles) => triangles.next(),
23:         }
24:     }
25: 
26:     fn size_hint(&self) -> (usize, Option<usize>) {
27:         match self {
28:             Self::Interior(triangle) => triangle.iter().size_hint(),
29:             Self::Boundary(triangles) => triangles.size_hint(),
30:         }
31:     }
32: }
33: 
34: impl ExactSizeIterator for ClippedTriangles {}
35: 
36: #[cfg(test)]
37: impl ClippedTriangles {
38:     fn is_empty(&self) -> bool {
39:         self.len() == 0
40:     }
41: }
42: 
43: impl PreparedTriangle {
44:     pub(super) fn new(triangle: [Vec3; 3]) -> Self {
45:         let low = triangle
46:             .map(|p| p.xz())
47:             .into_iter()
48:             .fold(Vec2::splat(f32::INFINITY), Vec2::min);
49:         let high = triangle
50:             .map(|p| p.xz())
51:             .into_iter()
52:             .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max);
53:         Self {
54:             triangle,
55:             low,
56:             high,
57:         }
58:     }
59: 
60:     pub(super) fn in_rectangle(&self, minimum: Vec2, maximum: Vec2) -> ClippedTriangles {
61:         let Self {
62:             triangle,
63:             low,
64:             high,
65:         } = *self;
66:         if low.cmpge(maximum).any() || high.cmplt(minimum).any() {
67:             return ClippedTriangles::Interior(None);
68:         }
69:         if low.cmpge(minimum).all() && high.cmple(maximum).all() {
70:             return ClippedTriangles::Interior(Some(triangle));
71:         }
72:         let [a, b, c] = triangle.map(Vec3::as_dvec3);
73:         let normal = (b - a).cross(c - a);
74:         let represented = |point: DVec3| {
75:             let mut point = point.as_vec3();
76:             if normal.y.abs() > 0.0 {
77:                 // Height is evaluated at represented X/Z coordinates, avoiding a
78:                 // false steep normal in tiny pieces at large geographic coordinates.
79:                 point.y = (a.y
80:                     - (normal.x * (f64::from(point.x) - a.x)
81:                         + normal.z * (f64::from(point.z) - a.z))
82:                         / normal.y) as f32;
83:             }
84:             point
85:         };
86:         let mut polygon = vec![a, b, c];
87:         for (axis, bound, direction) in [
88:             (0, minimum.x, 1.0),
89:             (0, maximum.x, -1.0),
90:             (2, minimum.y, 1.0),
91:             (2, maximum.y, -1.0),
92:         ] {
93:             let distance = |point: DVec3| (point[axis] - f64::from(bound)) * direction;
94:             let mut clipped = Vec::new();
95:             for i in 0..polygon.len() {
96:                 let a = polygon[i];
97:                 let b = polygon[(i + 1) % polygon.len()];
98:                 let da = distance(a);
99:                 let db = distance(b);
100:                 if da >= 0.0 {
101:                     clipped.push(a);
102:                 }
103:                 if (da >= 0.0) != (db >= 0.0) {
104:                     clipped.push(a.lerp(b, da / (da - db)));
105:                 }
106:             }
107:             polygon = clipped;
108:             if polygon.is_empty() {
109:                 return ClippedTriangles::Interior(None);
110:             }
111:         }
112:         let polygon = polygon.into_iter().map(represented).collect::<Vec<_>>();
113:         let triangles = (1..polygon.len().saturating_sub(1))
114:             .filter_map(|i| {
115:                 let triangle = [polygon[0], polygon[i], polygon[i + 1]];
116:                 ((triangle[1] - triangle[0])
117:                     .cross(triangle[2] - triangle[0])
118:                     .length_squared()
119:                     > 0.0)
120:                     .then_some(triangle)
121:             })
122:             .collect::<Vec<_>>();
123:         ClippedTriangles::Boundary(triangles.into_iter())
124:     }
125: }
