1: //! Ordinary terrain rendering excludes exactly shared interior prism sides.
2: //! Closed collision cells and physical support remain untouched. Matching is
3: //! local to each property and uses vertex bits, with no positional tolerance.
4: 
5: use super::*;
6: use adventuresim_tactical_core::city_layout::grounding::{
7:     BoundedSettlementTerrain, PropertyFoundationMesh,
8: };
9: use std::collections::HashMap;
10: 
11: pub(super) struct GroundPresentation<'a> {
12:     surface: &'a BoundedSettlementTerrain,
13:     foundations: Vec<VisibleFoundation<'a>>,
14:     regions: Option<PresentationRegions>,
15: }
16: 
17: impl<'a> GroundPresentation<'a> {
18:     #[cfg(test)]
19:     pub(super) fn new(surface: &'a BoundedSettlementTerrain) -> Self {
20:         Self::from_foundations(surface, surface.foundations().iter())
21:     }
22: 
23:     pub(super) fn in_rectangles(
24:         surface: &'a BoundedSettlementTerrain,
25:         rectangles: &[[Vec2; 2]],
26:     ) -> Self {
27:         let regions = PresentationRegions::new(rectangles);
28:         let foundations = surface.foundations().iter().filter(|foundation| {
29:             let (low, high) = foundation
30:                 .positions()
31:                 .iter()
32:                 .chain(foundation.cut_faces().iter().flatten())
33:                 .fold(
34:                     (Vec2::splat(f32::INFINITY), Vec2::splat(f32::NEG_INFINITY)),
35:                     |(low, high), point| (low.min(point.xz()), high.max(point.xz())),
36:                 );
37:             regions.overlaps_bounds(low, high)
38:         });
39:         let mut presentation = Self::from_foundations(surface, foundations);
40:         presentation.regions = Some(regions);
41:         presentation
42:     }
43: 
44:     fn from_foundations(
45:         surface: &'a BoundedSettlementTerrain,
46:         foundations: impl Iterator<Item = &'a PropertyFoundationMesh>,
47:     ) -> Self {
48:         Self {
49:             surface,
50:             regions: None,
51:             foundations: foundations
52:                 .map(|mesh| VisibleFoundation {
53:                     mesh,
54:                     internal_sides: internal_sides(mesh),
55:                 })
56:                 .collect(),
57:         }
58:     }
59: 
60:     pub(super) fn triangles(
61:         &self,
62:         transition_collar: Option<TerrainTransitionCollar>,
63:     ) -> impl Iterator<Item = [Vec3; 3]> + '_ {
64:         // Match collision ownership using the original face centroid, before
65:         // reversing winding or clipping faces into presentation rectangles.
66:         let retained = move |triangle: &[Vec3; 3]| {
67:             self.overlaps_regions(triangle)
68:                 && !transition_collar.is_some_and(|collar| {
69:                     adventuresim_tactical_core::scene_coordinates::ScenePlanPoint::try_from(
70:                         (triangle.iter().copied().sum::<Vec3>() / 3.0).xz(),
71:                     )
72:                     .is_ok_and(|point| collar.cuts_out(point))
73:                 })
74:         };
75:         self.surface
76:             .natural_triangles()
77:             .iter()
78:             .filter(move |triangle| retained(triangle))
79:             .map(|[a, b, c]| [*a, *c, *b])
80:             .chain(
81:                 self.foundations
82:                     .iter()
83:                     .flat_map(|f| f.mesh.cut_faces().iter().copied())
84:                     .filter(move |triangle| retained(triangle)),
85:             )
86:             .chain(
87:                 self.foundations
88:                     .iter()
89:                     .flat_map(|visible| {
90:                         let foundation = visible.mesh;
91:                         let hidden = &visible.internal_sides;
92:                         foundation.solid_triangles().iter().enumerate().filter_map(
93:                             move |(face, indices)| {
94:                                 // Canonical cells have one top, one bottom and three
95:                                 // consecutive side pairs. Keep buried bottoms too;
96:                                 // visibility never substitutes for support validation.
97:                                 let cell_face = face % 8;
98:                                 let visible = cell_face < 2
99:                                     || hidden[face / 8] & (1 << ((cell_face - 2) / 2)) == 0;
100:                                 visible.then(|| indices.map(|i| foundation.positions()[i as usize]))
101:                             },
102:                         )
103:                     })
104:                     .filter(move |triangle| self.overlaps_regions(triangle)),
105:             )
106:     }
107: 
108:     fn overlaps_regions(&self, triangle: &[Vec3; 3]) -> bool {
109:         self.regions.as_ref().is_none_or(|regions| {
110:             let (low, high) = triangle.iter().fold(
111:                 (Vec2::splat(f32::INFINITY), Vec2::splat(f32::NEG_INFINITY)),
112:                 |(low, high), point| (low.min(point.xz()), high.max(point.xz())),
113:             );
114:             regions.overlaps_bounds(low, high)
115:         })
116:     }
117: }
118: 
119: /// The clipper's same half-open exclusion keeps crossing and vertical faces.
120: /// Union rejection avoids scanning every rectangle for distant terrain faces.
121: struct PresentationRegions {
122:     bounds: [Vec2; 2],
123:     rectangles: Vec<[Vec2; 2]>,
124: }
125: 
126: impl PresentationRegions {
127:     fn new(rectangles: &[[Vec2; 2]]) -> Self {
128:         let bounds = rectangles.iter().fold(
129:             [Vec2::splat(f32::INFINITY), Vec2::splat(f32::NEG_INFINITY)],
130:             |[low, high], [minimum, maximum]| [low.min(*minimum), high.max(*maximum)],
131:         );
132:         Self {
133:             bounds,
134:             rectangles: rectangles.to_vec(),
135:         }
136:     }
137: 
138:     fn overlaps_bounds(&self, low: Vec2, high: Vec2) -> bool {
139:         let overlaps = |[minimum, maximum]: &[Vec2; 2]| {
140:             !low.cmpge(*maximum).any() && !high.cmplt(*minimum).any()
141:         };
142:         overlaps(&self.bounds) && self.rectangles.iter().any(overlaps)
143:     }
144: }
145: 
146: struct VisibleFoundation<'a> {
147:     mesh: &'a PropertyFoundationMesh,
148:     internal_sides: Vec<u8>,
149: }
150: 
151: #[derive(Clone, Copy)]
152: struct SideRef {
153:     cell: usize,
154:     side: usize,
155:     forward: bool,
156: }
157: 
158: enum SideOccurrence {
159:     Single(SideRef),
160:     Pair(SideRef, SideRef),
161:     Multiple,
162: }
163: 
164: impl SideOccurrence {
165:     fn visit(&mut self, side: SideRef) {
166:         *self = match *self {
167:             Self::Single(first) => Self::Pair(first, side),
168:             Self::Pair(_, _) | Self::Multiple => Self::Multiple,
169:         };
170:     }
171: }
172: 
173: fn internal_sides(foundation: &PropertyFoundationMesh) -> Vec<u8> {
174:     let cells = foundation.positions().as_chunks::<6>().0;
175:     let mut hidden = vec![0; cells.len()];
176:     let mut occurrences = HashMap::new();
177:     for (cell, points) in cells.iter().enumerate() {
178:         let bits = points.map(|point| point.to_array().map(f32::to_bits));
179:         for (side, (a, b)) in [(0, 1), (1, 2), (2, 0)].into_iter().enumerate() {
180:             let mut vertices = [bits[a], bits[b], bits[a + 3], bits[b + 3]];
181:             vertices.sort_unstable();
182:             let reference = SideRef {
183:                 cell,
184:                 side,
185:                 forward: bits[a] < bits[b],
186:             };
187:             occurrences
188:                 .entry(vertices)
189:                 .and_modify(|entry: &mut SideOccurrence| entry.visit(reference))
190:                 .or_insert(SideOccurrence::Single(reference));
191:         }
192:     }
193:     for occurrence in occurrences.into_values() {
194:         if let SideOccurrence::Pair(first, second) = occurrence
195:             && first.forward != second.forward
196:         {
197:             hidden[first.cell] |= 1 << first.side;
198:             hidden[second.cell] |= 1 << second.side;
199:         }
200:     }
201:     hidden
202: }
