29:         CityPropertyId(property),
30:         PropertyMembers::new(vec![property.into()]).unwrap(),
31:         prisms,
32:         cuts.into_iter()
33:             .map(|t| t.map(|p| Position::from_metres(p).unwrap()))
34:             .collect(),
35:     )
36:     .unwrap()
