57: fn clipped_triangles(
58:     presentation: &GroundPresentation<'_>,
59:     regions: &[[Vec2; 2]],
60:     collar: Option<TerrainTransitionCollar>,
61: ) -> Vec<[[u32; 3]; 3]> {
