1: //! The accepted graded surface replaces raw vista geometry without overlap.
2: use super::*;
3: use adventuresim_tactical_core::city_layout::grounding::GeographicSurface;
4: use adventuresim_tactical_core::city_layout::{
5:     CitySceneLayout, CitySingleProperty, CompoundGradingPolicy,
