10: fn surface(meshes: &[Mesh]) -> GeographicSurface {
11:     GeographicSurface::from_triangles(meshes.iter().flat_map(|mesh| {
12:         let VertexAttributeValues::Float32x3(positions) =
13:             mesh.attribute(Mesh::ATTRIBUTE_POSITION).unwrap()
14:         else {
15:             panic!("terrain position format");
16:         };
17:         let indices = mesh.indices().unwrap().iter().collect::<Vec<_>>();
18:         indices
19:             .as_chunks::<3>()
20:             .0
21:             .iter()
22:             .map(|t| t.map(|i| Vec3::from_array(positions[i])))
23:             .filter(|triangle| {
24:                 let [a, b, c] = triangle.map(Vec3::as_dvec3);
25:                 let ab = b - a;
26:                 let ac = c - a;
27:                 // Bound interpolation, coordinate differences and the cross
28:                 // product at the scene-coordinate scale, in area units. Using
29:                 // only edge products misses a short edge created by rounding
30:                 // two copies of the same clipped endpoint differently.
31:                 let projection_roundoff = 8.0
32:                     * f64::EPSILON
33:                     * (a.length() + b.length() + c.length())
34:                     * (ab.length() + ac.length());
35:                 // Retaining walls and unmeasurable graphics slivers cannot
36:                 // supply an affine ground height. Use geographic admission;
37:                 // the assertions below still require complete plot coverage.
38:                 ab.cross(ac).y > projection_roundoff
39:                     && GeographicSurface::from_triangles([*triangle]).is_some()
40:             })
41:             .collect::<Vec<_>>()
42:     }))
43:     .unwrap()
44: }
