208: /// Frozen pre-partition traversal: rectangle order, source face order, then
209: /// the existing clipper, normals and pigments. This is a test-only reference.
210: fn repeated_traversal_meshes(
211:     terrain: &SceneTerrain,
212:     lod: &VistaLod,
213:     inner: Vec2,
214:     coarser: Option<&VistaLod>,
215:     environment: Option<&SceneEnvironment>,
216:     weather: WeatherSnapshot,
217: ) -> Vec<Mesh> {
218:     let surface = terrain.property_surface().unwrap();
219:     let half =
220:         Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1)) * lod.spacing_metres * 0.5;
221:     let cells = VISTA_CHUNK_CELLS.min(
222:         (usize::from(lod.width.max(lod.depth)) - 1)
223:             .div_ceil(2)
224:             .max(1),
225:     );
226:     let presentation = GroundPresentation::new(surface);
227:     let colors = VistaVertexColors::new(lod, coarser, environment, weather);
228:     let mut meshes = Vec::new();
229:     for z in (0..usize::from(lod.depth - 1)).step_by(cells) {
230:         for x in (0..usize::from(lod.width - 1)).step_by(cells) {
231:             let minimum = Vec2::new(x as f32, z as f32) * lod.spacing_metres - half;
232:             let maximum = (minimum + Vec2::splat(cells as f32 * lod.spacing_metres)).min(half);
233:             let triangles = cell_rectangles_outside_inner_rectangle(minimum, maximum, inner)
234:                 .into_iter()
235:                 .flat_map(|[x0, x1, z0, z1]| {
236:                     presentation.triangles(None).flat_map(move |triangle| {
237:                         clip::PreparedTriangle::new(triangle)
238:                             .in_rectangle(Vec2::new(x0, z0), Vec2::new(x1, z1))
239:                     })
240:                 });
241:             let mut mesh = triangle_mesh(triangles);
242:             let positions = mesh
243:                 .attribute(Mesh::ATTRIBUTE_POSITION)
244:                 .unwrap()
245:                 .as_float3()
246:                 .unwrap();
247:             if positions.is_empty() {
248:                 continue;
249:             }
250:             let values = positions
251:                 .iter()
252:                 .map(|p| {
253:                     colors
254:                         .at(
255:                             PlanDisplacement::try_from(Vec2::new(p[0], p[2])).unwrap(),
256:                             inner,
257:                         )
258:                         .unwrap()
259:                 })
260:                 .collect::<Vec<_>>();
261:             mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, values);
262:             meshes.push(mesh);
263:         }
264:     }
265:     meshes
266: }
