1: //! A vista waits for its exact canonical terrain before preparing presentation.
2: use super::*;
3: #[derive(Resource, Default)]
4: pub(in crate::presentation) struct PendingVista(pub Option<SceneVistaBundle>);
5: 
6: impl PendingVista {
7:     pub(super) fn accept<'a>(
8:         &mut self,
9:         bundle: &SceneVistaBundle,
10:         mut environments: impl Iterator<Item = &'a SceneEnvironment>,
11:     ) -> bool {
12:         let ready = environments.any(|environment| environment.scene_digest == bundle.scene_digest);
13:         self.0 = (!ready).then(|| bundle.clone());
14:         ready
15:     }
16: }
17: 
18: pub(in crate::presentation) fn present_ready_vista(
19:     mut pending: ResMut<PendingVista>,
20:     terrains: Query<(&SceneTerrain, &SceneEnvironment)>,
21:     mut commands: Commands,
22: ) {
23:     if pending.0.as_ref().is_some_and(|bundle| {
24:         terrains
25:             .iter()
26:             .any(|(_, environment)| environment.scene_digest == bundle.scene_digest)
27:     }) {
28:         commands.trigger(pending.0.take().expect("ready pending vista"));
29:     }
30: }
