2: //! Bilinear, LOD and playable-edge interpolation retain their original order.
3: //! The fields are local to one mesh preparation and its exact weather snapshot.
4: use super::*;
5: 
6: pub(super) const PLAYABLE_COLOR_TRANSITION_CELLS: f32 = 4.0;
7: 
8: pub(super) struct VistaVertexColors<'a> {
9:     own: SampleColors<'a>,
10:     coarser: Option<SampleColors<'a>>,
11:     playable: Option<Vec4>,
12: }
13: 
14: impl<'a> VistaVertexColors<'a> {
15:     pub(super) fn new(
16:         lod: &'a VistaLod,
17:         coarser: Option<&'a VistaLod>,
18:         environment: Option<&SceneEnvironment>,
19:         weather: WeatherSnapshot,
20:     ) -> Self {
21:         Self {
22:             own: SampleColors::new(lod, weather),
23:             coarser: coarser.map(|lod| SampleColors::new(lod, weather)),
24:             playable: environment.map(|environment| {
25:                 Vec4::from_array(scene_ground_color(environment).to_linear().to_f32_array())
26:             }),
27:         }
28:     }
29: 
30:     pub(super) fn at(
31:         &self,
32:         local: PlanDisplacement,
33:         playable_half_extent: Vec2,
34:     ) -> Option<[f32; 4]> {
35:         let lod = self.own.lod;
36:         let world = lod.scene_point(local).ok()?;
37:         let own = self.own.at(world)?;
38:         let vista_color = self
39:             .coarser
40:             .as_ref()
41:             .map(|coarser| {
42:                 let weight = lod_transition_weight(lod, coarser.lod, world);
43:                 coarser
44:                     .at(world)
45:                     .map(|color| own.lerp(color, weight))
46:                     .unwrap_or(own)
47:             })
48:             .unwrap_or(own);
49:         Some(
50:             self.playable
51:                 .map(|playable| {
52:                     // Cover proportions summarize wider ecological patches than height
53:                     // samples. Keep the existing four-cell pigment transition.
54:                     stitch_vista_color_to_playable_edge(
55:                         local.metres(),
56:                         playable_half_extent,
57:                         lod.spacing_metres * PLAYABLE_COLOR_TRANSITION_CELLS,
58:                         vista_color,
59:                         playable,
60:                     )
61:                 })
62:                 .unwrap_or(vista_color)
63:                 .to_array(),
64:         )
65:     }
66: }
67: 
68: struct SampleColors<'a> {
69:     lod: &'a VistaLod,
70:     colors: Vec<Vec4>,
71: }
72: 
73: impl<'a> SampleColors<'a> {
74:     fn new(lod: &'a VistaLod, weather: WeatherSnapshot) -> Self {
75:         Self {
76:             lod,
77:             colors: lod
78:                 .environment
79:                 .iter()
80:                 .map(|sample| vista_sample_color(*sample, weather))
81:                 .collect(),
82:         }
83:     }
84: 
85:     fn at(&self, world: ScenePlanPoint) -> Option<Vec4> {
86:         let world = world.metres();
87:         let lod = self.lod;
88:         let width = usize::from(lod.width);
89:         let depth = usize::from(lod.depth);
90:         let local = world
91:             - Vec2::new(
92:                 lod.origin_east_metres as f32,
93:                 lod.origin_north_metres as f32,
94:             );
95:         let coordinate = local / lod.spacing_metres
96:             + Vec2::new((width - 1) as f32 * 0.5, (depth - 1) as f32 * 0.5);
97:         if coordinate.x < 0.0
98:             || coordinate.y < 0.0
99:             || coordinate.x > (width - 1) as f32
100:             || coordinate.y > (depth - 1) as f32
101:         {
102:             return None;
103:         }
104:         let lower = coordinate.floor().as_uvec2();
105:         let upper = (lower + UVec2::ONE).min(UVec2::new(width as u32 - 1, depth as u32 - 1));
106:         let fraction = coordinate.fract();
107:         let at = |x: u32, z: u32| self.colors[z as usize * width + x as usize];
108:         let near = at(lower.x, lower.y).lerp(at(upper.x, lower.y), fraction.x);
109:         let far = at(lower.x, upper.y).lerp(at(upper.x, upper.y), fraction.x);
110:         Some(near.lerp(far, fraction.y))
111:     }
112: }
113: 
114: pub(super) fn stitch_vista_color_to_playable_edge(
115:     local: Vec2,
116:     playable_half_extent: Vec2,
117:     transition_width: f32,
118:     vista_color: Vec4,
119:     playable_color: Vec4,
120: ) -> Vec4 {
121:     let outside_distance = (local.abs() - playable_half_extent)
122:         .max(Vec2::ZERO)
123:         .max_element();
124:     let vista_weight = if transition_width > 0.0 {
125:         (outside_distance / transition_width).clamp(0.0, 1.0)
126:     } else {
127:         f32::from(outside_distance > 0.0)
128:     };
129:     let mut stitched = playable_color.lerp(vista_color, vista_weight);
130:     // Alpha carries distant geometric-sward coverage, not material opacity.
131:     // Preserve it while blending only the molded substrate pigment.
132:     stitched.w = vista_color.w;
133:     stitched
134: }
135: 
136: pub(super) fn vista_sample_color(sample: EnvironmentalSample, weather: WeatherSnapshot) -> Vec4 {
137:     let mut color = Vec4::from_array(
138:         super::super::ground_palette::sample_ground_color(sample, weather)
139:             .to_linear()
140:             .to_f32_array(),
141:     );
142:     let hills = bps(sample.hilly_bps);
143:     let snow = bps(weather.snow_cover_bps);
144:     let exposed_rock = hills
145:         * (1.0 - bps(sample.water_bps))
146:         * (1.0 - bps(sample.wetland_bps) * 0.8)
147:         * (1.0 - bps(sample.canopy_bps) * 0.45)
148:         * (1.0 - snow);
149:     let rock = Color::srgb_u8(104, 101, 91).to_linear().to_f32_array();
150:     color = color.lerp(Vec4::from_array(rock), exposed_rock * 0.62);
151:     color.w = vista_sward_coverage(sample) * (1.0 - snow * 0.92);
152:     color
153: }
154: 
155: pub(super) fn vista_sward_coverage(sample: EnvironmentalSample) -> f32 {
156:     let surface = match sample.surface {
157:         TacticalSurface::Open | TacticalSurface::SparseWoods => 1.0,
158:         TacticalSurface::DeepWoods => 0.28,
159:         TacticalSurface::Wetland => 0.42,
160:         TacticalSurface::Road | TacticalSurface::Water => 0.0,
161:     };
162:     (surface
163:         * (1.0 - bps(sample.water_bps))
164:         * (1.0 - bps(sample.cultivation_bps) * 0.72)
165:         * (1.0 - bps(sample.hilly_bps) * 0.82))
166:         .clamp(0.0, 1.0)
167: }
