169: #[cfg(test)]
170: pub(super) fn presented_color(
171:     lod: &VistaLod,
172:     x: usize,
173:     z: usize,
174:     world: Vec2,
175:     coarser_lod: Option<&VistaLod>,
176:     weather: WeatherSnapshot,
177: ) -> [f32; 4] {
178:     let own = vista_sample_color(lod.environment[z * usize::from(lod.width) + x], weather);
179:     let Some(coarser) = coarser_lod else {
180:         return own.to_array();
181:     };
182:     let world = ScenePlanPoint::try_from(world).unwrap();
183:     let weight = lod_transition_weight(lod, coarser, world);
184:     SampleColors::new(coarser, weather)
185:         .at(world)
186:         .map(|color| own.lerp(color, weight))
187:         .unwrap_or(own)
188:         .to_array()
189: }
