1: //! Give cultivated beds exclusive ground triangles inside their packed plot.
2: use bevy::math::{DVec3, Vec2};
3: use std::collections::{BTreeMap, BTreeSet};
4: 
5: pub(super) const SPATIAL_CELL_METRES: f32 = 32.0;
6: 
7: pub(super) struct SpatialIndex<'a, T> {
8:     items: &'a [T],
9:     cells: BTreeMap<(i32, i32), Vec<usize>>,
10: }
11: 
12: impl<'a, T> SpatialIndex<'a, T> {
13:     pub(super) fn new(items: &'a [T], item_bounds: impl Fn(&T) -> (Vec2, Vec2)) -> Self {
14:         let mut cells = BTreeMap::<_, Vec<_>>::new();
15:         for (index, item) in items.iter().enumerate() {
16:             let (minimum, maximum) = item_bounds(item);
17:             for key in cell_keys(minimum, maximum) {
18:                 cells.entry(key).or_default().push(index);
19:             }
20:         }
21:         Self { items, cells }
22:     }
23: 
24:     pub(super) fn candidates(&self, corners: [Vec2; 4]) -> Vec<&'a T> {
25:         let (minimum, maximum) = bounds(corners);
26:         let indices = cell_keys(minimum, maximum)
27:             .flat_map(|key| self.cells.get(&key).into_iter().flatten().copied())
28:             .collect::<BTreeSet<_>>();
29:         indices
30:             .into_iter()
31:             .map(|index| &self.items[index])
32:             .collect()
33:     }
34: }
35: 
36: pub(super) fn bounds(points: [Vec2; 4]) -> (Vec2, Vec2) {
37:     points.into_iter().fold(
38:         (Vec2::splat(f32::INFINITY), Vec2::splat(f32::NEG_INFINITY)),
39:         |(minimum, maximum), point| (minimum.min(point), maximum.max(point)),
40:     )
41: }
42: 
43: fn cell_keys(minimum: Vec2, maximum: Vec2) -> impl Iterator<Item = (i32, i32)> {
44:     let minimum = (minimum / SPATIAL_CELL_METRES).floor().as_ivec2();
45:     let maximum = (maximum / SPATIAL_CELL_METRES).floor().as_ivec2();
46:     (minimum.y..=maximum.y).flat_map(move |y| (minimum.x..=maximum.x).map(move |x| (x, y)))
47: }
48: 
49: pub(super) fn overlaps(a: [Vec2; 4], b: [Vec2; 4]) -> bool {
50:     let (amin, amax) = bounds(a);
51:     let (bmin, bmax) = bounds(b);
52:     amin.x < bmax.x && amax.x > bmin.x && amin.y < bmax.y && amax.y > bmin.y
53: }
54: 
55: pub(super) fn subtract(polygon: Vec<DVec3>, beds: &[[Vec2; 4]]) -> Vec<Vec<DVec3>> {
56:     let mut pieces = vec![polygon];
57:     for bed in beds {
58:         pieces = pieces
59:             .into_iter()
60:             .flat_map(|piece| outside(piece, *bed))
61:             .collect();
62:     }
63:     pieces
64: }
65: 
66: fn outside(mut remaining: Vec<DVec3>, bed: [Vec2; 4]) -> Vec<Vec<DVec3>> {
67:     let bed = bed.map(Vec2::as_dvec2);
68:     let winding = (bed[1] - bed[0]).perp_dot(bed[3] - bed[0]).signum();
69:     let mut pieces = Vec::new();
70:     for side in 0..4 {
71:         let start = bed[side];
72:         let edge = bed[(side + 1) % 4] - start;
73:         let distance = |p: DVec3| edge.perp_dot(bevy::math::DVec2::new(p.x, p.z) - start) * winding;
74:         let mut inside = Vec::new();
75:         let mut outside = Vec::new();
76:         for index in 0..remaining.len() {
77:             let a = remaining[index];
78:             let b = remaining[(index + 1) % remaining.len()];
79:             let da = distance(a);
80:             let db = distance(b);
81:             if da >= 0.0 {
82:                 inside.push(a);
83:             }
84:             if da <= 0.0 {
85:                 outside.push(a);
86:             }
87:             if (da > 0.0 && db < 0.0) || (da < 0.0 && db > 0.0) {
88:                 let crossing = a.lerp(b, da / (da - db));
89:                 inside.push(crossing);
90:                 outside.push(crossing);
91:             }
92:         }
93:         if outside.len() >= 3 {
94:             pieces.push(outside);
95:         }
96:         remaining = inside;
97:         if remaining.len() < 3 {
98:             break;
99:         }
100:     }
101:     pieces
102: }
