1: //! Pure street clipping and retained upload-ready city-ground batches.
2: use super::*;
3: use crate::presentation::preparation::PreparationResult;
4: use crate::presentation::{
5:     ownership::{PresentationOwner, PresentationOwners},
6:     terrain::PreparedTerrainLandform,
7:     vista::geographic_ground,
8: };
9: use std::sync::{Arc, OnceLock};
10: 
11: type InstalledGround = Vec<(traffic::TrafficTile, CityGroundKind, Handle<Mesh>, usize)>;
12: type GroundUpload = Result<InstalledGround, Arc<geographic_ground::GeographicGroundError>>;
13: 
14: #[derive(serde::Serialize, serde::Deserialize)]
15: pub(in crate::presentation) struct PreparedCityGround {
16:     batches: Vec<(traffic::TrafficTile, CityGroundKind, mesh::SurfaceVertices)>,
17:     #[serde(skip)]
18:     installed: PresentationOwners<OnceLock<GroundUpload>>,
19:     #[serde(skip)]
20:     pub(super) traffic: streaming::RetainedTrafficMasks,
21: }
22: 
23: impl PreparedCityGround {
24:     pub(super) fn new(
25:         streets: &[CityStreetPatch],
26:         yards: &[CityYardPatch],
27:         groups: &[FurnitureGroup],
28:         support: &GroundSupport,
29:     ) -> Self {
30:         let mut builders: [CitySurfaceMeshBuilder; 5] = Default::default();
31:         let beds = yards
32:             .iter()
33:             .filter(|yard| yard.surface == CityYardSurface::KitchenGarden)
34:             .map(|yard| yard.corners_metres)
35:             .collect::<Vec<_>>();
36:         let bed_index = partition::SpatialIndex::new(&beds, |bed| partition::bounds(*bed));
37:         let group_index = partition::SpatialIndex::new(groups, |group| {
38:             partition::bounds(group.footprint.corners())
39:         });
40:         for yard in yards.iter().copied() {
41:             builders[CityGroundKind::from(yard.surface).index()].append_yard(
42:                 yard,
43:                 &bed_index,
44:                 support,
45:                 &group_index,
46:             );
47:         }
48:         for street in streets.iter().copied() {
49:             builders[CityGroundKind::from(street.surface()).index()].append_street(
50:                 street,
51:                 support,
52:                 &group_index,
53:             );
54:         }
55:         Self {
56:             batches: builders
57:                 .into_iter()
58:                 .zip(CityGroundKind::ALL)
59:                 .flat_map(|(builder, kind)| {
60:                     builder
61:                         .into_vertices()
62:                         .map(move |(tile, vertices)| (tile, kind, vertices))
63:                 })
64:                 .collect(),
65:             installed: Default::default(),
66:             traffic: Default::default(),
67:         }
68:     }
69: 
70:     pub(in crate::presentation) fn from_scene(
71:         input: &TacticalSceneInput,
72:         terrain: &SceneTerrain,
73:         landform: &PreparedTerrainLandform,
74:         groups: &[FurnitureGroup],
75:         maximum_lods: usize,
76:     ) -> PreparationResult<Self> {
77:         let mut support = GroundSupport::default();
78:         let environment = input.environment_snapshot(input.digest()?);
79:         let lods = input
80:             .vista
81:             .lods
82:             .iter()
83:             .take(maximum_lods)
84:             .collect::<Vec<_>>();
85:         let mut inner = Vec2::new(terrain.width(), terrain.depth()) * 0.5;
86:         if let Some(surface) = terrain.property_surface() {
87:             let outer = lods.iter().fold(inner, |extent, lod| {
88:                 extent.max(
89:                     Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1))
90:                         * lod.spacing_metres
91:                         * 0.5,
92:                 )
93:             });
94:             support.add_owned_region(
95:                 surface,
96:                 outer,
97:                 input.landform.map(|recipe| recipe.transition_collar()),
98:             );
99:         } else {
100:             support.add_mesh(
101:                 &crate::presentation::terrain::urban_playable_mesh(
102:                     terrain,
103:                     input.landform.as_ref(),
104:                 ),
105:                 Vec3::ZERO,
106:             );
107:         }
108:         if let PreparedTerrainLandform::Patch(patch) = landform {
109:             support.add_patch(patch);
110:         }
111:         for (index, lod) in lods
112:             .iter()
113:             .copied()
114:             .enumerate()
115:             .filter(|_| terrain.property_surface().is_none())
116:         {
117:             let origin = Vec3::new(
118:                 lod.origin_east_metres as f32,
119:                 0.0,
120:                 lod.origin_north_metres as f32,
121:             );
122:             for mesh in super::super::vista_lod_meshes_with_morph(
123:                 lod,
124:                 inner,
125:                 lods.get(index + 1).copied(),
126:                 (index == 0).then_some(terrain),
127:                 (index == 0).then_some(&environment),
128:                 environment.weather,
129:                 input.landform.map(|recipe| recipe.transition_collar()),
130:             )? {
131:                 support.add_mesh(&mesh, origin);
132:             }
133:             inner = Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1))
134:                 * lod.spacing_metres
135:                 * 0.5;
136:         }
137:         Ok(Self::new(&input.streets, &input.yards, groups, &support))
138:     }
139: 
140:     pub(super) fn meshes(
141:         &self,
142:         owner: PresentationOwner,
143:         meshes: &mut Assets<Mesh>,
144:     ) -> Result<&InstalledGround, Arc<geographic_ground::GeographicGroundError>> {
145:         self.installed
146:             .get(owner)
147:             .get_or_init(|| {
148:                 self.batches
149:                     .iter()
150:                     .map(|(tile, kind, vertices)| {
151:                         let mut mesh = vertices.clone().build();
152:                         if owner == PresentationOwner::RegionalMap {
153:                             mesh = geographic_ground::reflected(mesh)?;
154:                         }
155:                         let triangles = mesh_triangle_count(&mesh);
156:                         Ok((*tile, *kind, meshes.add(mesh), triangles))
157:                     })
158:                     .collect::<Result<_, geographic_ground::GeographicGroundError>>()
159:                     .map_err(Arc::new)
160:             })
161:             .as_ref()
162:             .map_err(Arc::clone)
163:     }
164: }
