271:             let map = map.indices().unwrap().iter().collect::<Vec<_>>();
272:             for (actor, map) in actor.as_chunks::<3>().0.iter().zip(map.as_chunks::<3>().0) {
273:                 assert_eq!([actor[0], actor[2], actor[1]], *map);
274:             }
275:         }
276:         let count = assets.len();
277:         assert_eq!(
278:             restored
279:                 .meshes(PresentationOwner::RegionalMap, &mut assets)
280:                 .unwrap()
281:                 .iter()
282:                 .map(|batch| batch.2.clone())
283:                 .collect::<Vec<_>>(),
284:             map_handles
285:         );
286:         assert_eq!(
287:             assets.len(),
288:             count,
289:             "warm map return reuses its own uploads"
290:         );
291:     }
292: }
