1: //! Bounded street-detail residency for a freely explored city showcase.
2: use super::*;
3: use std::collections::BTreeMap;
4: use std::sync::{Arc, Mutex};
5: use traffic::{TrafficMask, TrafficNetwork, TrafficTile};
6: 
7: pub(super) type RetainedTrafficMasks = Arc<Mutex<BTreeMap<TrafficTile, TrafficMask>>>;
8: 
9: const DETAIL_RADIUS_METRES: f32 = 110.0;
10: const NETWORK_MARGIN_METRES: f32 = 96.0;
11: 
12: #[derive(Resource)]
13: pub(crate) struct StreamCityTraffic;
14: 
15: #[derive(Component)]
16: pub(crate) struct StreamedTrafficTile(pub(super) TrafficTile);
17: 
18: #[derive(Resource)]
19: pub(crate) struct CityTrafficResidency {
20:     streets: Vec<CityStreetPatch>,
21:     neutral: TrafficMask,
22:     masks: RetainedTrafficMasks,
23: }
24: 
25: impl CityTrafficResidency {
26:     pub(super) fn new(
27:         streets: Vec<CityStreetPatch>,
28:         neutral: TrafficMask,
29:         masks: RetainedTrafficMasks,
30:     ) -> Self {
31:         Self {
32:             streets,
33:             neutral,
34:             masks,
35:         }
36:     }
37: }
38: 
39: pub(crate) fn update(
40:     residency: Option<Res<CityTrafficResidency>>,
41:     cameras: Query<&GlobalTransform, With<TacticalGameplayCamera>>,
42:     tiles: Query<(&StreamedTrafficTile, &MeshMaterial3d<CityGroundMaterial>)>,
43:     mut materials: ResMut<Assets<CityGroundMaterial>>,
44:     mut images: ResMut<Assets<Image>>,
45: ) {
46:     let Some(residency) = residency else {
47:         return;
48:     };
49:     let Some(camera) = cameras.iter().next() else {
50:         return;
51:     };
52:     let position = camera.translation();
53:     let mut wanted = tiles
54:         .iter()
55:         .map(|(tile, _)| tile.0)
56:         .filter(|tile| {
57:             let centre = tile.corners().into_iter().sum::<Vec2>() * 0.25;
58:             Vec3::new(centre.x, 0.0, centre.y).distance(position) < DETAIL_RADIUS_METRES
59:         })
60:         .collect::<Vec<_>>();
61:     wanted.sort();
62:     wanted.dedup();
63:     let mut masks = residency.masks.lock().expect("city traffic masks");
64:     masks.retain(|tile, _| wanted.contains(tile));
65:     // At most one tile per frame, with no whole-city wheel-stroke allocation.
66:     if let Some(tile) = wanted
67:         .into_iter()
68:         .filter(|tile| !masks.contains_key(tile))
69:         .min_by(|a, b| {
70:             a.corners()[0]
71:                 .distance_squared(position.xz())
72:                 .total_cmp(&b.corners()[0].distance_squared(position.xz()))
73:         })
74:     {
75:         let streets = nearby_streets(&residency.streets, tile);
76:         let network = TrafficNetwork::new(&streets);
77:         masks.insert(tile, TrafficMask::bake(&network, tile, &mut images));
78:     }
79:     for (tile, handle) in &tiles {
80:         let mask = masks.get(&tile.0).unwrap_or(&residency.neutral);
81:         if materials
82:             .get(&handle.0)
83:             .is_some_and(|material| material.extension.traffic_mask != mask.image)
84:         {
85:             let mut material = materials
86:                 .get_mut(&handle.0)
87:                 .expect("existing city material");
88:             material.extension.traffic_mask = mask.image.clone();
89:             material.extension.traffic_transform = mask.transform;
90:         }
91:     }
92: }
93: 
94: fn nearby_streets(streets: &[CityStreetPatch], tile: TrafficTile) -> Vec<CityStreetPatch> {
95:     let corners = tile.corners();
96:     let minimum = corners[0] - Vec2::splat(NETWORK_MARGIN_METRES);
97:     let maximum = corners[2] + Vec2::splat(NETWORK_MARGIN_METRES);
98:     streets
99:         .iter()
100:         .copied()
101:         .filter(|street| {
102:             let (min, max) = match *street {
103:                 CityStreetPatch::Corridor {
104:                     start_metres,
105:                     end_metres,
106:                     half_width_metres,
107:                     ..
108:                 } => (
109:                     start_metres.min(end_metres) - Vec2::splat(half_width_metres),
110:                     start_metres.max(end_metres) + Vec2::splat(half_width_metres),
111:                 ),
112:                 CityStreetPatch::Market { corners_metres, .. } => (
113:                     corners_metres
114:                         .into_iter()
115:                         .fold(Vec2::splat(f32::INFINITY), Vec2::min),
116:                     corners_metres
117:                         .into_iter()
118:                         .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max),
119:                 ),
120:             };
121:             min.cmple(maximum).all() && max.cmpge(minimum).all()
122:         })
123:         .collect()
124: }
