130:     fn street_detail_never_builds_the_whole_city_network() {
131:         let input: TacticalSceneInput = serde_json::from_str(include_str!(
132:             "../../../../../../assets/tactical-scenes/massive-city.json"
133:         ))
134:         .unwrap();
