136:         assert!(!streets.is_empty());
137:         assert!(streets.len() < input.streets.len() / 5);
138:         assert!(TrafficNetwork::new(&streets).stroke_count() < 300_000);
139:     }
140: }

1: //! Street clipping against the actual terrain triangles, including vista seams.
2: 
3: use super::*;
4: use adventuresim_tactical_core::{prelude::SceneTerrainPatch, scene_coordinates::ScenePlanPoint};
5: use bevy::mesh::VertexAttributeValues;
6: mod index;
7: 
8: const CLIP_EPSILON: f32 = 0.00001;
9: 
10: #[derive(Clone, Default)]
11: pub(in crate::presentation) struct GroundSupport {
12:     triangles: Vec<[Vec3; 3]>,
13:     index: std::sync::OnceLock<index::TriangleIndex>,
14: }
15: 
16: impl GroundSupport {
17:     /// Admitted patch buffers use the same canonical east/up/north metres as
18:     /// ordinary terrain. Retain their walkable faces without renderer meshes.
19:     pub(in crate::presentation::vista) fn add_patch(&mut self, patch: &SceneTerrainPatch) {
20:         self.add_triangles(
21:             patch.indices().as_chunks::<3>().0.iter().map(|indices| {
22:                 indices.map(|index| Vec3::from_array(patch.positions()[index as usize]))
23:             }),
24:             Vec3::ZERO,
25:         );
26:     }
27: 
28:     /// Highest point on the presented city ground, in canonical east/up/north
29:     /// metres. Missing coverage never substitutes a heightfield or nearest face.
30:     pub(in crate::presentation) fn position(&self, point: ScenePlanPoint) -> Option<Vec3> {
31:         let point = point.metres();
32:         let index = self
33:             .index
34:             .get_or_init(|| index::TriangleIndex::new(&self.triangles));
35:         let mut highest: Option<Vec3> = None;
36:         index.query(point, point, |index| {
37:             let triangle = self.triangles[index].map(Vec3::as_dvec3);
38:             let query = point.as_dvec2();
39:             let [a, b, c] = triangle;
40:             // Upward-facing source triangles are clockwise in the east/north
41:             // plan. Classify edges in double precision, as paving clipping does.
42:             if [(a, b), (b, c), (c, a)].into_iter().any(|(start, end)| {
43:                 (end.xz() - start.xz()).perp_dot(query - start.xz()) > f64::from(CLIP_EPSILON)
44:             }) {
45:                 return;
46:             }
47:             let normal = (b - a).cross(c - a);
48:             let height = a.y - (normal.x * (query.x - a.x) + normal.z * (query.y - a.z)) / normal.y;
49:             let position = Vec3::new(point.x, height as f32, point.y);
50:             if highest.is_none_or(|current| position.y > current.y) {
51:                 highest = Some(position);
52:             }
53:         });
54:         highest
55:     }
56: 
57:     pub(in crate::presentation::vista) fn add_mesh(&mut self, mesh: &Mesh, origin: Vec3) {
58:         let Some(positions) = mesh
59:             .attribute(Mesh::ATTRIBUTE_POSITION)
60:             .and_then(VertexAttributeValues::as_float3)
61:         else {
62:             return;
63:         };
64:         let Some(indices) = mesh.indices() else {
65:             return;
66:         };
67:         let indices = indices.iter().collect::<Vec<_>>();
68:         let triangles = indices.as_chunks::<3>().0.iter().map(|indices| {
69:             [indices[0], indices[1], indices[2]].map(|index| Vec3::from_array(positions[index]))
70:         });
71:         self.add_triangles(triangles, origin);
72:     }
73: 
74:     /// Owned terrain already carries the exact triangles. Avoid materializing
75:     /// renderer vertices, normals, UVs and indices just to discard buried and
76:     /// vertical faces for street clipping. The eligibility rule is shared.
77:     pub(in crate::presentation::vista) fn add_triangles(
78:         &mut self,
79:         triangles: impl IntoIterator<Item = [Vec3; 3]>,
80:         origin: Vec3,
81:     ) {
82:         for triangle in triangles {
83:             let triangle = triangle.map(|point| point + origin);
84:             // Vista skirts and cliff walls are not walkable ground support.
85:             if (triangle[1] - triangle[0])
86:                 .cross(triangle[2] - triangle[0])
87:                 .y
88:                 <= CLIP_EPSILON
89:             {
90:                 continue;
91:             }
92:             self.triangles.push(triangle);
93:         }
94:         self.index.take();
95:     }
96: 
97:     pub(in crate::presentation) fn clip(
98:         &self,
99:         corners: [Vec2; 4],
100:         mut emit: impl FnMut([bevy::math::DVec3; 3]),
101:     ) {
102:         let minimum = corners
103:             .into_iter()
104:             .fold(Vec2::splat(f32::INFINITY), Vec2::min);
105:         let maximum = corners
106:             .into_iter()
107:             .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max);
108:         let index = self
109:             .index
110:             .get_or_init(|| index::TriangleIndex::new(&self.triangles));
111:         index.query(minimum, maximum, |index| {
112:             let triangle = self.triangles[index];
113:             let tri_minimum = triangle
114:                 .map(|point| point.xz())
115:                 .into_iter()
116:                 .fold(Vec2::splat(f32::INFINITY), Vec2::min);
117:             let tri_maximum = triangle
118:                 .map(|point| point.xz())
119:                 .into_iter()
120:                 .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max);
121:             if !tri_maximum.cmpge(minimum).all() || !tri_minimum.cmple(maximum).all() {
122:                 return;
123:             }
124:             let polygon = clip_polygon(triangle.map(Vec3::as_dvec3).to_vec(), corners);
125:             for index in 1..polygon.len().saturating_sub(1) {
126:                 let clipped = [polygon[0], polygon[index], polygon[index + 1]];
127:                 if (clipped[1] - clipped[0])
128:                     .cross(clipped[2] - clipped[0])
129:                     .length_squared()
130:                     > f64::from(CLIP_EPSILON * CLIP_EPSILON)
131:                 {
132:                     emit(clipped);
133:                 }
134:             }
135:         });
136:     }
137: }
138: 
139: pub(super) fn clip_polygon(
140:     mut polygon: Vec<bevy::math::DVec3>,
141:     corners: [Vec2; 4],
142: ) -> Vec<bevy::math::DVec3> {
143:     // Keep intersections in double precision until the represented polygon is
144:     // complete. Repeated f32 lerps can move a constant source edge by one ULP
145:     // across a retaining boundary and place paving on the wrong ground level.
146:     let corners = corners.map(Vec2::as_dvec2);
147:     let winding = (corners[1] - corners[0])
148:         .perp_dot(corners[3] - corners[0])
149:         .signum();
150:     for side in 0..4 {

151:         let start = corners[side];
152:         let edge = corners[(side + 1) % 4] - start;
153:         let distance = |point: bevy::math::DVec3| edge.perp_dot(point.xz() - start) * winding;
154:         let mut clipped = Vec::new();
155:         for index in 0..polygon.len() {
156:             let a = polygon[index];
157:             let b = polygon[(index + 1) % polygon.len()];
158:             let da = distance(a);
159:             let db = distance(b);
160:             if da >= -f64::from(CLIP_EPSILON) {
161:                 clipped.push(a);
162:             }
163:             if (da >= 0.0) != (db >= 0.0) {
164:                 clipped.push(a.lerp(b, da / (da - db)));
165:             }
166:         }
167:         polygon = clipped;
168:         if polygon.is_empty() {
169:             break;
170:         }
171:     }
172:     polygon
173: }
174: 
175: /// Inverse bilinear coordinates preserve the semantic market/yard footprint
176: /// when terrain clipping inserts vertices on an irregular block boundary.
177: pub(super) fn footprint_uv(corners: [Vec2; 4], point: Vec2) -> Vec2 {
178:     let [a, b, c, d] = corners;
179:     let mut uv = Vec2::splat(0.5);
180:     for _ in 0..6 {
181:         let residual = a.lerp(b, uv.x).lerp(d.lerp(c, uv.x), uv.y) - point;
182:         let du = (b - a).lerp(c - d, uv.y);
183:         let dv = (d - a).lerp(c - b, uv.x);
184:         let determinant = du.perp_dot(dv);
185:         if determinant.abs() < CLIP_EPSILON {
186:             break;
187:         }
188:         uv -= Vec2::new(residual.perp_dot(dv), du.perp_dot(residual)) / determinant;
189:     }
190:     uv.clamp(Vec2::ZERO, Vec2::ONE)
191: }
