2: use super::*;
3: 
4: const TRIANGLES_PER_LEAF: usize = 8;
5: 
6: #[derive(Clone)]
7: pub(super) struct TriangleIndex {
8:     order: Vec<usize>,
9:     nodes: Vec<Node>,
