25:         let index = TriangleIndex::new(&triangles);
26:         let mut candidates = Vec::new();
27:         index.query(Vec2::splat(-0.5), Vec2::splat(0.5), |index| {
28:             candidates.push(index)
29:         });
30:         assert!(candidates.contains(&0));
31:         assert!(candidates.contains(&1000));
32:         assert!(
33:             candidates.len() < 32,
34:             "local query must reject distant leaves"
35:         );
36:         for x in [-100.0, 0.0, 50.0, 999.0, 2000.0] {
37:             let min = Vec2::new(x, -0.5);
