41:             for (i, triangle) in triangles.iter().enumerate() {
42:                 let tri_min = triangle
43:                     .iter()
44:                     .map(|p| p.xz())
45:                     .fold(Vec2::splat(f32::INFINITY), Vec2::min);
46:                 let tri_max = triangle
47:                     .iter()
48:                     .map(|p| p.xz())
49:                     .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max);
50:                 if tri_max.cmpge(min).all() && tri_min.cmple(max).all() {
