58: #[derive(Clone)]
59: struct Node {
60:     minimum: Vec2,
61:     maximum: Vec2,
62:     range: std::ops::Range<usize>,
63:     children: Option<(usize, usize)>,
64: }
65: 
66: impl TriangleIndex {
67:     pub fn new(triangles: &[[Vec3; 3]]) -> Self {
68:         let bounds: Vec<_> = triangles
69:             .iter()
70:             .map(|triangle| {
71:                 triangle.iter().fold(
72:                     (Vec2::splat(f32::INFINITY), Vec2::splat(f32::NEG_INFINITY)),
73:                     |(min, max), point| (min.min(point.xz()), max.max(point.xz())),
74:                 )
75:             })
76:             .collect();
77:         let mut index = Self {
78:             order: (0..triangles.len()).collect(),
79:             nodes: Vec::new(),
80:         };
81:         index.partition(0..triangles.len(), &bounds);
82:         index
83:     }
84: 
85:     fn partition(&mut self, range: std::ops::Range<usize>, bounds: &[(Vec2, Vec2)]) -> usize {
86:         let (minimum, maximum) = self.order[range.clone()].iter().fold(
87:             (Vec2::splat(f32::INFINITY), Vec2::splat(f32::NEG_INFINITY)),
88:             |(min, max), &index| (min.min(bounds[index].0), max.max(bounds[index].1)),
89:         );
90:         let node = self.nodes.len();
91:         self.nodes.push(Node {
92:             minimum,
93:             maximum,
94:             range: range.clone(),
95:             children: None,
96:         });
97:         if range.len() > TRIANGLES_PER_LEAF {
98:             let extent = maximum - minimum;
99:             let axis = usize::from(extent.y > extent.x);
100:             let middle = range.len() / 2;
101:             self.order[range.clone()].select_nth_unstable_by(middle, |&a, &b| {
102:                 (bounds[a].0[axis] + bounds[a].1[axis])
103:                     .total_cmp(&(bounds[b].0[axis] + bounds[b].1[axis]))
104:                     .then_with(|| a.cmp(&b))
105:             });
106:             let split = range.start + middle;
107:             let left = self.partition(range.start..split, bounds);
108:             let right = self.partition(split..range.end, bounds);
109:             self.nodes[node].children = Some((left, right));
110:         }
111:         node
112:     }
113: 
114:     pub fn query(&self, minimum: Vec2, maximum: Vec2, mut emit: impl FnMut(usize)) {
115:         self.visit(0, minimum, maximum, &mut emit);
116:     }
117: 
118:     fn visit(&self, index: usize, minimum: Vec2, maximum: Vec2, emit: &mut impl FnMut(usize)) {
119:         let node = &self.nodes[index];
120:         if !node.maximum.cmpge(minimum).all() || !node.minimum.cmple(maximum).all() {
121:             return;
122:         }
123:         if let Some((left, right)) = node.children {
124:             self.visit(left, minimum, maximum, emit);
125:             self.visit(right, minimum, maximum, emit);
126:         } else {
127:             for &triangle in &self.order[node.range.clone()] {
128:                 emit(triangle);
129:             }
130:         }
131:     }
132: }

1: //! Static traffic history shared by every overlapping ground patch.
2: //!
3: //! Curves are baked once into metre-aligned tiles. The production shader samples
4: //! those tiles for road shoulders, broad churn and individual wheel marks.
5: use super::*;
6: use std::collections::BTreeMap;
7: 
8: mod mask;
9: mod paths;
10: #[cfg(test)]
11: mod tests;
12: 
13: pub(super) use mask::TrafficMask;
14: pub(super) use paths::TrafficNetwork;
15: 
16: const TILE_METRES: f32 = 64.0;
17: const TEXELS_PER_METRE: f32 = 4.0;
18: const TILE_INTERIOR_PIXELS: usize = 256;
19: const FILTER_GUTTER_PIXELS: usize = 1;
20: const TILE_PIXELS: usize = TILE_INTERIOR_PIXELS + FILTER_GUTTER_PIXELS * 2;
21: const ROAD_SHOULDER_METRES: f32 = 1.2;
22: 
23: #[derive(
24:     Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd, serde::Serialize, serde::Deserialize,
25: )]
26: pub(super) struct TrafficTile(pub i32, pub i32);
27: 
28: impl TrafficTile {
29:     pub(super) fn at(point: Vec2) -> Self {
30:         let cell = (point / TILE_METRES).floor().as_ivec2();
31:         Self(cell.x, cell.y)
32:     }
33: 
34:     fn origin(self) -> Vec2 {
35:         Vec2::new(self.0 as f32, self.1 as f32) * TILE_METRES
36:     }
37: 
38:     pub(super) fn corners(self) -> [Vec2; 4] {
39:         let origin = self.origin();
40:         [
41:             origin,
42:             origin + Vec2::X * TILE_METRES,
43:             origin + Vec2::splat(TILE_METRES),
44:             origin + Vec2::Y * TILE_METRES,
45:         ]
46:     }
47: 
48:     pub(super) fn covering(minimum: Vec2, maximum: Vec2) -> impl Iterator<Item = Self> {
49:         let min = Self::at(minimum);
50:         let max = Self::at(maximum);
51:         (min.1..=max.1).flat_map(move |y| (min.0..=max.0).map(move |x| Self(x, y)))
52:     }
53: }
54: 
55: #[derive(Clone, Copy)]
56: struct Road {
57:     start: Vec2,
58:     end: Vec2,
59:     half_width: f32,
60:     forward: Vec2,
61:     length: f32,
62: }
63: 
64: impl Road {
65:     fn new(start: Vec2, end: Vec2, half_width: f32) -> Self {
66:         Self {
67:             start,
68:             end,
69:             half_width,
70:             forward: (end - start).normalize(),
71:             length: start.distance(end),
72:         }
73:     }
74: 
75:     fn coordinates(self, point: Vec2) -> Vec2 {
76:         let delta = point - self.start;
77:         Vec2::new(self.forward.perp_dot(delta), self.forward.dot(delta))
78:     }
79: 
80:     fn clearance(self, point: Vec2) -> f32 {
81:         let local = self.coordinates(point);
82:         (self.half_width - local.x.abs())
83:             .min(local.y)
84:             .min(self.length - local.y)
85:     }
86: }
87: 
88: #[derive(Clone, Copy)]
89: struct WheelStroke {
90:     start: Vec2,
91:     end: Vec2,
92:     half_width: f32,
93:     strength: f32,
94: }
95: 
96: fn smooth_band(inner: f32, outer: f32, distance: f32) -> f32 {
97:     let t = ((distance - inner) / (outer - inner)).clamp(0.0, 1.0);
98:     1.0 - t * t * (3.0 - 2.0 * t)
99: }
100: 
101: fn quad_clearance(corners: [Vec2; 4], point: Vec2) -> f32 {
102:     let winding = (corners[1] - corners[0])
103:         .perp_dot(corners[3] - corners[0])
104:         .signum();
105:     (0..4)
106:         .map(|i| {
107:             let edge = corners[(i + 1) % 4] - corners[i];
108:             edge.normalize_or_zero().perp_dot(point - corners[i]) * winding
109:         })
110:         .fold(f32::INFINITY, f32::min)
111: }
112: 
113: // Internal rectangle ends are not boundaries of the road union. Probe only
114: // near an individual edge; ordinary road interiors use the exact fast path.
115: fn union_support(point: Vec2, radius: f32, clearance: impl Fn(Vec2) -> f32) -> bool {
116:     if clearance(point) >= radius {
117:         return true;
118:     }
119:     if clearance(point) < 0.0 {
120:         return false;
121:     }
122:     const ENVELOPE_DIRECTIONS: usize = 16;
123:     (0..ENVELOPE_DIRECTIONS).all(|index| {
124:         let angle = index as f32 * std::f32::consts::TAU / ENVELOPE_DIRECTIONS as f32;
125:         clearance(point + Vec2::new(angle.cos(), angle.sin()) * radius) >= 0.0
126:     })
127: }

1: //! Bounded tile rasterization with identical world-space filter gutters.
2: use super::*;
3: use bevy::{
4:     image::ImageSampler,
5:     render::render_resource::{Extent3d, TextureDimension, TextureFormat},
6: };
7: 
8: #[derive(Clone)]
9: pub(in super::super) struct TrafficMask {
10:     pub(in super::super) image: Handle<Image>,
11:     pub(in super::super) transform: Vec4,
12: }
13: 
14: impl TrafficMask {
15:     pub(in super::super) fn neutral(images: &mut Assets<Image>) -> Self {
16:         let image = Image::new_fill(
17:             Extent3d {
18:                 width: 1,
19:                 height: 1,
20:                 depth_or_array_layers: 1,
21:             },
22:             TextureDimension::D2,
23:             &[0, 0, 0, 255],
24:             TextureFormat::Rgba8Unorm,
25:             RenderAssetUsages::RENDER_WORLD,
26:         );
27:         Self {
28:             image: images.add(image),
29:             transform: Vec4::ZERO,
30:         }
31:     }
32:     pub(in super::super) fn bake(
33:         network: &TrafficNetwork,
34:         tile: TrafficTile,
35:         images: &mut Assets<Image>,
36:     ) -> Self {
37:         let pixels = network.pixels(tile);
38:         let mut image = Image::new(
39:             Extent3d {
40:                 width: TILE_PIXELS as u32,
41:                 height: TILE_PIXELS as u32,
42:                 depth_or_array_layers: 1,
43:             },
44:             TextureDimension::D2,
45:             pixels,
46:             TextureFormat::Rgba8Unorm,
47:             RenderAssetUsages::RENDER_WORLD,
48:         );
49:         image.sampler = ImageSampler::linear();
50:         let origin = tile.origin() - Vec2::splat(FILTER_GUTTER_PIXELS as f32 / TEXELS_PER_METRE);
51:         Self {
52:             image: images.add(image),
53:             transform: Vec4::new(
54:                 origin.x,
55:                 origin.y,
56:                 TEXELS_PER_METRE / TILE_PIXELS as f32,
57:                 TEXELS_PER_METRE / TILE_PIXELS as f32,
58:             ),
59:         }
60:     }
61: }
62: 
63: impl TrafficNetwork {
64:     pub(super) fn pixels(&self, tile: TrafficTile) -> Vec<u8> {
65:         let origin = tile.origin() - Vec2::splat(FILTER_GUTTER_PIXELS as f32 / TEXELS_PER_METRE);
66:         let maximum = origin + Vec2::splat(TILE_PIXELS as f32 / TEXELS_PER_METRE);
67:         let roads = self
68:             .roads
69:             .iter()
70:             .copied()
71:             .filter(|road| {
72:                 let padding = Vec2::splat(road.half_width);
73:                 (road.start.min(road.end) - padding).cmple(maximum).all()
74:                     && (road.start.max(road.end) + padding).cmpge(origin).all()
75:             })
76:             .collect::<Vec<_>>();
77:         let markets = self
78:             .markets
79:             .iter()
80:             .copied()
81:             .filter(|corners| {
82:                 let min = corners
83:                     .iter()
84:                     .copied()
85:                     .fold(Vec2::splat(f32::INFINITY), Vec2::min);
86:                 let max = corners
87:                     .iter()
88:                     .copied()
89:                     .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max);
90:                 min.cmple(maximum).all() && max.cmpge(origin).all()
91:             })
92:             .collect::<Vec<_>>();
93:         let mut pixels = vec![0_u8; TILE_PIXELS * TILE_PIXELS * 4];
94:         for y in 0..TILE_PIXELS {
95:             for x in 0..TILE_PIXELS {
96:                 let point =
97:                     origin + (Vec2::new(x as f32, y as f32) + Vec2::splat(0.5)) / TEXELS_PER_METRE;
98:                 let mut mud = 0.0_f32;
99:                 let mut clearance = f32::NEG_INFINITY;
100:                 for road in &roads {
101:                     let edge = road.clearance(point);
102:                     clearance = clearance.max(edge);
103:                     if edge < 0.0 {
104:                         continue;
105:                     }
106:                     let local = road.coordinates(point);
107:                     // Hooves, displaced soil and many vehicle lanes fill most
108:                     // of the carriageway, independently of the sharper ruts.
109:                     mud = mud.max(
110:                         smooth_band(
111:                             road.half_width * 0.48,
112:                             road.half_width * 0.92,
113:                             local.x.abs(),
114:                         ) * 0.88,
115:                     );
116:                 }
117:                 for &corners in &markets {
118:                     clearance = clearance.max(quad_clearance(corners, point));
119:                 }
120:                 if (0.0..ROAD_SHOULDER_METRES).contains(&clearance) {
121:                     let at = |p| {
122:                         roads
123:                             .iter()
124:                             .map(|road| road.clearance(p))
125:                             .chain(markets.iter().map(|&corners| quad_clearance(corners, p)))
126:                             .fold(f32::NEG_INFINITY, f32::max)
127:                     };
128:                     for fraction in [0.25, 0.5, 0.75, 1.0] {
129:                         let radius = ROAD_SHOULDER_METRES * fraction;
130:                         if union_support(point, radius, at) {
131:                             clearance = clearance.max(radius);
132:                         } else {
133:                             break;
134:                         }
135:                     }
136:                 }
137:                 let index = (y * TILE_PIXELS + x) * 4;
138:                 pixels[index] = (mud * 255.0) as u8;
139:                 pixels[index + 2] =
140:                     ((1.0 - smooth_band(0.0, ROAD_SHOULDER_METRES, clearance)) * 255.0) as u8;
141:                 pixels[index + 3] = 255;
142:             }
143:         }
144:         if let Some(strokes) = self.tiles.get(&tile) {
145:             for &index in strokes {
146:                 rasterize(&mut pixels, origin, self.strokes[index]);
147:             }
148:         }
149:         pixels
150:     }
151: }
152: 
153: fn rasterize(pixels: &mut [u8], origin: Vec2, stroke: WheelStroke) {
154:     let radius = stroke.half_width + paths::WHEEL_FEATHER_METRES;
155:     let min = (((stroke.start.min(stroke.end) - Vec2::splat(radius) - origin) * TEXELS_PER_METRE)
156:         .floor()
157:         .as_ivec2())
158:     .max(IVec2::ZERO);
159:     let max = (((stroke.start.max(stroke.end) + Vec2::splat(radius) - origin) * TEXELS_PER_METRE)
160:         .ceil()
161:         .as_ivec2())
162:     .min(IVec2::splat(TILE_PIXELS as i32 - 1));
163:     let delta = stroke.end - stroke.start;
164:     for y in min.y..=max.y {
165:         for x in min.x..=max.x {
166:             let point =
167:                 origin + (Vec2::new(x as f32, y as f32) + Vec2::splat(0.5)) / TEXELS_PER_METRE;
168:             let t = ((point - stroke.start).dot(delta) / delta.length_squared()).clamp(0.0, 1.0);
169:             let distance = point.distance(stroke.start + delta * t);
170:             let value = smooth_band(stroke.half_width * 0.35, radius, distance) * stroke.strength;
171:             let index = (y as usize * TILE_PIXELS + x as usize) * 4;
172:             pixels[index + 1] = pixels[index + 1].max((value * 255.0) as u8);
173:         }
174:     }
175: }

1: //! Canonical street connections and overlapping carriage passes.
2: use super::*;
3: 
4: const NODE_SNAP_PER_METRE: f32 = 1000.0;
5: const GEOMETRY_EPSILON: f32 = 0.001;
6: const PATH_STEP_METRES: f32 = 0.6;
7: const VEHICLE_PASSES: usize = 7;
8: const MIN_GAUGE_METRES: f32 = 1.1;
9: const GAUGE_VARIATION_METRES: f32 = 0.12;
10: const WHEEL_HALF_WIDTH_METRES: f32 = 0.13;
11: pub(super) const WHEEL_FEATHER_METRES: f32 = 0.16;
12: const WHEELBASE_METRES: f32 = 2.0;
13: const FRONTAGE_CLEARANCE_METRES: f32 = 0.35;
14: const TURN_REACH_WIDTHS: f32 = 2.5;
15: const TURN_CONTROL_REACH_FRACTION: f32 = 0.45;
16: const PASS_STRENGTHS: [f32; VEHICLE_PASSES] = [0.35, 0.5, 0.85, 0.45, 0.65, 1.0, 0.4];
17: 
18: pub(in super::super) struct TrafficNetwork {
19:     pub(super) roads: Vec<Road>,
20:     pub(super) markets: Vec<[Vec2; 4]>,
21:     pub(super) strokes: Vec<WheelStroke>,
22:     pub(super) tiles: BTreeMap<TrafficTile, Vec<usize>>,
23:     road_tiles: BTreeMap<TrafficTile, Vec<usize>>,
24:     market_tiles: BTreeMap<TrafficTile, Vec<usize>>,
25: }
26: 
27: #[derive(Clone, Copy)]
28: struct Arm {
29:     direction: Vec2,
30:     length: f32,
31:     half_width: f32,
32: }
33: 
34: enum AxleTracks {
35:     Front,
36:     Both,
37: }
38: 
39: struct Junction {
40:     point: Vec2,
41:     arms: Vec<Arm>,
42: }
43: 
44: impl TrafficNetwork {
45:     pub(in super::super) fn new(streets: &[CityStreetPatch]) -> Self {
46:         let mut roads: BTreeMap<_, Road> = BTreeMap::new();
47:         let mut markets = Vec::new();
48:         for street in streets {
49:             match *street {
50:                 CityStreetPatch::Corridor {
51:                     mut start_metres,
52:                     mut end_metres,
53:                     half_width_metres,
54:                     ..
55:                 } => {
56:                     if node_key(end_metres) < node_key(start_metres) {
57:                         std::mem::swap(&mut start_metres, &mut end_metres);
58:                     }
59:                     roads
60:                         .entry((node_key(start_metres), node_key(end_metres)))
61:                         .and_modify(|road| road.half_width = road.half_width.max(half_width_metres))
62:                         .or_insert_with(|| Road::new(start_metres, end_metres, half_width_metres));
63:                 }
64:                 CityStreetPatch::Market { corners_metres, .. } => markets.push(corners_metres),
65:             }
66:         }
67:         let mut network = Self {
68:             roads: roads.into_values().collect(),
69:             markets,
70:             strokes: Vec::new(),
71:             tiles: BTreeMap::new(),
72:             road_tiles: BTreeMap::new(),
73:             market_tiles: BTreeMap::new(),
74:         };
75:         for (index, road) in network.roads.iter().enumerate() {
76:             let padding = Vec2::splat(road.half_width);
77:             for tile in TrafficTile::covering(
78:                 road.start.min(road.end) - padding,
79:                 road.start.max(road.end) + padding,
80:             ) {
81:                 network.road_tiles.entry(tile).or_default().push(index);
82:             }
83:         }
84:         for (index, corners) in network.markets.iter().enumerate() {
85:             let (min, max) = super::super::partition::bounds(*corners);
86:             for tile in TrafficTile::covering(
87:                 min - Vec2::splat(GEOMETRY_EPSILON),
88:                 max + Vec2::splat(GEOMETRY_EPSILON),
89:             ) {
90:                 network.market_tiles.entry(tile).or_default().push(index);
91:             }
92:         }
93:         for index in 0..network.roads.len() {
94:             network.straight(network.roads[index]);
95:         }
96:         for junction in network.junctions() {
97:             for a in 0..junction.arms.len() {
98:                 for b in a + 1..junction.arms.len() {
99:                     network.turn(junction.point, junction.arms[a], junction.arms[b]);
100:                 }
101:             }
102:         }
103:         for (index, stroke) in network.strokes.iter().enumerate() {
104:             let padding =
105:                 Vec2::splat(stroke.half_width + WHEEL_FEATHER_METRES + 1.0 / TEXELS_PER_METRE);
106:             for tile in TrafficTile::covering(
107:                 stroke.start.min(stroke.end) - padding,
108:                 stroke.start.max(stroke.end) + padding,
109:             ) {
110:                 network.tiles.entry(tile).or_default().push(index);
111:             }
112:         }
113:         network
114:     }
115: 
116:     pub(in super::super) fn stroke_count(&self) -> usize {
117:         self.strokes.len()
118:     }
119: 
120:     fn junctions(&self) -> Vec<Junction> {
121:         let mut nodes: BTreeMap<(i32, i32), Vec2> = BTreeMap::new();
122:         for road in &self.roads {
123:             for point in [road.start, road.end] {
124:                 nodes.insert(node_key(point), point);
125:             }
126:         }
127:         for (index, a) in self.roads.iter().enumerate() {
128:             for b in &self.roads[index + 1..] {
129:                 let da = a.end - a.start;
130:                 let db = b.end - b.start;
131:                 let cross = da.perp_dot(db);
132:                 if cross.abs() < GEOMETRY_EPSILON {
133:                     continue;
134:                 }
135:                 let delta = b.start - a.start;
136:                 let t = delta.perp_dot(db) / cross;
137:                 let u = delta.perp_dot(da) / cross;
138:                 if (0.0..=1.0).contains(&t) && (0.0..=1.0).contains(&u) {
139:                     let point = a.start + da * t;
140:                     nodes.entry(node_key(point)).or_insert(point);
141:                 }
142:             }
143:         }
144:         nodes
145:             .into_values()
146:             .filter_map(|point| {
147:                 let mut arms: Vec<Arm> = Vec::new();
148:                 for road in &self.roads {
149:                     let local = road.coordinates(point);
150:                     if local.x.abs() > GEOMETRY_EPSILON
151:                         || local.y < -GEOMETRY_EPSILON
152:                         || local.y > road.start.distance(road.end) + GEOMETRY_EPSILON
153:                     {
154:                         continue;
155:                     }
156:                     for end in [road.start, road.end] {
157:                         let delta = end - point;
158:                         let length = delta.length();
159:                         if length <= GEOMETRY_EPSILON {
160:                             continue;
161:                         }
162:                         let direction = delta / length;
163:                         if !arms
164:                             .iter()
165:                             .any(|arm| arm.direction.dot(direction) > 1.0 - GEOMETRY_EPSILON)
166:                         {
167:                             arms.push(Arm {
168:                                 direction,
169:                                 length,
170:                                 half_width: road.half_width,

171:                             });
172:                         }
173:                     }
174:                 }
175:                 (arms.len() >= 2).then_some(Junction { point, arms })
176:             })
177:             .collect()
178:     }
179: 
180:     fn straight(&mut self, road: Road) {
181:         let length = road.start.distance(road.end);
182:         let direction = (road.end - road.start) / length;
183:         let normal = Vec2::new(-direction.y, direction.x);
184:         let steps = (length / PATH_STEP_METRES).ceil() as usize;
185:         for pass in 0..VEHICLE_PASSES {
186:             let (gauge, offset) = pass_dimensions(pass, road.half_width);
187:             let points = (0..=steps)
188:                 .map(|step| {
189:                     let t = step as f32 / steps as f32;
190:                     let wander = (t * std::f32::consts::TAU).sin() * (pass as f32 + 1.0) * 0.025;
191:                     road.start.lerp(road.end, t) + normal * (offset + wander)
192:                 })
193:                 .collect::<Vec<_>>();
194:             self.wheels(&points, gauge, pass, AxleTracks::Front);
195:         }
196:     }
197: 
198:     fn turn(&mut self, node: Vec2, a: Arm, b: Arm) {
199:         let alignment = a.direction.dot(b.direction);
200:         if alignment > 0.98 || alignment < -1.0 + GEOMETRY_EPSILON {
201:             return;
202:         }
203:         let width = a.half_width.min(b.half_width);
204:         let reach = (width * TURN_REACH_WIDTHS)
205:             .min(a.length * 0.45)
206:             .min(b.length * 0.45);
207:         let controls = [
208:             node + a.direction * reach,
209:             node + a.direction * reach * TURN_CONTROL_REACH_FRACTION,
210:             node + b.direction * reach * TURN_CONTROL_REACH_FRACTION,
211:             node + b.direction * reach,
212:         ];
213:         let steps = ((reach * 2.0 / PATH_STEP_METRES).ceil() as usize).max(4);
214:         for pass in 0..VEHICLE_PASSES {
215:             let (gauge, offset) = pass_dimensions(pass, width);
216:             let points = (0..=steps)
217:                 .map(|step| {
218:                     let t = step as f32 / steps as f32;
219:                     let position = bezier(controls, t);
220:                     let tangent = ((controls[1] - controls[0]) * (1.0 - t).powi(2)
221:                         + (controls[2] - controls[1]) * 2.0 * (1.0 - t) * t
222:                         + (controls[3] - controls[2]) * t * t)
223:                         .normalize();
224:                     position + Vec2::new(-tangent.y, tangent.x) * offset
225:                 })
226:                 .collect::<Vec<_>>();
227:             let lead_steps = (WHEELBASE_METRES * 2.0 / PATH_STEP_METRES).ceil() as usize;
228:             let mut extended = Vec::new();
229:             let incoming = (points[1] - points[0]).normalize();
230:             let outgoing = (points[points.len() - 1] - points[points.len() - 2]).normalize();
231:             for step in (1..=lead_steps).rev() {
232:                 extended.push(points[0] - incoming * step as f32 * PATH_STEP_METRES);
233:             }
234:             extended.extend_from_slice(&points);
235:             for step in 1..=lead_steps {
236:                 extended.push(points[points.len() - 1] + outgoing * step as f32 * PATH_STEP_METRES);
237:             }
238:             self.wheels(&extended, gauge, pass, AxleTracks::Both);
239:             extended.reverse();
240:             self.wheels(&extended, gauge, pass, AxleTracks::Both);
241:         }
242:     }
243: 
244:     fn wheels(&mut self, points: &[Vec2], gauge: f32, pass: usize, axles: AxleTracks) {
245:         let mut candidate = Vec::new();
246:         let mut rear = points[0] - (points[1] - points[0]).normalize() * WHEELBASE_METRES;
247:         let mut rear_points = vec![rear];
248:         for pair in points.windows(2) {
249:             rear = pair[1] - (pair[1] - rear).normalize() * WHEELBASE_METRES;
250:             rear_points.push(rear);
251:         }
252:         for axle in std::iter::once(points)
253:             .chain(matches!(axles, AxleTracks::Both).then_some(rear_points.as_slice()))
254:         {
255:             for pair in axle.windows(2) {
256:                 let delta = pair[1] - pair[0];
257:                 if delta.length_squared() < GEOMETRY_EPSILON {
258:                     continue;
259:                 }
260:                 let normal = Vec2::new(-delta.y, delta.x).normalize();
261:                 for side in [-1.0, 1.0] {
262:                     let shift = normal * gauge * 0.5 * side;
263:                     let stroke = WheelStroke {
264:                         start: pair[0] + shift,
265:                         end: pair[1] + shift,
266:                         half_width: WHEEL_HALF_WIDTH_METRES + pass as f32 * 0.013,
267:                         strength: PASS_STRENGTHS[pass],
268:                     };
269:                     // Check the full feathered wheel envelope against the visible
270:                     // rectangle union, including halfway through each segment.
271:                     if [stroke.start, stroke.end, stroke.start.lerp(stroke.end, 0.5)]
272:                         .into_iter()
273:                         .any(|p| {
274:                             !union_support(p, stroke.half_width + WHEEL_FEATHER_METRES, |point| {
275:                                 self.clearance(point)
276:                             })
277:                         })
278:                     {
279:                         if matches!(axles, AxleTracks::Both) {
280:                             return;
281:                         }
282:                         continue;
283:                     }
284:                     candidate.push(stroke);
285:                 }
286:             }
287:         }
288:         self.strokes.extend(candidate);
289:     }
290: 
291:     pub(super) fn clearance(&self, point: Vec2) -> f32 {
292:         self.road_tiles
293:             .get(&TrafficTile::at(point))
294:             .into_iter()
295:             .flatten()
296:             .map(|&index| self.roads[index].clearance(point))
297:             .chain(
298:                 self.market_tiles
299:                     .get(&TrafficTile::at(point))
300:                     .into_iter()
301:                     .flatten()
302:                     .map(|&index| quad_clearance(self.markets[index], point)),
303:             )
304:             .fold(f32::NEG_INFINITY, f32::max)
305:     }
306: }
307: 
308: fn node_key(point: Vec2) -> (i32, i32) {
309:     let key = (point * NODE_SNAP_PER_METRE).round().as_ivec2();
310:     (key.x, key.y)
311: }
312: 
313: fn pass_dimensions(pass: usize, half_width: f32) -> (f32, f32) {
314:     let gauge = (MIN_GAUGE_METRES + pass as f32 * GAUGE_VARIATION_METRES).min(half_width * 0.85);
315:     let usable = (half_width * 0.68 - gauge * 0.5 - FRONTAGE_CLEARANCE_METRES).max(0.0);
316:     let offset = (pass as f32 / (VEHICLE_PASSES - 1) as f32 * 2.0 - 1.0) * usable;
317:     (gauge, offset)
318: }
319: 
320: fn bezier(p: [Vec2; 4], t: f32) -> Vec2 {
321:     p[0] * (1.0 - t).powi(3)
322:         + p[1] * 3.0 * (1.0 - t).powi(2) * t
323:         + p[2] * 3.0 * (1.0 - t) * t * t
324:         + p[3] * t.powi(3)
325: }

