9: pub(in crate::presentation) fn update_weather_occlusion_map(
10:     active: Res<ActiveTacticalScene>,
11:     scenes: Query<(
12:         &SceneEnvironment,
13:         Option<&SceneTerrain>,
14:         Option<&StrategicBackdrop>,
15:     )>,
16:     trees: Query<(&GlobalTransform, &StreamedTreePresentation)>,
17:     tree_cache: Res<TreePresentationCache>,
18:     mut state: ResMut<WeatherOcclusionState>,
19:     mut images: ResMut<Assets<Image>>,
20: ) {
21:     let Some(scene) = active.entity else {
22:         return;
23:     };
24:     let Some(map) = state
25:         .scene
26:         .filter(|selected| *selected == scene)
27:         .and(state.map.as_ref())
28:     else {
29:         return;
30:     };
31:     let Ok((environment, terrain, backdrop)) = scenes.get(scene) else {
32:         return;
33:     };
34:     let Some(terrain) = weather_surface(terrain, backdrop) else {
35:         return;
36:     };
37:     if environment.weather.precipitation == Precipitation::Clear {
38:         return;
39:     }
40: 
41:     let signature = weather_occlusion_tree_signature(scene, &trees);
42:     if state.tree_signature == Some(signature) {
43:         return;
44:     }
45:     let replacement = match weather_occlusion_image(terrain, map.range, &trees, &tree_cache) {
46:         Ok(image) => image,
47:         Err(error) => {
48:             warn!(%error, "Weather occlusion raster rejected");
49:             return;
50:         }
51:     };
52:     let Some(mut image) = images.get_mut(&map.image) else {
53:         return;
54:     };
55:     *image = replacement;
56:     state.tree_signature = Some(signature);
57: }
