97: fn weather_occlusion_image(
98:     terrain: &SceneTerrain,
99:     bounds: SceneElevationRange,
100:     trees: &Query<(&GlobalTransform, &StreamedTreePresentation)>,
101:     tree_cache: &TreePresentationCache,
102: ) -> GeometryResult<Image> {
103:     let pixel_count = WEATHER_OCCLUSION_RESOLUTION as usize * WEATHER_OCCLUSION_RESOLUTION as usize;
104:     let mut shelter_heights = vec![None; pixel_count];
105:     for (transform, presentation) in trees {
106:         let Some(branches) =
107:             tree_cache.weather_occlusion_branches(presentation.weather_occlusion_cache_key())
108:         else {
109:             continue;
110:         };
111:         for branch in branches.iter().filter(|branch| branch.depth <= 2) {
112:             rasterize_weather_branch(&mut shelter_heights, terrain, transform, branch)?;
113:         }
114:     }
115: 
116:     let minimum = bounds.minimum().metres() - 2.0;
117:     let range = PositiveLength::from_metres(bounds.maximum().metres() + 24.0 - minimum)?.metres();
118:     let mut pixels = vec![0; pixel_count * 4];
119:     for (index, height) in shelter_heights.into_iter().enumerate() {
120:         let Some(height) = height else {
121:             continue;
122:         };
123:         let encoded =
124:             (((height.metres() - minimum) / range).clamp(0.0, 1.0) * 65_535.0).round() as u16;
125:         pixels[index * 4] = (encoded & 0xff) as u8;
126:         pixels[index * 4 + 1] = (encoded >> 8) as u8;
127:         pixels[index * 4 + 3] = 255;
128:     }
129:     Ok(Image::new(
130:         Extent3d {
131:             width: WEATHER_OCCLUSION_RESOLUTION,
132:             height: WEATHER_OCCLUSION_RESOLUTION,
133:             depth_or_array_layers: 1,
134:         },
135:         TextureDimension::D2,
136:         pixels,
137:         TextureFormat::Rgba8Unorm,
138:         RenderAssetUsages::RENDER_WORLD,
139:     ))
140: }
