71:                     window.opening_id,
72:                 ),
73:             ));
74:         }
75:     });
76:     Ok(())
77: }

1: //! Anchors in the full-size tactical buildings along the shared frontage.
2: use super::preparation::{PreparationError, PreparationResult};
3: use super::protocol::{PlaceId, PlaceKind};
4: use super::staging::ConversationPose;
5: use crate::presentation::venues::select_building;
6: use adventuresim_building_generator::spatial_geometry::Position;
7: use adventuresim_building_generator::{OpeningUse, interior::InteriorLayout};
8: use adventuresim_tactical_core::prelude::*;
9: use adventuresim_tactical_core::scene_coordinates::{Scene, ScenePlanPoint};
10: use bevy::prelude::*;
11: 
12: pub(super) const ROOM_LAYER: usize = 0;
13: #[derive(Clone)]
14: pub(super) struct Venue {
15:     pub anchor: Position<Scene>,
16:     pub approach: Position<Scene>,
17:     pub positions: Vec<ConversationPose>,
18: }
19: 
20: struct SelectedBuildings {
21:     promoted: Vec<GeneratedBuilding>,
22:     selected: std::collections::HashMap<
23:         PlaceId,
24:         adventuresim_tactical_core::scene_input::SceneBuildingId,
25:     >,
26: }
