28: impl Venue {
29:     pub(super) fn from_building(
30:         building: &GeneratedBuilding,
31:         layout: &InteriorLayout,
32:     ) -> PreparationResult<Self> {
33:         let bounds = building.collision.bounds;
34:         let transform = building.transform()?;
35:         let positions = ConversationPose::in_building(building, layout)?;
36:         let anchor = positions
37:             .first()
38:             .ok_or(PreparationError::MissingConversationPosition {
39:                 building: building.placement.id,
40:             })?
41:             .anchor;
42:         let door = building.plan.opening_assemblies.iter().find(|opening| {
43:             matches!(opening.use_kind, OpeningUse::Door | OpeningUse::Gate)
44:                 && opening.frame.outside_room.is_none()
45:                 && opening.sill_elevation_metres.abs() < 0.1
46:         });
47:         let outward = door.map_or(Vec3::Z, |door| {
48:             Vec3::new(door.frame.outward.x, 0.0, door.frame.outward.y)
49:         });
50:         let outward = transform.rotation * outward;
51:         // A standing-eye perspective from the real approach, with the entire facade in view.
52:         let distance = bounds.extent()?.metres().xz().max_element() * 0.8 + 4.0;
53:         let target = transform.translation;
54:         let eye = Vec3::new(
55:             target.x,
56:             building.placement.base_elevation_metres.metres() + 1.7,
57:             target.z,
58:         ) + outward * distance;
59:         Ok(Self {
60:             anchor,
61:             approach: Position::from_metres(eye)?,
62:             positions,
63:         })
64:     }
65: }
