67: impl SelectedBuildings {
68:     fn prepare(
69:         input: &TacticalSceneInput,
70:         view: &super::protocol::StrategicView,
71:         generated: &mut crate::presentation::PreparedStrategicScene,
72:     ) -> PreparationResult<Self> {
73:         let mut promoted = Vec::new();
74:         let mut selected = std::collections::HashMap::new();
75:         for place in &view.places {
76:             let id = select_building(
77:                 input,
78:                 place.kind,
79:                 view.people
80:                     .iter()
81:                     .filter(|p| p.place == place.id)
82:                     .map(|p| p.id.0),
83:             );
84:             if let Some(id) = id {
85:                 selected.insert(place.id.clone(), id);
86:                 if !generated
87:                     .buildings
88:                     .iter()
89:                     .chain(promoted.iter())
90:                     .any(|b| b.placement.id == id)
91:                 {
92:                     let placement = input
93:                         .distant_buildings
94:                         .iter()
95:                         .find(|b| b.id == id)
96:                         .ok_or(PreparationError::MissingBuildingPlacement { building: id })?;
97:                     let program = placement.occupied_program();
98:                     let recipe = generated.building_recipes.get_or_generate(&program)?;
99:                     promoted.push(GeneratedBuilding {
100:                         placement: (*placement).into(),
101:                         plan: recipe.plan.clone(),
102:                         collision: recipe.collision.clone(),
103:                     });
104:                 }
105:             }
106:         }
107:         Ok(Self { promoted, selected })
108:     }
109: }
110: 
111: pub(super) fn prepare_venues(
112:     input: &TacticalSceneInput,
113:     view: &super::protocol::StrategicView,
114:     generated: &mut crate::presentation::PreparedStrategicScene,
115:     street: &mut Option<super::street::Street>,
116:     backdrop: &crate::presentation::StrategicBackdrop,
117: ) -> PreparationResult<std::collections::HashMap<PlaceId, Venue>> {
118:     let mut venues = std::collections::HashMap::new();
119:     let SelectedBuildings { promoted, selected } =
120:         SelectedBuildings::prepare(input, view, generated)?;
121:     generated.furniture.furnish_interiors(&promoted)?;
122:     generated.buildings.extend(promoted);
123:     *street = if view
124:         .places
125:         .iter()
126:         .any(|place| place.kind != PlaceKind::Camp)
127:     {
128:         Some(super::street::Street::arrange(
129:             input,
130:             &view.places,
131:             &selected,
132:             generated,
133:             backdrop,
134:         )?)
135:     } else {
136:         None
137:     };
138:     for place in &view.places {
139:         let mut venue = if let Some(building) = selected
140:             .get(&place.id)
141:             .and_then(|id| generated.buildings.iter().find(|b| b.placement.id == *id))
142:         {
143:             let interior = generated
144:                 .furniture
145:                 .interiors
146:                 .iter()
147:                 .find(|interior| interior.building_id == building.placement.id)
148:                 .ok_or(PreparationError::MissingInterior {
149:                     building: building.placement.id,
150:                 })?;

151:             Venue::from_building(building, &interior.layout)?
152:         } else {
153:             // Public squares and camps are real outdoor positions on the terrain.
154:             let elevation = backdrop.required_height_at(ScenePlanPoint::ORIGIN)?;
155:             let anchor = Position::from_metres(Vec3::Y * elevation.metres())?;
156:             Venue {
157:                 anchor,
158:                 positions: vec![ConversationPose {
159:                     anchor,
160:                     facing: Quat::IDENTITY,
161:                 }],
162:                 approach: Position::from_metres(anchor.metres() + Vec3::new(0.0, 1.7, 12.0))?,
163:             }
164:         };
165:         if matches!(place.kind, PlaceKind::Square | PlaceKind::Camp) {
166:             let position = venue.approach;
167:             let elevation = backdrop.required_height_at(ScenePlanPoint::from(position))?;
168:             venue.anchor = Position::from_metres(Vec3::new(
169:                 position.metres().x,
170:                 elevation.metres(),
171:                 position.metres().z,
172:             ))?;
173:             venue.positions = vec![ConversationPose {
174:                 anchor: venue.anchor,
175:                 facing: Quat::IDENTITY,
176:             }];
177:         }
178:         venues.insert(place.id.clone(), venue);
179:     }
180:     Ok(venues)
181: }
