1: //! Bounded return-trip images; scene identity includes the environment digest.
2: use super::*;
3: 
4: const RETAINED_CITY_VIEWS: usize = 2;
5: const RETAINED_IMAGE_BYTES: u64 = 64 * 1024 * 1024;
6: 
7: pub(super) struct SavedViews {
8:     identity: (String, String),
9:     frames: HashMap<ViewKey, Frame>,
10: }
11: 
12: impl SavedViews {
13:     fn bytes(&self) -> u64 {
14:         self.frames
15:             .values()
16:             .map(|f| u64::from(f.signature.rect.width) * u64::from(f.signature.rect.height) * 4)
17:             .sum()
18:     }
19: 
20:     fn discard(self, commands: &mut Commands) {
21:         for frame in self.frames.into_values() {
22:             commands.entity(frame.sprite).despawn();
23:         }
24:     }
25: }
26: 
27: impl CachedViews {
28:     pub(super) fn change_scene(&mut self, commands: &mut Commands, scene: &RetainedScene) {
29:         let mut frames = std::mem::take(&mut self.frames);
30:         for frame in frames.values_mut() {
31:             if let Some(camera) = frame.camera.take() {
32:                 deactivate(commands, camera);
33:                 self.free_cameras.push(camera);
34:             }
35:             commands.entity(frame.sprite).insert(Visibility::Hidden);
36:         }
37:         frames.retain(|_, frame| {
38:             if frame.remaining == 0 {
39:                 true
40:             } else {
41:                 commands.entity(frame.sprite).despawn();
42:                 false
43:             }
44:         });
45:         if !self.identity.1.is_empty() && !frames.is_empty() {
46:             self.previous.push_back(SavedViews {
47:                 identity: self.identity.clone(),
48:                 frames,
49:             });
50:         } else {
51:             SavedViews {
52:                 identity: self.identity.clone(),
53:                 frames,
54:             }
55:             .discard(commands);
56:         }
57:         self.identity = (scene.location.clone(), scene.digest.clone());
58:         if let Some(index) = self
59:             .previous
60:             .iter()
61:             .position(|saved| saved.identity == self.identity)
62:         {
63:             self.frames = self.previous.remove(index).expect("retained city").frames;
64:         }
65:         while self.previous.len() > RETAINED_CITY_VIEWS
66:             || self.previous.iter().map(SavedViews::bytes).sum::<u64>() > RETAINED_IMAGE_BYTES
67:         {
68:             if let Some(old) = self.previous.pop_front() {
69:                 old.discard(commands);
70:             }
71:         }
72:         self.scene = scene.root;
73:     }
74: }
