7: 
8: #[derive(Component)]
9: pub(super) struct SceneEquipment;
10: 
11: #[derive(Component, Default)]
12: pub(super) struct Wardrobe(Vec<EquipmentAppearance>, Vec<Entity>);
13: 
14: pub(super) fn sync_equipment(
15:     mut commands: Commands,
16:     view: Option<Res<StrategicView>>,
17:     scene: Res<RetainedScene>,
18:     wardrobes: Query<&Wardrobe>,
19: ) {
20:     let Some(view) = view else {
21:         return;
22:     };
23:     if !view.is_changed() && !scene.is_changed() {
24:         return;
25:     }
26:     for person in &view.people {
27:         let Some(model) = scene.people.get(&person.id) else {
28:             continue;
29:         };
30:         let owner = model.entity;
31:         if let Ok(current) = wardrobes.get(owner) {
32:             if current.0 == person.equipment {
33:                 continue;
34:             }
35:             for entity in &current.1 {
36:                 commands.entity(*entity).despawn();
37:             }
38:         }
39:         let items: HashMap<_, _> = person
40:             .equipment
41:             .iter()
42:             .map(|item| (item.id.clone(), commands.spawn_empty().id()))
43:             .collect();
44:         for item in &person.equipment {
45:             spawn_item(&mut commands, owner, item, &items);
46:         }
47:         commands.entity(owner).insert(Wardrobe(
48:             person.equipment.clone(),
49:             items.into_values().collect(),
50:         ));
51:     }
52: }
