54: fn spawn_item(
55:     commands: &mut Commands,
56:     owner: Entity,
57:     item: &EquipmentAppearance,
58:     items: &HashMap<PresentationId, Entity>,
59: ) {
60:     let entity = items[&item.id];
61:     let Some(definition) = item_catalog::definition(&item.item) else {
62:         commands.entity(entity).despawn();
63:         return;
64:     };
65:     let Some(equipment) = &definition.equipment else {
66:         commands.entity(entity).despawn();
67:         return;
68:     };
69:     let physical = equipment.physical;
70:     let mut entity = commands.entity(entity);
71:     entity.insert((
72:         SceneEquipment,
73:         ItemOf(owner),
74:         ChildOf(owner),
75:         Transform::IDENTITY,
76:         ItemProperties {
77:             id: item.item.clone(),
78:             weight: definition.weight_kg,
79:         },
80:         TacticalEquipmentPhysical {
81:             dimensions_m: Vec3::from_array(physical.dimensions_m),
82:             grip_to_tip_m: physical.grip_to_tip_m,
83:             // These entities present equipment; they have no striking volume.
84:             striking_head_length_m: 0.0,
85:             anchor_offset_m: Vec3::from_array(physical.anchor_offset_m),
86:         },
87:         EquipmentTopology {
88:             placement_id: Some(item.placement.clone()),
89:             occupancies: item
90:                 .occupancies
91:                 .iter()
92:                 .enumerate()
93:                 .filter_map(|(index, row)| {
94:                     Some(EquipmentTopologyOccupancy {
95:                         occupancy_id: format!("presentation:{}:{index}", item.id.0),
96:                         anchor: match &row.anchor {
97:                             AppearanceAnchor::Character(location) => {
98:                                 TacticalEquipmentAnchor::CharacterLocation(*location)
99:                             }
100:                             AppearanceAnchor::Attachment { parent, point } => {
101:                                 TacticalEquipmentAnchor::ItemAttachment {
102:                                     parent: *items.get(parent)?,
103:                                     attachment_point_id: point.clone(),
104:                                 }
105:                             }
106:                         },
107:                         channel: row.channel,
108:                         order: row.order,
109:                         requirement_index: row.requirement_index,
110:                         capacity_index: row.capacity_index,
111:                     })
112:                 })
113:                 .collect(),
114:         },
115:     ));
116:     if let Some(recipe) = &item.weapon {
117:         entity.insert(WeaponAppearance {
118:             generator_version: recipe.generator_version,
119:             design_hash: recipe.design_hash,
120:             recipe: recipe.recipe.clone(),
121:         });
122:     }
123:     if let Some(recipe) = &item.holder {
124:         entity.insert(WeaponHolderAppearance {
125:             generator_version: recipe.generator_version,
126:             design_hash: recipe.design_hash,
127:             recipe: recipe.recipe.clone(),
128:         });
129:     }
130:     if let Some(slot) = held_slot(item) {
131:         entity.insert(slot);
132:     }
133: }
134: 
135: fn held_slot(item: &EquipmentAppearance) -> Option<EquipSlot> {
136:     use adventuresim_core::item_catalog::{EquipmentChannel, EquipmentLocation};
137:     item.occupancies.iter().find_map(|row| match row.anchor {
138:         AppearanceAnchor::Character(EquipmentLocation::LeftHand)
139:             if row.channel == EquipmentChannel::Held =>
140:         {
141:             Some(EquipSlot::HoldingLeft)
142:         }
143:         AppearanceAnchor::Character(EquipmentLocation::RightHand)
144:             if row.channel == EquipmentChannel::Held =>
145:         {
146:             Some(EquipSlot::HoldingRight)
147:         }
148:         _ => None,
149:     })
150: }

