6: pub(super) fn spawn_building(
7:     commands: &mut Commands,
8:     building: GeneratedBuilding,
9:     root: Entity,
10:     input: Option<&TacticalSceneInput>,
11: ) -> Result {
12:     let transform = building.transform()?;
13:     let datum = building.geometry_datum()?;
14:     let mut entity = commands.spawn((
15:         Transform::from_translation(transform.translation).with_rotation(transform.rotation),
16:         ChildOf(root),
17:     ));
18:     if let Some(establishment) = input.and_then(|input| {
19:         input
20:             .establishments
21:             .iter()
22:             .find(|e| e.building_id == building.placement.id)
23:     }) {
24:         entity.insert(establishment.clone());
25:     }
26:     let entity = entity.id();
27:     for leaf in compile_operable_doors(&building.plan)? {
28:         let pose = datum.door(leaf)?;
29:         let door = pose.leaf();
30:         let centre = door.closed_centre.metres();
31:         commands.spawn((
32:             SceneDoor {
33:                 building_id: building.placement.id,
34:                 opening_id: door.opening,
35:                 size_metres: door.size_metres,
36:                 doorway_centre_metres: door.closed_centre,
37:                 tangent: door.tangent.spatial(),
38:                 outward: door.outward.spatial(),
39:             },
40:             Transform::from_translation(centre).with_rotation(pose.native_rotation()),
41:             ChildOf(root),
42:         ));
43:     }
44:     for leaf in compile_operable_windows(&building.plan)? {
45:         let pose = datum.window(leaf)?;
46:         let window = pose.leaf();
47:         let centre = window.closed_centre.metres();
48:         commands.spawn((
49:             SceneWindow {
50:                 building_id: building.placement.id,
51:                 opening_id: window.opening,
52:                 leaf: window.leaf,
53:                 bars: window.bars,
54:                 size_metres: window.size_metres,
55:                 opening_centre_metres: window.closed_centre,
56:                 tangent: window.tangent.spatial(),
57:                 outward: window.outward.spatial(),
58:             },
59:             Transform::from_translation(centre).with_rotation(pose.native_rotation()),
60:             ChildOf(root),
61:         ));
62:     }
63:     // Insert the prepared geometry together with its descriptor so the add
64:     // observer can consume it without regenerating the same tactical plan.
65:     commands.entity(entity).insert((
66:         crate::presentation::PreparedBuildingGeometry(
67:             adventuresim_tactical_core::scene_input::GeneratedBuildingRecipe {
68:                 program: building.placement.program.clone(),
69:                 plan: building.plan,
70:                 collision: building.collision,
71:             },
72:         ),
73:         SceneBuilding {
74:             id: building.placement.id,
75:             program: building.placement.program,
76:             orientation: building.placement.orientation,
77:         },
78:     ));
79:     Ok(())
80: }
