87:     for furniture in &generated.furniture.instances {
88:         commands.spawn((
89:             furniture.scene,
90:             Transform::from_translation(furniture.position_metres.metres())
91:                 .with_rotation(Quat::from_rotation_y(furniture.orientation.yaw_radians())),
92:             ChildOf(root),
93:         ));
94:     }
95: }

