126:         let rank = view
127:             .people
128:             .iter()
129:             .filter(|other| {
130:                 other.place == person.place && other.presentation == person.presentation
131:             })
132:             .position(|other| other.id == person.id)
133:             .unwrap_or(0);
134:         let pose = venue.positions[rank % venue.positions.len()];
135:         let anchor = pose.anchor;
136:         let facing = pose.facing;
137:         if let Some(current) = scene.people.get_mut(&person.id) {
138:             if current.anchor != anchor || current.facing != facing {
139:                 current.anchor = anchor;
