205: fn inherit_model_layers(
206:     mut commands: Commands,
207:     added: Query<Entity, (With<Mesh3d>, Without<RenderLayers>)>,
208:     parents: Query<&ChildOf>,
209:     models: Query<&SceneModel>,
210:     equipment_roots: Query<&crate::equipment::ItemPlaceholder>,
211:     owners: Query<&adventuresim_tactical_core::prelude::ItemOf>,
212: ) {
213:     for entity in &added {
214:         let mut current = entity;
215:         while let Ok(parent) = parents.get(current) {
216:             current = parent.parent();
217:             let equipment_owner = equipment_roots
218:                 .get(current)
219:                 .ok()
220:                 .and_then(|item| owners.get(item.0).ok())
221:                 .map(|owner| owner.0);
222:             if let Ok(model) = models
223:                 .get(current)
224:                 .or_else(|_| models.get(equipment_owner.unwrap_or(current)))
225:             {
226:                 commands
227:                     .entity(entity)
228:                     .insert((RenderLayers::none().with(model.0), SceneMesh));
229:                 break;
230:             }
231:         }
232:     }
233: }
