239: fn cull_equipment(
240:     mut commands: Commands,
241:     meshes: Res<Assets<Mesh>>,
242:     equipment: Query<
243:         (Entity, &Mesh3d),
244:         (
245:             With<SceneMesh>,
246:             With<bevy::camera::visibility::NoFrustumCulling>,
247:         ),
248:     >,
249: ) {
250:     // Strategic actors only idle in place. A conservative margin covers the
251:     // idle motion and identity morphs while excluding other venues' equipment.
252:     const IDLE_BOUNDS_MARGIN_METRES: f32 = 0.4;
253:     use bevy::camera::{primitives::MeshAabb, visibility::NoAutoAabb};
254:     for (entity, mesh) in &equipment {
255:         let Some(mut bounds) = meshes.get(&mesh.0).and_then(MeshAabb::compute_aabb) else {
256:             continue;
257:         };
258:         bounds.half_extents += bevy::math::Vec3A::splat(IDLE_BOUNDS_MARGIN_METRES);
259:         commands
260:             .entity(entity)
261:             .insert((bounds, NoAutoAabb))
262:             .remove::<bevy::camera::visibility::NoFrustumCulling>();
263:     }
264: }
