270: fn sync_room_lights(
271:     mut commands: Commands,
272:     scene: Res<RetainedScene>,
273:     lights: Query<(Entity, Option<&RenderLayers>), Or<(With<DirectionalLight>, With<PointLight>)>>,
274: ) {
275:     let layers = RenderLayers::from_iter(
276:         std::iter::once(buildings::ROOM_LAYER)
277:             .chain(scene.people.values().map(|person| person.layer)),
278:     );
279:     for (entity, current) in &lights {
280:         if current.is_none_or(|current| current.iter().any(|layer| layer == buildings::ROOM_LAYER))
281:             && current != Some(&layers)
282:         {
283:             commands.entity(entity).insert(layers.clone());
284:         }
285:     }
286: }
