14:     pub x: u32,
15:     pub y: u32,
16:     pub width: u32,
17:     pub height: u32,
18:     pub full_width: u32,
19:     pub full_height: u32,
20:     pub offset_x: f32,
21:     pub offset_y: f32,
22: }
23: 
24: impl CanvasRect {
25:     pub(super) fn uncropped(self) -> Self {
26:         Self {
27:             x: 0,
28:             y: 0,
29:             width: self.full_width,
30:             height: self.full_height,
31:             offset_x: 0.0,
32:             offset_y: 0.0,
33:             ..self
34:         }
35:     }
36: 
37:     pub fn apply(self, camera: &mut Camera, size: UVec2) {
38:         let origin = UVec2::new(self.x, self.y).min(size);
39:         let extent = UVec2::new(self.width, self.height).min(size - origin);
40:         camera.is_active = extent.min_element() > 0;
41:         if !camera.is_active {
42:             return;
43:         }
44:         camera.viewport = Some(bevy::camera::Viewport {
45:             physical_position: origin,
46:             physical_size: extent,
47:             ..default()
48:         });
49:         camera.sub_camera_view = Some(bevy::camera::SubCameraView {
50:             full_size: UVec2::new(self.full_width.max(1), self.full_height.max(1)),
51:             offset: Vec2::new(self.offset_x, self.offset_y),
52:             size: extent,
53:         });
54:     }
55: }
