126:             offset_y: 0.0,
127:         };
128:         rect.apply(&mut camera, UVec2::new(800, 600));
129:         assert!(!camera.is_active);
130:         CanvasRect { x: 760, ..rect }.apply(&mut camera, UVec2::new(800, 600));
131:         assert_eq!(camera.viewport.unwrap().physical_size, UVec2::new(40, 80));
132:     }
133: }

1: //! One census per resident scene, outside steady rendering and navigation.
2: use super::{RetainedScene, cached_views::CachedViews, status::SceneAssetsReady};
3: use adventuresim_tactical_core::prelude::{SceneDoor, SceneFurniture, SceneWindow};
4: use bevy::prelude::*;
5: use std::collections::{BTreeMap, HashSet};
6: 
7: const MAX_CENSUS_GROUPS: usize = 20;
8: 
9: #[derive(Default, serde::Serialize)]
10: struct Counts {
11:     instances: usize,
12:     visible: usize,
13:     visible_cuboids: usize,
14:     #[serde(skip)]
15:     meshes: HashSet<AssetId<Mesh>>,
16:     unique_meshes: usize,
17: }
18: 
19: #[expect(
20:     clippy::type_complexity,
21:     reason = "the hierarchy query groups the component tags used to classify scene parts"
22: )]
23: pub(super) fn census(
24:     scene: Res<RetainedScene>,
25:     ready: Res<SceneAssetsReady>,
26:     cache: Res<CachedViews>,
27:     mut recorded: Local<Option<Entity>>,
28:     meshes: Res<Assets<Mesh>>,
29:     parts: Query<(Entity, &Mesh3d, Option<&ViewVisibility>)>,
30:     hierarchy: Query<(
31:         Option<&Name>,
32:         Option<&ChildOf>,
33:         Has<SceneDoor>,
34:         Has<SceneWindow>,
35:         Has<SceneFurniture>,
36:         Has<crate::presentation::PresentedSign>,
37:     )>,
38: ) {
39:     if !ready.0 || !cache.is_ready() || scene.root.is_none() || scene.root == *recorded {
40:         return;
41:     }
42:     *recorded = scene.root;
43:     let mut groups: BTreeMap<String, Counts> = BTreeMap::new();
44:     for (entity, mesh, visible) in &parts {
45:         let mut cursor = entity;
46:         let label = loop {
47:             let Ok((name, parent, door, window, furniture, sign)) = hierarchy.get(cursor) else {
48:                 break "unnamed";
49:             };
50:             if door {
51:                 break "operable doors";
52:             }
53:             if window {
54:                 break "operable windows";
55:             }
56:             if furniture {
57:                 break "furniture";
58:             }
59:             if sign {
60:                 break "shop signs";
61:             }
62:             if let Some(name) = name {
63:                 break name.as_str();
64:             }
65:             let Some(parent) = parent else {
66:                 break "unnamed";
67:             };
68:             cursor = parent.parent();
69:         };
70:         let count = groups.entry(label.to_owned()).or_default();
71:         count.instances += 1;
72:         count.meshes.insert(mesh.id());
73:         if visible.is_some_and(|visible| visible.get()) {
74:             count.visible += 1;
75:             count.visible_cuboids +=
76:                 usize::from(meshes.get(mesh).is_some_and(|mesh| {
77:                     mesh.try_indices().is_ok_and(|indices| indices.len() == 36)
78:                 }));
79:         }
80:     }
81:     let mut groups: Vec<_> = groups.into_iter().collect();
82:     groups.sort_by_key(|(_, count)| std::cmp::Reverse(count.visible));
83:     for (_, count) in &mut groups {
84:         count.unique_meshes = count.meshes.len();
85:     }
86:     // Bounded telemetry, not a frame-by-frame traversal or diagnostic overlay.
87:     for (name, count) in groups.into_iter().take(MAX_CENSUS_GROUPS) {
88:         info!(
89:             "City mesh census {name}: {}",
90:             serde_json::to_string(&count).unwrap()
91:         );
92:     }
93: }

1: //! Retained residents outside live views must not be skinned for shadow maps.
2: use super::{SceneMesh, views::StrategicCamera};
3: use bevy::{camera::visibility::RenderLayers, light::NotShadowCaster, prelude::*};
4: 
5: #[derive(Component)]
6: pub(super) struct InactiveCharacterShadow;
7: 
8: #[expect(
9:     clippy::type_complexity,
10:     reason = "the query reads render layers and shadow ownership together"
11: )]
12: pub(super) fn sync_character_shadows(
13:     mut commands: Commands,
14:     cameras: Query<(&Camera, &RenderLayers), With<StrategicCamera>>,
15:     meshes: Query<
16:         (
17:             Entity,
18:             &RenderLayers,
19:             Has<NotShadowCaster>,
20:             Has<InactiveCharacterShadow>,
21:         ),
22:         With<SceneMesh>,
23:     >,
24: ) {
25:     let active = cameras
26:         .iter()
27:         .filter(|(camera, _)| camera.is_active)
28:         .fold(RenderLayers::none(), |layers, (_, camera)| {
29:             layers.union(camera)
30:         });
31:     for (entity, layers, disabled, owned) in &meshes {
32:         if layers.intersects(&active) {
33:             if owned {
34:                 commands
35:                     .entity(entity)
36:                     .remove::<(NotShadowCaster, InactiveCharacterShadow)>();
37:             }
38:         } else if !disabled {
39:             commands
40:                 .entity(entity)
41:                 .insert((NotShadowCaster, InactiveCharacterShadow));
42:         }
43:     }
44: }
45: 
46: #[cfg(test)]
47: mod tests {
48:     use super::*;
49: 
50:     #[test]
51:     fn live_views_restore_only_the_shadow_flags_owned_by_character_culling() {
52:         let mut app = App::new();
53:         app.add_systems(Update, sync_character_shadows);
54:         let stage = app
55:             .world_mut()
56:             .spawn((StrategicCamera, Camera::default(), RenderLayers::layer(3)))
57:             .id();
58:         let first = app
59:             .world_mut()
60:             .spawn((SceneMesh, RenderLayers::layer(3)))
61:             .id();
62:         let second = app
63:             .world_mut()
64:             .spawn((SceneMesh, RenderLayers::layer(4)))
65:             .id();
66:         let authored = app
67:             .world_mut()
68:             .spawn((SceneMesh, RenderLayers::layer(4), NotShadowCaster))
69:             .id();
70:         app.update();
71:         assert!(app.world().get::<NotShadowCaster>(first).is_none());
72:         assert!(app.world().get::<NotShadowCaster>(second).is_some());
73:         let portrait = app
74:             .world_mut()
75:             .spawn((StrategicCamera, Camera::default(), RenderLayers::layer(4)))
76:             .id();
77:         app.update();
78:         assert!(app.world().get::<NotShadowCaster>(second).is_none());
79:         assert!(app.world().get::<NotShadowCaster>(authored).is_some());
80:         app.world_mut()
81:             .get_mut::<Camera>(portrait)
82:             .unwrap()
83:             .is_active = false;
84:         app.update();
85:         assert!(app.world().get::<NotShadowCaster>(second).is_some());
86:         app.world_mut()
87:             .entity_mut(stage)
88:             .insert(RenderLayers::layer(4));
89:         app.update();
90:         assert!(app.world().get::<NotShadowCaster>(first).is_some());
91:         assert!(app.world().get::<NotShadowCaster>(second).is_none());
92:         assert!(app.world().get::<NotShadowCaster>(authored).is_some());
93:     }
