19: 
20: impl CharacterReadiness<'_, '_> {
21:     pub(super) fn counts(
22:         &self,
23:         view: Option<&StrategicView>,
24:         scene: &RetainedScene,
25:     ) -> CharacterCounts {
26:         let mut counts = CharacterCounts {
27:             roster: view.map_or(0, |view| view.people.len()),
28:             loaded: self.models.iter().count(),
29:             posed: self
30:                 .poses
31:                 .iter()
32:                 .filter(|pose| pose.has_presented_pose())
33:                 .count(),
34:             required: 0,
35:             required_posed: 0,
36:         };
37:         if let Some(view) = view {
38:             for person in view
39:                 .people
40:                 .iter()
41:                 .filter(|person| view.requires_person(person.id))
42:             {
43:                 counts.required += 1;
44:                 if scene.people.get(&person.id).is_some_and(|person| {
45:                     self.poses
46:                         .get(person.entity)
47:                         .is_ok_and(|pose| pose.has_presented_pose())
48:                 }) {
49:                     counts.required_posed += 1;
50:                 }
51:             }
52:         }
53:         counts
54:     }
55: }

