150:     if view.as_ref().is_some_and(|view| view.is_changed()) {
151:         *settled = 0;
152:     }
153:     let installed = view.as_ref().is_some_and(|view| {
154:         scene.location == view.location
155:             && scene.next_place == view.places.len()
156:             && scene.pending.is_empty()
157:             && view
158:                 .people
159:                 .iter()
160:                 .filter(|person| view.requires_person(person.id))
161:                 .all(|person| scene.people.contains_key(&person.id))
162:     }) && counts.loaded == scene.people.len()
163:         && counts.posed == counts.loaded
164:         && textures_ready
165:         && city.as_ref().is_none_or(|city| city.finished())
166:         && terrain.is_empty()
167:         && sky.is_ready(&settings)
168:         && failure.0.is_none()
169:         && scene.error.is_none();
170:     installed_ready.0 = installed;
171:     let complete = installed
172:         && equipment_ready
173:         && waiting == 0
174:         && city.as_ref().is_none_or(|city| {
175:             city.total == 0 || crate::presentation::city_gpu_ready(PresentationOwner::Scene)
176:         });
177:     assets_ready.0 = complete;
178:     if complete && cache.is_ready() {
