189:         installed_ready: installed,
190:         snapshots_pending: cache.pending_captures(),
191:         settled_render_frames: *settled,
192:         buildings: scene.next_place,
193:         street: scene.street.clone(),
194:         characters: counts.roster,
195:         loaded_characters: counts.loaded,
196:         posed_characters: counts.posed,
197:         required_characters: counts.required,
198:         posed_required_characters: counts.required_posed,
199:         textures_ready,
200:         sky_ready: sky.is_ready(&settings),
201:         terrain_pending: terrain.iter().count(),
202:         city_pending: city
203:             .as_ref()
204:             .map_or(0, |city| city.total - city.completed()),
205:         waiting_pipelines: waiting,
206:         equipment_ready,
207:         equipment_pending: (!equipment_ready).then(|| equipment.pending_summary(items.iter())),
208:         error: status_error(&scene, &failure, city.as_deref(), equipment_state),
209:     };
210:     status.publish();
