213: fn status_error(
214:     scene: &RetainedScene,
215:     failure: &SceneAssetFailure,
216:     city: Option<&crate::presentation::PendingCityBuildings>,
217:     equipment_state: std::result::Result<bool, &'static str>,
218: ) -> Option<String> {
