1: //! One full-size frontage in the retained city, viewed through one perspective camera.
2: use super::preparation::{PreparationError, PreparationResult};
3: use super::protocol::PlaceId;
4: use adventuresim_building_generator::OpeningUse;
5: use adventuresim_building_generator::spatial_geometry::Position;
6: use adventuresim_tactical_core::prelude::*;
7: use adventuresim_tactical_core::scene_coordinates::{PlanDisplacement, Scene, ScenePlanPoint};
8: use bevy::prelude::*;
9: use serde::Serialize;
10: use std::collections::HashMap;
11: 
12: const BUILDING_GAP_METRES: f32 = 4.0;
13: const MINIMUM_BAY_METRES: f32 = 18.0;
14: const CITY_CLEARANCE_METRES: f32 = 128.0;
15: const SKY_MARGIN_METRES: f32 = 8.0;
16: const GROUND_DEPTH_METRES: f32 = 512.0;
17: const EYE_HEIGHT_METRES: f32 = 1.7;
18: const FRAME_CENTRE_HEIGHT_FRACTION: f32 = 0.45;
19: 
20: #[derive(Clone, Serialize)]
21: pub(super) struct StreetBay {
22:     pub id: String,
23:     pub width: f32,
24: }
25: 
26: #[derive(Clone, Serialize)]
27: pub(super) struct Street {
28:     pub bays: Vec<StreetBay>,
29:     pub width: f32,
30:     pub height: f32,
31:     #[serde(skip)]
32:     pub front: Position<Scene>,
33: }
34: 
35: #[derive(Component)]
36: pub(super) struct StreetGround(Street);
37: 
38: struct BuildingRelocation {
39:     before: Transform,
40:     after: Transform,
41: }
42: 
43: impl Street {
44:     pub(super) fn arrange(
45:         input: &TacticalSceneInput,
46:         places: &[super::protocol::Place],
47:         selected: &HashMap<PlaceId, adventuresim_tactical_core::scene_input::SceneBuildingId>,
48:         generated: &mut crate::presentation::PreparedStrategicScene,
49:         backdrop: &crate::presentation::StrategicBackdrop,
50:     ) -> PreparationResult<Self> {
51:         let front_z = input
52:             .distant_buildings
53:             .iter()
54:             .map(|b| b.centre_metres.metres().y)
55:             .chain(
56:                 generated
57:                     .buildings
58:                     .iter()
59:                     .map(|b| b.placement.centre_metres.metres().y),
60:             )
61:             .fold(0.0, f32::max)
62:             + CITY_CLEARANCE_METRES;
63:         let front_point = ScenePlanPoint::try_from(Vec2::new(0.0, front_z))?;
64:         let elevation = backdrop.required_height_at(front_point)?;
65:         let mut street = Self {
66:             bays: Vec::new(),
67:             width: 0.0,
68:             height: MINIMUM_BAY_METRES,
69:             front: Position::from_metres(Vec3::new(0.0, elevation.metres(), front_z))?,
70:         };
71:         let mut moves = HashMap::new();
72:         for place in places {
73:             let building = selected.get(&place.id).and_then(|id| {
74:                 generated
75:                     .buildings
76:                     .iter_mut()
77:                     .find(|b| b.placement.id == *id)
78:             });
79:             let mut width = MINIMUM_BAY_METRES;
80:             if let Some(building) = building {
81:                 let before = building.transform()?;
82:                 let outward = building
83:                     .plan
84:                     .opening_assemblies
85:                     .iter()
86:                     .find(|opening| {
87:                         matches!(opening.use_kind, OpeningUse::Door | OpeningUse::Gate)
88:                             && opening.frame.outside_room.is_none()
89:                             && opening.sill_elevation_metres.abs() < 0.1
90:                     })
91:                     .map_or(Vec2::Y, |opening| opening.frame.outward);
92:                 let yaw = -outward.x.atan2(outward.y);
93:                 let orientation = BuildingOrientation::from_radians(yaw)
94:                     .ok_or(PreparationError::DoorwayOrientation)?;
95:                 let extent = building.collision.bounds.extent()?.metres();
96:                 let rotation = Quat::from_rotation_y(yaw);
97:                 let size =
98:                     (rotation * Vec3::X * extent.x).abs() + (rotation * Vec3::Z * extent.z).abs();
99:                 width = width.max(size.x + BUILDING_GAP_METRES);
100:                 street.height = street.height.max(extent.y + SKY_MARGIN_METRES);
101:                 building.placement.orientation = orientation;
102:                 building.placement.centre_metres =
103:                     adventuresim_tactical_core::scene_coordinates::ScenePlanPoint::try_from(
104:                         Vec2::new(street.width + width * 0.5, front_z - size.z * 0.5),
105:                     )?;
106:                 building.placement.base_elevation_metres = elevation;
107:                 moves.insert(
108:                     building.placement.id,
109:                     BuildingRelocation {
110:                         before,
111:                         after: building.transform()?,
112:                     },
113:                 );
114:             }
115:             street.bays.push(StreetBay {
116:                 id: place.id.0.clone(),
117:                 width,
118:             });
119:             street.width += width;
120:         }
121:         let centering = PlanDisplacement::try_from(Vec2::new(-street.width * 0.5, 0.0))?;
122:         for building in &mut generated.buildings {
123:             if let Some(relocation) = moves.get_mut(&building.placement.id) {
124:                 let centre = building.placement.centre_metres;
125:                 building.placement.centre_metres = centre.translated(centering)?;
126:                 relocation.after = building.transform()?;
127:             }
128:         }
129:         relocate_interior_furniture(&mut generated.furniture, &moves)?;
130:         Ok(street)
131:     }
132: 
133:     pub(super) fn camera(&self) -> Transform {
134:         let target = self.front.metres() + Vec3::Y * self.height * FRAME_CENTRE_HEIGHT_FRACTION;
135:         Transform::from_translation(
136:             self.front.metres() + Vec3::new(0.0, EYE_HEIGHT_METRES, self.distance()),
137:         )
138:         .looking_at(target, Vec3::Y)
139:     }
140: 
141:     pub(super) fn vertical_fov(&self) -> f32 {
142:         2.0 * (self.height * 0.5 / self.distance()).atan()
143:     }
144: 
145:     pub(super) fn spawn_ground(&self, commands: &mut Commands, root: Entity) {
146:         commands.spawn((StreetGround(self.clone()), ChildOf(root)));
147:     }
148:     fn distance(&self) -> f32 {
149:         // Keep a normal horizontal lens across the wide strip, rather than an
150:         // extreme wide-angle lens obtained by retaining the old vertical FOV.
151:         let fov = crate::presentation::TacticalCameraSetup::default()
152:             .vertical_fov_degrees
153:             .to_radians();
154:         self.width.max(MINIMUM_BAY_METRES) * 0.5 / (fov * 0.5).tan()
155:     }
156: }
157: 
158: pub(super) fn build_ground(
159:     mut commands: Commands,
160:     grounds: Query<(Entity, &StreetGround), Added<StreetGround>>,

161:     mut meshes: ResMut<Assets<Mesh>>,
162:     mut materials: ResMut<Assets<StandardMaterial>>,
163: ) {
164:     for (entity, ground) in &grounds {
165:         let street = &ground.0;
166:         commands.entity(entity).insert((
167:             Mesh3d(
168:                 meshes.add(
169:                     Plane3d::default()
170:                         .mesh()
171:                         .size(street.width + GROUND_DEPTH_METRES, GROUND_DEPTH_METRES),
172:                 ),
173:             ),
174:             MeshMaterial3d(materials.add(StandardMaterial {
175:                 base_color: Color::srgb(0.25, 0.23, 0.19),
176:                 perceptual_roughness: 1.0,
177:                 ..default()
178:             })),
179:             Transform::from_translation(street.front.metres() + Vec3::Y * 0.01),
180:         ));
181:     }
182: }
183: 
184: fn relocate_interior_furniture(
185:     furniture: &mut FurnitureLayout,
186:     moves: &HashMap<adventuresim_tactical_core::scene_input::SceneBuildingId, BuildingRelocation>,
187: ) -> PreparationResult<()> {
188:     for furniture in &mut furniture.instances {
189:         if let FurnitureLocation::Interior { building_id, .. } = furniture.scene.location
190:             && let Some(relocation) = moves.get(&building_id)
191:         {
192:             let local = relocation
193:                 .before
194:                 .compute_affine()
195:                 .inverse()
196:                 .transform_point3(furniture.position_metres.metres());
197:             furniture.position_metres =
198:                 adventuresim_building_generator::spatial_geometry::Position::from_metres(
199:                     relocation.after.transform_point(local),
200:                 )?;
201:             let delta = (relocation.after.rotation * relocation.before.rotation.inverse())
202:                 .to_euler(EulerRot::YXZ)
203:                 .0;
204:             furniture.orientation =
205:                 BuildingOrientation::from_radians(furniture.orientation.yaw_radians() + delta)
206:                     .ok_or(PreparationError::FurnitureOrientation)?;
207:         }
208:     }
209:     Ok(())
210: }
