16: 
17: const HEAD_HEIGHT_METRES: f32 = 1.65;
18: const PORTRAIT_DISTANCE_METRES: f32 = 0.30;
19: // Actor views retain nearby room/street context. The header alone needs the
20: // distant skyline; drawing that entire city behind an interior wastes GPU work.
21: const ACTOR_VIEW_DISTANCE_METRES: f32 = 128.0;
22: use super::staging::CONVERSATION_DISTANCE_METRES;
23: 
24: pub(super) struct ViewSpec {
25:     pub cache: Option<super::cached_views::ViewKey>,
26:     pub rect: CanvasRect,
27:     pub transform: Transform,
28:     pub projection: Projection,
29:     pub layers: RenderLayers,
30: }
