32: pub(super) fn person_view(
33:     rect: CanvasRect,
34:     anchor: Position<Scene>,
35:     facing: Quat,
36:     portrait: bool,
37:     layers: RenderLayers,
38: ) -> ViewSpec {
39:     let target = anchor.metres() + Vec3::Y * if portrait { HEAD_HEIGHT_METRES } else { 1.2 };
40:     let distance = if portrait {
41:         PORTRAIT_DISTANCE_METRES
42:     } else {
43:         CONVERSATION_DISTANCE_METRES
44:     };
45:     ViewSpec {
46:         cache: None,
47:         rect,
48:         transform: Transform::from_translation(target + facing * Vec3::Z * distance)
49:             .looking_at(target, Vec3::Y),
50:         projection: PerspectiveProjection {
51:             fov: crate::presentation::TacticalCameraSetup::default()
52:                 .vertical_fov_degrees
53:                 .to_radians(),
54:             near: 0.05,
55:             far: ACTOR_VIEW_DISTANCE_METRES,
56:             ..default()
57:         }
58:         .into(),
59:         layers,
60:     }
61: }
