63: pub(super) fn sync_views(
64:     mut commands: Commands,
65:     requested: Option<Res<StrategicView>>,
66:     scene: Res<RetainedScene>,
67:     mut retained: ResMut<ViewCameras>,
68:     mut cache: super::cached_views::CacheWorld,
69:     windows: Query<&Window>,
70:     mut cameras: Query<
71:         (
72:             &mut Camera,
73:             &mut Transform,
74:             &mut Projection,
75:             &mut RenderLayers,
76:         ),
77:         With<StrategicCamera>,
78:     >,
79: ) {
80:     let Some(window) = windows.iter().next() else {
81:         return;
82:     };
83:     if requested.as_ref().is_some_and(|view| !view.is_changed()) && !scene.is_changed() {
84:         return;
85:     }
86:     let size = window.resolution.physical_size();
87:     let specs = view_specs(requested.as_deref(), &scene);
88:     cache.sync(&mut commands, &specs, &scene, requested.as_deref(), window);
89:     let live = specs
90:         .iter()
91:         .filter(|spec| spec.cache.is_none())
92:         .collect::<Vec<_>>();
93:     for (index, spec) in live.iter().enumerate() {
94:         if let Some(entity) = retained.0.get(index)
95:             && let Ok((mut camera, mut transform, mut projection, mut layers)) =
96:                 cameras.get_mut(*entity)
97:         {
98:             spec.rect.apply(&mut camera, size);
99:             *transform = spec.transform;
100:             *projection = spec.projection.clone();
101:             *layers = spec.layers.clone();
102:         } else {
103:             let mut camera = Camera {
104:                 order: index as isize + 1,
105:                 clear_color: ClearColorConfig::Custom(Color::srgb(0.13, 0.16, 0.19)),
106:                 ..default()
107:             };
108:             spec.rect.apply(&mut camera, size);
109:             retained.0.push(
110:                 commands
111:                     .spawn((
112:                         StrategicCamera,
113:                         crate::presentation::interior_lighting::FixedViewExposure,
114:                         Camera3d::default(),
115:                         camera,
116:                         spec.transform,
117:                         spec.projection.clone(),
118:                         spec.layers.clone(),
119:                         Msaa::Off,
120:                         bevy::camera::Exposure::SUNLIGHT,
121:                     ))
122:                     .id(),
123:             );
124:         }
125:     }
126:     for entity in retained.0.iter().skip(live.len()) {
127:         if let Ok((mut camera, ..)) = cameras.get_mut(*entity) {
128:             camera.is_active = false;
129:         }
130:     }
131: }
