207: /// Copy the tactical camera's actual sky, exposure and post-processing state.
208: /// The gameplay marker remains unique for input and environment bake systems.
209: #[expect(
210:     clippy::type_complexity,
211:     reason = "Camera appearance is inherited from the single tactical camera"
212: )]
213: pub(super) fn sync_environment(
214:     mut commands: Commands,
215:     source: Query<
216:         (
217:             Ref<bevy::camera::Exposure>,
218:             Ref<bevy::core_pipeline::tonemapping::Tonemapping>,
219:             Ref<bevy::pbr::DistanceFog>,
220:             Ref<Msaa>,
221:             Ref<bevy::light::ShadowFilteringMethod>,
222:             Option<Ref<EnvironmentMapLight>>,
223:             Option<Ref<bevy::pbr::AtmosphereSettings>>,
224:         ),
225:         With<crate::presentation::TacticalGameplayCamera>,
226:     >,
227:     targets: Query<(
228:         Entity,
229:         Ref<StrategicCamera>,
230:         Option<&crate::presentation::RegionalMapCamera>,
231:     )>,
232: ) {
233:     let Ok((exposure, tone, fog, msaa, shadows, environment, atmosphere)) = source.single() else {
234:         return;
235:     };
236:     let changed = exposure.is_changed()
237:         || tone.is_changed()
238:         || fog.is_changed()
239:         || msaa.is_changed()
240:         || shadows.is_changed()
241:         || environment.as_ref().is_some_and(|value| value.is_changed())
242:         || atmosphere.as_ref().is_some_and(|value| value.is_changed());
243:     for (entity, marker, map) in &targets {
244:         // A reused snapshot camera reinserts its marker and camera defaults.
245:         // Restore the final settings before extraction, just as for a new view.
246:         if !changed && !marker.is_changed() {
247:             continue;
248:         }
249:         let mut target = commands.entity(entity);
250:         target.insert((*exposure, *tone, *msaa, *shadows));
251:         // Continental views must not inherit the street camera's fog reach or
252:         // atmosphere depth reconstruction. Lighting and asset residency are shared.
253:         if map.is_some() {
254:             target.remove::<(bevy::pbr::DistanceFog, bevy::pbr::AtmosphereSettings)>();
255:         } else {
256:             target.insert((*fog).clone());
257:             if let Some(atmosphere) = &atmosphere {
258:                 target.insert((**atmosphere).clone());
259:             }
260:         }
261:         if let Some(environment) = &environment {
262:             target.insert((**environment).clone());
263:         }
264:     }
265: }
