1: //! Local presentation of the same scene document consumed by the tactical server.
2: //! These entities carry asset descriptors only; authority arrives through replication.
3: use super::preparation::{PreparationError, PreparationResult, SharedPreparationResult};
4: use super::{RetainedScene, SceneRoot, buildings, protocol::StrategicView};
5: use adventuresim_tactical_core::{prelude::*, scene_input::SceneInputError};
6: use bevy::prelude::*;
7: use std::sync::Arc;
8: 
9: #[derive(Resource)]
10: pub(crate) struct SceneDocument {
11:     location: String,
12:     input: SharedPreparationResult<TacticalSceneInput>,
13:     #[cfg(target_family = "wasm")]
14:     preparation: crate::presentation::generation::PreparationTicket,
15: }
16: impl SceneDocument {
17:     pub(crate) fn parse(
18:         location: String,
19:         json: &str,
20:         #[cfg(target_family = "wasm")]
21:         preparation: crate::presentation::generation::PreparationTicket,
22:     ) -> Self {
23:         let input = serde_json::from_str::<TacticalSceneInput>(json)
24:             .map_err(SceneInputError::from)
25:             .and_then(|input| {
26:                 input.validate()?;
27:                 Ok(input)
28:             })
29:             .map_err(PreparationError::from)
30:             .map_err(Arc::new);
31:         Self {
32:             location,
33:             input,
34:             #[cfg(target_family = "wasm")]
35:             preparation,
36:         }
37:     }
38: 
39:     fn generated_scene(
40:         &self,
41:     ) -> SharedPreparationResult<crate::presentation::PreparedStrategicScene> {
42:         let input = self.input.as_ref().map_err(Arc::clone)?;
43:         #[cfg(target_family = "wasm")]
44:         let generated = crate::presentation::generation::activate(self.preparation, input);
45:         #[cfg(not(target_family = "wasm"))]
46:         let generated = crate::presentation::PreparedStrategicScene::generate(input);
47:         generated.map_err(PreparationError::from).map_err(Arc::new)
48:     }
49: }
50: 
51: pub(super) fn retain_scene(
52:     mut commands: Commands,
53:     requested: Option<Res<StrategicView>>,
54:     document: Option<Res<SceneDocument>>,
55:     mut scene: ResMut<RetainedScene>,
56:     materials: Option<Res<crate::presentation::TacticalBuildingMaterials>>,
57:     textures: Res<adventuresim_procedural_textures::ProceduralTextureResidency>,
58:     settings: Res<crate::presentation::TacticalGraphicsSettings>,
59: ) {
60:     let (Some(view), Some(document), Some(_)) = (requested, document, materials) else {
61:         return;
62:     };
63:     if document.location != view.location
64:         || !textures.is_ready(
65:             adventuresim_procedural_textures::PROCEDURAL_TEXTURE_CATALOGUE
66:                 .iter()
67:                 .map(|recipe| recipe.id),
68:         )
69:     {
70:         return;
71:     }
72:     if scene.location == view.location && scene.error.is_some() {
73:         return;
74:     }
75:     if scene.location != view.location || scene.root.is_none() {
76:         let generated = match document.generated_scene() {
77:             Ok(generated) => generated,
78:             Err(error) => {
79:                 scene.error = Some(error);
80:                 return;
81:             }
82:         };
83:         if let Some(root) = scene.root {
84:             commands.entity(root).despawn();
85:         }
86:         commands.queue(crate::presentation::clear_scene_entities);
87:         *scene = RetainedScene {
88:             location: view.location.clone(),
89:             ..default()
90:         };
91:         match &document.input {
92:             Ok(input) => {
93:                 if let Err(error) = prepare(
94:                     &mut commands,
95:                     input,
96:                     &view,
97:                     &mut scene,
98:                     generated,
99:                     settings.config.rendering.vista.maximum_lods,
100:                 ) {
101:                     scene.error = Some(Arc::new(error));
102:                 }
103:             }
104:             Err(error) => scene.error = Some(error.clone()),
105:         }
106:     }
107:     if !scene.pending.is_empty() {
108:         let (Some(building), Some(root)) = (scene.pending.pop_front(), scene.root) else {
109:             return;
110:         };
111:         if let Err(error) = super::instances::spawn_building(
112:             &mut commands,
113:             building,
114:             root,
115:             document.input.as_ref().ok(),
116:         ) {
117:             scene.error = Some(Arc::new(PreparationError::Presentation(error)));
118:         }
119:     }
120: }

1: //! Enforce the finite actor-camera range for ordinary meshes as well as the GPU city.
2: use super::views::StrategicCamera;
3: use bevy::{
4:     camera::{
5:         primitives::{Aabb, Frustum},
6:         visibility::{NoFrustumCulling, VisibilitySystems, VisibleEntities},
7:     },
8:     prelude::*,
9: };
10: use std::any::TypeId;
11: 
12: pub(super) fn install(app: &mut App) {
13:     app.add_systems(
14:         PostUpdate,
15:         (enforce_far_plane, wait_for_installation)
16:             .chain()
17:             .after(VisibilitySystems::CheckVisibility),
18:     );
19: }
20: 
21: #[expect(
22:     clippy::type_complexity,
23:     reason = "Initial scene and bootstrap camera mesh lists share the installation gate"
24: )]
25: fn wait_for_installation(
26:     view: Option<Res<super::protocol::StrategicView>>,
27:     installed: Res<super::status::SceneInstallationReady>,
28:     scene: Option<Res<super::RetainedScene>>,
29:     mut opened: Local<bool>,
30:     mut previous_scene: Local<Option<Entity>>,
31:     mut cameras: Query<
32:         &mut VisibleEntities,
33:         (
34:             Without<crate::presentation::RegionalMapCamera>,
35:             Or<(
36:                 With<StrategicCamera>,
37:                 With<crate::presentation::TacticalGameplayCamera>,
38:             )>,
39:         ),
40:     >,
41: ) {
42:     let root = scene.as_ref().and_then(|scene| scene.root);
43:     if *previous_scene != root {
44:         *previous_scene = root;
45:         *opened = false;
46:     } else {
47:         *opened |= installed.0;
48:     }
49:     if *opened || view.is_none() {
50:         return;
51:     }
52:     // Keep atmosphere baking, light visibility, uploads, and pose initialization
53:     // running. Only postpone mesh specialization until the final environment is
54:     // installed. Reopen for each city; weather changes within an installed city
55:     // never close this gate. The first frame of a replacement ignores the old
56:     // city's readiness, which is published at the end of the previous frame.
57:     for mut visible in &mut cameras {
58:         visible.get_mut(TypeId::of::<Mesh3d>()).clear();
59:     }
60: }
61: 
62: fn enforce_far_plane(
63:     mut cameras: Query<(&Camera, &Frustum, &mut VisibleEntities), With<StrategicCamera>>,
64:     meshes: Query<(&Aabb, &GlobalTransform), Without<NoFrustumCulling>>,
65: ) {
66:     // Bevy deliberately omits the far plane from ordinary CPU mesh culling.
67:     // Filter each camera's list independently; shadow caster lists and the
68:     // aggregate ViewVisibility must remain available to other views.
69:     for (camera, frustum, mut visible) in &mut cameras {
70:         if !camera.is_active {
71:             continue;
72:         }
73:         let plane = frustum.half_spaces[5].normal_d();
74:         visible.get_mut(TypeId::of::<Mesh3d>()).retain(|entity| {
75:             let Ok((aabb, transform)) = meshes.get(*entity) else {
76:                 return true;
77:             };
78:             let world = transform.affine();
79:             let center = world.transform_point3a(aabb.center);
80:             let radius = aabb
81:                 .half_extents
82:                 .dot((world.matrix3.transpose() * bevy::math::Vec3A::from(plane.truncate())).abs());
83:             plane.truncate().dot(center.into()) + plane.w >= -radius
84:         });
85:     }
86: }
