122: fn prepare(
123:     commands: &mut Commands,
124:     input: &TacticalSceneInput,
125:     view: &StrategicView,
126:     retained: &mut RetainedScene,
127:     mut generated: crate::presentation::PreparedStrategicScene,
128:     maximum_lods: usize,
129: ) -> PreparationResult<()> {
130:     let backdrop = crate::presentation::StrategicBackdrop::new(input, maximum_lods)?;
131:     let backdrop = crate::presentation::PreparedBackdrop::new(
132:         backdrop,
133:         input.environment_snapshot(generated.digest.clone()),
134:     )?;
135:     retained.venues = buildings::prepare_venues(
136:         input,
137:         view,
138:         &mut generated,
139:         &mut retained.street,
140:         backdrop.backdrop(),
141:     )?;
142:     retained.digest = generated.digest.clone();
143:     let root = commands
144:         .spawn((SceneRoot, Transform::default(), Visibility::Inherited))
145:         .id();
146:     retained.root = Some(root);
147:     if let Some(street) = &retained.street {
148:         street.spawn_ground(commands, root);
149:     }
150:     super::instances::spawn_props(commands, &mut generated, root);
151:     backdrop.spawn(commands, root);
152:     crate::presentation::queue_strategic_city(commands, input, &generated.buildings);
153:     let recipes = std::mem::take(&mut generated.building_recipes);
154:     commands.queue(move |world: &mut World| {
155:         world
156:             .resource_mut::<crate::presentation::TacticalBuildingMeshCache>()
157:             .recipes = recipes;
158:     });
159:     retained.pending = generated.buildings.into();
160:     retained.next_place = view.places.len();
161:     Ok(())
162: }
