973: /// Render performance captures into a texture so Windows compositor pacing
974: /// cannot masquerade as renderer work on sub-refresh-rate frame budgets.
975: fn redirect_performance_camera_offscreen(
976:     mut commands: Commands,
977:     camera: Single<Entity, With<TacticalGameplayCamera>>,
978:     mut images: ResMut<Assets<Image>>,
979: ) {
980:     let image = Image::new_target_texture(
981:         PERFORMANCE_VIEW_WIDTH,
982:         PERFORMANCE_VIEW_HEIGHT,
983:         bevy::render::render_resource::TextureFormat::Rgba8UnormSrgb,
984:         None,
985:     );
986:     commands
987:         .entity(*camera)
988:         .insert(RenderTarget::Image(images.add(image).into()));
989: }
