991: fn capture_presentation_plugin() -> TacticalPresentationPlugin {
992:     let mut plugin = TacticalPresentationPlugin::default();
993:     if std::env::var_os("TACTICAL_BENCH_DISABLE_SHADOWS").is_some() {
994:         plugin.config.rendering.shadows.enabled = false;
995:     }
996:     if std::env::var_os("TACTICAL_BENCH_DISABLE_POST_PROCESSING").is_some() {
997:         plugin.config.rendering.bloom.enabled = false;
998:     }
999:     // Cost-scaling overrides so the performance benchmark can measure the
1000:     // gameplay-preset configuration instead of only the 1.0 reference.
1001:     let scale_override = |name: &str| std::env::var(name).ok()?.parse::<f32>().ok();
