1040: )]
1041: fn observed_presentation_features(
1042:     settings: &TacticalGraphicsSettings,
1043:     environment_map: Option<&EnvironmentMapLight>,
1044:     atmosphere: Option<&AtmosphereSettings>,
1045:     images: &Assets<Image>,
1046:     exposure: &Exposure,
1047:     tonemapping: &Tonemapping,
1048:     ambient: &GlobalAmbientLight,
1049:     ambient_handoff: &AtmosphereIblStatus,
1050:     _celestial: &CelestialProvenance,
1051: ) -> PresentationFeatures {
1052:     let requested = requested_feature_state();
1053:     let observed_settings = feature_state(settings);
1054:     let environment_map_size = environment_map
1055:         .and_then(|light| images.get(&light.specular_map))
1056:         .map(|image| {
1057:             [
1058:                 image.texture_descriptor.size.width,
1059:                 image.texture_descriptor.size.height,
1060:             ]
1061:         });
1062:     let observed = ObservedPresentationFeatures {
1063:         settings: observed_settings,
1064:         camera_environment_map: environment_map.is_some(),
1065:         camera_environment_map_size: environment_map_size,
1066:         camera_environment_map_intensity: environment_map.map(|light| light.intensity),
1067:         camera_exposure_ev100: exposure.ev100,
1068:         camera_tonemapping: match tonemapping {
1069:             Tonemapping::None => CaptureTonemapping::None,
1070:             Tonemapping::Reinhard => CaptureTonemapping::Reinhard,
1071:             Tonemapping::ReinhardLuminance => CaptureTonemapping::ReinhardLuminance,
1072:             Tonemapping::AcesFitted => CaptureTonemapping::AcesFitted,
1073:             Tonemapping::AgX => CaptureTonemapping::AgX,
1074:             Tonemapping::SomewhatBoringDisplayTransform => {
1075:                 CaptureTonemapping::SomewhatBoringDisplayTransform
1076:             }
1077:             Tonemapping::TonyMcMapface => CaptureTonemapping::TonyMcMapface,
1078:             Tonemapping::BlenderFilmic => CaptureTonemapping::BlenderFilmic,
1079:             Tonemapping::KhronosPbrNeutral => CaptureTonemapping::KhronosPbrNeutral,
1080:         },

1081:         ambient_color: ambient.color.to_linear().to_f32_array(),
1082:         ambient_brightness: ambient.brightness,
1083:         ambient_policy: if ambient_handoff.active {
1084:             "atmosphere_ibl"
1085:         } else {
1086:             "awaiting_atmosphere_ibl"
1087:         },
1088:         expected_ambient_brightness: 0.0,
1089:     };
1090:     let requested_matches_observed = observed_settings == requested
1091:         && observed.camera_environment_map == requested.environment_light
1092:         && observed.camera_environment_map_size
1093:             == requested
1094:                 .environment_light
1095:                 .then_some([requested.environment_map_size; 2])
1096:         && observed.camera_environment_map_intensity
1097:             == requested.environment_light.then_some(1.0)
1098:         && atmosphere.is_some() == requested.atmosphere
1099:         // Production exposure is driven by the scene's solar/lunar state and
1100:         // may be between authored targets while the ECS observer settles.
1101:         && observed.camera_exposure_ev100.is_finite()
1102:         && (-1.35..=15.0).contains(&observed.camera_exposure_ev100)
1103:         && *tonemapping == Tonemapping::AcesFitted
1104:         && observed.ambient_brightness.is_finite()
1105:         && (observed.ambient_brightness - observed.expected_ambient_brightness).abs() <= 0.01;
1106:     PresentationFeatures {
1107:         requested,
1108:         observed,
1109:         requested_matches_observed,
1110:         weather_iteration_in_scope: false,
1111:         water_iteration_in_scope: false,
1112:         cloud_iteration_in_scope: false,
1113:         cave_iteration_in_scope: false,
1114:         characters_present: false,
1115:     }
1116: }
