1118: fn selected_capture_views(
1119:     profile: &str,
1120:     requested: &[String],
1121: ) -> Result<Vec<CaptureViewSpec>, String> {
1122:     let profile_views = match profile {
1123:         PLANT_REVIEW_PROFILE => view_specs::PLANT_REVIEW_VIEWS.as_slice(),
1124:         FUNGUS_REVIEW_PROFILE => view_specs::FUNGUS_REVIEW_VIEWS.as_slice(),
1125:         PLANT_LOD_REVIEW_PROFILE => view_specs::PLANT_LOD_REVIEW_VIEWS.as_slice(),
1126:         PLANT_LOD_ISOLATED_PROFILE => view_specs::PLANT_LOD_ISOLATED_VIEWS.as_slice(),
1127:         "semantic" => CAPTURE_VIEWS.as_slice(),
1128:         "environment-review" => ENVIRONMENT_REVIEW_VIEWS.as_slice(),
1129:         LANDFORM_REVIEW_PROFILE => LANDFORM_REVIEW_VIEWS.as_slice(),
1130:         INTERIOR_REVIEW_PROFILE => INTERIOR_REVIEW_VIEWS.as_slice(),
1131:         CITY_REVIEW_PROFILE => CITY_REVIEW_VIEWS.as_slice(),
1132:         fixed_city_cameras::PROFILE => fixed_city_cameras::VIEWS.as_slice(),
1133:         furniture_capture::PROFILE => view_specs::FURNITURE_REVIEW_VIEWS.as_slice(),
1134:         interior_furniture_capture::PROFILE => interior_furniture_capture::VIEWS.as_slice(),
1135:         interior_furniture_capture::ROOMS_PROFILE => {
1136:             interior_furniture_capture::ROOM_VIEWS.as_slice()
1137:         }
1138:         building_review::SHOP_PROFILE => view_specs::SHOP_REVIEW_VIEWS.as_slice(),
1139:         building_review::WORKPLACE_PROFILE => view_specs::WORKPLACE_REVIEW_VIEWS.as_slice(),
1140:         building_review::PARISH_PROFILE => view_specs::PARISH_REVIEW_VIEWS.as_slice(),
1141:         building_review::HEATING_PROFILE => view_specs::HEATING_REVIEW_VIEWS.as_slice(),
1142:         building_review::GARDEN_PROFILE => view_specs::GARDEN_REVIEW_VIEWS.as_slice(),
1143:         building_review::FACADE_PROFILE => view_specs::FACADE_REVIEW_VIEWS.as_slice(),
1144:         building_review::GABLE_PROFILE => view_specs::GABLE_REVIEW_VIEWS.as_slice(),
1145:         building_review::COMPOUND_PROFILE => view_specs::COMPOUND_REVIEW_VIEWS.as_slice(),
1146:         "animation-play" => ANIMATION_PLAY_VIEWS.as_slice(),
1147:         "tree-cold-traversal" => TREE_COLD_TRAVERSAL_VIEWS.as_slice(),
1148:         BEECH_LEAF_MOTION_PROFILE => BEECH_LEAF_MOTION_VIEWS.as_slice(),
1149:         _ => return Err(format!("unknown profile {profile}")),
1150:     };
1151:     if requested.is_empty() {
1152:         return Ok(profile_views.to_vec());
1153:     }
1154:     if profile == "tree-cold-traversal" {
1155:         let mut seen = BTreeSet::new();
1156:         let mut last_requested_index = 0;
1157:         for slug in requested {
1158:             if slug == "warmup" {
1159:                 return Err("warmup is implicit and cannot be requested".into());
1160:             }
1161:             if !seen.insert(slug.as_str()) {
1162:                 return Err(format!("duplicate requested view {slug}"));
1163:             }
1164:             let index = profile_views
1165:                 .iter()
1166:                 .position(|view| view.slug == slug)
1167:                 .ok_or_else(|| format!("unknown requested view {slug}"))?;
1168:             last_requested_index = last_requested_index.max(index);
1169:         }
1170:         // A cold-traversal plate is temporal evidence, not an independent
1171:         // camera pose. Preserve every preceding approach/retreat frame so a
1172:         // filtered capture cannot teleport from the distant-card warmup into
1173:         // an unstreamed near tree and manufacture a floating crown.
1174:         return Ok(profile_views[..=last_requested_index].to_vec());
1175:     }
1176:     let mut selected = vec![profile_views[0]];
1177:     let mut seen = BTreeSet::new();
1178:     for slug in requested {
1179:         if slug == "warmup" {
1180:             return Err("warmup is implicit and cannot be requested".into());
1181:         }
1182:         if !seen.insert(slug.as_str()) {
1183:             return Err(format!("duplicate requested view {slug}"));
1184:         }
1185:         let view = profile_views
1186:             .iter()
1187:             .find(|view| view.slug == slug)
1188:             .copied()
1189:             .ok_or_else(|| format!("unknown requested view {slug}"))?;
1190:         selected.push(view);
1191:     }
1192:     Ok(selected)
1193: }
