        })
    }
    CapturePose::BranchJunction => {
        let species = state
            .tree_focus_entity
            .and_then(|entity| lighting.presented_tree_species.get(entity).ok())
            .copied();
        view_camera::lit_branch_junction(state, species).map(|view| {
            view_camera::CaptureCameraPlacement {
                view,
                obstruction: None,
