        install(&mut app, super::super::fixed_city_cameras::PROFILE);
        assert!(app.is_plugin_added::<super::super::building_review::BuildingReviewPlugin>());
    }
}

use adventuresim_building_generator::spatial_geometry::Position;
use adventuresim_building_generator::{BuildingArchetype, Direction, WALL_THICKNESS_METRES};
use adventuresim_tactical_core::prelude::GeneratedBuilding;
use bevy::prelude::*;

use super::capture_state::{BuildingReviewCamera, PlasterRakingLight};

const PLASTER_REVIEW_CAMERA_DISTANCE_METRES: f32 = 0.82;
const PLASTER_REVIEW_LIGHT_TANGENT_DISTANCE_METRES: f32 = 1.2;
const PLASTER_REVIEW_LIGHT_INCIDENCE_DEGREES: f32 = 10.0;

const REVIEW_ARCHETYPES: [BuildingArchetype; 4] = [
    BuildingArchetype::TownHouse,
    BuildingArchetype::HallHouse,
    BuildingArchetype::FachwerkCottage,
    BuildingArchetype::FachwerkMerchantHouse,
];

pub(super) fn capture_cameras(
    buildings: &[GeneratedBuilding],
    profile: &str,
) -> Result<Vec<BuildingReviewCamera>> {
    if profile != super::INTERIOR_REVIEW_PROFILE {
        return Ok(Vec::new());
    }
    let mut cameras = Vec::new();
    for archetype in REVIEW_ARCHETYPES {
        let building = buildings
            .iter()
            .find(|building| building.plan.archetype == archetype)
            .ok_or_else(|| format!("interior review lacks {}", archetype.slug()))?;
        cameras.push(camera_for_storey(building, 0, 0)?);
        cameras.push(camera_for_storey(building, 1, 1)?);
    }
    let hall_house = buildings
        .iter()
        .find(|building| building.plan.archetype == BuildingArchetype::HallHouse)
        .expect("interior-review fixture lacks hall-house plaster proof");
    cameras.push(plaster_raking_camera(hall_house)?);
    let merchant_house = buildings
        .iter()
        .find(|building| building.plan.archetype == BuildingArchetype::FachwerkMerchantHouse)
        .expect("interior-review fixture lacks merchant-house partition proof");
    cameras.push(partition_review_camera(merchant_house)?);
    Ok(cameras)
}

fn partition_review_camera(building: &GeneratedBuilding) -> Result<BuildingReviewCamera> {
    let storey = &building.plan.storeys[0];
    let room = storey
        .rooms
        .iter()
        .max_by_key(|room| room.cells.len())
        .expect("partition review ground storey has a room");
    let wall = storey
        .walls
        .iter()
        .enumerate()
        .filter(|(_, wall)| wall.inside_room == room.id && !wall.exterior())
        .max_by_key(|(index, _)| {
            usize::from(storey.openings.iter().any(|opening| opening.wall == *index))
        })
        .map(|(_, wall)| *wall)
        .expect("partition review building has an internal wall facing its largest room");
    let centroid =
        room.cells.iter().map(|cell| cell.centre()).sum::<Vec2>() / room.cells.len() as f32;
    let local_origin = building.collision.bounds.centre()?.metres();
    let transform = building.transform()?;
    Ok(BuildingReviewCamera {
        position: Position::from_metres(
            transform.transform_point(Vec3::new(centroid.x, 1.48, centroid.y) - local_origin),
        )?,
        target: Position::from_metres(
            transform
                .transform_point(Vec3::new(wall.centre().x, 1.38, wall.centre().y) - local_origin),
        )?,
        plaster_raking_light: None,
    })
}

fn plaster_raking_camera(building: &GeneratedBuilding) -> Result<BuildingReviewCamera> {
    let storey = &building.plan.storeys[0];
    let room = storey
        .rooms
        .iter()
        .max_by_key(|room| room.cells.len())
        .expect("hall house ground storey has a room");
    let wall = storey
        .walls
        .iter()
        .enumerate()
        .filter(|(index, wall)| {
            wall.inside_room == room.id
                && !wall.exterior()
                && !storey.openings.iter().any(|opening| opening.wall == *index)
        })
        .map(|(_, wall)| *wall)
        .next()
        .expect("hall house has an unopened interior plaster wall");
    let inward_local = match wall.direction {
        Direction::North => -Vec2::Y,
        Direction::East => -Vec2::X,
        Direction::South => Vec2::Y,
        Direction::West => Vec2::X,
    };
    let tangent_local = if wall.is_horizontal() {
        Vec2::X
    } else {
        Vec2::Y
    };
    let wall_face = wall.centre() + inward_local * (WALL_THICKNESS_METRES * 0.5 + 0.002);
    let local_origin = building.collision.bounds.centre()?.metres();
    let building_transform = building.transform()?;
    let wall_point = building_transform
        .transform_point(Vec3::new(wall_face.x, 1.42, wall_face.y) - local_origin);
    let inward_normal =
        (building_transform.rotation * Vec3::new(inward_local.x, 0.0, inward_local.y)).normalize();
    let tangent = (building_transform.rotation * Vec3::new(tangent_local.x, 0.0, tangent_local.y))
        .normalize();
    let incidence = PLASTER_REVIEW_LIGHT_INCIDENCE_DEGREES.to_radians();
    let light_direction = tangent * incidence.cos() + inward_normal * incidence.sin();
    let light_position =
        wall_point + light_direction * PLASTER_REVIEW_LIGHT_TANGENT_DISTANCE_METRES;
    Ok(BuildingReviewCamera {
        position: Position::from_metres(
            wall_point + inward_normal * PLASTER_REVIEW_CAMERA_DISTANCE_METRES,
        )?,
        target: Position::from_metres(wall_point)?,
        plaster_raking_light: Some(PlasterRakingLight {
            wall_point,
            inward_normal,
            position: light_position,
        }),
    })
}

fn camera_for_storey(
    building: &GeneratedBuilding,
    preferred_storey: usize,
    angle_variant: usize,
) -> Result<BuildingReviewCamera> {
    let storey = building
        .plan
        .storeys
        .get(preferred_storey)
        .unwrap_or(&building.plan.storeys[0]);
    let room = storey
        .rooms
        .iter()
        .max_by_key(|room| room.cells.len())

];

pub(super) const VIEWS: [CaptureViewSpec; CATALOG.len() + 2 + finishes::LABELS.len()] =
    catalog_views();
pub(super) const ROOM_VIEWS: [CaptureViewSpec; ROOM_LABELS.len() + 1] = room_views();

#[derive(Debug, thiserror::Error)]
enum CatalogAdmissionError {
    #[error("catalog fixture must have no placed furniture")]
    AlreadyPlaced,
    #[error("catalog key {key:?} is absent from the authored catalogue")]
    MissingCatalogueEntry { key: FurnitureKey },
    #[error("catalog orientation must be finite")]
    InvalidOrientation,
}

const fn catalog_views() -> [CaptureViewSpec; CATALOG.len() + 2 + finishes::LABELS.len()] {
    let warmup = CaptureViewSpec::new(
        "warmup",
        "Production furniture catalog warmup",
        CapturePose::CityExterior { camera: 0 },
        CATALOG_FOV_DEGREES,
        100,
    )
    .warmup()
    .vista();
    let mut views = [warmup; CATALOG.len() + 2 + finishes::LABELS.len()];
    let mut index = 0;
    while index < CATALOG.len() {
        views[index + 1] = CaptureViewSpec::new(
            CATALOG[index].0,
            CATALOG[index].1,
            CapturePose::CityExterior {
                camera: index as u8,
            },
            CATALOG_FOV_DEGREES,
            100,
        )
        .vista()
        .settled_readback_pair();
        index += 1;
    }
    views[CATALOG.len() + 1] = CaptureViewSpec::new(
        "joined-counters",
        "Contiguous counter runs with corner and endcaps",
        CapturePose::CityExterior {
            camera: CATALOG.len() as u8,
        },
        CATALOG_FOV_DEGREES,
        100,
    )
    .vista()
    .settled_readback_pair();
    let mut finish = 0;
    while finish < finishes::LABELS.len() {
        views[CATALOG.len() + 2 + finish] = CaptureViewSpec::new(
            finishes::LABELS[finish].0,
            finishes::LABELS[finish].1,
            CapturePose::CityExterior {
                camera: (CATALOG.len() + 1 + finish) as u8,
            },
            CATALOG_FOV_DEGREES,
            100,
        )
        .vista()
        .settled_readback_pair();
        finish += 1;
    }
    views
}

const fn room_views() -> [CaptureViewSpec; ROOM_LABELS.len() + 1] {
    let warmup = CaptureViewSpec::new(
        "warmup",
        "Production furnished room warmup",
        CapturePose::BuildingInterior { camera: 0 },
        ROOM_FOV_DEGREES,
        100,
    )
    .warmup();
    let mut views = [warmup; ROOM_LABELS.len() + 1];
    let mut index = 0;
    while index < ROOM_LABELS.len() {
        views[index + 1] = CaptureViewSpec::new(
            ROOM_LABELS[index].0,
            ROOM_LABELS[index].1,
            CapturePose::BuildingInterior {
                camera: index as u8,
            },
            ROOM_FOV_DEGREES,
            100,
        )
        .settled_readback_pair();
        index += 1;
    }
    views
}

pub(super) fn is_profile(profile: &str) -> bool {
    matches!(profile, PROFILE | ROOMS_PROFILE)
}

pub(super) fn setup_rooms(
    commands: &mut Commands,
    buildings: &[GeneratedBuilding],
    layout: &FurnitureLayout,
    profile: &str,
    output: &std::path::Path,
) -> Result<Option<Vec<BuildingReviewCamera>>> {
    if profile != ROOMS_PROFILE {
        return Ok(None);
    }
    super::building_review::setup_geometry_requirements(commands, buildings, output)?;
    let cameras = ROOM_USES
        .into_iter()
        .enumerate()
        .map(|(index, usage)| {
            let building = buildings
                .iter()
                .find(|building| building.placement.program.usage == Some(usage))
                .ok_or_else(|| format!("furnished room fixture lacks {usage:?}"))?;
            use adventuresim_building_generator::RoomKind;
            let selection = match index {
                0 | 1 => rooms::RoomSelection::Role(RoomKind::CommonRoom),
                2 => rooms::RoomSelection::Role(RoomKind::Shop),
                3 | 11 | 12 => rooms::RoomSelection::Role(RoomKind::Workshop),
                4 | 10 => rooms::RoomSelection::Role(RoomKind::Nave),
                5 => rooms::RoomSelection::Role(RoomKind::Ward),
                6 => rooms::RoomSelection::Role(RoomKind::Guardroom),
                7 => rooms::RoomSelection::Role(RoomKind::Storage),
                8 => rooms::RoomSelection::UpperKeep,
                9 => rooms::RoomSelection::Bedroom,
                13 => rooms::RoomSelection::Role(RoomKind::CountingRoom),
                14 => rooms::RoomSelection::Operating(FurnitureKind::TreadleLoom),
                15 => rooms::RoomSelection::Operating(FurnitureKind::SpinningStool),
                _ => unreachable!("every authored room view has a semantic selection"),
            };
            rooms::camera(building, layout, selection)
        })
        .collect::<Result<Vec<_>>>()?;
    expect_furniture(commands, layout)?;
    std::fs::write(
        output.join("interior-access-proofs.json"),
        serde_json::to_vec_pretty(&layout.interiors).unwrap(),
    )
    .expect("write room access proofs");
    Ok(Some(cameras))
}

fn envelope_corners(size: Vec3) -> [Vec3; 8] {

    std::array::from_fn(|index| {
        Vec3::new(
            if index & 1 == 0 {
                -size.x * 0.5
            } else {
                size.x * 0.5
            },
            if index & 2 == 0 { 0.0 } else { size.y },
            if index & 4 == 0 {
                -size.z * 0.5
            } else {
                size.z * 0.5
            },
        )
    })
}

fn expect_furniture(commands: &mut Commands, layout: &FurnitureLayout) -> Result {
    commands.insert_resource(super::furniture_readiness::ExpectedFurniture {
        instances: layout.instances.len() + layout.distant_instances.len(),
        batches: layout
            .instances
            .iter()
            .chain(&layout.distant_instances)
            .map(|instance| instance.scene.key.recipe().map(|r| r.meshes.len()))
            .collect::<std::result::Result<Vec<_>, _>>()?
            .into_iter()
            .sum(),
    });
    Ok(())
}

