67:         let point = ScenePlanPoint::try_from(Vec2::new(
68:             f32::from(x) * grid.spacing_metres - terrain.width() * 0.5,
69:             f32::from(z) * grid.spacing_metres - terrain.depth() * 0.5,
70:         ))?;
71:         let elevation = terrain.required_height_at(point)?;
72:         let position = Position::from_metres(Vec3::new(
73:             point.metres().x,
