20: #[derive(Clone, Copy, Debug)]
21: enum SceneCameraOrientation {
22:     LookingAt { up: SpatialDirection<Scene> },
23:     Fixed(RigidRotation),
24: }
25: 
26: impl SceneCameraView {
27:     pub(in crate::tactical_scene_viewer) fn looking_at(
28:         position: Position<Scene>,
29:         target: Position<Scene>,
30:         up: SpatialDirection<Scene>,
31:     ) -> CaptureCameraResult<Self> {
32:         let forward = (target.metres() - position.metres())
33:             .try_normalize()
34:             .ok_or(CaptureCameraError::InvalidView)?;
35:         forward
36:             .cross(up.vector())
37:             .try_normalize()
38:             .ok_or(CaptureCameraError::InvalidView)?;
39:         Ok(Self {
40:             position,
41:             target,
42:             orientation: SceneCameraOrientation::LookingAt { up },
43:         })
44:     }
45: 
46:     pub(in crate::tactical_scene_viewer) fn oriented(
47:         position: Position<Scene>,
48:         target: Position<Scene>,
49:         rotation: RigidRotation,
50:     ) -> Self {
51:         Self {
52:             position,
53:             target,
54:             orientation: SceneCameraOrientation::Fixed(rotation),
55:         }
56:     }
57: 
58:     /// Native scene-vector representation for the framework view port.
59:     pub(in crate::tactical_scene_viewer) fn native_up(self) -> Vec3 {
60:         match self.orientation {
61:             SceneCameraOrientation::LookingAt { up } => up.vector(),
62:             SceneCameraOrientation::Fixed(rotation) => rotation.quaternion() * Vec3::Y,
63:         }
64:     }
65: 
66:     pub(in crate::tactical_scene_viewer) fn native_transform(self) -> Transform {
67:         let transform = Transform::from_translation(self.position.metres());
68:         match self.orientation {
69:             // Bevy owns the final look-at kernel. Keep its original arithmetic.
70:             SceneCameraOrientation::LookingAt { .. } => {
71:                 transform.looking_at(self.target.metres(), self.native_up())
72:             }
73:             SceneCameraOrientation::Fixed(rotation) => {
74:                 transform.with_rotation(rotation.quaternion())
75:             }
76:         }
77:     }
78: }

