1: //! Capture observations from the serialized geographic backdrop grids.
2: 
3: use adventuresim_building_generator::spatial_geometry::{GeometryError, SignedLength};
4: use adventuresim_tactical_core::{
5:     city_layout::grounding::{GeographicHeightControl, GeographicHeightRange, SupportElevation},
6:     scene_coordinates::ScenePlanPoint,
7:     scene_input::{TacticalSceneInput, VistaLevelIndex},
8: };
9: use bevy::math::Vec2;
10: 
11: pub(super) type VistaGeometryResult<T> = Result<T, VistaGeometryError>;
12: 
13: /// A nonempty observation; extrema keep their actual sampling locations.
14: #[derive(Clone, Copy, Debug)]
15: pub(super) struct VistaCaptureGeometry {
16:     diameter: SignedLength,
17:     extrema: GeographicHeightRange,
18:     relief: SignedLength,
19: }
20: 
21: #[derive(Debug, thiserror::Error)]
22: pub(super) enum VistaGeometryError {
23:     #[error(transparent)]
24:     Geometry(#[from] GeometryError),
25:     #[error("vista elevation is not finite at {point:?}")]
26:     InvalidElevation { point: ScenePlanPoint },
27:     #[error("vista level {level} has no columns")]
28:     MissingColumns { level: VistaLevelIndex },
29: }
30: 
31: impl VistaCaptureGeometry {
32:     pub(super) fn from_source(input: &TacticalSceneInput) -> VistaGeometryResult<Option<Self>> {
33:         let mut diameter = 0.0_f32;
34:         let mut extrema: Option<GeographicHeightRange> = None;
35:         for lod in &input.vista.lods {
36:             if lod.width == 0 {
37:                 return Err(VistaGeometryError::MissingColumns { level: lod.level });
38:             }
39:             diameter = diameter.max(f32::from(lod.width.saturating_sub(1)) * lod.spacing_metres);
40:             let center_x = f32::from(lod.width.saturating_sub(1)) * 0.5;
41:             let center_z = f32::from(lod.depth.saturating_sub(1)) * 0.5;
42:             for (index, height) in lod.heights_metres.iter().copied().enumerate() {
43:                 // Complete the original row-major grid-to-scene projection before admission.
44:                 let x = (index % usize::from(lod.width)) as f32;
45:                 let z = (index / usize::from(lod.width)) as f32;
46:                 let point = ScenePlanPoint::try_from(Vec2::new(
47:                     (x - center_x) * lod.spacing_metres + lod.origin_east_metres as f32,
48:                     (z - center_z) * lod.spacing_metres + lod.origin_north_metres as f32,
49:                 ))?;
50:                 let elevation = SupportElevation::from_metres(height)
51:                     .ok_or(VistaGeometryError::InvalidElevation { point })?;
52:                 let control = GeographicHeightControl { point, elevation };
53:                 match &mut extrema {
54:                     Some(range) => {
55:                         if elevation.metres() < range.minimum.elevation.metres() {
56:                             range.minimum = control;
57:                         }
58:                         if elevation.metres() > range.maximum.elevation.metres() {
59:                             range.maximum = control;
60:                         }
61:                     }
62:                     None => {
63:                         extrema = Some(GeographicHeightRange {
64:                             minimum: control,
65:                             maximum: control,
66:                         })
67:                     }
68:                 }
69:             }
70:         }
71:         let Some(extrema) = extrema else {
72:             return Ok(None);
73:         };
74:         Ok(Some(Self {
75:             diameter: SignedLength::from_metres(diameter)?,
76:             extrema,
77:             relief: SignedLength::from_metres(
78:                 extrema.maximum.elevation.metres() - extrema.minimum.elevation.metres(),
79:             )?,
80:         }))
81:     }
82: 
83:     pub(super) fn diameter(self) -> SignedLength {
84:         self.diameter
85:     }
86: 
87:     pub(super) fn minimum(self) -> GeographicHeightControl {
88:         self.extrema.minimum
89:     }
90: 
91:     pub(super) fn maximum(self) -> GeographicHeightControl {
92:         self.extrema.maximum
93:     }
94: 
95:     pub(super) fn relief(self) -> SignedLength {
96:         self.relief
97:     }
98: }

