6: impl CapturePose {
7:     pub(in crate::tactical_scene_viewer) fn accepts_plant(
8:         self,
9:         species: adventuresim_plant_generator::PlantSpecies,
10:     ) -> bool {
11:         match self {
12:             Self::Fungus {
13:                 species: requested, ..
14:             } => species == adventuresim_plant_generator::PlantSpecies::Fungus(requested),
15:             _ => true,
16:         }
17:     }
18: 
19:     pub(in crate::tactical_scene_viewer) fn plant_camera(
20:         self,
21:         root: Position<Scene>,
22:     ) -> CaptureCameraResult<SceneCameraView> {
23:         let root = root.metres();
24:         if let Self::PlantLod { distance } = self {
25:             let distance = distance.metres();
26:             let approach = Vec3::new(-root.x, 0.0, -root.z).normalize_or(Vec3::Z);
27:             let eye = root + (approach + Vec3::Y * 0.2).normalize() * distance;
28:             return SceneCameraView::looking_at(
29:                 Position::from_metres(eye)?,
30:                 Position::from_metres(root + Vec3::Y * 0.08)?,
31:                 SpatialDirection::from_normalized(Vec3::Y)?,
32:             );
33:         }
34:         let (distance, target_height, elevation) = match self {
35:             Self::Plant { distance } => {
36:                 (distance.metres(), 0.18, distance.metres().clamp(0.35, 1.5))
37:             }
38:             Self::Fungus { distance, .. } => (
39:                 distance.metres(),
40:                 0.06,
41:                 (distance.metres() * 0.3).clamp(0.10, 1.5),
42:             ),
43:             _ => unreachable!("only botanical poses use plant camera framing"),
44:         };
45:         let target = root + Vec3::Y * target_height;
46:         let approach = Vec3::new(-root.x, 0.0, -root.z).normalize_or(Vec3::Z);
47:         SceneCameraView::looking_at(
48:             Position::from_metres(target + approach * distance + Vec3::Y * elevation)?,
49:             Position::from_metres(target)?,
50:             SpatialDirection::from_normalized(Vec3::Y)?,
51:         )
52:     }
53: }
