336: fn camera_observation_matches(
337:     observed: ObservedSkyCamera,
338:     requested_translation: Vec3,
339:     requested_direction: Vec3,
340:     requested_fov_degrees: f32,
341: ) -> bool {
342:     observed.render_observations >= 2
343:         && observed
344:             .translation
345:             .abs_diff_eq(requested_translation, 1e-4)
346:         && observed.direction.abs_diff_eq(requested_direction, 1e-4)
347:         && (observed.vertical_fov_degrees - requested_fov_degrees).abs() <= 1e-3
348: }
349: 
350: fn capture_view(
351:     mut commands: Commands,
352:     mut state: ResMut<SkyCaptureState>,
353:     camera: Single<(&Exposure, &GlobalTransform, &Projection), With<TacticalGameplayCamera>>,
354:     camera_probe: Res<SkyCameraProbe>,
355:     sunlight: Single<&DirectionalLight, With<crate::presentation::TacticalSunlight>>,
356: ) {
357:     if state.in_flight {
358:         return;
359:     }
360:     let Some(render_observed) = *camera_probe.0.lock().expect("sky camera probe lock") else {
361:         return;
362:     };
363:     let main_fov_degrees = match camera.2 {
364:         Projection::Perspective(perspective) => perspective.fov.to_degrees(),
365:         _ => f32::NAN,
366:     };
367:     let requested_translation = Vec3::from_array(state.camera_translation);
368:     let requested_direction = Vec3::from_array(state.camera_direction);
369:     let main_observed = ObservedSkyCamera {
370:         translation: camera.1.translation(),
371:         direction: camera.1.forward().as_vec3(),
372:         vertical_fov_degrees: main_fov_degrees,
373:         render_observations: render_observed.render_observations,
374:     };
375:     state.observed_camera = Some(render_observed);
376:     state.camera_observation_ready = camera_observation_matches(
377:         render_observed,
378:         requested_translation,
379:         requested_direction,
380:         state.vertical_fov_degrees,
381:     ) && camera_observation_matches(
382:         main_observed,
383:         requested_translation,
384:         requested_direction,
385:         state.vertical_fov_degrees,
386:     );
387:     if state.settled < state.settle_frames {
388:         state.settled += 1;
389:         return;
390:     }
391:     state.in_flight = true;
392:     if !state.prime_complete {
393:         commands.spawn(Screenshot::primary_window()).observe(
394:             |_: On<ScreenshotCaptured>, mut state: ResMut<SkyCaptureState>| {
395:                 state.prime_complete = true;
396:                 state.settled = 0;
397:                 state.in_flight = false;
398:             },
399:         );
400:         return;
401:     }
402: 
403:     let path = state.output.clone();
404:     let exposure_ev100 = camera.0.ev100;
405:     let solar_source_illuminance_lux = sunlight.illuminance;
406:     commands.spawn(Screenshot::primary_window()).observe(
407:         move |captured: On<ScreenshotCaptured>,
408:               state: Res<SkyCaptureState>,
409:               mut exit: MessageWriter<AppExit>| {
410:             let horizon_row = projected_horizon_row(
411:                 captured.image.height(),
412:                 state.camera_direction[1].asin(),
413:                 state.vertical_fov_degrees.to_radians(),
414:             );
415:             let metrics = sky_metrics(
416:                 captured.image.data.as_deref(),
417:                 captured.image.width(),
