420:             );
421:             let expected_dimensions =
422:                 captured.image.width() == VIEW_WIDTH && captured.image.height() == VIEW_HEIGHT;
423:             let subject_content = match state.view {
424:                 SkyView::Sun | SkyView::SunDetail | SkyView::Moon => {
425:                     metrics.bright_pixel_count >= 16
426:                 }
427:                 SkyView::Twilight => twilight_subject_content(&metrics),
428:                 SkyView::Stars => metrics.bright_pixel_count >= 8,
429:                 SkyView::CloudCumulus
430:                 | SkyView::CloudStratocumulus
431:                 | SkyView::CloudCirrus
432:                 | SkyView::CloudOvercast
