474:                 upper_sky_luma_variance: metrics.upper_sky_luma_variance,
475:                 horizon_sky_mean_luma: metrics.horizon_sky_mean_luma,
476:                 horizon_sky_red_blue_delta: metrics.horizon_sky_red_blue_delta,
477:                 sun_disk_angular_diameter_degrees: SunDisk::EARTH.angular_size.to_degrees(),
478:                 diagnostic_magnification: matches!(state.view, SkyView::SunDetail),
479:                 cloud_profile: cloud_profile_slug(state.view),
480:                 exposure_ev100,

481:                 solar_source_illuminance_lux,
482:                 atmosphere_enabled: true,
483:                 environment_map_size: 64,
484:                 revision: capture_revision(),
485:                 source_identity: std::env::var("CAPTURE_SOURCE_IDENTITY")
486:                     .unwrap_or_else(|_| "standalone-unlabelled".into()),
487:                 validation,
488:             };
489:             save_to_disk(&path)(captured);
490:             let manifest_path = path.with_extension("manifest.json");
491:             fs::write(
492:                 &manifest_path,
493:                 serde_json::to_vec_pretty(&manifest).unwrap(),
494:             )
495:             .expect("write sky manifest");
496:             if manifest.validation.passed {
497:                 exit.write(AppExit::Success);
498:             } else {
499:                 fs::write(
500:                     path.with_extension("failure.txt"),
501:                     "Sky semantic validation failed.\n",
502:                 )
503:                 .expect("write sky failure marker");
504:                 exit.write(AppExit::error());
505:             }
506:         },
507:     );
508: }
