510: #[derive(Default)]
511: struct SkyMetrics {
512:     bright_pixel_bps: u16,
513:     non_black_pixel_bps: u16,
514:     bright_pixel_count: usize,
515:     non_black_pixel_count: usize,
516:     horizon_luma_delta: f32,
517:     upper_sky_mean_luma: f32,
518:     upper_sky_luma_variance: f32,
519:     horizon_sky_mean_luma: f32,
520:     horizon_sky_red_blue_delta: f32,
521: }
522: 
523: fn sky_metrics(data: Option<&[u8]>, width: u32, height: u32, horizon_row: usize) -> SkyMetrics {
524:     let Some(data) = data else {
525:         return SkyMetrics::default();
526:     };
527:     let pixels = data.as_chunks::<4>().0;
528:     if pixels.is_empty() {
529:         return SkyMetrics::default();
530:     }
531:     let mut bright = 0usize;
532:     let mut non_black = 0usize;
533:     let mut upper = 0u64;
534:     let mut lower = 0u64;
535:     let mut upper_sky_sum = 0.0_f64;
536:     let mut upper_sky_squared_sum = 0.0_f64;
537:     let mut upper_sky_count = 0usize;
538:     let mut horizon_sky_luma_sum = 0.0_f64;
539:     let mut horizon_sky_red_blue_sum = 0.0_f64;
540:     let mut horizon_sky_count = 0usize;
541:     let split = pixels.len() / 2;
542:     for (index, pixel) in pixels.iter().enumerate() {
543:         let luma =
544:             (u16::from(pixel[0]) * 54 + u16::from(pixel[1]) * 183 + u16::from(pixel[2]) * 19) / 256;
545:         bright += usize::from(luma >= 180);
546:         non_black += usize::from(luma >= 6);
547:         if index < split {
548:             upper += u64::from(luma)
549:         } else {
550:             lower += u64::from(luma)
551:         }
552:         let y = index / width.max(1) as usize;
553:         let sky_horizon = horizon_row.min(height as usize);
554:         if y < sky_horizon.saturating_sub(height as usize / 8) {
555:             upper_sky_sum += f64::from(luma);
556:             upper_sky_squared_sum += f64::from(luma).powi(2);
557:             upper_sky_count += 1;
558:         } else if y < sky_horizon {
559:             horizon_sky_luma_sum += f64::from(luma);
560:             horizon_sky_red_blue_sum += f64::from(pixel[0]) - f64::from(pixel[2]);
561:             horizon_sky_count += 1;
562:         }
563:     }
564:     let bps = |count: usize| {
565:         adventuresim_world_schema::UnitBasisPoints::from_ratio_floor(
566:             count as u64,
567:             pixels.len() as u64,
568:         )
569:         .expect("sky capture has pixels")
570:         .get()
571:     };
572:     let upper_sky_mean = upper_sky_sum / upper_sky_count.max(1) as f64;
573:     SkyMetrics {
574:         bright_pixel_bps: bps(bright),
575:         non_black_pixel_bps: bps(non_black),
576:         bright_pixel_count: bright,
577:         non_black_pixel_count: non_black,
578:         horizon_luma_delta: ((upper as f64 / split as f64)
579:             - (lower as f64 / (pixels.len() - split) as f64))
580:             .abs() as f32,
581:         upper_sky_mean_luma: upper_sky_mean as f32,
582:         upper_sky_luma_variance: (upper_sky_squared_sum / upper_sky_count.max(1) as f64
583:             - upper_sky_mean * upper_sky_mean)
584:             .max(0.0) as f32,
585:         horizon_sky_mean_luma: (horizon_sky_luma_sum / horizon_sky_count.max(1) as f64) as f32,
586:         horizon_sky_red_blue_delta: (horizon_sky_red_blue_sum / horizon_sky_count.max(1) as f64)
587:             as f32,
588:     }
589: }
590: 
591: fn projected_horizon_row(height: u32, camera_elevation: f32, vertical_fov: f32) -> usize {
592:     let focal_y = height as f32 / (2.0 * (vertical_fov * 0.5).tan());
593:     (height as f32 * 0.5 + camera_elevation.tan() * focal_y)
594:         .round()
595:         .clamp(0.0, height as f32) as usize
596: }
597: 
598: fn twilight_subject_content(metrics: &SkyMetrics) -> bool {
599:     metrics.upper_sky_mean_luma >= 6.0
600:         && metrics.upper_sky_luma_variance >= 4.0
601:         && metrics.horizon_sky_mean_luma >= metrics.upper_sky_mean_luma + 3.0
602:         && metrics.horizon_sky_red_blue_delta >= 3.0
603: }
