653: fn capture_revision() -> String {
654:     Command::new("git")
655:         .args(["rev-parse", "HEAD"])
656:         .output()
657:         .ok()
658:         .filter(|output| output.status.success())
659:         .and_then(|output| String::from_utf8(output.stdout).ok())
660:         .map(|value| value.trim().to_owned())
661:         .unwrap_or_else(|| "unavailable".into())
662: }
