664: fn to_bevy_direction(east_up_north: [f32; 3]) -> Vec3 {
665:     Vec3::new(east_up_north[0], east_up_north[1], -east_up_north[2]).normalize()
666: }
667: 
668: fn horizon_view(direction: Vec3, altitude: f32) -> Vec3 {
669:     let horizontal = Vec3::new(direction.x, 0.0, direction.z).normalize_or_zero();
670:     (horizontal + Vec3::Y * altitude).normalize()
671: }
