170:     }
171: 
172:     let content_rect = context.content_rect();
173:     let (camera, camera_transform) = camera.into_inner();
174:     for (entity, side, state, limbs, root_transform, rig) in &enemies {
175:         if !enemy_incapacitation_wheel_visible(*side, state.incapacitation) {
176:             continue;
177:         }
178:         let Ok(view) = viewer.get(entity) else {
179:             continue;
180:         };
181:         let will = view.skill_check(Skill::Will, LimbWeights::all_equal());
182:         let sources = state.incapacitation_sources(limbs.total_damage(), will);
183:         let head_position = rig
184:             .and_then(|rig| rig.get(&BoneRole::Head))
185:             .and_then(|head| bone_transforms.get(*head).ok())
186:             .map_or_else(
187:                 || root_transform.translation() + Vec3::Y * ENEMY_WHEEL_ROOT_FALLBACK_HEIGHT_METRES,
188:                 |head| head.translation() + Vec3::Y * ENEMY_WHEEL_HEAD_CLEARANCE_METRES,
189:             );
190:         let Ok(viewport_position) = camera.world_to_viewport(camera_transform, head_position)
191:         else {
192:             continue;
193:         };
194:         let center = Pos2::new(viewport_position.x, viewport_position.y);
195:         if !content_rect
196:             .expand(ENEMY_INCAPACITATION_WHEEL_RADIUS)
197:             .contains(center)
198:         {
199:             continue;
200:         }
201:         paint_incapacitation_wheel(
202:             &painter,
203:             center,
204:             state,
205:             sources,
206:             ENEMY_INCAPACITATION_WHEEL_RADIUS,
207:             ENEMY_INCAPACITATION_WHEEL_WIDTH,
208:         );
209:     }
210: 
211:     Ok(())
212: }
213: 
214: fn paint_incapacitation_wheel(
215:     painter: &egui::Painter,
216:     center: Pos2,
217:     state: &TacticalCombatState,
218:     sources: TacticalIncapacitationSources,
219:     radius: f32,
220:     width: f32,
221: ) {
222:     painter.circle_stroke(
223:         center,
224:         radius,
225:         Stroke::new(
226:             width,
227:             Color32::from_rgba_unmultiplied(0x10, 0x12, 0x16, 150),
228:         ),
229:     );
230: 
231:     if state.is_incapacitated() {
232:         painter.circle_stroke(
233:             center,
234:             radius,
235:             Stroke::new(
236:                 width + 6.0,
237:                 Color32::from_rgba_unmultiplied(0xc8, 0x47, 0x47, 70),
238:             ),
239:         );
240:     }
241: 
242:     let mut cursor = -std::f32::consts::FRAC_PI_2;
243:     let mut remaining = 1.0_f32;
244:     for (raw_amount, color) in forecast_wheel_segments(sources, state.projected_increase) {
245:         let Some(amount) = visible_incapacitation_wheel_amount(raw_amount, remaining) else {
246:             continue;
247:         };
248:         let end = cursor + amount * std::f32::consts::TAU;
249:         let steps = (amount * INCAPACITATION_WHEEL_RESOLUTION).ceil().max(2.0) as usize;
250:         let points = (0..=steps)
251:             .map(|step| {
252:                 let angle = cursor + (end - cursor) * step as f32 / steps as f32;
253:                 Pos2::new(
254:                     center.x + radius * angle.cos(),
255:                     center.y + radius * angle.sin(),
256:                 )
257:             })
258:             .collect();
259:         painter.add(egui::Shape::line(points, Stroke::new(width, color)));
260:         cursor = end;
261:         remaining -= amount;
262:         if remaining <= 0.0 {
263:             break;
264:         }
265:     }
266: }
