711: fn item_display_name(item: &ItemQueryItem) -> String {
712:     let qty = if item.quantity.get() > 1 {
713:         format!(" x{}", item.quantity.get())
714:     } else {
715:         String::new()
716:     };
717:     let slot = if let Some(slot) = item.slot {
718:         format!("{slot}: ")
719:     } else {
720:         String::new()
721:     };
722:     let name = if item.properties.id.is_empty() {
723:         "unknown"
724:     } else {
725:         item.properties.id.as_str()
726:     };
727: 
728:     if let Some(weapon) = item.weapon {
729:         format!("{slot}{name}{qty}\nprecision: {:.1}", weapon.precision)
730:     } else if let Some(armor) = item.armor {
731:         format!(
732:             "{slot}{name}{qty}\ncoverage: {:.1} | padding: {:.1}\nrange_of_motion: {:.1} | flexibility: {:.1}",
733:             armor.coverage, armor.padding, armor.range_of_motion, armor.flexibility
734:         )
735:     } else if let Some(shield) = item.shield {
736:         format!("{slot}{name}{qty}\nblock: {:.1}", shield.block)
737:     } else {
738:         format!("{slot}{name}{qty}")
739:     }
740: }
