834: fn on_successful_attack_display(
835:     event: On<SuccessfulAttackResponse>,
836:     mut cmd: Commands,
837:     q_player: Query<(&Player, &CharacterId)>,
838:     mut span: Single<(Entity, &mut AttackResultText, &mut Text)>,
839: ) {
840:     let Some((player, id)) = event.hit.first().and_then(|e| q_player.get(*e).ok()) else {
841:         return;
842:     };
843: 
844:     span.1.timer.reset();
845:     span.1.timer.unpause();
846:     span.2.clear();
847:     cmd.entity(span.0)
848:         .despawn_children()
849:         .with_children(|children| {
850:             children.spawn(TextSpan::new("Attacking "));
851:             children.spawn((
852:                 ClassList::new("player-id"),
853:                 TextSpan::new(player.name.clone()),
854:                 InlineStyle::new(&format!(
855:                     "--player-color: {}",
856:                     id.color().to_srgba().to_hex()
857:                 )),
858:             ));
859:             children.spawn(TextSpan::new(": "));
860:             match event.result {
861:                 AttackResult::ToAttacker { balance_damage, .. } => {
862:                     let reason = match event.defender_response {
863:                         DefenderResponse::None => "Missed",
864:                         DefenderResponse::Block { .. } => "Blocked",
865:                         DefenderResponse::Dodge { .. } => "Dodged",
866:                         DefenderResponse::Parry { .. } => "Parried",
867:                     };
868:                     children.spawn((ClassList::new("error"), TextSpan::new("fail")));
869:                     children.spawn(TextSpan::new(format!(
870:                         "\n\n{reason}! Got {balance_damage:.1} balance damage\n\n[part: {}]",
871:                         event.body_part
872:                     )));
873:                 }
874:                 AttackResult::ToDefender {
875:                     cut_damage,
876:                     blunt_damage,
877:                     balance_damage,
878:                     ..
879:                 } => {
880:                     children.spawn((ClassList::new("success"), TextSpan::new("success")));
881:                     children.spawn(TextSpan::new(format!(
882:                         "\n\nDealt..\n{:.1} damage ({cut_damage:.1}C + {blunt_damage:.1}B)\n{balance_damage:.1} balance damage\n\n[part: {} | flanking: {:.1}]",
883:                         cut_damage + blunt_damage,
884:                         event.body_part,
885:                         event.flanking
886:                     )));
887:                 }
888:             }
889:         });
890: }
