3: 
4: pub(super) fn incapacitation_wheel_segments(
5:     sources: TacticalIncapacitationSources,
6: ) -> [(f32, Color32); 9] {
7:     [
8:         (
9:             sources.pain + sources.acute_trauma,
10:             Color32::from_rgb(0xd9, 0x73, 0xa2),
11:         ),
12:         (sources.blood_loss, Color32::from_rgb(0xc8, 0x47, 0x47)),
13:         (sources.fear, Color32::from_rgb(0x4f, 0x83, 0xcc)),
14:         (sources.fatigue, Color32::from_rgb(0x20, 0x20, 0x20)),
15:         (sources.hunger, Color32::from_rgb(0xb5, 0x7a, 0x35)),
16:         (sources.thirst, Color32::from_rgb(0x3f, 0x9f, 0xa8)),
17:         (sources.thermal, Color32::from_rgb(0x7d, 0x8e, 0xe8)),
18:         (sources.imbalance, Color32::WHITE),
19:         (
20:             sources.encumbrance,
21:             Color32::from_rgba_unmultiplied(160, 160, 160, 120),
22:         ),
23:     ]
24: }
25: 
26: /// Keep all current impairment visible before allocating remaining wheel
27: /// space to yellow forecasts. Forecasts never displace actual sources.
28: pub(super) fn forecast_wheel_segments(
29:     current: TacticalIncapacitationSources,
30:     forecast: TacticalIncapacitationSources,
31: ) -> Vec<(f32, Color32)> {
32:     let available = (1.0 - current.total()).clamp(0.0, 1.0);
33:     let predicted = forecast.total().max(0.0);
34:     let scale = if predicted > 0.0 {
35:         (available / predicted).min(1.0)
36:     } else {
37:         0.0
38:     };
39:     incapacitation_wheel_segments(current)
40:         .into_iter()
41:         .zip(incapacitation_wheel_segments(forecast))
42:         .flat_map(|((actual, color), (increase, _))| {
43:             [
44:                 (actual, color),
45:                 (increase.max(0.0) * scale, Color32::YELLOW),
46:             ]
47:         })
48:         .collect()
49: }
