1: use adventuresim_tactical_core::prelude::*;
2: use adventuresim_tactical_core::scene_coordinates::ScenePlanPoint;
3: use adventuresim_world_schema::UnitBasisPoints;
4: use bevy::audio::{AudioSink, AudioSinkPlayback, PlaybackMode, Volume};
5: use bevy::prelude::*;
6: 
7: use crate::{audio_config::TacticalAudioConfig, player::ClientPlayer};
8: 
9: pub struct WeatherAudioPlugin;
10: 
11: #[derive(Component, Clone, Copy, Debug, Eq, PartialEq)]
12: enum RainAudioLayer {
13:     Surface(RainSurface),
14:     HeavyStorm,
15: }
16: 
17: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
18: enum RainSurface {
19:     SoftGround,
20:     Foliage,
21:     HardGround,
22:     Water,
23: }
24: 
25: impl Plugin for WeatherAudioPlugin {
26:     fn build(&self, app: &mut App) {
27:         app.add_systems(Startup, spawn_rain_layers)
28:             .add_systems(Update, update_rain_layers);
29:     }
30: }
31: 
32: impl RainSurface {
33:     const ALL: [Self; 4] = [
34:         Self::SoftGround,
35:         Self::Foliage,
36:         Self::HardGround,
37:         Self::Water,
38:     ];
39: 
40:     fn asset_path(self) -> &'static str {
41:         match self {
42:             Self::SoftGround => "audio/weather/rain/soft-ground.ogg",
43:             Self::Foliage => "audio/weather/rain/foliage.ogg",
44:             Self::HardGround => "audio/weather/rain/hard-ground.ogg",
45:             Self::Water => "audio/weather/rain/water.ogg",
46:         }
47:     }
48: 
49:     fn at(surface: Option<GroundSurface>) -> Self {
50:         let Some(surface) = surface else {
51:             return Self::SoftGround;
52:         };
53:         match (surface.cover, surface.substrate) {
54:             (GroundCover::TallGrass | GroundCover::LeafLitter | GroundCover::Reeds, _) => {
55:                 Self::Foliage
56:             }
57:             (GroundCover::LooseStone, _) => Self::HardGround,
58:             (_, GroundSubstrate::Water) => Self::Water,
59:             (_, GroundSubstrate::Stone | GroundSubstrate::Gravel | GroundSubstrate::Road) => {
60:                 Self::HardGround
61:             }
62:             (_, GroundSubstrate::Soil | GroundSubstrate::Mud) => Self::SoftGround,
63:         }
64:     }
65: }
66: 
67: fn spawn_rain_layers(mut commands: Commands, asset_server: Res<AssetServer>) {
68:     for surface in RainSurface::ALL {
69:         spawn_rain_layer(
70:             &mut commands,
71:             &asset_server,
72:             RainAudioLayer::Surface(surface),
73:             surface.asset_path(),
74:         );
75:     }
76:     spawn_rain_layer(
77:         &mut commands,
78:         &asset_server,
79:         RainAudioLayer::HeavyStorm,
80:         "audio/weather/rain/rain-heavy.ogg",
81:     );
82: }
83: 
84: fn spawn_rain_layer(
85:     commands: &mut Commands,
86:     asset_server: &AssetServer,
87:     layer: RainAudioLayer,
88:     path: &'static str,
89: ) {
90:     commands.spawn((
91:         Name::new(format!("tactical-rain-{layer:?}")),
92:         layer,
93:         AudioPlayer::new(asset_server.load(path)),
94:         PlaybackSettings {
95:             mode: PlaybackMode::Loop,
96:             volume: Volume::SILENT,
97:             ..default()
98:         },
99:     ));
100: }
101: 
102: fn update_rain_layers(
103:     time: Res<Time>,
104:     environments: Query<&SceneEnvironment>,
105:     grounds: Query<&SceneGround>,
106:     listeners: Query<&GlobalTransform, With<ClientPlayer>>,
107:     mut layers: Query<(&RainAudioLayer, &mut AudioSink)>,
108:     config: Res<TacticalAudioConfig>,
109: ) {
110:     let weather = environments
111:         .iter()
112:         .next()
113:         .map(|environment| environment.weather);
114:     let intensity = weather
115:         .filter(|weather| weather.precipitation == Precipitation::Rain)
116:         .map(|weather| UnitBasisPoints::saturating(weather.intensity_bps))
117:         .unwrap_or_default();
118:     let listener_position = listeners
119:         .iter()
120:         .next()
121:         .and_then(|transform| ScenePlanPoint::from_metres(transform.translation().xz()));
122:     let surface = RainSurface::at(listener_position.and_then(|position| {
123:         grounds
124:             .iter()
125:             .next()
126:             .and_then(|ground| ground.ground_at(position))
127:     }));
128:     let (surface_volume, storm_volume) = rain_mix(intensity, &config);
129:     let response = 1.0 - (-config.weather.volume_response_per_second * time.delta_secs()).exp();
130:     for (layer, mut sink) in &mut layers {

131:         let target = match layer {
132:             RainAudioLayer::Surface(candidate) if *candidate == surface => surface_volume,
133:             RainAudioLayer::Surface(_) => 0.0,
134:             RainAudioLayer::HeavyStorm => storm_volume,
135:         };
136:         let volume = sink.volume().to_linear().lerp(target, response);
137:         sink.set_volume(Volume::Linear(volume));
138:     }
139: }
140: 
141: fn rain_mix(intensity: UnitBasisPoints, config: &TacticalAudioConfig) -> (f32, f32) {
142:     // Native gain calculation uses the weather intensity as a unit fraction.
143:     let intensity = intensity.as_unit_f32().clamp(0.0, 1.0);
144:     let weather = &config.weather;
145:     let storm = ((intensity - weather.heavy_rain_start_fraction)
146:         / (1.0 - weather.heavy_rain_start_fraction))
147:         .clamp(0.0, 1.0);
148:     let storm = storm * storm * (3.0 - 2.0 * storm);
149:     (
150:         weather.rain_surface_maximum_relative_volume
151:             * intensity.powf(weather.surface_intensity_exponent)
152:             * (1.0 - storm * weather.storm_surface_ducking),
153:         weather.rain_storm_maximum_relative_volume * storm,
154:     )
155: }
156: 
157: #[cfg(test)]
158: mod tests {
159:     use super::*;
160: 
161:     fn config() -> TacticalAudioConfig {
162:         TacticalAudioConfig::parse(include_str!("../../../assets/config/tactical-audio.yaml"))
163:             .unwrap()
164:     }
165: 
166:     fn surface(substrate: GroundSubstrate, cover: GroundCover) -> GroundSurface {
167:         GroundSurface {
168:             substrate,
169:             cover,
170:             ..default()
171:         }
172:     }
173: 
174:     #[test]
175:     fn cover_and_substrate_select_distinct_rain_beds() {
176:         assert_eq!(
177:             RainSurface::at(Some(surface(GroundSubstrate::Soil, GroundCover::TallGrass))),
178:             RainSurface::Foliage
179:         );
180:         assert_eq!(
181:             RainSurface::at(Some(surface(GroundSubstrate::Road, GroundCover::Bare))),
182:             RainSurface::HardGround
183:         );
184:         assert_eq!(
185:             RainSurface::at(Some(surface(GroundSubstrate::Water, GroundCover::Bare))),
186:             RainSurface::Water
187:         );
188:     }
189: 
190:     #[test]
191:     fn heavy_storm_layer_enters_only_above_its_threshold() {
192:         let config = config();
193:         assert_eq!(rain_mix(UnitBasisPoints::ZERO, &config), (0.0, 0.0));
194:         assert_eq!(
195:             rain_mix(
196:                 UnitBasisPoints::from_unit_f32(config.weather.heavy_rain_start_fraction).unwrap(),
197:                 &config,
198:             )
199:             .1,
200:             0.0
201:         );
202:         assert!(
203:             rain_mix(UnitBasisPoints::WHOLE, &config).1
204:                 > rain_mix(UnitBasisPoints::from_unit_f32(0.8).unwrap(), &config).1
205:         );
206:         assert!(rain_mix(UnitBasisPoints::WHOLE, &config).0 > 0.0);
207:     }
208: }

