1: //! Checked authored cadence policy and its complete native smoothing kernel.
2: 
3: use super::{
4:     AnimationElapsed, AnimationQuantity, AnimationValueError, AnimationValueResult, CycleDelta,
5:     NonnegativeLength, measurement::checked_nonnegative,
6: };
7: use adventuresim_building_generator::spatial_geometry::PositiveLength;
8: use adventuresim_core::linear_speed::NonnegativeSpeed;
9: use serde::{Deserialize, Serialize};
10: 
11: /// Nonnegative authored steps per second; zero needs no reciprocal period.
12: #[derive(Clone, Copy, Debug, PartialEq, PartialOrd, Serialize, Deserialize, derive_more::Into)]
13: #[serde(try_from = "f32", into = "f32")]
14: pub struct StepCadence(f32);
15: 
16: /// The smooth cap cannot begin below zero cadence. Keep authored scalar bits
17: /// and the calibrated-distance floor together after admission.
18: #[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
19: #[serde(try_from = "CadenceCapInput")]
20: pub struct AuthoredCadenceCap {
21:     maximum_per_second: StepCadence,
22:     transition_width_per_second: StepCadence,
23:     minimum_step_distance_metres: PositiveLength,
24: }
25: 
26: #[derive(Deserialize)]
27: #[serde(deny_unknown_fields)]
28: struct CadenceCapInput {
29:     maximum_per_second: StepCadence,
30:     transition_width_per_second: StepCadence,
31:     minimum_step_distance_metres: PositiveLength,
32: }
33: 
34: #[derive(Clone, Copy, Debug)]
35: pub struct CadenceSelection {
36:     requested: CadenceDemand,
37:     applied: StepCadence,
38: }
39: 
40: /// Finite motion can demand a rate beyond f32 when divided by a small stride.
41: #[derive(Clone, Copy, Debug)]
42: pub enum CadenceDemand {
43:     Finite(StepCadence),
44:     ExceedsScalarRange,
45: }
46: 
47: impl StepCadence {
48:     pub fn from_per_second(value: f32) -> AnimationValueResult<Self> {
49:         checked_nonnegative(value, AnimationQuantity::StepCadence).map(Self)
50:     }
51: 
52:     /// Native steps/second at trace, polynomial and derivative endpoints.
53:     pub fn per_second(self) -> f32 {
54:         self.0
55:     }
56: 
57:     /// Two steps make one cycle. Multiplication precedes halving so overflow
58:     /// is reported before an unwrapped phase delta can be retained.
59:     pub fn cycle_delta(self, elapsed: AnimationElapsed) -> AnimationValueResult<CycleDelta> {
60:         CycleDelta::from_arithmetic(self.0 * elapsed.seconds().max(0.0) * 0.5)
61:     }
62: }
63: 
64: impl AuthoredCadenceCap {
65:     pub fn new(
66:         maximum_per_second: StepCadence,
67:         transition_width_per_second: StepCadence,
68:         minimum_step_distance_metres: PositiveLength,
69:     ) -> AnimationValueResult<Self> {
70:         if transition_width_per_second.0 * 0.5 > maximum_per_second.0 {
71:             return Err(AnimationValueError::CadenceTransitionBelowZero);
72:         }
73:         Ok(Self {
74:             maximum_per_second,
75:             transition_width_per_second,
76:             minimum_step_distance_metres,
77:         })
78:     }
79: 
80:     pub fn select_for_motion(
81:         self,
82:         speed: NonnegativeSpeed,
83:         step_distance: NonnegativeLength,
84:     ) -> AnimationValueResult<CadenceSelection> {
85:         let requested =
86:             CadenceDemand::from_motion(speed, step_distance, self.minimum_step_distance_metres)?;
87:         self.select(requested)
88:     }
89: 
90:     pub fn select(self, requested: CadenceDemand) -> AnimationValueResult<CadenceSelection> {
91:         let applied = match requested {
92:             CadenceDemand::ExceedsScalarRange => self.maximum_per_second,
93:             CadenceDemand::Finite(requested) => {
94:                 // Native C2 polynomial in steps/second. The checked policy
95:                 // prevents a negative transition start; no reciprocal is needed
96:                 // for a zero-width hard cap. Preserve every scalar operation.
97:                 let half_width = self.transition_width_per_second.0 * 0.5;
98:                 let transition_start = self.maximum_per_second.0 - half_width;
99:                 let transition_end = self.maximum_per_second.0 + half_width;
100:                 if requested.0 <= transition_start {
101:                     requested
102:                 } else if requested.0 >= transition_end {
103:                     self.maximum_per_second
104:                 } else {
105:                     let t = (requested.0 - transition_start) / self.transition_width_per_second.0;
106:                     // Integral of 1 - smoothstep(t): unit initial slope,
107:                     // zero final slope and zero curvature at both ends.
108:                     let applied = transition_start
109:                         + self.transition_width_per_second.0 * (t - t.powi(3) + 0.5 * t.powi(4));
110:                     if !applied.is_finite() {
111:                         return Err(AnimationValueError::Overflow {
112:                             quantity: AnimationQuantity::StepCadence,
113:                         });
114:                     }
115:                     StepCadence::from_per_second(applied)?
116:                 }
117:             }
118:         };
119:         Ok(CadenceSelection { requested, applied })
120:     }
121: }
122: 
123: impl CadenceDemand {
124:     fn from_motion(
125:         speed: NonnegativeSpeed,
126:         step_distance: NonnegativeLength,
127:         minimum: PositiveLength,
128:     ) -> AnimationValueResult<Self> {
129:         // Metres/second divided by calibrated metres/step at the complete
130:         // demand kernel. Positive floor and finite speed exclude NaN/negative
131:         // demand; represent positive scalar overflow explicitly before retention.
132:         let requested = speed.metres_per_second() / step_distance.metres().max(minimum.metres());
133:         if requested.is_infinite() {
134:             Ok(Self::ExceedsScalarRange)
135:         } else {
136:             StepCadence::from_per_second(requested).map(Self::Finite)
137:         }
138:     }
139: }
140: 
141: impl CadenceSelection {
142:     pub fn requested(self) -> CadenceDemand {
143:         self.requested
144:     }
145: 
146:     pub fn applied(self) -> StepCadence {
147:         self.applied
148:     }
149: 
150:     pub fn is_capped(self) -> bool {
151:         match self.requested {
152:             CadenceDemand::Finite(requested) => self.applied < requested,
153:             CadenceDemand::ExceedsScalarRange => true,
154:         }
155:     }
156: }
