161: fn posture_transition_samples(
162:     state: &SkeletonState,
163: ) -> AnimationValueResult<Option<Vec<PoseSample>>> {
164:     let Some(transition) = state.posture_transition() else {
165:         return Ok(None);
166:     };
167:     use PostureTransitionKind::*;
168:     if let DiveToDowned { direction, .. } = transition.kind() {
169:         return Ok(Some(dive_transition_samples(
170:             state.lead_foot,
171:             direction,
172:             transition.phase(),
173:         )?));
174:     }
175:     let (start, middle, end) = match transition.kind() {
176:         UprightToProne => (
177:             SemanticPose::IdleRelaxed,
178:             SemanticPose::ProneTransition,
179:             SemanticPose::ProneIdle,
180:         ),
181:         ProneToUpright => (
182:             SemanticPose::ProneIdle,
183:             SemanticPose::ProneTransition,
184:             SemanticPose::IdleRelaxed,
185:         ),
186:         ProneToSupine { direction } => (
187:             SemanticPose::ProneIdle,
188:             roll_pose(direction),
189:             SemanticPose::SupineIdle,
190:         ),
191:         SupineToProne { direction } => (
192:             SemanticPose::SupineIdle,
193:             // Reversing a prone-to-supine roll reverses its travel too. Pick
194:             // the opposite authored side so input direction remains spatial.
195:             roll_pose(direction.opposite()),
196:             SemanticPose::ProneIdle,
197:         ),
198:         SupineToUpright => (
199:             SemanticPose::SupineIdle,
200:             SemanticPose::SupineTransition,
201:             SemanticPose::IdleRelaxed,
202:         ),
203:         DiveToDowned { .. } => unreachable!("dive transitions return above"),
204:     };
205:     let phase = transition.phase().fraction();
206:     let (pose, next, progress) = if phase < 0.5 {
207:         (start, middle, phase * 2.0)
208:     } else {
209:         (middle, end, (phase - 0.5) * 2.0)
210:     };
211:     Ok(Some(vec![PoseSample {
212:         pose,
213:         sampling: PoseSampling::Span {
214:             end: next,
215:             progress: UnitInterval::from_fraction(progress)?,
216:         },
217:         weight: BlendWeight::ONE,
218:         mirror_lower_body: ClipMirror::Original,
219:     }]))
220: }
221: 
222: fn downed_facing_samples(state: &SkeletonState) -> AnimationValueResult<Option<Vec<PoseSample>>> {
223:     let Some(facing) = state.downed_facing() else {
224:         return Ok(None);
225:     };
226:     let roll = facing.roll_coordinate().half_turns();
227:     // Whole values are already represented by the body's prone/supine base
228:     // pose. Leaving a zero-progress roll action active here would mask the
229:     // crawl/scamper base layer for as long as aim remains held.
230:     if (roll - roll.round()).abs() <= 1.0e-4 {
231:         return Ok(None);
232:     }
233:     let start_index = roll.floor() as i64;
234:     let progress = roll - roll.floor();
235:     let start_prone = start_index.rem_euclid(2) == 0;
236:     let (start, end) = if start_prone {
237:         (SemanticPose::ProneIdle, SemanticPose::SupineIdle)
238:     } else {
239:         (SemanticPose::SupineIdle, SemanticPose::ProneIdle)
240:     };
241:     let middle = if start_index.rem_euclid(2) == 0 {
242:         SemanticPose::ProneSupineRollRight
243:     } else {
244:         SemanticPose::ProneSupineRollLeft
245:     };
246:     let (pose, next, span) = if progress < 0.5 {
247:         (start, middle, progress * 2.0)
248:     } else {
249:         (middle, end, (progress - 0.5) * 2.0)
250:     };
251:     Ok(Some(vec![PoseSample {
252:         pose,
253:         sampling: PoseSampling::Span {
254:             end: next,
255:             progress: UnitInterval::from_fraction(span)?,
256:         },
257:         weight: BlendWeight::ONE,
258:         mirror_lower_body: ClipMirror::Original,
259:     }]))
260: }
261: 
262: fn dive_transition_samples(
263:     _lead: LeadFoot,
264:     direction: DiveDirection,
265:     phase: UnitInterval,
266: ) -> AnimationValueResult<Vec<PoseSample>> {
267:     let dive = dive_pose(direction);
268:     let progress = phase;
269:     let phase = progress.fraction();
270:     if phase < DIVE_GROUND_CONTACT_PHASE.fraction() {
271:         return Ok(vec![PoseSample {
272:             pose: SemanticPose::GuardThrust,
273:             sampling: PoseSampling::Span {
274:                 end: dive,
275:                 progress: UnitInterval::from_fraction(phase * 2.0)?,
276:             },
277:             weight: BlendWeight::ONE,
278:             mirror_lower_body: ClipMirror::Original,
279:         }]);
280:     }
281:     let contact = match direction {
282:         DiveDirection::Forward => SemanticPose::ProneIdle,
283:         DiveDirection::Backward => SemanticPose::SupineIdle,
284:         DiveDirection::Left => SemanticPose::ProneSupineRollLeft,
285:         DiveDirection::Right => SemanticPose::ProneSupineRollRight,
286:     };
287:     // Contact begins and ends at zero blend velocity, matching the procedural
288:     // pelvis release and the authoritative directional root handoff. Starting
289:     // this span linearly made the complete upper-body chain visibly twist on
290:     // the first grounded frame, including on forward dives with no root yaw.
291:     let recovery = dive_contact_pose_progress(progress)?;
292:     Ok(vec![PoseSample {
293:         pose: dive,
294:         sampling: PoseSampling::Span {
295:             end: contact,
296:             progress: recovery,
297:         },
298:         weight: BlendWeight::ONE,
299:         mirror_lower_body: ClipMirror::Original,
300:     }])
301: }
302: 
303: /// The dive clip contributes only above the pelvis. The lower body holds the
304: /// guard through takeoff, then blends into the appropriate ground contact.
305: fn dive_lower_body_samples(
306:     _lead: LeadFoot,
307:     direction: DiveDirection,
308:     phase: UnitInterval,
309: ) -> AnimationValueResult<Vec<PoseSample>> {
310:     let progress = phase;

311:     let phase = progress.fraction();
312:     let sampling = if phase < DIVE_GROUND_CONTACT_PHASE.fraction() {
313:         PoseSampling::Anchor
314:     } else {
315:         let contact = match direction {
316:             DiveDirection::Forward => SemanticPose::ProneIdle,
317:             DiveDirection::Backward => SemanticPose::SupineIdle,
318:             DiveDirection::Left => SemanticPose::ProneSupineRollLeft,
319:             DiveDirection::Right => SemanticPose::ProneSupineRollRight,
320:         };
321:         PoseSampling::Span {
322:             end: contact,
323:             progress: dive_contact_pose_progress(progress)?,
324:         }
325:     };
326:     Ok(vec![PoseSample {
327:         pose: SemanticPose::GuardThrust,
328:         sampling,
329:         weight: BlendWeight::ONE,
330:         mirror_lower_body: ClipMirror::Original,
331:     }])
332: }
333: 
334: fn dive_contact_pose_progress(phase: UnitInterval) -> AnimationValueResult<UnitInterval> {
335:     smoothstep01((phase.fraction() - DIVE_GROUND_CONTACT_PHASE.fraction()) * 2.0)
336: }
337: 
338: fn dive_pose(direction: DiveDirection) -> SemanticPose {
339:     match direction {
340:         DiveDirection::Forward => SemanticPose::DiveForward,
341:         DiveDirection::Backward => SemanticPose::DiveBackward,
342:         DiveDirection::Left => SemanticPose::DiveLeft,
343:         DiveDirection::Right => SemanticPose::DiveRight,
344:     }
345: }
346: 
347: fn roll_pose(direction: RollDirection) -> SemanticPose {
348:     match direction {
349:         RollDirection::Left => SemanticPose::ProneSupineRollLeft,
350:         RollDirection::Right => SemanticPose::ProneSupineRollRight,
351:     }
352: }
353: 
354: fn raised_guard_locomotion_samples(state: &SkeletonState) -> Vec<PoseSample> {
355:     let preparation = state.attack_preparation();
356:     let sampling = if preparation.from == preparation.to {
357:         PoseSampling::Anchor
358:     } else {
359:         PoseSampling::Span {
360:             end: guard_pose(preparation.to),
361:             progress: preparation.progress,
362:         }
363:     };
364:     vec![PoseSample {
365:         pose: guard_pose(preparation.from),
366:         sampling,
367:         weight: BlendWeight::ONE,
368:         mirror_lower_body: ClipMirror::Original,
369:     }]
370: }
371: 
372: fn smoothstep01(value: f32) -> AnimationValueResult<UnitInterval> {
373:     let value = value.clamp(0.0, 1.0);
374:     Ok(UnitInterval::from_fraction(
375:         value * value * (3.0 - 2.0 * value),
376:     )?)
377: }
