379: fn airborne_sample(horizontal_speed: NonnegativeSpeed) -> AnimationValueResult<PoseSample> {
380:     Ok(PoseSample {
381:         pose: SemanticPose::AirborneCenter,
382:         sampling: PoseSampling::Span {
383:             end: SemanticPose::AirborneTravel,
384:             progress: smoothstep01(
385:                 horizontal_speed.metres_per_second()
386:                     / walk_locomotion_profile()
387:                         .reference_speed
388:                         .metres_per_second(),
389:             )?,
390:         },
391:         weight: BlendWeight::ONE,
392:         mirror_lower_body: ClipMirror::Original,
393:     })
394: }
