3: pub(super) fn attack_samples(state: &SkeletonState) -> AnimationValueResult<Vec<PoseSample>> {
4:     let phase = state.action_phase();
5:     let animation = state.attack_animation().unwrap_or(AttackAnimation::Thrust);
6:     let start_guard =
7:         if animation == AttackAnimation::Offhand && !state.attack_animations.offhand_preparation {
8:             guard_pose(state.attack_preparation().to)
9:         } else {
10:             guard_pose(animation)
11:         };
12:     let end_guard = guard_pose(state.attack_preparation().to);
13:     let contact =
14:         if animation == AttackAnimation::Offhand && state.attack_animations.offhand_preparation {
15:             SemanticPose::AttackOffhandPrepared
16:         } else {
17:             attack_pose(animation)
18:         };
19:     if let Some(continuation) = state.attack_continuation() {
20:         return Ok(vec![PoseSample {
21:             pose: start_guard,
22:             sampling: PoseSampling::ContinuationSpan {
23:                 contact,
24:                 end: recovery_pose(animation),
25:                 outgoing: continuation_pose(animation),
26:                 finish: end_guard,
27:                 start_coordinate: continuation.start_coordinate,
28:                 incoming_tangent: continuation.incoming_tangent,
29:                 ready_phase: ContinuationReadiness::FOLLOW_READY,
30:                 progress: phase,
31:             },
32:             weight: BlendWeight::ONE,
33:             mirror_lower_body: ClipMirror::Original,
34:         }]);
35:     }
36:     let coordinate = if phase.fraction() < 0.5 || !state.attack_has_queued_continuation() {
37:         state.attack_curve().coordinate(phase)?
38:     } else {
39:         state.attack_curve().queued_recovery_coordinate(phase)?
40:     };
41:     Ok(vec![PoseSample {
42:         pose: start_guard,
43:         sampling: PoseSampling::CurveSpan {
44:             end: contact,
45:             coordinate,
46:         },
47:         weight: BlendWeight::ONE,
48:         mirror_lower_body: ClipMirror::Original,
49:     }])
50: }
51: 
52: pub(super) fn guard_pose(animation: AttackAnimation) -> SemanticPose {
53:     match animation {
54:         AttackAnimation::Swing => SemanticPose::GuardSwing,
55:         AttackAnimation::Thrust => SemanticPose::GuardThrust,
56:         AttackAnimation::Offhand => SemanticPose::GuardOffhand,
57:     }
58: }
59: 
60: fn attack_pose(animation: AttackAnimation) -> SemanticPose {
61:     match animation {
62:         AttackAnimation::Swing => SemanticPose::AttackSwing,
63:         AttackAnimation::Thrust => SemanticPose::AttackThrust,
64:         AttackAnimation::Offhand => SemanticPose::AttackOffhand,
65:     }
66: }
67: 
68: fn recovery_pose(animation: AttackAnimation) -> SemanticPose {
69:     match animation {
70:         AttackAnimation::Swing => SemanticPose::RecoverSwing,
71:         AttackAnimation::Thrust => SemanticPose::RecoverThrust,
72:         AttackAnimation::Offhand => SemanticPose::GuardOffhand,
73:     }
74: }
75: 
76: fn continuation_pose(animation: AttackAnimation) -> SemanticPose {
77:     match animation {
78:         AttackAnimation::Swing => SemanticPose::ContinueSwing,
79:         AttackAnimation::Thrust => SemanticPose::ContinueThrust,
80:         AttackAnimation::Offhand => SemanticPose::AttackOffhand,
81:     }
82: }

