8: pub(super) fn combat_lower_body_samples(
9:     state: &SkeletonState,
10:     speed: NonnegativeSpeed,
11: ) -> AnimationValueResult<Vec<PoseSample>> {
12:     if speed
13:         <= crate::combat_config::runtime_animation_config()
14:             .playback
15:             .initial_locomotion_speed_metres_per_second
16:         || !state.raised_locomotion().is_moving()
17:     {
18:         return Ok(vec![anchor_sample(SemanticPose::CombatStance)]);
19:     }
20:     if state.is_guarded_sprinting() {
21:         return locomotion_samples(speed, state.gait_phase);
22:     }
23:     let direction = state.raised_locomotion().local_direction();
24:     let strafe = direction.x.abs();
25:     let skip = direction.y.abs();
26:     let total = strafe + skip;
27:     if total <= 0.0 {
28:         return Ok(vec![anchor_sample(SemanticPose::CombatStance)]);
29:     }
30:     let mut samples = Vec::with_capacity(2);
31:     if strafe > 0.0 {
32:         let phase = combat_cycle_phase(state.gait_phase)?;
33:         let mut sample = cycle_sample(
34:             SemanticPose::StrafeCycle,
35:             if direction.x < 0.0 {
36:                 reverse_cycle_phase(phase)?
37:             } else {
38:                 phase
39:             },
40:         );
41:         sample.weight = BlendWeight::from_factor(strafe / total)?;
42:         samples.push(sample);
43:     }
44:     if skip > 0.0 {
45:         let phase = combat_cycle_phase(state.gait_phase)?;
46:         // Forward skip selects the opposite authored contact half-cycle.
47:         let phase = if direction.y < 0.0 {
48:             CyclePhase::from_cycles((phase.cycles() + 0.5).rem_euclid(1.0))?
49:         } else {
50:             phase
51:         };
52:         let mut sample = cycle_sample(SemanticPose::SkipCycle, phase);
53:         sample.weight = BlendWeight::from_factor(skip / total)?;
54:         samples.push(sample);
55:     }
56:     Ok(samples)
57: }
58: 
59: pub(super) fn quickstep_lower_body_samples(
60:     state: &SkeletonState,
61: ) -> AnimationValueResult<Vec<PoseSample>> {
62:     // The full action phase keeps authored load/launch/landing on the physical force curve.
63:     let progress = state.action_phase();
64:     let direction = state.action_direction().normalize_or_zero();
65:     let directional = [
66:         (direction.y.max(0.0), SemanticPose::QuickstepForwardTakeoff),
67:         (direction.x.max(0.0), SemanticPose::QuickstepRightTakeoff),
68:         ((-direction.x).max(0.0), SemanticPose::QuickstepLeftTakeoff),
69:         ((-direction.y).max(0.0), SemanticPose::QuickstepBackTakeoff),
70:     ];
71:     let total = directional.iter().map(|(weight, _)| weight).sum::<f32>();
72:     directional
73:         .into_iter()
74:         .filter(|(weight, _)| *weight > 0.0)
75:         .map(|(weight, pose)| {
76:             Ok(PoseSample {
77:                 pose,
78:                 sampling: PoseSampling::Timeline { progress },
79:                 weight: BlendWeight::from_factor(weight / total)?,
80:                 mirror_lower_body: ClipMirror::Original,
81:             })
82:         })
83:         .collect()
84: }
