86: pub(super) fn gait_or_idle(
87:     speed: NonnegativeSpeed,
88:     phase: CyclePhase,
89:     idle: SemanticPose,
90:     contact: SemanticPose,
91: ) -> AnimationValueResult<Vec<PoseSample>> {
92:     if speed
93:         < crate::combat_config::runtime_animation_config()
94:             .playback
95:             .initial_locomotion_speed_metres_per_second
96:     {
97:         Ok(vec![PoseSample {
98:             pose: idle,
99:             sampling: PoseSampling::Anchor,
100:             weight: BlendWeight::ONE,
101:             mirror_lower_body: ClipMirror::Original,
102:         }])
103:     } else {
104:         alternating_contact_pair(phase, contact)
105:     }
