108: /// Ordinary upright locomotion blends the forward gait against the authored
109: /// strafe cycle in the hips' frame. As the root turns toward world velocity,
110: /// the lateral contribution naturally falls to zero.
111: pub(super) fn upright_locomotion_samples(
112:     state: &SkeletonState,
113:     speed: NonnegativeSpeed,
114: ) -> AnimationValueResult<Vec<PoseSample>> {
115:     let phase = state.gait_phase.wrapped();
116:     let direction = state.animation_local_velocity().xz().normalize_or_zero();
117:     let lateral = direction.x.abs();
118:     let longitudinal = direction.y.abs();
119:     let total = lateral + longitudinal;
120:     if lateral <= 0.0 || total <= 0.0 {
121:         return locomotion_samples(speed, phase);
122:     }
123: 
124:     let locomotion = smoothstep01(
125:         speed.metres_per_second()
126:             / crate::combat_config::runtime_animation_config()
127:                 .locomotion
128:                 .blend_speed
129:                 .metres_per_second(),
130:     )?
131:     .fraction();
132:     let longitudinal_weight = longitudinal / total;
133:     let lateral_weight = lateral / total;
134:     let mut samples = locomotion_samples(speed, phase)?;
135:     for sample in &mut samples {
136:         if sample.pose == SemanticPose::IdleRelaxed {
137:             continue;
138:         }
139:         sample.weight = sample
140:             .weight
141:             .checked_scale(BlendWeight::from_factor(longitudinal_weight)?)?;
142:     }
143:     let strafe_phase = combat_cycle_phase(phase)?;
144:     let mut strafe = cycle_sample(
145:         SemanticPose::StrafeCycle,
146:         if direction.x < 0.0 {
147:             reverse_cycle_phase(strafe_phase)?
148:         } else {
149:             strafe_phase
150:         },
151:     );
152:     strafe.weight = BlendWeight::from_factor(locomotion * lateral_weight)?;
153:     samples.push(strafe);
154:     samples.retain(|sample| !sample.weight.is_absent());
155:     Ok(samples)
156: }
