158: pub(super) fn downed_animation_speed(
159:     state: &SkeletonState,
160:     speed: NonnegativeSpeed,
161: ) -> NonnegativeSpeed {
162:     if state.is_downed_turning() {
163:         speed
164:     } else {
165:         NonnegativeSpeed::ZERO
166:     }
167: }
168: 
169: fn combat_cycle_phase(gait_phase: CyclePhase) -> AnimationValueResult<CyclePhase> {
170:     // Authored combat contacts are frames 6/18 of a 24-frame cycle.

171:     CyclePhase::from_cycles((gait_phase.cycles() + 0.25).rem_euclid(1.0))
172: }
173: 
174: fn reverse_cycle_phase(phase: CyclePhase) -> AnimationValueResult<CyclePhase> {
175:     CyclePhase::from_cycles((1.0 - phase.cycles()).rem_euclid(1.0))
176: }
177: 
178: fn anchor_sample(pose: SemanticPose) -> PoseSample {
179:     PoseSample {
180:         pose,
181:         sampling: PoseSampling::Anchor,
182:         weight: BlendWeight::ONE,
183:         mirror_lower_body: ClipMirror::Original,
184:     }
185: }
186: 
187: fn alternating_contact_pair(
188:     phase: CyclePhase,
189:     contact: SemanticPose,
190: ) -> AnimationValueResult<Vec<PoseSample>> {
191:     let half = phase.wrapped().cycles() * 2.0;
192:     let progress = smoothstep01(half.fract())?.fraction();
193:     let (start_mirrored, end_mirrored) = if half < 1.0 {
194:         (ClipMirror::Original, ClipMirror::Mirrored)
195:     } else {
196:         (ClipMirror::Mirrored, ClipMirror::Original)
197:     };
198:     let mut samples = Vec::with_capacity(2);
199:     if progress < 1.0 {
200:         samples.push(PoseSample {
201:             pose: contact,
202:             sampling: PoseSampling::Anchor,
203:             weight: BlendWeight::from_factor(1.0 - progress)?,
204:             mirror_lower_body: start_mirrored,
205:         });
206:     }
207:     if progress > 0.0 {
208:         samples.push(PoseSample {
209:             pose: contact,
210:             sampling: PoseSampling::Anchor,
211:             weight: BlendWeight::from_factor(progress)?,
212:             mirror_lower_body: end_mirrored,
213:         });
214:     }
215:     Ok(samples)
216: }
217: 
218: fn locomotion_samples(
219:     speed: NonnegativeSpeed,
220:     phase: CyclePhase,
221: ) -> AnimationValueResult<Vec<PoseSample>> {
222:     let locomotion = smoothstep01(
223:         speed.metres_per_second()
224:             / crate::combat_config::runtime_animation_config()
225:                 .locomotion
226:                 .blend_speed
227:                 .metres_per_second(),
228:     )?
229:     .fraction();
230:     let run = ((speed.metres_per_second()
231:         - walk_locomotion_profile()
232:             .reference_speed
233:             .metres_per_second())
234:         / (run_locomotion_profile().reference_speed.metres_per_second()
235:             - walk_locomotion_profile()
236:                 .reference_speed
237:                 .metres_per_second()))
238:     .clamp(0.0, 1.0);
239:     let mut samples = Vec::with_capacity(5);
240:     append_scaled(
241:         &mut samples,
242:         vec![PoseSample {
243:             pose: SemanticPose::IdleRelaxed,
244:             sampling: PoseSampling::Anchor,
245:             weight: BlendWeight::ONE,
246:             mirror_lower_body: ClipMirror::Original,
247:         }],
248:         BlendWeight::from_factor(1.0 - locomotion)?,
249:     )?;
250:     append_scaled(
251:         &mut samples,
252:         vec![cycle_sample(SemanticPose::WalkContact, phase)],
253:         BlendWeight::from_factor(locomotion * (1.0 - run))?,
254:     )?;
255:     append_scaled(
256:         &mut samples,
257:         vec![cycle_sample(SemanticPose::RunContact, phase)],
258:         BlendWeight::from_factor(locomotion * run)?,
259:     )?;
260:     samples.retain(|sample| !sample.weight.is_absent());
261:     Ok(samples)
262: }
263: 
264: fn cycle_sample(pose: SemanticPose, phase: CyclePhase) -> PoseSample {
265:     PoseSample {
266:         pose,
267:         sampling: PoseSampling::Cycle {
268:             phase: phase.wrapped(),
269:         },
270:         weight: BlendWeight::ONE,
271:         mirror_lower_body: ClipMirror::Original,
272:     }
273: }
274: 
275: fn append_scaled(
276:     into: &mut Vec<PoseSample>,
277:     samples: Vec<PoseSample>,
278:     scale: BlendWeight,
279: ) -> AnimationValueResult<()> {
280:     let scaled = samples
281:         .into_iter()
282:         .map(|mut sample| {
283:             sample.weight = sample.weight.checked_scale(scale)?;
284:             Ok(sample)
285:         })
286:         .collect::<AnimationValueResult<Vec<_>>>()?;
287:     into.extend(scaled);
288:     Ok(())
289: }
