291: #[cfg(test)]
292: pub(in crate::animation) fn gait_pair(
293:     phase: CyclePhase,
294:     contact: SemanticPose,
295:     passing: SemanticPose,
296: ) -> AnimationValueResult<Vec<PoseSample>> {
297:     let quarter = phase.cycles().rem_euclid(1.0) * GAIT_QUARTERS_PER_CYCLE;
298:     // A smooth cubic Hermite coordinate gives every sparse contact/flight
299:     // anchor zero endpoint velocity. Linear quarter interpolation changed
300:     // velocity discontinuously at each anchor and produced a visible knee and
301:     // ankle snap even though the poses themselves were continuous.
302:     let progress = smoothstep01(quarter.fract())?.fraction();
303:     let (start, start_mirrored, end, end_mirrored) = match quarter.floor() as u8 {
304:         0 => (contact, ClipMirror::Original, passing, ClipMirror::Original),
305:         1 => (passing, ClipMirror::Original, contact, ClipMirror::Mirrored),
306:         2 => (contact, ClipMirror::Mirrored, passing, ClipMirror::Mirrored),
307:         _ => (passing, ClipMirror::Mirrored, contact, ClipMirror::Original),
308:     };
309:     let mut samples = Vec::with_capacity(2);
310:     if progress < 1.0 {
311:         samples.push(PoseSample {
312:             pose: start,
313:             sampling: PoseSampling::Anchor,
314:             weight: BlendWeight::from_factor(1.0 - progress)?,
315:             mirror_lower_body: start_mirrored,
316:         });
317:     }
318:     if progress > 0.0 {
319:         samples.push(PoseSample {
320:             pose: end,
321:             sampling: PoseSampling::Anchor,
322:             weight: BlendWeight::from_factor(progress)?,
323:             mirror_lower_body: end_mirrored,
324:         });
325:     }
326:     Ok(samples)
327: }

1: //! Height treatment roles over shared finite nonnegative measurements.
2: 
3: use super::{
4:     AnimationElapsed, AnimationQuantity, AnimationValueError, AnimationValueResult, CyclePhase,
5:     LandingImpactSpeed, NonnegativeLength, NonnegativeSpeed, UnitInterval,
6: };
7: use adventuresim_building_generator::spatial_geometry::SignedLength;
8: use serde::{Deserialize, Serialize};
9: 
10: /// A zero-permitting height amplitude or compression, in metres.
11: #[derive(
12:     Clone,
13:     Copy,
14:     derive_more::Debug,
15:     Default,
16:     PartialEq,
17:     PartialOrd,
18:     Serialize,
19:     Deserialize,
20:     derive_more::Into,
21: )]
22: #[serde(try_from = "f32", into = "f32")]
23: #[debug("HeightDistance({:?})", self.0.metres())]
24: #[into(f32)]
25: pub struct HeightDistance(NonnegativeLength);
26: 
27: /// A nonnegative absorption or recovery rate, in metres per second.
28: #[derive(
29:     Clone,
30:     Copy,
31:     derive_more::Debug,
32:     Default,
33:     PartialEq,
34:     PartialOrd,
35:     Serialize,
36:     Deserialize,
37:     derive_more::Into,
38: )]
39: #[serde(try_from = "f32", into = "f32")]
40: #[debug("HeightSpeed({:?})", self.0.metres_per_second())]
41: #[into(f32)]
42: pub struct HeightSpeed(NonnegativeSpeed);
43: 
44: impl HeightDistance {
45:     pub const ZERO: Self = Self(NonnegativeLength::ZERO);
46:     pub fn from_metres(value: f32) -> AnimationValueResult<Self> {
47:         NonnegativeLength::from_metres(value)
48:             .map(Self)
49:             .map_err(|error| error.for_quantity(AnimationQuantity::HeightDistance))
50:     }
51:     pub fn metres(self) -> f32 {
52:         self.0.metres()
53:     }
54:     pub fn scaled_by(self, weight: UnitInterval) -> AnimationValueResult<Self> {
55:         Self::from_arithmetic(self.metres() * weight.fraction())
56:     }
57:     /// A flight wave multiplies the periodic factor before its authored amplitude.
58:     pub fn flight_wave(
59:         self,
60:         phase: CyclePhase,
61:         weight: UnitInterval,
62:     ) -> AnimationValueResult<Self> {
63:         let half_step = (phase.cycles().rem_euclid(0.5) * 2.0).clamp(0.0, 1.0);
64:         let flight = (half_step * std::f32::consts::PI).sin().powi(2) * self.metres();
65:         Self::from_arithmetic(flight * weight.fraction())
66:     }
67:     pub fn advance_towards(self, target: Self, maximum_delta: Self) -> AnimationValueResult<Self> {
68:         let value = self.metres()
69:             + (target.metres() - self.metres()).clamp(
70:                 -maximum_delta.metres().max(0.0),
71:                 maximum_delta.metres().max(0.0),
72:             );
73:         Self::from_arithmetic(value)
74:     }
75:     pub fn from_arithmetic(value: f32) -> AnimationValueResult<Self> {
76:         if !value.is_finite() {
77:             return Err(AnimationValueError::Overflow {
78:                 quantity: AnimationQuantity::HeightDistance,
79:             });
80:         }
81:         Self::from_metres(value)
82:     }
83:     pub fn difference(self, other: Self) -> AnimationValueResult<SignedLength> {
84:         SignedLength::from_metres(self.metres() - other.metres()).map_err(|_| {
85:             AnimationValueError::Overflow {
86:                 quantity: AnimationQuantity::HeightOffset,
87:             }
88:         })
89:     }
90: }
91: impl HeightSpeed {
92:     pub const ZERO: Self = Self(NonnegativeSpeed::ZERO);
93:     pub fn from_metres_per_second(value: f32) -> AnimationValueResult<Self> {
94:         NonnegativeSpeed::from_metres_per_second(value)
95:             .map(Self)
96:             .map_err(|error| {
97:                 AnimationValueError::from(error).for_quantity(AnimationQuantity::HeightSpeed)
98:             })
99:     }
100:     pub fn metres_per_second(self) -> f32 {
101:         self.0.metres_per_second()
102:     }
103:     pub fn max(self, other: Self) -> Self {
104:         if self.0 >= other.0 { self } else { other }
105:     }
106:     /// Landing absorption uses the larger of the measured impact and configured minimum.
107:     pub fn absorption(impact: LandingImpactSpeed, minimum: Self) -> Self {
108:         Self(impact.speed().max(minimum.0))
109:     }
110:     pub fn recovery(
111:         compression: HeightDistance,
112:         elapsed: AnimationElapsed,
113:     ) -> AnimationValueResult<Self> {
114:         let rate = compression.metres() / elapsed.seconds();
115:         if !rate.is_finite() {
116:             return Err(AnimationValueError::Overflow {
117:                 quantity: AnimationQuantity::HeightSpeed,
118:             });
119:         }
120:         Self::from_metres_per_second(rate)
121:     }
122:     pub fn over(self, elapsed: AnimationElapsed) -> AnimationValueResult<HeightDistance> {
123:         HeightDistance::from_arithmetic(self.0.metres_per_second() * elapsed.seconds())
124:     }
125: }
126: 
127: impl TryFrom<f32> for HeightDistance {
128:     type Error = AnimationValueError;
129:     fn try_from(value: f32) -> AnimationValueResult<Self> {
130:         Self::from_metres(value)
131:     }
132: }
133: impl TryFrom<f32> for HeightSpeed {
134:     type Error = AnimationValueError;
135:     fn try_from(value: f32) -> AnimationValueResult<Self> {
136:         Self::from_metres_per_second(value)
137:     }
138: }

