58: impl SkeletonState {
59:     /// Presentation motion finishes an in-flight raised-guard step after
60:     /// gameplay velocity stops. Speed otherwise follows authoritative motion.
61:     pub fn animation_local_velocity(&self) -> Vec3 {
62:         let raised = self.raised_locomotion();
63:         if self.weapon_guard() == WeaponGuardState::Raised && raised.is_moving() {
64:             raised.local_velocity()
65:         } else {
66:             self.local_velocity
67:         }
68:     }
69: 
70:     /// Measure animation motion in the body's horizontal plane. Reject a
71:     /// nonfinite norm before applying the existing downed-turning minimum.
72:     pub fn animation_speed(&self) -> AnimationValueResult<NonnegativeSpeed> {
73:         let physical = self.animation_local_velocity().xz().length();
74:         if !physical.is_finite() {
75:             return Err(AnimationValueError::Overflow {
76:                 quantity: AnimationQuantity::Speed,
77:             });
78:         }
79:         let physical = NonnegativeSpeed::from_metres_per_second(physical)?;
80:         Ok(if self.is_downed_turning() {
81:             physical.max(MINIMUM_DOWNED_ANIMATION_SPEED)
82:         } else {
83:             physical
84:         })
85:     }
86: }
