129: pub fn locomotion_profile(
130:     state: &SkeletonState,
131:     speed: NonnegativeSpeed,
132: ) -> AnimationValueResult<LocomotionProfile> {
133:     match state.body() {
134:         BodyState::Prone => return Ok(prone_locomotion_profile()),
135:         BodyState::Supine => return Ok(supine_locomotion_profile()),
136:         _ => {}
137:     }
138:     if state.weapon_guard() == WeaponGuardState::Raised && !state.is_guarded_sprinting() {
139:         return Ok(LocomotionProfile {
140:             step_distance: guard_step_length()?,
141:             ..raised_guard_locomotion_profile()
142:         });
143:     }
144:     let walk = walk_locomotion_profile();
145:     let run_profile = run_locomotion_profile();

146:     let run = ((speed.metres_per_second() - walk.reference_speed.metres_per_second())
147:         / (run_profile.reference_speed.metres_per_second()
148:             - walk.reference_speed.metres_per_second()))
149:     .clamp(0.0, 1.0);
150:     Ok(LocomotionProfile {
151:         gait: if run >= 0.5 {
152:             LocomotionGait::Run
153:         } else {
154:             LocomotionGait::Walk
155:         },
156:         reference_speed: walk
157:             .reference_speed
158:             .checked_lerp(run_profile.reference_speed, run)?,
159:         step_distance: ordinary_step_distance(speed)?,
160:         support_phase_radius: walk
161:             .support_phase_radius
162:             .checked_lerp(run_profile.support_phase_radius, run)?,
163:         bounce_metres: walk
164:             .bounce_metres
165:             .scaled_by(UnitInterval::from_fraction(1.0 - run)?)?,
166:         flight_apex_metres: run_profile
167:             .flight_apex_metres
168:             .scaled_by(UnitInterval::from_fraction(run)?)?,
169:         landing: landing_profile(),
170:     })
171: }
172: 
173: /// Shared distance model through authored walk/run reference points. This
174: /// replaces duplicated cadence arithmetic without changing current timing.
175: pub fn ordinary_step_distance(speed: NonnegativeSpeed) -> AnimationValueResult<NonnegativeLength> {
176:     let speed = speed.metres_per_second().max(0.0);
177:     let walk = walk_locomotion_profile();
178:     let run = run_locomotion_profile();
179:     let distance = if speed <= walk.reference_speed.metres_per_second() {
180:         0.9_f32.lerp(
181:             walk.step_distance.metres(),
182:             speed / walk.reference_speed.metres_per_second(),
183:         )
184:     } else {
185:         let blend = ((speed - walk.reference_speed.metres_per_second())
186:             / (run.reference_speed.metres_per_second() - walk.reference_speed.metres_per_second()))
187:         .clamp(0.0, 1.0);
188:         walk.step_distance
189:             .metres()
190:             .lerp(run.step_distance.metres(), blend)
191:     };
192:     NonnegativeLength::from_arithmetic(distance)
193: }
194: 
195: pub fn gait_cycle_phase_delta(
196:     profile: LocomotionProfile,
197:     speed: NonnegativeSpeed,
198:     elapsed: AnimationElapsed,
199: ) -> AnimationValueResult<CycleDelta> {
200:     // Speed and elapsed seconds meet only in this physical cadence kernel.
201:     CycleDelta::from_arithmetic(
202:         speed.metres_per_second().max(0.0) * elapsed.seconds().max(0.0)
203:             / (profile.step_distance.metres().max(0.01) * 2.0),
204:     )
205: }
206: 
207: pub fn gait_support_weights(
208:     profile: LocomotionProfile,
209:     phase: CyclePhase,
210: ) -> AnimationValueResult<(UnitInterval, UnitInterval)> {
211:     if profile.gait == LocomotionGait::RaisedGuard {
212:         return Ok((UnitInterval::ONE, UnitInterval::ONE));
213:     }
214:     let phase = phase.cycles();
215:     let support = |contact: f32| {
216:         let distance = {
217:             let delta = (phase - contact).abs();
218:             delta.min(1.0 - delta)
219:         };
220:         (1.0 - smoothstep(
221:             profile.support_phase_radius.cycles() * 0.45,
222:             profile.support_phase_radius.cycles(),
223:             distance,
224:         ))
225:         .clamp(0.0, 1.0)
226:     };
227:     Ok((
228:         UnitInterval::from_fraction(support(0.0))?,
229:         UnitInterval::from_fraction(support(0.5))?,
230:     ))
231: }
232: 
233: fn smoothstep(edge0: f32, edge1: f32, value: f32) -> f32 {
234:     if edge1 <= edge0 {
235:         return f32::from(value >= edge1);
236:     }
237:     let t = ((value - edge0) / (edge1 - edge0)).clamp(0.0, 1.0);
238:     t * t * (3.0 - 2.0 * t)
239: }
240: 
241: fn landing_profile() -> LandingProfile {
242:     let config = crate::combat_config::runtime_animation_config()
243:         .locomotion
244:         .landing;
245:     LandingProfile {
246:         minimum_impact_speed_metres_per_second: config.minimum_impact_speed_metres_per_second,
247:         compression_per_metre_per_second: config.compression_per_metre_per_second,
248:         minimum_compression_metres: config.minimum_compression_metres,
249:         maximum_compression_metres: config.maximum_compression_metres,
250:         recovery_seconds: config.recovery_seconds.elapsed(),
251:     }
252: }
253: 
254: fn gait_profile(
255:     gait: LocomotionGait,
256:     config: crate::combat_config::AnimationGaitConfig,
257: ) -> LocomotionProfile {
258:     LocomotionProfile {
259:         gait,
260:         reference_speed: config.reference_speed_metres_per_second.nonnegative(),
261:         step_distance: config.step_distance_metres.into(),
262:         support_phase_radius: config.support_phase_radius,
263:         bounce_metres: config.bounce_metres,
264:         flight_apex_metres: config.flight_apex_metres,
265:         landing: landing_profile(),
266:     }
267: }

