33: #[derive(Debug, Clone, PartialEq, Eq)]
34: pub enum PackValidationError {
35:     Duplicate(AnimationPackId),
36:     MissingFallback {
37:         pack: AnimationPackId,
38:         fallback: AnimationPackId,
39:     },
40:     FallbackCycle(AnimationPackId),
41:     IncompatibleSkeleton {
42:         pack: AnimationPackId,
43:         fallback: AnimationPackId,
44:     },
45:     MissingRoot(AnimationPackId),
46:     RootHasFallback(AnimationPackId),
47:     MissingRequiredPose(SemanticPose),
48: }
49: 
50: impl AnimationPackLibrary {
51:     /// Resolves gameplay attack capabilities with pack-local override
52:     /// semantics. A pack that owns any attack owns the complete attack choice;
53:     /// its missing attacks stay unavailable. Only a pack with no attacks at
54:     /// all inherits the nearest parent's attack set.
55:     pub fn attack_animations(&self, root: &AnimationPackId) -> AttackAnimations {
56:         let mut pack_id = Some(root);
57:         let mut seen = HashSet::new();
58:         let mut main = None;
59:         let mut offhand = false;
60:         let mut offhand_preparation = false;
61:         while let Some(id) = pack_id {
62:             if !seen.insert(id) {
63:                 break;
64:             }
65:             let Some(pack) = self.packs.get(id) else {
66:                 break;
67:             };
68:             let attacks = AttackAnimations {
69:                 swing: pack.clips.contains(&SemanticPose::AttackSwing),
70:                 swing_continuation: pack.clips.contains(&SemanticPose::RecoverSwing)
71:                     && pack.clips.contains(&SemanticPose::ContinueSwing),
72:                 thrust: pack.clips.contains(&SemanticPose::AttackThrust),
73:                 thrust_continuation: pack.clips.contains(&SemanticPose::RecoverThrust)
74:                     && pack.clips.contains(&SemanticPose::ContinueThrust),
75:                 offhand: pack.clips.contains(&SemanticPose::AttackOffhand),
76:                 offhand_preparation: pack.clips.contains(&SemanticPose::AttackOffhandPrepared),
77:             };
78:             if main.is_none() && (attacks.swing || attacks.thrust) {
79:                 main = Some(attacks);
80:             }
81:             offhand |= attacks.offhand;
82:             offhand_preparation |= attacks.offhand && attacks.offhand_preparation;
83:             if main.is_some() && offhand {
84:                 break;
85:             }
86:             pack_id = pack.fallback.as_ref();
87:         }
88:         let mut attacks = main.unwrap_or(AttackAnimations::NONE);
89:         attacks.offhand = offhand;
90:         attacks.offhand_preparation = offhand_preparation;
91:         attacks
92:     }
93: 
94:     pub fn insert(&mut self, pack: AnimationPack) -> Result<(), PackValidationError> {
95:         if self.packs.contains_key(&pack.id) {
96:             return Err(PackValidationError::Duplicate(pack.id));
97:         }
98:         self.packs.insert(pack.id.clone(), pack);
99:         Ok(())
100:     }
101: 
102:     /// Validates references, cycles, and skeleton compatibility. Incomplete
103:     /// packs are accepted while art is in progress; call [`Self::validate_complete`]
104:     /// for release/content validation.
105:     pub fn validate_structure(&self) -> Result<(), PackValidationError> {
106:         for pack in self.packs.values() {
107:             let mut seen = HashSet::new();
108:             let mut current = pack;
109:             loop {
110:                 if !seen.insert(&current.id) {
111:                     return Err(PackValidationError::FallbackCycle(pack.id.clone()));
112:                 }
113:                 let Some(fallback_id) = current.fallback.as_ref() else {
114:                     break;
115:                 };
116:                 let Some(fallback) = self.packs.get(fallback_id) else {
117:                     return Err(PackValidationError::MissingFallback {
118:                         pack: current.id.clone(),
119:                         fallback: fallback_id.to_owned(),
120:                     });
121:                 };
122:                 if fallback.skeleton_family != pack.skeleton_family {
123:                     return Err(PackValidationError::IncompatibleSkeleton {
124:                         pack: current.id.clone(),
125:                         fallback: fallback.id.clone(),
126:                     });
127:                 }
128:                 current = fallback;
129:             }
130:         }

