45: impl ReferenceAcceleration {
46:     pub fn from_metres_per_second_squared(value: f32) -> AnimationValueResult<Self> {
47:         let value = checked_nonnegative(value, AnimationQuantity::ReferenceAcceleration)?;
48:         if value == 0.0 {
49:             return Err(AnimationValueError::NonPositive {
50:                 quantity: AnimationQuantity::ReferenceAcceleration,
51:             });
52:         }
53:         Ok(Self(value))
54:     }
55:     /// Native component/reference ratio inside the body-local acceleration kernel.
56:     pub fn component_ratio(self, acceleration: f32) -> f32 {
57:         acceleration / self.0
58:     }
59: }
