61: impl ResponseRate {
62:     pub fn from_per_second(value: f32) -> AnimationValueResult<Self> {
63:         checked_nonnegative(value, AnimationQuantity::ResponseRate).map(Self)
64:     }
65:     pub fn exponential_fraction(
66:         self,
67:         elapsed: AnimationElapsed,
68:     ) -> AnimationValueResult<UnitInterval> {
69:         let exponent = -self.0 * elapsed.seconds();
70:         // Finite nonnegative inputs can overflow the exponent to -infinity;
71:         // exp(-infinity) still gives the valid full-response limit.
72:         Ok(UnitInterval::from_fraction(1.0 - exponent.exp())?)
73:     }
74:     /// Linear per-step drain, capped at full response by the existing damping law.
75:     pub fn step_fraction(self, elapsed: AnimationElapsed) -> AnimationValueResult<UnitInterval> {
76:         Ok(UnitInterval::from_fraction(
77:             (self.0 * elapsed.seconds()).min(1.0),
78:         )?)
79:     }
80:     /// Native coefficient multiplying angular velocity in the PD muscle kernel.
81:     pub fn per_second(self) -> f32 {
82:         self.0
83:     }
84: }
