86: impl InertialLeanGain {
87:     pub fn from_gain(value: f32) -> AnimationValueResult<Self> {
88:         checked_nonnegative(value, AnimationQuantity::InertialLeanGain).map(Self)
89:     }
90:     pub fn interpolated(self, other: Self, fraction: UnitInterval) -> AnimationValueResult<Self> {
91:         // Same scalar order as glam's FloatExt::lerp, including subnormal results.
92:         Self::from_gain(self.0 + (other.0 - self.0) * fraction.fraction())
93:             .map_err(|error| error.for_quantity(AnimationQuantity::BodyAngle))
94:     }
95:     /// Native multiplier of a signed body angle, independent of additive pose weight.
96:     pub fn gain(self) -> f32 {
97:         self.0
98:     }
99: }
100: 
101: impl ImpactCompressionCompliance {
102:     pub fn from_metres_per_metres_per_second(value: f32) -> AnimationValueResult<Self> {
103:         checked_nonnegative(value, AnimationQuantity::ImpactCompressionCompliance).map(Self)
104:     }
105:     pub fn compression(
106:         self,
107:         impact: LandingImpactSpeed,
108:         minimum: HeightDistance,
109:         maximum: HeightDistance,
110:     ) -> AnimationValueResult<HeightDistance> {
111:         let compression = impact.metres_per_second() * self.0;
112:         if !compression.is_finite() {
113:             return Err(AnimationValueError::Overflow {
114:                 quantity: AnimationQuantity::HeightDistance,
115:             });
116:         }
117:         if minimum > maximum {
118:             return Err(AnimationValueError::InvertedBounds {
119:                 quantity: AnimationQuantity::HeightDistance,
120:             });
121:         }
122:         HeightDistance::from_arithmetic(compression.clamp(minimum.metres(), maximum.metres()))
123:     }
124: }
