1: //! Checked contribution weights and cyclic sample coordinates shared by evaluation.
2: 
3: use super::{
4:     AnimationQuantity, AnimationValueError, AnimationValueResult, LOCOMOTION_SECOND_CONTACT_PHASE,
5:     LeadFoot,
6: };
7: use serde::{Deserialize, Serialize};
8: 
9: /// Finite cycles, deliberately signed and unwrapped until a periodic operation.
10: #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, derive_more::Into)]
11: #[serde(try_from = "f32", into = "f32")]
12: pub struct CyclePhase(f32);
13: 
14: /// Finite signed cycle displacement; unlike a coordinate, it never wraps implicitly.
15: #[derive(Debug, Clone, Copy, PartialEq, PartialOrd, Serialize, Deserialize, derive_more::Into)]
16: #[serde(try_from = "f32", into = "f32")]
17: pub struct CycleDelta(f32);
18: 
19: /// A finite nonnegative contribution. Independent contributions may exceed one.
20: #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, derive_more::Into)]
21: #[serde(try_from = "f32", into = "f32")]
22: pub struct BlendWeight(f32);
23: 
24: /// Binary selection of the authored original or mirrored clip.
25: #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
26: #[serde(from = "bool", into = "bool")]
27: pub enum ClipMirror {
28:     Original,
29:     Mirrored,
30: }
31: 
32: impl CyclePhase {
33:     pub const ZERO: Self = Self(0.0);
34:     pub fn from_cycles(cycles: f32) -> AnimationValueResult<Self> {
35:         if !cycles.is_finite() {
36:             return Err(AnimationValueError::NonFinite {
37:                 quantity: AnimationQuantity::CyclePhase,
38:             });
39:         }
40:         Ok(Self(cycles))
41:     }
42:     /// Admit a native coordinate-kernel result before retaining a phase.
43:     pub fn from_arithmetic(cycles: f32) -> AnimationValueResult<Self> {
44:         if !cycles.is_finite() {
45:             return Err(AnimationValueError::Overflow {
46:                 quantity: AnimationQuantity::CyclePhase,
47:             });
48:         }
49:         Ok(Self(cycles))
50:     }
51:     pub fn cycles(self) -> f32 {
52:         self.0
53:     }
54:     pub fn wrapped(self) -> Self {
55:         Self(self.0.rem_euclid(1.0))
56:     }
57:     pub fn checked_advance(self, delta: CycleDelta) -> AnimationValueResult<Self> {
58:         let cycles = self.0 + delta.0;
59:         if !cycles.is_finite() {
60:             return Err(AnimationValueError::Overflow {
61:                 quantity: AnimationQuantity::CyclePhase,
62:             });
63:         }
64:         Ok(Self(cycles))
65:     }
66:     pub fn checked_difference(self, previous: Self) -> AnimationValueResult<CycleDelta> {
67:         CycleDelta::from_arithmetic(self.0 - previous.0)
68:     }
69:     /// Remaining cycles to the canonical bilateral contact, in the existing
70:     /// subtract-then-modulo order. Subtracting zero or half a cycle from a
71:     /// finite f32 cannot overflow, so this periodic kernel remains infallible.
72:     pub fn until_contact(self, foot: LeadFoot) -> CycleDelta {
73:         CycleDelta((Self::contact_cycles(foot) - self.0).rem_euclid(1.0))
74:     }
75:     /// Elapsed cycles after this foot's contact, retaining subtract-then-modulo order.
76:     pub fn since_contact(self, foot: LeadFoot) -> CycleDelta {
77:         CycleDelta((self.0 - Self::contact_cycles(foot)).rem_euclid(1.0))
78:     }
79:     /// Signed offset from the nearest contact for sagittal foot roll.
80:     /// The half-cycle shift remains after subtraction and before modulo.
81:     pub fn nearest_contact_offset(self, foot: LeadFoot) -> CycleDelta {
82:         CycleDelta((self.0 - Self::contact_cycles(foot) + 0.5).rem_euclid(1.0) - 0.5)
83:     }
84:     fn contact_cycles(foot: LeadFoot) -> f32 {
85:         match foot {
86:             LeadFoot::Left => 0.0,
87:             LeadFoot::Right => LOCOMOTION_SECOND_CONTACT_PHASE,
88:         }
89:     }
90: }
91: 
92: impl CycleDelta {
93:     /// A bounded cycle fraction widens losslessly to an unwrapped displacement.
94:     pub fn from_unit_cycles(value: super::UnitInterval) -> Self {
95:         Self(value.fraction())
96:     }
97:     /// Native interpolation of two cycle displacements, before retaining the result.
98:     pub fn checked_lerp(self, other: Self, fraction: f32) -> AnimationValueResult<Self> {
99:         use bevy::math::FloatExt;
100:         Self::from_arithmetic(self.0.lerp(other.0, fraction))
101:     }
102: 
103:     pub const ZERO: Self = Self(0.0);
104:     pub fn from_cycles(cycles: f32) -> AnimationValueResult<Self> {
105:         if !cycles.is_finite() {
106:             return Err(AnimationValueError::NonFinite {
107:                 quantity: AnimationQuantity::CycleDelta,
108:             });
109:         }
110:         Ok(Self(cycles))
111:     }
112:     /// Admit the result of a native cycle arithmetic kernel before retention.
113:     pub fn from_arithmetic(cycles: f32) -> AnimationValueResult<Self> {
114:         if !cycles.is_finite() {
115:             return Err(AnimationValueError::Overflow {
116:                 quantity: AnimationQuantity::CycleDelta,
117:             });
118:         }
119:         Ok(Self(cycles))
120:     }
121:     pub fn cycles(self) -> f32 {
122:         self.0
123:     }
124:     pub fn checked_add(self, other: Self) -> AnimationValueResult<Self> {
125:         Self::from_arithmetic(self.0 + other.0)

126:     }
127:     pub fn checked_sub(self, other: Self) -> AnimationValueResult<Self> {
128:         Self::from_arithmetic(self.0 - other.0)
129:     }
130: }
