132: impl BlendWeight {
133:     pub const ZERO: Self = Self(0.0);
134:     pub const ONE: Self = Self(1.0);
135:     pub fn from_factor(factor: f32) -> AnimationValueResult<Self> {
136:         if !factor.is_finite() {
137:             return Err(AnimationValueError::NonFinite {
138:                 quantity: AnimationQuantity::BlendWeight,
139:             });
140:         }
141:         if factor < 0.0 {
142:             return Err(AnimationValueError::Negative {
143:                 quantity: AnimationQuantity::BlendWeight,
144:             });
145:         }
146:         Ok(Self(factor))
147:     }
148:     pub fn checked_add(self, other: Self) -> AnimationValueResult<Self> {
149:         let factor = self.0 + other.0;
150:         if !factor.is_finite() {
151:             return Err(AnimationValueError::Overflow {
152:                 quantity: AnimationQuantity::BlendWeight,
153:             });
154:         }
155:         Ok(Self(factor))
156:     }
157:     /// Multiplies two admitted contributions without publishing an overflow.
158:     pub fn checked_scale(self, scale: Self) -> AnimationValueResult<Self> {
159:         let factor = self.0 * scale.0;
160:         if !factor.is_finite() {
161:             return Err(AnimationValueError::Overflow {
162:                 quantity: AnimationQuantity::BlendWeight,
163:             });
164:         }
165:         Ok(Self(factor))
166:     }
167:     pub fn factor(self) -> f32 {
168:         self.0
169:     }
170:     /// There is no authored minimum contribution: every positive factor counts.
171:     pub fn is_absent(self) -> bool {
172:         self.0 <= 0.0
173:     }
174: }
