124: /// Server-authored planar contact positions for raised-guard footwork. Values
125: /// are stored in the controller's local X/Z frame and advected against body
126: /// motion, so a planted virtual foot remains fixed while the root travels.
127: #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
128: pub struct GuardContacts {
129:     left: Vec2,
130:     right: Vec2,
131: }
132: 
133: impl GuardContacts {
134:     pub fn left(self) -> Vec2 {
135:         self.left
136:     }
137: 
138:     pub fn right(self) -> Vec2 {
139:         self.right
140:     }
141: 
142:     fn advected(self, local_displacement: Vec2) -> Self {
143:         Self {
144:             left: self.left - local_displacement,
145:             right: self.right - local_displacement,
146:         }
147:     }
148: 
149:     fn with_contact(self, foot: LeadFoot, position: Vec2) -> Self {
150:         match foot {
151:             LeadFoot::Left => Self {
152:                 left: position,
153:                 ..self
154:             },
155:             LeadFoot::Right => Self {
156:                 right: position,
157:                 ..self
158:             },
159:         }
160:     }
161: 
162:     fn normalized(self) -> Self {
163:         let finite = |value: Vec2, fallback: Vec2| {
164:             if value.is_finite() { value } else { fallback }
165:         };
166:         Self {
167:             left: finite(
168:                 self.left,
169:                 Vec2::new(-guard_footwork_config().default_half_width_metres, 0.0),
170:             ),
171:             right: finite(
172:                 self.right,
173:                 Vec2::new(guard_footwork_config().default_half_width_metres, 0.0),
174:             ),
175:         }
176:     }
177: }
178: 
179: impl Default for GuardContacts {
180:     fn default() -> Self {

181:         Self {
182:             left: Vec2::new(-guard_footwork_config().default_half_width_metres, 0.0),
183:             right: Vec2::new(guard_footwork_config().default_half_width_metres, 0.0),
184:         }
185:     }
186: }
