188: /// One complete, authoritative raised-guard swing. Contact timing and landing
189: /// placement are a single plan; presentation may interpolate within it but may
190: /// not postpone its contact tick.
191: #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
192: pub struct GuardStepPlan {
193:     contacts: GuardContacts,
194:     swing_foot: LeadFoot,
195:     swing_start: Vec2,
196:     landing: Vec2,
197:     start_tick: AnimationSampleTick,
198:     contact_tick: AnimationSampleTick,
199: }
200: 
201: impl GuardStepPlan {
202:     pub fn contacts(self) -> GuardContacts {
203:         self.contacts
204:     }
205: 
206:     pub fn swing_foot(self) -> LeadFoot {
207:         self.swing_foot
208:     }
209: 
210:     pub fn swing_start(self) -> Vec2 {
211:         self.swing_start
212:     }
213: 
214:     pub fn landing(self) -> Vec2 {
215:         self.landing
216:     }
217: 
218:     pub fn start_tick(self) -> AnimationSampleTick {
219:         self.start_tick
220:     }
221: 
222:     pub fn contact_tick(self) -> AnimationSampleTick {
223:         self.contact_tick
224:     }
225: 
226:     pub fn progress(self, tick: AnimationSampleTick) -> f32 {
227:         let duration = self
228:             .contact_tick
229:             .saturating_sub(self.start_tick)
230:             .max(AnimationSampleSpan::ONE);
231:         tick.saturating_sub(self.start_tick).samples() as f32 / duration.samples() as f32
232:     }
233: 
234:     pub fn direction(self) -> Vec2 {
235:         (self.landing - self.swing_start).normalize_or_zero()
236:     }
237: 
238:     fn advected(mut self, local_displacement: Vec2) -> Self {
239:         self.contacts = self.contacts.advected(local_displacement);
240:         self.swing_start -= local_displacement;
241:         self.landing -= local_displacement;
242:         self
243:     }
244: 
245:     fn normalized(mut self) -> Self {
246:         self.contacts = self.contacts.normalized();
247:         if !self.swing_start.is_finite() {
248:             self.swing_start = match self.swing_foot {
249:                 LeadFoot::Left => self.contacts.left,
250:                 LeadFoot::Right => self.contacts.right,
251:             };
252:         }
253:         if !self.landing.is_finite() {
254:             self.landing = self.swing_start;
255:         }
256:         self.contact_tick = self
257:             .contact_tick
258:             .max(self.start_tick.saturating_add(AnimationSampleSpan::ONE));
259:         self
260:     }
261: }
