293:     pub fn next_swing(self) -> Option<LeadFoot> {
294:         match self {
295:             Self::Planted { next_swing, .. } => Some(next_swing),
296:             Self::Stepping(step) => Some(opposite_foot(step.swing_foot)),
297:             Self::Uninitialized => None,
298:         }
299:     }
