301:     fn normalized(self) -> Self {
302:         match self {
303:             Self::Uninitialized => Self::Uninitialized,
304:             Self::Planted {
305:                 contacts,
306:                 next_swing,
307:             } => Self::Planted {
308:                 contacts: contacts.normalized(),
309:                 next_swing,
310:             },
311:             Self::Stepping(step) => Self::Stepping(step.normalized()),
