655:     /// and low-skill attacks telegraph and follow through more.
656:     pub fn from_handling(moment_of_inertia_kg_m2: f32, skill: f32) -> Self {
657:         Self::from_handling_with_config(
658:             moment_of_inertia_kg_m2,
659:             skill,
660:             &crate::combat_config::TacticalCombatConfig::default()
661:                 .presentation
662:                 .attack_curve,
663:         )
664:     }
665: 
666:     pub fn from_handling_with_config(
667:         moment_of_inertia_kg_m2: f32,
668:         skill: f32,
669:         config: &crate::combat_config::AttackCurveConfig,
670:     ) -> Self {
671:         let inertia = if moment_of_inertia_kg_m2.is_finite() {
672:             moment_of_inertia_kg_m2.max(0.0)
673:         } else {
674:             0.3
675:         };
676:         let inertia_difficulty = (inertia / (inertia + config.inertia_characteristic)).sqrt();
677:         let skill = finite_clamp(skill / 5.0, 0.0, 1.0, 0.0);
678:         let lack_of_control =
679:             inertia_difficulty * config.inertia_weight + (1.0 - skill) * config.skill_weight;
680:         Self {
681:             tell_fraction: config.tell_base + config.tell_span * lack_of_control,
682:             drawback: config.drawback_base + config.drawback_span * lack_of_control,
683:             follow_through_fraction: config.follow_through_base
684:                 + config.follow_through_span * lack_of_control,
685:             overshoot: config.overshoot_base + config.overshoot_span * lack_of_control,
686:         }
687:         .normalized_with_limits(config.maximum_drawback, config.maximum_overshoot)
688:     }
689: 
690:     fn normalized(self) -> Self {
691:         self.normalized_with_limits(Self::maximum_drawback(), Self::maximum_overshoot())
692:     }
693: 
694:     fn normalized_with_limits(mut self, maximum_drawback: f32, maximum_overshoot: f32) -> Self {
695:         self.tell_fraction = finite_clamp(self.tell_fraction, 0.15, 0.75, 0.45);
696:         self.drawback = finite_clamp(self.drawback, 0.0, maximum_drawback, 0.3);
697:         self.follow_through_fraction = finite_clamp(self.follow_through_fraction, 0.1, 0.65, 0.3);
698:         self.overshoot = finite_clamp(self.overshoot, 0.0, maximum_overshoot, 0.2);
699:         self
700:     }
701: 
702:     /// Unclamped semantic pose coordinate at a normalized action phase where
703:     /// contact remains exactly 0.5.
704:     pub fn coordinate(self, phase: UnitInterval) -> AnimationValueResult<AttackPoseCoordinate> {
705:         let phase = phase.fraction();
706:         let tell_end = self.tell_fraction * 0.5;
707:         let follow_through_end = 0.5 + self.follow_through_fraction * 0.5;
708:         let [
709:             tell_acceleration,
710:             contact_acceleration,
711:             follow_through_acceleration,
712:         ] = self.knot_accelerations();
713:         let coordinate = if phase <= tell_end {
714:             quintic_hermite(
715:                 0.0,
716:                 -self.drawback,
717:                 0.0,
718:                 0.0,
719:                 0.0,
720:                 tell_acceleration * tell_end * tell_end,

721:                 phase / tell_end,
722:             )
723:         } else if phase <= 0.5 {
724:             let duration = 0.5 - tell_end;
725:             quintic_hermite(
726:                 -self.drawback,
727:                 1.0,
728:                 0.0,
729:                 self.contact_velocity() * duration,
730:                 tell_acceleration * duration * duration,
731:                 contact_acceleration * duration * duration,
732:                 (phase - tell_end) / duration,
733:             )
734:         } else if phase <= follow_through_end {
735:             let duration = follow_through_end - 0.5;
736:             quintic_hermite(
737:                 1.0,
738:                 1.0 + self.overshoot,
739:                 self.contact_velocity() * duration,
740:                 self.overshoot,
741:                 contact_acceleration * duration * duration,
742:                 follow_through_acceleration * duration * duration,
743:                 (phase - 0.5) / duration,
744:             )
745:         } else {
746:             let duration = 1.0 - follow_through_end;
747:             let incoming_velocity = self.overshoot / (follow_through_end - 0.5);
748:             quintic_hermite(
749:                 1.0 + self.overshoot,
750:                 0.0,
751:                 incoming_velocity * duration,
752:                 0.0,
753:                 follow_through_acceleration * duration * duration,
754:                 0.0,
755:                 (phase - follow_through_end) / duration,
756:             )
757:         };
758:         AttackPoseCoordinate::from_arithmetic(coordinate)
759:     }
760: 
761:     /// A queued continuation consumes the complete post-contact backswing.
762:     /// It reaches the furthest frame-0-to-frame-4 extrapolation with a live
763:     /// tangent so the follow-up preparation can inherit its momentum.
764:     pub fn queued_recovery_coordinate(
765:         self,
766:         phase: UnitInterval,
767:     ) -> AnimationValueResult<AttackPoseCoordinate> {
768:         let progress = phase;
769:         let phase = progress.fraction();
770:         let follow_through_end = 0.5 + self.follow_through_fraction * 0.5;
771:         let coordinate = if phase <= 0.5 {
772:             return self.coordinate(progress);
773:         } else if phase <= follow_through_end {
774:             let duration = follow_through_end - 0.5;
775:             let contact_acceleration = self.knot_accelerations()[1];
776:             quintic_hermite(
777:                 1.0,
778:                 1.0 + self.overshoot,
779:                 self.contact_velocity() * duration,
780:                 self.overshoot,
781:                 contact_acceleration * duration * duration,
782:                 0.0,
783:                 (phase - 0.5) / duration,
784:             )
785:         } else {
786:             let duration = follow_through_end - 0.5;
787:             let coordinate =
788:                 1.0 + self.overshoot + (phase - follow_through_end) * self.overshoot / duration;
789:             coordinate.min(1.0 + Self::maximum_overshoot())
790:         };
791:         AttackPoseCoordinate::from_arithmetic(coordinate)
792:     }
793: 
794:     fn queued_transition_phase(self) -> f32 {
795:         0.5 + self.follow_through_fraction * 0.5
796:     }
797: 
798:     /// Phase-coordinate speed shared by the strike and follow-through at
799:     /// contact. Bounding it by both neighboring secants keeps each quintic
800:     /// segment monotone while preventing the old stop-and-restart seam.
801:     fn contact_velocity(self) -> f32 {
802:         if self.overshoot <= 0.0 {
803:             return 0.0;
804:         }
805:         let strike_duration = 0.5 * (1.0 - self.tell_fraction);
806:         let follow_through_duration = 0.5 * self.follow_through_fraction;
807:         let strike_secant = (1.0 + self.drawback) / strike_duration;
808:         let follow_through_secant = self.overshoot / follow_through_duration;
809:         2.0 * strike_secant.min(follow_through_secant)
810:     }
811: 
812:     fn knot_accelerations(self) -> [f32; 3] {
813:         let tell_duration = self.tell_fraction * 0.5;
814:         let strike_duration = 0.5 - tell_duration;
815:         let follow_through_duration = self.follow_through_fraction * 0.5;
816:         let recovery_duration = 0.5 - follow_through_duration;
817:         let tell_secant = -self.drawback / tell_duration;
818:         let strike_secant = (1.0 + self.drawback) / strike_duration;
819:         let follow_through_secant = self.overshoot / follow_through_duration;
820:         let recovery_secant = -(1.0 + self.overshoot) / recovery_duration;
821:         [
822:             centered_knot_acceleration(tell_secant, strike_secant, tell_duration, strike_duration),
823:             centered_knot_acceleration(
824:                 strike_secant,
825:                 follow_through_secant,
826:                 strike_duration,
827:                 follow_through_duration,
828:             ),
829:             centered_knot_acceleration(
830:                 follow_through_secant,
831:                 recovery_secant,
832:                 follow_through_duration,
833:                 recovery_duration,
834:             ),
835:         ]
836:     }
837: }
838: 
839: fn finite_clamp(value: f32, minimum: f32, maximum: f32, fallback: f32) -> f32 {
840:     if value.is_finite() {
841:         value.clamp(minimum, maximum)
842:     } else {
843:         fallback
844:     }
845: }
846: 
847: fn smoothstep(value: f32) -> f32 {
848:     let value = value.clamp(0.0, 1.0);
849:     value * value * (3.0 - 2.0 * value)
850: }
851: 
852: fn centered_knot_acceleration(
853:     incoming_secant: f32,
854:     outgoing_secant: f32,
855:     incoming_duration: f32,
856:     outgoing_duration: f32,
857: ) -> f32 {
858:     2.0 * (outgoing_secant - incoming_secant) / (incoming_duration + outgoing_duration)
859: }
860: 
861: /// Quintic Hermite interpolation with explicit endpoint velocity and
862: /// acceleration. Derivatives are expressed in normalized-segment coordinates.
863: fn quintic_hermite(
864:     start: f32,
865:     end: f32,
866:     start_velocity: f32,
867:     end_velocity: f32,
868:     start_acceleration: f32,
869:     end_acceleration: f32,
870:     progress: f32,
871: ) -> f32 {
872:     let t = progress.clamp(0.0, 1.0);
873:     let t2 = t * t;
874:     let t3 = t2 * t;
875:     let t4 = t3 * t;
876:     let t5 = t4 * t;
877:     let start_position_basis = 1.0 - 10.0 * t3 + 15.0 * t4 - 6.0 * t5;
878:     let start_velocity_basis = t - 6.0 * t3 + 8.0 * t4 - 3.0 * t5;
879:     let start_acceleration_basis = 0.5 * (t2 - 3.0 * t3 + 3.0 * t4 - t5);
880:     let end_position_basis = 10.0 * t3 - 15.0 * t4 + 6.0 * t5;
881:     let end_velocity_basis = -4.0 * t3 + 7.0 * t4 - 3.0 * t5;
882:     let end_acceleration_basis = 0.5 * (t3 - 2.0 * t4 + t5);
883:     start * start_position_basis
884:         + start_velocity * start_velocity_basis
885:         + start_acceleration * start_acceleration_basis
886:         + end * end_position_basis
887:         + end_velocity * end_velocity_basis
888:         + end_acceleration * end_acceleration_basis
889: }
