1458:     pub fn begin_posture_transition(
1459:         &mut self,
1460:         kind: PostureTransitionKind,
1461:         start_tick: AnimationSampleTick,
1462:         duration_ticks: AnimationSampleSpan,
1463:     ) -> bool {
1464:         if self.posture_transition.is_some() || !kind.accepts(self.body) {
1465:             return false;
1466:         }
