1468:         self.raised_footwork = GuardFootworkPlan::default();
1469:         self.jump_anticipation = JumpAnticipation::Inactive;
1470:         self.guarded_sprint_locomotion = GuardedLocomotionMode::Footwork;
1471:         self.action = ActionState::default();
1472:         self.downed_facing = None;
1473:         self.downed_turning = DownedMotion::Resting;
1474:         self.posture_transition = Some(PostureTransitionState::new(
1475:             kind,
1476:             start_tick,
1477:             duration_ticks,
1478:         ));
