1481:     pub fn advance_posture_transition(
1482:         &mut self,
1483:         current_tick: AnimationSampleTick,
1484:     ) -> AnimationValueResult<()> {
1485:         let Some(mut transition) = self.posture_transition else {
1486:             return Ok(());
1487:         };
1488:         let elapsed = current_tick.saturating_sub(transition.start_tick);
1489:         if matches!(
1490:             transition.kind,
1491:             PostureTransitionKind::DiveToDowned {
1492:                 trajectory: DiveTrajectory::GroundedSlide,
1493:                 ..
1494:             }
1495:         ) {
1496:             if elapsed >= transition.duration_ticks {
1497:                 self.finish_posture_transition(transition.kind);
1498:                 return Ok(());
1499:             }
1500:             transition.phase = UnitInterval::from_fraction(
1501:                 elapsed.samples() as f32 / transition.duration_ticks.samples() as f32,
1502:             )?;
1503:             self.posture_transition = Some(transition);
1504:             return Ok(());
1505:         }
1506:         if matches!(transition.kind, PostureTransitionKind::DiveToDowned { .. }) {
1507:             if !self.body.is_surface_supported() {
1508:                 transition.dive_was_airborne = true;
1509:                 transition.phase = UnitInterval::HALF;
1510:                 self.posture_transition = Some(transition);
1511:                 return Ok(());
1512:             }
1513:             if transition.dive_was_airborne {
1514:                 let landing_tick = *transition.dive_landing_tick.get_or_insert(current_tick);
1515:                 let recovery_elapsed = current_tick.saturating_sub(landing_tick);
1516:                 if recovery_elapsed >= transition.duration_ticks {
1517:                     self.finish_posture_transition(transition.kind);
1518:                     return Ok(());
1519:                 }
1520:                 transition.phase = UnitInterval::from_fraction(
1521:                     0.5 + 0.5 * recovery_elapsed.samples() as f32
1522:                         / transition.duration_ticks.samples() as f32,
1523:                 )?;
1524:                 self.posture_transition = Some(transition);
1525:                 return Ok(());
1526:             }
1527:             if elapsed >= transition.duration_ticks {
1528:                 // A delayed or missed unsupported-controller sample must not
1529:                 // skip directly from the loading half to the final contact
1530:                 // pose. Enter the same bounded recovery used after a detected
1531:                 // landing so pose and facing remain continuous.
1532:                 transition.dive_was_airborne = true;
1533:                 transition.dive_landing_tick = Some(current_tick);
1534:                 transition.phase = UnitInterval::HALF;
1535:                 self.posture_transition = Some(transition);
1536:                 return Ok(());
1537:             }
1538:             transition.phase = UnitInterval::from_fraction(
1539:                 0.5 * elapsed.samples() as f32 / transition.duration_ticks.samples() as f32,
1540:             )?;
1541:             self.posture_transition = Some(transition);
1542:             return Ok(());
1543:         }
1544:         if elapsed >= transition.duration_ticks {
1545:             self.posture_transition = None;
1546:             self.transition_body(transition.kind.target());
1547:             return Ok(());
1548:         }
1549:         transition.phase = UnitInterval::from_fraction(
1550:             elapsed.samples() as f32 / transition.duration_ticks.samples() as f32,
1551:         )?;
1552:         self.posture_transition = Some(transition);
1553:         Ok(())
1554:     }
1555:     fn finish_posture_transition(&mut self, kind: PostureTransitionKind) {
1556:         self.posture_transition = None;
1557:         self.transition_body(kind.target());
1558:         // A lateral dive's recovery already ends at the matching authored
1559:         // side-supported roll pose. Seed the continuous roll coordinate at
1560:         // that exact midpoint so camera-following can continue from it rather
1561:         // than briefly returning through prone idle. Without held aim, the
1562:         // ordinary downed-facing update settles this midpoint back to prone.
1563:         self.downed_facing = match kind {
1564:             PostureTransitionKind::DiveToDowned {
1565:                 direction: DiveDirection::Left,
1566:                 ..
1567:             } => Some(DownedFacingState::landed(DownedFacingPose::RollLeft)),
1568:             PostureTransitionKind::DiveToDowned {
1569:                 direction: DiveDirection::Right,
1570:                 ..
1571:             } => Some(DownedFacingState::landed(DownedFacingPose::RollRight)),
1572:             _ => None,
1573:         };
1574:     }
