1757:     /// Tick where a queued attack may enter its authored follow-up
1758:     /// preparation, after the current attack reaches full follow-through but
1759:     /// before its ordinary return-to-guard recovery would begin.
1760:     pub fn attack_continuation_tick(&self) -> Option<AnimationSampleTick> {
1761:         match self.action {
1762:             ActionState(ActionKind::Attack {
1763:                 curve,
1764:                 timeline,
1765:                 sequence: AttackSequence::Initial,
1766:                 ..
1767:             }) => {
1768:                 let recovery_progress =
1769:                     ((curve.queued_transition_phase() - 0.5) * 2.0).clamp(0.0, 1.0);
1770:                 let follow_through_ticks = (timeline.recovery_ticks.samples() as f64
1771:                     * recovery_progress as f64)
1772:                     .ceil() as u64;
1773:                 Some(
1774:                     timeline
1775:                         .contact_tick()
1776:                         .saturating_add(AnimationSampleSpan::from(follow_through_ticks)),
1777:                 )
1778:             }
1779:             _ => None,
1780:         }
1781:     }
