1854:     /// Starts an attack with independently authored preparation and recovery.
1855:     /// Contact remains semantic phase 0.5 for presentation and gameplay.
1856:     pub fn begin_attack_timed(
1857:         &mut self,
1858:         spec: AttackSpec,
1859:         start_tick: AnimationSampleTick,
1860:         contact_tick: AnimationSampleTick,
1861:         end_tick: AnimationSampleTick,
1862:     ) -> Result<(), ActionTransitionError> {
1863:         self.action_admission()?;
1864:         let target_height = if spec.target_height.is_finite() {
1865:             spec.target_height.clamp(0.0, 1.0)
1866:         } else {
1867:             AttackSpec::default().target_height
1868:         };
1869:         if let ActionState(ActionKind::Attack {
1870:             animation,
1871:             hand: AttackHand::Main,
1872:             sequence: AttackSequence::Initial,
1873:             curve,
1874:             timeline,
1875:             queued,
1876:             ..
1877:         }) = &mut self.action
1878:         {
1879:             let recovery_progress = curve.follow_through_fraction.clamp(0.0, 1.0);
1880:             let transition_tick =
1881:                 timeline
1882:                     .contact_tick()
1883:                     .saturating_add(AnimationSampleSpan::from(
1884:                         (timeline.recovery_ticks.samples() as f64 * recovery_progress as f64).ceil()
1885:                             as u64,
1886:                     ));
1887:             let may_follow = queued.is_none()
1888:                 && spec.hand == AttackHand::Main
1889:                 && spec.continuation
1890:                 && spec.animation == *animation
1891:                 && start_tick >= transition_tick;
1892:             if may_follow {
1893:                 let queued_timeline =
1894:                     ActionTimeline::with_recovery(start_tick, contact_tick, end_tick);
1895:                 // Coordinate change from the two timeline intervals and the
1896:                 // authored readiness knot; preserve the original f32 order.
1897:                 let incoming_tangent = IncomingAttackTangent::from_arithmetic(
1898:                     curve.overshoot
1899:                         * queued_timeline.preparation_ticks.samples() as f32
1900:                         * ContinuationReadiness::FOLLOW_READY.preparation_fraction()
1901:                         / (curve.follow_through_fraction
1902:                             * timeline.recovery_ticks.samples() as f32),
1903:                 )
1904:                 .map_err(ActionTransitionError::InvalidAnimationValue)?;
1905:                 let transition_phase = 0.5
1906:                     + 0.5
1907:                         * transition_tick
1908:                             .saturating_sub(timeline.contact_tick())
1909:                             .samples() as f32
1910:                         / timeline
1911:                             .recovery_ticks
1912:                             .max(AnimationSampleSpan::ONE)
1913:                             .samples() as f32;
1914:                 *queued = Some(QueuedAttack {
1915:                     target_height,
1916:                     animation: spec.animation,
1917:                     strike_family: spec.strike_family,
1918:                     hand: spec.hand,
1919:                     curve: spec.curve.normalized(),
1920:                     timeline: queued_timeline,
1921:                     start_coordinate: curve
1922:                         .queued_recovery_coordinate(
1923:                             UnitInterval::from_fraction(transition_phase).map_err(|error| {
1924:                                 ActionTransitionError::InvalidAnimationValue(error.into())
1925:                             })?,
1926:                         )
1927:                         .map_err(ActionTransitionError::InvalidAnimationValue)?,
1928:                     incoming_tangent,
1929:                 });
1930:                 return Ok(());
1931:             }
1932:         }
1933:         if self.action_kind() != SkeletonAction::None {
1934:             return Err(ActionTransitionError::ActionBusy);
1935:         }
1936:         self.action = ActionState(ActionKind::Attack {
1937:             target_height,
1938:             animation: spec.animation,
1939:             strike_family: spec.strike_family,
1940:             hand: spec.hand,
1941:             sequence: if spec.continuation {
1942:                 AttackSequence::Continuation {
1943:                     start_coordinate: AttackPoseCoordinate::from_arithmetic(
1944:                         1.0 + spec.curve.overshoot,
1945:                     )
1946:                     .map_err(ActionTransitionError::InvalidAnimationValue)?,
1947:                     incoming_tangent: IncomingAttackTangent::ZERO,
1948:                 }
1949:             } else {
1950:                 AttackSequence::Initial
1951:             },
1952:             curve: spec.curve.normalized(),
1953:             timeline: ActionTimeline::with_recovery(start_tick, contact_tick, end_tick),
1954:             queued: None,
1955:         });
1956:         Ok(())
1957:     }
