1976:     /// Advances independently timed preparation, contact, and recovery.
1977:     pub fn advance_action(
1978:         &mut self,
1979:         current_tick: AnimationSampleTick,
1980:     ) -> AnimationValueResult<()> {

1981:         let mut action = self.action;
1982:         let queued = match action {
1983:             ActionState(ActionKind::Attack {
1984:                 curve,
1985:                 timeline,
1986:                 queued: Some(queued),
1987:                 ..
1988:             }) if current_tick
1989:                 >= timeline
1990:                     .contact_tick()
1991:                     .saturating_add(AnimationSampleSpan::from(
1992:                         (timeline.recovery_ticks.samples() as f64
1993:                             * curve.follow_through_fraction as f64)
1994:                             .ceil() as u64,
1995:                     )) =>
1996:             {
1997:                 Some(queued)
1998:             }
1999:             _ => None,
2000:         };
2001:         if let Some(queued) = queued {
2002:             action = ActionState(ActionKind::Attack {
2003:                 target_height: queued.target_height,
2004:                 animation: queued.animation,
2005:                 strike_family: queued.strike_family,
2006:                 hand: queued.hand,
