2010:                 },
2011:                 curve: queued.curve,
2012:                 timeline: queued.timeline,
2013:                 queued: None,
2014:             });
2015:         }
2016:         let timeline = match &mut action {
2017:             ActionState(ActionKind::Idle) => return Ok(()),
2018:             ActionState(ActionKind::Dodge { timeline, .. })
2019:             | ActionState(ActionKind::Attack { timeline, .. })
2020:             | ActionState(ActionKind::Block { timeline, .. }) => timeline,
2021:         };
2022:         match timeline.sample(current_tick)? {
2023:             ActionTimelineSample::Complete => action = ActionState::default(),
2024:             ActionTimelineSample::Active(phase) => timeline.phase = phase,
2025:         }
2026:         self.action = action;
