2030: 
2031: fn advance_contact_identity(
2032:     skeleton: &mut SkeletonState,
2033:     handoffs: u32,
2034:     first_contact: Option<LeadFoot>,
2035: ) {
2036:     for handoff in 0..handoffs {
2037:         skeleton.contact_sequence = skeleton.contact_sequence.next();
2038:         skeleton.contact_foot = if handoff == 0 {
2039:             first_contact.unwrap_or_else(|| opposite_foot(skeleton.contact_foot))
2040:         } else {
2041:             opposite_foot(skeleton.contact_foot)
2042:         };
2043:     }
2044: }
2045: 
2046: pub(super) fn opposite_foot(foot: LeadFoot) -> LeadFoot {
2047:     match foot {
2048:         LeadFoot::Left => LeadFoot::Right,
2049:         LeadFoot::Right => LeadFoot::Left,
2050:     }
2051: }
2052: 
2053: /// Anatomical foot leading a close-guard shuffle in local controller space.
2054: /// Forward local velocity is -Y; backward therefore swaps the authored lead.
2055: /// A predominantly lateral shuffle uses the foot on the movement side.
2056: pub fn guard_movement_front_foot(lead: LeadFoot, local_direction: Vec2) -> LeadFoot {
2057:     let direction = local_direction.normalize_or_zero();
2058:     if direction == Vec2::ZERO || direction.y.abs() >= direction.x.abs() {
2059:         if direction.y > 0.0 {
2060:             opposite_foot(lead)
2061:         } else {
2062:             lead
2063:         }
2064:     } else if direction.x < 0.0 {
2065:         LeadFoot::Left
2066:     } else {
2067:         LeadFoot::Right
2068:     }
2069: }

