1: //! Continuous downed-roll coordinates, contact-sector policy and camera admission.
2: 
3: use super::turn_deadline::body_yaw;
4: use super::*;
5: 
6: /// Finite signed, unwrapped half turns around the downed body's longitudinal axis.
7: #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, derive_more::Into)]
8: #[serde(try_from = "f32", into = "f32")]
9: pub struct SignedHalfTurns(f32);
10: 
11: /// Finite nonnegative maximum half-turn travel for one camera observation.
12: #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, derive_more::Into)]
13: #[serde(try_from = "f32", into = "f32")]
14: pub struct DownedFacingStep(f32);
15: 
16: /// Signed roll command in [-1,1], distinct from metres/second and cycle phase.
17: #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, derive_more::Into)]
18: #[serde(try_from = "f32", into = "f32")]
19: pub struct DownedRollMotion(f32);
