28: /// Camera-driven roll around a downed character's head-to-feet axis. The
29: /// target is one of four sticky sectors; `half_turns` is the transient
30: /// interpolation coordinate. Values remain unwrapped so crossing the rear
31: /// camera seam does not reverse an in-progress roll.
32: #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
33: #[serde(from = "DownedFacingWire")]
34: pub struct DownedFacingState {
