37:     lateral_motion: DownedRollMotion,
38: }
39: 
40: /// Whether camera aim is holding a sector or releasing to stable contact.
41: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
42: pub enum DownedFacingAim {
43:     Held,
44:     Released,
45: }
46: 
47: /// Discrete camera-facing pose selected while a character is downed.
48: /// Interpolation occurs only while moving between these four sector centers.
49: #[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
50: pub enum DownedFacingPose {
51:     #[default]
52:     Prone,
53:     RollRight,
54:     Supine,
55:     RollLeft,
56: }
