58: impl SignedHalfTurns {
59:     pub const ZERO: Self = Self(0.0);
60:     pub fn from_half_turns(value: f32) -> AnimationValueResult<Self> {
61:         if !value.is_finite() {
62:             return Err(AnimationValueError::NonFinite {
63:                 quantity: AnimationQuantity::DownedFacing,
64:             });
65:         }
66:         Ok(Self(value))
67:     }
68:     /// Project only at the roll's lattice/interpolation, scalar fixture or wire math.
69:     pub fn half_turns(self) -> f32 {
70:         self.0
71:     }
72: }
