74: impl DownedFacingStep {
75:     pub const ZERO: Self = Self(0.0);
76:     pub const SETTLE_CONTACT: Self = Self(1.0);
77:     pub fn from_half_turns(value: f32) -> AnimationValueResult<Self> {
78:         super::super::measurement::checked_nonnegative(value, AnimationQuantity::DownedFacingStep)
79:             .map(Self)
80:     }
81:     /// Camera timestep production preserves the prior no-motion sanitation for
82:     /// a nonfinite computed step; the checked scalar constructor never repairs it.
83:     pub fn for_frame(elapsed: AnimationElapsed, full_turn: PositiveAnimationDuration) -> Self {
84:         let step = elapsed.seconds() / full_turn.seconds();
85:         Self(if step.is_finite() { step.max(0.0) } else { 0.0 })
86:     }
87:     fn half_turns(self) -> f32 {
