89:     }
90: }
91: 
92: impl DownedRollMotion {
93:     pub const REST: Self = Self(0.0);
94:     pub const LEFT: Self = Self(-1.0);
95:     pub const RIGHT: Self = Self(1.0);
96:     pub fn from_fraction(value: f32) -> AnimationValueResult<Self> {
97:         let quantity = AnimationQuantity::DownedRollMotion;
98:         if !value.is_finite() {
99:             return Err(AnimationValueError::NonFinite { quantity });
100:         }
101:         if !(-1.0..=1.0).contains(&value) {
102:             return Err(AnimationValueError::OutsideSignedUnitInterval { quantity });
103:         }
104:         Ok(Self(value))
105:     }
106:     /// Native controller speed multiplication or movement-vector component.
107:     pub fn fraction(self) -> f32 {
108:         self.0
109:     }
110:     pub fn is_moving(self) -> bool {
