130:             }),
131:             target: wire.target,
132:             lateral_motion: DownedRollMotion(if wire.lateral_motion.is_finite() {
133:                 wire.lateral_motion.clamp(-1.0, 1.0)
134:             } else {
135:                 0.0
136:             }),
137:         }
138:     }
139: }
