141: impl TryFrom<f32> for SignedHalfTurns {
142:     type Error = AnimationValueError;
143:     fn try_from(value: f32) -> AnimationValueResult<Self> {
144:         Self::from_half_turns(value)
145:     }
146: }
147: impl TryFrom<f32> for DownedFacingStep {
148:     type Error = AnimationValueError;
149:     fn try_from(value: f32) -> AnimationValueResult<Self> {
150:         Self::from_half_turns(value)
151:     }
152: }
153: impl TryFrom<f32> for DownedRollMotion {
154:     type Error = AnimationValueError;
155:     fn try_from(value: f32) -> AnimationValueResult<Self> {
156:         Self::from_fraction(value)
157:     }
158: }
159: 
160: impl DownedFacingPose {
161:     fn from_half_turns(value: f32) -> Self {
162:         match (value * 2.0).round() as i64 % 4 {
163:             0 => Self::Prone,
164:             1 | -3 => Self::RollRight,
165:             2 | -2 => Self::Supine,
166:             3 | -1 => Self::RollLeft,
167:             _ => unreachable!("remainder is bounded to four downed poses"),
168:         }
169:     }
170: 
171:     fn canonical_half_turns(self) -> f32 {
172:         match self {
173:             Self::Prone => 0.0,
174:             Self::RollRight => 0.5,
175:             Self::Supine => 1.0,
176:             Self::RollLeft => -0.5,
177:         }
178:     }

