214: impl SkeletonState {
215:     /// Follows or settles the downed roll. Held aim selects one of four sticky
216:     /// camera sectors; only a sector change interpolates the pose. After
217:     /// release, the retained roll coordinate settles to the nearest whole
218:     /// contact pose, keeping body parity at exact half-roll ties.
219:     /// Returns true while the camera-driven state remains active.
220:     pub fn advance_downed_facing(
221:         &mut self,
222:         camera_target_half_turns: SignedHalfTurns,
223:         aim: DownedFacingAim,
224:         maximum_step: DownedFacingStep,
225:     ) -> AnimationValueResult<bool> {
226:         if !matches!(self.body, BodyState::Prone | BodyState::Supine)
227:             || self.posture_transition.is_some()
228:         {
229:             self.downed_facing = None;
230:             return Ok(false);
231:         }
232:         let aim_held = aim == DownedFacingAim::Held;
233:         let camera_target = camera_target_half_turns.half_turns();
234:         let initial_target = match self.body {
235:             BodyState::Prone => DownedFacingPose::Prone,
236:             BodyState::Supine => DownedFacingPose::Supine,
237:             _ => unreachable!("downed body checked above"),
238:         };
239:         let initial = initial_target.half_turns_near(camera_target);
240:         let previous = self.downed_facing;
241:         let current = previous
242:             .map(|state| state.half_turns.half_turns())
243:             .unwrap_or(initial);
244:         let target = if aim_held {
245:             let tuning = crate::combat_config::runtime_animation_config().state_transitions;
246:             let committed = previous.map(|state| state.target).unwrap_or(initial_target);
247:             let committed_half_turns = committed.half_turns_near(current);
248:             let camera_unwrapped =
249:                 camera_target + ((committed_half_turns - camera_target) / 2.0).round() * 2.0;
250:             let target_pose = if (camera_unwrapped - committed_half_turns).abs()
251:                 > tuning.downed_facing_sector_half_width.half_turns()
252:                     + tuning.downed_facing_edge_stickiness.half_turns()
253:             {
254:                 DownedFacingPose::from_half_turns(camera_unwrapped)
255:             } else {
256:                 committed
257:             };
258:             target_pose.half_turns_near(camera_unwrapped)
259:         } else {
260:             let lower = current.floor();
261:             if (current - lower - 0.5).abs() <= 1.0e-4 {
262:                 match self.body {
263:                     BodyState::Prone => (current / 2.0).round() * 2.0,
264:                     BodyState::Supine => ((current - 1.0) / 2.0).round() * 2.0 + 1.0,
265:                     _ => unreachable!("downed body checked above"),
266:                 }
267:             } else {
268:                 current.round()
269:             }
270:         };
271:         let target_pose = if aim_held {
272:             DownedFacingPose::from_half_turns(target)
273:         } else if (target as i64).rem_euclid(2) == 0 {
274:             DownedFacingPose::Prone
275:         } else {
276:             DownedFacingPose::Supine
277:         };
278:         let step = maximum_step.half_turns().max(0.0);
279:         let next = current + (target - current).clamp(-step, step);
280:         self.downed_facing = Some(DownedFacingState {
281:             half_turns: SignedHalfTurns::from_half_turns(next).map_err(|_| {
282:                 AnimationValueError::Overflow {
283:                     quantity: AnimationQuantity::DownedFacing,
284:                 }
285:             })?,
286:             target: target_pose,
287:             lateral_motion: DownedRollMotion::from_change(next - current),
288:         });
289: 
290:         if (next - next.round()).abs() <= 1.0e-4 {
291:             let contact = next.round() as i64;
292:             self.transition_body(if contact.rem_euclid(2) == 0 {
293:                 BodyState::Prone
294:             } else {
295:                 BodyState::Supine
296:             });
297:             if !aim_held {
298:                 self.downed_facing = None;
299:                 return Ok(false);
300:             }
301:         }
302:         Ok(true)
303:     }
304: }
