306: /// Converts camera yaw into the continuous downed-roll coordinate relative to
307: /// the body's fixed head direction. A quarter turn is the half-roll pose and a
308: /// half turn is the opposite contact pose.
309: pub fn downed_camera_roll_target(
310:     body_rotation: Quat,
311:     controller_orientation: Quat,
312: ) -> SignedHalfTurns {
313:     let body = body_yaw(body_rotation);
314:     let camera_forward = controller_yaw(controller_orientation) * Vec3::NEG_Z;
315:     let camera = camera_forward.x.atan2(camera_forward.z);
316:     let mut delta = (camera - body + std::f32::consts::PI).rem_euclid(std::f32::consts::TAU)
317:         - std::f32::consts::PI;
318:     if (delta + std::f32::consts::PI).abs() <= 1.0e-5 {
319:         delta = std::f32::consts::PI;
320:     }
321:     let target = delta / std::f32::consts::PI;
322:     // This is the original camera-observation sanitation, now at its producer.
323:     SignedHalfTurns(if target.is_finite() { target } else { 0.0 })
324: }
