1: //! Authoritative contact planning and elapsed guard-footwork integration.
2: 
3: use super::*;
4: 
5: pub(super) fn advance_guard_footwork(
6:     skeleton: &mut SkeletonState,
7:     delta_seconds: AnimationElapsed,
8:     physical_speed: NonnegativeSpeed,
9:     tick: AnimationSampleTick,
10: ) -> AnimationValueResult<()> {
11:     let displacement = skeleton.local_velocity.xz() * delta_seconds.seconds();
12:     let physical_velocity = skeleton.local_velocity.xz();
13:     let physical_direction = physical_velocity.normalize_or_zero();
14:     let mut plan = match skeleton.raised_footwork {
15:         GuardFootworkPlan::Uninitialized => GuardFootworkPlan::Planted {
16:             contacts: GuardContacts::default(),
17:             next_swing: guard_movement_front_foot(
18:                 skeleton.lead_foot,
19:                 skeleton.raised_locomotion().local_direction(),
20:             ),
21:         },
22:         GuardFootworkPlan::Planted {
23:             contacts,
24:             next_swing,
25:         } => GuardFootworkPlan::Planted {
26:             contacts: contacts.advected(displacement),
27:             next_swing,
28:         },
29:         GuardFootworkPlan::Stepping(step) => {
30:             GuardFootworkPlan::Stepping(step.advected(displacement))
31:         }
32:     };
33: 
34:     if let GuardFootworkPlan::Stepping(mut step) = plan {
35:         let direction = if physical_direction == Vec2::ZERO {
36:             step.direction()
37:         } else {
38:             physical_direction
39:         };
40:         let leading_contact = step
41:             .contacts
42:             .left
43:             .dot(direction)
44:             .max(step.contacts.right.dot(direction));
45:         let contact_due = tick >= step.contact_tick || leading_contact <= 0.0;
46:         if contact_due {
47:             let contact_margin = guard_footwork_config().contact_margin_metres;
48:             if step.landing.dot(direction) < contact_margin {
49:                 step.landing += direction * (contact_margin - step.landing.dot(direction));
50:             }
51:             let contacts = step.contacts.with_contact(step.swing_foot, step.landing);
52:             skeleton.contact_foot = step.swing_foot;
53:             skeleton.contact_sequence = skeleton.contact_sequence.next();
54:             plan = GuardFootworkPlan::Planted {
55:                 contacts,
56:                 next_swing: opposite_foot(step.swing_foot),
57:             };
58:         }
59:     }
60: 
61:     if let GuardFootworkPlan::Planted {
62:         contacts,
63:         next_swing,
64:     } = plan
65:         && physical_speed > STATIONARY_ANIMATION_SPEED_LIMIT
66:     {
67:         plan = GuardFootworkPlan::Stepping(plan_guard_step(
68:             contacts,
69:             next_swing,
70:             physical_velocity,
71:             physical_speed,
72:             tick,
73:         ));
74:         skeleton.contact_foot = opposite_foot(next_swing);
75:     }
76: 
77:     skeleton.gait_phase = CyclePhase::from_cycles(match plan {
78:         GuardFootworkPlan::Stepping(step) => {
79:             let progress = step.progress(tick).clamp(0.0, 1.0);
80:             match step.swing_foot {
81:                 LeadFoot::Left => (0.5 + 0.5 * progress).rem_euclid(1.0),
82:                 LeadFoot::Right => 0.5 * progress,
83:             }
84:         }
85:         GuardFootworkPlan::Uninitialized | GuardFootworkPlan::Planted { .. } => {
86:             match skeleton.contact_foot {
87:                 LeadFoot::Left => 0.0,
88:                 LeadFoot::Right => 0.5,
89:             }
90:         }
91:     })?;
92:     skeleton.raised_footwork = plan;
93:     Ok(())
94: }
95: 
96: fn plan_guard_step(
97:     contacts: GuardContacts,
98:     swing_foot: LeadFoot,
99:     local_velocity: Vec2,
100:     physical_speed: NonnegativeSpeed,
101:     start_tick: AnimationSampleTick,
102: ) -> GuardStepPlan {
103:     let speed = physical_speed
104:         .max(STATIONARY_ANIMATION_SPEED_LIMIT)
105:         .metres_per_second();
106:     let direction = local_velocity.normalize_or_zero();
107:     let tuning = guard_footwork_config();
108:     let available_reach = tuning.planning_reach_metres - tuning.contact_margin_metres;
109:     let reach_seconds = available_reach / speed;
110:     let leading_contact = contacts
111:         .left
112:         .dot(direction)
113:         .max(contacts.right.dot(direction));
114:     let support_seconds = if leading_contact > 0.0 {
115:         leading_contact / speed
116:     } else {
117:         locomotion_sample_rate().interval().seconds()
118:     };
119:     let duration_seconds = reach_seconds.min(support_seconds).clamp(
120:         tuning.minimum_step_seconds.seconds(),
121:         tuning.maximum_step_seconds.seconds(),
122:     );
123:     let duration_ticks = AnimationSampleSpan::from(
124:         (duration_seconds * locomotion_sample_rate().hertz())
125:             .ceil()
126:             .max(1.0) as u64,
127:     );
128:     let forward = (speed * duration_ticks.samples() as f32 / locomotion_sample_rate().hertz()
129:         + tuning.contact_margin_metres)
130:         .min(tuning.planning_reach_metres);
131:     let side = match swing_foot {
132:         LeadFoot::Left => -tuning.default_half_width_metres,
133:         LeadFoot::Right => tuning.default_half_width_metres,
134:     };
135:     let mut landing = direction * forward + Vec2::X * side;
136:     let along_shortfall = forward - landing.dot(direction);
137:     if along_shortfall > 0.0 {
138:         landing += direction * along_shortfall;
139:     }
140:     landing = landing.clamp_length_max(tuning.planning_reach_metres);
141:     let swing_start = match swing_foot {
142:         LeadFoot::Left => contacts.left,
143:         LeadFoot::Right => contacts.right,
144:     };
145:     GuardStepPlan {
146:         contacts,
147:         swing_foot,
148:         swing_start,
149:         landing,
150:         start_tick,
151:         contact_tick: start_tick.saturating_add(duration_ticks),
152:     }
153: }

1: //! Admitted posture timelines and root-facing handoff for downed contacts.
2: 
3: use super::*;
4: 
5: #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
6: pub struct PostureTransitionState {
7:     pub(super) kind: PostureTransitionKind,
8:     pub(super) start_tick: AnimationSampleTick,
9:     pub(super) duration_ticks: AnimationSampleSpan,
10:     #[serde(deserialize_with = "crate::animation::pose_coordinates::deserialize_progress")]
11:     pub(super) phase: UnitInterval,
12:     pub(super) dive_was_airborne: bool,
13:     pub(super) dive_landing_tick: Option<AnimationSampleTick>,
14: }
15: 
16: struct DiveRecovery {
17:     direction: DiveDirection,
18:     progress: UnitInterval,
19: }
20: 
21: impl PostureTransitionState {
22:     pub(super) fn new(
23:         kind: PostureTransitionKind,
24:         start_tick: AnimationSampleTick,
25:         duration_ticks: AnimationSampleSpan,
26:     ) -> Self {
27:         Self {
28:             kind,
29:             start_tick,
30:             duration_ticks: duration_ticks.max(AnimationSampleSpan::ONE),
31:             phase: UnitInterval::ZERO,
32:             dive_was_airborne: false,
33:             dive_landing_tick: None,
34:         }
35:     }
36: 
37:     pub(super) fn normalized(mut self) -> Self {
38:         self.duration_ticks = self.duration_ticks.max(AnimationSampleSpan::ONE);
39:         self
40:     }
41: 
42:     pub fn kind(self) -> PostureTransitionKind {
43:         self.kind
44:     }
45: 
46:     pub fn phase(self) -> UnitInterval {
47:         self.phase
48:     }
49: 
50:     /// Returns the dive recovery progress after terrain contact.
51:     /// The first half of a dive is guard-to-airborne and remains fixed at its
52:     /// airborne endpoint until impact; only the second half transfers the
53:     /// directional pose into its canonical downed contact pose.
54:     fn dive_recovery(self) -> AnimationValueResult<Option<DiveRecovery>> {
55:         let PostureTransitionKind::DiveToDowned {
56:             direction,
57:             trajectory,
58:         } = self.kind
59:         else {
60:             return Ok(None);
61:         };
62:         // The authored body first settles out of its tilted dive pose, then
63:         // expresses the planar yaw of the downed contact. Starting root yaw at
64:         // contact gets ahead of that anatomical turn and visibly twists the
65:         // whole character before the supine pose catches up. Reserve the first
66:         // part of recovery for settling, then transfer root yaw with zero
67:         // endpoint velocity. The endpoint remains the complete canonical turn.
68:         let root_handoff_start_fraction = crate::combat_config::runtime_animation_config()
69:             .state_transitions
70:             .dive_root_handoff_start_fraction;
71:         let root_handoff_end_fraction = match trajectory {
72:             // The shorter slide devotes a larger normalized share to the same
73:             // fixed presentation settling time, so its handoff finishes with
74:             // the transition. The longer airborne recovery can finish just
75:             // before the terminal pose without outrunning the authored turn.
76:             DiveTrajectory::GroundedSlide => 1.0,
77:             DiveTrajectory::Airborne => 0.92,
78:         };
79:         let recovery = ((self.phase.fraction() - 0.5) * 2.0).clamp(0.0, 1.0);
80:         let handoff = ((recovery - root_handoff_start_fraction)
81:             / (root_handoff_end_fraction - root_handoff_start_fraction))
82:             .clamp(0.0, 1.0);
83:         Ok(Some(DiveRecovery {
84:             direction,
85:             progress: UnitInterval::from_fraction(smoothstep(handoff))?,
86:         }))
87:     }
88: }
89: 
90: /// Incremental root-yaw handoff for the directional downed contact pose.
91: /// Applying this after each posture-transition advance keeps the character's
92: /// world-space head-to-feet direction fixed from contact through the final
93: /// downed pose.
94: pub fn dive_landing_facing_delta(
95:     previous: Option<PostureTransitionState>,
96:     current: Option<PostureTransitionState>,
97: ) -> AnimationValueResult<Quat> {
98:     let Some(previous) = previous else {
99:         return Ok(Quat::IDENTITY);
100:     };
101:     let Some(DiveRecovery {
102:         direction,
103:         progress: previous_progress,
104:     }) = previous.dive_recovery()?
105:     else {
106:         return Ok(Quat::IDENTITY);
107:     };
108:     let current_progress = match current {
109:         Some(current) => current
110:             .dive_recovery()?
111:             .filter(|recovery| recovery.direction == direction)
112:             .map_or(UnitInterval::ONE, |recovery| recovery.progress),
113:         None => UnitInterval::ONE,
114:     };
115:     let total_yaw = match direction {
116:         DiveDirection::Forward => 0.0,
117:         // The authored backward-dive-to-supine blend contains the body's
118:         // half-turn. Transfer the inverse half-turn to the gameplay root over
119:         // the same contact-recovery interval so visible facing stays fixed
120:         // while the root reaches the canonical supine orientation. This must
121:         // not be omitted or applied as a single completion-tick correction.
122:         DiveDirection::Backward => std::f32::consts::PI,
123:         DiveDirection::Left => std::f32::consts::FRAC_PI_2,
124:         DiveDirection::Right => -std::f32::consts::FRAC_PI_2,
125:     };
126:     Ok(Quat::from_rotation_y(
127:         total_yaw * (current_progress.fraction() - previous_progress.fraction()).clamp(0.0, 1.0),
128:     ))
129: }
130: 
131: /// Returns the incremental root counter-yaw for a supine get-up.
132: ///
133: /// Supine contact poses use the head-facing orientation required by the
134: /// continuous prone/supine roll coordinate. Interpolating that convention
135: /// into canonical upright poses therefore contains an implicit positive-pi
136: /// turn during the midpoint-to-upright half of the transition. Applying the
137: /// equivalent negative root turn only during that same half cancels the turn
138: /// in world space while leaving the root in the correct upright orientation at
139: /// the endpoint. No other posture transition receives this correction.
140: pub fn supine_get_up_counter_yaw_delta(
141:     previous: Option<PostureTransitionState>,
142:     current: Option<PostureTransitionState>,
143: ) -> Quat {
144:     let Some(previous) =
145:         previous.filter(|transition| transition.kind() == PostureTransitionKind::SupineToUpright)
146:     else {
147:         return Quat::IDENTITY;
148:     };
149:     let previous_progress = ((previous.phase().fraction() - 0.5) * 2.0).clamp(0.0, 1.0);
150:     let current_progress = current
151:         .filter(|transition| transition.kind() == PostureTransitionKind::SupineToUpright)
152:         .map_or(1.0, |transition| {
153:             ((transition.phase().fraction() - 0.5) * 2.0).clamp(0.0, 1.0)
154:         });
155:     Quat::from_rotation_y(
156:         -std::f32::consts::PI * (current_progress - previous_progress).clamp(0.0, 1.0),
157:     )
158: }

