1: //! Checked controller observations projected into retained locomotion state.
2: 
3: use super::*;
4: 
5: /// One authoritative fixed-tick locomotion observation. The tactical server
6: /// supplies this from its character controller; deterministic presentation
7: /// fixtures replay the same boundary without inventing gait phase directly.
8: #[derive(Debug, Clone, Copy, PartialEq)]
9: pub struct SkeletonLocomotionInput {
10:     orientation: Quat,
11:     linear_velocity: Vec3,
12:     ground_contact: GroundContact,
13:     delta_seconds: AnimationElapsed,
14:     tick: AnimationSampleTick,
15: }
16: 
17: struct ProjectedObservation {
18:     local_velocity: Vec3,
19:     local_speed: NonnegativeSpeed,
20:     world_acceleration: Vec3,
21:     physical_speed: NonnegativeSpeed,
22:     landing_impact: Option<LandingImpactSpeed>,
23: }
24: 
25: impl SkeletonLocomotionInput {
26:     /// Admit the controller's native orientation and world velocity once. A
27:     /// finite quaternion need not be unit length at this existing boundary;
28:     /// transformed vectors and derived norms are checked during projection.
29:     pub fn from_controller(
30:         orientation: Quat,
31:         linear_velocity: Vec3,
32:         ground_contact: GroundContact,
33:         delta_seconds: AnimationElapsed,
34:         tick: AnimationSampleTick,
35:     ) -> AnimationValueResult<Self> {
36:         if !linear_velocity.is_finite() {
37:             return Err(AnimationValueError::NonFinite {
38:                 quantity: AnimationQuantity::WorldVelocity,
39:             });
40:         }
41:         if !orientation.is_finite() {
42:             return Err(AnimationValueError::NonFinite {
43:                 quantity: AnimationQuantity::BodyOrientation,
44:             });
45:         }
46:         Ok(Self {
47:             orientation,
48:             linear_velocity,
49:             ground_contact,
50:             delta_seconds,
51:             tick,
52:         })
53:     }
54: }
55: 
56: impl ProjectedObservation {
57:     fn admit(
58:         skeleton: &SkeletonState,
59:         input: SkeletonLocomotionInput,
60:         body_rotation: Quat,
61:     ) -> AnimationValueResult<Self> {
62:         if !skeleton.world_velocity.is_finite() {
63:             return Err(AnimationValueError::NonFinite {
64:                 quantity: AnimationQuantity::WorldVelocity,
65:             });
66:         }
67:         if !body_rotation.is_finite() {
68:             return Err(AnimationValueError::NonFinite {
69:                 quantity: AnimationQuantity::BodyOrientation,
70:             });
71:         }
72:         // Native Bevy vectors are transformed into controller/body frames at this seam.
73:         let previous_world_velocity = skeleton.world_velocity;
74:         let controller_local = controller_yaw(input.orientation).inverse() * input.linear_velocity;
75:         let body_local = body_rotation.inverse() * input.linear_velocity;
76:         let local_velocity = if skeleton.weapon_guard() == WeaponGuardState::Raised {
77:             controller_local
78:         } else {
79:             body_local
80:         };
81:         let physical_speed = input.linear_velocity.xz().length();
82:         let local_speed = local_velocity.xz().length();
83:         let acceleration = if input.tick == skeleton.locomotion_sample_tick.wrapping_next() {
84:             (input.linear_velocity - previous_world_velocity) * locomotion_sample_rate().hertz()
85:         } else {
86:             Vec3::ZERO
87:         };
88:         if !local_velocity.is_finite()
89:             || !local_speed.is_finite()
90:             || !physical_speed.is_finite()
91:             || !acceleration.length_squared().is_finite()
92:         {
93:             return Err(AnimationValueError::Overflow {
94:                 quantity: AnimationQuantity::WorldVelocity,
95:             });
96:         }
97:         let landing_impact = if !skeleton.body.is_surface_supported()
98:             && input.ground_contact == GroundContact::Grounded
99:         {
100:             // Upward finite velocity has zero downward impact; this is physical
101:             // projection after admission, not repair of an invalid speed.
102:             Some(LandingImpactSpeed::from_metres_per_second(
103:                 (-previous_world_velocity.y).max(0.0),
104:             )?)
105:         } else {
106:             None
107:         };
108:         Ok(Self {
109:             local_velocity,
110:             local_speed: NonnegativeSpeed::from_metres_per_second(local_speed)?,
111:             physical_speed: NonnegativeSpeed::from_metres_per_second(physical_speed)?,
112:             world_acceleration: acceleration.clamp_length_max(80.0),
113:             landing_impact,
114:         })
115:     }
116: }
117: 
118: /// Projects controller motion into the compact replicated animation state.
119: /// Bone evaluation remains client-only; this is the shared server seam that
