175:     skeleton.transition_body(if input.ground_contact == GroundContact::Grounded {
176:         match skeleton.body {
177:             BodyState::Prone | BodyState::Supine => skeleton.body,
178:             _ => BodyState::Grounded(GroundedPosture::Upright),
179:         }
180:     } else {
181:         BodyState::Airborne
182:     });
183:     if landed && skeleton.action_kind() == SkeletonAction::Dodge {
184:         // Contact ends presentation ownership immediately. Residual horizontal
185:         // velocity remains authoritative and can continue through ordinary
186:         // raised locomotion while the server applies its landing drag.
187:         skeleton.action = ActionState::default();
188:     }
189: 
190:     advance_projected_ground_cycle(
191:         skeleton,
192:         input,
193:         local_velocity,
194:         physical_speed,
195:         local_speed,
196:         requested_local_direction,
197:     )?;
198:     skeleton.advance_action(input.tick)?;
199:     Ok(())
200: }
201: 
202: fn advance_projected_ground_cycle(
203:     skeleton: &mut SkeletonState,
204:     input: SkeletonLocomotionInput,
205:     local_velocity: Vec3,
206:     physical_speed: NonnegativeSpeed,
207:     local_speed: NonnegativeSpeed,
208:     requested_local_direction: Option<Vec2>,
209: ) -> AnimationValueResult<()> {
210:     let ground_speed = if skeleton.is_downed_turning() {
211:         // Turning in place has no physical velocity, but its crawl/scamper
212:         // cycle should run at twice the former synthetic cadence.
213:         physical_speed
214:             .max(crate::animation::locomotion::MINIMUM_DOWNED_ANIMATION_SPEED)
215:             .checked_scale(2.0)?
216:     } else if matches!(skeleton.body, BodyState::Prone | BodyState::Supine) {
217:         // Residual impulses and collision correction may translate a downed
218:         // body, but prone/supine presentation deliberately slides in its idle
219:         // pose. Velocity-driven locomotion belongs only to upright bodies.
220:         NonnegativeSpeed::ZERO
221:     } else {
222:         physical_speed
223:     };
224:     if skeleton.weapon_guard() == WeaponGuardState::Raised && skeleton.posture() == Posture::Upright
225:     {
226:         advance_raised_locomotion_intent(
227:             skeleton,
228:             local_velocity,
229:             local_speed,
230:             requested_local_direction,
231:         );
232:         advance_guard_footwork(
233:             skeleton,
234:             input
235:                 .delta_seconds
236:                 .min(AnimationElapsed::from_seconds(1.0)?),
237:             local_speed,
238:             input.tick,
239:         )?;
240:     } else {
241:         skeleton.set_raised_locomotion(RaisedLocomotionIntent::planted());
242:         if input.ground_contact == GroundContact::Grounded
243:             && ground_speed
244:                 > crate::combat_config::runtime_animation_config()
245:                     .playback
246:                     .initial_locomotion_speed_metres_per_second
247:         {
248:             let profile = locomotion_profile(skeleton, skeleton.animation_speed()?)?;
249:             let phase = skeleton.gait_phase.wrapped();
250:             let next_phase = phase.checked_advance(gait_cycle_phase_delta(
251:                 profile,
252:                 ground_speed,
253:                 input.delta_seconds.capped_by_seconds(1.0)?,
254:             )?)?;
255:             let handoffs = ((next_phase.cycles() * f32::from(LOCOMOTION_CONTACTS_PER_CYCLE))
256:                 .floor()
257:                 - (phase.cycles() * f32::from(LOCOMOTION_CONTACTS_PER_CYCLE)).floor())
258:             .max(0.0) as u32;
259:             skeleton.gait_phase = next_phase.wrapped();
260:             advance_contact_identity(skeleton, handoffs, None);
261:             if skeleton.weapon_guard() == WeaponGuardState::Lowered {
262:                 skeleton.lead_foot =
263:                     if skeleton.gait_phase.cycles() < LOCOMOTION_SECOND_CONTACT_PHASE {
264:                         LeadFoot::Left
265:                     } else {
266:                         LeadFoot::Right
267:                     };
268:             }
269:         }
270:     }
271:     Ok(())
272: }

1: //! Observed raised-guard movement and held-request normalization.
2: 
3: use super::SkeletonState;
4: use crate::animation::STATIONARY_ANIMATION_SPEED_LIMIT;
5: use adventuresim_core::linear_speed::NonnegativeSpeed;
6: use bevy::prelude::{Vec2, Vec3};
7: use serde::{Deserialize, Serialize};
8: 
9: const MINIMUM_REQUESTED_GUARD_SPEED: NonnegativeSpeed =
10:     match NonnegativeSpeed::from_metres_per_second(0.051) {
11:         Ok(speed) => speed,
12:         Err(_) => panic!("invalid raised movement request threshold"),
13:     };
14: 
15: /// Compact authoritative input for client-side raised-guard foot placement.
16: /// The authority replicates only observed motion. Exact visual plants, swing
17: /// ownership, and progress are client presentation state, as in Overgrowth's
18: /// velocity-driven foot stance.
19: /// This invariant-bearing type intentionally does not implement Bevy reflection;
20: /// reflected field mutation would bypass its validated constructors.
21: #[derive(Debug, Clone, Copy, PartialEq, Serialize)]
22: pub struct RaisedLocomotionIntent(RaisedLocomotionKind);
23: 
24: #[derive(Debug, Clone, Copy, PartialEq, Serialize)]
25: #[serde(rename_all = "snake_case")]
26: enum RaisedLocomotionKind {
27:     Planted,
28:     Moving {
29:         local_direction: Vec2,
30:         speed: NonnegativeSpeed,
31:     },
32: }
33: 
34: #[derive(Deserialize)]
35: #[serde(rename_all = "snake_case")]
36: enum RaisedLocomotionWire {
37:     Planted,
38:     Moving { local_direction: Vec2, speed: f32 },
39: }
40: 
41: impl<'de> Deserialize<'de> for RaisedLocomotionIntent {
42:     fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
43:     where
44:         D: serde::Deserializer<'de>,
45:     {
46:         let value = RaisedLocomotionWire::deserialize(deserializer)?;
47:         Ok(match value {
48:             RaisedLocomotionWire::Planted => Self::planted(),
49:             RaisedLocomotionWire::Moving {
50:                 local_direction,
51:                 speed,
52:             } => Self::from_native_movement(local_direction, speed),
53:         })
54:     }
55: }
56: 
57: impl Default for RaisedLocomotionIntent {
58:     fn default() -> Self {
59:         Self::planted()
60:     }
61: }
62: 
63: impl RaisedLocomotionIntent {
64:     pub fn planted() -> Self {
65:         Self(RaisedLocomotionKind::Planted)
66:     }
67: 
68:     /// Creates validated moving intent. Invalid or effectively stationary
69:     /// input becomes planted while retaining its handoff identity.
70:     pub fn moving(local_direction: Vec2, speed: NonnegativeSpeed) -> Self {
71:         let direction = local_direction.normalize_or_zero();
72:         if !local_direction.is_finite()
73:             || direction == Vec2::ZERO
74:             || speed <= STATIONARY_ANIMATION_SPEED_LIMIT
75:         {
76:             return Self::planted();
77:         }
78:         Self(RaisedLocomotionKind::Moving {
79:             local_direction: direction,
80:             speed,
81:         })
82:     }
83: 
84:     /// Decode native observed/wire speeds using the existing planted normalization policy.
85:     pub(in crate::animation) fn from_native_movement(local_direction: Vec2, speed: f32) -> Self {
86:         match NonnegativeSpeed::from_metres_per_second(speed) {
87:             Ok(speed) => Self::moving(local_direction, speed),
88:             Err(_) => Self::planted(),
89:         }
90:     }
91: 
92:     pub fn is_moving(self) -> bool {
93:         matches!(self.0, RaisedLocomotionKind::Moving { .. })
94:     }
95: 
96:     pub fn local_direction(self) -> Vec2 {
97:         match self.0 {
98:             RaisedLocomotionKind::Moving {
99:                 local_direction, ..
100:             } => local_direction,
101:             RaisedLocomotionKind::Planted => Vec2::ZERO,
102:         }
103:     }
104: 
105:     pub fn speed(self) -> NonnegativeSpeed {
106:         match self.0 {
107:             RaisedLocomotionKind::Moving { speed, .. } => speed,
108:             RaisedLocomotionKind::Planted => NonnegativeSpeed::ZERO,
109:         }
110:     }
111: 
112:     pub fn local_velocity(self) -> Vec3 {
113:         let direction = self.local_direction();
114:         Vec3::new(direction.x, 0.0, direction.y) * self.speed().metres_per_second()
115:     }
116: }
117: 
118: pub(super) fn advance_raised_locomotion_intent(
119:     skeleton: &mut SkeletonState,
120:     observed_local_velocity: Vec3,
121:     observed_speed: NonnegativeSpeed,
122:     requested_local_direction: Option<Vec2>,
123: ) {
124:     let intent = skeleton.raised_locomotion();
125:     let observed = (observed_speed > STATIONARY_ANIMATION_SPEED_LIMIT).then(|| {
126:         RaisedLocomotionIntent::moving(
127:             Vec2::new(observed_local_velocity.x, observed_local_velocity.z),
128:             observed_speed,
129:         )
130:     });
131:     let requested = requested_local_direction.and_then(|direction| direction.try_normalize());
132:     let moving = observed.or_else(|| {
133:         requested.map(|direction| {
134:             RaisedLocomotionIntent::moving(
135:                 direction,
136:                 intent.speed().max(MINIMUM_REQUESTED_GUARD_SPEED),
137:             )
138:         })
139:     });
140:     skeleton.set_raised_locomotion(match moving {
141:         Some(moving) => moving,
142:         None if skeleton.raised_footwork.step().is_some() => intent,
143:         None => RaisedLocomotionIntent::planted(),
144:     });
145: }

