1: //! Checked facing policy keeps deadline quotients inside the bounded turn kernel.
2: 
3: use super::{SkeletonAction, WeaponGuardState};
4: use crate::animation::{
5:     AngularSpeedRadians, AnimationElapsed, AnimationQuantity, AnimationValueError,
6:     AnimationValueResult, PositiveAnimationDuration, STATIONARY_ANIMATION_SPEED_LIMIT,
7: };
8: use adventuresim_building_generator::spatial_geometry::Radians;
9: use bevy::math::{Quat, Vec3, Vec3Swizzles};
10: 
11: /// Finite admitted operands for a configured or deadline-directed planar turn.
12: /// A tiny deadline may overflow the transient rate; only the completed native
13: /// quotient -> elapsed product -> pi cap is the retained rotation operation.
14: #[derive(Clone, Copy, Debug)]
15: pub struct BodyFacingTurn(TurnPolicy);
16: 
17: #[derive(Clone, Copy, Debug)]
18: enum TurnPolicy {
19:     Speed(AngularSpeedRadians),
20:     HalfTurn(PositiveAnimationDuration),
21:     Deadline {
22:         angle: Radians,
23:         duration: PositiveAnimationDuration,
24:     },
25: }
26: 
27: impl BodyFacingTurn {
28:     pub fn configured_half_turn(duration: PositiveAnimationDuration) -> Self {
29:         Self(TurnPolicy::HalfTurn(duration))
30:     }
31: 
32:     pub fn configured_speed(speed: AngularSpeedRadians) -> Self {
33:         Self(TurnPolicy::Speed(speed))
34:     }
35: 
36:     /// The effective deadline is the larger of remaining time and frame elapsed.
37:     /// Missing planar direction and two real zero intervals preserve no turn.
38:     pub fn for_deadline(
39:         current: Quat,
40:         desired_forward: Vec3,
41:         remaining: AnimationElapsed,
42:         elapsed: AnimationElapsed,
43:     ) -> AnimationValueResult<Self> {
44:         let Some(desired) = desired_forward.xz().try_normalize() else {
45:             return Ok(Self::configured_speed(AngularSpeedRadians::ZERO));
46:         };
47:         let current = (current * Vec3::Z).xz().normalize_or_zero();
48:         let duration = remaining.max(elapsed);
49:         if duration.is_zero() {
50:             return Ok(Self::configured_speed(AngularSpeedRadians::ZERO));
51:         }
52:         let angle = Radians::new(current.angle_to(desired).abs()).map_err(|_| {
53:             AnimationValueError::NonFinite {
54:                 quantity: AnimationQuantity::BodyOrientation,
55:             }
56:         })?;
57:         Ok(Self(TurnPolicy::Deadline {
58:             angle,
59:             duration: PositiveAnimationDuration::from_elapsed(duration)?,
60:         }))
61:     }
62: 
63:     /// Native yaw integration is the only rate projection for application facing.
64:     pub fn advance(
65:         self,
66:         current: Quat,
67:         desired_forward: Vec3,
68:         elapsed: AnimationElapsed,
69:     ) -> AnimationValueResult<Quat> {
70:         let current_yaw = body_yaw(current);
71:         let desired_yaw = desired_forward.x.atan2(desired_forward.z);
72:         let mut delta = (desired_yaw - current_yaw + std::f32::consts::PI)
73:             .rem_euclid(std::f32::consts::TAU)
74:             - std::f32::consts::PI;
75:         if (delta + std::f32::consts::PI).abs() <= 1.0e-5 {
76:             delta = std::f32::consts::PI;
77:         }
78:         let maximum = (self.native_radians_per_second() * elapsed.seconds().max(0.0))
79:             .min(std::f32::consts::PI);
80:         rotation_from_yaw(current_yaw + delta.clamp(-maximum, maximum))
81:     }
82: 
83:     /// Captured-vector error budget at the final report's angular measurement.
84:     pub fn tracking_residual(self, before: Vec3, desired: Vec3, elapsed: AnimationElapsed) -> f32 {
85:         (before.angle_between(desired) - self.native_radians_per_second() * elapsed.seconds())
86:             .max(0.0)
87:     }
88: 
89:     // Local to the two complete native numerical kernels above. Infinity can be
90:     // transient here, but is never an admitted speed, field, or application handoff.
91:     fn native_radians_per_second(self) -> f32 {
92:         match self.0 {
93:             TurnPolicy::Speed(speed) => speed.radians_per_second(),
94:             TurnPolicy::HalfTurn(duration) => std::f32::consts::PI / duration.seconds(),
95:             TurnPolicy::Deadline { angle, duration } => angle.radians() / duration.seconds(),
96:         }
97:     }
98: }
99: 
100: pub fn body_facing_turn() -> BodyFacingTurn {
101:     BodyFacingTurn::configured_half_turn(
102:         crate::combat_config::runtime_combat_presentation_config().body_turn_seconds_per_half_turn,
103:     )
104: }
105: 
106: pub fn downed_turn_speed_radians() -> AngularSpeedRadians {
107:     crate::combat_config::runtime_combat_presentation_config().downed_turn_radians_per_second
108: }
109: 
110: /// Returns the controller's yaw without allowing camera pitch or roll to tilt
111: /// planar locomotion into or out of the ground plane.
112: pub fn controller_yaw(orientation: Quat) -> Quat {
113:     let forward = orientation * Vec3::NEG_Z;
114:     let Some(flat_forward) = forward.xz().try_normalize() else {
115:         return Quat::IDENTITY;
116:     };
117:     Quat::from_rotation_y((-flat_forward.x).atan2(-flat_forward.y))
118: }
119: 
120: /// Root orientation committed when a procedural directional dive launches.
121: /// Dive travel and pelvis tilt are both camera-relative, so they must capture
122: /// the same controller frame before posture-transition facing locks.
123: pub fn dive_launch_root_rotation(controller_orientation: Quat) -> Quat {
124:     let forward = controller_yaw(controller_orientation) * Vec3::NEG_Z;
125:     Quat::from_rotation_y(forward.x.atan2(forward.z))
126: }
127: 
128: /// Guard follows look; ordinary moving states follow authoritative planar velocity.
129: pub fn advance_body_facing(
130:     current: Quat,
131:     controller_orientation: Quat,
132:     linear_velocity: Vec3,
133:     action: SkeletonAction,
134:     weapon_guard: WeaponGuardState,
135:     elapsed: AnimationElapsed,
136: ) -> AnimationValueResult<Quat> {
137:     advance_body_facing_with_turn(
138:         current,
139:         controller_orientation,
140:         linear_velocity,
141:         action,
142:         weapon_guard,
143:         elapsed,
144:         body_facing_turn(),
145:     )

