1: use super::*;
2: use crate::scene_coordinates::{ArchitecturalGateDatum, ArchitecturalPlanProjection, GateRelative};
3: use adventuresim_building_generator::spatial_geometry::{Elevation, Radians};
4: use adventuresim_building_generator::{CollisionCuboid, CollisionError, DoorSpec, GenerationError};
5: use bevy::math::{Quat, Vec3};
6: 
7: const SWEEP_STEP_RADIANS: f32 = core::f32::consts::PI / 180.0;
8: 
9: /// Each enlarged sample contains the complete angular interval around it.
10: /// Candidate filtering uses bounding spheres; the final test uses oriented solids.
11: pub(super) fn clear(
12:     door: DoorSpec<GateRelative>,
13:     solids: &[CollisionCuboid<GateRelative>],
14: ) -> Result<bool, GenerationError> {
15:     let radius = door.horizontal_sweep_radius_metres()?;
16:     let candidates = solids
17:         .iter()
18:         .filter(|solid| {
19:             solid.centre.metres().distance(door.hinge_centre.metres())
20:                 <= radius.hypot(door.size_metres.metres().y * 0.5)
21:                     + solid.size.metres().length() * 0.5
22:         })
23:         .collect::<Vec<_>>();
24:     let steps = (door.open_angle_radians.radians().abs() / SWEEP_STEP_RADIANS).ceil() as usize;
25:     let step = door.open_angle_radians.radians() / steps as f32;
26:     let padding = radius * step.abs() * 0.5;
27:     for index in 0..steps {
28:         let angle = step * (index as f32 + 0.5);
29:         let leaf = CollisionCuboid::from_metres(
30:             door.source,
31:             door.hinge_centre.metres()
32:                 + Quat::from_rotation_y(angle)
33:                     * (door.closed_centre.metres() - door.hinge_centre.metres()),
34:             door.size_metres.metres() + Vec3::new(padding, 0.0, padding) * 2.0,
35:             door.closed_yaw_radians.radians() + angle,
36:             0.0,
37:             0.0,
38:         )?;
39:         if candidates.iter().any(|solid| leaf.intersects(**solid)) {
40:             return Ok(false);
41:         }
42:     }
43:     Ok(true)
44: }
45: 
46: pub(super) fn building_solids(
47:     placement: &TacticalBuildingPlacement,
48:     recipe: &Recipe,
49: ) -> Result<Vec<CollisionCuboid<GateRelative>>, GenerationError> {
50:     let datum = ArchitecturalGateDatum {
51:         plan: ArchitecturalPlanProjection::from_placement(placement, recipe.collision.bounds)
52:             .map_err(|_| {
53:                 adventuresim_building_generator::spatial_geometry::GeometryError::InvalidProjection
54:             })?,
55:         floor: Elevation::ZERO,
56:     };
57:     recipe
58:         .collision
59:         .cuboids
60:         .iter()
61:         .map(|solid| {
62:             let construct = || {
63:                 Ok(CollisionCuboid {
64:                     source: solid.source,
65:                     centre: datum.point(solid.centre)?,
66:                     size: solid.size,
67:                     yaw_radians: Radians::new(
68:                         solid.yaw_radians.radians() + placement.orientation.yaw_radians(),
69:                     )?,
70:                     crossfall_radians: solid.crossfall_radians,
71:                     longfall_radians: solid.longfall_radians,
72:                 })
73:             };
74:             construct().map_err(|cause| {
75:                 GenerationError::Collision(CollisionError {
76:                     source_id: solid.source,
77:                     cause,
78:                 })
79:             })
80:         })
81:         .collect()
82: }
