105:     }
106:     /// Plan without changing input terrain or placement. Installing selected
107:     /// floors and terrain is a separate producer operation. Complete membership
108:     /// is retained across playable/distant partitioning; no nearest match is used.
109:     pub fn plan_compound_support(
110:         &self,
111:         geographic: &GeographicSurface,
112:         policy: CompoundGradingPolicy,
113:     ) -> Result<Vec<CompoundSupportPlan>, CitySupportError> {
114:         self.validate_physical_support_members()?;
