116:             .playable
117:             .iter()
118:             .cloned()
119:             .chain(
120:                 self.distant
121:                     .iter()
122:                     .copied()
123:                     .map(TacticalBuildingPlacement::from),
124:             )
125:             .map(|b| (b.id, b))
126:             .collect();
127:         let mut compounds: Vec<_> = self.compounds.iter().collect();
128:         compounds.sort_by_key(|c| c.id);
129:         let mut recipes = self.support_recipes.clone();
130:         compounds
131:             .into_iter()
132:             .map(|property| {
133:                 plan_property(
134:                     property,
135:                     &buildings,
136:                     &mut recipes,
137:                     geographic,
138:                     &self.streets,
139:                     policy,
140:                 )
141:             })
142:             .collect()
143:     }
