1: //! Prefer the property's near street half within the declared maximum apron.
2: use super::*;
3: use crate::city_layout::grounding::access::{access_regions, available_run};
4: 
5: pub(super) fn select(
6:     property: &CityCompound,
7:     observations: CompoundSupportLevels,
8:     threshold: crate::scene_coordinates::ScenePlanPoint,
9:     geographic: &GeographicSurface,
10:     streets: &[CityStreetPatch],
11:     policy: CompoundGradingPolicy,
12: ) -> Result<CompoundSupportPlan, CitySupportError> {
13:     let threshold_point = threshold;
14:     let threshold = threshold.metres();
15:     let plot = property.plot;
16:     let local = plot
17:         .orientation()
18:         .world_to_local(threshold - plot.centre_metres());
19:     let edge = plot.centre_metres()
20:         + plot
21:             .orientation()
22:             .local_to_world(Vec2::new(local.x, -plot.dimensions_metres().y * 0.5));
23:     let direction = plot.orientation().local_to_world(-Vec2::Y);
24:     let offset = plot.orientation().local_to_world(Vec2::X) * policy.street_apron.0.x * 0.5;
25:     let maximum = policy.street_apron.0.y;
26:     let regions = access_regions(plot, streets, edge)?;
27:     let preferred = (available_run(
28:         edge,
29:         direction,
30:         offset,
31:         &regions,
32:         maximum,
33:         policy.limits.contact_tolerance_metres(),
34:     ) - policy.limits.contact_tolerance_metres())
35:     .max(0.0);
36:     let candidate = |run: f32| {
37:         CompoundSupportRequest {
38:             property,
39:             observations,
40:             street_threshold_metres: threshold_point,
41:             street_apron: (|| -> adventuresim_building_generator::spatial_geometry::GeometryResult<CityPlotBounds> { CityPlotBounds::new(crate::scene_coordinates::ScenePlanPoint::try_from(edge + direction * run * 0.5)?,adventuresim_building_generator::spatial_geometry::PlanDimensions::from_metres(Vec2::new(policy.street_apron.0.x, run))?,plot.orientation()) })().map_err(|cause| SupportDiagnostic::framed_geometry(property, edge, cause))?,
42:             geographic,
43:             limits: policy.limits,
44:             stairs: policy.stairs,
45:             embedment: policy.embedment,
46:         }
47:         .select()
48:     };
49:     // A steep approach may require more of the existing external reservation.
50:     // Both candidates retain the same members and complete source constraints;
51:     // final composition still rejects any intersection with another property.
52:     if preferred > 0.0 && preferred < maximum {
53:         match candidate(preferred) {
54:             Ok(plan) => return Ok(plan),
55:             Err(error)
56:                 if matches!(
57:                     error.constraint,
58:                     SupportConstraint::StairGoing
59:                         | SupportConstraint::StairClearance
60:                         | SupportConstraint::AccessGrade
61:                         | SupportConstraint::CutFill
62:                 ) => {}
63:             Err(error) => return Err(CitySupportError::Support(error)),
64:         }
65:     }
66:     candidate(maximum).map_err(CitySupportError::Support)
67: }

