5: pub(super) fn corridor(segment: CityAccessSegment) -> Option<CityPlotBounds> {
6:     let direction = segment.end_metres() - segment.start_metres();
7:     CityPlotBounds::new(
8:         crate::scene_coordinates::ScenePlanPoint::try_from(
9:             (segment.start_metres() + segment.end_metres()) * 0.5,
10:         )
11:         .ok()?,
12:         adventuresim_building_generator::spatial_geometry::PlanDimensions::from_metres(Vec2::new(
13:             direction.length() + segment.half_width_metres() * 2.0,
14:             segment.half_width_metres() * 2.0,
