22: pub(super) fn overlaps(first: &[Vec2], second: &[Vec2], margin: f32) -> bool {
23:     [first, second]
24:         .into_iter()
25:         .flat_map(|polygon| {
26:             polygon
27:                 .iter()
28:                 .zip(polygon.iter().cycle().skip(1))
29:                 .take(polygon.len())
30:         })
31:         .all(|(a, b)| {
32:             let axis = (*b - *a).perp().normalize_or_zero();
33:             let interval = |points: &[Vec2]| {
34:                 points
35:                     .iter()
36:                     .fold((f32::INFINITY, f32::NEG_INFINITY), |(min, max), point| {
37:                         let p = point.dot(axis);
38:                         (min.min(p), max.max(p))
39:                     })
40:             };
41:             let (a, b) = interval(first);
42:             let (c, d) = interval(second);
43:             b + margin > c && d + margin > a
44:         })
45: }
