46: pub(in crate::city_layout) fn available_run(
47:     edge: Vec2,
48:     direction: Vec2,
49:     offset: Vec2,
50:     regions: &[Vec<bevy::math::DVec2>],
51:     maximum: f32,
52:     tolerance: f32,
53: ) -> f32 {
54:     // A clear strip may straddle a junction between street segments. Subtract
55:     // their union, rather than requiring both strip edges inside one segment.
56:     let maximum = if maximum.is_finite() {
57:         maximum
58:     } else {
59:         regions
60:             .iter()
61:             .flat_map(|r| r.iter().copied())
62:             .map(|p| (p - edge.as_dvec2()).dot(direction.as_dvec2()) as f32)
63:             .fold(0.0_f32, f32::max)
64:     };
65:     if maximum <= 0.0 {
66:         return 0.0;
67:     }
68:     let points = [
69:         edge - offset,
70:         edge + direction * maximum - offset,
71:         edge + direction * maximum + offset,
72:         edge + offset,
73:     ];
74:     let mut remaining = vec![points.map(Vec2::as_dvec2).to_vec()];
75:     for region in regions {
76:         remaining = remaining
77:             .into_iter()
78:             .flat_map(|polygon| crate::city_layout::grounding::planar::subtract(polygon, region))
79:             .collect();
80:     }
81:     remaining
82:         .into_iter()
83:         .filter(|polygon| minimum_width(polygon) > f64::from(tolerance))
84:         .flat_map(|polygon| polygon.into_iter())
85:         .map(|p| (p - edge.as_dvec2()).dot(direction.as_dvec2()) as f32)
86:         .fold(maximum, f32::min)
87:         .max(0.0)
88: }
