90: fn minimum_width(polygon: &[bevy::math::DVec2]) -> f64 {
91:     if super::planar::signed_area(polygon) == 0.0 {
92:         return 0.0;
93:     }
94:     (0..polygon.len())
95:         .filter_map(|i| {
96:             let edge = polygon[(i + 1) % polygon.len()] - polygon[i];
97:             (edge.length_squared() > 0.0).then(|| {
98:                 let normal = edge.perp().normalize();
99:                 let lo = polygon
100:                     .iter()
101:                     .map(|p| p.dot(normal))
102:                     .fold(f64::INFINITY, f64::min);
