4: pub(super) fn exterior(regions: &[Vec<DVec2>]) -> Vec<[DVec2; 2]> {
5:     let mut result = Vec::new();
6:     for (owner, corners) in regions.iter().enumerate() {
7:         for i in 0..corners.len() {
8:             let a = corners[i];
9:             let b = corners[(i + 1) % corners.len()];
10:             let direction = b - a;
11:             let mut stations = vec![0.0, 1.0];
12:             for region in regions {
13:                 for j in 0..region.len() {
14:                     let origin = region[j];
15:                     let edge = region[(j + 1) % region.len()] - origin;
16:                     // A shared endpoint can round just beyond the segment's
17:                     // closed intersection interval. Retain projected corners
18:                     // on this same half-plane before testing a crossing.
19:                     for point in [origin, origin + edge] {
20:                         if direction.perp_dot(point - a).abs()
21:                             <= predicate_error(direction, point, a)
22:                         {
23:                             let t = (point - a).dot(direction) / direction.length_squared();
24:                             if (0.0..=1.0).contains(&t) {
25:                                 stations.push(t);
26:                             }
27:                         }
28:                     }
29:                     let divisor = direction.perp_dot(edge);
30:                     if divisor.abs() > 0.0 {
31:                         let t = (origin - a).perp_dot(edge) / divisor;
32:                         let u = (origin - a).perp_dot(direction) / divisor;
33:                         if (0.0..=1.0).contains(&t) && (0.0..=1.0).contains(&u) {
34:                             stations.push(t);
35:                         }
36:                     }
37:                 }
38:             }
39:             stations.sort_by(f64::total_cmp);
40:             stations.dedup();
41:             for pair in stations.windows(2) {
42:                 let midpoint = a + direction * ((pair[0] + pair[1]) * 0.5);
43:                 let outward = -direction.perp();
44:                 let covered = regions.iter().enumerate().any(|(other, region)| {
45:                     if other == owner {
46:                         return false;
47:                     }
48:                     let mut boundary = false;
49:                     let mut exits = false;
50:                     for j in 0..region.len() {
51:                         let edge = region[(j + 1) % region.len()] - region[j];
52:                         let side = edge.perp_dot(midpoint - region[j]);
53:                         let error = predicate_error(edge, midpoint, region[j]);
54:                         if side < -error {
55:                             return false;
56:                         }
57:                         if side.abs() <= error {
58:                             boundary = true;
59:                             exits |= edge.perp_dot(outward) < 0.0;
60:                         }
61:                     }
62:                     !exits || (boundary && other < owner)
63:                 });
64:                 if !covered && pair[1] > pair[0] {
65:                     result.push([a + direction * pair[0], a + direction * pair[1]]);
66:                 }
67:             }
68:         }
69:     }
70:     result
