73: fn predicate_error(edge: DVec2, point: DVec2, origin: DVec2) -> f64 {
74:     // Bound eight scalar operations, including scene-origin subtraction.
75:     // This is arithmetic roundoff, not a grading or contact envelope.
76:     f64::EPSILON * edge.length() * (point.length() + origin.length()).max(1.0) * 8.0
