79: pub(super) fn segment_interval(
80:     segment: [DVec2; 2],
81:     polygon: &[DVec2],
82:     tolerance_metres: f64,
83: ) -> Option<(f64, f64)> {
84:     let [a, b] = segment;
85:     let direction = b - a;
86:     let mut begin = 0.0_f64;
87:     let mut end = 1.0_f64;
88:     for i in 0..polygon.len() {
89:         let edge = polygon[(i + 1) % polygon.len()] - polygon[i];
90:         let origin = edge.perp_dot(a - polygon[i]) + tolerance_metres * edge.length();
91:         let rate = edge.perp_dot(direction);
92:         if rate == 0.0 {
93:             if origin < 0.0 {
94:                 return None;
95:             }
96:         } else if rate > 0.0 {
97:             begin = begin.max(-origin / rate);
98:         } else {
99:             end = end.min(-origin / rate);
100:         }
101:     }
102:     (end > begin).then_some((begin, end))
103: }
