124: impl CompoundSupportPlan {
125:     /// An explicitly bound apron shares the plot's front half-plane. Computing
126:     /// the same line independently through rounded rectangle centres can leave
127:     /// a micrometre-wide source triangle blocking the full doorway route.
128:     /// Only this property's declared join is welded; unrelated terraces and
129:     /// source heights are untouched. Double precision keeps the shared line
130:     /// until final presentation/collision vertices are emitted.
131:     pub(in crate::city_layout::grounding) fn source_clipping_outlines(
132:         &self,
133:     ) -> Vec<Vec<bevy::math::DVec2>> {
134:         let mut regions: Vec<_> = self
135:             .support_regions()
136:             .into_iter()
137:             .map(|region| region.corners().map(|point| point.as_dvec2()).to_vec())
138:             .collect();
139:         if self.street_entry.is_some() {
140:             let (a, b) = (regions[0][0], regions[0][1]);
141:             let edge = b - a;
142:             // support_regions appends the bound street entry after the front
143:             // bearing, so this branch has a complete final apron rectangle.
144:             let last = regions.len() - 1;
145:             let apron = &mut regions[last];
146:             for point in &mut apron[2..] {
147:                 *point = a + edge * ((*point - a).dot(edge) / edge.length_squared());
148:             }
149:         }
150:         regions
151:     }
