328: fn validate_owners(plans: &[&PropertySupportSurface]) -> Result<(), SettlementSupportError> {
329:     use crate::city_layout::grounding::planar::query::{PlanarBounds, PlanarQueryIndex};
330:     // Include complete source-clipping outlines, especially entry aprons
331:     // outside a plot. The broad phase only avoids disjoint owner pairs; exact
332:     // clipping below retains its canonical conflict order and diagnostics.
333:     let bounds: Vec<_> = plans
334:         .iter()
335:         .map(|plan| {
336:             PlanarBounds::from_points(plan.clipping_outlines.iter().flatten().copied())
337:                 .ok_or(SupportGeometryIssue::Query)
338:         })
339:         .collect::<Result<_, _>>()?;
340:     let index = PlanarQueryIndex::from_bounds(bounds.clone());
341:     let mut properties = BTreeSet::new();
342:     let mut members = std::collections::BTreeMap::new();
343:     for (ordinal, plan) in plans.iter().enumerate() {
344:         let property = plan.property_id();
345:         if !properties.insert(property) {
346:             return Err(SettlementSupportError::DuplicateProperty { property });
347:         }
348:         for building in &plan.mesh.member_building_ids {
349:             if let Some(first) = members.insert(*building, property) {
350:                 return Err(SettlementSupportError::DuplicateMember {
351:                     building: *building,
352:                     first,
353:                     second: property,
354:                 });
355:             }
356:         }
357:         for earlier in index
358:             .intersections(bounds[ordinal])
359:             .into_iter()
360:             .filter(|earlier| *earlier < ordinal)
361:             .map(|earlier| plans[earlier])
362:         {
363:             for (first, first_outline) in earlier
364:                 .support_regions()
365:                 .iter()
366:                 .zip(&earlier.clipping_outlines)
367:             {
368:                 for (second, second_outline) in
369:                     plan.support_regions().iter().zip(&plan.clipping_outlines)
370:                 {
371:                     if let Some((location_metres, area_square_metres)) =
372:                         overlap(*first, *second, first_outline, second_outline)
373:                     {
374:                         return Err(SettlementSupportError::OwnershipOverlap {
375:                             first: earlier.property_id(),
376:                             first_members: earlier.mesh.member_building_ids.clone(),
377:                             second: property,
378:                             second_members: plan.mesh.member_building_ids.clone(),
379:                             location_metres: crate::scene_coordinates::ScenePlanPoint::try_from(
380:                                 location_metres,
381:                             )
382:                             .map_err(|_| SupportGeometryIssue::NonFinite)?,
383:                             area_square_metres: DiagnosticArea::from_square_metres(
384:                                 area_square_metres,
385:                             )
386:                             .ok_or(SupportGeometryIssue::NonFinite)?,
387:                             first_region: *first,
388:                             second_region: *second,
389:                         });
390:                     }
391:                 }
392:             }
393:         }
394:     }
395:     Ok(())
396: }
397: 
398: fn overlap(
399:     first: CityPlotBounds,
400:     second: CityPlotBounds,
401:     first_outline: &[bevy::math::DVec2],
402:     second_outline: &[bevy::math::DVec2],
403: ) -> Option<(Vec2, f64)> {
404:     if !first.intersects(second) {
405:         return None;
406:     }
407:     let mut intersection = first_outline.to_vec();
408:     for i in 0..second_outline.len() {
409:         let a = second_outline[i];
410:         let edge = second_outline[(i + 1) % second_outline.len()] - a;
411:         intersection =
412:             crate::city_layout::grounding::planar::clip(intersection, |p| edge.perp_dot(p - a));
413:     }
414:     let area = crate::city_layout::grounding::planar::signed_area(&intersection).abs();
415:     (area > 0.0).then(|| {
416:         let location =
417:             intersection.iter().copied().sum::<bevy::math::DVec2>() / intersection.len() as f64;
418:         (location.as_vec2(), area)
419:     })
420: }

