4: /// Canonicalization and edge lengths depend only on admitted source vertices.
5: /// Sharing this cache keeps terrain clones from copying another face buffer.
6: #[derive(Clone, Debug, Default)]
7: pub(in crate::city_layout::grounding::foundations::settlement) struct PreparedSupportTriangles {
8:     natural: Vec<Option<PreparedTriangle>>,
9:     foundations: Vec<Vec<Option<PreparedTriangle>>>,
10: }
11: 
12: #[derive(Clone, Debug)]
13: pub(super) struct PreparedTriangle {
14:     geometry: GroundTriangle,
15:     edge_lengths: [f64; 3],
16: }
17: 
18: impl PreparedSupportTriangles {
19:     pub fn from_surface(surface: &BoundedSettlementTerrain) -> Self {
20:         Self {
21:             natural: surface
22:                 .natural_triangles
23:                 .iter()
24:                 .copied()
25:                 .map(PreparedTriangle::new)
26:                 .collect(),
27:             foundations: surface
28:                 .foundations
29:                 .iter()
30:                 .map(|foundation| {
31:                     foundation
32:                         .support_triangles
33:                         .iter()
34:                         .map(|indices| {
35:                             PreparedTriangle::new(
36:                                 indices.map(|index| foundation.positions[index as usize]),
37:                             )
38:                         })
39:                         .collect()
40:                 })
41:                 .collect(),
42:         }
43:     }
44: 
45:     pub(super) fn triangle(&self, reference: SupportTriangleRef) -> Option<&PreparedTriangle> {
46:         match reference {
47:             SupportTriangleRef::Natural(index) => self.natural[index].as_ref(),
48:             SupportTriangleRef::Foundation { owner, triangle } => {
49:                 self.foundations[owner][triangle].as_ref()
50:             }
51:         }
52:     }
53: }
54: 
55: impl PreparedTriangle {
56:     fn new(points: [Vec3; 3]) -> Option<Self> {
57:         // Finite degenerate source faces remain legal and have no support hit.
58:         let geometry = GroundTriangle::new(points)?;
59:         let points = geometry.points().map(|point| point.xz().as_dvec2());
60:         let edge_lengths =
61:             std::array::from_fn(|index| (points[(index + 1) % 3] - points[index]).length());
62:         Some(Self {
63:             geometry,
64:             edge_lengths,
65:         })
66:     }
67: 
68:     pub(super) fn geometry(&self) -> &GroundTriangle {
69:         &self.geometry
70:     }
71: 
72:     pub(super) fn contains(&self, point: Vec2, tolerance_metres: f32) -> bool {
73:         // Retain the original unnormalized half-plane arithmetic and order.
74:         // Normalized planes can change classifications at rounded shared edges.
75:         let points = self.geometry.points();
76:         (0..3).all(|index| {
77:             let origin = points[index].xz().as_dvec2();
78:             let edge = points[(index + 1) % 3].xz().as_dvec2() - origin;
79:             edge.perp_dot(point.as_dvec2() - origin)
80:                 >= -f64::from(tolerance_metres) * self.edge_lengths[index]
81:         })
82:     }
83: }

