1: //! One source retains fine playable triangles and the existing vista seams.
2: use super::*;
3: use crate::{
4:     scene::SceneTerrain,
5:     scene_input::{VistaLod, VistaSample},
6:     vista_surface::{
7:         cell_rectangles_outside_inner_rectangle, presented_vista_vertex_height,
8:         subdivide_playable_boundary_rectangle,
9:     },
10: };
11: 
12: impl GeographicSurface {
13:     /// Exact current presentation surface before owned grading. Fine playable
14:     /// triangles are retained, not resampled onto a vista grid. Each centered
15:     /// vista ring excludes the preceding rectangle and uses the renderer's
16:     /// subdivision, height morph and playable-edge stitching policy.
17:     /// Malformed, offset or nonexpanding rings are rejected explicitly.
18:     pub fn from_presented_scene(terrain: &SceneTerrain, vista: &VistaSample) -> Option<Self> {
19:         let playable = terrain.sampled_geographic_surface()?;
20:         let mut triangles: Vec<_> = playable.triangles().collect();
21:         let mut inner_half_extent = Vec2::new(terrain.width(), terrain.depth()) * 0.5;
22:         for lod in &vista.lods {
23:             let half_extent = Vec2::new(
24:                 f32::from(lod.width.checked_sub(1)?),
25:                 f32::from(lod.depth.checked_sub(1)?),
26:             ) * lod.spacing_metres
27:                 * 0.5;
28:             if lod.width < 2
29:                 || lod.depth < 2
30:                 || lod.heights_metres.len() != usize::from(lod.width) * usize::from(lod.depth)
31:                 || !lod.spacing_metres.is_finite()
32:                 || lod.spacing_metres <= 0.0
33:                 || lod.origin_east_metres != 0.0
34:                 || lod.origin_north_metres != 0.0
35:                 || half_extent.cmple(inner_half_extent).any()
36:             {
37:                 return None;
38:             }
39:             inner_half_extent = half_extent;
40:         }
41:         inner_half_extent = Vec2::new(terrain.width(), terrain.depth()) * 0.5;
42:         for (index, lod) in vista.lods.iter().enumerate() {
43:             append_ring(
44:                 &mut triangles,
45:                 lod,
46:                 vista.lods.get(index + 1),
47:                 (index == 0).then_some(terrain),
48:                 inner_half_extent,
49:             )?;
50:             inner_half_extent = Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1))
51:                 * lod.spacing_metres
52:                 * 0.5;
53:         }
54:         Self::from_triangles(triangles)
55:     }
56: }
57: 
58: fn append_ring(
59:     triangles: &mut Vec<[Vec3; 3]>,
60:     lod: &VistaLod,
61:     coarser: Option<&VistaLod>,
62:     terrain: Option<&SceneTerrain>,
63:     inner_half_extent: Vec2,
64: ) -> Option<()> {
65:     let size = Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1));
66:     for z in 0..usize::from(lod.depth - 1) {
67:         for x in 0..usize::from(lod.width - 1) {
68:             let minimum = (Vec2::new(x as f32, z as f32) - size * 0.5) * lod.spacing_metres;
69:             let maximum = minimum + Vec2::splat(lod.spacing_metres);
70:             for rectangle in
71:                 cell_rectangles_outside_inner_rectangle(minimum, maximum, inner_half_extent)
72:             {
73:                 for [x0, x1, z0, z1] in
74:                     subdivide_playable_boundary_rectangle(rectangle, inner_half_extent, terrain)
75:                 {
76:                     let vertex = |x, z| {
77:                         let point = Vec2::new(x, z);
78:                         Some(Vec3::new(
79:                             x,
80:                             presented_vista_vertex_height(
81:                                 lod,
82:                                 coarser,
83:                                 terrain,
84:                                 crate::scene_coordinates::PlanDisplacement::from_metres(point)?,
85:                                 inner_half_extent,
86:                             )?
87:                             .metres(),
88:                             z,
89:                         ))
90:                     };
91:                     let [a, b, c, d] = [
92:                         vertex(x0, z0)?,
93:                         vertex(x1, z0)?,
94:                         vertex(x1, z1)?,
95:                         vertex(x0, z1)?,
96:                     ];
97:                     triangles.extend([[a, b, c], [a, c, d]]);
98:                 }
99:             }
100:         }
101:     }
102:     Some(())
103: }
