1: //! Footprint coverage and physical grade include complete triangle intersections.
2: use super::*;
3: use crate::city_layout::grounding::planar::{clip, signed_area};
4: 
5: /// A slope observation alone cannot certify traversal across retaining edges.
6: #[derive(Clone, Copy, Debug, Serialize)]
7: pub struct GeographicRegionMeasurement {
8:     pub required_area_square_metres: DiagnosticArea,
9:     pub covered_area_square_metres: DiagnosticArea,
10:     pub maximum_grade: GeographicGrade,
11:     pub maximum_grade_location_metres: crate::scene_coordinates::ScenePlanPoint,
12:     pub maximum_grade_triangle_metres: [adventuresim_building_generator::spatial_geometry::Position<
13:         crate::scene_coordinates::Scene,
14:     >; 3],
15: }
16: 
17: impl GeographicSurface {
18:     /// Measure all affine source triangles intersecting a convex footprint.
19:     /// Missing area remains explicit. Vertical risers, gate sweeps and actor
20:     /// clearance require separate collision checks against the composed solid.
21:     pub fn measure_region(
22:         &self,
23:         outline: &crate::scene_coordinates::ScenePlanPolygon,
24:     ) -> Option<GeographicRegionMeasurement> {
25:         let outline: Vec<_> = outline
26:             .vertices()
27:             .iter()
28:             .map(|p| p.metres().as_dvec2())
29:             .collect();
30:         if outline.len() < 3 || outline.iter().any(|p| !p.is_finite()) {
31:             return None;
32:         }
33:         let required_area_square_metres = signed_area(&outline);
34:         if required_area_square_metres <= 0.0 {
35:             return None;
36:         }
37:         let bounds = PlanarBounds::from_points(outline.iter().copied())?;
38:         let mut covered_area_square_metres = 0.0;
39:         let mut maximum: Option<GeographicRegionMeasurement> = None;
40:         for index in self.query.intersections(bounds) {
41:             let triangle = &self.triangles[index];
42:             let points = triangle.points();
43:             let mut polygon = points.map(|p| p.xz().as_dvec2()).to_vec();
44:             for i in 0..outline.len() {
45:                 let a = outline[i];
46:                 let edge = outline[(i + 1) % outline.len()] - a;
47:                 polygon = clip(polygon, |p| edge.perp_dot(p - a));
48:             }
49:             let area = signed_area(&polygon);
50:             if area <= 0.0 {
51:                 continue;
52:             }
53:             covered_area_square_metres += area;
54:             let [a, b, c] = points.map(Vec3::as_dvec3);
55:             let normal = (b - a).cross(c - a);
56:             let grade = normal.xz().length() / normal.y.abs();
57:             if maximum.is_none_or(|old| grade > old.maximum_grade.ratio()) {
58:                 let location =
59:                     polygon.iter().copied().sum::<bevy::math::DVec2>() / polygon.len() as f64;
60:                 maximum = Some(GeographicRegionMeasurement {
61:                     required_area_square_metres: DiagnosticArea::from_square_metres(required_area_square_metres)?,
62:                     covered_area_square_metres: DiagnosticArea::from_square_metres(covered_area_square_metres)?,
63:                     maximum_grade: GeographicGrade::from_ratio(grade)?,
64:                     maximum_grade_location_metres: crate::scene_coordinates::ScenePlanPoint::from_metres(location.as_vec2())?,
65:                     maximum_grade_triangle_metres: points.map(adventuresim_building_generator::spatial_geometry::Position::from_metres).into_iter().collect::<Result<Vec<_>, _>>().ok()?.try_into().ok()?,
66:                 });
67:             }
68:         }
69:         let mut measurement = maximum?;
70:         measurement.covered_area_square_metres =
71:             DiagnosticArea::from_square_metres(covered_area_square_metres)?;
72:         Some(measurement)
73:     }
74: }
