1: //! Binary products encode six-vertex cells once, with their existing topology.
2: //! Documents retain explicit indices. Executable-bound caches never mix codecs.
3: use super::*;
4: use serde::{Deserializer, Serializer, de::Error};
5: 
6: #[derive(Serialize, Deserialize)]
7: #[serde(remote = "PropertyFoundationMesh")]
8: struct FoundationDocument {
9:     property_id: CityPropertyId,
10:     member_building_ids: Vec<crate::scene_input::SceneBuildingId>,
11:     #[serde(with = "crate::geometry_transport")]
12:     positions: Vec<Vec3>,
13:     #[serde(with = "crate::geometry_transport")]
14:     solid_triangles: Vec<[u32; 3]>,
15:     #[serde(with = "crate::geometry_transport")]
16:     support_triangles: Vec<[u32; 3]>,
17:     #[serde(with = "crate::geometry_transport")]
18:     cut_faces: Vec<[Vec3; 3]>,
19: }
20: 
21: #[derive(Serialize, Deserialize)]
22: struct FoundationCells {
23:     property_id: CityPropertyId,
24:     member_building_ids: Vec<crate::scene_input::SceneBuildingId>,
25:     #[serde(with = "crate::geometry_transport::binary")]
26:     positions: Vec<Vec3>,
27:     #[serde(with = "crate::geometry_transport::binary")]
28:     cut_faces: Vec<[Vec3; 3]>,
29: }
30: 
31: /// Borrow geometry during encoding rather than cloning a settlement's cells.
32: #[derive(Serialize)]
33: struct FoundationCellsRef<'a> {
34:     property_id: CityPropertyId,
35:     member_building_ids: &'a [crate::scene_input::SceneBuildingId],
36:     #[serde(with = "crate::geometry_transport::binary")]
37:     positions: &'a [Vec3],
38:     #[serde(with = "crate::geometry_transport::binary")]
39:     cut_faces: &'a [[Vec3; 3]],
40: }
41: 
42: #[derive(Debug, thiserror::Error)]
43: enum FoundationEncodingIssue {
44:     #[error("foundation must contain complete six-vertex cells within u32 indexing")]
45:     Cells,
46:     #[error("foundation indices differ from the closed six-vertex prism topology")]
47:     Topology,
48: }
49: 
50: fn cell_count(positions: &[Vec3]) -> Result<usize, FoundationEncodingIssue> {
51:     if !positions.len().is_multiple_of(6) || u32::try_from(positions.len()).is_err() {
52:         return Err(FoundationEncodingIssue::Cells);
53:     }
54:     Ok(positions.len() / 6)
55: }
56: 
57: impl Serialize for PropertyFoundationMesh {
58:     fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
59:         self.validate().map_err(serde::ser::Error::custom)?;
60:         if serializer.is_human_readable() {
61:             return FoundationDocument::serialize(self, serializer);
62:         }
63:         let cells = cell_count(&self.positions).map_err(serde::ser::Error::custom)?;
64:         let topology_matches = self.support_triangles.len() == cells
65:             && self.solid_triangles.len() == cells * FOUNDATION_PRISM_TRIANGLES.len()
66:             && (0..cells).all(|cell| {
67:                 let start = (cell * 6) as u32;
68:                 self.support_triangles[cell] == [start, start + 2, start + 1]
69:                     && self.solid_triangles[cell * FOUNDATION_PRISM_TRIANGLES.len()
70:                         ..(cell + 1) * FOUNDATION_PRISM_TRIANGLES.len()]
71:                         == FOUNDATION_PRISM_TRIANGLES.map(|t| t.map(|i| i + start))
72:             });
73:         if !topology_matches {
74:             return Err(serde::ser::Error::custom(FoundationEncodingIssue::Topology));
75:         }
76:         FoundationCellsRef {
77:             property_id: self.property_id,
78:             member_building_ids: &self.member_building_ids,
79:             positions: &self.positions,
80:             cut_faces: &self.cut_faces,
81:         }
82:         .serialize(serializer)
83:     }
84: }
85: 
86: impl<'de> Deserialize<'de> for PropertyFoundationMesh {
87:     fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
88:         if deserializer.is_human_readable() {
89:             let mesh = FoundationDocument::deserialize(deserializer)?;
90:             mesh.validate().map_err(D::Error::custom)?;
91:             return Ok(mesh);
92:         }
93:         let cells = FoundationCells::deserialize(deserializer)?;
94:         let count = cell_count(&cells.positions).map_err(D::Error::custom)?;
95:         let mut mesh = Self {
96:             property_id: cells.property_id,
97:             member_building_ids: cells.member_building_ids,
98:             positions: cells.positions,
99:             cut_faces: cells.cut_faces,
100:             solid_triangles: Vec::with_capacity(count * FOUNDATION_PRISM_TRIANGLES.len()),
101:             support_triangles: Vec::with_capacity(count),
102:         };
103:         for cell in 0..count {
104:             let start = (cell * 6) as u32;
105:             mesh.support_triangles.push([start, start + 2, start + 1]);
106:             mesh.solid_triangles
107:                 .extend(FOUNDATION_PRISM_TRIANGLES.map(|t| t.map(|i| i + start)));
108:         }
109:         mesh.validate().map_err(D::Error::custom)?;
110:         Ok(mesh)
111:     }
112: }
