42: /// A minimum deficit and maximum excess have opposite subtraction directions.
43: /// Exact comparisons report the absolute discrepancy.
44: #[derive(Clone, Copy, Debug, PartialEq, Serialize)]
45: #[serde(rename_all = "snake_case")]
46: pub enum BoundViolation<T> {
47:     Minimum { actual: T, required: T },
48:     Maximum { actual: T, permitted: T },
49:     Exact { actual: T, required: T },
50: }
51: impl<T: Copy> BoundViolation<T> {
52:     fn controls(self) -> ViolationControls<T> {
53:         match self {
54:             Self::Minimum { actual, required } => ViolationControls {
55:                 actual,
56:                 limit: required,
57:                 bound: SupportBound::Minimum,
58:             },
59:             Self::Maximum { actual, permitted } => ViolationControls {
60:                 actual,
61:                 limit: permitted,
62:                 bound: SupportBound::Maximum,
63:             },
64:             Self::Exact { actual, required } => ViolationControls {
65:                 actual,
66:                 limit: required,
67:                 bound: SupportBound::Exact,
68:             },
69:         }
70:     }
71:     fn with_bound(self, bound: SupportBound) -> Self {
72:         let ViolationControls { actual, limit, .. } = self.controls();
73:         match bound {
74:             SupportBound::Minimum => Self::Minimum {
75:                 actual,
76:                 required: limit,
77:             },
78:             SupportBound::Maximum => Self::Maximum {
79:                 actual,
80:                 permitted: limit,
81:             },
82:             SupportBound::Exact => Self::Exact {
83:                 actual,
84:                 required: limit,
85:             },
86:         }
87:     }
88: }
