90: /// A comparison cannot mix lengths, areas or cardinalities.
91: /// ```compile_fail
92: /// use adventuresim_tactical_core::city_layout::grounding::{BoundViolation, DiagnosticMetres, DiagnosticCount};
93: /// let comparison = BoundViolation::Maximum {
94: ///     actual: DiagnosticMetres::from_metres(2.0).unwrap(),
95: ///     permitted: DiagnosticCount::new(1),
96: /// };
97: /// ```
98: #[derive(Clone, Copy, Debug, PartialEq, Serialize)]
99: #[serde(rename_all = "snake_case")]
100: pub enum SupportViolation {
101:     Metres(BoundViolation<DiagnosticMetres>),
102:     SquareMetres(BoundViolation<DiagnosticArea>),
103:     Count(BoundViolation<DiagnosticCount>),
104:     /// A numerical kernel could not produce a finite measurement.
105:     Unmeasurable {
106:         unit: SupportDiagnosticUnit,
107:         bound: SupportBound,
108:     },
109: }
110: impl SupportViolation {
111:     /// Native diagnostic adapter for finite solver controls. This port chooses
112:     /// units from the preventing constraint; values never re-enter geometry.
113:     pub(super) fn maximum(unit: SupportDiagnosticUnit, actual: f64, permitted: f64) -> Self {
114:         match unit {
115:             SupportDiagnosticUnit::Metres => match (
116:                 DiagnosticMetres::from_metres(actual),
117:                 DiagnosticMetres::from_metres(permitted),
118:             ) {
119:                 (Some(actual), Some(permitted)) => {
120:                     Self::Metres(BoundViolation::Maximum { actual, permitted })
121:                 }
122:                 _ => Self::Unmeasurable {
123:                     unit,
124:                     bound: SupportBound::Maximum,
125:                 },
126:             },
127:             SupportDiagnosticUnit::SquareMetres => match (
128:                 DiagnosticArea::from_square_metres(actual),
129:                 DiagnosticArea::from_square_metres(permitted),
130:             ) {
131:                 (Some(actual), Some(permitted)) => {
132:                     Self::SquareMetres(BoundViolation::Maximum { actual, permitted })
133:                 }
134:                 _ => Self::Unmeasurable {
135:                     unit,

136:                     bound: SupportBound::Maximum,
137:                 },
138:             },
139:             SupportDiagnosticUnit::Count
140:                 if actual.is_finite()
141:                     && actual >= 0.0
142:                     && permitted.is_finite()
143:                     && permitted >= 0.0 =>
144:             {
145:                 Self::Count(BoundViolation::Maximum {
146:                     actual: DiagnosticCount(actual as u64),
147:                     permitted: DiagnosticCount(permitted as u64),
148:                 })
149:             }
150:             _ => Self::Unmeasurable {
151:                 unit,
152:                 bound: SupportBound::Maximum,
153:             },
154:         }
155:     }
156:     pub(super) fn with_bound(self, bound: SupportBound) -> Self {
157:         match self {
158:             Self::Metres(v) => Self::Metres(v.with_bound(bound)),
159:             Self::SquareMetres(v) => Self::SquareMetres(v.with_bound(bound)),
160:             Self::Count(v) => Self::Count(v.with_bound(bound)),
161:             Self::Unmeasurable { unit, .. } => Self::Unmeasurable { unit, bound },
162:         }
163:     }
164:     pub fn unit(self) -> SupportDiagnosticUnit {
165:         match self {
166:             Self::Metres(_) => SupportDiagnosticUnit::Metres,
167:             Self::SquareMetres(_) => SupportDiagnosticUnit::SquareMetres,
168:             Self::Count(_) => SupportDiagnosticUnit::Count,
169:             Self::Unmeasurable { unit, .. } => unit,
170:         }
171:     }
172:     /// Presentation/test numerical port. Unmeasurable controls remain explicit
173:     /// in the structured error; infinity here conveys them only to formatting.
174:     pub fn actual_value(self) -> f64 {
175:         self.values().actual
176:     }
177:     pub fn limit_value(self) -> f64 {
178:         self.values().limit
179:     }
180:     pub fn discrepancy_value(self) -> f64 {
181:         let ViolationControls {
182:             actual,
183:             limit,
184:             bound,
185:         } = self.values();
186:         match bound {
187:             SupportBound::Minimum => (limit - actual).max(0.0),
188:             SupportBound::Maximum => (actual - limit).max(0.0),
189:             SupportBound::Exact => (actual - limit).abs(),
190:         }
191:     }
192:     fn values(self) -> ViolationControls<f64> {
193:         match self {
194:             Self::Metres(v) => {
195:                 let c = v.controls();
196:                 ViolationControls {
197:                     actual: c.actual.0,
198:                     limit: c.limit.0,
199:                     bound: c.bound,
200:                 }
201:             }
202:             Self::SquareMetres(v) => {
203:                 let c = v.controls();
204:                 ViolationControls {
205:                     actual: c.actual.0,
206:                     limit: c.limit.0,
207:                     bound: c.bound,
208:                 }
209:             }
210:             Self::Count(v) => {
211:                 let c = v.controls();
212:                 ViolationControls {
213:                     actual: c.actual.0 as f64,
214:                     limit: c.limit.0 as f64,
215:                     bound: c.bound,
216:                 }
217:             }
218:             Self::Unmeasurable { bound, .. } => ViolationControls {
219:                 actual: f64::INFINITY,
220:                 limit: 0.0,
221:                 bound,
222:             },
223:         }
224:     }
225: }
