52: impl PropertySupportMesh {
53:     pub fn property_id(&self) -> CityPropertyId {
54:         self.property_id
55:     }
56:     pub fn member_building_ids(&self) -> &[crate::scene_input::SceneBuildingId] {
57:         &self.member_building_ids
58:     }
59:     /// Finite native scene-metre vertices at the mesh upload/physics boundary.
60:     pub fn positions(&self) -> &[Vec3] {
61:         &self.positions
62:     }
63:     pub fn support_triangles(&self) -> &[[u32; 3]] {
64:         &self.support_triangles
65:     }
66:     pub fn retaining_triangles(&self) -> &[[u32; 3]] {
67:         &self.retaining_triangles
68:     }
69:     fn validate_geometry(&self) -> Result<(), SupportSurfaceIssue> {
70:         if self.property_id.0 == 0
71:             || self.member_building_ids.is_empty()
72:             || self
73:                 .member_building_ids
74:                 .iter()
75:                 .enumerate()
76:                 .any(|(i, id)| id.0 == 0 || self.member_building_ids[..i].contains(id))
77:         {
78:             return Err(SupportSurfaceIssue::Members);
79:         }
80:         if !self.contact_tolerance_metres.is_finite()
81:             || self.contact_tolerance_metres <= 0.0
82:             || self.positions.iter().any(|p| !p.is_finite())
83:         {
84:             return Err(SupportSurfaceIssue::Bounds);
85:         }
86:         if self.positions.len() > u32::MAX as usize
87:             || self.support_triangles.is_empty()
88:             || self
89:                 .support_triangles
90:                 .iter()
91:                 .chain(&self.retaining_triangles)
92:                 .any(|t| {
93:                     t.iter().any(|i| *i as usize >= self.positions.len())
94:                         || t[0] == t[1]
95:                         || t[1] == t[2]
96:                         || t[2] == t[0]
97:                 })
98:         {
99:             return Err(SupportSurfaceIssue::Topology);
100:         }
101:         Ok(())
102:     }
103: 
104:     /// The same support and retaining triangles used by physical traversal.
105:     /// This surface collider does not establish a finite foundation volume.
106:     pub fn collider(&self) -> Result<avian3d::prelude::Collider, SupportColliderError> {
107:         avian3d::prelude::Collider::try_trimesh(
108:             self.positions.clone(),
109:             self.support_triangles
110:                 .iter()
111:                 .chain(&self.retaining_triangles)
112:                 .copied()
113:                 .collect(),
114:         )
115:         .map_err(|cause| SupportColliderError::Surface {
116:             property: self.property_id,
117:             members: self.member_building_ids.clone(),
118:             cause,
119:         })
120:     }
