3: impl PropertySupportMesh {
4:     pub(super) fn vertex_start(&self, added: usize, point: Vec2) -> Result<u32, SupportDiagnostic> {
5:         let total = self.positions.len().checked_add(added);
6:         let within = total.and_then(|count| u32::try_from(count).ok());
7:         let reject = |actual: Option<usize>| {
8:             let mut error = SupportDiagnostic::for_mesh(
9:                 self,
10:                 SupportConstraint::MeshIndexCapacity,
11:                 point,
12:                 0.0,
13:                 0.0,
14:             );
15:             error.violation = match actual.and_then(|n| u64::try_from(n).ok()) {
16:                 Some(actual) => SupportViolation::Count(BoundViolation::Maximum {
17:                     actual: DiagnosticCount::new(actual),
18:                     permitted: DiagnosticCount::new(u64::from(u32::MAX)),
19:                 }),
20:                 None => SupportViolation::Unmeasurable {
21:                     unit: SupportDiagnosticUnit::Count,
22:                     bound: SupportBound::Maximum,
23:                 },
24:             };
25:             error
26:         };
27:         if within.is_none() {
28:             return Err(reject(total));
29:         }
30:         u32::try_from(self.positions.len()).map_err(|_| reject(Some(self.positions.len())))
31:     }
32: }
