10:     ) -> Result<Self, SupportDiagnostic> {
11:         let mut mesh = Self::empty_for_compound(plan);
12:         let CompoundGrid {
13:             xs,
14:             zs,
15:             begin,
16:             sign,
17:         } = CompoundGrid::from_plan(plan);
18:         let columns = xs.len() - 1;
19:         let mut cells = Vec::new();
20:         for z in zs.windows(2) {
21:             for x in xs.windows(2) {
22:                 let centre = Vec2::new((x[0] + x[1]) * 0.5, (z[0] + z[1]) * 0.5);
23:                 let point = plan.property.plot.centre_metres()
24:                     + plan.property.plot.orientation().local_to_world(centre);
25:                 if plan
26:                     .street_entry
27:                     .as_ref()
28:                     .is_some_and(|entry| entry.support_region.contains(point))
29:                 {
30:                     cells.push(None);
31:                     continue;
32:                 }
33:                 let side = plan.property.boundary.gate.hinge.opposite().sign();
34:                 let heights = if (centre.x - plan.split_frontage_metres) * side > 0.0 {
35:                     [
36:                         profile_height(plan, z[0], begin, sign)?,
37:                         profile_height(plan, z[1], begin, sign)?,
38:                     ]
39:                 } else {
40:                     [plan.main_height(centre).ok_or_else(|| SupportDiagnostic::framed_geometry(
41:                         &plan.property, point, adventuresim_building_generator::spatial_geometry::GeometryError::InvalidProjection))?; 2]
42:                 };
43:                 let points = [
44:                     world(plan, x[0], z[0], heights[0]),
45:                     world(plan, x[1], z[0], heights[0]),
46:                     world(plan, x[1], z[1], heights[1]),
47:                     world(plan, x[0], z[1], heights[1]),
48:                 ];
49:                 mesh.quad(points, SupportFaceRole::Bearing)?;
50:                 cells.push(Some(SupportCell(points)));
51:             }
52:         }
53:         append_retaining_faces(&mut mesh, &cells, columns)?;
54:         append_street_approach(
55:             plan,
56:             &mut mesh,
57:             begin,
58:             sign,
59:             plan.property.plot.dimensions_metres().y * 0.5,
60:         )?;
61:         Ok(mesh)
62:     }
63: }
64: 
65: fn world(plan: &CompoundSupportPlan, x: f32, z: f32, height: SupportElevation) -> Vec3 {
66:     let p = plan.property.plot.centre_metres()
67:         + plan
68:             .property
69:             .plot
70:             .orientation()
71:             .local_to_world(Vec2::new(x, z));
72:     Vec3::new(p.x, height.metres(), p.y)
73: }
74: 
75: fn bounded_cuts(cuts: &mut Vec<f32>, half: f32, tolerance: f32) {
76:     cuts.retain(|v| *v >= -half && *v <= half);
77:     cuts.sort_by(f32::total_cmp);
78:     // Independently transformed landings can differ by float rounding. Their
79:     // declared contact tolerance prevents microscopic, ill-conditioned cells.
80:     cuts.dedup_by(|a, b| (*a - *b).abs() <= tolerance);
81: }
82: 
83: fn append_retaining_faces(
84:     mesh: &mut PropertySupportMesh,
85:     cells: &[Option<SupportCell>],
86:     columns: usize,
87: ) -> Result<(), SupportDiagnostic> {
88:     for (i, cell) in cells.iter().enumerate() {
89:         let Some(SupportCell(a)) = cell else { continue };
90:         let mut edges = Vec::new();
91:         if i % columns + 1 < columns
92:             && let Some(SupportCell(b)) = cells[i + 1]
93:         {
94:             edges.push([a[1], a[2], b[3], b[0]]);
95:         }
96:         if i + columns < cells.len()
97:             && let Some(SupportCell(b)) = cells[i + columns]
98:         {
99:             edges.push([a[3], a[2], b[1], b[0]]);
100:         }
101:         for edge in edges {
102:             if (edge[0].y - edge[3].y).abs() > mesh.contact_tolerance_metres
103:                 || (edge[1].y - edge[2].y).abs() > mesh.contact_tolerance_metres
104:             {
105:                 mesh.quad(edge, SupportFaceRole::Retaining)?;
106:             }
107:         }
108:     }
109:     Ok(())
110: }
111: 
112: fn append_street_approach(
113:     plan: &CompoundSupportPlan,
114:     mesh: &mut PropertySupportMesh,
115:     begin: f32,
116:     sign: f32,
117:     half_depth: f32,
118: ) -> Result<(), SupportDiagnostic> {
119:     let boundary = begin.clamp(-half_depth, half_depth);
120:     let mut rows = vec![begin, boundary];
121:     let range = begin.min(boundary)..=begin.max(boundary);
122:     rows.extend(
123:         plan.passage_profile
124:             .points()
125:             .map(|p| begin + sign * p.coordinate.metres())
126:             .filter(|z| range.contains(z)),
127:     );
128:     rows.sort_by(f32::total_cmp);
129:     rows.dedup_by(|a, b| (*a - *b).abs() <= plan.limits.contact_tolerance_metres.metres());
130:     let centre = plan
131:         .property
132:         .plot
133:         .orientation()
134:         .world_to_local(plan.passage.start_metres() - plan.property.plot.centre_metres())
135:         .x;
136:     let half_width = plan.passage.half_width_metres();
137:     for band in rows.windows(2) {
138:         let heights = [
139:             profile_height(plan, band[0], begin, sign)?,
140:             profile_height(plan, band[1], begin, sign)?,

141:         ];
142:         mesh.quad(
143:             [
144:                 world(plan, centre - half_width, band[0], heights[0]),
145:                 world(plan, centre + half_width, band[0], heights[0]),
146:                 world(plan, centre + half_width, band[1], heights[1]),
147:                 world(plan, centre - half_width, band[1], heights[1]),
148:             ],
149:             SupportFaceRole::Bearing,
150:         )?;
151:     }
152:     Ok(())
153: }
154: 
155: fn profile_height(
156:     plan: &CompoundSupportPlan,
157:     ordinate: f32,
158:     begin: f32,
159:     sign: f32,
160: ) -> Result<SupportElevation, SupportDiagnostic> {
161:     let coordinate =
162:         ProfileCoordinate::from_metres((ordinate - begin) * sign).ok_or_else(|| {
163:             SupportDiagnostic::new(
164:                 &plan.property,
165:                 SupportConstraint::Reservation,
166:                 SupportBoundary::GateLanding,
167:                 plan.passage.start_metres(),
168:                 1.0,
169:                 0.0,
170:             )
171:         })?;
172:     Ok(plan.passage_profile.height_at(coordinate))
173: }
174: 
175: /// Native plot-local metre partitions shared by mesh authoring and floor records.
176: struct CompoundGrid {
177:     xs: Vec<f32>,
178:     zs: Vec<f32>,
179:     begin: f32,
180:     sign: f32,
181: }
182: impl CompoundGrid {
183:     fn from_plan(plan: &CompoundSupportPlan) -> Self {
184:         let half = plan.property.plot.dimensions_metres() * 0.5;
185:         let local = |point| {
186:             plan.property
187:                 .plot
188:                 .orientation()
189:                 .world_to_local(point - plan.property.plot.centre_metres())
190:         };
191:         let begin = local(plan.passage.start_metres()).y;
192:         let sign = (local(plan.passage.end_metres()).y - begin).signum();
193:         let mut xs = vec![-half.x, half.x, plan.split_frontage_metres];
194:         let mut zs = vec![-half.y, half.y];
195:         zs.extend(plan.court_profile.points().map(|p| p.coordinate.metres()));
196:         zs.extend(
197:             plan.passage_profile
198:                 .points()
199:                 .map(|p| begin + sign * p.coordinate.metres()),
200:         );
201:         for stair in &plan.court_stairs {
202:             let (x, z) = stair.local_cuts();
203:             xs.extend(x);
204:             zs.extend(z);
205:         }
206:         if let Some(entry) = &plan.street_entry {
207:             for corner in entry.support_region.corners() {
208:                 let point = local(corner);
209:                 xs.push(point.x);
210:                 zs.push(point.y);
211:             }
212:         }
213:         bounded_cuts(
214:             &mut xs,
215:             half.x,
216:             plan.limits.contact_tolerance_metres.metres(),
217:         );
218:         bounded_cuts(
219:             &mut zs,
220:             half.y,
221:             plan.limits.contact_tolerance_metres.metres(),
222:         );
223:         Self {
224:             xs,
225:             zs,
226:             begin,
227:             sign,
228:         }
229:     }
230: }
231: pub(in crate::city_layout::grounding) fn floor_regions(
232:     plan: &CompoundSupportPlan,
233:     member: MemberSupport,
234: ) -> Result<Vec<surface::FloorRegion>, surface::FloorBearingConstructionError> {
235:     use crate::scene_coordinates::{ScenePlanPoint, ScenePlanPolygon};
236:     let grid = CompoundGrid::from_plan(plan);
237:     let breaks: Vec<_> = plan
238:         .court_profile
239:         .points()
240:         .map(|p| p.coordinate.metres())
241:         .collect();
242:     let mut regions = Vec::new();
243:     for z in grid.zs.windows(2) {
244:         for x in grid.xs.windows(2) {
245:             let centre = Vec2::new((x[0] + x[1]) * 0.5, (z[0] + z[1]) * 0.5);
246:             let point = plan.property.plot.centre_metres()
247:                 + plan.property.plot.orientation().local_to_world(centre);
248:             let on_member_plateau = if member.building_id == plan.levels.front.building_id {
249:                 centre.y <= breaks[1]
250:             } else {
251:                 centre.y >= breaks[breaks.len() - 2]
252:             };
253:             let main_side = (centre.x - plan.split_frontage_metres)
254:                 * plan.property.boundary.gate.hinge.opposite().sign()
255:                 <= 0.0;
256:             if !on_member_plateau
257:                 || !main_side
258:                 || plan.main_height(centre) != Some(member.elevation)
259:                 || plan
260:                     .street_entry
261:                     .as_ref()
262:                     .is_some_and(|entry| entry.support_region.contains(point))
263:             {
264:                 continue;
265:             }
266:             regions.push(surface::FloorRegion::from_scene(
267:                 ScenePlanPolygon::from_ordered_vertices(
268:                     [(x[0], z[0]), (x[1], z[0]), (x[1], z[1]), (x[0], z[1])]
269:                         .into_iter()
270:                         .map(|(x, z)| {
271:                             ScenePlanPoint::try_from(world(plan, x, z, SupportElevation::ZERO).xz())
272:                         })
273:                         .collect::<Result<Vec<_>, _>>()?,
274:                 )?,
275:             )?);
276:         }
277:     }
278:     Ok(regions)
279: }

1: //! A doorway landing inside its own bearing must not duplicate the floor.
2: use super::*;
3: use crate::city_layout::grounding::foundations::GroundTriangle;
4: 
5: impl PropertySupportMesh {
6:     pub(in crate::city_layout::grounding) fn append_outside_floor(
7:         &mut self,
8:         other: &Self,
9:         floor: &[bevy::math::DVec2],
10:     ) -> Result<(), SupportDiagnostic> {
11:         for indices in &other.support_triangles {
12:             let triangle = GroundTriangle::new(indices.map(|i| other.positions[i as usize]))
13:                 .ok_or_else(|| {
14:                     SupportDiagnostic::for_mesh(
15:                         self,
16:                         SupportConstraint::Reservation,
17:                         other.positions[indices[0] as usize].xz(),
18:                         1.0,
19:                         0.0,
20:                     )
21:                 })?;
22:             for piece in triangle.outside_outline(floor) {
23:                 let [a, b, c] = piece.points();
24:                 let start = self.vertex_start(3, a.xz())?;
25:                 self.positions.extend([a, c, b]);
26:                 self.support_triangles.push([start, start + 1, start + 2]);
27:             }
28:         }
29:         for indices in &other.retaining_triangles {
30:             let start = self.vertex_start(3, other.positions[indices[0] as usize].xz())?;
31:             self.positions
32:                 .extend(indices.map(|i| other.positions[i as usize]));
33:             self.retaining_triangles.push([start, start + 1, start + 2]);
34:         }
35:         Ok(())
36:     }
37: }

1: //! Conservative broad phase preserves exact clipping and canonical input order.
2: use bevy::math::DVec2;
3: 
4: /// Structural branching capacity; this does not prescribe terrain resolution.
5: const PLANAR_QUERY_LEAF_REGIONS: usize = 8;
6: 
7: #[derive(Clone, Copy, Debug)]
8: pub(in crate::city_layout::grounding) struct PlanarBounds {
9:     minimum: DVec2,
10:     maximum: DVec2,
11: }
12: 
13: impl PlanarBounds {
14:     pub fn from_triangle(points: [crate::scene_coordinates::ScenePlanPoint; 3]) -> Self {
15:         let [first, second, third] = points.map(|point| point.metres().as_dvec2());
16:         Self {
17:             minimum: first.min(second).min(third),
18:             maximum: first.max(second).max(third),
19:         }
20:     }
21:     pub fn from_points(points: impl IntoIterator<Item = DVec2>) -> Option<Self> {
22:         let mut points = points.into_iter();
23:         let first = points.next()?;
24:         if !first.is_finite() {
25:             return None;
26:         }
27:         points.try_fold(
28:             Self {
29:                 minimum: first,
30:                 maximum: first,
31:             },
32:             |bounds, point| {
33:                 point.is_finite().then_some(Self {
34:                     minimum: bounds.minimum.min(point),
35:                     maximum: bounds.maximum.max(point),
36:                 })
37:             },
38:         )
39:     }
40: 
41:     pub fn expanded(self, distance: f64) -> Self {
42:         Self {
43:             minimum: self.minimum - DVec2::splat(distance),
44:             maximum: self.maximum + DVec2::splat(distance),
45:         }
46:     }
47: 
48:     fn union(self, other: Self) -> Self {
49:         Self {
50:             minimum: self.minimum.min(other.minimum),
51:             maximum: self.maximum.max(other.maximum),
52:         }
53:     }
54: 
55:     pub fn intersects(self, other: Self) -> bool {
56:         !self.minimum.cmpgt(other.maximum).any() && !self.maximum.cmplt(other.minimum).any()
57:     }
58: }
59: 
60: #[derive(Clone, Debug)]
61: enum QueryChildren {
62:     Branch { left: usize, right: usize },
63:     Leaf(Vec<usize>),
64: }
65: 
66: #[derive(Clone, Debug)]
67: struct QueryNode {
68:     bounds: PlanarBounds,
69:     children: QueryChildren,
70: }
71: 
72: /// References address the unchanged source collection. Results retain its
73: /// iteration order, including ties on shared edges and overlapping inputs.
74: /// This producer-only index is not a generated or serialized terrain product.
75: #[derive(Clone, Debug)]
76: pub(in crate::city_layout::grounding) struct PlanarQueryIndex {
77:     bounds: Vec<PlanarBounds>,
78:     nodes: Vec<QueryNode>,
79: }
80: 
81: impl PlanarQueryIndex {
82:     pub fn from_bounds(bounds: Vec<PlanarBounds>) -> Self {
83:         let mut index = Self {
84:             bounds,
85:             nodes: Vec::new(),
86:         };
87:         let mut regions: Vec<_> = (0..index.bounds.len()).collect();
88:         if !regions.is_empty() {
89:             index.append(&mut regions);
90:         }
91:         index
92:     }
93: 
94:     fn append(&mut self, regions: &mut [usize]) -> usize {
95:         // The root is guarded as nonempty; both recursive partitions follow
96:         // the leaf-capacity check and split strictly inside the slice.
97:         let bounds = regions[1..]
98:             .iter()
99:             .fold(self.bounds[regions[0]], |bounds, index| {
100:                 bounds.union(self.bounds[*index])
101:             });
102:         let node = self.nodes.len();
103:         self.nodes.push(QueryNode {
104:             bounds,
105:             children: QueryChildren::Leaf(Vec::new()),
106:         });
107:         let children = if regions.len() <= PLANAR_QUERY_LEAF_REGIONS {
108:             QueryChildren::Leaf(regions.to_vec())
109:         } else {
110:             let extent = bounds.maximum - bounds.minimum;
111:             let axis = usize::from(extent.y > extent.x);
112:             let centre = |i: &usize| self.bounds[*i].minimum[axis] + self.bounds[*i].maximum[axis];
113:             let midpoint = regions.len() / 2;
114:             // Only the two membership sets are needed here. Queries restore
115:             // authoritative source order after visiting the matching leaves.
116:             regions.select_nth_unstable_by(midpoint, |a, b| {
117:                 centre(a).total_cmp(&centre(b)).then(a.cmp(b))
118:             });
119:             let (left, right) = regions.split_at_mut(midpoint);
120:             QueryChildren::Branch {
121:                 left: self.append(left),
122:                 right: self.append(right),
123:             }
124:         };
125:         self.nodes[node].children = children;

1: //! Ordered support sequences distinguish walkable grades from retaining steps.
2: use super::*;
3: 
4: /// Finite signed ordinate along a bound profile, in metres.
5: #[derive(Clone, Copy, Debug, PartialEq)]
6: pub(super) struct ProfileCoordinate(f32);
7: impl ProfileCoordinate {
8:     pub const ZERO: Self = Self(0.0);
9:     pub fn from_metres(metres: f32) -> Option<Self> {
10:         metres.is_finite().then_some(Self(metres))
11:     }
12:     pub fn metres(self) -> f32 {
13:         self.0
14:     }
15: }
16: 
17: #[derive(Clone, Copy, Debug, PartialEq)]
18: pub(super) struct ProfilePoint {
19:     pub coordinate: ProfileCoordinate,
20:     pub elevation: SupportElevation,
21: }
22: impl ProfilePoint {
23:     pub fn at_metres(coordinate: f32, elevation: SupportElevation) -> Option<Self> {
24:         elevation.metres().is_finite().then_some(Self {
25:             coordinate: ProfileCoordinate::from_metres(coordinate)?,
26:             elevation,
27:         })
28:     }
29: }
30: 
31: #[derive(Clone, Copy, Debug, PartialEq)]
32: pub(super) enum ProfileError {
33:     Empty,
34:     InvalidElevation { coordinate: ProfileCoordinate },
35:     Reversed { coordinate: ProfileCoordinate },
36: }
37: impl ProfileError {
38:     pub fn coordinate(self) -> ProfileCoordinate {
39:         match self {
40:             Self::Empty => ProfileCoordinate::ZERO,
41:             Self::InvalidElevation { coordinate } | Self::Reversed { coordinate } => coordinate,
42:         }
43:     }
44: }
45: 
46: /// Nonempty finite ordered storage. Repeated ordinates represent vertical
47: /// retaining faces. Walkability is additionally checked at passage construction.
48: #[derive(Clone, Debug, PartialEq)]
49: pub(super) struct SupportProfile {
50:     first: ProfilePoint,
51:     remainder: Vec<ProfilePoint>,
52: }
53: #[derive(Clone, Copy)]
54: pub(super) enum FloorBasisRole {
55:     Court,
56:     PassageTerminalLanding,
57: }
58: impl SupportProfile {
59:     pub fn stepped(points: Vec<ProfilePoint>) -> Result<Self, ProfileError> {
60:         let mut points = points.into_iter();
61:         let first = points.next().ok_or(ProfileError::Empty)?;
62:         let remainder: Vec<_> = points.collect();
63:         let profile = Self { first, remainder };
64:         let mut previous = first.coordinate;
65:         for point in profile.points() {
66:             if !point.elevation.metres().is_finite() {
67:                 return Err(ProfileError::InvalidElevation {
68:                     coordinate: point.coordinate,
69:                 });
70:             }
71:             if point.coordinate.metres() < previous.metres() {
72:                 return Err(ProfileError::Reversed {
73:                     coordinate: point.coordinate,
74:                 });
75:             }
76:             previous = point.coordinate;
77:         }
78:         Ok(profile)
79:     }
80: 
81:     pub fn points(&self) -> impl DoubleEndedIterator<Item = &ProfilePoint> {
82:         std::iter::once(&self.first).chain(self.remainder.iter())
83:     }
84: 
85:     pub fn checked(
86:         property: &CityCompound,
87:         points: Vec<ProfilePoint>,
88:         limits: SupportLimits,
89:         boundary: SupportBoundary,
90:         location_at: impl Fn(ProfileCoordinate) -> Vec2,
91:     ) -> Result<Self, SupportDiagnostic> {
92:         // Preserve the passage's strict ordering/grade rejection separately
93:         // from the stepped court's nondecreasing-order storage invariant.
94:         for pair in points.windows(2) {
95:             let run = pair[1].coordinate.metres() - pair[0].coordinate.metres();
96:             let rise = (pair[1].elevation.metres() - pair[0].elevation.metres()).abs();
97:             let permitted = run.max(0.0) * limits.maximum_grade.ratio();
98:             if run <= 0.0 || rise > permitted + limits.contact_tolerance_metres.metres() {
99:                 return Err(SupportDiagnostic::new(
100:                     property,
101:                     SupportConstraint::AccessGrade,
102:                     boundary,
103:                     location_at(pair[0].coordinate),
104:                     rise,
105:                     permitted,
106:                 ));
107:             }
108:         }
109:         Self::stepped(points).map_err(|error| {
110:             SupportDiagnostic::new(
111:                 property,
112:                 SupportConstraint::Reservation,
113:                 boundary,
114:                 location_at(error.coordinate()),
115:                 1.0,
116:                 0.0,
117:             )
118:         })
119:     }
120: 
121:     pub fn height_at(&self, coordinate: ProfileCoordinate) -> SupportElevation {
122:         let distance = coordinate.metres();
123:         if distance <= self.first.coordinate.metres() {
124:             return self.first.elevation;
125:         }
126:         let mut previous = self.first;
127:         for next in &self.remainder {
128:             if distance <= next.coordinate.metres() {
129:                 let run = next.coordinate.metres() - previous.coordinate.metres();
130:                 let fraction = (distance - previous.coordinate.metres()) / run;

131:                 let value = previous.elevation.metres()
132:                     + fraction * (next.elevation.metres() - previous.elevation.metres());
133:                 if run.is_finite() && value.is_finite() {
134:                     return SupportElevation(value);
135:                 }
136:                 let fraction = (f64::from(distance) - f64::from(previous.coordinate.metres()))
137:                     / (f64::from(next.coordinate.metres())
138:                         - f64::from(previous.coordinate.metres()));
139:                 let begin = f64::from(previous.elevation.metres());
140:                 let end = f64::from(next.elevation.metres());
141:                 return SupportElevation((begin * (1.0 - fraction) + end * fraction) as f32);
142:             }
143:             previous = *next;
144:         }
145:         previous.elevation
146:     }
147: 
148:     /// Affine-response probes preserve the sequence invariant. They do not
149:     /// certify a changed passage grade and cannot bypass final plan acceptance.
150:     pub fn translated_for_floor_basis(&self, role: FloorBasisRole) -> Result<Self, ProfileError> {
151:         let mut points: Vec<_> = self.points().copied().collect();
152:         let begin = match role {
153:             FloorBasisRole::Court => 0,
154:             FloorBasisRole::PassageTerminalLanding => points.len().saturating_sub(2),
155:         };
156:         for point in &mut points[begin..] {
157:             point.elevation = SupportElevation::from_metres(point.elevation.metres() + 1.0).ok_or(
158:                 ProfileError::InvalidElevation {
159:                     coordinate: point.coordinate,
160:                 },
161:             )?;
162:         }
163:         Self::stepped(points)
164:     }
165: }
