9: mod tests;
10: 
11: #[derive(Clone, Copy, Debug, PartialEq)]
12: pub struct DoorwaySupportBinding {
13:     pub entrance: adventuresim_building_generator::BuildingEntranceId,
14:     pub support: adventuresim_building_generator::BuildingEntranceSupport,
15:     pub threshold_metres: crate::scene_coordinates::ScenePlanPoint,
16:     pub outward: adventuresim_building_generator::spatial_geometry::PlanDirection<
17:         crate::scene_coordinates::Scene,
18:     >,
19: }
20: 
21: #[derive(Clone, Debug)]
22: pub struct SingleBuildingSupportPlan {
23:     pub property: CitySingleProperty,
24:     pub floor: MemberSupport,
25:     pub thresholds: Vec<DoorwaySupportBinding>,
26:     pub surface: PropertySupportSurface,
27: }
28: 
29: pub struct SingleBuildingSupportRequest<'a> {
30:     pub property: CitySingleProperty,
31:     pub bearing: CityPlotBounds,
32:     pub bearing_region: FloorRegion,
33:     pub thresholds: &'a [DoorwaySupportBinding],
34:     pub geographic: &'a GeographicSurface,
35:     pub streets: &'a [CityStreetPatch],
36:     pub policy: SinglePropertyGradingPolicy,
37: }
38: 
39: impl SingleBuildingSupportRequest<'_> {
40:     /// Select the architectural floor from an exact ground doorway, then prove
41:     /// complete source intersections and all doorway approaches. Other courts
42:     /// and gardens retain natural terrain; this does not level the whole plot.
43:     pub fn select(self) -> Result<SingleBuildingSupportPlan, SupportDiagnostic> {
44:         let mut surface = PropertySupportSurface::for_single_bearing(&self)?;
45:         let thresholds = self.thresholds.to_vec();
46:         if thresholds.is_empty() {
47:             let mut error = surface.rejection(
48:                 SupportConstraint::ThresholdBinding,
49:                 SupportBoundary::FrontBearing,
50:                 self.bearing.centre_metres(),
51:                 0.0,
52:                 1.0,
53:             );
54:             error.violation = error.violation.with_bound(SupportBound::Minimum);
55:             return Err(error);
56:         }
57:         if let Some(duplicate) = thresholds.iter().enumerate().find_map(|(index, entry)| {
58:             thresholds[..index]
59:                 .iter()
60:                 .any(|previous| previous.entrance == entry.entrance)
61:                 .then_some(entry)
62:         }) {
63:             let mut error = surface.rejection(
64:                 SupportConstraint::ThresholdBinding,
65:                 SupportBoundary::FrontBearing,
66:                 duplicate.threshold_metres.metres(),
67:                 2.0,
68:                 1.0,
69:             );
70:             error.violation = error.violation.with_bound(SupportBound::Exact);
71:             error.entrance = Some(duplicate.entrance);
72:             return Err(error);
73:         }
74:         let mut constructed: Vec<_> = thresholds
75:             .iter()
76:             .filter(|entry| {
77:                 entry.support
78:                     == adventuresim_building_generator::BuildingEntranceSupport::ArchitecturalFloor
79:             })
80:             .collect();
81:         // Retain the admitted entrance order while preserving the established
82:         // lowest-identity floor selection and canonical apron assembly order.
83:         constructed.sort_by_key(|entry| entry.entrance);
84:         let aprons = constructed
85:             .iter()
86:             .map(|door| apron::prepare(&self, **door, &surface))
87:             .collect::<Result<Vec<_>, _>>()?;
88:         let selected = floor::select(&self, &constructed, &aprons, &surface)?;
89:         let elevation = selected.elevation;
90:         surface.floor_bearings = vec![surface::FloorBearing {
91:             building: self.property.building_id,
92:             regions: vec![self.bearing_region.clone()],
93:             elevation,
94:         }];
95:         surface
96:             .mesh
97:             .convex_floor(self.bearing_region.outline(), elevation)?;
98:         for prepared in aprons {
99:             prepared.append_to(&self, elevation, &mut surface)?;
100:         }
101:         surface.validate_source_controls(self.geographic)?;
102:         let surface = surface.admit_generated()?;
103:         Ok(SingleBuildingSupportPlan {
104:             property: self.property,
105:             floor: MemberSupport {
106:                 building_id: self.property.building_id,
107:                 contact: self.bearing,
108:                 court_threshold_metres: selected.threshold,
109:                 elevation,
110:             },
111:             thresholds,
112:             surface,
113:         })
114:     }
115: }

1: //! Door approaches stop inside the owned plot or its near half of the street.
2: use super::*;
3: mod surface;
4: use super::super::access::{access_regions, available_run};
5: 
6: pub(super) fn prepare(
7:     request: &SingleBuildingSupportRequest<'_>,
8:     door: DoorwaySupportBinding,
9:     surface: &PropertySupportSurface,
10: ) -> Result<PreparedApron, SupportDiagnostic> {
11:     let reject = |constraint, point, measured, permitted| {
12:         surface.rejection(
13:             constraint,
14:             SupportBoundary::StreetLanding,
15:             point,
16:             measured,
17:             permitted,
18:         )
19:     };
20:     if !door.outward.vector().is_finite()
21:         || (door.outward.vector().length_squared() - 1.0).abs()
22:             > surface.limits.contact_tolerance_metres.metres()
23:     {
24:         return Err(reject(
25:             SupportConstraint::ThresholdBinding,
26:             door.threshold_metres.metres(),
27:             1.0,
28:             0.0,
29:         ));
30:     }
31:     let direction = door.outward.vector();
32:     let tangent = Vec2::new(direction.y, -direction.x);
33:     let outside = planar::distance_outside(
34:         door.threshold_metres.metres().as_dvec2(),
35:         &surface.clipping_outlines[0],
36:     ) as f32;
37:     if outside > surface.limits.contact_tolerance_metres.metres() {
38:         return Err(reject(
39:             SupportConstraint::ThresholdBearing,
40:             door.threshold_metres.metres(),
41:             outside,
42:             surface.limits.contact_tolerance_metres.metres(),
43:         ));
44:     }
45:     let edge = door.threshold_metres.metres();
46:     let width = request.policy.doorway_apron.dimensions_metres().x;
47:     let offset = tangent * width * 0.5;
48:     let private = vec![
49:         request.property.plot.corners().map(Vec2::as_dvec2).to_vec(),
50:         surface.clipping_outlines[0].clone(),
51:     ];
52:     let mut regions =
53:         access_regions(request.property.plot, request.streets, edge).map_err(|cause| {
54:             let mut error = surface.rejection(
55:                 SupportConstraint::Reservation,
56:                 SupportBoundary::FrontBearing,
57:                 edge,
58:                 1.0,
59:                 0.0,
60:             );
61:             error.construction_failure =
62:                 Some(Box::new(SupportConstructionError::FramedGeometry(cause)));
63:             error
64:         })?;
65:     regions.push(surface.clipping_outlines[0].clone());
66:     let internal_run = available_run(
67:         edge,
68:         direction,
69:         offset,
70:         &private,
71:         f32::INFINITY,
72:         request.policy.limits.contact_tolerance_metres(),
73:     );
74:     let run = available_run(
75:         edge,
76:         direction,
77:         offset,
78:         &regions,
79:         internal_run + request.policy.doorway_apron.dimensions_metres().y,
80:         request.policy.limits.contact_tolerance_metres(),
81:     );
82:     // Keep a contact-sized natural strip at the approach boundary. Opposing
83:     // approaches must not acquire the same street support through f32 rounding.
84:     let run = (run - request.policy.limits.contact_tolerance_metres()).max(0.0);
85:     let landing = request
86:         .policy
87:         .stairs
88:         .minimum_floor_landing_run_metres
89:         .metres();
90:     if run <= landing {
91:         let mut error = reject(SupportConstraint::StairClearance, edge, run, landing);
92:         error.violation = error.violation.with_bound(SupportBound::Minimum);
93:         return Err(error);
94:     }
95:     let outer = edge + direction * run;
96:     let points = [outer - offset, outer + offset, edge + offset, edge - offset];
97:     let source = source_pair(request, surface, [points[0], points[1]])?;
98:     Ok(PreparedApron {
99:         outer,
100:         direction,
101:         offset,
102:         run,
103:         landing,
104:         source,
105:         edge,
106:     })
107: }
108: 
109: #[derive(Clone, Copy)]
110: pub(super) struct PreparedApron {
111:     outer: Vec2,
112:     direction: Vec2,
113:     offset: Vec2,
114:     run: f32,
115:     landing: f32,
116:     source: [f32; 2],
117:     edge: Vec2,
118: }
119: 
120: /// Independent lower and upper floor constraints. A crossed pair represents
121: /// infeasibility and is diagnosed by floor selection, never silently reordered.
122: pub(super) struct FloorConstraints {
