1: //! Narrow flights connect a level court to independently supported floors.
2: //! Step dimensions are supplied by the caller; no movement limit is relaxed.
3: use super::*;
4: use crate::scene_coordinates::ScenePlanPoint;
5: use adventuresim_building_generator::spatial_geometry::{
6:     GeometryError, GeometryResult, PositiveLength, SignedLength,
7: };
8: use std::num::NonZeroU16;
9: 
10: /// A court flight in scene east/north coordinates and absolute support datums.
11: /// Building-generator access flights instead belong to architectural space.
12: #[derive(Clone, Copy, Debug, Serialize)]
13: pub struct SupportStairFlight {
14:     pub top: ScenePlanPoint,
15:     pub bottom: ScenePlanPoint,
16:     pub top_elevation_metres: SupportElevation,
17:     pub bottom_elevation_metres: SupportElevation,
18:     pub riser_count: NonZeroU16,
19:     pub going_metres: PositiveLength,
20:     pub nosing_metres: SignedLength,
21: }
22: 
23: /// Architectural stair bounds, distinct from the actor's maximum step height.
24: #[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize, bevy::reflect::Reflect)]
25: #[reflect(opaque)]
26: pub struct CourtStairLimits {
27:     pub(super) maximum_riser_metres:
28:         adventuresim_building_generator::spatial_geometry::PositiveLength,
29:     pub(super) minimum_going_metres:
30:         adventuresim_building_generator::spatial_geometry::PositiveLength,
31:     minimum_clear_width_metres: adventuresim_building_generator::spatial_geometry::PositiveLength,
32:     pub(super) minimum_floor_landing_run_metres:
33:         adventuresim_building_generator::spatial_geometry::PositiveLength,
34:     minimum_court_landing_run_metres:
35:         adventuresim_building_generator::spatial_geometry::PositiveLength,
36: }
37: 
38: #[derive(Clone, Debug)]
39: pub(super) struct CourtStair {
40:     pub flight: SupportStairFlight,
41:     pub half_width_metres: PositiveLength,
42:     pub bottom_local: Vec2,
43:     pub top_local: Vec2,
44:     floor_local: Vec2,
45:     floor_landing_half_length_metres: PositiveLength,
46:     floor_elevation_metres: SupportElevation,
47: }
48: 
49: impl CourtStairLimits {
50:     pub const fn new(
51:         maximum_riser_metres: adventuresim_building_generator::spatial_geometry::PositiveLength,
52:         minimum_going_metres: adventuresim_building_generator::spatial_geometry::PositiveLength,
53:         minimum_clear_width_metres: adventuresim_building_generator::spatial_geometry::PositiveLength,
54:         minimum_floor_landing_run_metres: adventuresim_building_generator::spatial_geometry::PositiveLength,
55:         minimum_court_landing_run_metres: adventuresim_building_generator::spatial_geometry::PositiveLength,
56:     ) -> Self {
57:         Self {
58:             maximum_riser_metres,
59:             minimum_going_metres,
60:             minimum_clear_width_metres,
61:             minimum_floor_landing_run_metres,
62:             minimum_court_landing_run_metres,
63:         }
64:     }
65: 
66:     /// Run remaining after reserving complete landings at both bound endpoints.
67:     pub fn available_run_metres(self, route: &CityAccessSegment) -> Option<f32> {
68:         let floor_landing = self
69:             .minimum_floor_landing_run_metres
70:             .metres()
71:             .max(route.half_width_metres());
72:         let court_landing = self
73:             .minimum_court_landing_run_metres
74:             .metres()
75:             .max(route.half_width_metres());
76:         let run = route.start_metres().distance(route.end_metres()) - floor_landing - court_landing;
77:         (run.is_finite() && run > 0.0).then_some(run)
78:     }
79: 
80:     pub(super) fn maximum_rise_metres(
81:         self,
82:         route: &CityAccessSegment,
83:         limits: SupportLimits,
84:     ) -> f32 {
85:         let Some(run) = self.available_run_metres(route) else {
86:             return 0.0;
87:         };
88:         let risers = (run / self.minimum_going_metres.metres())
89:             .floor()
90:             .min(f32::from(u16::MAX));
91:         (run * limits.maximum_grade.ratio()).min(risers * self.maximum_riser_metres.metres())
92:             - limits.contact_tolerance_metres.metres()
93:     }
94: }
95: 
96: impl CourtStair {
97:     pub(super) fn shift_floor(&mut self, offset: SignedLength) -> GeometryResult<()> {
98:         let top = self.flight.top_elevation_metres.translated(offset)?;
99:         let bottom = self.flight.bottom_elevation_metres.translated(offset)?;
100:         let floor = self.floor_elevation_metres.translated(offset)?;
101:         self.flight.top_elevation_metres = top;
102:         self.flight.bottom_elevation_metres = bottom;
103:         self.floor_elevation_metres = floor;
104:         Ok(())
105:     }
106: 
107:     pub fn compile(
108:         property: &CityCompound,
109:         route: &CityAccessSegment,
110:         floor: SupportElevation,
111:         court: SupportElevation,
112:         bounds: CourtStairLimits,
113:         limits: SupportLimits,
114:     ) -> Result<Option<Self>, SupportDiagnostic> {
115:         let delta = route.end_metres() - route.start_metres();
116:         let direction = delta.normalize_or_zero();
117:         let floor_landing = bounds
118:             .minimum_floor_landing_run_metres
119:             .metres()
120:             .max(route.half_width_metres());

121:         let court_landing = bounds
122:             .minimum_court_landing_run_metres
123:             .metres()
124:             .max(route.half_width_metres());
125:         let width =
126:             (bounds.minimum_clear_width_metres.metres() * 0.5).max(route.half_width_metres());
127:         let court_end = route.start_metres() + direction * court_landing;
128:         let floor_end = route.end_metres() - direction * floor_landing;
129:         let run = delta.length() - floor_landing - court_landing;
130:         let rise = (floor.metres() - court.metres()).abs();
131:         if run <= 0.0
132:             || rise > run * limits.maximum_grade.ratio() + limits.contact_tolerance_metres.metres()
133:         {
134:             return Err(SupportDiagnostic::new(
135:                 property,
136:                 SupportConstraint::AccessGrade,
137:                 SupportBoundary::CourtLanding,
138:                 court_end,
139:                 rise,
140:                 run.max(0.0) * limits.maximum_grade.ratio(),
141:             ));
142:         }
143:         if rise <= limits.contact_tolerance_metres.metres() {
144:             return Ok(None);
145:         }
146:         validate_reservation(
147:             property,
148:             route,
149:             direction,
150:             width,
151:             floor_landing,
152:             court_landing,
153:         )?;
154:         let count = (rise / bounds.maximum_riser_metres.metres()).ceil();
155:         if count > f32::from(u16::MAX) {
156:             return Err(SupportDiagnostic::new(
157:                 property,
158:                 SupportConstraint::StairGoing,
159:                 SupportBoundary::CourtLanding,
160:                 court_end,
161:                 count * bounds.minimum_going_metres.metres(),
162:                 run,
163:             ));
164:         }
165:         let required_run = count * bounds.minimum_going_metres.metres();
166:         if required_run > run + limits.contact_tolerance_metres.metres() {
167:             return Err(SupportDiagnostic::new(
168:                 property,
169:                 SupportConstraint::StairGoing,
170:                 SupportBoundary::CourtLanding,
171:                 court_end,
172:                 required_run,
173:                 run,
174:             ));
175:         }
176:         let (top, bottom, top_height, bottom_height) = if floor.metres() > court.metres() {
177:             (floor_end, court_end, floor, court)
178:         } else {
179:             (court_end, floor_end, court, floor)
180:         };
181:         let geometry_error = |cause| SupportDiagnostic::framed_geometry(property, court_end, cause);
182:         let riser_count = NonZeroU16::new(count as u16)
183:             .ok_or_else(|| geometry_error(GeometryError::InvalidProjection))?;
184:         let flight = SupportStairFlight {
185:             top: ScenePlanPoint::try_from(top).map_err(geometry_error)?,
186:             bottom: ScenePlanPoint::try_from(bottom).map_err(geometry_error)?,
187:             top_elevation_metres: top_height,
188:             bottom_elevation_metres: bottom_height,
189:             riser_count,
190:             going_metres: PositiveLength::from_metres(run / count).map_err(geometry_error)?,
191:             nosing_metres: SignedLength::ZERO,
192:         };
193:         Ok(Some(Self::new(
194:             property,
195:             route.end(),
196:             flight,
197:             PositiveLength::from_metres(width).map_err(geometry_error)?,
198:             PositiveLength::from_metres(floor_landing).map_err(geometry_error)?,
199:             floor,
200:         )))
201:     }
202: 
203:     /// Native plot-local rectangle and tread calculation; the returned datum
204:     /// remains checked through the containing support plan.
205:     pub fn height_at(&self, local: Vec2) -> Option<GeometryResult<SupportElevation>> {
206:         if (local - self.floor_local)
207:             .abs()
208:             .cmple(Vec2::new(
209:                 self.half_width_metres.metres(),
210:                 self.floor_landing_half_length_metres.metres(),
211:             ))
212:             .all()
213:         {
214:             return Some(Ok(self.floor_elevation_metres));
215:         }
216:         let axis = self.top_local - self.bottom_local;
217:         let length = axis.length();
218:         let distance = (local - self.bottom_local).dot(axis / length);
219:         let across = (local - self.bottom_local).perp_dot(axis / length).abs();
220:         if !(0.0..=length).contains(&distance) || across > self.half_width_metres.metres() {
221:             return None;
222:         }
223:         let count = f32::from(self.flight.riser_count.get());
224:         let tread = (distance / length * count).ceil().clamp(0.0, count);
225:         Some(
226:             SupportElevation::from_metres(
227:                 self.flight.bottom_elevation_metres.metres()
228:                     + (self.flight.top_elevation_metres.metres()
229:                         - self.flight.bottom_elevation_metres.metres())
230:                         * tread
231:                         / count,
232:             )
233:             .ok_or(GeometryError::InvalidProjection),
234:         )
235:     }
236: 
237:     pub fn local_cuts(&self) -> (Vec<f32>, Vec<f32>) {
238:         let width = self.half_width_metres.metres();
239:         let x = self.top_local.x;
240:         let count = self.flight.riser_count.get();

241:         let mut z: Vec<_> = (0..=count)
242:             .map(|i| {
243:                 self.bottom_local.y
244:                     + (self.top_local.y - self.bottom_local.y) * f32::from(i) / f32::from(count)
245:             })
246:             .collect();
247:         z.extend([
248:             self.floor_local.y - self.floor_landing_half_length_metres.metres(),
249:             self.floor_local.y + self.floor_landing_half_length_metres.metres(),
250:         ]);
251:         (vec![x - width, x + width], z)
252:     }
253: 
254:     /// Project the admitted scene flight into its bound plot's native support
255:     /// partition. The plot orientation owns this local rectangle/tread frame.
256:     fn new(
257:         property: &CityCompound,
258:         floor_threshold: ScenePlanPoint,
259:         flight: SupportStairFlight,
260:         half_width: PositiveLength,
261:         floor_landing: PositiveLength,
262:         floor: SupportElevation,
263:     ) -> Self {
264:         let local = |point: ScenePlanPoint| {
265:             property
266:                 .plot
267:                 .orientation()
268:                 .world_to_local(point.metres() - property.plot.centre_metres())
269:         };
270:         Self {
271:             top_local: local(flight.top),
272:             bottom_local: local(flight.bottom),
273:             floor_local: local(floor_threshold),
274:             flight,
275:             half_width_metres: half_width,
276:             floor_landing_half_length_metres: floor_landing,
277:             floor_elevation_metres: floor,
278:         }
279:     }
280: }
281: 
282: fn validate_reservation(
283:     property: &CityCompound,
284:     route: &CityAccessSegment,
285:     direction: Vec2,
286:     half_width: f32,
287:     floor_landing: f32,
288:     court_landing: f32,
289: ) -> Result<(), SupportDiagnostic> {
290:     let across = Vec2::new(-direction.y, direction.x);
291:     for (anchor, landing) in [
292:         (route.start_metres(), court_landing),
293:         (route.end_metres(), floor_landing),
294:     ] {
295:         for along in [-landing, landing] {
296:             for side in [-half_width, half_width] {
297:                 let point = anchor + direction * along + across * side;
298:                 let local = property
299:                     .plot
300:                     .orientation()
301:                     .world_to_local(point - property.plot.centre_metres());
302:                 let outside =
303:                     (local.abs() - property.plot.dimensions_metres() * 0.5).max(Vec2::ZERO);
304:                 if outside.length_squared() > 0.0 {
305:                     return Err(SupportDiagnostic::new(
306:                         property,
307:                         SupportConstraint::StairClearance,
308:                         SupportBoundary::PropertyReservation,
309:                         point,
310:                         outside.length(),
311:                         0.0,
312:                     ));
313:                 }
314:             }
315:         }
316:     }
317:     Ok(())
318: }

