49: impl PropertySupportSurface {
50:     /// Admit completed producer geometry before publishing its immutable owner.
51:     /// Decoding uses the same geometry and floor proof in `validate_encoded`.
52:     pub(super) fn admit_generated(self) -> Result<Self, SupportDiagnostic> {
53:         if let Err(issue) = self.validate_encoded() {
54:             let mut diagnostic = self.rejection(
55:                 SupportConstraint::Reservation,
56:                 SupportBoundary::PropertyReservation,
57:                 self.regions
58:                     .first()
59:                     .map_or(Vec2::ZERO, |region| region.centre_metres()),
60:                 1.0,
61:                 0.0,
62:             );
63:             diagnostic.construction_failure =
64:                 Some(Box::new(SupportConstructionError::Surface(issue)));
65:             return Err(diagnostic);
66:         }
67:         Ok(self)
68:     }
