70:     pub fn property_id(&self) -> CityPropertyId {
71:         self.mesh.property_id
72:     }
73: 
74:     pub fn member_building_ids(&self) -> &[crate::scene_input::SceneBuildingId] {
75:         &self.mesh.member_building_ids
76:     }
77: 
78:     pub fn support_regions(&self) -> &[CityPlotBounds] {
79:         &self.regions
80:     }
81: 
82:     /// Exact accepted single-building approaches, including workplace passages.
83:     /// Their first region is the bearing floor; the rest follow the sorted
84:     /// ground entrance identities. Compound routes retain their own contract.
85:     pub(crate) fn doorway_approaches(&self) -> &[CityPlotBounds] {
86:         match self.treatment {
87:             SupportGradingAttempt::SingleBuildingFloorAndEntrances => &self.regions[1..],
88:             SupportGradingAttempt::Compound(_) | SupportGradingAttempt::NotSelected => &[],
89:         }
90:     }
