92:     pub fn contains(&self, point: crate::scene_coordinates::ScenePlanPoint) -> bool {
93:         let point = point.metres();
94:         self.clipping_outlines.iter().any(|outline| {
95:             (0..outline.len()).all(|i| {
96:                 (outline[(i + 1) % outline.len()] - outline[i])
97:                     .perp_dot(point.as_dvec2() - outline[i])
98:                     >= 0.0
99:             })
100:         })

