43: fn goslar_1238_enclosure_follows_all_terraces_and_anchors_the_gate_above_the_front_floor() {
44:     let fixture = Fixture::load();
45:     let (mesh, gate, foundation) = project(&fixture);
46:     let source = fixture.source();
47:     let plan = fixture.selected_plan(&source);
48:     assert!(gate.metres() - plan.member_support()[0].elevation.metres() > 2.3);
49:     let post_head = gate.metres() + fixture.property.boundary.gate.height_metres + 0.15;
50:     let mut post_soil = Vec::new();
51:     let collider = mesh.collider().unwrap().into_solid().unwrap();
52:     for cell in &mesh.cells {
53:         let centre = cell.native_positions()[..3].iter().copied().sum::<Vec3>() / 3.0;
54:         assert!(
55:             collider
56:                 .cast_ray(
57:                     Vec3::Y * gate.metres(),
58:                     Rotation::default(),
59:                     centre + Vec3::Y * (gate.metres() + 0.01),
60:                     -Vec3::Y,
61:                     0.02,
62:                     false
63:                 )
64:                 .is_some()
65:         );
66:         if cell.element() == BoundarySupportElement::GatePost(PropertySide::Left) {
67:             for top in &cell.native_positions()[..3] {
68:                 assert!((top.y + gate.metres() - post_head).abs() < 0.001);
69:             }
70:             post_soil.extend(
71:                 cell.native_positions()[3..]
72:                     .iter()
73:                     .map(|p| p.y + gate.metres() + 0.2),
74:             );
75:         }
76:         for point in &cell.native_positions()[3..] {
77:             let world = *point + Vec3::Y * gate.metres();
78:             if matches!(cell.element(), BoundarySupportElement::WallCap(_)) {
79:                 continue;
80:             }
81:             let support = foundation
82:                 .support_triangles
83:                 .iter()
84:                 .filter_map(|indices| {
85:                     let triangle = super::super::foundations::GroundTriangle::new(
86:                         indices.map(|i| foundation.positions[i as usize]),
87:                     )?;
88:                     triangle
89:                         .contains(world.xz(), 0.001)
90:                         .then(|| triangle.height_at(world.xz()))
91:                 })
92:                 .any(|h| (world.y + 0.2 - h).abs() < 0.001);
93:             assert!(
94:                 support,
95:                 "unbound masonry bearing {:?} at {world:?}",
96:                 cell.element()
97:             );
98:         }
99:     }
100:     let low = post_soil.iter().copied().fold(f32::INFINITY, f32::min);
101:     let high = post_soil.iter().copied().fold(f32::NEG_INFINITY, f32::max);
102:     assert!(
103:         high - low > 2.3,
104:         "the complete hinge-post footprint must straddle both levels"
105:     );
106: }
