230:                 let point = a + (b - a) * (u as f32 / 10.0) + (c - a) * (v as f32 / 10.0);
231:                 if plan.contains(
232:                     crate::scene_coordinates::ScenePlanPoint::try_from(point.xz()).unwrap(),
233:                 ) {
234:                     continue;
235:                 }
236:                 let heights: Vec<_> = terrain
237:                     .elevations_at(
238:                         crate::scene_coordinates::ScenePlanPoint::from_metres(point.xz()).unwrap(),
239:                     )
240:                     .iter()
241:                     .collect();
242:                 assert!(
243:                     !heights.is_empty(),
244:                     "outside terrain was removed at {point:?}"
245:                 );
246:                 assert!(
247:                     heights.iter().all(|h| (h.metres() - point.y).abs() < 0.001),
248:                     "outside terrain changed at {point:?}: {heights:?}"
249:                 );
250:             }
251:         }
252:     }
253: }
