1: //! Traversal uses the production KCC, collider shape and authored movement limits.
2: //! These checks isolate the proposed support surface; they do not accept a city.
3: use super::*;
4: use adventuresim_core::combat::HUMANOID_COLLISION_RADIUS_METRES;
5: use avian3d::prelude::*;
6: use bevy::prelude::*;
7: use bevy::time::TimeUpdateStrategy;
8: use bevy_ahoy::{AhoySystems, CharacterController, input::AccumulatedInput};
9: use bevy_enhanced_input::EnhancedInputPlugin;
10: use std::time::Duration;
11: 
12: mod gardens;
13: mod outdoor;
14: mod production;
15: mod single;
16: 
17: struct Walker {
18:     app: App,
19:     entity: Entity,
20: }
21: 
22: #[derive(Component)]
23: struct WalkGoal(Vec2);
24: 
25: #[derive(Component, Default)]
26: struct LastDriveVelocity(Vec3);
27: 
28: #[derive(Component)]
29: struct ExactBuildingGeometry(crate::scene_input::GeneratedBuilding);
30: 
31: fn drive(mut walkers: Query<(&Position, &WalkGoal, &mut AccumulatedInput)>) {
32:     for (position, goal, mut input) in &mut walkers {
33:         let delta = goal.0 - position.0.xz();
34:         // A route waypoint asks the pedestrian to arrive and stop. Taper input
35:         // over one body radius instead of steering a full-speed U-turn through
36:         // a narrow doorway with the real motor's bounded turning acceleration.
37:         let movement = delta.normalize_or_zero()
38:             * (delta.length() / HUMANOID_COLLISION_RADIUS_METRES).min(1.0);
39:         input.last_movement = Some(Vec2::new(movement.x, -movement.y));
40:     }
41: }
42: 
43: fn capture_drive(mut walkers: Query<(&LinearVelocity, &mut LastDriveVelocity)>) {
44:     for (velocity, mut sample) in &mut walkers {
45:         sample.0 = velocity.0;
46:     }
47: }
48: 
49: impl Walker {
50:     fn on_surface(mesh: &PropertySupportMesh, start: Vec2, elevation: f32) -> Self {
51:         Self::on_collider(mesh.collider().unwrap(), start, elevation)
52:     }
53: 
54:     fn on_collider(surface: Collider, start: Vec2, elevation: f32) -> Self {
55:         Self::on_colliders([surface], start, elevation)
56:     }
57: 
58:     fn on_colliders(
59:         surfaces: impl IntoIterator<Item = Collider>,
60:         start: Vec2,
61:         elevation: f32,
62:     ) -> Self {
63:         let mut app = App::new();
64:         app.add_plugins((
65:             MinimalPlugins,
66:             bevy::input::InputPlugin,
67:             TransformPlugin,
68:             EnhancedInputPlugin,
69:             crate::physics::AdventureSimulatorPhysicsPlugin::default(),
70:         ));
71:         let tick = Duration::from_secs_f64(1.0 / 64.0);
72:         app.insert_resource(TimeUpdateStrategy::ManualDuration(tick));
73:         app.insert_resource(Time::<Fixed>::from_duration(tick));
74:         app.add_systems(
75:             FixedPostUpdate,
76:             drive.before(crate::physics::AdventureSimulatorPhysicsSet::ApplyCharacterMotor),
77:         );
78:         app.add_systems(
79:             FixedPostUpdate,
80:             capture_drive
81:                 .after(crate::physics::AdventureSimulatorPhysicsSet::ApplyCharacterMotor)
82:                 .before(AhoySystems::MoveCharacters),
83:         );
84:         for (index, surface) in surfaces.into_iter().enumerate() {
85:             app.world_mut().spawn((
86:                 Name::new(format!("support shape {index}")),
87:                 RigidBody::Static,
88:                 surface,
89:                 Transform::default(),
90:             ));
91:         }
92:         let config = crate::combat_config::TacticalCombatConfig::default();
93:         let motor = &config.movement.motor;
94:         let collider = Collider::cylinder(HUMANOID_COLLISION_RADIUS_METRES, 1.9);
95:         let bottom = -collider.aabb(Vec3::ZERO, Rotation::default()).min.y;
96:         let controller = CharacterController {
97:             speed: config
98:                 .movement
99:                 .speeds_metres_per_second
100:                 .walk
101:                 .metres_per_second(),
102:             gravity: motor.gravity_metres_per_second_squared,
103:             step_size: motor.maximum_step_height_metres,
104:             min_walk_cos: motor.maximum_walkable_slope_degrees.to_radians().cos(),
105:             ..default()
106:         };
107:         let entity = app
108:             .world_mut()
109:             .spawn((
110:                 controller,
111:                 crate::physics::MovementPace::Walk,
112:                 LastDriveVelocity::default(),
113:                 collider,
114:                 Transform::from_xyz(start.x, elevation + bottom + 0.05, start.y),
115:             ))
116:             .id();
117:         app.finish();
118:         app.cleanup();
119:         for _ in 0..64 {
120:             app.update();
121:         }
122:         Self { app, entity }
123:     }
124: 
125:     fn attempt_walk_to(&mut self, target: Vec2) -> Vec3 {
126:         let start = self
127:             .app
128:             .world()
129:             .get::<Position>(self.entity)
130:             .unwrap()
131:             .0
132:             .xz();
133:         let speed = crate::combat_config::TacticalCombatConfig::default()
134:             .movement
135:             .speeds_metres_per_second

136:             .walk;
137:         let tick = self.app.world().resource::<Time<Fixed>>().delta_secs();
138:         // Preserve the existing ten-second control window. Long geographic
139:         // approaches need a route-length budget, not a larger movement limit.
140:         let route_ticks = ((start.distance(target) / speed.metres_per_second() * 2.0 + 1.0) / tick)
141:             .ceil() as usize;
142:         self.app
143:             .world_mut()
144:             .entity_mut(self.entity)
145:             .insert(WalkGoal(target));
146:         for _ in 0..route_ticks.max(640) {
147:             let position = self.app.world().get::<Position>(self.entity).unwrap().0;
148:             let delta = target - position.xz();
149:             if delta.length() < 0.08 {
150:                 self.app
151:                     .world_mut()
152:                     .entity_mut(self.entity)
153:                     .remove::<WalkGoal>();
154:                 // Use the production motor to brake; do not zero its velocity.
155:                 for _ in 0..64 {
156:                     if self
157:                         .app
158:                         .world()
159:                         .get::<LinearVelocity>(self.entity)
160:                         .unwrap()
161:                         .xz()
162:                         .length()
163:                         < 0.01
164:                     {
165:                         break;
166:                     }
167:                     self.app.update();
168:                 }
169:                 return self.app.world().get::<Position>(self.entity).unwrap().0;
170:             }
171:             self.app.update();
172:         }
173:         self.app.world().get::<Position>(self.entity).unwrap().0
174:     }
175: 
176:     fn walk_to(&mut self, target: Vec2) -> Vec3 {
177:         let position = self.attempt_walk_to(target);
178:         if position.xz().distance(target) >= 0.08 {
179:             self.capture_step_casts(position);
180:         }
181:         assert!(
182:             position.xz().distance(target) < 0.08,
183:             "target {target:?}, stopped at {position:?}, velocity {:?}, input {:?}, transform {:?}",
184:             self.app.world().get::<LinearVelocity>(self.entity),
185:             self.app.world().get::<AccumulatedInput>(self.entity),
186:             self.app.world().get::<Transform>(self.entity),
187:         );
188:         position
189:     }
190: 
191:     fn install_property_buildings(&mut self, plan: &CompoundSupportPlan, fixture: &Fixture) {
192:         use crate::scene_input::{
193:             GeneratedBuilding, TacticalBuildingPlacement, compile_tactical_building_collider,
194:         };
195:         let value = &fixture.document;
196:         for key in ["front_distant_placement", "rear_distant_placement"] {
197:             let distant: DistantBuildingPlacement =
198:                 serde_json::from_value(value[key].clone()).unwrap();
199:             let mut placement = TacticalBuildingPlacement::from(distant);
200:             placement.base_elevation_metres = plan
201:                 .member_support()
202:                 .iter()
203:                 .find(|m| m.building_id == placement.id)
204:                 .unwrap()
205:                 .elevation;
206:             let recipe = GeneratedBuildingRecipe::generate(placement.program.clone()).unwrap();
207:             let building = GeneratedBuilding {
208:                 placement,
209:                 plan: recipe.plan,
210:                 collision: recipe.collision,
211:             };
212:             self.app.world_mut().spawn((
213:                 crate::scene_input::SceneBuilding {
214:                     id: building.placement.id,
215:                     program: building.placement.program.clone(),
216:                     orientation: building.placement.orientation,
217:                 },
218:                 RigidBody::Static,
219:                 compile_tactical_building_collider(&building.collision).unwrap(),
220:                 building.transform().unwrap(),
221:                 ExactBuildingGeometry(building),
222:             ));
223:         }
224:     }
225: 
226:     fn capture_step_casts(&mut self, position: Vec3) {
227:         let collider = self
228:             .app
229:             .world()
230:             .get::<Collider>(self.entity)
231:             .unwrap()
232:             .clone();
233:         let controller = self
234:             .app
235:             .world()
236:             .get::<CharacterController>(self.entity)
237:             .unwrap()
238:             .clone();
239:         let velocity = self
240:             .app
241:             .world()
242:             .get::<LastDriveVelocity>(self.entity)
243:             .unwrap()
244:             .0;
245:         let tick = self.app.world().resource::<Time<Fixed>>().delta_secs();
246:         let wish = (self.app.world().get::<WalkGoal>(self.entity).unwrap().0 - position.xz())
247:             .normalize_or_zero()
248:             * controller.speed;
249:         let direction = Vec3::new(wish.x, 0.0, wish.y).normalize_or_zero();
250:         println!(
251:             "controller speed {}, grounded/state {:?}, output {:?}, wish {wish:?}, final velocity {:?}",
252:             controller.speed,
253:             self.app
254:                 .world()
255:                 .get::<bevy_ahoy::CharacterControllerState>(self.entity),
256:             self.app
257:                 .world()
258:                 .get::<bevy_ahoy::CharacterControllerOutput>(self.entity),
259:             self.app.world().get::<LinearVelocity>(self.entity)
260:         );
261:         if let Some(ground) = self
262:             .app
263:             .world()
264:             .get::<bevy_ahoy::CharacterControllerState>(self.entity)
265:             .and_then(|s| s.grounded)
266:         {
267:             println!(
268:                 "ground entity {:?}, shape bounds {:?}",
269:                 self.app.world().get::<Name>(ground.entity),
270:                 self.app

271:                     .world()
272:                     .get::<Collider>(ground.entity)
273:                     .map(|c| c.aabb(Vec3::ZERO, Rotation::default()))
274:             );
275:         }
276:         let mut state = bevy::ecs::system::SystemState::<MoveAndSlide>::new(self.app.world_mut());
277:         let query = state.get(self.app.world()).unwrap();
278:         let cast = |from, movement| {
279:             query.cast_move(
280:                 &collider,
281:                 from,
282:                 Quat::IDENTITY,
283:                 movement,
284:                 controller.move_and_slide.skin_width,
285:                 &controller.filter,
286:             )
287:         };
288:         let raised = position + Vec3::Y * controller.step_size;
289:         println!(
290:             "drive velocity {velocity:?}, tick {tick}, step {}, skin {}",
291:             controller.step_size, controller.move_and_slide.skin_width
292:         );
293:         println!(
294:             "up {:?}, ledge {:?}, down {:?}",
295:             cast(position, Vec3::Y * controller.step_size),
296:             cast(raised, direction * controller.min_step_ledge_space),
297:             cast(
298:                 raised + Vec3::new(wish.x, 0.0, wish.y) * tick,
299:                 Vec3::NEG_Y * controller.step_size
300:             )
301:         );
302:         if let Some(hit) = cast(raised, direction * controller.min_step_ledge_space) {
303:             println!(
304:                 "blocked entity name {:?}, building {:?}",
305:                 self.app.world().get::<Name>(hit.entity),
306:                 self.app
307:                     .world()
308:                     .get::<crate::scene_input::SceneBuilding>(hit.entity)
309:             );
310:             let Some(ExactBuildingGeometry(building)) = self.app.world().get(hit.entity) else {
311:                 return;
312:             };
313:             let point = building
314:                 .transform()
315:                 .unwrap()
316:                 .compute_affine()
317:                 .inverse()
318:                 .transform_point3(hit.point2)
319:                 + building.collision.bounds.centre().unwrap().metres();
320:             for cuboid in &building.collision.cuboids {
321:                 let rotation = Quat::from_rotation_y(cuboid.yaw_radians.radians())
322:                     * Quat::from_rotation_x(cuboid.crossfall_radians.radians())
323:                     * Quat::from_rotation_z(cuboid.longfall_radians.radians());
324:                 let offset = rotation.inverse() * (point - cuboid.centre.metres());
325:                 if offset
326:                     .abs()
327:                     .cmple(cuboid.size.metres() * 0.5 + Vec3::splat(0.001))
328:                     .all()
329:                 {
330:                     let solid = building
331:                         .plan
332:                         .resolved_geometry
333:                         .solids
334:                         .iter()
335:                         .find(|s| s.id == cuboid.source);
336:                     println!(
337:                         "blocked member {}, arch point {point:?}, cuboid {cuboid:?}, solid {solid:?}",
338:                         building.placement.id
339:                     );
340:                 }
341:             }
342:         }
343:     }
344: }
