500: fn traverse_court(fixture: &Fixture) {
501:     // Full doorway approach must clear the collider's rear radius before the
502:     // actor's head reaches the wall. The short surface-only landing is invalid
503:     // for this entry, even though it admits an isolated threshold-centre goal.
504:     let source = fixture.source();
505:     let plan = fixture.selected_plan(&source);
506:     let terrain = BoundedSettlementTerrain::compile(
507:         &(std::slice::from_ref(&plan))
508:             .iter()
509:             .map(|plan| plan.support_surface().unwrap())
510:             .collect::<Vec<_>>(),
511:         &source,
512:         FoundationEmbedment::from_metres(0.2).unwrap(),
513:     )
514:     .unwrap();
515:     let passage = fixture
516:         .property
517:         .access
518:         .iter()
519:         .find(|r| {
520:             r.contains_centreline(
521:                 crate::scene_coordinates::ScenePlanPoint::try_from(
522:                     fixture.property.boundary.gate.centre_metres,
523:                 )
524:                 .unwrap(),
525:             )
526:         })
527:         .unwrap();
528:     let mut walker = Walker::on_colliders(
529:         terrain.colliders().unwrap(),
530:         passage.start_metres(),
531:         plan.levels.street.metres(),
532:     );
533:     walker.install_property_buildings(&plan, fixture);
534:     let crate::city_layout::grounding::BoundarySupportProjection {
