garden 105: 
garden 106: fn garden_walker(
garden 107:     garden: &crate::city_layout::CityGarden,
garden 108:     ground: &crate::scene::SceneTerrain,
garden 109:     terrain: &[Collider],
garden 110:     buildings: &[OccupiedBuilding],
garden 111:     outdoor: &outdoor::OutdoorCollision,
garden 112:     input: &TacticalSceneInput,
garden 113: ) -> Walker {
garden 114:     occupied_walker(
garden 115:         garden.access[0].start_metres(),

116:         garden.plot.centre_metres(),
117:         garden.plot.dimensions_metres().length() + 6.0,
118:         ground,
119:         terrain,
120:         buildings,
121:         outdoor,
122:         input,
123:         None,
124:     )
125: }
126: 
127: #[expect(
128:     clippy::too_many_arguments,
129:     reason = "test world retains explicit route bounds and production geometry"
130: )]
131: pub(super) fn occupied_walker(
132:     start: Vec2,
133:     centre: Vec2,
134:     radius: f32,
135:     ground: &crate::scene::SceneTerrain,
136:     terrain: &[Collider],
137:     buildings: &[OccupiedBuilding],
138:     outdoor: &outdoor::OutdoorCollision,
139:     input: &TacticalSceneInput,
140:     open_property: Option<crate::city_layout::CityPropertyId>,
141: ) -> Walker {
142:     let elevation = ground
143:         .height_at(ScenePlanPoint::from_metres(start).unwrap())
144:         .unwrap();
145:     // Bounds selection drops no geometry near an access lane. The natural
146:     // source body intersects this box and retains its complete original BVH.
147:     let inside = |position: Vec3, shape: &Collider, rotation: Quat| {
148:         let bounds = shape.aabb(position, rotation);
149:         let half = Vec2::splat(radius);
150:         !bounds.max.xz().cmplt(centre - half).any() && !bounds.min.xz().cmpgt(centre + half).any()
151:     };
152:     let mut walker = Walker::on_colliders(
153:         terrain
154:             .iter()
155:             .filter(|shape| inside(Vec3::ZERO, shape, Quat::IDENTITY))
156:             .cloned(),
157:         start,
158:         elevation.metres(),
159:     );
160:     for building in buildings {
161:         let shape = &building.collider;
162:         let transform = building.building.transform().unwrap();
163:         if inside(transform.translation, shape, transform.rotation) {
164:             walker
165:                 .app
166:                 .world_mut()
167:                 .spawn((RigidBody::Static, shape.clone(), transform));
168:         }
169:     }
170:     outdoor.install(&mut walker.app, inside);
171:     for compound in &input.compounds {
172:         if compound.plot.centre_metres().distance(centre)
173:             > radius + compound.plot.dimensions_metres().length()
174:         {
175:             continue;
176:         }
177:         let boundary = crate::scene_input::GeneratedBoundary::project(compound, ground).unwrap();
178:         walker.app.world_mut().spawn((
179:             RigidBody::Static,
180:             boundary
181:                 .scene()
182:                 .fixed_support()
183:                 .collider()
184:                 .unwrap()
185:                 .into_solid()
186:                 .unwrap(),
187:             Transform::from_xyz(0.0, boundary.elevation_metres().metres(), 0.0),
188:         ));
189:         let door = compound.boundary.gate.door(compound.id).unwrap();
190:         let rotation = Quat::from_rotation_y(if open_property == Some(compound.id) {
191:             door.open_angle_radians.radians()
192:         } else {
193:             0.0
194:         });
195:         let leaf = door.hinge_centre.metres()
196:             + rotation * (door.closed_centre.metres() - door.hinge_centre.metres())
197:             + Vec3::Y * boundary.elevation_metres().metres();
198:         walker.app.world_mut().spawn((
199:             RigidBody::Static,
200:             Collider::cuboid(
201:                 door.size_metres.metres().x,
202:                 door.size_metres.metres().y,
203:                 door.size_metres.metres().z,
204:             ),
205:             Transform::from_translation(leaf)
206:                 .with_rotation(rotation * Quat::from_rotation_y(door.closed_yaw_radians.radians())),
207:         ));
208:     }
209:     for _ in 0..64 {
210:         walker.app.update();
211:     }
212:     walker
213: }
