1: //! Install the server's physical outdoor instances in an acceptance world.
2: use super::*;
3: use crate::scene_coordinates::ScenePlanPoint;
4: use crate::scene_input::furniture::{FurnitureLayout, furniture_collider};
5: use crate::scene_input::{GeneratedObstacle, TacticalSceneInput};
6: 
7: pub(super) struct OutdoorCollision(Vec<(Name, Collider, Transform)>);
8: 
9: impl OutdoorCollision {
10:     pub(super) fn compile(
11:         input: &TacticalSceneInput,
12:         terrain: &crate::scene::SceneTerrain,
13:         obstacles: &[GeneratedObstacle],
14:         furniture: &FurnitureLayout,
15:     ) -> Self {
16:         let mut bodies = Vec::new();
17:         for obstacle in obstacles {
18:             let (x, z, shape, offset, yaw) = match *obstacle {
19:                 GeneratedObstacle::Tree { x, z } => (
20:                     x,
21:                     z,
22:                     Collider::cylinder(
23:                         crate::scene_input::TREE_TRUNK_RADIUS_METRES,
24:                         crate::scene_input::TREE_TRUNK_HEIGHT_METRES,
25:                     ),
26:                     crate::scene_input::TREE_TRUNK_HEIGHT_METRES * 0.5,
27:                     0.0,
28:                 ),
29:                 GeneratedObstacle::Rock { x, z, recipe } => (
30:                     x,
31:                     z,
32:                     Collider::sphere(recipe.collision_radius_metres()),
33:                     recipe.collision_radius_metres(),
34:                     (recipe.seed.to_u64() >> 40) as f32 / ((1_u32 << 24) - 1) as f32
35:                         * core::f32::consts::TAU,
36:                 ),
37:             };
38:             let point = ScenePlanPoint::from_metres(
39:                 Vec2::new(f32::from(x), f32::from(z)) * input.playable.spacing_metres
40:                     - Vec2::new(terrain.width(), terrain.depth()) * 0.5,
41:             )
42:             .unwrap();
43:             let height = terrain
44:                 .height_at(point)
45:                 .expect("physical obstacle has source support");
46:             bodies.push((
47:                 Name::new(format!("Obstacle {x},{z}")),
48:                 shape,
49:                 Transform::from_xyz(point.metres().x, height.metres() + offset, point.metres().y)
50:                     .with_rotation(Quat::from_rotation_y(yaw)),
51:             ));
52:         }
53:         // Distant instances are accepted scenery without server physics.
54:         for instance in &furniture.instances {
55:             bodies.push((
56:                 Name::new(format!("Furniture {}", instance.scene.id.0)),
57:                 furniture_collider(instance.scene.key).unwrap(),
58:                 Transform::from_translation(instance.position_metres.metres())
59:                     .with_rotation(Quat::from_rotation_y(instance.orientation.yaw_radians())),
60:             ));
61:         }
62:         Self(bodies)
63:     }
64: 
65:     pub(super) fn install(
66:         &self,
67:         app: &mut App,
68:         intersects: impl Fn(Vec3, &Collider, Quat) -> bool,
69:     ) {
70:         for (name, shape, transform) in &self.0 {
71:             if intersects(transform.translation, shape, transform.rotation) {
72:                 app.world_mut()
73:                     .spawn((name.clone(), RigidBody::Static, shape.clone(), *transform));
74:             }
75:         }
76:     }
77: }

