6: #[test]
7: #[ignore = "requires a frozen production export in FABELGEIST_TERRAIN_SCENE"]
8: fn production_single_entrances_allow_full_width_entry_and_return() {
9:     let input = TacticalSceneInput::load(std::path::Path::new(
10:         &std::env::var("FABELGEIST_TERRAIN_SCENE").unwrap(),
11:     ))
12:     .unwrap();
13:     let selected = std::env::var("FABELGEIST_SINGLE_PROPERTY")
14:         .ok()
15:         .map(|id| id.parse::<u64>().unwrap());
16:     let scene = input
17:         .generate_unfurnished(GeneratedBuildingRecipes::default())
18:         .unwrap();
19:     let outdoor = outdoor::OutdoorCollision::compile(
20:         &input,
21:         &scene.terrain,
22:         &scene.obstacles,
23:         &scene.furniture,
24:     );
25:     let terrain = scene.terrain.colliders().unwrap();
26:     let mut buildings = scene.buildings;
27:     for distant in &input.distant_buildings {
28:         let placement = crate::scene_input::TacticalBuildingPlacement::from(*distant);
29:         let recipe = GeneratedBuildingRecipe::generate(placement.program.clone()).unwrap();
30:         buildings.push(crate::scene_input::GeneratedBuilding {
31:             placement,
32:             plan: recipe.plan,
33:             collision: recipe.collision,
34:         });
35:     }
36:     let buildings: Vec<_> = buildings
37:         .into_iter()
38:         .map(gardens::OccupiedBuilding::from)
39:         .collect();
40:     let mut observations = Vec::new();
41:     for owner in input.grounding.as_ref().unwrap().surfaces() {
42:         if owner.member_building_ids().len() != 1
43:             || selected.is_some_and(|id| id != owner.property_id().0)
44:         {
45:             continue;
46:         }
47:         let building = &buildings
48:             .iter()
49:             .find(|b| b.building.placement.id == owner.member_building_ids()[0])
50:             .unwrap()
51:             .building;
52:         let transform = building.transform().unwrap();
53:         let origin = building.collision.bounds.centre().unwrap().metres().xz();
54:         let mut doors: Vec<_> = compile_ground_entrances(&building.plan)
55:             .unwrap()
56:             .into_iter()
57:             .filter(|door| door.support == BuildingEntranceSupport::ArchitecturalFloor)
58:             .collect();
59:         doors.sort_by_key(|door| door.id);
60:         assert_eq!(doors.len(), owner.support_regions().len() - 1);
61:         for (door, apron) in doors.into_iter().zip(&owner.support_regions()[1..]) {
62:             if let Ok(selected) = std::env::var("FABELGEIST_SINGLE_ENTRANCE") {
63:                 let selected: adventuresim_building_generator::BuildingEntranceId =
64:                     serde_json::from_str(&selected).unwrap();
65:                 if door.id != selected {
66:                     continue;
67:                 }
68:             }
69:             let outward = building
70:                 .placement
71:                 .orientation
72:                 .local_to_world(door.outward.vector());
73:             let tangent = Vec2::new(outward.y, -outward.x);
74:             let threshold = building.placement.centre_metres.metres()
75:                 + building
76:                     .placement
77:                     .orientation
78:                     .local_to_world(door.threshold_metres.metres() - origin);
79:             let outer = apron.centre_metres() + outward * apron.dimensions_metres().y * 0.5;
80:             let skin = CharacterController::default().move_and_slide.skin_width;
81:             let tolerance = crate::city_layout::CompoundGradingPolicy::bounded_settlement()
82:                 .limits
83:                 .contact_tolerance_metres();
84:             let edge_clearance = apron.dimensions_metres().x * 0.5
85:                 - HUMANOID_COLLISION_RADIUS_METRES
86:                 - skin
87:                 - tolerance;
88:             assert!(edge_clearance >= 0.0);
89:             let tracks = if std::env::var_os("FABELGEIST_CENTRELINE_ONLY").is_some() {
90:                 vec![0.0]
91:             } else {
92:                 vec![-edge_clearance, 0.0, edge_clearance]
93:             };
94:             let tracks = if let Ok(index) = std::env::var("FABELGEIST_SINGLE_TRACK") {
95:                 vec![tracks[index.parse::<usize>().unwrap()]]
96:             } else {
97:                 tracks
98:             };
99:             for lateral in tracks {
100:                 let offset = tangent * lateral;
101:                 let start = outer + outward * 0.35 + offset;
102:                 let target = threshold - outward * 0.35 + offset;
103:                 let mut walker = gardens::occupied_walker(
104:                     start,
105:                     threshold,
106:                     apron.dimensions_metres().length() + 6.0,
107:                     &scene.terrain,
108:                     &terrain,
109:                     &buildings,
110:                     &outdoor,

111:                     &input,
112:                     None,
113:                 );
114:                 let arrival = walker.attempt_walk_to(target);
115:                 let arrival_distance = arrival.xz().distance(target);
116:                 let return_position = if arrival_distance < 0.08 {
117:                     walker.attempt_walk_to(start)
118:                 } else {
119:                     arrival
120:                 };
121:                 let return_distance = return_position.xz().distance(start);
122:                 let passed = arrival_distance < 0.08 && return_distance < 0.08;
123:                 observations.push(serde_json::json!({"property_id":owner.property_id(),
124:                     "building_id":building.placement.id,"entrance":door.id,
125:                     "lateral_metres":lateral,"start_metres":start,"target_metres":target,
126:                     "arrival_metres":arrival,"arrival_shortfall_metres":arrival_distance,
127:                     "return_metres":return_position,"return_shortfall_metres":return_distance,"permitted_metres":0.08,"pass":passed,
128:                     "floor_metres":building.placement.base_elevation_metres.metres(),
129:                     "transform_origin_metres":transform.translation}));
130:                 if !passed {
131:                     walker.capture_step_casts(return_position);
132:                     break;
133:                 }
134:             }
135:             if observations.last().is_some_and(|o| o["pass"] == false) {
136:                 break;
137:             }
138:         }
139:         println!(
140:             "single {}: {}",
141:             owner.property_id().0,
142:             if observations.last().is_some_and(|o| o["pass"] == false) {
143:                 "FAIL"
144:             } else {
145:                 "pass"
146:             }
147:         );
148:         if observations.last().is_some_and(|o| o["pass"] == false) {
149:             break;
150:         }
151:     }
152:     if let Ok(path) = std::env::var("FABELGEIST_SINGLE_REPORT") {
153:         std::fs::write(path, serde_json::to_vec_pretty(&serde_json::json!({
154:             "input_digest":input.digest().unwrap(),"observations":observations,
155:             "scope":"Production KCC with complete canonical terrain and exact nearby fixed geometry and production tactical obstacles and outdoor furniture. Unfurnished interiors; vista furniture has no physics. Open building entrances, closed compound gates; centre and both usable-width edges, entry and return."
156:         })).unwrap()).unwrap();
157:     }
158:     assert!(!observations.is_empty());
159:     assert!(
160:         observations.iter().all(|o| o["pass"] == true),
161:         "{:?}",
162:         observations.iter().find(|o| o["pass"] == false)
163:     );
164: }
