1: //! Semantic ground patches derived from the developed city blocks.
2: 
3: use std::collections::BTreeSet;
4: 
5: use bevy::{math::Vec2, prelude::Reflect};
6: use serde::{Deserialize, Serialize};
7: 
8: use super::*;
9: 
10: const SURFACE_EDGE_TOLERANCE_METRES: f32 = 0.001;
11: pub const MAX_CITY_STREET_PATCHES: usize = 12_000;
12: pub const MAX_CITY_YARD_PATCHES: usize = MAX_CITY_LOTS * 3;
13: 
14: /// Historically plausible surface treatment for one part of the urban street network.
15: #[derive(Clone, Copy, Debug, Eq, PartialEq, Reflect, Serialize, Deserialize)]
16: #[serde(rename_all = "snake_case")]
17: pub enum CityStreetSurface {
18:     CompactedEarth,
19:     Gravel,
20:     Fieldstone,
21: }
22: 
23: impl CityStreetSurface {
24:     pub const fn priority(self) -> u8 {
25:         match self {
26:             Self::CompactedEarth => 0,
27:             Self::Gravel => 1,
28:             Self::Fieldstone => 2,
29:         }
30:     }
31: }
32: 
33: /// One bounded surface patch in the connected street network.
34: #[derive(Clone, Copy, Debug, PartialEq, Reflect, Serialize, Deserialize)]
35: #[serde(rename_all = "snake_case", tag = "shape")]
36: pub enum CityStreetPatch {
37:     Corridor {
38:         start_metres: Vec2,
39:         end_metres: Vec2,
40:         half_width_metres: f32,
41:         surface: CityStreetSurface,
42:     },
43:     Market {
44:         corners_metres: [Vec2; 4],
45:         surface: CityStreetSurface,
46:     },
47: }
48: 
49: impl CityStreetPatch {
50:     pub fn surface(self) -> CityStreetSurface {
51:         match self {
52:             Self::Corridor { surface, .. } | Self::Market { surface, .. } => surface,
53:         }
54:     }
55: 
56:     pub fn contains(self, point: Vec2) -> bool {
57:         match self {
58:             Self::Corridor {
59:                 start_metres,
60:                 end_metres,
61:                 half_width_metres,
62:                 ..
63:             } => {
64:                 let displacement = end_metres - start_metres;
65:                 let fraction = ((point - start_metres).dot(displacement)
66:                     / displacement.length_squared())
67:                 .clamp(0.0, 1.0);
68:                 point.distance_squared(start_metres + displacement * fraction)
69:                     <= (half_width_metres + SURFACE_EDGE_TOLERANCE_METRES).powi(2)
70:             }
71:             Self::Market { corners_metres, .. } => convex_quad_contains(corners_metres, point),
72:         }
73:     }
74: 
75:     pub fn is_valid(self) -> bool {
76:         match self {
77:             Self::Corridor {
78:                 start_metres,
79:                 end_metres,
80:                 half_width_metres,
81:                 ..
82:             } => {
83:                 start_metres.is_finite()
84:                     && end_metres.is_finite()
85:                     && start_metres.distance_squared(end_metres).is_finite()
86:                     && start_metres.distance_squared(end_metres) > 0.0
87:                     && half_width_metres.is_finite()
88:                     && (1.0..=20.0).contains(&half_width_metres)
89:             }
90:             Self::Market { corners_metres, .. } => corners_metres.into_iter().all(Vec2::is_finite),
91:         }
92:     }
93: }
94: 
95: /// Surface treatment inside one developed urban block.
96: #[derive(Clone, Copy, Debug, Eq, PartialEq, Reflect, Serialize, Deserialize)]
97: #[serde(rename_all = "snake_case")]
98: pub enum CityYardSurface {
99:     PackedEarth,
100:     KitchenGarden,
101: }
102: 
103: /// One developed block interior beneath its buildings and rear courts.
104: #[derive(Clone, Copy, Debug, PartialEq, Reflect, Serialize, Deserialize)]
105: #[serde(deny_unknown_fields)]
106: pub struct CityYardPatch {
107:     pub corners_metres: [Vec2; 4],
108:     pub surface: CityYardSurface,
109: }
110: 
111: impl CityYardPatch {
112:     pub fn contains(self, point: Vec2) -> bool {
113:         convex_quad_contains(self.corners_metres, point)
114:     }
115: 
116:     pub fn is_valid(self) -> bool {
117:         self.corners_metres.into_iter().all(Vec2::is_finite)
118:             && polygon_area(self.corners_metres).abs() > 1.0
119:     }
120: }
121: 
122: pub(super) fn city_yard_patches(lots: &[CandidateLot]) -> Vec<CityYardPatch> {
123:     let mut patches = Vec::new();
124:     for candidate in lots {
125:         let lot = candidate.lot;
126:         patches.push(CityYardPatch {
127:             corners_metres: plots::corners(plots::reservation(lot)),
128:             surface: CityYardSurface::PackedEarth,
129:         });
130:     }

131:     patches
132: }
133: 
134: pub(super) fn city_street_patches(
135:     graph: &StreetGraph,
136:     developed_blocks: &BTreeSet<BlockId>,
137: ) -> Vec<CityStreetPatch> {
138:     graph.developed_streets(developed_blocks)
139: }
140: 
141: fn convex_quad_contains(corners: [Vec2; 4], point: Vec2) -> bool {
142:     let mut sign = 0.0_f32;
143:     for index in 0..4 {
144:         let start = corners[index];
145:         let end = corners[(index + 1) % 4];
146:         let cross = (end - start).perp_dot(point - start);
147:         if cross == 0.0 {
148:             continue;
149:         }
150:         if sign == 0.0 {
151:             sign = cross.signum();
152:         } else if cross.signum() != sign {
153:             return false;
154:         }
155:     }
156:     true
157: }
158: 
159: fn polygon_area(corners: [Vec2; 4]) -> f32 {
160:     (0..4)
161:         .map(|index| corners[index].perp_dot(corners[(index + 1) % 4]))
162:         .sum::<f32>()
163:         * 0.5
164: }
