combat 106:                 return Ok(MeleeLungeArrival::ArrivesIn(
combat 107:                     AnimationElapsed::from_seconds(fixed_tick_safety)?,
combat 108:                 ));
combat 109:             }
combat 110:             let speed = forward_speed_metres_per_second.metres_per_second();
combat 111:             let acceleration =
combat 112:                 forward_acceleration_metres_per_second_squared.metres_per_second_squared();
