combat 122:             let acceleration_distance = 0.5 * acceleration * acceleration_seconds.powi(2);
combat 123:             let travel_seconds = if distance_metres <= acceleration_distance {
combat 124:                 (2.0 * distance_metres.max(0.0) / acceleration).sqrt()
combat 125:             } else {

126:                 acceleration_seconds + (distance_metres - acceleration_distance) / speed
127:             };
