11: impl TacticalCombatConfig {
12:     /// Makes a validated process-lifetime snapshot available to animation
13:     /// code that runs below Bevy's system-parameter boundary.
14:     pub fn install_runtime_snapshot(&self) -> Result<(), TacticalCombatConfigError> {
15:         self.validate()?;
16:         *runtime_config_lock()
17:             .write()
18:             .expect("tactical combat config lock should not be poisoned") = self.clone();
19:         RUNTIME_CONFIG_VERSION.fetch_add(1, Ordering::Release);
20:         Ok(())
21:     }
22: }
23: 
24: static RUNTIME_CONFIG: OnceLock<RwLock<TacticalCombatConfig>> = OnceLock::new();
25: static RUNTIME_CONFIG_VERSION: AtomicU64 = AtomicU64::new(0);
26: 
27: thread_local! {
28:     static CACHED_ANIMATION_CONFIG: Cell<Option<(u64, TacticalAnimationConfig)>> = const {
29:         Cell::new(None)
30:     };
31: }
32: 
33: fn runtime_config_lock() -> &'static RwLock<TacticalCombatConfig> {
34:     RUNTIME_CONFIG.get_or_init(|| RwLock::new(TacticalCombatConfig::default()))
35: }
36: 
37: /// Returns the active animation tuning selected from runtime YAML. The value
38: /// is copied so animation evaluation never holds a synchronization guard.
39: pub fn runtime_animation_config() -> TacticalAnimationConfig {
40:     let version = RUNTIME_CONFIG_VERSION.load(Ordering::Acquire);
41:     CACHED_ANIMATION_CONFIG.with(|cache| {
42:         if let Some((cached_version, config)) = cache.get()
43:             && cached_version == version
44:         {
45:             return config;
46:         }
47:         let config = runtime_config_lock()
48:             .read()
49:             .expect("tactical combat config lock should not be poisoned")
50:             .animation;
51:         cache.set(Some((version, config)));
52:         config
53:     })
54: }
