14: const DOOR_INTERIOR_SIDE_EPSILON_METRES: f32 = 0.05;
15: 
16: pub fn can_grab_door_from_inside(
17:     character_position: Vec3,
18:     doorway_centre: Vec3,
19:     tangent: Vec3,
20:     outward: Vec3,
21:     half_width_metres: f32,
22: ) -> bool {
23:     let offset = character_position - doorway_centre;
24:     let signed_depth = offset.dot(outward);
25:     let lateral_distance = offset.dot(tangent).abs();
26:     (-DOOR_GRAB_DEPTH_METRES..=-DOOR_INTERIOR_SIDE_EPSILON_METRES).contains(&signed_depth)
27:         && lateral_distance <= half_width_metres + DOOR_GRAB_LATERAL_MARGIN_METRES
28: }
