2: //! landform; neither bedding nor an observed cliff is asserted by the recipe.
3: 
4: use bevy::math::{FloatExt, Vec2, Vec3, Vec3Swizzles};
5: 
6: use crate::{
7:     marching_tetrahedra::marching_tetrahedra,
8:     scene::SceneTerrain,
9:     scene_coordinates::ScenePlanPoint,
10:     volumetric_terrain::{
11:         SceneTerrainPatch, TerrainLandformKind, TerrainLandformRecipe, TerrainRecipeError,
12:         TerrainRecipeResult, support::height_at_extended_edge,
13:     },
14: };
15: 
16: mod basalt;
17: mod carbonate;
18: mod granite;
19: mod slump;
20: 
21: const SAMPLE_MARGIN_CELLS: f32 = 2.0;
22: const MAX_GRID_SIDE: usize = 195;
23: const MAX_GRID_HEIGHT: usize = 96;
24: const SANDSTONE_RECESS_METRES: f32 = 1.6;
25: const SANDSTONE_ROOF_FRACTION: f32 = 0.3;
26: const TALUS_RELIEF_FRACTION: f32 = 0.18;
27: const TALUS_CENTRE_METRES: f32 = 3.0;
28: const TALUS_HALF_WIDTH_METRES: f32 = 4.0;
29: const CARBONATE_RESIDUAL_RELIEF_FRACTION: f32 = 0.05;
30: 
31: pub(crate) fn patch(
32:     terrain: &SceneTerrain,
33:     recipe: TerrainLandformRecipe,
34: ) -> TerrainRecipeResult<SceneTerrainPatch> {
35:     let spacing = f32::from(recipe.lod().voxel_cm()) / 100.0;
36:     let origin = Vec2::new(recipe.origin_cm()[0] as f32, recipe.origin_cm()[1] as f32) / 100.0;
37:     let radius = f32::from(recipe.half_length_cm().max(recipe.half_width_cm())) / 100.0 + 2.0;
38:     let radius = (radius / spacing).ceil() * spacing + spacing;
39:     let side = (radius * 2.0 / spacing).round() as usize + 1;
40:     let mut minimum = f32::INFINITY;
41:     let mut maximum = f32::NEG_INFINITY;
42:     for z in 0..side {
43:         for x in 0..side {
44:             let point = ScenePlanPoint::from_metres(
45:                 origin + Vec2::new(x as f32, z as f32) * spacing - Vec2::splat(radius),
46:             )
47:             .ok_or(TerrainRecipeError::NonFiniteField)?;
48:             let height = height_at_extended_edge(terrain, point)?.metres();
49:             minimum = minimum.min(height);
50:             maximum = maximum.max(height);
51:         }
52:     }
53:     let relief = f32::from(recipe.relief_cm()) / 100.0;
54:     let bottom = ((minimum - relief - spacing * SAMPLE_MARGIN_CELLS) / spacing).floor() * spacing
55:         - spacing * 0.5;
56:     let top = maximum + spacing * SAMPLE_MARGIN_CELLS;
57:     let vertical = ((top - bottom) / spacing).ceil() as usize + 1;
58:     if side > MAX_GRID_SIDE || vertical > MAX_GRID_HEIGHT {
59:         return Err(TerrainRecipeError::ErosionVoxelGridBound);
60:     }
61:     marching_tetrahedra(
62:         [side, vertical, side],
63:         |index| {
64:             Vec3::new(
65:                 origin.x + index[0] as f32 * spacing - radius,
66:                 bottom + index[1] as f32 * spacing,
67:                 origin.y + index[2] as f32 * spacing - radius,
68:             )
69:         },
70:         |position| field(terrain, recipe, position),
71:         recipe.transition_collar(),
72:     )
73: }
74: 
75: fn field(
76:     terrain: &SceneTerrain,
77:     recipe: TerrainLandformRecipe,
78:     point: Vec3,
79: ) -> TerrainRecipeResult<f32> {
80:     let collar = recipe.transition_collar();
81:     let weight = collar.blend_weight(point.xz());
82:     let query =
83:         ScenePlanPoint::from_metres(point.xz()).ok_or(TerrainRecipeError::NonFiniteField)?;
84:     let height = height_at_extended_edge(terrain, query)?;
85:     let base = point.y - height.metres();
86:     if weight <= 0.0 {
87:         return Ok(base);
88:     }
89:     let local = collar.local_coordinates(point.xz());
90:     let tangent = Vec2::new(
91:         f32::from(recipe.tangent_permyriad()[0]),
92:         f32::from(recipe.tangent_permyriad()[1]),
93:     )
94:     .normalize();
95:     let downhill = Vec2::new(-tangent.y, tangent.x);
96:     let foot_distance = f32::from(recipe.half_width_cm() - recipe.collar_cm()) / 100.0;
97:     // Grade to the existing downhill foot. Subtracting relief from every local
98:     // height would create a closed trench when the collar returned uphill.
99:     let foot_point = ScenePlanPoint::from_metres(point.xz() + downhill * (foot_distance - local.y))
100:         .ok_or(TerrainRecipeError::NonFiniteField)?;
101:     let foot = height_at_extended_edge(terrain, foot_point)?;
102:     let relief = (height.metres() - foot.metres())
103:         .max(0.001)
104:         .min(f32::from(recipe.relief_cm()) / 100.0);
105:     let depth_fraction = ((height.metres() - point.y) / relief).clamp(0.0, 1.0);
106:     // A thick upper ledge remains above a shallow weathering alcove. This is
107:     // variation within sandstone, not an invented sandstone/shale contact.
108:     let recess = ((depth_fraction - SANDSTONE_ROOF_FRACTION) / (1.0 - SANDSTONE_ROOF_FRACTION)
109:         * std::f32::consts::PI)
110:         .sin()
111:         .max(0.0);
112:     let (front, debris_fraction) = match recipe.kind() {
113:         TerrainLandformKind::SandstoneAlcove => (
114:             -SANDSTONE_RECESS_METRES.min(relief * 0.35) * recess,
115:             TALUS_RELIEF_FRACTION,
116:         ),
117:         TerrainLandformKind::CarbonateDissolution => (
118:             carbonate::front(local.x, depth_fraction, relief, recipe.seed()),
119:             CARBONATE_RESIDUAL_RELIEF_FRACTION,
120:         ),
121:         TerrainLandformKind::GraniteJointRockfall => (
122:             granite::front(local.x, depth_fraction, relief, recipe.seed()),
123:             TALUS_RELIEF_FRACTION,
124:         ),
125:         TerrainLandformKind::BasaltCoolingColumns => {
126:             (basalt::front(local.x, recipe.seed()), TALUS_RELIEF_FRACTION)
127:         }
128:         TerrainLandformKind::CohesiveSlumpHeadscarp => {
129:             (slump::front(local.x, depth_fraction, relief), 0.0)
130:         }

131:         TerrainLandformKind::FaultScarp => unreachable!("faults use the displacement field"),
132:     };
133:     let talus = (1.0 - ((local.y - TALUS_CENTRE_METRES) / TALUS_HALF_WIDTH_METRES).abs()).max(0.0)
134:         * relief
135:         * debris_fraction;
136:     let retained_material = match recipe.kind() {
137:         TerrainLandformKind::GraniteJointRockfall => granite::fragments(local.x, local.y, relief),
138:         TerrainLandformKind::CohesiveSlumpHeadscarp => slump::bench(local.x, local.y),
139:         _ => 0.0,
140:     };
141:     let floor = foot.metres() + talus + retained_material;
142:     let cut = (local.y - front).min(point.y - floor);
143:     Ok(base.lerp(base.max(cut), weight))
144: }
