309:     fn assert_sound_mesh_lod(kind: TerrainLandformKind, lod: TerrainLandformLod) {
310:         let terrain =
311:             SceneTerrain::new(60, 60, 1.0, |p| -(p.y - 30.0) * 0.4 + (p.x - 30.0) * 0.03).unwrap();
312:         let recipe = TerrainLandformRecipe::from_quantized(
313:             crate::volumetric_terrain::QuantizedLandformRecipe {
314:                 kind,
315:                 lod,
316:                 ..crate::volumetric_terrain::QuantizedLandformRecipe::from(recipe())
317:             },
318:         )
319:         .unwrap();
320:         let generate = |threads| {
321:             rayon::ThreadPoolBuilder::new()
322:                 .num_threads(threads)
323:                 .build()
324:                 .unwrap()
325:                 .install(|| {
326:                     crate::volumetric_terrain::terrain_landform_patch(&terrain, recipe).unwrap()
327:                 })
328:         };
329:         let mesh = generate(1);
330:         assert_eq!(mesh, generate(4));
331:         let mut edges = HashMap::<(u32, u32), (usize, i32)>::new();
332:         for triangle in mesh.indices().as_chunks::<3>().0 {
333:             let [a, b, c] = triangle.map(|i| Vec3::from_array(mesh.positions()[i as usize]));
334:             assert!(a.is_finite() && b.is_finite() && c.is_finite());
335:             assert!((b - a).cross(c - a).length_squared() > 0.0);
336:             for (a, b) in [
337:                 (triangle[0], triangle[1]),
338:                 (triangle[1], triangle[2]),
339:                 (triangle[2], triangle[0]),
340:             ] {
341:                 let entry = edges.entry((a.min(b), a.max(b))).or_default();
342:                 entry.0 += 1;
343:                 entry.1 += if a < b { 1 } else { -1 };
344:             }
345:         }
346:         for ((a, b), (count, direction_sum)) in edges {
347:             let midpoint = (Vec3::from_array(mesh.positions()[a as usize])
348:                 + Vec3::from_array(mesh.positions()[b as usize]))
349:                 * 0.5;
350:             assert!(count <= 2);
351:             if count == 2 {
352:                 assert_eq!(
353:                     direction_sum, 0,
354:                     "adjacent faces must wind opposite ways on their shared edge"
355:                 );
356:             }
357:             if crate::scene_coordinates::ScenePlanPoint::try_from(midpoint.xz())
358:                 .is_ok_and(|point| recipe.transition_collar().contains(point))
359:             {
360:                 assert_eq!(
361:                     count,
362:                     2,
363:                     "interior edge {:?} -> {:?}",
364:                     mesh.positions()[a as usize],
365:                     mesh.positions()[b as usize]
366:                 );
367:             }
368:         }
369:         if matches!(
370:             kind,
371:             TerrainLandformKind::BasaltCoolingColumns | TerrainLandformKind::CohesiveSlumpHeadscarp
372:         ) {
373:             let vertical_area: f32 = mesh
374:                 .indices()
375:                 .as_chunks::<3>()
376:                 .0
377:                 .iter()
378:                 .map(|triangle| {
379:                     let [a, b, c] =
380:                         triangle.map(|i| Vec3::from_array(mesh.positions()[i as usize]));
381:                     let cross = (b - a).cross(c - a);
382:                     if cross.normalize().y.abs() < 0.025 {
383:                         cross.length() * 0.5
384:                     } else {
385:                         0.0
386:                     }
387:                 })
388:                 .sum();
389:             assert!(vertical_area > 5.0, "vertical area {vertical_area}");
390:         } else if kind != TerrainLandformKind::FaultScarp {
391:             assert!(mesh.normals().iter().any(|normal| normal[1] < -0.2));
392:         }
393:         assert!(mesh.triangle_count() < 150000);
394:     }
395: }

