590: pub(super) fn body_part_index(part: BodyPart) -> usize {
591:     match part {
592:         BodyPart::LeftArm => 0,
593:         BodyPart::RightArm => 1,
594:         BodyPart::LeftLeg => 2,
595:         BodyPart::RightLeg => 3,
596:         BodyPart::Chest => 4,
597:         BodyPart::Stomach => 5,
598:         BodyPart::Head => 6,
599:     }
600: }
601: 
602: /// Requires `ItemOf` to already be on the entity: single-component inserts
603: /// in every live equip path place `ItemOf` first, and batched inserts
604: /// (spawn bundles, replication) run hooks only after the whole batch has
605: /// landed. The one path where neither holds - `bevy_scene` applying
606: /// components one at a time in an order that puts `EquipSlot` before
607: /// `ItemOf` - doesn't need this hook at all, because scenes capture and
608: /// restore `InventoryItems` (holding fields included) as data.
609: fn on_equip_slot_replaced(mut world: DeferredWorld, ctx: HookContext) {
610:     match world.get::<EquipSlot>(ctx.entity) {
611:         Some(EquipSlot::HoldingLeft | EquipSlot::HoldingRight)
612:             if world.get::<WeaponItem>(ctx.entity).is_some() =>
613:         {
614:             let Some(root) = world.get::<ItemOf>(ctx.entity).map(|i| i.0) else {
615:                 return;
616:             };
617:             let Some(mut items) = world.get_mut::<InventoryItems>(root) else {
618:                 return;
619:             };
620:             items.holding_weapon = Some(ctx.entity);
621:         }
622:         Some(EquipSlot::HoldingLeft | EquipSlot::HoldingRight)
623:             if world.get::<ShieldItem>(ctx.entity).is_some() =>
624:         {
625:             let Some(root) = world.get::<ItemOf>(ctx.entity).map(|i| i.0) else {
626:                 return;
627:             };
628:             let Some(mut items) = world.get_mut::<InventoryItems>(root) else {
629:                 return;
630:             };
631:             items.holding_shield = Some(ctx.entity);
632:         }
633:         _ => {}
634:     }
635: }
636: 
637: fn on_equip_slot_removed(mut world: DeferredWorld, ctx: HookContext) {
638:     let Some(root) = world.get::<ItemOf>(ctx.entity).map(|i| i.0) else {
639:         return;
640:     };
641:     let Some(mut items) = world.get_mut::<InventoryItems>(root) else {
642:         return;
643:     };
644: 
645:     if items.holding_weapon == Some(ctx.entity) {
646:         items.holding_weapon = None;
647:     }
648:     if items.holding_shield == Some(ctx.entity) {
649:         items.holding_shield = None;
650:     }

651: }
