1: //! Equipment command ordering and authoritative mutation revisions.
2: 
3: use bevy::prelude::*;
4: use serde::{Deserialize, Serialize};
5: 
6: /// Forward distances below half the wrapping u32 space are unambiguous.
7: const MAX_FORWARD_SEQUENCE_DISTANCE: u32 = u32::MAX / 2;
8: 
9: /// Client equipment-command chronology, independent of simulation input ticks.
10: /// Zero is a valid command sequence after wraparound.
11: #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, Reflect)]
12: #[serde(transparent)]
13: #[reflect(opaque)]
14: #[reflect(Serialize, Deserialize)]
15: pub struct EquipmentSequence(u32);
16: 
17: /// Replicated equipment mutation revision; zero is the actual initial state.
18: #[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize, Reflect)]
19: #[serde(transparent)]
20: #[reflect(opaque)]
21: #[reflect(Serialize, Deserialize)]
22: pub struct EquipmentRevision(u32);
23: 
24: impl Default for EquipmentSequence {
25:     fn default() -> Self {
26:         Self::FIRST
27:     }
28: }
29: 
30: impl EquipmentSequence {
31:     pub const FIRST: Self = Self(1);
32: 
33:     /// Admit the complete native u32 protocol representation, including zero.
34:     pub const fn from_encoded(value: u32) -> Self {
35:         Self(value)
36:     }
37: 
38:     pub const fn encoded(self) -> u32 {
39:         self.0
40:     }
41: 
42:     pub const fn next(self) -> Self {
43:         Self(self.0.wrapping_add(1))
44:     }
45: 
46:     pub const fn is_newer_than(self, previous: Self) -> bool {
47:         let distance = self.0.wrapping_sub(previous.0);
48:         distance != 0 && distance <= MAX_FORWARD_SEQUENCE_DISTANCE
49:     }
50: 
51:     /// Preserve the initial command window without inventing a prior command.
52:     /// The first client send is one; later first observations may also lie in
53:     /// the forward half-window. A wrapped zero needs an actual prior sequence.
54:     pub const fn is_admissible_after(self, previous: Option<Self>) -> bool {
55:         match previous {
56:             Some(previous) => self.is_newer_than(previous),
57:             None => self.0 >= Self::FIRST.0 && self.0 <= MAX_FORWARD_SEQUENCE_DISTANCE,
58:         }
59:     }
60: }
61: 
62: impl EquipmentRevision {
63:     pub const INITIAL: Self = Self(0);
64: 
65:     pub const fn from_encoded(value: u32) -> Self {
66:         Self(value)
67:     }
68: 
69:     pub const fn encoded(self) -> u32 {
70:         self.0
71:     }
72: 
73:     pub const fn next(self) -> Self {
74:         Self(self.0.wrapping_add(1))
75:     }
76: }

