1: //! Replication-stable ordering of body-root equipment. Entity allocation order
2: //! is deliberately absent: a client remaps every server entity independently.
3: use super::{EquipmentTopology, TacticalEquipmentAnchor};
4: use adventuresim_core::item_catalog::{self, EquipmentFitZone, EquipmentLocation};
5: use std::cmp::Reverse;
6: 
7: #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
8: pub struct EquipmentRootOrder<'a> {
9:     channel: Reverse<u8>,
10:     layer: Reverse<u16>,
11:     fit_zone: Option<EquipmentFitZone>,
12:     item_id: &'a str,
13:     placement_id: Option<&'a str>,
14: }
15: 
16: impl EquipmentTopology {
17:     /// Outermost layers first, then anatomical fit zone and authored identity.
18:     /// Valid equipped roots cannot share a location/channel/order/fit zone;
19:     /// catalog identity supplies a stable secondary key without network IDs.
20:     pub fn root_order<'a>(
21:         &'a self,
22:         location: EquipmentLocation,
23:         item_id: &'a str,
24:     ) -> Option<EquipmentRootOrder<'a>> {
25:         let placement = item_catalog::definition(item_id)
26:             .and_then(|definition| definition.equipment.as_ref())
27:             .and_then(|equipment| {
28:                 equipment
29:                     .placements
30:                     .iter()
31:                     .find(|placement| Some(placement.id.as_str()) == self.placement_id.as_deref())
32:             });
33:         self.occupancies
34:             .iter()
35:             .filter_map(|occupancy| {
36:                 if occupancy.anchor != TacticalEquipmentAnchor::CharacterLocation(location) {
37:                     return None;
38:                 }
39:                 let fit_zone = placement
40:                     .and_then(|placement| {
41:                         placement
42:                             .occupancy
43:                             .get(usize::from(occupancy.requirement_index))
44:                     })
45:                     .filter(|requirement| {
46:                         requirement.location == location && requirement.channel == occupancy.channel
47:                     })
48:                     .and_then(|requirement| requirement.fit_zone);
49:                 Some(EquipmentRootOrder {
50:                     channel: Reverse(occupancy.channel.order()),
51:                     layer: Reverse(occupancy.order),
52:                     fit_zone,
53:                     item_id,
54:                     placement_id: self.placement_id.as_deref(),
55:                 })
56:             })
57:             .min()
58:     }
59: }
