76:                 .placements[0];
77:             let topology = EquipmentTopology {
78:                 placement_id: Some(placement.id.clone()),
79:                 occupancies: placement
80:                     .occupancy
81:                     .iter()
82:                     .enumerate()
83:                     .map(|(index, requirement)| EquipmentTopologyOccupancy {
84:                         occupancy_id: format!("{item_id}:{index}"),
85:                         anchor: TacticalEquipmentAnchor::CharacterLocation(requirement.location),
86:                         channel: requirement.channel,
87:                         order: requirement.order,
88:                         requirement_index: index as u16,
89:                         capacity_index: 0,
90:                     })
91:                     .collect(),
92:             };
93:             (item_id, topology)
94:         });
95:         let server_entities = [
96:             Entity::from_bits(10),
97:             Entity::from_bits(20),
98:             Entity::from_bits(30),
99:         ];
100:         let client_entities = [
101:             Entity::from_bits(300),
102:             Entity::from_bits(200),
103:             Entity::from_bits(100),
104:         ];
105:         let order = |entities: [Entity; 3]| {
106:             let mut local_roots = roots.iter().zip(entities).collect::<Vec<_>>();
107:             local_roots
108:                 .sort_by_key(|((item_id, topology), _)| topology.root_order(location, item_id));
109:             local_roots
110:                 .into_iter()
111:                 .map(|(_, entity)| entity)
112:                 .collect::<Vec<_>>()
113:         };
114:         let mapped_server_order = order(server_entities)
115:             .into_iter()
116:             .map(|entity| {
117:                 client_entities[server_entities
118:                     .iter()
119:                     .position(|server| *server == entity)
120:                     .unwrap()]
121:             })
122:             .collect::<Vec<_>>();
123:         assert_eq!(order(client_entities), mapped_server_order);
124:         assert_eq!(
125:             order(client_entities),
126:             client_entities,
127:             "fit zones traverse upper arm, elbow, forearm"
128:         );
129:     }
130: }

