21: #[test]
22: fn trimmed_height_extraction_preserves_ordered_mesh_buffers() {
23:     let dimensions = [8, 13, 7];
24:     let position_at = |[x, y, z]: [usize; 3]| {
25:         Vec3::new(
26:             x as f32 * 0.5 - 2.0,
27:             y as f32 * 0.25 - 1.0,
28:             z as f32 * 0.5 - 2.0,
29:         )
30:     };
31:     for fixture in 0..6 {
32:         let heights = (0..dimensions[0] * dimensions[2])
33:             .map(|column| {
34:                 let x = column % dimensions[0];
35:                 let z = column / dimensions[0];
36:                 match fixture {
37:                     0 => 0.0,
38:                     1 => x as f32 * 0.25 - 0.5,
39:                     2 => {
40:                         if x < 4 {
41:                             -2.0
42:                         } else {
43:                             3.0
44:                         }
45:                     }
46:                     3 => (x as f32 * 0.7).sin() + (z as f32 * 0.4).cos() * 0.3,
47:                     4 => {
48:                         if (x + z) % 2 == 0 {
49:                             0.000009
50:                         } else {
51:                             -0.000011
52:                         }
53:                     }
54:                     _ => x as f32 * 0.25 + z as f32 * 0.125 - 0.5,
55:                 }
56:             })
57:             .collect::<Vec<_>>();
58:         let dense = marching_tetrahedra(
59:             dimensions,
60:             position_at,
61:             |point| {
62:                 let x = ((point.x + 2.0) * 2.0) as usize;
63:                 let z = ((point.z + 2.0) * 2.0) as usize;
64:                 Ok(point.y - heights[z * dimensions[0] + x])
65:             },
66:             collar(),
67:         )
68:         .unwrap();
69:         let trimmed = marching_height_surface(dimensions, position_at, &heights, collar()).unwrap();
70:         assert_eq!(trimmed, dense, "height fixture {fixture}");
71:     }
72: }
