165: const QUICKSTEP_FORCE_CURVE_RAMP_FRACTION: f32 = 0.31;
166: /// Smooth rise, maximal mid-push force, and smooth release. Its normalized
167: /// area is 0.69, matching the force-time profile used to calibrate the
168: /// biomechanical values in `combat.yaml`.
169: pub fn quickstep_force_curve(normalized_time: f32) -> f32 {
170:     let t = normalized_time.clamp(0.0, 1.0);
171:     let edge = t.min(1.0 - t);
172:     if edge >= QUICKSTEP_FORCE_CURVE_RAMP_FRACTION {
173:         1.0
174:     } else {
175:         let x = edge / QUICKSTEP_FORCE_CURVE_RAMP_FRACTION;
176:         x * x * (3.0 - 2.0 * x)
177:     }
178: }
