215: /// Scales the authored reference travel by the character's hip-to-ankle chain.
216: pub fn quickstep_target_displacement_metres(
217:     leg_length_metres: f32,
218:     motor: &crate::combat_config::CharacterMotorConfig,
219: ) -> f32 {
220:     let reference_leg_length = motor.reference_quickstep_leg_length_metres;
221:     let leg_length = if leg_length_metres.is_finite() && leg_length_metres > 0.0 {
222:         leg_length_metres
223:     } else {
224:         reference_leg_length
225:     };
226:     motor.reference_quickstep_target_displacement_metres * leg_length / reference_leg_length
227: }
