332: fn apply_character_motor(
333:     time: Res<Time<Fixed>>,
334:     mut commands: Commands,
335:     mut controllers: MovementControllerQuery<'_, '_>,
336:     viewer: TacticalPlayerViewer,
337:     dimensions: Query<&CharacterDimensions>,
338:     combat_config: Res<crate::combat_config::TacticalCombatConfig>,
339: ) {
340:     let movement_config = &combat_config.movement;
341:     let speeds = &movement_config.speeds_metres_per_second;
342:     for (
343:         entity,
344:         input,
345:         mut controller,
346:         controller_state,
347:         mut velocity,
348:         mass_component,
349:         look,
350:         skeleton,
351:         pace,
352:         quickstep_push,
353:         melee_lunge,
354:         transform,
355:         mismatch_logged,
356:     ) in &mut controllers
357:     {
358:         let attack_quickstep_ended = melee_lunge.is_some_and(|lunge| lunge.quickstep)
359:             && !skeleton.is_some_and(|skeleton| {
360:                 skeleton.action_kind() == crate::animation::SkeletonAction::Attack
361:             });
362:         let melee_lunge = melee_lunge.filter(|_| {
363:             skeleton.is_some_and(|skeleton| {
364:                 skeleton.action_kind() == crate::animation::SkeletonAction::Attack
365:             })
366:         });
367:         if melee_lunge.is_none() {
368:             commands.entity(entity).remove::<MeleeLungeMovement>();
369:         }
370:         // Ahoy's crouch flag supplies the short collider used by downed and
371:         // posture-transition states. Their configured speeds are already the
372:         // final physical targets, so the collider must not scale speed again.
373:         controller.crouch_speed_scale = 1.0;
374:         let maneuver_jump_height = skeleton.and_then(|skeleton| {
375:             match skeleton
376:                 .posture_transition()
377:                 .map(|transition| transition.kind())
378:             {
379:                 Some(crate::animation::PostureTransitionKind::DiveToDowned {
380:                     trajectory: crate::animation::DiveTrajectory::Airborne,
381:                     ..
382:                 }) => Some(movement_config.jump_heights_metres.dive),
383:                 Some(crate::animation::PostureTransitionKind::DiveToDowned {
384:                     trajectory: crate::animation::DiveTrajectory::GroundedSlide,
385:                     ..
386:                 }) => Some(0.0),
387:                 _ => None,
388:             }
389:         });
390:         let motor = &movement_config.motor;

391:         controller_config::apply_motor_config(&mut controller, motor);
392:         let guard = skeleton.map_or(WeaponGuardState::Lowered, SkeletonState::weapon_guard);
393:         let roll_motion =
394:             skeleton.map_or(DownedRollMotion::REST, SkeletonState::downed_lateral_motion);
395:         if roll_motion.is_moving() {
396:             controller.speed = speeds.roll.metres_per_second() * roll_motion.fraction().abs();
397:         } else if skeleton.is_some_and(SkeletonState::is_posture_transitioning) {
398:             controller.speed = 0.0;
399:         } else if skeleton.is_some_and(|skeleton| {
400:             skeleton.action_kind() == crate::animation::SkeletonAction::Dodge
401:                 && skeleton.action_direction() != Vec2::ZERO
402:         }) {
403:             controller.speed = speeds.quickstep.metres_per_second();
404:         } else if let Some(lunge) = melee_lunge {
405:             controller.speed = if lunge.quickstep {
406:                 speeds.quickstep.metres_per_second()
407:             } else {
408:                 speeds.run.metres_per_second()
409:             };
410:         } else {
411:             controller.speed = match movement_speed::ordinary_controller_speed(
412:                 input.last_movement,
413:                 pace.copied(),
414:                 guard,
415:                 skeleton.map(SkeletonState::body),
416:                 viewer.get(entity).ok(),
417:                 movement_config,
418:             ) {
419:                 Ok(speed) => speed.metres_per_second(),
420:                 Err(error) => {
421:                     warn!(%error, ?entity, "Rejected character movement speed");
422:                     continue;
423:                 }
424:             };
425:         }
426: 
427:         let (mass_kg, biological_mass_kg, leg_strength, leg_agility) = viewer.get(entity).map_or(
428:             (
429:                 motor.fallback_character_mass_kg,
430:                 motor.fallback_character_mass_kg,
431:                 motor.reference_leg_strength,
432:                 motor.reference_leg_agility,
433:             ),
434:             |player| {
435:                 let burden = player.body_weight() + player.inventory_weight();
436:                 let left_health = player.body_part_health(BodyPart::LeftLeg).max(0.0);
437:                 let right_health = player.body_part_health(BodyPart::RightLeg).max(0.0);
438:                 (
439:                     burden.max(1.0),
440:                     player.body_weight().max(1.0),
441:                     (player.raw_limb_attr(LimbAttribute::Strength, BodyPart::LeftLeg)
442:                         * left_health
443:                         + player.raw_limb_attr(LimbAttribute::Strength, BodyPart::RightLeg)
444:                             * right_health)
445:                         * 0.5,
446:                     (player.raw_limb_attr(LimbAttribute::Agility, BodyPart::LeftLeg) * left_health
447:                         + player.raw_limb_attr(LimbAttribute::Agility, BodyPart::RightLeg)
448:                             * right_health)
449:                         * 0.5,
450:                 )
451:             },
452:         );
453:         if let Some(mut mass) = mass_component {
454:             mass.0 = mass_kg;
455:         } else {
456:             commands.entity(entity).insert(Mass(mass_kg));
457:         }
458:         controller.jump_height = maneuver_jump_height.unwrap_or_else(|| {
459:             ordinary_jump_height(
460:                 movement_config.jump_heights_metres.ordinary,
461:                 mass_kg,
462:                 leg_strength,
463:                 leg_agility,
464:                 motor,
465:             )
466:         });
467: 
468:         let orientation = look.map_or(controller_state.orientation, CharacterLook::to_quat);
469: 
470:         let quickstep_action = skeleton.is_some_and(|skeleton| {
471:             skeleton.action_kind() == crate::animation::SkeletonAction::Dodge
472:                 && skeleton.action_direction() != Vec2::ZERO
473:         });
474:         let attack_quickstep = melee_lunge.is_some_and(|lunge| lunge.quickstep);
475:         let quickstep_push_present = quickstep_push.is_some();
476:         let quickstep_push_active = quickstep_push.as_ref().is_some_and(|push| push.active);
477:         if let Some(mut push) = quickstep_push {
478:             if attack_quickstep_ended {
479:                 push.cancel();
480:             }
481:             let world_direction = (push.orientation
482:                 * Vec3::new(push.direction.x, 0.0, -push.direction.y))
483:             .xz()
484:             .normalize_or_zero();
485:             let action_duration = movement_config.maneuvers.quickstep_duration_seconds;
486:             let clock = push.sample_clock(skeleton, action_duration);
487:             let elapsed_ticks = clock.elapsed;
488:             let forward_velocity = velocity.xz().dot(world_direction);
489:             let bounded_recovery = clock.bounded_recovery(quickstep_action, forward_velocity);
490:             if push.active && (quickstep_action || attack_quickstep || bounded_recovery) {
491:                 let support_duration = match quickstep_push_duration(leg_agility, motor) {
492:                     Ok(duration) => duration,
493:                     Err(error) => {
494:                         warn!(%error, ?entity, "Rejected quickstep support duration");
495:                         continue;
496:                     }
497:                 };
498:                 let velocity_before = velocity.0;
499:                 if mismatch_logged {
500:                     commands.entity(entity).remove::<QuickstepMismatchLogged>();
501:                 }
502:                 let displacement = (transform.translation - push.origin)
503:                     .xz()
504:                     .dot(world_direction)
505:                     .max(0.0);
506:                 if let Some(lunge) = melee_lunge
507:                     && lunge.quickstep
508:                     && melee_lunge_has_arrived(displacement, lunge.distance_metres)
509:                 {
510:                     push.cancel();
511:                     commands.entity(entity).remove::<MeleeLungeMovement>();
512:                     continue;
513:                 }
514:                 // Target the state produced by this integration step. Sampling
515:                 // the current tick leaves one full force step of momentum for
516:                 // ordinary locomotion to clean up after the dodge has ended.
517:                 let phase = clock.target_phase();
518:                 let leg_length = dimensions
519:                     .get(entity)
520:                     .map_or(motor.reference_quickstep_leg_length_metres, |dimensions| {

521:                         dimensions.leg_length_metres
522:                     });
523:                 let target_displacement = melee_lunge.map_or_else(
524:                     || quickstep_target_displacement_metres(leg_length, motor),
525:                     |lunge| {
526:                         quickstep_target_displacement_metres(leg_length, motor)
527:                             .min(lunge.distance_metres)
528:                     },
529:                 );
530:                 let target = match quickstep_motion_target(
531:                     phase,
532:                     target_displacement,
533:                     action_duration.elapsed(),
534:                     motor.quickstep_authored_displacement_profile,
535:                 ) {
536:                     Ok(target) => target,
537:                     Err(error) => {
538:                         warn!(%error, ?entity, "Rejected quickstep target speed");
539:                         continue;
540:                     }
541:                 };
542:                 let forward_speed = match SignedSpeed::from_metres_per_second(forward_velocity) {
543:                     Ok(speed) => speed,
544:                     Err(error) => {
545:                         warn!(%error, ?entity, "Rejected quickstep observed speed");
546:                         continue;
547:                     }
548:                 };
549:                 let maximum_force = quickstep_peak_horizontal_force_newtons(
550:                     biological_mass_kg,
551:                     leg_strength,
552:                     motor,
553:                 );
554:                 let tracking_force = quickstep_tracking_force_newtons(
555:                     displacement,
556:                     forward_speed,
557:                     target,
558:                     mass_kg,
559:                     maximum_force,
560:                     AnimationElapsed::from(time.delta()),
561:                 );
562:                 let planar_delta =
563:                     world_direction * tracking_force / mass_kg.max(1.0) * time.delta_secs();
564:                 velocity.x += planar_delta.x;
565:                 velocity.z += planar_delta.y;
566:                 if !quickstep_action
567:                     && !attack_quickstep
568:                     && velocity.xz().dot(world_direction).abs() <= 0.02
569:                 {
570:                     push.cancel();
571:                 }
572: 
573:                 let support_ticks = AnimationSampleSpan::from(
574:                     (support_duration.seconds() * locomotion_sample_rate().hertz())
575:                         .ceil()
576:                         .max(1.0) as u64,
577:                 );
578:                 let length_scale =
579:                     target_displacement / motor.reference_quickstep_target_displacement_metres;
580:                 if elapsed_ticks < support_ticks
581:                     && displacement
582:                         < motor.quickstep_maximum_supported_root_displacement_metres * length_scale
583:                 {
584:                     // While the virtual legs remain in contact, their baseline
585:                     // normal force supports body weight. Ahoy therefore must
586:                     // not apply airborne gravity yet; only the excess vertical
587:                     // ground-reaction force changes vertical velocity.
588:                     controller.gravity = 0.0;
589:                     let support_phase =
590:                         (elapsed_ticks.samples() as f32 + 0.5) / support_ticks.samples() as f32;
591:                     let force_scale = quickstep_force_curve(support_phase);
592:                     let horizontal_force = maximum_force * force_scale;
593:                     let vertical_net_force =
594:                         horizontal_force * motor.quickstep_takeoff_angle_degrees.to_radians().tan();
595:                     velocity.y += vertical_net_force / mass_kg * time.delta_secs();
596:                 }
597:                 info!(
598:                     target: "quickstep_trace",
599:                     ?entity,
600:                     skeleton_tick = skeleton.map_or(0, |skeleton| skeleton.locomotion_sample_tick.encoded()),
601:                     push_start_tick = push.start_tick.encoded(),
602:                     elapsed_ticks = elapsed_ticks.samples(),
603:                     ?world_direction,
604:                     phase,
605:                     displacement,
606:                     forward_velocity,
607:                     target_displacement = target.displacement_metres,
608:                     target_velocity = target.velocity_metres_per_second.metres_per_second(),
609:                     target_acceleration = target.acceleration_metres_per_second_squared,
610:                     tracking_force,
611:                     maximum_force,
612:                     ?velocity_before,
613:                     velocity_after = ?velocity.0,
614:                     grounded = ?controller_state.grounded,
615:                     "[quickstep][motor-pre-collision] integrated force"
616:                 );
617:                 continue;
618:             }
619:             if push.active && !quickstep_action && !attack_quickstep {
620:                 push.cancel();
621:             }
622:         }
623:         if quickstep_action {
624:             if !mismatch_logged {
625:                 warn!(
626:                     target: "quickstep_trace",
627:                     ?entity,
628:                     skeleton_tick = skeleton.map_or(0, |skeleton| skeleton.locomotion_sample_tick.encoded()),
629:                     action_direction = ?skeleton.map_or(Vec2::ZERO, SkeletonState::action_direction),
630:                     push_present = quickstep_push_present,
631:                     push_active = quickstep_push_active,
632:                     translation = ?transform.translation,
633:                     linear_velocity = ?velocity.0,
634:                     "[quickstep][motor] dodge animation has no active force actuator"
635:                 );
636:                 commands.entity(entity).insert(QuickstepMismatchLogged);
637:             }
638:             // A missing actuator can occur only during partial state restore.
639:             // Stop through the same bounded leg force instead of snapping the
640:             // velocity so rollback recovery remains physically continuous.
641:             let maximum_force =
642:                 quickstep_peak_horizontal_force_newtons(biological_mass_kg, leg_strength, motor);
643:             let requested_force = -velocity.xz() * mass_kg.max(1.0) / time.delta_secs();
644:             let force = requested_force.clamp_length_max(maximum_force);
645:             velocity.x += force.x / mass_kg.max(1.0) * time.delta_secs();
646:             velocity.z += force.y / mass_kg.max(1.0) * time.delta_secs();
647:             continue;
648:         }
649:         if mismatch_logged {
650:             commands.entity(entity).remove::<QuickstepMismatchLogged>();

651:         }
652:         if let Some(transition) = skeleton.and_then(SkeletonState::posture_transition)
653:             && matches!(
654:                 transition.kind(),
655:                 crate::animation::PostureTransitionKind::DiveToDowned {
656:                     trajectory: crate::animation::DiveTrajectory::GroundedSlide,
657:                     ..
658:                 }
659:             )
660:         {
661:             // The authored first half lowers the body while retaining exact
662:             // sprint momentum. After body contact, integrate bounded kinetic
663:             // drag; do not hand the slide to the ordinary target-speed motor.
664:             if transition.phase().fraction() >= 0.5 && controller_state.grounded.is_some() {
665:                 let next = slide_drag_velocity(velocity.xz(), motor, time.delta_secs());
666:                 velocity.x = next.x;
667:                 velocity.z = next.y;
668:             }
669:             continue;
670:         }
671:         let movement = input.last_movement.unwrap_or_default();
672:         let forward = (orientation * Vec3::NEG_Z).with_y(0.0).normalize_or_zero();
673:         let right = (orientation * Vec3::X).with_y(0.0).normalize_or_zero();
674:         let desired_direction = if let Some(lunge) = melee_lunge {
675:             let travelled = (transform.translation - lunge.origin)
676:                 .xz()
677:                 .dot(lunge.direction)
678:                 .max(0.0);
679:             if melee_lunge_has_arrived(travelled, lunge.distance_metres) {
680:                 commands.entity(entity).remove::<MeleeLungeMovement>();
681:                 Vec3::ZERO
682:             } else {
683:                 Vec3::new(lunge.direction.x, 0.0, lunge.direction.y)
684:             }
685:         } else {
686:             (movement.y * forward + movement.x * right).normalize_or_zero()
687:         };
688:         let grounded = controller_state.grounded.is_some();
689:         let strength_scale = (leg_strength.max(0.0) / motor.reference_leg_strength).max(0.0);
690:         let agility_scale = (leg_agility.max(0.0) / motor.reference_leg_agility).max(0.0);
691:         let (drive_force, braking_force) =
692:             character_motor_force_limits(motor, mass_kg, strength_scale);
693:         let horizontal = velocity.xz();
694:         let target_speed = controller.speed;
695:         let target = desired_direction.xz() * target_speed;
696:         let next = if grounded {
697:             let traction_acceleration =
698:                 motor.gravity_metres_per_second_squared * motor.traction_coefficient;
699:             let sustained_lateral_acceleration = (motor.gravity_metres_per_second_squared
700:                 * motor.reference_lateral_acceleration_gravities
701:                 * agility_scale)
702:                 .min(traction_acceleration);
703:             let lateral_acceleration = cut_lateral_acceleration(
704:                 horizontal,
705:                 desired_direction.xz(),
706:                 sustained_lateral_acceleration,
707:                 traction_acceleration,
708:                 leg_agility,
709:             );
710:             let reference_turn_radius = agility_sprint_turn_radius(leg_agility, motor);
711:             let observed_speed = match NonnegativeSpeed::from_metres_per_second(horizontal.length())
712:             {
713:                 Ok(speed) => speed,
714:                 Err(error) => {
715:                     warn!(%error, ?entity, "Rejected ordinary turn speed");
716:                     continue;
717:                 }
718:             };
719:             let turn_radius = ordinary_turn_radius(observed_speed, reference_turn_radius);
720:             approach_ground_velocity(
721:                 horizontal,
722:                 target,
723:                 GroundVelocityLimits {
724:                     drive_acceleration: drive_force / mass_kg,
725:                     braking_acceleration: braking_force / mass_kg,
726:                     lateral_acceleration,
727:                     traction_acceleration,
728:                     turn_radius,
729:                 },
730:                 time.delta_secs(),
731:             )
732:         } else {
733:             approach_velocity(
734:                 horizontal,
735:                 target,
736:                 drive_force / mass_kg * motor.air_control_force_scale,
737:                 time.delta_secs(),
738:             )
739:         };
740:         velocity.x = next.x;
741:         velocity.z = next.y;
742:     }
743: }
744: 
745: fn slide_drag_velocity(
746:     velocity: Vec2,
747:     motor: &crate::combat_config::CharacterMotorConfig,
748:     delta_seconds: f32,
749: ) -> Vec2 {
750:     approach_velocity(
751:         velocity,
752:         Vec2::ZERO,
753:         motor.gravity_metres_per_second_squared * motor.slide_drag_coefficient,
754:         delta_seconds,
755:     )
756: }
757: 
758: fn character_motor_force_limits(
759:     motor: &crate::combat_config::CharacterMotorConfig,
760:     mass_kg: f32,
761:     strength_scale: f32,
762: ) -> (f32, f32) {
763:     let traction_force =
764:         mass_kg.max(1.0) * motor.gravity_metres_per_second_squared * motor.traction_coefficient;
765:     (
766:         (motor.reference_ground_drive_force_newtons * strength_scale.max(0.0)).min(traction_force),
767:         (motor.reference_ground_braking_force_newtons * strength_scale.max(0.0))
768:             .min(traction_force),
769:     )
770: }
771: 
772: fn ordinary_jump_height(
773:     reference_height: f32,
774:     mass_kg: f32,
775:     leg_strength: f32,
776:     leg_agility: f32,
777:     motor: &crate::combat_config::CharacterMotorConfig,
778: ) -> f32 {
779:     let athleticism = ((leg_strength / motor.reference_leg_strength
780:         + leg_agility / motor.reference_leg_agility)

781:         * 0.5)
782:         .max(0.0);
783:     // Attribute 3 is the reference healthy adult. Attribute 4 produces about
784:     // a 0.39 m unburdened rise and attribute 5 about 0.49 m; burden reduces
785:     // takeoff energy per unit mass without changing Earth-normal gravity.
786:     let takeoff_velocity_scale = 0.58 + 0.42 * athleticism;
787:     let burden_scale = (REFERENCE_BURDEN_KG / mass_kg.max(1.0)).clamp(0.25, 1.25);
788:     reference_height * takeoff_velocity_scale * takeoff_velocity_scale * burden_scale
789: }
790: 
791: /// Converts the configured full-sprint arc into a speed-dependent ordinary
792: /// turn. Below the reference sprint, constant centripetal acceleration gives
793: /// `r = v^2 / a`, so running and jogging turn progressively more tightly while
794: /// retaining their speed. The small floor represents the space required to
795: /// redirect a standing body instead of collapsing toward a zero-radius pivot.
796: fn ordinary_turn_radius(speed: NonnegativeSpeed, reference_sprint_radius: f32) -> f32 {
797:     let speed_fraction = (speed.metres_per_second().max(0.0)
798:         / REFERENCE_SPRINT_SPEED_METRES_PER_SECOND.metres_per_second())
799:     .clamp(0.0, 1.0);
800:     (reference_sprint_radius * speed_fraction * speed_fraction)
801:         .max(MINIMUM_ORDINARY_TURN_RADIUS_METRES)
802: }
803: 
804: /// Smooth bounded response through the declarative Agility 1, 3, and 5 sprint
805: /// radii. In normalized attribute space `x = (agility - 3) / 2`, the unique
806: /// quadratic through the three anchors is `reference + linear*x + curve*x^2`.
807: /// Validation guarantees its derivative remains negative over `-1..=1`.
808: fn agility_sprint_turn_radius(
809:     leg_agility: f32,
810:     motor: &crate::combat_config::CharacterMotorConfig,
811: ) -> f32 {
812:     let x = (leg_agility.clamp(1.0, 5.0) - 3.0) * 0.5;
813:     let low = motor.agility_one_sprint_turn_radius_metres;
814:     let reference = motor.reference_sprint_turn_radius_metres;
815:     let high = motor.agility_five_sprint_turn_radius_metres;
816:     let linear = (high - low) * 0.5;
817:     let curve = (high + low) * 0.5 - reference;
818:     reference + linear * x + curve * x * x
819: }
820: 
821: fn cut_lateral_acceleration(
822:     current: Vec2,
823:     desired_direction: Vec2,
824:     sustained_acceleration: f32,
825:     traction_acceleration: f32,
826:     leg_agility: f32,
827: ) -> f32 {
828:     if current.length_squared() <= 1.0e-6 || desired_direction == Vec2::ZERO {
829:         return sustained_acceleration;
830:     }
831:     let cosine = current.normalize().dot(desired_direction).clamp(-1.0, 1.0);
832:     let lateral_demand = (1.0 - cosine * cosine).sqrt();
833:     // A hard plant can briefly approach the surface traction ceiling. Average
834:     // agility exploits part of that reserve; John (Agility 4) can use it all.
835:     let plant_skill = (leg_agility / 4.0).clamp(0.0, 1.0);
836:     sustained_acceleration.lerp(traction_acceleration, lateral_demand * plant_skill)
837: }
838: 
839: #[derive(Debug, Clone, Copy)]
840: struct GroundVelocityLimits {
841:     drive_acceleration: f32,
842:     braking_acceleration: f32,
843:     lateral_acceleration: f32,
844:     traction_acceleration: f32,
845:     turn_radius: f32,
846: }
847: 
848: fn approach_ground_velocity(
849:     current: Vec2,
850:     target: Vec2,
851:     limits: GroundVelocityLimits,
852:     delta_seconds: f32,
853: ) -> Vec2 {
854:     let GroundVelocityLimits {
855:         drive_acceleration,
856:         braking_acceleration,
857:         lateral_acceleration,
858:         traction_acceleration,
859:         turn_radius,
860:     } = limits;
861:     if current == target || delta_seconds <= 0.0 {
862:         return current;
863:     }
864:     let current_speed = current.length();
865:     let target_speed = target.length();
866:     if target_speed <= 1.0e-6 {
867:         return approach_velocity(
868:             current,
869:             Vec2::ZERO,
870:             braking_acceleration.min(traction_acceleration),
871:             delta_seconds,
872:         );
873:     }
874:     if current_speed <= 1.0e-6 {
875:         return approach_velocity(
876:             Vec2::ZERO,
877:             target,
878:             drive_acceleration.min(traction_acceleration),
879:             delta_seconds,
880:         );
881:     }
882: 
883:     let current_direction = current / current_speed;
884:     let target_direction = target / target_speed;
885:     let cosine = current_direction.dot(target_direction).clamp(-1.0, 1.0);
886:     // An exact reversal has no physically meaningful turn side. Brake to zero
887:     // before accelerating backward instead of choosing an arbitrary U-turn.
888:     if cosine < -0.999 {
889:         return approach_velocity(
890:             current,
891:             Vec2::ZERO,
892:             braking_acceleration.min(traction_acceleration),
893:             delta_seconds,
894:         );
895:     }
896: 
897:     let cross = current_direction.perp_dot(target_direction);
898:     let angle = cross.atan2(cosine);
899:     let radius_acceleration = current_speed * current_speed / turn_radius.max(0.01);
900:     let steering_acceleration = lateral_acceleration.max(radius_acceleration);
901:     let maximum_turn = steering_acceleration * delta_seconds / current_speed;
902:     let turn = angle.clamp(-maximum_turn, maximum_turn);
903:     let (sin, cos) = turn.sin_cos();
904:     let turned_direction = Vec2::new(
905:         current_direction.x * cos - current_direction.y * sin,
906:         current_direction.x * sin + current_direction.y * cos,
907:     );
908:     let speed_acceleration = if target_speed >= current_speed {
909:         drive_acceleration
910:     } else {

911:         braking_acceleration
912:     }
913:     .min(traction_acceleration)
914:     .max(0.0);
915:     let next_speed = current_speed
916:         + (target_speed - current_speed).clamp(
917:             -speed_acceleration * delta_seconds,
918:             speed_acceleration * delta_seconds,
919:         );
920:     turned_direction * next_speed
921: }
922: 
923: fn approach_velocity(current: Vec2, target: Vec2, acceleration: f32, delta_seconds: f32) -> Vec2 {
924:     let maximum_delta = (acceleration.max(0.0) * delta_seconds.max(0.0)).max(0.0);
925:     current + (target - current).clamp_length_max(maximum_delta)
926: }
