1130:     fn integrated_right_angle_turn(speed: f32, agility: f32) -> (f32, f32, f32) {
1131:         let grounded = avian3d::character_controller::move_and_slide::MoveHitData {
1132:             entity: Entity::PLACEHOLDER,
1133:             distance: 0.0,
1134:             point1: Vec3::ZERO,
1135:             point2: Vec3::ZERO,
1136:             normal1: Vec3::Y,
1137:             normal2: Vec3::NEG_Y,
1138:             collision_distance: 0.0,
1139:         };
1140:         let defaults = crate::combat_config::TacticalCombatConfig::default();
1141:         let movement = crate::combat_config::TacticalMovementConfig {
1142:             speeds_metres_per_second: crate::combat_config::MovementSpeedsConfig {
1143:                 run: NonnegativeSpeed::from_metres_per_second(speed).unwrap(),
1144:                 ..defaults.movement.speeds_metres_per_second.clone()
1145:             },
1146:             ..defaults.movement.clone()
1147:         };
1148:         let config = crate::combat_config::TacticalCombatConfig {
1149:             movement,
1150:             ..defaults
1151:         };
1152:         let motor = &config.movement.motor;
1153:         let turn_radius = ordinary_turn_radius(
1154:             adventuresim_core::linear_speed::NonnegativeSpeed::from_metres_per_second(speed)
1155:                 .unwrap(),
1156:             agility_sprint_turn_radius(agility, motor),
1157:         );
1158:         let attributes = crate::player::TacticalAttributes(PlayerAttributeValues {
1159:             left_leg_agility: agility,
1160:             right_leg_agility: agility,
1161:             ..default()
1162:         });
1163:         let mut world = World::new();
1164:         let entity = world
1165:             .spawn((
1166:                 AccumulatedInput {
1167:                     // Identity controller orientation maps backward local input
1168:                     // to world +Z, ninety degrees left of the initial +X run.
1169:                     last_movement: Some(-Vec2::Y),
1170:                     ..default()

1171:                 },
1172:                 CharacterController::default(),
1173:                 CharacterControllerState {
1174:                     grounded: Some(grounded),
1175:                     ..default()
1176:                 },
1177:                 LinearVelocity(Vec3::X * speed),
1178:                 Mass(80.0),
1179:                 Transform::default(),
1180:                 crate::player::Limbs::default(),
1181:                 crate::player::Skills::default(),
1182:                 crate::player::Stats::default(),
1183:                 attributes,
1184:             ))
1185:             .id();
1186:         let delta_seconds = locomotion_sample_rate().interval().seconds();
1187:         world.insert_resource(config);
1188:         let mut fixed_time = Time::<Fixed>::from_hz(locomotion_sample_rate().hertz() as f64);
1189:         fixed_time.advance_by(std::time::Duration::from_secs_f32(delta_seconds));
1190:         world.insert_resource(fixed_time);
1191:         let mut schedule = Schedule::default();
1192:         schedule.add_systems(apply_character_motor);
1193: 
1194:         let centre = Vec2::Y * turn_radius;
1195:         let mut maximum_radius_error = 0.0_f32;
1196:         let mut minimum_speed = speed;
1197: 
1198:         for _ in 0..128 {
1199:             schedule.run(&mut world);
1200:             let velocity = world.get::<LinearVelocity>(entity).unwrap().0;
1201:             world.get_mut::<Transform>(entity).unwrap().translation += velocity * delta_seconds;
1202:             let position = world.get::<Transform>(entity).unwrap().translation.xz();
1203:             let horizontal_velocity = velocity.xz();
1204:             minimum_speed = minimum_speed.min(horizontal_velocity.length());
1205:             maximum_radius_error =
1206:                 maximum_radius_error.max(((position - centre).length() - turn_radius).abs());
1207:             if horizontal_velocity.normalize().dot(Vec2::Y) > 0.99999 {
1208:                 break;
1209:             }
1210:         }
1211: 
1212:         let position = world.get::<Transform>(entity).unwrap().translation.xz();
1213:         (
1214:             position.length() / std::f32::consts::SQRT_2,
1215:             minimum_speed,
1216:             maximum_radius_error,
1217:         )
1218:     }
