5: 
6: pub(super) fn apply_motor_config(
7:     controller: &mut CharacterController,
8:     motor: &CharacterMotorConfig,
9: ) {
10:     controller.acceleration_hz = 0.0;
11:     controller.air_acceleration_hz = 0.0;
12:     controller.water_acceleration_hz = 0.0;
13:     controller.friction_hz = 0.0;
14:     controller.stop_speed = 0.0;
15:     controller.gravity = motor.gravity_metres_per_second_squared;
16:     controller.step_size = motor.maximum_step_height_metres;
17:     controller.min_walk_cos = motor.maximum_walkable_slope_degrees.to_radians().cos();
18: }

1: //! Calibrated movement controls and their intentional exertion speeds.
2: 
3: use super::MovementPace;
4: use crate::animation::{BodyState, WeaponGuardState};
5: use crate::{combat_config::TacticalMovementConfig, player::TacticalPlayerView};
6: use adventuresim_core::linear_speed::{NonnegativeSpeed, SpeedResult};
7: use adventuresim_core::prelude::*;
8: use bevy::prelude::Vec2;
9: 
10: pub const TACTICAL_WALK_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(1.7);
11: pub const BREATH_PER_METRE_PER_SECOND: f32 = 0.0034;
12: pub const TACTICAL_BREATH_RESPONSE_SCALE: f32 = 5.0;
13: pub(super) const REFERENCE_LEG_STRENGTH: f32 = 3.0;
14: pub(super) const REFERENCE_BURDEN_KG: f32 = 70.0;
15: pub(super) const MINIMUM_JOG_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(1.8);
16: pub(super) const ELITE_MARATHON_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(5.83);
17: pub(super) const JOG_ENDURANCE_CURVE_EXPONENT: f32 = 1.873_873;
18: pub(super) const SPRINT_CURVE_BASE_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(1.4);
19: pub(super) const REFERENCE_SPRINT_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(8.0);
20: pub(super) const ELITE_SPRINT_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(12.4);
21: /// Authored ordinary-run reference and fallback for entities without attributes.
22: pub const TACTICAL_RUN_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(5.5);
23: /// Maximum ordinary controller speed while the weapon guard is raised.
24: pub const TACTICAL_GUARD_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(2.0);
25: /// Deliberate prone crawl used by the walking control mode.
26: pub const TACTICAL_PRONE_WALK_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(0.45);
27: /// Maximum urgent unencumbered crawl while sprint is held.
28: pub const TACTICAL_PRONE_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(2.0);
29: /// Body-local lateral crawl is slower than longitudinal travel.
30: pub const TACTICAL_PRONE_LATERAL_SPEED_SCALE: f32 = 0.375;
31: /// Crawling costs three times upright effort; neutral prone jogging divides by this factor.
32: pub(super) const TACTICAL_PRONE_EFFORT_SCALE: f32 = 3.0;
33: pub const TACTICAL_ROLL_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(1.3);
34: pub const TACTICAL_DIVE_HORIZONTAL_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(7.0);
35: pub const TACTICAL_QUICKSTEP_SPEED_METRES_PER_SECOND: NonnegativeSpeed = authored_speed(3.5);
36: 
37: /// Existing controller fallback when an entity has no character attributes.
38: pub(super) const UNATTRIBUTED_JOG_SPEED: NonnegativeSpeed = authored_speed(3.75);
39: 
40: pub fn tactical_jog_speed(endurance: f32) -> SpeedResult<NonnegativeSpeed> {
41:     let endurance = endurance.clamp(0.0, 5.0);
42:     if endurance <= 1.0 {
43:         let smooth_endurance = endurance * endurance * (3.0 - 2.0 * endurance);
44:         return TACTICAL_WALK_SPEED_METRES_PER_SECOND
45:             .checked_lerp(MINIMUM_JOG_SPEED_METRES_PER_SECOND, smooth_endurance);
46:     }
47:     let normalized = (endurance - 1.0) / 4.0;
48:     NonnegativeSpeed::from_metres_per_second(
49:         MINIMUM_JOG_SPEED_METRES_PER_SECOND.metres_per_second()
50:             + (ELITE_MARATHON_SPEED_METRES_PER_SECOND.metres_per_second()
51:                 - MINIMUM_JOG_SPEED_METRES_PER_SECOND.metres_per_second())
52:                 * normalized.powf(JOG_ENDURANCE_CURVE_EXPONENT),
53:     )
54: }
55: 
56: pub fn tactical_breath_recovery_per_second(endurance: f32) -> SpeedResult<f32> {
57:     Ok(tactical_jog_speed(endurance)?.metres_per_second() * BREATH_PER_METRE_PER_SECOND)
58: }
59: 
60: /// Intentional exertion, rather than externally imposed velocity, owns this rate.
61: pub fn tactical_exhaustion_change_per_second(
62:     effort_speed: NonnegativeSpeed,
63:     endurance: f32,
64: ) -> SpeedResult<f32> {
65:     Ok(
66:         (effort_speed.metres_per_second() * BREATH_PER_METRE_PER_SECOND
67:             - tactical_breath_recovery_per_second(endurance)?)
68:             * TACTICAL_BREATH_RESPONSE_SCALE,
69:     )
70: }
71: 
72: /// Movement's additive contribution to tactical exhaustion. A full jog is
73: /// explicitly capped at neutral, while partial jog input and walking recover
74: /// exhaustion and sprinting accumulates it. Other exhaustion sources can add
75: /// their own rates without being cleared by the selected movement pace.
76: pub fn tactical_movement_exhaustion_change_per_second(
77:     movement: Option<Vec2>,
78:     pace: MovementPace,
79:     weapon_guard: WeaponGuardState,
80:     body: crate::animation::BodyState,
81:     endurance: f32,
82:     sprint_speed: NonnegativeSpeed,
83: ) -> SpeedResult<f32> {
84:     let jog_speed = tactical_jog_speed(endurance)?;
85:     let effort_speed = if body == crate::animation::BodyState::Prone {
86:         tactical_prone_movement_speed_for_pace(movement, pace, jog_speed)?
87:             .checked_scale(TACTICAL_PRONE_EFFORT_SCALE)?
88:     } else {
89:         tactical_movement_speed_for_pace(movement, pace, weapon_guard, jog_speed, sprint_speed)?
90:     };
91:     let change = tactical_exhaustion_change_per_second(effort_speed, endurance)?;
92:     if pace == MovementPace::Jog {
93:         Ok(change.min(0.0))
94:     } else {
95:         Ok(change)
96:     }
97: }
98: 
99: pub fn tactical_sprint_speed(
100:     left_leg_strength: f32,
101:     right_leg_strength: f32,
102:     left_leg_health: f32,
103:     right_leg_health: f32,
104:     burden_kg: f32,
105: ) -> SpeedResult<NonnegativeSpeed> {
106:     let effective_strength = ((left_leg_strength * left_leg_health.max(0.0)
107:         + right_leg_strength * right_leg_health.max(0.0))
108:         * 0.5)
109:         .max(0.0);
110:     let strength_ratio = effective_strength / REFERENCE_LEG_STRENGTH;
111:     let burden_ratio = REFERENCE_BURDEN_KG / burden_kg.max(1.0);
112:     let strength_speed = (REFERENCE_SPRINT_SPEED_METRES_PER_SECOND.metres_per_second()
113:         - SPRINT_CURVE_BASE_SPEED_METRES_PER_SECOND.metres_per_second())
114:         * strength_ratio;
115:     NonnegativeSpeed::from_metres_per_second(
116:         (SPRINT_CURVE_BASE_SPEED_METRES_PER_SECOND.metres_per_second()
117:             + strength_speed * burden_ratio.sqrt())
118:         .clamp(
119:             TACTICAL_WALK_SPEED_METRES_PER_SECOND.metres_per_second(),
120:             ELITE_SPRINT_SPEED_METRES_PER_SECOND.metres_per_second(),
121:         ),
122:     )
123: }
124: 
125: /// Preserves the analogue movement magnitude after Ahoy normalizes its wish
126: /// direction. Keyboard input has magnitude one; a half-deflected stick sets a
127: /// half-speed controller target.
128: pub fn tactical_movement_speed(movement: Option<Vec2>) -> SpeedResult<NonnegativeSpeed> {
129:     tactical_movement_speed_for_guard(movement, WeaponGuardState::Lowered)
130: }

131: 
132: /// Resolves the controller target speed at the server-side Ahoy seam. The
133: /// radial input magnitude is retained after Ahoy normalizes its wish direction.
134: pub fn tactical_movement_speed_for_guard(
135:     movement: Option<Vec2>,
136:     weapon_guard: WeaponGuardState,
137: ) -> SpeedResult<NonnegativeSpeed> {
138:     let cap = match weapon_guard {
139:         WeaponGuardState::Lowered => TACTICAL_RUN_SPEED_METRES_PER_SECOND,
140:         WeaponGuardState::Raised => TACTICAL_GUARD_SPEED_METRES_PER_SECOND,
141:     };
142:     cap.checked_scale(movement.map_or(0.0, |movement| movement.length().clamp(0.0, 1.0)))
143: }
144: 
145: pub fn tactical_movement_speed_for_pace(
146:     movement: Option<Vec2>,
147:     pace: MovementPace,
148:     weapon_guard: WeaponGuardState,
149:     jog_speed: NonnegativeSpeed,
150:     sprint_speed: NonnegativeSpeed,
151: ) -> SpeedResult<NonnegativeSpeed> {
152:     let requested = match pace {
153:         MovementPace::Walk => TACTICAL_WALK_SPEED_METRES_PER_SECOND,
154:         MovementPace::Jog => jog_speed,
155:         MovementPace::Sprint => sprint_speed,
156:     };
157:     let cap = if weapon_guard == WeaponGuardState::Raised {
158:         match pace {
159:             MovementPace::Sprint => jog_speed,
160:             _ => requested.min(TACTICAL_GUARD_SPEED_METRES_PER_SECOND),
161:         }
162:     } else {
163:         requested
164:     };
165:     cap.checked_scale(movement.map_or(0.0, |movement| movement.length().clamp(0.0, 1.0)))
166: }
167: 
168: /// Resolve configured ordinary pace, guard cap and prone effort before the native controller assignment.
169: pub(super) fn ordinary_controller_speed(
170:     movement: Option<Vec2>,
171:     pace: Option<MovementPace>,
172:     guard: WeaponGuardState,
173:     body: Option<BodyState>,
174:     player: Option<TacticalPlayerView<'_, '_, '_>>,
175:     config: &TacticalMovementConfig,
176: ) -> SpeedResult<NonnegativeSpeed> {
177:     let speeds = &config.speeds_metres_per_second;
178:     let input_magnitude = movement.map_or(0.0, |movement| movement.length().clamp(0.0, 1.0));
179:     let (jog, sprint) = match player {
180:         Some(player) => {
181:             let burden = player.body_weight() + player.inventory_weight();
182:             let jog =
183:                 tactical_jog_speed(player.raw_single_body_part_attr(SimpleAttribute::Endurance))?;
184:             let sprint = tactical_sprint_speed(
185:                 player.raw_limb_attr(LimbAttribute::Strength, BodyPart::LeftLeg),
186:                 player.raw_limb_attr(LimbAttribute::Strength, BodyPart::RightLeg),
187:                 player.body_part_health(BodyPart::LeftLeg),
188:                 player.body_part_health(BodyPart::RightLeg),
189:                 burden,
190:             )?;
191:             (jog, sprint)
192:         }
193:         None => (UNATTRIBUTED_JOG_SPEED, speeds.run),
194:     };
195:     let requested = pace.map_or(speeds.run, |pace| match pace {
196:         MovementPace::Walk => speeds.walk,
197:         MovementPace::Jog => jog,
198:         MovementPace::Sprint => sprint,
199:     });
200:     let cap = if guard == WeaponGuardState::Raised {
201:         match pace {
202:             Some(MovementPace::Sprint) => jog,
203:             _ => requested.min(speeds.raised_guard),
204:         }
205:     } else {
206:         requested
207:     };
208:     // Keep the ordinary assignment's admission before the existing prone override.
209:     let ordinary = cap.checked_scale(input_magnitude)?;
210:     if matches!(body, Some(BodyState::Prone | BodyState::Supine)) {
211:         let source = match pace {
212:             None | Some(MovementPace::Walk) => speeds.prone_walk.metres_per_second(),
213:             Some(MovementPace::Jog) => jog.metres_per_second() / config.prone_effort_scale,
214:             Some(MovementPace::Sprint) => speeds.prone.metres_per_second(),
215:         };
216:         NonnegativeSpeed::from_metres_per_second(source * input_magnitude)
217:     } else {
218:         Ok(ordinary)
219:     }
220: }
221: 
222: pub(super) fn tactical_prone_movement_speed_for_pace(
223:     movement: Option<Vec2>,
224:     pace: MovementPace,
225:     upright_jog_speed: NonnegativeSpeed,
226: ) -> SpeedResult<NonnegativeSpeed> {
227:     let speed = tactical_prone_speed_for_pace(pace, upright_jog_speed)?;
228:     let movement = movement.unwrap_or_default();
229:     speed.checked_scale(
230:         Vec2::new(movement.x * TACTICAL_PRONE_LATERAL_SPEED_SCALE, movement.y)
231:             .length()
232:             .clamp(0.0, 1.0),
233:     )
234: }
235: 
236: pub(super) fn tactical_prone_speed_for_pace(
237:     pace: MovementPace,
238:     upright_jog_speed: NonnegativeSpeed,
239: ) -> SpeedResult<NonnegativeSpeed> {
240:     match pace {
241:         MovementPace::Walk => Ok(TACTICAL_PRONE_WALK_SPEED_METRES_PER_SECOND),
242:         MovementPace::Jog => NonnegativeSpeed::from_metres_per_second(
243:             upright_jog_speed.metres_per_second() / TACTICAL_PRONE_EFFORT_SCALE,
244:         ),
245:         MovementPace::Sprint => Ok(TACTICAL_PRONE_SPEED_METRES_PER_SECOND),
246:     }
247: }
248: 
249: const fn authored_speed(value: f32) -> NonnegativeSpeed {
250:     match NonnegativeSpeed::from_metres_per_second(value) {
251:         Ok(speed) => speed,
252:         Err(_) => panic!("invalid built-in movement speed"),
253:     }
254: }
