1: //! Quickstep actuator lifecycle and authoritative sample-clock alignment.
2: 
3: use super::*;
4: use crate::animation::AnimationSampleSpan;
5: 
6: pub(super) struct QuickstepSampleClock {
7:     pub(super) elapsed: AnimationSampleSpan,
8:     action: AnimationSampleSpan,
9: }
10: 
11: impl QuickstepSampleClock {
12:     pub(super) fn bounded_recovery(&self, quickstep_action: bool, forward_velocity: f32) -> bool {
13:         !quickstep_action
14:             && self.elapsed <= self.action.saturating_add(AnimationSampleSpan::from(2u64))
15:             && forward_velocity.abs() > 0.02
16:     }
17: 
18:     pub(super) fn target_phase(&self) -> f32 {
19:         self.elapsed
20:             .saturating_add(AnimationSampleSpan::ONE)
21:             .samples() as f32
22:             / self.action.samples() as f32
23:     }
24: }
25: 
26: impl QuickstepPush {
27:     pub fn begin(
28:         &mut self,
29:         start_tick: crate::animation::AnimationSampleTick,
30:         direction: Vec2,
31:         orientation: Quat,
32:         origin: Vec3,
33:     ) {
34:         self.start_tick = start_tick;
35:         self.direction = direction.normalize_or_zero();
36:         self.orientation = orientation;
37:         self.origin = origin;
38:         self.active = self.direction != Vec2::ZERO;
39:     }
40: 
41:     pub fn cancel(&mut self) {
42:         self.active = false;
43:     }
44:     pub(super) fn sample_clock(
45:         &self,
46:         skeleton: Option<&SkeletonState>,
47:         duration: PositiveAnimationDuration,
48:     ) -> QuickstepSampleClock {
49:         QuickstepSampleClock {
50:             elapsed: self.elapsed_sample_ticks(skeleton),
51:             action: AnimationSampleSpan::from(
52:                 (duration.seconds() * locomotion_sample_rate().hertz())
53:                     .round()
54:                     .max(1.0) as u64,
55:             ),
56:         }
57:     }
58: 
59:     /// Retain the elapsed authoritative sample span for this actuator.
60:     pub(super) fn elapsed_sample_ticks(
61:         &self,
62:         skeleton: Option<&SkeletonState>,
63:     ) -> AnimationSampleSpan {
64:         skeleton
65:             .map_or(self.start_tick, |skeleton| skeleton.locomotion_sample_tick)
66:             .saturating_sub(self.start_tick)
67:     }
68: }
69: 
70: /// Converts the configured complete quickstep duration into the midpoint tick
71: /// expected by the shared symmetric dodge timeline. Keeping this conversion
72: /// in one place prevents a contact duration from accidentally being doubled.
73: pub fn quickstep_action_contact_ticks(duration: PositiveAnimationDuration) -> AnimationSampleSpan {
74:     let total_ticks = (duration
75:         .seconds()
76:         .max(2.0 / locomotion_sample_rate().hertz())
77:         * locomotion_sample_rate().hertz())
78:     .round()
79:     .max(2.0) as u64;
80:     AnimationSampleSpan::from((total_ticks / 2).max(1))
81: }

