241:     /// Applies up to `damage` (0-1 scale) to `part`'s health, clamped to what
242:     /// remains, and returns how much was actually applied. Mirrors
243:     /// `CombatBody::apply_damage` in `adventuresim_core::autoresolve`.
244:     pub fn apply_damage(&mut self, part: BodyPart, damage: f32) -> f32 {
245:         let health = match part {
246:             BodyPart::LeftArm => &mut self.left_arm,
247:             BodyPart::RightArm => &mut self.right_arm,
248:             BodyPart::LeftLeg => &mut self.left_leg,
249:             BodyPart::RightLeg => &mut self.right_leg,
250:             BodyPart::Chest => &mut self.chest,
251:             BodyPart::Stomach => &mut self.stomach,
252:             BodyPart::Head => &mut self.head,
253:         };
254:         let applied = damage.max(0.0).min(health.max(0.0));
255:         *health = (*health - applied).max(0.0);
256:         applied
257:     }
