3: use super::*;
4: use adventuresim_core::elapsed::{AnimationElapsed, ElapsedResult};
5: 
6: /// Contact timing combines authored rotational inertia with the attacker's arm
7: /// strength. The correction is deliberately bounded: strength helps control a
8: /// difficult weapon but does not erase the physical distinction between it
9: /// and a knife.
10: pub fn attack_preparation_secs(
11:     view: &TacticalPlayerView<'_, '_, '_>,
12:     style: MeleeAttackStyle,
13: ) -> ElapsedResult<AnimationElapsed> {
14:     let inertia = view.weapon_moment_of_inertia().max(0.0);
15:     let inertia_difficulty = if view.weapon_is_unarmed() {
16:         0.35
17:     } else {
18:         (inertia / (inertia + 0.45)).sqrt()
19:     };
20:     let strength = view.limb_attr_by_weight(LimbAttribute::Strength, LimbWeights::both_arms());
21:     let strength_scale = (1.0 + (3.0 - strength) * 0.08 * inertia_difficulty).clamp(0.85, 1.20);
22:     AnimationElapsed::from_seconds(
23:         (view.weapon_windup_secs_for(style)?.seconds() * strength_scale).clamp(0.08, 0.75),
24:     )
25: }
26: 
27: /// Skill mostly improves braking and redirection rather than raw peak weapon
28: /// speed. Continuations save additional recovery but remain bounded.
29: pub fn attack_recovery_secs(
30:     view: &TacticalPlayerView<'_, '_, '_>,
31:     style: MeleeAttackStyle,
32:     continuation: bool,
33: ) -> ElapsedResult<AnimationElapsed> {
34:     let control = (effective_weapon_handling_skill(view) / 5.0).clamp(0.0, 1.0);
35:     let skill_scale = 1.12 - 0.28 * control;
36:     let continuation_scale = if continuation { 0.78 } else { 1.0 };
37:     AnimationElapsed::from_seconds(
38:         (view.weapon_recovery_secs_for(style)?.seconds() * skill_scale * continuation_scale)
39:             .clamp(0.08, 0.55),
40:     )
41: }

