1: //! Client input coordinates, distinct from the animation sample clock.
2: 
3: use bevy::prelude::Reflect;
4: use derive_more::{Display, From};
5: use serde::{Deserialize, Serialize};
6: 
7: /// A complete client input sample on the wrapping 32-bit transport clock.
8: /// Every integer is valid, including the first observed zero.
9: #[derive(
10:     Clone, Copy, Debug, Default, PartialEq, Eq, Reflect, Serialize, Deserialize, From, Display,
11: )]
12: #[serde(transparent)]
13: pub struct PlayerInputTick(u32);
14: 
15: impl PlayerInputTick {
16:     pub const ZERO: Self = Self(0);
17:     pub const MAX: Self = Self(u32::MAX);
18: 
19:     pub fn wrapping_next(self) -> Self {
20:         Self(self.0.wrapping_add(1))
21:     }
22: 
23:     /// Unreliable-channel ordering within the existing half-range window.
24:     pub fn is_newer_than(self, previous: Self) -> bool {
25:         let distance = self.0.wrapping_sub(previous.0);
26:         distance != 0 && distance <= u32::MAX / 2
27:     }
28: 
29:     /// Original scalar at a transport, diagnostic or native sequence boundary.
30:     pub fn encoded(self) -> u32 {
31:         self.0
32:     }
33: }

