56: impl TerrainGenerator {
57:     pub fn new(seed: fabelgeist_determinism::Seed) -> Self {
58:         Self {
59:             seed,
60:             period: 30.0,
61:             grid_scale: 1.0,
62:         }
63:     }
64: 
65:     pub fn generate(
66:         self,
67:         width: usize,
68:         height: usize,
69:         depth: usize,
70:     ) -> Result<SceneTerrain, TerrainAdmissionError> {
71:         let mut noise = Noise::from(LayeredNoise::new(
72:             Normed::<f32>::default(),
73:             Persistence(0.5),
74:             FractalLayers {
75:                 layer: Octave::<MixCellGradients<OrthoGrid, Smoothstep, QuickGradients>>::default(),
76:                 lacunarity: 2.0,
77:                 amount: 8,
78:             },
79:         ));
80:         // Noiz owns a 32-bit native seed port; preserve the original low word.
81:         noise.set_seed(self.seed.to_u64() as u32);
82:         noise.set_period(self.period);
83: 
84:         SceneTerrain::new(width, depth, self.grid_scale, move |location| {
85:             let normal: f32 = noise.sample(location);
86:             normal * height as f32
87:         })
