95:     /// cells. This constructor is the scene-input boundary used by both the
96:     /// server collider and the client's replicated playable mesh.
97:     pub fn from_heightmap(
98:         grid_width: usize,
99:         grid_depth: usize,
100:         scale: f32,
101:         heightmap: Vec<f32>,
102:     ) -> Option<Self> {
103:         let terrain = Self {
104:             heightmap,
105:             width: grid_width,
106:             scale,
107:             coarse_stride: 1,
108:             geometry: TerrainGeometry::Sampled,
109:         };
110:         if terrain.grid_depth_checked()? != grid_depth {
111:             return None;
112:         }
113:         terrain.validate().ok()?;
114:         Some(terrain)
115:     }
