199:     pub fn grid_width(&self) -> usize {
200:         self.width
201:     }
202: 
203:     pub fn grid_depth(&self) -> usize {
204:         self.heightmap.len() / self.width
205:     }
206: 
207:     pub fn width(&self) -> f32 {
208:         self.grid_width().saturating_sub(1) as f32 * self.scale
209:     }
210: 
211:     pub fn depth(&self) -> f32 {
212:         self.grid_depth().saturating_sub(1) as f32 * self.scale
213:     }
214: 
215:     pub fn grid_scale(&self) -> f32 {
216:         self.scale
217:     }
218: 
219:     pub fn coarse_grid_scale(&self) -> f32 {
220:         self.scale * self.coarse_stride.max(1) as f32
221:     }
222: 
223:     /// Constrain the actual rendered/collision triangle gradients. Already valid
224:     /// relief retains its bits; owned support is never rewritten by this repair.
225:     pub fn constrain_max_grade(
226:         &mut self,
227:         maximum_grade: grade::TerrainGradeLimit,
228:     ) -> Result<(), TerrainGradeError> {
229:         if !matches!(self.geometry, TerrainGeometry::Sampled) {
230:             return Err(TerrainGradeError::OwnedSurface);
231:         }
232:         let depth = self.grid_depth();
233:         grade::constrain(
234:             &mut self.heightmap,
235:             self.width,
236:             depth,
237:             self.scale,
238:             maximum_grade.ratio(),
239:         )
240:     }
241: 
242:     /// Rewrites authoritative samples in centered world coordinates while
243:     /// preserving the terrain dimensions and render/collider correspondence.
244:     /// Publish the replacement only after every sample is admitted.
245:     pub fn rewrite_heights(
246:         &mut self,
247:         mut rewrite: impl FnMut(ScenePlanPoint, SupportElevation) -> Option<SupportElevation>,
248:     ) -> bool {
249:         if !matches!(self.geometry, TerrainGeometry::Sampled) {
250:             return false;
251:         }
252:         let half_extent = Vec2::new(self.width(), self.depth()) * 0.5;
253:         let mut replacement = Vec::with_capacity(self.heightmap.len());
254:         for z in 0..self.grid_depth() {
255:             for x in 0..self.grid_width() {
256:                 let index = z * self.grid_width() + x;
257:                 let Some(point) = ScenePlanPoint::from_metres(
258:                     Vec2::new(x as f32, z as f32) * self.scale - half_extent,
259:                 ) else {
260:                     return false;
261:                 };
262:                 let Some(height) = SupportElevation::from_metres(self.heightmap[index])
263:                     .and_then(|height| rewrite(point, height))
264:                 else {
265:                     return false;
266:                 };
267:                 replacement.push(height.metres());
268:             }
269:         }
270:         self.heightmap = replacement;
271:         true
272:     }
273: 
274:     /// Install each shape on its own static body. Owned foundation compounds
275:     /// and the natural trimesh cannot be nested in one composite collider.
276:     pub fn colliders(
277:         &self,
278:     ) -> Result<Vec<Collider>, crate::city_layout::grounding::SupportColliderError> {
279:         match &self.geometry {
280:             TerrainGeometry::Sampled => Ok(vec![Collider::heightfield(

281:                 self.collider_height_matrix(),
282:                 Vec3::new(self.width(), 1.0, self.depth()),
283:             )]),
284:             TerrainGeometry::Owned(surface) => surface.colliders(),
285:         }
286:     }
287: 
288:     fn collider_height_matrix(&self) -> Vec<Vec<f32>> {
289:         // Avian flattens this nested Vec directly into Parry's column-major
290:         // Array2. Supply X-major values while retaining Z rows and X columns
291:         // as the matrix dimensions expected by Parry's heightfield.
292:         let column_major = (0..self.grid_width())
293:             .flat_map(|x| {
294:                 (0..self.grid_depth()).map(move |z| self.heightmap[x + z * self.grid_width()])
295:             })
296:             .collect::<Vec<_>>();
297:         column_major
298:             .chunks_exact(self.grid_width())
299:             .map(|row| row.to_vec())
300:             .collect()
301:     }
