320:     #[cfg(test)]
321:     fn mesh_components(&self) -> (Vec<[f32; 3]>, Vec<u32>, Vec<[f32; 2]>) {
322:         self.mesh_components_with_stride(1)
323:     }
324: 
325:     #[cfg(any(feature = "meshgen", test))]
326:     fn mesh_components_with_stride(
327:         &self,
328:         stride: usize,
329:     ) -> (Vec<[f32; 3]>, Vec<u32>, Vec<[f32; 2]>) {
330:         self.mesh_components_with_stride_filtered(stride, |_| true)
331:     }
332: 
333:     pub(crate) fn mesh_components_with_stride_filtered(
334:         &self,
335:         stride: usize,
336:         keep_cell: impl Fn(Vec2) -> bool,
337:     ) -> (Vec<[f32; 3]>, Vec<u32>, Vec<[f32; 2]>) {
338:         if let TerrainGeometry::Owned(surface) = &self.geometry {
339:             return self.owned_mesh_components(surface, keep_cell);
340:         }
341:         let stride = stride.max(1);
342:         let xs = (0..self.grid_width()).step_by(stride).collect::<Vec<_>>();
343:         let zs = (0..self.grid_depth()).step_by(stride).collect::<Vec<_>>();
344:         debug_assert_eq!(xs.last().copied(), Some(self.grid_width() - 1));
345:         debug_assert_eq!(zs.last().copied(), Some(self.grid_depth() - 1));
346:         let mesh_offset = Vec2::new(
347:             self.grid_width().saturating_sub(1) as f32,
348:             self.grid_depth().saturating_sub(1) as f32,
349:         ) * -0.5;
350: 
351:         let mut positions = Vec::with_capacity(xs.len() * zs.len());
352:         let mut uvs = Vec::with_capacity(xs.len() * zs.len());
353:         // Keep vertices in the same row-major (z * width + x) order used by
354:         // height sampling and the triangle indices below. Iterating x first
355:         // transposed the storage without transposing the indices, which made
356:         // otherwise smooth terrain render as long shredded triangles.
357:         for &z in &zs {
358:             for &x in &xs {
359:                 let i = z * self.grid_width() + x;
360:                 let y = self.heightmap[i];
361: 
362:                 uvs.push([
363:                     x as f32 / (self.grid_width() - 1) as f32,
364:                     z as f32 / (self.grid_depth() - 1) as f32,
365:                 ]);
366: 
367:                 let x = (x as f32 + mesh_offset.x) * self.scale;
368:                 let z = (z as f32 + mesh_offset.y) * self.scale;
369:                 positions.push([x, y, z]);
370:             }
371:         }
372: 
373:         let mut indices = Vec::with_capacity((xs.len() - 1) * (zs.len() - 1) * 6);
374:         for x in 0..xs.len() - 1 {
375:             for z in 0..zs.len() - 1 {
376:                 let i = (z * xs.len() + x) as u32;
377:                 let cell_triangles = [
378:                     [i, i + xs.len() as u32, i + 1],
379:                     [i + 1, i + xs.len() as u32, i + xs.len() as u32 + 1],
380:                 ];
381:                 for triangle in cell_triangles {
382:                     let centre = triangle
383:                         .iter()
384:                         .map(|&index| {
385:                             let position = positions[index as usize];
386:                             Vec2::new(position[0], position[2])
387:                         })
388:                         .sum::<Vec2>()
389:                         / 3.0;
390:                     if keep_cell(centre) {
391:                         indices.extend_from_slice(&triangle);
392:                     }
393:                 }
394:             }
395:         }
396: 
397:         (positions, indices, uvs)
398:     }
399: }
