1: //! Decode and native-grid admission precede terrain queries and framework use.
2: use super::*;
3: 
4: #[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
5: pub enum TerrainAdmissionError {
6:     #[error(
7:         "terrain needs at least two finite grid vertices on each axis within u32 mesh capacity"
8:     )]
9:     Dimensions,
10:     #[error("terrain grid scale and represented extents must be finite and positive")]
11:     Scale,
12:     #[error("terrain coarse stride must divide both cell dimensions")]
13:     Stride,
14:     #[error("terrain height samples must be finite")]
15:     Heights,
16: }
17: 
18: #[derive(Deserialize)]
19: pub(super) struct TerrainWire {
20:     heightmap: Vec<f32>,
21:     width: usize,
22:     scale: f32,
23:     coarse_stride: usize,
24:     geometry: TerrainGeometry,
25: }
26: impl TryFrom<TerrainWire> for SceneTerrain {
27:     type Error = TerrainAdmissionError;
28:     fn try_from(wire: TerrainWire) -> Result<Self, Self::Error> {
29:         let terrain = Self {
30:             heightmap: wire.heightmap,
31:             width: wire.width,
32:             scale: wire.scale,
33:             coarse_stride: wire.coarse_stride,
34:             geometry: wire.geometry,
35:         };
36:         terrain.validate()?;
37:         Ok(terrain)
38:     }
39: }
40: 
41: pub(super) fn validate_dimensions(
42:     width: usize,
43:     depth: usize,
44:     scale: f32,
45:     stride: usize,
46: ) -> Result<(), TerrainAdmissionError> {
47:     if width < 2
48:         || depth < 2
49:         || width
50:             .checked_mul(depth)
51:             .is_none_or(|n| n > u32::MAX as usize)
52:         || (width - 1)
53:             .checked_mul(depth - 1)
54:             .and_then(|n| n.checked_mul(6))
55:             .is_none_or(|n| n > u32::MAX as usize)
56:     {
57:         return Err(TerrainAdmissionError::Dimensions);
58:     }
59:     if !scale.is_finite()
60:         || scale <= 0.0
61:         || !((width - 1) as f32 * scale).is_finite()
62:         || !((depth - 1) as f32 * scale).is_finite()
63:     {
64:         return Err(TerrainAdmissionError::Scale);
65:     }
66:     if stride == 0 || !(width - 1).is_multiple_of(stride) || !(depth - 1).is_multiple_of(stride) {
67:         return Err(TerrainAdmissionError::Stride);
68:     }
69:     Ok(())
70: }
71: impl SceneTerrain {
72:     pub(super) fn grid_depth_checked(&self) -> Option<usize> {
73:         (self.width != 0 && self.heightmap.len().is_multiple_of(self.width))
74:             .then(|| self.heightmap.len() / self.width)
75:     }
76:     pub(super) fn validate(&self) -> Result<(), TerrainAdmissionError> {
77:         let depth = self
78:             .grid_depth_checked()
79:             .ok_or(TerrainAdmissionError::Dimensions)?;
80:         validate_dimensions(self.width, depth, self.scale, self.coarse_stride)?;
81:         if self.heightmap.iter().any(|h| !h.is_finite()) {
82:             return Err(TerrainAdmissionError::Heights);
83:         }
84:         Ok(())
85:     }
86: }
87: impl Default for SceneTerrain {
88:     /// A finite flat metre-square grid is the framework default.
89:     fn default() -> Self {
90:         Self {
91:             heightmap: vec![0.0; 4],
92:             width: 2,
93:             scale: 1.0,
94:             coarse_stride: 1,
95:             geometry: TerrainGeometry::Sampled,
96:         }
97:     }
98: }
