1: //! Bound the gradient of the triangles shared by rendering and collision.
2: use crate::city_layout::grounding::{DiagnosticCount, GeographicGrade};
3: use thiserror::Error;
4: /// Finite nonnegative maximum terrain rise/run; zero admits level terrain.
5: #[derive(Clone, Copy, Debug, PartialEq, serde::Serialize, bevy::reflect::Reflect)]
6: #[serde(transparent)]
7: #[reflect(opaque)]
8: pub struct TerrainGradeLimit(f32);
9: impl TerrainGradeLimit {
10:     /// Repair grade of procedural ground, distinct from actor movement limits.
11:     pub const PLAYABLE: Self = Self(0.65);
12:     pub const fn from_ratio(value: f32) -> Option<Self> {
13:         if value.is_finite() && value >= 0.0 {
14:             Some(Self(value))
15:         } else {
16:             None
17:         }
18:     }
19:     pub const fn ratio(self) -> f32 {
20:         self.0
21:     }
22: }
23: impl<'de> serde::Deserialize<'de> for TerrainGradeLimit {
24:     fn deserialize<D: serde::Deserializer<'de>>(decoder: D) -> Result<Self, D::Error> {
25:         Self::from_ratio(<f32 as serde::Deserialize>::deserialize(decoder)?).ok_or_else(|| {
26:             serde::de::Error::custom("terrain grade limit must be finite and nonnegative")
27:         })
28:     }
29: }
30: /// Column/row ordinals in the admitted row-major heightmap.
31: #[derive(Clone, Copy, Debug, PartialEq)]
32: pub struct HeightmapCell {
33:     pub column: usize,
34:     pub row: usize,
35: }
36: struct WorstCell {
37:     sample: Option<HeightmapCell>,
38:     rise_metres: f64,
39: }
40: 
41: /// A finite work bound; exhausting it rejects preparation rather than publishing
42: /// a surface whose advertised grade differs from its physical bearing faces.
43: const MAXIMUM_REPAIR_SWEEPS: usize = 1_024;
44: const CARDINAL_PRECONDITION_SWEEPS: usize = 4;
45: const HEIGHTMAP_ROUNDOFF_ULPS: f64 = 4.0;
46: 
47: #[derive(Debug, Error, Clone, PartialEq)]
48: pub enum TerrainGradeError {
49:     #[error("grade repair requires a finite sampled heightmap and nonnegative grade")]
50:     InvalidInput,
51:     #[error("selected owned support cannot be rewritten as a sampled heightmap")]
52:     OwnedSurface,
53:     #[error(
54:         "terrain triangle at sample {sample:?} has grade {measured}, above {permitted:?}, after {sweeps} repair sweeps"
55:     )]
56:     Convergence {
57:         sample: HeightmapCell,
58:         measured: GeographicGrade,
59:         permitted: TerrainGradeLimit,
60:         sweeps: DiagnosticCount,
61:     },
62: }
63: 
64: pub(crate) fn constrain(
65:     heights: &mut [f32],
66:     width: usize,
67:     depth: usize,
68:     spacing: f32,
69:     maximum_grade: f32,
70: ) -> Result<(), TerrainGradeError> {
71:     if width < 2
72:         || depth < 2
73:         || width.checked_mul(depth) != Some(heights.len())
74:         || !spacing.is_finite()
75:         || spacing <= 0.0
76:         || !maximum_grade.is_finite()
77:         || maximum_grade < 0.0
78:         || heights.iter().any(|h| !h.is_finite())
79:     {
80:         return Err(TerrainGradeError::InvalidInput);
81:     }
82:     let bound = f64::from(spacing) * f64::from(maximum_grade);
83:     let mut values: Vec<_> = heights.iter().map(|h| f64::from(*h)).collect();
84:     let magnitude = values
85:         .iter()
86:         .fold(f64::from(spacing), |m, h| m.max(h.abs()));
87:     let roundoff = magnitude * f64::from(f32::EPSILON) * HEIGHTMAP_ROUNDOFF_ULPS;
88:     let WorstCell {
89:         rise_metres: initial,
90:         ..
91:     } = worst(&values, width, depth, None);
92:     if initial <= bound + roundoff {
93:         // Geographic relief already satisfying the physical limit retains every
94:         // original bit, including axis-aligned slopes near the permitted bound.
95:         return Ok(());
96:     }
97: 
98:     precondition(&mut values, width, depth, bound);
99:     let target = (bound - roundoff).max(0.0);
100:     let mut dirty = vec![true; (width - 1) * (depth - 1)];
101:     for sweep in 0..MAXIMUM_REPAIR_SWEEPS {
102:         repair_sweep(
103:             &mut values,
104:             &mut dirty,
105:             [width, depth],
106:             target,
107:             SweepDirection::for_pass(sweep),
108:         );
109:         // Clean cells were proved valid at their last visit and have no
110:         // subsequently changed vertex. Only dirty cells can prevent convergence.
111:         let WorstCell {
112:             rise_metres: residual,
113:             ..
114:         } = worst(&values, width, depth, Some(&dirty));
115:         if residual <= target + roundoff * 0.5 {
116:             let replacement: Vec<_> = values.into_iter().map(|value| value as f32).collect();
117:             if replacement.iter().any(|height| !height.is_finite()) {
118:                 return Err(TerrainGradeError::InvalidInput);
119:             }
120:             heights.copy_from_slice(&replacement);
121:             return Ok(());
122:         }
123:     }
124:     let WorstCell {
125:         sample,
126:         rise_metres: measured,
127:     } = worst(&values, width, depth, None);
128:     Err(TerrainGradeError::Convergence {
129:         sample: sample.unwrap_or(HeightmapCell { column: 0, row: 0 }),
130:         measured: GeographicGrade::from_ratio(measured / f64::from(spacing))
131:             .ok_or(TerrainGradeError::InvalidInput)?,
132:         permitted: TerrainGradeLimit::from_ratio(maximum_grade)
133:             .ok_or(TerrainGradeError::InvalidInput)?,
134:         sweeps: DiagnosticCount::new(MAXIMUM_REPAIR_SWEEPS as u64),
135:     })
136: }
137: 
138: #[derive(Clone, Copy)]
139: enum SweepDirection {
140:     Forward,

141:     Reverse,
142: }
143: impl SweepDirection {
144:     fn for_pass(pass: usize) -> Self {
145:         if pass.is_multiple_of(2) {
146:             Self::Forward
147:         } else {
148:             Self::Reverse
149:         }
150:     }
151:     fn index(self, offset: usize, vertices: usize) -> usize {
152:         match self {
153:             Self::Forward => offset,
154:             Self::Reverse => vertices - 2 - offset,
155:         }
156:     }
157: }
158: 
159: // A triangle can change only when one of its shared vertices changes. Dirty
160: // cells retain the original raster order, including changes earlier in this
161: // same pass; skipping a clean cell therefore skips only a proven no-op.
162: fn repair_sweep(
163:     values: &mut [f64],
164:     dirty: &mut [bool],
165:     [width, depth]: [usize; 2],
166:     target: f64,
167:     direction: SweepDirection,
168: ) {
169:     for row in 0..depth - 1 {
170:         let z = direction.index(row, depth);
171:         for column in 0..width - 1 {
172:             let x = direction.index(column, width);
173:             let cell = z * (width - 1) + x;
174:             if !dirty[cell] {
175:                 continue;
176:             }
177:             dirty[cell] = false;
178:             let i = z * width + x;
179:             let first = project(values, [i, i + 1, i + width], target);
180:             let second = project(values, [i + width + 1, i + width, i + 1], target);
181:             if first || second {
182:                 for adjacent_z in z.saturating_sub(1)..=(z + 1).min(depth - 2) {
183:                     for adjacent_x in x.saturating_sub(1)..=(x + 1).min(width - 2) {
184:                         dirty[adjacent_z * (width - 1) + adjacent_x] = true;
185:                     }
186:                 }
187:             }
188:         }
189:     }
190: }
191: 
192: /// Retain the established cardinal repair as a deterministic preconditioner.
193: /// It bounds isolated source-cell jumps before the physical face projection;
194: /// it is insufficient by itself because two permitted axes can form a steep face.
195: fn precondition(values: &mut [f64], width: usize, depth: usize, bound: f64) {
196:     let clamp = |values: &mut [f64], source: usize, target: usize| {
197:         values[target] = values[target].clamp(values[source] - bound, values[source] + bound);
198:     };
199:     for _ in 0..CARDINAL_PRECONDITION_SWEEPS {
200:         for z in 0..depth {
201:             for x in 1..width {
202:                 clamp(values, z * width + x - 1, z * width + x);
203:             }
204:             for x in (0..width - 1).rev() {
205:                 clamp(values, z * width + x + 1, z * width + x);
206:             }
207:         }
208:         for x in 0..width {
209:             for z in 1..depth {
210:                 clamp(values, (z - 1) * width + x, z * width + x);
211:             }
212:             for z in (0..depth - 1).rev() {
213:                 clamp(values, (z + 1) * width + x, z * width + x);
214:             }
215:         }
216:     }
217: }
218: 
219: fn worst(values: &[f64], width: usize, depth: usize, dirty: Option<&[bool]>) -> WorstCell {
220:     let mut sample = None;
221:     let mut maximum = 0.0_f64;
222:     for z in 0..depth - 1 {
223:         for x in 0..width - 1 {
224:             if dirty.is_some_and(|cells| !cells[z * (width - 1) + x]) {
225:                 continue;
226:             }
227:             let i = z * width + x;
228:             let [a, b, c, d] = [
229:                 values[i],
230:                 values[i + 1],
231:                 values[i + width],
232:                 values[i + width + 1],
233:             ];
234:             let first = (b - a) * (b - a) + (c - a) * (c - a);
235:             let second = (b - d) * (b - d) + (c - d) * (c - d);
236:             let magnitude_squared = first.max(second);
237:             if magnitude_squared > maximum {
238:                 maximum = magnitude_squared;
239:                 sample = Some(HeightmapCell { column: x, row: z });
240:             }
241:         }
242:     }
243:     WorstCell {
244:         sample,
245:         rise_metres: libm::sqrt(maximum),
246:     }
247: }
