139:     /// use this to avoid extending blades across a leaf-litter boundary.
140:     pub fn cover_intersects_square(
141:         &self,
142:         centre: ScenePlanPoint,
143:         half_extent: f32,
144:         cover: GroundCover,
145:     ) -> bool {
146:         if !half_extent.is_finite() || half_extent < 0.0 {
147:             return false;
148:         }
149:         let centre = centre.metres();
150:         let half_size = Vec2::new(self.width(), self.depth()) * 0.5;
151:         let minimum = ((centre - Vec2::splat(half_extent) + half_size) / self.scale)
152:             .floor()
153:             .max(Vec2::ZERO);
154:         let maximum = ((centre + Vec2::splat(half_extent) + half_size) / self.scale)
155:             .ceil()
156:             .min(Vec2::new(
157:                 (self.grid_width() - 1) as f32,
158:                 (self.grid_depth() - 1) as f32,
159:             ));
160:         if minimum.x > maximum.x || minimum.y > maximum.y {
161:             return false;
162:         }
