12: #[derive(Default, Debug, Clone)]
13: struct SpatialBuckets(BTreeMap<(i32, i32), Vec<usize>>);
14: 
15: /// Exact urban-surface queries accelerated by a coarse spatial lookup.
16: #[derive(Default, Debug, Clone)]
17: pub struct UrbanGroundLookup {
18:     streets: Vec<CityStreetPatch>,
19:     yards: Vec<CityYardPatch>,
20:     buildings: Vec<CityPlotBounds>,
21:     street_buckets: SpatialBuckets,
22:     yard_buckets: SpatialBuckets,
23:     building_buckets: SpatialBuckets,
24: }
