26: #[derive(Default, Serialize, Deserialize, Debug, Reflect, Clone)]
27: pub struct UrbanGroundSurfaces {
28:     streets: Vec<CityStreetPatch>,
29:     yards: Vec<CityYardPatch>,
30:     buildings: Vec<CityPlotBounds>,
31:     #[serde(skip)]
32:     #[reflect(ignore)]
33:     lookup: OnceLock<UrbanGroundLookup>,
34: }
35: 
36: impl SpatialBuckets {
37:     fn new(bounds: impl IntoIterator<Item = (Vec2, Vec2)>) -> Self {
38:         let mut buckets = BTreeMap::<(i32, i32), Vec<usize>>::new();
39:         for (index, (minimum, maximum)) in bounds.into_iter().enumerate() {
40:             let minimum = (minimum / SPATIAL_BUCKET_METRES).floor().as_ivec2();
41:             let maximum = (maximum / SPATIAL_BUCKET_METRES).floor().as_ivec2();
42:             for x in minimum.x..=maximum.x {
43:                 for y in minimum.y..=maximum.y {
44:                     buckets.entry((x, y)).or_default().push(index);
45:                 }
46:             }
47:         }
48:         Self(buckets)
49:     }
50: 
51:     fn at(&self, point: Vec2) -> &[usize] {
52:         let cell = (point / SPATIAL_BUCKET_METRES).floor().as_ivec2();
53:         self.0.get(&(cell.x, cell.y)).map_or(&[], Vec::as_slice)
54:     }
55: 
56:     fn overlapping(&self, minimum: Vec2, maximum: Vec2) -> impl Iterator<Item = usize> + '_ {
57:         let minimum = (minimum / SPATIAL_BUCKET_METRES).floor().as_ivec2();
58:         let maximum = (maximum / SPATIAL_BUCKET_METRES).floor().as_ivec2();
59:         (minimum.x..=maximum.x)
60:             .flat_map(move |x| (minimum.y..=maximum.y).map(move |y| (x, y)))
61:             .filter_map(|cell| self.0.get(&cell))
62:             .flatten()
63:             .copied()
64:     }
65: }
66: 
67: impl UrbanGroundLookup {
68:     pub fn new(
69:         streets: &[CityStreetPatch],
70:         yards: &[CityYardPatch],
71:         buildings: &[CityPlotBounds],
72:     ) -> Self {
73:         Self {
74:             streets: streets.to_vec(),
75:             yards: yards.to_vec(),
76:             buildings: buildings.to_vec(),
77:             street_buckets: SpatialBuckets::new(streets.iter().map(street_bounds)),
78:             yard_buckets: SpatialBuckets::new(
79:                 yards.iter().map(|yard| corners_bounds(yard.corners_metres)),
80:             ),
81:             building_buckets: SpatialBuckets::new(
82:                 buildings
83:                     .iter()
84:                     .map(|building| corners_bounds(building.corners())),
85:             ),
86:         }
87:     }
88: 
89:     pub fn suppresses_grass(&self, point: ScenePlanPoint) -> bool {
90:         self.street_buckets
91:             .at(point.metres())
92:             .iter()
93:             .any(|&index| self.streets[index].contains(point.metres()))
94:             || self
95:                 .yard_buckets
96:                 .at(point.metres())
97:                 .iter()
98:                 .any(|&index| self.yards[index].contains(point.metres()))
99:     }
100: 
101:     fn surface_at(&self, position: ScenePlanPoint) -> Option<GroundSurface> {
102:         let substrate = if let Some(street) = self
103:             .street_buckets
104:             .at(position.metres())
105:             .iter()
106:             .map(|&index| self.streets[index])
107:             .filter(|street| street.contains(position.metres()))
108:             .max_by_key(|street| street.surface().priority())
109:         {
110:             match street.surface() {
111:                 CityStreetSurface::CompactedEarth => GroundSubstrate::Soil,
112:                 CityStreetSurface::Gravel => GroundSubstrate::Gravel,
113:                 CityStreetSurface::Fieldstone => GroundSubstrate::Road,
114:             }
115:         } else if self
116:             .building_buckets
117:             .at(position.metres())
118:             .iter()
119:             .any(|&index| self.buildings[index].contains(position.metres()))
120:         {
121:             GroundSubstrate::Stone
122:         } else if self
123:             .yard_buckets
124:             .at(position.metres())
125:             .iter()

126:             .any(|&index| self.yards[index].contains(position.metres()))
127:         {
128:             GroundSubstrate::Soil
129:         } else {
130:             return None;
131:         };
132:         Some(GroundSurface {
133:             substrate,
134:             cover: GroundCover::Bare,
135:             cover_density_bps: 0,
136:             cover_height_cm: 0,
137:         })
138:     }
139: 
140:     fn overlaps_disk(&self, centre: ScenePlanPoint, radius_metres: f32) -> bool {
141:         let centre = centre.metres();
142:         let minimum = centre - Vec2::splat(radius_metres);
143:         let maximum = centre + Vec2::splat(radius_metres);
144:         self.street_buckets
145:             .overlapping(minimum, maximum)
146:             .any(|index| match self.streets[index] {
147:                 CityStreetPatch::Corridor {
148:                     start_metres,
149:                     end_metres,
150:                     half_width_metres,
151:                     ..
152:                 } => {
153:                     segment_distance(centre, start_metres, end_metres)
154:                         <= radius_metres + half_width_metres
