159:                 }
160:             })
161:             || self
162:                 .yard_buckets
163:                 .overlapping(minimum, maximum)
164:                 .any(|index| {
165:                     let yard = self.yards[index];
166:                     yard.contains(centre)
167:                         || touches_edges(centre, radius_metres, yard.corners_metres)
168:                 })
169:             || self
170:                 .building_buckets
171:                 .overlapping(minimum, maximum)
172:                 .any(|index| {
173:                     let bounds = self.buildings[index];
174:                     bounds.contains(centre)
175:                         || touches_edges(centre, radius_metres, bounds.corners())
176:                 })
177:     }
