268: fn segment_distance(point: Vec2, start: Vec2, end: Vec2) -> f32 {
269:     let edge = end - start;
270:     let length_squared = edge.length_squared();
271:     let fraction = if length_squared > 0.0 {
272:         ((point - start).dot(edge) / length_squared).clamp(0.0, 1.0)
273:     } else {
274:         0.0
275:     };
276:     point.distance(start + edge * fraction)
277: }
278: fn touches_edges(centre: Vec2, radius: f32, corners: [Vec2; 4]) -> bool {
279:     (0..4).any(|side| segment_distance(centre, corners[side], corners[(side + 1) % 4]) <= radius)
