1: //! Scene support queries share the rendered and collided triangle surface.
2: use super::{SceneTerrain, TerrainGeometry};
3: use crate::{
4:     city_layout::grounding::{SupportElevation, SurfaceHit},
5:     scene_coordinates::ScenePlanPoint,
6: };
7: use bevy::math::{Dir3, Vec2, Vec3};
8: 
9: pub type TerrainSupportResult<T> = Result<T, TerrainSupportError>;
10: 
11: /// Nonempty ordered bounds in absolute scene elevation metres.
12: #[derive(Clone, Copy, Debug, PartialEq)]
13: pub struct SceneElevationRange {
14:     minimum: SupportElevation,
15:     maximum: SupportElevation,
16: }
17: 
18: #[derive(Clone, Copy, Debug, PartialEq, thiserror::Error)]
19: pub enum TerrainSupportError {
20:     #[error("terrain has no physical support at {point:?}")]
21:     MissingSupport { point: ScenePlanPoint },
22:     #[error("terrain has no finite nonempty elevation bounds")]
23:     MissingElevationRange,
24: }
25: 
26: impl SceneElevationRange {
27:     pub fn new(minimum: SupportElevation, maximum: SupportElevation) -> Option<Self> {
28:         (minimum.metres() <= maximum.metres()).then_some(Self { minimum, maximum })
29:     }
30: 
31:     pub fn minimum(self) -> SupportElevation {
32:         self.minimum
33:     }
34: 
35:     pub fn maximum(self) -> SupportElevation {
36:         self.maximum
37:     }
38: 
39:     /// Complete the reduction over native heightfield or compiled mesh samples.
40:     fn from_native_metres(mut heights: impl Iterator<Item = f32>) -> Option<Self> {
41:         let first = heights.next()?;
42:         if !first.is_finite() {
43:             return None;
44:         }
45:         let mut minimum = first;
46:         let mut maximum = first;
47:         for height in heights {
48:             if !height.is_finite() {
49:                 return None;
50:             }
51:             minimum = minimum.min(height);
52:             maximum = maximum.max(height);
53:         }
54:         Self::new(
55:             SupportElevation::from_metres(minimum)?,
56:             SupportElevation::from_metres(maximum)?,
57:         )
58:     }
59: }
60: 
61: impl SceneTerrain {
62:     pub fn required_height_at(
63:         &self,
64:         point: ScenePlanPoint,
65:     ) -> TerrainSupportResult<SupportElevation> {
66:         self.height_at(point)
67:             .ok_or(TerrainSupportError::MissingSupport { point })
68:     }
69: 
70:     pub fn required_elevation_range(&self) -> TerrainSupportResult<SceneElevationRange> {
71:         self.elevation_range()
72:             .ok_or(TerrainSupportError::MissingElevationRange)
73:     }
74: 
75:     pub fn elevation_range(&self) -> Option<SceneElevationRange> {
76:         match &self.geometry {
77:             TerrainGeometry::Sampled => {
78:                 SceneElevationRange::from_native_metres(self.heightmap.iter().copied())
79:             }
80:             TerrainGeometry::Owned(surface) => {
81:                 SceneElevationRange::from_native_metres(surface.support_heights())
82:             }
83:         }
84:     }
85: 
86:     pub fn height_at(&self, point: ScenePlanPoint) -> Option<SupportElevation> {
87:         self.surface_at_stride(point, 1)
88:             .map(|sample| sample.elevation)
89:     }
90: 
91:     /// Samples the triangle surface used by the coarse render LOD.
92:     pub fn coarse_height_at(&self, point: ScenePlanPoint) -> Option<SupportElevation> {
93:         self.surface_at_stride(point, self.coarse_stride.max(1))
94:             .map(|sample| sample.elevation)
95:     }
96: 
97:     /// Returns the finite, normalized normal of the rendered/collided triangle.
98:     pub fn normal_at(&self, point: ScenePlanPoint) -> Option<Dir3> {
99:         self.surface_at_stride(point, 1).map(|sample| sample.normal)
100:     }
101: 
102:     /// Samples the same triangle surface used by the rendered mesh and
103:     /// authoritative collider. Returning the triangle normal alongside the
104:     /// height keeps terrain IK from fitting a foot to a different, bilinear
105:     /// surface than the one visible beneath it.
106:     pub(super) fn surface_at_stride(
107:         &self,
108:         point: ScenePlanPoint,
109:         stride: usize,
110:     ) -> Option<SurfaceHit> {
111:         if let TerrainGeometry::Owned(surface) = &self.geometry {
112:             return surface.highest_surface_at(point);
113:         }
114:         if self.scale <= 0.0 || self.grid_width() < 2 || self.grid_depth() < 2 {
115:             return None;
116:         }
117:         // The sampled grid is centered in scene-local east/north metres.
118:         let pos = point.metres() + Vec2::new(self.width(), self.depth()) * 0.5;
119:         let grid = pos / self.scale;
120:         if grid.x < 0.0
121:             || grid.y < 0.0
122:             || grid.x > (self.grid_width() - 1) as f32
123:             || grid.y > (self.grid_depth() - 1) as f32
124:         {
125:             return None;

126:         }
127:         // The final vertex has no cell to its right/below. Sample its adjacent
128:         // cell with a coordinate of one so edges remain well-defined.
129:         let stride = stride.max(1);
130:         let last_cell_x = ((self.grid_width() - 2) / stride) * stride;
131:         let last_cell_y = ((self.grid_depth() - 2) / stride) * stride;
132:         let min_x = ((grid.x / stride as f32).floor() as usize * stride).min(last_cell_x);
133:         let min_y = ((grid.y / stride as f32).floor() as usize * stride).min(last_cell_y);
134:         let max_x = (min_x + stride).min(self.grid_width() - 1);
135:         let max_y = (min_y + stride).min(self.grid_depth() - 1);
136:         let cell_scale_x = (max_x - min_x) as f32 * self.scale;
137:         let cell_scale_z = (max_y - min_y) as f32 * self.scale;
138:         let fraction = Vec2::new(
139:             (grid.x - min_x as f32) / (max_x - min_x) as f32,
140:             (grid.y - min_y as f32) / (max_y - min_y) as f32,
141:         );
142: 
143:         let x0y0 = *self.heightmap.get(min_x + min_y * self.width)?;
144:         let x1y0 = *self.heightmap.get(max_x + min_y * self.width)?;
145:         let x0y1 = *self.heightmap.get(min_x + max_y * self.width)?;
146:         let x1y1 = *self.heightmap.get(max_x + max_y * self.width)?;
147: 
148:         let (height, tangent_x, tangent_z) = if fraction.x + fraction.y <= 1.0 {
149:             // Matches [x0y0, x0y1, x1y0] in `mesh_components_with_stride` and
150:             // Avian's default heightfield subdivision.
151:             (
152:                 x0y0 + (x1y0 - x0y0) * fraction.x + (x0y1 - x0y0) * fraction.y,
153:                 Vec3::new(cell_scale_x, x1y0 - x0y0, 0.0),
154:                 Vec3::new(0.0, x0y1 - x0y0, cell_scale_z),
155:             )
156:         } else {
157:             // Matches [x1y0, x0y1, x1y1].
158:             (
159:                 x1y1 + (x0y1 - x1y1) * (1.0 - fraction.x) + (x1y0 - x1y1) * (1.0 - fraction.y),
160:                 Vec3::new(cell_scale_x, x1y1 - x0y1, 0.0),
