106:     /// Only validated rigid transforms may enter here. Distinct vertices and
107:     /// positive represented area reject coordinate collapse/overflow; no general
108:     /// closure or deserialization can bypass the authored convexity boundary.
109:     fn from_rigid_projection(vertices: Vec<ScenePlanPoint>) -> Result<Self, PlanGeometryError> {
110:         let Some(first) = vertices.first() else {
111:             return Err(PlanGeometryError::DegeneratePolygon);
112:         };
113:         let origin = first.metres().as_dvec2();
114:         let area = vertices
115:             .iter()
116:             .zip(vertices.iter().cycle().skip(1))
117:             .map(|(a, b)| (a.metres().as_dvec2() - origin).perp_dot(b.metres().as_dvec2() - origin))
118:             .sum::<f64>();
119:         if vertices.len() < 3 || area <= 0.0 {
120:             return Err(PlanGeometryError::DegeneratePolygon);
121:         }
122:         for (vertex, point) in vertices.iter().enumerate() {
123:             if vertices[..vertex].contains(point) {
124:                 return Err(PlanGeometryError::DuplicateVertex { vertex });
125:             }
126:         }
127:         Ok(Self(vertices))
128:     }
129: }
