427: fn validate_grid(
428:     grid: &TerrainSampleGrid,
429:     max_side: usize,
430:     grid_kind: SampleGridKind,
431: ) -> SceneInputResult<()> {
432:     let width = usize::from(grid.width);
433:     let depth = usize::from(grid.depth);
434:     if width < 2 || depth < 2 || width > max_side || depth > max_side {
435:         return invalid(SceneValidationError::GridDimensions { grid: grid_kind });
436:     }
437:     if !grid.spacing_metres.is_finite() || !(0.25..=2_000.0).contains(&grid.spacing_metres) {
438:         return invalid(SceneValidationError::GridSpacing { grid: grid_kind });
439:     }
440:     let expected = width.checked_mul(depth).ok_or({
441:         SceneInputError::Validation(SceneValidationError::GridOverflow { grid: grid_kind })
442:     })?;
443:     if grid.heights_metres.len() != expected || grid.environment.len() != expected {
444:         return invalid(SceneValidationError::GridSamples { grid: grid_kind });
445:     }
446:     if grid
447:         .heights_metres
448:         .iter()
449:         .any(|height| !height.is_finite() || !(-12_000.0..=12_000.0).contains(height))
450:     {
451:         return invalid(SceneValidationError::GridHeight { grid: grid_kind });
452:     }
453:     if grid.environment.iter().any(|sample| {
454:         [
455:             sample.canopy_bps,
456:             sample.wetland_bps,
457:             sample.cultivation_bps,
458:             sample.water_bps,
459:             sample.hilly_bps,
460:             sample.crossing_bps,
461:         ]
462:         .into_iter()
463:         .any(|value| value > BASIS_POINTS_PER_WHOLE)
464:     }) {
465:         return invalid(SceneValidationError::GridEnvironment { grid: grid_kind });
466:     }
467:     Ok(())
468: }
