300: pub(super) fn validate_building_pads(buildings: &[GeneratedBuilding]) -> SceneInputResult<()> {
301:     let footprints = buildings
302:         .iter()
303:         .map(|building| {
304:             let half_extents = (building.collision.bounds.plan_half_extents()?.metres()
305:                 - Vec2::splat(PARTY_WALL_PROJECTION_ALLOWANCE_METRES))
306:             .max(Vec2::splat(0.1));
307:             Ok((
308:                 building.placement.id,
309:                 building.placement.centre_metres.metres(),
310:                 half_extents,
311:                 building.placement.orientation,
312:             ))
313:         })
314:         .collect::<GeometryResult<Vec<_>>>()?;
315:     for (index, &(id, centre, half_extents, orientation)) in footprints.iter().enumerate() {
316:         for &(other_id, other_centre, other_half_extents, other_orientation) in
317:             &footprints[index + 1..]
318:         {
319:             if oriented_rectangles_overlap(
320:                 centre,
321:                 half_extents,
322:                 orientation,
323:                 other_centre,
324:                 other_half_extents,
325:                 other_orientation,
326:             ) {
327:                 return invalid(SceneValidationError::BuildingOverlap {
328:                     building: id,
329:                     other: other_id,
330:                 });

331:             }
332:         }
333:     }
334:     Ok(())
335: }
336: 
337: pub(crate) fn oriented_rectangles_overlap(
338:     first_centre: Vec2,
339:     first_half_extents: Vec2,
340:     first_orientation: BuildingOrientation,
341:     second_centre: Vec2,
342:     second_half_extents: Vec2,
343:     second_orientation: BuildingOrientation,
344: ) -> bool {
345:     let first_axes = [
346:         first_orientation.local_to_world(Vec2::X),
347:         first_orientation.local_to_world(Vec2::Y),
348:     ];
349:     let second_axes = [
350:         second_orientation.local_to_world(Vec2::X),
351:         second_orientation.local_to_world(Vec2::Y),
352:     ];
353:     let centre_delta = second_centre - first_centre;
354:     first_axes.into_iter().chain(second_axes).all(|axis| {
355:         let first_radius = first_half_extents.x * axis.dot(first_axes[0]).abs()
356:             + first_half_extents.y * axis.dot(first_axes[1]).abs();
357:         let second_radius = second_half_extents.x * axis.dot(second_axes[0]).abs()
358:             + second_half_extents.y * axis.dot(second_axes[1]).abs();
359:         centre_delta.dot(axis).abs() < first_radius + second_radius
360:     })
361: }
