1: //! Horizontal obstacle exclusions retain their scene origin and collision extents.
2: 
3: use super::BuildingOrientation;
4: use crate::scene_coordinates::ScenePlanPoint;
5: use crate::scene_input::GeneratedObstacle;
6: use adventuresim_building_generator::spatial_geometry::{GeometryResult, PlanExtents};
7: use bevy::math::Vec2;
8: 
9: const OBSTACLE_APRON_METRES: f32 = 5.5;
10: 
11: /// Collision reservations permit degenerate half extents, unlike occupied plots.
12: /// Their apron excludes obstacles without selecting a terrain or building floor.
13: #[derive(Clone, Copy, Debug)]
14: pub(in crate::scene_input) struct ObstacleReservation {
15:     pub(in crate::scene_input) centre: ScenePlanPoint,
16:     pub(in crate::scene_input) half_extents: PlanExtents,
17:     pub(in crate::scene_input) orientation: BuildingOrientation,
18: }
19: 
20: impl ObstacleReservation {
21:     fn contains_apron(self, point: ScenePlanPoint) -> bool {
22:         let offset = self
23:             .orientation
24:             .world_to_local(point.metres() - self.centre.metres())
25:             .abs();
26:         offset
27:             .cmple(self.half_extents.metres() + Vec2::splat(OBSTACLE_APRON_METRES))
28:             .all()
29:     }
30: }
31: 
32: pub(in crate::scene_input) fn obstacle_intersects_building(
33:     obstacle: GeneratedObstacle,
34:     obstacle_spacing: f32,
35:     terrain_extent: Vec2,
36:     reservations: &[ObstacleReservation],
37: ) -> GeometryResult<bool> {
38:     let (x, z) = match obstacle {
39:         GeneratedObstacle::Tree { x, z } | GeneratedObstacle::Rock { x, z, .. } => (x, z),
40:     };
41:     // Decode the grid with the original multiply-then-subtract order.
42:     let point = ScenePlanPoint::try_from(
43:         Vec2::new(f32::from(x), f32::from(z)) * obstacle_spacing - terrain_extent * 0.5,
44:     )?;
45:     Ok(reservations
46:         .iter()
47:         .any(|reservation| reservation.contains_apron(point)))
48: }
