2: use super::{GeneratedObstacle, SceneTerrain};
3: use crate::scene_coordinates::ScenePlanPoint;
4: use adventuresim_building_generator::spatial_geometry::{GeometryError, PositiveLength};
5: use bevy::math::Vec2;
6: #[derive(Clone, Copy)]
7: pub(super) struct TerrainRockInfluence {
8:     pub(super) centre: ScenePlanPoint,
9:     pub(super) radius: PositiveLength,
10: }
11: #[derive(Default)]
12: pub(super) struct TerrainDetailObstacles {
13:     pub(super) trees: Vec<ScenePlanPoint>,
14:     pub(super) rocks: Vec<TerrainRockInfluence>,
15: }
16: impl TerrainDetailObstacles {
17:     /// Row-major cell ordinals and metre spacing are the obstacle-grid port.
18:     pub(super) fn from_obstacles(
19:         terrain: &SceneTerrain,
20:         obstacles: &[GeneratedObstacle],
21:         obstacle_spacing: f32,
22:     ) -> Result<Self, GeometryError> {
23:         let half_extent = Vec2::new(terrain.width(), terrain.depth()) * 0.5;
24:         let mut influences = Self::default();
25:         for obstacle in obstacles {
26:             match *obstacle {
27:                 GeneratedObstacle::Tree { x, z } => {
28:                     influences.trees.push(ScenePlanPoint::try_from(
29:                         Vec2::new(
30:                             f32::from(x) * obstacle_spacing,
31:                             f32::from(z) * obstacle_spacing,
32:                         ) - half_extent,
33:                     )?)
34:                 }
35:                 GeneratedObstacle::Rock { x, z, recipe } => {
36:                     influences.rocks.push(TerrainRockInfluence {
37:                         centre: ScenePlanPoint::try_from(
38:                             Vec2::new(
39:                                 f32::from(x) * obstacle_spacing,
40:                                 f32::from(z) * obstacle_spacing,
41:                             ) - half_extent,
42:                         )?,
43:                         radius: PositiveLength::from_metres(recipe.collision_radius_metres())?,
44:                     })
45:                 }
46:             }
47:         }
48:         Ok(influences)
49:     }
50: }

