2: use std::collections::{BTreeMap, BTreeSet};
3: 
4: use adventuresim_building_generator::signs::ShopName;
5: use adventuresim_world_schema::person_names::RenderedPersonalName;
6: use adventuresim_world_schema::settlement_buildings::BusinessId;
7: 
8: /// Immutable operator and display identity for one business in a tactical scene.
9: /// The mission snapshot owns `operator_name`; validation requires `shop_name`
10: /// to match that captured name and building use. Later missions recapture it.
11: #[derive(Clone, Debug, Eq, PartialEq, Component, Serialize, Deserialize)]
12: #[component(immutable)]
13: #[serde(deny_unknown_fields)]
14: pub struct SceneEstablishment {
15:     pub building_id: crate::scene_input::SceneBuildingId,
16:     pub business_id: BusinessId,
17:     pub operator_character_id: crate::player::CharacterId,
18:     pub operator_name: RenderedPersonalName,
19:     pub shop_name: Option<ShopName>,
20: }
21: 
22: pub(super) fn validate(input: &TacticalSceneInput) -> Result<(), SceneInputError> {
23:     let buildings = input
24:         .buildings
25:         .iter()
26:         .map(|building| (building.id, building.program.usage))
27:         .chain(
28:             input
29:                 .distant_buildings
30:                 .iter()
31:                 .map(|building| (building.id, building.usage)),
32:         )
33:         .collect::<BTreeMap<_, _>>();
34:     let mut building_ids = BTreeSet::new();
35:     let mut business_ids = BTreeSet::new();
36:     let mut operator_ids = BTreeSet::new();
37:     let mut settlement_id = None::<&str>;
38:     for establishment in &input.establishments {
39:         if establishment.building_id.0 == 0
40:             || establishment.operator_character_id.0 == 0
41:             || establishment.operator_name.as_str().is_empty()
42:         {
43:             return invalid(SceneValidationError::EstablishmentIdentity);
44:         }
45:         if !building_ids.insert(establishment.building_id)
46:             || !business_ids.insert(&establishment.business_id)
47:             || !operator_ids.insert(establishment.operator_character_id)
48:         {
49:             return invalid(SceneValidationError::EstablishmentDuplicate);
50:         }
51:         if settlement_id
52:             .replace(&establishment.business_id.settlement_id)
53:             .is_some_and(|expected| expected != establishment.business_id.settlement_id)
54:         {
55:             return invalid(SceneValidationError::EstablishmentSettlement);
56:         }
57:         let Some(usage) = buildings.get(&establishment.building_id).copied().flatten() else {
58:             return invalid(SceneValidationError::EstablishmentBuilding);
59:         };
60:         if usage != establishment.business_id.key.usage {
61:             return invalid(SceneValidationError::EstablishmentUsage);
62:         }
63:         if establishment.shop_name != ShopName::for_operator(&establishment.operator_name, usage) {
64:             return invalid(SceneValidationError::EstablishmentShopName);
65:         }
66:     }
67:     Ok(())
68: }

