72:     pub fn corners(self) -> [Vec2; 4] {
73:         [
74:             Vec2::new(-1.0, -1.0),
75:             Vec2::new(1.0, -1.0),
76:             Vec2::ONE,
77:             Vec2::new(-1.0, 1.0),
78:         ]
79:         .map(|corner| {
80:             self.centre.metres()
81:                 + self
82:                     .orientation
83:                     .local_to_world(corner * self.half_extents.metres())
84:         })
85:     }
