1: use super::*;
2: use crate::city_layout::CityStreetPatch;
3: 
4: pub(super) const DOOR_APPROACH_METRES: f32 = 4.0;
5: pub(super) const DOOR_SHOULDER_METRES: f32 = 0.5;
6: pub(super) const MARKET_AISLE_HALF_WIDTH_METRES: f32 = 2.0;
7: const EDGE_ROAD_MIN_ALIGNMENT: f32 = 0.95;
8: 
9: /// Adjacent streets can be wider than the market's pedestrian perimeter aisle.
10: /// Start vendor rows behind their full reserved width, including angled caps.
11: pub(super) fn market_edge_clearance(
12:     input: &TacticalSceneInput,
13:     start: Vec2,
14:     end: Vec2,
15:     inward: Vec2,
16: ) -> Result<f32, crate::scene_input::SceneInputError> {
17:     let tangent = (end - start).normalize_or_zero();
18:     let edge_length = start.distance(end);
19:     let mut clearance = MARKET_AISLE_HALF_WIDTH_METRES;
20:     for patch in &input.streets {
21:         let CityStreetPatch::Corridor {
22:             start_metres,
23:             end_metres,
24:             half_width_metres,
25:             ..
26:         } = *patch
27:         else {
28:             continue;
29:         };
30:         if (end_metres - start_metres)
31:             .normalize_or_zero()
32:             .dot(tangent)
33:             .abs()
34:             < EDGE_ROAD_MIN_ALIGNMENT
35:         {
36:             continue;
37:         }
38:         let mut minimum = Vec2::splat(f32::INFINITY);
39:         let mut maximum = Vec2::splat(f32::NEG_INFINITY);
40:         for corner in route(start_metres, end_metres, half_width_metres)?.corners() {
41:             let offset = corner - start;
42:             let projected = Vec2::new(offset.dot(tangent), offset.dot(inward));
43:             minimum = minimum.min(projected);
44:             maximum = maximum.max(projected);
45:         }
46:         if maximum.x >= 0.0
47:             && minimum.x <= edge_length
48:             && maximum.y >= 0.0
49:             && minimum.y <= MARKET_AISLE_HALF_WIDTH_METRES
50:         {
51:             clearance = clearance.max(maximum.y);
52:         }
53:     }
54:     Ok(clearance)
55: }
56: 
57: /// Native metre vectors enter from the existing city street/route producer.
58: /// Admission occurs here before they become scene reservations.
59: pub(super) fn route(
60:     start: Vec2,
61:     end: Vec2,
62:     half_width: f32,
63: ) -> Result<FurnitureFootprint, crate::scene_input::SceneInputError> {
64:     Ok(FurnitureFootprint::from_metres(
65:         (start + end) * 0.5,
66:         Vec2::new(start.distance(end) * 0.5 + half_width, half_width),
67:         BuildingOrientation::from_frontage_tangent(end - start)
68:             .unwrap_or(BuildingOrientation::IDENTITY),
69:     )?)
70: }
