72: pub(super) fn routes(
73:     input: &TacticalSceneInput,
74:     buildings: &[sites::FurnitureSite],
75: ) -> Result<Vec<FurnitureFootprint>, crate::scene_input::SceneInputError> {
76:     let mut routes = Vec::new();
77:     for patch in &input.streets {
78:         match *patch {
79:             CityStreetPatch::Corridor {
80:                 start_metres,
81:                 end_metres,
82:                 half_width_metres,
83:                 ..
84:             } => {
85:                 routes.push(route(start_metres, end_metres, half_width_metres)?);
86:             }
87:             CityStreetPatch::Market {
88:                 corners_metres: corners,
89:                 ..
90:             } => {
91:                 // Preserve both crossings and a perimeter circuit before any
92:                 // stalls are proposed in the remaining quadrants.
93:                 for edge in 0..4 {
94:                     routes.push(route(
95:                         corners[edge],
96:                         corners[(edge + 1) % 4],
97:                         MARKET_AISLE_HALF_WIDTH_METRES,
98:                     )?);
99:                 }
100:                 for edge in 0..2 {
101:                     let start = (corners[edge] + corners[edge + 1]) * 0.5;
102:                     let end = (corners[(edge + 2) % 4] + corners[(edge + 3) % 4]) * 0.5;
103:                     routes.push(route(start, end, MARKET_AISLE_HALF_WIDTH_METRES)?);
104:                 }
105:             }
106:         }
107:     }
108:     for building in buildings {
109:         routes.extend(building.routes.iter().copied());
110:     }

111:     if let Some(projection) = &input.grounding {
112:         // The accepted approach can include a property setback as well as the
113:         // bounded street apron. Reserve the actual grading contract, including
114:         // entrances expressed as workplace passages without a door assembly.
115:         for surface in projection.surfaces() {
116:             for approach in surface.doorway_approaches() {
117:                 routes.push(FurnitureFootprint::accepted_approach(*approach)?);
118:             }
119:         }
120:     }
121:     for compound in &input.compounds {
122:         routes.extend(
123:             compound
124:                 .access
125:                 .iter()
126:                 .map(|access| {
127:                     route(
128:                         access.start_metres(),
129:                         access.end_metres(),
130:                         access.half_width_metres(),
131:                     )
132:                 })
133:                 .collect::<Result<Vec<_>, _>>()?,
134:         );
135:         routes.push(FurnitureFootprint::gate_sweep(compound)?);
136:     }
137:     for garden in &input.gardens {
138:         routes.extend(
139:             garden
140:                 .access
141:                 .iter()
142:                 .map(|a| route(a.start_metres(), a.end_metres(), a.half_width_metres()))
143:                 .collect::<Result<Vec<_>, _>>()?,
144:         );
145:         routes.push(FurnitureFootprint::from_metres(
146:             garden.cultivated_bounds.centre_metres(),
147:             garden.cultivated_bounds.dimensions_metres() * 0.5,
148:             garden.cultivated_bounds.orientation(),
149:         )?);
150:     }
151:     Ok(routes)
152: }
