154: pub(super) fn obstacles(
155:     input: &TacticalSceneInput,
156:     terrain: &SceneTerrain,
157:     buildings: &[sites::FurnitureSite],
158:     obstacles: &[GeneratedObstacle],
159: ) -> Result<Vec<FurnitureFootprint>, super::super::SceneInputError> {
160:     let mut footprints = buildings
161:         .iter()
162:         .map(|building| {
163:             FurnitureFootprint::from_metres(
164:                 building.placement.centre_metres.metres(),
165:                 building.half_extents.metres(),
166:                 building.placement.orientation,
167:             )
168:         })
169:         .collect::<Result<Vec<_>, _>>()?;
170:     for compound in &input.compounds {
171:         footprints.extend(
172:             compound
173:                 .boundary
174:                 .fixed_members()?
175:                 .iter()
176:                 .map(|member| {
177:                     FurnitureFootprint::from_metres(
178:                         member.pose.plan_metres(),
179:                         Vec2::new(member.size_metres.metres().x, member.size_metres.metres().z)
180:                             * 0.5,
181:                         member.orientation,
182:                     )
183:                 })
184:                 .collect::<Result<Vec<_>, _>>()?,
185:         );
186:     }
187:     for obstacle in obstacles {
188:         let (x, z, radius) = match *obstacle {
189:             GeneratedObstacle::Tree { x, z } => (x, z, super::super::TREE_TRUNK_RADIUS_METRES),
190:             GeneratedObstacle::Rock { x, z, recipe } => (x, z, recipe.collision_radius_metres()),
191:         };
192:         footprints.push(FurnitureFootprint::from_metres(
193:             Vec2::new(f32::from(x), f32::from(z)) * input.playable.spacing_metres
194:                 - Vec2::new(terrain.width(), terrain.depth()) * 0.5,
195:             Vec2::splat(radius),
196:             BuildingOrientation::IDENTITY,
197:         )?);
198:     }
199:     Ok(footprints)
200: }
