202: impl FurnitureFootprint {
203:     pub(super) fn accepted_approach(
204:         region: crate::city_layout::CityPlotBounds,
205:     ) -> Result<Self, crate::scene_input::SceneInputError> {
206:         Ok(Self::from_metres(
207:             region.centre_metres(),
208:             region.dimensions_metres() * 0.5 + Vec2::splat(DOOR_SHOULDER_METRES),
209:             region.orientation(),
210:         )?)
211:     }
212: 
213:     fn gate_sweep(
214:         compound: &crate::city_layout::CityCompound,
215:     ) -> Result<Self, crate::scene_input::SceneInputError> {
216:         let gate = compound.boundary.gate.door(compound.id)?;
217:         let hinge = Vec2::new(gate.hinge_centre.metres().x, gate.hinge_centre.metres().z);
218:         // Reserve the inward quarter of the hinge's enclosing square for the
219:         // complete leaf sweep, independently of its current dynamic state.
220:         Ok(Self::from_metres(
221:             hinge
222:                 + compound
223:                     .boundary
224:                     .gate
225:                     .orientation
226:                     .local_to_world(Vec2::new(-compound.boundary.gate.hinge.sign(), 1.0))
227:                     * gate.size_metres.metres().x
228:                     * 0.5,
229:             Vec2::splat(gate.size_metres.metres().x * 0.5 + gate.size_metres.metres().z),
230:             compound.boundary.gate.orientation,
231:         )?)
232:     }
233: }
