8: #[serde(try_from = "LocalWire")]
9: pub(super) struct LocalReservation {
10:     #[serde(with = "offset_wire", rename = "centre_metres")]
11:     centre: Displacement<CollisionRelative>,
12:     #[serde(rename = "half_extents_metres")]
13:     half_extents: PlanExtents,
