16: #[derive(Deserialize)]
17: struct LocalWire {
18:     centre_metres: Vec2,
19:     half_extents_metres: PlanExtents,
20:     orientation: BuildingOrientation,
21: }
22: impl TryFrom<LocalWire> for LocalReservation {
23:     type Error = GeometryError;
24:     fn try_from(wire: LocalWire) -> Result<Self, Self::Error> {
25:         Self::from_metres(
26:             wire.centre_metres,
27:             wire.half_extents_metres.metres(),
28:             wire.orientation,
29:         )
30:     }
31: }
32: impl LocalReservation {
33:     /// Native opening/passage plan buffers are translated to the collision datum.
34:     pub(super) fn from_metres(
35:         centre: Vec2,
36:         extents: Vec2,
37:         orientation: BuildingOrientation,
38:     ) -> Result<Self, GeometryError> {
39:         let centre = Displacement::from_metres(Vec3::new(centre.x, 0.0, centre.y))?;
40:         let half_extents = PlanExtents::from_metres(extents)?;
41:         if !orientation.is_valid() {
42:             return Err(GeometryError::InvalidProjection);
43:         }
44:         for corner in [
45:             Vec2::new(-1.0, -1.0),
46:             Vec2::new(1.0, -1.0),
47:             Vec2::ONE,
48:             Vec2::new(-1.0, 1.0),
49:         ] {
50:             if !(centre.metres().xz() + orientation.local_to_world(corner * extents)).is_finite() {
51:                 return Err(GeometryError::InvalidProjection);
52:             }
53:         }
54:         Ok(Self {
55:             centre,
56:             half_extents,
57:             orientation,
58:         })
59:     }
60:     pub(super) fn route(start: Vec2, end: Vec2, half_width: f32) -> Result<Self, GeometryError> {
61:         Self::from_metres(
62:             (start + end) * 0.5,
63:             Vec2::new(start.distance(end) * 0.5 + half_width, half_width),
64:             BuildingOrientation::from_frontage_tangent(end - start)
65:                 .unwrap_or(BuildingOrientation::IDENTITY),
66:         )
67:     }
68:     pub(super) fn place(
69:         &self,
70:         placement: &TacticalBuildingPlacement,
71:     ) -> Result<FurnitureFootprint, GeometryError> {
72:         let centre = crate::scene_coordinates::ScenePlanPoint::try_from(
73:             placement.centre_metres.metres()
74:                 + placement
75:                     .orientation
76:                     .local_to_world(self.centre.metres().xz()),
77:         )?;
78:         let orientation = BuildingOrientation::from_radians(
79:             placement.orientation.yaw_radians() + self.orientation.yaw_radians(),
80:         )
81:         .ok_or(GeometryError::InvalidProjection)?;
82:         FurnitureFootprint::new(centre, self.half_extents, orientation)
83:     }
84: }
