102: pub(super) fn report_terrain_delta(name: &str, input: &TacticalSceneInput, terrain: &SceneTerrain) {
103:     let spacing_metres = 0.5;
104:     let mut max_abs = 0.0_f32;
105:     let mut max_positive = 0.0_f32;
106:     let mut max_street_abs = 0.0_f32;
107:     for z in 0..=(terrain.depth() / spacing_metres) as usize {
108:         for x in 0..=(terrain.width() / spacing_metres) as usize {
109:             let point = Vec2::new(
110:                 x as f32 * spacing_metres - terrain.width() * 0.5,
111:                 z as f32 * spacing_metres - terrain.depth() * 0.5,
112:             );
113:             let scene_point = ScenePlanPoint::from_metres(point).unwrap();
114:             let (Some(fine), Some(coarse)) = (
115:                 terrain.height_at(scene_point),
116:                 terrain.coarse_height_at(scene_point),
117:             ) else {
118:                 continue;
119:             };
120:             let delta = fine.metres() - coarse.metres();
121:             max_abs = max_abs.max(delta.abs());
122:             max_positive = max_positive.max(delta);
123:             if input.streets.iter().any(|patch| patch.contains(point)) {
124:                 max_street_abs = max_street_abs.max(delta.abs());
125:             }

