11: #[derive(Clone, Debug, PartialEq, Component, Serialize, Deserialize)]
12: #[component(immutable)]
13: #[serde(deny_unknown_fields, try_from = "SceneGardenWire")]
14: pub struct SceneGarden {
15:     garden: CityGarden,
16:     /// Exact roots in scene coordinates; membership and horizontal poses stay
17:     /// in the authoritative garden descriptor. A house floor is not soil.
18:     plant_support: Vec<GardenPlantSupport>,
19: }
20: 
21: #[derive(Deserialize)]
22: #[serde(deny_unknown_fields)]
23: struct SceneGardenWire {
24:     garden: CityGarden,
25:     plant_support: Vec<GardenPlantSupport>,
26: }
27: impl TryFrom<SceneGardenWire> for SceneGarden {
28:     type Error = GardenSupportError;
29:     fn try_from(wire: SceneGardenWire) -> Result<Self, Self::Error> {
30:         Self::from_support(wire.garden, wire.plant_support)
31:     }
32: }
33: impl SceneGarden {
34:     pub fn garden(&self) -> &CityGarden {
35:         &self.garden
36:     }
37:     pub fn plant_support(&self) -> &[GardenPlantSupport] {
38:         &self.plant_support
39:     }
40:     pub fn from_support(
41:         garden: CityGarden,
42:         plant_support: Vec<GardenPlantSupport>,
43:     ) -> Result<Self, GardenSupportError> {
44:         if garden.owner.0 == 0
45:             || garden.owner.0 > MAX_CITY_LOTS as u64
46:             || garden.front_building_id.0 == 0
47:             || garden.plants.iter().any(|plant| plant.id.0 == 0)
48:         {
49:             return Err(GardenSupportError::Identity {
50:                 property: garden.owner,
51:                 building: garden.front_building_id,
52:                 plant: garden
53:                     .plants
54:                     .iter()
55:                     .find(|plant| plant.id.0 == 0)
56:                     .map(|plant| plant.id),
57:             });
58:         }
59:         let mut ids = BTreeSet::new();
60:         for (index, plant) in garden.plants.iter().enumerate() {
61:             let actual = plant_support.get(index).map(|root| root.plant_id);
62:             if !ids.insert(plant.id) || actual != Some(plant.id) {
63:                 return Err(GardenSupportError::Membership {
64:                     property: garden.owner,
65:                     building: garden.front_building_id,
66:                     index,
67:                     expected: Some(plant.id),
68:                     actual,
69:                 });
70:             }
71:         }
72:         if plant_support.len() != garden.plants.len() {
73:             return Err(GardenSupportError::Membership {
74:                 property: garden.owner,
75:                 building: garden.front_building_id,
76:                 index: garden.plants.len(),
77:                 expected: None,
78:                 actual: plant_support
79:                     .get(garden.plants.len())
80:                     .map(|root| root.plant_id),
81:             });
82:         }
83:         Ok(Self {
84:             garden,
85:             plant_support,
86:         })
87:     }
88: }
