94:     pub elevation: SupportElevation,
95: }
96: 
97: pub(super) fn validate(input: &TacticalSceneInput) -> Result<(), SceneInputError> {
98:     if input.gardens.len() > MAX_CITY_LOTS {
99:         return invalid(SceneValidationError::GardenCount);
100:     }
101:     let mut owners = input
102:         .compounds
103:         .iter()
104:         .map(|c| c.id)
105:         .collect::<BTreeSet<_>>();
106:     let mut members = input
107:         .compounds
108:         .iter()
109:         .flat_map(|c| [c.front_building_id, c.rear_building_id])
110:         .collect::<BTreeSet<_>>();
111:     let mut plants = BTreeSet::new();
112:     for garden in &input.gardens {
113:         if garden.owner.0 == 0
114:             || garden.owner.0 > MAX_CITY_LOTS as u64
115:             || garden.owner.0 != garden.front_building_id.0
116:             || !owners.insert(garden.owner)
117:             || !members.insert(garden.front_building_id)
118:             || garden
119:                 .plants
120:                 .iter()
121:                 .any(|p| p.id.0 == 0 || !plants.insert(p.id))
122:         {
123:             return invalid(SceneValidationError::GardenOwnership {
124:                 owner: super::validation_error::SceneOwnerContext::garden(garden),
125:             });

