176:     /// Exhaustively checks garden clearance against complete rendered buildings.
177:     ///
178:     /// Intended for scene authoring and tests. This compiles every distinct
179:     /// distant recipe, including its detailed meshes, and is not part of loading
180:     /// an accepted scene. Runtime validation retains ownership and plot checks.
181:     pub fn audit_garden_clearance(
182:         &self,
183:         generated: &GeneratedTacticalScene,
184:     ) -> Result<(), SceneInputError> {
185:         crate::city_layout::validate_scene_gardens(
186:             &self.gardens,
187:             &generated.buildings,
188:             &self.distant_buildings,
189:         )
190:         .map_err(|cause| SceneInputError::Validation(SceneValidationError::GardenClearance(cause)))
191:     }
192: }
