35: impl SceneGarden {
36:     /// Project every accepted plant without moving, omitting or reseeding it.
37:     /// This binds roots only; route grade and enclosure clearance have separate
38:     /// acceptance checks. The complete geographic/support terrain is required.
39:     pub fn project(garden: CityGarden, terrain: &SceneTerrain) -> Result<Self> {
40:         let plant_support = garden
41:             .plants
42:             .iter()
43:             .map(|plant| {
44:                 let elevation = terrain.height_at(plant.centre_metres).ok_or(
45:                     GardenSupportError::MissingSoil {
46:                         property: garden.owner,
47:                         building: garden.front_building_id,
48:                         plant: plant.id,
49:                         location_metres: plant.centre_metres,
50:                     },
51:                 )?;
52:                 Ok(GardenPlantSupport {
53:                     plant_id: plant.id,
54:                     elevation,
55:                 })
56:             })
57:             .collect::<Result<_>>()?;
58:         Self::from_support(garden, plant_support)
59:     }
60: }
