171: fn move_first_property(mut input: TacticalSceneInput, offset: Vec2) -> TacticalSceneInput {
172:     input.gardens.truncate(1);
173:     input.distant_buildings.clear();
174:     input.streets.truncate(1);
175:     input.yards.truncate(3);
176:     input.buildings[0].centre_metres = input.buildings[0]
177:         .centre_metres
178:         .translated(crate::scene_coordinates::PlanDisplacement::try_from(offset).unwrap())
179:         .unwrap();
180:     let garden = &mut input.gardens[0];
181:     garden
182:         .plot
183:         .relocate(
184:             crate::scene_coordinates::ScenePlanPoint::try_from(
185:                 garden.plot.centre_metres() + (offset),
186:             )
187:             .unwrap(),
188:         )
189:         .unwrap();
190:     garden
191:         .cultivated_bounds
192:         .relocate(
193:             crate::scene_coordinates::ScenePlanPoint::try_from(
194:                 garden.cultivated_bounds.centre_metres() + (offset),
195:             )
196:             .unwrap(),
197:         )
198:         .unwrap();
199:     for bed in &mut garden.beds {
200:         bed.relocate(
201:             crate::scene_coordinates::ScenePlanPoint::try_from(bed.centre_metres() + (offset))
202:                 .unwrap(),
203:         )
204:         .unwrap();
205:     }
206:     for route in &mut garden.access {
207:         route
208:             .update_endpoints(
209:                 crate::scene_coordinates::ScenePlanPoint::try_from(route.start_metres() + (offset))
210:                     .unwrap(),
211:                 route.end(),
212:             )
213:             .unwrap();
214:         route
215:             .update_endpoints(
216:                 route.start(),
217:                 crate::scene_coordinates::ScenePlanPoint::try_from(route.end_metres() + (offset))
218:                     .unwrap(),
219:             )
220:             .unwrap();
221:     }
222:     for plant in &mut garden.plants {
223:         plant.centre_metres = plant
224:             .centre_metres
225:             .translated(crate::scene_coordinates::PlanDisplacement::try_from(offset).unwrap())
226:             .unwrap();
227:     }
228:     for yard in &mut input.yards {
229:         for point in &mut yard.corners_metres {
230:             *point += offset;
231:         }
232:     }
233:     for street in &mut input.streets {
234:         if let crate::city_layout::CityStreetPatch::Corridor {
235:             start_metres,
236:             end_metres,
237:             ..
238:         } = street
239:         {
240:             *start_metres += offset;
241:             *end_metres += offset;
242:         }
243:     }
244:     input
245: }
