1: //! Complete scene context prepares geographic relief before property grading.
2: use super::*;
3: use crate::scene_input::refinement::refine_authoritative_terrain;
4: 
5: /// Geographic preparation retains the scene's complete asset reservations.
6: /// Floors and owned support are installed only after this surface is prepared.
7: #[derive(Debug)]
8: pub struct UngradedSceneTerrain {
9:     pub terrain: SceneTerrain,
10:     pub ground: SceneGround,
11:     pub buildings: Vec<GeneratedBuilding>,
12:     pub obstacles: Vec<GeneratedObstacle>,
13:     pub repairs: SceneRepairReport,
14: }
15: 
16: impl TacticalSceneInput {
17:     /// Prepare the exact fine terrain used as the source for bounded grading.
18:     /// No scene clone, synthetic source or omitted property changes the ground
19:     /// cover or obstacle context. This operation does not seat buildings.
20:     pub fn prepare_geographic_terrain(
21:         &self,
22:         recipes: &mut GeneratedBuildingRecipes,
23:     ) -> Result<UngradedSceneTerrain, SceneInputError> {
24:         self.validate_source()?;
25:         let buildings = buildings::prepare_buildings(&self.buildings, recipes)?;
26:         let (width, depth, spacing, mut heights, mut environment) =
27:             upsample_playable_grid(&self.playable);
28:         let mut repairs =
29:             prepare_terrain(self, width, depth, spacing, &mut heights, &mut environment)?;
30:         let coarse = SceneTerrain::from_heightmap(width, depth, spacing, heights).ok_or(
31:             SceneInputError::Validation(SceneValidationError::GeographicHeightmap),
32:         )?;
33:         let mut obstacles = generated_obstacles(self);
34:         remove_reserved_obstacles(self, &mut obstacles, &mut repairs);
35:         let reservations = obstacle_reservations(self, &buildings)?;
36:         remove_building_obstacles(self, &coarse, &reservations, &mut obstacles, &mut repairs)?;
37:         let ground = build_scene_ground(
38:             &environment,
39:             &coarse,
40:             &obstacles,
41:             self.playable.spacing_metres,
42:             &buildings,
43:             &self.streets,
44:             &self.yards,
45:         )?;
46:         // Geographic repair and microrelief precede property grading. No pad
47:         // selects a floor, suppresses source relief or levels adjacent land.
48:         let terrain = refine_authoritative_terrain(
49:             self.seed,
50:             &coarse,
51:             &ground,
52:             &obstacles,
53:             self.playable.spacing_metres,
54:             self.weather.ground_moisture_bps,
55:         )?;
56:         Ok(UngradedSceneTerrain {
57:             terrain,
58:             ground,
59:             buildings,
60:             obstacles,
61:             repairs,
62:         })
63:     }
64: }
65: 
66: fn obstacle_reservations(
67:     input: &TacticalSceneInput,
68:     buildings: &[GeneratedBuilding],
69: ) -> Result<Vec<buildings::ObstacleReservation>, SceneInputError> {
70:     let mut pads: Vec<_> = buildings
71:         .iter()
72:         .map(|building| Ok(buildings::ObstacleReservation {
73:             centre: building.placement.centre_metres,
74:             half_extents: building.collision.bounds.plan_half_extents()?,
75:             orientation: building.placement.orientation,
76:         }))
77:         .collect::<Result<Vec<_>, adventuresim_building_generator::spatial_geometry::GeometryError>>()?;
78:     // Only horizontal occupancy removes obstacles. Compound members may have
79:     // different floors, and garden soil need not share its house's elevation.
80:     pads.extend(
81:         input
82:             .compounds
83:             .iter()
84:             .map(|property| property.plot)
85:             .chain(input.gardens.iter().map(|garden| garden.plot))
86:             .map(|plot| buildings::ObstacleReservation {
87:                 centre: plot.centre(),
88:                 half_extents: plot.dimensions().half_extents(),
89:                 orientation: plot.orientation(),
90:             }),
91:     );
92:     Ok(pads)
93: }
