6: 
7: #[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
8: pub struct GeneratedBuildingRecipe {
9:     pub program: BuildingProgram,
10:     pub plan: BuildingPlan,
11:     pub collision: BuildingCollision,
12: }
13: 
14: impl GeneratedBuildingRecipe {
15:     pub fn generate(program: BuildingProgram) -> Result<Self, GenerationError> {
16:         let plan = generate(&program)?;
17:         let collision = compile_building_collision(&plan)?;
18:         Ok(Self {
19:             program,
20:             plan,
21:             collision,
22:         })
23:     }
24: }
25: 
26: /// Shares each exact program's plan and collision across preparation consumers.
27: /// Render compilation takes ownership so temporary CPU geometry can be released.
28: #[derive(Clone, Debug, Default)]
29: pub struct GeneratedBuildingRecipes {
30:     recipes: Vec<GeneratedBuildingRecipe>,
31:     pub sites: Vec<ProgramFurnitureSite>,
32: }
33: 
34: #[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
35: pub struct ProgramFurnitureSite {
36:     pub program: BuildingProgram,
37:     pub recipe: super::furniture::FurnitureSiteRecipe,
38: }
39: impl GeneratedBuildingRecipes {
40:     pub fn insert(&mut self, recipe: GeneratedBuildingRecipe) {
41:         self.recipes
42:             .retain(|existing| existing.program != recipe.program);
43:         self.recipes.push(recipe);
44:     }
45:     pub fn get_or_generate(
46:         &mut self,
47:         program: &BuildingProgram,
48:     ) -> Result<&GeneratedBuildingRecipe, GenerationError> {
49:         let index = match self
50:             .recipes
51:             .iter()
52:             .position(|recipe| recipe.program == *program)
53:         {
54:             Some(index) => index,
55:             None => {
56:                 self.recipes
57:                     .push(GeneratedBuildingRecipe::generate(program.clone())?);
58:                 self.recipes.len() - 1
59:             }
60:         };
61:         Ok(&self.recipes[index])
62:     }
63: 
64:     pub fn take(&mut self, program: &BuildingProgram) -> Option<GeneratedBuildingRecipe> {
65:         let index = self
66:             .recipes
67:             .iter()
68:             .position(|recipe| recipe.program == *program)?;
69:         Some(self.recipes.swap_remove(index))
70:     }
71: 
72:     pub fn clear(&mut self) {
73:         self.recipes.clear();
74:         self.sites.clear();
75:     }
76: 
77:     pub fn is_empty(&self) -> bool {
78:         self.recipes.is_empty() && self.sites.is_empty()
79:     }
80: }
