1: //! Authoritative microrelief is prepared before owned property support.
2: use super::{
3:     GeneratedObstacle, SceneInputError, SceneInputResult, SceneValidationError,
4:     detail_noise::DetailNoise,
5:     detail_obstacles::{TerrainDetailObstacles, TerrainRockInfluence},
6:     rock_recipe::wrapped_angle_difference,
7: };
8: use crate::{
9:     city_layout::grounding::SupportElevation,
10:     scene::{GroundCover, GroundSubstrate, SceneGround, SceneTerrain},
11:     scene_coordinates::ScenePlanPoint,
12:     terrain_streams as streams,
13: };
14: use adventuresim_world_schema::UnitBasisPoints;
15: use bevy::math::Vec2;
16: use fabelgeist_determinism::Seed;
17: use road::road_surface_relief;
18: 
19: mod road;
20: 
21: pub(super) const AUTHORITATIVE_DETAIL_SPACING_METRES: f32 = 0.5;
22: const DETAIL_RELIEF_MINIMUM_METRES: f32 = -0.075;
23: const DETAIL_RELIEF_MAXIMUM_METRES: f32 = 0.105;
24: 
25: #[derive(Clone, Copy)]
26: struct TerrainShapeSample {
27:     downhill: Vec2,
28:     slope: f32,
29:     concavity: f32,
30: }
31: 
32: /// Builds the one high-resolution surface used by height queries, IK,
33: /// rendering, and the server heightfield collider. The original grid is kept
34: /// implicitly as `SceneTerrain`'s coarse render LOD.
35: pub(super) fn refine_authoritative_terrain(
36:     seed: Seed,
37:     terrain: &SceneTerrain,
38:     ground: &SceneGround,
39:     obstacles: &[GeneratedObstacle],
40:     obstacle_spacing: f32,
41:     moisture_bps: u16,
42: ) -> SceneInputResult<SceneTerrain> {
43:     let influences = TerrainDetailObstacles::from_obstacles(terrain, obstacles, obstacle_spacing)?;
44:     let detail_seed = streams::DETAIL.seed(seed, &[]);
45:     let noise = DetailNoise::new(detail_seed);
46:     let mut terrain = terrain
47:         .refined(AUTHORITATIVE_DETAIL_SPACING_METRES, |point, base_height| {
48:             SupportElevation::from_metres(
49:                 base_height.metres()
50:                     + authoritative_surface_relief(
51:                         detail_seed,
52:                         point,
53:                         terrain,
54:                         ground,
55:                         moisture_bps,
56:                         &influences,
57:                         &noise,
58:                     ),
59:             )
60:         })
61:         .ok_or(SceneInputError::Validation(
62:             SceneValidationError::DetailTerrain,
63:         ))?;
64:     terrain.constrain_max_grade(crate::scene::grade::TerrainGradeLimit::PLAYABLE)?;
65:     Ok(terrain)
66: }
67: 
68: fn authoritative_surface_relief(
69:     seed: Seed,
70:     point: ScenePlanPoint,
71:     terrain: &SceneTerrain,
72:     ground: &SceneGround,
73:     moisture_bps: u16,
74:     influences: &TerrainDetailObstacles,
75:     noise: &DetailNoise,
76: ) -> f32 {
77:     let surface = ground.ground_at(point);
78:     if surface.is_some_and(|surface| surface.substrate == GroundSubstrate::Water) {
79:         return 0.0;
80:     }
81:     if surface.is_some_and(|surface| surface.substrate == GroundSubstrate::Road) {
82:         return road_surface_relief(point, ground, noise);
83:     }
84: 
85:     let broad = signed_ground_noise(noise.fields.broad, point.metres() / 3.2, noise) * 0.024;
86:     let fine = signed_ground_noise(noise.fields.fine, point.metres() / 0.92, noise) * 0.009;
87:     let clod_strength = match surface.map(|surface| surface.substrate) {
88:         Some(GroundSubstrate::Stone) => 0.0,
89:         Some(GroundSubstrate::Gravel) => 0.25,
90:         Some(GroundSubstrate::Mud | GroundSubstrate::Soil) => 1.0,
91:         Some(GroundSubstrate::Road | GroundSubstrate::Water) => unreachable!(),
92:         None => 1.0,
93:     };
94:     let clods = terrain_clod_relief(point, noise) * clod_strength;
95:     let shape = terrain_shape_sample(terrain, point, AUTHORITATIVE_DETAIL_SPACING_METRES * 3.0);
96:     let process_relief = shape.map_or(0.0, |shape| {
97:         drainage_relief(point, shape, moisture_bps, noise)
98:             + soil_creep_relief(point, shape, noise)
99:             + shape.concavity.clamp(-0.018, 0.024)
100:     });
101:     let roots = tree_root_relief(seed, point, &influences.trees);
102:     let rock_contact = boulder_ground_relief(seed, point, shape, &influences.rocks, noise);
103:     let rock_strata = match surface.map(|surface| surface.substrate) {
104:         Some(GroundSubstrate::Stone) => rocky_substrate_relief(seed, point, shape, 1.0, noise),
105:         Some(GroundSubstrate::Gravel) => rocky_substrate_relief(seed, point, shape, 0.62, noise),
106:         _ => 0.0,
107:     };
108:     let substrate_strength = match surface.map(|surface| surface.substrate) {
109:         Some(GroundSubstrate::Stone) => 0.54,
110:         Some(GroundSubstrate::Gravel) => 0.68,
111:         Some(GroundSubstrate::Mud) => 0.78,
112:         Some(GroundSubstrate::Soil) => 1.0,
113:         Some(GroundSubstrate::Road | GroundSubstrate::Water) => unreachable!(),
114:         None => 0.62,
115:     };
116:     let cover_strength = match surface.map(|surface| surface.cover) {
117:         Some(GroundCover::Reeds) => 0.35,
118:         Some(GroundCover::LooseStone) => 0.78,
119:         _ => 1.0,
120:     };
121:     ((broad + fine + clods + process_relief) * substrate_strength * cover_strength
122:         + roots
123:         + rock_contact
124:         + rock_strata)
125:         .clamp(DETAIL_RELIEF_MINIMUM_METRES, DETAIL_RELIEF_MAXIMUM_METRES)

126: }
127: 
128: fn terrain_shape_sample(
129:     terrain: &SceneTerrain,
130:     point: ScenePlanPoint,
131:     radius: f32,
132: ) -> Option<TerrainShapeSample> {
133:     let centre = terrain.height_at(point)?;
134:     let east = terrain.height_at(ScenePlanPoint::from_metres(
135:         point.metres() + Vec2::X * radius,
136:     )?)?;
137:     let west = terrain.height_at(ScenePlanPoint::from_metres(
138:         point.metres() - Vec2::X * radius,
139:     )?)?;
140:     let north = terrain.height_at(ScenePlanPoint::from_metres(
141:         point.metres() + Vec2::Y * radius,
142:     )?)?;
143:     let south = terrain.height_at(ScenePlanPoint::from_metres(
144:         point.metres() - Vec2::Y * radius,
145:     )?)?;
146:     let gradient = Vec2::new(
147:         east.metres() - west.metres(),
148:         north.metres() - south.metres(),
149:     ) / (radius * 2.0);
150:     let slope = gradient.length();
151:     let downhill = if slope > 0.000_1 {
152:         -gradient / slope
153:     } else {
154:         Vec2::X
155:     };
156:     Some(TerrainShapeSample {
157:         downhill,
158:         slope,
159:         concavity: ((east.metres() + west.metres() + north.metres() + south.metres()) * 0.25
160:             - centre.metres())
161:             * 0.18,
162:     })
163: }
164: 
165: fn signed_ground_noise(seed: Seed, point: Vec2, noise: &DetailNoise) -> f32 {
166:     noise.sample(seed, point) * 2.0 - 1.0
167: }
168: 
169: fn terrain_clod_relief(point: ScenePlanPoint, noise: &DetailNoise) -> f32 {
170:     let point = point.metres();
171:     let field = noise.sample(noise.fields.clod, point / 0.58);
172:     detail_smoothstep(0.69, 0.91, field) * 0.022 - 0.003
173: }
174: 
175: fn drainage_relief(
176:     point: ScenePlanPoint,
177:     shape: TerrainShapeSample,
178:     moisture_bps: u16,
179:     noise: &DetailNoise,
180: ) -> f32 {
181:     let point = point.metres();
182:     let slope_weight = detail_smoothstep(0.012, 0.16, shape.slope);
183:     if slope_weight <= 0.0 {
184:         return 0.0;
185:     }
186:     let normal = Vec2::new(-shape.downhill.y, shape.downhill.x);
187:     let warp = signed_ground_noise(noise.fields.rill_warp, point / 5.5, noise) * 0.85;
188:     let spacing = 2.6 + noise.sample(noise.fields.rill_spacing, point / 11.0) * 1.4;
189:     let distance = periodic_distance(point.dot(normal) + warp, spacing);
190:     let channel = 1.0 - detail_smoothstep(0.08, 0.34, distance);
191:     let shoulder =
192:         detail_smoothstep(0.18, 0.42, distance) * (1.0 - detail_smoothstep(0.42, 0.72, distance));
193:     let moisture = UnitBasisPoints::saturating(moisture_bps).as_unit_f32();
194:     (-channel * (0.026 + moisture * 0.012) + shoulder * 0.009) * slope_weight
195: }
196: 
197: fn soil_creep_relief(point: ScenePlanPoint, shape: TerrainShapeSample, noise: &DetailNoise) -> f32 {
198:     let point = point.metres();
199:     let slope_weight = detail_smoothstep(0.035, 0.22, shape.slope);
200:     let warp = signed_ground_noise(noise.fields.creep_warp, point / 7.0, noise) * 0.55;
201:     let distance = periodic_distance(point.dot(shape.downhill) + warp, 3.1);
202:     (1.0 - detail_smoothstep(0.12, 0.52, distance)) * 0.019 * slope_weight
203: }
204: 
205: fn rocky_substrate_relief(
206:     seed: Seed,
207:     point: ScenePlanPoint,
208:     shape: Option<TerrainShapeSample>,
209:     strength: f32,
210:     noise: &DetailNoise,
211: ) -> f32 {
212:     let point = point.metres();
213:     let fallback_angle = streams::STRATA_DIRECTION
214:         .rng(seed, &[])
215:         .inclusive_unit_f32()
216:         * core::f32::consts::TAU;
217:     let downhill = shape.map(|shape| shape.downhill).unwrap_or(Vec2::new(
218:         libm::cosf(fallback_angle),
219:         libm::sinf(fallback_angle),
220:     ));
221:     let across = Vec2::new(-downhill.y, downhill.x);
222:     let slope_weight = shape
223:         .map(|shape| detail_smoothstep(0.018, 0.18, shape.slope))
224:         .unwrap_or(0.35);
225:     let contour = point.dot(downhill)
226:         + signed_ground_noise(noise.fields.strata_warp, point / 6.5, noise) * 0.72;
227:     let shelf = (1.0 - detail_smoothstep(0.08, 0.48, periodic_distance(contour, 2.15)))
228:         * (0.019 + slope_weight * 0.029);
229:     let fracture_a = periodic_distance(
230:         point.dot(across) + signed_ground_noise(noise.fields.fracture_a, point / 4.8, noise) * 0.4,
231:         3.7,
232:     );
233:     let diagonal = (across * 0.72 + downhill * 0.69).normalize_or_zero();
234:     let fracture_b = periodic_distance(
235:         point.dot(diagonal)
236:             + signed_ground_noise(noise.fields.fracture_b, point / 5.6, noise) * 0.34,
237:         5.3,
238:     );
239:     let crack = (1.0 - detail_smoothstep(0.035, 0.17, fracture_a))
240:         .max((1.0 - detail_smoothstep(0.035, 0.15, fracture_b)) * 0.72);
