244: fn boulder_ground_relief(
245:     seed: Seed,
246:     point: ScenePlanPoint,
247:     shape: Option<TerrainShapeSample>,
248:     rocks: &[TerrainRockInfluence],
249:     noise: &DetailNoise,
250: ) -> f32 {

251:     let point = point.metres();
252:     let mut relief = 0.0;
253:     for rock in rocks {
254:         let offset = point - rock.centre.metres();
255:         let distance = offset.length();
256:         let radius = rock.radius.metres().max(0.35);
257:         if distance > radius * 5.0 {
258:             continue;
259:         }
260:         let rock_seed = streams::ROCK_INFLUENCE.seed(
261:             seed,
262:             &[
263:                 u64::from(rock.centre.metres().x.to_bits()),
264:                 u64::from(rock.centre.metres().y.to_bits()),
265:             ],
266:         );
267:         let fallback_angle = streams::ROCK_DOWNHILL
268:             .rng(rock_seed, &[])
269:             .inclusive_unit_f32()
270:             * core::f32::consts::TAU;
271:         let downhill = shape.map(|shape| shape.downhill).unwrap_or(Vec2::new(
272:             libm::cosf(fallback_angle),
273:             libm::sinf(fallback_angle),
274:         ));
275:         let across_axis = Vec2::new(-downhill.y, downhill.x);
276:         let socket = (1.0 - detail_smoothstep(radius * 0.48, radius * 1.08, distance)) * -0.042;
277:         let apron = detail_smoothstep(radius * 0.72, radius * 1.04, distance)
278:             * (1.0 - detail_smoothstep(radius * 1.04, radius * 1.72, distance))
279:             * 0.033;
280:         let downstream = offset.dot(downhill);
281:         let across = offset.dot(across_axis).abs();
282:         let tail_length =
283:             radius * (3.2 + streams::ROCK_TAIL.rng(rock_seed, &[]).inclusive_unit_f32() * 1.1);
284:         let longitudinal = detail_smoothstep(radius * 0.45, radius * 0.95, downstream)
285:             * (1.0 - detail_smoothstep(tail_length * 0.62, tail_length, downstream));
286:         let tail_width = radius * 0.42 + downstream.max(0.0) * 0.24;
287:         let lateral = 1.0 - detail_smoothstep(tail_width * 0.42, tail_width, across);
288:         let granular = 0.72
289:             + noise.sample(
290:                 streams::ROCK_DEBRIS.seed(rock_seed, &[]),
291:                 Vec2::new(downstream / 1.7, across / 0.8),
292:             ) * 0.28;
293:         relief += socket + apron + longitudinal * lateral * granular * 0.034;
294:     }
295:     relief.clamp(-0.055, 0.07)
296: }
