298: fn tree_root_relief(seed: Seed, point: ScenePlanPoint, tree_positions: &[ScenePlanPoint]) -> f32 {
299:     let point = point.metres();
300:     let mut relief = 0.0;
301:     for &tree in tree_positions {
302:         let tree = tree.metres();
303:         let offset = point - tree;
304:         let radius = offset.length();
305:         if radius > 8.0 {
306:             continue;
307:         }
308:         let tree_seed = streams::TREE_ROOTS.seed(
309:             seed,
310:             &[u64::from(tree.x.to_bits()), u64::from(tree.y.to_bits())],
311:         );
312:         let mound = libm::expf(-(radius / 1.35).powi(2)) * 0.045;
313:         let basin = detail_smoothstep(0.9, 1.8, radius)
314:             * (1.0 - detail_smoothstep(5.2, 7.7, radius))
315:             * -0.012;
316:         let angle = libm::atan2f(offset.y, offset.x);
317:         let mut ridges = 0.0_f32;
318:         for root in 0..7_u64 {
319:             let mut random = streams::ROOT_SHAPE.rng(tree_seed, &[root]);
320:             let origin = random.inclusive_unit_f32() * core::f32::consts::TAU;
321:             let phase = random.inclusive_unit_f32() * core::f32::consts::TAU;
322:             let length = 4.8 + random.inclusive_unit_f32() * 2.9;
323:             if radius > length || radius < 0.28 {
324:                 continue;
325:             }
326:             let curved_angle = origin + libm::sinf(radius * 0.9 + phase) * 0.11;
327:             let angular_distance = wrapped_angle_difference(angle, curved_angle).abs() * radius;
328:             let width = 0.16 + radius * 0.045;
329:             let ridge = 1.0 - detail_smoothstep(width * 0.3, width, angular_distance);
330:             let taper = 1.0 - detail_smoothstep(length * 0.58, length, radius);
331:             ridges = ridges.max(ridge * taper * (0.082 - radius * 0.007).max(0.025));
332:         }
333:         relief += mound + basin + ridges;
334:     }
335:     relief.clamp(-0.02, 0.115)
336: }
337: 
338: fn periodic_distance(value: f32, period: f32) -> f32 {
339:     let wrapped = value.rem_euclid(period);
340:     wrapped.min(period - wrapped)
341: }
342: 
343: fn detail_smoothstep(edge0: f32, edge1: f32, value: f32) -> f32 {
344:     let t = ((value - edge0) / (edge1 - edge0)).clamp(0.0, 1.0);
345:     t * t * (3.0 - 2.0 * t)
346: }

