1: //! Native road-profile probes preserve the deterministic source relief.
2: use super::{DetailNoise, GroundSubstrate, SceneGround, ScenePlanPoint, signed_ground_noise};
3: use bevy::math::Vec2;
4: 
5: pub(super) fn road_surface_relief(
6:     point: ScenePlanPoint,
7:     ground: &SceneGround,
8:     noise: &DetailNoise,
9: ) -> f32 {
10:     let point = point.metres();
11:     let is_road = |sample: Vec2| {
12:         ScenePlanPoint::from_metres(sample)
13:             .and_then(|point| ground.ground_at(point))
14:             .is_some_and(|surface| surface.substrate == GroundSubstrate::Road)
15:     };
16:     let mut tangent = Vec2::X;
17:     let mut best_score: Option<i32> = None;
18:     for direction_index in 0..8 {
19:         let angle = direction_index as f32 * core::f32::consts::PI / 8.0;
20:         let candidate = Vec2::new(libm::cosf(angle), libm::sinf(angle));
21:         let score = [0.75_f32, 1.5, 2.5]
22:             .into_iter()
23:             .map(|distance| {
24:                 i32::from(is_road(point + candidate * distance))
25:                     + i32::from(is_road(point - candidate * distance))
26:             })
27:             .sum();
28:         if best_score.is_none_or(|best| score > best) {
29:             best_score = Some(score);
30:             tangent = candidate;
31:         }
32:     }
33:     let normal = Vec2::new(-tangent.y, tangent.x);
34:     let edge_distance = |direction: f32| {
35:         (1..=24)
36:             .map(|step| step as f32 * 0.25)
37:             .find(|distance| !is_road(point + normal * direction * *distance))
38:             .unwrap_or(6.0)
39:     };
40:     let positive_edge = edge_distance(1.0);
41:     let negative_edge = edge_distance(-1.0);
42:     let half_width = ((positive_edge + negative_edge) * 0.5).max(0.6);
43:     let across = (negative_edge - positive_edge) * 0.5;
44:     let rut_offset = (half_width * 0.46).clamp(0.38, 0.82);
45:     let rut_width = (half_width * 0.12).clamp(0.14, 0.27);
46:     // Accepted terrain hashes require software transcendental math on all targets.
47:     let gaussian = |distance: f32| libm::expf(-(distance / rut_width).powi(2) * 1.7);
48:     let ruts = gaussian(across - rut_offset) + gaussian(across + rut_offset);
49:     let crown = (1.0 - (across / half_width).powi(2)).max(0.0) * 0.026;
50:     let travelled = point.dot(tangent);
51:     let irregularity = signed_ground_noise(
52:         noise.fields.road_rut,
53:         Vec2::new(travelled / 2.4, across / 1.1),
54:         noise,
55:     ) * 0.004;
56:     (crown - ruts * 0.038 + irregularity).clamp(-0.048, 0.032)
57: }
