381: // Bilinear, LOD, seam and triangle interpolation are one native calculation.
382: // Intermediate f32 samples stay unadmitted so a nonfinite coarse sample cannot
383: // become "absent" and select the valid-own fallback before the completed result.
384: fn native_presented_vista_vertex_height(
385:     lod: &VistaLod,
386:     coarser_lod: Option<&VistaLod>,
387:     playable_terrain: Option<&SceneTerrain>,
388:     local: PlanDisplacement,
389:     playable_half_extent: Vec2,
390: ) -> Option<f32> {
391:     let world = lod.scene_point(local).ok()?;
392:     let vista_height = native_presented_height_at(lod, world, coarser_lod)?;
393:     Some(playable_terrain.map_or(vista_height, |terrain| {
394:         native_stitch_vista_height_to_playable_edge(
395:             terrain,
396:             local,
397:             playable_half_extent,
398:             lod.spacing_metres,
399:             vista_height,
400:         )
401:     }))
402: }
403: 
404: fn native_stitch_vista_height_to_playable_edge(
405:     terrain: &SceneTerrain,
406:     local: PlanDisplacement,
407:     playable_half_extent: Vec2,
408:     transition_width: f32,
409:     vista_height: f32,
410: ) -> f32 {
411:     let local = local.metres();
412:     let boundary = local.clamp(-playable_half_extent, playable_half_extent);
413:     let Some(playable_height) =
414:         ScenePlanPoint::from_metres(boundary).and_then(|point| terrain.height_at(point))
415:     else {
416:         return vista_height;
417:     };
418:     let outside_distance = (local.abs() - playable_half_extent)
419:         .max(Vec2::ZERO)
420:         .max_element();
421:     let vista_weight = if transition_width > 0.0 {
422:         (outside_distance / transition_width).clamp(0.0, 1.0)
423:     } else {
424:         f32::from(outside_distance > 0.0)
425:     };
426:     playable_height.metres().lerp(vista_height, vista_weight)
427: }
428: 
429: fn native_presented_height_at(
430:     lod: &VistaLod,
431:     world: ScenePlanPoint,
432:     coarser_lod: Option<&VistaLod>,
433: ) -> Option<f32> {
434:     let own = native_sample_vista_height(lod, world)?;
435:     let Some(coarser) = coarser_lod else {
436:         return Some(own);
437:     };
438:     if !coarser.has_height_grid() {
439:         return None;
440:     }
441:     let weight = lod_transition_weight(lod, coarser, world);
442:     if weight <= 0.0 {
443:         return Some(own);
444:     }
445:     Some(
446:         native_sample_vista_height(coarser, world)
447:             .map(|height| own.lerp(height, weight))
448:             .unwrap_or(own),
449:     )
450: }
451: 
452: fn native_sample_vista_height(lod: &VistaLod, world: ScenePlanPoint) -> Option<f32> {
453:     if !lod.has_height_grid() {
454:         return None;
455:     }
456:     let world = world.metres();
457:     let width = usize::from(lod.width);
458:     let depth = usize::from(lod.depth);
459:     let local = world
460:         - Vec2::new(
461:             lod.origin_east_metres as f32,
462:             lod.origin_north_metres as f32,
463:         );
464:     let coordinate =
465:         local / lod.spacing_metres + Vec2::new((width - 1) as f32 * 0.5, (depth - 1) as f32 * 0.5);
466:     if coordinate.x < 0.0
467:         || coordinate.y < 0.0
468:         || coordinate.x > (width - 1) as f32
469:         || coordinate.y > (depth - 1) as f32
470:     {
471:         return None;
472:     }
473:     let lower = coordinate.floor().as_uvec2();
474:     let upper = (lower + UVec2::ONE).min(UVec2::new(width as u32 - 1, depth as u32 - 1));
475:     let fraction = coordinate.fract();
476:     let at = |x: u32, z: u32| lod.heights_metres[z as usize * width + x as usize];
477:     let near = at(lower.x, lower.y).lerp(at(upper.x, lower.y), fraction.x);
478:     let far = at(lower.x, upper.y).lerp(at(upper.x, upper.y), fraction.x);
479:     Some(near.lerp(far, fraction.y))
480: }

1: //! Bounded implicit terrain patches and deterministic marching tetrahedra.
2: //!
3: //! The server selects a compact, immutable landform recipe. Server collision
4: //! and client presentation extract the same field after heightfield repair;
5: //! no terrain simulation or mesh persistence runs during tactical ticks.
6: //! The heightfield remains authoritative outside the transition collar.
