107: impl SimulatedScarpSurface {
108:     fn offset_at(&self, point: ScenePlanPoint) -> f32 {
109:         let grid = (point.metres() - self.minimum.metres()) / self.spacing;
110:         let x0 = (grid.x.floor() as usize).min(self.side - 2);
111:         let z0 = (grid.y.floor() as usize).min(self.side - 2);
112:         let fraction = (grid - Vec2::new(x0 as f32, z0 as f32)).clamp(Vec2::ZERO, Vec2::ONE);
113:         let a = self.offsets[z0 * self.side + x0];
114:         let b = self.offsets[z0 * self.side + x0 + 1];
115:         let c = self.offsets[(z0 + 1) * self.side + x0];
116:         let d = self.offsets[(z0 + 1) * self.side + x0 + 1];
117:         a.lerp(b, fraction.x)
118:             .lerp(c.lerp(d, fraction.x), fraction.y)
119:     }
120: 
121:     fn height_range(&self, terrain: &SceneTerrain) -> TerrainRecipeResult<SceneElevationRange> {
122:         if self.offsets.is_empty() {
123:             return Err(TerrainRecipeError::EmptySurface);
124:         }
125:         let (minimum, maximum) = self

126:             .offsets
127:             .par_iter()
128:             .enumerate()
129:             .map(|(index, offset)| -> TerrainRecipeResult<(f32, f32)> {
130:                 let x = index % self.side;
131:                 let z = index / self.side;
132:                 let point = ScenePlanPoint::from_metres(
133:                     self.minimum.metres() + Vec2::new(x as f32, z as f32) * self.spacing,
134:                 )
135:                 .ok_or(TerrainRecipeError::NonFiniteField)?;
136:                 let height = height_at_extended_edge(terrain, point)?.metres() + offset;
137:                 if !height.is_finite() {
138:                     return Err(TerrainRecipeError::NonFiniteField);
139:                 }
140:                 Ok((height, height))
141:             })
142:             .try_reduce(
143:                 || (f32::INFINITY, f32::NEG_INFINITY),
144:                 |(left_minimum, left_maximum), (right_minimum, right_maximum)| {
145:                     Ok((
146:                         left_minimum.min(right_minimum),
147:                         left_maximum.max(right_maximum),
148:                     ))
149:                 },
150:             )?;
151:         SceneElevationRange::new(
152:             SupportElevation::from_metres(minimum).ok_or(TerrainRecipeError::NonFiniteField)?,
153:             SupportElevation::from_metres(maximum).ok_or(TerrainRecipeError::NonFiniteField)?,
154:         )
155:         .ok_or(TerrainRecipeError::NonFiniteField)
156:     }
157: }
158: 
159: pub fn terrain_landform_patch(
160:     terrain: &SceneTerrain,
161:     recipe: TerrainLandformRecipe,
162: ) -> TerrainRecipeResult<SceneTerrainPatch> {
163:     recipe.validate(terrain)?;
164:     if recipe.kind != TerrainLandformKind::FaultScarp {
165:         return crate::erosional_terrain::patch(terrain, recipe);
166:     }
167:     let spacing = f32::from(recipe.lod.voxel_cm()) / 100.0;
168:     let origin = Vec2::new(recipe.origin_cm[0] as f32, recipe.origin_cm[1] as f32) / 100.0;
169:     let radius = f32::from(recipe.half_length_cm.max(recipe.half_width_cm)) / 100.0
170:         + SCARP_RUPTURE_WANDER_METRES;
171:     // March one sample beyond the transition's outer edge. An isosurface that
172:     // lands exactly on the final voxel plane has no neighbouring cell from
173:     // which marching tetrahedra can emit its last triangles, which otherwise
174:     // leaves a thin rectangular opening at the fault tips.
175:     let radius = (radius / spacing).ceil() * spacing + spacing;
176:     let side = ((radius * 2.0 / spacing).round() as usize).saturating_add(1);
177:     let throw = f32::from(recipe.relief_cm) / 100.0;
178:     let minimum = ScenePlanPoint::from_metres(origin - Vec2::splat(radius))
179:         .ok_or(TerrainRecipeError::NonFiniteField)?;
180:     let surface = simulate_fault_scarp(terrain, recipe, side, spacing, minimum)?;
181:     let range = surface.height_range(terrain)?;
182:     // Offset the vertical lattice so a flat heightfield cannot coincide with
183:     // an entire voxel plane. Coincident zero-valued edges collapse otherwise
184:     // valid tetrahedra at the zero-displacement collar contour.
185:     let bottom = ((range.minimum().metres() - throw - spacing * 2.0) / spacing).floor() * spacing
186:         - spacing * 0.5;
187:     let required_top = range.maximum().metres() + throw + spacing * 2.0;
188:     let vertical = ((required_top - bottom) / spacing).ceil() as usize + 1;
189:     if side > 195 || vertical > 96 {
190:         return Err(TerrainRecipeError::VoxelGridBound);
191:     }
192:     let dimensions = [side, vertical, side];
193:     let sample_position = |index: [usize; 3]| {
194:         Vec3::new(
195:             origin.x + index[0] as f32 * spacing - radius,
196:             bottom + index[1] as f32 * spacing,
197:             origin.y + index[2] as f32 * spacing - radius,
198:         )
199:     };
200:     // A fault is a displaced height surface. Every vertical sample in a
201:     // column shares the exact same terrain lookup and displacement. Reuse the
202:     // producer's coordinate expression so ownership-edge rounding is unchanged.
203:     let surface_heights = (0..side * side)
204:         .into_par_iter()
205:         .map(|index| -> TerrainRecipeResult<f32> {
206:             let point =
207:                 ScenePlanPoint::from_metres(sample_position([index % side, 0, index / side]).xz())
208:                     .ok_or(TerrainRecipeError::NonFiniteField)?;
209:             Ok(height_at_extended_edge(terrain, point)?.metres() + surface.offset_at(point))
210:         })
211:         .collect::<TerrainRecipeResult<Vec<_>>>()?;
212:     marching_height_surface(
213:         dimensions,
214:         sample_position,
215:         &surface_heights,
216:         recipe.transition_collar(),
217:     )
218: }
219: 
220: fn simulate_fault_scarp(
221:     terrain: &SceneTerrain,
222:     recipe: TerrainLandformRecipe,
223:     side: usize,
224:     spacing: f32,
225:     minimum: ScenePlanPoint,
226: ) -> TerrainRecipeResult<SimulatedScarpSurface> {
227:     let collar = recipe.transition_collar();
228:     let throw = f32::from(recipe.relief_cm) / 100.0;
229:     // Keep both displaced blocks clear of the original heightfield.  A zero
230:     // offset on either side makes the replacement isosurface coincide with
231:     // the removed heightfield and can leave an unmeshed ownership hole.  The
232:     // unequal split leaves most relief on the footwall while retaining a
233:     // lower source surface from which the erosion pass can build its apron.
234:     let footwall_uplift = throw * 0.875;
235:     let hanging_wall_drop = -throw * 0.125;
236:     let mut offsets = vec![0.0; side * side];
237:     let mut masks = vec![0.0; side * side];
238:     let mut base_heights = vec![0.0; side * side];
239:     offsets
240:         .par_iter_mut()
241:         .zip(masks.par_iter_mut())
242:         .zip(base_heights.par_iter_mut())
243:         .enumerate()
244:         .try_for_each(
245:             |(index, ((offset, mask), base_height))| -> TerrainRecipeResult<()> {
246:                 let x = index % side;
247:                 let z = index / side;
248:                 let point = ScenePlanPoint::from_metres(
249:                     minimum.metres() + Vec2::new(x as f32, z as f32) * spacing,
250:                 )

251:                 .ok_or(TerrainRecipeError::NonFiniteField)?;
252:                 let local = collar.local_coordinates(point.metres());
253:                 let along = local.x;
254:                 let across = local.y;
255:                 *mask = collar.blend_weight(point.metres());
256:                 let throw_variation = 0.84
257:                     + (smooth_value_noise(
258:                         StreamId::new("terrain.volume.throw").seed(recipe.seed, &[]),
259:                         along / 3.6,
260:                     ) * 0.5
261:                         + 0.5)
262:                         * 0.16;
263:                 *offset = if across >= 0.0 {
264:                     hanging_wall_drop
265:                 } else {
266:                     footwall_uplift
267:                 } * *mask
268:                     * throw_variation;
269:                 *base_height = height_at_extended_edge(terrain, point)?.metres();
270:                 Ok(())
271:             },
272:         )?;
273: 
274:     erode_surface(
275:         &mut offsets,
276:         &masks,
277:         &base_heights,
278:         recipe,
279:         collar,
280:         side,
281:         spacing,
282:         minimum,
283:     );
284: 
285:     Ok(SimulatedScarpSurface {
286:         minimum,
287:         spacing,
288:         side,
289:         offsets,
290:     })
291: }
292: 
293: #[expect(
294:     clippy::too_many_arguments,
295:     reason = "the erosion grid inputs are independent"
296: )]
297: fn erode_surface(
298:     offsets: &mut [f32],
299:     masks: &[f32],
300:     base_heights: &[f32],
301:     recipe: TerrainLandformRecipe,
302:     collar: TerrainTransitionCollar,
303:     side: usize,
304:     spacing: f32,
305:     minimum: ScenePlanPoint,
306: ) {
307:     let resistances = ScarpResistanceGrid::new(masks, recipe, collar, side, spacing, minimum);
308:     let mut horizontal_transfers = vec![0.0; offsets.len()];
309:     let mut vertical_transfers = vec![0.0; offsets.len()];
310:     for _ in 0..SCARP_EROSION_STEPS {
311:         horizontal_transfers
312:             .par_iter_mut()
313:             .zip(vertical_transfers.par_iter_mut())
314:             .enumerate()
315:             .for_each(|(source, (horizontal, vertical))| {
316:                 let x = source % side;
317:                 let z = source / side;
318:                 let cell = resistances.cell(source);
319:                 let transfer_to = |nx: usize, nz: usize, resistance: Option<ScarpResistance>| {
320:                     let Some(resistance) = resistance else {
321:                         return 0.0;
322:                     };
323:                     let target = nz * side + nx;
324:                     let difference = (base_heights[source] + offsets[source])
325:                         - (base_heights[target] + offsets[target]);
326:                     let resistance = resistance.coefficient();
327:                     let threshold = spacing
328:                         * (SCARP_COLLUVIAL_GRADE + resistance * SCARP_RESISTANT_FACE_GRADE_RANGE);
329:                     let excess = difference.abs() - threshold;
330:                     if excess <= 0.0 {
331:                         return 0.0;
332:                     }
333:                     let transfer =
334:                         excess * SCARP_MAXIMUM_TRANSFER_FRACTION * (1.0 - resistance * 0.55);
335:                     transfer * difference.signum()
336:                 };
337:                 *horizontal = transfer_to(x + 1, z, cell.x_neighbor);
338:                 *vertical = transfer_to(x, z + 1, cell.z_neighbor);
339:             });
340:         offsets
341:             .par_iter_mut()
342:             .enumerate()
343:             .for_each(|(index, offset)| {
344:                 if masks[index] <= 0.0 {
345:                     *offset = 0.0;
346:                     return;
347:                 }
348:                 let x = index % side;
349:                 let z = index / side;
350:                 let mut transfer = 0.0;
351:                 if z > 0 {
352:                     transfer += vertical_transfers[index - side];
353:                 }
354:                 if x > 0 {
355:                     transfer += horizontal_transfers[index - 1];
356:                 }
357:                 transfer -= horizontal_transfers[index];
358:                 transfer -= vertical_transfers[index];
359:                 *offset += transfer;
360:             });
361:     }
362: }
363: 
364: fn smooth_value_noise(seed: fabelgeist_determinism::Seed, coordinate: f32) -> f32 {
365:     let cell = coordinate.floor() as i64;
366:     let fraction = smoothstep01(coordinate - coordinate.floor());
367:     let sample = |offset: i64| {
368:         StreamId::new("terrain.volume.lattice")
369:             .rng(seed, &[cell.wrapping_add(offset) as u64])
370:             .inclusive_unit_f32()
371:             * 2.0
372:             - 1.0
373:     };
374:     sample(0).lerp(sample(1), fraction)
375: }

376: 
377: fn smoothstep01(value: f32) -> f32 {
378:     let value = value.clamp(0.0, 1.0);
379:     value * value * (3.0 - 2.0 * value)
380: }
