57:                         collar,
58:                         (source_point + target_point) * 0.5,
59:                         half_length,
60:                     ))
61:                 };
62:                 CellResistance {
63:                     x_neighbor: sample(x + 1, z),
64:                     z_neighbor: sample(x, z + 1),
65:                 }
66:             })
67:             .collect();
