76: impl ScarpResistance {
77:     /// Native stencil handoff: preserve the field's coefficient and arithmetic.
78:     pub(super) fn coefficient(self) -> f32 {
79:         self.0
80:     }
81: 
82:     fn sample(seed: Seed, collar: TerrainTransitionCollar, point: Vec2, half_length: f32) -> Self {
83:         let local = collar.local_coordinates(point);
84:         // The uplifted block retains a narrower bedrock face than the broader
85:         // colluvial toe on the hanging-wall side.
86:         let free_face_distance = (local.y + 0.35).abs();
87:         let free_face = smoothstep01(
88:             (SCARP_FREE_FACE_HALF_WIDTH_METRES - free_face_distance)
89:                 / SCARP_FREE_FACE_HALF_WIDTH_METRES,
90:         );
91:         let coherent_material = (smooth_value_noise(
92:             StreamId::new("terrain.volume.resistance").seed(seed, &[]),
93:             local.x / 6.5 + local.y / 8.0,
94:         ) * 0.5
95:             + 0.5)
96:             * 0.18;
97:         let drainage = scarp_gully_strength(seed, local.x, half_length)
98:             * smoothstep01((SCARP_FREE_FACE_HALF_WIDTH_METRES * 2.4 - local.y.abs()) / 3.0);
99:         Self((0.08 + free_face * 0.78 + coherent_material - drainage * 0.58).clamp(0.0, 1.0))
100:     }
101: }
102: 
103: fn scarp_gully_strength(seed: Seed, along: f32, half_length: f32) -> f32 {
104:     (0..SCARP_GULLY_COUNT)
105:         .map(|index| {
106:             let mut random = StreamId::new("terrain.gully").rng(seed, &[index as u64]);
107:             let interval = (index as f32 + 0.5) / SCARP_GULLY_COUNT as f32;
108:             let jitter = (random.inclusive_unit_f32() - 0.5) * 0.16;
109:             let centre = (interval + jitter) * half_length * 1.8 - half_length * 0.9;
110:             let width = 1.4 + random.inclusive_unit_f32() * 1.3;
111:             smoothstep01((width - (along - centre).abs()) / width)
112:         })
113:         .fold(0.0, f32::max)
114: }
