299: fn inferred_structure(
300:     preset: TerrainSurfacePreset,
301:     seed: fabelgeist_determinism::Seed,
302:     tangent_permyriad: [i16; 2],
303: ) -> TerrainGeologicStructure {
304:     // EGDI supplies unit lithology, not a local measured column, dip, or
305:     // strike. This stable seed/tangent construction is explicitly artistic
306:     // inference: it gives one scene-wide frame to bedding/foliation without
307:     // presenting it as observed field structure.
308:     let random = |purpose| StreamId::new(purpose).rng(seed, &[]).inclusive_unit_f32();
309:     let tangent = [
310:         f32::from(tangent_permyriad[0]) / 10_000.0,
311:         f32::from(tangent_permyriad[1]) / 10_000.0,
312:     ];
313:     let dip = match preset {
314:         TerrainSurfacePreset::MetamorphicFoliated | TerrainSurfacePreset::MixedRock => {
315:             0.28 + random("geology.foliation-dip") * 0.58
316:         }
317:         _ => 0.06 + random("geology.bedding-dip") * 0.30,
318:     };
319:     let horizontal = (1.0 - dip * dip).sqrt();
320:     let normal = [
321:         (-tangent[1] * horizontal * 10_000.0).round() as i16,
322:         (dip * 10_000.0).round() as i16,
323:         (tangent[0] * horizontal * 10_000.0).round() as i16,
324:     ];
325:     match preset {
326:         TerrainSurfacePreset::Sandstone
327:         | TerrainSurfacePreset::FineClastic
328:         | TerrainSurfacePreset::Shale
329:         | TerrainSurfacePreset::Carbonate
330:         | TerrainSurfacePreset::Chalk
331:         | TerrainSurfacePreset::Evaporite
332:         | TerrainSurfacePreset::Organic
333:         | TerrainSurfacePreset::CohesiveSediment => TerrainGeologicStructure::Bedded {
334:             normal_permyriad: normal,
335:             bed_thickness_cm: (24.0 + random("geology.bed-thickness") * 210.0).round() as u16,
336:             thickness_variation_bps: (900.0 + random("geology.thickness-variation") * 2_800.0)
337:                 .round() as u16,
338:             warp_cm: (8.0 + random("geology.bed-warp") * 54.0).round() as u16,
339:             cross_bedding_bps: if preset == TerrainSurfacePreset::Sandstone {
340:                 (900.0 + random("geology.cross-bedding") * 2_700.0).round() as u16
341:             } else {
342:                 0
343:             },
344:         },
345:         TerrainSurfacePreset::MetamorphicFoliated | TerrainSurfacePreset::MixedRock => {
346:             TerrainGeologicStructure::Foliated {
347:                 normal_permyriad: normal,
348:                 band_spacing_cm: (16.0 + random("geology.band-spacing") * 150.0).round() as u16,
349:                 warp_cm: (5.0 + random("geology.fold-warp") * 42.0).round() as u16,
350:             }
351:         }
352:         TerrainSurfacePreset::Granite
353:         | TerrainSurfacePreset::Plutonic
354:         | TerrainSurfacePreset::Basalt
355:         | TerrainSurfacePreset::Volcanic
356:         | TerrainSurfacePreset::Siliceous
357:         | TerrainSurfacePreset::MetamorphicMassive
358:         | TerrainSurfacePreset::ConglomerateBreccia
359:         | TerrainSurfacePreset::UnconsolidatedSediment => TerrainGeologicStructure::Massive,
360:     }
361: }
