178: 
179: impl SprintInputState {
180:     fn update_with_threshold(
181:         &mut self,
182:         shift_down: bool,
183:         elapsed: AnimationElapsed,
184:         hold_threshold: PositiveAnimationDuration,
185:     ) -> AnimationValueResult<()> {
186:         let mut next = *self;
187:         // The current frame's delta ends at this sample, so it belongs to a
188:         // key that was already down. Counting it here includes the release
189:         // frame without pretending a new press began at the frame's start.
190:         if next.shift_down && !next.deactivating_press {
191:             next.held_seconds = next.held_seconds.checked_add(elapsed)?;
192:         }
193:         if shift_down && !next.shift_down {
194:             next.deactivating_press = next.active;
195:             next.active = !next.active;
196:             next.held_seconds = AnimationElapsed::ZERO;
197:         } else if !shift_down && next.shift_down {
198:             if !next.deactivating_press && next.held_seconds > hold_threshold.elapsed() {
199:                 next.active = false;
200:             }
201:             next.held_seconds = AnimationElapsed::ZERO;
202:             next.deactivating_press = false;
203:         }
204:         next.shift_down = shift_down;
205:         *self = next;
206:         Ok(())
207:     }
208: 
209:     fn cancel_latch_when_idle(&mut self, moving: bool) {
210:         if !moving && !self.shift_down {
211:             self.active = false;
212:         }
213:     }
214: }
